VALUES
  (12, 1, '', '[{"id":752,"position":1,"text_uthmani":"الٓر ۚ","transliteration":"alif-lam-ra","translation_bn":"আলিফ লাম-রা","root":"—","lemma":"الٓر ۚ","grammar_bn":"শব্দ"},{"id":754,"position":2,"text_uthmani":"تِلْكَ","transliteration":"til''ka","translation_bn":"এই","root":"—","lemma":"ذَٰلِك","grammar_bn":"নির্দেশক সর্বনাম (Demonstrative)"},{"id":755,"position":3,"text_uthmani":"ءَايَـٰتُ","transliteration":"āyātu","translation_bn":"আয়াতগুলো","root":"ايي","lemma":"ءَايَة","grammar_bn":"বিশেষ্য (Noun)"},{"id":756,"position":4,"text_uthmani":"ٱلْكِتَـٰبِ","transliteration":"l-kitābi","translation_bn":"(এমন) কিতাবের","root":"كتب","lemma":"كِتَٰب","grammar_bn":"শব্দ"},{"id":757,"position":5,"text_uthmani":"ٱلْمُبِينِ","transliteration":"l-mubīni","translation_bn":"(যা) সুস্পষ্ট","root":"بين","lemma":"مُّبِين","grammar_bn":"শব্দ"},{"id":758,"position":6,"text_uthmani":"١","transliteration":"","translation_bn":"(১)","root":"—","lemma":"١","grammar_bn":"মার্কার"}]'::jsonb, 'alif-lam-ra til''ka āyātu l-kitābi l-mubīni', 'আলিফ, লাম-রা, এগুলো সুস্পষ্ট কিতাবের আয়াতসমূহ।', 'Alif, Lam, Ra. These are the verses of the clear Book.', 'আলিফ, লাম-রা, এগুলো সুস্পষ্ট কিতাবের আয়াতসমূহ।', 'Alif, Lam, Ra. These are the verses of the clear Book.', NULL, NULL, NULL, NULL, NULL, 'https://everyayah.com/data/Alafasy_128kbps/012001.mp3', now()),
  (12, 2, '', '[{"id":1176,"position":1,"text_uthmani":"إِنَّآ","transliteration":"innā","translation_bn":"নিশ্চয়ই আমরা","root":"—","lemma":"إِنّ","grammar_bn":"অভিঘাত পদ (Accusative)"},{"id":1177,"position":2,"text_uthmani":"أَنزَلْنَـٰهُ","transliteration":"anzalnāhu","translation_bn":"তা আমরা অবতীর্ণ করেছি","root":"نزل","lemma":"أَنزَلَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":1178,"position":3,"text_uthmani":"قُرْءَٰنًا","transliteration":"qur''ānan","translation_bn":"কুরআন (বানিয়ে)","root":"قرا","lemma":"قُرْءَان","grammar_bn":"নামবাচক বিশেষ্য (Proper Noun)"},{"id":1179,"position":4,"text_uthmani":"عَرَبِيًّۭا","transliteration":"ʿarabiyyan","translation_bn":"আরবী (ভাষায়)","root":"عرب","lemma":"عَرَبِيّ","grammar_bn":"বিশেষণ (Adjective)"},{"id":1180,"position":5,"text_uthmani":"لَّعَلَّكُمْ","transliteration":"laʿallakum","translation_bn":"তোমরা যাতে","root":"—","lemma":"لَعَلّ","grammar_bn":"অভিঘাত পদ (Accusative)"},{"id":1181,"position":6,"text_uthmani":"تَعْقِلُونَ","transliteration":"taʿqilūna","translation_bn":"বুঝতে পারো","root":"عقل","lemma":"عَقَلُ","grammar_bn":"ক্রিয়া (Verb)"},{"id":1182,"position":7,"text_uthmani":"٢","transliteration":"","translation_bn":"(২)","root":"—","lemma":"٢","grammar_bn":"মার্কার"}]'::jsonb, 'innā anzalnāhu qur''ānan ʿarabiyyan laʿallakum taʿqilūna', 'আমি তা অবতীর্ণ করেছি, আরবী ভাষার কুরআন, যাতে তোমরা ভালভাবে বুঝতে পার।', 'Indeed, We have sent it down as an Arabic Qur''an that you might understand.', 'আমি তা অবতীর্ণ করেছি, আরবী ভাষার কুরআন, যাতে তোমরা ভালভাবে বুঝতে পার।', 'Indeed, We have sent it down as an Arabic Qur''an that you might understand.', NULL, NULL, NULL, NULL, NULL, 'https://everyayah.com/data/Alafasy_128kbps/012002.mp3', now()),
  (12, 3, '', '[{"id":2970,"position":1,"text_uthmani":"نَحْنُ","transliteration":"naḥnu","translation_bn":"আমরা","root":"—","lemma":"نَحْنُ","grammar_bn":"সর্বনাম (Pronoun)"},{"id":2971,"position":2,"text_uthmani":"نَقُصُّ","transliteration":"naquṣṣu","translation_bn":"বর্ণনা করছি","root":"قصص","lemma":"قَصَّ","grammar_bn":"ক্রিয়া (Verb)"},{"id":2972,"position":3,"text_uthmani":"عَلَيْكَ","transliteration":"ʿalayka","translation_bn":"তোমার কাছে","root":"—","lemma":"عَلَىٰ\r","grammar_bn":"অব্যয় (Preposition)"},{"id":2973,"position":4,"text_uthmani":"أَحْسَنَ","transliteration":"aḥsana","translation_bn":"অতি উত্তম","root":"حسن","lemma":"أَحْسَن","grammar_bn":"বিশেষ্য (Noun)"},{"id":2974,"position":5,"text_uthmani":"ٱلْقَصَصِ","transliteration":"l-qaṣaṣi","translation_bn":"কাহিনীসমূহ","root":"قصص","lemma":"قَصَص","grammar_bn":"শব্দ"},{"id":2975,"position":6,"text_uthmani":"بِمَآ","transliteration":"bimā","translation_bn":"মাধ্যমে যা","root":"—","lemma":"مَا\r","grammar_bn":"অব্যয় (Preposition)"},{"id":2976,"position":7,"text_uthmani":"أَوْحَيْنَآ","transliteration":"awḥaynā","translation_bn":"আমরা ওহী করেছি","root":"وحي","lemma":"أَوْحَىٰ^","grammar_bn":"ক্রিয়া (Verb)"},{"id":2977,"position":8,"text_uthmani":"إِلَيْكَ","transliteration":"ilayka","translation_bn":"তোমার প্রতি","root":"—","lemma":"إِلَىٰ\r","grammar_bn":"অব্যয় (Preposition)"},{"id":2978,"position":9,"text_uthmani":"هَـٰذَا","transliteration":"hādhā","translation_bn":"এই","root":"—","lemma":"هَٰذَا","grammar_bn":"নির্দেশক সর্বনাম (Demonstrative)"},{"id":2979,"position":10,"text_uthmani":"ٱلْقُرْءَانَ","transliteration":"l-qur''āna","translation_bn":"কুর''আন","root":"قرا","lemma":"قُرْءَان","grammar_bn":"শব্দ"},{"id":2980,"position":11,"text_uthmani":"وَإِن","transliteration":"wa-in","translation_bn":"যদিও নিশ্চয়ই","root":"—","lemma":"إِن\r","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":2981,"position":12,"text_uthmani":"كُنتَ","transliteration":"kunta","translation_bn":"তুমি ছিলে","root":"كون","lemma":"كَانَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":2982,"position":13,"text_uthmani":"مِن","transliteration":"min","translation_bn":"থেকে","root":"—","lemma":"مِن\r","grammar_bn":"অব্যয় (Preposition)"},{"id":2983,"position":14,"text_uthmani":"قَبْلِهِۦ","transliteration":"qablihi","translation_bn":"পূর্ব এর","root":"قبل","lemma":"قَبْل","grammar_bn":"বিশেষ্য (Noun)"},{"id":2984,"position":15,"text_uthmani":"لَمِنَ","transliteration":"lamina","translation_bn":"অবশ্যই অন্তর্ভুক্ত","root":"—","lemma":"مِن\r","grammar_bn":"দৃঢ়তাবোধক (Emphatic)"},{"id":2985,"position":16,"text_uthmani":"ٱلْغَـٰفِلِينَ","transliteration":"l-ghāfilīna","translation_bn":"অনবহিতদের","root":"غفل","lemma":"غَٰفِل","grammar_bn":"শব্দ"},{"id":2986,"position":17,"text_uthmani":"٣","transliteration":"","translation_bn":"(৩)","root":"—","lemma":"٣","grammar_bn":"মার্কার"}]'::jsonb, 'naḥnu naquṣṣu ʿalayka aḥsana l-qaṣaṣi bimā awḥaynā ilayka hādhā l-qur''āna wa-in kunta min qablihi lamina l-ghāfilīna', 'আমি তোমার কাছে সর্বোত্তম কাহিনী বর্ণনা করছি, এ কুরআন তোমার কাছে ওয়াহী যোগে পাঠিয়ে, যদিও এর পূর্বে তুমি না-জানা লোকদের মধ্যেই শামিল ছিলে।', 'We relate to you, [O Muhammad], the best of stories in what We have revealed to you of this Qur''an although you were, before it, among the unaware.', 'আমি তোমার কাছে সর্বোত্তম কাহিনী বর্ণনা করছি, এ কুরআন তোমার কাছে ওয়াহী যোগে পাঠিয়ে, যদিও এর পূর্বে তুমি না-জানা লোকদের মধ্যেই শামিল ছিলে।', 'We relate to you, [O Muhammad], the best of stories in what We have revealed to you of this Qur''an although you were, before it, among the unaware.', NULL, NULL, NULL, NULL, NULL, 'https://everyayah.com/data/Alafasy_128kbps/012003.mp3', now()),
  (12, 4, '', '[{"id":4280,"position":1,"text_uthmani":"إِذْ","transliteration":"idh","translation_bn":"যখন (স্মরণ করো)","root":"—","lemma":"إِذ\r","grammar_bn":"কালবাচক (Time)"},{"id":4281,"position":2,"text_uthmani":"قَالَ","transliteration":"qāla","translation_bn":"বলেছিলো","root":"قول","lemma":"قَالَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":4282,"position":3,"text_uthmani":"يُوسُفُ","transliteration":"yūsufu","translation_bn":"ইউসুফ","root":"—","lemma":"يُوسُف","grammar_bn":"নামবাচক বিশেষ্য (Proper Noun)"},{"id":4283,"position":4,"text_uthmani":"لِأَبِيهِ","transliteration":"li-abīhi","translation_bn":"তার পিতাকে","root":"ابو","lemma":"أَبٌ","grammar_bn":"অব্যয় (Preposition)"},{"id":4284,"position":5,"text_uthmani":"يَـٰٓأَبَتِ","transliteration":"yāabati","translation_bn":"\"হে আমার পিতা","root":"ابو","lemma":"أَبٌ","grammar_bn":"সম্বোধন পদ (Vocative)"},{"id":4285,"position":6,"text_uthmani":"إِنِّى","transliteration":"innī","translation_bn":"নিশ্চয়ই আমি","root":"—","lemma":"إِنّ","grammar_bn":"অভিঘাত পদ (Accusative)"},{"id":4286,"position":7,"text_uthmani":"رَأَيْتُ","transliteration":"ra-aytu","translation_bn":"(স্বপ্নে) দেখেছি","root":"راي","lemma":"رَءَا","grammar_bn":"ক্রিয়া (Verb)"},{"id":4287,"position":8,"text_uthmani":"أَحَدَ","transliteration":"aḥada","translation_bn":"এগারো","root":"احد","lemma":"أَحَد","grammar_bn":"বিশেষ্য (Noun)"},{"id":4288,"position":9,"text_uthmani":"عَشَرَ","transliteration":"ʿashara","translation_bn":"এগারো","root":"عشر","lemma":"عَشَر","grammar_bn":"বিশেষ্য (Noun)"},{"id":4289,"position":10,"text_uthmani":"كَوْكَبًۭا","transliteration":"kawkaban","translation_bn":"তারাকে","root":"كوكب","lemma":"كَوْكَب","grammar_bn":"বিশেষ্য (Noun)"},{"id":4290,"position":11,"text_uthmani":"وَٱلشَّمْسَ","transliteration":"wal-shamsa","translation_bn":"এবং সূর্যকে","root":"شمس","lemma":"شَمْس","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":4291,"position":12,"text_uthmani":"وَٱلْقَمَرَ","transliteration":"wal-qamara","translation_bn":"এবং চাঁদকে","root":"قمر","lemma":"قَمَر","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":4292,"position":13,"text_uthmani":"رَأَيْتُهُمْ","transliteration":"ra-aytuhum","translation_bn":"তাদের আমি দেখেছি","root":"راي","lemma":"رَءَا","grammar_bn":"ক্রিয়া (Verb)"},{"id":4293,"position":14,"text_uthmani":"لِى","transliteration":"lī","translation_bn":"আমাকে","root":"—","lemma":"لِى","grammar_bn":"অব্যয় (Preposition)"},{"id":4294,"position":15,"text_uthmani":"سَـٰجِدِينَ","transliteration":"sājidīna","translation_bn":"(তারা) সিজদাকারী\"","root":"سجد","lemma":"سَاجِد","grammar_bn":"বিশেষ্য (Noun)"},{"id":4295,"position":16,"text_uthmani":"٤","transliteration":"","translation_bn":"(৪)","root":"—","lemma":"٤","grammar_bn":"মার্কার"}]'::jsonb, 'idh qāla yūsufu li-abīhi yāabati innī ra-aytu aḥada ʿashara kawkaban wal-shamsa wal-qamara ra-aytuhum lī sājidīna', 'স্মরণ কর, ইউসুফ যখন তার পিতাকে বলেছিল, ‘হে আব্বাজান! আমি (স্বপ্নে) দেখেছি এগারটি তারকা আর সূর্য ও চন্দ্র; দেখলাম তারা আমাকে সাজদাহ করছে।’', '[Of these stories mention] when Joseph said to his father, "O my father, indeed I have seen [in a dream] eleven stars and the sun and the moon; I saw them prostrating to me."', 'স্মরণ কর, ইউসুফ যখন তার পিতাকে বলেছিল, ‘হে আব্বাজান! আমি (স্বপ্নে) দেখেছি এগারটি তারকা আর সূর্য ও চন্দ্র; দেখলাম তারা আমাকে সাজদাহ করছে।’', '[Of these stories mention] when Joseph said to his father, "O my father, indeed I have seen [in a dream] eleven stars and the sun and the moon; I saw them prostrating to me."', NULL, NULL, NULL, NULL, NULL, 'https://everyayah.com/data/Alafasy_128kbps/012004.mp3', now()),
  (12, 5, '', '[{"id":5554,"position":1,"text_uthmani":"قَالَ","transliteration":"qāla","translation_bn":"সে বললো","root":"قول","lemma":"قَالَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":5555,"position":2,"text_uthmani":"يَـٰبُنَىَّ","transliteration":"yābunayya","translation_bn":"\"হে আমার পুত্র","root":"بني","lemma":"بُنَىّ","grammar_bn":"সম্বোধন পদ (Vocative)"},{"id":5556,"position":3,"text_uthmani":"لَا","transliteration":"lā","translation_bn":"না","root":"—","lemma":"لَا\r","grammar_bn":"নিষেধবাচক (Prohibition)"},{"id":5557,"position":4,"text_uthmani":"تَقْصُصْ","transliteration":"taqṣuṣ","translation_bn":"বর্ণনা করো","root":"قصص","lemma":"قَصَّ","grammar_bn":"ক্রিয়া (Verb)"},{"id":5558,"position":5,"text_uthmani":"رُءْيَاكَ","transliteration":"ru''yāka","translation_bn":"তোমার স্বপ্ন","root":"راي","lemma":"رُّءْيَا","grammar_bn":"বিশেষ্য (Noun)"},{"id":5559,"position":6,"text_uthmani":"عَلَىٰٓ","transliteration":"ʿalā","translation_bn":"কাছে","root":"—","lemma":"عَلَىٰ\r","grammar_bn":"অব্যয় (Preposition)"},{"id":5560,"position":7,"text_uthmani":"إِخْوَتِكَ","transliteration":"ikh''watika","translation_bn":"তোমার ভাইদের","root":"اخو","lemma":"إِخْوَةٌ","grammar_bn":"বিশেষ্য (Noun)"},{"id":5561,"position":8,"text_uthmani":"فَيَكِيدُوا۟","transliteration":"fayakīdū","translation_bn":"তাহ''লে তারা চক্রান্ত করবে","root":"كيد","lemma":"كِيدُ","grammar_bn":"শব্দ"},{"id":5562,"position":9,"text_uthmani":"لَكَ","transliteration":"laka","translation_bn":"তোমার বিরুদ্ধে","root":"—","lemma":"لَكَ","grammar_bn":"অব্যয় (Preposition)"},{"id":5563,"position":10,"text_uthmani":"كَيْدًا ۖ","transliteration":"kaydan","translation_bn":"(বড়) চক্রান্ত","root":"كيد","lemma":"كَيْد","grammar_bn":"বিশেষ্য (Noun)"},{"id":5565,"position":11,"text_uthmani":"إِنَّ","transliteration":"inna","translation_bn":"নিশ্চয়ই","root":"—","lemma":"إِنّ","grammar_bn":"অভিঘাত পদ (Accusative)"},{"id":5566,"position":12,"text_uthmani":"ٱلشَّيْطَـٰنَ","transliteration":"l-shayṭāna","translation_bn":"শয়তান","root":"شطن","lemma":"شَيْطَٰن","grammar_bn":"শব্দ"},{"id":5567,"position":13,"text_uthmani":"لِلْإِنسَـٰنِ","transliteration":"lil''insāni","translation_bn":"মানুষের জন্যে","root":"انس","lemma":"إِنسَٰن","grammar_bn":"অব্যয় (Preposition)"},{"id":5568,"position":14,"text_uthmani":"عَدُوٌّۭ","transliteration":"ʿaduwwun","translation_bn":"শত্রু","root":"عدو","lemma":"عَدُوّ","grammar_bn":"বিশেষ্য (Noun)"},{"id":5569,"position":15,"text_uthmani":"مُّبِينٌۭ","transliteration":"mubīnun","translation_bn":"প্রকাশ্য","root":"بين","lemma":"مُّبِين","grammar_bn":"বিশেষ্য (Noun)"},{"id":5570,"position":16,"text_uthmani":"٥","transliteration":"","translation_bn":"(৫)","root":"—","lemma":"٥","grammar_bn":"মার্কার"}]'::jsonb, 'qāla yābunayya lā taqṣuṣ ru''yāka ʿalā ikh''watika fayakīdū laka kaydan inna l-shayṭāna lil''insāni ʿaduwwun mubīnun', 'তার পিতা বললেন, ‘হে আমার পুত্র! তোমার স্বপ্নের কথা তোমার ভাইদের কাছে বর্ণনা করো না। যদি কর তাহলে তারা তোমার বিরুদ্ধে চক্রান্ত করবে। শাইত্বান তো মানুষের প্রকাশ্য দুশমন।', 'He said, "O my son, do not relate your vision to your brothers or they will contrive against you a plan. Indeed Satan, to man, is a manifest enemy.', 'তার পিতা বললেন, ‘হে আমার পুত্র! তোমার স্বপ্নের কথা তোমার ভাইদের কাছে বর্ণনা করো না। যদি কর তাহলে তারা তোমার বিরুদ্ধে চক্রান্ত করবে। শাইত্বান তো মানুষের প্রকাশ্য দুশমন।', 'He said, "O my son, do not relate your vision to your brothers or they will contrive against you a plan. Indeed Satan, to man, is a manifest enemy.', NULL, NULL, NULL, NULL, NULL, 'https://everyayah.com/data/Alafasy_128kbps/012005.mp3', now()),
  (12, 6, '', '[{"id":6797,"position":1,"text_uthmani":"وَكَذَٰلِكَ","transliteration":"wakadhālika","translation_bn":"এবং এভাবেই (হবে)","root":"—","lemma":"ذَٰلِك","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":6798,"position":2,"text_uthmani":"يَجْتَبِيكَ","transliteration":"yajtabīka","translation_bn":"তোমাকে মনোনীত করবেন","root":"جبي","lemma":"ٱجْتَبَىٰ","grammar_bn":"ক্রিয়া (Verb)"},{"id":6799,"position":3,"text_uthmani":"رَبُّكَ","transliteration":"rabbuka","translation_bn":"তোমার রব","root":"ربب","lemma":"رَبّ","grammar_bn":"বিশেষ্য (Noun)"},{"id":6800,"position":4,"text_uthmani":"وَيُعَلِّمُكَ","transliteration":"wayuʿallimuka","translation_bn":"ও তোমাকে শিখাবেন","root":"علم","lemma":"عَلَّمَ","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":6801,"position":5,"text_uthmani":"مِن","transliteration":"min","translation_bn":"থেকে","root":"—","lemma":"مِن\r","grammar_bn":"অব্যয় (Preposition)"},{"id":6802,"position":6,"text_uthmani":"تَأْوِيلِ","transliteration":"tawīli","translation_bn":"ব্যাখ্যা","root":"اول","lemma":"تَأْوِيل","grammar_bn":"বিশেষ্য (Noun)"},{"id":6803,"position":7,"text_uthmani":"ٱلْأَحَادِيثِ","transliteration":"l-aḥādīthi","translation_bn":"স্বপ্নের","root":"حدث","lemma":"حَدِيث","grammar_bn":"শব্দ"},{"id":6804,"position":8,"text_uthmani":"وَيُتِمُّ","transliteration":"wayutimmu","translation_bn":"পূর্ণ করবেন","root":"تمم","lemma":"أَتَمَّ","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":6805,"position":9,"text_uthmani":"نِعْمَتَهُۥ","transliteration":"niʿ''matahu","translation_bn":"তাঁর অনুগ্রহ","root":"نعم","lemma":"نِعْمَة","grammar_bn":"বিশেষ্য (Noun)"},{"id":6806,"position":10,"text_uthmani":"عَلَيْكَ","transliteration":"ʿalayka","translation_bn":"তোমার উপর","root":"—","lemma":"عَلَىٰ\r","grammar_bn":"অব্যয় (Preposition)"},{"id":6807,"position":11,"text_uthmani":"وَعَلَىٰٓ","transliteration":"waʿalā","translation_bn":"এবং উপর","root":"—","lemma":"عَلَىٰ\r","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":6808,"position":12,"text_uthmani":"ءَالِ","transliteration":"āli","translation_bn":"বংশধরদের","root":"اول","lemma":"ءَال","grammar_bn":"বিশেষ্য (Noun)"},{"id":6809,"position":13,"text_uthmani":"يَعْقُوبَ","transliteration":"yaʿqūba","translation_bn":"ইয়াকুবের","root":"—","lemma":"يَعْقُوب","grammar_bn":"নামবাচক বিশেষ্য (Proper Noun)"},{"id":6810,"position":14,"text_uthmani":"كَمَآ","transliteration":"kamā","translation_bn":"যেমন","root":"—","lemma":"مَا\r","grammar_bn":"অব্যয় (Preposition)"},{"id":6811,"position":15,"text_uthmani":"أَتَمَّهَا","transliteration":"atammahā","translation_bn":"তা পূর্ণ করেছিলেন","root":"تمم","lemma":"أَتَمَّ","grammar_bn":"ক্রিয়া (Verb)"},{"id":6812,"position":16,"text_uthmani":"عَلَىٰٓ","transliteration":"ʿalā","translation_bn":"উপর","root":"—","lemma":"عَلَىٰ\r","grammar_bn":"অব্যয় (Preposition)"},{"id":6813,"position":17,"text_uthmani":"أَبَوَيْكَ","transliteration":"abawayka","translation_bn":"তোমার পিতৃ-পুরুষের","root":"ابو","lemma":"أَبَوَان","grammar_bn":"বিশেষ্য (Noun)"},{"id":6814,"position":18,"text_uthmani":"مِن","transliteration":"min","translation_bn":"থেকে","root":"—","lemma":"مِن\r","grammar_bn":"অব্যয় (Preposition)"},{"id":6815,"position":19,"text_uthmani":"قَبْلُ","transliteration":"qablu","translation_bn":"পূর্ব","root":"قبل","lemma":"قَبْل","grammar_bn":"বিশেষ্য (Noun)"},{"id":6816,"position":20,"text_uthmani":"إِبْرَٰهِيمَ","transliteration":"ib''rāhīma","translation_bn":"(যেমন) ইবরাহীমের","root":"—","lemma":"إِبْرَاهِيم","grammar_bn":"নামবাচক বিশেষ্য (Proper Noun)"},{"id":6817,"position":21,"text_uthmani":"وَإِسْحَـٰقَ ۚ","transliteration":"wa-is''ḥāqa","translation_bn":"ও ইসহাকের (উপর)","root":"—","lemma":"إِسْحَاق","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":6819,"position":22,"text_uthmani":"إِنَّ","transliteration":"inna","translation_bn":"নিশ্চয়ই","root":"—","lemma":"إِنّ","grammar_bn":"অভিঘাত পদ (Accusative)"},{"id":6820,"position":23,"text_uthmani":"رَبَّكَ","transliteration":"rabbaka","translation_bn":"তোমার রব","root":"ربب","lemma":"رَبّ","grammar_bn":"বিশেষ্য (Noun)"},{"id":6821,"position":24,"text_uthmani":"عَلِيمٌ","transliteration":"ʿalīmun","translation_bn":"সর্বজ্ঞ","root":"علم","lemma":"عَلِيم","grammar_bn":"বিশেষ্য (Noun)"},{"id":6822,"position":25,"text_uthmani":"حَكِيمٌۭ","transliteration":"ḥakīmun","translation_bn":"প্রজ্ঞাময়\"","root":"حكم","lemma":"حَكِيم","grammar_bn":"বিশেষণ (Adjective)"},{"id":6823,"position":26,"text_uthmani":"٦","transliteration":"","translation_bn":"(৬)","root":"—","lemma":"٦","grammar_bn":"মার্কার"}]'::jsonb, 'wakadhālika yajtabīka rabbuka wayuʿallimuka min tawīli l-aḥādīthi wayutimmu niʿ''matahu ʿalayka waʿalā āli yaʿqūba kamā atammahā ʿalā abawayka min qablu ib''rāhīma wa-is''ḥāqa inna rabbaka ʿalīmun ḥakīmun', '(স্বপ্নে যেমন দেখেছ) এভাবে তোমার প্রতিপালক তোমাকে মনোনীত করবেন, তোমাকে স্বপ্নের ব্যাখ্যা শিক্ষা দিবেন এবং তিনি তাঁর অনুগ্রহ তোমার প্রতি আর ইয়া‘কূব পরিবারের প্রতি পূর্ণ করবেন যেভাবে তিনি তা পূর্বে তোমার পিতৃ-পুরুষ ইবরাহীম ও ইসহাকের প্রতি পূর্ণ করেছিলেন, নিশ্চয়ই তোমার রব্ব সর্বজ্ঞ, বড়ই প্রজ্ঞাবান।’', 'And thus will your Lord choose you and teach you the interpretation of narratives and complete His favor upon you and upon the family of Jacob, as He completed it upon your fathers before, Abraham and Isaac. Indeed, your Lord is Knowing and Wise."', '(স্বপ্নে যেমন দেখেছ) এভাবে তোমার প্রতিপালক তোমাকে মনোনীত করবেন, তোমাকে স্বপ্নের ব্যাখ্যা শিক্ষা দিবেন এবং তিনি তাঁর অনুগ্রহ তোমার প্রতি আর ইয়া‘কূব পরিবারের প্রতি পূর্ণ করবেন যেভাবে তিনি তা পূর্বে তোমার পিতৃ-পুরুষ ইবরাহীম ও ইসহাকের প্রতি পূর্ণ করেছিলেন, নিশ্চয়ই তোমার রব্ব সর্বজ্ঞ, বড়ই প্রজ্ঞাবান।’', 'And thus will your Lord choose you and teach you the interpretation of narratives and complete His favor upon you and upon the family of Jacob, as He completed it upon your fathers before, Abraham and Isaac. Indeed, your Lord is Knowing and Wise."', NULL, NULL, NULL, NULL, NULL, 'https://everyayah.com/data/Alafasy_128kbps/012006.mp3', now()),
  (12, 7, '', '[{"id":8149,"position":1,"text_uthmani":"۞ لَّقَدْ","transliteration":"laqad","translation_bn":"নিশ্চয়ই","root":"—","lemma":"قَد\r","grammar_bn":"দৃঢ়তাবোধক (Emphatic)"},{"id":8150,"position":2,"text_uthmani":"كَانَ","transliteration":"kāna","translation_bn":"ছিলো","root":"كون","lemma":"كَانَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":8151,"position":3,"text_uthmani":"فِى","transliteration":"fī","translation_bn":"মধ্যে","root":"—","lemma":"فِى\r","grammar_bn":"অব্যয় (Preposition)"},{"id":8152,"position":4,"text_uthmani":"يُوسُفَ","transliteration":"yūsufa","translation_bn":"ইউসুফের (কাহিনীর)","root":"—","lemma":"يُوسُف","grammar_bn":"নামবাচক বিশেষ্য (Proper Noun)"},{"id":8153,"position":5,"text_uthmani":"وَإِخْوَتِهِۦٓ","transliteration":"wa-ikh''watihi","translation_bn":"ও তার ভাইদের","root":"اخو","lemma":"إِخْوَةٌ","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":8154,"position":6,"text_uthmani":"ءَايَـٰتٌۭ","transliteration":"āyātun","translation_bn":"নিদর্শনসমূহ","root":"ايي","lemma":"ءَايَة","grammar_bn":"বিশেষ্য (Noun)"},{"id":8155,"position":7,"text_uthmani":"لِّلسَّآئِلِينَ","transliteration":"lilssāilīna","translation_bn":"জিজ্ঞাসাকারীদের জন্যে","root":"سال","lemma":"سَا^ئِل","grammar_bn":"অব্যয় (Preposition)"},{"id":8156,"position":8,"text_uthmani":"٧","transliteration":"","translation_bn":"(৭)","root":"—","lemma":"٧","grammar_bn":"মার্কার"}]'::jsonb, 'laqad kāna fī yūsufa wa-ikh''watihi āyātun lilssāilīna', 'ইউসুফ আর তার ভাইদের ঘটনায় সত্য সন্ধানীদের জন্য অবশ্যই নিদর্শনাবলী আছে।', 'Certainly were there in Joseph and his brothers signs for those who ask,', 'ইউসুফ আর তার ভাইদের ঘটনায় সত্য সন্ধানীদের জন্য অবশ্যই নিদর্শনাবলী আছে।', 'Certainly were there in Joseph and his brothers signs for those who ask,', NULL, NULL, NULL, NULL, NULL, 'https://everyayah.com/data/Alafasy_128kbps/012007.mp3', now()),
  (12, 8, '', '[{"id":9315,"position":1,"text_uthmani":"إِذْ","transliteration":"idh","translation_bn":"যখন (স্মরণ করো)","root":"—","lemma":"إِذ\r","grammar_bn":"কালবাচক (Time)"},{"id":9316,"position":2,"text_uthmani":"قَالُوا۟","transliteration":"qālū","translation_bn":"(তারা ভাইয়েরা) বলেছিলো","root":"قول","lemma":"قَالَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":9317,"position":3,"text_uthmani":"لَيُوسُفُ","transliteration":"layūsufu","translation_bn":"\"অবশ্যই ইউসুফ","root":"—","lemma":"يُوسُف","grammar_bn":"দৃঢ়তাবোধক (Emphatic)"},{"id":9318,"position":4,"text_uthmani":"وَأَخُوهُ","transliteration":"wa-akhūhu","translation_bn":"ও তার ভাই","root":"اخو","lemma":"أَخ","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":9319,"position":5,"text_uthmani":"أَحَبُّ","transliteration":"aḥabbu","translation_bn":"অধিক প্রিয়","root":"حبب","lemma":"أَحَبّ","grammar_bn":"বিশেষণ (Adjective)"},{"id":9320,"position":6,"text_uthmani":"إِلَىٰٓ","transliteration":"ilā","translation_bn":"কাছে","root":"—","lemma":"إِلَىٰ\r","grammar_bn":"অব্যয় (Preposition)"},{"id":9321,"position":7,"text_uthmani":"أَبِينَا","transliteration":"abīnā","translation_bn":"আমাদের পিতার","root":"ابو","lemma":"أَبٌ","grammar_bn":"বিশেষ্য (Noun)"},{"id":9322,"position":8,"text_uthmani":"مِنَّا","transliteration":"minnā","translation_bn":"আমাদের চেয়ে","root":"—","lemma":"مِن\r","grammar_bn":"অব্যয় (Preposition)"},{"id":9323,"position":9,"text_uthmani":"وَنَحْنُ","transliteration":"wanaḥnu","translation_bn":"অথচ আমরা","root":"—","lemma":"وَنَحْنُ","grammar_bn":"অবস্থাবাচক (Circumstantial)"},{"id":9324,"position":10,"text_uthmani":"عُصْبَةٌ","transliteration":"ʿuṣ''batun","translation_bn":"একটি ঐক্যবদ্ধ দল","root":"عصب","lemma":"عُصْبَة","grammar_bn":"বিশেষ্য (Noun)"},{"id":9325,"position":11,"text_uthmani":"إِنَّ","transliteration":"inna","translation_bn":"নিশ্চয়ই","root":"—","lemma":"إِنّ","grammar_bn":"অভিঘাত পদ (Accusative)"},{"id":9326,"position":12,"text_uthmani":"أَبَانَا","transliteration":"abānā","translation_bn":"আমাদের পিতা","root":"ابو","lemma":"أَبٌ","grammar_bn":"বিশেষ্য (Noun)"},{"id":9327,"position":13,"text_uthmani":"لَفِى","transliteration":"lafī","translation_bn":"অবশ্যই মধ্যে","root":"—","lemma":"فِى\r","grammar_bn":"দৃঢ়তাবোধক (Emphatic)"},{"id":9328,"position":14,"text_uthmani":"ضَلَـٰلٍۢ","transliteration":"ḍalālin","translation_bn":"বিভ্রান্তির","root":"ضلل","lemma":"ضَلَٰل","grammar_bn":"বিশেষ্য (Noun)"},{"id":9329,"position":15,"text_uthmani":"مُّبِينٍ","transliteration":"mubīnin","translation_bn":"প্রকাশ্য","root":"بين","lemma":"مُّبِين","grammar_bn":"বিশেষণ (Adjective)"},{"id":9330,"position":16,"text_uthmani":"٨","transliteration":"","translation_bn":"(৮)","root":"—","lemma":"٨","grammar_bn":"মার্কার"}]'::jsonb, 'idh qālū layūsufu wa-akhūhu aḥabbu ilā abīnā minnā wanaḥnu ʿuṣ''batun inna abānā lafī ḍalālin mubīnin', 'স্মরণ কর, যখন তারা (বৈমাত্রেয় ভাইগণ) বলাবলি করছিল, ‘নিশ্চয়ই ইউসুফ আর তার (সহোদর) ভাই আমাদের পিতার কাছে আমাদের চেয়ে বেশি প্রিয়, অথচ আমরা পুরো একটা দল, আমাদের পিতা স্পষ্ট ভুলের মধ্যে আছেন।', 'When they said, "Joseph and his brother are more beloved to our father than we, while we are a clan. Indeed, our father is in clear error.', 'স্মরণ কর, যখন তারা (বৈমাত্রেয় ভাইগণ) বলাবলি করছিল, ‘নিশ্চয়ই ইউসুফ আর তার (সহোদর) ভাই আমাদের পিতার কাছে আমাদের চেয়ে বেশি প্রিয়, অথচ আমরা পুরো একটা দল, আমাদের পিতা স্পষ্ট ভুলের মধ্যে আছেন।', 'When they said, "Joseph and his brother are more beloved to our father than we, while we are a clan. Indeed, our father is in clear error.', NULL, NULL, NULL, NULL, NULL, 'https://everyayah.com/data/Alafasy_128kbps/012008.mp3', now()),
  (12, 9, '', '[{"id":10497,"position":1,"text_uthmani":"ٱقْتُلُوا۟","transliteration":"uq''tulū","translation_bn":"তোমরা হত্যা করো","root":"قتل","lemma":"قَتَلَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":10498,"position":2,"text_uthmani":"يُوسُفَ","transliteration":"yūsufa","translation_bn":"ইউসুফকে","root":"—","lemma":"يُوسُف","grammar_bn":"নামবাচক বিশেষ্য (Proper Noun)"},{"id":10499,"position":3,"text_uthmani":"أَوِ","transliteration":"awi","translation_bn":"বা","root":"—","lemma":"أَو\r","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":10500,"position":4,"text_uthmani":"ٱطْرَحُوهُ","transliteration":"iṭ''raḥūhu","translation_bn":"তাকে ফেলে আসো","root":"طرح","lemma":"ٱطْرَحُ","grammar_bn":"ক্রিয়া (Verb)"},{"id":10501,"position":5,"text_uthmani":"أَرْضًۭا","transliteration":"arḍan","translation_bn":"কোন স্থানে","root":"ارض","lemma":"أَرْض","grammar_bn":"বিশেষ্য (Noun)"},{"id":10502,"position":6,"text_uthmani":"يَخْلُ","transliteration":"yakhlu","translation_bn":"নিবিষ্ট হবে","root":"خلو","lemma":"خَلَا","grammar_bn":"ক্রিয়া (Verb)"},{"id":10503,"position":7,"text_uthmani":"لَكُمْ","transliteration":"lakum","translation_bn":"তোমাদের দিকে","root":"—","lemma":"لَكُمْ","grammar_bn":"অব্যয় (Preposition)"},{"id":10504,"position":8,"text_uthmani":"وَجْهُ","transliteration":"wajhu","translation_bn":"দৃষ্টি","root":"وجه","lemma":"وَجْه","grammar_bn":"বিশেষ্য (Noun)"},{"id":10505,"position":9,"text_uthmani":"أَبِيكُمْ","transliteration":"abīkum","translation_bn":"তোমাদের পিতার","root":"ابو","lemma":"أَبٌ","grammar_bn":"বিশেষ্য (Noun)"},{"id":10506,"position":10,"text_uthmani":"وَتَكُونُوا۟","transliteration":"watakūnū","translation_bn":"ও তোমরা হয়ে যাবে","root":"كون","lemma":"كَانَ","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":10507,"position":11,"text_uthmani":"مِنۢ","transliteration":"min","translation_bn":"থেকে","root":"—","lemma":"مِن\r","grammar_bn":"অব্যয় (Preposition)"},{"id":10508,"position":12,"text_uthmani":"بَعْدِهِۦ","transliteration":"baʿdihi","translation_bn":"এরপর","root":"بعد","lemma":"بَعْد","grammar_bn":"বিশেষ্য (Noun)"},{"id":10509,"position":13,"text_uthmani":"قَوْمًۭا","transliteration":"qawman","translation_bn":"লোক","root":"قوم","lemma":"قَوْم","grammar_bn":"বিশেষ্য (Noun)"},{"id":10510,"position":14,"text_uthmani":"صَـٰلِحِينَ","transliteration":"ṣāliḥīna","translation_bn":"সৎকর্মশীল\"","root":"صلح","lemma":"صَٰلِح","grammar_bn":"বিশেষণ (Adjective)"},{"id":10511,"position":15,"text_uthmani":"٩","transliteration":"","translation_bn":"(৯)","root":"—","lemma":"٩","grammar_bn":"মার্কার"}]'::jsonb, 'uq''tulū yūsufa awi iṭ''raḥūhu arḍan yakhlu lakum wajhu abīkum watakūnū min baʿdihi qawman ṣāliḥīna', 'তোমরা ইউসুফকে হত্যা করে ফেল কিংবা তাকে কোন ভূমিতে ফেলে আস, তাহলে তোমাদের পিতার দৃষ্টি তোমাদের প্রতিই নিবদ্ধ হবে, তার পর তোমরা (তাওবাহ করে) ভাল লোক হয়ে যাবে।', 'Kill Joseph or cast him out to [another] land; the countenance of your father will [then] be only for you, and you will be after that a righteous people."', 'তোমরা ইউসুফকে হত্যা করে ফেল কিংবা তাকে কোন ভূমিতে ফেলে আস, তাহলে তোমাদের পিতার দৃষ্টি তোমাদের প্রতিই নিবদ্ধ হবে, তার পর তোমরা (তাওবাহ করে) ভাল লোক হয়ে যাবে।', 'Kill Joseph or cast him out to [another] land; the countenance of your father will [then] be only for you, and you will be after that a righteous people."', NULL, NULL, NULL, NULL, NULL, 'https://everyayah.com/data/Alafasy_128kbps/012009.mp3', now()),
  (12, 10, '', '[{"id":11767,"position":1,"text_uthmani":"قَالَ","transliteration":"qāla","translation_bn":"বললো","root":"قول","lemma":"قَالَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":11768,"position":2,"text_uthmani":"قَآئِلٌۭ","transliteration":"qāilun","translation_bn":"এক প্রবক্তা","root":"قول","lemma":"قَا^ئِل","grammar_bn":"বিশেষ্য (Noun)"},{"id":11769,"position":3,"text_uthmani":"مِّنْهُمْ","transliteration":"min''hum","translation_bn":"তাদের মধ্য হ''তে","root":"—","lemma":"مِن\r","grammar_bn":"অব্যয় (Preposition)"},{"id":11770,"position":4,"text_uthmani":"لَا","transliteration":"lā","translation_bn":"\"না","root":"—","lemma":"لَا\r","grammar_bn":"নিষেধবাচক (Prohibition)"},{"id":11771,"position":5,"text_uthmani":"تَقْتُلُوا۟","transliteration":"taqtulū","translation_bn":"তোমরা হত্যা করো","root":"قتل","lemma":"قَتَلَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":11772,"position":6,"text_uthmani":"يُوسُفَ","transliteration":"yūsufa","translation_bn":"ইউসুফকে","root":"—","lemma":"يُوسُف","grammar_bn":"নামবাচক বিশেষ্য (Proper Noun)"},{"id":11773,"position":7,"text_uthmani":"وَأَلْقُوهُ","transliteration":"wa-alqūhu","translation_bn":"বরং তাকে নিক্ষেপ করো","root":"لقي","lemma":"أَلْقَىٰ^","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":11774,"position":8,"text_uthmani":"فِى","transliteration":"fī","translation_bn":"মধ্যে","root":"—","lemma":"فِى\r","grammar_bn":"অব্যয় (Preposition)"},{"id":11775,"position":9,"text_uthmani":"غَيَـٰبَتِ","transliteration":"ghayābati","translation_bn":"(অন্ধকার) গভীরে","root":"غيب","lemma":"غَيَٰبَت","grammar_bn":"বিশেষ্য (Noun)"},{"id":11776,"position":10,"text_uthmani":"ٱلْجُبِّ","transliteration":"l-jubi","translation_bn":"কূপের","root":"جبب","lemma":"جُبّ","grammar_bn":"শব্দ"},{"id":11777,"position":11,"text_uthmani":"يَلْتَقِطْهُ","transliteration":"yaltaqiṭ''hu","translation_bn":"তাকে তুলে নিবে","root":"لقط","lemma":"ٱلْتَقَطَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":11778,"position":12,"text_uthmani":"بَعْضُ","transliteration":"baʿḍu","translation_bn":"কেউ","root":"بعض","lemma":"بَعْض","grammar_bn":"বিশেষ্য (Noun)"},{"id":11779,"position":13,"text_uthmani":"ٱلسَّيَّارَةِ","transliteration":"l-sayārati","translation_bn":"পথযাত্রীদলের","root":"سير","lemma":"سَيَّارَة","grammar_bn":"শব্দ"},{"id":11780,"position":14,"text_uthmani":"إِن","transliteration":"in","translation_bn":"যদি","root":"—","lemma":"إِن\r","grammar_bn":"শর্তবাচক (Conditional)"},{"id":11781,"position":15,"text_uthmani":"كُنتُمْ","transliteration":"kuntum","translation_bn":"তোমরা হও","root":"كون","lemma":"كَانَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":11782,"position":16,"text_uthmani":"فَـٰعِلِينَ","transliteration":"fāʿilīna","translation_bn":"কর্মসম্পাদনকারী\"","root":"فعل","lemma":"فَاعِل","grammar_bn":"বিশেষ্য (Noun)"},{"id":11783,"position":17,"text_uthmani":"١٠","transliteration":"","translation_bn":"(১০)","root":"—","lemma":"١٠","grammar_bn":"মার্কার"}]'::jsonb, 'qāla qāilun min''hum lā taqtulū yūsufa wa-alqūhu fī ghayābati l-jubi yaltaqiṭ''hu baʿḍu l-sayārati in kuntum fāʿilīna', 'তাদের একজন বলল, তোমরা ইউসুফকে হত্যা করো না, তোমাদেরকে যদি কিছু করতেই হয় বরং তাকে কোন অন্ধ কূপে ফেলে দাও, কোন যাত্রীদল তাকে উঠিয়ে নিয়ে যাবে।’', 'Said a speaker among them, "Do not kill Joseph but throw him into the bottom of the well; some travelers will pick him up - if you would do [something]."', 'তাদের একজন বলল, তোমরা ইউসুফকে হত্যা করো না, তোমাদেরকে যদি কিছু করতেই হয় বরং তাকে কোন অন্ধ কূপে ফেলে দাও, কোন যাত্রীদল তাকে উঠিয়ে নিয়ে যাবে।’', 'Said a speaker among them, "Do not kill Joseph but throw him into the bottom of the well; some travelers will pick him up - if you would do [something]."', NULL, NULL, NULL, NULL, NULL, 'https://everyayah.com/data/Alafasy_128kbps/012010.mp3', now()),
  (12, 11, '', '[{"id":13092,"position":1,"text_uthmani":"قَالُوا۟","transliteration":"qālū","translation_bn":"তারা বললো","root":"قول","lemma":"قَالَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":13093,"position":2,"text_uthmani":"يَـٰٓأَبَانَا","transliteration":"yāabānā","translation_bn":"\"হে আমাদের পিতা","root":"ابو","lemma":"أَبٌ","grammar_bn":"সম্বোধন পদ (Vocative)"},{"id":13094,"position":3,"text_uthmani":"مَا","transliteration":"mā","translation_bn":"কি","root":"—","lemma":"مَا\r","grammar_bn":"সাপেক্ষ সর্বনাম (Relative)"},{"id":13095,"position":4,"text_uthmani":"لَكَ","transliteration":"laka","translation_bn":"আপনার হয়েছে","root":"—","lemma":"لَكَ","grammar_bn":"অব্যয় (Preposition)"},{"id":13096,"position":5,"text_uthmani":"لَا","transliteration":"lā","translation_bn":"না","root":"—","lemma":"لَا\r","grammar_bn":"না-বোধক (Negative)"},{"id":13097,"position":6,"text_uthmani":"تَأْمَ۫نَّا","transliteration":"tamannā","translation_bn":"আমাদের বিশ্বাস করেন","root":"امن","lemma":"أَمِنَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":13098,"position":7,"text_uthmani":"عَلَىٰ","transliteration":"ʿalā","translation_bn":"ব্যাপারে","root":"—","lemma":"عَلَىٰ\r","grammar_bn":"অব্যয় (Preposition)"},{"id":13099,"position":8,"text_uthmani":"يُوسُفَ","transliteration":"yūsufa","translation_bn":"ইউসুফের","root":"—","lemma":"يُوسُف","grammar_bn":"নামবাচক বিশেষ্য (Proper Noun)"},{"id":13100,"position":9,"text_uthmani":"وَإِنَّا","transliteration":"wa-innā","translation_bn":"অথচ নিশ্চয়ই আমরা","root":"—","lemma":"إِنّ","grammar_bn":"অবস্থাবাচক (Circumstantial)"},{"id":13101,"position":10,"text_uthmani":"لَهُۥ","transliteration":"lahu","translation_bn":"জন্যে তার","root":"—","lemma":"لَهُۥ","grammar_bn":"অব্যয় (Preposition)"},{"id":13102,"position":11,"text_uthmani":"لَنَـٰصِحُونَ","transliteration":"lanāṣiḥūna","translation_bn":"অবশ্যই (সবাই) হিতাকাঙ্ক্ষী","root":"نصح","lemma":"نَاصِح","grammar_bn":"দৃঢ়তাবোধক (Emphatic)"},{"id":13103,"position":12,"text_uthmani":"١١","transliteration":"","translation_bn":"(১১)","root":"—","lemma":"١١","grammar_bn":"মার্কার"}]'::jsonb, 'qālū yāabānā mā laka lā tamannā ʿalā yūsufa wa-innā lahu lanāṣiḥūna', 'তারা বলল, ‘হে আমাদের আব্বাজান! কী ব্যাপার, আপনি ইউসুফের ব্যাপারে আমাদেরকে বিশ্বাস করেন না কেন, অথচ আমরা অবশ্যই তার কল্যাণকামী।', 'They said, "O our father, why do you not entrust us with Joseph while indeed, we are to him sincere counselors?', 'তারা বলল, ‘হে আমাদের আব্বাজান! কী ব্যাপার, আপনি ইউসুফের ব্যাপারে আমাদেরকে বিশ্বাস করেন না কেন, অথচ আমরা অবশ্যই তার কল্যাণকামী।', 'They said, "O our father, why do you not entrust us with Joseph while indeed, we are to him sincere counselors?', NULL, NULL, NULL, NULL, NULL, 'https://everyayah.com/data/Alafasy_128kbps/012011.mp3', now()),
  (12, 12, '', '[{"id":14368,"position":1,"text_uthmani":"أَرْسِلْهُ","transliteration":"arsil''hu","translation_bn":"তাকে পাঠান","root":"رسل","lemma":"أَرْسَلَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":14369,"position":2,"text_uthmani":"مَعَنَا","transliteration":"maʿanā","translation_bn":"আমাদের সাথে","root":"—","lemma":"مَع","grammar_bn":"স্থানবাচক (Location)"},{"id":14370,"position":3,"text_uthmani":"غَدًۭا","transliteration":"ghadan","translation_bn":"আগামীকাল","root":"غدو","lemma":"غَد","grammar_bn":"বিশেষ্য (Noun)"},{"id":14371,"position":4,"text_uthmani":"يَرْتَعْ","transliteration":"yartaʿ","translation_bn":"সে ফল খাবে","root":"رتع","lemma":"يَرْتَعْ","grammar_bn":"ক্রিয়া (Verb)"},{"id":14372,"position":5,"text_uthmani":"وَيَلْعَبْ","transliteration":"wayalʿab","translation_bn":"ও খেলবে","root":"لعب","lemma":"يَلْعَبْ","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":14373,"position":6,"text_uthmani":"وَإِنَّا","transliteration":"wa-innā","translation_bn":"এবং নিশ্চয়ই আমরা","root":"—","lemma":"إِنّ","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":14374,"position":7,"text_uthmani":"لَهُۥ","transliteration":"lahu","translation_bn":"তার জন্যে\"","root":"—","lemma":"لَهُۥ","grammar_bn":"অব্যয় (Preposition)"},{"id":14375,"position":8,"text_uthmani":"لَحَـٰفِظُونَ","transliteration":"laḥāfiẓūna","translation_bn":"অবশ্যই (সবাই) সংরক্ষক\"","root":"حفظ","lemma":"حَٰفِظ","grammar_bn":"দৃঢ়তাবোধক (Emphatic)"},{"id":14376,"position":9,"text_uthmani":"١٢","transliteration":"","translation_bn":"(১২)","root":"—","lemma":"١٢","grammar_bn":"মার্কার"}]'::jsonb, 'arsil''hu maʿanā ghadan yartaʿ wayalʿab wa-innā lahu laḥāfiẓūna', 'তাকে আগামীকাল আমাদের সঙ্গে পাঠিয়ে দিন, সে আমোদ করবে আর খেলবে, আমরা তার পুরোপুরি দেখাশুনা করব।’', 'Send him with us tomorrow that he may eat well and play. And indeed, we will be his guardians.', 'তাকে আগামীকাল আমাদের সঙ্গে পাঠিয়ে দিন, সে আমোদ করবে আর খেলবে, আমরা তার পুরোপুরি দেখাশুনা করব।’', 'Send him with us tomorrow that he may eat well and play. And indeed, we will be his guardians.', NULL, NULL, NULL, NULL, NULL, 'https://everyayah.com/data/Alafasy_128kbps/012012.mp3', now()),
  (12, 13, '', '[{"id":15485,"position":1,"text_uthmani":"قَالَ","transliteration":"qāla","translation_bn":"সে বললো","root":"قول","lemma":"قَالَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":15486,"position":2,"text_uthmani":"إِنِّى","transliteration":"innī","translation_bn":"\"নিশ্চয়ই আমার","root":"—","lemma":"إِنّ","grammar_bn":"অভিঘাত পদ (Accusative)"},{"id":15487,"position":3,"text_uthmani":"لَيَحْزُنُنِىٓ","transliteration":"layaḥzununī","translation_bn":"আমার অবশ্যই চিন্তা লাগে","root":"حزن","lemma":"يَحْزُن","grammar_bn":"দৃঢ়তাবোধক (Emphatic)"},{"id":15488,"position":4,"text_uthmani":"أَن","transliteration":"an","translation_bn":"যে","root":"—","lemma":"أَن\r","grammar_bn":"অধীনস্থ যোজক (Subordinating)"},{"id":15489,"position":5,"text_uthmani":"تَذْهَبُوا۟","transliteration":"tadhhabū","translation_bn":"তোমরা যাবে","root":"ذهب","lemma":"ذَهَبَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":15490,"position":6,"text_uthmani":"بِهِۦ","transliteration":"bihi","translation_bn":"নিয়ে তাকে","root":"—","lemma":"بِهِۦ","grammar_bn":"অব্যয় (Preposition)"},{"id":15491,"position":7,"text_uthmani":"وَأَخَافُ","transliteration":"wa-akhāfu","translation_bn":"এবং আমি ভয় করি","root":"خوف","lemma":"خَافَ","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":15492,"position":8,"text_uthmani":"أَن","transliteration":"an","translation_bn":"যে","root":"—","lemma":"أَن\r","grammar_bn":"অধীনস্থ যোজক (Subordinating)"},{"id":15493,"position":9,"text_uthmani":"يَأْكُلَهُ","transliteration":"yakulahu","translation_bn":"তাকে খেয়ে ফেলবে","root":"اكل","lemma":"أَكَلَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":15494,"position":10,"text_uthmani":"ٱلذِّئْبُ","transliteration":"l-dhi''bu","translation_bn":"নেকড়ে বাঘ","root":"ذاب","lemma":"ذِّئْب","grammar_bn":"শব্দ"},{"id":15495,"position":11,"text_uthmani":"وَأَنتُمْ","transliteration":"wa-antum","translation_bn":"এ অবস্থায় যে তোমরা","root":"—","lemma":"وَأَنتُمْ","grammar_bn":"অবস্থাবাচক (Circumstantial)"},{"id":15496,"position":12,"text_uthmani":"عَنْهُ","transliteration":"ʿanhu","translation_bn":"তার থেকে","root":"—","lemma":"عَن\r","grammar_bn":"অব্যয় (Preposition)"},{"id":15497,"position":13,"text_uthmani":"غَـٰفِلُونَ","transliteration":"ghāfilūna","translation_bn":"অমনোযোগী হয়ে যাবে\"","root":"غفل","lemma":"غَٰفِل","grammar_bn":"বিশেষ্য (Noun)"},{"id":15498,"position":14,"text_uthmani":"١٣","transliteration":"","translation_bn":"(১৩)","root":"—","lemma":"١٣","grammar_bn":"মার্কার"}]'::jsonb, 'qāla innī layaḥzununī an tadhhabū bihi wa-akhāfu an yakulahu l-dhi''bu wa-antum ʿanhu ghāfilūna', 'পিতা বলল, ‘তোমরা যে তাকে নিয়ে যাবে সেটা আমাকে অবশ্যই কষ্ট দেবে আর আমি ভয় করছি যে, নেকড়ে বাঘ তাকে খেয়ে ফেলবে, আর তখন তার সম্পর্কে তোমরা বে-খেয়াল হয়ে থাকবে।’', '[Jacob] said, "Indeed, it saddens me that you should take him, and I fear that a wolf would eat him while you are of him unaware."', 'পিতা বলল, ‘তোমরা যে তাকে নিয়ে যাবে সেটা আমাকে অবশ্যই কষ্ট দেবে আর আমি ভয় করছি যে, নেকড়ে বাঘ তাকে খেয়ে ফেলবে, আর তখন তার সম্পর্কে তোমরা বে-খেয়াল হয়ে থাকবে।’', '[Jacob] said, "Indeed, it saddens me that you should take him, and I fear that a wolf would eat him while you are of him unaware."', NULL, NULL, NULL, NULL, NULL, 'https://everyayah.com/data/Alafasy_128kbps/012013.mp3', now()),
  (12, 14, '', '[{"id":16517,"position":1,"text_uthmani":"قَالُوا۟","transliteration":"qālū","translation_bn":"তারা বললো","root":"قول","lemma":"قَالَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":16518,"position":2,"text_uthmani":"لَئِنْ","transliteration":"la-in","translation_bn":"\"অবশ্য যদি","root":"—","lemma":"إِن\r","grammar_bn":"দৃঢ়তাবোধক (Emphatic)"},{"id":16519,"position":3,"text_uthmani":"أَكَلَهُ","transliteration":"akalahu","translation_bn":"তাকে খায়","root":"اكل","lemma":"أَكَلَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":16520,"position":4,"text_uthmani":"ٱلذِّئْبُ","transliteration":"l-dhi''bu","translation_bn":"নেকড়ে বাঘ","root":"ذاب","lemma":"ذِّئْب","grammar_bn":"শব্দ"},{"id":16521,"position":5,"text_uthmani":"وَنَحْنُ","transliteration":"wanaḥnu","translation_bn":"এ অবস্থায় যে আমরা","root":"—","lemma":"وَنَحْنُ","grammar_bn":"অবস্থাবাচক (Circumstantial)"},{"id":16522,"position":6,"text_uthmani":"عُصْبَةٌ","transliteration":"ʿuṣ''batun","translation_bn":"একটি ঐক্যবদ্ধ দল","root":"عصب","lemma":"عُصْبَة","grammar_bn":"বিশেষ্য (Noun)"},{"id":16523,"position":7,"text_uthmani":"إِنَّآ","transliteration":"innā","translation_bn":"নিশ্চয়ই আমরা","root":"—","lemma":"إِنّ","grammar_bn":"অভিঘাত পদ (Accusative)"},{"id":16524,"position":8,"text_uthmani":"إِذًۭا","transliteration":"idhan","translation_bn":"তাহ''লে","root":"—","lemma":"إِذًا\r","grammar_bn":"উত্তর পদ (Answer)"},{"id":16525,"position":9,"text_uthmani":"لَّخَـٰسِرُونَ","transliteration":"lakhāsirūna","translation_bn":"অবশ্যই ক্ষতিগ্রস্ত হবো\"","root":"خسر","lemma":"خَٰسِرِين","grammar_bn":"দৃঢ়তাবোধক (Emphatic)"},{"id":16526,"position":10,"text_uthmani":"١٤","transliteration":"","translation_bn":"(১৪)","root":"—","lemma":"١٤","grammar_bn":"মার্কার"}]'::jsonb, 'qālū la-in akalahu l-dhi''bu wanaḥnu ʿuṣ''batun innā idhan lakhāsirūna', 'তারা বলল, ‘আমরা একটা দল থাকতে তাকে যদি নেকড়ে বাঘে খেয়ে ফেলে, তাহলে তো আমরা অপদার্থই বনে যাবো।’', 'They said, "If a wolf should eat him while we are a [strong] clan, indeed, we would then be losers."', 'তারা বলল, ‘আমরা একটা দল থাকতে তাকে যদি নেকড়ে বাঘে খেয়ে ফেলে, তাহলে তো আমরা অপদার্থই বনে যাবো।’', 'They said, "If a wolf should eat him while we are a [strong] clan, indeed, we would then be losers."', NULL, NULL, NULL, NULL, NULL, 'https://everyayah.com/data/Alafasy_128kbps/012014.mp3', now()),
  (12, 15, '', '[{"id":17715,"position":1,"text_uthmani":"فَلَمَّا","transliteration":"falammā","translation_bn":"অতঃপর যখন","root":"—","lemma":"لَمَّا\r","grammar_bn":"শব্দ"},{"id":17716,"position":2,"text_uthmani":"ذَهَبُوا۟","transliteration":"dhahabū","translation_bn":"তারা গেলো","root":"ذهب","lemma":"ذَهَبَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":17717,"position":3,"text_uthmani":"بِهِۦ","transliteration":"bihi","translation_bn":"নিয়ে তাকে","root":"—","lemma":"بِهِۦ","grammar_bn":"অব্যয় (Preposition)"},{"id":17718,"position":4,"text_uthmani":"وَأَجْمَعُوٓا۟","transliteration":"wa-ajmaʿū","translation_bn":"এবং তারা একমত হলো","root":"جمع","lemma":"أَجْمَعُ","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":17719,"position":5,"text_uthmani":"أَن","transliteration":"an","translation_bn":"যে","root":"—","lemma":"أَن\r","grammar_bn":"অধীনস্থ যোজক (Subordinating)"},{"id":17720,"position":6,"text_uthmani":"يَجْعَلُوهُ","transliteration":"yajʿalūhu","translation_bn":"তাকে তারা ফেলে দিবে","root":"جعل","lemma":"جَعَلَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":17721,"position":7,"text_uthmani":"فِى","transliteration":"fī","translation_bn":"মধ্যে","root":"—","lemma":"فِى\r","grammar_bn":"অব্যয় (Preposition)"},{"id":17722,"position":8,"text_uthmani":"غَيَـٰبَتِ","transliteration":"ghayābati","translation_bn":"(অন্ধকার) গভীরে","root":"غيب","lemma":"غَيَٰبَت","grammar_bn":"বিশেষ্য (Noun)"},{"id":17723,"position":9,"text_uthmani":"ٱلْجُبِّ ۚ","transliteration":"l-jubi","translation_bn":"কূপের","root":"جبب","lemma":"جُبّ","grammar_bn":"শব্দ"},{"id":17725,"position":10,"text_uthmani":"وَأَوْحَيْنَآ","transliteration":"wa-awḥaynā","translation_bn":"এ অবস্থায় আমরা ওহী করলাম","root":"وحي","lemma":"أَوْحَىٰ^","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":17726,"position":11,"text_uthmani":"إِلَيْهِ","transliteration":"ilayhi","translation_bn":"তার কাছে","root":"—","lemma":"إِلَىٰ\r","grammar_bn":"অব্যয় (Preposition)"},{"id":17727,"position":12,"text_uthmani":"لَتُنَبِّئَنَّهُم","transliteration":"latunabbi-annahum","translation_bn":"\"তাদের তুমি নিশ্চয়ই এক সময় জানিয়ে দিবে","root":"نبا","lemma":"نَبَّأَ","grammar_bn":"দৃঢ়তাবোধক (Emphatic)"},{"id":17728,"position":13,"text_uthmani":"بِأَمْرِهِمْ","transliteration":"bi-amrihim","translation_bn":"সম্পর্কে তাদের কাজ","root":"امر","lemma":"أَمْر","grammar_bn":"অব্যয় (Preposition)"},{"id":17729,"position":14,"text_uthmani":"هَـٰذَا","transliteration":"hādhā","translation_bn":"এই","root":"—","lemma":"هَٰذَا","grammar_bn":"নির্দেশক সর্বনাম (Demonstrative)"},{"id":17730,"position":15,"text_uthmani":"وَهُمْ","transliteration":"wahum","translation_bn":"(এখন) অথচ তারা","root":"—","lemma":"وَهُمْ","grammar_bn":"অবস্থাবাচক (Circumstantial)"},{"id":17731,"position":16,"text_uthmani":"لَا","transliteration":"lā","translation_bn":"না","root":"—","lemma":"لَا\r","grammar_bn":"না-বোধক (Negative)"},{"id":17732,"position":17,"text_uthmani":"يَشْعُرُونَ","transliteration":"yashʿurūna","translation_bn":"তারা অনুভব করছে\"","root":"شعر","lemma":"يَشْعُرُ","grammar_bn":"ক্রিয়া (Verb)"},{"id":17733,"position":18,"text_uthmani":"١٥","transliteration":"","translation_bn":"(১৫)","root":"—","lemma":"١٥","grammar_bn":"মার্কার"}]'::jsonb, 'falammā dhahabū bihi wa-ajmaʿū an yajʿalūhu fī ghayābati l-jubi wa-awḥaynā ilayhi latunabbi-annahum bi-amrihim hādhā wahum lā yashʿurūna', 'অতঃপর যখন তারা তাকে নিয়ে গেল, আর তাকে অন্ধ কূপে ফেলার ব্যাপারে মতৈক্যে পৌঁছল, এমতাবস্থায় আমি ইউসুফকে ওয়াহী করলাম- এক সময় আসবে যখন তুমি তাদেরকে তাদের এ কর্মের কথা অবশ্য অবশ্যই ব্যক্ত করবে।’ অথচ তারা (অর্থাৎ ইউসুফের ভাইয়েরা) মোটেই টের পাবে না।', 'So when they took him [out] and agreed to put him into the bottom of the well... But We inspired to him, "You will surely inform them [someday] about this affair of theirs while they do not perceive [your identity]."', 'অতঃপর যখন তারা তাকে নিয়ে গেল, আর তাকে অন্ধ কূপে ফেলার ব্যাপারে মতৈক্যে পৌঁছল, এমতাবস্থায় আমি ইউসুফকে ওয়াহী করলাম- এক সময় আসবে যখন তুমি তাদেরকে তাদের এ কর্মের কথা অবশ্য অবশ্যই ব্যক্ত করবে।’ অথচ তারা (অর্থাৎ ইউসুফের ভাইয়েরা) মোটেই টের পাবে না।', 'So when they took him [out] and agreed to put him into the bottom of the well... But We inspired to him, "You will surely inform them [someday] about this affair of theirs while they do not perceive [your identity]."', NULL, NULL, NULL, NULL, NULL, 'https://everyayah.com/data/Alafasy_128kbps/012015.mp3', now()),
  (12, 16, '', '[{"id":18724,"position":1,"text_uthmani":"وَجَآءُوٓ","transliteration":"wajāū","translation_bn":"এবং তারা আসলো","root":"جيا","lemma":"جَا^ءَ","grammar_bn":"শব্দ"},{"id":18725,"position":2,"text_uthmani":"أَبَاهُمْ","transliteration":"abāhum","translation_bn":"তাদের পিতার কাছে","root":"ابو","lemma":"أَبٌ","grammar_bn":"বিশেষ্য (Noun)"},{"id":18726,"position":3,"text_uthmani":"عِشَآءًۭ","transliteration":"ʿishāan","translation_bn":"সন্ধ্যাকালে","root":"عشو","lemma":"عِشَا^ء","grammar_bn":"বিশেষ্য (Noun)"},{"id":18727,"position":4,"text_uthmani":"يَبْكُونَ","transliteration":"yabkūna","translation_bn":"কাঁদতে কাঁদতে","root":"بكي","lemma":"بَكَتْ","grammar_bn":"ক্রিয়া (Verb)"},{"id":18728,"position":5,"text_uthmani":"١٦","transliteration":"","translation_bn":"(১৬)","root":"—","lemma":"١٦","grammar_bn":"মার্কার"}]'::jsonb, 'wajāū abāhum ʿishāan yabkūna', 'রাতের প্রথম প্রহরে তারা তাদের পিতার কাছে কাঁদতে কাঁদতে আসল।', 'And they came to their father at night, weeping.', 'রাতের প্রথম প্রহরে তারা তাদের পিতার কাছে কাঁদতে কাঁদতে আসল।', 'And they came to their father at night, weeping.', NULL, NULL, NULL, NULL, NULL, 'https://everyayah.com/data/Alafasy_128kbps/012016.mp3', now()),
  (12, 17, '', '[{"id":19804,"position":1,"text_uthmani":"قَالُوا۟","transliteration":"qālū","translation_bn":"তারা বললো","root":"قول","lemma":"قَالَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":19805,"position":2,"text_uthmani":"يَـٰٓأَبَانَآ","transliteration":"yāabānā","translation_bn":"\"হে আমাদের পিতা","root":"ابو","lemma":"أَبٌ","grammar_bn":"সম্বোধন পদ (Vocative)"},{"id":19806,"position":3,"text_uthmani":"إِنَّا","transliteration":"innā","translation_bn":"নিশ্চয়ই আমরা","root":"—","lemma":"إِنّ","grammar_bn":"অভিঘাত পদ (Accusative)"},{"id":19807,"position":4,"text_uthmani":"ذَهَبْنَا","transliteration":"dhahabnā","translation_bn":"আমরা গিয়েছিলাম","root":"ذهب","lemma":"ذَهَبَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":19808,"position":5,"text_uthmani":"نَسْتَبِقُ","transliteration":"nastabiqu","translation_bn":"দৌড়ের পাল্লা দিচ্ছিলাম","root":"سبق","lemma":"ٱسْتَبَقَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":19809,"position":6,"text_uthmani":"وَتَرَكْنَا","transliteration":"wataraknā","translation_bn":"ও আমরা রেখে গিয়েছিলাম","root":"ترك","lemma":"تَرَكَ","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":19810,"position":7,"text_uthmani":"يُوسُفَ","transliteration":"yūsufa","translation_bn":"ইউসুফকে","root":"—","lemma":"يُوسُف","grammar_bn":"নামবাচক বিশেষ্য (Proper Noun)"},{"id":19811,"position":8,"text_uthmani":"عِندَ","transliteration":"ʿinda","translation_bn":"কাছে","root":"عند","lemma":"عِند","grammar_bn":"স্থানবাচক (Location)"},{"id":19812,"position":9,"text_uthmani":"مَتَـٰعِنَا","transliteration":"matāʿinā","translation_bn":"আমাদের মালপত্রের","root":"متع","lemma":"مَتَٰع","grammar_bn":"বিশেষ্য (Noun)"},{"id":19813,"position":10,"text_uthmani":"فَأَكَلَهُ","transliteration":"fa-akalahu","translation_bn":"তাকে তখন খেয়ে ফেলে","root":"اكل","lemma":"أَكَلَ","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":19814,"position":11,"text_uthmani":"ٱلذِّئْبُ ۖ","transliteration":"l-dhi''bu","translation_bn":"নেকড়ে বাঘ","root":"ذاب","lemma":"ذِّئْب","grammar_bn":"শব্দ"},{"id":19816,"position":12,"text_uthmani":"وَمَآ","transliteration":"wamā","translation_bn":"অথচ নন","root":"—","lemma":"مَا","grammar_bn":"শব্দ"},{"id":19817,"position":13,"text_uthmani":"أَنتَ","transliteration":"anta","translation_bn":"আপনি","root":"—","lemma":"أَنتَ","grammar_bn":"সর্বনাম (Pronoun)"},{"id":19818,"position":14,"text_uthmani":"بِمُؤْمِنٍۢ","transliteration":"bimu''minin","translation_bn":"বিশ্বাসকারী","root":"امن","lemma":"مُؤْمِن","grammar_bn":"অব্যয় (Preposition)"},{"id":19819,"position":15,"text_uthmani":"لَّنَا","transliteration":"lanā","translation_bn":"আমাদেরকে","root":"—","lemma":"لَّنَا","grammar_bn":"অব্যয় (Preposition)"},{"id":19820,"position":16,"text_uthmani":"وَلَوْ","transliteration":"walaw","translation_bn":"যদিও","root":"—","lemma":"لَو\r","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":19821,"position":17,"text_uthmani":"كُنَّا","transliteration":"kunnā","translation_bn":"আমরা হই","root":"كون","lemma":"كَانَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":19822,"position":18,"text_uthmani":"صَـٰدِقِينَ","transliteration":"ṣādiqīna","translation_bn":"(সবাই) সত্যবাদী\"","root":"صدق","lemma":"صَادِق","grammar_bn":"বিশেষ্য (Noun)"},{"id":19823,"position":19,"text_uthmani":"١٧","transliteration":"","translation_bn":"(১৭)","root":"—","lemma":"١٧","grammar_bn":"মার্কার"}]'::jsonb, 'qālū yāabānā innā dhahabnā nastabiqu wataraknā yūsufa ʿinda matāʿinā fa-akalahu l-dhi''bu wamā anta bimu''minin lanā walaw kunnā ṣādiqīna', 'তারা বলল, ‘হে আমাদের আব্বাজান! আমরা দৌড়ের প্রতিযোগিতা করছিলাম, আর ইউসুফকে আমরা আমাদের জিনিসপত্রের কাছে রেখে গিয়েছিলাম, তখন তাকে নেকড়ে বাঘে খেয়ে ফেলল, কিন্তু আপনি তো আমাদের কথা বিশ্বাস করবেন না, আমরা সত্যবাদী হলেও।’', 'They said, "O our father, indeed we went racing each other and left Joseph with our possessions, and a wolf ate him. But you would not believe us, even if we were truthful."', 'তারা বলল, ‘হে আমাদের আব্বাজান! আমরা দৌড়ের প্রতিযোগিতা করছিলাম, আর ইউসুফকে আমরা আমাদের জিনিসপত্রের কাছে রেখে গিয়েছিলাম, তখন তাকে নেকড়ে বাঘে খেয়ে ফেলল, কিন্তু আপনি তো আমাদের কথা বিশ্বাস করবেন না, আমরা সত্যবাদী হলেও।’', 'They said, "O our father, indeed we went racing each other and left Joseph with our possessions, and a wolf ate him. But you would not believe us, even if we were truthful."', NULL, NULL, NULL, NULL, NULL, 'https://everyayah.com/data/Alafasy_128kbps/012017.mp3', now()),
  (12, 18, '', '[{"id":20881,"position":1,"text_uthmani":"وَجَآءُو","transliteration":"wajāū","translation_bn":"এবং তারা আসলো","root":"جيا","lemma":"جَا^ءَ","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":20882,"position":2,"text_uthmani":"عَلَىٰ","transliteration":"ʿalā","translation_bn":"উপর","root":"—","lemma":"عَلَىٰ\r","grammar_bn":"অব্যয় (Preposition)"},{"id":20883,"position":3,"text_uthmani":"قَمِيصِهِۦ","transliteration":"qamīṣihi","translation_bn":"তার জামার","root":"قمص","lemma":"قَمِيص","grammar_bn":"বিশেষ্য (Noun)"},{"id":20884,"position":4,"text_uthmani":"بِدَمٍۢ","transliteration":"bidamin","translation_bn":"নিয়ে রক্ত (লাগিয়ে)","root":"دمو","lemma":"دَم","grammar_bn":"অব্যয় (Preposition)"},{"id":20885,"position":5,"text_uthmani":"كَذِبٍۢ ۚ","transliteration":"kadhibin","translation_bn":"মিথ্যা","root":"كذب","lemma":"كَذِب","grammar_bn":"বিশেষ্য (Noun)"},{"id":20887,"position":6,"text_uthmani":"قَالَ","transliteration":"qāla","translation_bn":"সে বললো","root":"قول","lemma":"قَالَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":20888,"position":7,"text_uthmani":"بَلْ","transliteration":"bal","translation_bn":"\"বরং","root":"—","lemma":"بَل\r","grammar_bn":"প্রত্যাহার পদ (Retraction)"},{"id":20889,"position":8,"text_uthmani":"سَوَّلَتْ","transliteration":"sawwalat","translation_bn":"সাজিয়ে দিয়েছে","root":"سول","lemma":"سَوَّلَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":20890,"position":9,"text_uthmani":"لَكُمْ","transliteration":"lakum","translation_bn":"তোমাদেরকে","root":"—","lemma":"لَكُمْ","grammar_bn":"অব্যয় (Preposition)"},{"id":20891,"position":10,"text_uthmani":"أَنفُسُكُمْ","transliteration":"anfusukum","translation_bn":"তোমাদের মন","root":"نفس","lemma":"نَفْس","grammar_bn":"বিশেষ্য (Noun)"},{"id":20892,"position":11,"text_uthmani":"أَمْرًۭا ۖ","transliteration":"amran","translation_bn":"এ কাজ","root":"امر","lemma":"أَمْر","grammar_bn":"বিশেষ্য (Noun)"},{"id":20894,"position":12,"text_uthmani":"فَصَبْرٌۭ","transliteration":"faṣabrun","translation_bn":"অতএব ধৈর্য ধরাই","root":"صبر","lemma":"صَبْر","grammar_bn":"শব্দ"},{"id":20895,"position":13,"text_uthmani":"جَمِيلٌۭ ۖ","transliteration":"jamīlun","translation_bn":"উত্তম","root":"جمل","lemma":"جَمِيل","grammar_bn":"বিশেষণ (Adjective)"},{"id":20897,"position":14,"text_uthmani":"وَٱللَّهُ","transliteration":"wal-lahu","translation_bn":"এবং আল্লাহই","root":"اله","lemma":"ٱللَّه","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":20898,"position":15,"text_uthmani":"ٱلْمُسْتَعَانُ","transliteration":"l-mus''taʿānu","translation_bn":"সাহায্যস্থল","root":"عون","lemma":"مُسْتَعَان","grammar_bn":"শব্দ"},{"id":20899,"position":16,"text_uthmani":"عَلَىٰ","transliteration":"ʿalā","translation_bn":"এক্ষেত্রে","root":"—","lemma":"عَلَىٰ\r","grammar_bn":"অব্যয় (Preposition)"},{"id":20900,"position":17,"text_uthmani":"مَا","transliteration":"mā","translation_bn":"যা","root":"—","lemma":"مَا\r","grammar_bn":"সাপেক্ষ সর্বনাম (Relative)"},{"id":20901,"position":18,"text_uthmani":"تَصِفُونَ","transliteration":"taṣifūna","translation_bn":"তোমরা বর্ণনা করছো\"","root":"وصف","lemma":"يَصِفُ","grammar_bn":"ক্রিয়া (Verb)"},{"id":20902,"position":19,"text_uthmani":"١٨","transliteration":"","translation_bn":"(১৮)","root":"—","lemma":"١٨","grammar_bn":"মার্কার"}]'::jsonb, 'wajāū ʿalā qamīṣihi bidamin kadhibin qāla bal sawwalat lakum anfusukum amran faṣabrun jamīlun wal-lahu l-mus''taʿānu ʿalā mā taṣifūna', 'তারা তার জামায় মিছেমিছি রক্ত মাখিয়ে নিয়ে এসেছিল। পিতা বলল, ‘না, বরং তোমাদের প্রবৃত্তি তোমাদেরকে একটা কাহিনী বানাতে উদ্বুদ্ধ করেছে। ঠিক আছে, আমি পুরোপুরি ধৈর্য ধারণ করব, তোমরা যা বানিয়েছ সে ব্যাপারে আল্লাহই আমার আশ্রয়স্থল।’', 'And they brought upon his shirt false blood. [Jacob] said, "Rather, your souls have enticed you to something, so patience is most fitting. And Allah is the one sought for help against that which you describe."', 'তারা তার জামায় মিছেমিছি রক্ত মাখিয়ে নিয়ে এসেছিল। পিতা বলল, ‘না, বরং তোমাদের প্রবৃত্তি তোমাদেরকে একটা কাহিনী বানাতে উদ্বুদ্ধ করেছে। ঠিক আছে, আমি পুরোপুরি ধৈর্য ধারণ করব, তোমরা যা বানিয়েছ সে ব্যাপারে আল্লাহই আমার আশ্রয়স্থল।’', 'And they brought upon his shirt false blood. [Jacob] said, "Rather, your souls have enticed you to something, so patience is most fitting. And Allah is the one sought for help against that which you describe."', NULL, NULL, NULL, NULL, NULL, 'https://everyayah.com/data/Alafasy_128kbps/012018.mp3', now()),
  (12, 19, '', '[{"id":21948,"position":1,"text_uthmani":"وَجَآءَتْ","transliteration":"wajāat","translation_bn":"এবং আসলো","root":"جيا","lemma":"جَا^ءَ","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":21949,"position":2,"text_uthmani":"سَيَّارَةٌۭ","transliteration":"sayyāratun","translation_bn":"এক যাত্রীদল","root":"سير","lemma":"سَيَّارَة","grammar_bn":"বিশেষ্য (Noun)"},{"id":21950,"position":3,"text_uthmani":"فَأَرْسَلُوا۟","transliteration":"fa-arsalū","translation_bn":"অতঃপর তারা পাঠালো","root":"رسل","lemma":"أَرْسَلَ","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":21951,"position":4,"text_uthmani":"وَارِدَهُمْ","transliteration":"wāridahum","translation_bn":"তাদের পানি সংগ্রাহককে","root":"ورد","lemma":"وَارِد","grammar_bn":"বিশেষ্য (Noun)"},{"id":21952,"position":5,"text_uthmani":"فَأَدْلَىٰ","transliteration":"fa-adlā","translation_bn":"সে তখন নামিয়ে দিলো","root":"دلو","lemma":"أَدْلَىٰ","grammar_bn":"শব্দ"},{"id":21953,"position":6,"text_uthmani":"دَلْوَهُۥ ۖ","transliteration":"dalwahu","translation_bn":"তার বালতি","root":"دلو","lemma":"دَلْو","grammar_bn":"বিশেষ্য (Noun)"},{"id":21955,"position":7,"text_uthmani":"قَالَ","transliteration":"qāla","translation_bn":"সে বললো","root":"قول","lemma":"قَالَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":21956,"position":8,"text_uthmani":"يَـٰبُشْرَىٰ","transliteration":"yābush''rā","translation_bn":"\"কি সুখবর!","root":"بشر","lemma":"بُشْرَىٰ","grammar_bn":"সম্বোধন পদ (Vocative)"},{"id":21957,"position":9,"text_uthmani":"هَـٰذَا","transliteration":"hādhā","translation_bn":"এযে","root":"—","lemma":"هَٰذَا","grammar_bn":"নির্দেশক সর্বনাম (Demonstrative)"},{"id":21958,"position":10,"text_uthmani":"غُلَـٰمٌۭ ۚ","transliteration":"ghulāmun","translation_bn":"একটি ছেলে\"","root":"غلم","lemma":"غُلَٰم","grammar_bn":"বিশেষ্য (Noun)"},{"id":21960,"position":11,"text_uthmani":"وَأَسَرُّوهُ","transliteration":"wa-asarrūhu","translation_bn":"এবং তাকে লুকালো","root":"سرر","lemma":"أَسَرَّ","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":21961,"position":12,"text_uthmani":"بِضَـٰعَةًۭ ۚ","transliteration":"biḍāʿatan","translation_bn":"পণ্যদ্রব্য হিসেবে","root":"بضع","lemma":"بِضَٰعَة","grammar_bn":"বিশেষ্য (Noun)"},{"id":21963,"position":13,"text_uthmani":"وَٱللَّهُ","transliteration":"wal-lahu","translation_bn":"এবং আল্লাহ","root":"اله","lemma":"ٱللَّه","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":21964,"position":14,"text_uthmani":"عَلِيمٌۢ","transliteration":"ʿalīmun","translation_bn":"খুবই অবহিত","root":"علم","lemma":"عَلِيم","grammar_bn":"বিশেষণ (Adjective)"},{"id":21965,"position":15,"text_uthmani":"بِمَا","transliteration":"bimā","translation_bn":"বিষয়ে যা","root":"—","lemma":"مَا\r","grammar_bn":"অব্যয় (Preposition)"},{"id":21966,"position":16,"text_uthmani":"يَعْمَلُونَ","transliteration":"yaʿmalūna","translation_bn":"তারা কাজ করছিলো","root":"عمل","lemma":"عَمِلَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":21967,"position":17,"text_uthmani":"١٩","transliteration":"","translation_bn":"(১৯)","root":"—","lemma":"١٩","grammar_bn":"মার্কার"}]'::jsonb, 'wajāat sayyāratun fa-arsalū wāridahum fa-adlā dalwahu qāla yābush''rā hādhā ghulāmun wa-asarrūhu biḍāʿatan wal-lahu ʿalīmun bimā yaʿmalūna', 'সেখানে একটা কাফেলা আসলো। তারা তাদের পানি সংগ্রহকারীকে পাঠালো। সে তার পানির বালতি নামিয়ে দিল। সে বলল, ‘কী খুশির খবর! এ যে দেখছি এক বালক!’ তারা তাকে পণ্য দ্রব্য জ্ঞানে লুকিয়ে দিল, আর তারা যা করছিল সে সম্পর্কে আল্লাহ খুবই অবহিত।', 'And there came a company of travelers; then they sent their water drawer, and he let down his bucket. He said, "Good news! Here is a boy." And they concealed him, [taking him] as merchandise; and Allah was knowing of what they did.', 'সেখানে একটা কাফেলা আসলো। তারা তাদের পানি সংগ্রহকারীকে পাঠালো। সে তার পানির বালতি নামিয়ে দিল। সে বলল, ‘কী খুশির খবর! এ যে দেখছি এক বালক!’ তারা তাকে পণ্য দ্রব্য জ্ঞানে লুকিয়ে দিল, আর তারা যা করছিল সে সম্পর্কে আল্লাহ খুবই অবহিত।', 'And there came a company of travelers; then they sent their water drawer, and he let down his bucket. He said, "Good news! Here is a boy." And they concealed him, [taking him] as merchandise; and Allah was knowing of what they did.', NULL, NULL, NULL, NULL, NULL, 'https://everyayah.com/data/Alafasy_128kbps/012019.mp3', now()),
  (12, 20, '', '[{"id":22454,"position":1,"text_uthmani":"وَشَرَوْهُ","transliteration":"washarawhu","translation_bn":"এবং তাকে তারা বিক্রি করে দিলো","root":"شري","lemma":"شَرَ","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":22455,"position":2,"text_uthmani":"بِثَمَنٍۭ","transliteration":"bithamanin","translation_bn":"দাম দিয়ে","root":"ثمن","lemma":"ثَمَن","grammar_bn":"অব্যয় (Preposition)"},{"id":22456,"position":3,"text_uthmani":"بَخْسٍۢ","transliteration":"bakhsin","translation_bn":"সামান্য","root":"بخس","lemma":"بَخْس","grammar_bn":"বিশেষণ (Adjective)"},{"id":22457,"position":4,"text_uthmani":"دَرَٰهِمَ","transliteration":"darāhima","translation_bn":"দিরহাম","root":"درهم","lemma":"دَرَٰهِم","grammar_bn":"বিশেষ্য (Noun)"},{"id":22458,"position":5,"text_uthmani":"مَعْدُودَةٍۢ","transliteration":"maʿdūdatin","translation_bn":"কয়েকটি মাত্র","root":"عدد","lemma":"مَّعْدُودَة","grammar_bn":"বিশেষণ (Adjective)"},{"id":22459,"position":6,"text_uthmani":"وَكَانُوا۟","transliteration":"wakānū","translation_bn":"এবং তারা ছিলো","root":"كون","lemma":"كَانَ","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":22460,"position":7,"text_uthmani":"فِيهِ","transliteration":"fīhi","translation_bn":"তার (দামের) ব্যাপারে","root":"—","lemma":"فِى\r","grammar_bn":"অব্যয় (Preposition)"},{"id":22461,"position":8,"text_uthmani":"مِنَ","transliteration":"mina","translation_bn":"অন্তর্ভুক্ত","root":"—","lemma":"مِن\r","grammar_bn":"অব্যয় (Preposition)"},{"id":22462,"position":9,"text_uthmani":"ٱلزَّٰهِدِينَ","transliteration":"l-zāhidīna","translation_bn":"নিরাসক্তদের","root":"زهد","lemma":"زَّٰهِدِين","grammar_bn":"শব্দ"},{"id":22463,"position":10,"text_uthmani":"٢٠","transliteration":"","translation_bn":"(২০)","root":"—","lemma":"٢٠","grammar_bn":"মার্কার"}]'::jsonb, 'washarawhu bithamanin bakhsin darāhima maʿdūdatin wakānū fīhi mina l-zāhidīna', 'তারা তাকে স্বল্প মূল্যে- মাত্র কয়টি দিরহামের বিনিময়ে বিক্রি করে দিল, তারা ছিল তাকে তুচ্ছ জ্ঞানকারী!', 'And they sold him for a reduced price - a few dirhams - and they were, concerning him, of those content with little.', 'তারা তাকে স্বল্প মূল্যে- মাত্র কয়টি দিরহামের বিনিময়ে বিক্রি করে দিল, তারা ছিল তাকে তুচ্ছ জ্ঞানকারী!', 'And they sold him for a reduced price - a few dirhams - and they were, concerning him, of those content with little.', NULL, NULL, NULL, NULL, NULL, 'https://everyayah.com/data/Alafasy_128kbps/012020.mp3', now()),
  (12, 21, '', '[{"id":24047,"position":1,"text_uthmani":"وَقَالَ","transliteration":"waqāla","translation_bn":"এবং বললো","root":"قول","lemma":"قَالَ","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":24048,"position":2,"text_uthmani":"ٱلَّذِى","transliteration":"alladhī","translation_bn":"যে","root":"—","lemma":"ٱلَّذِى","grammar_bn":"সাপেক্ষ সর্বনাম (Relative)"},{"id":24049,"position":3,"text_uthmani":"ٱشْتَرَىٰهُ","transliteration":"ish''tarāhu","translation_bn":"তাকে কিনেছিলো","root":"شري","lemma":"ٱشْتَرَىٰ","grammar_bn":"ক্রিয়া (Verb)"},{"id":24050,"position":4,"text_uthmani":"مِن","transliteration":"min","translation_bn":"থেকে","root":"—","lemma":"مِن\r","grammar_bn":"অব্যয় (Preposition)"},{"id":24051,"position":5,"text_uthmani":"مِّصْرَ","transliteration":"miṣ''ra","translation_bn":"মিশর","root":"مصر","lemma":"مِصْر","grammar_bn":"নামবাচক বিশেষ্য (Proper Noun)"},{"id":24052,"position":6,"text_uthmani":"لِٱمْرَأَتِهِۦٓ","transliteration":"li-im''ra-atihi","translation_bn":"তার স্ত্রীকে","root":"مرا","lemma":"ٱمْرَأَت","grammar_bn":"অব্যয় (Preposition)"},{"id":24053,"position":7,"text_uthmani":"أَكْرِمِى","transliteration":"akrimī","translation_bn":"\"সম্মানজনক ব্যবস্থা করো","root":"كرم","lemma":"أَكْرَمَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":24054,"position":8,"text_uthmani":"مَثْوَىٰهُ","transliteration":"mathwāhu","translation_bn":"তার থাকার","root":"ثوي","lemma":"مَثْوًى","grammar_bn":"বিশেষ্য (Noun)"},{"id":24055,"position":9,"text_uthmani":"عَسَىٰٓ","transliteration":"ʿasā","translation_bn":"আশা করা যায়","root":"عسي","lemma":"عَسَى","grammar_bn":"ক্রিয়া (Verb)"},{"id":24056,"position":10,"text_uthmani":"أَن","transliteration":"an","translation_bn":"যে","root":"—","lemma":"أَن\r","grammar_bn":"অধীনস্থ যোজক (Subordinating)"},{"id":24057,"position":11,"text_uthmani":"يَنفَعَنَآ","transliteration":"yanfaʿanā","translation_bn":"আমাদের সে উপকারে আসবে","root":"نفع","lemma":"نَفَعَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":24058,"position":12,"text_uthmani":"أَ