  (13, 1, '', '[{"id":769,"position":1,"text_uthmani":"الٓمٓر ۚ","transliteration":"alif-lam-meem-ra","translation_bn":"আলিফ লা-ম মী-ম রা-","root":"—","lemma":"الٓمٓر ۚ","grammar_bn":"শব্দ"},{"id":771,"position":2,"text_uthmani":"تِلْكَ","transliteration":"til''ka","translation_bn":"এই","root":"—","lemma":"ذَٰلِك","grammar_bn":"নির্দেশক সর্বনাম (Demonstrative)"},{"id":772,"position":3,"text_uthmani":"ءَايَـٰتُ","transliteration":"āyātu","translation_bn":"আয়াতসমূহ","root":"ايي","lemma":"ءَايَة","grammar_bn":"বিশেষ্য (Noun)"},{"id":773,"position":4,"text_uthmani":"ٱلْكِتَـٰبِ ۗ","transliteration":"l-kitābi","translation_bn":"কিতাবের","root":"كتب","lemma":"كِتَٰب","grammar_bn":"শব্দ"},{"id":775,"position":5,"text_uthmani":"وَٱلَّذِىٓ","transliteration":"wa-alladhī","translation_bn":"এবং যা","root":"—","lemma":"ٱلَّذِى","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":776,"position":6,"text_uthmani":"أُنزِلَ","transliteration":"unzila","translation_bn":"অবতীর্ণ হয়েছে","root":"نزل","lemma":"أَنزَلَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":777,"position":7,"text_uthmani":"إِلَيْكَ","transliteration":"ilayka","translation_bn":"তোমার প্রতি","root":"—","lemma":"إِلَىٰ\r","grammar_bn":"অব্যয় (Preposition)"},{"id":778,"position":8,"text_uthmani":"مِن","transliteration":"min","translation_bn":"থেকে","root":"—","lemma":"مِن\r","grammar_bn":"অব্যয় (Preposition)"},{"id":779,"position":9,"text_uthmani":"رَّبِّكَ","transliteration":"rabbika","translation_bn":"তোমার রবের","root":"ربب","lemma":"رَبّ","grammar_bn":"বিশেষ্য (Noun)"},{"id":780,"position":10,"text_uthmani":"ٱلْحَقُّ","transliteration":"l-ḥaqu","translation_bn":"(তা) সত্য","root":"حقق","lemma":"حَقّ","grammar_bn":"শব্দ"},{"id":781,"position":11,"text_uthmani":"وَلَـٰكِنَّ","transliteration":"walākinna","translation_bn":"কিন্তু","root":"—","lemma":"لَٰكِنّ","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":782,"position":12,"text_uthmani":"أَكْثَرَ","transliteration":"akthara","translation_bn":"অধিকাংশ","root":"كثر","lemma":"أَكْثَر","grammar_bn":"বিশেষ্য (Noun)"},{"id":783,"position":13,"text_uthmani":"ٱلنَّاسِ","transliteration":"l-nāsi","translation_bn":"মানুষ","root":"نوس","lemma":"نَّاس","grammar_bn":"শব্দ"},{"id":784,"position":14,"text_uthmani":"لَا","transliteration":"lā","translation_bn":"না","root":"—","lemma":"لَا\r","grammar_bn":"না-বোধক (Negative)"},{"id":785,"position":15,"text_uthmani":"يُؤْمِنُونَ","transliteration":"yu''minūna","translation_bn":"ঈমান আনে","root":"امن","lemma":"ءَامَنَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":786,"position":16,"text_uthmani":"١","transliteration":"","translation_bn":"(১)","root":"—","lemma":"١","grammar_bn":"মার্কার"}]'::jsonb, 'alif-lam-meem-ra til''ka āyātu l-kitābi wa-alladhī unzila ilayka min rabbika l-ḥaqu walākinna akthara l-nāsi lā yu''minūna', 'আলিফ-লাম-মীম-র, এগুলো কিতাবের আয়াতসমূহ, আর তোমার প্রতিপালকের নিকট থেকে তোমার প্রতি যা অবতীর্ণ হয়েছে তা প্রকৃত সত্য, কিন্তু অধিকাংশ মানুষই ঈমান আনে না।', 'Alif, Lam, Meem, Ra. These are the verses of the Book; and what has been revealed to you from your Lord is the truth, but most of the people do not believe.', 'আলিফ-লাম-মীম-র, এগুলো কিতাবের আয়াতসমূহ, আর তোমার প্রতিপালকের নিকট থেকে তোমার প্রতি যা অবতীর্ণ হয়েছে তা প্রকৃত সত্য, কিন্তু অধিকাংশ মানুষই ঈমান আনে না।', 'Alif, Lam, Meem, Ra. These are the verses of the Book; and what has been revealed to you from your Lord is the truth, but most of the people do not believe.', NULL, NULL, NULL, NULL, NULL, 'https://everyayah.com/data/Alafasy_128kbps/013001.mp3', now()),
  (13, 2, '', '[{"id":1846,"position":1,"text_uthmani":"ٱللَّهُ","transliteration":"al-lahu","translation_bn":"(তিনিই) আল্লাহ","root":"اله","lemma":"ٱللَّه","grammar_bn":"নামবাচক বিশেষ্য (Proper Noun)"},{"id":1847,"position":2,"text_uthmani":"ٱلَّذِى","transliteration":"alladhī","translation_bn":"যিনি","root":"—","lemma":"ٱلَّذِى","grammar_bn":"সাপেক্ষ সর্বনাম (Relative)"},{"id":1848,"position":3,"text_uthmani":"رَفَعَ","transliteration":"rafaʿa","translation_bn":"উপরে স্থাপন করেছেন","root":"رفع","lemma":"رَفَعَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":1849,"position":4,"text_uthmani":"ٱلسَّمَـٰوَٰتِ","transliteration":"l-samāwāti","translation_bn":"আকাশমন্ডলী","root":"سمو","lemma":"سَمَا^ء","grammar_bn":"শব্দ"},{"id":1850,"position":5,"text_uthmani":"بِغَيْرِ","transliteration":"bighayri","translation_bn":"ছাড়া","root":"غير","lemma":"غَيْر","grammar_bn":"অব্যয় (Preposition)"},{"id":1851,"position":6,"text_uthmani":"عَمَدٍۢ","transliteration":"ʿamadin","translation_bn":"কোন খুঁটি","root":"عمد","lemma":"عَمَد","grammar_bn":"বিশেষ্য (Noun)"},{"id":1852,"position":7,"text_uthmani":"تَرَوْنَهَا ۖ","transliteration":"tarawnahā","translation_bn":"তা তোমরা দেখছো","root":"راي","lemma":"رَءَا","grammar_bn":"ক্রিয়া (Verb)"},{"id":1854,"position":8,"text_uthmani":"ثُمَّ","transliteration":"thumma","translation_bn":"এরপর","root":"—","lemma":"ثُمّ\r","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":1855,"position":9,"text_uthmani":"ٱسْتَوَىٰ","transliteration":"is''tawā","translation_bn":"উঠেছেন","root":"سوي","lemma":"ٱسْتَوَىٰ^","grammar_bn":"ক্রিয়া (Verb)"},{"id":1856,"position":10,"text_uthmani":"عَلَى","transliteration":"ʿalā","translation_bn":"উপর","root":"—","lemma":"عَلَىٰ\r","grammar_bn":"অব্যয় (Preposition)"},{"id":1857,"position":11,"text_uthmani":"ٱلْعَرْشِ ۖ","transliteration":"l-ʿarshi","translation_bn":"আরশের","root":"عرش","lemma":"عَرْش","grammar_bn":"শব্দ"},{"id":1859,"position":12,"text_uthmani":"وَسَخَّرَ","transliteration":"wasakhara","translation_bn":"এবং অ