  (14, 1, '', '[{"id":815,"position":1,"text_uthmani":"الٓر ۚ","transliteration":"alif-lam-ra","translation_bn":"আলিফ- লা-ম রা-","root":"—","lemma":"الٓر ۚ","grammar_bn":"শব্দ"},{"id":817,"position":2,"text_uthmani":"كِتَـٰبٌ","transliteration":"kitābun","translation_bn":"(এই) কিতাব","root":"كتب","lemma":"كِتَٰب","grammar_bn":"বিশেষ্য (Noun)"},{"id":818,"position":3,"text_uthmani":"أَنزَلْنَـٰهُ","transliteration":"anzalnāhu","translation_bn":"তা আমরা অবতীর্ণ করেছি","root":"نزل","lemma":"أَنزَلَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":819,"position":4,"text_uthmani":"إِلَيْكَ","transliteration":"ilayka","translation_bn":"তোমার প্রতি","root":"—","lemma":"إِلَىٰ\r","grammar_bn":"অব্যয় (Preposition)"},{"id":820,"position":5,"text_uthmani":"لِتُخْرِجَ","transliteration":"litukh''rija","translation_bn":"যেন তুমি বের করো","root":"خرج","lemma":"أَخْرَجَ","grammar_bn":"শব্দ"},{"id":821,"position":6,"text_uthmani":"ٱلنَّاسَ","transliteration":"l-nāsa","translation_bn":"মানুষকে","root":"نوس","lemma":"نَّاس","grammar_bn":"শব্দ"},{"id":822,"position":7,"text_uthmani":"مِنَ","transliteration":"mina","translation_bn":"থেকে","root":"—","lemma":"مِن\r","grammar_bn":"অব্যয় (Preposition)"},{"id":823,"position":8,"text_uthmani":"ٱلظُّلُمَـٰتِ","transliteration":"l-ẓulumāti","translation_bn":"অন্ধকারসমূহ","root":"ظلم","lemma":"ظُلُمَٰت","grammar_bn":"শব্দ"},{"id":824,"position":9,"text_uthmani":"إِلَى","transliteration":"ilā","translation_bn":"দিকে","root":"—","lemma":"إِلَىٰ\r","grammar_bn":"অব্যয় (Preposition)"},{"id":825,"position":10,"text_uthmani":"ٱلنُّورِ","transliteration":"l-nūri","translation_bn":"আলোর","root":"نور","lemma":"نُور","grammar_bn":"শব্দ"},{"id":826,"position":11,"text_uthmani":"بِإِذْنِ","transliteration":"bi-idh''ni","translation_bn":"অনুমতিক্রমে","root":"اذن","lemma":"إِذْن","grammar_bn":"অব্যয় (Preposition)"},{"id":827,"position":12,"text_uthmani":"رَبِّهِمْ","transliteration":"rabbihim","translation_bn":"তাদের রবের","root":"ربب","lemma":"رَبّ","grammar_bn":"বিশেষ্য (Noun)"},{"id":828,"position":13,"text_uthmani":"إِلَىٰ","transliteration":"ilā","translation_bn":"দিকে","root":"—","lemma":"إِلَىٰ\r","grammar_bn":"অব্যয় (Preposition)"},{"id":829,"position":14,"text_uthmani":"صِرَٰطِ","transliteration":"ṣirāṭi","translation_bn":"পথের","root":"صرط","lemma":"صِرَٰط","grammar_bn":"বিশেষ্য (Noun)"},{"id":830,"position":15,"text_uthmani":"ٱلْعَزِيزِ","transliteration":"l-ʿazīzi","translation_bn":"পরাক্রমশালী","root":"عزز","lemma":"عَزِيز","grammar_bn":"শব্দ"},{"id":831,"position":16,"text_uthmani":"ٱلْحَمِيدِ","transliteration":"l-ḥamīdi","translation_bn":"প্রশংসিত","root":"حمد","lemma":"حَمِيد","grammar_bn":"শব্দ"},{"id":832,"position":17,"text_uthmani":"١","transliteration":"","translation_bn":"(১)","root":"—","lemma":"١","grammar_bn":"মার্কার"}]'::jsonb, 'alif-lam-ra kitābun anzalnāhu ilayka litukh''rija l-nāsa mina l-ẓulumāti ilā l-nūri bi-idh''ni rabbihim ilā ṣirāṭi l-ʿazīzi l-ḥamīdi', 'আলিফ-লাম-র, একটা কিতাব যা তোমার প্রতি অবতীর্ণ করেছি যাতে তুমি মানুষকে তাদের প্রতিপালকের নির্দেশে অন্ধকার থেকে নিয়ে আসতে পার আলোর দিকে- মহাপরাক্রমশালী প্রশংসিতের পথে।', 'Alif, Lam, Ra. [This is] a Book which We have revealed to you, [O Muhammad], that you might bring mankind out of darknesses into the light by permission of their Lord - to the path of the Exalted in Might, the Praiseworthy -', 'আলিফ-লাম-র, একটা কিতাব যা তোমার প্রতি অবতীর্ণ করেছি যাতে তুমি মানুষকে তাদের প্রতিপালকের নির্দেশে অন্ধকার থেকে নিয়ে আসতে পার আলোর দিকে- মহাপরাক্রমশালী প্রশংসিতের পথে।', 'Alif, Lam, Ra. [This is] a Book which We have revealed to you, [O Muhammad], that you might bring mankind out of darknesses into the light by permission of their Lord - to the path of the Exalted in Might, the Praiseworthy -', NULL, NULL, NULL, NULL, NULL, 'https://everyayah.com/data/Alafasy_128kbps/014001.mp3', now()),
  (14, 2, '', '[{"id":1925,"position":1,"text_uthmani":"ٱللَّهِ","transliteration":"al-lahi","translation_bn":"আল্লাহ","root":"اله","lemma":"ٱللَّه","grammar_bn":"নামবাচক বিশেষ্য (Proper Noun)"},{"id":1926,"position":2,"text_uthmani":"ٱلَّذِى","transliteration":"alladhī","translation_bn":"তিনিই","root":"—","lemma":"ٱلَّذِى","grammar_bn":"সাপেক্ষ সর্বনাম (Relative)"},{"id":1927,"position":3,"text_uthmani":"لَهُۥ","transliteration":"lahu","translation_bn":"জন্যে যার","root":"—","lemma":"لَهُۥ","grammar_bn":"অব্যয় (Preposition)"},{"id":1928,"position":4,"text_uthmani":"مَا","transliteration":"mā","translation_bn":"যা কিছূু","root":"—","lemma":"مَا\r","grammar_bn":"সাপেক্ষ সর্বনাম (Relative)"},{"id":1929,"position":5,"text_uthmani":"فِى","transliteration":"fī","translation_bn":"মধ্যে আছে","root":"—","lemma":"فِى\r","grammar_bn":"অব্যয় (Preposition)"},{"id":1930,"position":6,"text_uthmani":"ٱلسَّمَـٰوَٰتِ","transliteration":"l-samāwāti","translation_bn":"আকাশের","root":"سمو","lemma":"سَمَا^ء","grammar_bn":"শব্দ"},{"id":1931,"position":7,"text_uthmani":"وَمَا","transliteration":"wamā","translation_bn":"ও যা কিছু","root":"—","lemma":"مَا\r","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":1932,"position":8,"text_uthmani":"فِى","transliteration":"fī","translation_bn":"মধ্যে আছে","root":"—","lemma":"فِى\r","grammar_bn":"অব্যয় (Preposition)"},{"id":1933,"position":9,"text_uthmani":"ٱلْأَرْضِ ۗ","transliteration":"l-arḍi","translation_bn":"পৃথিবীর","root":"ارض","lemma":"أَرْض","grammar_bn":"শব্দ"},{"id":1935,"position":10,"text_uthmani":"وَوَيْلٌۭ","transliteration":"wawaylun","translation_bn":"এবং দুর্ভোগ","root":"—","lemma":"وَيْل","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":1936,"position":11,"text_uthmani":"لِّلْكَـٰفِرِينَ","transliteration":"lil''kāfirīna","translation_bn":"কাফেরদের জন্যে","root":"كفر","lemma":"كَٰفِرُون","grammar_bn":"অব্যয় (Preposition)"},{"id":1937,"position":12,"text_uthmani":"مِنْ","transliteration":"min","translation_bn":"হতে","root":"—","lemma":"مِن\r","grammar_bn":"অব্যয় (Preposition)"},{"id":1938,"position":13,"text_uthmani":"عَذَابٍۢ","transliteration":"ʿadhābin","translation_bn":"শাস্তি","root":"عذب","lemma":"عَذَاب","grammar_bn":"বিশেষ্য (Noun)"},{"id":1939,"position":14,"text_uthmani":"شَدِيدٍ","transliteration":"shadīdin","translation_bn":"কঠোর","root":"شدد","lemma":"شَدِيد","grammar_bn":"বিশেষণ (Adjective)"},{"id":1940,"position":15,"text_uthmani":"٢","transliteration":"","translation_bn":"(২)","root":"—","lemma":"٢","grammar_bn":"মার্কার"}]'::jsonb, 'al-lahi alladhī lahu mā fī l-samāwāti wamā fī l-arḍi wawaylun lil''kāfirīna min ʿadhābin shadīdin', 'আল্লাহ- আসমানসমূহে যা কিছু আছে আর পৃথিবীতে যা কিছু আছে, সবই তাঁর মালিকানাধীন। কিন্তু কাফিরদের জন্য আছে কঠিন শাস্তির দুর্ভোগ।', 'Allah, to whom belongs whatever is in the heavens and whatever is on the earth. And woe to the disbelievers from a severe punishment', 'আল্লাহ- আসমানসমূহে যা কিছু আছে আর পৃথিবীতে যা কিছু আছে, সবই তাঁর মালিকানাধীন। কিন্তু কাফিরদের জন্য আছে কঠিন শাস্তির দুর্ভোগ।', 'Allah, to whom belongs whatever is in the heavens and whatever is on the earth. And woe to the disbelievers from a severe punishment', NULL, NULL, NULL, NULL, NULL, 'https://everyayah.com/data/Alafasy_128kbps/014002.mp3', now()),
  (14, 3, '', '[{"id":3079,"position":1,"text_uthmani":"ٱلَّذِينَ","transliteration":"alladhīna","translation_bn":"যারা","root":"—","lemma":"ٱلَّذِى","grammar_bn":"সাপেক্ষ সর্বনাম (Relative)"},{"id":3080,"position":2,"text_uthmani":"يَسْتَحِبُّونَ","transliteration":"yastaḥibbūna","translation_bn":"প্রাধান্য দেয়","root":"حبب","lemma":"ٱسْتَحَبُّ","grammar_bn":"ক্রিয়া (Verb)"},{"id":3081,"position":3,"text_uthmani":"ٱلْحَيَوٰةَ","transliteration":"l-ḥayata","translation_bn":"জীবনকে","root":"حيي","lemma":"حَيَوٰة","grammar_bn":"শব্দ"},{"id":3082,"position":4,"text_uthmani":"ٱلدُّنْيَا","transliteration":"l-dun''yā","translation_bn":"পার্থিব","root":"دنو","lemma":"دُّنْيَا","grammar_bn":"শব্দ"},{"id":3083,"position":5,"text_uthmani":"عَلَى","transliteration":"ʿalā","translation_bn":"উপর","root":"—","lemma":"عَلَىٰ\r","grammar_bn":"অব্যয় (Preposition)"},{"id":3084,"position":6,"text_uthmani":"ٱلْـَٔاخِرَةِ","transliteration":"l-ākhirati","translation_bn":"আখিরাতের","root":"اخر","lemma":"ا^خِر","grammar_bn":"শব্দ"},{"id":3085,"position":7,"text_uthmani":"وَيَصُدُّونَ","transliteration":"wayaṣuddūna","translation_bn":"ও (মানুষকে) বাধা দেয়","root":"صدد","lemma":"صَدَّ","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":3086,"position":8,"text_uthmani":"عَن","transliteration":"ʿan","translation_bn":"থেকে","root":"—","lemma":"عَن\r","grammar_bn":"অব্যয় (Preposition)"},{"id":3087,"position":9,"text_uthmani":"سَبِيلِ","transliteration":"sabīli","translation_bn":"পথ","root":"سبل","lemma":"سَبِيل","grammar_bn":"বিশেষ্য (Noun)"},{"id":3088,"position":10,"text_uthmani":"ٱللَّهِ","transliteration":"l-lahi","translation_bn":"আল্লাহর","root":"اله","lemma":"ٱللَّه","grammar_bn":"নামবাচক বিশেষ্য (Proper Noun)"},{"id":3089,"position":11,"text_uthmani":"وَيَبْغُونَهَا","transliteration":"wayabghūnahā","translation_bn":"ও তাকে করতে চায়","root":"بغي","lemma":"بَغَىٰ","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":3090,"position":12,"text_uthmani":"عِوَجًا ۚ","transliteration":"ʿiwajan","translation_bn":"বাঁকা","root":"عوج","lemma":"عِوَج","grammar_bn":"বিশেষ্য (Noun)"},{"id":3092,"position":13,"text_uthmani":"أُو۟لَـٰٓئِكَ","transliteration":"ulāika","translation_bn":"ঐসব লোক","root":"—","lemma":"أُولَٰ^ئِك","grammar_bn":"নির্দেশক সর্বনাম (Demonstrative)"},{"id":3093,"position":14,"text_uthmani":"فِى","transliteration":"fī","translation_bn":"মধ্যে আছে","root":"—","lemma":"فِى\r","grammar_bn":"অব্যয় (Preposition)"},{"id":3094,"position":15,"text_uthmani":"ضَلَـٰلٍۭ","transliteration":"ḍalālin","translation_bn":"বিপথে","root":"ضلل","lemma":"ضَلَٰل","grammar_bn":"বিশেষ্য (Noun)"},{"id":3095,"position":16,"text_uthmani":"بَعِيدٍۢ","transliteration":"baʿīdin","translation_bn":"(বহু) দূরে","root":"بعد","lemma":"بَعِيد","grammar_bn":"বিশেষণ (Adjective)"},{"id":3096,"position":17,"text_uthmani":"٣","transliteration":"","translation_bn":"(৩)","root":"—","lemma":"٣","grammar_bn":"মার্কার"}]'::jsonb, 'alladhīna yastaḥibbūna l-ḥayata l-dun''yā ʿalā l-ākhirati wayaṣuddūna ʿan sabīli l-lahi wayabghūnahā ʿiwajan ulāika fī ḍalālin baʿīdin', 'যারা আখেরাতের তুলনায় দুনিয়ার জিন্দিগীকে শ্রেয় জ্ঞান করে, যারা আল্লাহর পথ থেকে (লোকদেরকে) বিরত রাখে আর তাতে বক্রতা আনার আকাঙ্ক্ষা পোষণ করে। এরা গোমরাহীতে বহু দূরে চলে গেছে।', 'The ones who prefer the worldly life over the Hereafter and avert [people] from the way of Allah, seeking to make it (seem) deviant. Those are in extreme error.', 'যারা আখেরাতের তুলনায় দুনিয়ার জিন্দিগীকে শ্রেয় জ্ঞান করে, যারা আল্লাহর পথ থেকে (লোকদেরকে) বিরত রাখে আর তাতে বক্রতা আনার আকাঙ্ক্ষা পোষণ করে। এরা গোমরাহীতে বহু দূরে চলে গেছে।', 'The ones who prefer the worldly life over the Hereafter and avert [people] from the way of Allah, seeking to make it (seem) deviant. Those are in extreme error.', NULL, NULL, NULL, NULL, NULL, 'https://everyayah.com/data/Alafasy_128kbps/014003.mp3', now()),
  (14, 4, '', '[{"id":4473,"position":1,"text_uthmani":"وَمَآ","transliteration":"wamā","translation_bn":"এবং নি","root":"—","lemma":"مَا\r","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":4474,"position":2,"text_uthmani":"أَرْسَلْنَا","transliteration":"arsalnā","translation_bn":"আমরা পাঠাই","root":"رسل","lemma":"أَرْسَلَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":4475,"position":3,"text_uthmani":"مِن","transliteration":"min","translation_bn":"কোনো","root":"—","lemma":"مِن\r","grammar_bn":"অব্যয় (Preposition)"},{"id":4476,"position":4,"text_uthmani":"رَّسُولٍ","transliteration":"rasūlin","translation_bn":"রাসূলকে","root":"رسل","lemma":"رَسُول","grammar_bn":"বিশেষ্য (Noun)"},{"id":4477,"position":5,"text_uthmani":"إِلَّا","transliteration":"illā","translation_bn":"ছাড়া","root":"—","lemma":"إِلَّا\r","grammar_bn":"সীমাবদ্ধতা (Restriction)"},{"id":4478,"position":6,"text_uthmani":"بِلِسَانِ","transliteration":"bilisāni","translation_bn":"দিয়ে ভাষা","root":"لسن","lemma":"لِسَان","grammar_bn":"অব্যয় (Preposition)"},{"id":4479,"position":7,"text_uthmani":"قَوْمِهِۦ","transliteration":"qawmihi","translation_bn":"তার জাতির","root":"قوم","lemma":"قَوْم","grammar_bn":"বিশেষ্য (Noun)"},{"id":4480,"position":8,"text_uthmani":"لِيُبَيِّنَ","transliteration":"liyubayyina","translation_bn":"যেন সুস্পষ্ট করে বর্ণনা করেন","root":"بين","lemma":"بَيَّنُ","grammar_bn":"শব্দ"},{"id":4481,"position":9,"text_uthmani":"لَهُمْ ۖ","transliteration":"lahum","translation_bn":"তাদেরকে","root":"—","lemma":"لَهُمْ ۖ","grammar_bn":"অব্যয় (Preposition)"},{"id":4483,"position":10,"text_uthmani":"فَيُضِلُّ","transliteration":"fayuḍillu","translation_bn":"অতঃপর পথভ্রষ্ট করেন","root":"ضلل","lemma":"أَضَلَّ","grammar_bn":"শব্দ"},{"id":4484,"position":11,"text_uthmani":"ٱللَّهُ","transliteration":"l-lahu","translation_bn":"আল্লাহ","root":"اله","lemma":"ٱللَّه","grammar_bn":"নামবাচক বিশেষ্য (Proper Noun)"},{"id":4485,"position":12,"text_uthmani":"مَن","transliteration":"man","translation_bn":"যাকে","root":"—","lemma":"مَن\r","grammar_bn":"সাপেক্ষ সর্বনাম (Relative)"},{"id":4486,"position":13,"text_uthmani":"يَشَآءُ","transliteration":"yashāu","translation_bn":"ইচ্ছে করেন","root":"شيا","lemma":"شَا^ءَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":4487,"position":14,"text_uthmani":"وَيَهْدِى","transliteration":"wayahdī","translation_bn":"ও সৎ পথ দেখান","root":"هدي","lemma":"هَدَى","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":4488,"position":15,"text_uthmani":"مَن","transliteration":"man","translation_bn":"যাকে","root":"—","lemma":"مَن\r","grammar_bn":"সাপেক্ষ সর্বনাম (Relative)"},{"id":4489,"position":16,"text_uthmani":"يَشَآءُ ۚ","transliteration":"yashāu","translation_bn":"ইচ্ছে করেন","root":"شيا","lemma":"شَا^ءَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":4491,"position":17,"text_uthmani":"وَهُوَ","transliteration":"wahuwa","translation_bn":"এবং তিনি","root":"—","lemma":"وَهُوَ","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":4492,"position":18,"text_uthmani":"ٱلْعَزِيزُ","transliteration":"l-ʿazīzu","translation_bn":"পরাক্রমশালী","root":"عزز","lemma":"عَزِيز","grammar_bn":"শব্দ"},{"id":4493,"position":19,"text_uthmani":"ٱلْحَكِيمُ","transliteration":"l-ḥakīmu","translation_bn":"প্রজ্ঞাময়","root":"حكم","lemma":"حَكِيم","grammar_bn":"শব্দ"},{"id":4494,"position":20,"text_uthmani":"٤","transliteration":"","translation_bn":"(৪)","root":"—","lemma":"٤","grammar_bn":"মার্কার"}]'::jsonb, 'wamā arsalnā min rasūlin illā bilisāni qawmihi liyubayyina lahum fayuḍillu l-lahu man yashāu wayahdī man yashāu wahuwa l-ʿazīzu l-ḥakīmu', 'আমি কোন রসূলকেই তার জাতির ভাষা ছাড়া পাঠাইনি যাতে তাদের কাছে স্পষ্টভাবে (আমার নির্দেশগুলো) বর্ণনা করতে পারে। অতঃপর আল্লাহ যাকে ইচ্ছে পথহারা করেছেন, আর যাকে ইচ্ছে সঠিক পথ দেখিয়েছেন, তিনি বড়ই পরাক্রান্ত, বিজ্ঞানময়।', 'And We did not send any messenger except [speaking] in the language of his people to state clearly for them, and Allah sends astray [thereby] whom He wills and guides whom He wills. And He is the Exalted in Might, the Wise.', 'আমি কোন রসূলকেই তার জাতির ভাষা ছাড়া পাঠাইনি যাতে তাদের কাছে স্পষ্টভাবে (আমার নির্দেশগুলো) বর্ণনা করতে পারে। অতঃপর আল্লাহ যাকে ইচ্ছে পথহারা করেছেন, আর যাকে ইচ্ছে সঠিক পথ দেখিয়েছেন, তিনি বড়ই পরাক্রান্ত, বিজ্ঞানময়।', 'And We did not send any messenger except [speaking] in the language of his people to state clearly for them, and Allah sends astray [thereby] whom He wills and guides whom He wills. And He is the Exalted in Might, the Wise.', NULL, NULL, NULL, NULL, NULL, 'https://everyayah.com/data/Alafasy_128kbps/014004.mp3', now()),
  (14, 5, '', '[{"id":5719,"position":1,"text_uthmani":"وَلَقَدْ","transliteration":"walaqad","translation_bn":"এবং নিশ্চয়ই","root":"—","lemma":"قَد\r","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":5720,"position":2,"text_uthmani":"أَرْسَلْنَا","transliteration":"arsalnā","translation_bn":"আমরা প্রেরণ করেছিলাম","root":"رسل","lemma":"أَرْسَلَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":5721,"position":3,"text_uthmani":"مُوسَىٰ","transliteration":"mūsā","translation_bn":"মুসাকে","root":"—","lemma":"مُوسَىٰ","grammar_bn":"নামবাচক বিশেষ্য (Proper Noun)"},{"id":5722,"position":4,"text_uthmani":"بِـَٔايَـٰتِنَآ","transliteration":"biāyātinā","translation_bn":"দিয়ে আমাদের নিদর্শনাদি","root":"ايي","lemma":"ءَايَة","grammar_bn":"অব্যয় (Preposition)"},{"id":5723,"position":5,"text_uthmani":"أَنْ","transliteration":"an","translation_bn":"যে","root":"—","lemma":"أَن\r","grammar_bn":"উদ্দেশ্যবাচক (Intention)"},{"id":5724,"position":6,"text_uthmani":"أَخْرِجْ","transliteration":"akhrij","translation_bn":"\"বের করো","root":"خرج","lemma":"أَخْرَجَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":5725,"position":7,"text_uthmani":"قَوْمَكَ","transliteration":"qawmaka","translation_bn":"তোমার জাতিকে","root":"قوم","lemma":"قَوْم","grammar_bn":"বিশেষ্য (Noun)"},{"id":5726,"position":8,"text_uthmani":"مِنَ","transliteration":"mina","translation_bn":"থেকে","root":"—","lemma":"مِن\r","grammar_bn":"অব্যয় (Preposition)"},{"id":5727,"position":9,"text_uthmani":"ٱلظُّلُمَـٰتِ","transliteration":"l-ẓulumāti","translation_bn":"অন্ধকারসমূহ","root":"ظلم","lemma":"ظُلُمَٰت","grammar_bn":"শব্দ"},{"id":5728,"position":10,"text_uthmani":"إِلَى","transliteration":"ilā","translation_bn":"দিকে","root":"—","lemma":"إِلَىٰ\r","grammar_bn":"অব্যয় (Preposition)"},{"id":5729,"position":11,"text_uthmani":"ٱلنُّورِ","transliteration":"l-nūri","translation_bn":"আলোর","root":"نور","lemma":"نُور","grammar_bn":"শব্দ"},{"id":5730,"position":12,"text_uthmani":"وَذَكِّرْهُم","transliteration":"wadhakkir''hum","translation_bn":"এবং তাদেরকে উপদেশ দাও","root":"ذكر","lemma":"ذُكِّرَ","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":5731,"position":13,"text_uthmani":"بِأَيَّىٰمِ","transliteration":"bi-ayyāmi","translation_bn":"দিয়ে দিনগুলো","root":"يوم","lemma":"يَوْم","grammar_bn":"অব্যয় (Preposition)"},{"id":5732,"position":14,"text_uthmani":"ٱللَّهِ ۚ","transliteration":"l-lahi","translation_bn":"আল্লাহর\"","root":"اله","lemma":"ٱللَّه","grammar_bn":"নামবাচক বিশেষ্য (Proper Noun)"},{"id":5734,"position":15,"text_uthmani":"إِنَّ","transliteration":"inna","translation_bn":"নিশ্চয়ই","root":"—","lemma":"إِنّ","grammar_bn":"অভিঘাত পদ (Accusative)"},{"id":5735,"position":16,"text_uthmani":"فِى","transliteration":"fī","translation_bn":"মধ্যে আছে","root":"—","lemma":"فِى\r","grammar_bn":"অব্যয় (Preposition)"},{"id":5736,"position":17,"text_uthmani":"ذَٰلِكَ","transliteration":"dhālika","translation_bn":"এর","root":"—","lemma":"ذَٰلِك","grammar_bn":"নির্দেশক সর্বনাম (Demonstrative)"},{"id":5737,"position":18,"text_uthmani":"لَـَٔايَـٰتٍۢ","transliteration":"laāyātin","translation_bn":"অবশ্যই নিদর্শনাবলী","root":"ايي","lemma":"ءَايَة","grammar_bn":"দৃঢ়তাবোধক (Emphatic)"},{"id":5738,"position":19,"text_uthmani":"لِّكُلِّ","transliteration":"likulli","translation_bn":"জন্যে প্রত্যেক","root":"كلل","lemma":"كُلّ","grammar_bn":"অব্যয় (Preposition)"},{"id":5739,"position":20,"text_uthmani":"صَبَّارٍۢ","transliteration":"ṣabbārin","translation_bn":"পরম ধৈর্যশীল","root":"صبر","lemma":"صَبَّار","grammar_bn":"বিশেষণ (Adjective)"},{"id":5740,"position":21,"text_uthmani":"شَكُورٍۢ","transliteration":"shakūrin","translation_bn":"পরম কৃতজ্ঞ ব্যক্তির","root":"شكر","lemma":"شَكُور","grammar_bn":"বিশেষণ (Adjective)"},{"id":5741,"position":22,"text_uthmani":"٥","transliteration":"","translation_bn":"(৫)","root":"—","lemma":"٥","grammar_bn":"মার্কার"}]'::jsonb, 'walaqad arsalnā mūsā biāyātinā an akhrij qawmaka mina l-ẓulumāti ilā l-nūri wadhakkir''hum bi-ayyāmi l-lahi inna fī dhālika laāyātin likulli ṣabbārin shakūrin', 'আর অবশ্যই আমি মূসাকে আমার নিদর্শনসমূহ দিয়ে পাঠিয়েছিলাম আর বলেছিলাম, তোমার জাতিকে অন্ধকার থেকে আলোতে বের করে আন, আর তাদেরকে আল্লাহর হুকুমে ঘটিত অতীতের ঘটনাবলী দিয়ে উপদেশ দাও। এতে প্রত্যেক পরম সহিষ্ণু ও পরম কৃতজ্ঞ ব্যক্তির জন্য অবশ্যই নিদর্শনসমূহ রয়েছে।', 'And We certainly sent Moses with Our signs, [saying], "Bring out your people from darknesses into the light and remind them of the days of Allah." Indeed in that are signs for everyone patient and grateful.', 'আর অবশ্যই আমি মূসাকে আমার নিদর্শনসমূহ দিয়ে পাঠিয়েছিলাম আর বলেছিলাম, তোমার জাতিকে অন্ধকার থেকে আলোতে বের করে আন, আর তাদেরকে আল্লাহর হুকুমে ঘটিত অতীতের ঘটনাবলী দিয়ে উপদেশ দাও। এতে প্রত্যেক পরম সহিষ্ণু ও পরম কৃতজ্ঞ ব্যক্তির জন্য অবশ্যই নিদর্শনসমূহ রয়েছে।', 'And We certainly sent Moses with Our signs, [saying], "Bring out your people from darknesses into the light and remind them of the days of Allah." Indeed in that are signs for everyone patient and grateful.', NULL, NULL, NULL, NULL, NULL, 'https://everyayah.com/data/Alafasy_128kbps/014005.mp3', now()),
  (14, 6, '', '[{"id":7009,"position":1,"text_uthmani":"وَإِذْ","transliteration":"wa-idh","translation_bn":"এবং স্মরণ করো যখন","root":"—","lemma":"إِذ\r","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":7010,"position":2,"text_uthmani":"قَالَ","transliteration":"qāla","translation_bn":"বলেছিলো","root":"قول","lemma":"قَالَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":7011,"position":3,"text_uthmani":"مُوسَىٰ","transliteration":"mūsā","translation_bn":"মুসা","root":"—","lemma":"مُوسَىٰ","grammar_bn":"নামবাচক বিশেষ্য (Proper Noun)"},{"id":7012,"position":4,"text_uthmani":"لِقَوْمِهِ","transliteration":"liqawmihi","translation_bn":"তার জাতিকে","root":"قوم","lemma":"قَوْم","grammar_bn":"অব্যয় (Preposition)"},{"id":7013,"position":5,"text_uthmani":"ٱذْكُرُوا۟","transliteration":"udh''kurū","translation_bn":"\"তোমরা স্মরণ করো","root":"ذكر","lemma":"ذَكَرَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":7014,"position":6,"text_uthmani":"نِعْمَةَ","transliteration":"niʿ''mata","translation_bn":"অনুগ্রহ","root":"نعم","lemma":"نِعْمَة","grammar_bn":"বিশেষ্য (Noun)"},{"id":7015,"position":7,"text_uthmani":"ٱللَّهِ","transliteration":"l-lahi","translation_bn":"আল্লাহর","root":"اله","lemma":"ٱللَّه","grammar_bn":"নামবাচক বিশেষ্য (Proper Noun)"},{"id":7016,"position":8,"text_uthmani":"عَلَيْكُمْ","transliteration":"ʿalaykum","translation_bn":"তোমাদের উপর","root":"—","lemma":"عَلَىٰ\r","grammar_bn":"অব্যয় (Preposition)"},{"id":7017,"position":9,"text_uthmani":"إِذْ","transliteration":"idh","translation_bn":"যখন","root":"—","lemma":"إِذ\r","grammar_bn":"কালবাচক (Time)"},{"id":7018,"position":10,"text_uthmani":"أَنجَىٰكُم","transliteration":"anjākum","translation_bn":"তোমাদের তিনি রক্ষা করেন","root":"نجو","lemma":"أَنجَىٰ","grammar_bn":"ক্রিয়া (Verb)"},{"id":7019,"position":11,"text_uthmani":"مِّنْ","transliteration":"min","translation_bn":"থেকে","root":"—","lemma":"مِن\r","grammar_bn":"অব্যয় (Preposition)"},{"id":7020,"position":12,"text_uthmani":"ءَالِ","transliteration":"āli","translation_bn":"সম্প্রদায়","root":"اول","lemma":"ءَال","grammar_bn":"বিশেষ্য (Noun)"},{"id":7021,"position":13,"text_uthmani":"فِرْعَوْنَ","transliteration":"fir''ʿawna","translation_bn":"ফিরাউনের","root":"—","lemma":"فِرْعَوْن","grammar_bn":"নামবাচক বিশেষ্য (Proper Noun)"},{"id":7022,"position":14,"text_uthmani":"يَسُومُونَكُمْ","transliteration":"yasūmūnakum","translation_bn":"তোমাদের উপর তারা প্রয়োগ করতো","root":"سوم","lemma":"يَسُومُ","grammar_bn":"ক্রিয়া (Verb)"},{"id":7023,"position":15,"text_uthmani":"سُوٓءَ","transliteration":"sūa","translation_bn":"নিকৃষ্ট","root":"سوا","lemma":"سُو^ء","grammar_bn":"বিশেষ্য (Noun)"},{"id":7024,"position":16,"text_uthmani":"ٱلْعَذَابِ","transliteration":"l-ʿadhābi","translation_bn":"শাস্তি","root":"عذب","lemma":"عَذَاب","grammar_bn":"শব্দ"},{"id":7025,"position":17,"text_uthmani":"وَيُذَبِّحُونَ","transliteration":"wayudhabbiḥūna","translation_bn":"এবং তারা জবেহ করতো","root":"ذبح","lemma":"يُذَبِّحُ","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":7026,"position":18,"text_uthmani":"أَبْنَآءَكُمْ","transliteration":"abnāakum","translation_bn":"তোমাদের পুত্রসন্তানদেরকে","root":"بني","lemma":"ٱبْن","grammar_bn":"বিশেষ্য (Noun)"},{"id":7027,"position":19,"text_uthmani":"وَيَسْتَحْيُونَ","transliteration":"wayastaḥyūna","translation_bn":"ও তারা জীবিত রাখতো","root":"حيي","lemma":"يَسْتَحْىِ.^","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":7028,"position":20,"text_uthmani":"نِسَآءَكُمْ ۚ","transliteration":"nisāakum","translation_bn":"তোমাদের মেয়েদেরকে","root":"نسو","lemma":"نِسَا^ء","grammar_bn":"বিশেষ্য (Noun)"},{"id":7030,"position":21,"text_uthmani":"وَفِى","transliteration":"wafī","translation_bn":"এবং মধ্যে (ছিলো)","root":"—","lemma":"فِى\r","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":7031,"position":22,"text_uthmani":"ذَٰلِكُم","transliteration":"dhālikum","translation_bn":"এর তোমাদের জন্যে","root":"—","lemma":"ذَٰلِك","grammar_bn":"নির্দেশক সর্বনাম (Demonstrative)"},{"id":7032,"position":23,"text_uthmani":"بَلَآءٌۭ","transliteration":"balāon","translation_bn":"পরীক্ষা","root":"بلو","lemma":"بَلَا^ء","grammar_bn":"বিশেষ্য (Noun)"},{"id":7033,"position":24,"text_uthmani":"مِّن","transliteration":"min","translation_bn":"থেকে","root":"—","lemma":"مِن\r","grammar_bn":"অব্যয় (Preposition)"},{"id":7034,"position":25,"text_uthmani":"رَّبِّكُمْ","transliteration":"rabbikum","translation_bn":"তোমাদের রবের","root":"ربب","lemma":"رَبّ","grammar_bn":"বিশেষ্য (Noun)"},{"id":7035,"position":26,"text_uthmani":"عَظِيمٌۭ","transliteration":"ʿaẓīmun","translation_bn":"বিরাট\"","root":"عظم","lemma":"عَظِيم","grammar_bn":"বিশেষণ (Adjective)"},{"id":7036,"position":27,"text_uthmani":"٦","transliteration":"","translation_bn":"(৬)","root":"—","lemma":"٦","grammar_bn":"মার্কার"}]'::jsonb, 'wa-idh qāla mūsā liqawmihi udh''kurū niʿ''mata l-lahi ʿalaykum idh anjākum min āli fir''ʿawna yasūmūnakum sūa l-ʿadhābi wayudhabbiḥūna abnāakum wayastaḥyūna nisāakum wafī dhālikum balāon min rabbikum ʿaẓīmun', 'স্মরণ কর, যখন মূসা তার সম্প্রদায়কে বলেছিল, ‘তোমরা তোমাদের প্রতি আল্লাহর নি‘মাতের কথা স্মরণ কর যখন তিনি তোমাদেরকে ফির‘আওনী গোষ্ঠী থেকে রক্ষা করেছিলেন যারা তোমাদেরকে জঘন্য রকমের শাস্তিতে পিষ্ট করছিল। তোমাদের পুত্রদেরকে তারা হত্যা করত আর তোমাদের নারীদেরকে জীবিত রাখত। এটা ছিল তোমাদের জন্য আল্লাহর পক্ষ হতে এক কঠিন পরীক্ষা।', 'And [recall, O Children of Israel], when Moses said to His people, "Remember the favor of Allah upon you when He saved you from the people of Pharaoh, who were afflicting you with the worst torment and were slaughtering your [newborn] sons and keeping your females alive. And in that was a great trial from your Lord.', 'স্মরণ কর, যখন মূসা তার সম্প্রদায়কে বলেছিল, ‘তোমরা তোমাদের প্রতি আল্লাহর নি‘মাতের কথা স্মরণ কর যখন তিনি তোমাদেরকে ফির‘আওনী গোষ্ঠী থেকে রক্ষা করেছিলেন যারা তোমাদেরকে জঘন্য রকমের শাস্তিতে পিষ্ট করছিল। তোমাদের পুত্রদেরকে তারা হত্যা করত আর তোমাদের নারীদেরকে জীবিত রাখত। এটা ছিল তোমাদের জন্য আল্লাহর পক্ষ হতে এক কঠিন পরীক্ষা।', 'And [recall, O Children of Israel], when Moses said to His people, "Remember the favor of Allah upon you when He saved you from the people of Pharaoh, who were afflicting you with the worst torment and were slaughtering your [newborn] sons and keeping your females alive. And in that was a great trial from your Lord.', NULL, NULL, NULL, NULL, NULL, 'https://everyayah.com/data/Alafasy_128kbps/014006.mp3', now()),
  (14, 7, '', '[{"id":8324,"position":1,"text_uthmani":"وَإِذْ","transliteration":"wa-idh","translation_bn":"এবং (স্মরণ করো) যখন","root":"—","lemma":"إِذ\r","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":8325,"position":2,"text_uthmani":"تَأَذَّنَ","transliteration":"ta-adhana","translation_bn":"ঘোষণা করেন","root":"اذن","lemma":"تَأَذَّنَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":8326,"position":3,"text_uthmani":"رَبُّكُمْ","transliteration":"rabbukum","translation_bn":"তোমার রব","root":"ربب","lemma":"رَبّ","grammar_bn":"বিশেষ্য (Noun)"},{"id":8327,"position":4,"text_uthmani":"لَئِن","transliteration":"la-in","translation_bn":"\"অবশ্যই যদি","root":"—","lemma":"إِن\r","grammar_bn":"দৃঢ়তাবোধক (Emphatic)"},{"id":8328,"position":5,"text_uthmani":"شَكَرْتُمْ","transliteration":"shakartum","translation_bn":"তোমরা কৃতজ্ঞ হও","root":"شكر","lemma":"شَكَرَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":8329,"position":6,"text_uthmani":"لَأَزِيدَنَّكُمْ ۖ","transliteration":"la-azīdannakum","translation_bn":"এবং তোমাদের অবশ্যই অধিক দিবো","root":"زيد","lemma":"زَادَ","grammar_bn":"দৃঢ়তাবোধক (Emphatic)"},{"id":8331,"position":7,"text_uthmani":"وَلَئِن","transliteration":"wala-in","translation_bn":"আর অবশ্যই যদি","root":"—","lemma":"إِن\r","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":8332,"position":8,"text_uthmani":"كَفَرْتُمْ","transliteration":"kafartum","translation_bn":"তোমরা অকৃতজ্ঞ হও","root":"كفر","lemma":"كَفَرَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":8333,"position":9,"text_uthmani":"إِنَّ","transliteration":"inna","translation_bn":"নিশ্চয়ই (তবে)","root":"—","lemma":"إِنّ","grammar_bn":"অভিঘাত পদ (Accusative)"},{"id":8334,"position":10,"text_uthmani":"عَذَابِى","transliteration":"ʿadhābī","translation_bn":"আমার শাস্তি","root":"عذب","lemma":"عَذَاب","grammar_bn":"বিশেষ্য (Noun)"},{"id":8335,"position":11,"text_uthmani":"لَشَدِيدٌۭ","transliteration":"lashadīdun","translation_bn":"অবশ্যই কঠোর\"","root":"شدد","lemma":"شَدِيد","grammar_bn":"দৃঢ়তাবোধক (Emphatic)"},{"id":8336,"position":12,"text_uthmani":"٧","transliteration":"","translation_bn":"(৭)","root":"—","lemma":"٧","grammar_bn":"মার্কার"}]'::jsonb, 'wa-idh ta-adhana rabbukum la-in shakartum la-azīdannakum wala-in kafartum inna ʿadhābī lashadīdun', 'স্মরণ কর, যখন তোমাদের প্রতিপালক ঘোষণা করেন, যদি তোমরা কৃতজ্ঞতা প্রকাশ কর তাহলে আমি অবশ্যই তোমাদের জন্য (আমার নি‘য়ামাত) বৃদ্ধি করে দেব, আর যদি তোমরা অকৃতজ্ঞ হও (তবে জেনে রেখ, অকৃতজ্ঞদের জন্য) আমার শাস্তি অবশ্যই কঠিন।', 'And [remember] when your Lord proclaimed, ''If you are grateful, I will surely increase you [in favor]; but if you deny, indeed, My punishment is severe.'' "', 'স্মরণ কর, যখন তোমাদের প্রতিপালক ঘোষণা করেন, যদি তোমরা কৃতজ্ঞতা প্রকাশ কর তাহলে আমি অবশ্যই তোমাদের জন্য (আমার নি‘য়ামাত) বৃদ্ধি করে দেব, আর যদি তোমরা অকৃতজ্ঞ হও (তবে জেনে রেখ, অকৃতজ্ঞদের জন্য) আমার শাস্তি অবশ্যই কঠিন।', 'And [remember] when your Lord proclaimed, ''If you are grateful, I will surely increase you [in favor]; but if you deny, indeed, My punishment is severe.'' "', NULL, NULL, NULL, NULL, NULL, 'https://everyayah.com/data/Alafasy_128kbps/014007.mp3', now()),
  (14, 8, '', '[{"id":9479,"position":1,"text_uthmani":"وَقَالَ","transliteration":"waqāla","translation_bn":"এবং বলেছিলো","root":"قول","lemma":"قَالَ","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":9480,"position":2,"text_uthmani":"مُوسَىٰٓ","transliteration":"mūsā","translation_bn":"মুসা","root":"—","lemma":"مُوسَىٰ","grammar_bn":"নামবাচক বিশেষ্য (Proper Noun)"},{"id":9481,"position":3,"text_uthmani":"إِن","transliteration":"in","translation_bn":"\"যদি","root":"—","lemma":"إِن\r","grammar_bn":"শর্তবাচক (Conditional)"},{"id":9482,"position":4,"text_uthmani":"تَكْفُرُوٓا۟","transliteration":"takfurū","translation_bn":"অস্বীকার করো","root":"كفر","lemma":"كَفَرَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":9483,"position":5,"text_uthmani":"أَنتُمْ","transliteration":"antum","translation_bn":"তোমরা","root":"—","lemma":"أَنتُمْ","grammar_bn":"সর্বনাম (Pronoun)"},{"id":9484,"position":6,"text_uthmani":"وَمَن","transliteration":"waman","translation_bn":"ও যা কিছু","root":"—","lemma":"مَن\r","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":9485,"position":7,"text_uthmani":"فِى","transliteration":"fī","translation_bn":"মধ্যে আছে","root":"—","lemma":"فِى\r","grammar_bn":"অব্যয় (Preposition)"},{"id":9486,"position":8,"text_uthmani":"ٱلْأَرْضِ","transliteration":"l-arḍi","translation_bn":"পৃথিবীর","root":"ارض","lemma":"أَرْض","grammar_bn":"শব্দ"},{"id":9487,"position":9,"text_uthmani":"جَمِيعًۭا","transliteration":"jamīʿan","translation_bn":"সকলেই","root":"جمع","lemma":"جَمِيع","grammar_bn":"বিশেষ্য (Noun)"},{"id":9488,"position":10,"text_uthmani":"فَإِنَّ","transliteration":"fa-inna","translation_bn":"তবুও নিশ্চয়ই","root":"—","lemma":"إِنّ","grammar_bn":"শব্দ"},{"id":9489,"position":11,"text_uthmani":"ٱللَّهَ","transliteration":"l-laha","translation_bn":"আল্লাহ","root":"اله","lemma":"ٱللَّه","grammar_bn":"নামবাচক বিশেষ্য (Proper Noun)"},{"id":9490,"position":12,"text_uthmani":"لَغَنِىٌّ","transliteration":"laghaniyyun","translation_bn":"অবশ্যই অভাবমুক্ত","root":"غني","lemma":"غ