  (15, 41, '', '[{"id":42129,"position":1,"text_uthmani":"قَالَ","transliteration":"qāla","translation_bn":"তিনি বললেন","root":"قول","lemma":"قَالَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":42130,"position":2,"text_uthmani":"هَـٰذَا","transliteration":"hādhā","translation_bn":"\"এটা","root":"—","lemma":"هَٰذَا","grammar_bn":"নির্দেশক সর্বনাম (Demonstrative)"},{"id":42131,"position":3,"text_uthmani":"صِرَٰطٌ","transliteration":"ṣirāṭun","translation_bn":"পথ","root":"صرط","lemma":"صِرَٰط","grammar_bn":"বিশেষ্য (Noun)"},{"id":42132,"position":4,"text_uthmani":"عَلَىَّ","transliteration":"ʿalayya","translation_bn":"আমার দিকে","root":"—","lemma":"عَلَىٰ\r","grammar_bn":"অব্যয় (Preposition)"},{"id":42133,"position":5,"text_uthmani":"مُسْتَقِيمٌ","transliteration":"mus''taqīmun","translation_bn":"সরল","root":"قوم","lemma":"مُّسْتَقِيم","grammar_bn":"বিশেষ্য (Noun)"},{"id":42134,"position":6,"text_uthmani":"٤١","transliteration":"","translation_bn":"(৪১)","root":"—","lemma":"٤١","grammar_bn":"মার্কার"}]'::jsonb, 'qāla hādhā ṣirāṭun ʿalayya mus''taqīmun', 'তিনি বললেন- (আমার বাছাই করা বান্দারা যে পথে চলছে) এটাই আমার কাছে পৌঁছার সরল সোজা পথ।', '[Allah] said, "This is a path [of return] to Me [that is] straight.', 'তিনি বললেন- (আমার বাছাই করা বান্দারা যে পথে চলছে) এটাই আমার কাছে পৌঁছার সরল সোজা পথ।', '[Allah] said, "This is a path [of return] to Me [that is] straight.', NULL, NULL, NULL, NULL, NULL, 'https://everyayah.com/data/Alafasy_128kbps/015041.mp3', now()),
  (15, 42, '', '[{"id":43315,"position":1,"text_uthmani":"إِنَّ","transliteration":"inna","translation_bn":"নিশ্চয়ই (যারা)","root":"—","lemma":"إِنّ","grammar_bn":"অভিঘাত পদ (Accusative)"},{"id":43316,"position":2,"text_uthmani":"عِبَادِى","transliteration":"ʿibādī","translation_bn":"আমার দাসরা","root":"عبد","lemma":"عَبْد","grammar_bn":"বিশেষ্য (Noun)"},{"id":43317,"position":3,"text_uthmani":"لَيْسَ","transliteration":"laysa","translation_bn":"নেই","root":"ليس","lemma":"لَّيْسَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":43318,"position":4,"text_uthmani":"لَكَ","transliteration":"laka","translation_bn":"তোমার জন্যে","root":"—","lemma":"لَكَ","grammar_bn":"অব্যয় (Preposition)"},{"id":43319,"position":5,"text_uthmani":"عَلَيْهِمْ","transliteration":"ʿalayhim","translation_bn":"তাদের উপর","root":"—","lemma":"عَلَىٰ\r","grammar_bn":"অব্যয় (Preposition)"},{"id":43320,"position":6,"text_uthmani":"سُلْطَـٰنٌ","transliteration":"sul''ṭānun","translation_bn":"কোন প্রভাব","root":"سلط","lemma":"سُلْطَٰن","grammar_bn":"বিশেষ্য (Noun)"},{"id":43321,"position":7,"text_uthmani":"إِلَّا","transliteration":"illā","translation_bn":"এ ছাড়া","root":"—","lemma":"إِلَّا\r","grammar_bn":"সীমাবদ্ধতা (Restriction)"},{"id":43322,"position":8,"text_uthmani":"مَنِ","transliteration":"mani","translation_bn":"যে","root":"—","lemma":"مَن\r","grammar_bn":"সাপেক্ষ সর্বনাম (Relative)"},{"id":43323,"position":9,"text_uthmani":"ٱتَّبَعَكَ","transliteration":"ittabaʿaka","translation_bn":"তোমার অনুসরণ করবে","root":"تبع","lemma":"ٱتَّبَعَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":43324,"position":10,"text_uthmani":"مِنَ","transliteration":"mina","translation_bn":"থেকে","root":"—","lemma":"مِن\r","grammar_bn":"অব্যয় (Preposition)"},{"id":43325,"position":11,"text_uthmani":"ٱلْغَاوِينَ","transliteration":"l-ghāwīna","translation_bn":"পথভ্রষ্ট\"","root":"غوي","lemma":"غَٰوِين","grammar_bn":"শব্দ"},{"id":43326,"position":12,"text_uthmani":"٤٢","transliteration":"","translation_bn":"(৪২)","root":"—","lemma":"٤٢","grammar_bn":"মার্কার"}]'::jsonb, 'inna ʿibādī laysa laka ʿalayhim sul''ṭānun illā mani ittabaʿaka mina l-ghāwīna', 'আমার প্রকৃত বান্দাহ্দের উপর তোমার কোন আধিপত্য চলবে না, তোমাকে যারা অনুসরণ করে সেই বিভ্রান্তরা ছাড়া।', 'Indeed, My servants - no authority will you have over them, except those who follow you of the deviators.', 'আমার প্রকৃত বান্দাহ্দের উপর তোমার কোন আধিপত্য চলবে না, তোমাকে যারা অনুসরণ করে সেই বিভ্রান্তরা ছাড়া।', 'Indeed, My servants - no authority will you have over them, except those who follow you of the deviators.', NULL, NULL, NULL, NULL, NULL, 'https://everyayah.com/data/Alafasy_128kbps/015042.mp3', now()),
  (15, 43, '', '[{"id":44076,"position":1,"text_uthmani":"وَإِنَّ","transliteration":"wa-inna","translation_bn":"এবং নিশ্চয়ই","root":"—","lemma":"إِنّ","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":44077,"position":2,"text_uthmani":"جَهَنَّمَ","transliteration":"jahannama","translation_bn":"জাহান্নাম","root":"—","lemma":"جَهَنَّم","grammar_bn":"নামবাচক বিশেষ্য (Proper Noun)"},{"id":44078,"position":3,"text_uthmani":"لَمَوْعِدُهُمْ","transliteration":"lamawʿiduhum","translation_bn":"অবশ্যই প্রতিশ্রুত স্হান তাদের","root":"وعد","lemma":"مَّوْعِد","grammar_bn":"দৃঢ়তাবোধক (Emphatic)"},{"id":44079,"position":4,"text_uthmani":"أَجْمَعِينَ","transliteration":"ajmaʿīna","translation_bn":"সকলের","root":"جمع","lemma":"أَجْمَعِين","grammar_bn":"বিশেষ্য (Noun)"},{"id":44080,"position":5,"text_uthmani":"٤٣","transliteration":"","translation_bn":"(৪৩)","root":"—","lemma":"٤٣","grammar_bn":"মার্কার"}]'::jsonb, 'wa-inna jahannama lamawʿiduhum ajmaʿīna', 'আর তাদের সবার জন্য অবশ্যই ওয়া‘দাকৃত স্থান হচ্ছে জাহান্নাম।', 'And indeed, Hell is the promised place for them all.', 'আর তাদের সবার জন্য অবশ্যই ওয়া‘দাকৃত স্থান হচ্ছে জাহান্নাম।', 'And indeed, Hell is the promised place for them all.', NULL, NULL, NULL, NULL, NULL, 'https://everyayah.com/data/Alafasy_128kbps/015043.mp3', now()),
  (15, 44, '', '[{"id":44878,"position":1,"text_uthmani":"لَهَا","transliteration":"lahā","translation_bn":"তার আছে","root":"—","lemma":"لَهَا","grammar_bn":"অব্যয় (Preposition)"},{"id":44879,"position":2,"text_uthmani":"سَبْعَةُ","transliteration":"sabʿatu","translation_bn":"সাতটি","root":"سبع","lemma":"سَبْعَة","grammar_bn":"বিশেষ্য (Noun)"},{"id":44880,"position":3,"text_uthmani":"أَبْوَٰبٍۢ","transliteration":"abwābin","translation_bn":"দরজা","root":"بوب","lemma":"بَاب","grammar_bn":"বিশেষ্য (Noun)"},{"id":44881,"position":4,"text_uthmani":"لِّكُلِّ","transliteration":"likulli","translation_bn":"জন্যে প্রত্যেকটির","root":"كلل","lemma":"كُلّ","grammar_bn":"অব্যয় (Preposition)"},{"id":44882,"position":5,"text_uthmani":"بَابٍۢ","transliteration":"bābin","translation_bn":"দরজার","root":"بوب","lemma":"بَاب","grammar_bn":"বিশেষ্য (Noun)"},{"id":44883,"position":6,"text_uthmani":"مِّنْهُمْ","transliteration":"min''hum","translation_bn":"তাদের থেকে","root":"—","lemma":"مِن\r","grammar_bn":"অব্যয় (Preposition)"},{"id":44884,"position":7,"text_uthmani":"جُزْءٌۭ","transliteration":"juz''on","translation_bn":"অংশ (দল)","root":"جزا","lemma":"جُزْء","grammar_bn":"বিশেষ্য (Noun)"},{"id":44885,"position":8,"text_uthmani":"مَّقْسُومٌ","transliteration":"maqsūmun","translation_bn":"পৃথক পৃথক","root":"قسم","lemma":"مَّقْسُوم","grammar_bn":"বিশেষ্য (Noun)"},{"id":44886,"position":9,"text_uthmani":"٤٤","transliteration":"","translation_bn":"(৪৪)","root":"—","lemma":"٤٤","grammar_bn":"মার্কার"}]'::jsonb, 'lahā sabʿatu abwābin likulli bābin min''hum juz''on maqsūmun', 'তার সাতটা দরজা আছে। প্রত্যেক দরজার জন্য তাদের মধ্যে শ্রেণী নির্দিষ্ট আছে।’', 'It has seven gates; for every gate is of them a portion designated."', 'তার সাতটা দরজা আছে। প্রত্যেক দরজার জন্য তাদের মধ্যে শ্রেণী নির্দিষ্ট আছে।’', 'It has seven gates; for every gate is of them a portion designated."', NULL, NULL, NULL, NULL, NULL, 'https://everyayah.com/data/Alafasy_128kbps/015044.mp3', now()),
  (15, 45, '', '[{"id":45550,"position":1,"text_uthmani":"إِنَّ","transliteration":"inna","translation_bn":"নিশ্চয়ই","root":"—","lemma":"إِنّ","grammar_bn":"অভিঘাত পদ (Accusative)"},{"id":45551,"position":2,"text_uthmani":"ٱلْمُتَّقِينَ","transliteration":"l-mutaqīna","translation_bn":"মুত্তাকীরা","root":"وقي","lemma":"مُتَّقِين","grammar_bn":"শব্দ"},{"id":45552,"position":3,"text_uthmani":"فِى","transliteration":"fī","translation_bn":"মধ্যে (থাকবে)","root":"—","lemma":"فِى\r","grammar_bn":"অব্যয় (Preposition)"},{"id":45553,"position":4,"text_uthmani":"جَنَّـٰتٍۢ","transliteration":"jannātin","translation_bn":"জান্নাতের","root":"جنن","lemma":"جَنَّة","grammar_bn":"বিশেষ্য (Noun)"},{"id":45554,"position":5,"text_uthmani":"وَعُيُونٍ","transliteration":"waʿuyūnin","translation_bn":"ও ঝর্ণাধারাসমূহের","root":"عين","lemma":"عَيْن","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":45555,"position":6,"text_uthmani":"٤٥","transliteration":"","translation_bn":"(৪৫)","root":"—","lemma":"٤٥","grammar_bn":"মার্কার"}]'::jsonb, 'inna l-mutaqīna fī jannātin waʿuyūnin', 'অবশ্যই মুত্তাকীরা থাকবে জান্নাতে আর নির্ঝরিণীগুলোর মধ্যে।', 'Indeed, the righteous will be within gardens and springs.', 'অবশ্যই মুত্তাকীরা থাকবে জান্নাতে আর নির্ঝরিণীগুলোর মধ্যে।', 'Indeed, the righteous will be within gardens and springs.', NULL, NULL, NULL, NULL, NULL, 'https://everyayah.com/data/Alafasy_128kbps/015045.mp3', now()),
  (15, 46, '', '[{"id":46242,"position":1,"text_uthmani":"ٱدْخُلُوهَا","transliteration":"ud''khulūhā","translation_bn":"\"তাতে তোমরা প্রবেশ করো","root":"دخل","lemma":"دَخَلَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":46243,"position":2,"text_uthmani":"بِسَلَـٰمٍ","transliteration":"bisalāmin","translation_bn":"সাথে শান্তির","root":"سلم","lemma":"سَلَٰم","grammar_bn":"অব্যয় (Preposition)"},{"id":46244,"position":3,"text_uthmani":"ءَامِنِينَ","transliteration":"āminīna","translation_bn":"নিরাপদে\"","root":"امن","lemma":"ءَامِنِين","grammar_bn":"বিশেষ্য (Noun)"},{"id":46245,"position":4,"text_uthmani":"٤٦","transliteration":"","translation_bn":"(৪৬)","root":"—","lemma":"٤٦","grammar_bn":"মার্কার"}]'::jsonb, 'ud''khulūhā bisalāmin āminīna', 'তাদেরকে বলা হবে, ‘পূর্ণ শান্তি ও নিরাপত্তার সাথে তোমরা এতে প্রবেশ কর।’', '[Having been told], "Enter it in peace, safe [and secure]."', 'তাদেরকে বলা হবে, ‘পূর্ণ শান্তি ও নিরাপত্তার সাথে তোমরা এতে প্রবেশ কর।’', '[Having been told], "Enter it in peace, safe [and secure]."', NULL, NULL, NULL, NULL, NULL, 'https://everyayah.com/data/Alafasy_128kbps/015046.mp3', now()),
  (15, 47, '', '[{"id":46911,"position":1,"text_uthmani":"وَنَزَعْنَا","transliteration":"wanazaʿnā","translation_bn":"এবং আমরা দূর করে দিবো","root":"نزع","lemma":"نَزَعَ","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":46912,"position":2,"text_uthmani":"مَا","transliteration":"mā","translation_bn":"যা","root":"—","lemma":"مَا\r","grammar_bn":"সাপেক্ষ সর্বনাম (Relative)"},{"id":46913,"position":3,"text_uthmani":"فِى","transliteration":"fī","translation_bn":"মধ্যে আছে","root":"—","lemma":"فِى\r","grammar_bn":"অব্যয় (Preposition)"},{"id":46914,"position":4,"text_uthmani":"صُدُورِهِم","transliteration":"ṣudūrihim","translation_bn":"তাদের অন্তরসমূহের","root":"صدر","lemma":"صَدْر","grammar_bn":"বিশেষ্য (Noun)"},{"id":46915,"position":5,"text_uthmani":"مِّنْ","transliteration":"min","translation_bn":"থেকে","root":"—","lemma":"مِن\r","grammar_bn":"অব্যয় (Preposition)"},{"id":46916,"position":6,"text_uthmani":"غِلٍّ","transliteration":"ghillin","translation_bn":"ঈর্ষা","root":"غلل","lemma":"غِلّ","grammar_bn":"বিশেষ্য (Noun)"},{"id":46917,"position":7,"text_uthmani":"إِخْوَٰنًا","transliteration":"ikh''wānan","translation_bn":"ভাই ভাই হয়ে (তারা বসবে)","root":"اخو","lemma":"أَخ","grammar_bn":"বিশেষ্য (Noun)"},{"id":46918,"position":8,"text_uthmani":"عَلَىٰ","transliteration":"ʿalā","translation_bn":"উপর","root":"—","lemma":"عَلَىٰ\r","grammar_bn":"অব্যয় (Preposition)"},{"id":46919,"position":9,"text_uthmani":"سُرُرٍۢ","transliteration":"sururin","translation_bn":"আসনসমূহের","root":"سرر","lemma":"سُرُر","grammar_bn":"বিশেষ্য (Noun)"},{"id":46920,"position":10,"text_uthmani":"مُّتَقَـٰبِلِينَ","transliteration":"mutaqābilīna","translation_bn":"মুখোমুখি হয়ে","root":"قبل","lemma":"مُّتَقَٰبِلِين","grammar_bn":"বিশেষ্য (Noun)"},{"id":46921,"position":11,"text_uthmani":"٤٧","transliteration":"","translation_bn":"(৪৭)","root":"—","lemma":"٤٧","grammar_bn":"মার্কার"}]'::jsonb, 'wanazaʿnā mā fī ṣudūrihim min ghillin ikh''wānan ʿalā sururin mutaqābilīna', 'তাদের অন্তর থেকে আমি বিদ্বেষ দূরীভূত করব, তারা ভ্রাতৃবন্ধনে আবদ্ধ হয়ে আসনে মুখোমুখী সমাসীন হবে।', 'And We will remove whatever is in their breasts of resentment, [so they will be] brothers, on thrones facing each other.', 'তাদের অন্তর থেকে আমি বিদ্বেষ দূরীভূত করব, তারা ভ্রাতৃবন্ধনে আবদ্ধ হয়ে আসনে মুখোমুখী সমাসীন হবে।', 'And We will remove whatever is in their breasts of resentment, [so they will be] brothers, on thrones facing each other.', NULL, NULL, NULL, NULL, NULL, 'https://everyayah.com/data/Alafasy_128kbps/015047.mp3', now()),
  (15, 48, '', '[{"id":47651,"position":1,"text_uthmani":"لَا","transliteration":"lā","translation_bn":"না","root":"—","lemma":"لَا\r","grammar_bn":"না-বোধক (Negative)"},{"id":47652,"position":2,"text_uthmani":"يَمَسُّهُمْ","transliteration":"yamassuhum","translation_bn":"তাদের স্পর্শ করবে","root":"مسس","lemma":"مَسَّ","grammar_bn":"ক্রিয়া (Verb)"},{"id":47653,"position":3,"text_uthmani":"فِيهَا","transliteration":"fīhā","translation_bn":"তার মধ্যে","root":"—","lemma":"فِى\r","grammar_bn":"অব্যয় (Preposition)"},{"id":47654,"position":4,"text_uthmani":"نَصَبٌۭ","transliteration":"naṣabun","translation_bn":"কোনো অবসাদ","root":"نصب","lemma":"نَصَب","grammar_bn":"বিশেষ্য (Noun)"},{"id":47655,"position":5,"text_uthmani":"وَمَا","transliteration":"wamā","translation_bn":"আছে  না","root":"—","lemma":"مَا\r","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":47656,"position":6,"text_uthmani":"هُم","transliteration":"hum","translation_bn":"তারা","root":"—","lemma":"هُم","grammar_bn":"সর্বনাম (Pronoun)"},{"id":47657,"position":7,"text_uthmani":"مِّنْهَا","transliteration":"min''hā","translation_bn":"তা থেকে","root":"—","lemma":"مِن\r","grammar_bn":"অব্যয় (Preposition)"},{"id":47658,"position":8,"text_uthmani":"بِمُخْرَجِينَ","transliteration":"bimukh''rajīna","translation_bn":"বহিষ্কৃত হবে","root":"خرج","lemma":"مُخْرَج","grammar_bn":"অব্যয় (Preposition)"},{"id":47659,"position":9,"text_uthmani":"٤٨","transliteration":"","translation_bn":"(৪৮)","root":"—","lemma":"٤٨","grammar_bn":"মার্কার"}]'::jsonb, 'lā yamassuhum fīhā naṣabun wamā hum min''hā bimukh''rajīna', 'কোন ক্লান্তি তাদেরকে স্পর্শ করবে না, আর সেখান থেকে তারা কখনও বহিষ্কৃতও হবে না।', 'No fatigue will touch them therein, nor from it will they [ever] be removed.', 'কোন ক্লান্তি তাদেরকে স্পর্শ করবে না, আর সেখান থেকে তারা কখনও বহিষ্কৃতও হবে না।', 'No fatigue will touch them therein, nor from it will they [ever] be removed.', NULL, NULL, NULL, NULL, NULL, 'https://everyayah.com/data/Alafasy_128kbps/015048.mp3', now()),
  (15, 49, '', '[{"id":48307,"position":1,"text_uthmani":"۞ نَبِّئْ","transliteration":"nabbi","translation_bn":"জানিয়ে দাও","root":"نبا","lemma":"نَبَّأَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":48308,"position":2,"text_uthmani":"عِبَادِىٓ","transliteration":"ʿibādī","translation_bn":"আমার দাসদের","root":"عبد","lemma":"عَبْد","grammar_bn":"বিশেষ্য (Noun)"},{"id":48309,"position":3,"text_uthmani":"أَنِّىٓ","transliteration":"annī","translation_bn":"যে আমি","root":"—","lemma":"أَنّ","grammar_bn":"অভিঘাত পদ (Accusative)"},{"id":48310,"position":4,"text_uthmani":"أَنَا","transliteration":"anā","translation_bn":"আমিই","root":"—","lemma":"أَنَا","grammar_bn":"সর্বনাম (Pronoun)"},{"id":48311,"position":5,"text_uthmani":"ٱلْغَفُورُ","transliteration":"l-ghafūru","translation_bn":"ক্ষমাশীল","root":"غفر","lemma":"غَفُور","grammar_bn":"শব্দ"},{"id":48312,"position":6,"text_uthmani":"ٱلرَّحِيمُ","transliteration":"l-raḥīmu","translation_bn":"পরম দয়ালু","root":"رحم","lemma":"رَّحِيم","grammar_bn":"শব্দ"},{"id":48313,"position":7,"text_uthmani":"٤٩","transliteration":"","translation_bn":"(৪৯)","root":"—","lemma":"٤٩","grammar_bn":"মার্কার"}]'::jsonb, 'nabbi ʿibādī annī anā l-ghafūru l-raḥīmu', 'আমার বান্দাহদেরকে সংবাদ দাও যে, আমি বড়ই ক্ষমাশীল, বড়ই দয়ালু।', '[O Muhammad], inform My servants that it is I who am the Forgiving, the Merciful.', 'আমার বান্দাহদেরকে সংবাদ দাও যে, আমি বড়ই ক্ষমাশীল, বড়ই দয়ালু।', '[O Muhammad], inform My servants that it is I who am the Forgiving, the Merciful.', NULL, NULL, NULL, NULL, NULL, 'https://everyayah.com/data/Alafasy_128kbps/015049.mp3', now()),
  (15, 50, '', '[{"id":48983,"position":1,"text_uthmani":"وَأَنَّ","transliteration":"wa-anna","translation_bn":"এবং (এও) যে","root":"—","lemma":"أَنّ","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":48984,"position":2,"text_uthmani":"عَذَابِى","transliteration":"ʿadhābī","translation_bn":"আমার শাস্তিও","root":"عذب","lemma":"عَذَاب","grammar_bn":"বিশেষ্য (Noun)"},{"id":48985,"position":3,"text_uthmani":"هُوَ","transliteration":"huwa","translation_bn":"তা","root":"—","lemma":"هُوَ","grammar_bn":"সর্বনাম (Pronoun)"},{"id":48986,"position":4,"text_uthmani":"ٱلْعَذَابُ","transliteration":"l-ʿadhābu","translation_bn":"শাস্তি","root":"عذب","lemma":"عَذَاب","grammar_bn":"শব্দ"},{"id":48987,"position":5,"text_uthmani":"ٱلْأَلِيمُ","transliteration":"l-alīmu","translation_bn":"নিদারুণ","root":"الم","lemma":"أَلِيم","grammar_bn":"শব্দ"},{"id":48988,"position":6,"text_uthmani":"٥٠","transliteration":"","translation_bn":"(৫০)","root":"—","lemma":"٥٠","grammar_bn":"মার্কার"}]'::jsonb, 'wa-anna ʿadhābī huwa l-ʿadhābu l-alīmu', 'আর আমার শাস্তি- তা বড়ই ভয়াবহ শাস্তি।', 'And that it is My punishment which is the painful punishment.', 'আর আমার শাস্তি- তা বড়ই ভয়াবহ শাস্তি।', 'And that it is My punishment which is the painful punishment.', NULL, NULL, NULL, NULL, NULL, 'https://everyayah.com/data/Alafasy_128kbps/015050.mp3', now()),
