  (15, 64, '', '[{"id":56940,"position":1,"text_uthmani":"وَأَتَيْنَـٰكَ","transliteration":"wa-ataynāka","translation_bn":"এবং তোমার কাছে আমরা এসেছি","root":"اتي","lemma":"أَتَى","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":56941,"position":2,"text_uthmani":"بِٱلْحَقِّ","transliteration":"bil-ḥaqi","translation_bn":"নিয়ে সত্য","root":"حقق","lemma":"حَقّ","grammar_bn":"অব্যয় (Preposition)"},{"id":56942,"position":3,"text_uthmani":"وَإِنَّا","transliteration":"wa-innā","translation_bn":"এবং নিশ্চয়ই আমরা","root":"—","lemma":"إِنّ","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":56943,"position":4,"text_uthmani":"لَصَـٰدِقُونَ","transliteration":"laṣādiqūna","translation_bn":"অবশ্যই সত্যবাদী","root":"صدق","lemma":"صَادِق","grammar_bn":"দৃঢ়তাবোধক (Emphatic)"},{"id":56944,"position":5,"text_uthmani":"٦٤","transliteration":"","translation_bn":"(৬৪)","root":"—","lemma":"٦٤","grammar_bn":"মার্কার"}]'::jsonb, 'wa-ataynāka bil-ḥaqi wa-innā laṣādiqūna', 'তোমার কাছে আমরা সত্য নিয়েই এসেছি, আর আমরা অবশ্যই সত্যবাদী।', 'And we have come to you with truth, and indeed, we are truthful.', 'তোমার কাছে আমরা সত্য নিয়েই এসেছি, আর আমরা অবশ্যই সত্যবাদী।', 'And we have come to you with truth, and indeed, we are truthful.', NULL, NULL, NULL, NULL, NULL, 'https://everyayah.com/data/Alafasy_128kbps/015064.mp3', now()),
  (15, 65, '', '[{"id":57388,"position":1,"text_uthmani":"فَأَسْرِ","transliteration":"fa-asri","translation_bn":"সুতরাং চলে যাও","root":"سري","lemma":"أَسْرَىٰ","grammar_bn":"শব্দ"},{"id":57389,"position":2,"text_uthmani":"بِأَهْلِكَ","transliteration":"bi-ahlika","translation_bn":"নিয়ে তোমার পরিবার","root":"اهل","lemma":"أَهْل","grammar_bn":"অব্যয় (Preposition)"},{"id":57390,"position":3,"text_uthmani":"بِقِطْعٍۢ","transliteration":"biqiṭ''ʿin","translation_bn":"অংশে","root":"قطع","lemma":"قِطْع","grammar_bn":"অব্যয় (Preposition)"},{"id":57391,"position":4,"text_uthmani":"مِّنَ","transliteration":"mina","translation_bn":"কিছু","root":"—","lemma":"مِن\r","grammar_bn":"অব্যয় (Preposition)"},{"id":57392,"position":5,"text_uthmani":"ٱلَّيْلِ","transliteration":"al-layli","translation_bn":"রাতের","root":"ليل","lemma":"لَيْل","grammar_bn":"শব্দ"},{"id":57393,"position":6,"text_uthmani":"وَٱتَّبِعْ","transliteration":"wa-ittabiʿ","translation_bn":"এবং তুমি চলবে","root":"تبع","lemma":"ٱتَّبَعَ","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":57394,"position":7,"text_uthmani":"أَدْبَـٰرَهُمْ","transliteration":"adbārahum","translation_bn":"তাদের পিছনে পিছনে","root":"دبر","lemma":"دُبُر","grammar_bn":"বিশেষ্য (Noun)"},{"id":57395,"position":8,"text_uthmani":"وَلَا","transliteration":"walā","translation_bn":"এবং না","root":"—","lemma":"لَا\r","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":57396,"position":9,"text_uthmani":"يَلْتَفِتْ","transliteration":"yaltafit","translation_bn":"তাকাবে (পিছনে)","root":"لفت","lemma":"يَلْتَفِتْ","grammar_bn":"ক্রিয়া (Verb)"},{"id":57397,"position":10,"text_uthmani":"مِنكُمْ","transliteration":"minkum","translation_bn":"তোমাদের মধ্য থেকে","root":"—","lemma":"مِن\r","grammar_bn":"অব্যয় (Preposition)"},{"id":57398,"position":11,"text_uthmani":"أَحَدٌۭ","transliteration":"aḥadun","translation_bn":"কেউ","root":"احد","lemma":"أَحَد","grammar_bn":"বিশেষ্য (Noun)"},{"id":57399,"position":12,"text_uthmani":"وَٱمْضُوا۟","transliteration":"wa-im''ḍū","translation_bn":"এবং তোমরা চলে যাও","root":"مضي","lemma":"مَضَىٰ","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":57400,"position":13,"text_uthmani":"حَيْثُ","transliteration":"ḥaythu","translation_bn":"যেখানে","root":"حيث\r","lemma":"حَيْث","grammar_bn":"স্থানবাচক (Location)"},{"id":57401,"position":14,"text_uthmani":"تُؤْمَرُونَ","transliteration":"tu''marūna","translation_bn":"তোমাদের নির্দেশ দেয়া হয়েছে\"","root":"امر","lemma":"أَمَرَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":57402,"position":15,"text_uthmani":"٦٥","transliteration":"","translation_bn":"(৬৫)","root":"—","lemma":"٦٥","grammar_bn":"মার্কার"}]'::jsonb, 'fa-asri bi-ahlika biqiṭ''ʿin mina al-layli wa-ittabiʿ adbārahum walā yaltafit minkum aḥadun wa-im''ḍū ḥaythu tu''marūna', 'কাজেই কিছুটা রাত থাকতে তুমি তোমার পরিবারবর্গকে নিয়ে বেরিয়ে পড় আর তুমি তাদের পেছনে পেছনে চলতে থাক। তোমাদের কেউ যেন পেছনে ফিরে না তাকায় বরং যেখানে যেতে বলা হচ্ছে চলে যাও।’', 'So set out with your family during a portion of the night and follow behind them and let not anyone among you look back and continue on to where you are commanded."', 'কাজেই কিছুটা রাত থাকতে তুমি তোমার পরিবারবর্গকে নিয়ে বেরিয়ে পড় আর তুমি তাদের পেছনে পেছনে চলতে থাক। তোমাদের কেউ যেন পেছনে ফিরে না তাকায় বরং যেখানে যেতে বলা হচ্ছে চলে যাও।’', 'So set out with your family during a portion of the night and follow behind them and let not anyone among you look back and continue on to where you are commanded."', NULL, NULL, NULL, NULL, NULL, 'https://everyayah.com/data/Alafasy_128kbps/015065.mp3', now()),
