  (16, 1, '', '[{"id":892,"position":1,"text_uthmani":"أَتَىٰٓ","transliteration":"atā","translation_bn":"এসেছে","root":"اتي","lemma":"أَتَى","grammar_bn":"ক্রিয়া (Verb)"},{"id":893,"position":2,"text_uthmani":"أَمْرُ","transliteration":"amru","translation_bn":"আদেশ","root":"امر","lemma":"أَمْر","grammar_bn":"বিশেষ্য (Noun)"},{"id":894,"position":3,"text_uthmani":"ٱللَّهِ","transliteration":"l-lahi","translation_bn":"আল্লাহ্‌র","root":"اله","lemma":"ٱللَّه","grammar_bn":"নামবাচক বিশেষ্য (Proper Noun)"},{"id":895,"position":4,"text_uthmani":"فَلَا","transliteration":"falā","translation_bn":"সুতরাং না","root":"—","lemma":"لَا\r","grammar_bn":"শব্দ"},{"id":896,"position":5,"text_uthmani":"تَسْتَعْجِلُوهُ ۚ","transliteration":"tastaʿjilūhu","translation_bn":"তা তোমরা তাড়াহুড়া করতে চেয়ো","root":"عجل","lemma":"ٱسْتَعْجَلَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":898,"position":6,"text_uthmani":"سُبْحَـٰنَهُۥ","transliteration":"sub''ḥānahu","translation_bn":"তিনি পবিত্র","root":"سبح","lemma":"سُبْحَٰن","grammar_bn":"বিশেষ্য (Noun)"},{"id":899,"position":7,"text_uthmani":"وَتَعَـٰلَىٰ","transliteration":"wataʿālā","translation_bn":"ও বহু ঊর্দ্ধে","root":"علو","lemma":"تَعَٰلَىٰ","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":900,"position":8,"text_uthmani":"عَمَّا","transliteration":"ʿammā","translation_bn":"তা থেকে যা","root":"—","lemma":"عَن\r","grammar_bn":"অব্যয় (Preposition)"},{"id":901,"position":9,"text_uthmani":"يُشْرِكُونَ","transliteration":"yush''rikūna","translation_bn":"তারা শরীক করে","root":"شرك","lemma":"أَشْرَكَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":902,"position":10,"text_uthmani":"١","transliteration":"","translation_bn":"(১)","root":"—","lemma":"١","grammar_bn":"মার্কার"}]'::jsonb, 'atā amru l-lahi falā tastaʿjilūhu sub''ḥānahu wataʿālā ʿammā yush''rikūna', 'আল্লাহর নির্দেশ এসে গেছে, অতএব এর জন্য তাড়াহুড়ো করো না। তিনি মহান পবিত্র, তারা যাকে শরীক সাব্যস্ত করে তাত্থেকে তিনি বহু ঊর্ধ্বে।', 'The command of Allah is coming, so be not impatient for it. Exalted is He and high above what they associate with Him.', 'আল্লাহর নির্দেশ এসে গেছে, অতএব এর জন্য তাড়াহুড়ো করো না। তিনি মহান পবিত্র, তারা যাকে শরীক সাব্যস্ত করে তাত্থেকে তিনি বহু ঊর্ধ্বে।', 'The command of Allah is coming, so be not impatient for it. Exalted is He and high above what they associate with Him.', NULL, NULL, NULL, NULL, NULL, 'https://everyayah.com/data/Alafasy_128kbps/016001.mp3', now()),
  (16, 2, '', '[{"id":1994,"position":1,"text_uthmani":"يُنَزِّلُ","transliteration":"yunazzilu","translation_bn":"অবতীর্ণ করেন","root":"نزل","lemma":"نَزَّلَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":1995,"position":2,"text_uthmani":"ٱلْمَلَـٰٓئِكَةَ","transliteration":"l-malāikata","translation_bn":"ফেরেশতাদেরকে","root":"ملك","lemma":"مَلَك","grammar_bn":"শব্দ"},{"id":1996,"position":3,"text_uthmani":"بِٱلرُّوحِ","transliteration":"bil-rūḥi","translation_bn":"দিয়ে ওহী","root":"روح","lemma":"رُوح","grammar_bn":"অব্যয় (Preposition)"},{"id":1997,"position":4,"text_uthmani":"مِنْ","transliteration":"min","translation_bn":"থেকে","root":"—","lemma":"مِن\r","grammar_bn":"অব্যয় (Preposition)"},{"id":1998,"position":5,"text_uthmani":"أَمْرِهِۦ","transliteration":"amrihi","translation_bn":"তাঁর নির্দেশের","root":"امر","lemma":"أَمْر","grammar_bn":"বিশেষ্য (Noun)"},{"id":1999,"position":6,"text_uthmani":"عَلَىٰ","transliteration":"ʿalā","translation_bn":"উপর","root":"—","lemma":"عَلَىٰ\r","grammar_bn":"অব্যয় (Preposition)"},{"id":2000,"position":7,"text_uthmani":"مَن","transliteration":"man","translation_bn":"(তার) যাকে","root":"—","lemma":"مَن\r","grammar_bn":"সাপেক্ষ সর্বনাম (Relative)"},{"id":2001,"position":8,"text_uthmani":"يَشَآءُ","transliteration":"yashāu","translation_bn":"ইচ্ছে করেন","root":"شيا","lemma":"شَا^ءَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":2002,"position":9,"text_uthmani":"مِنْ","transliteration":"min","translation_bn":"মধ্য হ''তে","root":"—","lemma":"مِن\r","grammar_bn":"অব্যয় (Preposition)"},{"id":2003,"position":10,"text_uthmani":"عِبَادِهِۦٓ","transliteration":"ʿibādihi","translation_bn":"তাঁর দাসদের","root":"عبد","lemma":"عَبْد","grammar_bn":"বিশেষ্য (Noun)"},{"id":2004,"position":11,"text_uthmani":"أَنْ","transliteration":"an","translation_bn":"যে","root":"—","lemma":"أَن\r","grammar_bn":"অধীনস্থ যোজক (Subordinating)"},{"id":2005,"position":12,"text_uthmani":"أَنذِرُوٓا۟","transliteration":"andhirū","translation_bn":"\"তোমরা সতর্ক করো","root":"نذر","lemma":"أَنذَرَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":2006,"position":13,"text_uthmani":"أَنَّهُۥ","transliteration":"annahu","translation_bn":"এই মর্মে যে","root":"—","lemma":"أَنّ","grammar_bn":"অভিঘাত পদ (Accusative)"},{"id":2007,"position":14,"text_uthmani":"لَآ","transliteration":"lā","translation_bn":"নেই","root":"—","lemma":"لَا\r","grammar_bn":"না-বোধক (Negative)"},{"id":2008,"position":15,"text_uthmani":"إِلَـٰهَ","transliteration":"ilāha","translation_bn":"কোন ইলাহ","root":"اله","lemma":"إِلَٰه","grammar_bn":"বিশেষ্য (Noun)"},{"id":2009,"position":16,"text_uthmani":"إِلَّآ","transliteration":"illā","translation_bn":"ছাড়া","root":"—","lemma":"إِلَّا\r","grammar_bn":"সীমাবদ্ধতা (Restriction)"},{"id":2010,"position":17,"text_uthmani":"أَنَا۠","transliteration":"anā","translation_bn":"আমি","root":"—","lemma":"أَنَا۠","grammar_bn":"সর্বনাম (Pronoun)"},{"id":2011,"position":18,"text_uthmani":"فَٱتَّقُونِ","transliteration":"fa-ittaqūni","translation_bn":"সুতরাং তোমরা আমাকে ভয় করো\"","root":"وقي","lemma":"ٱتَّقَىٰ","grammar_bn":"শব্দ"},{"id":2012,"position":19,"text_uthmani":"٢","transliteration":"","translation_bn":"(২)","root":"—","lemma":"٢","grammar_bn":"মার্কার"}]'::jsonb, 'yunazzilu l-malāikata bil-rūḥi min amrihi ʿalā man yashāu min ʿibādihi an andhirū annahu lā ilāha illā anā fa-ittaqūni', 'তিনি তাঁর এ রূহকে (ওহীক) যে বান্দাহর উপর চান স্বীয় নির্দেশক্রমে ফেরেশতাদের মাধ্যমে অবতীর্ণ করেন (এই মর্মে যে) তোমরা সতর্ক কর যে, আমি ছাড়া সত্যিকারের কোন ইলাহ নেই, কাজেই আমাকে ভয় কর।', 'He sends down the angels, with the inspiration of His command, upon whom He wills of His servants, [telling them], "Warn that there is no deity except Me; so fear Me."', 'তিনি তাঁর এ রূহকে (ওহীক) যে বান্দাহর উপর চান স্বীয় নির্দেশক্রমে ফেরেশতাদের মাধ্যমে অবতীর্ণ করেন (এই মর্মে যে) তোমরা সতর্ক কর যে, আমি ছাড়া সত্যিকারের কোন ইলাহ নেই, কাজেই আমাকে ভয় কর।', 'He sends down the angels, with the inspiration of His command, upon whom He wills of His servants, [telling them], "Warn that there is no deity except Me; so fear Me."', NULL, NULL, NULL, NULL, NULL, 'https://everyayah.com/data/Alafasy_128kbps/016002.mp3', now()),
  (16, 3, '', '[{"id":3192,"position":1,"text_uthmani":"خَلَقَ","transliteration":"khalaqa","translation_bn":"তিনি সৃষ্টি করেছেন","root":"خلق","lemma":"خَلَقَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":3193,"position":2,"text_uthmani":"ٱلسَّمَـٰوَٰتِ","transliteration":"l-samāwāti","translation_bn":"আকাশমন্ডলী","root":"سمو","lemma":"سَمَا^ء","grammar_bn":"শব্দ"},{"id":3194,"position":3,"text_uthmani":"وَٱلْأَرْضَ","transliteration":"wal-arḍa","translation_bn":"ও পৃথিবী","root":"ارض","lemma":"أَرْض","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":3195,"position":4,"text_uthmani":"بِٱلْحَقِّ ۚ","transliteration":"bil-ḥaqi","translation_bn":"দিয়ে মহাসত্য","root":"حقق","lemma":"حَقّ","grammar_bn":"অব্যয় (Preposition)"},{"id":3197,"position":5,"text_uthmani":"تَعَـٰلَىٰ","transliteration":"taʿālā","translation_bn":"বহু ঊর্দ্ধে","root":"علو","lemma":"تَعَٰلَىٰ","grammar_bn":"ক্রিয়া (Verb)"},{"id":3198,"position":6,"text_uthmani":"عَمَّا","transliteration":"ʿammā","translation_bn":"তা থেকে যা","root":"—","lemma":"عَن\r","grammar_bn":"অব্যয় (Preposition)"},{"id":3199,"position":7,"text_uthmani":"يُشْرِكُونَ","transliteration":"yush''rikūna","translation_bn":"তারা শরীক করে","root":"شرك","lemma":"أَشْرَكَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":3200,"position":8,"text_uthmani":"٣","transliteration":"","translation_bn":"(৩)","root":"—","lemma":"٣","grammar_bn":"মার্কার"}]'::jsonb, 'khalaqa l-samāwāti wal-arḍa bil-ḥaqi taʿālā ʿammā yush''rikūna', 'তিনি (বিশেষ উদ্দেশ্য সাধনের নিমিত্তে) প্রকৃতভাবেই আসমানসমূহ যমীন সৃষ্টি করেছেন, তারা যাকে আল্লাহর অংশীদার গণ্য করে তাত্থেকে তিনি বহু ঊর্ধ্বে।', 'He created the heavens and earth in truth. High is He above what they associate with Him.', 'তিনি (বিশেষ উদ্দেশ্য সাধনের নিমিত্তে) প্রকৃতভাবেই আসমানসমূহ যমীন সৃষ্টি করেছেন, তারা যাকে আল্লাহর অংশীদার গণ্য করে তাত্থেকে তিনি বহু ঊর্ধ্বে।', 'He created the heavens and earth in truth. High is He above what they associate with Him.', NULL, NULL, NULL, NULL, NULL, 'https://everyayah.com/data/Alafasy_128kbps/016003.mp3', now()),
  (16, 4, '', '[{"id":4166,"position":1,"text_uthmani":"خَلَقَ","transliteration":"khalaqa","translation_bn":"তিনি সৃষ্টি করেছেন","root":"خلق","lemma":"خَلَقَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":4167,"position":2,"text_uthmani":"ٱلْإِنسَـٰنَ","transliteration":"l-insāna","translation_bn":"মানুষকে","root":"انس","lemma":"إِنسَٰن","grammar_bn":"শব্দ"},{"id":4168,"position":3,"text_uthmani":"مِن","transliteration":"min","translation_bn":"থেকে","root":"—","lemma":"مِن\r","grammar_bn":"অব্যয় (Preposition)"},{"id":4169,"position":4,"text_uthmani":"نُّطْفَةٍۢ","transliteration":"nuṭ''fatin","translation_bn":"শুক্র","root":"نطف","lemma":"نُّطْفَة","grammar_bn":"বিশেষ্য (Noun)"},{"id":4170,"position":5,"text_uthmani":"فَإِذَا","transliteration":"fa-idhā","translation_bn":"অতঃপর যখন (সৃষ্টি হলো)","root":"—","lemma":"إِذَا\r","grammar_bn":"শব্দ"},{"id":4171,"position":6,"text_uthmani":"هُوَ","transliteration":"huwa","translation_bn":"সে (হলো)","root":"—","lemma":"هُوَ","grammar_bn":"সর্বনাম (Pronoun)"},{"id":4172,"position":7,"text_uthmani":"خَصِيمٌۭ","transliteration":"khaṣīmun","translation_bn":"ঝগড়াটে","root":"خصم","lemma":"خَصِيم","grammar_bn":"বিশেষ্য (Noun)"},{"id":4173,"position":8,"text_uthmani":"مُّبِينٌۭ","transliteration":"mubīnun","translation_bn":"সুস্পষ্ট","root":"بين","lemma":"مُّبِين","grammar_bn":"বিশেষ্য (Noun)"},{"id":4174,"position":9,"text_uthmani":"٤","transliteration":"","translation_bn":"(৪)","root":"—","lemma":"٤","grammar_bn":"মার্কার"}]'::jsonb, 'khalaqa l-insāna min nuṭ''fatin fa-idhā huwa khaṣīmun mubīnun', 'তিনি শুক্র-কীট থেকে মানুষ সৃষ্টি করেছেন অথচ সে প্রকাশ্য ঝগড়াটে সেজে বসল।', 'He created man from a sperm-drop; then at once, he is a clear adversary.', 'তিনি শুক্র-কীট থেকে মানুষ সৃষ্টি করেছেন অথচ সে প্রকাশ্য ঝগড়াটে সেজে বসল।', 'He created man from a sperm-drop; then at once, he is a clear adversary.', NULL, NULL, NULL, NULL, NULL, 'https://everyayah.com/data/Alafasy_128kbps/016004.mp3', now()),
  (16, 5, '', '[{"id":5798,"position":1,"text_uthmani":"وَٱلْأَنْعَـٰمَ","transliteration":"wal-anʿāma","translation_bn":"এবং গবাদিপশু","root":"نعم","lemma":"نَّعَم","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":5799,"position":2,"text_uthmani":"خَلَقَهَا ۗ","transliteration":"khalaqahā","translation_bn":"তিনি সৃষ্টি করেছেন তা","root":"خلق","lemma":"خَلَقَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":5801,"position":3,"text_uthmani":"لَكُمْ","transliteration":"lakum","translation_bn":"তোমাদের জন্যে","root":"—","lemma":"لَكُمْ","grammar_bn":"অব্যয় (Preposition)"},{"id":5802,"position":4,"text_uthmani":"فِيهَا","transliteration":"fīhā","translation_bn":"তার মধ্যে (আছে)","root":"—","lemma":"فِى\r","grammar_bn":"অব্যয় (Preposition)"},{"id":5803,"position":5,"text_uthmani":"دِفْءٌۭ","transliteration":"dif''on","translation_bn":"শীত নিবারক উপকরণ","root":"دفا","lemma":"دِفْء","grammar_bn":"বিশেষ্য (Noun)"},{"id":5804,"position":6,"text_uthmani":"وَمَنَـٰفِعُ","transliteration":"wamanāfiʿu","translation_bn":"ও উপকারিতাসমূহ","root":"نفع","lemma":"مَنَٰفِع","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":5805,"position":7,"text_uthmani":"وَمِنْهَا","transliteration":"wamin''hā","translation_bn":"এবং তা থেকে","root":"—","lemma":"مِن\r","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":5806,"position":8,"text_uthmani":"تَأْكُلُونَ","transliteration":"takulūna","translation_bn":"তোমরা খাও","root":"اكل","lemma":"أَكَلَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":5807,"position":9,"text_uthmani":"٥","transliteration":"","translation_bn":"(৫)","root":"—","lemma":"٥","grammar_bn":"মার্কার"}]'::jsonb, 'wal-anʿāma khalaqahā lakum fīhā dif''on wamanāfiʿu wamin''hā takulūna', 'তিনি চতুস্পদ জন্তু সৃষ্টি করেছেন এবং তাতে তোমাদের জন্য আছে (শীত) নিবারক আর বহু উপকারিতাও, আর সেগুলো থেকে তোমরা আহার কর।', 'And the grazing livestock He has created for you; in them is warmth and [numerous] benefits, and from them you eat.', 'তিনি চতুস্পদ জন্তু সৃষ্টি করেছেন এবং তাতে তোমাদের জন্য আছে (শীত) নিবারক আর বহু উপকারিতাও, আর সেগুলো থেকে তোমরা আহার কর।', 'And the grazing livestock He has created for you; in them is warmth and [numerous] benefits, and from them you eat.', NULL, NULL, NULL, NULL, NULL, 'https://everyayah.com/data/Alafasy_128kbps/016005.mp3', now()),
  (16, 6, '', '[{"id":7088,"position":1,"text_uthmani":"وَلَكُمْ","transliteration":"walakum","translation_bn":"এবং তোমাদের জন্যে","root":"—","lemma":"وَلَكُمْ","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":7089,"position":2,"text_uthmani":"فِيهَا","transliteration":"fīhā","translation_bn":"তার মধ্যে (আছে)","root":"—","lemma":"فِى\r","grammar_bn":"অব্যয় (Preposition)"},{"id":7090,"position":3,"text_uthmani":"جَمَالٌ","transliteration":"jamālun","translation_bn":"সৌন্দর্য","root":"جمل","lemma":"جَمَال","grammar_bn":"বিশেষ্য (Noun)"},{"id":7091,"position":4,"text_uthmani":"حِينَ","transliteration":"ḥīna","translation_bn":"যখন","root":"حين","lemma":"حِين","grammar_bn":"বিশেষ্য (Noun)"},{"id":7092,"position":5,"text_uthmani":"تُرِيحُونَ","transliteration":"turīḥūna","translation_bn":"তোমরা সন্ধ্যায় চারণভূমি থেকে আনো","root":"روح","lemma":"تُرِيحُ","grammar_bn":"ক্রিয়া (Verb)"},{"id":7093,"position":6,"text_uthmani":"وَحِينَ","transliteration":"waḥīna","translation_bn":"ও যখন","root":"حين","lemma":"حِين","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":7094,"position":7,"text_uthmani":"تَسْرَحُونَ","transliteration":"tasraḥūna","translation_bn":"তোমরা সকালে চারণভূমিতে নিয়ে যাও","root":"سرح","lemma":"تَسْرَحُ","grammar_bn":"ক্রিয়া (Verb)"},{"id":7095,"position":8,"text_uthmani":"٦","transliteration":"","translation_bn":"(৬)","root":"—","lemma":"٦","grammar_bn":"মার্কার"}]'::jsonb, 'walakum fīhā jamālun ḥīna turīḥūna waḥīna tasraḥūna', 'তোমরা গর্বভরে সৌন্দর্য অনুভব কর যখন তোমরা সন্ধ্যাবেলা সেগুলোকে বাড়ীর পানে হাঁকিয়ে আন আর সকাল বেলা বিচরণের জন্য পাঠাও।', 'And for you in them is [the enjoyment of] beauty when you bring them in [for the evening] and when you send them out [to pasture].', 'তোমরা গর্বভরে সৌন্দর্য অনুভব কর যখন তোমরা সন্ধ্যাবেলা সেগুলোকে বাড়ীর পানে হাঁকিয়ে আন আর সকাল বেলা বিচরণের জন্য পাঠাও।', 'And for you in them is [the enjoyment of] beauty when you bring them in [for the evening] and when you send them out [to pasture].', NULL, NULL, NULL, NULL, NULL, 'https://everyayah.com/data/Alafasy_128kbps/016006.mp3', now()),
  (16, 7, '', '[{"id":8395,"position":1,"text_uthmani":"وَتَحْمِلُ","transliteration":"wataḥmilu","translation_bn":"এবং তা বহন করে","root":"حمل","lemma":"حَمَلَ","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":8396,"position":2,"text_uthmani":"أَثْقَالَكُمْ","transliteration":"athqālakum","translation_bn":"তোমাদের ভার","root":"ثقل","lemma":"ثَّقَلَان","grammar_bn":"বিশেষ্য (Noun)"},{"id":8397,"position":3,"text_uthmani":"إِلَىٰ","transliteration":"ilā","translation_bn":"দিকে","root":"—","lemma":"إِلَىٰ\r","grammar_bn":"অব্যয় (Preposition)"},{"id":8398,"position":4,"text_uthmani":"بَلَدٍۢ","transliteration":"baladin","translation_bn":"এমন শহরের","root":"بلد","lemma":"بَلَد","grammar_bn":"বিশেষ্য (Noun)"},{"id":8399,"position":5,"text_uthmani":"لَّمْ","transliteration":"lam","translation_bn":"না","root":"—","lemma":"لَم\r","grammar_bn":"না-বোধক (Negative)"},{"id":8400,"position":6,"text_uthmani":"تَكُونُوا۟","transliteration":"takūnū","translation_bn":"তোমরা ছিলে","root":"كون","lemma":"كَانَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":8401,"position":7,"text_uthmani":"بَـٰلِغِيهِ","transliteration":"bālighīhi","translation_bn":"সেখানে পৌঁছাতে সক্ষম","root":"بلغ","lemma":"بَٰلِغ","grammar_bn":"বিশেষ্য (Noun)"},{"id":8402,"position":8,"text_uthmani":"إِلَّا","transliteration":"illā","translation_bn":"এ ছাড়া","root":"—","lemma":"إِلَّا\r","grammar_bn":"সীমাবদ্ধতা (Restriction)"},{"id":8403,"position":9,"text_uthmani":"بِشِقِّ","transliteration":"bishiqqi","translation_bn":"সহ কষ্ট","root":"شقق","lemma":"شِقّ","grammar_bn":"অব্যয় (Preposition)"},{"id":8404,"position":10,"text_uthmani":"ٱلْأَنفُسِ ۚ","transliteration":"l-anfusi","translation_bn":"প্রানান্ত","root":"نفس","lemma":"نَفْس","grammar_bn":"শব্দ"},{"id":8406,"position":11,"text_uthmani":"إِنَّ","transliteration":"inna","translation_bn":"নিশ্চয়ই","root":"—","lemma":"إِنّ","grammar_bn":"অভিঘাত পদ (Accusative)"},{"id":8407,"position":12,"text_uthmani":"رَبَّكُمْ","transliteration":"rabbakum","translation_bn":"তোমার রব","root":"ربب","lemma":"رَبّ","grammar_bn":"বিশেষ্য (Noun)"},{"id":8408,"position":13,"text_uthmani":"لَرَءُوفٌۭ","transliteration":"laraūfun","translation_bn":"অবশ্যই অনুগ্রহশীল","root":"راف","lemma":"رَءُوف","grammar_bn":"দৃঢ়তাবোধক (Emphatic)"},{"id":8409,"position":14,"text_uthmani":"رَّحِيمٌۭ","transliteration":"raḥīmun","translation_bn":"পরম দয়ালু","root":"رحم","lemma":"رَّحِيم","grammar_bn":"বিশেষণ (Adjective)"},{"id":8410,"position":15,"text_uthmani":"٧","transliteration":"","translation_bn":"(৭)","root":"—","lemma":"٧","grammar_bn":"মার্কার"}]'::jsonb, 'wataḥmilu athqālakum ilā baladin lam takūnū bālighīhi illā bishiqqi l-anfusi inna rabbakum laraūfun raḥīmun', 'আর এগুলো তোমাদের ভার বোঝা বহন ক’রে এমন স্থান পর্যন্ত নিয়ে যায়, প্রাণান্তকর ক্লেশ ছাড়া যেখানে তোমরা পৌঁছতে পারতে না, তোমাদের প্রতিপালক অবশ্যই বড়ই দয়ার্দ্র, বড়ই দয়ালু।', 'And they carry your loads to a land you could not have reached except with difficulty to yourselves. Indeed, your Lord is Kind and Merciful.', 'আর এগুলো তোমাদের ভার বোঝা বহন ক’রে এমন স্থান পর্যন্ত নিয়ে যায়, প্রাণান্তকর ক্লেশ ছাড়া যেখানে তোমরা পৌঁছতে পারতে না, তোমাদের প্রতিপালক অবশ্যই বড়ই দয়ার্দ্র, বড়ই দয়ালু।', 'And they carry your loads to a land you could not have reached except with difficulty to yourselves. Indeed, your Lord is Kind and Merciful.', NULL, NULL, NULL, NULL, NULL, 'https://everyayah.com/data/Alafasy_128kbps/016007.mp3', now()),
  (16, 8, '', '[{"id":9587,"position":1,"text_uthmani":"وَٱلْخَيْلَ","transliteration":"wal-khayla","translation_bn":"এবং ঘোড়া (সৃষ্টি করেছেন)","root":"خيل","lemma":"خَيْل","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":9588,"position":2,"text_uthmani":"وَٱلْبِغَالَ","transliteration":"wal-bighāla","translation_bn":"ও খচ্চর","root":"بغل","lemma":"بِغَال","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":9589,"position":3,"text_uthmani":"وَٱلْحَمِيرَ","transliteration":"wal-ḥamīra","translation_bn":"ও গাধা","root":"حمر","lemma":"حِمَار","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":9590,"position":4,"text_uthmani":"لِتَرْكَبُوهَا","transliteration":"litarkabūhā","translation_bn":"জন্যে তোমাদের চড়ার","root":"ركب","lemma":"رَكِبَ","grammar_bn":"শব্দ"},{"id":9591,"position":5,"text_uthmani":"وَزِينَةًۭ ۚ","transliteration":"wazīnatan","translation_bn":"ও শোভা (স্বরূপ)","root":"زين","lemma":"زِينَة","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":9593,"position":6,"text_uthmani":"وَيَخْلُقُ","transliteration":"wayakhluqu","translation_bn":"এবং তিনি সৃষ্টি করেছেন","root":"خلق","lemma":"خَلَقَ","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":9594,"position":7,"text_uthmani":"مَا","transliteration":"mā","translation_bn":"(কিছু) যা","root":"—","lemma":"مَا\r","grammar_bn":"সাপেক্ষ সর্বনাম (Relative)"},{"id":9595,"position":8,"text_uthmani":"لَا","transliteration":"lā","translation_bn":"না","root":"—","lemma":"لَا\r","grammar_bn":"না-বোধক (Negative)"},{"id":9596,"position":9,"text_uthmani":"تَعْلَمُونَ","transliteration":"taʿlamūna","translation_bn":"তোমরা জানো","root":"علم","lemma":"عَلِمَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":9597,"position":10,"text_uthmani":"٨","transliteration":"","translation_bn":"(৮)","root":"—","lemma":"٨","grammar_bn":"মার্কার"}]'::jsonb, 'wal-khayla wal-bighāla wal-ḥamīra litarkabūhā wazīnatan wayakhluqu mā lā taʿlamūna', 'তিনি ঘোড়া, খচ্চর ও গর্দভ সৃষ্টি করেছেন যাতে তোমরা ওগুলোতে আরোহণ করতে পার আর শোভা-সৌন্দর্যের জন্যও; তিনি পয়দা করেন অনেক কিছু যা তোমাদের জানা নেই।', 'And [He created] the horses, mules and donkeys for you to ride and [as] adornment. And He creates that which you do not know.', 'তিনি ঘোড়া, খচ্চর ও গর্দভ সৃষ্টি করেছেন যাতে তোমরা ওগুলোতে আরোহণ করতে পার আর শোভা-সৌন্দর্যের জন্যও; তিনি পয়দা করেন অনেক কিছু যা তোমাদের জানা নেই।', 'And [He created] the horses, mules and donkeys for you to ride and [as] adornment. And He creates that which you do not know.', NULL, NULL, NULL, NULL, NULL, 'https://everyayah.com/data/Alafasy_128kbps/016008.mp3', now()),
  (16, 9, '', '[{"id":10760,"position":1,"text_uthmani":"وَعَلَى","transliteration":"waʿalā","translation_bn":"এবং উপর","root":"—","lemma":"عَلَىٰ\r","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":10761,"position":2,"text_uthmani":"ٱللَّهِ","transliteration":"l-lahi","translation_bn":"আল্লাহর (দায়িত্ব)","root":"اله","lemma":"ٱللَّه","grammar_bn":"নামবাচক বিশেষ্য (Proper Noun)"},{"id":10762,"position":3,"text_uthmani":"قَصْدُ","transliteration":"qaṣdu","translation_bn":"প্রদর্শন","root":"قصد","lemma":"قَصْد","grammar_bn":"বিশেষ্য (Noun)"},{"id":10763,"position":4,"text_uthmani":"ٱلسَّبِيلِ","transliteration":"l-sabīli","translation_bn":"পথ","root":"سبل","lemma":"سَبِيل","grammar_bn":"শব্দ"},{"id":10764,"position":5,"text_uthmani":"وَمِنْهَا","transliteration":"wamin''hā","translation_bn":"কিন্তু তা থেকে আছে","root":"—","lemma":"مِن\r","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":10765,"position":6,"text_uthmani":"جَآئِرٌۭ ۚ","transliteration":"jāirun","translation_bn":"বাঁকা (পথও)","root":"جور","lemma":"جَا^ئِر","grammar_bn":"বিশেষ্য (Noun)"},{"id":10767,"position":7,"text_uthmani":"وَلَوْ","transliteration":"walaw","translation_bn":"এবং যদি","root":"—","lemma":"لَو\r","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":10768,"position":8,"text_uthmani":"شَآءَ","transliteration":"shāa","translation_bn":"ইচ্ছে করেন","root":"شيا","lemma":"شَا^ءَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":10769,"position":9,"text_uthmani":"لَهَدَىٰكُمْ","transliteration":"lahadākum","translation_bn":"অবশ্যই সৎপথে পরিচালনা করতেন তোমাদের","root":"هدي","lemma":"هَدَى","grammar_bn":"দৃঢ়তাবোধক (Emphatic)"},{"id":10770,"position":10,"text_uthmani":"أَجْمَعِينَ","transliteration":"ajmaʿīna","translation_bn":"সকলকেই","root":"جمع","lemma":"أَجْمَعِين","grammar_bn":"বিশেষ্য (Noun)"},{"id":10771,"position":11,"text_uthmani":"٩","transliteration":"","translation_bn":"(৯)","root":"—","lemma":"٩","grammar_bn":"মার্কার"}]'::jsonb, 'waʿalā l-lahi qaṣdu l-sabīli wamin''hā jāirun walaw shāa lahadākum ajmaʿīna', 'আল্লাহরই দায়িত্বে রয়েছে সরল পথপ্রদর্শন। পথগুলোর মধ্যে বাঁকা পথও আছে। তিনি যদি ইচ্ছে করতেন তাহলে অবশ্যই তোমাদের সকলকেই সঠিক পথ প্রদর্শন করতেন।', 'And upon Allah is the direction of the [right] way, and among the various paths are those deviating. And if He willed, He could have guided you all.', 'আল্লাহরই দায়িত্বে রয়েছে সরল পথপ্রদর্শন। পথগুলোর মধ্যে বাঁকা পথও আছে। তিনি যদি ইচ্ছে করতেন তাহলে অবশ্যই তোমাদের সকলকেই সঠিক পথ প্রদর্শন করতেন।', 'And upon Allah is the direction of the [right] way, and among the various paths are those deviating. And if He willed, He could have guided you all.', NULL, NULL, NULL, NULL, NULL, 'https://everyayah.com/data/Alafasy_128kbps/016009.mp3', now()),
  (16, 10, '', '[{"id":12011,"position":1,"text_uthmani":"هُوَ","transliteration":"huwa","translation_bn":"তিনিই (রব)","root":"—","lemma":"هُوَ","grammar_bn":"সর্বনাম (Pronoun)"},{"id":12012,"position":2,"text_uthmani":"ٱلَّذِىٓ","transliteration":"alladhī","translation_bn":"যিনি","root":"—","lemma":"ٱلَّذِى","grammar_bn":"সাপেক্ষ সর্বনাম (Relative)"},{"id":12013,"position":3,"text_uthmani":"أَنزَلَ","transliteration":"anzala","translation_bn":"বর্ষণ করেছেন","root":"نزل","lemma":"أَنزَلَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":12014,"position":4,"text_uthmani":"مِنَ","transliteration":"mina","translation_bn":"থেকে","root":"—","lemma":"مِن\r","grammar_bn":"অব্যয় (Preposition)"},{"id":12015,"position":5,"text_uthmani":"ٱلسَّمَآءِ","transliteration":"l-samāi","translation_bn":"আকাশ","root":"سمو","lemma":"سَمَا^ء","grammar_bn":"শব্দ"},{"id":12016,"position":6,"text_uthmani":"مَآءًۭ ۖ","transliteration":"māan","translation_bn":"পানি","root":"موه","lemma":"مَا^ء","grammar_bn":"বিশেষ্য (Noun)"},{"id":12018,"position":7,"text_uthmani":"لَّكُم","transliteration":"lakum","translation_bn":"জন্যে তোমাদের","root":"—","lemma":"لَّكُم","grammar_bn":"অব্যয় (Preposition)"},{"id":12019,"position":8,"text_uthmani":"مِّنْهُ","transliteration":"min''hu","translation_bn":"কিছু তার","root":"—","lemma":"مِن\r","grammar_bn":"অব্যয় (Preposition)"},{"id":12020,"position":9,"text_uthmani":"شَرَابٌۭ","transliteration":"sharābun","translation_bn":"পানীয় (পেয়ে থাকো)","root":"شرب","lemma":"شَرَاب","grammar_bn":"বিশেষ্য (Noun)"},{"id":12021,"position":10,"text_uthmani":"وَمِنْهُ","transliteration":"wamin''hu","translation_bn":"এবং তা থেকে","root":"—","lemma":"مِن\r","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":12022,"position":11,"text_uthmani":"شَجَرٌۭ","transliteration":"shajarun","translation_bn":"গাছপালা (জন্মে)","root":"شجر","lemma":"شَجَر","grammar_bn":"বিশেষ্য (Noun)"},{"id":12023,"position":12,"text_uthmani":"فِيهِ","transliteration":"fīhi","translation_bn":"তার মধ্যে","root":"—","lemma":"فِى\r","grammar_bn":"অব্যয় (Preposition)"},{"id":12024,"position":13,"text_uthmani":"تُسِيمُونَ","transliteration":"tusīmūna","translation_bn":"তোমরা পশু চরিয়ে থাকো","root":"سوم","lemma":"تُسِيمُ","grammar_bn":"ক্রিয়া (Verb)"},{"id":12025,"position":14,"text_uthmani":"١٠","transliteration":"","translation_bn":"(১০)","root":"—","lemma":"١٠","grammar_bn":"মার্কার"}]'::jsonb, 'huwa alladhī anzala mina l-samāi māan lakum min''hu sharābun wamin''hu shajarun fīhi tusīmūna', 'তিনি আকাশ থেকে পানি বর্ষণ করেন যাতে আছে তোমাদের জন্য পানীয় আর তাতে জন্মে বৃক্ষ লতা যা তোমাদের পশুগুলোকে খাওয়াও।', 'It is He who sends down rain from the sky; from it is drink and from it is foliage in which you pasture [animals].', 'তিনি আকাশ থেকে পানি বর্ষণ করেন যাতে আছে তোমাদের জন্য পানীয় আর তাতে জন্মে বৃক্ষ লতা যা তোমাদের পশুগুলোকে খাওয়াও।', 'It is He who sends down rain from the sky; from it is drink and from it is foliage in which you pasture [animals].', NULL, NULL, NULL, NULL, NULL, 'https://everyayah.com/data/Alafasy_128kbps/016010.mp3', now()),
  (16, 11, '', '[{"id":13332,"position":1,"text_uthmani":"يُنۢبِتُ","transliteration":"yunbitu","translation_bn":"তিনি উদগত করেন","root":"نبت","lemma":"أَن[بَتَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":13333,"position":2,"text_uthmani":"لَكُم","transliteration":"lakum","translation_bn":"জন্যে তোমাদের","root":"—","lemma":"لَكُم","grammar_bn":"অব্যয় (Preposition)"},{"id":13334,"position":3,"text_uthmani":"بِهِ","transliteration":"bihi","translation_bn":"দিয়ে তা","root":"—","lemma":"بِهِ","grammar_bn":"অব্যয় (Preposition)"},{"id":13335,"position":4,"text_uthmani":"ٱلزَّرْعَ","transliteration":"l-zarʿa","translation_bn":"শস্য","root":"زرع","lemma":"زَرْع","grammar_bn":"শব্দ"},{"id":13336,"position":5,"text_uthmani":"وَٱلزَّيْتُونَ","transliteration":"wal-zaytūna","translation_bn":"ও যায়তুনসমূহ","root":"زيت","lemma":"زَّيْتُون","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":13337,"position":6,"text_uthmani":"وَٱلنَّخِيلَ","transliteration":"wal-nakhīla","translation_bn":"ও খেজুরসমূহ","root":"نخل","lemma":"نَّخِيل","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":13338,"position":7,"text_uthmani":"وَٱلْأَعْنَـٰبَ","transliteration":"wal-aʿnāba","translation_bn":"ও আঙ্গুরসমূহ","root":"عنب","lemma":"عِنَب","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":13339,"position":8,"text_uthmani":"وَمِن","transliteration":"wamin","translation_bn":"এবং ধরণের","root":"—","lemma":"مِن\r","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":13340,"position":9,"text_uthmani":"كُلِّ","transliteration":"kulli","translation_bn":"সব","root":"كلل","lemma":"كُلّ","grammar_bn":"বিশেষ্য (Noun)"},{"id":13341,"position":10,"text_uthmani":"ٱلثَّمَرَٰتِ ۗ","transliteration":"l-thamarāti","translation_bn":"ফলসমূহ","root":"ثمر","lemma":"ثَمَرَٰت","grammar_bn":"শব্দ"},{"id":13343,"position":11,"text_uthmani":"إِنَّ","transliteration":"inna","translation_bn":"নিশ্চয়ই","root":"—","lemma":"إِنّ","grammar_bn":"অভিঘাত পদ (Accusative)"},{"id":13344,"position":12,"text_uthmani":"فِى","transliteration":"fī","translation_bn":"মধ্যে (রয়েছে)","root":"—","lemma":"فِى\r","grammar_bn":"অব্যয় (Preposition)"},{"id":13345,"position":13,"text_uthmani":"ذَٰلِكَ","transliteration":"dhālika","translation_bn":"এর","root":"—","lemma":"ذَٰلِك","grammar_bn":"নির্দেশক সর্বনাম (Demonstrative)"},{"id":13346,"position":14,"text_uthmani":"لَـَٔايَةًۭ","transliteration":"laāyatan","translation_bn":"অবশ্যই নিদর্শন","root":"ايي","lemma":"ءَايَة","grammar_bn":"দৃঢ়তাবোধক (Emphatic)"},{"id":13347,"position":15,"text_uthmani":"لِّقَوْمٍۢ","transliteration":"liqawmin","translation_bn":"লোকদের জন্যে","root":"قوم","lemma":"قَوْم","grammar_bn":"অব্যয় (Preposition)"},{"id":13348,"position":16,"text_uthmani":"يَتَفَكَّرُونَ","transliteration":"yatafakkarūna","translation_bn":"(যারা) চিন্তা ভাবনা করে","root":"فكر","lemma":"يَتَفَكَّرُ","grammar_bn":"ক্রিয়া (Verb)"},{"id":13349,"position":17,"text_uthmani":"١١","transliteration":"","translation_bn":"(১১)","root":"—","lemma":"١١","grammar_bn":"মার্কার"}]'::jsonb, 'yunbitu lakum bihi l-zarʿa wal-zaytūna wal-nakhīla wal-aʿnāba wamin kulli l-thamarāti inna fī dhālika laāyatan liqawmin yatafakkarūna', 'তিনি তা দিয়ে তোমাদের জন্য জন্মান শস্য, যায়তূন, খেজুর, আঙ্গুর এবং সর্বপ্রকার ফল। এতে চিন্তাশীল মানুষদের জন্য নিদর্শন রয়েছে।', 'He causes to grow for you thereby the crops, olives, palm trees, grapevines, and from all the fruits. Indeed in that is a sign for a people who give thought.', 'তিনি তা দিয়ে তোমাদের জন্য জন্মান শস্য, যায়তূন, খেজুর, আঙ্গুর এবং সর্বপ্রকার ফল। এতে চিন্তাশীল মানুষদের জন্য নিদর্শন রয়েছে।', 'He causes to grow for you thereby the crops, olives, palm trees, grapevines, and from all the fruits. Indeed in that is a sign for a people who give thought.', NULL, NULL, NULL, NULL, NULL, 'https://everyayah.com/data/Alafasy_128kbps/016011.mp3', now()),
  (16, 12, '', '[{"id":14611,"position":1,"text_uthmani":"وَسَخَّرَ","transliteration":"wasakhara","translation_bn":"এবং অধীন করেছেন","root":"سخر","lemma":"سَخَّرَ","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":14612,"position":2,"text_uthmani":"لَكُمُ","transliteration":"lakumu","translation_bn":"তোমাদের জন্যে","root":"—","lemma":"لَكُمُ","grammar_bn":"অব্যয় (Preposition)"},{"id":14613,"position":3,"text_uthmani":"ٱلَّيْلَ","transliteration":"al-layla","translation_bn":"রাতকে","root":"ليل","lemma":"لَيْل","grammar_bn":"শব্দ"},{"id":14614,"position":4,"text_uthmani":"وَٱلنَّهَارَ","transliteration":"wal-nahāra","translation_bn":"ও দিনকে","root":"نهر","lemma":"نَهَار","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":14615,"position":5,"text_uthmani":"وَٱلشَّمْسَ","transliteration":"wal-shamsa","translation_bn":"এবং সূর্যকে","root":"شمس","lemma":"شَمْس","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":14616,"position":6,"text_uthmani":"وَٱلْقَمَرَ ۖ","transliteration":"wal-qamara","translation_bn":"ও চাঁদকে","root":"قمر","lemma":"قَمَر","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":14618,"position":7,"text_uthmani":"وَٱلنُّجُومُ","transliteration":"wal-nujūmu","translation_bn":"এবং তারাগুলোও","root":"نجم","lemma":"نَّجْم","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":14619,"position":8,"text_uthmani":"مُسَخَّرَٰتٌۢ","transliteration":"musakharātun","translation_bn":"অধীন হয়েছে","root":"سخر","lemma":"مُسَخَّرَٰت","grammar_bn":"বিশেষ্য (Noun)"},{"id":14620,"position":9,"text_uthmani":"بِأَمْرِهِۦٓ ۗ","transliteration":"bi-amrihi","translation_bn":"দিয়ে তাঁর বিধান","root":"امر","lemma":"أَمْر","grammar_bn":"অব্যয় (Preposition)"},{"id":14622,"position":10,"text_uthmani":"إِنَّ","transliteration":"inna","translation_bn":"নিশ্চয়ই","root":"—","lemma":"إِنّ","grammar_bn":"অভিঘাত পদ (Accusative)"},{"id":14623,"position":11,"text_uthmani":"فِى","transliteration":"fī","translation_bn":"মধ্যে (রয়েছে)","root":"—","lemma":"فِى\r","grammar_bn":"অব্যয় (Preposition)"},{"id":14624,"position":12,"text_uthmani":"ذَٰلِكَ","transliteration":"dhālika","translation_bn":"এর","root":"—","lemma":"ذَٰلِك","grammar_bn":"নির্দেশক সর্বনাম (Demonstrative)"},{"id":14625,"position":13,"text_uthmani":"لَـَٔايَـٰتٍۢ","transliteration":"laāyātin","translation_bn":"অবশ্যই নিদর্শনসমূহ","root":"ايي","lemma":"ءَايَة","grammar_bn":"দৃঢ়তাবোধক (Emphatic)"},{"id":14626,"position":14,"text_uthmani":"لِّقَوْمٍۢ","transliteration":"liqawmin","translation_bn":"জন্যে লোকদের","root":"قوم","lemma":"قَوْم","grammar_bn":"অব্যয় (Preposition)"},{"id":14627,"position":15,"text_uthmani":"يَعْقِلُونَ","transliteration":"yaʿqilūna","translation_bn":"(যারা)জ্ঞান রাখে","root":"عقل","lemma":"عَقَلُ","grammar_bn":"ক্রিয়া (Verb)"},{"id":14628,"position":16,"text_uthmani":"١٢","transliteration":"","translation_bn":"(১২)","root":"—","lemma":"١٢","grammar_bn":"মার্কার"}]'::jsonb, 'wasakhara lakumu al-layla wal-nahāra wal-shamsa wal-qamara wal-nujūmu musakharātun bi-amrihi inna fī dhālika laāyātin liqawmin yaʿqilūna', 'তিনিই রাত ও দিনকে তোমাদের উপকারে নিয়োজিত করেছেন। আর সুরুজ ও চাঁদকেও; এবং তারকারাজিও তাঁরই নির্দেশে নিয়ন্ত্রিত; বিবেকসম্পন্ন লোকেদের জন্য এতে অবশ্যই বহু নিদর্শন রয়েছে।', 'And He has subjected for you the night and day and the sun and moon, and the stars are subjected by His command. Indeed in that are signs for a people who reason.', 'তিনিই রাত ও দিনকে তোমাদের উপকারে নিয়োজিত করেছেন। আর সুরুজ ও চাঁদকেও; এবং তারকারাজিও তাঁরই নির্দেশে নিয়ন্ত্রিত; বিবেকসম্পন্ন লোকেদের জন্য এতে অবশ্যই বহু নিদর্শন রয়েছে।', 'And He has subjected for you the night and day and the sun and moon, and the stars are subjected by His command. Indeed in that are signs for a people who reason.', NULL, NULL, NULL, NULL, NULL, 'https://everyayah.com/data/Alafasy_128kbps/016012.mp3', now()),
  (16, 13, '', '[{"id":15704,"position":1,"text_uthmani":"وَمَا","transliteration":"wamā","translation_bn":"আরো (কিছু) যা","root":"—","lemma":"مَا\r","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":15705,"position":2,"text_uthmani":"ذَرَأَ","transliteration":"dhara-a","translation_bn":"সৃষ্টি করেছেন","root":"ذرا","lemma":"ذَرَأَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":15706,"position":3,"text_uthmani":"لَكُمْ","transliteration":"lakum","translation_bn":"তোমাদের জন্যে","root":"—","lemma":"لَكُمْ","grammar_bn":"অব্যয় (Preposition)"},{"id":15707,"position":4,"text_uthmani":"فِى","transliteration":"fī","translation_bn":"মধ্যে","root":"—","lemma":"فِى\r","grammar_bn":"অব্যয় (Preposition)"},{"id":15708,"position":5,"text_uthmani":"ٱلْأَرْضِ","transliteration":"l-arḍi","translation_bn":"পৃথিবীর","root":"ارض","lemma":"أَرْض","grammar_bn":"শব্দ"},{"id":15709,"position":6,"text_uthmani":"مُخْتَلِفًا","transliteration":"mukh''talifan","translation_bn":"বিভিন্ন","root":"خلف","lemma":"مُّخْتَلِف","grammar_bn":"বিশেষ্য (Noun)"},{"id":15710,"position":7,"text_uthmani":"أَلْوَٰنُهُۥٓ ۗ","transliteration":"alwānuhu","translation_bn":"তার রংসমূহ","root":"لون","lemma":"لَوْن","grammar_bn":"বিশেষ্য (Noun)"},{"id":15712,"position":8,"text_uthmani":"إِنَّ","transliteration":"inna","translation_bn":"নিশ্চয়ই","root":"—","lemma":"إِنّ","grammar_bn":"অভিঘাত পদ (Accusative)"},{"id":15713,"position":9,"text_uthmani":"فِى","transliteration":"fī","translation_bn":"মধ্যে (রয়েছে)","root":"—","lemma":"فِى\r","grammar_bn":"অব্যয় (Preposition)"},{"id":15714,"position":10,"text_uthmani":"ذَٰلِكَ","transliteration":"dhālika","translation_bn":"এর","root":"—","lemma":"ذَٰلِك","grammar_bn":"নির্দেশক সর্বনাম (Demonstrative)"},{"id":15715,"position":11,"text_uthmani":"لَـَٔايَةًۭ","transliteration":"laāyatan","translation_bn":"অবশ্যই নিদর্শন","root":"ايي","lemma":"ءَايَة","grammar_bn":"দৃঢ়তাবোধক (Emphatic)"},{"id":15716,"position":12,"text_uthmani":"لِّقَوْمٍۢ","transliteration":"liqawmin","translation_bn":"লোকদের জন্যে","root":"قوم","lemma":"قَوْم","grammar_bn":"অব্যয় (Preposition)"},{"id":15717,"position":13,"text_uthmani":"يَذَّكَّرُونَ","transliteration":"yadhakkarūna","translation_bn":"(যারা) শিক্ষা গ্রহণ করে","root":"ذكر","lemma":"تَذَكَّرَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":15718,"position":14,"text_uthmani":"١٣","transliteration":"","translation_bn":"(১৩)","root":"—","lemma":"١٣","grammar_bn":"মার্কার"}]'::jsonb, 'wamā dhara-a lakum fī l-arḍi mukh''talifan alwānuhu inna fī dhālika laāyatan liqawmin yadhakkarūna', 'আর তিনি তোমাদের জন্য যমীনে বিভিন্ন রং-এর বস্তুরাজি সৃষ্টি করেছেন। এতে ঐ সমস্ত লোকেদের জন্য নিশ্চিতভাবে নিদর্শন আছে যারা উপদেশ গ্রহণ করতে চায়।', 'And [He has subjected] whatever He multiplied for you on the earth of varying colors. Indeed in that is a sign for a people who remember.', 'আর তিনি তোমাদের জন্য যমীনে বিভিন্ন রং-এর বস্তুরাজি সৃষ্টি করেছেন। এতে ঐ সমস্ত লোকেদের জন্য নিশ্চিতভাবে নিদর্শন আছে যারা উপদেশ গ্রহণ করতে চায়।', 'And [He has subjected] whatever He multiplied for you on the earth of varying colors. Indeed in that is a sign for a people who remember.', NULL, NULL, NULL, NULL, NULL, 'https://everyayah.com/data/Alafasy_128kbps/016013.mp3', now()),
  (16, 14, '', '[{"id":16760,"position":1,"text_uthmani":"وَهُوَ","transliteration":"wahuwa","translation_bn":"এবং তিনি","root":"—","lemma":"وَهُوَ","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":16761,"position":2,"text_uthmani":"ٱلَّذِى","transliteration":"alladhī","translation_bn":"যিনি","root":"—","lemma":"ٱلَّذِى","grammar_bn":"সাপেক্ষ সর্বনাম (Relative)"},{"id":16762,"position":3,"text_uthmani":"سَخَّرَ","transliteration":"sakhara","translation_bn":"অধীন করেছেন","root":"سخر","lemma":"سَخَّرَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":16763,"position":4,"text_uthmani":"ٱلْبَحْرَ","transliteration":"l-baḥra","translation_bn":"সমুদ্রকে","root":"بحر","lemma":"بَحْر","grammar_bn":"শব্দ"},{"id":16764,"position":5,"text_uthmani":"لِتَأْكُلُوا۟","transliteration":"litakulū","translation_bn":"যেন তোমরা  খেতে পারো","root":"اكل","lemma":"أَكَلَ","grammar_bn":"শব্দ"},{"id":16765,"position":6,"text_uthmani":"مِنْهُ","transliteration":"min''hu","translation_bn":"তা থেকে","root":"—","lemma":"مِن\r","grammar_bn":"অব্যয় (Preposition)"},{"id":16766,"position":7,"text_uthmani":"لَحْمًۭا","transliteration":"laḥman","translation_bn":"(মাছ) গোশত","root":"لحم","lemma":"لَحْم","grammar_bn":"বিশেষ্য (Noun)"},{"id":16767,"position":8,"text_uthmani":"طَرِيًّۭا","transliteration":"ṭariyyan","translation_bn":"তাজা","root":"طرو","lemma":"طَرِيّ","grammar_bn":"বিশেষণ (Adjective)"},{"id":16768,"position":9,"text_uthmani":"وَتَسْتَخْرِجُوا۟","transliteration":"watastakhrijū","translation_bn":"তোমরা বের করতে পারো","root":"خرج","lemma":"ٱسْتَخْرَجَ","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":16769,"position":10,"text_uthmani":"مِنْهُ","transliteration":"min''hu","translation_bn":"তা থেকে","root":"—","lemma":"مِن\r","grammar_bn":"অব্যয় (Preposition)"},{"id":16770,"position":11,"text_uthmani":"حِلْيَةًۭ","transliteration":"ḥil''yatan","translation_bn":"সৌন্দর্য শোভা (মনি-মুক্তা)","root":"حلي","lemma":"حِلْيَة","grammar_bn":"বিশেষ্য (Noun)"},{"id":16771,"position":12,"text_uthmani":"تَلْبَسُونَهَا","transliteration":"talbasūnahā","translation_bn":"তোমরা তা পরিধান করো","root":"لبس","lemma":"لَبَسْ","grammar_bn":"ক্রিয়া (Verb)"},{"id":16772,"position":13,"text_uthmani":"وَتَرَى","transliteration":"watarā","translation_bn":"এবং দেখছো","root":"راي","lemma":"رَءَا","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":16773,"position":14,"text_uthmani":"ٱلْفُلْكَ","transliteration":"l-ful''ka","translation_bn":"নৌযানসমূহকে","root":"فلك","lemma":"فُلْك","grammar_bn":"শব্দ"},{"id":16774,"position":15,"text_uthmani":"مَوَاخِرَ","transliteration":"mawākhira","translation_bn":"পানি বিদীর্ণকারী","root":"مخر","lemma":"مَوَاخِر","grammar_bn":"বিশেষ্য (Noun)"},{"id":16775,"position":16,"text_uthmani":"فِيهِ","transliteration":"fīhi","translation_bn":"তার মধ্যে","root":"—","lemma":"فِى\r","grammar_bn":"অব্যয় (Preposition)"},{"id":16776,"position":17,"text_uthmani":"وَلِتَبْتَغُوا۟","transliteration":"walitabtaghū","translation_bn":"এবং যেন তোমরা সন্ধান করতে পারো","root":"بغي","lemma":"ٱبْتَغَىٰ","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":16777,"position":18,"text_uthmani":"مِن","transliteration":"min","translation_bn":"থেকে","root":"—","lemma":"مِن\r","grammar_bn":"অব্যয় (Preposition)"},{"id":16778,"position":19,"text_uthmani":"فَضْلِهِۦ","transliteration":"faḍlihi","translation_bn":"তাঁর অনুগ্রহ","root":"فضل","lemma":"فَضْل","grammar_bn":"বিশেষ্য (Noun)"},{"id":16779,"position":20,"text_uthmani":"وَلَعَلَّكُمْ","transliteration":"walaʿallakum","translation_bn":"এবং তোমরা যাতে","root":"—","lemma":"لَعَلّ","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":16780,"position":21,"text_uthmani":"تَشْكُرُونَ","transliteration":"tashkurūna","translation_bn":"কৃতজ্ঞতা প্রকাশ করো","root":"شكر","lemma":"شَكَرَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":16781,"position":22,"text_uthmani":"١٤","transliteration":"","translation_bn":"(১৪)","root":"—","lemma":"١٤","grammar_bn":"মার্কার"}]'::jsonb, 'wahuwa alladhī sakhara l-baḥra litakulū min''hu laḥman ṭariyyan watastakhrijū min''hu ḥil''yatan talbasūnahā watarā l-ful''ka mawākhira fīhi walitabtaghū min faḍlihi walaʿallakum tashkurūna', 'তিনিই সমুদ্রকে কল্যাণে নিয়োজিত রেখেছেন যাতে তোমরা তাত্থেকে তাজা গোশত খেতে পার, আর তাত্থেকে তোমরা রত্নরাজি সংগ্রহ করতে পার যা তোমরা অলংকার হিসেবে পরিধান কর। আর নৌযানগুলোকে তোমরা দেখতে পাও ঢেউয়ের বুক চিরে তাতে চলাচল করে, যাতে তোমরা তাঁর অনুগ্রহ তালাশ করতে পার আর শোকর আদায় করতে পার।', 'And it is He who subjected the sea for you to eat from it tender meat and to extract from it ornaments which you wear. And you see the ships plowing through it, and [He subjected it] that you may seek of His bounty; and perhaps you will be grateful.', 'তিনিই সমুদ্রকে কল্যাণে নিয়োজিত রেখেছেন যাতে তোমরা তাত্থেকে তাজা গোশত খেতে পার, আর তাত্থেকে তোমরা রত্নরাজি সংগ্রহ করতে পার যা তোমরা অলংকার হিসেবে পরিধান কর। আর নৌযানগুলোকে তোমরা দেখতে পাও ঢেউয়ের বুক চিরে তাতে চলাচল করে, যাতে তোমরা তাঁর অনুগ্রহ তালাশ করতে পার আর শোকর আদায় করতে পার।', 'And it is He who subjected the sea for you to eat from it tender meat and to extract from it ornaments which you wear. And you see the ships plowing through it, and [He subjected it] that you may seek of His bounty; and perhaps you will be grateful.', NULL, NULL, NULL, NULL, NULL, 'https://everyayah.com/data/Alafasy_128kbps/016014.mp3', now()),
  (16, 15, '', '[{"id":17930,"position":1,"text_uthmani":"وَأَلْقَىٰ","transliteration":"wa-alqā","translation_bn":"এবং তিনি স্থাপন করেছেন","root":"لقي","lemma":"أَلْقَىٰ^","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":17931,"position":2,"text_uthmani":"فِى","transliteration":"fī","translation_bn":"মধ্যে","root":"—","lemma":"فِى\r","grammar_bn":"অব্যয় (Preposition)"},{"id":17932,"position":3,"text_uthmani":"ٱلْأَرْضِ","transliteration":"l-arḍi","translation_bn":"পৃথিবীর","root":"ارض","lemma":"أَرْض","grammar_bn":"শব্দ"},{"id":17933,"position":4,"text_uthmani":"رَوَٰسِىَ","transliteration":"rawāsiya","translation_bn":"পর্বতসমূহকে","root":"رسو","lemma":"رَوَٰسِى","grammar_bn":"বিশেষ্য (Noun)"},{"id":17934,"position":5,"text_uthmani":"أَن","transliteration":"an","translation_bn":"(এমন না হয়) যে","root":"—","lemma":"أَن\r","grammar_bn":"অধীনস্থ যোজক (Subordinating)"},{"id":17935,"position":6,"text_uthmani":"تَمِيدَ","transliteration":"tamīda","translation_bn":"হেলে যায়","root":"ميد","lemma":"تَمِيدَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":17936,"position":7,"text_uthmani":"بِكُمْ","transliteration":"bikum","translation_bn":"তোমাদের নিয়ে","root":"—","lemma":"بِكُمْ","grammar_bn":"অব্যয় (Preposition)"},{"id":17937,"position":8,"text_uthmani":"وَأَنْهَـٰرًۭا","transliteration":"wa-anhāran","translation_bn":"ও নদীসমূহ","root":"نهر","lemma":"نَهَر","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":17938,"position":9,"text_uthmani":"وَسُبُلًۭا","transliteration":"wasubulan","translation_bn":"এবং রাস্তাসমূহ","root":"سبل","lemma":"سَبِيل","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":17939,"position":10,"text_uthmani":"لَّعَلَّكُمْ","transliteration":"laʿallakum","translation_bn":"যাতে তোমরা","root":"—","lemma":"لَعَلّ","grammar_bn":"অভিঘাত পদ (Accusative)"},{"id":17940,"position":11,"text_uthmani":"تَهْتَدُونَ","transliteration":"tahtadūna","translation_bn":"পথের সন্ধান পাও","root":"هدي","lemma":"ٱهْتَدَىٰ","grammar_bn":"ক্রিয়া (Verb)"},{"id":17941,"position":12,"text_uthmani":"١٥","transliteration":"","translation_bn":"(১৫)","root":"—","lemma":"١٥","grammar_bn":"মার্কার"}]'::jsonb, 'wa-alqā fī l-arḍi rawāsiya an tamīda bikum wa-anhāran wasubulan laʿallakum tahtadūna', 'তিনি যমীনে সুদৃঢ় পর্বত সংস্থাপিত করেছেন যাতে যমীন তোমাদেরকে নিয়ে আন্দোলিত না হয়, আর সংস্থাপিত করেছেন নদী নির্ঝরিণী আর পথ যাতে তোমরা পথের সন্ধান পেতে পার।', 'And He has cast into the earth firmly set mountains, lest it shift with you, and [made] rivers and roads, that you may be guided,', 'তিনি যমীনে সুদৃঢ় পর্বত সংস্থাপিত করেছেন যাতে যমীন তোমাদেরকে নিয়ে আন্দোলিত না হয়, আর সংস্থাপিত করেছেন নদী নির্ঝরিণী আর পথ যাতে তোমরা পথের সন্ধান পেতে পার।', 'And He has cast into the earth firmly set mountains, lest it shift with you, and [made] rivers and roads, that you may be guided,', NULL, NULL, NULL, NULL, NULL, 'https://everyayah.com/data/Alafasy_128kbps/016015.mp3', now()),
  (16, 16, '', '[{"id":18945,"position":1,"text_uthmani":"وَعَلَـٰمَـٰتٍۢ ۚ","transliteration":"waʿalāmātin","translation_bn":"ও (যমীনে) পথনির্ণায়ক চিহ্নসমূহ","root":"علم","lemma":"عَلَٰمَٰت","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":18947,"position":2,"text_uthmani":"وَبِٱلنَّجْمِ","transliteration":"wabil-najmi","translation_bn":"এবং সাহায্যে নক্ষত্রের","root":"نجم","lemma":"نَّجْم","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":18948,"position":3,"text_uthmani":"هُمْ","transliteration":"hum","translation_bn":"তারা","root":"—","lemma":"هُمْ","grammar_bn":"সর্বনাম (Pronoun)"},{"id":18949,"position":4,"text_uthmani":"يَهْتَدُونَ","transliteration":"yahtadūna","translation_bn":"পথ নির্দেশ পায়","root":"هدي","lemma":"ٱهْتَدَىٰ","grammar_bn":"ক্রিয়া (Verb)"},{"id":18950,"position":5,"text_uthmani":"١٦","transliteration":"","translation_bn":"(১৬)","root":"—","lemma":"١٦","grammar_bn":"মার্কার"}]'::jsonb, 'waʿalāmātin wabil-najmi hum yahtadūna', 'আর দিক-দিশা প্রদানকারী চিহ্নসমূহ; আর তারকারাজির সাহায্যেও তারা পথনির্দেশ লাভ করে।', 'And landmarks. And by the stars they are [also] guided.', 'আর দিক-দিশা প্রদানকারী চিহ্নসমূহ; আর তারকারাজির সাহায্যেও তারা পথনির্দেশ লাভ করে।', 'And landmarks. And by the stars they are [also] guided.', NULL, NULL, NULL, NULL, NULL, 'https://everyayah.com/data/Alafasy_128kbps/016016.mp3', now()),
  (16, 17, '', '[{"id":20046,"position":1,"text_uthmani":"أَفَمَن","transliteration":"afaman","translation_bn":"তবে কি যিনি","root":"—","lemma":"مَن\r","grammar_bn":"প্রশ্নবোধক (Interrogative)"},{"id":20047,"position":2,"text_uthmani":"يَخْلُقُ","transliteration":"yakhluqu","translation_bn":"সৃষ্টি করেছেন","root":"خلق","lemma":"خَلَقَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":20048,"position":3,"text_uthmani":"كَمَن","transliteration":"kaman","translation_bn":"(তার) মতো যে","root":"—","lemma":"مَن\r","grammar_bn":"অব্যয় (Preposition)"},{"id":20049,"position":4,"text_uthmani":"لَّا","transliteration":"lā","translation_bn":"না","root":"—","lemma":"لَا\r","grammar_bn":"না-বোধক (Negative)"},{"id":20050,"position":5,"text_uthmani":"يَخْلُقُ ۗ","transliteration":"yakhluqu","translation_bn":"সৃষ্টি করে (কোন কিছুই)","root":"خلق","lemma":"خَلَقَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":20052,"position":6,"text_uthmani":"أَفَلَا","transliteration":"afalā","translation_bn":"তবুও কি না","root":"—","lemma":"لَا\r","grammar_bn":"প্রশ্নবোধক (Interrogative)"},{"id":20053,"position":7,"text_uthmani":"تَذَكَّرُونَ","transliteration":"tadhakkarūna","translation_bn":"তোমরা শিক্ষা গ্রহণ করবে","root":"ذكر","lemma":"تَذَكَّرَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":20054,"position":8,"text_uthmani":"١٧","transliteration":"","translation_bn":"(১৭)","root":"—","lemma":"١٧","grammar_bn":"মার্কার"}]'::jsonb, 'afaman yakhluqu kaman lā yakhluqu afalā tadhakkarūna', 'যিনি সৃষ্টি করেন তিনি কি তার মত যে সৃষ্টি করে না? তবে কি তোমরা শিক্ষা গ্রহণ করবে না?', 'Then is He who creates like one who does not create? So will you not be reminded?', 'যিনি সৃষ্টি করেন তিনি কি তার মত যে সৃষ্টি করে না? তবে কি তোমরা শিক্ষা গ্রহণ করবে না?', 'Then is He who creates like one who does not create? So will you not be reminded?', NULL, NULL, NULL, NULL, NULL, 'https://everyayah.com/data/Alafasy_128kbps/016017.mp3', now()),
  (16, 18, '', '[{"id":21135,"position":1,"text_uthmani":"وَإِن","transliteration":"wa-in","translation_bn":"এবং যদি","root":"—","lemma":"إِن\r","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":21136,"position":2,"text_uthmani":"تَعُدُّوا۟","transliteration":"taʿuddū","translation_bn":"তোমরা গণনা করো","root":"عدد","lemma":"عَدَّ","grammar_bn":"ক্রিয়া (Verb)"},{"id":21137,"position":3,"text_uthmani":"نِعْمَةَ","transliteration":"niʿ''mata","translation_bn":"অনুগ্রহকে","root":"نعم","lemma":"نِعْمَة","grammar_bn":"বিশেষ্য (Noun)"},{"id":21138,"position":4,"text_uthmani":"ٱللَّهِ","transliteration":"l-lahi","translation_bn":"আল্লাহর","root":"اله","lemma":"ٱللَّه","grammar_bn":"নামবাচক বিশেষ্য (Proper Noun)"},{"id":21139,"position":5,"text_uthmani":"لَا","transliteration":"lā","translation_bn":"না","root":"—","lemma":"لَا\r","grammar_bn":"নিষেধবাচক (Prohibition)"},{"id":21140,"position":6,"text_uthmani":"تُحْصُوهَآ ۗ","transliteration":"tuḥ''ṣūhā","translation_bn":"তার সংখ্যা নির্ণয় করতে পারবে","root":"حصي","lemma":"أَحْصَىٰ","grammar_bn":"ক্রিয়া (Verb)"},{"id":21142,"position":7,"text_uthmani":"إِنَّ","transliteration":"inna","translation_bn":"নিশ্চয়ই","root":"—","lemma":"إِنّ","grammar_bn":"অভিঘাত পদ (Accusative)"},{"id":21143,"position":8,"text_uthmani":"ٱللَّهَ","transliteration":"l-laha","translation_bn":"আল্লাহ্‌","root":"اله","lemma":"ٱللَّه","grammar_bn":"নামবাচক বিশেষ্য (Proper Noun)"},{"id":21144,"position":9,"text_uthmani":"لَغَفُورٌۭ","transliteration":"laghafūrun","translation_bn":"অবশ্যই ক্ষমাশীল","root":"غفر","lemma":"غَفُور","grammar_bn":"দৃঢ়তাবোধক (Emphatic)"},{"id":21145,"position":10,"text_uthmani":"رَّحِيمٌۭ","transliteration":"raḥīmun","translation_bn":"পরম দয়ালু","root":"رحم","lemma":"رَّحِيم","grammar_bn":"বিশেষণ (Adjective)"},{"id":21146,"position":11,"text_uthmani":"١٨","transliteration":"","translation_bn":"(১৮)","root":"—","lemma":"١٨","grammar_bn":"মার্কার"}]'::jsonb, 'wa-in taʿuddū niʿ''mata l-lahi lā tuḥ''ṣūhā inna l-laha laghafūrun raḥīmun', 'তোমরা আল্লাহর নি‘মাতসমূহকে গণনা করলে তার সংখ্যা নির্ণয় করতে পারবে না; আল্লাহ অবশ্যই বড়ই ক্ষমাশীল, বড়ই দয়ালু।', 'And if you should count the favors of Allah, you could not enumerate them. Indeed, Allah is Forgiving and Merciful.', 'তোমরা আল্লাহর নি‘মাতসমূহকে গণনা করলে তার সংখ্যা নির্ণয় করতে পারবে না; আল্লাহ অবশ্যই বড়ই ক্ষমাশীল, বড়ই দয়ালু।', 'And if you should count the favors of Allah, you could not enumerate them. Indeed, Allah is Forgiving and Merciful.', NULL, NULL, NULL, NULL, NULL, 'https://everyayah.com/data/Alafasy_128kbps/016018.mp3', now()),
  (16, 19, '', '[{"id":22251,"position":1,"text_uthmani":"وَٱللَّهُ","transliteration":"wal-lahu","translation_bn":"এবং আল্লাহ্‌","root":"اله","lemma":"ٱللَّه","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":22252,"position":2,"text_uthmani":"يَعْلَمُ","transliteration":"yaʿlamu","translation_bn":"জানেন","root":"علم","lemma":"عَلِمَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":22253,"position":3,"text_uthmani":"مَا","transliteration":"mā","translation_bn":"যা","root":"—","lemma":"مَا\r","grammar_bn":"সাপেক্ষ সর্বনাম (Relative)"},{"id":22254,"position":4,"text_uthmani":"تُسِرُّونَ","transliteration":"tusirrūna","translation_bn":"তোমরা গোপন রাখো","root":"سرر","lemma":"أَسَرَّ","grammar_bn":"ক্রিয়া (Verb)"},{"id":22255,"position":5,"text_uthmani":"وَمَا","transliteration":"wamā","translation_bn":"এবং যা","root":"—","lemma":"مَا\r","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":22256,"position":6,"text_uthmani":"تُعْلِنُونَ","transliteration":"tuʿ''linūna","translation_bn":"তোমরা প্রকাশ করো","root":"علن","lemma":"أَعْلَن","grammar_bn":"ক্রিয়া (Verb)"},{"id":22257,"position":7,"text_uthmani":"١٩","transliteration":"","translation_bn":"(১৯)","root":"—","lemma":"١٩","grammar_bn":"মার্কার"}]'::jsonb, 'wal-lahu yaʿlamu mā tusirrūna wamā tuʿ''linūna', 'আল্লাহ জানেন তোমরা যা গোপন কর আর যা তোমরা প্রকাশ কর।', 'And Allah knows what you conceal and what you declare.', 'আল্লাহ জানেন তোমরা যা গোপন কর আর যা তোমরা প্রকাশ কর।', 'And Allah knows what you conceal and what you declare.', NULL, NULL, NULL, NULL, NULL, 'https://everyayah.com/data/Alafasy_128kbps/016019.mp3', now()),
  (16, 20, '', '[{"id":23270,"position":1,"text_uthmani":"وَٱلَّذِينَ","transliteration":"wa-alladhīna","translation_bn":"এবং যারা","root":"—","lemma":"ٱلَّذِى","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":23271,"position":2,"text_uthmani":"يَدْعُونَ","transliteration":"yadʿūna","translation_bn":"ডাকে","root":"دعو","lemma":"دَعَا","grammar_bn":"ক্রিয়া (Verb)"},{"id":23272,"position":3,"text_uthmani":"مِن","transliteration":"min","translation_bn":"থেকে","root":"—","lemma":"مِن\r","grammar_bn":"অব্যয় (Preposition)"},{"id":23273,"position":4,"text_uthmani":"دُونِ","transliteration":"dūni","translation_bn":"ছাড়া","root":"دون","lemma":"دُون","grammar_bn":"বিশেষ্য (Noun)"},{"id":23274,"position":5,"text_uthmani":"ٱللَّهِ","transliteration":"l-lahi","translation_bn":"আল্লাহকে","root":"اله","lemma":"ٱللَّه","grammar_bn":"নামবাচক বিশেষ্য (Proper Noun)"},{"id":23275,"position":6,"text_uthmani":"لَا","transliteration":"lā","translation_bn":"না","root":"—","lemma":"لَا\r","grammar_bn":"না-বোধক (Negative)"},{"id":23276,"position":7,"text_uthmani":"يَخْلُقُونَ","transliteration":"yakhluqūna","translation_bn":"তারা সৃষ্টি করে","root":"خلق","lemma":"خَلَقَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":23277,"position":8,"text_uthmani":"شَيْـًۭٔا","transliteration":"shayan","translation_bn":"কোনো কিছু","root":"شيا","lemma":"شَىْء","grammar_bn":"বিশেষ্য (Noun)"},{"id":23278,"position":9,"text_uthmani":"وَهُمْ","transliteration":"wahum","translation_bn":"বরং তাদেরকে","root":"—","lemma":"وَهُمْ","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":23279,"position":10,"text_uthmani":"يُخْلَقُونَ","transliteration":"yukh''laqūna","translation_bn":"সৃষ্টি করা হয়েছে","root":"خلق","lemma":"خَلَقَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":23280,"position":11,"text_uthmani":"٢٠","transliteration":"","translation_bn":"(২০)","root":"—","lemma":"٢٠","grammar_bn":"মার্কার"}]'::jsonb, 'wa-alladhīna yadʿūna min dūni l-lahi lā yakhluqūna shayan wahum yukh''laqūna', 'তারা আল্লাহ ছাড়া অন্য যাদেরকে ডাকে তারা কিছুই সৃষ্টি করে না, তারা (নিজেরাই) সৃষ্ট।', 'And those they invoke other than Allah create nothing, and they [themselves] are created.', 'তারা আল্লাহ ছাড়া অন্য যাদেরকে ডাকে তারা কিছুই সৃষ্টি করে না, তারা (নিজেরাই) সৃষ্ট।', 'And those they invoke other than Allah create nothing, and they [themselves] are created.', NULL, NULL, NULL, NULL, NULL, 'https://everyayah.com/data/Alafasy_128kbps/016020.mp3', now()),
  (16, 21, '', '[{"id":24337,"position":1,"text_uthmani":"أَمْوَٰتٌ","transliteration":"amwātun","translation_bn":"(তারা) মৃত","root":"موت","lemma":"مَّيِّت","grammar_bn":"বিশেষ্য (Noun)"},{"id":24338,"position":2,"text_uthmani":"غَيْرُ","transliteration":"ghayru","translation_bn":"নয়","root":"غير","lemma":"غَيْر","grammar_bn":"বিশেষ্য (Noun)"},{"id":24339,"position":3,"text_uthmani":"أَحْيَآءٍۢ ۖ","transliteration":"aḥyāin","translation_bn":"জীবিত","root":"حيي","lemma":"حَيّ","grammar_bn":"বিশেষ্য (Noun)"},{"id":24341,"position":4,"text_uthmani":"وَمَا","transliteration":"wamā","translation_bn":"এবং না","root":"—","lemma":"مَا\r","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":24342,"position":5,"text_uthmani":"يَشْعُرُونَ","transliteration":"yashʿurūna","translation_bn":"চেতনা রাখে","root":"شعر","lemma":"يَشْعُرُ","grammar_bn":"ক্রিয়া (Verb)"},{"id":24343,"position":6,"text_uthmani":"أَيَّانَ","transliteration":"ayyāna","translation_bn":"কবে","root":"—","lemma":"أَيَّان\r","grammar_bn":"প্রশ্নবোধক (Interrogative)"},{"id":24344,"position":7,"text_uthmani":"يُبْعَثُونَ","transliteration":"yub''ʿathūna","translation_bn":"উঠানো হবে তাদের","root":"بعث","lemma":"بَعَثَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":24345,"position":8,"text_uthmani":"٢١","transliteration":"","translation_bn":"(২১)","root":"—","lemma":"٢١","grammar_bn":"মার্কার"}]'::jsonb, 'amwātun ghayru aḥyāin wamā yashʿurūna ayyāna yub''ʿathūna', 'তারা প্রাণহীন, জীবিত নয়, তাদের কোনই চেতনা নেই কবে তাদেরকে (পুনর্জীবিত করে) উঠানো হবে।', 'They are, [in fact], dead, not alive, and they do not perceive when they will be resurrected.', 'তারা প্রাণহীন, জীবিত নয়, তাদের কোনই চেতনা নেই কবে তাদেরকে (পুনর্জীবিত করে) উঠানো হবে।', 'They are, [in fact], dead, not alive, and they do not perceive when they will be resurrected.', NULL, NULL, NULL, NULL, NULL, 'https://everyayah.com/data/Alafasy_128kbps/016021.mp3', now()),
  (16, 22, '', '[{"id":25364,"position":1,"text_uthmani":"إِلَـٰهُكُمْ","transliteration":"ilāhukum","translation_bn":"তোমাদের ইলাহ","root":"اله","lemma":"إِلَٰه","grammar_bn":"বিশেষ্য (Noun)"},{"id":25365,"position":2,"text_uthmani":"إِلَـٰهٌۭ","transliteration":"ilāhun","translation_bn":"ইলাহ","root":"اله","lemma":"إِلَٰه","grammar_bn":"বিশেষ্য (Noun)"},{"id":25366,"position":3,"text_uthmani":"وَٰحِدٌۭ ۚ","transliteration":"wāḥidun","translation_bn":"একই","root":"وحد","lemma":"وَٰحِد","grammar_bn":"বিশেষণ (Adjective)"},{"id":25368,"position":4,"text_uthmani":"فَٱلَّذِينَ","transliteration":"fa-alladhīna","translation_bn":"সুতরাং যারা","root":"—","lemma":"ٱلَّذِى","grammar_bn":"শব্দ"},{"id":25369,"position":5,"text_uthmani":"لَا","transliteration":"lā","translation_bn":"না","root":"—","lemma":"لَا\r","grammar_bn":"না-বোধক (Negative)"},{"id":25370,"position":6,"text_uthmani":"يُؤْمِنُونَ","transliteration":"yu''minūna","translation_bn":"বিশ্বাস করে","root":"امن","lemma":"ءَامَنَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":25371,"position":7,"text_uthmani":"بِٱلْـَٔاخِرَةِ","transliteration":"bil-ākhirati","translation_bn":"প্রতি আখেরাতের","root":"اخر","lemma":"ا^خِر","grammar_bn":"অব্যয় (Preposition)"},{"id":25372,"position":8,"text_uthmani":"قُلُوبُهُم","transliteration":"qulūbuhum","translation_bn":"তাদের অন্তরসমূহ","root":"قلب","lemma":"قَلْب","grammar_bn":"বিশেষ্য (Noun)"},{"id":25373,"position":9,"text_uthmani":"مُّنكِرَةٌۭ","transliteration":"munkiratun","translation_bn":"সত্যবিমুখ","root":"نكر","lemma":"مُّنكِرَة","grammar_bn":"বিশেষ্য (Noun)"},{"id":25374,"position":10,"text_uthmani":"وَهُم","transliteration":"wahum","translation_bn":"এবং তারা","root":"—","lemma":"وَهُم","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":25375,"position":11,"text_uthmani":"مُّسْتَكْبِرُونَ","transliteration":"mus''takbirūna","translation_bn":"অহংকারী","root":"كبر","lemma":"مُسْتَكْبِر","grammar_bn":"বিশেষ্য (Noun)"},{"id":25376,"position":12,"text_uthmani":"٢٢","transliteration":"","translation_bn":"(২২)","root":"—","lemma":"٢٢","grammar_bn":"মার্কার"}]'::jsonb, 'ilāhukum ilāhun wāḥidun fa-alladhīna lā yu''minūna bil-ākhirati qulūbuhum munkiratun wahum mus''takbirūna', 'তোমাদের ইলাহ হলেন এক ইলাহ। কাজেই যারা আখেরাতে বিশ্বাস করে না, তাদের অন্তর সত্য-অস্বীকারকারী আর তারা অহংকারী।', 'Your god is one God. But those who do not believe in the Hereafter - their hearts are disapproving, and they are arrogant.', 'তোমাদের ইলাহ হলেন এক ইলাহ। কাজেই যারা আখেরাতে বিশ্বাস করে না, তাদের অন্তর সত্য-অস্বীকারকারী আর তারা অহংকারী।', 'Your god is one God. But those who do not believe in the Hereafter - their hearts are disapproving, and they are arrogant.', NULL, NULL, NULL, NULL, NULL, 'https://everyayah.com/data/Alafasy_128kbps/016022.mp3', now()),
  (16, 23, '', '[{"id":26411,"position":1,"text_uthmani":"لَا","transliteration":"lā","translation_bn":"নেই","root":"—","lemma":"لَا\r","grammar_bn":"না-বোধক (Negative)"},{"id":26412,"position":2,"text_uthmani":"جَرَمَ","transliteration":"jarama","translation_bn":"সন্দেহ","root":"جرم","lemma":"جَرَم","grammar_bn":"বিশেষ্য (Noun)"},{"id":26413,"position":3,"text_uthmani":"أَنَّ","transliteration":"anna","translation_bn":"যে","root":"—","lemma":"أَنّ","grammar_bn":"অভিঘাত পদ (Accusative)"},{"id":26414,"position":4,"text_uthmani":"ٱللَّهَ","transliteration":"l-laha","translation_bn":"আল্লাহ্‌","root":"اله","lemma":"ٱللَّه","grammar_bn":"নামবাচক বিশেষ্য (Proper Noun)"},{"id":26415,"position":5,"text_uthmani":"يَعْلَمُ","transliteration":"yaʿlamu","translation_bn":"জানেন","root":"علم","lemma":"عَلِمَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":26416,"position":6,"text_uthmani":"مَا","transliteration":"mā","translation_bn":"যা","root":"—","lemma":"مَا\r","grammar_bn":"সাপেক্ষ সর্বনাম (Relative)"},{"id":26417,"position":7,"text_uthmani":"يُسِرُّونَ","transliteration":"yusirrūna","translation_bn":"তারা গোপন রাখে","root":"سرر","lemma":"أَسَرَّ","grammar_bn":"ক্রিয়া (Verb)"},{"id":26418,"position":8,"text_uthmani":"وَمَا","transliteration":"wamā","translation_bn":"এবং যা","root":"—","lemma":"مَا\r","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":26419,"position":9,"text_uthmani":"يُعْلِنُونَ ۚ","transliteration":"yuʿ''linūna","translation_bn":"তারা প্রকাশ করে","root":"علن","lemma":"أَعْلَن","grammar_bn":"ক্রিয়া (Verb)"},{"id":26421,"position":10,"text_uthmani":"إِنَّهُۥ","transliteration":"innahu","translation_bn":"নিশ্চয়ই তিনি","root":"—","lemma":"إِنّ","grammar_bn":"অভিঘাত পদ (Accusative)"},{"id":26422,"position":11,"text_uthmani":"لَا","transliteration":"lā","translation_bn":"না","root":"—","lemma":"لَا\r","grammar_bn":"না-বোধক (Negative)"},{"id":26423,"position":12,"text_uthmani":"يُحِبُّ","transliteration":"yuḥibbu","translation_bn":"ভালোবাসেন","root":"حبب","lemma":"أَحْبَبْ","grammar_bn":"ক্রিয়া (Verb)"},{"id":26424,"position":13,"text_uthmani":"ٱلْمُسْتَكْبِرِينَ","transliteration":"l-mus''takbirīna","translation_bn":"অহংকারীদেরকে","root":"كبر","lemma":"مُسْتَكْبِر","grammar_bn":"শব্দ"},{"id":26425,"position":14,"text_uthmani":"٢٣","transliteration":"","translation_bn":"(২৩)","root":"—","lemma":"٢٣","grammar_bn":"মার্কার"}]'::jsonb, 'lā jarama anna l-laha yaʿlamu mā yusirrūna wamā yuʿ''linūna innahu lā yuḥibbu l-mus''takbirīna', 'এতে কোন সন্দেহ নেই যে, আল্লাহ জানেন যা তারা গোপন করে আর যা প্রকাশ করে, তিনি অহঙ্কারীদেরকে ভালবাসেন না।', 'Assuredly, Allah knows what they conceal and what they declare. Indeed, He does not like the arrogant.', 'এতে কোন সন্দেহ নেই যে, আল্লাহ জানেন যা তারা গোপন করে আর যা প্রকাশ করে, তিনি অহঙ্কারীদেরকে ভালবাসেন না।', 'Assuredly, Allah knows what they conceal and what they declare. Indeed, He does not like the arrogant.', NULL, NULL, NULL, NULL, NULL, 'https://everyayah.com/data/Alafasy_128kbps/016023.mp3', now()),
  (16, 24, '', '[{"id":27423,"position":1,"text_uthmani":"وَإِذَا","transliteration":"wa-idhā","translation_bn":"এবং যখন","root":"—","lemma":"إِذَا\r","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":27424,"position":2,"text_uthmani":"قِيلَ","transliteration":"qīla","translation_bn":"বলা হয়","root":"قول","lemma":"قَالَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":27425,"position":3,"text_uthmani":"لَهُم","transliteration":"lahum","translation_bn":"তাদেরকে","root":"—","lemma":"لَهُم","grammar_bn":"অব্যয় (Preposition)"},{"id":27426,"position":4,"text_uthmani":"مَّاذَآ","transliteration":"mādhā","translation_bn":"\"কি","root":"—","lemma":"مَاذَا\r","grammar_bn":"প্রশ্নবোধক (Interrogative)"},{"id":27427,"position":5,"text_uthmani":"أَنزَلَ","transliteration":"anzala","translation_bn":"অবতীর্ণ করেছেন","root":"نزل","lemma":"أَنزَلَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":27428,"position":6,"text_uthmani":"رَبُّكُمْ ۙ","transliteration":"rabbukum","translation_bn":"তোমাদের রব","root":"ربب","lemma":"رَبّ","grammar_bn":"বিশেষ্য (Noun)"},{"id":27430,"position":7,"text_uthmani":"قَالُوٓا۟","transliteration":"qālū","translation_bn":"তারা বলে","root":"قول","lemma":"قَالَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":27431,"position":8,"text_uthmani":"أَسَـٰطِيرُ","transliteration":"asāṭīru","translation_bn":"\"উপকথাসমূহ","root":"سطر","lemma":"أَسَٰطِير","grammar_bn":"বিশেষ্য (Noun)"},{"id":27432,"position":9,"text_uthmani":"ٱلْأَوَّلِينَ","transliteration":"l-awalīna","translation_bn":"পূর্ববর্তীদের\"","root":"اول","lemma":"أَوَّل","grammar_bn":"শব্দ"},{"id":27433,"position":10,"text_uthmani":"٢٤","transliteration":"","translation_bn":"(২৪)","root":"—","lemma":"٢٤","grammar_bn":"মার্কার"}]'::jsonb, 'wa-idhā qīla lahum mādhā anzala rabbukum qālū asāṭīru l-awalīna', 'তাদেরকে যখন বলা হয়, ‘তোমাদের প্রতিপালক কী নাযিল করেছেন’ তখন তারা বলে- ‘পূর্ববর্তীদের কল্প-কাহিনী’।', 'And when it is said to them, "What has your Lord sent down?" They say, "Legends of the former peoples,"', 'তাদেরকে যখন বলা হয়, ‘তোমাদের প্রতিপালক কী নাযিল করেছেন’ তখন তারা বলে- ‘পূর্ববর্তীদের কল্প-কাহিনী’।', 'And when it is said to them, "What has your Lord sent down?" They say, "Legends of the former peoples,"', NULL, NULL, NULL, NULL, NULL, 'https://everyayah.com/data/Alafasy_128kbps/016024.mp3', now()),
  (16, 25, '', '[{"id":28483,"position":1,"text_uthmani":"لِيَحْمِلُوٓا۟","transliteration":"liyaḥmilū","translation_bn":"যেন তারা বহন করে","root":"حمل","lemma":"حَمَلَ","grammar_bn":"শব্দ"},{"id":28484,"position":2,"text_uthmani":"أَوْزَارَهُمْ","transliteration":"awzārahum","translation_bn":"তাদের বোঝাসমূহ (পাপের)","root":"وزر","lemma":"وِزْر","grammar_bn":"বিশেষ্য (Noun)"},{"id":28485,"position":3,"text_uthmani":"كَامِلَةًۭ","transliteration":"kāmilatan","translation_bn":"সম্পূর্ণ","root":"كمل","lemma":"كَامِلَة","grammar_bn":"বিশেষ্য (Noun)"},{"id":28486,"position":4,"text_uthmani":"يَوْمَ","transliteration":"yawma","translation_bn":"দিনে","root":"يوم","lemma":"يَوْم","grammar_bn":"বিশেষ্য (Noun)"},{"id":28487,"position":5,"text_uthmani":"ٱلْقِيَـٰمَةِ ۙ","transliteration":"l-qiyāmati","translation_bn":"ক্বিয়ামাতের","root":"قوم","lemma":"قِيَٰمَة","grammar_bn":"শব্দ"},{"id":28489,"position":6,"text_uthmani":"وَمِنْ","transliteration":"wamin","translation_bn":"এবং থেকে","root":"—","lemma":"مِن\r","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":28490,"position":7,"text_uthmani":"أَوْزَارِ","transliteration":"awzāri","translation_bn":"বোঝাসমূহ","root":"وزر","lemma":"وِزْر","grammar_bn":"বিশেষ্য (Noun)"},{"id":28491,"position":8,"text_uthmani":"ٱلَّذِينَ","transliteration":"alladhīna","translation_bn":"(তাদের) যাদের","root":"—","lemma":"ٱلَّذِى","grammar_bn":"সাপেক্ষ সর্বনাম (Relative)"},{"id":28492,"position":9,"text_uthmani":"يُضِلُّونَهُم","transliteration":"yuḍillūnahum","translation_bn":"তারা বিভ্রান্ত করেছে তাদেরকে","root":"ضلل","lemma":"أَضَلَّ","grammar_bn":"ক্রিয়া (Verb)"},{"id":28493,"position":10,"text_uthmani":"بِغَيْرِ","transliteration":"bighayri","translation_bn":"ছাড়া","root":"غير","lemma":"غَيْر","grammar_bn":"অব্যয় (Preposition)"},{"id":28494,"position":11,"text_uthmani":"عِلْمٍ ۗ","transliteration":"ʿil''min","translation_bn":"কোনো জ্ঞান","root":"علم","lemma":"عِلْم","grammar_bn":"বিশেষ্য (Noun)"},{"id":28496,"position":12,"text_uthmani":"أَلَا","transliteration":"alā","translation_bn":"জেনে রাখো","root":"—","lemma":"أَلَا^\r","grammar_bn":"অসম্পূর্ণ (Inceptive)"},{"id":28497,"position":13,"text_uthmani":"سَآءَ","transliteration":"sāa","translation_bn":"অতি নিকৃষ্ট","root":"سوا","lemma":"سَا^ءَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":28498,"position":14,"text_uthmani":"مَا","transliteration":"mā","translation_bn":"যা","root":"—","lemma":"مَا\r","grammar_bn":"সাপেক্ষ সর্বনাম (Relative)"},{"id":28499,"position":15,"text_uthmani":"يَزِرُونَ","transliteration":"yazirūna","translation_bn":"তারা বহন করবে","root":"وزر","lemma":"يَزِرُ","grammar_bn":"ক্রিয়া (Verb)"},{"id":28500,"position":16,"text_uthmani":"٢٥","transliteration":"","translation_bn":"(২৫)","root":"—","lemma":"٢٥","grammar_bn":"মার্কার"}]'::jsonb, 'liyaḥmilū awzārahum kāmilatan yawma l-qiyāmati wamin awzāri alladhīna yuḍillūnahum bighayri ʿil''min alā sāa mā yazirūna', 'যার ফলে ক্বিয়ামাত দিবসে তারা বহন করবে নিজেদের পাপের বোঝা পূর্ণ মাত্রায়, আর (আংশিক) তাদেরও পাপের বোঝা যাদেরকে তারা গুমরাহ করেছে নিজেদের অজ্ঞতার কারণে। হায়, তারা যা বহন করবে তা কতই না নিকৃষ্ট!', 'That they may bear their own burdens in full on the Day of Resurrection and some of the burdens of those whom they misguide without knowledge. Unquestionably, evil is that which they bear.', 'যার ফলে ক্বিয়ামাত দিবসে তারা বহন করবে নিজেদের পাপের বোঝা পূর্ণ মাত্রায়, আর (আংশিক) তাদেরও পাপের বোঝা যাদেরকে তারা গুমরাহ করেছে নিজেদের অজ্ঞতার কারণে। হায়, তারা যা বহন করবে তা কতই না নিকৃষ্ট!', 'That they may bear their own burdens in full on the Day of Resurrection and some of the burdens of those whom they misguide without knowledge. Unquestionably, evil is that which they bear.', NULL, NULL, NULL, NULL, NULL, 'https://everyayah.com/data/Alafasy_128kbps/016025.mp3', now()),
  (16, 26, '', '[{"id":29395,"position":1,"text_uthmani":"قَدْ","transliteration":"qad","translation_bn":"নিশ্চয়ই","root":"—","lemma":"قَد\r","grammar_bn":"নিশ্চয়তাবোধক (Certainty)"},{"id":29396,"position":2,"text_uthmani":"مَكَرَ","transliteration":"makara","translation_bn":"চক্রান্ত করেছিলো","root":"مكر","lemma":"مَكَرَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":29397,"position":3,"text_uthmani":"ٱلَّذِينَ","transliteration":"alladhīna","translation_bn":"যারা (ছিলো)","root":"—","lemma":"ٱلَّذِى","grammar_bn":"সাপেক্ষ সর্বনাম (Relative)"},{"id":29398,"position":4,"text_uthmani":"مِن","transliteration":"min","translation_bn":"থেকেই","root":"—","lemma":"مِن\r","grammar_bn":"অব্যয় (Preposition)"},{"id":29399,"position":5,"text_uthmani":"قَبْلِهِمْ","transliteration":"qablihim","translation_bn":"তাদের পূর্ব","root":"قبل","lemma":"قَبْل","grammar_bn":"বিশেষ্য (Noun)"},{"id":29400,"position":6,"text_uthmani":"فَأَتَى","transliteration":"fa-atā","translation_bn":"অতঃপর আসলেন (আঘাত করলেন)","root":"اتي","lemma":"أَتَى","grammar_bn":"শব্দ"},{"id":29401,"position":7,"text_uthmani":"ٱللَّهُ","transliteration":"l-lahu","translation_bn":"আল্লাহ্‌","root":"اله","lemma":"ٱللَّه","grammar_bn":"নামবাচক বিশেষ্য (Proper Noun)"},{"id":29402,"position":8,"text_uthmani":"بُنْيَـٰنَهُم","transliteration":"bun''yānahum","translation_bn":"তাদের কাঠামোতে","root":"بني","lemma":"بُنْيَٰن","grammar_bn":"বিশেষ্য (Noun)"},{"id":29403,"position":9,"text_uthmani":"مِّنَ","transliteration":"mina","translation_bn":"থেকে","root":"—","lemma":"مِن\r","grammar_bn":"অব্যয় (Preposition)"},{"id":29404,"position":10,"text_uthmani":"ٱلْقَوَاعِدِ","transliteration":"l-qawāʿidi","translation_bn":"ভিত্তিমূলের","root":"قعد","lemma":"قَوَاعِد","grammar_bn":"শব্দ"},{"id":29405,"position":11,"text_uthmani":"فَخَرَّ","transliteration":"fakharra","translation_bn":"অতঃপর ধসে পড়লো","root":"خرر","lemma":"خَرَّ","grammar_bn":"শব্দ"},{"id":29406,"position":12,"text_uthmani":"عَلَيْهِمُ","transliteration":"ʿalayhimu","translation_bn":"উপর তাদের","root":"—","lemma":"عَلَىٰ\r","grammar_bn":"অব্যয় (Preposition)"},{"id":29407,"position":13,"text_uthmani":"ٱلسَّقْفُ","transliteration":"l-saqfu","translation_bn":"ছাদ","root":"سقف","lemma":"سَقْف","grammar_bn":"শব্দ"},{"id":29408,"position":14,"text_uthmani":"مِن","transliteration":"min","translation_bn":"হ''তে","root":"—","lemma":"مِن\r","grammar_bn":"অব্যয় (Preposition)"},{"id":29409,"position":15,"text_uthmani":"فَوْقِهِمْ","transliteration":"fawqihim","translation_bn":"উপর তাদের","root":"فوق","lemma":"فَوْق","grammar_bn":"বিশেষ্য (Noun)"},{"id":29410,"position":16,"text_uthmani":"وَأَتَىٰهُمُ","transliteration":"wa-atāhumu","translation_bn":"এবং তাদের উপর আসলো","root":"اتي","lemma":"أَتَى","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":29411,"position":17,"text_uthmani":"ٱلْعَذَابُ","transliteration":"l-ʿadhābu","translation_bn":"শাস্তি","root":"عذب","lemma":"عَذَاب","grammar_bn":"শব্দ"},{"id":29412,"position":18,"text_uthmani":"مِنْ","transliteration":"min","translation_bn":"থেকে","root":"—","lemma":"مِن\r","grammar_bn":"অব্যয় (Preposition)"},{"id":29413,"position":19,"text_uthmani":"حَيْثُ","transliteration":"ḥaythu","translation_bn":"যেখান","root":"حيث","lemma":"حَيْث","grammar_bn":"বিশেষ্য (Noun)"},{"id":29414,"position":20,"text_uthmani":"لَا","transliteration":"lā","translation_bn":"না","root":"—","lemma":"لَا\r","grammar_bn":"না-বোধক (Negative)"},{"id":29415,"position":21,"text_uthmani":"يَشْعُرُونَ","transliteration":"yashʿurūna","translation_bn":"তারা ধারণ করে","root":"شعر","lemma":"يَشْعُرُ","grammar_bn":"ক্রিয়া (Verb)"},{"id":29416,"position":22,"text_uthmani":"٢٦","transliteration":"","translation_bn":"(২৬)","root":"—","lemma":"٢٦","grammar_bn":"মার্কার"}]'::jsonb, 'qad makara alladhīna min qablihim fa-atā l-lahu bun''yānahum mina l-qawāʿidi fakharra ʿalayhimu l-saqfu min fawqihim wa-atāhumu l-ʿadhābu min ḥaythu lā yashʿurūna', 'তাদের পূর্বে যারা ছিল তারাও চক্রান্ত করেছিল। ফলে আল্লাহ তাদের ইমারাতকে মূল থেকে উৎপাটিত করেছিলেন আর উপর থেকে ছাদ তাদের উপর ভেঙ্গে পড়ল, আর তাদের প্রতি শাস্তি পতিত হল এমন দিক হতে যা তারা এতটুকু টের পায়নি।', 'Those before them had already plotted, but Allah came at their building from the foundations, so the roof fell upon them from above them, and the punishment came to them from where they did not perceive.', 'তাদের পূর্বে যারা ছিল তারাও চক্রান্ত করেছিল। ফলে আল্লাহ তাদের ইমারাতকে মূল থেকে উৎপাটিত করেছিলেন আর উপর থেকে ছাদ তাদের উপর ভেঙ্গে পড়ল, আর তাদের প্রতি শাস্তি পতিত হল এমন দিক হতে যা তারা এতটুকু টের পায়নি।', 'Those before them had already plotted, but Allah came at their building from the foundations, so the roof fell upon them from above them, and the punishment came to them from where they did not perceive.', NULL, NULL, NULL, NULL, NULL, 'https://everyayah.com/data/Alafasy_128kbps/016026.mp3', now()),
  (16, 27, '', '[{"id":30389,"position":1,"text_uthmani":"ثُمَّ","transliteration":"thumma","translation_bn":"অতঃপর","root":"—","lemma":"ثُمّ\r","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":30390,"position":2,"text_uthmani":"يَوْمَ","transliteration":"yawma","translation_bn":"দিনে","root":"يوم","lemma":"يَوْم","grammar_bn":"বিশেষ্য (Noun)"},{"id":30391,"position":3,"text_uthmani":"ٱلْقِيَـٰمَةِ","transliteration":"l-qiyāmati","translation_bn":"ক্বিয়ামাতের","root":"قوم","lemma":"قِيَٰمَة","grammar_bn":"শব্দ"},{"id":30392,"position":4,"text_uthmani":"يُخْزِيهِمْ","transliteration":"yukh''zīhim","translation_bn":"তিনি লাঞ্ছিত করবেন তাদের","root":"خزي","lemma":"أَخْزَيْ","grammar_bn":"ক্রিয়া (Verb)"},{"id":30393,"position":5,"text_uthmani":"وَيَقُولُ","transliteration":"wayaqūlu","translation_bn":"এবং বলবেন","root":"قول","lemma":"قَالَ","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":30394,"position":6,"text_uthmani":"أَيْنَ","transliteration":"ayna","translation_bn":"\"কোথায়","root":"—","lemma":"أَيْن\r","grammar_bn":"প্রশ্নবোধক (Interrogative)"},{"id":30395,"position":7,"text_uthmani":"شُرَكَآءِىَ","transliteration":"shurakāiya","translation_bn":"আমার শরীকরা","root":"شرك","lemma":"شَرِيك","grammar_bn":"বিশেষ্য (Noun)"},{"id":30396,"position":8,"text_uthmani":"ٱلَّذِينَ","transliteration":"alladhīna","translation_bn":"যাদের (ব্যাপারে)","root":"—","lemma":"ٱلَّذِى","grammar_bn":"সাপেক্ষ সর্বনাম (Relative)"},{"id":30397,"position":9,"text_uthmani":"كُنتُمْ","transliteration":"kuntum","translation_bn":"তোমরা ছিলে","root":"كون","lemma":"كَانَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":30398,"position":10,"text_uthmani":"تُشَـٰٓقُّونَ","transliteration":"tushāqqūna","translation_bn":"তর্কাতর্কি করতে","root":"شقق","lemma":"شَا^قُّ","grammar_bn":"ক্রিয়া (Verb)"},{"id":30399,"position":11,"text_uthmani":"فِيهِمْ ۚ","transliteration":"fīhim","translation_bn":"তাদের ব্যাপারে\"","root":"—","lemma":"فِى\r","grammar_bn":"অব্যয় (Preposition)"},{"id":30401,"position":12,"text_u