  (17, 1, '', '[{"id":72,"position":1,"text_uthmani":"سُبْحَـٰنَ","transliteration":"sub''ḥāna","translation_bn":"মহিমাময় (সত্ত্বা)","root":"سبح","lemma":"سُبْحَٰن","grammar_bn":"বিশেষ্য (Noun)"},{"id":73,"position":2,"text_uthmani":"ٱلَّذِىٓ","transliteration":"alladhī","translation_bn":"(তিনি) যিনি","root":"—","lemma":"ٱلَّذِى","grammar_bn":"সাপেক্ষ সর্বনাম (Relative)"},{"id":74,"position":3,"text_uthmani":"أَسْرَىٰ","transliteration":"asrā","translation_bn":"ভ্রমণ করালেন","root":"سري","lemma":"أَسْرَىٰ","grammar_bn":"ক্রিয়া (Verb)"},{"id":75,"position":4,"text_uthmani":"بِعَبْدِهِۦ","transliteration":"biʿabdihi","translation_bn":"তাঁর দাসকে","root":"عبد","lemma":"عَبْد","grammar_bn":"অব্যয় (Preposition)"},{"id":76,"position":5,"text_uthmani":"لَيْلًۭا","transliteration":"laylan","translation_bn":"রাতে","root":"ليل","lemma":"لَيْل","grammar_bn":"বিশেষ্য (Noun)"},{"id":77,"position":6,"text_uthmani":"مِّنَ","transliteration":"mina","translation_bn":"থেকে","root":"—","lemma":"مِن\r","grammar_bn":"অব্যয় (Preposition)"},{"id":78,"position":7,"text_uthmani":"ٱلْمَسْجِدِ","transliteration":"l-masjidi","translation_bn":"মাসজিদ","root":"سجد","lemma":"مَسْجِد","grammar_bn":"শব্দ"},{"id":79,"position":8,"text_uthmani":"ٱلْحَرَامِ","transliteration":"l-ḥarāmi","translation_bn":"হারাম","root":"حرم","lemma":"حَرَام","grammar_bn":"শব্দ"},{"id":80,"position":9,"text_uthmani":"إِلَى","transliteration":"ilā","translation_bn":"পর্যন্ত","root":"—","lemma":"إِلَىٰ\r","grammar_bn":"অব্যয় (Preposition)"},{"id":81,"position":10,"text_uthmani":"ٱلْمَسْجِدِ","transliteration":"l-masjidi","translation_bn":"মাসজিদ","root":"سجد","lemma":"مَسْجِد","grammar_bn":"শব্দ"},{"id":82,"position":11,"text_uthmani":"ٱلْأَقْصَا","transliteration":"l-aqṣā","translation_bn":"আকসা","root":"قصو","lemma":"أَقْصَا","grammar_bn":"শব্দ"},{"id":83,"position":12,"text_uthmani":"ٱلَّذِى","transliteration":"alladhī","translation_bn":"যা","root":"—","lemma":"ٱلَّذِى","grammar_bn":"সাপেক্ষ সর্বনাম (Relative)"},{"id":84,"position":13,"text_uthmani":"بَـٰرَكْنَا","transliteration":"bāraknā","translation_bn":"আমরা কল্যাণময় করেছি","root":"برك","lemma":"بَٰرَكَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":85,"position":14,"text_uthmani":"حَوْلَهُۥ","transliteration":"ḥawlahu","translation_bn":"তার আশ-পাশকে","root":"حول","lemma":"حَوْل","grammar_bn":"বিশেষ্য (Noun)"},{"id":86,"position":15,"text_uthmani":"لِنُرِيَهُۥ","transliteration":"linuriyahu","translation_bn":"যেন তাকে দেখাই আমরা","root":"راي","lemma":"أَرَيْ","grammar_bn":"শব্দ"},{"id":87,"position":16,"text_uthmani":"مِنْ","transliteration":"min","translation_bn":"কিছু","root":"—","lemma":"مِن\r","grammar_bn":"অব্যয় (Preposition)"},{"id":88,"position":17,"text_uthmani":"ءَايَـٰتِنَآ ۚ","transliteration":"āyātinā","translation_bn":"আমাদের নিদর্শনাবলীর","root":"ايي","lemma":"ءَايَة","grammar_bn":"বিশেষ্য (Noun)"},{"id":90,"position":18,"text_uthmani":"إِنَّهُۥ","transliteration":"innahu","translation_bn":"নিশ্চয়ই তিনি","root":"—","lemma":"إِنّ","grammar_bn":"অভিঘাত পদ (Accusative)"},{"id":91,"position":19,"text_uthmani":"هُوَ","transliteration":"huwa","translation_bn":"তিনিই","root":"—","lemma":"هُوَ","grammar_bn":"সর্বনাম (Pronoun)"},{"id":92,"position":20,"text_uthmani":"ٱلسَّمِيعُ","transliteration":"l-samīʿu","translation_bn":"সর্বশ্রোতা","root":"سمع","lemma":"سَمِيع","grammar_bn":"শব্দ"},{"id":93,"position":21,"text_uthmani":"ٱلْبَصِيرُ","transliteration":"l-baṣīru","translation_bn":"সর্বদ্রষ্টা","root":"بصر","lemma":"بَصِير","grammar_bn":"শব্দ"},{"id":94,"position":22,"text_uthmani":"١","transliteration":"","translation_bn":"(১)","root":"—","lemma":"١","grammar_bn":"মার্কার"}]'::jsonb, 'sub''ḥāna alladhī asrā biʿabdihi laylan mina l-masjidi l-ḥarāmi ilā l-masjidi l-aqṣā alladhī bāraknā ḥawlahu linuriyahu min āyātinā innahu huwa l-samīʿu l-baṣīru', 'পবিত্র ও মহীয়ান তিনি যিনি তাঁর বান্দাহকে রাতের বেলা ভ্রমণ করিয়েছেন মাসজিদুল হারাম থেকে মাসজিদুল আকসা পর্যন্ত, যার চারপাশকে আমি কল্যাণময় করেছি। তাকে আমার নিদর্শনাবলী দেখানোর জন্য, তিনি সর্বশ্রোতা, সর্বদ্রষ্টা।', 'Exalted is He who took His Servant by night from al-Masjid al-Haram to al-Masjid al-Aqsa, whose surroundings We have blessed, to show him of Our signs. Indeed, He is the Hearing, the Seeing.', 'পবিত্র ও মহীয়ান তিনি যিনি তাঁর বান্দাহকে রাতের বেলা ভ্রমণ করিয়েছেন মাসজিদুল হারাম থেকে মাসজিদুল আকসা পর্যন্ত, যার চারপাশকে আমি কল্যাণময় করেছি। তাকে আমার নিদর্শনাবলী দেখানোর জন্য, তিনি সর্বশ্রোতা, সর্বদ্রষ্টা।', 'Exalted is He who took His Servant by night from al-Masjid al-Haram to al-Masjid al-Aqsa, whose surroundings We have blessed, to show him of Our signs. Indeed, He is the Hearing, the Seeing.', NULL, NULL, NULL, NULL, NULL, 'https://everyayah.com/data/Alafasy_128kbps/017001.mp3', now()),
  (17, 2, '', '[{"id":919,"position":1,"text_uthmani":"وَءَاتَيْنَا","transliteration":"waātaynā","translation_bn":"এবং আমরা দিয়েছিলাম","root":"اتي","lemma":"ا^تَى","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":920,"position":2,"text_uthmani":"مُوسَى","transliteration":"mūsā","translation_bn":"মূসাকে","root":"—","lemma":"مُوسَىٰ","grammar_bn":"নামবাচক বিশেষ্য (Proper Noun)"},{"id":921,"position":3,"text_uthmani":"ٱلْكِتَـٰبَ","transliteration":"l-kitāba","translation_bn":"কিতাব","root":"كتب","lemma":"كِتَٰب","grammar_bn":"শব্দ"},{"id":922,"position":4,"text_uthmani":"وَجَعَلْنَـٰهُ","transliteration":"wajaʿalnāhu","translation_bn":"ও তাকে আমরা বানিয়েছিলাম","root":"جعل","lemma":"جَعَلَ","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":923,"position":5,"text_uthmani":"هُدًۭى","transliteration":"hudan","translation_bn":"পথ নির্দেশক","root":"هدي","lemma":"هُدًى","grammar_bn":"বিশেষ্য (Noun)"},{"id":924,"position":6,"text_uthmani":"لِّبَنِىٓ","transliteration":"libanī","translation_bn":"জন্যে বনী","root":"بني","lemma":"بُنَىّ","grammar_bn":"অব্যয় (Preposition)"},{"id":925,"position":7,"text_uthmani":"إِسْرَٰٓءِيلَ","transliteration":"is''rāīla","translation_bn":"ইসরাঈলদের","root":"—","lemma":"إِسْرَائِيل","grammar_bn":"নামবাচক বিশেষ্য (Proper Noun)"},{"id":926,"position":8,"text_uthmani":"أَلَّا","transliteration":"allā","translation_bn":"\"যে না","root":"—","lemma":"أَن\r","grammar_bn":"অধীনস্থ যোজক (Subordinating)"},{"id":927,"position":9,"text_uthmani":"تَتَّخِذُوا۟","transliteration":"tattakhidhū","translation_bn":"তোমরা গ্রহণ করো","root":"اخذ","lemma":"ٱتَّخَذَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":928,"position":10,"text_uthmani":"مِن","transliteration":"min","translation_bn":"ছাড়া","root":"—","lemma":"مِن\r","grammar_bn":"অব্যয় (Preposition)"},{"id":929,"position":11,"text_uthmani":"دُونِى","transliteration":"dūnī","translation_bn":"আমাকে","root":"دون","lemma":"دُون","grammar_bn":"বিশেষ্য (Noun)"},{"id":930,"position":12,"text_uthmani":"وَكِيلًۭا","transliteration":"wakīlan","translation_bn":"কর্মবিধায়ক\"","root":"وكل","lemma":"وَكِيل","grammar_bn":"বিশেষ্য (Noun)"},{"id":931,"position":13,"text_uthmani":"٢","transliteration":"","translation_bn":"(২)","root":"—","lemma":"٢","grammar_bn":"মার্কার"}]'::jsonb, 'waātaynā mūsā l-kitāba wajaʿalnāhu hudan libanī is''rāīla allā tattakhidhū min dūnī wakīlan', 'আর আমি মূসাকে কিতাব দিয়েছিলাম আর সেটাকে করেছিলাম ইসরাঈল বংশীয়দের জন্য সত্যপথের নির্দেশক। (তাতে নির্দেশ দিয়েছিলাম) যে, আমাকে ছাড়া অন্যকে কর্ম নিয়ন্তা গ্রহণ করো না।', 'And We gave Moses the Scripture and made it a guidance for the Children of Israel that you not take other than Me as Disposer of affairs,', 'আর আমি মূসাকে কিতাব দিয়েছিলাম আর সেটাকে করেছিলাম ইসরাঈল বংশীয়দের জন্য সত্যপথের নির্দেশক। (তাতে নির্দেশ দিয়েছিলাম) যে, আমাকে ছাড়া অন্যকে কর্ম নিয়ন্তা গ্রহণ করো না।', 'And We gave Moses the Scripture and made it a guidance for the Children of Israel that you not take other than Me as Disposer of affairs,', NULL, NULL, NULL, NULL, NULL, 'https://everyayah.com/data/Alafasy_128kbps/017002.mp3', now()),
