  (18, 1, '', '[{"id":145,"position":1,"text_uthmani":"ٱلْحَمْدُ","transliteration":"al-ḥamdu","translation_bn":"সকল প্রশংসা","root":"حمد","lemma":"حَمْد","grammar_bn":"শব্দ"},{"id":146,"position":2,"text_uthmani":"لِلَّهِ","transliteration":"lillahi","translation_bn":"জন্যে আল্লাহর","root":"اله","lemma":"ٱللَّه","grammar_bn":"অব্যয় (Preposition)"},{"id":147,"position":3,"text_uthmani":"ٱلَّذِىٓ","transliteration":"alladhī","translation_bn":"যিনি","root":"—","lemma":"ٱلَّذِى","grammar_bn":"সাপেক্ষ সর্বনাম (Relative)"},{"id":148,"position":4,"text_uthmani":"أَنزَلَ","transliteration":"anzala","translation_bn":"অবতীর্ণ করেছেন","root":"نزل","lemma":"أَنزَلَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":149,"position":5,"text_uthmani":"عَلَىٰ","transliteration":"ʿalā","translation_bn":"উপর","root":"—","lemma":"عَلَىٰ\r","grammar_bn":"অব্যয় (Preposition)"},{"id":150,"position":6,"text_uthmani":"عَبْدِهِ","transliteration":"ʿabdihi","translation_bn":"তাঁর দাসের","root":"عبد","lemma":"عَبْد","grammar_bn":"বিশেষ্য (Noun)"},{"id":151,"position":7,"text_uthmani":"ٱلْكِتَـٰبَ","transliteration":"l-kitāba","translation_bn":"এই গ্রন্থ","root":"كتب","lemma":"كِتَٰب","grammar_bn":"শব্দ"},{"id":152,"position":8,"text_uthmani":"وَلَمْ","transliteration":"walam","translation_bn":"এবং","root":"—","lemma":"لَم\r","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":153,"position":9,"text_uthmani":"يَجْعَل","transliteration":"yajʿal","translation_bn":"রাখেননি","root":"جعل","lemma":"جَعَلَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":154,"position":10,"text_uthmani":"لَّهُۥ","transliteration":"lahu","translation_bn":"জন্যে তার","root":"—","lemma":"لَّهُۥ","grammar_bn":"অব্যয় (Preposition)"},{"id":155,"position":11,"text_uthmani":"عِوَجَاۜ","transliteration":"ʿiwajā","translation_bn":"কোনো বক্রতা","root":"عوج","lemma":"عِوَج","grammar_bn":"বিশেষ্য (Noun)"},{"id":157,"position":12,"text_uthmani":"١","transliteration":"","translation_bn":"(১)","root":"—","lemma":"١","grammar_bn":"মার্কার"}]'::jsonb, 'al-ḥamdu lillahi alladhī anzala ʿalā ʿabdihi l-kitāba walam yajʿal lahu ʿiwajā', 'সকল প্রশংসা আল্লাহর জন্য যিনি তাঁর বান্দাদের প্রতি কিতাব নাযিল করেছেন, আর তাতে কোন বক্রতার অবকাশ রাখেননি।', '[All] praise is [due] to Allah, who has sent down upon His Servant the Book and has not made therein any deviance.', 'সকল প্রশংসা আল্লাহর জন্য যিনি তাঁর বান্দাদের প্রতি কিতাব নাযিল করেছেন, আর তাতে কোন বক্রতার অবকাশ রাখেননি।', '[All] praise is [due] to Allah, who has sent down upon His Servant the Book and has not made therein any deviance.', NULL, NULL, NULL, NULL, NULL, 'https://everyayah.com/data/Alafasy_128kbps/018001.mp3', now()),
  (18, 2, '', '[{"id":980,"position":1,"text_uthmani":"قَيِّمًۭا","transliteration":"qayyiman","translation_bn":"দৃঢ়ভাবে প্রতিষ্ঠিত","root":"قوم","lemma":"قَيِّم","grammar_bn":"বিশেষণ (Adjective)"},{"id":981,"position":2,"text_uthmani":"لِّيُنذِرَ","transliteration":"liyundhira","translation_bn":"জন্যে সতর্ক করার","root":"نذر","lemma":"أَنذَرَ","grammar_bn":"শব্দ"},{"id":982,"position":3,"text_uthmani":"بَأْسًۭا","transliteration":"basan","translation_bn":"শাস্তি (সম্পর্কে)","root":"باس","lemma":"بَأْس","grammar_bn":"বিশেষ্য (Noun)"},{"id":983,"position":4,"text_uthmani":"شَدِيدًۭا","transliteration":"shadīdan","translation_bn":"কঠিন","root":"شدد","lemma":"شَدِيد","grammar_bn":"বিশেষণ (Adjective)"},{"id":984,"position":5,"text_uthmani":"مِّن","transliteration":"min","translation_bn":"থেকে","root":"—","lemma":"مِن\r","grammar_bn":"অব্যয় (Preposition)"},{"id":985,"position":6,"text_uthmani":"لَّدُنْهُ","transliteration":"ladun''hu","translation_bn":"তাঁর পক্ষ","root":"لدن","lemma":"لَّدُن","grammar_bn":"বিশেষ্য (Noun)"},{"id":986,"position":7,"text_uthmani":"وَيُبَشِّرَ","transliteration":"wayubashira","translation_bn":"এবং সুসংবাদ দেয়","root":"بشر","lemma":"بُشِّرَ","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":987,"position":8,"text_uthmani":"ٱلْمُؤْمِنِينَ","transliteration":"l-mu''minīna","translation_bn":"মু''মিনদেরকে","root":"امن","lemma":"مُؤْمِن","grammar_bn":"শব্দ"},{"id":988,"position":9,"text_uthmani":"ٱلَّذِينَ","transliteration":"alladhīna","translation_bn":"যারা","root":"—","lemma":"ٱلَّذِى","grammar_bn":"সাপেক্ষ সর্বনাম (Relative)"},{"id":989,"position":10,"text_uthmani":"يَعْمَلُونَ","transliteration":"yaʿmalūna","translation_bn":"কাজ করে","root":"عمل","lemma":"عَمِلَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":990,"position":11,"text_uthmani":"ٱلصَّـٰلِحَـٰتِ","transliteration":"l-ṣāliḥāti","translation_bn":"সৎ","root":"صلح","lemma":"صَّٰلِحَٰت","grammar_bn":"শব্দ"},{"id":991,"position":12,"text_uthmani":"أَنَّ","transliteration":"anna","translation_bn":"যে","root":"—","lemma":"أَنّ","grammar_bn":"অভিঘাত পদ (Accusative)"},{"id":992,"position":13,"text_uthmani":"لَهُمْ","transliteration":"lahum","translation_bn":"জন্যে তাদের আছে","root":"—","lemma":"لَهُمْ","grammar_bn":"অব্যয় (Preposition)"},{"id":993,"position":14,"text_uthmani":"أَجْرًا","transliteration":"ajran","translation_bn":"পুরস্কার","root":"اجر","lemma":"أَجْر","grammar_bn":"বিশেষ্য (Noun)"},{"id":994,"position":15,"text_uthmani":"حَسَنًۭا","transliteration":"ḥasanan","translation_bn":"উত্তম","root":"حسن","lemma":"حَسَن","grammar_bn":"বিশেষণ (Adjective)"},{"id":995,"position":16,"text_uthmani":"٢","transliteration":"","translation_bn":"(২)","root":"—","lemma":"٢","grammar_bn":"মার্কার"}]'::jsonb, 'qayyiman liyundhira basan shadīdan min ladun''hu wayubashira l-mu''minīna alladhīna yaʿmalūna l-ṣāliḥāti anna lahum ajran ḥasanan', '(তিনি সেটাকে করেছেন) সত্য, স্পষ্ট ও অকাট্য তাঁর কঠিন শাস্তি সম্পর্কে সতর্ক করার জন্য। আর যারা সৎকাজ করে সেই মু’মিনদেরকে সুসংবাদ দেয়ার জন্য যে, তাদের জন্য আছে উত্তম প্রতিফল।', '[He has made it] straight, to warn of severe punishment from Him and to give good tidings to the believers who do righteous deeds that they will have a good reward', '(তিনি সেটাকে করেছেন) সত্য, স্পষ্ট ও অকাট্য তাঁর কঠিন শাস্তি সম্পর্কে সতর্ক করার জন্য। আর যারা সৎকাজ করে সেই মু’মিনদেরকে সুসংবাদ দেয়ার জন্য যে, তাদের জন্য আছে উত্তম প্রতিফল।', '[He has made it] straight, to warn of severe punishment from Him and to give good tidings to the believers who do righteous deeds that they will have a good reward', NULL, NULL, NULL, NULL, NULL, 'https://everyayah.com/data/Alafasy_128kbps/018002.mp3', now()),
  (18, 3, '', '[{"id":2072,"position":1,"text_uthmani":"مَّـٰكِثِينَ","transliteration":"mākithīna","translation_bn":"তারা বসবাসকারী (হবে)","root":"مكث","lemma":"مَّٰكِثِين","grammar_bn":"বিশেষ্য (Noun)"},{"id":2073,"position":2,"text_uthmani":"فِيهِ","transliteration":"fīhi","translation_bn":"মধ্যে তার","root":"—","lemma":"فِى\r","grammar_bn":"অব্যয় (Preposition)"},{"id":2074,"position":3,"text_uthmani":"أَبَدًۭا","transliteration":"abadan","translation_bn":"চিরকাল","root":"ابد","lemma":"أَبَدًا","grammar_bn":"কালবাচক (Time)"},{"id":2075,"position":4,"text_uthmani":"٣","transliteration":"","translation_bn":"(৩)","root":"—","lemma":"٣","grammar_bn":"মার্কার"}]'::jsonb, 'mākithīna fīhi abadan', 'তাতে তারা চিরকাল থাকবে।', 'In which they will remain forever', 'তাতে তারা চিরকাল থাকবে।', 'In which they will remain forever', NULL, NULL, NULL, NULL, NULL, 'https://everyayah.com/data/Alafasy_128kbps/018003.mp3', now()),
  (18, 4, '', '[{"id":3336,"position":1,"text_uthmani":"وَيُنذِرَ","transliteration":"wayundhira","translation_bn":"এবং সতর্ক করে","root":"نذر","lemma":"أَنذَرَ","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":3337,"position":2,"text_uthmani":"ٱلَّذِينَ","transliteration":"alladhīna","translation_bn":"(তাদেরকে) যারা","root":"—","lemma":"ٱلَّذِى","grammar_bn":"সাপেক্ষ সর্বনাম (Relative)"},{"id":3338,"position":3,"text_uthmani":"قَالُوا۟","transliteration":"qālū","translation_bn":"বলে","root":"قول","lemma":"قَالَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":3339,"position":4,"text_uthmani":"ٱتَّخَذَ","transliteration":"ittakhadha","translation_bn":"\"গ্রহণ করেছেন","root":"اخذ","lemma":"ٱتَّخَذَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":3340,"position":5,"text_uthmani":"ٱللَّهُ","transliteration":"l-lahu","translation_bn":"\"আল্লাহ","root":"اله","lemma":"ٱللَّه","grammar_bn":"নামবাচক বিশেষ্য (Proper Noun)"},{"id":3341,"position":6,"text_uthmani":"وَلَدًۭا","transliteration":"waladan","translation_bn":"সন্তান\"","root":"ولد","lemma":"وَلَد","grammar_bn":"বিশেষ্য (Noun)"},{"id":3342,"position":7,"text_uthmani":"٤","transliteration":"","translation_bn":"(৪)","root":"—","lemma":"٤","grammar_bn":"মার্কার"}]'::jsonb, 'wayundhira alladhīna qālū ittakhadha l-lahu waladan', 'আর তাদেরকে সতর্ক করার জন্য যারা বলে, ‘আল্লাহ পুত্র গ্রহণ করেছেন।’', 'And to warn those who say, "Allah has taken a son."', 'আর তাদেরকে সতর্ক করার জন্য যারা বলে, ‘আল্লাহ পুত্র গ্রহণ করেছেন।’', 'And to warn those who say, "Allah has taken a son."', NULL, NULL, NULL, NULL, NULL, 'https://everyayah.com/data/Alafasy_128kbps/018004.mp3', now()),
  (18, 5, '', '[{"id":4719,"position":1,"text_uthmani":"مَّا","transliteration":"mā","translation_bn":"নেই","root":"—","lemma":"مَا\r","grammar_bn":"না-বোধক (Negative)"},{"id":4720,"position":2,"text_uthmani":"لَهُم","transliteration":"lahum","translation_bn":"কাছে তাদের","root":"—","lemma":"لَهُم","grammar_bn":"অব্যয় (Preposition)"},{"id":4721,"position":3,"text_uthmani":"بِهِۦ","transliteration":"bihi","translation_bn":"সম্পর্কে সে","root":"—","lemma":"بِهِۦ","grammar_bn":"অব্যয় (Preposition)"},{"id":4722,"position":4,"text_uthmani":"مِنْ","transliteration":"min","translation_bn":"কোনো","root":"—","lemma":"مِن\r","grammar_bn":"অব্যয় (Preposition)"},{"id":4723,"position":5,"text_uthmani":"عِلْمٍۢ","transliteration":"ʿil''min","translation_bn":"জ্ঞান","root":"علم","lemma":"عِلْم","grammar_bn":"বিশেষ্য (Noun)"},{"id":4724,"position":6,"text_uthmani":"وَلَا","transliteration":"walā","translation_bn":"এবং না (আছে)","root":"—","lemma":"لَا\r","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":4725,"position":7,"text_uthmani":"لِـَٔابَآئِهِمْ ۚ","transliteration":"liābāihim","translation_bn":"কাছে পিতৃপুরুষদের তাদের","root":"ابو","lemma":"ا^بَاء","grammar_bn":"অব্যয় (Preposition)"},{"id":4727,"position":8,"text_uthmani":"كَبُرَتْ","transliteration":"kaburat","translation_bn":"সাংঘাতিক","root":"كبر","lemma":"كَبُرَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":4728,"position":9,"text_uthmani":"كَلِمَةًۭ","transliteration":"kalimatan","translation_bn":"কথা","root":"كلم","lemma":"كَلِمَة","grammar_bn":"বিশেষ্য (Noun)"},{"id":4729,"position":10,"text_uthmani":"تَخْرُجُ","transliteration":"takhruju","translation_bn":"তা বের হয়","root":"خرج","lemma":"خَرَجَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":4730,"position":11,"text_uthmani":"مِنْ","transliteration":"min","translation_bn":"থেকে","root":"—","lemma":"مِن\r","grammar_bn":"অব্যয় (Preposition)"},{"id":4731,"position":12,"text_uthmani":"أَفْوَٰهِهِمْ ۚ","transliteration":"afwāhihim","translation_bn":"মুখগুলোর তাদের","root":"فوه","lemma":"أَفْوَٰه","grammar_bn":"বিশেষ্য (Noun)"},{"id":4733,"position":13,"text_uthmani":"إِن","transliteration":"in","translation_bn":"না","root":"—","lemma":"إِن\r","grammar_bn":"না-বোধক (Negative)"},{"id":4734,"position":14,"text_uthmani":"يَقُولُونَ","transliteration":"yaqūlūna","translation_bn":"তারা বলে","root":"قول","lemma":"قَالَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":4735,"position":15,"text_uthmani":"إِلَّا","transliteration":"illā","translation_bn":"ছাড়া","root":"—","lemma":"إِلَّا\r","grammar_bn":"সীমাবদ্ধতা (Restriction)"},{"id":4736,"position":16,"text_uthmani":"كَذِبًۭا","transliteration":"kadhiban","translation_bn":"মিথ্যা","root":"كذب","lemma":"كَذِب","grammar_bn":"বিশেষ্য (Noun)"},{"id":4737,"position":17,"text_uthmani":"٥","transliteration":"","translation_bn":"(৫)","root":"—","lemma":"٥","grammar_bn":"মার্কার"}]'::jsonb, 'mā lahum bihi min ʿil''min walā liābāihim kaburat kalimatan takhruju min afwāhihim in yaqūlūna illā kadhiban', 'এ সম্পর্কে তাদের কোন জ্ঞান নেই, আর তাদের পিতৃ-পুরুষদেরও ছিল না। তাদের মুখ থেকে বের হয় বড়ই সাংঘাতিক কথা। তারা যা বলে তা মিথ্যে ছাড়া কিছুই নয়।', 'They have no knowledge of it, nor had their fathers. Grave is the word that comes out of their mouths; they speak not except a lie.', 'এ সম্পর্কে তাদের কোন জ্ঞান নেই, আর তাদের পিতৃ-পুরুষদেরও ছিল না। তাদের মুখ থেকে বের হয় বড়ই সাংঘাতিক কথা। তারা যা বলে তা মিথ্যে ছাড়া কিছুই নয়।', 'They have no knowledge of it, nor had their fathers. Grave is the word that comes out of their mouths; they speak not except a lie.', NULL, NULL, NULL, NULL, NULL, 'https://everyayah.com/data/Alafasy_128kbps/018005.mp3', now()),
  (18, 6, '', '[{"id":5987,"position":1,"text_uthmani":"فَلَعَلَّكَ","transliteration":"falaʿallaka","translation_bn":"তবে তুমি সম্ভবতঃ","root":"—","lemma":"لَعَلّ","grammar_bn":"শব্দ"},{"id":5988,"position":2,"text_uthmani":"بَـٰخِعٌۭ","transliteration":"bākhiʿun","translation_bn":"বিনাশকারী হবে","root":"بخع","lemma":"بَٰخِع","grammar_bn":"বিশেষ্য (Noun)"},{"id":5989,"position":3,"text_uthmani":"نَّفْسَكَ","transliteration":"nafsaka","translation_bn":"তোমার প্রাণ","root":"نفس","lemma":"نَفْس","grammar_bn":"বিশেষ্য (Noun)"},{"id":5990,"position":4,"text_uthmani":"عَلَىٰٓ","transliteration":"ʿalā","translation_bn":"থেকে থেকে","root":"—","lemma":"عَلَىٰ\r","grammar_bn":"অব্যয় (Preposition)"},{"id":5991,"position":5,"text_uthmani":"ءَاثَـٰرِهِمْ","transliteration":"āthārihim","translation_bn":"পিছনে তাদের","root":"اثر","lemma":"أَثَر","grammar_bn":"বিশেষ্য (Noun)"},{"id":5992,"position":6,"text_uthmani":"إِن","transliteration":"in","translation_bn":"যদি","root":"—","lemma":"إِن\r","grammar_bn":"শর্তবাচক (Conditional)"},{"id":5993,"position":7,"text_uthmani":"لَّمْ","transliteration":"lam","translation_bn":"না","root":"—","lemma":"لَم\r","grammar_bn":"না-বোধক (Negative)"},{"id":5994,"position":8,"text_uthmani":"يُؤْمِنُوا۟","transliteration":"yu''minū","translation_bn":"তারা ঈমান আনে","root":"امن","lemma":"ءَامَنَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":5995,"position":9,"text_uthmani":"بِهَـٰذَا","transliteration":"bihādhā","translation_bn":"উপর এই","root":"—","lemma":"هَٰذَا","grammar_bn":"অব্যয় (Preposition)"},{"id":5996,"position":10,"text_uthmani":"ٱلْحَدِيثِ","transliteration":"l-ḥadīthi","translation_bn":"কথার","root":"حدث","lemma":"حَدِيث","grammar_bn":"শব্দ"},{"id":5997,"position":11,"text_uthmani":"أَسَفًا","transliteration":"asafan","translation_bn":"দুঃখে","root":"اسف","lemma":"أَسَف","grammar_bn":"বিশেষ্য (Noun)"},{"id":5998,"position":12,"text_uthmani":"٦","transliteration":"","translation_bn":"(৬)","root":"—","lemma":"٦","grammar_bn":"মার্কার"}]'::jsonb, 'falaʿallaka bākhiʿun nafsaka ʿalā āthārihim in lam yu''minū bihādhā l-ḥadīthi asafan', 'তারা এ বাণীতে (কুরআনে) বিশ্বাস না করার কারণে মনে হচ্ছে (হে নাবী!) তুমি তার দুঃখে তোমার নিজের জান বিনাশ করে দেবে।', 'Then perhaps you would kill yourself through grief over them, [O Muhammad], if they do not believe in this message, [and] out of sorrow.', 'তারা এ বাণীতে (কুরআনে) বিশ্বাস না করার কারণে মনে হচ্ছে (হে নাবী!) তুমি তার দুঃখে তোমার নিজের জান বিনাশ করে দেবে।', 'Then perhaps you would kill yourself through grief over them, [O Muhammad], if they do not believe in this message, [and] out of sorrow.', NULL, NULL, NULL, NULL, NULL, 'https://everyayah.com/data/Alafasy_128kbps/018006.mp3', now()),
  (18, 7, '', '[{"id":7301,"position":1,"text_uthmani":"إِنَّا","transliteration":"innā","translation_bn":"নিশ্চয়ই আমরা","root":"—","lemma":"إِنّ","grammar_bn":"অভিঘাত পদ (Accusative)"},{"id":7302,"position":2,"text_uthmani":"جَعَلْنَا","transliteration":"jaʿalnā","translation_bn":"আমরা বানিয়েছি","root":"جعل","lemma":"جَعَلَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":7303,"position":3,"text_uthmani":"مَا","transliteration":"mā","translation_bn":"যা (আছে)","root":"—","lemma":"مَا\r","grammar_bn":"সাপেক্ষ সর্বনাম (Relative)"},{"id":7304,"position":4,"text_uthmani":"عَلَى","transliteration":"ʿalā","translation_bn":"উপর","root":"—","lemma":"عَلَىٰ\r","grammar_bn":"অব্যয় (Preposition)"},{"id":7305,"position":5,"text_uthmani":"ٱلْأَرْضِ","transliteration":"l-arḍi","translation_bn":"জমিনের","root":"ارض","lemma":"أَرْض","grammar_bn":"শব্দ"},{"id":7306,"position":6,"text_uthmani":"زِينَةًۭ","transliteration":"zīnatan","translation_bn":"শোভা","root":"زين","lemma":"زِينَة","grammar_bn":"বিশেষ্য (Noun)"},{"id":7307,"position":7,"text_uthmani":"لَّهَا","transliteration":"lahā","translation_bn":"জন্যে তার","root":"—","lemma":"لَّهَا","grammar_bn":"অব্যয় (Preposition)"},{"id":7308,"position":8,"text_uthmani":"لِنَبْلُوَهُمْ","transliteration":"linabluwahum","translation_bn":"যাতে পরীক্ষা করি আমরা তাদেরকে","root":"بلو","lemma":"بَلَوْ","grammar_bn":"শব্দ"},{"id":7309,"position":9,"text_uthmani":"أَيُّهُمْ","transliteration":"ayyuhum","translation_bn":"কে মধ্যে তাদের","root":"—","lemma":"أَىّ","grammar_bn":"প্রশ্নবোধক (Interrogative)"},{"id":7310,"position":10,"text_uthmani":"أَحْسَنُ","transliteration":"aḥsanu","translation_bn":"উত্তম","root":"حسن","lemma":"أَحْسَن","grammar_bn":"বিশেষ্য (Noun)"},{"id":7311,"position":11,"text_uthmani":"عَمَلًۭا","transliteration":"ʿamalan","translation_bn":"কাজে","root":"عمل","lemma":"عَمَل","grammar_bn":"বিশেষ্য (Noun)"},{"id":7312,"position":12,"text_uthmani":"٧","transliteration":"","translation_bn":"(৭)","root":"—","lemma":"٧","grammar_bn":"মার্কার"}]'::jsonb, 'innā jaʿalnā mā ʿalā l-arḍi zīnatan lahā linabluwahum ayyuhum aḥsanu ʿamalan', 'যমীনের উপর যা কিছু আছে আমি সেগুলোকে তার শোভা-সৌন্দর্য করেছি যাতে আমি মানুষকে পরীক্ষা করতে পারি যে, ‘আমালের ক্ষেত্রে কারা উত্তম।', 'Indeed, We have made that which is on the earth adornment for it that We may test them [as to] which of them is best in deed.', 'যমীনের উপর যা কিছু আছে আমি সেগুলোকে তার শোভা-সৌন্দর্য করেছি যাতে আমি মানুষকে পরীক্ষা করতে পারি যে, ‘আমালের ক্ষেত্রে কারা উত্তম।', 'Indeed, We have made that which is on the earth adornment for it that We may test them [as to] which of them is best in deed.', NULL, NULL, NULL, NULL, NULL, 'https://everyayah.com/data/Alafasy_128kbps/018007.mp3', now()),
  (18, 8, '', '[{"id":8571,"position":1,"text_uthmani":"وَإِنَّا","transliteration":"wa-innā","translation_bn":"এবং নিশ্চয়ই আমরা","root":"—","lemma":"إِنّ","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":8572,"position":2,"text_uthmani":"لَجَـٰعِلُونَ","transliteration":"lajāʿilūna","translation_bn":"অবশ্যই পরিণতকারী","root":"جعل","lemma":"جَاعِل","grammar_bn":"দৃঢ়তাবোধক (Emphatic)"},{"id":8573,"position":3,"text_uthmani":"مَا","transliteration":"mā","translation_bn":"যা আছে","root":"—","lemma":"مَا\r","grammar_bn":"সাপেক্ষ সর্বনাম (Relative)"},{"id":8574,"position":4,"text_uthmani":"عَلَيْهَا","transliteration":"ʿalayhā","translation_bn":"উপর তার","root":"—","lemma":"عَلَىٰ\r","grammar_bn":"অব্যয় (Preposition)"},{"id":8575,"position":5,"text_uthmani":"صَعِيدًۭا","transliteration":"ṣaʿīdan","translation_bn":"ভূমি","root":"صعد","lemma":"صَعِيد","grammar_bn":"বিশেষ্য (Noun)"},{"id":8576,"position":6,"text_uthmani":"جُرُزًا","transliteration":"juruzan","translation_bn":"বিরান","root":"جرز","lemma":"جُرُز","grammar_bn":"বিশেষণ (Adjective)"},{"id":8577,"position":7,"text_uthmani":"٨","transliteration":"","translation_bn":"(৮)","root":"—","lemma":"٨","grammar_bn":"মার্কার"}]'::jsonb, 'wa-innā lajāʿilūna mā ʿalayhā ṣaʿīdan juruzan', 'আমি অবশ্যই তার উপর যা আছে তা বৃক্ষলতাহীন শুকনো ধূলা মাটিতে পরিণত করব।', 'And indeed, We will make that which is upon it [into] a barren ground.', 'আমি অবশ্যই তার উপর যা আছে তা বৃক্ষলতাহীন শুকনো ধূলা মাটিতে পরিণত করব।', 'And indeed, We will make that which is upon it [into] a barren ground.', NULL, NULL, NULL, NULL, NULL, 'https://everyayah.com/data/Alafasy_128kbps/018008.mp3', now()),
  (18, 9, '', '[{"id":9785,"position":1,"text_uthmani":"أَمْ","transliteration":"am","translation_bn":"কি","root":"—","lemma":"أَم\r","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":9786,"position":2,"text_uthmani":"حَسِبْتَ","transliteration":"ḥasib''ta","translation_bn":"তুমি মনে করেছো","root":"حسب","lemma":"حَسِبَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":9787,"position":3,"text_uthmani":"أَنَّ","transliteration":"anna","translation_bn":"যে","root":"—","lemma":"أَنّ","grammar_bn":"অভিঘাত পদ (Accusative)"},{"id":9788,"position":4,"text_uthmani":"أَصْحَـٰبَ","transliteration":"aṣḥāba","translation_bn":"অধিবাসীরা","root":"صحب","lemma":"أَصْحَٰب","grammar_bn":"বিশেষ্য (Noun)"},{"id":9789,"position":5,"text_uthmani":"ٱلْكَهْفِ","transliteration":"l-kahfi","translation_bn":"গুহার","root":"كهف","lemma":"كَهْف","grammar_bn":"শব্দ"},{"id":9790,"position":6,"text_uthmani":"وَٱلرَّقِيمِ","transliteration":"wal-raqīmi","translation_bn":"ও রাকীমের","root":"رقم","lemma":"رَّقِيم","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":9791,"position":7,"text_uthmani":"كَانُوا۟","transliteration":"kānū","translation_bn":"ছিলো","root":"كون","lemma":"كَانَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":9792,"position":8,"text_uthmani":"مِنْ","transliteration":"min","translation_bn":"মধ্য থেকে","root":"—","lemma":"مِن\r","grammar_bn":"অব্যয় (Preposition)"},{"id":9793,"position":9,"text_uthmani":"ءَايَـٰتِنَا","transliteration":"āyātinā","translation_bn":"আমাদের নিদর্শনগুলোর","root":"ايي","lemma":"ءَايَة","grammar_bn":"বিশেষ্য (Noun)"},{"id":9794,"position":10,"text_uthmani":"عَجَبًا","transliteration":"ʿajaban","translation_bn":"আশ্চর্যজনক","root":"عجب","lemma":"عَجَب","grammar_bn":"বিশেষণ (Adjective)"},{"id":9795,"position":11,"text_uthmani":"٩","transliteration":"","translation_bn":"(৯)","root":"—","lemma":"٩","grammar_bn":"মার্কার"}]'::jsonb, 'am ḥasib''ta anna aṣḥāba l-kahfi wal-raqīmi kānū min āyātinā ʿajaban', 'তুমি কি মনে কর যে, গুহা ও রকীমের অধিবাসীরা ছিল আমার নিদর্শনগুলোর মধ্যে বিস্ময়কর?', 'Or have you thought that the companions of the cave and the inscription were, among Our signs, a wonder?', 'তুমি কি মনে কর যে, গুহা ও রকীমের অধিবাসীরা ছিল আমার নিদর্শনগুলোর মধ্যে বিস্ময়কর?', 'Or have you thought that the companions of the cave and the inscription were, among Our signs, a wonder?', NULL, NULL, NULL, NULL, NULL, 'https://everyayah.com/data/Alafasy_128kbps/018009.mp3', now()),
  (18, 10, '', '[{"id":10929,"position":1,"text_uthmani":"إِذْ","transliteration":"idh","translation_bn":"যখন","root":"—","lemma":"إِذ\r","grammar_bn":"কালবাচক (Time)"},{"id":10930,"position":2,"text_uthmani":"أَوَى","transliteration":"awā","translation_bn":"আশ্রয় নিয়েছিলো","root":"اوي","lemma":"أَوَى","grammar_bn":"ক্রিয়া (Verb)"},{"id":10931,"position":3,"text_uthmani":"ٱلْفِتْيَةُ","transliteration":"l-fit''yatu","translation_bn":"যুবকরা","root":"فتي","lemma":"فِتْيَة","grammar_bn":"শব্দ"},{"id":10932,"position":4,"text_uthmani":"إِلَى","transliteration":"ilā","translation_bn":"মধ্যে","root":"—","lemma":"إِلَىٰ\r","grammar_bn":"অব্যয় (Preposition)"},{"id":10933,"position":5,"text_uthmani":"ٱلْكَهْفِ","transliteration":"l-kahfi","translation_bn":"গুহার","root":"كهف","lemma":"كَهْف","grammar_bn":"শব্দ"},{"id":10934,"position":6,"text_uthmani":"فَقَالُوا۟","transliteration":"faqālū","translation_bn":"তখন তারা বলেছিলো","root":"قول","lemma":"قَالَ","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":10935,"position":7,"text_uthmani":"رَبَّنَآ","transliteration":"rabbanā","translation_bn":"\"হে আমাদের রব","root":"ربب","lemma":"رَبّ","grammar_bn":"বিশেষ্য (Noun)"},{"id":10936,"position":8,"text_uthmani":"ءَاتِنَا","transliteration":"ātinā","translation_bn":"আমাদের দাও","root":"اتي","lemma":"ا^تَى","grammar_bn":"ক্রিয়া (Verb)"},{"id":10937,"position":9,"text_uthmani":"مِن","transliteration":"min","translation_bn":"থেকে","root":"—","lemma":"مِن\r","grammar_bn":"অব্যয় (Preposition)"},{"id":10938,"position":10,"text_uthmani":"لَّدُنكَ","transliteration":"ladunka","translation_bn":"তোমার পক্ষ","root":"لدن","lemma":"لَّدُن","grammar_bn":"বিশেষ্য (Noun)"},{"id":10939,"position":11,"text_uthmani":"رَحْمَةًۭ","transliteration":"raḥmatan","translation_bn":"অনুগ্রহ","root":"رحم","lemma":"رَحْمَة","grammar_bn":"বিশেষ্য (Noun)"},{"id":10940,"position":12,"text_uthmani":"وَهَيِّئْ","transliteration":"wahayyi","translation_bn":"এবং ব্যবস্হা করে দাও","root":"هيا","lemma":"يُهَيِّئْ","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":10941,"position":13,"text_uthmani":"لَنَا","transliteration":"lanā","translation_bn":"জন্যে আমাদের","root":"—","lemma":"لَنَا","grammar_bn":"অব্যয় (Preposition)"},{"id":10942,"position":14,"text_uthmani":"مِنْ","transliteration":"min","translation_bn":"থেকে","root":"—","lemma":"مِن\r","grammar_bn":"অব্যয় (Preposition)"},{"id":10943,"position":15,"text_uthmani":"أَمْرِنَا","transliteration":"amrinā","translation_bn":"আমাদের কাজ","root":"امر","lemma":"أَمْر","grammar_bn":"বিশেষ্য (Noun)"},{"id":10944,"position":16,"text_uthmani":"رَشَدًۭا","transliteration":"rashadan","translation_bn":"সুষ্ঠ ভাবে\"","root":"رشد","lemma":"رَشَد","grammar_bn":"বিশেষ্য (Noun)"},{"id":10945,"position":17,"text_uthmani":"١٠","transliteration":"","translation_bn":"(১০)","root":"—","lemma":"١٠","grammar_bn":"মার্কার"}]'::jsonb, 'idh awā l-fit''yatu ilā l-kahfi faqālū rabbanā ātinā min ladunka raḥmatan wahayyi lanā min amrinā rashadan', 'যুবকরা যখন গুহায় আশ্রয় গ্রহণ করল তখন তারা বলল, ‘হে আমাদের প্রতিপালক! তুমি তোমার নিকট হতে আমাদেরকে রহমত দান কর আর আমাদের ব্যাপারটি সুষ্ঠুভাবে সম্পাদন কর।’', '[Mention] when the youths retreated to the cave and said, "Our Lord, grant us from Yourself mercy and prepare for us from our affair right guidance."', 'যুবকরা যখন গুহায় আশ্রয় গ্রহণ করল তখন তারা বলল, ‘হে আমাদের প্রতিপালক! তুমি তোমার নিকট হতে আমাদেরকে রহমত দান কর আর আমাদের ব্যাপারটি সুষ্ঠুভাবে সম্পাদন কর।’', '[Mention] when the youths retreated to the cave and said, "Our Lord, grant us from Yourself mercy and prepare for us from our affair right guidance."', NULL, NULL, NULL, NULL, NULL, 'https://everyayah.com/data/Alafasy_128kbps/018010.mp3', now()),
  (18, 11, '', '[{"id":12247,"position":1,"text_uthmani":"فَضَرَبْنَا","transliteration":"faḍarabnā","translation_bn":"অতঃপর আমরা (ঘুমের পর্দা) দিলাম","root":"ضرب","lemma":"ضَرَبَ","grammar_bn":"শব্দ"},{"id":12248,"position":2,"text_uthmani":"عَلَىٰٓ","transliteration":"ʿalā","translation_bn":"উপর","root":"—","lemma":"عَلَىٰ\r","grammar_bn":"অব্যয় (Preposition)"},{"id":12249,"position":3,"text_uthmani":"ءَاذَانِهِمْ","transliteration":"ādhānihim","translation_bn":"কানগুলোর তাদের","root":"اذن","lemma":"أُذُنٌ","grammar_bn":"বিশেষ্য (Noun)"},{"id":12250,"position":4,"text_uthmani":"فِى","transliteration":"fī","translation_bn":"মধ্যে","root":"—","lemma":"فِى\r","grammar_bn":"অব্যয় (Preposition)"},{"id":12251,"position":5,"text_uthmani":"ٱلْكَهْفِ","transliteration":"l-kahfi","translation_bn":"গুহার","root":"كهف","lemma":"كَهْف","grammar_bn":"শব্দ"},{"id":12252,"position":6,"text_uthmani":"سِنِينَ","transliteration":"sinīna","translation_bn":"বছর","root":"سنو","lemma":"سِنِين","grammar_bn":"বিশেষ্য (Noun)"},{"id":12253,"position":7,"text_uthmani":"عَدَدًۭا","transliteration":"ʿadadan","translation_bn":"কয়েক","root":"عدد","lemma":"عَدَد","grammar_bn":"বিশেষণ (Adjective)"},{"id":12254,"position":8,"text_uthmani":"١١","transliteration":"","translation_bn":"(১১)","root":"—","lemma":"١١","grammar_bn":"মার্কার"}]'::jsonb, 'faḍarabnā ʿalā ādhānihim fī l-kahfi sinīna ʿadadan', 'অতঃপর আমি তাদেরকে গুহায় ঘুমন্ত অবস্থায় কয়েক বছর রেখে দিলাম।', 'So We cast [a cover of sleep] over their ears within the cave for a number of years.', 'অতঃপর আমি তাদেরকে গুহায় ঘুমন্ত অবস্থায় কয়েক বছর রেখে দিলাম।', 'So We cast [a cover of sleep] over their ears within the cave for a number of years.', NULL, NULL, NULL, NULL, NULL, 'https://everyayah.com/data/Alafasy_128kbps/018011.mp3', now()),
  (18, 12, '', '[{"id":13593,"position":1,"text_uthmani":"ثُمَّ","transliteration":"thumma","translation_bn":"এরপর","root":"—","lemma":"ثُمّ\r","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":13594,"position":2,"text_uthmani":"بَعَثْنَـٰهُمْ","transliteration":"baʿathnāhum","translation_bn":"আমরা জাগালাম তাদের","root":"بعث","lemma":"بَعَثَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":13595,"position":3,"text_uthmani":"لِنَعْلَمَ","transliteration":"linaʿlama","translation_bn":"যেন আমরা জানি","root":"علم","lemma":"عَلِمَ","grammar_bn":"শব্দ"},{"id":13596,"position":4,"text_uthmani":"أَىُّ","transliteration":"ayyu","translation_bn":"কোনটি","root":"—","lemma":"أَىّ\r","grammar_bn":"প্রশ্নবোধক (Interrogative)"},{"id":13597,"position":5,"text_uthmani":"ٱلْحِزْبَيْنِ","transliteration":"l-ḥiz''bayni","translation_bn":"দু''দলের","root":"حزب","lemma":"حِزْب","grammar_bn":"শব্দ"},{"id":13598,"position":6,"text_uthmani":"أَحْصَىٰ","transliteration":"aḥṣā","translation_bn":"হিসাব করেছিলো (সঠিক)","root":"حصي","lemma":"أَحْصَىٰ2","grammar_bn":"বিশেষ্য (Noun)"},{"id":13599,"position":7,"text_uthmani":"لِمَا","transliteration":"limā","translation_bn":"জন্যে যা","root":"—","lemma":"مَا\r","grammar_bn":"অব্যয় (Preposition)"},{"id":13600,"position":8,"text_uthmani":"لَبِثُوٓا۟","transliteration":"labithū","translation_bn":"তারা অবস্থান করেছিলো","root":"لبث","lemma":"لَبِثَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":13601,"position":9,"text_uthmani":"أَمَدًۭا","transliteration":"amadan","translation_bn":"সময়কাল","root":"امد","lemma":"أَمَد","grammar_bn":"বিশেষ্য (Noun)"},{"id":13602,"position":10,"text_uthmani":"١٢","transliteration":"","translation_bn":"(১২)","root":"—","lemma":"١٢","grammar_bn":"মার্কার"}]'::jsonb, 'thumma baʿathnāhum linaʿlama ayyu l-ḥiz''bayni aḥṣā limā labithū amadan', 'পরে তাদেরকে জাগ্রত করলাম এটা জানার জন্য যে, (গুহাবাসীরা আর যাদের যুগে তারা জাগ্রত হয়েছিল সে যুগের লোকেরা এ) দু’টি দলের মধ্যে কোনটি তাদের অবস্থানকালের সঠিক হিসাব করতে পারে।', 'Then We awakened them that We might show which of the two factions was most precise in calculating what [extent] they had remained in time.', 'পরে তাদেরকে জাগ্রত করলাম এটা জানার জন্য যে, (গুহাবাসীরা আর যাদের যুগে তারা জাগ্রত হয়েছিল সে যুগের লোকেরা এ) দু’টি দলের মধ্যে কোনটি তাদের অবস্থানকালের সঠিক হিসাব করতে পারে।', 'Then We awakened them that We might show which of the two factions was most precise in calculating what [extent] they had remained in time.', NULL, NULL, NULL, NULL, NULL, 'https://everyayah.com/data/Alafasy_128kbps/018012.mp3', now()),
  (18, 13, '', '[{"id":14789,"position":1,"text_uthmani":"نَّحْنُ","transliteration":"naḥnu","translation_bn":"আমরা","root":"—","lemma":"نَّحْنُ","grammar_bn":"সর্বনাম (Pronoun)"},{"id":14790,"position":2,"text_uthmani":"نَقُصُّ","transliteration":"naquṣṣu","translation_bn":"বর্ণনা করছি","root":"قصص","lemma":"قَصَّ","grammar_bn":"ক্রিয়া (Verb)"},{"id":14791,"position":3,"text_uthmani":"عَلَيْكَ","transliteration":"ʿalayka","translation_bn":"কাছে তোমার","root":"—","lemma":"عَلَىٰ\r","grammar_bn":"অব্যয় (Preposition)"},{"id":14792,"position":4,"text_uthmani":"نَبَأَهُم","transliteration":"naba-ahum","translation_bn":"খবর তাদের","root":"نبا","lemma":"نَبَأ","grammar_bn":"বিশেষ্য (Noun)"},{"id":14793,"position":5,"text_uthmani":"بِٱلْحَقِّ ۚ","transliteration":"bil-ḥaqi","translation_bn":"ভাবে সঠিক","root":"حقق","lemma":"حَقّ","grammar_bn":"অব্যয় (Preposition)"},{"id":14795,"position":6,"text_uthmani":"إِنَّهُمْ","transliteration":"innahum","translation_bn":"নিশ্চয়ই তারা","root":"—","lemma":"إِنّ","grammar_bn":"অভিঘাত পদ (Accusative)"},{"id":14796,"position":7,"text_uthmani":"فِتْيَةٌ","transliteration":"fit''yatun","translation_bn":"যুবক (ছিলো)","root":"فتي","lemma":"فِتْيَة","grammar_bn":"বিশেষ্য (Noun)"},{"id":14797,"position":8,"text_uthmani":"ءَامَنُوا۟","transliteration":"āmanū","translation_bn":"ঈমান এনেছিলো","root":"امن","lemma":"ءَامَنَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":14798,"position":9,"text_uthmani":"بِرَبِّهِمْ","transliteration":"birabbihim","translation_bn":"উপর রবের তাদের","root":"ربب","lemma":"رَبّ","grammar_bn":"অব্যয় (Preposition)"},{"id":14799,"position":10,"text_uthmani":"وَزِدْنَـٰهُمْ","transliteration":"wazid''nāhum","translation_bn":"এবং আমরা বাড়িয়ে দিয়েছিলাম তাদের","root":"زيد","lemma":"زَادَ","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":14800,"position":11,"text_uthmani":"هُدًۭى","transliteration":"hudan","translation_bn":"পথের দিশা","root":"هدي","lemma":"هُدًى","grammar_bn":"বিশেষ্য (Noun)"},{"id":14801,"position":12,"text_uthmani":"١٣","transliteration":"","translation_bn":"(১৩)","root":"—","lemma":"١٣","grammar_bn":"মার্কার"}]'::jsonb, 'naḥnu naquṣṣu ʿalayka naba-ahum bil-ḥaqi innahum fit''yatun āmanū birabbihim wazid''nāhum hudan', 'আমি তাদের সঠিক বৃত্তান্ত তোমার কাছে বর্ণনা করছি। তারা ছিল কয়েকজন যুবক, তারা তাদের প্রতিপালকের উপর ঈমান এনেছিল আর আমি তাদের হিদায়াত (ঈমানী চেতনাকে) বৃদ্ধি করে দিয়েছিলাম।', 'It is We who relate to you, [O Muhammad], their story in truth. Indeed, they were youths who believed in their Lord, and We increased them in guidance.', 'আমি তাদের সঠিক বৃত্তান্ত তোমার কাছে বর্ণনা করছি। তারা ছিল কয়েকজন যুবক, তারা তাদের প্রতিপালকের উপর ঈমান এনেছিল আর আমি তাদের হিদায়াত (ঈমানী চেতনাকে) বৃদ্ধি করে দিয়েছিলাম।', 'It is We who relate to you, [O Muhammad], their story in truth. Indeed, they were youths who believed in their Lord, and We increased them in guidance.', NULL, NULL, NULL, NULL, NULL, 'https://everyayah.com/data/Alafasy_128kbps/018013.mp3', now()),
  (18, 14, '', '[{"id":15859,"position":1,"text_uthmani":"وَرَبَطْنَا","transliteration":"warabaṭnā","translation_bn":"এবং আমরা দৃঢ় করেছিলাম","root":"ربط","lemma":"رَّبَطْ","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":15860,"position":2,"text_uthmani":"عَلَىٰ","transliteration":"ʿalā","translation_bn":"উপর","root":"—","lemma":"عَلَىٰ\r","grammar_bn":"অব্যয় (Preposition)"},{"id":15861,"position":3,"text_uthmani":"قُلُوبِهِمْ","transliteration":"qulūbihim","translation_bn":"অন্তরগুলো তাদের","root":"قلب","lemma":"قَلْب","grammar_bn":"বিশেষ্য (Noun)"},{"id":15862,"position":4,"text_uthmani":"إِذْ","transliteration":"idh","translation_bn":"যখন","root":"—","lemma":"إِذ\r","grammar_bn":"কালবাচক (Time)"},{"id":15863,"position":5,"text_uthmani":"قَامُوا۟","transliteration":"qāmū","translation_bn":"তারা দাঁড়িয়েছিলো","root":"قوم","lemma":"قَامَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":15864,"position":6,"text_uthmani":"فَقَالُوا۟","transliteration":"faqālū","translation_bn":"তখন তারা বলেছিলো","root":"قول","lemma":"قَالَ","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":15865,"position":7,"text_uthmani":"رَبُّنَا","transliteration":"rabbunā","translation_bn":"\"আমাদের রব","root":"ربب","lemma":"رَبّ","grammar_bn":"বিশেষ্য (Noun)"},{"id":15866,"position":8,"text_uthmani":"رَبُّ","transliteration":"rabbu","translation_bn":"রব","root":"ربب","lemma":"رَبّ","grammar_bn":"বিশেষ্য (Noun)"},{"id":15867,"position":9,"text_uthmani":"ٱلسَّمَـٰوَٰتِ","transliteration":"l-samāwāti","translation_bn":"আকাশসমূহের","root":"سمو","lemma":"سَمَا^ء","grammar_bn":"শব্দ"},{"id":15868,"position":10,"text_uthmani":"وَٱلْأَرْضِ","transliteration":"wal-arḍi","translation_bn":"এবং পৃথিবীর","root":"ارض","lemma":"أَرْض","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":15869,"position":11,"text_uthmani":"لَن","transliteration":"lan","translation_bn":"কখনও না","root":"—","lemma":"لَن\r","grammar_bn":"না-বোধক (Negative)"},{"id":15870,"position":12,"text_uthmani":"نَّدْعُوَا۟","transliteration":"nadʿuwā","translation_bn":"আমরা ডাকবো","root":"دعو","lemma":"دَعَا","grammar_bn":"ক্রিয়া (Verb)"},{"id":15871,"position":13,"text_uthmani":"مِن","transliteration":"min","translation_bn":"ছাড়া","root":"—","lemma":"مِن\r","grammar_bn":"অব্যয় (Preposition)"},{"id":15872,"position":14,"text_uthmani":"دُونِهِۦٓ","transliteration":"dūnihi","translation_bn":"তাকে","root":"دون","lemma":"دُون","grammar_bn":"বিশেষ্য (Noun)"},{"id":15873,"position":15,"text_uthmani":"إِلَـٰهًۭا ۖ","transliteration":"ilāhan","translation_bn":"(অন্য) ইলাহকে","root":"اله","lemma":"إِلَٰه","grammar_bn":"বিশেষ্য (Noun)"},{"id":15875,"position":16,"text_uthmani":"لَّقَدْ","transliteration":"laqad","translation_bn":"নিশ্চয়ই (যদি করি)","root":"—","lemma":"قَد\r","grammar_bn":"দৃঢ়তাবোধক (Emphatic)"},{"id":15876,"position":17,"text_uthmani":"قُلْنَآ","transliteration":"qul''nā","translation_bn":"আমরা বলবো","root":"قول","lemma":"قَالَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":15877,"position":18,"text_uthmani":"إِذًۭا","transliteration":"idhan","translation_bn":"তাহ''লে","root":"—","lemma":"إِذًا\r","grammar_bn":"আশ্চর্যসূচক (Surprise)"},{"id":15878,"position":19,"text_uthmani":"شَطَطًا","transliteration":"shaṭaṭan","translation_bn":"গর্হিত (কথা)","root":"شطط","lemma":"شَطَط","grammar_bn":"বিশেষ্য (Noun)"},{"id":15879,"position":20,"text_uthmani":"١٤","transliteration":"","translation_bn":"(১৪)","root":"—","lemma":"١٤","grammar_bn":"মার্কার"}]'::jsonb, 'warabaṭnā ʿalā qulūbihim idh qāmū faqālū rabbunā rabbu l-samāwāti wal-arḍi lan nadʿuwā min dūnihi ilāhan laqad qul''nā idhan shaṭaṭan', 'আর তাদের দিল মযবুত করে দিয়েছিলাম যখন তারা (মুশরিক রাজা ও তার অনুসারীদের বিরুদ্ধে) দাঁড়িয়ে গেল তখন বলল, ‘আমাদের প্রতিপালক তো তিনিই যিনি আসমানসমূহ যমীনের প্রতিপালক। আমরা কক্ষনো তাঁকে ত্যাগ করে অন্য কোন ইলাহকে ডাকব না। যদি আমরা ডাকি তাহলে মহা অপরাধের কথাই বলা হবে।', 'And We made firm their hearts when they stood up and said, "Our Lord is the Lord of the heavens and the earth. Never will we invoke besides Him any deity. We would have certainly spoken, then, an excessive transgression.', 'আর তাদের দিল মযবুত করে দিয়েছিলাম যখন তারা (মুশরিক রাজা ও তার অনুসারীদের বিরুদ্ধে) দাঁড়িয়ে গেল তখন বলল, ‘আমাদের প্রতিপালক তো তিনিই যিনি আসমানসমূহ যমীনের প্রতিপালক। আমরা কক্ষনো তাঁকে ত্যাগ করে অন্য কোন ইলাহকে ডাকব না। যদি আমরা ডাকি তাহলে মহা অপরাধের কথাই বলা হবে।', 'And We made firm their hearts when they stood up and said, "Our Lord is the Lord of the heavens and the earth. Never will we invoke besides Him any deity. We would have certainly spoken, then, an excessive transgression.', NULL, NULL, NULL, NULL, NULL, 'https://everyayah.com/data/Alafasy_128kbps/018014.mp3', now()),
  (18, 15, '', '[{"id":16979,"position":1,"text_uthmani":"هَـٰٓؤُلَآءِ","transliteration":"hāulāi","translation_bn":"এসব","root":"—","lemma":"هَٰذَا","grammar_bn":"নির্দেশক সর্বনাম (Demonstrative)"},{"id":16980,"position":2,"text_uthmani":"قَوْمُنَا","transliteration":"qawmunā","translation_bn":"আমার স্বজাতির লোক","root":"قوم","lemma":"قَوْم","grammar_bn":"বিশেষ্য (Noun)"},{"id":16981,"position":3,"text_uthmani":"ٱتَّخَذُوا۟","transliteration":"ittakhadhū","translation_bn":"গ্রহণ করেছে","root":"اخذ","lemma":"ٱتَّخَذَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":16982,"position":4,"text_uthmani":"مِن","transliteration":"min","translation_bn":"ছাড়া","root":"—","lemma":"مِن\r","grammar_bn":"অব্যয় (Preposition)"},{"id":16983,"position":5,"text_uthmani":"دُونِهِۦٓ","transliteration":"dūnihi","translation_bn":"তাঁকে","root":"دون","lemma":"دُون","grammar_bn":"বিশেষ্য (Noun)"},{"id":16984,"position":6,"text_uthmani":"ءَالِهَةًۭ ۖ","transliteration":"ālihatan","translation_bn":"বহু উপাস্য","root":"اله","lemma":"إِلَٰه","grammar_bn":"বিশেষ্য (Noun)"},{"id":16986,"position":7,"text_uthmani":"لَّوْلَا","transliteration":"lawlā","translation_bn":"কেন না","root":"—","lemma":"لَوْلَا^\r","grammar_bn":"উৎসাহবাচক (Exhortation)"},{"id":16987,"position":8,"text_uthmani":"يَأْتُونَ","transliteration":"yatūna","translation_bn":"তারা আসে","root":"اتي","lemma":"أَتَى","grammar_bn":"ক্রিয়া (Verb)"},{"id":16988,"position":9,"text_uthmani":"عَلَيْهِم","transliteration":"ʿalayhim","translation_bn":"কাছে তাদের","root":"—","lemma":"عَلَىٰ\r","grammar_bn":"অব্যয় (Preposition)"},{"id":16989,"position":10,"text_uthmani":"بِسُلْطَـٰنٍۭ","transliteration":"bisul''ṭānin","translation_bn":"নিয়ে প্রমাণ","root":"سلط","lemma":"سُلْطَٰن","grammar_bn":"অব্যয় (Preposition)"},{"id":16990,"position":11,"text_uthmani":"بَيِّنٍۢ ۖ","transliteration":"bayyinin","translation_bn":"সুস্পষ্ট","root":"بين","lemma":"بَيِّن","grammar_bn":"বিশেষণ (Adjective)"},{"id":16992,"position":12,"text_uthmani":"فَمَنْ","transliteration":"faman","translation_bn":"অতঃপর কে","root":"—","lemma":"مَن\r","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":16993,"position":13,"text_uthmani":"أَظْلَمُ","transliteration":"aẓlamu","translation_bn":"অধিক সীমালঙ্ঘনকারী","root":"ظلم","lemma":"أَظْلَم","grammar_bn":"বিশেষ্য (Noun)"},{"id":16994,"position":14,"text_uthmani":"مِمَّنِ","transliteration":"mimmani","translation_bn":"তার চেয়ে যে","root":"—","lemma":"مِن\r","grammar_bn":"অব্যয় (Preposition)"},{"id":16995,"position":15,"text_uthmani":"ٱفْتَرَىٰ","transliteration":"if''tarā","translation_bn":"আরোপ করে","root":"فري","lemma":"ٱفْتَرَىٰ","grammar_bn":"ক্রিয়া (Verb)"},{"id":16996,"position":16,"text_uthmani":"عَلَى","transliteration":"ʿalā","translation_bn":"উপর","root":"—","lemma":"عَلَىٰ\r","grammar_bn":"অব্যয় (Preposition)"},{"id":16997,"position":17,"text_uthmani":"ٱللَّهِ","transliteration":"l-lahi","translation_bn":"আল্লাহ্‌র","root":"اله","lemma":"ٱللَّه","grammar_bn":"নামবাচক বিশেষ্য (Proper Noun)"},{"id":16998,"position":18,"text_uthmani":"كَذِبًۭا","transliteration":"kadhiban","translation_bn":"মিথ্যা","root":"كذب","lemma":"كَذِب","grammar_bn":"বিশেষ্য (Noun)"},{"id":16999,"position":19,"text_uthmani":"١٥","transliteration":"","translation_bn":"(১৫)","root":"—","lemma":"١٥","grammar_bn":"মার্কার"}]'::jsonb, 'hāulāi qawmunā ittakhadhū min dūnihi ālihatan lawlā yatūna ʿalayhim bisul''ṭānin bayyinin faman aẓlamu mimmani if''tarā ʿalā l-lahi kadhiban', 'আমাদের জাতির এই লোকেরা তাঁর পরিবর্তে বহু ইলাহ গ্রহণ করেছে, তারা তাদের ইলাহদের ব্যাপারে সুস্পষ্ট দলীল প্রমাণ পেশ করে না কেন? তার থেকে বড় যালিম আর কে হতে পারে যে আল্লাহ সম্পর্কে মিথ্যা রচনা করে?', 'These, our people, have taken besides Him deities. Why do they not bring for [worship of] them a clear authority? And who is more unjust than one who invents about Allah a lie?"', 'আমাদের জাতির এই লোকেরা তাঁর পরিবর্তে বহু ইলাহ গ্রহণ করেছে, তারা তাদের ইলাহদের ব্যাপারে সুস্পষ্ট দলীল প্রমাণ পেশ করে না কেন? তার থেকে বড় যালিম আর কে হতে পারে যে আল্লাহ সম্পর্কে মিথ্যা রচনা করে?', 'These, our people, have taken besides Him deities. Why do they not bring for [worship of] them a clear authority? And who is more unjust than one who invents about Allah a lie?"', NULL, NULL, NULL, NULL, NULL, 'https://everyayah.com/data/Alafasy_128kbps/018015.mp3', now()),
  (18, 16, '', '[{"id":18086,"position":1,"text_uthmani":"وَإِذِ","transliteration":"wa-idhi","translation_bn":"এবং যখন","root":"—","lemma":"إِذ\r","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":18087,"position":2,"text_uthmani":"ٱعْتَزَلْتُمُوهُمْ","transliteration":"iʿ''tazaltumūhum","translation_bn":"তোমরা বিচ্ছিন্ন হয়েছো তাদের (থেকে)","root":"عزل","lemma":"ٱعْتَزَلَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":18088,"position":3,"text_uthmani":"وَمَا","transliteration":"wamā","translation_bn":"এবং যাদের","root":"—","lemma":"مَا\r","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":18089,"position":4,"text_uthmani":"يَعْبُدُونَ","transliteration":"yaʿbudūna","translation_bn":"তারা উপাসনা করে","root":"عبد","lemma":"عَبَدَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":18090,"position":5,"text_uthmani":"إِلَّا","transliteration":"illā","translation_bn":"ছাড়া","root":"—","lemma":"إِلَّا\r","grammar_bn":"সীমাবদ্ধতা (Restriction)"},{"id":18091,"position":6,"text_uthmani":"ٱللَّهَ","transliteration":"l-laha","translation_bn":"আল্লাহ্‌র","root":"اله","lemma":"ٱللَّه","grammar_bn":"নামবাচক বিশেষ্য (Proper Noun)"},{"id":18092,"position":7,"text_uthmani":"فَأْوُۥٓا۟","transliteration":"fawū","translation_bn":"তাহ''লে আশ্রয় নাও","root":"اوي","lemma":"أَوَى","grammar_bn":"শব্দ"},{"id":18093,"position":8,"text_uthmani":"إِلَى","transliteration":"ilā","translation_bn":"মধ্যে","root":"—","lemma":"إِلَىٰ\r","grammar_bn":"অব্যয় (Preposition)"},{"id":18094,"position":9,"text_uthmani":"ٱلْكَهْفِ","transliteration":"l-kahfi","translation_bn":"গুহার","root":"كهف","lemma":"كَهْف","grammar_bn":"শব্দ"},{"id":18095,"position":10,"text_uthmani":"يَنشُرْ","transliteration":"yanshur","translation_bn":"প্রশস্ত করবেন","root":"نشر","lemma":"نُشِرَتْ","grammar_bn":"ক্রিয়া (Verb)"},{"id":18096,"position":11,"text_uthmani":"لَكُمْ","transliteration":"lakum","translation_bn":"জন্যে তোমাদের","root":"—","lemma":"لَكُمْ","grammar_bn":"অব্যয় (Preposition)"},{"id":18097,"position":12,"text_uthmani":"رَبُّكُم","transliteration":"rabbukum","translation_bn":"রব তোমাদের","root":"ربب","lemma":"رَبّ","grammar_bn":"বিশেষ্য (Noun)"},{"id":18098,"position":13,"text_uthmani":"مِّن","transliteration":"min","translation_bn":"সাহায্যে","root":"—","lemma":"مِن\r","grammar_bn":"অব্যয় (Preposition)"},{"id":18099,"position":14,"text_uthmani":"رَّحْمَتِهِۦ","transliteration":"raḥmatihi","translation_bn":"তাঁর অনুগ্রহের","root":"رحم","lemma":"رَحْمَة","grammar_bn":"বিশেষ্য (Noun)"},{"id":18100,"position":15,"text_uthmani":"وَيُهَيِّئْ","transliteration":"wayuhayyi","translation_bn":"এবং তৈরি করে দিবেন","root":"هيا","lemma":"يُهَيِّئْ","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":18101,"position":16,"text_uthmani":"لَكُم","transliteration":"lakum","translation_bn":"জন্যে তোমাদের","root":"—","lemma":"لَكُم","grammar_bn":"অব্যয় (Preposition)"},{"id":18102,"position":17,"text_uthmani":"مِّنْ","transliteration":"min","translation_bn":"থেকে","root":"—","lemma":"مِن\r","grammar_bn":"অব্যয় (Preposition)"},{"id":18103,"position":18,"text_uthmani":"أَمْرِكُم","transliteration":"amrikum","translation_bn":"কাজ তোমাদের","root":"امر","lemma":"أَمْر","grammar_bn":"বিশেষ্য (Noun)"},{"id":18104,"position":19,"text_uthmani":"مِّرْفَقًۭا","transliteration":"mir''faqan","translation_bn":"ফলপ্রসূ\"","root":"رفق","lemma":"مِّرْفَق","grammar_bn":"বিশেষ্য (Noun)"},{"id":18105,"position":20,"text_uthmani":"١٦","transliteration":"","translation_bn":"(১৬)","root":"—","lemma":"١٦","grammar_bn":"মার্কার"}]'::jsonb, 'wa-idhi iʿ''tazaltumūhum wamā yaʿbudūna illā l-laha fawū ilā l-kahfi yanshur lakum rabbukum min raḥmatihi wayuhayyi lakum min amrikum mir''faqan', 'এখন যেহেতু তোমরা তাদের থেকে আর তারা আল্লাহ ছাড়া যেগুলোর ‘ইবাদাত করে তাদের থেকে সম্পর্ক ছিন্ন করে নিয়েছ, তখন চল, গুহায় গিয়ে আশ্রয় গ্রহণ কর। তোমাদের জন্য তোমাদের প্রতিপালক তাঁর কল্যাণ বিস্তার করবেন আর তোমাদের কাজ-কর্মকে ফলদায়ক করে দেবেন।’', '[The youths said to one another], "And when you have withdrawn from them and that which they worship other than Allah, retreat to the cave. Your Lord will spread out for you of His mercy and will prepare for you from your affair facility."', 'এখন যেহেতু তোমরা তাদের থেকে আর তারা আল্লাহ ছাড়া যেগুলোর ‘ইবাদাত করে তাদের থেকে সম্পর্ক ছিন্ন করে নিয়েছ, তখন চল, গুহায় গিয়ে আশ্রয় গ্রহণ কর। তোমাদের জন্য তোমাদের প্রতিপালক তাঁর কল্যাণ বিস্তার করবেন আর তোমাদের কাজ-কর্মকে ফলদায়ক করে দেবেন।’', '[The youths said to one another], "And when you have withdrawn from them and that which they worship other than Allah, retreat to the cave. Your Lord will spread out for you of His mercy and will prepare for you from your affair facility."', NULL, NULL, NULL, NULL, NULL, 'https://everyayah.com/data/Alafasy_128kbps/018016.mp3', now()),
  (18, 17, '', '[{"id":19093,"position":1,"text_uthmani":"۞ وَتَرَى","transliteration":"watarā","translation_bn":"এবং তুমি দেখবে","root":"راي","lemma":"رَءَا","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":19094,"position":2,"text_uthmani":"ٱلشَّمْسَ","transliteration":"l-shamsa","translation_bn":"সূর্যকে","root":"شمس","lemma":"شَمْس","grammar_bn":"শব্দ"},{"id":19095,"position":3,"text_uthmani":"إِذَا","transliteration":"idhā","translation_bn":"যখন","root":"—","lemma":"إِذَا\r","grammar_bn":"কালবাচক (Time)"},{"id":19096,"position":4,"text_uthmani":"طَلَعَت","transliteration":"ṭalaʿat","translation_bn":"উদয় হয়","root":"طلع","lemma":"طَلَعَت","grammar_bn":"ক্রিয়া (Verb)"},{"id":19097,"position":5,"text_uthmani":"تَّزَٰوَرُ","transliteration":"tazāwaru","translation_bn":"সরে যায়","root":"زور","lemma":"تَّزَٰوَرُ","grammar_bn":"ক্রিয়া (Verb)"},{"id":19098,"position":6,"text_uthmani":"عَن","transliteration":"ʿan","translation_bn":"থেকে","root":"—","lemma":"عَن\r","grammar_bn":"অব্যয় (Preposition)"},{"id":19099,"position":7,"text_uthmani":"كَهْفِهِمْ","transliteration":"kahfihim","translation_bn":"গুহা তাদের","root":"كهف","lemma":"كَهْف","grammar_bn":"বিশেষ্য (Noun)"},{"id":19100,"position":8,"text_uthmani":"ذَاتَ","transliteration":"dhāta","translation_bn":"পাশ দিয়ে","root":"—","lemma":"ذُو","grammar_bn":"স্থানবাচক (Location)"},{"id":19101,"position":9,"text_uthmani":"ٱلْيَمِينِ","transliteration":"l-yamīni","translation_bn":"ডান","root":"يمن","lemma":"يَمِين","grammar_bn":"শব্দ"},{"id":19102,"position":10,"text_uthmani":"وَإِذَا","transliteration":"wa-idhā","translation_bn":"এবং যখন","root":"—","lemma":"إِذَا\r","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":19103,"position":11,"text_uthmani":"غَرَبَت","transliteration":"gharabat","translation_bn":"অস্ত যায়","root":"غرب","lemma":"غَرَبَت","grammar_bn":"ক্রিয়া (Verb)"},{"id":19104,"position":12,"text_uthmani":"تَّقْرِضُهُمْ","transliteration":"taqriḍuhum","translation_bn":"তা অতিক্রম করে তাদেরকে","root":"قرض","lemma":"تَّقْرِضُ","grammar_bn":"ক্রিয়া (Verb)"},{"id":19105,"position":13,"text_uthmani":"ذَاتَ","transliteration":"dhāta","translation_bn":"পাশ দিয়ে","root":"—","lemma":"ذُو","grammar_bn":"স্থানবাচক (Location)"},{"id":19106,"position":14,"text_uthmani":"ٱلشِّمَالِ","transliteration":"l-shimāli","translation_bn":"বাম","root":"شمل","lemma":"شِّمَال","grammar_bn":"শব্দ"},{"id":19107,"position":15,"text_uthmani":"وَهُمْ","transliteration":"wahum","translation_bn":"অথচ তারা","root":"—","lemma":"وَهُمْ","grammar_bn":"অবস্থাবাচক (Circumstantial)"},{"id":19108,"position":16,"text_uthmani":"فِى","transliteration":"fī","translation_bn":"মধ্যে","root":"—","lemma":"فِى\r","grammar_bn":"অব্যয় (Preposition)"},{"id":19109,"position":17,"text_uthmani":"فَجْوَةٍۢ","transliteration":"fajwatin","translation_bn":"প্রশস্ত চত্বরের","root":"فجو","lemma":"فَجْوَة","grammar_bn":"বিশেষ্য (Noun)"},{"id":19110,"position":18,"text_uthmani":"مِّنْهُ ۚ","transliteration":"min''hu","translation_bn":"থেকে তা","root":"—","lemma":"مِن\r","grammar_bn":"অব্যয় (Preposition)"},{"id":19112,"position":19,"text_uthmani":"ذَٰلِكَ","transliteration":"dhālika","translation_bn":"এটা","root":"—","lemma":"ذَٰلِك","grammar_bn":"নির্দেশক সর্বনাম (Demonstrative)"},{"id":19113,"position":20,"text_uthmani":"مِنْ","transliteration":"min","translation_bn":"মধ্য থেকে","root":"—","lemma":"مِن\r","grammar_bn":"অব্যয় (Preposition)"},{"id":19114,"position":21,"text_uthmani":"ءَايَـٰتِ","transliteration":"āyāti","translation_bn":"নিদর্শনাদির","root":"ايي","lemma":"ءَايَة","grammar_bn":"বিশেষ্য (Noun)"},{"id":19115,"position":22,"text_uthmani":"ٱللَّهِ ۗ","transliteration":"l-lahi","translation_bn":"আল্লাহ্‌র","root":"اله","lemma":"ٱللَّه","grammar_bn":"নামবাচক বিশেষ্য (Proper Noun)"},{"id":19117,"position":23,"text_uthmani":"مَن","transliteration":"man","translation_bn":"যাকে","root":"—","lemma":"مَن\r","grammar_bn":"সাপেক্ষ সর্বনাম (Relative)"},{"id":19118,"position":24,"text_uthmani":"يَهْدِ","transliteration":"yahdi","translation_bn":"পথ দেখান","root":"هدي","lemma":"هَدَى","grammar_bn":"ক্রিয়া (Verb)"},{"id":19119,"position":25,"text_uthmani":"ٱللَّهُ","transliteration":"l-lahu","translation_bn":"আল্লাহ্‌","root":"اله","lemma":"ٱللَّه","grammar_bn":"নামবাচক বিশেষ্য (Proper Noun)"},{"id":19120,"position":26,"text_uthmani":"فَهُوَ","transliteration":"fahuwa","translation_bn":"অতঃপর সেই","root":"—","lemma":"فَهُوَ","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":19121,"position":27,"text_uthmani":"ٱلْمُهْتَدِ ۖ","transliteration":"l-muh''tadi","translation_bn":"সঠিক পথপ্রাপ্ত","root":"هدي","lemma":"مُّهْتَد","grammar_bn":"শব্দ"},{"id":19123,"position":28,"text_uthmani":"وَمَن","transliteration":"waman","translation_bn":"এবং যাকে","root":"—","lemma":"مَن\r","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":19124,"position":29,"text_uthmani":"يُضْلِلْ","transliteration":"yuḍ''lil","translation_bn":"পথভ্রষ্ট করেন","root":"ضلل","lemma":"أَضَلَّ","grammar_bn":"ক্রিয়া (Verb)"},{"id":19125,"position":30,"text_uthmani":"فَلَن","transliteration":"falan","translation_bn":"তখন কখনও না","root":"—","lemma":"لَن\r","grammar_bn":"শব্দ"},{"id":19126,"position":31,"text_uthmani":"تَجِدَ","transliteration":"tajida","translation_bn":"তুমি পাবে","root":"وجد","lemma":"وَجَدَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":19127,"position":32,"text_uthmani":"لَهُۥ","transliteration":"lahu","translation_bn":"জন্যে তার","root":"—","lemma":"لَهُۥ","grammar_bn":"অব্যয় (Preposition)"},{"id":19128,"position":33,"text_uthmani":"وَلِيًّۭا","transliteration":"waliyyan","translation_bn":"কোনো অভিভাবক","root":"ولي","lemma":"وَلِىّ","grammar_bn":"বিশেষ্য (Noun)"},{"id":19129,"position":34,"text_uthmani":"مُّرْشِدًۭا","transliteration":"mur''shidan","translation_bn":"কোনো পথ প্রদর্শক","root":"رشد","lemma":"مُّرْشِد","grammar_bn":"বিশেষণ (Adjective)"},{"id":19130,"position":35,"text_uthmani":"١٧","transliteration":"","translation_bn":"(১৭)","root":"—","lemma":"١٧","grammar_bn":"মার্কার"}]'::jsonb, 'watarā l-shamsa idhā ṭalaʿat tazāwaru ʿan kahfihim dhāta l-yamīni wa-idhā gharabat taqriḍuhum dhāta l-shimāli wahum fī fajwatin min''hu dhālika min āyāti l-lahi man yahdi l-lahu fahuwa l-muh''tadi waman yuḍ''lil falan tajida lahu waliyyan mur''shidan', 'তুমি দেখতে পেতে সূর্য উদয়ের সময় তাদের গুহা হতে ডান দিকে হেলে যেত, আর যখন তা অস্তমিত হত তখন তা তাদের থেকে বাম দিকে নেমে যেত, আর তারা ছিল গুহার অভ্যন্তরে বিশাল চত্বরে। এ হচ্ছে আল্লাহর নিদর্শনসমূহের অন্যতম। আল্লাহ যাকে সৎপথ দেখান সে সঠিকপথপ্রাপ্ত আর যাকে তিনি পথহারা করেন, তার জন্য তুমি কক্ষনো সৎপথের দিশা দানকারী অভিভাবক পাবে না।', 'And [had you been present], you would see the sun when it rose, inclining away from their cave on the right, and when it set, passing away from them on the left, while they were [laying] within an open space thereof. That was from the signs of Allah. He whom Allah guides is the [rightly] guided, but he whom He leaves astray - never will you find for him a protecting guide.', 'তুমি দেখতে পেতে সূর্য উদয়ের সময় তাদের গুহা হতে ডান দিকে হেলে যেত, আর যখন তা অস্তমিত হত তখন তা তাদের থেকে বাম দিকে নেমে যেত, আর তারা ছিল গুহার অভ্যন্তরে বিশাল চত্বরে। এ হচ্ছে আল্লাহর নিদর্শনসমূহের অন্যতম। আল্লাহ যাকে সৎপথ দেখান সে সঠিকপথপ্রাপ্ত আর যাকে তিনি পথহারা করেন, তার জন্য তুমি কক্ষনো সৎপথের দিশা দানকারী অভিভাবক পাবে না।', 'And [had you been present], you would see the sun when it rose, inclining away from their cave on the right, and when it set, passing away from them on the left, while they were [laying] within an open space thereof. That was from the signs of Allah. He whom Allah guides is the [rightly] guided, but he whom He leaves astray - never will you find for him a protecting guide.', NULL, NULL, NULL, NULL, NULL, 'https://everyayah.com/data/Alafasy_128kbps/018017.mp3', now()),
  (18, 18, '', '[{"id":20218,"position":1,"text_uthmani":"وَتَحْسَبُهُمْ","transliteration":"wataḥsabuhum","translation_bn":"এবং তুমি মনে করবে তাদের","root":"حسب","lemma":"حَسِبَ","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":20219,"position":2,"text_uthmani":"أَيْقَاظًۭا","transliteration":"ayqāẓan","translation_bn":"জাগ্রত","root":"يقظ","lemma":"أَيْقَاظ","grammar_bn":"বিশেষ্য (Noun)"},{"id":20220,"position":3,"text_uthmani":"وَهُمْ","transliteration":"wahum","translation_bn":"অথচ তারা (ছিলো)","root":"—","lemma":"وَهُمْ","grammar_bn":"অবস্থাবাচক (Circumstantial)"},{"id":20221,"position":4,"text_uthmani":"رُقُودٌۭ ۚ","transliteration":"ruqūdun","translation_bn":"ঘুমন্ত","root":"رقد","lemma":"رُقُود","grammar_bn":"বিশেষ্য (Noun)"},{"id":20223,"position":5,"text_uthmani":"وَنُقَلِّبُهُمْ","transliteration":"wanuqallibuhum","translation_bn":"এবং পাশ ফেরাতাম আমরা তাদের","root":"قلب","lemma":"قَلَّبُ","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":20224,"position":6,"text_uthmani":"ذَاتَ","transliteration":"dhāta","translation_bn":"পাশে","root":"—","lemma":"ذُو","grammar_bn":"বিশেষ্য (Noun)"},{"id":20225,"position":7,"text_uthmani":"ٱلْيَمِينِ","transliteration":"l-yamīni","translation_bn":"ডান","root":"يمن","lemma":"يَمِين","grammar_bn":"শব্দ"},{"id":20226,"position":8,"text_uthmani":"وَذَاتَ","transliteration":"wadhāta","translation_bn":"ও পাশে","root":"—","lemma":"ذُو","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":20227,"position":9,"text_uthmani":"ٱلشِّمَالِ ۖ","transliteration":"l-shimāli","translation_bn":"বাম","root":"شمل","lemma":"شِّمَال","grammar_bn":"শব্দ"},{"id":20229,"position":10,"text_uthmani":"وَكَلْبُهُم","transliteration":"wakalbuhum","translation_bn":"এবং (ছিলো) তাদের কুকুর","root":"كلب","lemma":"كَلْب","grammar_bn":"অবস্থাবাচক (Circumstantial)"},{"id":20230,"position":11,"text_uthmani":"بَـٰسِطٌۭ","transliteration":"bāsiṭun","translation_bn":"প্রসারিতকারী","root":"بسط","lemma":"بَٰسِط","grammar_bn":"বিশেষ্য (Noun)"},{"id":20231,"position":12,"text_uthmani":"ذِرَاعَيْهِ","transliteration":"dhirāʿayhi","translation_bn":"তার সামনের দু''পা","root":"ذرع","lemma":"ذِرَاع","grammar_bn":"বিশেষ্য (Noun)"},{"id":20232,"position":13,"text_uthmani":"بِٱلْوَصِيدِ ۚ","transliteration":"bil-waṣīdi","translation_bn":"মধ্যে গর্তের মুখের","root":"وصد","lemma":"وَصِيد","grammar_bn":"অব্যয় (Preposition)"},{"id":20234,"position":14,"text_uthmani":"لَوِ","transliteration":"lawi","translation_bn":"যদি","root":"—","lemma":"لَو\r","grammar_bn":"শর্তবাচক (Conditional)"},{"id":20235,"position":15,"text_uthmani":"ٱطَّلَعْتَ","transliteration":"iṭṭalaʿta","translation_bn":"উঁকি মেরে দেখতে","root":"طلع","lemma":"طَّلَعَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":20236,"position":16,"text_uthmani":"عَلَيْهِمْ","transliteration":"ʿalayhim","translation_bn":"দিকে তাদের","root":"—","lemma":"عَلَىٰ\r","grammar_bn":"অব্যয় (Preposition)"},{"id":20237,"position":17,"text_uthmani":"لَوَلَّيْتَ","transliteration":"lawallayta","translation_bn":"অবশ্যই তুমি পিঠ ফিরাতে","root":"ولي","lemma":"وَلَّىٰ","grammar_bn":"দৃঢ়তাবোধক (Emphatic)"},{"id":20238,"position":18,"text_uthmani":"مِنْهُمْ","transliteration":"min''hum","translation_bn":"থেকে তাদের","root":"—","lemma":"مِن\r","grammar_bn":"অব্যয় (Preposition)"},{"id":20239,"position":19,"text_uthmani":"فِرَارًۭا","transliteration":"firāran","translation_bn":"পালিয়ে","root":"فرر","lemma":"فِرَار","grammar_bn":"বিশেষ্য (Noun)"},{"id":20240,"position":20,"text_uthmani":"وَلَمُلِئْتَ","transliteration":"walamuli''ta","translation_bn":"এবং অবশ্যই সঞ্চার হতো","root":"ملا","lemma":"مُلِئَتْ","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":20241,"position":21,"text_uthmani":"مِنْهُمْ","transliteration":"min''hum","translation_bn":"থেকে তাদের","root":"—","lemma":"مِن\r","grammar_bn":"অব্যয় (Preposition)"},{"id":20242,"position":22,"text_uthmani":"رُعْبًۭا","transliteration":"ruʿ''ban","translation_bn":"ভয়","root":"رعب","lemma":"رُعْب","grammar_bn":"বিশেষ্য (Noun)"},{"id":20243,"position":23,"text_uthmani":"١٨","transliteration":"","translation_bn":"(১৮)","root":"—","lemma":"١٨","grammar_bn":"মার্কার"}]'::jsonb, 'wataḥsabuhum ayqāẓan wahum ruqūdun wanuqallibuhum dhāta l-yamīni wadhāta l-shimāli wakalbuhum bāsiṭun dhirāʿayhi bil-waṣīdi lawi iṭṭalaʿta ʿalayhim lawallayta min''hum firāran walamuli''ta min''hum ruʿ''ban', 'তুমি মনে করবে যে তারা সজাগ, অথচ তারা ছিল ঘুমন্ত, আমি তাদের ডানে বামে পার্শ্ব পরিবর্তন করাতাম। আর তাদের কুকুরটি ছিল গুহাদ্বারের সম্মুখে তার সামনের পা দু’টি প্রসারিত করে। তুমি যদি তাদেরকে তাকিয়ে দেখতে তাহলে অবশ্যই পেছন ফিরে পালিয়ে যেতে, আর অবশ্যই তাদের ভয়ে আতঙ্কিত হয়ে পড়তে।', 'And you would think them awake, while they were asleep. And We turned them to the right and to the left, while their dog stretched his forelegs at the entrance. If you had looked at them, you would have turned from them in flight and been filled by them with terror.', 'তুমি মনে করবে যে তারা সজাগ, অথচ তারা ছিল ঘুমন্ত, আমি তাদের ডানে বামে পার্শ্ব পরিবর্তন করাতাম। আর তাদের কুকুরটি ছিল গুহাদ্বারের সম্মুখে তার সামনের পা দু’টি প্রসারিত করে। তুমি যদি তাদেরকে তাকিয়ে দেখতে তাহলে অবশ্যই পেছন ফিরে পালিয়ে যেতে, আর অবশ্যই তাদের ভয়ে আতঙ্কিত হয়ে পড়তে।', 'And you would think them awake, while they were asleep. And We turned them to the right and to the left, while their dog stretched his forelegs at the entrance. If you had looked at them, you would have turned from them in flight and been filled by them with terror.', NULL, NULL, NULL, NULL, NULL, 'https://everyayah.com/data/Alafasy_128kbps/018018.mp3', now()),
  (18, 19, '', '[{"id":21305,"position":1,"text_uthmani":"وَكَذَٰلِكَ","transliteration":"wakadhālika","translation_bn":"এবং এভাবেই","root":"—","lemma":"ذَٰلِك","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":21306,"position":2,"text_uthmani":"بَعَثْنَـٰهُمْ","transliteration":"baʿathnāhum","translation_bn":"আমরা উঠালাম তাদের","root":"بعث","lemma":"بَعَثَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":21307,"position":3,"text_uthmani":"لِيَتَسَآءَلُوا۟","transliteration":"liyatasāalū","translation_bn":"যেন তারা পরস্পরে জিজ্ঞেস করে","root":"سال","lemma":"يَتَسَا^ءَلُ","grammar_bn":"শব্দ"},{"id":21308,"position":4,"text_uthmani":"بَيْنَهُمْ ۚ","transliteration":"baynahum","translation_bn":"মাঝে তাদের","root":"بين","lemma":"بَيْن","grammar_bn":"স্থানবাচক (Location)"},{"id":21310,"position":5,"text_uthmani":"قَالَ","transliteration":"qāla","translation_bn":"বললো","root":"قول","lemma":"قَالَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":21311,"position":6,"text_uthmani":"قَآئِلٌۭ","transliteration":"qāilun","translation_bn":"একজন কথক","root":"قول","lemma":"قَا^ئِل","grammar_bn":"বিশেষ্য (Noun)"},{"id":21312,"position":7,"text_uthmani":"مِّنْهُمْ","transliteration":"min''hum","translation_bn":"মধ্য থেকে তাদের","root":"—","lemma":"مِن\r","grammar_bn":"অব্যয় (Preposition)"},{"id":21313,"position":8,"text_uthmani":"كَمْ","transliteration":"kam","translation_bn":"\"কত (দিন)","root":"—","lemma":"كَم\r","grammar_bn":"প্রশ্নবোধক (Interrogative)"},{"id":21314,"position":9,"text_uthmani":"لَبِثْتُمْ ۖ","transliteration":"labith''tum","translation_bn":"অবস্থান করেছিলে তোমরা\"","root":"لبث","lemma":"لَبِثَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":21316,"position":10,"text_uthmani":"قَالُوا۟","transliteration":"qālū","translation_bn":"তারা বলেছিলো","root":"قول","lemma":"قَالَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":21317,"position":11,"text_uthmani":"لَبِثْنَا","transliteration":"labith''nā","translation_bn":"\"অবস্থান করেছিলাম আমরা","root":"لبث","lemma":"لَبِثَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":21318,"position":12,"text_uthmani":"يَوْمًا","transliteration":"yawman","translation_bn":"একদিন","root":"يوم","lemma":"يَوْم","grammar_bn":"বিশেষ্য (Noun)"},{"id":21319,"position":13,"text_uthmani":"أَوْ","transliteration":"aw","translation_bn":"বা","root":"—","lemma":"أَو\r","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":21320,"position":14,"text_uthmani":"بَعْضَ","transliteration":"baʿḍa","translation_bn":"কিছু অংশ","root":"بعض","lemma":"بَعْض","grammar_bn":"বিশেষ্য (Noun)"},{"id":21321,"position":15,"text_uthmani":"يَوْمٍۢ ۚ","transliteration":"yawmin","translation_bn":"একদিনের\"","root":"يوم","lemma":"يَوْم","grammar_bn":"বিশেষ্য (Noun)"},{"id":21323,"position":16,"text_uthmani":"قَالُوا۟","transliteration":"qālū","translation_bn":"তারা বলেছিলো","root":"قول","lemma":"قَالَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":21324,"position":17,"text_uthmani":"رَبُّكُمْ","transliteration":"rabbukum","translation_bn":"\"রব তোমাদের","root":"ربب","lemma":"رَبّ","grammar_bn":"বিশেষ্য (Noun)"},{"id":21325,"position":18,"text_uthmani":"أَعْلَمُ","transliteration":"aʿlamu","translation_bn":"খুব জানেন","root":"علم","lemma":"أَعْلَم","grammar_bn":"বিশেষণ (Adjective)"},{"id":21326,"position":19,"text_uthmani":"بِمَا","transliteration":"bimā","translation_bn":"এ সম্বন্ধে যা","root":"—","lemma":"مَا\r","grammar_bn":"অব্যয় (Preposition)"},{"id":21327,"position":20,"text_uthmani":"لَبِثْتُمْ","transliteration":"labith''tum","translation_bn":"অবস্থান করেছো তোমরা","root":"لبث","lemma":"لَبِثَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":21328,"position":21,"text_uthmani":"فَٱبْعَثُوٓا۟","transliteration":"fa-ib''ʿathū","translation_bn":"তোমরা এখন পাঠাও","root":"بعث","lemma":"بَعَثَ","grammar_bn":"শব্দ"},{"id":21329,"position":22,"text_uthmani":"أَحَدَكُم","transliteration":"aḥadakum","translation_bn":"তোমাদের একজনকে","root":"احد","lemma":"أَحَد","grammar_bn":"বিশেষ্য (Noun)"},{"id":21330,"position":23,"text_uthmani":"بِوَرِقِكُمْ","transliteration":"biwariqikum","translation_bn":"দিয়ে তোমাদের মুদ্রা","root":"ورق","lemma":"وَرِق","grammar_bn":"অব্যয় (Preposition)"},{"id":21331,"position":24,"text_uthmani":"هَـٰذِهِۦٓ","transliteration":"hādhihi","translation_bn":"এই","root":"—","lemma":"هَٰذَا","grammar_bn":"নির্দেশক সর্বনাম (Demonstrative)"},{"id":21332,"position":25,"text_uthmani":"إِلَى","transliteration":"ilā","translation_bn":"দিকে","root":"—","lemma":"إِلَىٰ\r","grammar_bn":"অব্যয় (Preposition)"},{"id":21333,"position":26,"text_uthmani":"ٱلْمَدِينَةِ","transliteration":"l-madīnati","translation_bn":"শহরটির","root":"مدن","lemma":"مَدِينَة","grammar_bn":"শব্দ"},{"id":21334,"position":27,"text_uthmani":"فَلْيَنظُرْ","transliteration":"falyanẓur","translation_bn":"তবে সে যেন দেখে","root":"نظر","lemma":"نَّظَرَ","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":21335,"position":28,"text_uthmani":"أَيُّهَآ","transliteration":"ayyuhā","translation_bn":"কোনটি","root":"—","lemma":"أَيُّهَا","grammar_bn":"বিশেষ্য (Noun)"},{"id":21336,"position":29,"text_uthmani":"أَزْكَىٰ","transliteration":"azkā","translation_bn":"পবিত্রতম","root":"زكو","lemma":"أَزْكَىٰ","grammar_bn":"বিশেষ্য (Noun)"},{"id":21337,"position":30,"text_uthmani":"طَعَامًۭا","transliteration":"ṭaʿāman","translation_bn":"খাদ্য","root":"طعم","lemma":"طَعَام","grammar_bn":"বিশেষ্য (Noun)"},{"id":21338,"position":31,"text_uthmani":"فَلْيَأْتِكُم","transliteration":"falyatikum","translation_bn":"অতঃপর তোমাদের কাছে আসবে","root":"اتي","lemma":"أَتَى","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":21339,"position":32,"text_uthmani":"بِرِزْقٍۢ","transliteration":"biriz''qin","translation_bn":"নিয়ে খাদ্য","root":"رزق","lemma":"رِزْق","grammar_bn":"অব্যয় (Preposition)"},{"id":21340,"position":33,"text_uthmani":"مِّنْهُ","transliteration":"min''hu","translation_bn":"তা থেকে","root":"—","lemma":"مِن\r","grammar_bn":"অব্যয় (Preposition)"},{"id":21341,"position":34,"text_uthmani":"وَلْيَتَلَطَّفْ","transliteration":"walyatalaṭṭaf","translation_bn":"এবং সে যেন সতর্ক হয়","root":"لطف","lemma":"يَتَلَطَّفْ","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":21342,"position":35,"text_uthmani":"وَلَا","transliteration":"walā","translation_bn":"এবং না","root":"—","lemma":"لَا\r","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":21343,"position":36,"text_uthmani":"يُشْعِرَنَّ","transliteration":"yush''ʿiranna","translation_bn":"টের পেতে দেয়","root":"شعر","lemma":"يُشْعِرُ","grammar_bn":"ক্রিয়া (Verb)"},{"id":21344,"position":37,"text_uthmani":"بِكُمْ","transliteration":"bikum","translation_bn":"সম্বন্ধে তোমাদের","root":"—","lemma":"بِكُمْ","grammar_bn":"অব্যয় (Preposition)"},{"id":21345,"position":38,"text_uthmani":"أَحَدًا","transliteration":"aḥadan","translation_bn":"কাউকে\"","root":"احد","lemma":"أَحَد","grammar_bn":"বিশেষ্য (Noun)"},{"id":21346,"position":39,"text_uthmani":"١٩","transliteration":"","translation_bn":"(১৯)","root":"—","lemma":"١٩","grammar_bn":"মার্কার"}]'::jsonb, 'wakadhālika baʿathnāhum liyatasāalū baynahum qāla qāilun min''hum kam labith''tum qālū labith''nā yawman aw baʿḍa yawmin qālū rabbukum aʿlamu bimā labith''tum fa-ib''ʿathū aḥadakum biwariqikum hādhihi ilā l-madīnati falyanẓur ayyuhā azkā ṭaʿāman falyatikum biriz''qin min''hu walyatalaṭṭaf walā yush''ʿiranna bikum aḥadan', 'আর তাদের এই অবস্থায় আমি তাদেরকে জাগ্রত করলাম যাতে তারা পরস্পরকে জিজ্ঞাসাবাদ করে। তাদের একজন বলল, ‘তোমরা ক’দ্দিন থাকলে?’ তারা বলল, ‘আমরা একদিন কিংবা একদিনের কিছু অংশ হয়তো রয়েছি।’ (শেষে) তারা (সবাই) বলল, ‘তোমাদের প্রতিপালকই ভাল জানেন তোমরা কতকাল রয়েছ। এখন তোমাদের একজনকে তোমাদের এই মুদ্রা নিয়ে শহরে পাঠিয়ে দাও। সে যেন দেখে উত্তম খাবার কোনটি আর তাথেকে তোমাদের জন্য কিছু খাবার নিয়ে আসে। সে যেন বুদ্ধিমত্তার সঙ্গে কাজ করে, আর তোমাদের ব্যাপারে কেউ যেন কোনক্রমেই টের না পায়।', 'And similarly, We awakened them that they might question one another. Said a speaker from among them, "How long have you remained [here]?" They said, "We have remained a day or part of a day." They said, "Your Lord is most knowing of how long you remained. So send one of you with this silver coin of yours to the city and let him look to which is the best of food and bring you provision from it and let him be cautious. And let no one be aware of you.', 'আর তাদের এই অবস্থায় আমি তাদেরকে জাগ্রত করলাম যাতে তারা পরস্পরকে জিজ্ঞাসাবাদ করে। তাদের একজন বলল, ‘তোমরা ক’দ্দিন থাকলে?’ তারা বলল, ‘আমরা একদিন কিংবা একদিনের কিছু অংশ হয়তো রয়েছি।’ (শেষে) তারা (সবাই) বলল, ‘তোমাদের প্রতিপালকই ভাল জানেন তোমরা কতকাল রয়েছ। এখন তোমাদের একজনকে তোমাদের এই মুদ্রা নিয়ে শহরে পাঠিয়ে দাও। সে যেন দেখে উত্তম খাবার কোনটি আর তাথেকে তোমাদের জন্য কিছু খাবার নিয়ে আসে। সে যেন বুদ্ধিমত্তার সঙ্গে কাজ করে, আর তোমাদের ব্যাপারে কেউ যেন কোনক্রমেই টের না পায়।', 'And similarly, We awakened them that they might question one another. Said a speaker from among them, "How long have you remained [here]?" They said, "We have remained a day or part of a day." They said, "Your Lord is most knowing of how long you remained. So send one of you with this silver coin of yours to the city and let him look to which is the best of food and bring you provision from it and let him be cautious. And let no one be aware of you.', NULL, NULL, NULL, NULL, NULL, 'https://everyayah.com/data/Alafasy_128kbps/018019.mp3', now()),
  (18, 20, '', '[{"id":22387,"position":1,"text_uthmani":"إِنَّهُمْ","transliteration":"innahum","translation_bn":"\"নিশ্চয়ই তারা","root":"—","lemma":"إِنّ","grammar_bn":"অভিঘাত পদ (Accusative)"},{"id":22388,"position":2,"text_uthmani":"إِن","transliteration":"in","translation_bn":"যদি","root":"—","lemma":"إِن\r","grammar_bn":"শর্তবাচক (Conditional)"},{"id":22389,"position":3,"text_uthmani":"يَظْهَرُوا۟","transliteration":"yaẓharū","translation_bn":"তারা টের পায়","root":"ظهر","lemma":"ظَهَرَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":22390,"position":4,"text_uthmani":"عَلَيْكُمْ","transliteration":"ʿalaykum","translation_bn":"সম্পর্কে তোমাদের","root":"—","lemma":"عَلَىٰ\r","grammar_bn":"অব্যয় (Preposition)"},{"id":22391,"position":5,"text_uthmani":"يَرْجُمُوكُمْ","transliteration":"yarjumūkum","translation_bn":"পাথর মেরে হত্যা করবে তোমাদের","root":"رجم","lemma":"رَجَمْ","grammar_bn":"ক্রিয়া (Verb)"},{"id":22392,"position":6,"text_uthmani":"أَوْ","transliteration":"aw","translation_bn":"অথবা","root":"—","lemma":"أَو\r","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":22393,"position":7,"text_uthmani":"يُعِيدُوكُمْ","transliteration":"yuʿīdūkum","translation_bn":"ফিরিয়ে আনবে তোমাদের","root":"عود","lemma":"أُعِيدُ","grammar_bn":"ক্রিয়া (Verb)"},{"id":22394,"position":8,"text_uthmani":"فِى","transliteration":"fī","translation_bn":"মধ্যে","root":"—","lemma":"فِى\r","grammar_bn":"অব্যয় (Preposition)"},{"id":22395,"position":9,"text_uthmani":"مِلَّتِهِمْ","transliteration":"millatihim","translation_bn":"ধর্মের তাদের","root":"ملل","lemma":"مِلَّة","grammar_bn":"বিশেষ্য (Noun)"},{"id":22396,"position":10,"text_uthmani":"وَلَن","transliteration":"walan","translation_bn":"এবং কখনও না","root":"—","lemma":"لَن\r","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":22397,"position":11,"text_uthmani":"تُفْلِحُوٓا۟","transliteration":"tuf''liḥū","translation_bn":"তোমরা সফল হবে","root":"فلح","lemma":"أَفْلَحَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":22398,"position":12,"text_uthmani":"إِذًا","transliteration":"idhan","translation_bn":"তাহ''লে","root":"—","lemma":"إِذًا\r","grammar_bn":"উত্তর পদ (Answer)"},{"id":22399,"position":13,"text_uthmani":"أَبَدًۭا","transliteration":"abadan","translation_bn":"কখনও\"","root":"ابد","lemma":"أَبَدًا","grammar_bn":"কালবাচক (Time)"},{"id":22400,"position":14,"text_uthmani":"٢٠","transliteration":"","translation_bn":"(২০)","root":"—","lemma":"٢٠","grammar_bn":"মার্কার"}]'::jsonb, 'innahum in yaẓharū ʿalaykum yarjumūkum aw yuʿīdūkum fī millatihim walan tuf''liḥū idhan abadan', 'যদি তারা তোমাদের কথা জেনে ফেলে তাহলে তারা তোমাদেরকে পাথর মেরে হত্যা করবে কিংবা তোমাদেরকে তাদের ধর্মে ফিরিয়ে নিবে, সে অবস্থায় তোমরা কক্ষনো কল্যাণ লাভ করতে পারবে না।’', 'Indeed, if they come to know of you, they will stone you or return you to their religion. And never would you succeed, then - ever."', 'যদি তারা তোমাদের কথা জেনে ফেলে তাহলে তারা তোমাদেরকে পাথর মেরে হত্যা করবে কিংবা তোমাদেরকে তাদের ধর্মে ফিরিয়ে নিবে, সে অবস্থায় তোমরা কক্ষনো কল্যাণ লাভ করতে পারবে না।’', 'Indeed, if they come to know of you, they will stone you or return you to their religion. And never would you succeed, then - ever."', NULL, NULL, NULL, NULL, NULL, 'https://everyayah.com/data/Alafasy_128kbps/018020.mp3', now()),
  (18, 21, '', '[{"id":23497,"position":1,"text_uthmani":"وَكَذَٰلِكَ","transliteration":"wakadhālika","translation_bn":"এবং এভাবে","root":"—","lemma":"ذَٰلِك","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":23498,"position":2,"text_uthmani":"أَعْثَرْنَا","transliteration":"aʿtharnā","translation_bn":"আমরা জানিয়ে দিলাম","root":"عثر","lemma":"أَعْثَرْ","grammar_bn":"ক্রিয়া (Verb)"},{"id":23499,"position":3,"text_uthmani":"عَلَيْهِمْ","transliteration":"ʿalayhim","translation_bn":"সম্পর্কে তাদের","root":"—","lemma":"عَلَىٰ\r","grammar_bn":"অব্যয় (Preposition)"},{"id":23500,"position":4,"text_uthmani":"لِيَعْلَمُوٓا۟","transliteration":"liyaʿlamū","translation_bn":"যেন তারা জানে","root":"علم","lemma":"عَلِمَ","grammar_bn":"শব্দ"},{"id":23501,"position":5,"text_uthmani":"أَنَّ","transliteration":"anna","translation_bn":"যে","root":"—","lemma":"أَنّ","grammar_bn":"অভিঘাত পদ (Accusative)"},{"id":23502,"position":6,"text_uthmani":"وَعْدَ","transliteration":"waʿda","translation_bn":"প্রতিশ্রুতি","root":"وعد","lemma":"وَعْد","grammar_bn":"বিশেষ্য (Noun)"},{"id":23503,"position":7,"text_uthmani":"ٱللَّهِ","transliteration":"l-lahi","translation_bn":"আল্লাহ্‌র","root":"اله","lemma":"ٱللَّه","grammar_bn":"নামবাচক বিশেষ্য (Proper Noun)"},{"id":23504,"position":8,"text_uthmani":"حَقٌّۭ","transliteration":"ḥaqqun","translation_bn":"সত্য","root":"حقق","lemma":"حَقّ","grammar_bn":"বিশেষ্য (Noun)"},{"id":23505,"position":9,"text_uthmani":"وَأَنَّ","transliteration":"wa-anna","translation_bn":"এবং (এও) যে","root":"—","lemma":"أَنّ","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":23506,"position":10,"text_uthmani":"ٱلسَّاعَةَ","transliteration":"l-sāʿata","translation_bn":"ক্বিয়ামাত আসবেই","root":"سوع","lemma":"سَاعَة","grammar_bn":"শব্দ"},{"id":23507,"position":11,"text_uthmani":"لَا","transliteration":"lā","translation_bn":"নেই","root":"—","lemma":"لَا\r","grammar_bn":"না-বোধক (Negative)"},{"id":23508,"position":12,"text_uthmani":"رَيْبَ","transliteration":"rayba","translation_bn":"কোনো সন্দেহ","root":"ريب","lemma":"رَيْب","grammar_bn":"বিশেষ্য (Noun)"},{"id":23509,"position":13,"text_uthmani":"فِيهَآ","transliteration":"fīhā","translation_bn":"মধ্যে তার","root":"—","lemma":"فِى\r","grammar_bn":"অব্যয় (Preposition)"},{"id":23510,"position":14,"text_uthmani":"إِذْ","transliteration":"idh","translation_bn":"যখন","root":"—","lemma":"إِذ\r","grammar_bn":"কালবাচক (Time)"},{"id":23511,"position":15,"text_uthmani":"يَتَنَـٰزَعُونَ","transliteration":"yatanāzaʿūna","translation_bn":"তারা পরস্পরে বিতর্ক করছিলো","root":"نزع","lemma":"تَنَٰزَعُ","grammar_bn":"ক্রিয়া (Verb)"},{"id":23512,"position":16,"text_uthmani":"بَيْنَهُمْ","transliteration":"baynahum","translation_bn":"মাঝে তাদের","root":"بين","lemma":"بَيْن","grammar_bn":"স্থানবাচক (Location)"},{"id":23513,"position":17,"text_uthmani":"أَمْرَهُمْ ۖ","transliteration":"amrahum","translation_bn":"কাজে তাদের","root":"امر","lemma":"أَمْر","grammar_bn":"বিশেষ্য (Noun)"},{"id":23515,"position":18,"text_uthmani":"فَقَالُوا۟","transliteration":"faqālū","translation_bn":"তখন তারা বলেছিলো","root":"قول","lemma":"قَالَ","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":23516,"position":19,"text_uthmani":"ٱبْنُوا۟","transliteration":"ib''nū","translation_bn":"\"তোমরা নির্মাণ করো","root":"بني","lemma":"بَنَىٰ","grammar_bn":"ক্রিয়া (Verb)"},{"id":23517,"position":20,"text_uthmani":"عَلَيْهِم","transliteration":"ʿalayhim","translation_bn":"উপর তাদের","root":"—","lemma":"عَلَىٰ\r","grammar_bn":"অব্যয় (Preposition)"},{"id":23518,"position":21,"text_uthmani":"بُنْيَـٰنًۭا ۖ","transliteration":"bun''yānan","translation_bn":"সৌধ","root":"بني","lemma":"بُنْيَٰن","grammar_bn":"বিশেষ্য (Noun)"},{"id":23520,"position":22,"text_uthmani":"رَّبُّهُمْ","transliteration":"rabbuhum","translation_bn":"রব তাদের","root":"ربب","lemma":"رَبّ","grammar_bn":"বিশেষ্য (Noun)"},{"id":23521,"position":23,"text_uthmani":"أَعْلَمُ","transliteration":"aʿlamu","translation_bn":"ভালো জানেন","root":"علم","lemma":"أَعْلَم","grammar_bn":"বিশেষণ (Adjective)"},{"id":23522,"position":24,"text_uthmani":"بِهِمْ ۚ","transliteration":"bihim","translation_bn":"সম্বন্ধে তাদের\"","root":"—","lemma":"بِهِمْ ۚ","grammar_bn":"অব্যয় (Preposition)"},{"id":23524,"position":25,"text_uthmani":"قَالَ","transliteration":"qāla","translation_bn":"বললো","root":"قول","lemma":"قَالَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":23525,"position":26,"text_uthmani":"ٱلَّذِينَ","transliteration":"alladhīna","translation_bn":"যারা","root":"—","lemma":"ٱلَّذِى","grammar_bn":"সাপেক্ষ সর্বনাম (Relative)"},{"id":23526,"position":27,"text_uthmani":"غَلَبُوا۟","transliteration":"ghalabū","translation_bn":"প্রবল হয়েছিলো","root":"غلب","lemma":"غَلَبُ","grammar_bn":"ক্রিয়া (Verb)"},{"id":23527,"position":28,"text_uthmani":"عَلَىٰٓ","transliteration":"ʿalā","translation_bn":"উপর","root":"—","lemma":"عَلَىٰ\r","grammar_bn":"অব্যয় (Preposition)"},{"id":23528,"position":29,"text_uthmani":"أَمْرِهِمْ","transliteration":"amrihim","translation_bn":"তাদের মতের","root":"امر","lemma":"أَمْر","grammar_bn":"বিশেষ্য (Noun)"},{"id":23529,"position":30,"text_uthmani":"لَنَتَّخِذَنَّ","transliteration":"lanattakhidhanna","translation_bn":"\"অবশ্যই আমরা নির্মাণ করবো","root":"اخذ","lemma":"ٱتَّخَذَ","grammar_bn":"দৃঢ়তাবোধক (Emphatic)"},{"id":23530,"position":31,"text_uthmani":"عَلَيْهِم","transliteration":"ʿalayhim","translation_bn":"উপর তাদের","root":"—","lemma":"عَلَىٰ\r","grammar_bn":"অব্যয় (Preposition)"},{"id":23531,"position":32,"text_uthmani":"مَّسْجِدًۭا","transliteration":"masjidan","translation_bn":"মাসজিদ\"","root":"سجد","lemma":"مَسْجِد","grammar_bn":"বিশেষ্য (Noun)"},{"id":23532,"position":33,"text_uthmani":"٢١","transliteration":"","translation_bn":"(২১)","root":"—","lemma":"٢١","grammar_bn":"মার্কার"}]'::jsonb, 'wakadhālika aʿtharnā ʿalayhim liyaʿlamū anna waʿda l-lahi ḥaqqun wa-anna l-sāʿata lā rayba fīhā idh yatanāzaʿūna baynahum amrahum faqālū ib''nū ʿalayhim bun''yānan rabbuhum aʿlamu bihim qāla alladhīna ghalabū ʿalā amrihim lanattakhidhanna ʿalayhim masjidan', 'আমি এভাবে তাদের ব্যাপারটা লোকেদেরকে ওয়াকিফহাল করে দিলাম যাতে তারা জানতে পারে যে, আল্লাহর ওয়া‘দা সত্য, আর ক্বিয়ামাতের দিন সম্পর্কে কোন সন্দেহ নেই। যখন তারা (অর্থাৎ নগরবাসীরা) নিজেদের কর্তব্য সম্পর্কে নিজেদের মধ্যে বাদানুবাদ করছিল, (কতক) বলল, ‘তাদের উপর সৌধ নির্মাণ কর।’ তাদের প্রতিপালক তাদের সম্পর্কে ভাল জানেন। তাদের কর্তব্যকর্ম সম্পর্কে যাদের মতামত প্রাধান্য লাভ করল তারা বলল, ‘আমরা তাদের উপর অবশ্য অবশ্যই মাসজিদ নির্মাণ করব।’', 'And similarly, We caused them to be found that they [who found them] would know that the promise of Allah is truth and that of the Hour there is no doubt. [That was] when they disputed among themselves about their affair and [then] said, "Construct over them a structure. Their Lord is most knowing about them." Said those who prevailed in the matter, "We will surely take [for ourselves] over them a masjid."', 'আমি এভাবে তাদের ব্যাপারটা লোকেদেরকে ওয়াকিফহাল করে দিলাম যাতে তারা জানতে পারে যে, আল্লাহর ওয়া‘দা সত্য, আর ক্বিয়ামাতের দিন সম্পর্কে কোন সন্দেহ নেই। যখন তারা (অর্থাৎ নগরবাসীরা) নিজেদের কর্তব্য সম্পর্কে নিজেদের মধ্যে বাদানুবাদ করছিল, (কতক) বলল, ‘তাদের উপর সৌধ নির্মাণ কর।’ তাদের প্রতিপালক তাদের সম্পর্কে ভাল জানেন। তাদের কর্তব্যকর্ম সম্পর্কে যাদের মতামত প্রাধান্য লাভ করল তারা বলল, ‘আমরা তাদের উপর অবশ্য অবশ্যই মাসজিদ নির্মাণ করব।’', 'And similarly, We caused them to be found that they [who found them] would know that the promise of Allah is truth and that of the Hour there is no doubt. [That was] when they disputed among themselves about their affair and [then] said, "Construct over them a structure. Their Lord is most knowing about them." Said those who prevailed in the matter, "We will surely take [for ourselves] over them a masjid."', NULL, NULL, NULL, NULL, NULL, 'https://everyayah.com/data/Alafasy_128kbps/018021.mp3', now()),
  (18, 22, '', '[{"id":24531,"position":1,"text_uthmani":"سَيَقُولُونَ","transliteration":"sayaqūlūna","translation_bn":"তারা শীঘ্রই বলবে","root":"قول","lemma":"قَالَ","grammar_bn":"ভবিষ্যদ্বাচক (Future)"},{"id":24532,"position":2,"text_uthmani":"ثَلَـٰثَةٌۭ","transliteration":"thalāthatun","translation_bn":"তিন (তাদের সংখ্যা)","root":"ثلث","lemma":"ثَلَٰثَة","grammar_bn":"বিশেষ্য (Noun)"},{"id":24533,"position":3,"text_uthmani":"رَّابِعُهُمْ","transliteration":"rābiʿuhum","translation_bn":"চতুর্থটি (ছিলো) তাদের","root":"ربع","lemma":"رَابِع","grammar_bn":"বিশেষ্য (Noun)"},{"id":24534,"position":4,"text_uthmani":"كَلْبُهُمْ","transliteration":"kalbuhum","translation_bn":"কুকুর তাদের","root":"كلب","lemma":"كَلْب","grammar_bn":"বিশেষ্য (Noun)"},{"id":24535,"position":5,"text_uthmani":"وَيَقُولُونَ","transliteration":"wayaqūlūna","translation_bn":"এবং (কিছু লোক) বলবে","root":"قول","lemma":"قَالَ","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":24536,"position":6,"text_uthmani":"خَمْسَةٌۭ","transliteration":"khamsatun","translation_bn":"পাঁচ (জন)","root":"خمس","lemma":"خَمْسَة","grammar_bn":"বিশেষ্য (Noun)"},{"id":24537,"position":7,"text_uthmani":"سَادِسُهُمْ","transliteration":"sādisuhum","translation_bn":"ষষ্ঠটি তাদের","root":"سدس","lemma":"سَادِس","grammar_bn":"বিশেষ্য (Noun)"},{"id":24538,"position":8,"text_uthmani":"كَلْبُهُمْ","transliteration":"kalbuhum","translation_bn":"কুকুর তাদের","root":"كلب","lemma":"كَلْب","grammar_bn":"বিশেষ্য (Noun)"},{"id":24539,"position":9,"text_uthmani":"رَجْمًۢا","transliteration":"rajman","translation_bn":"আনুমানিক (কথা)","root":"رجم","lemma":"رَجْم","grammar_bn":"বিশেষ্য (Noun)"},{"id":24540,"position":10,"text_uthmani":"بِٱلْغَيْبِ ۖ","transliteration":"bil-ghaybi","translation_bn":"বিষয়ে অজানা","root":"غيب","lemma":"غَيْب","grammar_bn":"অব্যয় (Preposition)"},{"id":24542,"position":11,"text_uthmani":"وَيَقُولُونَ","transliteration":"wayaqūlūna","translation_bn":"এবং (কিছু লোক) বলবে","root":"قول","lemma":"قَالَ","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":24543,"position":12,"text_uthmani":"سَبْعَةٌۭ","transliteration":"sabʿatun","translation_bn":"সাত (তাদের সংখ্যা)","root":"سبع","lemma":"سَبْعَة","grammar_bn":"বিশেষ্য (Noun)"},{"id":24544,"position":13,"text_uthmani":"وَثَامِنُهُمْ","transliteration":"wathāminuhum","translation_bn":"এবং অষ্টমটি তাদের","root":"ثمن","lemma":"ثَامِن","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":24545,"position":14,"text_uthmani":"كَلْبُهُمْ ۚ","transliteration":"kalbuhum","translation_bn":"কুকুর তাদের","root":"كلب","lemma":"كَلْب","grammar_bn":"বিশেষ্য (Noun)"},{"id":24547,"position":15,"text_uthmani":"قُل","transliteration":"qul","translation_bn":"বলো","root":"قول","lemma":"قَالَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":24548,"position":16,"text_uthmani":"رَّبِّىٓ","transliteration":"rabbī","translation_bn":"\"আমার রব","root":"ربب","lemma":"رَبّ","grammar_bn":"বিশেষ্য (Noun)"},{"id":24549,"position":17,"text_uthmani":"أَعْلَمُ","transliteration":"aʿlamu","translation_bn":"ভালো জানেন","root":"علم","lemma":"أَعْلَم","grammar_bn":"বিশেষণ (Adjective)"},{"id":24550,"position":18,"text_uthmani":"بِعِدَّتِهِم","transliteration":"biʿiddatihim","translation_bn":"সম্পর্কে তাদের সংখ্যা","root":"عدد","lemma":"عِدَّة","grammar_bn":"অব্যয় (Preposition)"},{"id":24551,"position":19,"text_uthmani":"مَّا","transliteration":"mā","translation_bn":"না","root":"—","lemma":"مَا\r","grammar_bn":"সাপেক্ষ সর্বনাম (Relative)"},{"id":24552,"position":20,"text_uthmani":"يَعْلَمُهُمْ","transliteration":"yaʿlamuhum","translation_bn":"জানে তাদের","root":"علم","lemma":"عَلِمَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":24553,"position":21,"text_uthmani":"إِلَّا","transliteration":"illā","translation_bn":"ছাড়া","root":"—","lemma":"إِلَّا\r","grammar_bn":"সীমাবদ্ধতা (Restriction)"},{"id":24554,"position":22,"text_uthmani":"قَلِيلٌۭ ۗ","transliteration":"qalīlun","translation_bn":"অল্প (লোক)","root":"قلل","lemma":"قَلِيل","grammar_bn":"বিশেষ্য (Noun)"},{"id":24556,"position":23,"text_uthmani":"فَلَا","transliteration":"falā","translation_bn":"অতএব","root":"—","lemma":"لَا\r","grammar_bn":"শব্দ"},{"id":24557,"position":24,"text_uthmani":"تُمَارِ","transliteration":"tumāri","translation_bn":"বিতর্ক করো না","root":"مري","lemma":"تُمَارِ","grammar_bn":"ক্রিয়া (Verb)"},{"id":24558,"position":25,"text_uthmani":"فِيهِمْ","transliteration":"fīhim","translation_bn":"বিষয়ে তাদের","root":"—","lemma":"فِى\r","grammar_bn":"অব্যয় (Preposition)"},{"id":24559,"position":26,"text_uthmani":"إِلَّا","transliteration":"illā","translation_bn":"ছাড়া","root":"—","lemma":"إِلَّا\r","grammar_bn":"সীমাবদ্ধতা (Restriction)"},{"id":24560,"position":27,"text_uthmani":"مِرَآءًۭ","transliteration":"mirāan","translation_bn":"আলোচনা","root":"مري","lemma":"مِرَا^ء","grammar_bn":"বিশেষ্য (Noun)"},{"id":24561,"position":28,"text_uthmani":"ظَـٰهِرًۭا","transliteration":"ẓāhiran","translation_bn":"মামুলি","root":"ظهر","lemma":"ظَٰهِر","grammar_bn":"বিশেষ্য (Noun)"},{"id":24562,"position":29,"text_uthmani":"وَلَا","transliteration":"walā","translation_bn":"এবং না","root":"—","lemma":"لَا\r","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":24563,"position":30,"text_uthmani":"تَسْتَفْتِ","transliteration":"tastafti","translation_bn":"জিজ্ঞেস করবে তুমি","root":"فتي","lemma":"يَسْتَفْتُ","grammar_bn":"ক্রিয়া (Verb)"},{"id":24564,"position":31,"text_uthmani":"فِيهِم","transliteration":"fīhim","translation_bn":"বিষয়ে তাদের","root":"—","lemma":"فِى\r","grammar_bn":"অব্যয় (Preposition)"},{"id":24565,"position":32,"text_uthmani":"مِّنْهُمْ","transliteration":"min''hum","translation_bn":"মধ্য থেকে তাদের","root":"—","lemma":"مِن\r","grammar_bn":"অব্যয় (Preposition)"},{"id":24566,"position":33,"text_uthmani":"أَحَدًۭا","transliteration":"aḥadan","translation_bn":"কাউকে\"","root":"احد","lemma":"أَحَد","grammar_bn":"বিশেষ্য (Noun)"},{"id":24567,"position":34,"text_uthmani":"٢٢","transliteration":"","translation_bn":"(২২)","root":"—","lemma":"٢٢","grammar_bn":"মার্কার"}]'::jsonb, 'sayaqūlūna thalāthatun rābiʿuhum kalbuhum wayaqūlūna khamsatun sādisuhum kalbuhum rajman bil-ghaybi wayaqūlūna sabʿatun wathāminuhum kalbuhum qul rabbī aʿlamu biʿiddatihim mā yaʿlamuhum illā qalīlun falā tumāri fīhim illā mirāan ẓāhiran walā tastafti fīhim min''hum aḥadan', 'কতক লোক বলবে, ‘তারা ছিল তিনজন, তাদের চতুর্থটি ছিল তাদের কুকুর।’ আর কতক লোক বলবে, ‘তারা ছিল পাঁচ জন, তাদের ষষ্ঠটি ছিল তাদের কুকুর’, (এ কথা তারা বলবে) অজানা বিষয়ে সন্দেহপূর্ণ অনুমানের ভিত্তিতে। আবার তাদের কতক লোক বলবে, ‘তারা ছিল সাতজন, আর তাদের অষ্টমটি ছিল তাদের কুকুর।’ বল, ‘তাদের সংখ্যা সম্পর্কে আমার প্রতিপালকই বেশি জানেন।’ অল্প কয়জন ছাড়া তাদের সংখ্যা সম্পর্কে কেউ জানে না। কাজেই সাধারণ কথাবার্তা ছাড়া তাদের ব্যাপার নিয়ে বিতর্ক করো না, আর তাদের সম্পর্কে কারো কাছে কিছু জিজ্ঞেসও করো না।', 'They will say there were three, the fourth of them being their dog; and they will say there were five, the sixth of them being their dog - guessing at the unseen; and they will say there were seven, and the eighth of them was their dog. Say, [O Muhammad], "My Lord is most knowing of their number. None knows them except a few. So do not argue about them except with an obvious argument and do not inquire about them among [the speculators] from anyone."', 'কতক লোক বলবে, ‘তারা ছিল তিনজন, তাদের চতুর্থটি ছিল তাদের কুকুর।’ আর কতক লোক বলবে, ‘তারা ছিল পাঁচ জন, তাদের ষষ্ঠটি ছিল তাদের কুকুর’, (এ কথা তারা বলবে) অজানা বিষয়ে সন্দেহপূর্ণ অনুমানের ভিত্তিতে। আবার তাদের কতক লোক বলবে, ‘তারা ছিল সাতজন, আর তাদের অষ্টমটি ছিল তাদের কুকুর।’ বল, ‘তাদের সংখ্যা সম্পর্কে আমার প্রতিপালকই বেশি জানেন।’ অল্প কয়জন ছাড়া তাদের সংখ্যা সম্পর্কে কেউ জানে না। কাজেই সাধারণ কথাবার্তা ছাড়া তাদের ব্যাপার নিয়ে বিতর্ক করো না, আর তাদের সম্পর্কে কারো কাছে কিছু জিজ্ঞেসও করো না।', 'They will say there were three, the fourth of them being their dog; and they will say there were five, the sixth of them being their dog - guessing at the unseen; and they will say there were seven, and the eighth of them was their dog. Say, [O Muhammad], "My Lord is most knowing of their number. None knows them except a few. So do not argue about them except with an obvious argument and do not inquire about them among [the speculators] from anyone."', NULL, NULL, NULL, NULL, NULL, 'https://everyayah.com/data/Alafasy_128kbps/018022.mp3', now()),
  (18, 23, '', '[{"id":25631,"position":1,"text_uthmani":"وَلَا","transliteration":"walā","translation_bn":"এবং না","root":"—","lemma":"لَا\r","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":25632,"position":2,"text_uthmani":"تَقُولَنَّ","transliteration":"taqūlanna","translation_bn":"বলবে কখনও","root":"قول","lemma":"قَالَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":25633,"position":3,"text_uthmani":"لِشَا۟ىْءٍ","transliteration":"lishāy''in","translation_bn":"কোনো কিছুকে","root":"شيا","lemma":"شَىْء","grammar_bn":"অব্যয় (Preposition)"},{"id":25634,"position":4,"text_uthmani":"إِنِّى","transliteration":"innī","translation_bn":"\"নিশ্চয়ই আমি","root":"—","lemma":"إِنّ","grammar_bn":"অভিঘাত পদ (Accusative)"},{"id":25635,"position":5,"text_uthmani":"فَاعِلٌۭ","transliteration":"fāʿilun","translation_bn":"সম্পাদনকারী","root":"فعل","lemma":"فَاعِل","grammar_bn":"বিশেষ্য (Noun)"},{"id":25636,"position":6,"text_uthmani":"ذَٰلِكَ","transliteration":"dhālika","translation_bn":"এটা","root":"—","lemma":"ذَٰلِك","grammar_bn":"নির্দেশক সর্বনাম (Demonstrative)"},{"id":25637,"position":7,"text_uthmani":"غَدًا","transliteration":"ghadan","translation_bn":"আগামীকাল\"","root":"غدو","lemma":"غَد","grammar_bn":"বিশেষ্য (Noun)"},{"id":25638,"position":8,"text_uthmani":"٢٣","transliteration":"","translation_bn":"(২৩)","root":"—","lemma":"٢٣","grammar_bn":"মার্কার"}]'::jsonb, 'walā taqūlanna lishāy''in innī fāʿilun dhālika ghadan', 'কোন বিষয় সম্পর্কে কক্ষনো বল না যে, ‘ওটা আমি আগামীকাল করব।’', 'And never say of anything, "Indeed, I will do that tomorrow,"', 'কোন বিষয় সম্পর্কে কক্ষনো বল না যে, ‘ওটা আমি আগামীকাল করব।’', 'And never say of anything, "Indeed, I will do that tomorrow,"', NULL, NULL, NULL, NULL, NULL, 'https://everyayah.com/data/Alafasy_128kbps/018023.mp3', now()),
  (18, 24, '', '[{"id":26689,"position":1,"text_uthmani":"إِلَّآ","transliteration":"illā","translation_bn":"ছাড়া","root":"—","lemma":"إِلَّا\r","grammar_bn":"সীমাবদ্ধতা (Restriction)"},{"id":26690,"position":2,"text_uthmani":"أَن","transliteration":"an","translation_bn":"\"যে","root":"—","lemma":"أَن\r","grammar_bn":"অধীনস্থ যোজক (Subordinating)"},{"id":26691,"position":3,"text_uthmani":"يَشَآءَ","transliteration":"yashāa","translation_bn":"ইচ্ছে করেন\"","root":"شيا","lemma":"شَا^ءَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":26692,"position":4,"text_uthmani":"ٱللَّهُ ۚ","transliteration":"l-lahu","translation_bn":"আল্লাহ্‌\"","root":"اله","lemma":"ٱللَّه","grammar_bn":"নামবাচক বিশেষ্য (Proper Noun)"},{"id":26694,"position":5,"text_uthmani":"وَٱذْكُر","transliteration":"wa-udh''kur","translation_bn":"এবং স্মরণ করো","root":"ذكر","lemma":"ذَكَرَ","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":26695,"position":6,"text_uthmani":"رَّبَّكَ","transliteration":"rabbaka","translation_bn":"তোমার রবকে","root":"ربب","lemma":"رَبّ","grammar_bn":"বিশেষ্য (Noun)"},{"id":26696,"position":7,"text_uthmani":"إِذَا","transliteration":"idhā","translation_bn":"যদি","root":"—","lemma":"إِذَا\r","grammar_bn":"কালবাচক (Time)"},{"id":26697,"position":8,"text_uthmani":"نَسِيتَ","transliteration":"nasīta","translation_bn":"তুমি ভুলে যাও","root":"نسي","lemma":"نَسِىَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":26698,"position":9,"text_uthmani":"وَقُلْ","transliteration":"waqul","translation_bn":"এবং বলো","root":"قول","lemma":"قَالَ","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":26699,"position":10,"text_uthmani":"عَسَىٰٓ","transliteration":"ʿasā","translation_bn":"\"সম্ভবতঃ","root":"عسي","lemma":"عَسَى","grammar_bn":"ক্রিয়া (Verb)"},{"id":26700,"position":11,"text_uthmani":"أَن","transliteration":"an","translation_bn":"যে","root":"—","lemma":"أَن\r","grammar_bn":"অধীনস্থ যোজক (Subordinating)"},{"id":26701,"position":12,"text_uthmani":"يَهْدِيَنِ","transliteration":"yahdiyani","translation_bn":"আমাকে পথ দেখাবেন","root":"هدي","lemma":"هَدَى","grammar_bn":"ক্রিয়া (Verb)"},{"id":26702,"position":13,"text_uthmani":"رَبِّى","transliteration":"rabbī","translation_bn":"আমার রব","root":"ربب","lemma":"رَبّ","grammar_bn":"বিশেষ্য (Noun)"},{"id":26703,"position":14,"text_uthmani":"لِأَقْرَبَ","transliteration":"li-aqraba","translation_bn":"নিকটবর্তী (কথা)","root":"قرب","lemma":"أَقْرَب","grammar_bn":"অব্যয় (Preposition)"},{"id":26704,"position":15,"text_uthmani":"مِنْ","transliteration":"min","translation_bn":"চেয়ে","root":"—","lemma":"مِن\r","grammar_bn":"অব্যয় (Preposition)"},{"id":26705,"position":16,"text_uthmani":"هَـٰذَا","transliteration":"hādhā","translation_bn":"এটার","root":"—","lemma":"هَٰذَا","grammar_bn":"নির্দেশক সর্বনাম (Demonstrative)"},{"id":26706,"position":17,"text_uthmani":"رَشَدًۭا","transliteration":"rashadan","translation_bn":"সত্যের\"","root":"رشد","lemma":"رَشَد","grammar_bn":"বিশেষ্য (Noun)"},{"id":26707,"position":18,"text_uthmani":"٢٤","transliteration":"","translation_bn":"(২৪)","root":"—","lemma":"٢٤","grammar_bn":"মার্কার"}]'::jsonb, 'illā an yashāa l-lahu wa-udh''kur rabbaka idhā nasīta waqul ʿasā an yahdiyani rabbī li-aqraba min hādhā rashadan', '‘আল্লাহ ইচ্ছে করলে’ বলা ছাড়া। যদি ভুলে যাও (তবে মনে পড়ার সঙ্গে সঙ্গে) তোমার প্রতিপালককে স্মরণ কর আর বল, ‘আশা করি আমার প্রতিপালক আমাকে এর চেয়েও সত্যের নিকটবর্তী পথে পরিচালিত করবেন। (কেননা এক ব্যক্তি যেভাবেই সঠিক পথে চলুক না কেন, তার চেয়েও উত্তমভাবে পথ চলা যেতে পারে)।', 'Except [when adding], "If Allah wills." And remember your Lord when you forget [it] and say, "Perhaps my Lord will guide me to what is nearer than this to right conduct."', '‘আল্লাহ ইচ্ছে করলে’ বলা ছাড়া। যদি ভুলে যাও (তবে মনে পড়ার সঙ্গে সঙ্গে) তোমার প্রতিপালককে স্মরণ কর আর বল, ‘আশা করি আমার প্রতিপালক আমাকে এর চেয়েও সত্যের নিকটবর্তী পথে পরিচালিত করবেন। (কেননা এক ব্যক্তি যেভাবেই সঠিক পথে চলুক না কেন, তার চেয়েও উত্তমভাবে পথ চলা যেতে পারে)।', 'Except [when adding], "If Allah wills." And remember your Lord when you forget [it] and say, "Perhaps my Lord will guide me to what is nearer than this to right conduct."', NULL, NULL, NULL, NULL, NULL, 'https://everyayah.com/data/Alafasy_128kbps/018024.mp3', now()),
  (18, 25, '', '[{"id":27705,"position":1,"text_uthmani":"وَلَبِثُوا۟","transliteration":"walabithū","translation_bn":"এবং তারা অবস্থান করেছিলো","root":"لبث","lemma":"لَبِثَ","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":27706,"position":2,"text_uthmani":"فِى","transliteration":"fī","translation_bn":"মধ্যে","root":"—","lemma":"فِى\r","grammar_bn":"অব্যয় (Preposition)"},{"id":27707,"position":3,"text_uthmani":"كَهْفِهِمْ","transliteration":"kahfihim","translation_bn":"গুহার তাদের","root":"كهف","lemma":"كَهْف","grammar_bn":"বিশেষ্য (Noun)"},{"id":27708,"position":4,"text_uthmani":"ثَلَـٰثَ","transliteration":"thalātha","translation_bn":"তিন","root":"ثلث","lemma":"ثَلَٰث","grammar_bn":"বিশেষ্য (Noun)"},{"id":27709,"position":5,"text_uthmani":"مِا۟ئَةٍۢ","transliteration":"mi-atin","translation_bn":"শত","root":"ماي","lemma":"مِائَة","grammar_bn":"বিশেষ্য (Noun)"},{"id":27710,"position":6,"text_uthmani":"سِنِينَ","transliteration":"sinīna","translation_bn":"বছর","root":"سنو","lemma":"سِنِين","grammar_bn":"বিশেষ্য (Noun)"},{"id":27711,"position":7,"text_uthmani":"وَٱزْدَادُوا۟","transliteration":"wa-iz''dādū","translation_bn":"এবং তারা বৃদ্ধি করেছিলো","root":"زيد","lemma":"ٱزْدَادُ","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":27712,"position":8,"text_uthmani":"تِسْعًۭا","transliteration":"tis''ʿan","translation_bn":"(আরও) নয়","root":"تسع","lemma":"تِسْع","grammar_bn":"বিশেষ্য (Noun)"},{"id":27713,"position":9,"text_uthmani":"٢٥","transliteration":"","translation_bn":"(২৫)","root":"—","lemma":"٢٥","grammar_bn":"মার্কার"}]'::jsonb, 'walabithū fī kahfihim thalātha mi-atin sinīna wa-iz''dādū tis''ʿan', 'আর (কারো মতে) তারা তাদের গুহায় ছিল তিনশ’ বছর আর কিছু লোক নয় বছর বাড়িয়ে নিয়েছে।', 'And they remained in their cave for three hundred years and exceeded by nine.', 'আর (কারো মতে) তারা তাদের গুহায় ছিল তিনশ’ বছর আর কিছু লোক নয় বছর বাড়িয়ে নিয়েছে।', 'And they remained in their cave for three hundred years and exceeded by nine.', NULL, NULL, NULL, NULL, NULL, 'https://everyayah.com/data/Alafasy_128kbps/018025.mp3', now()),
  (18, 26, '', '[{"id":28671,"position":1,"text_uthmani":"قُلِ","transliteration":"quli","translation_bn":"বলো","root":"قول","lemma":"قَالَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":28672,"position":2,"text_uthmani":"ٱللَّهُ","transliteration":"l-lahu","translation_bn":"\"আল্লাহ্‌ই","root":"اله","lemma":"ٱللَّه","grammar_bn":"নামবাচক বিশেষ্য (Proper Noun)"},{"id":28673,"position":3,"text_uthmani":"أَعْلَمُ","transliteration":"aʿlamu","translation_bn":"ভালো জানেন","root":"علم","lemma":"أَعْلَم","grammar_bn":"বিশেষণ (Adjective)"},{"id":28674,"position":4,"text_uthmani":"بِمَا","transliteration":"bimā","translation_bn":"সম্পর্কে যা","root":"—","lemma":"مَا\r","grammar_bn":"অব্যয় (Preposition)"},{"id":28675,"position":5,"text_uthmani":"لَبِثُوا۟ ۖ","transliteration":"labithū","translation_bn":"তারা অবস্থান করেছিলো","root":"لبث","lemma":"لَبِثَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":28677,"position":6,"text_uthmani":"لَهُۥ","transliteration":"lahu","translation_bn":"আছে তাঁরই","root":"—","lemma":"لَهُۥ","grammar_bn":"অব্যয় (Preposition)"},{"id":28678,"position":7,"text_uthmani":"غَيْبُ","transliteration":"ghaybu","translation_bn":"অদৃশ্যের জ্ঞান","root":"غيب","lemma":"غَيْب","grammar_bn":"বিশেষ্য (Noun)"},{"id":28679,"position":8,"text_uthmani":"ٱلسَّمَـٰوَٰتِ","transliteration":"l-samāwāti","translation_bn":"আকাশসমূহের","root":"سمو","lemma":"سَمَا^ء","grammar_bn":"শব্দ"},{"id":28680,"position":9,"text_uthmani":"وَٱلْأَرْضِ ۖ","transliteration":"wal-arḍi","translation_bn":"এবং পৃথিবীর","root":"ارض","lemma":"أَرْض","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":28682,"position":10,"text_uthmani":"أَبْصِرْ","transliteration":"abṣir","translation_bn":"কত সুন্দরভাবে দেখেন","root":"بصر","lemma":"أَبْصَرَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":28683,"position":11,"text_uthmani":"بِهِۦ","transliteration":"bihi","translation_bn":"সম্পর্কে তা","root":"—","lemma":"بِهِۦ","grammar_bn":"অব্যয় (Preposition)"},{"id":28684,"position":12,"text_uthmani":"وَأَسْمِعْ ۚ","transliteration":"wa-asmiʿ","translation_bn":"এবং কত সুন্দর শুনেন","root":"سمع","lemma":"أَسْمَعَ","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":28686,"position":13,"text_uthmani":"مَا","transliteration":"mā","translation_bn":"নেই","root":"—","lemma":"مَا\r","grammar_bn":"না-বোধক (Negative)"},{"id":28687,"position":14,"text_uthmani":"لَهُم","transliteration":"lahum","translation_bn":"জন্যে তাদের","root":"—","lemma":"لَهُم","grammar_bn":"অব্যয় (Preposition)"},{"id":28688,"position":15,"text_uthmani":"مِّن","transliteration":"min","translation_bn":"ছাড়া","root":"—","lemma":"مِن\r","grammar_bn":"অব্যয় (Preposition)"},{"id":28689,"position":16,"text_uthmani":"دُونِهِۦ","transliteration":"dūnihi","translation_bn":"তিনি","root":"دون","lemma":"دُون","grammar_bn":"বিশেষ্য (Noun)"},{"id":28690,"position":17,"text_uthmani":"مِن","transliteration":"min","translation_bn":"কোনো","root":"—","lemma":"مِن\r","grammar_bn":"অব্যয় (Preposition)"},{"id":28691,"position":18,"text_uthmani":"وَلِىٍّۢ","transliteration":"waliyyin","translation_bn":"(অন্য) অভিভাবক","root":"ولي","lemma":"وَلِىّ","grammar_bn":"বিশেষ্য (Noun)"},{"id":28692,"position":19,"text_uthmani":"وَلَا","transliteration":"walā","translation_bn":"এবং না","root":"—","lemma":"لَا\r","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":28693,"position":20,"text_uthmani":"يُشْرِكُ","transliteration":"yush''riku","translation_bn":"তিনি শরিক করেন","root":"شرك","lemma":"أَشْرَكَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":28694,"position":21,"text_uthmani":"فِى","transliteration":"fī","translation_bn":"ব্যাপারে","root":"—","lemma":"فِى\r","grammar_bn":"অব্যয় (Preposition)"},{"id":28695,"position":22,"text_uthmani":"حُكْمِهِۦٓ","transliteration":"ḥuk''mihi","translation_bn":"তাঁর কর্তৃত্বের","root":"حكم","lemma":"حُكْم","grammar_bn":"বিশেষ্য (Noun)"},{"id":28696,"position":23,"text_uthmani":"أَحَدًۭا","transliteration":"aḥadan","translation_bn":"(অন্য) কাউকে\"","root":"احد","lemma":"أَحَد","grammar_bn":"বিশেষ্য (Noun)"},{"id":28697,"position":24,"text_uthmani":"٢٦","transliteration":"","translation_bn":"(২৬)","root":"—","lemma":"٢٦","grammar_bn":"মার্কার"}]'::jsonb, 'quli l-lahu aʿlamu bimā labithū lahu ghaybu l-samāwāti wal-arḍi abṣir bihi wa-asmiʿ mā lahum min dūnihi min waliyyin walā yush''riku fī ḥuk''mihi aḥadan', 'বল, ‘আল্লাহই ভাল জানেন তারা কতকাল (গুহায়) ছিল।’ আসমানসমূহ যমীনের অদৃশ্যের জ্ঞান তাঁরই আছে, কত স্পষ্টই না তিনি দেখেন, কত স্পষ্টই না তিনি শোনেন। তিনি ছাড়া তাদের কোন অভিভাবক নেই, তিনি তাঁর কর্তৃত্বে কাউকে অংশীদার করেন না।', 'Say, "Allah is most knowing of how long they remained. He has [knowledge of] the unseen [aspects] of the heavens and the earth. How Seeing is He and how Hearing! They have not besides Him any protector, and He shares not His legislation with anyone."', 'বল, ‘আল্লাহই ভাল জানেন তারা কতকাল (গুহায়) ছিল।’ আসমানসমূহ যমীনের অদৃশ্যের জ্ঞান তাঁরই আছে, কত স্পষ্টই না তিনি দেখেন, কত স্পষ্টই না তিনি শোনেন। তিনি ছাড়া তাদের কোন অভিভাবক নেই, তিনি তাঁর কর্তৃত্বে কাউকে অংশীদার করেন না।', 'Say, "Allah is most knowing of how long they remained. He has [knowledge of] the unseen [aspects] of the heavens and the earth. How Seeing is He and how Hearing! They have not besides Him any protector, and He shares not His legislation with anyone."', NULL, NULL, NULL, NULL, NULL, 'https://everyayah.com/data/Alafasy_128kbps/018026.mp3', now()),
  (18, 27, '', '[{"id":29565,"position":1,"text_uthmani":"وَٱتْلُ","transliteration":"wa-ut''lu","translation_bn":"এবং আবৃত্তি করো","root":"تلو","lemma":"تَلَىٰ","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":29566,"position":2,"text_uthmani":"مَآ","transliteration":"mā","translation_bn":"যা","root":"—","lemma":"مَا\r","grammar_bn":"সাপেক্ষ সর্বনাম (Relative)"},{"id":29567,"position":3,"text_uthmani":"أُوحِىَ","transliteration":"ūḥiya","translation_bn":"ওহী করা হয়েছে","root":"وحي","lemma":"أَوْحَىٰ^","grammar_bn":"ক্রিয়া (Verb)"},{"id":29568,"position":4,"text_uthmani":"إِلَيْكَ","transliteration":"ilayka","translation_bn":"প্রতি তোমার","root":"—","lemma":"إِلَىٰ\r","grammar_bn":"অব্যয় (Preposition)"},{"id":29569,"position":5,"text_uthmani":"مِن","transliteration":"min","translation_bn":"থেকে","root":"—","lemma":"مِن\r","grammar_bn":"অব্যয় (Preposition)"},{"id":29570,"position":6,"text_uthmani":"كِتَابِ","transliteration":"kitābi","translation_bn":"কিতাব","root":"كتب","lemma":"كِتَٰب","grammar_bn":"বিশেষ্য (Noun)"},{"id":29571,"position":7,"text_uthmani":"رَبِّكَ ۖ","transliteration":"rabbika","translation_bn":"তোমার রবের","root":"ربب","lemma":"رَبّ","grammar_bn":"বিশেষ্য (Noun)"},{"id":29573,"position":8,"text_uthmani":"لَا","transliteration":"lā","translation_bn":"নেই","root":"—","lemma":"لَا\r","grammar_bn":"না-বোধক (Negative)"},{"id":29574,"position":9,"text_uthmani":"مُبَدِّلَ","transliteration":"mubaddila","translation_bn":"পরিবর্তনকারী","root":"بدل","lemma":"مُبَدِّل","grammar_bn":"বিশেষ্য (Noun)"},{"id":29575,"position":10,"text_uthmani":"لِكَلِمَـٰتِهِۦ","transliteration":"likalimātihi","translation_bn":"তাঁর কথাগুলোর","root":"كلم","lemma":"كَلِمَٰت","grammar_bn":"অব্যয় (Preposition)"},{"id":29576,"position":11,"text_uthmani":"وَلَن","transliteration":"walan","translation_bn":"এবং কখনও না","root":"—","lemma":"لَن\r","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":29577,"position":12,"text_uthmani":"تَجِدَ","transliteration":"tajida","translation_bn":"তুমি পাবে","root":"وجد","lemma":"وَجَدَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":29578,"position":13,"text_uthmani":"مِن","transliteration":"min","translation_bn":"ছাড়া","root":"—","lemma":"مِن\r","grammar_bn":"অব্যয় (Preposition)"},{"id":29579,"position":14,"text_uthmani":"دُونِهِۦ","transliteration":"dūnihi","translation_bn":"তিনি","root":"دون","lemma":"دُون","grammar_bn":"বিশেষ্য (Noun)"},{"id":29580,"position":15,"text_uthmani":"مُلْتَحَدًۭا","transliteration":"mul''taḥadan","translation_bn":"আশ্রয়স্থান","root":"لحد","lemma":"مُلْتَحَد","grammar_bn":"বিশেষ্য (Noun)"},{"id":29581,"position":16,"text_uthmani":"٢٧","transliteration":"","translation_bn":"(২৭)","root":"—","lemma":"٢٧","grammar_bn":"মার্কার"}]'::jsonb, 'wa-ut''lu mā ūḥiya ilayka min kitābi rabbika lā mubaddila likalimātihi walan tajida min dūnihi mul''taḥadan', 'আর তুমি তোমার কাছে ওয়াহীকৃত তোমার প্রতিপালকের কিতাব থেকে পাঠ করে শুনাও, তাঁর কথা পরিবর্তন করে দেবে এমন কেউ নেই, আর তাঁকে ছাড়া তুমি কক্ষনো অন্য কাউকে আশ্রয়স্থল হিসেবে পাবে না।', 'And recite, [O Muhammad], what has been revealed to you of the Book of your Lord. There is no changer of His words, and never will you find in other than Him a refuge.', 'আর তুমি তোমার কাছে ওয়াহীকৃত তোমার প্রতিপালকের কিতাব থেকে পাঠ করে শুনাও, তাঁর কথা পরিবর্তন করে দেবে এমন কেউ নেই, আর তাঁকে ছাড়া তুমি কক্ষনো অন্য কাউকে আশ্রয়স্থল হিসেবে পাবে না।', 'And recite, [O Muhammad], what has been revealed to you of the Book of your Lord. There is no changer of His words, and never will you find in other than Him a refuge.', NULL, NULL, NULL, NULL, NULL, 'https://everyayah.com/data/Alafasy_128kbps/018027.mp3', now()),
  (18, 28, '', '[{"id":30579,"position":1,"text_uthmani":"وَٱصْبِرْ","transliteration":"wa-iṣ''bir","translation_bn":"এবং স্থিতিশীল রাখবে","root":"صبر","lemma":"صَبَرَ","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":30580,"position":2,"text_uthmani":"نَفْسَكَ","transliteration":"nafsaka","translation_bn":"তোমার নিজেকে","root":"نفس","lemma":"نَفْس","grammar_bn":"বিশেষ্য (Noun)"},{"id":30581,"position":3,"text_uthmani":"مَعَ","transliteration":"maʿa","translation_bn":"সাথে","root":"—","lemma":"مَع","grammar_bn":"স্থানবাচক (Location)"},{"id":30582,"position":4,"text_uthmani":"ٱلَّذِينَ","transliteration":"alladhīna","translation_bn":"(তাদের) যারা","root":"—","lemma":"ٱلَّذِى","grammar_bn":"সাপেক্ষ সর্বনাম (Relative)"},{"id":30583,"position":5,"text_uthmani":"يَدْعُونَ","transliteration":"yadʿūna","translation_bn":"ডাকে","root":"دعو","lemma":"دَعَا","grammar_bn":"ক্রিয়া (Verb)"},{"id":30584,"position":6,"text_uthmani":"رَبَّهُم","transliteration":"rabbahum","translation_bn":"রবকে তাদের","root":"ربب","lemma":"رَبّ","grammar_bn":"বিশেষ্য (Noun)"},{"id":30585,"position":7,"text_uthmani":"بِٱلْغَدَوٰةِ","transliteration":"bil-ghadati","translation_bn":"বেলায় সকাল","root":"غدو","lemma":"غَدَوٰة","grammar_bn":"অব্যয় (Preposition)"},{"id":30586,"position":8,"text_uthmani":"وَٱلْعَشِىِّ","transliteration":"wal-ʿashiyi","translation_bn":"ও সন্ধ্যায়","root":"عشو","lemma":"عَشِىّ","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":30587,"position":9,"text_uthmani":"يُرِيدُونَ","transliteration":"yurīdūna","translation_bn":"তারা চায়","root":"رود","lemma":"أَرَادَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":30588,"position":10,"text_uthmani":"وَجْهَهُۥ ۖ","transliteration":"wajhahu","translation_bn":"তাঁর সন্তুষ্টি","root":"وجه","lemma":"وَجْه","grammar_bn":"বিশেষ্য (Noun)"},{"id":30590,"position":11,"text_uthmani":"وَلَا","transliteration":"walā","translation_bn":"এবং না","root":"—","lemma":"لَا\r","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":30591,"position":12,"text_uthmani":"تَعْدُ","transliteration":"taʿdu","translation_bn":"ফিরিয়ে নিও","root":"عدو","lemma":"يَعْدُ","grammar_bn":"ক্রিয়া (Verb)"},{"id":30592,"position":13,"text_uthmani":"عَيْنَاكَ","transliteration":"ʿaynāka","translation_bn":"তোমার দু''চোখ","root":"عين","lemma":"عَيْن","grammar_bn":"বিশেষ্য (Noun)"},{"id":30593,"position":14,"text_uthmani":"عَنْهُمْ","transliteration":"ʿanhum","translation_bn":"থেকে তাদের","root":"—","lemma":"عَن\r","grammar_bn":"অব্যয় (Preposition)"},{"id":30594,"position":15,"text_uthmani":"تُرِيدُ","transliteration":"turīdu","translation_bn":"তুমি চাও","root":"رود","lemma":"أَرَادَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":30595,"position":16,"text_uthmani":"زِينَةَ","transliteration":"zīnata","translation_bn":"শোভা","root":"زين","lemma":"زِينَة","grammar_bn":"বিশেষ্য (Noun)"},{"id":30596,"position":17,"text_uthmani":"ٱلْحَيَوٰةِ","transliteration":"l-ḥayati","translation_bn":"জীবনের","root":"حيي","lemma":"حَيَوٰة","grammar_bn":"শব্দ"},{"id":30597,"position":18,"text_uthmani":"ٱلدُّنْيَا ۖ","transliteration":"l-dun''yā","translation_bn":"পার্থিব","root":"دنو","lemma":"دُّنْيَا","grammar_bn":"শব্দ"},{"id":30599,"position":19,"text_uthmani":"وَلَا","transliteration":"walā","translation_bn":"এবং না","root":"—","lemma":"لَا\r","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":30600,"position":20,"text_uthmani":"تُطِعْ","transliteration":"tuṭiʿ","translation_bn":"আনুগত্য করো","root":"طوع","lemma":"أَطَاعَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":30601,"position":21,"text_uthmani":"مَنْ","transliteration":"man","translation_bn":"(তার) যার","root":"—","lemma":"مَن\r","grammar_bn":"সাপেক্ষ সর্বনাম (Relative)"},{"id":30602,"position":22,"text_uthmani":"أَغْفَلْنَا","transliteration":"aghfalnā","translation_bn":"আমরা অমনোযোগী করে দিয়েছি","root":"غفل","lemma":"أَغْفَلْ","grammar_bn":"ক্রিয়া (Verb)"},{"id":30603,"position":23,"text_uthmani":"قَلْبَهُۥ","transliteration":"qalbahu","translation_bn":"অন্তরকে তার","root":"قلب","lemma":"قَلْب","grammar_bn":"বিশেষ্য (Noun)"},{"id":30604,"position":24,"text_uthmani":"عَن","transliteration":"ʿan","translation_bn":"থেকে","root":"—","lemma":"عَن\r","grammar_bn":"অব্যয় (Preposition)"},{"id":30605,"position":25,"text_uthmani":"ذِكْرِنَا","transliteration":"dhik''rinā","translation_bn":"আমাদের স্মরণ","root":"ذكر","lemma":"ذِكْر","grammar_bn":"বিশেষ্য (Noun)"},{"id":30606,"position":26,"text_uthmani":"وَٱتَّبَعَ","transliteration":"wa-ittabaʿa","translation_bn":"এবং অনুসরণ করে","root":"تبع","lemma":"ٱتَّبَعَ","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":30607,"position":27,"text_uthmani":"هَوَىٰهُ","transliteration":"hawāhu","translation_bn":"তাদের খেয়াল-খুশির","root":"هوي","lemma":"هَوَا^ء","grammar_bn":"বিশেষ্য (Noun)"},{"id":30608,"position":28,"text_uthmani":"وَكَانَ","transliteration":"wakāna","translation_bn":"এবং হয়েছে","root":"كون","lemma":"كَانَ","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":30609,"position":29,"text_uthmani":"أَمْرُهُۥ","transliteration":"amruhu","translation_bn":"তার কাজ","root":"امر","lemma":"أَمْر","grammar_bn":"বিশেষ্য (Noun)"},{"id":30610,"position":30,"text_uthmani":"فُرُطًۭا","transliteration":"furuṭan","translation_bn":"সীমালঙ্ঘনমূলক","root":"فرط","lemma":"فُرُط","grammar_bn":"বিশেষ্য (Noun)"},{"id":30611,"position":31,"text_uthmani":"٢٨","transliteration":"","translation_bn":"(২৮)","root":"—","lemma":"٢٨","grammar_bn":"মার্কার"}]'::jsonb, 'wa-iṣ''bir nafsaka maʿa alladhīna yadʿūna rabbahum bil-ghadati wal-ʿashiyi yurīdūna wajhahu walā taʿdu ʿaynāka ʿanhum turīdu zīnata l-ḥayati l-dun''yā walā tuṭiʿ man aghfalnā qalbahu ʿan dhik''rinā wa-ittabaʿa hawāhu wakāna amruhu furuṭan', 'তুমি দৃঢ় চিত্ত হয়ে তাদের সাথে অবস্থান কর যারা সকাল-সন্ধ্যা তাদের প্রতিপালককে আহবান করে তাঁর সন্তুষ্টি লাভের সন্ধানে। পার্থিব জীবনের শোভা ও চাকচিক্য কামনায় তুমি তাদের থেকে তোমার দৃষ্টি ফিরিয়ে নিও না। তুমি তার আনুগত্য কর না যার অন্তরকে আমি আমার স্মরণ হতে উদাসীন করে দিয়েছি, যে নিজের প্রবৃত্তির আনুগত্য করে আর যার কার্যকলাপ হচ্ছে সীমালঙ্ঘনমূলক।', 'And keep yourself patient [by being] with those who call upon their Lord in the morning and the evening, seeking His countenance. And let not your eyes pass beyond them, desiring adornments of the worldly life, and do not obey one whose heart We have made heedless of Our remembrance and who follows his desire and whose affair is ever [in] neglect.', 'তুমি দৃঢ় চিত্ত হয়ে তাদের সাথে অবস্থান কর যারা সকাল-সন্ধ্যা তাদের প্রতিপালককে আহবান করে তাঁর সন্তুষ্টি লাভের সন্ধানে। পার্থিব জীবনের শোভা ও চাকচিক্য কামনায় তুমি তাদের থেকে তোমার দৃষ্টি ফিরিয়ে নিও না। তুমি তার আনুগত্য কর না যার অন্তরকে আমি আমার স্মরণ হতে উদাসীন করে দিয়েছি, যে নিজের প্রবৃত্তির আনুগত্য করে আর যার কার্যকলাপ হচ্ছে সীমালঙ্ঘনমূলক।', 'And keep yourself patient [by being] with those who call upon their Lord in the morning and the evening, seeking His countenance. And let not your eyes pass beyond them, desiring adornments of the worldly life, and do not obey one whose heart We have made heedless of Our remembrance and who follows his desire and whose affair is ever [in] neglect.', NULL, NULL, NULL, NULL, NULL, 'https://everyayah.com/data/Alafasy_128kbps/018028.mp3', now()),
  (18, 29, '', '[{"id":31603,"position":1,"text_uthmani":"وَقُلِ","transliteration":"waquli","translation_bn":"এবং বলো","root":"قول","lemma":"قَالَ","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":31604,"position":2,"text_uthmani":"ٱلْحَقُّ","transliteration":"l-ḥaqu","translation_bn":"\"(এসেছে) সত্য","root":"حقق","lemma":"حَقّ","grammar_bn":"শব্দ"},{"id":31605,"position":3,"text_uthmani":"مِن","transliteration":"min","translation_bn":"পক্ষ হ''তে","root":"—","lemma":"مِن\r","grammar_bn":"অব্যয় (Preposition)"},{"id":31606,"position":4,"text_uthmani":"رَّبِّكُمْ ۖ","transliteration":"rabbikum","translation_bn":"রবের তোমার","root":"ربب","lemma":"رَبّ","grammar_bn":"বিশেষ্য (Noun)"},{"id":31608,"position":5,"text_uthmani":"فَمَن","transliteration":"faman","translation_bn":"অতএব যে","root":"—","lemma":"مَن\r","grammar_bn":"শব্দ"},{"id":31609,"position":6,"text_uthmani":"شَآءَ","transliteration":"shāa","translation_bn":"ইচ্ছে করে","root":"شيا","lemma":"شَا^ءَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":31610,"position":7,"text_uthmani":"فَلْيُؤْمِن","transliteration":"falyu''min","translation_bn":"অতঃপর ঈমান আনুক","root":"امن","lemma":"ءَامَنَ","grammar_bn":"শব্দ"},{"id":31611,"position":8,"text_uthmani":"وَمَن","transliteration":"waman","translation_bn":"এবং যে","root":"—","lemma":"مَن\r","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":31612,"position":9,"text_uthmani":"شَآءَ","transliteration":"shāa","translation_bn":"ইচ্ছে করে","root":"شيا","lemma":"شَا^ءَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":31613,"position":10,"text_uthmani":"فَلْيَكْفُرْ ۚ","transliteration":"falyakfur","translation_bn":"অতঃপর অস্বীকার করুক\"","root":"كفر","lemma":"كَفَرَ","grammar_bn":"শব্দ"},{"id":31615,"position":11,"text_uthmani":"إِنَّآ","transliteration":"innā","translation_bn":"নিশ্চয়ই আমরা","root":"—","lemma":"إِنّ","grammar_bn":"অভিঘাত পদ (Accusative)"},{"id":31616,"position":12,"text_uthmani":"أَعْتَدْنَا","transliteration":"aʿtadnā","translation_bn":"আমরা প্রস্তুত করে রেখেছি","root":"عتد","lemma":"أَعْتَدَتْ","grammar_bn":"ক্রিয়া (Verb)"},{"id":31617,"position":13,"text_uthmani":"لِلظَّـٰلِمِينَ","transliteration":"lilẓẓālimīna","translation_bn":"জন্যে সীমালঙ্ঘনকারীদের","root":"ظلم","lemma":"ظَالِم","grammar_bn":"অব্যয় (Preposition)"},{"id":31618,"position":14,"text_uthmani":"نَارًا","transliteration":"nāran","translation_bn":"জাহান্নামের আগুন","root":"نور","lemma":"نَار","grammar_bn":"বিশেষ্য (Noun)"},{"id":31619,"position":15,"text_uthmani":"أَحَاطَ","transliteration":"aḥāṭa","translation_bn":"পরিবেষ্টন করেছে","root":"حوط","lemma":"أَحَاطَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":31620,"position":16,"text_uthmani":"بِهِمْ","transliteration":"bihim","translation_bn":"সহ তাদেরকে","root":"—","lemma":"بِهِمْ","grammar_bn":"অব্যয় (Preposition)"},{"id":31621,"position":17,"text_uthmani":"سُرَادِقُهَا ۚ","transliteration":"surādiquhā","translation_bn":"তার শিখা","root":"سردق","lemma":"سُرَادِق","grammar_bn":"বিশেষ্য (Noun)"},{"id":31623,"position":18,"text_uthmani":"وَإِن","transliteration":"wa-in","translation_bn":"এবং যদি","root":"—","lemma":"إِن\r","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":31624,"position":19,"text_uthmani":"يَسْتَغِيثُوا۟","transliteration":"yastaghīthū","translation_bn":"তারা পান করতে চায়","root":"غوث","lemma":"ٱسْتَغَٰثَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":31625,"position":20,"text_uthmani":"يُغَاثُوا۟","transliteration":"yughāthū","translation_bn":"তাদের পানি দেয়া হবে","root":"غوث","lemma":"يُغَاثُ","grammar_bn":"ক্রিয়া (Verb)"},{"id":31626,"position":21,"text_uthmani":"بِمَآءٍۢ","transliteration":"bimāin","translation_bn":"এমন পানি","root":"موه","lemma":"مَا^ء","grammar_bn":"অব্যয় (Preposition)"},{"id":31627,"position":22,"text_uthmani":"كَٱلْمُهْلِ","transliteration":"kal-muh''li","translation_bn":"মতো তেলের গাদের","root":"مهل","lemma":"مُهْل","grammar_bn":"অব্যয় (Preposition)"},{"id":31628,"position":23,"text_uthmani":"يَشْوِى","transliteration":"yashwī","translation_bn":"ঝলসে দিবে","root":"شوي","lemma":"يَشْوِى","grammar_bn":"ক্রিয়া (Verb)"},{"id":31629,"position":24,"text_uthmani":"ٱلْوُجُوهَ ۚ","transliteration":"l-wujūha","translation_bn":"মুখসমূহকে","root":"وجه","lemma":"وَجْه","grammar_bn":"শব্দ"},{"id":31631,"position":25,"text_uthmani":"بِئْسَ","transliteration":"bi''sa","translation_bn":"কত নিকৃষ্ট","root":"باس","lemma":"بِئْسَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":31632,"position":26,"text_uthmani":"ٱلشَّرَابُ","transliteration":"l-sharābu","translation_bn":"পানীয়","root":"شرب","lemma":"شَرَاب","grammar_bn":"শব্দ"},{"id":31633,"position":27,"text_uthmani":"وَسَآءَتْ","transliteration":"wasāat","translation_bn":"এবং অতিশয় খারাপ","root":"سوا","lemma":"سَا^ءَ","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":31634,"position":28,"text_uthmani":"مُرْتَفَقًا","transliteration":"mur''tafaqan","translation_bn":"আশ্রয়স্থল","root":"رفق","lemma":"مُرْتَفَق","grammar_bn":"বিশেষ্য (Noun)"},{"id":31635,"position":29,"text_uthmani":"٢٩","transliteration":"","translation_bn":"(২৯)","root":"—","lemma":"٢٩","grammar_bn":"মার্কার"}]'::jsonb, 'waquli l-ḥaqu min rabbikum faman shāa falyu''min waman shāa falyakfur innā aʿtadnā lilẓẓālimīna nāran aḥāṭa bihim surādiquhā wa-in yastaghīthū yughāthū bimāin kal-muh''li yashwī l-wujūha bi''sa l-sharābu wasāat mur''tafaqan', 'আর বলে দাও, ‘সত্য এসেছে তোমাদের রব্বের নিকট হতে, কাজেই যার ইচ্ছে ঈমান আনুক আর যার ইচ্ছে সত্যকে অস্বীকার করুক।’ আমি (অস্বীকারকারী) যালিমদের জন্য আগুন প্রস্তুত করে রেখেছি যার লেলিহান শিখা তাদেরকে ঘিরে ফেলেছে। তারা পানীয় চাইলে তাদেরকে গলিত শিশার ন্যায় পানি দেয়া হবে যা তাদের মুখমন্ডল দগ্ধ করবে, কতই না নিকৃষ্ট পানীয়! আর কতই না নিকৃষ্ট আশ্রয়স্থল!', 'And say, "The truth is from your Lord, so whoever wills - let him believe; and whoever wills - let him disbelieve." Indeed, We have prepared for the wrongdoers a fire whose walls will surround them. And if they call for relief, they will be relieved with water like murky oil, which scalds [their] faces. Wretched is the drink, and evil is the resting place.', 'আর বলে দাও, ‘সত্য এসেছে তোমাদের রব্বের নিকট হতে, কাজেই যার ইচ্ছে ঈমান আনুক আর যার ইচ্ছে সত্যকে অস্বীকার করুক।’ আমি (অস্বীকারকারী) যালিমদের জন্য আগুন প্রস্তুত করে রেখেছি যার লেলিহান শিখা তাদেরকে ঘিরে ফেলেছে। তারা পানীয় চাইলে তাদেরকে গলিত শিশার ন্যায় পানি দেয়া হবে যা তাদের মুখমন্ডল দগ্ধ করবে, কতই না নিকৃষ্ট পানীয়! আর কতই না নিকৃষ্ট আশ্রয়স্থল!', 'And say, "The truth is from your Lord, so whoever wills - let him believe; and whoever wills - let him disbelieve." Indeed, We have prepared for the wrongdoers a fire whose walls will surround them. And if they call for relief, they will be relieved with water like murky oil, which scalds [their] faces. Wretched is the drink, and evil is the resting place.', NULL, NULL, NULL, NULL, NULL, 'https://everyayah.com/data/Alafasy_128kbps/018029.mp3', now()),
  (18, 30, '', '[{"id":32501,"position":1,"text_uthmani":"إِنَّ","transliteration":"inna","translation_bn":"নিশ্চয়ই","root":"—","lemma":"إِنّ","grammar_bn":"অভিঘাত পদ (Accusative)"},{"id":32502,"position":2,"text_uthmani":"ٱلَّذِينَ","transliteration":"alladhīna","translation_bn":"যারা","root":"—","lemma":"ٱلَّذِى","grammar_bn":"সাপেক্ষ সর্বনাম (Relative)"},{"id":32503,"position":3,"text_uthmani":"ءَامَنُوا۟","transliteration":"āmanū","translation_bn":"ঈমান এনেছে","root":"امن","lemma":"ءَامَنَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":32504,"position":4,"text_uthmani":"وَعَمِلُوا۟","transliteration":"waʿamilū","translation_bn":"এবং কাজ করেছে","root":"عمل","lemma":"عَمِلَ","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":32505,"position":5,"text_uthmani":"ٱلصَّـٰلِحَـٰتِ","transliteration":"l-ṣāliḥāti","translation_bn":"সৎ","root":"صلح","lemma":"صَّٰلِحَٰت","grammar_bn":"শব্দ"},{"id":32506,"position":6,"text_uthmani":"إِنَّا","transliteration":"innā","translation_bn":"নিশ্চয়ই আমরা","root":"—","lemma":"إِنّ","grammar_bn":"অভিঘাত পদ (Accusative)"},{"id":32507,"position":7,"text_uthmani":"لَا","transliteration":"lā","translation_bn":"না","root":"—","lemma":"لَا\r","grammar_bn":"না-বোধক (Negative)"},{"id":32508,"position":8,"text_uthmani":"نُضِيعُ","transliteration":"nuḍīʿu","translation_bn":"আমরা বিনষ্ট করি","root":"ضيع","lemma":"أَضَاعُ","grammar_bn":"ক্রিয়া (Verb)"},{"id":32509,"position":9,"text_uthmani":"أَجْرَ","transliteration":"ajra","translation_bn":"পুরস্কার","root":"اجر","lemma":"أَجْر","grammar_bn":"বিশেষ্য (Noun)"},{"id":32510,"position":10,"text_uthmani":"مَنْ","transliteration":"man","translation_bn":"যে","root":"—","lemma":"مَن\r","grammar_bn":"সাপেক্ষ সর্বনাম (Relative)"},{"id":32511,"position":11,"text_uthmani":"أَحْسَنَ","transliteration":"aḥsana","translation_bn":"ভালো করে","root":"حسن","lemma":"أَحْسَنَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":32512,"position":12,"text_uthmani":"عَمَلًا","transliteration":"ʿamalan","translation_bn":"কাজ","root":"عمل","lemma":"عَمَل","grammar_bn":"বিশেষ্য (Noun)"},{"id":32513,"position":13,"text_uthmani":"٣٠","transliteration":"","translation_bn":"(৩০)","root":"—","lemma":"٣٠","grammar_bn":"মার্কার"}]'::jsonb, 'inna alladhīna āmanū waʿamilū l-ṣāliḥāti innā lā nuḍīʿu ajra man aḥsana ʿamalan', 'যারা ঈমান আনে আর সৎ কাজ করে- যে উত্তমভাবে কাজ করে আমি তার কর্মফল বিনষ্ট করি না।', 'Indeed, those who have believed and done righteous deeds - indeed, We will not allow to be lost the reward of any who did well in deeds.', 'যারা ঈমান আনে আর সৎ কাজ করে- যে উত্তমভাবে কাজ করে আমি তার কর্মফল বিনষ্ট করি না।', 'Indeed, those who have believed and done righteous deeds - indeed, We will not allow to be lost the reward of any who did well in deeds.', NULL, NULL, NULL, NULL, NULL, 'https://everyayah.com/data/Alafasy_128kbps/018030.mp3', now()),
  (18, 31, '', '[{"id":33363,"position":1,"text_uthmani":"أُو۟لَـٰٓئِكَ","transliteration":"ulāika","translation_bn":"এসব লোক","root":"—","lemma":"أُولَٰ^ئِك","grammar_bn":"নির্দেশক সর্বনাম (Demonstrative)"},{"id":33364,"position":2,"text_uthmani":"لَهُمْ","transliteration":"lahum","translation_bn":"জন্যে রয়েছে তাদের","root":"—","lemma":"لَهُمْ","grammar_bn":"অব্যয় (Preposition)"},{"id":33365,"position":3,"text_uthmani":"جَنَّـٰتُ","transliteration":"jannātu","translation_bn":"জান্নাতসমূহ","root":"جنن","lemma":"جَنَّة","grammar_bn":"বিশেষ্য (Noun)"},{"id":33366,"position":4,"text_uthmani":"عَدْنٍۢ","transliteration":"ʿadnin","translation_bn":"স্থায়ী","root":"—","lemma":"عَدْن","grammar_bn":"নামবাচক বিশেষ্য (Proper Noun)"},{"id":33367,"position":5,"text_uthmani":"تَجْرِى","transliteration":"tajrī","translation_bn":"প্রবাহিত হয়","root":"جري","lemma":"جَرَيْ","grammar_bn":"ক্রিয়া (Verb)"},{"id":33368,"position":6,"text_uthmani":"مِن","transliteration":"min","translation_bn":"থেকে","root":"—","lemma":"مِن\r","grammar_bn":"অব্যয় (Preposition)"},{"id":33369,"position":7,"text_uthmani":"تَحْتِهِمُ","transliteration":"taḥtihimu","translation_bn":"নিচ তার","root":"تحت","lemma":"تَحْت","grammar_bn":"বিশেষ্য (Noun)"},{"id":33370,"position":8,"text_uthmani":"ٱلْأَنْهَـٰرُ","transliteration":"l-anhāru","translation_bn":"ঝর্নাসমূহ","root":"نهر","lemma":"نَهَر","grammar_bn":"শব্দ"},{"id":33371,"position":9,"text_uthmani":"يُحَلَّوْنَ","transliteration":"yuḥallawna","translation_bn":"তাদের অলংকৃত করা হবে","root":"حلي","lemma":"حُلُّ","grammar_bn":"ক্রিয়া (Verb)"},{"id":33372,"position":10,"text_uthmani":"فِيهَا","transliteration":"fīhā","translation_bn":"মধ্যে তার","root":"—","lemma":"فِى\r","grammar_bn":"অব্যয় (Preposition)"},{"id":33373,"position":11,"text_uthmani":"مِنْ","transliteration":"min","translation_bn":"দিয়ে","root":"—","lemma":"مِن\r","grammar_bn":"অব্যয় (Preposition)"},{"id":33374,"position":12,"text_uthmani":"أَسَاوِرَ","transliteration":"asāwira","translation_bn":"কঙ্কণ","root":"سور","lemma":"أَسَاوِر","grammar_bn":"বিশেষ্য (Noun)"},{"id":33375,"position":13,"text_uthmani":"مِن","transliteration":"min","translation_bn":"তৈরী","root":"—","lemma":"مِن\r","grammar_bn":"অব্যয় (Preposition)"},{"id":33376,"position":14,"text_uthmani":"ذَهَبٍۢ","transliteration":"dhahabin","translation_bn":"সোনার","root":"ذهب","lemma":"ذَهَب","grammar_bn":"বিশেষ্য (Noun)"},{"id":33377,"position":15,"text_uthmani":"وَيَلْبَسُونَ","transliteration":"wayalbasūna","translation_bn":"এবং তাদের পরানো হবে","root":"لبس","lemma":"لَبَسْ","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":33378,"position":16,"text_uthmani":"ثِيَابًا","transliteration":"thiyāban","translation_bn":"পোষাক","root":"ثوب","lemma":"ثِيَاب","grammar_bn":"বিশেষ্য (Noun)"},{"id":33379,"position":17,"text_uthmani":"خُضْرًۭا","transliteration":"khuḍ''ran","translation_bn":"সবুজ","root":"خضر","lemma":"خُضْر","grammar_bn":"বিশেষ্য (Noun)"},{"id":33380,"position":18,"text_uthmani":"مِّن","transliteration":"min","translation_bn":"তৈরি","root":"—","lemma":"مِن\r","grammar_bn":"অব্যয় (Preposition)"},{"id":33381,"position":19,"text_uthmani":"سُندُسٍۢ","transliteration":"sundusin","translation_bn":"মিহি রেশমের","root":"—","lemma":"سُندُس","grammar_bn":"বিশেষ্য (Noun)"},{"id":33382,"position":20,"text_uthmani":"وَإِسْتَبْرَقٍۢ","transliteration":"wa-is''tabraqin","translation_bn":"ও মোটা রেশমের","root":"—","lemma":"إِسْتَبْرَق","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":33383,"position":21,"text_uthmani":"مُّتَّكِـِٔينَ","transliteration":"muttakiīna","translation_bn":"হেলান দিয়ে বসবে","root":"وكا","lemma":"مُتَّكِـ#ِين","grammar_bn":"বিশেষ্য (Noun)"},{"id":33384,"position":22,"text_uthmani":"فِيهَا","transliteration":"fīhā","translation_bn":"মধ্যে তার","root":"—","lemma":"فِى\r","grammar_bn":"অব্যয় (Preposition)"},{"id":33385,"position":23,"text_uthmani":"عَلَى","transliteration":"ʿalā","translation_bn":"উপর","root":"—","lemma":"عَلَىٰ\r","grammar_bn":"অব্যয় (Preposition)"},{"id":33386,"position":24,"text_uthmani":"ٱلْأَرَآئِكِ ۚ","transliteration":"l-arāiki","translation_bn":"উঁচু আসনের","root":"ارك","lemma":"أَرَا^ئِك","grammar_bn":"শব্দ"},{"id":33388,"position":25,"text_uthmani":"نِعْمَ","transliteration":"niʿ''ma","translation_bn":"কত সুন্দর","root":"نعم","lemma":"نِعْمَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":33389,"position":26,"text_uthmani":"ٱلثَّوَابُ","transliteration":"l-thawābu","translation_bn":"প্রতিদান","root":"ثوب","lemma":"ثَوَاب","grammar_bn":"শব্দ"},{"id":33390,"position":27,"text_uthmani":"وَحَسُنَتْ","transliteration":"waḥasunat","translation_bn":"এবং অতি উত্তম","root":"حسن","lemma":"حَسُنَ","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":33391,"position":28,"text_uthmani":"مُرْتَفَقًۭا","transliteration":"mur''tafaqan","translation_bn":"আশ্রয়স্থল","root":"رفق","lemma":"مُرْتَفَق","grammar_bn":"বিশেষ্য (Noun)"},{"id":33392,"position":29,"text_uthmani":"٣١","transliteration":"","translation_bn":"(৩১)","root":"—","lemma":"٣١","grammar_bn":"মার্কার"}]'::jsonb, 'ulāika lahum jannātu ʿadnin tajrī min taḥtihimu l-anhāru yuḥallawna fīhā min asāwira min dhahabin wayalbasūna thiyāban khuḍ''ran min sundusin wa-is''tabraqin muttakiīna fīhā ʿalā l-arāiki niʿ''ma l-thawābu waḥasunat mur''tafaqan', 'তাদের জন্য আছে স্থায়ী জান্নাত যার নিম্নদেশে ঝর্ণাধারা প্রবাহিত। সেখানে তাদেরকে অলংকৃত করা হবে স্বর্ণ কংকণে। সূক্ষ্ম ও গাঢ় রেশমের সবুজ পোশাক তারা পরিধান করবে। তারা গদি লাগানো উচ্চাসনে হেলান দিয়ে বসবে। কতই না উত্তম পুরস্কার! কতই না উত্তম আশ্রয়স্থল!', 'Those will have gardens of perpetual residence; beneath them rivers will flow. They will be adorned therein with bracelets of gold and will wear green garments of fine silk and brocade, reclining therein on adorned couches. Excellent is the reward, and good is the resting place.', 'তাদের জন্য আছে স্থায়ী জান্নাত যার নিম্নদেশে ঝর্ণাধারা প্রবাহিত। সেখানে তাদেরকে অলংকৃত করা হবে স্বর্ণ কংকণে। সূক্ষ্ম ও গাঢ় রেশমের সবুজ পোশাক তারা পরিধান করবে। তারা গদি লাগানো উচ্চাসনে হেলান দিয়ে বসবে। কতই না উত্তম পুরস্কার! কতই না উত্তম আশ্রয়স্থল!', 'Those will have gardens of perpetual residence; beneath them rivers will flow. They will be adorned therein with bracelets of gold and will wear green garments of fine silk and brocade, reclining therein on adorned couches. Excellent is the reward, and good is the resting place.', NULL, NULL, NULL, NULL, NULL, 'https://everyayah.com/data/Alafasy_128kbps/018031.mp3', now()),
  (18, 32, '', '[{"id":34432,"position":1,"text_uthmani":"۞ وَٱضْرِبْ","transliteration":"wa-iḍ''rib","translation_bn":"এবং পেশ করো","root":"ضرب","lemma":"ضَرَبَ","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":34433,"position":2,"text_uthmani":"لَهُم","transliteration":"lahum","translation_bn":"জন্যে তাদের","root":"—","lemma":"لَهُم","grammar_bn":"অব্যয় (Preposition)"},{"id":34434,"position":3,"text_uthmani":"مَّثَلًۭا","transliteration":"mathalan","translation_bn":"একটি দৃষ্টান্ত","root":"مثل","lemma":"مَثَل","grammar_bn":"বিশেষ্য (Noun)"},{"id":34435,"position":4,"text_uthmani":"رَّجُلَيْنِ","transliteration":"rajulayni","translation_bn":"দু''ব্যক্তির","root":"رجل","lemma":"رَجُل","grammar_bn":"বিশেষ্য (Noun)"},{"id":34436,"position":5,"text_uthmani":"جَعَلْنَا","transliteration":"jaʿalnā","translation_bn":"আমরা দিয়েছিলাম","root":"جعل","lemma":"جَعَلَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":34437,"position":6,"text_uthmani":"لِأَحَدِهِمَا","transliteration":"li-aḥadihimā","translation_bn":"দু''জনের একজনকে তাদের","root":"احد","lemma":"أَحَد","grammar_bn":"অব্যয় (Preposition)"},{"id":34438,"position":7,"text_uthmani":"جَنَّتَيْنِ","transliteration":"jannatayni","translation_bn":"দু''বাগান","root":"جنن","lemma":"جَنَّة","grammar_bn":"বিশেষ্য (Noun)"},{"id":34439,"position":8,"text_uthmani":"مِنْ","transliteration":"min","translation_bn":"থেকে","root":"—","lemma":"مِن\r","grammar_bn":"অব্যয় (Preposition)"},{"id":34440,"position":9,"text_uthmani":"أَعْنَـٰبٍۢ","transliteration":"aʿnābin","translation_bn":"আঙ্গুরসমূহের","root":"عنب","lemma":"عِنَب","grammar_bn":"বিশেষ্য (Noun)"},{"id":34441,"position":10,"text_uthmani":"وَحَفَفْنَـٰهُمَا","transliteration":"waḥafafnāhumā","translation_bn":"এবং দু''টিকে আমরা ঘিরে দিয়েছিলাম","root":"حفف","lemma":"حَفَفْ","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":34442,"position":11,"text_uthmani":"بِنَخْلٍۢ","transliteration":"binakhlin","translation_bn":"দিয়ে খেজুর গাছ","root":"نخل","lemma":"نَخْل","grammar_bn":"অব্যয় (Preposition)"},{"id":34443,"position":12,"text_uthmani":"وَجَعَلْنَا","transliteration":"wajaʿalnā","translation_bn":"এবং আমরা বানিয়েছিলাম","root":"جعل","lemma":"جَعَلَ","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":34444,"position":13,"text_uthmani":"بَيْنَهُمَا","transliteration":"baynahumā","translation_bn":"মাঝে উভয়ের","root":"بين","lemma":"بَيْن","grammar_bn":"স্থানবাচক (Location)"},{"id":34445,"position":14,"text_uthmani":"زَرْعًۭا","transliteration":"zarʿan","translation_bn":"শস্যক্ষেত্র","root":"زرع","lemma":"زَرْع","grammar_bn":"বিশেষ্য (Noun)"},{"id":34446,"position":15,"text_uthmani":"٣٢","transliteration":"","translation_bn":"(৩২)","root":"—","lemma":"٣٢","grammar_bn":"মার্কার"}]'::jsonb, 'wa-iḍ''rib lahum mathalan rajulayni jaʿalnā li-aḥadihimā jannatayni min aʿnābin waḥafafnāhumā binakhlin wajaʿalnā baynahumā zarʿan', 'তুমি তাদের কাছে দু’ব্যক্তির দৃষ্টান্ত বর্ণনা কর যাদের একজনকে আমি দিয়েছিলাম দু’টি আঙ্গুরের বাগান, আর ওগুলোকে খেজুর গাছ দিয়ে ঘিরে দিয়েছিলাম আর ও দু’টির মাঝে দিয়েছিলাম শষ্যক্ষেত।', 'And present to them an example of two men: We granted to one of them two gardens of grapevines, and We bordered them with palm trees and placed between them [fields of] crops.', 'তুমি তাদের কাছে দু’ব্যক্তির দৃষ্টান্ত বর্ণনা কর যাদের একজনকে আমি দিয়েছিলাম দু’টি আঙ্গুরের বাগান, আর ওগুলোকে খেজুর গাছ দিয়ে ঘিরে দিয়েছিলাম আর ও দু’টির মাঝে দিয়েছিলাম শষ্যক্ষেত।', 'And present to them an example of two men: We granted to one of them two gardens of grapevines, and We bordered them with palm trees and placed between them [fields of] crops.', NULL, NULL, NULL, NULL, NULL, 'https://everyayah.com/data/Alafasy_128kbps/018032.mp3', now()),
  (18, 33, '', '[{"id":35341,"position":1,"text_uthmani":"كِلْتَا","transliteration":"kil''tā","translation_bn":"উভয়","root":"كلو","lemma":"كِلْتَا","grammar_bn":"বিশেষ্য (Noun)"},{"id":35342,"position":2,"text_uthmani":"ٱلْجَنَّتَيْنِ","transliteration":"l-janatayni","translation_bn":"বাগান","root":"جنن","lemma":"جَنَّة","grammar_bn":"শব্দ"},{"id":35343,"position":3,"text_uthmani":"ءَاتَتْ","transliteration":"ātat","translation_bn":"দিতো","root":"اتي","lemma":"ا^تَى","grammar_bn":"ক্রিয়া (Verb)"},{"id":35344,"position":4,"text_uthmani":"أُكُلَهَا","transliteration":"ukulahā","translation_bn":"তার ফল","root":"اكل","lemma":"أُكُل","grammar_bn":"বিশেষ্য (Noun)"},{"id":35345,"position":5,"text_uthmani":"وَلَمْ","transliteration":"walam","translation_bn":"এবং নি","root":"—","lemma":"لَم\r","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":35346,"position":6,"text_uthmani":"تَظْلِم","transliteration":"taẓlim","translation_bn":"কম করে","root":"ظلم","lemma":"ظَلَمَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":35347,"position":7,"text_uthmani":"مِّنْهُ","transliteration":"min''hu","translation_bn":"থেকে তা","root":"—","lemma":"مِن\r","grammar_bn":"অব্যয় (Preposition)"},{"id":35348,"position":8,"text_uthmani":"شَيْـًۭٔا ۚ","transliteration":"shayan","translation_bn":"কিছু","root":"شيا","lemma":"شَىْء","grammar_bn":"বিশেষ্য (Noun)"},{"id":35350,"position":9,"text_uthmani":"وَفَجَّرْنَا","transliteration":"wafajjarnā","translation_bn":"এবং আমরা প্রবাহিত করলাম","root":"فجر","lemma":"فُجِّرَتْ","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":35351,"position":10,"text_uthmani":"خِلَـٰلَهُمَا","transliteration":"khilālahumā","translation_bn":"দু''টির ফাঁকে ফাঁকে তাদের","root":"خلل","lemma":"خِلَٰل","grammar_bn":"বিশেষ্য (Noun)"},{"id":35352,"position":11,"text_uthmani":"نَهَرًۭا","transliteration":"naharan","translation_bn":"ঝর্না","root":"نهر","lemma":"نَهَر","grammar_bn":"বিশেষ্য (Noun)"},{"id":35353,"position":12,"text_uthmani":"٣٣","transliteration":"","translation_bn":"(৩৩)","root":"—","lemma":"٣٣","grammar_bn":"মার্কার"}]'::jsonb, 'kil''tā l-janatayni ātat ukulahā walam taẓlim min''hu shayan wafajjarnā khilālahumā naharan', 'দু’টো বাগানই ফল দিত, এতে এতটুকু ত্রুটি করত না। এ দু’য়ের মাঝে আমি ঝর্ণাধারা প্রবাহিত করেছিলাম।', 'Each of the two gardens produced its fruit and did not fall short thereof in anything. And We caused to gush forth within them a river.', 'দু’টো বাগানই ফল দিত, এতে এতটুকু ত্রুটি করত না। এ দু’য়ের মাঝে আমি ঝর্ণাধারা প্রবাহিত করেছিলাম।', 'Each of the two gardens produced its fruit and did not fall short thereof in anything. And We caused to gush forth within them a river.', NULL, NULL, NULL, NULL, NULL, 'https://everyayah.com/data/Alafasy_128kbps/018033.mp3', now()),
  (18, 34, '', '[{"id":36226,"position":1,"text_uthmani":"وَكَانَ","transliteration":"wakāna","translation_bn":"এবং ছিলো","root":"كون","lemma":"كَانَ","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":36227,"position":2,"text_uthmani":"لَهُۥ","transliteration":"lahu","translation_bn":"জন্যে তার","root":"—","lemma":"لَهُۥ","grammar_bn":"অব্যয় (Preposition)"},{"id":36228,"position":3,"text_uthmani":"ثَمَرٌۭ","transliteration":"thamarun","translation_bn":"(প্রচুর) ধনসম্পদ","root":"ثمر","lemma":"ثَمَر","grammar_bn":"বিশেষ্য (Noun)"},{"id":36229,"position":4,"text_uthmani":"فَقَالَ","transliteration":"faqāla","translation_bn":"অতঃপর সে বললো","root":"قول","lemma":"قَالَ","grammar_bn":"শব্দ"},{"id":36230,"position":5,"text_uthmani":"لِصَـٰحِبِهِۦ","transliteration":"liṣāḥibihi","translation_bn":"তার সাথীকে","root":"صحب","lemma":"صَاحِب","grammar_bn":"অব্যয় (Preposition)"},{"id":36231,"position":6,"text_uthmani":"وَهُوَ","transliteration":"wahuwa","translation_bn":"এমতাবস্হায় যে, সে","root":"—","lemma":"وَهُوَ","grammar_bn":"অবস্থাবাচক (Circumstantial)"},{"id":36232,"position":7,"text_uthmani":"يُحَاوِرُهُۥٓ","transliteration":"yuḥāwiruhu","translation_bn":"তার সাথে আলোচনা করছিলো","root":"حور","lemma":"يُحَاوِرُ","grammar_bn":"ক্রিয়া (Verb)"},{"id":36233,"position":8,"text_uthmani":"أَنَا۠","transliteration":"anā","translation_bn":"\"আমি","root":"—","lemma":"أَنَا۠","grammar_bn":"সর্বনাম (Pronoun)"},{"id":36234,"position":9,"text_uthmani":"أَكْثَرُ","transliteration":"aktharu","translation_bn":"অধিকতর","root":"كثر","lemma":"أَكْثَر","grammar_bn":"বিশেষ্য (Noun)"},{"id":36235,"position":10,"text_uthmani":"مِنكَ","transliteration":"minka","translation_bn":"তোমার চেয়ে","root":"—","lemma":"مِن\r","grammar_bn":"অব্যয় (Preposition)"},{"id":36236,"position":11,"text_uthmani":"مَالًۭا","transliteration":"mālan","translation_bn":"সম্পদে","root":"مول","lemma":"مَال","grammar_bn":"বিশেষ্য (Noun)"},{"id":36237,"position":12,"text_uthmani":"وَأَعَزُّ","transliteration":"wa-aʿazzu","translation_bn":"ও অধিক শক্তিশালী","root":"عزز","lemma":"أَعَزّ","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":36238,"position":13,"text_uthmani":"نَفَرًۭا","transliteration":"nafaran","translation_bn":"জনশক্তিতে\"","root":"نفر","lemma":"نَفَر","grammar_bn":"বিশেষ্য (Noun)"},{"id":36239,"position":14,"text_uthmani":"٣٤","transliteration":"","translation_bn":"(৩৪)","root":"—","lemma":"٣٤","grammar_bn":"মার্কার"}]'::jsonb, 'wakāna lahu thamarun faqāla liṣāḥibihi wahuwa yuḥāwiruhu anā aktharu minka mālan wa-aʿazzu nafaran', 'লোকটির উৎপাদন ছিল প্রচুর। একদিন কথাবার্তা বলার সময় সে তার প্রতিবেশীকে বলল, ‘আমি সম্পদে তোমা হতে শ্রেষ্ঠ, আর জনবলে তোমা হতে শক্তিশালী।’', 'And he had fruit, so he said to his companion while he was conversing with him, "I am greater than you in wealth and mightier in [numbers of] men."', 'লোকটির উৎপাদন ছিল প্রচুর। একদিন কথাবার্তা বলার সময় সে তার প্রতিবেশীকে বলল, ‘আমি সম্পদে তোমা হতে শ্রেষ্ঠ, আর জনবলে তোমা হতে শক্তিশালী।’', 'And he had fruit, so he said to his companion while he was conversing with him, "I am greater than you in wealth and mightier in [numbers of] men."', NULL, NULL, NULL, NULL, NULL, 'https://everyayah.com/data/Alafasy_128kbps/018034.mp3', now()),
  (18, 35, '', '[{"id":37000,"position":1,"text_uthmani":"وَدَخَلَ","transliteration":"wadakhala","translation_bn":"এবং প্রবেশ করলো","root":"دخل","lemma":"دَخَلَ","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":37001,"position":2,"text_uthmani":"جَنَّتَهُۥ","transliteration":"jannatahu","translation_bn":"তার বাগানে","root":"جنن","lemma":"جَنَّة","grammar_bn":"বিশেষ্য (Noun)"},{"id":37002,"position":3,"text_uthmani":"وَهُوَ","transliteration":"wahuwa","translation_bn":"এবং এ অবস্থায় যে সে ছিলো","root":"—","lemma":"وَهُوَ","grammar_bn":"অবস্থাবাচক (Circumstantial)"},{"id":37003,"position":4,"text_uthmani":"ظَالِمٌۭ","transliteration":"ẓālimun","translation_bn":"সীমালঙ্ঘনকারী","root":"ظلم","lemma":"ظَالِم","grammar_bn":"বিশেষ্য (Noun)"},{"id":37004,"position":5,"text_uthmani":"لِّنَفْسِهِۦ","transliteration":"linafsihi","translation_bn":"উপর তার নিজের","root":"نفس","lemma":"نَفْس","grammar_bn":"অব্যয় (Preposition)"},{"id":37005,"position":6,"text_uthmani":"قَالَ","transliteration":"qāla","translation_bn":"সে বললো","root":"قول","lemma":"قَالَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":37006,"position":7,"text_uthmani":"مَآ","transliteration":"mā","translation_bn":"\"না","root":"—","lemma":"مَا\r","grammar_bn":"না-বোধক (Negative)"},{"id":37007,"position":8,"text_uthmani":"أَظُنُّ","transliteration":"aẓunnu","translation_bn":"আমি মনে করি","root":"ظنن","lemma":"ظَنَّ","grammar_bn":"ক্রিয়া (Verb)"},{"id":37008,"position":9,"text_uthmani":"أَن","transliteration":"an","translation_bn":"যে","root":"—","lemma":"أَن\r","grammar_bn":"অধীনস্থ যোজক (Subordinating)"},{"id":37009,"position":10,"text_uthmani":"تَبِيدَ","transliteration":"tabīda","translation_bn":"ধ্বংস হবে","root":"بيد","lemma":"تَبِيدَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":37010,"position":11,"text_uthmani":"هَـٰذِهِۦٓ","transliteration":"hādhihi","translation_bn":"এই (সম্পদ)","root":"—","lemma":"هَٰذَا","grammar_bn":"নির্দেশক সর্বনাম (Demonstrative)"},{"id":37011,"position":12,"text_uthmani":"أَبَدًۭا","transliteration":"abadan","translation_bn":"কখনও","root":"ابد","lemma":"أَبَدًا","grammar_bn":"কালবাচক (Time)"},{"id":37012,"position":13,"text_uthmani":"٣٥","transliteration":"","translation_bn":"(৩৫)","root":"—","lemma":"٣٥","grammar_bn":"মার্কার"}]'::jsonb, 'wadakhala jannatahu wahuwa ẓālimun linafsihi qāla mā aẓunnu an tabīda hādhihi abadan', 'নিজের প্রতি যুলম করে সে তার বাগানে প্রবেশ করল। সে বলল, ‘আমি ধারণা করি না যে, এটা কোনদিন ধ্বংস হয়ে যাবে।', 'And he entered his garden while he was unjust to himself. He said, "I do not think that this will perish - ever.', 'নিজের প্রতি যুলম করে সে তার বাগানে প্রবেশ করল। সে বলল, ‘আমি ধারণা করি না যে, এটা কোনদিন ধ্বংস হয়ে যাবে।', 'And he entered his garden while he was unjust to himself. He said, "I do not think that this will perish - ever.', NULL, NULL, NULL, NULL, NULL, 'https://everyayah.com/data/Alafasy_128kbps/018035.mp3', now()),
  (18, 36, '', '[{"id":37847,"position":1,"text_uthmani":"وَمَآ","transliteration":"wamā","translation_bn":"এবং না","root":"—","lemma":"مَا\r","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":37848,"position":2,"text_uthmani":"أَظُنُّ","transliteration":"aẓunnu","translation_bn":"আমি মনে করি","root":"ظنن","lemma":"ظَنَّ","grammar_bn":"ক্রিয়া (Verb)"},{"id":37849,"position":3,"text_uthmani":"ٱلسَّاعَةَ","transliteration":"l-sāʿata","translation_bn":"ক্বিয়ামাত","root":"سوع","lemma":"سَاعَة","grammar_bn":"শব্দ"},{"id":37850,"position":4,"text_uthmani":"قَآئِمَةًۭ","transliteration":"qāimatan","translation_bn":"সংঘটিত হবে","root":"قوم","lemma":"قَا^ئِمَة","grammar_bn":"বিশেষ্য (Noun)"},{"id":37851,"position":5,"text_uthmani":"وَلَئِن","transliteration":"wala-in","translation_bn":"এবং অবশ্যই যদি","root":"—","lemma":"إِن\r","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":37852,"position":6,"text_uthmani":"رُّدِدتُّ","transliteration":"rudidttu","translation_bn":"আমি প্রত্যাবর্তিত হই","root":"ردد","lemma":"رَدَّ","grammar_bn":"ক্রিয়া (Verb)"},{"id":37853,"position":7,"text_uthmani":"إِلَىٰ","transliteration":"ilā","translation_bn":"দিকে","root":"—","lemma":"إِلَىٰ\r","grammar_bn":"অব্যয় (Preposition)"},{"id":37854,"position":8,"text_uthmani":"رَبِّى","transliteration":"rabbī","translation_bn":"আমার রবের","root":"ربب","lemma":"رَبّ","grammar_bn":"বিশেষ্য (Noun)"},{"id":37855,"position":9,"text_uthmani":"لَأَجِدَنَّ","transliteration":"la-ajidanna","translation_bn":"অবশ্যই আমি পাবো","root":"وجد","lemma":"وَجَدَ","grammar_bn":"দৃঢ়তাবোধক (Emphatic)"},{"id":37856,"position":10,"text_uthmani":"خَيْرًۭا","transliteration":"khayran","translation_bn":"উত্তম","root":"خير","lemma":"خَيْر","grammar_bn":"বিশেষ্য (Noun)"},{"id":37857,"position":11,"text_uthmani":"مِّنْهَا","transliteration":"min''hā","translation_bn":"তাদের দু''টির চেয়েও","root":"—","lemma":"مِن\r","grammar_bn":"অব্যয় (Preposition)"},{"id":37858,"position":12,"text_uthmani":"مُنقَلَبًۭا","transliteration":"munqalaban","translation_bn":"প্রত্যাবর্তনস্থান\"","root":"قلب","lemma":"مُنقَلَب","grammar_bn":"বিশেষ্য (Noun)"},{"id":37859,"position":13,"text_uthmani":"٣٦","transliteration":"","translation_bn":"(৩৬)","root":"—","lemma":"٣٦","grammar_bn":"মার্কার"}]'::jsonb, 'wamā aẓunnu l-sāʿata qāimatan wala-in rudidttu ilā rabbī la-ajidanna khayran min''hā munqalaban', 'আমি মনে করি না যে কিয়ামাত হবে। আর যদি আমাকে আমার প্রতিপালকের কাছে ফিরিয়ে নেয়া হয়ই, তাহলে অবশ্য অবশ্যই আমি পরিবর্তে আরো উৎকৃষ্ট স্থান পাব।', 'And I do not think the Hour will occur. And even if I should be brought back to my Lord, I will surely find better than this as a return."', 'আমি মনে করি না যে কিয়ামাত হবে। আর যদি আমাকে আমার প্রতিপালকের কাছে ফিরিয়ে নেয়া হয়ই, তাহলে অবশ্য অবশ্যই আমি পরিবর্তে আরো উৎকৃষ্ট স্থান পাব।', 'And I do not think the Hour will occur. And even if I should be brought back to my Lord, I will surely find better than this as a return."', NULL, NULL, NULL, NULL, NULL, 'https://everyayah.com/data/Alafasy_128kbps/018036.mp3', now()),
  (18, 37, '', '[{"id":38710,"position":1,"text_uthmani":"قَالَ","transliteration":"qāla","translation_bn":"বললো","root":"قول","lemma":"قَالَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":38711,"position":2,"text_uthmani":"لَهُۥ","transliteration":"lahu","translation_bn":"তাকে","root":"—","lemma":"لَهُۥ","grammar_bn":"অব্যয় (Preposition)"},{"id":38712,"position":3,"text_uthmani":"صَاحِبُهُۥ","transliteration":"ṣāḥibuhu","translation_bn":"তার সাথী","root":"صحب","lemma":"صَاحِب","grammar_bn":"বিশেষ্য (Noun)"},{"id":38713,"position":4,"text_uthmani":"وَهُوَ","transliteration":"wahuwa","translation_bn":"এমতাবস্হায় যে সে","root":"—","lemma":"وَهُوَ","grammar_bn":"অবস্থাবাচক (Circumstantial)"},{"id":38714,"position":5,"text_uthmani":"يُحَاوِرُهُۥٓ","transliteration":"yuḥāwiruhu","translation_bn":"তার সাথে আলোচনা করেছিলো","root":"حور","lemma":"يُحَاوِرُ","grammar_bn":"ক্রিয়া (Verb)"},{"id":38715,"position":6,"text_uthmani":"أَكَفَرْتَ","transliteration":"akafarta","translation_bn":"\"কি তুমি অস্বীকার করছো","root":"كفر","lemma":"كَفَرَ","grammar_bn":"প্রশ্নবোধক (Interrogative)"},{"id":38716,"position":7,"text_uthmani":"بِٱلَّذِى","transliteration":"bi-alladhī","translation_bn":"(ঐ সত্ত্বা) কে যিনি","root":"—","lemma":"ٱلَّذِى","grammar_bn":"অব্যয় (Preposition)"},{"id":38717,"position":8,"text_uthmani":"خَلَقَكَ","transliteration":"khalaqaka","translation_bn":"তোমাকে সৃষ্টি করেছেন","root":"خلق","lemma":"خَلَقَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":38718,"position":9,"text_uthmani":"مِن","transliteration":"min","translation_bn":"থেকে","root":"—","lemma":"مِن\r","grammar_bn":"অব্যয় (Preposition)"},{"id":38719,"position":10,"text_uthmani":"تُرَابٍۢ","transliteration":"turābin","translation_bn":"মাটি","root":"ترب","lemma":"تُرَاب","grammar_bn":"বিশেষ্য (Noun)"},{"id":38720,"position":11,"text_uthmani":"ثُمَّ","transliteration":"thumma","translation_bn":"এরপর","root":"—","lemma":"ثُمّ\r","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":38721,"position":12,"text_uthmani":"مِن","transliteration":"min","translation_bn":"থেকে","root":"—","lemma":"مِن\r","grammar_bn":"অব্যয় (Preposition)"},{"id":38722,"position":13,"text_uthmani":"نُّطْفَةٍۢ","transliteration":"nuṭ''fatin","translation_bn":"শুক্র","root":"نطف","lemma":"نُّطْفَة","grammar_bn":"বিশেষ্য (Noun)"},{"id":38723,"position":14,"text_uthmani":"ثُمَّ","transliteration":"thumma","translation_bn":"এরপর","root":"—","lemma":"ثُمّ\r","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":38724,"position":15,"text_uthmani":"سَوَّىٰكَ","transliteration":"sawwāka","translation_bn":"তোমাকে সম্পূর্ণ করেছেন","root":"سوي","lemma":"سَوَّىٰ","grammar_bn":"ক্রিয়া (Verb)"},{"id":38725,"position":16,"text_uthmani":"رَجُلًۭا","transliteration":"rajulan","translation_bn":"মানুষে","root":"رجل","lemma":"رَجُل","grammar_bn":"বিশেষ্য (Noun)"},{"id":38726,"position":17,"text_uthmani":"٣٧","transliteration":"","translation_bn":"(৩৭)","root":"—","lemma":"٣٧","grammar_bn":"মার্কার"}]'::jsonb, 'qāla lahu ṣāḥibuhu wahuwa yuḥāwiruhu akafarta bi-alladhī khalaqaka min turābin thumma min nuṭ''fatin thumma sawwāka rajulan', 'কথার প্রসঙ্গ টেনে তার সাথী বলল, ‘তুমি কি তাঁকে অস্বীকার করছ যিনি তোমাকে মাটি থেকে সৃষ্টি করেছেন, অতঃপর শুক্র-কীট হতে, অতঃপর তোমাকে পূর্ণাঙ্গ দেহসম্পন্ন মানুষ বানিয়ে দিয়েছেন?', 'His companion said to him while he was conversing with him, "Have you disbelieved in He who created you from dust and then from a sperm-drop and then proportioned you [as] a man?', 'কথার প্রসঙ্গ টেনে তার সাথী বলল, ‘তুমি কি তাঁকে অস্বীকার করছ যিনি তোমাকে মাটি থেকে সৃষ্টি করেছেন, অতঃপর শুক্র-কীট হতে, অতঃপর তোমাকে পূর্ণাঙ্গ দেহসম্পন্ন মানুষ বানিয়ে দিয়েছেন?', 'His companion said to him while he was conversing with him, "Have you disbelieved in He who created you from dust and then from a sperm-drop and then proportioned you [as] a man?', NULL, NULL, NULL, NULL, NULL, 'https://everyayah.com/data/Alafasy_128kbps/018037.mp3', now()),
  (18, 38, '', '[{"id":40212,"position":1,"text_uthmani":"لَّـٰكِنَّا۠","transliteration":"lākinnā","translation_bn":"কিন্তু (আমি বলি)","root":"—","lemma":"لَٰكِن","grammar_bn":"অভিঘাত পদ (Accusative)"},{"id":40213,"position":2,"text_uthmani":"هُوَ","transliteration":"huwa","translation_bn":"তিনি","root":"—","lemma":"هُوَ","grammar_bn":"সর্বনাম (Pronoun)"},{"id":40214,"position":3,"text_uthmani":"ٱللَّهُ","transliteration":"l-lahu","translation_bn":"আল্লাহ্‌","root":"اله","lemma":"ٱللَّه","grammar_bn":"নামবাচক বিশেষ্য (Proper Noun)"},{"id":40215,"position":4,"text_uthmani":"رَبِّى","transliteration":"rabbī","translation_bn":"আমার রব","root":"ربب","lemma":"رَبّ","grammar_bn":"বিশেষ্য (Noun)"},{"id":40216,"position":5,"text_uthmani":"وَلَآ","transliteration":"walā","translation_bn":"এবং না","root":"—","lemma":"لَا\r","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":40217,"position":6,"text_uthmani":"أُشْرِكُ","transliteration":"ush''riku","translation_bn":"শরিক করি আমি","root":"شرك","lemma":"أَشْرَكَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":40218,"position":7,"text_uthmani":"بِرَبِّىٓ","transliteration":"birabbī","translation_bn":"সাথে আমার রবের","root":"ربب","lemma":"رَبّ","grammar_bn":"অব্যয় (Preposition)"},{"id":40219,"position":8,"text_uthmani":"أَحَدًۭا","transliteration":"aḥadan","translation_bn":"কাউকে","root":"احد","lemma":"أَحَد","grammar_bn":"বিশেষ্য (Noun)"},{"id":40220,"position":9,"text_uthmani":"٣٨","transliteration":"","translation_bn":"(৩৮)","root":"—","lemma":"٣٨","grammar_bn":"মার্কার"}]'::jsonb, 'lākinnā huwa l-lahu rabbī walā ush''riku birabbī aḥadan', '(আর আমার ব্যাপারে কথা হল) সেই আল্লাহই আমার প্রতিপালক, আমি কাউকে আমার প্রতিপালকের শরীক করব না।', 'But as for me, He is Allah, my Lord, and I do not associate with my Lord anyone.', '(আর আমার ব্যাপারে কথা হল) সেই আল্লাহই আমার প্রতিপালক, আমি কাউকে আমার প্রতিপালকের শরীক করব না।', 'But as for me, He is Allah, my Lord, and I do not associate with my Lord anyone.', NULL, NULL, NULL, NULL, NULL, 'https://everyayah.com/data/Alafasy_128kbps/018038.mp3', now()),
  (18, 39, '', '[{"id":40398,"position":1,"text_uthmani":"وَلَوْلَآ","transliteration":"walawlā","translation_bn":"এবং কেন না","root":"—","lemma":"لَوْلَا^\r","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":40399,"position":2,"text_uthmani":"إِذْ","transliteration":"idh","translation_bn":"যখন","root":"—","lemma":"إِذ\r","grammar_bn":"কালবাচক (Time)"},{"id":40400,"position":3,"text_uthmani":"دَخَلْتَ","transliteration":"dakhalta","translation_bn":"তুমি প্রবেশ করছিলে","root":"دخل","lemma":"دَخَلَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":40401,"position":4,"text_uthmani":"جَنَّتَكَ","transliteration":"jannataka","translation_bn":"তোমার বাগানে","root":"جنن","lemma":"جَنَّة","grammar_bn":"বিশেষ্য (Noun)"},{"id":40402,"position":5,"text_uthmani":"قُلْتَ","transliteration":"qul''ta","translation_bn":"তুমি বলেছিলে","root":"قول","lemma":"قَالَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":40403,"position":6,"text_uthmani":"مَا","transliteration":"mā","translation_bn":"\"যা","root":"—","lemma":"مَا\r","grammar_bn":"সাপেক্ষ সর্বনাম (Relative)"},{"id":40404,"position":7,"text_uthmani":"شَآءَ","transliteration":"shāa","translation_bn":"চেয়েছেন","root":"شيا","lemma":"شَا^ءَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":40405,"position":8,"text_uthmani":"ٱللَّهُ","transliteration":"l-lahu","translation_bn":"আল্লাহ্‌ (তাই হয়েছে)","root":"اله","lemma":"ٱللَّه","grammar_bn":"নামবাচক বিশেষ্য (Proper Noun)"},{"id":40406,"position":9,"text_uthmani":"لَا","transliteration":"lā","translation_bn":"নেই","root":"—","lemma":"لَا\r","grammar_bn":"না-বোধক (Negative)"},{"id":40407,"position":10,"text_uthmani":"قُوَّةَ","transliteration":"quwwata","translation_bn":"কোনো শক্তি","root":"قوي","lemma":"قُوَّة","grammar_bn":"বিশেষ্য (Noun)"},{"id":40408,"position":11,"text_uthmani":"إِلَّا","transliteration":"illā","translation_bn":"ছাড়া","root":"—","lemma":"إِلَّا\r","grammar_bn":"সীমাবদ্ধতা (Restriction)"},{"id":40409,"position":12,"text_uthmani":"بِٱللَّهِ ۚ","transliteration":"bil-lahi","translation_bn":"আল্লাহ্‌\"","root":"اله","lemma":"ٱللَّه","grammar_bn":"অব্যয় (Preposition)"},{"id":40411,"position":13,"text_uthmani":"إِن","transliteration":"in","translation_bn":"যদি","root":"—","lemma":"إِن\r","grammar_bn":"শর্তবাচক (Conditional)"},{"id":40412,"position":14,"text_uthmani":"تَرَنِ","transliteration":"tarani","translation_bn":"আমাকে দেখো","root":"راي","lemma":"رَءَا","grammar_bn":"ক্রিয়া (Verb)"},{"id":40413,"position":15,"text_uthmani":"أَنَا۠","transliteration":"anā","translation_bn":"আমি","root":"—","lemma":"أَنَا۠","grammar_bn":"সর্বনাম (Pronoun)"},{"id":40414,"position":16,"text_uthmani":"أَقَلَّ","transliteration":"aqalla","translation_bn":"স্বল্পতর","root":"قلل","lemma":"أَقَلّ","grammar_bn":"বিশেষ্য (Noun)"},{"id":40415,"position":17,"text_uthmani":"مِنكَ","transliteration":"minka","translation_bn":"তোমার চেয়ে","root":"—","lemma":"مِن\r","grammar_bn":"অব্যয় (Preposition)"},{"id":40416,"position":18,"text_uthmani":"مَالًۭا","transliteration":"mālan","translation_bn":"সম্পদে","root":"مول","lemma":"مَال","grammar_bn":"বিশেষ্য (Noun)"},{"id":40417,"position":19,"text_uthmani":"وَوَلَدًۭا","transliteration":"wawaladan","translation_bn":"এবং সন্তানে","root":"ولد","lemma":"وَلَد","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":40418,"position":20,"text_uthmani":"٣٩","transliteration":"","translation_bn":"(৩৯)","root":"—","lemma":"٣٩","grammar_bn":"মার্কার"}]'::jsonb, 'walawlā idh dakhalta jannataka qul''ta mā shāa l-lahu lā quwwata illā bil-lahi in tarani anā aqalla minka mālan wawaladan', 'তুমি যখন তোমার বাগানে প্রবেশ করলে তখন কেন বললে না, ‘আল্লাহ যা ইচ্ছে করেছেন (তা-ই হয়েছে), আল্লাহ ছাড়া কারো কোন শক্তি নেই। যদিও তুমি আমাকে ধনে-জনে তোমার চেয়ে কম দেখ,', 'And why did you, when you entered your garden, not say, ''What Allah willed [has occurred]; there is no power except in Allah ''? Although you see me less than you in wealth and children,', 'তুমি যখন তোমার বাগানে প্রবেশ করলে তখন কেন বললে না, ‘আল্লাহ যা ইচ্ছে করেছেন (তা-ই হয়েছে), আল্লাহ ছাড়া কারো কোন শক্তি নেই। যদিও তুমি আমাকে ধনে-জনে তোমার চেয়ে কম দেখ,', 'And why did you, when you entered your garden, not say, ''What Allah willed [has occurred]; there is no power except in Allah ''? Although you see me less than you in wealth and children,', NULL, NULL, NULL, NULL, NULL, 'https://everyayah.com/data/Alafasy_128kbps/018039.mp3', now()),
  (18, 40, '', '[{"id":41663,"position":1,"text_uthmani":"فَعَسَىٰ","transliteration":"faʿasā","translation_bn":"তবে হয়তো","root":"عسي","lemma":"عَسَى","grammar_bn":"শব্দ"},{"id":41664,"position":2,"text_uthmani":"رَبِّىٓ","transliteration":"rabbī","translation_bn":"আমার রব","root":"ربب","lemma":"رَبّ","grammar_bn":"বিশেষ্য (Noun)"},{"id":41665,"position":3,"text_uthmani":"أَن","transliteration":"an","translation_bn":"যে","root":"—","lemma":"أَن\r","grammar_bn":"অধীনস্থ যোজক (Subordinating)"},{"id":41666,"position":4,"text_uthmani":"يُؤْتِيَنِ","transliteration":"yu''tiyani","translation_bn":"আমাকে দান করবেন","root":"اتي","lemma":"ا^تَى","grammar_bn":"ক্রিয়া (Verb)"},{"id":41667,"position":5,"text_uthmani":"خَيْرًۭا","transliteration":"khayran","translation_bn":"উত্তম","root":"خير","lemma":"خَيْر","grammar_bn":"বিশেষ্য (Noun)"},{"id":41668,"position":6,"text_uthmani":"مِّن","transliteration":"min","translation_bn":"থেকে","root":"—","lemma":"مِن\r","grammar_bn":"অব্যয় (Preposition)"},{"id":41669,"position":7,"text_uthmani":"جَنَّتِكَ","transliteration":"jannatika","translation_bn":"তোমার বাগান","root":"جنن","lemma":"جَنَّة","grammar_bn":"বিশেষ্য (Noun)"},{"id":41670,"position":8,"text_uthmani":"وَيُرْسِلَ","transliteration":"wayur''sila","translation_bn":"এবং প্রেরণ করবেন","root":"رسل","lemma":"أَرْسَلَ","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":41671,"position":9,"text_uthmani":"عَلَيْهَا","transliteration":"ʿalayhā","translation_bn":"উপর তার","root":"—","lemma":"عَلَىٰ\r","grammar_bn":"অব্যয় (Preposition)"},{"id":41672,"position":10,"text_uthmani":"حُسْبَانًۭا","transliteration":"ḥus''bānan","translation_bn":"বিপর্যয়","root":"حسب","lemma":"حُسْبَان","grammar_bn":"বিশেষ্য (Noun)"},{"id":41673,"position":11,"text_uthmani":"مِّنَ","transliteration":"mina","translation_bn":"থেকে","root":"—","lemma":"مِن\r","grammar_bn":"অব্যয় (Preposition)"},{"id":41674,"position":12,"text_uthmani":"ٱلسَّمَآءِ","transliteration":"l-samāi","translation_bn":"আকাশ","root":"سمو","lemma":"سَمَا^ء","grammar_bn":"শব্দ"},{"id":41675,"position":13,"text_uthmani":"فَتُصْبِحَ","transliteration":"fatuṣ''biḥa","translation_bn":"অতঃপর তা হয়ে যাবে","root":"صبح","lemma":"أَصْبَحَ","grammar_bn":"শব্দ"},{"id":41676,"position":14,"text_uthmani":"صَعِيدًۭا","transliteration":"ṣaʿīdan","translation_bn":"মাটি","root":"صعد","lemma":"صَعِيد","grammar_bn":"বিশেষ্য (Noun)"},{"id":41677,"position":15,"text_uthmani":"زَلَقًا","transliteration":"zalaqan","translation_bn":"উদ্ভিদশূন্য","root":"زلق","lemma":"زَلَق","grammar_bn":"বিশেষ্য (Noun)"},{"id":41678,"position":16,"text_uthmani":"٤٠","transliteration":"","translation_bn":"(৪০)","root":"—","lemma":"٤٠","grammar_bn":"মার্কার"}]'::jsonb, 'faʿasā rabbī an yu''tiyani khayran min jannatika wayur''sila ʿalayhā ḥus''bānan mina l-samāi fatuṣ''biḥa ṣaʿīdan zalaqan', 'সম্ভবতঃ আমার প্রতিপালক আমাকে তোমার বাগান অপেক্ষাও উত্তম কিছু দান করবেন আর তোমার বাগানের উপর আসমান হতে কোন বিপদ পাঠিয়ে দিবেন, ফলে তা শূন্য ময়দানে পরিণত হবে।', 'It may be that my Lord will give me [something] better than your garden and will send upon it a calamity from the sky, and it will become a smooth, dusty ground,', 'সম্ভবতঃ আমার প্রতিপালক আমাকে তোমার বাগান অপেক্ষাও উত্তম কিছু দান করবেন আর তোমার বাগানের উপর আসমান হতে কোন বিপদ পাঠিয়ে দিবেন, ফলে তা শূন্য ময়দানে পরিণত হবে।', 'It may be that my Lord will give me [something] better than your garden and will send upon it a calamity from the sky, and it will become a smooth, dusty ground,', NULL, NULL, NULL, NULL, NULL, 'https://everyayah.com/data/Alafasy_128kbps/018040.mp3', now()),
  (18, 41, '', '[{"id":42027,"position":1,"text_uthmani":"أَوْ","transliteration":"aw","translation_bn":"অথবা","root":"—","lemma":"أَو\r","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":42028,"position":2,"text_uthmani":"يُصْبِحَ","transliteration":"yuṣ''biḥa","translation_bn":"হয়ে যাবে","root":"صبح","lemma":"أَصْبَحَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":42029,"position":3,"text_uthmani":"مَآؤُهَا","transliteration":"māuhā","translation_bn":"তার পানি","root":"موه","lemma":"مَا^ء","grammar_bn":"বিশেষ্য (Noun)"},{"id":42030,"position":4,"text_uthmani":"غَوْرًۭا","transliteration":"ghawran","translation_bn":"শুষ্ক","root":"غور","lemma":"غَوْر","grammar_bn":"বিশেষ্য (Noun)"},{"id":42031,"position":5,"text_uthmani":"فَلَن","transliteration":"falan","translation_bn":"অতঃপর কখনও না","root":"—","lemma":"لَن\r","grammar_bn":"শব্দ"},{"id":42032,"position":6,"text_uthmani":"تَسْتَطِيعَ","transliteration":"tastaṭīʿa","translation_bn":"তুমি সক্ষম হবে","root":"طوع","lemma":"ٱسْتَطَاعَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":42033,"position":7,"text_uthmani":"لَهُۥ","transliteration":"lahu","translation_bn":"জন্যে তার\"","root":"—","lemma":"لَهُۥ","grammar_bn":"অব্যয় (Preposition)"},{"id":42034,"position":8,"text_uthmani":"طَلَبًۭا","transliteration":"ṭalaban","translation_bn":"খুঁজে বের করতে\"","root":"طلب","lemma":"طَلَب","grammar_bn":"বিশেষ্য (Noun)"},{"id":42035,"position":9,"text_uthmani":"٤١","transliteration":"","translation_bn":"(৪১)","root":"—","lemma":"٤١","grammar_bn":"মার্কার"}]'::jsonb, 'aw yuṣ''biḥa māuhā ghawran falan tastaṭīʿa lahu ṭalaban', 'কিংবা তার পানি ভূ-গর্ভে চলে যাবে, ফলে তুমি কক্ষনো তার খোঁজ পাবে না।’', 'Or its water will become sunken [into the earth], so you would never be able to seek it."', 'কিংবা তার পানি ভূ-গর্ভে চলে যাবে, ফলে তুমি কক্ষনো তার খোঁজ পাবে না।’', 'Or its water will become sunken [into the earth], so you would never be able to seek it."', NULL, NULL, NULL, NULL, NULL, 'https://everyayah.com/data/Alafasy_128kbps/018041.mp3', now()),
  (18, 42, '', '[{"id":42762,"position":1,"text_uthmani":"وَأُحِيطَ","transliteration":"wa-uḥīṭa","translation_bn":"এবং (বিপর্যয়ে) পরিবেষ্টিত হলো","root":"حوط","lemma":"أَحَاطَ","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":42763,"position":2,"text_uthmani":"بِثَمَرِهِۦ","transliteration":"bithamarihi","translation_bn":"সহ তার ফল","root":"ثمر","lemma":"ثَمَر","grammar_bn":"অব্যয় (Preposition)"},{"id":42764,"position":3,"text_uthmani":"فَأَصْبَحَ","transliteration":"fa-aṣbaḥa","translation_bn":"ফলে সে শুরু করলো","root":"صبح","lemma":"أَصْبَحَ","grammar_bn":"শব্দ"},{"id":42765,"position":4,"text_uthmani":"يُقَلِّبُ","transliteration":"yuqallibu","translation_bn":"মুচড়াতে","root":"قلب","lemma":"قَلَّبُ","grammar_bn":"ক্রিয়া (Verb)"},{"id":42766,"position":5,"text_uthmani":"كَفَّيْهِ","transliteration":"kaffayhi","translation_bn":"দু''হাত তার","root":"كفف","lemma":"كَفَّي","grammar_bn":"বিশেষ্য (Noun)"},{"id":42767,"position":6,"text_uthmani":"عَلَىٰ","transliteration":"ʿalā","translation_bn":"এর উপর","root":"—","lemma":"عَلَىٰ\r","grammar_bn":"অব্যয় (Preposition)"},{"id":42768,"position":7,"text_uthmani":"مَآ","transliteration":"mā","translation_bn":"যা","root":"—","lemma":"مَا\r","grammar_bn":"সাপেক্ষ সর্বনাম (Relative)"},{"id":42769,"position":8,"text_uthmani":"أَنفَقَ","transliteration":"anfaqa","translation_bn":"সে খরচ করেছে","root":"نفق","lemma":"أَنفَقَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":42770,"position":9,"text_uthmani":"فِيهَا","transliteration":"fīhā","translation_bn":"মধ্যে তার","root":"—","lemma":"فِى\r","grammar_bn":"অব্যয় (Preposition)"},{"id":42771,"position":10,"text_uthmani":"وَهِىَ","transliteration":"wahiya","translation_bn":"এবং তা","root":"—","lemma":"وَهِىَ","grammar_bn":"অবস্থাবাচক (Circumstantial)"},{"id":42772,"position":11,"text_uthmani":"خَاوِيَةٌ","transliteration":"khāwiyatun","translation_bn":"উল্টে পড়েছিলো","root":"خوي","lemma":"خَاوِيَة","grammar_bn":"বিশেষ্য (Noun)"},{"id":42773,"position":12,"text_uthmani":"عَلَىٰ","transliteration":"ʿalā","translation_bn":"উপর","root":"—","lemma":"عَلَىٰ\r","grammar_bn":"অব্যয় (Preposition)"},{"id":42774,"position":13,"text_uthmani":"عُرُوشِهَا","transliteration":"ʿurūshihā","translation_bn":"তার মাচাগুলোর","root":"عرش","lemma":"عَرْش","grammar_bn":"বিশেষ্য (Noun)"},{"id":42775,"position":14,"text_uthmani":"وَيَقُولُ","transliteration":"wayaqūlu","translation_bn":"এবং সে বললো","root":"قول","lemma":"قَالَ","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":42776,"position":15,"text_uthmani":"يَـٰلَيْتَنِى","transliteration":"yālaytanī","translation_bn":"\"হায় (যদি)","root":"—","lemma":"لَيْت","grammar_bn":"সম্বোধন পদ (Vocative)"},{"id":42777,"position":16,"text_uthmani":"لَمْ","transliteration":"lam","translation_bn":"না","root":"—","lemma":"لَم\r","grammar_bn":"না-বোধক (Negative)"},{"id":42778,"position":17,"text_uthmani":"أُشْرِكْ","transliteration":"ush''rik","translation_bn":"আমি শরিক করতাম","root":"شرك","lemma":"أَشْرَكَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":42779,"position":18,"text_uthmani":"بِرَبِّىٓ","transliteration":"birabbī","translation_bn":"সাথে আমার রবের","root":"ربب","lemma":"رَبّ","grammar_bn":"অব্যয় (Preposition)"},{"id":42780,"position":19,"text_uthmani":"أَحَدًۭا","transliteration":"aḥadan","translation_bn":"অন্য কাউকে\"","root":"احد","lemma":"أَحَد","grammar_bn":"বিশেষ্য (Noun)"},{"id":42781,"position":20,"text_uthmani":"٤٢","transliteration":"","translation_bn":"(৪২)","root":"—","lemma":"٤٢","grammar_bn":"মার্কার"}]'::jsonb, 'wa-uḥīṭa bithamarihi fa-aṣbaḥa yuqallibu kaffayhi ʿalā mā anfaqa fīhā wahiya khāwiyatun ʿalā ʿurūshihā wayaqūlu yālaytanī lam ush''rik birabbī aḥadan', 'ধ্বংস তার ফল-ফসলকে ঘিরে ফেলল আর তাতে সে যা খরচ করেছিল তার জন্য হাত মলতে লাগল। তা ছিন্ন ভিন্ন অবস্থায় ভূমিসাৎ হয়ে গিয়েছিল। সে বলল, ‘হায়, আমি যদি আমার রব্ব-এর সাথে কাউকে শরীক না করতাম!’', 'And his fruits were encompassed [by ruin], so he began to turn his hands about [in dismay] over what he had spent on it, while it had collapsed upon its trellises, and said, "Oh, I wish I had not associated with my Lord anyone."', 'ধ্বংস তার ফল-ফসলকে ঘিরে ফেলল আর তাতে সে যা খরচ করেছিল তার জন্য হাত মলতে লাগল। তা ছিন্ন ভিন্ন অবস্থায় ভূমিসাৎ হয়ে গিয়েছিল। সে বলল, ‘হায়, আমি যদি আমার রব্ব-এর সাথে কাউকে শরীক না করতাম!’', 'And his fruits were encompassed [by ruin], so he began to turn his hands about [in dismay] over what he had spent on it, while it had collapsed upon its trellises, and said, "Oh, I wish I had not associated with my Lord anyone."', NULL, NULL, NULL, NULL, NULL, 'https://everyayah.com/data/Alafasy_128kbps/018042.mp3', now()),
  (18, 43, '', '[{"id":43556,"position":1,"text_uthmani":"وَلَمْ","transliteration":"walam","translation_bn":"এবং না","root":"—","lemma":"لَم\r","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":43557,"position":2,"text_uthmani":"تَكُن","transliteration":"takun","translation_bn":"ছিলো","root":"كون","lemma":"كَانَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":43558,"position":3,"text_uthmani":"لَّهُۥ","transliteration":"lahu","translation_bn":"জন্যে তার","root":"—","lemma":"لَّهُۥ","grammar_bn":"অব্যয় (Preposition)"},{"id":43559,"position":4,"text_uthmani":"فِئَةٌۭ","transliteration":"fi-atun","translation_bn":"কোনো দল","root":"فاي","lemma":"فِئَة","grammar_bn":"বিশেষ্য (Noun)"},{"id":43560,"position":5,"text_uthmani":"يَنصُرُونَهُۥ","transliteration":"yanṣurūnahu","translation_bn":"তাকে তারা সাহায্য করবে","root":"نصر","lemma":"نَصَرَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":43561,"position":6,"text_uthmani":"مِن","transliteration":"min","translation_bn":"থেকে","root":"—","lemma":"مِن\r","grammar_bn":"অব্যয় (Preposition)"},{"id":43562,"position":7,"text_uthmani":"دُونِ","transliteration":"dūni","translation_bn":"ছাড়া","root":"دون","lemma":"دُون","grammar_bn":"বিশেষ্য (Noun)"},{"id":43563,"position":8,"text_uthmani":"ٱللَّهِ","transliteration":"l-lahi","translation_bn":"আল্লাহ্‌","root":"اله","lemma":"ٱللَّه","grammar_bn":"নামবাচক বিশেষ্য (Proper Noun)"},{"id":43564,"position":9,"text_uthmani":"وَمَا","transliteration":"wamā","translation_bn":"আর না","root":"—","lemma":"مَا\r","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":43565,"position":10,"text_uthmani":"كَانَ","transliteration":"kāna","translation_bn":"সে ছিলো","root":"كون","lemma":"كَانَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":43566,"position":11,"text_uthmani":"مُنتَصِرًا","transliteration":"muntaṣiran","translation_bn":"প্রতিরোধকারী","root":"نصر","lemma":"مُّنتَصِر","grammar_bn":"বিশেষ্য (Noun)"},{"id":43567,"position":12,"text_uthmani":"٤٣","transliteration":"","translation_bn":"(৪৩)","root":"—","lemma":"٤٣","grammar_bn":"মার্কার"}]'::jsonb, 'walam takun lahu fi-atun yanṣurūnahu min dūni l-lahi wamā kāna muntaṣiran', 'আর আল্লাহ ছাড়া তাকে সাহায্য করার কোন দলবলও ছিল না, আর সে নিজেও এর মোকাবিলা করতে পারল না।', 'And there was for him no company to aid him other than Allah, nor could he defend himself.', 'আর আল্লাহ ছাড়া তাকে সাহায্য করার কোন দলবলও ছিল না, আর সে নিজেও এর মোকাবিলা করতে পারল না।', 'And there was for him no company to aid him other than Allah, nor could he defend himself.', NULL, NULL, NULL, NULL, NULL, 'https://everyayah.com/data/Alafasy_128kbps/018043.mp3', now()),
  (18, 44, '', '[{"id":44281,"position":1,"text_uthmani":"هُنَالِكَ","transliteration":"hunālika","translation_bn":"এ ক্ষেত্রে (জানতে পারলো)","root":"—","lemma":"هُنَالِك\r","grammar_bn":"কালবাচক (Time)"},{"id":44282,"position":2,"text_uthmani":"ٱلْوَلَـٰيَةُ","transliteration":"l-walāyatu","translation_bn":"অভিভাবকত্বের (অধিকার)","root":"ولي","lemma":"وَلَٰيَت","grammar_bn":"শব্দ"},{"id":44283,"position":3,"text_uthmani":"لِلَّهِ","transliteration":"lillahi","translation_bn":"জন্যে আল্লাহ্‌রই","root":"اله","lemma":"ٱللَّه","grammar_bn":"অব্যয় (Preposition)"},{"id":44284,"position":4,"text_uthmani":"ٱلْحَقِّ ۚ","transliteration":"l-ḥaqi","translation_bn":"তিনি সত্য","root":"حقق","lemma":"حَقّ","grammar_bn":"শব্দ"},{"id":44286,"position":5,"text_uthmani":"هُوَ","transliteration":"huwa","translation_bn":"তিনিই","root":"—","lemma":"هُوَ","grammar_bn":"সর্বনাম (Pronoun)"},{"id":44287,"position":6,"text_uthmani":"خَيْرٌۭ","transliteration":"khayrun","translation_bn":"উত্তম","root":"خير","lemma":"خَيْر","grammar_bn":"বিশেষ্য (Noun)"},{"id":44288,"position":7,"text_uthmani":"ثَوَابًۭا","transliteration":"thawāban","translation_bn":"পুরস্কারদানে","root":"ثوب","lemma":"ثَوَاب","grammar_bn":"বিশেষ্য (Noun)"},{"id":44289,"position":8,"text_uthmani":"وَخَيْرٌ","transliteration":"wakhayrun","translation_bn":"ও উত্তম","root":"خير","lemma":"خَيْر","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":44290,"position":9,"text_uthmani":"عُقْبًۭا","transliteration":"ʿuq''ban","translation_bn":"পরিণামে","root":"عقب","lemma":"عُقْب","grammar_bn":"বিশেষ্য (Noun)"},{"id":44291,"position":10,"text_uthmani":"٤٤","transliteration":"","translation_bn":"(৪৪)","root":"—","lemma":"٤٤","grammar_bn":"মার্কার"}]'::jsonb, 'hunālika l-walāyatu lillahi l-ḥaqi huwa khayrun thawāban wakhayrun ʿuq''ban', 'এ ব্যাপারে যাবতীয় কর্তৃত্ব ক্ষমতা সেই সত্যিকার আল্লাহর জন্যই নির্দিষ্ট। পুরস্কার দানে তিনিই উৎকৃষ্ট, আর সফল পরিণাম দানে তিনিই শ্রেষ্ঠ।', 'There the authority is [completely] for Allah, the Truth. He is best in reward and best in outcome.', 'এ ব্যাপারে যাবতীয় কর্তৃত্ব ক্ষমতা সেই সত্যিকার আল্লাহর জন্যই নির্দিষ্ট। পুরস্কার দানে তিনিই উৎকৃষ্ট, আর সফল পরিণাম দানে তিনিই শ্রেষ্ঠ।', 'There the authority is [completely] for Allah, the Truth. He is best in reward and best in outcome.', NULL, NULL, NULL, NULL, NULL, 'https://everyayah.com/data/Alafasy_128kbps/018044.mp3', now()),
  (18, 45, '', '[{"id":45041,"position":1,"text_uthmani":"وَٱضْرِبْ","transliteration":"wa-iḍ''rib","translation_bn":"এবং পেশ করো","root":"ضرب","lemma":"ضَرَبَ","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":45042,"position":2,"text_uthmani":"لَهُم","transliteration":"lahum","translation_bn":"জন্যে তাদের","root":"—","lemma":"لَهُم","grammar_bn":"অব্যয় (Preposition)"},{"id":45043,"position":3,"text_uthmani":"مَّثَلَ","transliteration":"mathala","translation_bn":"একটি দৃষ্টান্ত","root":"مثل","lemma":"مَثَل","grammar_bn":"বিশেষ্য (Noun)"},{"id":45044,"position":4,"text_uthmani":"ٱلْحَيَوٰةِ","transliteration":"l-ḥayati","translation_bn":"জীবনের","root":"حيي","lemma":"حَيَوٰة","grammar_bn":"শব্দ"},{"id":45045,"position":5,"text_uthmani":"ٱلدُّنْيَا","transliteration":"l-dun''yā","translation_bn":"পার্থিব","root":"دنو","lemma":"دُّنْيَا","grammar_bn":"শব্দ"},{"id":45046,"position":6,"text_uthmani":"كَمَآءٍ","transliteration":"kamāin","translation_bn":"মতো পানির","root":"موه","lemma":"مَا^ء","grammar_bn":"অব্যয় (Preposition)"},{"id":45047,"position":7,"text_uthmani":"أَنزَلْنَـٰهُ","transliteration":"anzalnāhu","translation_bn":"তা আমরা বর্ষণ করি","root":"نزل","lemma":"أَنزَلَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":45048,"position":8,"text_uthmani":"مِنَ","transliteration":"mina","translation_bn":"থেকে","root":"—","lemma":"مِن\r","grammar_bn":"অব্যয় (Preposition)"},{"id":45049,"position":9,"text_uthmani":"ٱلسَّمَآءِ","transliteration":"l-samāi","translation_bn":"আকাশ","root":"سمو","lemma":"سَمَا^ء","grammar_bn":"শব্দ"},{"id":45050,"position":10,"text_uthmani":"فَٱخْتَلَطَ","transliteration":"fa-ikh''talaṭa","translation_bn":"তখন ঘন হয়ে উঠে","root":"خلط","lemma":"ٱخْتَلَطَ","grammar_bn":"শব্দ"},{"id":45051,"position":11,"text_uthmani":"بِهِۦ","transliteration":"bihi","translation_bn":"দিয়ে তা","root":"—","lemma":"بِهِۦ","grammar_bn":"অব্যয় (Preposition)"},{"id":45052,"position":12,"text_uthmani":"نَبَاتُ","transliteration":"nabātu","translation_bn":"উদ্ভিদ","root":"نبت","lemma":"نَبَات","grammar_bn":"বিশেষ্য (Noun)"},{"id":45053,"position":13,"text_uthmani":"ٱلْأَرْضِ","transliteration":"l-arḍi","translation_bn":"মাটির","root":"ارض","lemma":"أَرْض","grammar_bn":"শব্দ"},{"id":45054,"position":14,"text_uthmani":"فَأَصْبَحَ","transliteration":"fa-aṣbaḥa","translation_bn":"অতঃপর হয়ে যায়","root":"صبح","lemma":"أَصْبَحَ","grammar_bn":"শব্দ"},{"id":45055,"position":15,"text_uthmani":"هَشِيمًۭا","transliteration":"hashīman","translation_bn":"ভুষি","root":"هشم","lemma":"هَشِيم","grammar_bn":"বিশেষ্য (Noun)"},{"id":45056,"position":16,"text_uthmani":"تَذْرُوهُ","transliteration":"tadhrūhu","translation_bn":"তা উড়িয়ে নিয়ে যায়","root":"ذرو","lemma":"تَذْرُو","grammar_bn":"ক্রিয়া (Verb)"},{"id":45057,"position":17,"text_uthmani":"ٱلرِّيَـٰحُ ۗ","transliteration":"l-riyāḥu","translation_bn":"বাতাস","root":"روح","lemma":"رِيح","grammar_bn":"শব্দ"},{"id":45059,"position":18,"text_uthmani":"وَكَانَ","transliteration":"wakāna","translation_bn":"এবং হলেন","root":"كون","lemma":"كَانَ","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":45060,"position":19,"text_uthmani":"ٱللَّهُ","transliteration":"l-lahu","translation_bn":"আল্লাহ্‌","root":"اله","lemma":"ٱللَّه","grammar_bn":"নামবাচক বিশেষ্য (Proper Noun)"},{"id":45061,"position":20,"text_uthmani":"عَلَىٰ","transliteration":"ʿalā","translation_bn":"উপর","root":"—","lemma":"عَلَىٰ\r","grammar_bn":"অব্যয় (Preposition)"},{"id":45062,"position":21,"text_uthmani":"كُلِّ","transliteration":"kulli","translation_bn":"সব","root":"كلل","lemma":"كُلّ","grammar_bn":"বিশেষ্য (Noun)"},{"id":45063,"position":22,"text_uthmani":"شَىْءٍۢ","transliteration":"shayin","translation_bn":"কিছুর","root":"شيا","lemma":"شَىْء","grammar_bn":"বিশেষ্য (Noun)"},{"id":45064,"position":23,"text_uthmani":"مُّقْتَدِرًا","transliteration":"muq''tadiran","translation_bn":"সর্বশক্তিমান","root":"قدر","lemma":"مُّقْتَدِر","grammar_bn":"বিশেষ্য (Noun)"},{"id":45065,"position":24,"text_uthmani":"٤٥","transliteration":"","translation_bn":"(৪৫)","root":"—","lemma":"٤٥","grammar_bn":"মার্কার"}]'::jsonb, 'wa-iḍ''rib lahum mathala l-ḥayati l-dun''yā kamāin anzalnāhu mina l-samāi fa-ikh''talaṭa bihi nabātu l-arḍi fa-aṣbaḥa hashīman tadhrūhu l-riyāḥu wakāna l-lahu ʿalā kulli shayin muq''tadiran', 'তাদের কাছে দুনিয়ার এ জীবনের দৃষ্টান্ত পেশ কর : তা হল পানির মত যা তিনি আকাশ হতে বর্ষণ করেন, যা দিয়ে যমীনে গাছ-গাছড়া ঘন হয়ে উদ্গত হয়, অতঃপর তা শুকনো খড়কুটায় পরিণত হয় যাকে বাতাস উড়িয়ে নিয়ে যায়। আল্লাহ হলেন সকল বিষয়ে শক্তিমান।', 'And present to them the example of the life of this world, [its being] like rain which We send down from the sky, and the vegetation of the earth mingles with it and [then] it becomes dry remnants, scattered by the winds. And Allah is ever, over all things, Perfect in Ability.', 'তাদের কাছে দুনিয়ার এ জীবনের দৃষ্টান্ত পেশ কর : তা হল পানির মত যা তিনি আকাশ হতে বর্ষণ করেন, যা দিয়ে যমীনে গাছ-গাছড়া ঘন হয়ে উদ্গত হয়, অতঃপর তা শুকনো খড়কুটায় পরিণত হয় যাকে বাতাস উড়িয়ে নিয়ে যায়। আল্লাহ হলেন সকল বিষয়ে শক্তিমান।', 'And present to them the example of the life of this world, [its being] like rain which We send down from the sky, and the vegetation of the earth mingles with it and [then] it becomes dry remnants, scattered by the winds. And Allah is ever, over all things, Perfect in Ability.', NULL, NULL, NULL, NULL, NULL, 'https://everyayah.com/data/Alafasy_128kbps/018045.mp3', now()),
  (18, 46, '', '[{"id":45748,"position":1,"text_uthmani":"ٱلْمَالُ","transliteration":"al-mālu","translation_bn":"ধনসম্পদ","root":"مول","lemma":"مَال","grammar_bn":"শব্দ"},{"id":45749,"position":2,"text_uthmani":"وَٱلْبَنُونَ","transliteration":"wal-banūna","translation_bn":"ও সন্তান-সন্ততি","root":"بني","lemma":"بُنَىّ","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":45750,"position":3,"text_uthmani":"زِينَةُ","transliteration":"zīnatu","translation_bn":"শোভা","root":"زين","lemma":"زِينَة","grammar_bn":"বিশেষ্য (Noun)"},{"id":45751,"position":4,"text_uthmani":"ٱلْحَيَوٰةِ","transliteration":"l-ḥayati","translation_bn":"জীবনের","root":"حيي","lemma":"حَيَوٰة","grammar_bn":"শব্দ"},{"id":45752,"position":5,"text_uthmani":"ٱلدُّنْيَا ۖ","transliteration":"l-dun''yā","translation_bn":"পার্থিব","root":"دنو","lemma":"دُّنْيَا","grammar_bn":"শব্দ"},{"id":45754,"position":6,"text_uthmani":"وَٱلْبَـٰقِيَـٰتُ","transliteration":"wal-bāqiyātu","translation_bn":"স্থায়ী","root":"بقي","lemma":"بَٰقِيَٰت","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":45755,"position":7,"text_uthmani":"ٱلصَّـٰلِحَـٰتُ","transliteration":"l-ṣāliḥātu","translation_bn":"সৎ কাজসমূহ","root":"صلح","lemma":"صَّٰلِحَٰت","grammar_bn":"শব্দ"},{"id":45756,"position":8,"text_uthmani":"خَيْرٌ","transliteration":"khayrun","translation_bn":"উত্তম","root":"خير","lemma":"خَيْر","grammar_bn":"বিশেষণ (Adjective)"},{"id":45757,"position":9,"text_uthmani":"عِندَ","transliteration":"ʿinda","translation_bn":"কাছে","root":"عند","lemma":"عِند","grammar_bn":"স্থানবাচক (Location)"},{"id":45758,"position":10,"text_uthmani":"رَبِّكَ","transliteration":"rabbika","translation_bn":"তোমার রবের","root":"ربب","lemma":"رَبّ","grammar_bn":"বিশেষ্য (Noun)"},{"id":45759,"position":11,"text_uthmani":"ثَوَابًۭا","transliteration":"thawāban","translation_bn":"প্রতিফল হিসেবে","root":"ثوب","lemma":"ثَوَاب","grammar_bn":"বিশেষ্য (Noun)"},{"id":45760,"position":12,"text_uthmani":"وَخَيْرٌ","transliteration":"wakhayrun","translation_bn":"ও উত্তম","root":"خير","lemma":"خَيْر","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":45761,"position":13,"text_uthmani":"أَمَلًۭا","transliteration":"amalan","translation_bn":"আকাঙ্ক্ষা হিসেবে","root":"امل","lemma":"أَمَل","grammar_bn":"বিশেষ্য (Noun)"},{"id":45762,"position":14,"text_uthmani":"٤٦","transliteration":"","translation_bn":"(৪৬)","root":"—","lemma":"٤٦","grammar_bn":"মার্কার"}]'::jsonb, 'al-mālu wal-banūna zīnatu l-ḥayati l-dun''yā wal-bāqiyātu l-ṣāliḥātu khayrun ʿinda rabbika thawāban wakhayrun amalan', 'ধন-সম্পদ আর সন্তানাদি পার্থিব জীবনের শোভা-সৌন্দর্য, আর তোমার প্রতিপালকের নিকট পুরস্কার লাভের জন্য স্থায়ী সৎকাজ হল উৎকৃষ্ট আর আকাঙ্ক্ষা পোষণের ভিত্তি হিসেবেও উত্তম।', 'Wealth and children are [but] adornment of the worldly life. But the enduring good deeds are better to your Lord for reward and better for [one''s] hope.', 'ধন-সম্পদ আর সন্তানাদি পার্থিব জীবনের শোভা-সৌন্দর্য, আর তোমার প্রতিপালকের নিকট পুরস্কার লাভের জন্য স্থায়ী সৎকাজ হল উৎকৃষ্ট আর আকাঙ্ক্ষা পোষণের ভিত্তি হিসেবেও উত্তম।', 'Wealth and children are [but] adornment of the worldly life. But the enduring good deeds are better to your Lord for reward and better for [one''s] hope.', NULL, NULL, NULL, NULL, NULL, 'https://everyayah.com/data/Alafasy_128kbps/018046.mp3', now()),
  (18, 47, '', '[{"id":46427,"position":1,"text_uthmani":"وَيَوْمَ","transliteration":"wayawma","translation_bn":"এবং যেদিন","root":"يوم","lemma":"يَوْم","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":46428,"position":2,"text_uthmani":"نُسَيِّرُ","transliteration":"nusayyiru","translation_bn":"আমরা চালাবো","root":"سير","lemma":"سُيِّرَتْ","grammar_bn":"ক্রিয়া (Verb)"},{"id":46429,"position":3,"text_uthmani":"ٱلْجِبَالَ","transliteration":"l-jibāla","translation_bn":"পর্বতসমূহকে","root":"جبل","lemma":"جَبَل","grammar_bn":"শব্দ"},{"id":46430,"position":4,"text_uthmani":"وَتَرَى","transliteration":"watarā","translation_bn":"এবং তুমি দেখবে","root":"راي","lemma":"رَءَا","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":46431,"position":5,"text_uthmani":"ٱلْأَرْضَ","transliteration":"l-arḍa","translation_bn":"পৃথিবীকে","root":"ارض","lemma":"أَرْض","grammar_bn":"শব্দ"},{"id":46432,"position":6,"text_uthmani":"بَارِزَةًۭ","transliteration":"bārizatan","translation_bn":"খোলা মাঠ","root":"برز","lemma":"بَارِزَة","grammar_bn":"বিশেষ্য (Noun)"},{"id":46433,"position":7,"text_uthmani":"وَحَشَرْنَـٰهُمْ","transliteration":"waḥasharnāhum","translation_bn":"এবং আমরা একত্র করবো তাদের","root":"حشر","lemma":"حَشَرَ","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":46434,"position":8,"text_uthmani":"فَلَمْ","transliteration":"falam","translation_bn":"অতঃপর না","root":"—","lemma":"لَم\r","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":46435,"position":9,"text_uthmani":"نُغَادِرْ","transliteration":"nughādir","translation_bn":"আমরা  ছাড়বো","root":"غدر","lemma":"يُغَادِرُ","grammar_bn":"ক্রিয়া (Verb)"},{"id":46436,"position":10,"text_uthmani":"مِنْهُمْ","transliteration":"min''hum","translation_bn":"মধ্য হ''তে তাদের","root":"—","lemma":"مِن\r","grammar_bn":"অব্যয় (Preposition)"},{"id":46437,"position":11,"text_uthmani":"أَحَدًۭا","transliteration":"aḥadan","translation_bn":"কাউকে","root":"احد","lemma":"أَحَد","grammar_bn":"বিশেষ্য (Noun)"},{"id":46438,"position":12,"text_uthmani":"٤٧","transliteration":"","translation_bn":"(৪৭)","root":"—","lemma":"٤٧","grammar_bn":"মার্কার"}]'::jsonb, 'wayawma nusayyiru l-jibāla watarā l-arḍa bārizatan waḥasharnāhum falam nughādir min''hum aḥadan', '(সেদিনের কথা চিন্তা কর) যেদিন আমি পর্বতমালাকে চালিত করব, আর পৃথিবীকে দেখতে পাবে উন্মুক্ত প্রান্তর আর তাদের সববাইকে আমি একত্রিত করব, কাউকেও বাদ দেব না।', 'And [warn of] the Day when We will remove the mountains and you will see the earth prominent, and We will gather them and not leave behind from them anyone.', '(সেদিনের কথা চিন্তা কর) যেদিন আমি পর্বতমালাকে চালিত করব, আর পৃথিবীকে দেখতে পাবে উন্মুক্ত প্রান্তর আর তাদের সববাইকে আমি একত্রিত করব, কাউকেও বাদ দেব না।', 'And [warn of] the Day when We will remove the mountains and you will see the earth prominent, and We will gather them and not leave behind from them anyone.', NULL, NULL, NULL, NULL, NULL, 'https://everyayah.com/data/Alafasy_128kbps/018047.mp3', now()),
  (18, 48, '', '[{"id":47395,"position":1,"text_uthmani":"وَعُرِضُوا۟","transliteration":"waʿuriḍū","translation_bn":"এবং তাদের পেশ করা হবে","root":"عرض","lemma":"عَرَضَ","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":47396,"position":2,"text_uthmani":"عَلَىٰ","transliteration":"ʿalā","translation_bn":"কাছে","root":"—","lemma":"عَلَىٰ\r","grammar_bn":"অব্যয় (Preposition)"},{"id":47397,"position":3,"text_uthmani":"رَبِّكَ","transliteration":"rabbika","translation_bn":"তোমার রবের","root":"ربب","lemma":"رَبّ","grammar_bn":"বিশেষ্য (Noun)"},{"id":47398,"position":4,"text_uthmani":"صَفًّۭا","transliteration":"ṣaffan","translation_bn":"সারিবদ্ধভাবে","root":"صفف","lemma":"صَفّ","grammar_bn":"বিশেষ্য (Noun)"},{"id":47399,"position":5,"text_uthmani":"لَّقَدْ","transliteration":"laqad","translation_bn":"\"নিশ্চয়ই","root":"—","lemma":"قَد\r","grammar_bn":"দৃঢ়তাবোধক (Emphatic)"},{"id":47400,"position":6,"text_uthmani":"جِئْتُمُونَا","transliteration":"ji''tumūnā","translation_bn":"আমাদের কাছে তোমরা এসেছো","root":"جيا","lemma":"جَا^ءَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":47401,"position":7,"text_uthmani":"كَمَا","transliteration":"kamā","translation_bn":"যেমন","root":"—","lemma":"مَا\r","grammar_bn":"অব্যয় (Preposition)"},{"id":47402,"position":8,"text_uthmani":"خَلَقْنَـٰكُمْ","transliteration":"khalaqnākum","translation_bn":"আমরা সৃষ্টি করেছিলাম তোমাদেরকে","root":"خلق","lemma":"خَلَقَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":47403,"position":9,"text_uthmani":"أَوَّلَ","transliteration":"awwala","translation_bn":"প্রথম","root":"اول","lemma":"أَوَّل","grammar_bn":"বিশেষ্য (Noun)"},{"id":47404,"position":10,"text_uthmani":"مَرَّةٍۭ ۚ","transliteration":"marratin","translation_bn":"বার","root":"مرر","lemma":"مَرَّة","grammar_bn":"বিশেষ্য (Noun)"},{"id":47406,"position":11,"text_uthmani":"بَلْ","transliteration":"bal","translation_bn":"বরং","root":"—","lemma":"بَل\r","grammar_bn":"প্রত্যাহার পদ (Retraction)"},{"id":47407,"position":12,"text_uthmani":"زَعَمْتُمْ","transliteration":"zaʿamtum","translation_bn":"তোমরা ভেবেছিলে","root":"زعم","lemma":"زَعَمَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":47408,"position":13,"text_uthmani":"أَلَّن","transliteration":"allan","translation_bn":"যে কখনও না","root":"—","lemma":"أَن\r","grammar_bn":"অধীনস্থ যোজক (Subordinating)"},{"id":47409,"position":14,"text_uthmani":"نَّجْعَلَ","transliteration":"najʿala","translation_bn":"আমরা উপস্থিত করবো","root":"جعل","lemma":"جَعَلَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":47410,"position":15,"text_uthmani":"لَكُم","transliteration":"lakum","translation_bn":"জন্যে তোমাদের","root":"—","lemma":"لَكُم","grammar_bn":"অব্যয় (Preposition)"},{"id":47411,"position":16,"text_uthmani":"مَّوْعِدًۭا","transliteration":"mawʿidan","translation_bn":"প্রতিশ্রুত সময়\"","root":"وعد","lemma":"مَّوْعِد","grammar_bn":"বিশেষ্য (Noun)"},{"id":47412,"position":17,"text_uthmani":"٤٨","transliteration":"","translation_bn":"(৪৮)","root":"—","lemma":"٤٨","grammar_bn":"মার্কার"}]'::jsonb, 'waʿuriḍū ʿalā rabbika ṣaffan laqad ji''tumūnā kamā khalaqnākum awwala marratin bal zaʿamtum allan najʿala lakum mawʿidan', 'তাদেরকে তোমার প্রতিপালকের সামনে সারিবদ্ধভাবে হাজির করা হবে (আর তাদেরকে বলা হবে), ‘তোমরা আমার কাছে এসেছ তেমনিভাবে যেভাবে আমি তোমাদেরকে প্রথমবার সৃষ্টি করেছিলাম। কিন্তু তোমরা তো ধারণা করেছিলে যে, আমার কাছে তোমাদের সাক্ষাতের নির্দিষ্টকাল আমি কক্ষনো উপস্থিত করব না।’', 'And they will be presented before your Lord in rows, [and He will say], "You have certainly come to Us just as We created you the first time. But you claimed that We would never make for you an appointment."', 'তাদেরকে তোমার প্রতিপালকের সামনে সারিবদ্ধভাবে হাজির করা হবে (আর তাদেরকে বলা হবে), ‘তোমরা আমার কাছে এসেছ তেমনিভাবে যেভাবে আমি তোমাদেরকে প্রথমবার সৃষ্টি করেছিলাম। কিন্তু তোমরা তো ধারণা করেছিলে যে, আমার কাছে তোমাদের সাক্ষাতের নির্দিষ্টকাল আমি কক্ষনো উপস্থিত করব না।’', 'And they will be presented before your Lord in rows, [and He will say], "You have certainly come to Us just as We created you the first time. But you claimed that We would never make for you an appointment."', NULL, NULL, NULL, NULL, NULL, 'https://everyayah.com/data/Alafasy_128kbps/018048.mp3', now()),
  (18, 49, '', '[{"id":48012,"position":1,"text_uthmani":"وَوُضِعَ","transliteration":"wawuḍiʿa","translation_bn":"এবং রাখা হবে","root":"وضع","lemma":"وَضَعَ","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":48013,"position":2,"text_uthmani":"ٱلْكِتَـٰبُ","transliteration":"l-kitābu","translation_bn":"(হিসেবের) কিতাব","root":"كتب","lemma":"كِتَٰب","grammar_bn":"শব্দ"},{"id":48014,"position":3,"text_uthmani":"فَتَرَى","transliteration":"fatarā","translation_bn":"অতঃপর তুমি দেখবে","root":"راي","lemma":"رَءَا","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":48015,"position":4,"text_uthmani":"ٱلْمُجْرِمِينَ","transliteration":"l-muj''rimīna","translation_bn":"অপরাধীদেরকে","root":"جرم","lemma":"مُجْرِم","grammar_bn":"শব্দ"},{"id":48016,"position":5,"text_uthmani":"مُشْفِقِينَ","transliteration":"mush''fiqīna","translation_bn":"আতঙ্কগ্রস্ত","root":"شفق","lemma":"مُشْفِقُون","grammar_bn":"বিশেষ্য (Noun)"},{"id":48017,"position":6,"text_uthmani":"مِمَّا","transliteration":"mimmā","translation_bn":"তা থেকে যা","root":"—","lemma":"مِن\r","grammar_bn":"অব্যয় (Preposition)"},{"id":48018,"position":7,"text_uthmani":"فِيهِ","transliteration":"fīhi","translation_bn":"মধ্যে আছে তার","root":"—","lemma":"فِى\r","grammar_bn":"অব্যয় (Preposition)"},{"id":48019,"position":8,"text_uthmani":"وَيَقُولُونَ","transliteration":"wayaqūlūna","translation_bn":"এবং তারা বলবে","root":"قول","lemma":"قَالَ","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":48020,"position":9,"text_uthmani":"يَـٰوَيْلَتَنَا","transliteration":"yāwaylatanā","translation_bn":"\"দুর্ভাগ্য হায়! আমাদের","root":"—","lemma":"وَيْل","grammar_bn":"সম্বোধন পদ (Vocative)"},{"id":48021,"position":10,"text_uthmani":"مَالِ","transliteration":"māli","translation_bn":"কেমন","root":"—","lemma":"مَا\r","grammar_bn":"প্রশ্নবোধক (Interrogative)"},{"id":48022,"position":11,"text_uthmani":"هَـٰذَا","transliteration":"hādhā","translation_bn":"এই","root":"—","lemma":"هَٰذَا","grammar_bn":"নির্দেশক সর্বনাম (Demonstrative)"},{"id":48023,"position":12,"text_uthmani":"ٱلْكِتَـٰبِ","transliteration":"l-kitābi","translation_bn":"(হিসেবের) কিতাব","root":"كتب","lemma":"كِتَٰب","grammar_bn":"শব্দ"},{"id":48024,"position":13,"text_uthmani":"لَا","transliteration":"lā","translation_bn":"না","root":"—","lemma":"لَا\r","grammar_bn":"না-বোধক (Negative)"},{"id":48025,"position":14,"text_uthmani":"يُغَادِرُ","transliteration":"yughādiru","translation_bn":"ছাড়ে","root":"غدر","lemma":"يُغَادِرُ","grammar_bn":"ক্রিয়া (Verb)"},{"id":48026,"position":15,"text_uthmani":"صَغِيرَةًۭ","transliteration":"ṣaghīratan","translation_bn":"ছোট","root":"صغر","lemma":"صَغِيرَة","grammar_bn":"বিশেষ্য (Noun)"},{"id":48027,"position":16,"text_uthmani":"وَلَا","transliteration":"walā","translation_bn":"আর না","root":"—","lemma":"لَا\r","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":48028,"position":17,"text_uthmani":"كَبِيرَةً","transliteration":"kabīratan","translation_bn":"বড়","root":"كبر","lemma":"كَبِيرَة","grammar_bn":"বিশেষ্য (Noun)"},{"id":48029,"position":18,"text_uthmani":"إِلَّآ","transliteration":"illā","translation_bn":"কিন্তু","root":"—","lemma":"إِلَّا\r","grammar_bn":"সীমাবদ্ধতা (Restriction)"},{"id":48030,"position":19,"text_uthmani":"أَحْصَىٰهَا ۚ","transliteration":"aḥṣāhā","translation_bn":"তা গুনে রেখেছে\"","root":"حصي","lemma":"أَحْصَىٰ","grammar_bn":"ক্রিয়া (Verb)"},{"id":48032,"position":20,"text_uthmani":"وَوَجَدُوا۟","transliteration":"wawajadū","translation_bn":"তারা পাবে","root":"وجد","lemma":"وَجَدَ","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":48033,"position":21,"text_uthmani":"مَا","transliteration":"mā","translation_bn":"যা","root":"—","lemma":"مَا\r","grammar_bn":"সাপেক্ষ সর্বনাম (Relative)"},{"id":48034,"position":22,"text_uthmani":"عَمِلُوا۟","transliteration":"ʿamilū","translation_bn":"তারা কাজ করছে","root":"عمل","lemma":"عَمِلَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":48035,"position":23,"text_uthmani":"حَاضِرًۭا ۗ","transliteration":"ḥāḍiran","translation_bn":"উপস্থিত","root":"حضر","lemma":"حَاضِر","grammar_bn":"বিশেষ্য (Noun)"},{"id":48037,"position":24,"text_uthmani":"وَلَا","transliteration":"walā","translation_bn":"এবং না","root":"—","lemma":"لَا\r","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":48038,"position":25,"text_uthmani":"يَظْلِمُ","transliteration":"yaẓlimu","translation_bn":"অন্যায় করবেন","root":"ظلم","lemma":"ظَلَمَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":48039,"position":26,"text_uthmani":"رَبُّكَ","transliteration":"rabbuka","translation_bn":"তোমার রব","root":"ربب","lemma":"رَبّ","grammar_bn":"বিশেষ্য (Noun)"},{"id":48040,"position":27,"text_uthmani":"أَحَدًۭا","transliteration":"aḥadan","translation_bn":"কাউকে","root":"احد","lemma":"أَحَد","grammar_bn":"বিশেষ্য (Noun)"},{"id":48041,"position":28,"text_uthmani":"٤٩","transliteration":"","translation_bn":"(৪৯)","root":"—","lemma":"٤٩","grammar_bn":"মার্কার"}]'::jsonb, 'wawuḍiʿa l-kitābu fatarā l-muj''rimīna mush''fiqīna mimmā fīhi wayaqūlūna yāwaylatanā māli hādhā l-kitābi lā yughādiru ṣaghīratan walā kabīratan illā aḥṣāhā wawajadū mā ʿamilū ḥāḍiran walā yaẓlimu rabbuka aḥadan', 'আর ‘আমালনামা হাজির করা হবে, আর তাতে যা (লেখে রাখা আছে) তার কারণে তুমি অপরাধী লোকদেরকে দেখতে পাবে ভীত আতঙ্কিত। আর তারা বলবে, ‘হায় কপাল! এটা কেমন কিতাব যে ছোট বড় কোন কাজই ছেড়ে দেয়নি বরং সব কিছুর হিসাব রেখেছে।’ তারা যা করেছে তা সামনে উপস্থিত পাবে, আর তোমার প্রতিপালক কারো প্রতি যুলম করবেন না।', 'And the record [of deeds] will be placed [open], and you will see the criminals fearful of that within it, and they will say, "Oh, woe to us! What is this book that leaves nothing small or great except that it has enumerated it?" And they will find what they did present [before them]. And your Lord does injustice to no one.', 'আর ‘আমালনামা হাজির করা হবে, আর তাতে যা (লেখে রাখা আছে) তার কারণে তুমি অপরাধী লোকদেরকে দেখতে পাবে ভীত আতঙ্কিত। আর তারা বলবে, ‘হায় কপাল! এটা কেমন কিতাব যে ছোট বড় কোন কাজই ছেড়ে দেয়নি বরং সব কিছুর হিসাব রেখেছে।’ তারা যা করেছে তা সামনে উপস্থিত পাবে, আর তোমার প্রতিপালক কারো প্রতি যুলম করবেন না।', 'And the record [of deeds] will be placed [open], and you will see the criminals fearful of that within it, and they will say, "Oh, woe to us! What is this book that leaves nothing small or great except that it has enumerated it?" And they will find what they did present [before them]. And your Lord does injustice to no one.', NULL, NULL, NULL, NULL, NULL, 'https://everyayah.com/data/Alafasy_128kbps/018049.mp3', now()),
  (18, 50, '', '[{"id":48720,"position":1,"text_uthmani":"وَإِذْ","transliteration":"wa-idh","translation_bn":"এবং (স্মরণ করো) যখন","root":"—","lemma":"إِذ\r","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":48721,"position":2,"text_uthmani":"قُلْنَا","transliteration":"qul''nā","translation_bn":"আমরা বলেছিলাম","root":"قول","lemma":"قَالَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":48722,"position":3,"text_uthmani":"لِلْمَلَـٰٓئِكَةِ","transliteration":"lil''malāikati","translation_bn":"ফেরেশতাদেরকে","root":"ملك","lemma":"مَلَك","grammar_bn":"অব্যয় (Preposition)"},{"id":48723,"position":4,"text_uthmani":"ٱسْجُدُوا۟","transliteration":"us''judū","translation_bn":"\"তোমরা সিজদা করো","root":"سجد","lemma":"سَجَدَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":48724,"position":5,"text_uthmani":"لِـَٔادَمَ","transliteration":"liādama","translation_bn":"আদমকে\"","root":"—","lemma":"ا^دَم","grammar_bn":"অব্যয় (Preposition)"},{"id":48725,"position":6,"text_uthmani":"فَسَجَدُوٓا۟","transliteration":"fasajadū","translation_bn":"তখন তারা সিজদা করেছিলো","root":"سجد","lemma":"سَجَدَ","grammar_bn":"শব্দ"},{"id":48726,"position":7,"text_uthmani":"إِلَّآ","transliteration":"illā","translation_bn":"ছাড়া","root":"—","lemma":"إِلَّا\r","grammar_bn":"সীমাবদ্ধতা (Restriction)"},{"id":48727,"position":8,"text_uthmani":"إِبْلِيسَ","transliteration":"ib''līsa","translation_bn":"ইবলীশ","root":"—","lemma":"إِبْلِيس","grammar_bn":"নামবাচক বিশেষ্য (Proper Noun)"},{"id":48728,"position":9,"text_uthmani":"كَانَ","transliteration":"kāna","translation_bn":"সে ছিলো","root":"كون","lemma":"كَانَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":48729,"position":10,"text_uthmani":"مِنَ","transliteration":"mina","translation_bn":"অন্তর্ভুক্ত","root":"—","lemma":"مِن\r","grammar_bn":"অব্যয় (Preposition)"},{"id":48730,"position":11,"text_uthmani":"ٱلْجِنِّ","transliteration":"l-jini","translation_bn":"জিনদের","root":"جنن","lemma":"جِنّ","grammar_bn":"শব্দ"},{"id":48731,"position":12,"text_uthmani":"فَفَسَقَ","transliteration":"fafasaqa","translation_bn":"তাই সে অমান্য করলো","root":"فسق","lemma":"فَسَقَ","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":48732,"position":13,"text_uthmani":"عَنْ","transliteration":"ʿan","translation_bn":"থেকে","root":"—","lemma":"عَن\r","grammar_bn":"অব্যয় (Preposition)"},{"id":48733,"position":14,"text_uthmani":"أَمْرِ","transliteration":"amri","translation_bn":"নির্দেশ","root":"امر","lemma":"أَمْر","grammar_bn":"বিশেষ্য (Noun)"},{"id":48734,"position":15,"text_uthmani":"رَبِّهِۦٓ ۗ","transliteration":"rabbihi","translation_bn":"তার রবের","root":"ربب","lemma":"رَبّ","grammar_bn":"বিশেষ্য (Noun)"},{"id":48736,"position":16,"text_uthmani":"أَفَتَتَّخِذُونَهُۥ","transliteration":"afatattakhidhūnahu","translation_bn":"কি তোমরা গ্রহণ করেছো তাকে","root":"اخذ","lemma":"ٱتَّخَذَ","grammar_bn":"প্রশ্নবোধক (Interrogative)"},{"id":48737,"position":17,"text_uthmani":"وَذُرِّيَّتَهُۥٓ","transliteration":"wadhurriyyatahu","translation_bn":"ও তার বংশধরকে","root":"ذرر","lemma":"ذُرِّيَّة","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":48738,"position":18,"text_uthmani":"أَوْلِيَآءَ","transliteration":"awliyāa","translation_bn":"অভিভাবকরূপে","root":"ولي","lemma":"وَلِىّ","grammar_bn":"বিশেষ্য (Noun)"},{"id":48739,"position":19,"text_uthmani":"مِن","transliteration":"min","translation_bn":"ছাড়া","root":"—","lemma":"مِن\r","grammar_bn":"অব্যয় (Preposition)"},{"id":48740,"position":20,"text_uthmani":"دُونِى","transliteration":"dūnī","translation_bn":"আমাকে","root":"دون","lemma":"دُون","grammar_bn":"বিশেষ্য (Noun)"},{"id":48741,"position":21,"text_uthmani":"وَهُمْ","transliteration":"wahum","translation_bn":"অথচ তারা","root":"—","lemma":"وَهُمْ","grammar_bn":"অবস্থাবাচক (Circumstantial)"},{"id":48742,"position":22,"text_uthmani":"لَكُمْ","transliteration":"lakum","translation_bn":"জন্যে তোমাদের","root":"—","lemma":"لَكُمْ","grammar_bn":"অব্যয় (Preposition)"},{"id":48743,"position":23,"text_uthmani":"عَدُوٌّۢ ۚ","transliteration":"ʿaduwwun","translation_bn":"শত্রু","root":"عدو","lemma":"عَدُوّ","grammar_bn":"বিশেষ্য (Noun)"},{"id":48745,"position":24,"text_uthmani":"بِئْسَ","transliteration":"bi''sa","translation_bn":"বড়ই খারাপ","root":"باس","lemma":"بِئْسَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":48746,"position":25,"text_uthmani":"لِلظَّـٰلِمِينَ","transliteration":"lilẓẓālimīna","translation_bn":"জন্যে সীমালঙ্ঘনকারীদের","root":"ظلم","lemma":"ظَالِم","grammar_bn":"অব্যয় (Preposition)"},{"id":48747,"position":26,"text_uthmani":"بَدَلًۭا","transliteration":"badalan","translation_bn":"বিনিময় হিসেবে","root":"بدل","lemma":"بَدَل","grammar_bn":"বিশেষণ (Adjective)"},{"id":48748,"position":27,"text_uthmani":"٥٠","transliteration":"","translation_bn":"(৫০)","root":"—","lemma":"٥٠","grammar_bn":"মার্কার"}]'::jsonb, 'wa-idh qul''nā lil''malāikati us''judū liādama fasajadū illā ib''līsa kāna mina l-jini fafasaqa ʿan amri rabbihi afatattakhidhūnahu wadhurriyyatahu awliyāa min dūnī wahum lakum ʿaduwwun bi''sa lilẓẓālimīna badalan', 'স্মরণ কর, যখন আমি ফেরেশতাদেরকে বলেছিলাম, ‘আদামকে সাজদাহ কর।’ তখন ইবলিশ ছাড়া তারা সবাই সাজদাহ করল। সে ছিল জ্বীনদের অন্তর্ভুক্ত। সে তার প্রতিপালকের নির্দেশ লঙ্ঘন করল। এতদসত্ত্বেও তোমরা কি আমাকে বাদ দিয়ে তাকে আর তার বংশধরকে অভিভাবক বানিয়ে নিচ্ছ? অথচ তারা তোমাদের দুশমন। যালিমদের এই বিনিময় বড়ই নিকৃষ্ট!', 'And [mention] when We said to the angels, "Prostrate to Adam," and they prostrated, except for Iblees. He was of the jinn and departed from the command of his Lord. Then will you take him and his descendants as allies other than Me while they are enemies to you? Wretched it is for the wrongdoers as an exchange.', 'স্মরণ কর, যখন আমি ফেরেশতাদেরকে বলেছিলাম, ‘আদামকে সাজদাহ কর।’ তখন ইবলিশ ছাড়া তারা সবাই সাজদাহ করল। সে ছিল জ্বীনদের অন্তর্ভুক্ত। সে তার প্রতিপালকের নির্দেশ লঙ্ঘন করল। এতদসত্ত্বেও তোমরা কি আমাকে বাদ দিয়ে তাকে আর তার বংশধরকে অভিভাবক বানিয়ে নিচ্ছ? অথচ তারা তোমাদের দুশমন। যালিমদের এই বিনিময় বড়ই নিকৃষ্ট!', 'And [mention] when We said to the angels, "Prostrate to Adam," and they prostrated, except for Iblees. He was of the jinn and departed from the command of his Lord. Then will you take him and his descendants as allies other than Me while they are enemies to you? Wretched it is for the wrongdoers as an exchange.', NULL, NULL, NULL, NULL, NULL, 'https://everyayah.com/data/Alafasy_128kbps/018050.mp3', now()),
  (18, 51, '', '[{"id":49244,"position":1,"text_uthmani":"۞ مَّآ","transliteration":"mā","translation_bn":"নি","root":"—","lemma":"مَا\r","grammar_bn":"না-বোধক (Negative)"},{"id":49245,"position":2,"text_uthmani":"أَشْهَدتُّهُمْ","transliteration":"ashhadttuhum","translation_bn":"তাদেরকে আমি সাক্ষী করি","root":"شهد","lemma":"أَشْهَدَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":49246,"position":3,"text_uthmani":"خَلْقَ","transliteration":"khalqa","translation_bn":"সৃষ্টিতে","root":"خلق","lemma":"خَلْق","grammar_bn":"বিশেষ্য (Noun)"},{"id":49247,"position":4,"text_uthmani":"ٱلسَّمَـٰوَٰتِ","transliteration":"l-samāwāti","translation_bn":"আকাশসমূহের","root":"سمو","lemma":"سَمَا^ء","grammar_bn":"শব্দ"},{"id":49248,"position":5,"text_uthmani":"وَٱلْأَرْضِ","transliteration":"wal-arḍi","translation_bn":"ও পৃথিবীর","root":"ارض","lemma":"أَرْض","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":49249,"position":6,"text_uthmani":"وَلَا","transliteration":"walā","translation_bn":"আর না","root":"—","lemma":"لَا\r","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":49250,"position":7,"text_uthmani":"خَلْقَ","transliteration":"khalqa","translation_bn":"সৃষ্টিতে","root":"خلق","lemma":"خَلْق","grammar_bn":"বিশেষ্য (Noun)"},{"id":49251,"position":8,"text_uthmani":"أَنفُسِهِمْ","transliteration":"anfusihim","translation_bn":"নিজেদের তাদের","root":"نفس","lemma":"نَفْس","grammar_bn":"বিশেষ্য (Noun)"},{"id":49252,"position":9,"text_uthmani":"وَمَا","transliteration":"wamā","translation_bn":"এবং না","root":"—","lemma":"مَا\r","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":49253,"position":10,"text_uthmani":"كُنتُ","transliteration":"kuntu","translation_bn":"আমি ছিলাম","root":"كون","lemma":"كَانَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":49254,"position":11,"text_uthmani":"مُتَّخِذَ","transliteration":"muttakhidha","translation_bn":"গ্রহণকারী","root":"اخذ","lemma":"مُتَّخِذ","grammar_bn":"বিশেষ্য (Noun)"},{"id":49255,"position":12,"text_uthmani":"ٱلْمُضِلِّينَ","transliteration":"l-muḍilīna","translation_bn":"বিভ্রান্তকারীদেরকে","root":"ضلل","lemma":"مُّضِلّ","grammar_bn":"শব্দ"},{"id":49256,"position":13,"text_uthmani":"عَضُدًۭا","transliteration":"ʿaḍudan","translation_bn":"সাহায্যকারীরূপে","root":"عضد","lemma":"عَضُد","grammar_bn":"বিশেষ্য (Noun)"},{"id":49257,"position":14,"text_uthmani":"٥١","transliteration":"","translation_bn":"(৫১)","root":"—","lemma":"٥١","grammar_bn":"মার্কার"}]'::jsonb, 'mā ashhadttuhum khalqa l-samāwāti wal-arḍi walā khalqa anfusihim wamā kuntu muttakhidha l-muḍilīna ʿaḍudan', 'আসমান যমীনের সৃষ্টিকালে আমি তাদেরকে সাক্ষী রাখিনি, আর তাদের নিজেদের সৃষ্টি (প্রত্যক্ষ করার জন্য)ও না, পথভ্রষ্টকারীদেরকে সাহায্যকারী গ্রহণ করা আমার কাজ নয়।', 'I did not make them witness to the creation of the heavens and the earth or to the creation of themselves, and I would not have taken the misguiders as assistants.', 'আসমান যমীনের সৃষ্টিকালে আমি তাদেরকে সাক্ষী রাখিনি, আর তাদের নিজেদের সৃষ্টি (প্রত্যক্ষ করার জন্য)ও না, পথভ্রষ্টকারীদেরকে সাহায্যকারী গ্রহণ করা আমার কাজ নয়।', 'I did not make them witness to the creation of the heavens and the earth or to the creation of themselves, and I would not have taken the misguiders as assistants.', NULL, NULL, NULL, NULL, NULL, 'https://everyayah.com/data/Alafasy_128kbps/018051.mp3', now()),
  (18, 52, '', '[{"id":49989,"position":1,"text_uthmani":"وَيَوْمَ","transliteration":"wayawma","translation_bn":"এবং যেদিন","root":"يوم","lemma":"يَوْم","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":49990,"position":2,"text_uthmani":"يَقُولُ","transliteration":"yaqūlu","translation_bn":"তিনি বলবেন","root":"قول","lemma":"قَالَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":49991,"position":3,"text_uthmani":"نَادُوا۟","transliteration":"nādū","translation_bn":"\"তোমরা ডাকো","root":"ندو","lemma":"نَادَىٰ","grammar_bn":"ক্রিয়া (Verb)"},{"id":49992,"position":4,"text_uthmani":"شُرَكَآءِىَ","transliteration":"shurakāiya","translation_bn":"আমার শরিকদেরকে","root":"شرك","lemma":"شَرِيك","grammar_bn":"বিশেষ্য (Noun)"},{"id":49993,"position":5,"text_uthmani":"ٱلَّذِينَ","transliteration":"alladhīna","translation_bn":"যাদেরকে","root":"—","lemma":"ٱلَّذِى","grammar_bn":"সাপেক্ষ সর্বনাম (Relative)"},{"id":49994,"position":6,"text_uthmani":"زَعَمْتُمْ","transliteration":"zaʿamtum","translation_bn":"মনে করেছিলে তোমরা\"","root":"زعم","lemma":"زَعَمَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":49995,"position":7,"text_uthmani":"فَدَعَوْهُمْ","transliteration":"fadaʿawhum","translation_bn":"তখন তারা ডাকবে তাদেরকে","root":"دعو","lemma":"دَعَا","grammar_bn":"শব্দ"},{"id":49996,"position":8,"text_uthmani":"فَلَمْ","transliteration":"falam","translation_bn":"কিন্তু না","root":"—","lemma":"لَم\r","grammar_bn":"শব্দ"},{"id":49997,"position":9,"text_uthmani":"يَسْتَجِيبُوا۟","transliteration":"yastajībū","translation_bn":"তারা ডাকে সাড়া দিবে","root":"جوب","lemma":"ٱسْتَجَابَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":49998,"position":10,"text_uthmani":"لَهُمْ","transliteration":"lahum","translation_bn":"তাদেরকে","root":"—","lemma":"لَهُمْ","grammar_bn":"অব্যয় (Preposition)"},{"id":49999,"position":11,"text_uthmani":"وَجَعَلْنَا","transliteration":"wajaʿalnā","translation_bn":"এবং আমরা রেখে দিবো","root":"جعل","lemma":"جَعَلَ","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":50000,"position":12,"text_uthmani":"بَيْنَهُم","transliteration":"baynahum","translation_bn":"মাঝে তাদের","root":"بين","lemma":"بَيْن","grammar_bn":"স্থানবাচক (Location)"},{"id":50001,"position":13,"text_uthmani":"مَّوْبِقًۭا","transliteration":"mawbiqan","translation_bn":"ধ্বংসের স্থান","root":"وبق","lemma":"مَّوْبِق","grammar_bn":"বিশেষ্য (Noun)"},{"id":50002,"position":14,"text_uthmani":"٥٢","transliteration":"","translation_bn":"(৫২)","root":"—","lemma":"٥٢","grammar_bn":"মার্কার"}]'::jsonb, 'wayawma yaqūlu nādū shurakāiya alladhīna zaʿamtum fadaʿawhum falam yastajībū lahum wajaʿalnā baynahum mawbiqan', 'সেদিন তিনি বলবেন, ‘তোমরা যাদেরকে আমার শরীক মনে করতে তাদেরকে ডাক।’ তখন তারা তাদেরকে ডাকবে, কিন্তু তারা তাদের ডাকে সাড়া দেবে না। আর আমি উভয় দলের মাঝে রেখে দেব এক ধ্বংস-গহ্বর।', 'And [warn of] the Day when He will say, "Call ''My partners'' whom you claimed," and they will invoke them, but they will not respond to them. And We will put between them [a valley of] destruction.', 'সেদিন তিনি বলবেন, ‘তোমরা যাদেরকে আমার শরীক মনে করতে তাদেরকে ডাক।’ তখন তারা তাদেরকে ডাকবে, কিন্তু তারা তাদের ডাকে সাড়া দেবে না। আর আমি উভয় দলের মাঝে রেখে দেব এক ধ্বংস-গহ্বর।', 'And [warn of] the Day when He will say, "Call ''My partners'' whom you claimed," and they will invoke them, but they will not respond to them. And We will put between them [a valley of] destruction.', NULL, NULL, NULL, NULL, NULL, 'https://everyayah.com/data/Alafasy_128kbps/018052.mp3', now()),
  (18, 53, '', '[{"id":50565,"position":1,"text_uthmani":"وَرَءَا","transliteration":"waraā","translation_bn":"এবং দেখবে","root":"راي","lemma":"رَءَا","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":50566,"position":2,"text_uthmani":"ٱلْمُجْرِمُونَ","transliteration":"l-muj''rimūna","translation_bn":"অপরাধীরা","root":"جرم","lemma":"مُجْرِم","grammar_bn":"শব্দ"},{"id":50567,"position":3,"text_uthmani":"ٱلنَّارَ","transliteration":"l-nāra","translation_bn":"আগুন","root":"نور","lemma":"نَار","grammar_bn":"শব্দ"},{"id":50568,"position":4,"text_uthmani":"فَظَنُّوٓا۟","transliteration":"faẓannū","translation_bn":"তখন তারা ভাববে","root":"ظنن","lemma":"ظَنَّ","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":50569,"position":5,"text_uthmani":"أَنَّهُم","transliteration":"annahum","translation_bn":"যে তারা","root":"—","lemma":"أَنّ","grammar_bn":"অভিঘাত পদ (Accusative)"},{"id":50570,"position":6,"text_uthmani":"مُّوَاقِعُوهَا","transliteration":"muwāqiʿūhā","translation_bn":"তাতে ফেলা হবে","root":"وقع","lemma":"مُّوَاقِعُو","grammar_bn":"বিশেষ্য (Noun)"},{"id":50571,"position":7,"text_uthmani":"وَلَمْ","transliteration":"walam","translation_bn":"এবং না","root":"—","lemma":"لَم\r","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":50572,"position":8,"text_uthmani":"يَجِدُوا۟","transliteration":"yajidū","translation_bn":"তারা পাবে","root":"وجد","lemma":"وَجَدَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":50573,"position":9,"text_uthmani":"عَنْهَا","transliteration":"ʿanhā","translation_bn":"থেকে তা","root":"—","lemma":"عَن\r","grammar_bn":"অব্যয় (Preposition)"},{"id":50574,"position":10,"text_uthmani":"مَصْرِفًۭا","transliteration":"maṣrifan","translation_bn":"ফিরার স্থান","root":"صرف","lemma":"مَصْرِف","grammar_bn":"বিশেষ্য (Noun)"},{"id":50575,"position":11,"text_uthmani":"٥٣","transliteration":"","translation_bn":"(৫৩)","root":"—","lemma":"٥٣","grammar_bn":"মার্কার"}]'::jsonb, 'waraā l-muj''rimūna l-nāra faẓannū annahum muwāqiʿūhā walam yajidū ʿanhā maṣrifan', 'অপরাধীরা আগুন দেখতে পাবে আর মনে করবে যে, তাদেরকে তাতে পতিত হতে হবে, কিন্তু সেখান থেকে ফিরে যাবার তারা কোনই উপায় পাবে না।', 'And the criminals will see the Fire and will be certain that they are to fall therein. And they will not find from it a way elsewhere.', 'অপরাধীরা আগুন দেখতে পাবে আর মনে করবে যে, তাদেরকে তাতে পতিত হতে হবে, কিন্তু সেখান থেকে ফিরে যাবার তারা কোনই উপায় পাবে না।', 'And the criminals will see the Fire and will be certain that they are to fall therein. And they will not find from it a way elsewhere.', NULL, NULL, NULL, NULL, NULL, 'https://everyayah.com/data/Alafasy_128kbps/018053.mp3', now()),
  (18, 54, '', '[{"id":51267,"position":1,"text_uthmani":"وَلَقَدْ","transliteration":"walaqad","translation_bn":"এবং নিশ্চয়ই","root":"—","lemma":"قَد\r","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":51268,"position":2,"text_uthmani":"صَرَّفْنَا","transliteration":"ṣarrafnā","translation_bn":"আমরা বিশদভাবে বর্ণনা করেছি","root":"صرف","lemma":"صَرَّفْ","grammar_bn":"ক্রিয়া (Verb)"},{"id":51269,"position":3,"text_uthmani":"فِى","transliteration":"fī","translation_bn":"মধ্যে","root":"—","lemma":"فِى\r","grammar_bn":"অব্যয় (Preposition)"},{"id":51270,"position":4,"text_uthmani":"هَـٰذَا","transliteration":"hādhā","translation_bn":"এই","root":"—","lemma":"هَٰذَا","grammar_bn":"নির্দেশক সর্বনাম (Demonstrative)"},{"id":51271,"position":5,"text_uthmani":"ٱلْقُرْءَانِ","transliteration":"l-qur''āni","translation_bn":"কুরআনের","root":"قرا","lemma":"قُرْءَان","grammar_bn":"শব্দ"},{"id":51272,"position":6,"text_uthmani":"لِلنَّاسِ","transliteration":"lilnnāsi","translation_bn":"জন্যে মানুষদের","root":"نوس","lemma":"نَّاس","grammar_bn":"অব্যয় (Preposition)"},{"id":51273,"position":7,"text_uthmani":"مِن","transliteration":"min","translation_bn":"থেকে","root":"—","lemma":"مِن\r","grammar_bn":"অব্যয় (Preposition)"},{"id":51274,"position":8,"text_uthmani":"كُلِّ","transliteration":"kulli","translation_bn":"প্রত্যেক","root":"كلل","lemma":"كُلّ","grammar_bn":"বিশেষ্য (Noun)"},{"id":51275,"position":9,"text_uthmani":"مَثَلٍۢ ۚ","transliteration":"mathalin","translation_bn":"দৃষ্টান্ত","root":"مثل","lemma":"مَثَل","grammar_bn":"বিশেষ্য (Noun)"},{"id":51277,"position":10,"text_uthmani":"وَكَانَ","transliteration":"wakāna","translation_bn":"অথচ হলো","root":"كون","lemma":"كَانَ","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":51278,"position":11,"text_uthmani":"ٱلْإِنسَـٰنُ","transliteration":"l-insānu","translation_bn":"মানুষ","root":"انس","lemma":"إِنسَٰن","grammar_bn":"শব্দ"},{"id":51279,"position":12,"text_uthmani":"أَكْثَرَ","transliteration":"akthara","translation_bn":"অধিকাংশ","root":"كثر","lemma":"أَكْثَر","grammar_bn":"বিশেষণ (Adjective)"},{"id":51280,"position":13,"text_uthmani":"شَىْءٍۢ","transliteration":"shayin","translation_bn":"বিষয়ে","root":"شيا","lemma":"شَىْء","grammar_bn":"বিশেষ্য (Noun)"},{"id":51281,"position":14,"text_uthmani":"جَدَلًۭا","transliteration":"jadalan","translation_bn":"ঝগড়াটে","root":"جدل","lemma":"جَدَل","grammar_bn":"বিশেষ্য (Noun)"},{"id":51282,"position":15,"text_uthmani":"٥٤","transliteration":"","translation_bn":"(৫৪)","root":"—","lemma":"٥٤","grammar_bn":"মার্কার"}]'::jsonb, 'walaqad ṣarrafnā fī hādhā l-qur''āni lilnnāsi min kulli mathalin wakāna l-insānu akthara shayin jadalan', 'আমি এ কুরআনে মানুষের (জ্ঞান লাভের) জন্য যাবতীয় দৃষ্টান্ত বিশদভাবে বিবৃত করেছি কিন্তু মানুষ অধিকাংশ বিষয়েই বিতর্ককারী।', 'And We have certainly diversified in this Qur''an for the people from every [kind of] example; but man has ever been, most of anything, [prone to] dispute.', 'আমি এ কুরআনে মানুষের (জ্ঞান লাভের) জন্য যাবতীয় দৃষ্টান্ত বিশদভাবে বিবৃত করেছি কিন্তু মানুষ অধিকাংশ বিষয়েই বিতর্ককারী।', 'And We have certainly diversified in this Qur''an for the people from every [kind of] example; but man has ever been, most of anything, [prone to] dispute.', NULL, NULL, NULL, NULL, NULL, 'https://everyayah.com/data/Alafasy_128kbps/018054.mp3', now()),
  (18, 55, '', '[{"id":51608,"position":1,"text_uthmani":"وَمَا","transliteration":"wamā","translation_bn":"এবং কি (জিনিস)","root":"—","lemma":"مَا\r","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":51609,"position":2,"text_uthmani":"مَنَعَ","transliteration":"manaʿa","translation_bn":"বাদা দেয়","root":"منع","lemma":"مَّنَعَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":51610,"position":3,"text_uthmani":"ٱلنَّاسَ","transliteration":"l-nāsa","translation_bn":"মানুষদেরকে","root":"نوس","lemma":"نَّاس","grammar_bn":"শব্দ"},{"id":51611,"position":4,"text_uthmani":"أَن","transliteration":"an","translation_bn":"যে","root":"—","lemma":"أَن\r","grammar_bn":"অধীনস্থ যোজক (Subordinating)"},{"id":51612,"position":5,"text_uthmani":"يُؤْمِنُوٓا۟","transliteration":"yu''minū","translation_bn":"তারা ঈমান আনবে","root":"امن","lemma":"ءَامَنَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":51613,"position":6,"text_uthmani":"إِذْ","transliteration":"idh","translation_bn":"যখন","root":"—","lemma":"إِذ\r","grammar_bn":"কালবাচক (Time)"},{"id":51614,"position":7,"text_uthmani":"جَآءَهُمُ","transliteration":"jāahumu","translation_bn":"এসেছে তাদের কাছে","root":"جيا","lemma":"جَا^ءَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":51615,"position":8,"text_uthmani":"ٱلْهُدَىٰ","transliteration":"l-hudā","translation_bn":"পথ নির্দেশ","root":"هدي","lemma":"هُدًى","grammar_bn":"শব্দ"},{"id":51616,"position":9,"text_uthmani":"وَيَسْتَغْفِرُوا۟","transliteration":"wayastaghfirū","translation_bn":"এবং তারা ক্ষমা চাইতে","root":"غفر","lemma":"ٱسْتَغْفَرَ","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":51617,"position":10,"text_uthmani":"رَبَّهُمْ","transliteration":"rabbahum","translation_bn":"রবের কাছে তাদের","root":"ربب","lemma":"رَبّ","grammar_bn":"বিশেষ্য (Noun)"},{"id":51618,"position":11,"text_uthmani":"إِلَّآ","transliteration":"illā","translation_bn":"ছাড়া","root":"—","lemma":"إِلَّا\r","grammar_bn":"সীমাবদ্ধতা (Restriction)"},{"id":51619,"position":12,"text_uthmani":"أَن","transliteration":"an","translation_bn":"যে","root":"—","lemma":"أَن\r","grammar_bn":"অধীনস্থ যোজক (Subordinating)"},{"id":51620,"position":13,"text_uthmani":"تَأْتِيَهُمْ","transliteration":"tatiyahum","translation_bn":"কাছ আসবে তাদের","root":"اتي","lemma":"أَتَى","grammar_bn":"ক্রিয়া (Verb)"},{"id":51621,"position":14,"text_uthmani":"سُنَّةُ","transliteration":"sunnatu","translation_bn":"অনুসৃত রীতি","root":"سنن","lemma":"سُنَّة","grammar_bn":"বিশেষ্য (Noun)"},{"id":51622,"position":15,"text_uthmani":"ٱلْأَوَّلِينَ","transliteration":"l-awalīna","translation_bn":"পূর্ববর্তীদের","root":"اول","lemma":"أَوَّل","grammar_bn":"শব্দ"},{"id":51623,"position":16,"text_uthmani":"أَوْ","transliteration":"aw","translation_bn":"অথবা","root":"—","lemma":"أَو\r","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":51624,"position":17,"text_uthmani":"يَأْتِيَهُمُ","transliteration":"yatiyahumu","translation_bn":"কাছে আসবে তাদের","root":"اتي","lemma":"أَتَى","grammar_bn":"ক্রিয়া (Verb)"},{"id":51625,"position":18,"text_uthmani":"ٱلْعَذَابُ","transliteration":"l-ʿadhābu","translation_bn":"শাস্তি","root":"عذب","lemma":"عَذَاب","grammar_bn":"শব্দ"},{"id":51626,"position":19,"text_uthmani":"قُبُلًۭا","transliteration":"qubulan","translation_bn":"সামনাসামনি","root":"قبل","lemma":"قُبُل","grammar_bn":"বিশেষ্য (Noun)"},{"id":51627,"position":20,"text_uthmani":"٥٥","transliteration":"","translation_bn":"(৫৫)","root":"—","lemma":"٥٥","grammar_bn":"মার্কার"}]'::jsonb, 'wamā manaʿa l-nāsa an yu''minū idh jāahumu l-hudā wayastaghfirū rabbahum illā an tatiyahum sunnatu l-awalīna aw yatiyahumu l-ʿadhābu qubulan', 'তাদের কাছে যখন পথের নির্দেশ আসে তখন ঈমান আনতে আর তাদের প্রতিপালকের কাছে ক্ষমা চাইতে মানুষকে এ ছাড়া আর অন্য কিছুই বাধা দেয় না যে, (তারা অপেক্ষায় থাকে যে) অতীতের জাতিগুলোর সঙ্গে যা করা হয়েছে, কখন তাদের সঙ্গেও তাই করা হবে অথবা কখন ‘আযাবকে তারা সরাসরি সামনে দেখতে পাবে।', 'And nothing has prevented the people from believing when guidance came to them and from asking forgiveness of their Lord except that there [must] befall them the [accustomed] precedent of the former peoples or that the punishment should come [directly] before them.', 'তাদের কাছে যখন পথের নির্দেশ আসে তখন ঈমান আনতে আর তাদের প্রতিপালকের কাছে ক্ষমা চাইতে মানুষকে এ ছাড়া আর অন্য কিছুই বাধা দেয় না যে, (তারা অপেক্ষায় থাকে যে) অতীতের জাতিগুলোর সঙ্গে যা করা হয়েছে, কখন তাদের সঙ্গেও তাই করা হবে অথবা কখন ‘আযাবকে তারা সরাসরি সামনে দেখতে পাবে।', 'And nothing has prevented the people from believing when guidance came to them and from asking forgiveness of their Lord except that there [must] befall them the [accustomed] precedent of the former peoples or that the punishment should come [directly] before them.', NULL, NULL, NULL, NULL, NULL, 'https://everyayah.com/data/Alafasy_128kbps/018055.mp3', now()),
  (18, 56, '', '[{"id":52220,"position":1,"text_uthmani":"وَمَا","transliteration":"wamā","translation_bn":"এবং না","root":"—","lemma":"مَا\r","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":52221,"position":2,"text_uthmani":"نُرْسِلُ","transliteration":"nur''silu","translation_bn":"আমরা প্রেরণ করি","root":"رسل","lemma":"أَرْسَلَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":52222,"position":3,"text_uthmani":"ٱلْمُرْسَلِينَ","transliteration":"l-mur''salīna","translation_bn":"রাসূলদেরকে","root":"رسل","lemma":"مُّرْسَل","grammar_bn":"শব্দ"},{"id":52223,"position":4,"text_uthmani":"إِلَّا","transliteration":"illā","translation_bn":"ছাড়া","root":"—","lemma":"إِلَّا\r","grammar_bn":"সীমাবদ্ধতা (Restriction)"},{"id":52224,"position":5,"text_uthmani":"مُبَشِّرِينَ","transliteration":"mubashirīna","translation_bn":"সুসংবাদদাতা","root":"بشر","lemma":"مُبَشِّر","grammar_bn":"বিশেষ্য (Noun)"},{"id":52225,"position":6,"text_uthmani":"وَمُنذِرِينَ ۚ","transliteration":"wamundhirīna","translation_bn":"এবং সতর্ককারী (রূপে)","root":"نذر","lemma":"مُنذِر","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":52227,"position":7,"text_uthmani":"وَيُجَـٰدِلُ","transliteration":"wayujādilu","translation_bn":"এবং বিতর্ক করে","root":"جدل","lemma":"جَٰدَلُ","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":52228,"position":8,"text_uthmani":"ٱلَّذِينَ","transliteration":"alladhīna","translation_bn":"যারা","root":"—","lemma":"ٱلَّذِى","grammar_bn":"সাপেক্ষ সর্বনাম (Relative)"},{"id":52229,"position":9,"text_uthmani":"كَفَرُوا۟","transliteration":"kafarū","translation_bn":"অস্বীকার করেছে","root":"كفر","lemma":"كَفَرَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":52230,"position":10,"text_uthmani":"بِٱلْبَـٰطِلِ","transliteration":"bil-bāṭili","translation_bn":"দিয়ে মিথ্যা","root":"بطل","lemma":"بَٰطِل","grammar_bn":"অব্যয় (Preposition)"},{"id":52231,"position":11,"text_uthmani":"لِيُدْحِضُوا۟","transliteration":"liyud''ḥiḍū","translation_bn":"যেন তারা ব্যর্থ করতে পারে","root":"دحض","lemma":"يُدْحِضُ","grammar_bn":"শব্দ"},{"id":52232,"position":12,"text_uthmani":"بِهِ","transliteration":"bihi","translation_bn":"দিয়ে তা","root":"—","lemma":"بِهِ","grammar_bn":"অব্যয় (Preposition)"},{"id":52233,"position":13,"text_uthmani":"ٱلْحَقَّ ۖ","transliteration":"l-ḥaqa","translation_bn":"সত্যকে","root":"حقق","lemma":"حَقّ","grammar_bn":"শব্দ"},{"id":52235,"position":14,"text_uthmani":"وَٱتَّخَذُوٓا۟","transliteration":"wa-ittakhadhū","translation_bn":"এবং তারা গ্রহণ করেছে","root":"اخذ","lemma":"ٱتَّخَذَ","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":52236,"position":15,"text_uthmani":"ءَايَـٰتِى","transliteration":"āyātī","translation_bn":"আমার নিদর্শনগুলোকে","root":"ايي","lemma":"ءَايَة","grammar_bn":"বিশেষ্য (Noun)"},{"id":52237,"position":16,"text_uthmani":"وَمَآ","transliteration":"wamā","translation_bn":"এবং (সেগুলোকে) যার","root":"—","lemma":"مَا\r","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":52238,"position":17,"text_uthmani":"أُنذِرُوا۟","transliteration":"undhirū","translation_bn":"সতর্ক করা হয়েছে","root":"نذر","lemma":"أَنذَرَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":52239,"position":18,"text_uthmani":"هُزُوًۭا","transliteration":"huzuwan","translation_bn":"বিদ্রূপরূপে","root":"هزا","lemma":"هُزُو","grammar_bn":"বিশেষ্য (Noun)"},{"id":52240,"position":19,"text_uthmani":"٥٦","transliteration":"","translation_bn":"(৫৬)","root":"—","lemma":"٥٦","grammar_bn":"মার্কার"}]'::jsonb, 'wamā nur''silu l-mur''salīna illā mubashirīna wamundhirīna wayujādilu alladhīna kafarū bil-bāṭili liyud''ḥiḍū bihi l-ḥaqa wa-ittakhadhū āyātī wamā undhirū huzuwan', 'আমি রসূলদেরকে পাঠিয়ে থাকি একমাত্র সুসংবাদদাতা আর সতর্ককারী হিসেবে। কিন্তু কাফিরগণ মিথ্যা যুক্তি পেশ করে বিতর্ক করছে তা দিয়ে সত্যকে দুর্বল করে দেয়ার উদ্দেশে, আর তারা আমার নিদর্শন ও ভয় দেখানোকে হাসি-তামাশার বিষয় বানিয়ে নিয়েছে।', 'And We send not the messengers except as bringers of good tidings and warners. And those who disbelieve dispute by [using] falsehood to [attempt to] invalidate thereby the truth and have taken My verses, and that of which they are warned, in ridicule.', 'আমি রসূলদেরকে পাঠিয়ে থাকি একমাত্র সুসংবাদদাতা আর সতর্ককারী হিসেবে। কিন্তু কাফিরগণ মিথ্যা যুক্তি পেশ করে বিতর্ক করছে তা দিয়ে সত্যকে দুর্বল করে দেয়ার উদ্দেশে, আর তারা আমার নিদর্শন ও ভয় দেখানোকে হাসি-তামাশার বিষয় বানিয়ে নিয়েছে।', 'And We send not the messengers except as bringers of good tidings and warners. And those who disbelieve dispute by [using] falsehood to [attempt to] invalidate thereby the truth and have taken My verses, and that of which they are warned, in ridicule.', NULL, NULL, NULL, NULL, NULL, 'https://everyayah.com/data/Alafasy_128kbps/018056.mp3', now()),
  (18, 57, '', '[{"id":52632,"position":1,"text_uthmani":"وَمَنْ","transliteration":"waman","translation_bn":"এবং কে","root":"—","lemma":"مَن\r","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":52633,"position":2,"text_uthmani":"أَظْلَمُ","transliteration":"aẓlamu","translation_bn":"অধিক সীমালঙ্ঘনকারী","root":"ظلم","lemma":"أَظْلَم","grammar_bn":"বিশেষ্য (Noun)"},{"id":52634,"position":3,"text_uthmani":"مِمَّن","transliteration":"mimman","translation_bn":"(তার) চেয়ে যাকে","root":"—","lemma":"مِن\r","grammar_bn":"অব্যয় (Preposition)"},{"id":52635,"position":4,"text_uthmani":"ذُكِّرَ","transliteration":"dhukkira","translation_bn":"স্মরণ করিয়ে দেয়া হয়েছে","root":"ذكر","lemma":"ذُكِّرَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":52636,"position":5,"text_uthmani":"بِـَٔايَـٰتِ","transliteration":"biāyāti","translation_bn":"দিয়ে নিদর্শন","root":"ايي","lemma":"ءَايَة","grammar_bn":"অব্যয় (Preposition)"},{"id":52637,"position":6,"text_uthmani":"رَبِّهِۦ","transliteration":"rabbihi","translation_bn":"রবের তার","root":"ربب","lemma":"رَبّ","grammar_bn":"বিশেষ্য (Noun)"},{"id":52638,"position":7,"text_uthmani":"فَأَعْرَضَ","transliteration":"fa-aʿraḍa","translation_bn":"তবুও সে মুখ ফিরিয়ে নিয়েছে","root":"عرض","lemma":"أَعْرَضَ","grammar_bn":"শব্দ"},{"id":52639,"position":8,"text_uthmani":"عَنْهَا","transliteration":"ʿanhā","translation_bn":"থেকে তা","root":"—","lemma":"عَن\r","grammar_bn":"অব্যয় (Preposition)"},{"id":52640,"position":9,"text_uthmani":"وَنَسِىَ","transliteration":"wanasiya","translation_bn":"ও ভুলে গিয়েছে","root":"نسي","lemma":"نَسِىَ","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":52641,"position":10,"text_uthmani":"مَا","transliteration":"mā","translation_bn":"যা","root":"—","lemma":"مَا\r","grammar_bn":"সাপেক্ষ সর্বনাম (Relative)"},{"id":52642,"position":11,"text_uthmani":"قَدَّمَتْ","transliteration":"qaddamat","translation_bn":"আগে পাঠিয়েছে","root":"قدم","lemma":"قَدَّمَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":52643,"position":12,"text_uthmani":"يَدَاهُ ۚ","transliteration":"yadāhu","translation_bn":"তার দু''হাত","root":"يدي","lemma":"يَد","grammar_bn":"বিশেষ্য (Noun)"},{"id":52645,"position":13,"text_uthmani":"إِنَّا","transliteration":"innā","translation_bn":"নিশ্চয়ই আমরা","root":"—","lemma":"إِنّ","grammar_bn":"অভিঘাত পদ (Accusative)"},{"id":52646,"position":14,"text_uthmani":"جَعَلْنَا","transliteration":"jaʿalnā","translation_bn":"আমরা দিয়েছি","root":"جعل","lemma":"جَعَلَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":52647,"position":15,"text_uthmani":"عَلَىٰ","transliteration":"ʿalā","translation_bn":"উপর","root":"—","lemma":"عَلَىٰ\r","grammar_bn":"অব্যয় (Preposition)"},{"id":52648,"position":16,"text_uthmani":"قُلُوبِهِمْ","transliteration":"qulūbihim","translation_bn":"তাদের অন্তরগুলোর","root":"قلب","lemma":"قَلْب","grammar_bn":"বিশেষ্য (Noun)"},{"id":52649,"position":17,"text_uthmani":"أَكِنَّةً","transliteration":"akinnatan","translation_bn":"আবরণ","root":"كنن","lemma":"أَكِنَّة","grammar_bn":"বিশেষ্য (Noun)"},{"id":52650,"position":18,"text_uthmani":"أَن","transliteration":"an","translation_bn":"যেন (না)","root":"—","lemma":"أَن\r","grammar_bn":"অধীনস্থ যোজক (Subordinating)"},{"id":52651,"position":19,"text_uthmani":"يَفْقَهُوهُ","transliteration":"yafqahūhu","translation_bn":"তা তারা বুঝে","root":"فقه","lemma":"يَفْقَهُ","grammar_bn":"ক্রিয়া (Verb)"},{"id":52652,"position":20,"text_uthmani":"وَفِىٓ","transliteration":"wafī","translation_bn":"ও মধ্যে","root":"—","lemma":"فِى\r","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":52653,"position":21,"text_uthmani":"ءَاذَانِهِمْ","transliteration":"ādhānihim","translation_bn":"কানগুলোর তাদের","root":"اذن","lemma":"أُذُنٌ","grammar_bn":"বিশেষ্য (Noun)"},{"id":52654,"position":22,"text_uthmani":"وَقْرًۭا ۖ","transliteration":"waqran","translation_bn":"বধিরতা (দিয়েছি)","root":"وقر","lemma":"وَقْر","grammar_bn":"বিশেষ্য (Noun)"},{"id":52656,"position":23,"text_uthmani":"وَإِن","transliteration":"wa-in","translation_bn":"এবং যদি","root":"—","lemma":"إِن\r","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":52657,"position":24,"text_uthmani":"تَدْعُهُمْ","transliteration":"tadʿuhum","translation_bn":"তুমি ডাকো তাদেরকে","root":"دعو","lemma":"دَعَا","grammar_bn":"ক্রিয়া (Verb)"},{"id":52658,"position":25,"text_uthmani":"إِلَى","transliteration":"ilā","translation_bn":"দিকে","root":"—","lemma":"إِلَىٰ\r","grammar_bn":"অব্যয় (Preposition)"},{"id":52659,"position":26,"text_uthmani":"ٱلْهُدَىٰ","transliteration":"l-hudā","translation_bn":"সৎপথে","root":"هدي","lemma":"هُدًى","grammar_bn":"শব্দ"},{"id":52660,"position":27,"text_uthmani":"فَلَن","transliteration":"falan","translation_bn":"তবুও না","root":"—","lemma":"لَن\r","grammar_bn":"শব্দ"},{"id":52661,"position":28,"text_uthmani":"يَهْتَدُوٓا۟","transliteration":"yahtadū","translation_bn":"তারা সঠিক পথ পাবে","root":"هدي","lemma":"ٱهْتَدَىٰ","grammar_bn":"ক্রিয়া (Verb)"},{"id":52662,"position":29,"text_uthmani":"إِذًا","transliteration":"idhan","translation_bn":"তাহ''লে","root":"—","lemma":"إِذًا\r","grammar_bn":"আশ্চর্যসূচক (Surprise)"},{"id":52663,"position":30,"text_uthmani":"أَبَدًۭا","transliteration":"abadan","translation_bn":"কখনও","root":"ابد","lemma":"أَبَدًا","grammar_bn":"কালবাচক (Time)"},{"id":52664,"position":31,"text_uthmani":"٥٧","transliteration":"","translation_bn":"(৫৭)","root":"—","lemma":"٥٧","grammar_bn":"মার্কার"}]'::jsonb, 'waman aẓlamu mimman dhukkira biāyāti rabbihi fa-aʿraḍa ʿanhā wanasiya mā qaddamat yadāhu innā jaʿalnā ʿalā qulūbihim akinnatan an yafqahūhu wafī ādhānihim waqran wa-in tadʿuhum ilā l-hudā falan yahtadū idhan abadan', 'তার থেকে বড় যালিম আর কে আছে যাকে তার প্রতিপালকের আয়াতগুলো স্মরণ করিয়ে দেয়া হলে সে তাত্থেকে মুখ ফিরিয়ে নেয় আর সে পূর্বে কৃত তার কর্মের (খারাপ পরিণতির) কথা ভুলে যায়। আমি তাদের অন্তরের উপর আবরণ দিয়ে দিয়েছি যাতে তারা তা (অর্থাৎ কুরআন) বুঝতে না পারে, আর তাদের কানে এঁটে দিয়েছি বধিরতা। তুমি তাদেরকে সৎপথে ডাকলেও তারা কক্ষনো সৎপথ গ্রহণ করবে না।', 'And who is more unjust than one who is reminded of the verses of his Lord but turns away from them and forgets what his hands have put forth? Indeed, We have placed over their hearts coverings, lest they understand it, and in their ears deafness. And if you invite them to guidance - they will never be guided, then - ever.', 'তার থেকে বড় যালিম আর কে আছে যাকে তার প্রতিপালকের আয়াতগুলো স্মরণ করিয়ে দেয়া হলে সে তাত্থেকে মুখ ফিরিয়ে নেয় আর সে পূর্বে কৃত তার কর্মের (খারাপ পরিণতির) কথা ভুলে যায়। আমি তাদের অন্তরের উপর আবরণ দিয়ে দিয়েছি যাতে তারা তা (অর্থাৎ কুরআন) বুঝতে না পারে, আর তাদের কানে এঁটে দিয়েছি বধিরতা। তুমি তাদেরকে সৎপথে ডাকলেও তারা কক্ষনো সৎপথ গ্রহণ করবে না।', 'And who is more unjust than one who is reminded of the verses of his Lord but turns away from them and forgets what his hands have put forth? Indeed, We have placed over their hearts coverings, lest they understand it, and in their ears deafness. And if you invite them to guidance - they will never be guided, then - ever.', NULL, NULL, NULL, NULL, NULL, 'https://everyayah.com/data/Alafasy_128kbps/018057.mp3', now()),
  (18, 58, '', '[{"id":53122,"position":1,"text_uthmani":"وَرَبُّكَ","transliteration":"warabbuka","translation_bn":"এবং তোমার রব","root":"ربب","lemma":"رَبّ","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":53123,"position":2,"text_uthmani":"ٱلْغَفُورُ","transliteration":"l-ghafūru","translation_bn":"ক্ষমাশীল","root":"غفر","lemma":"غَفُور","grammar_bn":"শব্দ"},{"id":53124,"position":3,"text_uthmani":"ذُو","transliteration":"dhū","translation_bn":"অধিকারী","root":"—","lemma":"ذُو","grammar_bn":"বিশেষ্য (Noun)"},{"id":53125,"position":4,"text_uthmani":"ٱلرَّحْمَةِ ۖ","transliteration":"l-raḥmati","translation_bn":"অনুগ্রহের","root":"رحم","lemma":"رَحْمَة","grammar_bn":"শব্দ"},{"id":53127,"position":5,"text_uthmani":"لَوْ","transliteration":"law","translation_bn":"যদি","root":"—","lemma":"لَو\r","grammar_bn":"শর্তবাচক (Conditional)"},{"id":53128,"position":6,"text_uthmani":"يُؤَاخِذُهُم","transliteration":"yuākhidhuhum","translation_bn":"পাকড়াও করতেন তিনি তাদের","root":"اخذ","lemma":"يُؤَاخِذُ","grammar_bn":"ক্রিয়া (Verb)"},{"id":53129,"position":7,"text_uthmani":"بِمَا","transliteration":"bimā","translation_bn":"এ কারণে যা","root":"—","lemma":"مَا\r","grammar_bn":"অব্যয় (Preposition)"},{"id":53130,"position":8,"text_uthmani":"كَسَبُوا۟","transliteration":"kasabū","translation_bn":"তারা অর্জন করেছিলো","root":"كسب","lemma":"كَسَبَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":53131,"position":9,"text_uthmani":"لَعَجَّلَ","transliteration":"laʿajjala","translation_bn":"অবশ্যই তাড়াতাড়ি এগিয়ে আনতেন","root":"عجل","lemma":"عَجَّلَ","grammar_bn":"দৃঢ়তাবোধক (Emphatic)"},{"id":53132,"position":10,"text_uthmani":"لَهُمُ","transliteration":"lahumu","translation_bn":"জন্যে তাদের","root":"—","lemma":"لَهُمُ","grammar_bn":"অব্যয় (Preposition)"},{"id":53133,"position":11,"text_uthmani":"ٱلْعَذَابَ ۚ","transliteration":"l-ʿadhāba","translation_bn":"শাস্তি","root":"عذب","lemma":"عَذَاب","grammar_bn":"শব্দ"},{"id":53135,"position":12,"text_uthmani":"بَل","transliteration":"bal","translation_bn":"বরং","root":"—","lemma":"بَل\r","grammar_bn":"প্রত্যাহার পদ (Retraction)"},{"id":53136,"position":13,"text_uthmani":"لَّهُم","transliteration":"lahum","translation_bn":"জন্যে রয়েছে তাদের","root":"—","lemma":"لَّهُم","grammar_bn":"অব্যয় (Preposition)"},{"id":53137,"position":14,"text_uthmani":"مَّوْعِدٌۭ","transliteration":"mawʿidun","translation_bn":"প্রতিশ্রুত সময়","root":"وعد","lemma":"مَّوْعِد","grammar_bn":"বিশেষ্য (Noun)"},{"id":53138,"position":15,"text_uthmani":"لَّن","transliteration":"lan","translation_bn":"কখনও না","root":"—","lemma":"لَن\r","grammar_bn":"না-বোধক (Negative)"},{"id":53139,"position":16,"text_uthmani":"يَجِدُوا۟","transliteration":"yajidū","translation_bn":"তারা পাবে","root":"وجد","lemma":"وَجَدَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":53140,"position":17,"text_uthmani":"مِن","transliteration":"min","translation_bn":"ছাড়া","root":"—","lemma":"مِن\r","grammar_bn":"অব্যয় (Preposition)"},{"id":53141,"position":18,"text_uthmani":"دُونِهِۦ","transliteration":"dūnihi","translation_bn":"তিনি","root":"دون","lemma":"دُون","grammar_bn":"বিশেষ্য (Noun)"},{"id":53142,"position":19,"text_uthmani":"مَوْئِلًۭا","transliteration":"mawilan","translation_bn":"পালানোর জায়গা","root":"وال","lemma":"مَوْئِل","grammar_bn":"বিশেষ্য (Noun)"},{"id":53143,"position":20,"text_uthmani":"٥٨","transliteration":"","translation_bn":"(৫৮)","root":"—","lemma":"٥٨","grammar_bn":"মার্কার"}]'::jsonb, 'warabbuka l-ghafūru dhū l-raḥmati law yuākhidhuhum bimā kasabū laʿajjala lahumu l-ʿadhāba bal lahum mawʿidun lan yajidū min dūnihi mawilan', 'তোমার প্রতিপালক ক্ষমাশীল, দয়ার আধার। তাদের কৃতকর্মের জন্য তিনি যদি তাদেরকে পাকড়াও করতেন, তাহলে তাদের উপর অবশ্যই শীঘ্রই ‘আযার পাঠাতেন, কিন্তু তাদের সঙ্গে কৃত ওয়া‘দার জন্য আছে নির্দিষ্ট সময়, যাকে পাশ কাটিয়ে তারা কক্ষনো আশ্রয়ের কোন জায়গা পাবে না।', 'And your Lord is the Forgiving, full of mercy. If He were to impose blame upon them for what they earned, He would have hastened for them the punishment. Rather, for them is an appointment from which they will never find an escape.', 'তোমার প্রতিপালক ক্ষমাশীল, দয়ার আধার। তাদের কৃতকর্মের জন্য তিনি যদি তাদেরকে পাকড়াও করতেন, তাহলে তাদের উপর অবশ্যই শীঘ্রই ‘আযার পাঠাতেন, কিন্তু তাদের সঙ্গে কৃত ওয়া‘দার জন্য আছে নির্দিষ্ট সময়, যাকে পাশ কাটিয়ে তারা কক্ষনো আশ্রয়ের কোন জায়গা পাবে না।', 'And your Lord is the Forgiving, full of mercy. If He were to impose blame upon them for what they earned, He would have hastened for them the punishment. Rather, for them is an appointment from which they will never find an escape.', NULL, NULL, NULL, NULL, NULL, 'https://everyayah.com/data/Alafasy_128kbps/018058.mp3', now()),
  (18, 59, '', '[{"id":53873,"position":1,"text_uthmani":"وَتِلْكَ","transliteration":"watil''ka","translation_bn":"এবং এসব","root":"—","lemma":"ذَٰلِك","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":53874,"position":2,"text_uthmani":"ٱلْقُرَىٰٓ","transliteration":"l-qurā","translation_bn":"জনপদগুলো","root":"قري","lemma":"قَرْيَة","grammar_bn":"শব্দ"},{"id":53875,"position":3,"text_uthmani":"أَهْلَكْنَـٰهُمْ","transliteration":"ahlaknāhum","translation_bn":"আমরা ধ্বংস করেছি তাদের","root":"هلك","lemma":"أَهْلَكَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":53876,"position":4,"text_uthmani":"لَمَّا","transliteration":"lammā","translation_bn":"যখন","root":"—","lemma":"لَمَّا\r","grammar_bn":"কালবাচক (Time)"},{"id":53877,"position":5,"text_uthmani":"ظَلَمُوا۟","transliteration":"ẓalamū","translation_bn":"তারা সীমালঙ্ঘন করেছিলো","root":"ظلم","lemma":"ظَلَمَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":53878,"position":6,"text_uthmani":"وَجَعَلْنَا","transliteration":"wajaʿalnā","translation_bn":"এবং আমরা নির্দিষ্ট করে রেখেছি","root":"جعل","lemma":"جَعَلَ","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":53879,"position":7,"text_uthmani":"لِمَهْلِكِهِم","transliteration":"limahlikihim","translation_bn":"জন্যে তাদের ধ্বংসের","root":"هلك","lemma":"مَهْلِك","grammar_bn":"অব্যয় (Preposition)"},{"id":53880,"position":8,"text_uthmani":"مَّوْعِدًۭا","transliteration":"mawʿidan","translation_bn":"একটা নির্দিষ্ট সময়","root":"وعد","lemma":"مَّوْعِد","grammar_bn":"বিশেষ্য (Noun)"},{"id":53881,"position":9,"text_uthmani":"٥٩","transliteration":"","translation_bn":"(৫৯)","root":"—","lemma":"٥٩","grammar_bn":"মার্কার"}]'::jsonb, 'watil''ka l-qurā ahlaknāhum lammā ẓalamū wajaʿalnā limahlikihim mawʿidan', 'ঐ সব জনদপকে আমি ধ্বংস করে দিয়েছিলাম যখন তারা বাড়াবাড়ি করেছিল, আর তাদের ধ্বংস সাধনের জন্য একটা প্রতিশ্রুত সময় স্থির করেছিলাম।', 'And those cities - We destroyed them when they wronged, and We made for their destruction an appointed time.', 'ঐ সব জনদপকে আমি ধ্বংস করে দিয়েছিলাম যখন তারা বাড়াবাড়ি করেছিল, আর তাদের ধ্বংস সাধনের জন্য একটা প্রতিশ্রুত সময় স্থির করেছিলাম।', 'And those cities - We destroyed them when they wronged, and We made for their destruction an appointed time.', NULL, NULL, NULL, NULL, NULL, 'https://everyayah.com/data/Alafasy_128kbps/018059.mp3', now()),
  (18, 60, '', '[{"id":54357,"position":1,"text_uthmani":"وَإِذْ","transliteration":"wa-idh","translation_bn":"এবং যখন","root":"—","lemma":"إِذ\r","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":54358,"position":2,"text_uthmani":"قَالَ","transliteration":"qāla","translation_bn":"বলেছিলো","root":"قول","lemma":"قَالَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":54359,"position":3,"text_uthmani":"مُوسَىٰ","transliteration":"mūsā","translation_bn":"মূসা","root":"—","lemma":"مُوسَىٰ","grammar_bn":"নামবাচক বিশেষ্য (Proper Noun)"},{"id":54360,"position":4,"text_uthmani":"لِفَتَىٰهُ","transliteration":"lifatāhu","translation_bn":"তার যুবক (সেবক)-কে","root":"فتي","lemma":"فَتَىٰ","grammar_bn":"অব্যয় (Preposition)"},{"id":54361,"position":5,"text_uthmani":"لَآ","transliteration":"lā","translation_bn":"\"না","root":"—","lemma":"لَا\r","grammar_bn":"না-বোধক (Negative)"},{"id":54362,"position":6,"text_uthmani":"أَبْرَحُ","transliteration":"abraḥu","translation_bn":"আমি থামবো","root":"برح","lemma":"أَبْرَحَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":54363,"position":7,"text_uthmani":"حَتَّىٰٓ","transliteration":"ḥattā","translation_bn":"যতক্ষণ না","root":"—","lemma":"حَتَّىٰ\r","grammar_bn":"অব্যয় (Preposition)"},{"id":54364,"position":8,"text_uthmani":"أَبْلُغَ","transliteration":"ablugha","translation_bn":"পৌঁছাবো আমি","root":"بلغ","lemma":"بَلَغَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":54365,"position":9,"text_uthmani":"مَجْمَعَ","transliteration":"majmaʿa","translation_bn":"সংগমস্থলে","root":"جمع","lemma":"مَجْمَع","grammar_bn":"বিশেষ্য (Noun)"},{"id":54366,"position":10,"text_uthmani":"ٱلْبَحْرَيْنِ","transliteration":"l-baḥrayni","translation_bn":"দুই সাগরের","root":"بحر","lemma":"بَحْر","grammar_bn":"শব্দ"},{"id":54367,"position":11,"text_uthmani":"أَوْ","transliteration":"aw","translation_bn":"বা","root":"—","lemma":"أَو\r","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":54368,"position":12,"text_uthmani":"أَمْضِىَ","transliteration":"amḍiya","translation_bn":"আমি চলতে থাকবো","root":"مضي","lemma":"مَضَىٰ","grammar_bn":"ক্রিয়া (Verb)"},{"id":54369,"position":13,"text_uthmani":"حُقُبًۭا","transliteration":"ḥuquban","translation_bn":"যুগ যুগ (দীর্ঘকাল)\"","root":"حقب","lemma":"حُقُب","grammar_bn":"বিশেষ্য (Noun)"},{"id":54370,"position":14,"text_uthmani":"٦٠","transliteration":"","translation_bn":"(৬০)","root":"—","lemma":"٦٠","grammar_bn":"মার্কার"}]'::jsonb, 'wa-idh qāla mūsā lifatāhu lā abraḥu ḥattā ablugha majmaʿa l-baḥrayni aw amḍiya ḥuquban', 'স্মরণ কর, যখন মূসা তার সঙ্গীকে বলেছিল, ‘দুই সমুদ্রের মিলনস্থলে পৌঁছা না পর্যন্ত আমি চলতেই থাকবো যদিও বছরের পর বছর চলতেও হয়।’', 'And [mention] when Moses said to his servant, "I will not cease [traveling] until I reach the junction of the two seas or continue for a long period."', 'স্মরণ কর, যখন মূসা তার সঙ্গীকে বলেছিল, ‘দুই সমুদ্রের মিলনস্থলে পৌঁছা না পর্যন্ত আমি চলতেই থাকবো যদিও বছরের পর বছর চলতেও হয়।’', 'And [mention] when Moses said to his servant, "I will not cease [traveling] until I reach the junction of the two seas or continue for a long period."', NULL, NULL, NULL, NULL, NULL, 'https://everyayah.com/data/Alafasy_128kbps/018060.mp3', now()),
  (18, 61, '', '[{"id":55014,"position":1,"text_uthmani":"فَلَمَّا","transliteration":"falammā","translation_bn":"অতঃপর যখন","root":"—","lemma":"لَمَّا\r","grammar_bn":"শব্দ"},{"id":55015,"position":2,"text_uthmani":"بَلَغَا","transliteration":"balaghā","translation_bn":"দু''জনে পৌঁছে গেলো","root":"بلغ","lemma":"بَلَغَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":55016,"position":3,"text_uthmani":"مَجْمَعَ","transliteration":"majmaʿa","translation_bn":"সংগমস্থলে","root":"جمع","lemma":"مَجْمَع","grammar_bn":"বিশেষ্য (Noun)"},{"id":55017,"position":4,"text_uthmani":"بَيْنِهِمَا","transliteration":"baynihimā","translation_bn":"দুই (সাগরের) মাঝের","root":"بين","lemma":"بَيْن","grammar_bn":"বিশেষ্য (Noun)"},{"id":55018,"position":5,"text_uthmani":"نَسِيَا","transliteration":"nasiyā","translation_bn":"দু''জনে ভুলে গেলো","root":"نسي","lemma":"نَسِىَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":55019,"position":6,"text_uthmani":"حُوتَهُمَا","transliteration":"ḥūtahumā","translation_bn":"দু''জনের মাছকে","root":"حوت","lemma":"حُوت","grammar_bn":"বিশেষ্য (Noun)"},{"id":55020,"position":7,"text_uthmani":"فَٱتَّخَذَ","transliteration":"fa-ittakhadha","translation_bn":"অতঃপর (মাছ) করে নিলো","root":"اخذ","lemma":"ٱتَّخَذَ","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":55021,"position":8,"text_uthmani":"سَبِيلَهُۥ","transliteration":"sabīlahu","translation_bn":"পথ তার","root":"سبل","lemma":"سَبِيل","grammar_bn":"বিশেষ্য (Noun)"},{"id":55022,"position":9,"text_uthmani":"فِى","transliteration":"fī","translation_bn":"মধ্যে","root":"—","lemma":"فِى\r","grammar_bn":"অব্যয় (Preposition)"},{"id":55023,"position":10,"text_uthmani":"ٱلْبَحْرِ","transliteration":"l-baḥri","translation_bn":"সমুদ্রের","root":"بحر","lemma":"بَحْر","grammar_bn":"শব্দ"},{"id":55024,"position":11,"text_uthmani":"سَرَبًۭا","transliteration":"saraban","translation_bn":"সুড়ঙ্গ করে","root":"سرب","lemma":"سَرَب","grammar_bn":"বিশেষ্য (Noun)"},{"id":55025,"position":12,"text_uthmani":"٦١","transliteration":"","translation_bn":"(৬১)","root":"—","lemma":"٦١","grammar_bn":"মার্কার"}]'::jsonb, 'falammā balaghā majmaʿa baynihimā nasiyā ḥūtahumā fa-ittakhadha sabīlahu fī l-baḥri saraban', 'অতঃপর যখন তারা দু’জনে দুই সমুদ্রের মিলন স্থলে পৌঁছল, তারা তাদের মাছের কথা ভুলে গেল আর সেটি সমুদ্রে তার পথ করে নিল সুড়ঙ্গের মত।', 'But when they reached the junction between them, they forgot their fish, and it took its course into the sea, slipping away.', 'অতঃপর যখন তারা দু’জনে দুই সমুদ্রের মিলন স্থলে পৌঁছল, তারা তাদের মাছের কথা ভুলে গেল আর সেটি সমুদ্রে তার পথ করে নিল সুড়ঙ্গের মত।', 'But when they reached the junction between them, they forgot their fish, and it took its course into the sea, slipping away.', NULL, NULL, NULL, NULL, NULL, 'https://everyayah.com/data/Alafasy_128kbps/018061.mp3', now()),
  (18, 62, '', '[{"id":55560,"position":1,"text_uthmani":"فَلَمَّا","transliteration":"falammā","translation_bn":"অতঃপর যখন","root":"—","lemma":"لَمَّا\r","grammar_bn":"শব্দ"},{"id":55561,"position":2,"text_uthmani":"جَاوَزَا","transliteration":"jāwazā","translation_bn":"দু''জনে অতিক্রম করলো","root":"جوز","lemma":"جَاوَزَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":55562,"position":3,"text_uthmani":"قَالَ","transliteration":"qāla","translation_bn":"সে বললো","root":"قول","lemma":"قَالَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":55563,"position":4,"text_uthmani":"لِفَتَىٰهُ","transliteration":"lifatāhu","translation_bn":"তার যুবক (সেবক)-কে","root":"فتي","lemma":"فَتَىٰ","grammar_bn":"অব্যয় (Preposition)"},{"id":55564,"position":5,"text_uthmani":"ءَاتِنَا","transliteration":"ātinā","translation_bn":"\"আমাদেরকে দাও","root":"اتي","lemma":"ا^تَى","grammar_bn":"ক্রিয়া (Verb)"},{"id":55565,"position":6,"text_uthmani":"غَدَآءَنَا","transliteration":"ghadāanā","translation_bn":"আমাদের (নাশতা) খাবার","root":"غدو","lemma":"غَدَا^ء","grammar_bn":"বিশেষ্য (Noun)"},{"id":55566,"position":7,"text_uthmani":"لَقَدْ","transliteration":"laqad","translation_bn":"নিশ্চয়ই","root":"—","lemma":"قَد\r","grammar_bn":"দৃঢ়তাবোধক (Emphatic)"},{"id":55567,"position":8,"text_uthmani":"لَقِينَا","transliteration":"laqīnā","translation_bn":"আমরা পেয়েছি","root":"لقي","lemma":"لَقُ","grammar_bn":"ক্রিয়া (Verb)"},{"id":55568,"position":9,"text_uthmani":"مِن","transliteration":"min","translation_bn":"থেকে","root":"—","lemma":"مِن\r","grammar_bn":"অব্যয় (Preposition)"},{"id":55569,"position":10,"text_uthmani":"سَفَرِنَا","transliteration":"safarinā","translation_bn":"আমাদের ভ্রমণ","root":"سفر","lemma":"سَفَر","grammar_bn":"বিশেষ্য (Noun)"},{"id":55570,"position":11,"text_uthmani":"هَـٰذَا","transliteration":"hādhā","translation_bn":"এই","root":"—","lemma":"هَٰذَا","grammar_bn":"নির্দেশক সর্বনাম (Demonstrative)"},{"id":55571,"position":12,"text_uthmani":"نَصَبًۭا","transliteration":"naṣaban","translation_bn":"ক্লান্তি\"","root":"نصب","lemma":"نَصَب","grammar_bn":"বিশেষ্য (Noun)"},{"id":55572,"position":13,"text_uthmani":"٦٢","transliteration":"","translation_bn":"(৬২)","root":"—","lemma":"٦٢","grammar_bn":"মার্কার"}]'::jsonb, 'falammā jāwazā qāla lifatāhu ātinā ghadāanā laqad laqīnā min safarinā hādhā naṣaban', 'যখন তারা আরো এগিয়ে গেল, সে তার সঙ্গীকে বলল, ‘আমাদের সকালের খাবার আন, আমরা আমাদের এই সফরে বড়ই ক্লান্ত হয়ে পড়েছি।’', 'So when they had passed beyond it, [Moses] said to his boy, "Bring us our morning meal. We have certainly suffered in this, our journey, [much] fatigue."', 'যখন তারা আরো এগিয়ে গেল, সে তার সঙ্গীকে বলল, ‘আমাদের সকালের খাবার আন, আমরা আমাদের এই সফরে বড়ই ক্লান্ত হয়ে পড়েছি।’', 'So when they had passed beyond it, [Moses] said to his boy, "Bring us our morning meal. We have certainly suffered in this, our journey, [much] fatigue."', NULL, NULL, NULL, NULL, NULL, 'https://everyayah.com/data/Alafasy_128kbps/018062.mp3', now()),
  (18, 63, '', '[{"id":56047,"position":1,"text_uthmani":"قَالَ","transliteration":"qāla","translation_bn":"সে বললো","root":"قول","lemma":"قَالَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":56048,"position":2,"text_uthmani":"أَرَءَيْتَ","transliteration":"ara-ayta","translation_bn":"\"কি আপনি লক্ষ্য করেছেন","root":"راي","lemma":"رَءَا","grammar_bn":"প্রশ্নবোধক (Interrogative)"},{"id":56049,"position":3,"text_uthmani":"إِذْ","transliteration":"idh","translation_bn":"যখন","root":"—","lemma":"إِذ\r","grammar_bn":"কালবাচক (Time)"},{"id":56050,"position":4,"text_uthmani":"أَوَيْنَآ","transliteration":"awaynā","translation_bn":"আমরা আশ্রয় নিয়েছিলাম","root":"اوي","lemma":"أَوَى","grammar_bn":"ক্রিয়া (Verb)"},{"id":56051,"position":5,"text_uthmani":"إِلَى","transliteration":"ilā","translation_bn":"কাছে","root":"—","lemma":"إِلَىٰ\r","grammar_bn":"অব্যয় (Preposition)"},{"id":56052,"position":6,"text_uthmani":"ٱلصَّخْرَةِ","transliteration":"l-ṣakhrati","translation_bn":"পাথরের","root":"صخر","lemma":"صَخْرَة","grammar_bn":"শব্দ"},{"id":56053,"position":7,"text_uthmani":"فَإِنِّى","transliteration":"fa-innī","translation_bn":"তখন আমি নিশ্চয়ই","root":"—","lemma":"إِنّ","grammar_bn":"শব্দ"},{"id":56054,"position":8,"text_uthmani":"نَسِيتُ","transliteration":"nasītu","translation_bn":"ভুলে গিয়েছিলাম","root":"نسي","lemma":"نَسِىَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":56055,"position":9,"text_uthmani":"ٱلْحُوتَ","transliteration":"l-ḥūta","translation_bn":"মাছকে","root":"حوت","lemma":"حُوت","grammar_bn":"শব্দ"},{"id":56056,"position":10,"text_uthmani":"وَمَآ","transliteration":"wamā","translation_bn":"এবং না","root":"—","lemma":"مَا\r","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":56057,"position":11,"text_uthmani":"أَنسَىٰنِيهُ","transliteration":"ansānīhu","translation_bn":"তা আমাকে ভুলিয়েছিলো","root":"نسي","lemma":"أَنسَىٰ","grammar_bn":"ক্রিয়া (Verb)"},{"id":56058,"position":12,"text_uthmani":"إِلَّا","transliteration":"illā","translation_bn":"ছাড়া","root":"—","lemma":"إِلَّا\r","grammar_bn":"সীমাবদ্ধতা (Restriction)"},{"id":56059,"position":13,"text_uthmani":"ٱلشَّيْطَـٰنُ","transliteration":"l-shayṭānu","translation_bn":"শয়তান","root":"شطن","lemma":"شَيْطَٰن","grammar_bn":"শব্দ"},{"id":56060,"position":14,"text_uthmani":"أَنْ","transliteration":"an","translation_bn":"যে","root":"—","lemma":"أَن\r","grammar_bn":"অধীনস্থ যোজক (Subordinating)"},{"id":56061,"position":15,"text_uthmani":"أَذْكُرَهُۥ ۚ","transliteration":"adhkurahu","translation_bn":"তা উল্লেখ করবো আমি","root":"ذكر","lemma":"ذَكَرَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":56063,"position":16,"text_uthmani":"وَٱتَّخَذَ","transliteration":"wa-ittakhadha","translation_bn":"এবং করে নিলো (মাছ)","root":"اخذ","lemma":"ٱتَّخَذَ","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":56064,"position":17,"text_uthmani":"سَبِيلَهُۥ","transliteration":"sabīlahu","translation_bn":"পথ তার","root":"سبل","lemma":"سَبِيل","grammar_bn":"বিশেষ্য (Noun)"},{"id":56065,"position":18,"text_uthmani":"فِى","transliteration":"fī","translation_bn":"মধ্যে","root":"—","lemma":"فِى\r","grammar_bn":"অব্যয় (Preposition)"},{"id":56066,"position":19,"text_uthmani":"ٱلْبَحْرِ","transliteration":"l-baḥri","translation_bn":"সাগরের","root":"بحر","lemma":"بَحْر","grammar_bn":"শব্দ"},{"id":56067,"position":20,"text_uthmani":"عَجَبًۭا","transliteration":"ʿajaban","translation_bn":"আশ্চর্যভাবে\"","root":"عجب","lemma":"عَجَب","grammar_bn":"বিশেষণ (Adjective)"},{"id":56068,"position":21,"text_uthmani":"٦٣","transliteration":"","translation_bn":"(৬৩)","root":"—","lemma":"٦٣","grammar_bn":"মার্কার"}]'::jsonb, 'qāla ara-ayta idh awaynā ilā l-ṣakhrati fa-innī nasītu l-ḥūta wamā ansānīhu illā l-shayṭānu an adhkurahu wa-ittakhadha sabīlahu fī l-baḥri ʿajaban', 'সঙ্গীটি বলল, ‘আপনি কি লক্ষ্য করেছেন, আমরা যখন শিলাখন্ডে (বসে) ছিলাম তখন আমি মাছের কথা ভুলে গিয়েছিলাম। সেটার কথা আপনাকে বলতে শয়তানই আমাকে ভুলিয়ে দিয়েছিল আর মাছটি বিস্ময়করভাবে সমুদ্রে তার রাস্তা করে চলে গিয়েছিল।’', 'He said, "Did you see when we retired to the rock? Indeed, I forgot [there] the fish. And none made me forget it except Satan - that I should mention it. And it took its course into the sea amazingly".', 'সঙ্গীটি বলল, ‘আপনি কি লক্ষ্য করেছেন, আমরা যখন শিলাখন্ডে (বসে) ছিলাম তখন আমি মাছের কথা ভুলে গিয়েছিলাম। সেটার কথা আপনাকে বলতে শয়তানই আমাকে ভুলিয়ে দিয়েছিল আর মাছটি বিস্ময়করভাবে সমুদ্রে তার রাস্তা করে চলে গিয়েছিল।’', 'He said, "Did you see when we retired to the rock? Indeed, I forgot [there] the fish. And none made me forget it except Satan - that I should mention it. And it took its course into the sea amazingly".', NULL, NULL, NULL, NULL, NULL, 'https://everyayah.com/data/Alafasy_128kbps/018063.mp3', now()),
  (18, 64, '', '[{"id":56570,"position":1,"text_uthmani":"قَالَ","transliteration":"qāla","translation_bn":"সে বললো","root":"قول","lemma":"قَالَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":56571,"position":2,"text_uthmani":"ذَٰلِكَ","transliteration":"dhālika","translation_bn":"\"সেটাই","root":"—","lemma":"ذَٰلِك","grammar_bn":"নির্দেশক সর্বনাম (Demonstrative)"},{"id":56572,"position":3,"text_uthmani":"مَا","transliteration":"mā","translation_bn":"যা","root":"—","lemma":"مَا\r","grammar_bn":"সাপেক্ষ সর্বনাম (Relative)"},{"id":56573,"position":4,"text_uthmani":"كُنَّا","transliteration":"kunnā","translation_bn":"চেয়েছি","root":"كون","lemma":"كَانَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":56574,"position":5,"text_uthmani":"نَبْغِ ۚ","transliteration":"nabghi","translation_bn":"আমরা\"","root":"بغي","lemma":"بَغَىٰ","grammar_bn":"ক্রিয়া (Verb)"},{"id":56576,"position":6,"text_uthmani":"فَٱرْتَدَّا","transliteration":"fa-ir''taddā","translation_bn":"অতঃপর দু''জনে ফিরে চললো","root":"ردد","lemma":"ٱرْتَدَّ","grammar_bn":"শব্দ"},{"id":56577,"position":7,"text_uthmani":"عَلَىٰٓ","transliteration":"ʿalā","translation_bn":"উপর","root":"—","lemma":"عَلَىٰ\r","grammar_bn":"অব্যয় (Preposition)"},{"id":56578,"position":8,"text_uthmani":"ءَاثَارِهِمَا","transliteration":"āthārihimā","translation_bn":"তাদের দু''জনের পায়ের চিহ্ন","root":"اثر","lemma":"أَثَر","grammar_bn":"বিশেষ্য (Noun)"},{"id":56579,"position":9,"text_uthmani":"قَصَصًۭا","transliteration":"qaṣaṣan","translation_bn":"অনুসরণ করে","root":"قصص","lemma":"قَصَص","grammar_bn":"বিশেষ্য (Noun)"},{"id":56580,"position":10,"text_uthmani":"٦٤","transliteration":"","translation_bn":"(৬৪)","root":"—","lemma":"٦٤","grammar_bn":"মার্কার"}]'::jsonb, 'qāla dhālika mā kunnā nabghi fa-ir''taddā ʿalā āthārihimā qaṣaṣan', 'মূসা বলল, ‘এটাই তো সে জায়গা যেটা আমরা খুঁজছি।’ কাজেই তারা তাদের পায়ের চিহ্ন ধরে ফিরে গেল।', '[Moses] said, "That is what we were seeking." So they returned, following their footprints.', 'মূসা বলল, ‘এটাই তো সে জায়গা যেটা আমরা খুঁজছি।’ কাজেই তারা তাদের পায়ের চিহ্ন ধরে ফিরে গেল।', '[Moses] said, "That is what we were seeking." So they returned, following their footprints.', NULL, NULL, NULL, NULL, NULL, 'https://everyayah.com/data/Alafasy_128kbps/018064.mp3', now()),
  (18, 65, '', '[{"id":57033,"position":1,"text_uthmani":"فَوَجَدَا","transliteration":"fawajadā","translation_bn":"তখন দু''জনে পেলো","root":"وجد","lemma":"وَجَدَ","grammar_bn":"শব্দ"},{"id":57034,"position":2,"text_uthmani":"عَبْدًۭا","transliteration":"ʿabdan","translation_bn":"এক দাসকে","root":"عبد","lemma":"عَبْد","grammar_bn":"বিশেষ্য (Noun)"},{"id":57035,"position":3,"text_uthmani":"مِّنْ","transliteration":"min","translation_bn":"মধ্য হ''তে","root":"—","lemma":"مِن\r","grammar_bn":"অব্যয় (Preposition)"},{"id":57036,"position":4,"text_uthmani":"عِبَادِنَآ","transliteration":"ʿibādinā","translation_bn":"আমাদের দাসদের","root":"عبد","lemma":"عَبْد","grammar_bn":"বিশেষ্য (Noun)"},{"id":57037,"position":5,"text_uthmani":"ءَاتَيْنَـٰهُ","transliteration":"ātaynāhu","translation_bn":"তাকে আমরা দিয়েছিলাম","root":"اتي","lemma":"ا^تَى","grammar_bn":"ক্রিয়া (Verb)"},{"id":57038,"position":6,"text_uthmani":"رَحْمَةًۭ","transliteration":"raḥmatan","translation_bn":"অনুগ্রহ","root":"رحم","lemma":"رَحْمَة","grammar_bn":"বিশেষ্য (Noun)"},{"id":57039,"position":7,"text_uthmani":"مِّنْ","transliteration":"min","translation_bn":"থেকে","root":"—","lemma":"مِن\r","grammar_bn":"অব্যয় (Preposition)"},{"id":57040,"position":8,"text_uthmani":"عِندِنَا","transliteration":"ʿindinā","translation_bn":"আমাদের নিকট","root":"عند","lemma":"عِند","grammar_bn":"বিশেষ্য (Noun)"},{"id":57041,"position":9,"text_uthmani":"وَعَلَّمْنَـٰهُ","transliteration":"waʿallamnāhu","translation_bn":"এবং তাকে আমরা শিখিয়েছিলাম","root":"علم","lemma":"عَلَّمَ","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":57042,"position":10,"text_uthmani":"مِن","transliteration":"min","translation_bn":"থেকে","root":"—","lemma":"مِن\r","grammar_bn":"অব্যয় (Preposition)"},{"id":57043,"position":11,"text_uthmani":"لَّدُنَّا","transliteration":"ladunnā","translation_bn":"আমাদের","root":"لدن","lemma":"لَّدُن","grammar_bn":"বিশেষ্য (Noun)"},{"id":57044,"position":12,"text_uthmani":"عِلْمًۭا","transliteration":"ʿil''man","translation_bn":"জ্ঞান","root":"علم","lemma":"عِلْم","grammar_bn":"বিশেষ্য (Noun)"},{"id":57045,"position":13,"text_uthmani":"٦٥","transliteration":"","translation_bn":"(৬৫)","root":"—","lemma":"٦٥","grammar_bn":"মার্কার"}]'::jsonb, 'fawajadā ʿabdan min ʿibādinā ātaynāhu raḥmatan min ʿindinā waʿallamnāhu min ladunnā ʿil''man', 'তখন তারা আমার বান্দাদের এক বান্দাকে পেল, যার প্রতি আমার পক্ষ থেকে অনুগ্রহ দান করেছিলাম আর আমার পক্ষ থেকে তাকে বিশেষ জ্ঞান দান করেছিলাম।', 'And they found a servant from among Our servants to whom we had given mercy from us and had taught him from Us a [certain] knowledge.', 'তখন তারা আমার বান্দাদের এক বান্দাকে পেল, যার প্রতি আমার পক্ষ থেকে অনুগ্রহ দান করেছিলাম আর আমার পক্ষ থেকে তাকে বিশেষ জ্ঞান দান করেছিলাম।', 'And they found a servant from among Our servants to whom we had given mercy from us and had taught him from Us a [certain] knowledge.', NULL, NULL, NULL, NULL, NULL, 'https://everyayah.com/data/Alafasy_128kbps/018065.mp3', now()),
  (18, 66, '', '[{"id":57562,"position":1,"text_uthmani":"قَالَ","transliteration":"qāla","translation_bn":"বললো","root":"قول","lemma":"قَالَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":57563,"position":2,"text_uthmani":"لَهُۥ","transliteration":"lahu","translation_bn":"তাকে","root":"—","lemma":"لَهُۥ","grammar_bn":"অব্যয় (Preposition)"},{"id":57564,"position":3,"text_uthmani":"مُوسَىٰ","transliteration":"mūsā","translation_bn":"মূসা","root":"—","lemma":"مُوسَىٰ","grammar_bn":"নামবাচক বিশেষ্য (Proper Noun)"},{"id":57565,"position":4,"text_uthmani":"هَلْ","transliteration":"hal","translation_bn":"\"কি","root":"—","lemma":"هَل\r","grammar_bn":"প্রশ্নবোধক (Interrogative)"},{"id":57566,"position":5,"text_uthmani":"أَتَّبِعُكَ","transliteration":"attabiʿuka","translation_bn":"আপনাকে অনুসরণ করবো","root":"تبع","lemma":"ٱتَّبَعَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":57567,"position":6,"text_uthmani":"عَلَىٰٓ","transliteration":"ʿalā","translation_bn":"(এ কথার) উপর","root":"—","lemma":"عَلَىٰ\r","grammar_bn":"অব্যয় (Preposition)"},{"id":57568,"position":7,"text_uthmani":"أَن","transliteration":"an","translation_bn":"যে","root":"—","lemma":"أَن\r","grammar_bn":"অধীনস্থ যোজক (Subordinating)"},{"id":57569,"position":8,"text_uthmani":"تُعَلِّمَنِ","transliteration":"tuʿallimani","translation_bn":"আপনি আমাকে শিখাবেন","root":"علم","lemma":"عَلَّمَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":57570,"position":9,"text_uthmani":"مِمَّا","transliteration":"mimmā","translation_bn":"তা হ''তে যা","root":"—","lemma":"مِن\r","grammar_bn":"অব্যয় (Preposition)"},{"id":57571,"position":10,"text_uthmani":"عُلِّمْتَ","transliteration":"ʿullim''ta","translation_bn":"আপনাকে শিখানো হয়েছে","root":"علم","lemma":"عَلَّمَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":57572,"position":11,"text_uthmani":"رُشْدًۭا","transliteration":"rush''dan","translation_bn":"সত্য জ্ঞান\"","root":"رشد","lemma":"رُشْد","grammar_bn":"বিশেষ্য (Noun)"},{"id":57573,"position":12,"text_uthmani":"٦٦","transliteration":"","translation_bn":"(৬৬)","root":"—","lemma":"٦٦","grammar_bn":"মার্কার"}]'::jsonb, 'qāla lahu mūsā hal attabiʿuka ʿalā an tuʿallimani mimmā ʿullim''ta rush''dan', 'মূসা তাকে বলল, ‘আমি কি এ শর্তে আপনার অনুসরণ করব যে, আপনি আমাকে সেই (বিশেষ) জ্ঞান থেকে শিক্ষা দেবেন যে জ্ঞান আপনাকে শেখানো হয়েছে?’', 'Moses said to him, "May I follow you on [the condition] that you teach me from what you have been taught of sound judgement?"', 'মূসা তাকে বলল, ‘আমি কি এ শর্তে আপনার অনুসরণ করব যে, আপনি আমাকে সেই (বিশেষ) জ্ঞান থেকে শিক্ষা দেবেন যে জ্ঞান আপনাকে শেখানো হয়েছে?’', 'Moses said to him, "May I follow you on [the condition] that you teach me from what you have been taught of sound judgement?"', NULL, NULL, NULL, NULL, NULL, 'https://everyayah.com/data/Alafasy_128kbps/018066.mp3', now()),
  (18, 67, '', '[{"id":57969,"position":1,"text_uthmani":"قَالَ","transliteration":"qāla","translation_bn":"সে বললো","root":"قول","lemma":"قَالَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":57970,"position":2,"text_uthmani":"إِنَّكَ","transliteration":"innaka","translation_bn":"\"নিশ্চয়ই আপনি","root":"—","lemma":"إِنّ","grammar_bn":"অভিঘাত পদ (Accusative)"},{"id":57971,"position":3,"text_uthmani":"لَن","transliteration":"lan","translation_bn":"কখনও না","root":"—","lemma":"لَن\r","grammar_bn":"না-বোধক (Negative)"},{"id":57972,"position":4,"text_uthmani":"تَسْتَطِيعَ","transliteration":"tastaṭīʿa","translation_bn":"পারবেন","root":"طوع","lemma":"ٱسْتَطَاعَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":57973,"position":5,"text_uthmani":"مَعِىَ","transliteration":"maʿiya","translation_bn":"আমার সাথে","root":"—","lemma":"مَع","grammar_bn":"স্থানবাচক (Location)"},{"id":57974,"position":6,"text_uthmani":"صَبْرًۭا","transliteration":"ṣabran","translation_bn":"ধৈর্য ধরতে","root":"صبر","lemma":"صَبْر","grammar_bn":"বিশেষ্য (Noun)"},{"id":57975,"position":7,"text_uthmani":"٦٧","transliteration":"","translation_bn":"(৬৭)","root":"—","lemma":"٦٧","grammar_bn":"মার্কার"}]'::jsonb, 'qāla innaka lan tastaṭīʿa maʿiya ṣabran', 'সে বলল, ‘আপনি কিছুতেই আমার সাথে ধৈর্য ধারণ করতে পারবেন না।’', 'He said, "Indeed, with me you will never be able to have patience.', 'সে বলল, ‘আপনি কিছুতেই আমার সাথে ধৈর্য ধারণ করতে পারবেন না।’', 'He said, "Indeed, with me you will never be able to have patience.', NULL, NULL, NULL, NULL, NULL, 'https://everyayah.com/data/Alafasy_128kbps/018067.mp3', now()),
