  (19, 1, '', '[{"id":162,"position":1,"text_uthmani":"كٓهيعٓصٓ","transliteration":"kaf-ha-ya-ain-sad","translation_bn":"কাফ-হা-ইয়া-''আইন-স-দ","root":"—","lemma":"كٓهيعٓصٓ","grammar_bn":"শব্দ"},{"id":163,"position":2,"text_uthmani":"١","transliteration":"","translation_bn":"(১)","root":"—","lemma":"١","grammar_bn":"মার্কার"}]'::jsonb, 'kaf-ha-ya-ain-sad', 'কাফ্-হা-ইয়্যা-‘আইন-সাদ।', 'Kaf, Ha, Ya, ''Ayn, Sad.', 'কাফ্-হা-ইয়্যা-‘আইন-সাদ।', 'Kaf, Ha, Ya, ''Ayn, Sad.', NULL, NULL, NULL, NULL, NULL, 'https://everyayah.com/data/Alafasy_128kbps/019001.mp3', now()),
  (19, 2, '', '[{"id":1025,"position":1,"text_uthmani":"ذِكْرُ","transliteration":"dhik''ru","translation_bn":"উল্লেখ (করা হচ্ছে)","root":"ذكر","lemma":"ذِكْر","grammar_bn":"বিশেষ্য (Noun)"},{"id":1026,"position":2,"text_uthmani":"رَحْمَتِ","transliteration":"raḥmati","translation_bn":"অনুগ্রহের","root":"رحم","lemma":"رَحْمَة","grammar_bn":"বিশেষ্য (Noun)"},{"id":1027,"position":3,"text_uthmani":"رَبِّكَ","transliteration":"rabbika","translation_bn":"তোমার রবের","root":"ربب","lemma":"رَبّ","grammar_bn":"বিশেষ্য (Noun)"},{"id":1028,"position":4,"text_uthmani":"عَبْدَهُۥ","transliteration":"ʿabdahu","translation_bn":"তাঁর দাস","root":"عبد","lemma":"عَبْد","grammar_bn":"বিশেষ্য (Noun)"},{"id":1029,"position":5,"text_uthmani":"زَكَرِيَّآ","transliteration":"zakariyyā","translation_bn":"যাকারিয়্যার (প্রতি)","root":"—","lemma":"زَكَرِيَّا","grammar_bn":"নামবাচক বিশেষ্য (Proper Noun)"},{"id":1030,"position":6,"text_uthmani":"٢","transliteration":"","translation_bn":"(২)","root":"—","lemma":"٢","grammar_bn":"মার্কার"}]'::jsonb, 'dhik''ru raḥmati rabbika ʿabdahu zakariyyā', 'এটা তোমার প্রতিপালকের অনুগ্রহের বিবরণ তাঁর বান্দাহ যাকারিয়্যার প্রতি।', '[This is] a mention of the mercy of your Lord to His servant Zechariah', 'এটা তোমার প্রতিপালকের অনুগ্রহের বিবরণ তাঁর বান্দাহ যাকারিয়্যার প্রতি।', '[This is] a mention of the mercy of your Lord to His servant Zechariah', NULL, NULL, NULL, NULL, NULL, 'https://everyayah.com/data/Alafasy_128kbps/019002.mp3', now()),
  (19, 3, '', '[{"id":2146,"position":1,"text_uthmani":"إِذْ","transliteration":"idh","translation_bn":"যখন","root":"—","lemma":"إِذ\r","grammar_bn":"কালবাচক (Time)"},{"id":2147,"position":2,"text_uthmani":"نَادَىٰ","transliteration":"nādā","translation_bn":"সে ডেকেছিলো","root":"ندو","lemma":"نَادَىٰ","grammar_bn":"ক্রিয়া (Verb)"},{"id":2148,"position":3,"text_uthmani":"رَبَّهُۥ","transliteration":"rabbahu","translation_bn":"তাঁর রবকে","root":"ربب","lemma":"رَبّ","grammar_bn":"বিশেষ্য (Noun)"},{"id":2149,"position":4,"text_uthmani":"نِدَآءً","transliteration":"nidāan","translation_bn":"ডাক","root":"ندو","lemma":"نِدَا^ء","grammar_bn":"বিশেষ্য (Noun)"},{"id":2150,"position":5,"text_uthmani":"خَفِيًّۭا","transliteration":"khafiyyan","translation_bn":"নিভৃতে","root":"خفي","lemma":"خَفِىّ","grammar_bn":"বিশেষণ (Adjective)"},{"id":2151,"position":6,"text_uthmani":"٣","transliteration":"","translation_bn":"(৩)","root":"—","lemma":"٣","grammar_bn":"মার্কার"}]'::jsonb, 'idh nādā rabbahu nidāan khafiyyan', 'যখন সে তার প্রতিপালককে আহবান করেছিল- এক গোপন আহবানে।', 'When he called to his Lord a private supplication.', 'যখন সে তার প্রতিপালককে আহবান করেছিল- এক গোপন আহবানে।', 'When he called to his Lord a private supplication.', NULL, NULL, NULL, NULL, NULL, 'https://everyayah.com/data/Alafasy_128kbps/019003.mp3', now()),
  (19, 4, '', '[{"id":3449,"position":1,"text_uthmani":"قَالَ","transliteration":"qāla","translation_bn":"সে বলেছিলো","root":"قول","lemma":"قَالَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":3450,"position":2,"text_uthmani":"رَبِّ","transliteration":"rabbi","translation_bn":"\"হে আমার রব","root":"ربب","lemma":"رَبّ","grammar_bn":"বিশেষ্য (Noun)"},{"id":3451,"position":3,"text_uthmani":"إِنِّى","transliteration":"innī","translation_bn":"আমি নিশ্চয়ই (এ অবস্থায় যে)","root":"—","lemma":"إِنّ","grammar_bn":"অভিঘাত পদ (Accusative)"},{"id":3452,"position":4,"text_uthmani":"وَهَنَ","transliteration":"wahana","translation_bn":"নরম হয়েছে","root":"وهن","lemma":"وَهَنَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":3453,"position":5,"text_uthmani":"ٱلْعَظْمُ","transliteration":"l-ʿaẓmu","translation_bn":"হাড় (মজ্জা)","root":"عظم","lemma":"عَظْم","grammar_bn":"শব্দ"},{"id":3454,"position":6,"text_uthmani":"مِنِّى","transliteration":"minnī","translation_bn":"আমার হ''তে","root":"—","lemma":"مِن\r","grammar_bn":"অব্যয় (Preposition)"},{"id":3455,"position":7,"text_uthmani":"وَٱشْتَعَلَ","transliteration":"wa-ish''taʿala","translation_bn":"এবং উজ্জ্বল (শুভ্র হয়েছে)","root":"شعل","lemma":"ٱشْتَعَلَ","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":3456,"position":8,"text_uthmani":"ٱلرَّأْسُ","transliteration":"l-rasu","translation_bn":"মাথা (চুল)","root":"راس","lemma":"رَأْس","grammar_bn":"শব্দ"},{"id":3457,"position":9,"text_uthmani":"شَيْبًۭا","transliteration":"shayban","translation_bn":"বার্ধক্যের (চিহ্নে)","root":"شيب","lemma":"شَيْب","grammar_bn":"বিশেষ্য (Noun)"},{"id":3458,"position":10,"text_uthmani":"وَلَمْ","transliteration":"walam","translation_bn":"এবং নি","root":"—","lemma":"لَم\r","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":3459,"position":11,"text_uthmani":"أَكُنۢ","transliteration":"akun","translation_bn":"আমি হই","root":"كون","lemma":"كَانَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":3460,"position":12,"text_uthmani":"بِدُعَآئِكَ","transliteration":"biduʿāika","translation_bn":"কারণে তোমাকে ডাকার","root":"دعو","lemma":"دُعَا^ء","grammar_bn":"অব্যয় (Preposition)"},{"id":3461,"position":13,"text_uthmani":"رَبِّ","transliteration":"rabbi","translation_bn":"হে আমার রব","root":"ربب","lemma":"رَبّ","grammar_bn":"বিশেষ্য (Noun)"},{"id":3462,"position":14,"text_uthmani":"شَقِيًّۭا","transliteration":"shaqiyyan","translation_bn":"ব্যর্থকাম","root":"شقو","lemma":"شَقِيّ","grammar_bn":"বিশেষ্য (Noun)"},{"id":3463,"position":15,"text_uthmani":"٤","transliteration":"","translation_bn":"(৪)","root":"—","lemma":"٤","grammar_bn":"মার্কার"}]'::jsonb, 'qāla rabbi innī wahana l-ʿaẓmu minnī wa-ish''taʿala l-rasu shayban walam akun biduʿāika rabbi shaqiyyan', 'সে বলেছিল, ‘হে আমার প্রতিপালক! আমার হাড়গুলো দুর্বল হয়ে গেছে, আর বার্ধক্যে আমার মস্তক সাদা হয়ে গেছে, হে আমার প্রতিপালক! তোমাকে ডেকে আমি কখনো বিফল হইনি।', 'He said, "My Lord, indeed my bones have weakened, and my head has filled with white, and never have I been in my supplication to You, my Lord, unhappy.', 'সে বলেছিল, ‘হে আমার প্রতিপালক! আমার হাড়গুলো দুর্বল হয়ে গেছে, আর বার্ধক্যে আমার মস্তক সাদা হয়ে গেছে, হে আমার প্রতিপালক! তোমাকে ডেকে আমি কখনো বিফল হইনি।', 'He said, "My Lord, indeed my bones have weakened, and my head has filled with white, and never have I been in my supplication to You, my Lord, unhappy.', NULL, NULL, NULL, NULL, NULL, 'https://everyayah.com/data/Alafasy_128kbps/019004.mp3', now()),
  (19, 5, '', '[{"id":4800,"position":1,"text_uthmani":"وَإِنِّى","transliteration":"wa-innī","translation_bn":"এবং আমি নিশ্চয়ই","root":"—","lemma":"إِنّ","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":4801,"position":2,"text_uthmani":"خِفْتُ","transliteration":"khif''tu","translation_bn":"ভয় করছি","root":"خوف","lemma":"خَافَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":4802,"position":3,"text_uthmani":"ٱلْمَوَٰلِىَ","transliteration":"l-mawāliya","translation_bn":"আমার স্বগোত্রদের","root":"ولي","lemma":"مَوَٰلِى","grammar_bn":"শব্দ"},{"id":4803,"position":4,"text_uthmani":"مِن","transliteration":"min","translation_bn":"থেকে","root":"—","lemma":"مِن\r","grammar_bn":"অব্যয় (Preposition)"},{"id":4804,"position":5,"text_uthmani":"وَرَآءِى","transliteration":"warāī","translation_bn":"আমার পর","root":"وري","lemma":"وَرَا^ء","grammar_bn":"বিশেষ্য (Noun)"},{"id":4805,"position":6,"text_uthmani":"وَكَانَتِ","transliteration":"wakānati","translation_bn":"এবং হয়েছে","root":"كون","lemma":"كَانَ","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":4806,"position":7,"text_uthmani":"ٱمْرَأَتِى","transliteration":"im''ra-atī","translation_bn":"আমার স্ত্রী","root":"مرا","lemma":"ٱمْرَأَت","grammar_bn":"বিশেষ্য (Noun)"},{"id":4807,"position":8,"text_uthmani":"عَاقِرًۭا","transliteration":"ʿāqiran","translation_bn":"বন্ধ্যা","root":"عقر","lemma":"عَاقِر","grammar_bn":"বিশেষ্য (Noun)"},{"id":4808,"position":9,"text_uthmani":"فَهَبْ","transliteration":"fahab","translation_bn":"তবুও দান করো","root":"وهب","lemma":"وَهَبَ","grammar_bn":"শব্দ"},{"id":4809,"position":10,"text_uthmani":"لِى","transliteration":"lī","translation_bn":"আমাকে","root":"—","lemma":"لِى","grammar_bn":"অব্যয় (Preposition)"},{"id":4810,"position":11,"text_uthmani":"مِن","transliteration":"min","translation_bn":"থেকে","root":"—","lemma":"مِن\r","grammar_bn":"অব্যয় (Preposition)"},{"id":4811,"position":12,"text_uthmani":"لَّدُنكَ","transliteration":"ladunka","translation_bn":"তোমার নিকট","root":"لدن","lemma":"لَّدُن","grammar_bn":"বিশেষ্য (Noun)"},{"id":4812,"position":13,"text_uthmani":"وَلِيًّۭا","transliteration":"waliyyan","translation_bn":"এক উত্তরাধিকারী","root":"ولي","lemma":"وَلِىّ","grammar_bn":"বিশেষ্য (Noun)"},{"id":4813,"position":14,"text_uthmani":"٥","transliteration":"","translation_bn":"(৫)","root":"—","lemma":"٥","grammar_bn":"মার্কার"}]'::jsonb, 'wa-innī khif''tu l-mawāliya min warāī wakānati im''ra-atī ʿāqiran fahab lī min ladunka waliyyan', 'আমার পরে আমার স্বগোত্রীয়রা (কী করবে) সে সম্পর্কে আমি আশঙ্কাবোধ করছি, আর আমার স্ত্রী হল বন্ধ্যা, কাজেই তুমি তোমার তরফ থেকে আমাকে একজন উত্তরাধিকারী দান কর', 'And indeed, I fear the successors after me, and my wife has been barren, so give me from Yourself an heir', 'আমার পরে আমার স্বগোত্রীয়রা (কী করবে) সে সম্পর্কে আমি আশঙ্কাবোধ করছি, আর আমার স্ত্রী হল বন্ধ্যা, কাজেই তুমি তোমার তরফ থেকে আমাকে একজন উত্তরাধিকারী দান কর', 'And indeed, I fear the successors after me, and my wife has been barren, so give me from Yourself an heir', NULL, NULL, NULL, NULL, NULL, 'https://everyayah.com/data/Alafasy_128kbps/019005.mp3', now()),
  (19, 6, '', '[{"id":6042,"position":1,"text_uthmani":"يَرِثُنِى","transliteration":"yarithunī","translation_bn":"আমার উত্তরাধিকারী হবে সে","root":"ورث","lemma":"وَرِثَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":6043,"position":2,"text_uthmani":"وَيَرِثُ","transliteration":"wayarithu","translation_bn":"ও উত্তরাধিকারী হবে","root":"ورث","lemma":"وَرِثَ","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":6044,"position":3,"text_uthmani":"مِنْ","transliteration":"min","translation_bn":"ব্যাপারে","root":"—","lemma":"مِن\r","grammar_bn":"অব্যয় (Preposition)"},{"id":6045,"position":4,"text_uthmani":"ءَالِ","transliteration":"āli","translation_bn":"বংশের","root":"اول","lemma":"ءَال","grammar_bn":"বিশেষ্য (Noun)"},{"id":6046,"position":5,"text_uthmani":"يَعْقُوبَ ۖ","transliteration":"yaʿqūba","translation_bn":"ইয়াকুবের","root":"—","lemma":"يَعْقُوب","grammar_bn":"নামবাচক বিশেষ্য (Proper Noun)"},{"id":6048,"position":6,"text_uthmani":"وَٱجْعَلْهُ","transliteration":"wa-ij''ʿalhu","translation_bn":"এবং তাকে করো","root":"جعل","lemma":"جَعَلَ","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":6049,"position":7,"text_uthmani":"رَبِّ","transliteration":"rabbi","translation_bn":"হে আমার রব","root":"ربب","lemma":"رَبّ","grammar_bn":"বিশেষ্য (Noun)"},{"id":6050,"position":8,"text_uthmani":"رَضِيًّۭا","transliteration":"raḍiyyan","translation_bn":"সন্তোষজনক\"","root":"رضو","lemma":"رَضِيّ","grammar_bn":"বিশেষ্য (Noun)"},{"id":6051,"position":9,"text_uthmani":"٦","transliteration":"","translation_bn":"(৬)","root":"—","lemma":"٦","grammar_bn":"মার্কার"}]'::jsonb, 'yarithunī wayarithu min āli yaʿqūba wa-ij''ʿalhu rabbi raḍiyyan', 'যে আমার উত্তরাধিকারী হবে আর উত্তরাধিকারী হবে ইয়া‘কুব পরিবারের; আর হে আমার প্রতিপালক! তাকে করুন আপনার সন্তুষ্টির পাত্র।', 'Who will inherit me and inherit from the family of Jacob. And make him, my Lord, pleasing [to You]."', 'যে আমার উত্তরাধিকারী হবে আর উত্তরাধিকারী হবে ইয়া‘কুব পরিবারের; আর হে আমার প্রতিপালক! তাকে করুন আপনার সন্তুষ্টির পাত্র।', 'Who will inherit me and inherit from the family of Jacob. And make him, my Lord, pleasing [to You]."', NULL, NULL, NULL, NULL, NULL, 'https://everyayah.com/data/Alafasy_128kbps/019006.mp3', now()),
  (19, 7, '', '[{"id":7365,"position":1,"text_uthmani":"يَـٰزَكَرِيَّآ","transliteration":"yāzakariyyā","translation_bn":"\"(বলা হলো) হে যাকারিয়্যা","root":"—","lemma":"زَكَرِيَّا","grammar_bn":"সম্বোধন পদ (Vocative)"},{"id":7366,"position":2,"text_uthmani":"إِنَّا","transliteration":"innā","translation_bn":"নিশ্চয়ই আমরা","root":"—","lemma":"إِنّ","grammar_bn":"অভিঘাত পদ (Accusative)"},{"id":7367,"position":3,"text_uthmani":"نُبَشِّرُكَ","transliteration":"nubashiruka","translation_bn":"তোমাকে সুসংবাদ দিচ্ছি","root":"بشر","lemma":"بُشِّرَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":7368,"position":4,"text_uthmani":"بِغُلَـٰمٍ","transliteration":"bighulāmin","translation_bn":"সম্পর্কে এক পুত্রের","root":"غلم","lemma":"غُلَٰم","grammar_bn":"অব্যয় (Preposition)"},{"id":7369,"position":5,"text_uthmani":"ٱسْمُهُۥ","transliteration":"us''muhu","translation_bn":"তার নাম (হবে)","root":"سمو","lemma":"ٱسْم","grammar_bn":"বিশেষ্য (Noun)"},{"id":7370,"position":6,"text_uthmani":"يَحْيَىٰ","transliteration":"yaḥyā","translation_bn":"ইয়াহইয়া","root":"—","lemma":"يَحْيَىٰ","grammar_bn":"নামবাচক বিশেষ্য (Proper Noun)"},{"id":7371,"position":7,"text_uthmani":"لَمْ","transliteration":"lam","translation_bn":"নি","root":"—","lemma":"لَم\r","grammar_bn":"না-বোধক (Negative)"},{"id":7372,"position":8,"text_uthmani":"نَجْعَل","transliteration":"najʿal","translation_bn":"আমরা করি","root":"جعل","lemma":"جَعَلَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":7373,"position":9,"text_uthmani":"لَّهُۥ","transliteration":"lahu","translation_bn":"তার জন্য","root":"—","lemma":"لَّهُۥ","grammar_bn":"অব্যয় (Preposition)"},{"id":7374,"position":10,"text_uthmani":"مِن","transliteration":"min","translation_bn":"থেকে","root":"—","lemma":"مِن\r","grammar_bn":"অব্যয় (Preposition)"},{"id":7375,"position":11,"text_uthmani":"قَبْلُ","transliteration":"qablu","translation_bn":"ইতিপূর্বে (অন্য কাউকে)","root":"قبل","lemma":"قَبْل","grammar_bn":"বিশেষ্য (Noun)"},{"id":7376,"position":12,"text_uthmani":"سَمِيًّۭا","transliteration":"samiyyan","translation_bn":"(সম) নামকরণ\"","root":"سمو","lemma":"سَمِيّ","grammar_bn":"বিশেষ্য (Noun)"},{"id":7377,"position":13,"text_uthmani":"٧","transliteration":"","translation_bn":"(৭)","root":"—","lemma":"٧","grammar_bn":"মার্কার"}]'::jsonb, 'yāzakariyyā innā nubashiruka bighulāmin us''muhu yaḥyā lam najʿal lahu min qablu samiyyan', 'তিনি বললেন, ‘হে যাকারিয়া! আমি তোমাকে একটি পুত্রের শুভ সংবাদ দিচ্ছি যার নাম হবে ইয়াহইয়া, পূর্বে এ নামে আমি কাউকে আখ্যায়িত করিনি।’', '[He was told], "O Zechariah, indeed We give you good tidings of a boy whose name will be John. We have not assigned to any before [this] name."', 'তিনি বললেন, ‘হে যাকারিয়া! আমি তোমাকে একটি পুত্রের শুভ সংবাদ দিচ্ছি যার নাম হবে ইয়াহইয়া, পূর্বে এ নামে আমি কাউকে আখ্যায়িত করিনি।’', '[He was told], "O Zechariah, indeed We give you good tidings of a boy whose name will be John. We have not assigned to any before [this] name."', NULL, NULL, NULL, NULL, NULL, 'https://everyayah.com/data/Alafasy_128kbps/019007.mp3', now()),
  (19, 8, '', '[{"id":8652,"position":1,"text_uthmani":"قَالَ","transliteration":"qāla","translation_bn":"সে বললো","root":"قول","lemma":"قَالَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":8653,"position":2,"text_uthmani":"رَبِّ","transliteration":"rabbi","translation_bn":"\"হে আমার রব","root":"ربب","lemma":"رَبّ","grammar_bn":"বিশেষ্য (Noun)"},{"id":8654,"position":3,"text_uthmani":"أَنَّىٰ","transliteration":"annā","translation_bn":"কেমন করে","root":"اني\r","lemma":"أَنَّىٰ","grammar_bn":"প্রশ্নবোধক (Interrogative)"},{"id":8655,"position":4,"text_uthmani":"يَكُونُ","transliteration":"yakūnu","translation_bn":"হবে","root":"كون","lemma":"كَانَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":8656,"position":5,"text_uthmani":"لِى","transliteration":"lī","translation_bn":"আমার","root":"—","lemma":"لِى","grammar_bn":"অব্যয় (Preposition)"},{"id":8657,"position":6,"text_uthmani":"غُلَـٰمٌۭ","transliteration":"ghulāmun","translation_bn":"পুত্র","root":"غلم","lemma":"غُلَٰم","grammar_bn":"বিশেষ্য (Noun)"},{"id":8658,"position":7,"text_uthmani":"وَكَانَتِ","transliteration":"wakānati","translation_bn":"যখন হলো","root":"كون","lemma":"كَانَ","grammar_bn":"অবস্থাবাচক (Circumstantial)"},{"id":8659,"position":8,"text_uthmani":"ٱمْرَأَتِى","transliteration":"im''ra-atī","translation_bn":"আমার স্ত্রী","root":"مرا","lemma":"ٱمْرَأَت","grammar_bn":"বিশেষ্য (Noun)"},{"id":8660,"position":9,"text_uthmani":"عَاقِرًۭا","transliteration":"ʿāqiran","translation_bn":"বন্ধ্যা","root":"عقر","lemma":"عَاقِر","grammar_bn":"বিশেষ্য (Noun)"},{"id":8661,"position":10,"text_uthmani":"وَقَدْ","transliteration":"waqad","translation_bn":"এবং নিশ্চয়ই","root":"—","lemma":"قَد\r","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":8662,"position":11,"text_uthmani":"بَلَغْتُ","transliteration":"balaghtu","translation_bn":"আমি উপনীত হয়েছি","root":"بلغ","lemma":"بَلَغَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":8663,"position":12,"text_uthmani":"مِنَ","transliteration":"mina","translation_bn":"কারণে","root":"—","lemma":"مِن\r","grammar_bn":"অব্যয় (Preposition)"},{"id":8664,"position":13,"text_uthmani":"ٱلْكِبَرِ","transliteration":"l-kibari","translation_bn":"বার্ধক্যের","root":"كبر","lemma":"كِبَر","grammar_bn":"শব্দ"},{"id":8665,"position":14,"text_uthmani":"عِتِيًّۭا","transliteration":"ʿitiyyan","translation_bn":"(চরম) শেষসীমায়\"","root":"عتو","lemma":"عِتِيّ","grammar_bn":"বিশেষ্য (Noun)"},{"id":8666,"position":15,"text_uthmani":"٨","transliteration":"","translation_bn":"(৮)","root":"—","lemma":"٨","grammar_bn":"মার্কার"}]'::jsonb, 'qāla rabbi annā yakūnu lī ghulāmun wakānati im''ra-atī ʿāqiran waqad balaghtu mina l-kibari ʿitiyyan', 'সে বলল, ‘হে আমার পালনকর্তা! আমার পুত্র হবে কেমন করে, আমার স্ত্রী তো বন্ধ্যা, আর আমি বার্ধক্যের শেষ স্তরে পৌঁছে গেছি।’', 'He said, "My Lord, how will I have a boy when my wife has been barren and I have reached extreme old age?"', 'সে বলল, ‘হে আমার পালনকর্তা! আমার পুত্র হবে কেমন করে, আমার স্ত্রী তো বন্ধ্যা, আর আমি বার্ধক্যের শেষ স্তরে পৌঁছে গেছি।’', 'He said, "My Lord, how will I have a boy when my wife has been barren and I have reached extreme old age?"', NULL, NULL, NULL, NULL, NULL, 'https://everyayah.com/data/Alafasy_128kbps/019008.mp3', now()),
  (19, 9, '', '[{"id":9853,"position":1,"text_uthmani":"قَالَ","transliteration":"qāla","translation_bn":"তিনি বললেন","root":"قول","lemma":"قَالَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":9854,"position":2,"text_uthmani":"كَذَٰلِكَ","transliteration":"kadhālika","translation_bn":"\"এরূপই (হবে)","root":"—","lemma":"ذَٰلِك","grammar_bn":"অব্যয় (Preposition)"},{"id":9855,"position":3,"text_uthmani":"قَالَ","transliteration":"qāla","translation_bn":"বললেন","root":"قول","lemma":"قَالَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":9856,"position":4,"text_uthmani":"رَبُّكَ","transliteration":"rabbuka","translation_bn":"তোমার রব","root":"ربب","lemma":"رَبّ","grammar_bn":"বিশেষ্য (Noun)"},{"id":9857,"position":5,"text_uthmani":"هُوَ","transliteration":"huwa","translation_bn":"তা","root":"—","lemma":"هُوَ","grammar_bn":"সর্বনাম (Pronoun)"},{"id":9858,"position":6,"text_uthmani":"عَلَىَّ","transliteration":"ʿalayya","translation_bn":"আমার উপর","root":"—","lemma":"عَلَىٰ\r","grammar_bn":"অব্যয় (Preposition)"},{"id":9859,"position":7,"text_uthmani":"هَيِّنٌۭ","transliteration":"hayyinun","translation_bn":"সহজসাধ্য","root":"هون","lemma":"هَيِّن","grammar_bn":"বিশেষ্য (Noun)"},{"id":9860,"position":8,"text_uthmani":"وَقَدْ","transliteration":"waqad","translation_bn":"এবং নিশ্চয়ই","root":"—","lemma":"قَد\r","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":9861,"position":9,"text_uthmani":"خَلَقْتُكَ","transliteration":"khalaqtuka","translation_bn":"তোমাকে আমি সৃষ্টি করেছি","root":"خلق","lemma":"خَلَقَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":9862,"position":10,"text_uthmani":"مِن","transliteration":"min","translation_bn":"থেকে","root":"—","lemma":"مِن\r","grammar_bn":"অব্যয় (Preposition)"},{"id":9863,"position":11,"text_uthmani":"قَبْلُ","transliteration":"qablu","translation_bn":"ইতিপূর্বে","root":"قبل","lemma":"قَبْل","grammar_bn":"বিশেষ্য (Noun)"},{"id":9864,"position":12,"text_uthmani":"وَلَمْ","transliteration":"walam","translation_bn":"যখন না","root":"—","lemma":"لَم\r","grammar_bn":"অবস্থাবাচক (Circumstantial)"},{"id":9865,"position":13,"text_uthmani":"تَكُ","transliteration":"taku","translation_bn":"তুমি ছিলে","root":"كون","lemma":"كَانَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":9866,"position":14,"text_uthmani":"شَيْـًۭٔا","transliteration":"shayan","translation_bn":"(কোন) কিছুই","root":"شيا","lemma":"شَىْء","grammar_bn":"বিশেষ্য (Noun)"},{"id":9867,"position":15,"text_uthmani":"٩","transliteration":"","translation_bn":"(৯)","root":"—","lemma":"٩","grammar_bn":"মার্কার"}]'::jsonb, 'qāla kadhālika qāla rabbuka huwa ʿalayya hayyinun waqad khalaqtuka min qablu walam taku shayan', 'তিনি বললেন, ‘এভাবেই হবে, তোমার প্রতিপালক বলেছেন, ‘এটা আমার পক্ষে সহজ। ইতোপূর্বে আমিই তোমাকে সৃষ্টি করেছি যখন তুমি কিছুই ছিলে না।’', '[An angel] said, "Thus [it will be]; your Lord says, ''It is easy for Me, for I created you before, while you were nothing.'' "', 'তিনি বললেন, ‘এভাবেই হবে, তোমার প্রতিপালক বলেছেন, ‘এটা আমার পক্ষে সহজ। ইতোপূর্বে আমিই তোমাকে সৃষ্টি করেছি যখন তুমি কিছুই ছিলে না।’', '[An angel] said, "Thus [it will be]; your Lord says, ''It is easy for Me, for I created you before, while you were nothing.'' "', NULL, NULL, NULL, NULL, NULL, 'https://everyayah.com/data/Alafasy_128kbps/019009.mp3', now()),
  (19, 10, '', '[{"id":11044,"position":1,"text_uthmani":"قَالَ","transliteration":"qāla","translation_bn":"সে বললো","root":"قول","lemma":"قَالَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":11045,"position":2,"text_uthmani":"رَبِّ","transliteration":"rabbi","translation_bn":"\"হে আমার রব","root":"ربب","lemma":"رَبّ","grammar_bn":"বিশেষ্য (Noun)"},{"id":11046,"position":3,"text_uthmani":"ٱجْعَل","transliteration":"ij''ʿal","translation_bn":"দাও","root":"جعل","lemma":"جَعَلَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":11047,"position":4,"text_uthmani":"لِّىٓ","transliteration":"lī","translation_bn":"আমাকে","root":"—","lemma":"لِّىٓ","grammar_bn":"অব্যয় (Preposition)"},{"id":11048,"position":5,"text_uthmani":"ءَايَةًۭ ۚ","transliteration":"āyatan","translation_bn":"একটা নিদর্শন\"","root":"ايي","lemma":"ءَايَة","grammar_bn":"বিশেষ্য (Noun)"},{"id":11050,"position":6,"text_uthmani":"قَالَ","transliteration":"qāla","translation_bn":"তিনি বললেন","root":"قول","lemma":"قَالَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":11051,"position":7,"text_uthmani":"ءَايَتُكَ","transliteration":"āyatuka","translation_bn":"\"তোমার নিদর্শন","root":"ايي","lemma":"ءَايَة","grammar_bn":"বিশেষ্য (Noun)"},{"id":11052,"position":8,"text_uthmani":"أَلَّا","transliteration":"allā","translation_bn":"(এই) যে না","root":"—","lemma":"أَن\r","grammar_bn":"অধীনস্থ যোজক (Subordinating)"},{"id":11053,"position":9,"text_uthmani":"تُكَلِّمَ","transliteration":"tukallima","translation_bn":"কথা বলতে পারবে","root":"كلم","lemma":"كَلَّمَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":11054,"position":10,"text_uthmani":"ٱلنَّاسَ","transliteration":"l-nāsa","translation_bn":"মানুষের (সাথে)","root":"نوس","lemma":"نَّاس","grammar_bn":"শব্দ"},{"id":11055,"position":11,"text_uthmani":"ثَلَـٰثَ","transliteration":"thalātha","translation_bn":"তিন","root":"ثلث","lemma":"ثَلَٰث","grammar_bn":"কালবাচক (Time)"},{"id":11056,"position":12,"text_uthmani":"لَيَالٍۢ","transliteration":"layālin","translation_bn":"রাত","root":"ليل","lemma":"لَيْل","grammar_bn":"বিশেষ্য (Noun)"},{"id":11057,"position":13,"text_uthmani":"سَوِيًّۭا","transliteration":"sawiyyan","translation_bn":"(ক্রমাগত) সুস্থ অবস্থায়\"","root":"سوي","lemma":"سَوِيّ","grammar_bn":"বিশেষ্য (Noun)"},{"id":11058,"position":14,"text_uthmani":"١٠","transliteration":"","translation_bn":"(১০)","root":"—","lemma":"١٠","grammar_bn":"মার্কার"}]'::jsonb, 'qāla rabbi ij''ʿal lī āyatan qāla āyatuka allā tukallima l-nāsa thalātha layālin sawiyyan', 'সে বলল, ‘হে আমার পালনকর্তা! আমার জন্য একটা চিহ্ন স্থির করে দিন।’ তিনি বললেন, ‘তোমার চিহ্ন এই যে, তুমি তিন রাত মানুষের সঙ্গে কথা বলবে না যদিও তুমি কথা বলতে সক্ষম।’', '[Zechariah] said, "My Lord, make for me a sign." He said, "Your sign is that you will not speak to the people for three nights, [being] sound."', 'সে বলল, ‘হে আমার পালনকর্তা! আমার জন্য একটা চিহ্ন স্থির করে দিন।’ তিনি বললেন, ‘তোমার চিহ্ন এই যে, তুমি তিন রাত মানুষের সঙ্গে কথা বলবে না যদিও তুমি কথা বলতে সক্ষম।’', '[Zechariah] said, "My Lord, make for me a sign." He said, "Your sign is that you will not speak to the people for three nights, [being] sound."', NULL, NULL, NULL, NULL, NULL, 'https://everyayah.com/data/Alafasy_128kbps/019010.mp3', now()),
  (19, 11, '', '[{"id":12318,"position":1,"text_uthmani":"فَخَرَجَ","transliteration":"fakharaja","translation_bn":"অতঃপর সে বের হলো","root":"خرج","lemma":"خَرَجَ","grammar_bn":"শব্দ"},{"id":12319,"position":2,"text_uthmani":"عَلَىٰ","transliteration":"ʿalā","translation_bn":"নিকট","root":"—","lemma":"عَلَىٰ\r","grammar_bn":"অব্যয় (Preposition)"},{"id":12320,"position":3,"text_uthmani":"قَوْمِهِۦ","transliteration":"qawmihi","translation_bn":"তার (জাতির) লোকদের","root":"قوم","lemma":"قَوْم","grammar_bn":"বিশেষ্য (Noun)"},{"id":12321,"position":4,"text_uthmani":"مِنَ","transliteration":"mina","translation_bn":"থেকে","root":"—","lemma":"مِن\r","grammar_bn":"অব্যয় (Preposition)"},{"id":12322,"position":5,"text_uthmani":"ٱلْمِحْرَابِ","transliteration":"l-miḥ''rābi","translation_bn":"মেহরাব","root":"حرب","lemma":"مِحْرَاب","grammar_bn":"শব্দ"},{"id":12323,"position":6,"text_uthmani":"فَأَوْحَىٰٓ","transliteration":"fa-awḥā","translation_bn":"সে অতঃপর ইঙ্গিত করলো","root":"وحي","lemma":"أَوْحَىٰ^","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":12324,"position":7,"text_uthmani":"إِلَيْهِمْ","transliteration":"ilayhim","translation_bn":"তাদের দিকে","root":"—","lemma":"إِلَىٰ\r","grammar_bn":"অব্যয় (Preposition)"},{"id":12325,"position":8,"text_uthmani":"أَن","transliteration":"an","translation_bn":"যে","root":"—","lemma":"أَن\r","grammar_bn":"উদ্দেশ্যবাচক (Intention)"},{"id":12326,"position":9,"text_uthmani":"سَبِّحُوا۟","transliteration":"sabbiḥū","translation_bn":"তোমরা পবিত্রতা ঘোষণা করো","root":"سبح","lemma":"سَبَّحَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":12327,"position":10,"text_uthmani":"بُكْرَةًۭ","transliteration":"buk''ratan","translation_bn":"সকালে","root":"بكر","lemma":"بُكْرَة","grammar_bn":"কালবাচক (Time)"},{"id":12328,"position":11,"text_uthmani":"وَعَشِيًّۭا","transliteration":"waʿashiyyan","translation_bn":"ও সন্ধ্যায়","root":"عشو","lemma":"عَشِىّ","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":12329,"position":12,"text_uthmani":"١١","transliteration":"","translation_bn":"(১১)","root":"—","lemma":"١١","grammar_bn":"মার্কার"}]'::jsonb, 'fakharaja ʿalā qawmihi mina l-miḥ''rābi fa-awḥā ilayhim an sabbiḥū buk''ratan waʿashiyyan', 'অতঃপর সে তার কুঠরি থেকে বের হয়ে তার সম্প্রদায়ের কাছে গেল এবং ইশারায় তাদেরকে সকাল-সন্ধ্যায় আল্লাহর প্রশংসা-পবিত্রতা বর্ণনা করতে বলল।', 'So he came out to his people from the prayer chamber and signaled to them to exalt [Allah] in the morning and afternoon.', 'অতঃপর সে তার কুঠরি থেকে বের হয়ে তার সম্প্রদায়ের কাছে গেল এবং ইশারায় তাদেরকে সকাল-সন্ধ্যায় আল্লাহর প্রশংসা-পবিত্রতা বর্ণনা করতে বলল।', 'So he came out to his people from the prayer chamber and signaled to them to exalt [Allah] in the morning and afternoon.', NULL, NULL, NULL, NULL, NULL, 'https://everyayah.com/data/Alafasy_128kbps/019011.mp3', now()),
  (19, 12, '', '[{"id":13678,"position":1,"text_uthmani":"يَـٰيَحْيَىٰ","transliteration":"yāyaḥyā","translation_bn":"\"(বড় হ''লে তাকে বলা হলো) হে ইয়াহইয়া","root":"—","lemma":"يَحْيَىٰ","grammar_bn":"সম্বোধন পদ (Vocative)"},{"id":13679,"position":2,"text_uthmani":"خُذِ","transliteration":"khudhi","translation_bn":"গ্রহণ করো","root":"اخذ","lemma":"أَخَذَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":13680,"position":3,"text_uthmani":"ٱلْكِتَـٰبَ","transliteration":"l-kitāba","translation_bn":"কিতাবকে","root":"كتب","lemma":"كِتَٰب","grammar_bn":"শব্দ"},{"id":13681,"position":4,"text_uthmani":"بِقُوَّةٍۢ ۖ","transliteration":"biquwwatin","translation_bn":"সহ দৃঢ়তা\"","root":"قوي","lemma":"قُوَّة","grammar_bn":"অব্যয় (Preposition)"},{"id":13683,"position":5,"text_uthmani":"وَءَاتَيْنَـٰهُ","transliteration":"waātaynāhu","translation_bn":"এবং তাকে আমরা দিয়েছিলাম","root":"اتي","lemma":"ا^تَى","grammar_bn":"শব্দ"},{"id":13684,"position":6,"text_uthmani":"ٱلْحُكْمَ","transliteration":"l-ḥuk''ma","translation_bn":"প্রজ্ঞা","root":"حكم","lemma":"حُكْم","grammar_bn":"শব্দ"},{"id":13685,"position":7,"text_uthmani":"صَبِيًّۭا","transliteration":"ṣabiyyan","translation_bn":"বাল্য অবস্থায়","root":"صبو","lemma":"صَبِيّ","grammar_bn":"বিশেষ্য (Noun)"},{"id":13686,"position":8,"text_uthmani":"١٢","transliteration":"","translation_bn":"(১২)","root":"—","lemma":"١٢","grammar_bn":"মার্কার"}]'::jsonb, 'yāyaḥyā khudhi l-kitāba biquwwatin waātaynāhu l-ḥuk''ma ṣabiyyan', '(তার পুত্রের কাছে নির্দেশ আসল) ‘হে ইয়াহ্ইয়া! এ কিতাব (তাওরাত) সুদৃঢ়ভাবে ধারণ কর।’ আমি তাকে বাল্য কালেই জ্ঞান দান করেছিলাম।', '[Allah] said, "O John, take the Scripture with determination." And We gave him judgement [while yet] a boy', '(তার পুত্রের কাছে নির্দেশ আসল) ‘হে ইয়াহ্ইয়া! এ কিতাব (তাওরাত) সুদৃঢ়ভাবে ধারণ কর।’ আমি তাকে বাল্য কালেই জ্ঞান দান করেছিলাম।', '[Allah] said, "O John, take the Scripture with determination." And We gave him judgement [while yet] a boy', NULL, NULL, NULL, NULL, NULL, 'https://everyayah.com/data/Alafasy_128kbps/019012.mp3', now()),
