  (19, 15, '', '[{"id":16816,"position":1,"text_uthmani":"وَسَلَـٰمٌ","transliteration":"wasalāmun","translation_bn":"এবং সালাম","root":"سلم","lemma":"سَلَٰم","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":16817,"position":2,"text_uthmani":"عَلَيْهِ","transliteration":"ʿalayhi","translation_bn":"তার উপর","root":"—","lemma":"عَلَىٰ\r","grammar_bn":"অব্যয় (Preposition)"},{"id":16818,"position":3,"text_uthmani":"يَوْمَ","transliteration":"yawma","translation_bn":"যেদিন","root":"يوم","lemma":"يَوْم","grammar_bn":"কালবাচক (Time)"},{"id":16819,"position":4,"text_uthmani":"وُلِدَ","transliteration":"wulida","translation_bn":"জন্মলাভ করে সে","root":"ولد","lemma":"وَلَدَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":16820,"position":5,"text_uthmani":"وَيَوْمَ","transliteration":"wayawma","translation_bn":"ও যেদিন","root":"يوم","lemma":"يَوْم","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":16821,"position":6,"text_uthmani":"يَمُوتُ","transliteration":"yamūtu","translation_bn":"সে মরবে","root":"موت","lemma":"مَّاتَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":16822,"position":7,"text_uthmani":"وَيَوْمَ","transliteration":"wayawma","translation_bn":"এবং যেদিন","root":"يوم","lemma":"يَوْم","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":16823,"position":8,"text_uthmani":"يُبْعَثُ","transliteration":"yub''ʿathu","translation_bn":"তাকে উঠানো হবে","root":"بعث","lemma":"بَعَثَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":16824,"position":9,"text_uthmani":"حَيًّۭا","transliteration":"ḥayyan","translation_bn":"জীবিত অবস্থায়","root":"حيي","lemma":"حَيّ","grammar_bn":"বিশেষ্য (Noun)"},{"id":16825,"position":10,"text_uthmani":"١٥","transliteration":"","translation_bn":"(১৫)","root":"—","lemma":"١٥","grammar_bn":"মার্কার"}]'::jsonb, 'wasalāmun ʿalayhi yawma wulida wayawma yamūtu wayawma yub''ʿathu ḥayyan', 'তার উপর শান্তি যেদিন সে জন্মেছে, যেদিন তার মৃত্যু হবে আর যেদিন সে জীবন্ত হয়ে উত্থিত হবে।', 'And peace be upon him the day he was born and the day he dies and the day he is raised alive.', 'তার উপর শান্তি যেদিন সে জন্মেছে, যেদিন তার মৃত্যু হবে আর যেদিন সে জীবন্ত হয়ে উত্থিত হবে।', 'And peace be upon him the day he was born and the day he dies and the day he is raised alive.', NULL, NULL, NULL, NULL, NULL, 'https://everyayah.com/data/Alafasy_128kbps/019015.mp3', now()),
  (19, 16, '', '[{"id":18173,"position":1,"text_uthmani":"وَٱذْكُرْ","transliteration":"wa-udh''kur","translation_bn":"এবং বর্ণনা করো (যা)","root":"ذكر","lemma":"ذَكَرَ","grammar_bn":"শব্দ"},{"id":18174,"position":2,"text_uthmani":"فِى","transliteration":"fī","translation_bn":"(বলা হয়েছে) মধ্যে","root":"—","lemma":"فِى\r","grammar_bn":"অব্যয় (Preposition)"},{"id":18175,"position":3,"text_uthmani":"ٱلْكِتَـٰبِ","transliteration":"l-kitābi","translation_bn":"(এই) কিতাবের","root":"كتب","lemma":"كِتَٰب","grammar_bn":"শব্দ"},{"id":18176,"position":4,"text_uthmani":"مَرْيَمَ","transliteration":"maryama","translation_bn":"মারইয়াম (সম্পর্কে)","root":"—","lemma":"مَرْيَم","grammar_bn":"নামবাচক বিশেষ্য (Proper Noun)"},{"id":18177,"position":5,"text_uthmani":"إِذِ","transliteration":"idhi","translation_bn":"যখন","root":"—","lemma":"إِذ\r","grammar_bn":"কালবাচক (Time)"},{"id":18178,"position":6,"text_uthmani":"ٱنتَبَذَتْ","transliteration":"intabadhat","translation_bn":"সে পৃথক হয়ে গেলো","root":"نبذ","lemma":"ٱنتَبَذَتْ","grammar_bn":"ক্রিয়া (Verb)"},{"id":18179,"position":7,"text_uthmani":"مِنْ","transliteration":"min","translation_bn":"থেকে","root":"—","lemma":"مِن\r","grammar_bn":"অব্যয় (Preposition)"},{"id":18180,"position":8,"text_uthmani":"أَهْلِهَا","transliteration":"ahlihā","translation_bn":"তার পরিবার","root":"اهل","lemma":"أَهْل","grammar_bn":"বিশেষ্য (Noun)"},{"id":18181,"position":9,"text_uthmani":"مَكَانًۭا","transliteration":"makānan","translation_bn":"স্থানে","root":"كون","lemma":"مَّكَان","grammar_bn":"স্থানবাচক (Location)"},{"id":18182,"position":10,"text_uthmani":"شَرْقِيًّۭا","transliteration":"sharqiyyan","translation_bn":"(বায়তুল মুকাদ্দাসের) পূর্বদিকের","root":"شرق","lemma":"شَرْقِيّ","grammar_bn":"বিশেষণ (Adjective)"},{"id":18183,"position":11,"text_uthmani":"١٦","transliteration":"","translation_bn":"(১৬)","root":"—","lemma":"١٦","grammar_bn":"মার্কার"}]'::jsonb, 'wa-udh''kur fī l-kitābi maryama idhi intabadhat min ahlihā makānan sharqiyyan', 'এ কিতাবে (উল্লেখিত) মারইয়ামের কাহিনী বর্ণনা কর- যখন সে তার পরিবারবর্গ হতে আলাদা হয়ে পূর্ব দিকে এক জায়গায় আশ্রয় নিয়েছিল।', 'And mention, [O Muhammad], in the Book [the story of] Mary, when she withdrew from her family to a place toward the east.', 'এ কিতাবে (উল্লেখিত) মারইয়ামের কাহিনী বর্ণনা কর- যখন সে তার পরিবারবর্গ হতে আলাদা হয়ে পূর্ব দিকে এক জায়গায় আশ্রয় নিয়েছিল।', 'And mention, [O Muhammad], in the Book [the story of] Mary, when she withdrew from her family to a place toward the east.', NULL, NULL, NULL, NULL, NULL, 'https://everyayah.com/data/Alafasy_128kbps/019016.mp3', now()),
  (19, 17, '', '[{"id":19209,"position":1,"text_uthmani":"فَٱتَّخَذَتْ","transliteration":"fa-ittakhadhat","translation_bn":"সে অতঃপর গ্রহণ করেছিলো (স্থান)","root":"اخذ","lemma":"ٱتَّخَذَ","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":19210,"position":2,"text_uthmani":"مِن","transliteration":"min","translation_bn":"মধ্য হতে","root":"—","lemma":"مِن\r","grammar_bn":"অব্যয় (Preposition)"},{"id":19211,"position":3,"text_uthmani":"دُونِهِمْ","transliteration":"dūnihim","translation_bn":"তাদের ছাড়া","root":"دون","lemma":"دُون","grammar_bn":"বিশেষ্য (Noun)"},{"id":19212,"position":4,"text_uthmani":"حِجَابًۭا","transliteration":"ḥijāban","translation_bn":"আড়ালে (অর্থাৎ ইতিকাফে বসলো)","root":"حجب","lemma":"حِجَاب","grammar_bn":"বিশেষ্য (Noun)"},{"id":19213,"position":5,"text_uthmani":"فَأَرْسَلْنَآ","transliteration":"fa-arsalnā","translation_bn":"আমরা অতঃপর প্রেরণ করলাম","root":"رسل","lemma":"أَرْسَلَ","grammar_bn":"শব্দ"},{"id":19214,"position":6,"text_uthmani":"إِلَيْهَا","transliteration":"ilayhā","translation_bn":"তার প্রতি","root":"—","lemma":"إِلَىٰ\r","grammar_bn":"অব্যয় (Preposition)"},{"id":19215,"position":7,"text_uthmani":"رُوحَنَا","transliteration":"rūḥanā","translation_bn":"আমাদের রূহ (অর্থাৎ ফেরেশতাকে)","root":"روح","lemma":"رُوح","grammar_bn":"বিশেষ্য (Noun)"},{"id":19216,"position":8,"text_uthmani":"فَتَمَثَّلَ","transliteration":"fatamathala","translation_bn":"অতঃপর সে আকৃতি ধারণ করলো","root":"مثل","lemma":"تَمَثَّلَ","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":19217,"position":9,"text_uthmani":"لَهَا","transliteration":"lahā","translation_bn":"তার কাছে","root":"—","lemma":"لَهَا","grammar_bn":"অব্যয় (Preposition)"},{"id":19218,"position":10,"text_uthmani":"بَشَرًۭا","transliteration":"basharan","translation_bn":"একজন মানুষের বেশে","root":"بشر","lemma":"بَشَر","grammar_bn":"বিশেষ্য (Noun)"},{"id":19219,"position":11,"text_uthmani":"سَوِيًّۭا","transliteration":"sawiyyan","translation_bn":"পূর্নাঙ্গ","root":"سوي","lemma":"سَوِيّ","grammar_bn":"বিশেষণ (Adjective)"},{"id":19220,"position":12,"text_uthmani":"١٧","transliteration":"","translation_bn":"(১৭)","root":"—","lemma":"١٧","grammar_bn":"মার্কার"}]'::jsonb, 'fa-ittakhadhat min dūnihim ḥijāban fa-arsalnā ilayhā rūḥanā fatamathala lahā basharan sawiyyan', 'সে তাদের থেকে (আড়াল করার জন্য) পর্দা টানিয়ে দিল। তখন আমি তার কাছে আমার রূহ্কে (অর্থাৎ জিবরীলকে) পাঠিয়ে দিলাম। তখন সে (অর্থাৎ জিবরীল) তার সামনে পূর্ণ মানুষের আকৃতি ধারণ করল।', 'And she took, in seclusion from them, a screen. Then We sent to her Our Angel, and he represented himself to her as a well-proportioned man.', 'সে তাদের থেকে (আড়াল করার জন্য) পর্দা টানিয়ে দিল। তখন আমি তার কাছে আমার রূহ্কে (অর্থাৎ জিবরীলকে) পাঠিয়ে দিলাম। তখন সে (অর্থাৎ জিবরীল) তার সামনে পূর্ণ মানুষের আকৃতি ধারণ করল।', 'And she took, in seclusion from them, a screen. Then We sent to her Our Angel, and he represented himself to her as a well-proportioned man.', NULL, NULL, NULL, NULL, NULL, 'https://everyayah.com/data/Alafasy_128kbps/019017.mp3', now()),
  (19, 18, '', '[{"id":20306,"position":1,"text_uthmani":"قَالَتْ","transliteration":"qālat","translation_bn":"(মারইয়াম) বললো","root":"قول","lemma":"قَالَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":20307,"position":2,"text_uthmani":"إِنِّىٓ","transliteration":"innī","translation_bn":"\"আমি নিশ্চয়ই","root":"—","lemma":"إِنّ","grammar_bn":"অভিঘাত পদ (Accusative)"},{"id":20308,"position":3,"text_uthmani":"أَعُوذُ","transliteration":"aʿūdhu","translation_bn":"আশ্রয় চাই","root":"عوذ","lemma":"عُذْ","grammar_bn":"ক্রিয়া (Verb)"},{"id":20309,"position":4,"text_uthmani":"بِٱلرَّحْمَـٰنِ","transliteration":"bil-raḥmāni","translation_bn":"কাছে দয়াময়ের","root":"رحم","lemma":"رَّحْمَٰن","grammar_bn":"অব্যয় (Preposition)"},{"id":20310,"position":5,"text_uthmani":"مِنكَ","transliteration":"minka","translation_bn":"তোমার থেকে","root":"—","lemma":"مِن\r","grammar_bn":"অব্যয় (Preposition)"},{"id":20311,"position":6,"text_uthmani":"إِن","transliteration":"in","translation_bn":"যদি","root":"—","lemma":"إِن\r","grammar_bn":"শর্তবাচক (Conditional)"},{"id":20312,"position":7,"text_uthmani":"كُنتَ","transliteration":"kunta","translation_bn":"তুমি হও","root":"كون","lemma":"كَانَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":20313,"position":8,"text_uthmani":"تَقِيًّۭا","transliteration":"taqiyyan","translation_bn":"মুত্তাকী\"","root":"وقي","lemma":"تَقِيّ","grammar_bn":"বিশেষ্য (Noun)"},{"id":20314,"position":9,"text_uthmani":"١٨","transliteration":"","translation_bn":"(১৮)","root":"—","lemma":"١٨","grammar_bn":"মার্কার"}]'::jsonb, 'qālat innī aʿūdhu bil-raḥmāni minka in kunta taqiyyan', 'মারইয়াম বলল, ‘আমি তোমা হতে দয়াময় আল্লাহর আশ্রয় প্রার্থনা করছি যদি তুমি আল্লাহকে ভয় কর’ (তবে আমার নিকট এসো না)।’', 'She said, "Indeed, I seek refuge in the Most Merciful from you, [so leave me], if you should be fearing of Allah."', 'মারইয়াম বলল, ‘আমি তোমা হতে দয়াময় আল্লাহর আশ্রয় প্রার্থনা করছি যদি তুমি আল্লাহকে ভয় কর’ (তবে আমার নিকট এসো না)।’', 'She said, "Indeed, I seek refuge in the Most Merciful from you, [so leave me], if you should be fearing of Allah."', NULL, NULL, NULL, NULL, NULL, 'https://everyayah.com/data/Alafasy_128kbps/019018.mp3', now()),
  (19, 19, '', '[{"id":21403,"position":1,"text_uthmani":"قَالَ","transliteration":"qāla","translation_bn":"সে বললো","root":"قول","lemma":"قَالَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":21404,"position":2,"text_uthmani":"إِنَّمَآ","transliteration":"innamā","translation_bn":"\"প্রকৃতপক্ষে","root":"—","lemma":"إِنّ","grammar_bn":"অভিঘাত পদ (Accusative)"},{"id":21405,"position":3,"text_uthmani":"أَنَا۠","transliteration":"anā","translation_bn":"আমি","root":"—","lemma":"أَنَا۠","grammar_bn":"সর্বনাম (Pronoun)"},{"id":21406,"position":4,"text_uthmani":"رَسُولُ","transliteration":"rasūlu","translation_bn":"(প্রেরিত) দূত","root":"رسل","lemma":"رَسُول","grammar_bn":"বিশেষ্য (Noun)"},{"id":21407,"position":5,"text_uthmani":"رَبِّكِ","transliteration":"rabbiki","translation_bn":"তোমার রবের","root":"ربب","lemma":"رَبّ","grammar_bn":"বিশেষ্য (Noun)"},{"id":21408,"position":6,"text_uthmani":"لِأَهَبَ","transliteration":"li-ahaba","translation_bn":"দান করি যেন","root":"وهب","lemma":"وَهَبَ","grammar_bn":"শব্দ"},{"id":21409,"position":7,"text_uthmani":"لَكِ","transliteration":"laki","translation_bn":"তোমাকে","root":"—","lemma":"لَكِ","grammar_bn":"অব্যয় (Preposition)"},{"id":21410,"position":8,"text_uthmani":"غُلَـٰمًۭا","transliteration":"ghulāman","translation_bn":"এক পুত্র","root":"غلم","lemma":"غُلَٰم","grammar_bn":"বিশেষ্য (Noun)"},{"id":21411,"position":9,"text_uthmani":"زَكِيًّۭا","transliteration":"zakiyyan","translation_bn":"পবিত্র\"","root":"زكو","lemma":"زَكِيّ","grammar_bn":"বিশেষণ (Adjective)"},{"id":21412,"position":10,"text_uthmani":"١٩","transliteration":"","translation_bn":"(১৯)","root":"—","lemma":"١٩","grammar_bn":"মার্কার"}]'::jsonb, 'qāla innamā anā rasūlu rabbiki li-ahaba laki ghulāman zakiyyan', 'সে বলল, ‘আমি তোমার প্রতিপালক কর্তৃক প্রেরিত হয়েছি তোমাকে একটি পুত-পবিত্র পুত্র দানের উদ্দেশ্যে।’', 'He said, "I am only the messenger of your Lord to give you [news of] a pure boy."', 'সে বলল, ‘আমি তোমার প্রতিপালক কর্তৃক প্রেরিত হয়েছি তোমাকে একটি পুত-পবিত্র পুত্র দানের উদ্দেশ্যে।’', 'He said, "I am only the messenger of your Lord to give you [news of] a pure boy."', NULL, NULL, NULL, NULL, NULL, 'https://everyayah.com/data/Alafasy_128kbps/019019.mp3', now()),
  (19, 20, '', '[{"id":22495,"position":1,"text_uthmani":"قَالَتْ","transliteration":"qālat","translation_bn":"সে বললো","root":"قول","lemma":"قَالَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":22496,"position":2,"text_uthmani":"أَنَّىٰ","transliteration":"annā","translation_bn":"\"কেমন করে","root":"اني\r","lemma":"أَنَّىٰ","grammar_bn":"প্রশ্নবোধক (Interrogative)"},{"id":22497,"position":3,"text_uthmani":"يَكُونُ","transliteration":"yakūnu","translation_bn":"হবে","root":"كون","lemma":"كَانَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":22498,"position":4,"text_uthmani":"لِى","transliteration":"lī","translation_bn":"আমার","root":"—","lemma":"لِى","grammar_bn":"অব্যয় (Preposition)"},{"id":22499,"position":5,"text_uthmani":"غُلَـٰمٌۭ","transliteration":"ghulāmun","translation_bn":"পুত্র","root":"غلم","lemma":"غُلَٰم","grammar_bn":"বিশেষ্য (Noun)"},{"id":22500,"position":6,"text_uthmani":"وَلَمْ","transliteration":"walam","translation_bn":"যখন নি","root":"—","lemma":"لَم\r","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":22501,"position":7,"text_uthmani":"يَمْسَسْنِى","transliteration":"yamsasnī","translation_bn":"আমাকে স্পর্শ করে","root":"مسس","lemma":"مَسَّ","grammar_bn":"ক্রিয়া (Verb)"},{"id":22502,"position":8,"text_uthmani":"بَشَرٌۭ","transliteration":"basharun","translation_bn":"কোন মানুষ","root":"بشر","lemma":"بَشَر","grammar_bn":"বিশেষ্য (Noun)"},{"id":22503,"position":9,"text_uthmani":"وَلَمْ","transliteration":"walam","translation_bn":"এবং নই","root":"—","lemma":"لَم\r","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":22504,"position":10,"text_uthmani":"أَكُ","transliteration":"aku","translation_bn":"আমি (হই)","root":"كون","lemma":"كَانَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":22505,"position":11,"text_uthmani":"بَغِيًّۭا","transliteration":"baghiyyan","translation_bn":"ব্যভিচারিণী\"","root":"بغي","lemma":"بَغِيّ","grammar_bn":"বিশেষ্য (Noun)"},{"id":22506,"position":12,"text_uthmani":"٢٠","transliteration":"","translation_bn":"(২০)","root":"—","lemma":"٢٠","grammar_bn":"মার্কার"}]'::jsonb, 'qālat annā yakūnu lī ghulāmun walam yamsasnī basharun walam aku baghiyyan', 'সে বলল, ‘কেমন করে আমার পুত্র হতে পারে, যখন কোন মানুষ আমাকে স্পর্শ করেনি, আর আমি অসতীও নই।’', 'She said, "How can I have a boy while no man has touched me and I have not been unchaste?"', 'সে বলল, ‘কেমন করে আমার পুত্র হতে পারে, যখন কোন মানুষ আমাকে স্পর্শ করেনি, আর আমি অসতীও নই।’', 'She said, "How can I have a boy while no man has touched me and I have not been unchaste?"', NULL, NULL, NULL, NULL, NULL, 'https://everyayah.com/data/Alafasy_128kbps/019020.mp3', now()),
  (19, 21, '', '[{"id":23643,"position":1,"text_uthmani":"قَالَ","transliteration":"qāla","translation_bn":"(ফেরেশতা) বললো","root":"قول","lemma":"قَالَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":23644,"position":2,"text_uthmani":"كَذَٰلِكِ","transliteration":"kadhāliki","translation_bn":"\"এরূপই (হবে)","root":"—","lemma":"ذَٰلِك","grammar_bn":"অব্যয় (Preposition)"},{"id":23645,"position":3,"text_uthmani":"قَالَ","transliteration":"qāla","translation_bn":"বলেছেন","root":"قول","lemma":"قَالَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":23646,"position":4,"text_uthmani":"رَبُّكِ","transliteration":"rabbuki","translation_bn":"তোমার রব","root":"ربب","lemma":"رَبّ","grammar_bn":"বিশেষ্য (Noun)"},{"id":23647,"position":5,"text_uthmani":"هُوَ","transliteration":"huwa","translation_bn":"তা","root":"—","lemma":"هُوَ","grammar_bn":"সর্বনাম (Pronoun)"},{"id":23648,"position":6,"text_uthmani":"عَلَىَّ","transliteration":"ʿalayya","translation_bn":"আমার উপর","root":"—","lemma":"عَلَىٰ\r","grammar_bn":"অব্যয় (Preposition)"},{"id":23649,"position":7,"text_uthmani":"هَيِّنٌۭ ۖ","transliteration":"hayyinun","translation_bn":"সহজ","root":"هون","lemma":"هَيِّن","grammar_bn":"বিশেষ্য (Noun)"},{"id":23651,"position":8,"text_uthmani":"وَلِنَجْعَلَهُۥٓ","transliteration":"walinajʿalahu","translation_bn":"এবং যেন তা আমরা করি","root":"جعل","lemma":"جَعَلَ","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":23652,"position":9,"text_uthmani":"ءَايَةًۭ","transliteration":"āyatan","translation_bn":"একটি নিদর্শন","root":"ايي","lemma":"ءَايَة","grammar_bn":"বিশেষ্য (Noun)"},{"id":23653,"position":10,"text_uthmani":"لِّلنَّاسِ","transliteration":"lilnnāsi","translation_bn":"মানুষদের জন্য","root":"نوس","lemma":"نَّاس","grammar_bn":"অব্যয় (Preposition)"},{"id":23654,"position":11,"text_uthmani":"وَرَحْمَةًۭ","transliteration":"waraḥmatan","translation_bn":"ও অনুগ্রহ","root":"رحم","lemma":"رَحْمَة","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":23655,"position":12,"text_uthmani":"مِّنَّا ۚ","transliteration":"minnā","translation_bn":"আমাদের থেকে","root":"—","lemma":"مِن\r","grammar_bn":"অব্যয় (Preposition)"},{"id":23657,"position":13,"text_uthmani":"وَكَانَ","transliteration":"wakāna","translation_bn":"এবং হয়েছে","root":"كون","lemma":"كَانَ","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":23658,"position":14,"text_uthmani":"أَمْرًۭا","transliteration":"amran","translation_bn":"বিষয় (সিদ্ধান্ত)","root":"امر","lemma":"أَمْر","grammar_bn":"বিশেষ্য (Noun)"},{"id":23659,"position":15,"text_uthmani":"مَّقْضِيًّۭا","transliteration":"maqḍiyyan","translation_bn":"স্থিরীকৃত","root":"قضي","lemma":"مَّقْضِيّ","grammar_bn":"বিশেষণ (Adjective)"},{"id":23660,"position":16,"text_uthmani":"٢١","transliteration":"","translation_bn":"(২১)","root":"—","lemma":"٢١","grammar_bn":"মার্কার"}]'::jsonb, 'qāla kadhāliki qāla rabbuki huwa ʿalayya hayyinun walinajʿalahu āyatan lilnnāsi waraḥmatan minnā wakāna amran maqḍiyyan', 'সে বলল, ‘এভাবেই হবে, তোমার প্রতিপালক বলেছেন- ‘ওটা আমার জন্য সহজ, আমি তাকে মানুষের জন্য নিদর্শন বানাতে চাই আর আমার পক্ষ থেকে এক রহমত, এ ব্যাপারে সিদ্ধান্ত হয়ে গেছে।’', 'He said, "Thus [it will be]; your Lord says, ''It is easy for Me, and We will make him a sign to the people and a mercy from Us. And it is a matter [already] decreed.'' "', 'সে বলল, ‘এভাবেই হবে, তোমার প্রতিপালক বলেছেন- ‘ওটা আমার জন্য সহজ, আমি তাকে মানুষের জন্য নিদর্শন বানাতে চাই আর আমার পক্ষ থেকে এক রহমত, এ ব্যাপারে সিদ্ধান্ত হয়ে গেছে।’', 'He said, "Thus [it will be]; your Lord says, ''It is easy for Me, and We will make him a sign to the people and a mercy from Us. And it is a matter [already] decreed.'' "', NULL, NULL, NULL, NULL, NULL, 'https://everyayah.com/data/Alafasy_128kbps/019021.mp3', now()),
  (19, 22, '', '[{"id":24614,"position":1,"text_uthmani":"۞ فَحَمَلَتْهُ","transliteration":"faḥamalathu","translation_bn":"তাকে সে অতঃপর গর্ভধারণ করলো","root":"حمل","lemma":"حَمَلَ","grammar_bn":"শব্দ"},{"id":24615,"position":2,"text_uthmani":"فَٱنتَبَذَتْ","transliteration":"fa-intabadhat","translation_bn":"অতঃপর সে পৃথক হয়ে গেলো","root":"نبذ","lemma":"ٱنتَبَذَتْ","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":24616,"position":3,"text_uthmani":"بِهِۦ","transliteration":"bihi","translation_bn":"তা নিয়ে","root":"—","lemma":"بِهِۦ","grammar_bn":"অব্যয় (Preposition)"},{"id":24617,"position":4,"text_uthmani":"مَكَانًۭا","transliteration":"makānan","translation_bn":"স্থানে","root":"كون","lemma":"مَّكَان","grammar_bn":"স্থানবাচক (Location)"},{"id":24618,"position":5,"text_uthmani":"قَصِيًّۭا","transliteration":"qaṣiyyan","translation_bn":"দূরবর্তী","root":"قصو","lemma":"قَصِيّ","grammar_bn":"বিশেষণ (Adjective)"},{"id":24619,"position":6,"text_uthmani":"٢٢","transliteration":"","translation_bn":"(২২)","root":"—","lemma":"٢٢","grammar_bn":"মার্কার"}]'::jsonb, 'faḥamalathu fa-intabadhat bihi makānan qaṣiyyan', 'অতঃপর ছেলে তার গর্ভে আসল। তখন সে তা নিয়ে দূরবর্তী জায়গায় চলে গেল।', 'So she conceived him, and she withdrew with him to a remote place.', 'অতঃপর ছেলে তার গর্ভে আসল। তখন সে তা নিয়ে দূরবর্তী জায়গায় চলে গেল।', 'So she conceived him, and she withdrew with him to a remote place.', NULL, NULL, NULL, NULL, NULL, 'https://everyayah.com/data/Alafasy_128kbps/019022.mp3', now()),
  (19, 23, '', '[{"id":25693,"position":1,"text_uthmani":"فَأَجَآءَهَا","transliteration":"fa-ajāahā","translation_bn":"অতঃপর তাকে নিয়ে এলো","root":"جيا","lemma":"جَا^ءَ","grammar_bn":"শব্দ"},{"id":25694,"position":2,"text_uthmani":"ٱلْمَخَاضُ","transliteration":"l-makhāḍu","translation_bn":"প্রসববেদনা","root":"مخض","lemma":"مَخَاض","grammar_bn":"শব্দ"},{"id":25695,"position":3,"text_uthmani":"إِلَىٰ","transliteration":"ilā","translation_bn":"কাছে","root":"—","lemma":"إِلَىٰ\r","grammar_bn":"অব্যয় (Preposition)"},{"id":25696,"position":4,"text_uthmani":"جِذْعِ","transliteration":"jidh''ʿi","translation_bn":"কান্ডের","root":"جذع","lemma":"جِذْع","grammar_bn":"বিশেষ্য (Noun)"},{"id":25697,"position":5,"text_uthmani":"ٱلنَّخْلَةِ","transliteration":"l-nakhlati","translation_bn":"খেজুর গাছের","root":"نخل","lemma":"نَّخْلَة","grammar_bn":"শব্দ"},{"id":25698,"position":6,"text_uthmani":"قَالَتْ","transliteration":"qālat","translation_bn":"সে বললো","root":"قول","lemma":"قَالَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":25699,"position":7,"text_uthmani":"يَـٰلَيْتَنِى","transliteration":"yālaytanī","translation_bn":"\"হায়! আমার আফসোস","root":"—","lemma":"لَيْت","grammar_bn":"সম্বোধন পদ (Vocative)"},{"id":25700,"position":8,"text_uthmani":"مِتُّ","transliteration":"mittu","translation_bn":"আমি (যদি) মরে যেতাম","root":"موت","lemma":"مَّاتَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":25701,"position":9,"text_uthmani":"قَبْلَ","transliteration":"qabla","translation_bn":"পূর্বে","root":"قبل","lemma":"قَبْل","grammar_bn":"কালবাচক (Time)"},{"id":25702,"position":10,"text_uthmani":"هَـٰذَا","transliteration":"hādhā","translation_bn":"এর","root":"—","lemma":"هَٰذَا","grammar_bn":"নির্দেশক সর্বনাম (Demonstrative)"},{"id":25703,"position":11,"text_uthmani":"وَكُنتُ","transliteration":"wakuntu","translation_bn":"এবং আমি হতাম","root":"كون","lemma":"كَانَ","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":25704,"position":12,"text_uthmani":"نَسْيًۭا","transliteration":"nasyan","translation_bn":"বিস্মৃত","root":"نسي","lemma":"نَسْي","grammar_bn":"বিশেষ্য (Noun)"},{"id":25705,"position":13,"text_uthmani":"مَّنسِيًّۭا","transliteration":"mansiyyan","translation_bn":"স্মৃতি বিলুপ্ত\"","root":"نسي","lemma":"مَّنسِيّ","grammar_bn":"বিশেষ্য (Noun)"},{"id":25706,"position":14,"text_uthmani":"٢٣","transliteration":"","translation_bn":"(২৩)","root":"—","lemma":"٢٣","grammar_bn":"মার্কার"}]'::jsonb, 'fa-ajāahā l-makhāḍu ilā jidh''ʿi l-nakhlati qālat yālaytanī mittu qabla hādhā wakuntu nasyan mansiyyan', 'সন্তান প্রসবের বেদনা তাকে এক খেজুর বৃক্ষতলের দিকে তাড়িত করল। সে বলে উঠল, ‘হায়! এর আগেই যদি আমি মরে যেতাম আর (মানুষের) স্মৃতি থেকে পুরোপুরি মুছে যেতাম!’', 'And the pains of childbirth drove her to the trunk of a palm tree. She said, "Oh, I wish I had died before this and was in oblivion, forgotten."', 'সন্তান প্রসবের বেদনা তাকে এক খেজুর বৃক্ষতলের দিকে তাড়িত করল। সে বলে উঠল, ‘হায়! এর আগেই যদি আমি মরে যেতাম আর (মানুষের) স্মৃতি থেকে পুরোপুরি মুছে যেতাম!’', 'And the pains of childbirth drove her to the trunk of a palm tree. She said, "Oh, I wish I had died before this and was in oblivion, forgotten."', NULL, NULL, NULL, NULL, NULL, 'https://everyayah.com/data/Alafasy_128kbps/019023.mp3', now()),
  (19, 24, '', '[{"id":26761,"position":1,"text_uthmani":"فَنَادَىٰهَا","transliteration":"fanādāhā","translation_bn":"অতঃপর ডেকে বললো (ফেরেশতা) তাকে","root":"ندو","lemma":"نَادَىٰ","grammar_bn":"শব্দ"},{"id":26762,"position":2,"text_uthmani":"مِن","transliteration":"min","translation_bn":"হ''তে","root":"—","lemma":"مِن\r","grammar_bn":"অব্যয় (Preposition)"},{"id":26763,"position":3,"text_uthmani":"تَحْتِهَآ","transliteration":"taḥtihā","translation_bn":"তার নিচ","root":"تحت","lemma":"تَحْت","grammar_bn":"বিশেষ্য (Noun)"},{"id":26764,"position":4,"text_uthmani":"أَلَّا","transliteration":"allā","translation_bn":"\"যে না","root":"—","lemma":"أَن\r","grammar_bn":"উদ্দেশ্যবাচক (Intention)"},{"id":26765,"position":5,"text_uthmani":"تَحْزَنِى","transliteration":"taḥzanī","translation_bn":"তুমি চিন্তা করো","root":"حزن","lemma":"يَحْزُن","grammar_bn":"ক্রিয়া (Verb)"},{"id":26766,"position":6,"text_uthmani":"قَدْ","transliteration":"qad","translation_bn":"নিশ্চয়ই","root":"—","lemma":"قَد\r","grammar_bn":"নিশ্চয়তাবোধক (Certainty)"},{"id":26767,"position":7,"text_uthmani":"جَعَلَ","transliteration":"jaʿala","translation_bn":"সৃষ্টি করেছেন","root":"جعل","lemma":"جَعَلَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":26768,"position":8,"text_uthmani":"رَبُّكِ","transliteration":"rabbuki","translation_bn":"তোমার রব","root":"ربب","lemma":"رَبّ","grammar_bn":"বিশেষ্য (Noun)"},{"id":26769,"position":9,"text_uthmani":"تَحْتَكِ","transliteration":"taḥtaki","translation_bn":"তোমার নিচে","root":"تحت","lemma":"تَحْت","grammar_bn":"স্থানবাচক (Location)"},{"id":26770,"position":10,"text_uthmani":"سَرِيًّۭا","transliteration":"sariyyan","translation_bn":"এক ঝর্ণা","root":"سري","lemma":"سَرِيّ","grammar_bn":"বিশেষ্য (Noun)"},{"id":26771,"position":11,"text_uthmani":"٢٤","transliteration":"","translation_bn":"(২৪)","root":"—","lemma":"٢٤","grammar_bn":"মার্কার"}]'::jsonb, 'fanādāhā min taḥtihā allā taḥzanī qad jaʿala rabbuki taḥtaki sariyyan', 'নিম্নদিক থেকে তাকে ডাক দেয়া হল, ‘তুমি দুঃখ করো না, তোমার প্রতিপালক তোমার পাদদেশ দিয়ে এক নির্ঝরিণী প্রবাহিত করে দিয়েছেন।', 'But he called her from below her, "Do not grieve; your Lord has provided beneath you a stream.', 'নিম্নদিক থেকে তাকে ডাক দেয়া হল, ‘তুমি দুঃখ করো না, তোমার প্রতিপালক তোমার পাদদেশ দিয়ে এক নির্ঝরিণী প্রবাহিত করে দিয়েছেন।', 'But he called her from below her, "Do not grieve; your Lord has provided beneath you a stream.', NULL, NULL, NULL, NULL, NULL, 'https://everyayah.com/data/Alafasy_128kbps/019024.mp3', now()),
  (19, 25, '', '[{"id":27790,"position":1,"text_uthmani":"وَهُزِّىٓ","transliteration":"wahuzzī","translation_bn":"এবং তুমি নাড়া দাও","root":"هزز","lemma":"هُزِّ","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":27791,"position":2,"text_uthmani":"إِلَيْكِ","transliteration":"ilayki","translation_bn":"তোমার দিকে","root":"—","lemma":"إِلَىٰ\r","grammar_bn":"অব্যয় (Preposition)"},{"id":27792,"position":3,"text_uthmani":"بِجِذْعِ","transliteration":"bijidh''ʿi","translation_bn":"কান্ডসহ","root":"جذع","lemma":"جِذْع","grammar_bn":"অব্যয় (Preposition)"},{"id":27793,"position":4,"text_uthmani":"ٱلنَّخْلَةِ","transliteration":"l-nakhlati","translation_bn":"খেজুর গাছের","root":"نخل","lemma":"نَّخْلَة","grammar_bn":"শব্দ"},{"id":27794,"position":5,"text_uthmani":"تُسَـٰقِطْ","transliteration":"tusāqiṭ","translation_bn":"ঝরে পড়বে","root":"سقط","lemma":"تُسَٰقِطْ","grammar_bn":"ক্রিয়া (Verb)"},{"id":27795,"position":6,"text_uthmani":"عَلَيْكِ","transliteration":"ʿalayki","translation_bn":"তোমার উপর","root":"—","lemma":"عَلَىٰ\r","grammar_bn":"অব্যয় (Preposition)"},{"id":27796,"position":7,"text_uthmani":"رُطَبًۭا","transliteration":"ruṭaban","translation_bn":"খেজুর","root":"رطب","lemma":"رُطَب","grammar_bn":"বিশেষ্য (Noun)"},{"id":27797,"position":8,"text_uthmani":"جَنِيًّۭا","transliteration":"janiyyan","translation_bn":"তাজা","root":"جني","lemma":"جَنِيّ","grammar_bn":"বিশেষণ (Adjective)"},{"id":27798,"position":9,"text_uthmani":"٢٥","transliteration":"","translation_bn":"(২৫)","root":"—","lemma":"٢٥","grammar_bn":"মার্কার"}]'::jsonb, 'wahuzzī ilayki bijidh''ʿi l-nakhlati tusāqiṭ ʿalayki ruṭaban janiyyan', 'খেজুর গাছের কান্ড ধরে তুমি তোমার দিকে নাড়া দাও, তা তোমার উপর তাজা পরিপক্ক খেজুর পতিত করবে।', 'And shake toward you the trunk of the palm tree; it will drop upon you ripe, fresh dates.', 'খেজুর গাছের কান্ড ধরে তুমি তোমার দিকে নাড়া দাও, তা তোমার উপর তাজা পরিপক্ক খেজুর পতিত করবে।', 'And shake toward you the trunk of the palm tree; it will drop upon you ripe, fresh dates.', NULL, NULL, NULL, NULL, NULL, 'https://everyayah.com/data/Alafasy_128kbps/019025.mp3', now()),
  (19, 26, '', '[{"id":28742,"position":1,"text_uthmani":"فَكُلِى","transliteration":"fakulī","translation_bn":"সুতরাং খাও","root":"اكل","lemma":"أَكَلَ","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":28743,"position":2,"text_uthmani":"وَٱشْرَبِى","transliteration":"wa-ish''rabī","translation_bn":"ও পান করো","root":"شرب","lemma":"شَرِبَ","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":28744,"position":3,"text_uthmani":"وَقَرِّى","transliteration":"waqarrī","translation_bn":"এবং জুড়াও","root":"قرر","lemma":"تَقَرَّ","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":28745,"position":4,"text_uthmani":"عَيْنًۭا ۖ","transliteration":"ʿaynan","translation_bn":"চোখকে","root":"عين","lemma":"عَيْن","grammar_bn":"বিশেষ্য (Noun)"},{"id":28747,"position":5,"text_uthmani":"فَإِمَّا","transliteration":"fa-immā","translation_bn":"অতঃপর যদি","root":"—","lemma":"إِمَّا\r","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":28748,"position":6,"text_uthmani":"تَرَيِنَّ","transliteration":"tarayinna","translation_bn":"তুমি দেখো","root":"راي","lemma":"رَءَا","grammar_bn":"ক্রিয়া (Verb)"},{"id":28749,"position":7,"text_uthmani":"مِنَ","transliteration":"mina","translation_bn":"মধ্য হ''তে","root":"—","lemma":"مِن\r","grammar_bn":"অব্যয় (Preposition)"},{"id":28750,"position":8,"text_uthmani":"ٱلْبَشَرِ","transliteration":"l-bashari","translation_bn":"মানুষের","root":"بشر","lemma":"بَشَر","grammar_bn":"শব্দ"},{"id":28751,"position":9,"text_uthmani":"أَحَدًۭا","transliteration":"aḥadan","translation_bn":"কাউকে","root":"احد","lemma":"أَحَد","grammar_bn":"বিশেষ্য (Noun)"},{"id":28752,"position":10,"text_uthmani":"فَقُولِىٓ","transliteration":"faqūlī","translation_bn":"তখন তুমি বলো","root":"قول","lemma":"قَالَ","grammar_bn":"শব্দ"},{"id":28753,"position":11,"text_uthmani":"إِنِّى","transliteration":"innī","translation_bn":"\"আমি নিশ্চয়ই","root":"—","lemma":"إِنّ","grammar_bn":"অভিঘাত পদ (Accusative)"},{"id":28754,"position":12,"text_uthmani":"نَذَرْتُ","transliteration":"nadhartu","translation_bn":"মানত করেছি","root":"نذر","lemma":"نَذَرْ","grammar_bn":"ক্রিয়া (Verb)"},{"id":28755,"position":13,"text_uthmani":"لِلرَّحْمَـٰنِ","transliteration":"lilrraḥmāni","translation_bn":"দয়াময়ের জন্য","root":"رحم","lemma":"رَّحْمَٰن","grammar_bn":"অব্যয় (Preposition)"},{"id":28756,"position":14,"text_uthmani":"صَوْمًۭا","transliteration":"ṣawman","translation_bn":"রোজা","root":"صوم","lemma":"صَوْم","grammar_bn":"বিশেষ্য (Noun)"},{"id":28757,"position":15,"text_uthmani":"فَلَنْ","transliteration":"falan","translation_bn":"অতএব না","root":"—","lemma":"لَن\r","grammar_bn":"শব্দ"},{"id":28758,"position":16,"text_uthmani":"أُكَلِّمَ","transliteration":"ukallima","translation_bn":"কথা বলবো আমি","root":"كلم","lemma":"كَلَّمَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":28759,"position":17,"text_uthmani":"ٱلْيَوْمَ","transliteration":"l-yawma","translation_bn":"আজ","root":"يوم","lemma":"يَوْم","grammar_bn":"শব্দ"},{"id":28760,"position":18,"text_uthmani":"إِنسِيًّۭا","transliteration":"insiyyan","translation_bn":"কোন মানুষের সাথে\"","root":"انس","lemma":"إِنسِيّ","grammar_bn":"বিশেষ্য (Noun)"},{"id":28761,"position":19,"text_uthmani":"٢٦","transliteration":"","translation_bn":"(২৬)","root":"—","lemma":"٢٦","grammar_bn":"মার্কার"}]'::jsonb, 'fakulī wa-ish''rabī waqarrī ʿaynan fa-immā tarayinna mina l-bashari aḥadan faqūlī innī nadhartu lilrraḥmāni ṣawman falan ukallima l-yawma insiyyan', 'অতঃপর খাও, পান কর আর (তোমার) চোখ জুড়াও। যদি তুমি কোন লোককে দেখতে পাও তাহলে বলবে- আমি রহমান আল্লাহর জন্য সাওম পালনের মানৎ করেছি, কাজেই আমি কোন মানুষের সঙ্গে আজ কিছুতেই কথা বলব না।’', 'So eat and drink and be contented. And if you see from among humanity anyone, say, ''Indeed, I have vowed to the Most Merciful abstention, so I will not speak today to [any] man.'' "', 'অতঃপর খাও, পান কর আর (তোমার) চোখ জুড়াও। যদি তুমি কোন লোককে দেখতে পাও তাহলে বলবে- আমি রহমান আল্লাহর জন্য সাওম পালনের মানৎ করেছি, কাজেই আমি কোন মানুষের সঙ্গে আজ কিছুতেই কথা বলব না।’', 'So eat and drink and be contented. And if you see from among humanity anyone, say, ''Indeed, I have vowed to the Most Merciful abstention, so I will not speak today to [any] man.'' "', NULL, NULL, NULL, NULL, NULL, 'https://everyayah.com/data/Alafasy_128kbps/019026.mp3', now()),
  (19, 27, '', '[{"id":30006,"position":1,"text_uthmani":"فَأَتَتْ","transliteration":"fa-atat","translation_bn":"অতঃপর সে আসলো","root":"اتي","lemma":"أَتَى","grammar_bn":"শব্দ"},{"id":30007,"position":2,"text_uthmani":"بِهِۦ","transliteration":"bihi","translation_bn":"তাকে নিয়ে","root":"—","lemma":"بِهِۦ","grammar_bn":"অব্যয় (Preposition)"},{"id":30008,"position":3,"text_uthmani":"قَوْمَهَا","transliteration":"qawmahā","translation_bn":"তার সম্প্রদায়ের কাছে","root":"قوم","lemma":"قَوْم","grammar_bn":"বিশেষ্য (Noun)"},{"id":30009,"position":4,"text_uthmani":"تَحْمِلُهُۥ ۖ","transliteration":"taḥmiluhu","translation_bn":"তাকে বহন করে","root":"حمل","lemma":"حَمَلَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":30011,"position":5,"text_uthmani":"قَالُوا۟","transliteration":"qālū","translation_bn":"তারা বললো","root":"قول","lemma":"قَالَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":30012,"position":6,"text_uthmani":"يَـٰمَرْيَمُ","transliteration":"yāmaryamu","translation_bn":"\"হে মারইয়াম","root":"—","lemma":"مَرْيَم","grammar_bn":"সম্বোধন পদ (Vocative)"},{"id":30013,"position":7,"text_uthmani":"لَقَدْ","transliteration":"laqad","translation_bn":"নিশ্চয়ই","root":"—","lemma":"قَد\r","grammar_bn":"দৃঢ়তাবোধক (Emphatic)"},{"id":30014,"position":8,"text_uthmani":"جِئْتِ","transliteration":"ji''ti","translation_bn":"এনেছো","root":"جيا","lemma":"جَا^ءَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":30015,"position":9,"text_uthmani":"شَيْـًۭٔا","transliteration":"shayan","translation_bn":"কিছু","root":"شيا","lemma":"شَىْء","grammar_bn":"বিশেষ্য (Noun)"},{"id":30016,"position":10,"text_uthmani":"فَرِيًّۭا","transliteration":"fariyyan","translation_bn":"জঘন্য","root":"فري","lemma":"فَرِيّ","grammar_bn":"বিশেষণ (Adjective)"},{"id":30017,"position":11,"text_uthmani":"٢٧","transliteration":"","translation_bn":"(২৭)","root":"—","lemma":"٢٧","grammar_bn":"মার্কার"}]'::jsonb, 'fa-atat bihi qawmahā taḥmiluhu qālū yāmaryamu laqad ji''ti shayan fariyyan', 'অতঃপর সে তার সন্তানকে বয়ে নিয়ে তার সম্প্রদায়ের কাছে আসল। তারা বলল, ‘হে মারইয়াম! তুমি তো এক অদ্ভুত জিনিস নিয়ে এসেছ!', 'Then she brought him to her people, carrying him. They said, "O Mary, you have certainly done a thing unprecedented.', 'অতঃপর সে তার সন্তানকে বয়ে নিয়ে তার সম্প্রদায়ের কাছে আসল। তারা বলল, ‘হে মারইয়াম! তুমি তো এক অদ্ভুত জিনিস নিয়ে এসেছ!', 'Then she brought him to her people, carrying him. They said, "O Mary, you have certainly done a thing unprecedented.', NULL, NULL, NULL, NULL, NULL, 'https://everyayah.com/data/Alafasy_128kbps/019027.mp3', now()),
  (19, 28, '', '[{"id":30807,"position":1,"text_uthmani":"يَـٰٓأُخْتَ","transliteration":"yāukh''ta","translation_bn":"হে বোন","root":"اخو","lemma":"أُخْت","grammar_bn":"সম্বোধন পদ (Vocative)"},{"id":30808,"position":2,"text_uthmani":"هَـٰرُونَ","transliteration":"hārūna","translation_bn":"হারূনের","root":"—","lemma":"هَٰرُون","grammar_bn":"নামবাচক বিশেষ্য (Proper Noun)"},{"id":30809,"position":3,"text_uthmani":"مَا","transliteration":"mā","translation_bn":"না","root":"—","lemma":"مَا\r","grammar_bn":"না-বোধক (Negative)"},{"id":30810,"position":4,"text_uthmani":"كَانَ","transliteration":"kāna","translation_bn":"ছিলেন","root":"كون","lemma":"كَانَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":30811,"position":5,"text_uthmani":"أَبُوكِ","transliteration":"abūki","translation_bn":"তোমার বাপ","root":"ابو","lemma":"أَبٌ","grammar_bn":"বিশেষ্য (Noun)"},{"id":30812,"position":6,"text_uthmani":"ٱمْرَأَ","transliteration":"im''ra-a","translation_bn":"ব্যক্তি","root":"مرا","lemma":"ٱمْرَأ","grammar_bn":"বিশেষ্য (Noun)"},{"id":30813,"position":7,"text_uthmani":"سَوْءٍۢ","transliteration":"sawin","translation_bn":"অসৎ","root":"سوا","lemma":"سَوْء","grammar_bn":"বিশেষ্য (Noun)"},{"id":30814,"position":8,"text_uthmani":"وَمَا","transliteration":"wamā","translation_bn":"আর না","root":"—","lemma":"مَا\r","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":30815,"position":9,"text_uthmani":"كَانَتْ","transliteration":"kānat","translation_bn":"ছিলেন","root":"كون","lemma":"كَانَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":30816,"position":10,"text_uthmani":"أُمُّكِ","transliteration":"ummuki","translation_bn":"তোমার মা","root":"امم","lemma":"أُمّ","grammar_bn":"বিশেষ্য (Noun)"},{"id":30817,"position":11,"text_uthmani":"بَغِيًّۭا","transliteration":"baghiyyan","translation_bn":"ব্যভিচারিনী (চরিত্রহীনা)\"","root":"بغي","lemma":"بَغِيّ","grammar_bn":"বিশেষ্য (Noun)"},{"id":30818,"position":12,"text_uthmani":"٢٨","transliteration":"","translation_bn":"(২৮)","root":"—","lemma":"٢٨","grammar_bn":"মার্কার"}]'::jsonb, 'yāukh''ta hārūna mā kāna abūki im''ra-a sawin wamā kānat ummuki baghiyyan', 'ওহে হারূনের বোন! তোমার পিতা তো খারাপ লোক ছিল না, আর তোমার মাও ছিল না কোন অসতী নারী।’', 'O sister of Aaron, your father was not a man of evil, nor was your mother unchaste."', 'ওহে হারূনের বোন! তোমার পিতা তো খারাপ লোক ছিল না, আর তোমার মাও ছিল না কোন অসতী নারী।’', 'O sister of Aaron, your father was not a man of evil, nor was your mother unchaste."', NULL, NULL, NULL, NULL, NULL, 'https://everyayah.com/data/Alafasy_128kbps/019028.mp3', now()),
  (19, 29, '', '[{"id":31963,"position":1,"text_uthmani":"فَأَشَارَتْ","transliteration":"fa-ashārat","translation_bn":"তখন সে ইঙ্গিত করলো","root":"شور","lemma":"أَشَارَتْ","grammar_bn":"শব্দ"},{"id":31964,"position":2,"text_uthmani":"إِلَيْهِ ۖ","transliteration":"ilayhi","translation_bn":"তার দিকে","root":"—","lemma":"إِلَىٰ\r","grammar_bn":"অব্যয় (Preposition)"},{"id":31966,"position":3,"text_uthmani":"قَالُوا۟","transliteration":"qālū","translation_bn":"তারা বললো","root":"قول","lemma":"قَالَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":31967,"position":4,"text_uthmani":"كَيْفَ","transliteration":"kayfa","translation_bn":"\"কিভাবে","root":"كيف\r","lemma":"كَيْف","grammar_bn":"প্রশ্নবোধক (Interrogative)"},{"id":31968,"position":5,"text_uthmani":"نُكَلِّمُ","transliteration":"nukallimu","translation_bn":"কথা বলবো আমরা","root":"كلم","lemma":"كَلَّمَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":31969,"position":6,"text_uthmani":"مَن","transliteration":"man","translation_bn":"যে","root":"—","lemma":"مَن\r","grammar_bn":"সাপেক্ষ সর্বনাম (Relative)"},{"id":31970,"position":7,"text_uthmani":"كَانَ","transliteration":"kāna","translation_bn":"আছে","root":"كون","lemma":"كَانَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":31971,"position":8,"text_uthmani":"فِى","transliteration":"fī","translation_bn":"মধ্যে","root":"—","lemma":"فِى\r","grammar_bn":"অব্যয় (Preposition)"},{"id":31972,"position":9,"text_uthmani":"ٱلْمَهْدِ","transliteration":"l-mahdi","translation_bn":"দোলনার","root":"مهد","lemma":"مَهْد","grammar_bn":"শব্দ"},{"id":31973,"position":10,"text_uthmani":"صَبِيًّۭا","transliteration":"ṣabiyyan","translation_bn":"ছোট্ট শিশু\"","root":"صبو","lemma":"صَبِيّ","grammar_bn":"বিশেষ্য (Noun)"},{"id":31974,"position":11,"text_uthmani":"٢٩","transliteration":"","translation_bn":"(২৯)","root":"—","lemma":"٢٩","grammar_bn":"মার্কার"}]'::jsonb, 'fa-ashārat ilayhi qālū kayfa nukallimu man kāna fī l-mahdi ṣabiyyan', 'তখন মারইয়াম তার ছেলের দিকে ইশারা করল। তারা বলল, ‘আমরা কোলের বাচ্চার সঙ্গে কীভাবে কথা