  (19, 30, '', '[{"id":32596,"position":1,"text_uthmani":"قَالَ","transliteration":"qāla","translation_bn":"(শিশু ঈসা) বললো","root":"قول","lemma":"قَالَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":32597,"position":2,"text_uthmani":"إِنِّى","transliteration":"innī","translation_bn":"\"নিশ্চয়ই আমি","root":"—","lemma":"إِنّ","grammar_bn":"অভিঘাত পদ (Accusative)"},{"id":32598,"position":3,"text_uthmani":"عَبْدُ","transliteration":"ʿabdu","translation_bn":"দাস","root":"عبد","lemma":"عَبْد","grammar_bn":"বিশেষ্য (Noun)"},{"id":32599,"position":4,"text_uthmani":"ٱللَّهِ","transliteration":"l-lahi","translation_bn":"আল্লাহ্‌র","root":"اله","lemma":"ٱللَّه","grammar_bn":"নামবাচক বিশেষ্য (Proper Noun)"},{"id":32600,"position":5,"text_uthmani":"ءَاتَىٰنِىَ","transliteration":"ātāniya","translation_bn":"আমাকে তিনি দিয়েছেন","root":"اتي","lemma":"ا^تَى","grammar_bn":"ক্রিয়া (Verb)"},{"id":32601,"position":6,"text_uthmani":"ٱلْكِتَـٰبَ","transliteration":"l-kitāba","translation_bn":"কিতাব","root":"كتب","lemma":"كِتَٰب","grammar_bn":"শব্দ"},{"id":32602,"position":7,"text_uthmani":"وَجَعَلَنِى","transliteration":"wajaʿalanī","translation_bn":"এবং আমাকে বানিয়েছেন","root":"جعل","lemma":"جَعَلَ","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":32603,"position":8,"text_uthmani":"نَبِيًّۭا","transliteration":"nabiyyan","translation_bn":"নাবী","root":"نبا","lemma":"نَّبِىّ","grammar_bn":"বিশেষ্য (Noun)"},{"id":32604,"position":9,"text_uthmani":"٣٠","transliteration":"","translation_bn":"(৩০)","root":"—","lemma":"٣٠","grammar_bn":"মার্কার"}]'::jsonb, 'qāla innī ʿabdu l-lahi ātāniya l-kitāba wajaʿalanī nabiyyan', 'শিশুটি বলে উঠল, ‘আমি আল্লাহর বান্দাহ, তিনি আমাকে কিতাব দিয়েছেন, আর আমাকে নবী করেছেন।', '[Jesus] said, "Indeed, I am the servant of Allah. He has given me the Scripture and made me a prophet.', 'শিশুটি বলে উঠল, ‘আমি আল্লাহর বান্দাহ, তিনি আমাকে কিতাব দিয়েছেন, আর আমাকে নবী করেছেন।', '[Jesus] said, "Indeed, I am the servant of Allah. He has given me the Scripture and made me a prophet.', NULL, NULL, NULL, NULL, NULL, 'https://everyayah.com/data/Alafasy_128kbps/019030.mp3', now()),
  (19, 31, '', '[{"id":33467,"position":1,"text_uthmani":"وَجَعَلَنِى","transliteration":"wajaʿalanī","translation_bn":"এবং আমাকে করেছেন","root":"جعل","lemma":"جَعَلَ","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":33468,"position":2,"text_uthmani":"مُبَارَكًا","transliteration":"mubārakan","translation_bn":"কল্যাণময়","root":"برك","lemma":"مُبَارَك","grammar_bn":"বিশেষ্য (Noun)"},{"id":33469,"position":3,"text_uthmani":"أَيْنَ","transliteration":"ayna","translation_bn":"যেখানে","root":"—","lemma":"أَيْن\r","grammar_bn":"স্থানবাচক (Location)"},{"id":33470,"position":4,"text_uthmani":"مَا","transliteration":"mā","translation_bn":"যা","root":"—","lemma":"مَا\r","grammar_bn":"সাপেক্ষ সর্বনাম (Relative)"},{"id":33471,"position":5,"text_uthmani":"كُنتُ","transliteration":"kuntu","translation_bn":"আমি থাকি","root":"كون","lemma":"كَانَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":33472,"position":6,"text_uthmani":"وَأَوْصَـٰنِى","transliteration":"wa-awṣānī","translation_bn":"এবং আমাকে নির্দেশ দিয়েছেন","root":"وصي","lemma":"أَوْصَٰ","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":33473,"position":7,"text_uthmani":"بِٱلصَّلَوٰةِ","transliteration":"bil-ṣalati","translation_bn":"ব্যাপারে সালাতের","root":"صلو","lemma":"صَلَوٰة","grammar_bn":"অব্যয় (Preposition)"},{"id":33474,"position":8,"text_uthmani":"وَٱلزَّكَوٰةِ","transliteration":"wal-zakati","translation_bn":"ও যাকাতের","root":"زكو","lemma":"زَكَوٰة","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":33475,"position":9,"text_uthmani":"مَا","transliteration":"mā","translation_bn":"যা","root":"—","lemma":"مَا\r","grammar_bn":"সাপেক্ষ সর্বনাম (Relative)"},{"id":33476,"position":10,"text_uthmani":"دُمْتُ","transliteration":"dum''tu","translation_bn":"আমি থাকি যতদিন পর্যন্ত","root":"دوم","lemma":"دَامُ","grammar_bn":"ক্রিয়া (Verb)"},{"id":33477,"position":11,"text_uthmani":"حَيًّۭا","transliteration":"ḥayyan","translation_bn":"জীবিত","root":"حيي","lemma":"حَيّ","grammar_bn":"বিশেষ্য (Noun)"},{"id":33478,"position":12,"text_uthmani":"٣١","transliteration":"","translation_bn":"(৩১)","root":"—","lemma":"٣١","grammar_bn":"মার্কার"}]'::jsonb, 'wajaʿalanī mubārakan ayna mā kuntu wa-awṣānī bil-ṣalati wal-zakati mā dum''tu ḥayyan', 'আমি যেখানেই থাকি না কেন তিনি আমাকে বরকতময় করেছেন আর আমাকে নামায ও যাকাতের হুকুম দিয়েছেন- যতদিন আমি জীবিত থাকি।', 'And He has made me blessed wherever I am and has enjoined upon me prayer and zakah as long as I remain alive', 'আমি যেখানেই থাকি না কেন তিনি আমাকে বরকতময় করেছেন আর আমাকে নামায ও যাকাতের হুকুম দিয়েছেন- যতদিন আমি জীবিত থাকি।', 'And He has made me blessed wherever I am and has enjoined upon me prayer and zakah as long as I remain alive', NULL, NULL, NULL, NULL, NULL, 'https://everyayah.com/data/Alafasy_128kbps/019031.mp3', now()),
  (19, 32, '', '[{"id":34513,"position":1,"text_uthmani":"وَبَرًّۢا","transliteration":"wabarran","translation_bn":"এবং অনুগত","root":"برر","lemma":"بَرّ","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":34514,"position":2,"text_uthmani":"بِوَٰلِدَتِى","transliteration":"biwālidatī","translation_bn":"আমার মায়ের","root":"ولد","lemma":"وَالِد","grammar_bn":"অব্যয় (Preposition)"},{"id":34515,"position":3,"text_uthmani":"وَلَمْ","transliteration":"walam","translation_bn":"এবং নি","root":"—","lemma":"لَم\r","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":34516,"position":4,"text_uthmani":"يَجْعَلْنِى","transliteration":"yajʿalnī","translation_bn":"আমাকে করেন","root":"جعل","lemma":"جَعَلَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":34517,"position":5,"text_uthmani":"جَبَّارًۭا","transliteration":"jabbāran","translation_bn":"উদ্ধত","root":"جبر","lemma":"جَبَّار","grammar_bn":"বিশেষ্য (Noun)"},{"id":34518,"position":6,"text_uthmani":"شَقِيًّۭا","transliteration":"shaqiyyan","translation_bn":"হতভাগ্য","root":"شقو","lemma":"شَقِيّ","grammar_bn":"বিশেষণ (Adjective)"},{"id":34519,"position":7,"text_uthmani":"٣٢","transliteration":"","translation_bn":"(৩২)","root":"—","lemma":"٣٢","grammar_bn":"মার্কার"}]'::jsonb, 'wabarran biwālidatī walam yajʿalnī jabbāran shaqiyyan', 'আর (তিনি আমাকে করেছেন) আমার মাতার প্রতি সদয়, তিনি আমাকে দাম্ভিক হতভাগ্য করেননি।', 'And [made me] dutiful to my mother, and He has not made me a wretched tyrant.', 'আর (তিনি আমাকে করেছেন) আমার মাতার প্রতি সদয়, তিনি আমাকে দাম্ভিক হতভাগ্য করেননি।', 'And [made me] dutiful to my mother, and He has not made me a wretched tyrant.', NULL, NULL, NULL, NULL, NULL, 'https://everyayah.com/data/Alafasy_128kbps/019032.mp3', now()),
  (19, 33, '', '[{"id":35552,"position":1,"text_uthmani":"وَٱلسَّلَـٰمُ","transliteration":"wal-salāmu","translation_bn":"এবং শান্তি","root":"سلم","lemma":"سَلَٰم","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":35553,"position":2,"text_uthmani":"عَلَىَّ","transliteration":"ʿalayya","translation_bn":"আমার উপর","root":"—","lemma":"عَلَىٰ\r","grammar_bn":"অব্যয় (Preposition)"},{"id":35554,"position":3,"text_uthmani":"يَوْمَ","transliteration":"yawma","translation_bn":"যেদিন","root":"يوم","lemma":"يَوْم","grammar_bn":"কালবাচক (Time)"},{"id":35555,"position":4,"text_uthmani":"وُلِدتُّ","transliteration":"wulidttu","translation_bn":"আমি জন্মলাভ করেছি","root":"ولد","lemma":"وَلَدَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":35556,"position":5,"text_uthmani":"وَيَوْمَ","transliteration":"wayawma","translation_bn":"ও যেদিন","root":"يوم","lemma":"يَوْم","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":35557,"position":6,"text_uthmani":"أَمُوتُ","transliteration":"amūtu","translation_bn":"আমি মরবো","root":"موت","lemma":"مَّاتَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":35558,"position":7,"text_uthmani":"وَيَوْمَ","transliteration":"wayawma","translation_bn":"ও যেদিন","root":"يوم","lemma":"يَوْم","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":35559,"position":8,"text_uthmani":"أُبْعَثُ","transliteration":"ub''ʿathu","translation_bn":"উত্থিত হবো","root":"بعث","lemma":"بَعَثَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":35560,"position":9,"text_uthmani":"حَيًّۭا","transliteration":"ḥayyan","translation_bn":"জীবিত\"","root":"حيي","lemma":"حَيّ","grammar_bn":"বিশেষ্য (Noun)"},{"id":35561,"position":10,"text_uthmani":"٣٣","transliteration":"","translation_bn":"(৩৩)","root":"—","lemma":"٣٣","grammar_bn":"মার্কার"}]'::jsonb, 'wal-salāmu ʿalayya yawma wulidttu wayawma amūtu wayawma ub''ʿathu ḥayyan', 'আমার উপর আছে শান্তি যেদিন আমি জন্মেছি, যেদিন আমার মৃত্যু হবে আর আমি যেদিন জীবিত হয়ে উত্থিত হব।’', 'And peace is on me the day I was born and the day I will die and the day I am raised alive."', 'আমার উপর আছে শান্তি যেদিন আমি জন্মেছি, যেদিন আমার মৃত্যু হবে আর আমি যেদিন জীবিত হয়ে উত্থিত হব।’', 'And peace is on me the day I was born and the day I will die and the day I am raised alive."', NULL, NULL, NULL, NULL, NULL, 'https://everyayah.com/data/Alafasy_128kbps/019033.mp3', now()),
  (19, 34, '', '[{"id":36312,"position":1,"text_uthmani":"ذَٰلِكَ","transliteration":"dhālika","translation_bn":"এই (হলো)","root":"—","lemma":"ذَٰلِك","grammar_bn":"নির্দেশক সর্বনাম (Demonstrative)"},{"id":36313,"position":2,"text_uthmani":"عِيسَى","transliteration":"ʿīsā","translation_bn":"ঈসা","root":"—","lemma":"عِيسَى","grammar_bn":"নামবাচক বিশেষ্য (Proper Noun)"},{"id":36314,"position":3,"text_uthmani":"ٱبْنُ","transliteration":"ub''nu","translation_bn":"পুত্র","root":"بني","lemma":"ٱبْن","grammar_bn":"বিশেষ্য (Noun)"},{"id":36315,"position":4,"text_uthmani":"مَرْيَمَ ۚ","transliteration":"maryama","translation_bn":"মারইয়ামের","root":"—","lemma":"مَرْيَم","grammar_bn":"নামবাচক বিশেষ্য (Proper Noun)"},{"id":36317,"position":5,"text_uthmani":"قَوْلَ","transliteration":"qawla","translation_bn":"কথা","root":"قول","lemma":"قَوْل","grammar_bn":"বিশেষ্য (Noun)"},{"id":36318,"position":6,"text_uthmani":"ٱلْحَقِّ","transliteration":"l-ḥaqi","translation_bn":"চূড়ান্ত সত্য","root":"حقق","lemma":"حَقّ","grammar_bn":"শব্দ"},{"id":36319,"position":7,"text_uthmani":"ٱلَّذِى","transliteration":"alladhī","translation_bn":"যা (এমন যে)","root":"—","lemma":"ٱلَّذِى","grammar_bn":"সাপেক্ষ সর্বনাম (Relative)"},{"id":36320,"position":8,"text_uthmani":"فِيهِ","transliteration":"fīhi","translation_bn":"যে বিষয়ে","root":"—","lemma":"فِى\r","grammar_bn":"অব্যয় (Preposition)"},{"id":36321,"position":9,"text_uthmani":"يَمْتَرُونَ","transliteration":"yamtarūna","translation_bn":"তারা সন্দেহ করছে","root":"مري","lemma":"يَمْتَرُ","grammar_bn":"ক্রিয়া (Verb)"},{"id":36322,"position":10,"text_uthmani":"٣٤","transliteration":"","translation_bn":"(৩৪)","root":"—","lemma":"٣٤","grammar_bn":"মার্কার"}]'::jsonb, 'dhālika ʿīsā ub''nu maryama qawla l-ḥaqi alladhī fīhi yamtarūna', 'এই হচ্ছে মারইয়াম-পুত্র ঈসা, (এটাই) সত্য কথা যে বিষয়ে লোকেরা সন্দেহ পোষণ করে।', 'That is Jesus, the son of Mary - the word of truth about which they are in dispute.', 'এই হচ্ছে মারইয়াম-পুত্র ঈসা, (এটাই) সত্য কথা যে বিষয়ে লোকেরা সন্দেহ পোষণ করে।', 'That is Jesus, the son of Mary - the word of truth about which they are in dispute.', NULL, NULL, NULL, NULL, NULL, 'https://everyayah.com/data/Alafasy_128kbps/019034.mp3', now()),
  (19, 35, '', '[{"id":37108,"position":1,"text_uthmani":"مَا","transliteration":"mā","translation_bn":"নয়","root":"—","lemma":"مَا\r","grammar_bn":"না-বোধক (Negative)"},{"id":37109,"position":2,"text_uthmani":"كَانَ","transliteration":"kāna","translation_bn":"কাজ","root":"كون","lemma":"كَانَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":37110,"position":3,"text_uthmani":"لِلَّهِ","transliteration":"lillahi","translation_bn":"আল্লাহ্‌র জন্য","root":"اله","lemma":"ٱللَّه","grammar_bn":"অব্যয় (Preposition)"},{"id":37111,"position":4,"text_uthmani":"أَن","transliteration":"an","translation_bn":"যে","root":"—","lemma":"أَن\r","grammar_bn":"অধীনস্থ যোজক (Subordinating)"},{"id":37112,"position":5,"text_uthmani":"يَتَّخِذَ","transliteration":"yattakhidha","translation_bn":"তিনি গ্রহণ করবেন","root":"اخذ","lemma":"ٱتَّخَذَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":37113,"position":6,"text_uthmani":"مِن","transliteration":"min","translation_bn":"কোন","root":"—","lemma":"مِن\r","grammar_bn":"অব্যয় (Preposition)"},{"id":37114,"position":7,"text_uthmani":"وَلَدٍۢ ۖ","transliteration":"waladin","translation_bn":"সন্তান","root":"ولد","lemma":"وَلَد","grammar_bn":"বিশেষ্য (Noun)"},{"id":37116,"position":8,"text_uthmani":"سُبْحَـٰنَهُۥٓ ۚ","transliteration":"sub''ḥānahu","translation_bn":"তিনি পবিত্র","root":"سبح","lemma":"سُبْحَٰن","grammar_bn":"বিশেষ্য (Noun)"},{"id":37118,"position":9,"text_uthmani":"إِذَا","transliteration":"idhā","translation_bn":"যখন","root":"—","lemma":"إِذَا\r","grammar_bn":"কালবাচক (Time)"},{"id":37119,"position":10,"text_uthmani":"قَضَىٰٓ","transliteration":"qaḍā","translation_bn":"স্হির করেন","root":"قضي","lemma":"قَضَىٰ^","grammar_bn":"ক্রিয়া (Verb)"},{"id":37120,"position":11,"text_uthmani":"أَمْرًۭا","transliteration":"amran","translation_bn":"কোন বিষয়কে","root":"امر","lemma":"أَمْر","grammar_bn":"বিশেষ্য (Noun)"},{"id":37121,"position":12,"text_uthmani":"فَإِنَّمَا","transliteration":"fa-innamā","translation_bn":"তখন শুধুমাত্র","root":"—","lemma":"إِنّ","grammar_bn":"শব্দ"},{"id":37122,"position":13,"text_uthmani":"يَقُولُ","transliteration":"yaqūlu","translation_bn":"বলেন","root":"قول","lemma":"قَالَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":37123,"position":14,"text_uthmani":"لَهُۥ","transliteration":"lahu","translation_bn":"তাকে","root":"—","lemma":"لَهُۥ","grammar_bn":"অব্যয় (Preposition)"},{"id":37124,"position":15,"text_uthmani":"كُن","transliteration":"kun","translation_bn":"\"হও\"","root":"كون","lemma":"كَانَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":37125,"position":16,"text_uthmani":"فَيَكُونُ","transliteration":"fayakūnu","translation_bn":"তখনই হয়ে যায়","root":"كون","lemma":"كَانَ","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":37126,"position":17,"text_uthmani":"٣٥","transliteration":"","translation_bn":"(৩৫)","root":"—","lemma":"٣٥","grammar_bn":"মার্কার"}]'::jsonb, 'mā kāna lillahi an yattakhidha min waladin sub''ḥānahu idhā qaḍā amran fa-innamā yaqūlu lahu kun fayakūnu', 'সন্তান গ্রহণ করা আল্লাহর কাজ নয়, তিনি পবিত্র, মহান; যখন তিনি কিছু করার সিদ্ধান্ত করেন তখন তার জন্য শুধু বলেন, ‘হয়ে যাও’, আর তা হয়ে যায়।', 'It is not [befitting] for Allah to take a son; exalted is He! When He decrees an affair, He only says to it, "Be," and it is.', 'সন্তান গ্রহণ করা আল্লাহর কাজ নয়, তিনি পবিত্র, মহান; যখন তিনি কিছু করার সিদ্ধান্ত করেন তখন তার জন্য শুধু বলেন, ‘হয়ে যাও’, আর তা হয়ে যায়।', 'It is not [befitting] for Allah to take a son; exalted is He! When He decrees an affair, He only says to it, "Be," and it is.', NULL, NULL, NULL, NULL, NULL, 'https://everyayah.com/data/Alafasy_128kbps/019035.mp3', now()),
  (19, 36, '', '[{"id":37922,"position":1,"text_uthmani":"وَإِنَّ","transliteration":"wa-inna","translation_bn":"\"এবং নিশ্চয়ই","root":"—","lemma":"إِنّ","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":37923,"position":2,"text_uthmani":"ٱللَّهَ","transliteration":"l-laha","translation_bn":"আল্লাহ্‌","root":"اله","lemma":"ٱللَّه","grammar_bn":"নামবাচক বিশেষ্য (Proper Noun)"},{"id":37924,"position":3,"text_uthmani":"رَبِّى","transliteration":"rabbī","translation_bn":"আমার রব","root":"ربب","lemma":"رَبّ","grammar_bn":"বিশেষ্য (Noun)"},{"id":37925,"position":4,"text_uthmani":"وَرَبُّكُمْ","transliteration":"warabbukum","translation_bn":"ও তোমাদের রব","root":"ربب","lemma":"رَبّ","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":37926,"position":5,"text_uthmani":"فَٱعْبُدُوهُ ۚ","transliteration":"fa-uʿ''budūhu","translation_bn":"সুতরাং তাঁরই তোমরা ইবাদাত করো","root":"عبد","lemma":"عَبَدَ","grammar_bn":"শব্দ"},{"id":37928,"position":6,"text_uthmani":"هَـٰذَا","transliteration":"hādhā","translation_bn":"এটা","root":"—","lemma":"هَٰذَا","grammar_bn":"নির্দেশক সর্বনাম (Demonstrative)"},{"id":37929,"position":7,"text_uthmani":"صِرَٰطٌۭ","transliteration":"ṣirāṭun","translation_bn":"পথ","root":"صرط","lemma":"صِرَٰط","grammar_bn":"বিশেষ্য (Noun)"},{"id":37930,"position":8,"text_uthmani":"مُّسْتَقِيمٌۭ","transliteration":"mus''taqīmun","translation_bn":"সরল সঠিক\"","root":"قوم","lemma":"مُّسْتَقِيم","grammar_bn":"বিশেষ্য (Noun)"},{"id":37931,"position":9,"text_uthmani":"٣٦","transliteration":"","translation_bn":"(৩৬)","root":"—","lemma":"٣٦","grammar_bn":"মার্কার"}]'::jsonb, 'wa-inna l-laha rabbī warabbukum fa-uʿ''budūhu hādhā ṣirāṭun mus''taqīmun', 'আল্লাহ্ই আমার ও তোমাদের প্রতিপালক, কাজেই তোমরা তাঁরই ‘ইবাদাত কর, এটাই সরল সুদৃঢ় পথ।', '[Jesus said], "And indeed, Allah is my Lord and your Lord, so worship Him. That is a straight path."', 'আল্লাহ্ই আমার ও তোমাদের প্রতিপালক, কাজেই তোমরা তাঁরই ‘ইবাদাত কর, এটাই সরল সুদৃঢ় পথ।', '[Jesus said], "And indeed, Allah is my Lord and your Lord, so worship Him. That is a straight path."', NULL, NULL, NULL, NULL, NULL, 'https://everyayah.com/data/Alafasy_128kbps/019036.mp3', now()),
  (19, 37, '', '[{"id":38749,"position":1,"text_uthmani":"فَٱخْتَلَفَ","transliteration":"fa-ikh''talafa","translation_bn":"অতঃপর মতভেদ করলো","root":"خلف","lemma":"ٱخْتَلَفَ","grammar_bn":"শব্দ"},{"id":38750,"position":2,"text_uthmani":"ٱلْأَحْزَابُ","transliteration":"l-aḥzābu","translation_bn":"বিভিন্ন দল","root":"حزب","lemma":"حِزْب","grammar_bn":"শব্দ"},{"id":38751,"position":3,"text_uthmani":"مِنۢ","transliteration":"min","translation_bn":"থেকে","root":"—","lemma":"مِن\r","grammar_bn":"অব্যয় (Preposition)"},{"id":38752,"position":4,"text_uthmani":"بَيْنِهِمْ ۖ","transliteration":"baynihim","translation_bn":"তাদের মাঝে","root":"بين","lemma":"بَيْن","grammar_bn":"বিশেষ্য (Noun)"},{"id":38754,"position":5,"text_uthmani":"فَوَيْلٌۭ","transliteration":"fawaylun","translation_bn":"সুতরাং দুর্ভোগ","root":"—","lemma":"وَيْل","grammar_bn":"শব্দ"},{"id":38755,"position":6,"text_uthmani":"لِّلَّذِينَ","transliteration":"lilladhīna","translation_bn":"(তাদের) জন্যে যারা","root":"—","lemma":"ٱلَّذِى","grammar_bn":"অব্যয় (Preposition)"},{"id":38756,"position":7,"text_uthmani":"كَفَرُوا۟","transliteration":"kafarū","translation_bn":"অস্বীকার করেছে","root":"كفر","lemma":"كَفَرَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":38757,"position":8,"text_uthmani":"مِن","transliteration":"min","translation_bn":"হ''তে","root":"—","lemma":"مِن\r","grammar_bn":"অব্যয় (Preposition)"},{"id":38758,"position":9,"text_uthmani":"مَّشْهَدِ","transliteration":"mashhadi","translation_bn":"সাক্ষাত","root":"شهد","lemma":"مَّشْهَد","grammar_bn":"বিশেষ্য (Noun)"},{"id":38759,"position":10,"text_uthmani":"يَوْمٍ","transliteration":"yawmin","translation_bn":"দিনের","root":"يوم","lemma":"يَوْم","grammar_bn":"বিশেষ্য (Noun)"},{"id":38760,"position":11,"text_uthmani":"عَظِيمٍ","transliteration":"ʿaẓīmin","translation_bn":"কঠিন","root":"عظم","lemma":"عَظِيم","grammar_bn":"বিশেষণ (Adjective)"},{"id":38761,"position":12,"text_uthmani":"٣٧","transliteration":"","translation_bn":"(৩৭)","root":"—","lemma":"٣٧","grammar_bn":"মার্কার"}]'::jsonb, 'fa-ikh''talafa l-aḥzābu min baynihim fawaylun lilladhīna kafarū min mashhadi yawmin ʿaẓīmin', 'অতঃপর দলগুলো তাদের মধ্যে মতভেদ করল। কাজেই সেই ভয়াবহ দিনের উপস্থিতকালে কাফিরদের জন্য ধ্বংস অনিবার্য।', 'Then the factions differed [concerning Jesus] from among them, so woe to those who disbelieved - from the scene of a tremendous Day.', 'অতঃপর দলগুলো তাদের মধ্যে মতভেদ করল। কাজেই সেই ভয়াবহ দিনের উপস্থিতকালে কাফিরদের জন্য ধ্বংস অনিবার্য।', 'Then the factions differed [concerning Jesus] from among them, so woe to those who disbelieved - from the scene of a tremendous Day.', NULL, NULL, NULL, NULL, NULL, 'https://everyayah.com/data/Alafasy_128kbps/019037.mp3', now()),
  (19, 38, '', '[{"id":39627,"position":1,"text_uthmani":"أَسْمِعْ","transliteration":"asmiʿ","translation_bn":"স্পষ্ট শুনবে","root":"سمع","lemma":"أَسْمَعَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":39628,"position":2,"text_uthmani":"بِهِمْ","transliteration":"bihim","translation_bn":"তারা কত","root":"—","lemma":"بِهِمْ","grammar_bn":"অব্যয় (Preposition)"},{"id":39629,"position":3,"text_uthmani":"وَأَبْصِرْ","transliteration":"wa-abṣir","translation_bn":"ও (কত স্পষ্ট) দেখবে","root":"بصر","lemma":"أَبْصَرَ","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":39630,"position":4,"text_uthmani":"يَوْمَ","transliteration":"yawma","translation_bn":"যেদিন","root":"يوم","lemma":"يَوْم","grammar_bn":"কালবাচক (Time)"},{"id":39631,"position":5,"text_uthmani":"يَأْتُونَنَا ۖ","transliteration":"yatūnanā","translation_bn":"আমাদের কাছে তারা আসবে","root":"اتي","lemma":"أَتَى","grammar_bn":"ক্রিয়া (Verb)"},{"id":39633,"position":6,"text_uthmani":"لَـٰكِنِ","transliteration":"lākini","translation_bn":"কিন্তু","root":"—","lemma":"لَٰكِن\r","grammar_bn":"সংশোধন পদ (Amendment)"},{"id":39634,"position":7,"text_uthmani":"ٱلظَّـٰلِمُونَ","transliteration":"l-ẓālimūna","translation_bn":"সীমালঙ্ঘনকারীরা","root":"ظلم","lemma":"ظَالِم","grammar_bn":"শব্দ"},{"id":39635,"position":8,"text_uthmani":"ٱلْيَوْمَ","transliteration":"l-yawma","translation_bn":"আজ","root":"يوم","lemma":"يَوْم","grammar_bn":"শব্দ"},{"id":39636,"position":9,"text_uthmani":"فِى","transliteration":"fī","translation_bn":"মধ্যে (রয়েছে)","root":"—","lemma":"فِى\r","grammar_bn":"অব্যয় (Preposition)"},{"id":39637,"position":10,"text_uthmani":"ضَلَـٰلٍۢ","transliteration":"ḍalālin","translation_bn":"বিভ্রান্তির","root":"ضلل","lemma":"ضَلَٰل","grammar_bn":"বিশেষ্য (Noun)"},{"id":39638,"position":11,"text_uthmani":"مُّبِينٍۢ","transliteration":"mubīnin","translation_bn":"সুস্পষ্ট","root":"بين","lemma":"مُّبِين","grammar_bn":"বিশেষণ (Adjective)"},{"id":39639,"position":12,"text_uthmani":"٣٨","transliteration":"","translation_bn":"(৩৮)","root":"—","lemma":"٣٨","grammar_bn":"মার্কার"}]'::jsonb, 'asmiʿ bihim wa-abṣir yawma yatūnanā lākini l-ẓālimūna l-yawma fī ḍalālin mubīnin', 'যেদিন তারা আমার কাছে আসবে সেদিন কতই না স্পষ্টভাবে তারা শুনতে পাবে আর দেখতে পাবে। কিন্তু যালিমরা আজ স্পষ্ট গুমরাহীর মধ্যে পড়ে আছে।', 'How [clearly] they will hear and see the Day they come to Us, but the wrongdoers today are in clear error.', 'যেদিন তারা আমার কাছে আসবে সেদিন কতই না স্পষ্টভাবে তারা শুনতে পাবে আর দেখতে পাবে। কিন্তু যালিমরা আজ স্পষ্ট গুমরাহীর মধ্যে পড়ে আছে।', 'How [clearly] they will hear and see the Day they come to Us, but the wrongdoers today are in clear error.', NULL, NULL, NULL, NULL, NULL, 'https://everyayah.com/data/Alafasy_128kbps/019038.mp3', now()),
  (19, 39, '', '[{"id":40451,"position":1,"text_uthmani":"وَأَنذِرْهُمْ","transliteration":"wa-andhir''hum","translation_bn":"এবং সতর্ক করো তাদেরকে","root":"نذر","lemma":"أَنذَرَ","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":40452,"position":2,"text_uthmani":"يَوْمَ","transliteration":"yawma","translation_bn":"দিন (সম্পর্কে)","root":"يوم","lemma":"يَوْم","grammar_bn":"কালবাচক (Time)"},{"id":40453,"position":3,"text_uthmani":"ٱلْحَسْرَةِ","transliteration":"l-ḥasrati","translation_bn":"পরিতাপের","root":"حسر","lemma":"حَسْرَة","grammar_bn":"শব্দ"},{"id":40454,"position":4,"text_uthmani":"إِذْ","transliteration":"idh","translation_bn":"যখন","root":"—","lemma":"إِذ\r","grammar_bn":"কালবাচক (Time)"},{"id":40455,"position":5,"text_uthmani":"قُضِىَ","transliteration":"quḍiya","translation_bn":"সিদ্ধান্ত হয়ে যাবে","root":"قضي","lemma":"قَضَىٰ^","grammar_bn":"ক্রিয়া (Verb)"},{"id":40456,"position":6,"text_uthmani":"ٱلْأَمْرُ","transliteration":"l-amru","translation_bn":"বিষয়টির","root":"امر","lemma":"أَمْر","grammar_bn":"শব্দ"},{"id":40457,"position":7,"text_uthmani":"وَهُمْ","transliteration":"wahum","translation_bn":"তারা এ অবস্থায় যখন","root":"—","lemma":"وَهُمْ","grammar_bn":"অবস্থাবাচক (Circumstantial)"},{"id":40458,"position":8,"text_uthmani":"فِى","transliteration":"fī","translation_bn":"মধ্যে (আছে)","root":"—","lemma":"فِى\r","grammar_bn":"অব্যয় (Preposition)"},{"id":40459,"position":9,"text_uthmani":"غَفْلَةٍۢ","transliteration":"ghaflatin","translation_bn":"উদাসীনতা","root":"غفل","lemma":"غَفْلَة","grammar_bn":"বিশেষ্য (Noun)"},{"id":40460,"position":10,"text_uthmani":"وَهُمْ","transliteration":"wahum","translation_bn":"এবং তারা","root":"—","lemma":"وَهُمْ","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":40461,"position":11,"text_uthmani":"لَا","transliteration":"lā","translation_bn":"না","root":"—","lemma":"لَا\r","grammar_bn":"না-বোধক (Negative)"},{"id":40462,"position":12,"text_uthmani":"يُؤْمِنُونَ","transliteration":"yu''minūna","translation_bn":"ঈমান আনছে","root":"امن","lemma":"ءَامَنَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":40463,"position":13,"text_uthmani":"٣٩","transliteration":"","translation_bn":"(৩৯)","root":"—","lemma":"٣٩","grammar_bn":"মার্কার"}]'::jsonb, 'wa-andhir''hum yawma l-ḥasrati idh quḍiya l-amru wahum fī ghaflatin wahum lā yu''minūna', 'বিপদের দিন সম্পর্কে তাদেরকে সতর্ক করে দাও যখন ব্যাপার চূড়ান্ত করা হবে আর (দেখ) এ সম্পর্কে তারা উদাসীন আর তারা ঈমান আনে না।', 'And warn them, [O Muhammad], of the Day of Regret, when the matter will be concluded; and [yet], they are in [a state of] heedlessness, and they do not believe.', 'বিপদের দিন সম্পর্কে তাদেরকে সতর্ক করে দাও যখন ব্যাপার চূড়ান্ত করা হবে আর (দেখ) এ সম্পর্কে তারা উদাসীন আর তারা ঈমান আনে না।', 'And warn them, [O Muhammad], of the Day of Regret, when the matter will be concluded; and [yet], they are in [a state of] heedlessness, and they do not believe.', NULL, NULL, NULL, NULL, NULL, 'https://everyayah.com/data/Alafasy_128kbps/019039.mp3', now()),
  (19, 40, '', '[{"id":41143,"position":1,"text_uthmani":"إِنَّا","transliteration":"innā","translation_bn":"নিশ্চয়ই আমরা","root":"—","lemma":"إِنّ","grammar_bn":"অভিঘাত পদ (Accusative)"},{"id":41144,"position":2,"text_uthmani":"نَحْنُ","transliteration":"naḥnu","translation_bn":"আমরা","root":"—","lemma":"نَحْنُ","grammar_bn":"সর্বনাম (Pronoun)"},{"id":41145,"position":3,"text_uthmani":"نَرِثُ","transliteration":"narithu","translation_bn":"উত্তরাধিকারী হবো","root":"ورث","lemma":"وَرِثَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":41146,"position":4,"text_uthmani":"ٱلْأَرْضَ","transliteration":"l-arḍa","translation_bn":"পৃথিবীর","root":"ارض","lemma":"أَرْض","grammar_bn":"শব্দ"},{"id":41147,"position":5,"text_uthmani":"وَمَنْ","transliteration":"waman","translation_bn":"এবং যা কিছু","root":"—","lemma":"مَن\r","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":41148,"position":6,"text_uthmani":"عَلَيْهَا","transliteration":"ʿalayhā","translation_bn":"তার উপর (আছে)","root":"—","lemma":"عَلَىٰ\r","grammar_bn":"অব্যয় (Preposition)"},{"id":41149,"position":7,"text_uthmani":"وَإِلَيْنَا","transliteration":"wa-ilaynā","translation_bn":"এবং আমাদেরই দিকে","root":"—","lemma":"إِلَىٰ\r","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":41150,"position":8,"text_uthmani":"يُرْجَعُونَ","transliteration":"yur''jaʿūna","translation_bn":"তাদের ফিরিয়ে আনা হবে","root":"رجع","lemma":"رَجَعَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":41151,"position":9,"text_uthmani":"٤٠","transliteration":"","translation_bn":"(৪০)","root":"—","lemma":"٤٠","grammar_bn":"মার্কার"}]'::jsonb, 'innā naḥnu narithu l-arḍa waman ʿalayhā wa-ilaynā yur''jaʿūna', 'যমীন আর যমীনের উপর যারা আছে তাদের মালিকানা আমারই থাকবে, আর তারা আমার কাছেই ফিরে আসবে।', 'Indeed, it is We who will inherit the earth and whoever is on it, and to Us they will be returned.', 'যমীন আর যমীনের উপর যারা আছে তাদের মালিকানা আমারই থাকবে, আর তারা আমার কাছেই ফিরে আসবে।', 'Indeed, it is We who will inherit the earth and whoever is on it, and to Us they will be returned.', NULL, NULL, NULL, NULL, NULL, 'https://everyayah.com/data/Alafasy_128kbps/019040.mp3', now()),
  (19, 41, '', '[{"id":42036,"position":1,"text_uthmani":"وَٱذْكُرْ","transliteration":"wa-udh''kur","translation_bn":"এবং বর্ণনা করো (যা)","root":"ذكر","lemma":"ذَكَرَ","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":42037,"position":2,"text_uthmani":"فِى","transliteration":"fī","translation_bn":"মধ্যে (বলা হচ্ছে)","root":"—","lemma":"فِى\r","grammar_bn":"অব্যয় (Preposition)"},{"id":42038,"position":3,"text_uthmani":"ٱلْكِتَـٰبِ","transliteration":"l-kitābi","translation_bn":"(এই) কিতাবের","root":"كتب","lemma":"كِتَٰب","grammar_bn":"শব্দ"},{"id":42039,"position":4,"text_uthmani":"إِبْرَٰهِيمَ ۚ","transliteration":"ib''rāhīma","translation_bn":"ইবরাহীম (সম্পর্কে)","root":"—","lemma":"إِبْرَاهِيم","grammar_bn":"নামবাচক বিশেষ্য (Proper Noun)"},{"id":42041,"position":5,"text_uthmani":"إِنَّهُۥ","transliteration":"innahu","translation_bn":"সে নিশ্চয়ই","root":"—","lemma":"إِنّ","grammar_bn":"অভিঘাত পদ (Accusative)"},{"id":42042,"position":6,"text_uthmani":"كَانَ","transliteration":"kāna","translation_bn":"ছিলো","root":"كون","lemma":"كَانَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":42043,"position":7,"text_uthmani":"صِدِّيقًۭا","transliteration":"ṣiddīqan","translation_bn":"সত্যনিষ্ঠ","root":"صدق","lemma":"صِدِّيق","grammar_bn":"বিশেষ্য (Noun)"},{"id":42044,"position":8,"text_uthmani":"نَّبِيًّا","transliteration":"nabiyyan","translation_bn":"নাবী","root":"نبا","lemma":"نَّبِىّ","grammar_bn":"বিশেষ্য (Noun)"},{"id":42045,"position":9,"text_uthmani":"٤١","transliteration":"","translation_bn":"(৪১)","root":"—","lemma":"٤١","grammar_bn":"মার্কার"}]'::jsonb, 'wa-udh''kur fī l-kitābi ib''rāhīma innahu kāna ṣiddīqan nabiyyan', 'এ কিতাবে উল্লেখিত ইবরাহীমের কথা স্মরণ কর, সে ছিল একজন সত্যনিষ্ঠ মানুষ, একজন নবী।', 'And mention in the Book [the story of] Abraham. Indeed, he was a man of truth and a prophet.', 'এ কিতাবে উল্লেখিত ইবরাহীমের কথা স্মরণ কর, সে ছিল একজন সত্যনিষ্ঠ মানুষ, একজন নবী।', 'And mention in the Book [the story of] Abraham. Indeed, he was a man of truth and a prophet.', NULL, NULL, NULL, NULL, NULL, 'https://everyayah.com/data/Alafasy_128kbps/019041.mp3', now()),
  (19, 42, '', '[{"id":42844,"position":1,"text_uthmani":"إِذْ","transliteration":"idh","translation_bn":"যখন","root":"—","lemma":"إِذ\r","grammar_bn":"কালবাচক (Time)"},{"id":42845,"position":2,"text_uthmani":"قَالَ","transliteration":"qāla","translation_bn":"সে বলেছিলো","root":"قول","lemma":"قَالَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":42846,"position":3,"text_uthmani":"لِأَبِيهِ","transliteration":"li-abīhi","translation_bn":"তার বাপকে","root":"ابو","lemma":"أَبٌ","grammar_bn":"অব্যয় (Preposition)"},{"id":42847,"position":4,"text_uthmani":"يَـٰٓأَبَتِ","transliteration":"yāabati","translation_bn":"\"হে আমার পিতা","root":"ابو","lemma":"أَبٌ","grammar_bn":"সম্বোধন পদ (Vocative)"},{"id":42848,"position":5,"text_uthmani":"لِمَ","transliteration":"lima","translation_bn":"কেন","root":"—","lemma":"مَا\r","grammar_bn":"অব্যয় (Preposition)"},{"id":42849,"position":6,"text_uthmani":"تَعْبُدُ","transliteration":"taʿbudu","translation_bn":"উপাসনা করেন আপনি","root":"عبد","lemma":"عَبَدَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":42850,"position":7,"text_uthmani":"مَا","transliteration":"mā","translation_bn":"যা","root":"—","lemma":"مَا\r","grammar_bn":"সাপেক্ষ সর্বনাম (Relative)"},{"id":42851,"position":8,"text_uthmani":"لَا","transliteration":"lā","translation_bn":"না","root":"—","lemma":"لَا\r","grammar_bn":"না-বোধক (Negative)"},{"id":42852,"position":9,"text_uthmani":"يَسْمَعُ","transliteration":"yasmaʿu","translation_bn":"শুনে","root":"سمع","lemma":"سَمِعَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":42853,"position":10,"text_uthmani":"وَلَا","transliteration":"walā","translation_bn":"আর না","root":"—","lemma":"لَا\r","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":42854,"position":11,"text_uthmani":"يُبْصِرُ","transliteration":"yub''ṣiru","translation_bn":"দেখে","root":"بصر","lemma":"أَبْصَرَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":42855,"position":12,"text_uthmani":"وَلَا","transliteration":"walā","translation_bn":"এবং না","root":"—","lemma":"لَا\r","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":42856,"position":13,"text_uthmani":"يُغْنِى","transliteration":"yugh''nī","translation_bn":"কাজে আসে","root":"غني","lemma":"أَغْنَتْ","grammar_bn":"ক্রিয়া (Verb)"},{"id":42857,"position":14,"text_uthmani":"عَنكَ","transliteration":"ʿanka","translation_bn":"আপনার জন্য","root":"—","lemma":"عَن\r","grammar_bn":"অব্যয় (Preposition)"},{"id":42858,"position":15,"text_uthmani":"شَيْـًۭٔا","transliteration":"shayan","translation_bn":"কিছুই","root":"شيا","lemma":"شَىْء","grammar_bn":"বিশেষ্য (Noun)"},{"id":42859,"position":16,"text_uthmani":"٤٢","transliteration":"","translation_bn":"(৪২)","root":"—","lemma":"٤٢","grammar_bn":"মার্কার"}]'::jsonb, 'idh qāla li-abīhi yāabati lima taʿbudu mā lā yasmaʿu walā yub''ṣiru walā yugh''nī ʿanka shayan', 'যখন সে তার পিতাকে বলেছিল, ‘হে আমার পিতা! আপনি কেন এমন জিনিসের ‘ইবাদাত করেন যা শুনে না, দেখে না, আর আপনার কোন কাজেই আসে না?', '[Mention] when he said to his father, "O my father, why do you worship that which does not hear and does not see and will not benefit you at all?', 'যখন সে তার পিতাকে বলেছিল, ‘হে আমার পিতা! আপনি কেন এমন জিনিসের ‘ইবাদাত করেন যা শুনে না, দেখে না, আর আপনার কোন কাজেই আসে না?', '[Mention] when he said to his father, "O my father, why do you worship that which does not hear and does not see and will not benefit you at all?', NULL, NULL, NULL, NULL, NULL, 'https://everyayah.com/data/Alafasy_128kbps/019042.mp3', now()),
  (19, 43, '', '[{"id":43579,"position":1,"text_uthmani":"يَـٰٓأَبَتِ","transliteration":"yāabati","translation_bn":"হে আমার পিতা","root":"ابو","lemma":"أَبٌ","grammar_bn":"সম্বোধন পদ (Vocative)"},{"id":43580,"position":2,"text_uthmani":"إِنِّى","transliteration":"innī","translation_bn":"নিশ্চয়ই আমার","root":"—","lemma":"إِنّ","grammar_bn":"অভিঘাত পদ (Accusative)"},{"id":43581,"position":3,"text_uthmani":"قَدْ","transliteration":"qad","translation_bn":"নিশ্চয়ই","root":"—","lemma":"قَد\r","grammar_bn":"নিশ্চয়তাবোধক (Certainty)"},{"id":43582,"position":4,"text_uthmani":"جَآءَنِى","transliteration":"jāanī","translation_bn":"এসেছে আমার কাছে","root":"جيا","lemma":"جَا^ءَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":43583,"position":5,"text_uthmani":"مِنَ","transliteration":"mina","translation_bn":"(এমন) কিছু","root":"—","lemma":"مِن\r","grammar_bn":"অব্যয় (Preposition)"},{"id":43584,"position":6,"text_uthmani":"ٱلْعِلْمِ","transliteration":"l-ʿil''mi","translation_bn":"জ্ঞান","root":"علم","lemma":"عِلْم","grammar_bn":"শব্দ"},{"id":43585,"position":7,"text_uthmani":"مَا","transliteration":"mā","translation_bn":"যা","root":"—","lemma":"مَا\r","grammar_bn":"সাপেক্ষ সর্বনাম (Relative)"},{"id":43586,"position":8,"text_uthmani":"لَمْ","transliteration":"lam","translation_bn":"নি","root":"—","lemma":"لَم\r","grammar_bn":"না-বোধক (Negative)"},{"id":43587,"position":9,"text_uthmani":"يَأْتِكَ","transliteration":"yatika","translation_bn":"আপনার কাছে আসে","root":"اتي","lemma":"أَتَى","grammar_bn":"ক্রিয়া (Verb)"},{"id":43588,"position":10,"text_uthmani":"فَٱتَّبِعْنِىٓ","transliteration":"fa-ittabiʿ''nī","translation_bn":"সুতরাং অনুসরণ করুন","root":"تبع","lemma":"ٱتَّبَعَ","grammar_bn":"শব্দ"},{"id":43589,"position":11,"text_uthmani":"أَهْدِكَ","transliteration":"ahdika","translation_bn":"আমি পথ দেখাবো","root":"هدي","lemma":"هَدَى","grammar_bn":"ক্রিয়া (Verb)"},{"id":43590,"position":12,"text_uthmani":"صِرَٰطًۭا","transliteration":"ṣirāṭan","translation_bn":"পথ","root":"صرط","lemma":"صِرَٰط","grammar_bn":"বিশেষ্য (Noun)"},{"id":43591,"position":13,"text_uthmani":"سَوِيًّۭا","transliteration":"sawiyyan","translation_bn":"সরল সঠিক","root":"سوي","lemma":"سَوِيّ","grammar_bn":"বিশেষণ (Adjective)"},{"id":43592,"position":14,"text_uthmani":"٤٣","transliteration":"","translation_bn":"(৪৩)","root":"—","lemma":"٤٣","grammar_bn":"মার্কার"}]'::jsonb, 'yāabati innī qad jāanī mina l-ʿil''mi mā lam yatika fa-ittabiʿ''nī ahdika ṣirāṭan sawiyyan', 'হে আমার পিতা! আমার কাছে এমন জ্ঞান এসেছে যা আপনার কাছে আসেনি, কাজেই আমার অনুসরণ করুন, আমি আপনাকে সরল সঠিক পথ দেখাব।', 'O my father, indeed there has come to me of knowledge that which has not come to you, so follow me; I will guide you to an even path.', 'হে আমার পিতা! আমার কাছে এমন জ্ঞান এসেছে যা আপনার কাছে আসেনি, কাজেই আমার অনুসরণ করুন, আমি আপনাকে সরল সঠিক পথ দেখাব।', 'O my father, indeed there has come to me of knowledge that which has not come to you, so follow me; I will guide you to an even path.', NULL, NULL, NULL, NULL, NULL, 'https://everyayah.com/data/Alafasy_128kbps/019043.mp3', now()),
  (19, 44, '', '[{"id":44313,"position":1,"text_uthmani":"يَـٰٓأَبَتِ","transliteration":"yāabati","translation_bn":"হে আমার পিতা","root":"ابو","lemma":"أَبٌ","grammar_bn":"সম্বোধন পদ (Vocative)"},{"id":44314,"position":2,"text_uthmani":"لَا","transliteration":"lā","translation_bn":"না","root":"—","lemma":"لَا\r","grammar_bn":"নিষেধবাচক (Prohibition)"},{"id":44315,"position":3,"text_uthmani":"تَعْبُدِ","transliteration":"taʿbudi","translation_bn":"উপাসনা করবেন","root":"عبد","lemma":"عَبَدَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":44316,"position":4,"text_uthmani":"ٱلشَّيْطَـٰنَ ۖ","transliteration":"l-shayṭāna","translation_bn":"শয়তানের","root":"شطن","lemma":"شَيْطَٰن","grammar_bn":"শব্দ"},{"id":44318,"position":5,"text_uthmani":"إِنَّ","transliteration":"inna","translation_bn":"নিশ্চয়ই","root":"—","lemma":"إِنّ","grammar_bn":"অভিঘাত পদ (Accusative)"},{"id":44319,"position":6,"text_uthmani":"ٱلشَّيْطَـٰنَ","transliteration":"l-shayṭāna","translation_bn":"শয়তান","root":"شطن","lemma":"شَيْطَٰن","grammar_bn":"শব্দ"},{"id":44320,"position":7,"text_uthmani":"كَانَ","transliteration":"kāna","translation_bn":"হলো","root":"كون","lemma":"كَانَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":44321,"position":8,"text_uthmani":"لِلرَّحْمَـٰنِ","transliteration":"lilrraḥmāni","translation_bn":"দয়াময়ের","root":"رحم","lemma":"رَّحْمَٰن","grammar_bn":"অব্যয় (Preposition)"},{"id":44322,"position":9,"text_uthmani":"عَصِيًّۭا","transliteration":"ʿaṣiyyan","translation_bn":"অবাধ্য","root":"عصي","lemma":"عَصِيّ","grammar_bn":"বিশেষ্য (Noun)"},{"id":44323,"position":10,"text_uthmani":"٤٤","transliteration":"","translation_bn":"(৪৪)","root":"—","lemma":"٤٤","grammar_bn":"মার্কার"}]'::jsonb, 'yāabati lā taʿbudi l-shayṭāna inna l-shayṭāna kāna lilrraḥmāni ʿaṣiyyan', 'হে আমার পিতা! আপনি শয়তানের ‘ইবাদাত করবেন না, শয়তান হচ্ছে দয়াময়ের বিরুদ্ধে বিদ্রোহী।', 'O my father, do not worship Satan. Indeed Satan has ever been, to the Most Merciful, disobedient.', 'হে আমার পিতা! আপনি শয়তানের ‘ইবাদাত করবেন না, শয়তান হচ্ছে দয়াময়ের বিরুদ্ধে বিদ্রোহী।', 'O my father, do not worship Satan. Indeed Satan has ever been, to the Most Merciful, disobedient.', NULL, NULL, NULL, NULL, NULL, 'https://everyayah.com/data/Alafasy_128kbps/019044.mp3', now()),
  (19, 45, '', '[{"id":45077,"position":1,"text_uthmani":"يَـٰٓأَبَتِ","transliteration":"yāabati","translation_bn":"হে আমার পিতা","root":"ابو","lemma":"أَبٌ","grammar_bn":"সম্বোধন পদ (Vocative)"},{"id":45078,"position":2,"text_uthmani":"إِنِّىٓ","transliteration":"innī","translation_bn":"নিশ্চয়ই আমি","root":"—","lemma":"إِنّ","grammar_bn":"অভিঘাত পদ (Accusative)"},{"id":45079,"position":3,"text_uthmani":"أَخَافُ","transliteration":"akhāfu","translation_bn":"ভয় করি আমি","root":"خوف","lemma":"خَافَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":45080,"position":4,"text_uthmani":"أَن","transliteration":"an","translation_bn":"যে","root":"—","lemma":"أَن\r","grammar_bn":"অধীনস্থ যোজক (Subordinating)"},{"id":45081,"position":5,"text_uthmani":"يَمَسَّكَ","transliteration":"yamassaka","translation_bn":"আপনাকে স্পর্শ করবে","root":"مسس","lemma":"مَسَّ","grammar_bn":"ক্রিয়া (Verb)"},{"id":45082,"position":6,"text_uthmani":"عَذَابٌۭ","transliteration":"ʿadhābun","translation_bn":"শাস্তি","root":"عذب","lemma":"عَذَاب","grammar_bn":"বিশেষ্য (Noun)"},{"id":45083,"position":7,"text_uthmani":"مِّنَ","transliteration":"mina","translation_bn":"থেকে","root":"—","lemma":"مِن\r","grammar_bn":"অব্যয় (Preposition)"},{"id":45084,"position":8,"text_uthmani":"ٱلرَّحْمَـٰنِ","transliteration":"l-raḥmāni","translation_bn":"দয়াময়ের","root":"رحم","lemma":"رَّحْمَٰن","grammar_bn":"শব্দ"},{"id":45085,"position":9,"text_uthmani":"فَتَكُونَ","transliteration":"fatakūna","translation_bn":"অতঃপর আপনি হবেন","root":"كون","lemma":"كَانَ","grammar_bn":"শব্দ"},{"id":45086,"position":10,"text_uthmani":"لِلشَّيْطَـٰنِ","transliteration":"lilshayṭāni","translation_bn":"শয়তানের জন্য","root":"شطن","lemma":"شَيْطَٰن","grammar_bn":"অব্যয় (Preposition)"},{"id":45087,"position":11,"text_uthmani":"وَلِيًّۭا","transliteration":"waliyyan","translation_bn":"বন্ধু\"","root":"ولي","lemma":"وَلِىّ","grammar_bn":"বিশেষ্য (Noun)"},{"id":45088,"position":12,"text_uthmani":"٤٥","transliteration":"","translation_bn":"(৪৫)","root":"—","lemma":"٤٥","grammar_bn":"মার্কার"}]'::jsonb, 'yāabati innī akhāfu an yamassaka ʿadhābun mina l-raḥmāni fatakūna lilshayṭāni waliyyan', 'হে আমার পিতা! আমার ভয় হয় যে, দয়াময়ের ‘আযাব আপনাকে ধরে বসবে, তখন আপনি শয়তানের বন্ধু হয়ে যাবেন।’', 'O my father, indeed I fear that there will touch you a punishment from the Most Merciful so you would be to Satan a companion [in Hellfire]."', 'হে আমার পিতা! আমার ভয় হয় যে, দয়াময়ের ‘আযাব আপনাকে ধরে বসবে, তখন আপনি শয়তানের বন্ধু হয়ে যাবেন।’', 'O my father, indeed I fear that there will touch you a punishment from the Most Merciful so you would be to Satan a companion [in Hellfire]."', NULL, NULL, NULL, NULL, NULL, 'https://everyayah.com/data/Alafasy_128kbps/019045.mp3', now()),
  (19, 46, '', '[{"id":45824,"position":1,"text_uthmani":"قَالَ","transliteration":"qāla","translation_bn":"সে বললো","root":"قول","lemma":"قَالَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":45825,"position":2,"text_uthmani":"أَرَاغِبٌ","transliteration":"arāghibun","translation_bn":"\"কি বিমুখ","root":"رغب","lemma":"رَاغِب","grammar_bn":"প্রশ্নবোধক (Interrogative)"},{"id":45826,"position":3,"text_uthmani":"أَنتَ","transliteration":"anta","translation_bn":"\"তুমি","root":"—","lemma":"أَنتَ","grammar_bn":"সর্বনাম (Pronoun)"},{"id":45827,"position":4,"text_uthmani":"عَنْ","transliteration":"ʿan","translation_bn":"হ''তে","root":"—","lemma":"عَن\r","grammar_bn":"অব্যয় (Preposition)"},{"id":45828,"position":5,"text_uthmani":"ءَالِهَتِى","transliteration":"ālihatī","translation_bn":"আমার দেব-দেবীগুলো","root":"اله","lemma":"إِلَٰه","grammar_bn":"বিশেষ্য (Noun)"},{"id":45829,"position":6,"text_uthmani":"يَـٰٓإِبْرَٰهِيمُ ۖ","transliteration":"yāib''rāhīmu","translation_bn":"হে ইবরাহীম","root":"—","lemma":"إِبْرَاهِيم","grammar_bn":"সম্বোধন পদ (Vocative)"},{"id":45831,"position":7,"text_uthmani":"لَئِن","transliteration":"la-in","translation_bn":"অবশ্যই যদি","root":"—","lemma":"إِن\r","grammar_bn":"দৃঢ়তাবোধক (Emphatic)"},{"id":45832,"position":8,"text_uthmani":"لَّمْ","transliteration":"lam","translation_bn":"না","root":"—","lemma":"لَم\r","grammar_bn":"না-বোধক (Negative)"},{"id":45833,"position":9,"text_uthmani":"تَنتَهِ","transliteration":"tantahi","translation_bn":"বিরত হও তুমি","root":"نهي","lemma":"ٱنتَهَىٰ","grammar_bn":"ক্রিয়া (Verb)"},{"id":45834,"position":10,"text_uthmani":"لَأَرْجُمَنَّكَ ۖ","transliteration":"la-arjumannaka","translation_bn":"অবশ্যই তোমাকে পাথর মেরে হত্যা করবোই","root":"رجم","lemma":"رَجَمْ","grammar_bn":"দৃঢ়তাবোধক (Emphatic)"},{"id":45836,"position":11,"text_uthmani":"وَٱهْجُرْنِى","transliteration":"wa-uh''jur''nī","translation_bn":"এবং আমাকে ছেড়ে চলে যাও","root":"هجر","lemma":"ٱهْجُرْ","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":45837,"position":12,"text_uthmani":"مَلِيًّۭا","transliteration":"maliyyan","translation_bn":"চিরতরে\"","root":"ملو","lemma":"مَلِيّ","grammar_bn":"বিশেষ্য (Noun)"},{"id":45838,"position":13,"text_uthmani":"٤٦","transliteration":"","translation_bn":"(৪৬)","root":"—","lemma":"٤٦","grammar_bn":"মার্কার"}]'::jsonb, 'qāla arāghibun anta ʿan ālihatī yāib''rāhīmu la-in lam tantahi la-arjumannaka wa-uh''jur''nī maliyyan', 'পিতা বলল, ‘হে ইবরাহীম! তুমি কি আমার দেবদেবীগুলো থেকে মুখ ফিরিয়ে নিচ্ছ? যদি তুমি বিরত না হও তবে আমি অবশ্যই তোমাকে পাথরের আঘাতে মেরে ফেলব। তুমি চিরতরে আমার কাছ থেকে দূর হয়ে যাও।’', '[His father] said, "Have you no desire for my gods, O Abraham? If you do not desist, I will surely stone you, so avoid me a prolonged time."', 'পিতা বলল, ‘হে ইবরাহীম! তুমি কি আমার দেবদেবীগুলো থেকে মুখ ফিরিয়ে নিচ্ছ? যদি তুমি বিরত না হও তবে আমি অবশ্যই তোমাকে পাথরের আঘাতে মেরে ফেলব। তুমি চিরতরে আমার কাছ থেকে দূর হয়ে যাও।’', '[His father] said, "Have you no desire for my gods, O Abraham? If you do not desist, I will surely stone you, so avoid me a prolonged time."', NULL, NULL, NULL, NULL, NULL, 'https://everyayah.com/data/Alafasy_128kbps/019046.mp3', now()),
