  (20, 2, '', '[{"id":1156,"position":1,"text_uthmani":"مَآ","transliteration":"mā","translation_bn":"না","root":"—","lemma":"مَا\r","grammar_bn":"না-বোধক (Negative)"},{"id":1157,"position":2,"text_uthmani":"أَنزَلْنَا","transliteration":"anzalnā","translation_bn":"আমরা অবতীর্ণ করেছি","root":"نزل","lemma":"أَنزَلَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":1158,"position":3,"text_uthmani":"عَلَيْكَ","transliteration":"ʿalayka","translation_bn":"তোমার উপর","root":"—","lemma":"عَلَىٰ\r","grammar_bn":"অব্যয় (Preposition)"},{"id":1159,"position":4,"text_uthmani":"ٱلْقُرْءَانَ","transliteration":"l-qur''āna","translation_bn":"(এই) কুরআন","root":"قرا","lemma":"قُرْءَان","grammar_bn":"শব্দ"},{"id":1160,"position":5,"text_uthmani":"لِتَشْقَىٰٓ","transliteration":"litashqā","translation_bn":"তোমাকে কষ্ট দেওয়ার জন্যে","root":"شقو","lemma":"شَقُ","grammar_bn":"শব্দ"},{"id":1161,"position":6,"text_uthmani":"٢","transliteration":"","translation_bn":"(২)","root":"—","lemma":"٢","grammar_bn":"মার্কার"}]'::jsonb, 'mā anzalnā ʿalayka l-qur''āna litashqā', 'তোমাকে ক্লেশ দেয়ার জন্য আমি তোমার প্রতি কুরআন নাযিল করিনি।', 'We have not sent down to you the Qur''an that you be distressed', 'তোমাকে ক্লেশ দেয়ার জন্য আমি তোমার প্রতি কুরআন নাযিল করিনি।', 'We have not sent down to you the Qur''an that you be distressed', NULL, NULL, NULL, NULL, NULL, 'https://everyayah.com/data/Alafasy_128kbps/020002.mp3', now()),
  (20, 3, '', '[{"id":2203,"position":1,"text_uthmani":"إِلَّا","transliteration":"illā","translation_bn":"কিন্তু","root":"—","lemma":"إِلَّا\r","grammar_bn":"সীমাবদ্ধতা (Restriction)"},{"id":2204,"position":2,"text_uthmani":"تَذْكِرَةًۭ","transliteration":"tadhkiratan","translation_bn":"উপদেশ","root":"ذكر","lemma":"تَذْكِرَة","grammar_bn":"বিশেষ্য (Noun)"},{"id":2205,"position":3,"text_uthmani":"لِّمَن","transliteration":"liman","translation_bn":"( তার ) জন্যে যে","root":"—","lemma":"مَن\r","grammar_bn":"অব্যয় (Preposition)"},{"id":2206,"position":4,"text_uthmani":"يَخْشَىٰ","transliteration":"yakhshā","translation_bn":"ভয় করে","root":"خشي","lemma":"خَشِىَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":2207,"position":5,"text_uthmani":"٣","transliteration":"","translation_bn":"(৩)","root":"—","lemma":"٣","grammar_bn":"মার্কার"}]'::jsonb, 'illā tadhkiratan liman yakhshā', 'বরং তা (নাযিল করেছি) কেবল সতর্কবাণী হিসেবে যে (আল্লাহকে) ভয় করে তার জন্য।', 'But only as a reminder for those who fear [Allah] -', 'বরং তা (নাযিল করেছি) কেবল সতর্কবাণী হিসেবে যে (আল্লাহকে) ভয় করে তার জন্য।', 'But only as a reminder for those who fear [Allah] -', NULL, NULL, NULL, NULL, NULL, 'https://everyayah.com/data/Alafasy_128kbps/020003.mp3', now()),
  (20, 4, '', '[{"id":3531,"position":1,"text_uthmani":"تَنزِيلًۭا","transliteration":"tanzīlan","translation_bn":"অবতীর্ণ করা ( হয়েছে )","root":"نزل","lemma":"تَنزِيل","grammar_bn":"বিশেষ্য (Noun)"},{"id":3532,"position":2,"text_uthmani":"مِّمَّنْ","transliteration":"mimman","translation_bn":"তাঁর পক্ষ হ''তে","root":"—","lemma":"مِن\r","grammar_bn":"অব্যয় (Preposition)"},{"id":3533,"position":3,"text_uthmani":"خَلَقَ","transliteration":"khalaqa","translation_bn":"( যিনি ) সৃষ্টি করেছেন","root":"خلق","lemma":"خَلَقَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":3534,"position":4,"text_uthmani":"ٱلْأَرْضَ","transliteration":"l-arḍa","translation_bn":"পৃথিবীকে","root":"ارض","lemma":"أَرْض","grammar_bn":"শব্দ"},{"id":3535,"position":5,"text_uthmani":"وَٱلسَّمَـٰوَٰتِ","transliteration":"wal-samāwāti","translation_bn":"ও আকাশমণ্ডলীকে","root":"سمو","lemma":"سَمَا^ء","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":3536,"position":6,"text_uthmani":"ٱلْعُلَى","transliteration":"l-ʿulā","translation_bn":"( যা ) সমুচ্চ","root":"علو","lemma":"عُلْيَا","grammar_bn":"শব্দ"},{"id":3537,"position":7,"text_uthmani":"٤","transliteration":"","translation_bn":"(৪)","root":"—","lemma":"٤","grammar_bn":"মার্কার"}]'::jsonb, 'tanzīlan mimman khalaqa l-arḍa wal-samāwāti l-ʿulā', 'যিনি পৃথিবী ও সুউচ্চ আকাশ সৃষ্টি করেছেন তাঁর নিকট হতে তা নাযিল হয়েছে।', 'A revelation from He who created the earth and highest heavens,', 'যিনি পৃথিবী ও সুউচ্চ আকাশ সৃষ্টি করেছেন তাঁর নিকট হতে তা নাযিল হয়েছে।', 'A revelation from He who created the earth and highest heavens,', NULL, NULL, NULL, NULL, NULL, 'https://everyayah.com/data/Alafasy_128kbps/020004.mp3', now()),
  (20, 5, '', '[{"id":4875,"position":1,"text_uthmani":"ٱلرَّحْمَـٰنُ","transliteration":"al-raḥmānu","translation_bn":"( তিনিই ) দয়াময়","root":"رحم","lemma":"رَّحْمَٰن","grammar_bn":"শব্দ"},{"id":4876,"position":2,"text_uthmani":"عَلَى","transliteration":"ʿalā","translation_bn":"যিনি উপর","root":"—","lemma":"عَلَىٰ\r","grammar_bn":"অব্যয় (Preposition)"},{"id":4877,"position":3,"text_uthmani":"ٱلْعَرْشِ","transliteration":"l-ʿarshi","translation_bn":"আরশের","root":"عرش","lemma":"عَرْش","grammar_bn":"শব্দ"},{"id":4878,"position":4,"text_uthmani":"ٱسْتَوَىٰ","transliteration":"is''tawā","translation_bn":"সমাসীন হয়েছেন","root":"سوي","lemma":"ٱسْتَوَىٰ^","grammar_bn":"ক্রিয়া (Verb)"},{"id":4879,"position":5,"text_uthmani":"٥","transliteration":"","translation_bn":"(৫)","root":"—","lemma":"٥","grammar_bn":"মার্কার"}]'::jsonb, 'al-raḥmānu ʿalā l-ʿarshi is''tawā', '‘আরশে দয়াময় সমুন্নত আছেন।', 'The Most Merciful [who is] above the Throne established.', '‘আরশে দয়াময় সমুন্নত আছেন।', 'The Most Merciful [who is] above the Throne established.', NULL, NULL, NULL, NULL, NULL, 'https://everyayah.com/data/Alafasy_128kbps/020005.mp3', now()),
