  (20, 35, '', '[{"id":37163,"position":1,"text_uthmani":"إِنَّكَ","transliteration":"innaka","translation_bn":"নিশ্চয়ই তুমি","root":"—","lemma":"إِنّ","grammar_bn":"অভিঘাত পদ (Accusative)"},{"id":37164,"position":2,"text_uthmani":"كُنتَ","transliteration":"kunta","translation_bn":"আছো","root":"كون","lemma":"كَانَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":37165,"position":3,"text_uthmani":"بِنَا","transliteration":"binā","translation_bn":"আমাদের উপর","root":"—","lemma":"بِنَا","grammar_bn":"অব্যয় (Preposition)"},{"id":37166,"position":4,"text_uthmani":"بَصِيرًۭا","transliteration":"baṣīran","translation_bn":"দৃষ্টিবান\"","root":"بصر","lemma":"بَصِير","grammar_bn":"বিশেষ্য (Noun)"},{"id":37167,"position":5,"text_uthmani":"٣٥","transliteration":"","translation_bn":"(৩৫)","root":"—","lemma":"٣٥","grammar_bn":"মার্কার"}]'::jsonb, 'innaka kunta binā baṣīran', 'তুমি তো আমাদের অবস্থা সবই দেখছ।’', 'Indeed, You are of us ever Seeing."', 'তুমি তো আমাদের অবস্থা সবই দেখছ।’', 'Indeed, You are of us ever Seeing."', NULL, NULL, NULL, NULL, NULL, 'https://everyayah.com/data/Alafasy_128kbps/020035.mp3', now()),
  (20, 36, '', '[{"id":37966,"position":1,"text_uthmani":"قَالَ","transliteration":"qāla","translation_bn":"তিনি বললেন","root":"قول","lemma":"قَالَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":37967,"position":2,"text_uthmani":"قَدْ","transliteration":"qad","translation_bn":"\"নিশ্চয়ই","root":"—","lemma":"قَد\r","grammar_bn":"নিশ্চয়তাবোধক (Certainty)"},{"id":37968,"position":3,"text_uthmani":"أُوتِيتَ","transliteration":"ūtīta","translation_bn":"তোমাকে দেয়া হলো","root":"اتي","lemma":"ا^تَى","grammar_bn":"ক্রিয়া (Verb)"},{"id":37969,"position":4,"text_uthmani":"سُؤْلَكَ","transliteration":"su''laka","translation_bn":"তোমার চাওয়া","root":"سال","lemma":"سُؤْل","grammar_bn":"বিশেষ্য (Noun)"},{"id":37970,"position":5,"text_uthmani":"يَـٰمُوسَىٰ","transliteration":"yāmūsā","translation_bn":"হে মূসা","root":"—","lemma":"مُوسَىٰ","grammar_bn":"সম্বোধন পদ (Vocative)"},{"id":37971,"position":6,"text_uthmani":"٣٦","transliteration":"","translation_bn":"(৩৬)","root":"—","lemma":"٣٦","grammar_bn":"মার্কার"}]'::jsonb, 'qāla qad ūtīta su''laka yāmūsā', 'তিনি (আল্লাহ) বললেন, ‘হে মূসা! তোমার প্রার্থনা গৃহীত হল।', '[Allah] said, "You have been granted your request, O Moses.', 'তিনি (আল্লাহ) বললেন, ‘হে মূসা! তোমার প্রার্থনা গৃহীত হল।', '[Allah] said, "You have been granted your request, O Moses.', NULL, NULL, NULL, NULL, NULL, 'https://everyayah.com/data/Alafasy_128kbps/020036.mp3', now()),
