  (20, 38, '', '[{"id":39698,"position":1,"text_uthmani":"إِذْ","transliteration":"idh","translation_bn":"(স্মরণ করো) যখন","root":"—","lemma":"إِذ\r","grammar_bn":"কালবাচক (Time)"},{"id":39699,"position":2,"text_uthmani":"أَوْحَيْنَآ","transliteration":"awḥaynā","translation_bn":"আমরা ইঙ্গিত করেছিলাম","root":"وحي","lemma":"أَوْحَىٰ^","grammar_bn":"ক্রিয়া (Verb)"},{"id":39700,"position":3,"text_uthmani":"إِلَىٰٓ","transliteration":"ilā","translation_bn":"প্রতি","root":"—","lemma":"إِلَىٰ\r","grammar_bn":"অব্যয় (Preposition)"},{"id":39701,"position":4,"text_uthmani":"أُمِّكَ","transliteration":"ummika","translation_bn":"তোমার মার","root":"امم","lemma":"أُمّ","grammar_bn":"বিশেষ্য (Noun)"},{"id":39702,"position":5,"text_uthmani":"مَا","transliteration":"mā","translation_bn":"(এভাবে) যা","root":"—","lemma":"مَا\r","grammar_bn":"সাপেক্ষ সর্বনাম (Relative)"},{"id":39703,"position":6,"text_uthmani":"يُوحَىٰٓ","transliteration":"yūḥā","translation_bn":"ওহী করা হয়।","root":"وحي","lemma":"أَوْحَىٰ^","grammar_bn":"ক্রিয়া (Verb)"},{"id":39704,"position":7,"text_uthmani":"٣٨","transliteration":"","translation_bn":"(৩৮)","root":"—","lemma":"٣٨","grammar_bn":"মার্কার"}]'::jsonb, 'idh awḥaynā ilā ummika mā yūḥā', 'যখন আমি তোমার মায়ের প্রতি ইঙ্গিত করেছিলাম যা ওয়াহীযোগে জানানো হয়েছিল-', 'When We inspired to your mother what We inspired,', 'যখন আমি তোমার মায়ের প্রতি ইঙ্গিত করেছিলাম যা ওয়াহীযোগে জানানো হয়েছিল-', 'When We inspired to your mother what We inspired,', NULL, NULL, NULL, NULL, NULL, 'https://everyayah.com/data/Alafasy_128kbps/020038.mp3', now()),
  (20, 39, '', '[{"id":40494,"position":1,"text_uthmani":"أَنِ","transliteration":"ani","translation_bn":"\"যে","root":"—","lemma":"أَن\r","grammar_bn":"উদ্দেশ্যবাচক (Intention)"},{"id":40495,"position":2,"text_uthmani":"ٱقْذِفِيهِ","transliteration":"iq''dhifīhi","translation_bn":"তাকে নিক্ষেপ করো (অর্থাৎ রেখে দাও)","root":"قذف","lemma":"قَذَفَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":40496,"position":3,"text_uthmani":"فِى","transliteration":"fī","translation_bn":"মধ্যে","root":"—","lemma":"فِى\r","grammar_bn":"অব্যয় (Preposition)"},{"id":40497,"position":4,"text_uthmani":"ٱلتَّابُوتِ","transliteration":"l-tābūti","translation_bn":"সিন্দুকের","root":"—","lemma":"تَّابُوت","grammar_bn":"শব্দ"},{"id":40498,"position":5,"text_uthmani":"فَٱقْذِفِيهِ","transliteration":"fa-iq''dhifīhi","translation_bn":"অতঃপর তা নিক্ষেপ করো (অর্থাৎ ভাসিয়ে দাও)","root":"قذف","lemma":"قَذَفَ","grammar_bn":"শব্দ"},{"id":40499,"position":6,"text_uthmani":"فِى","transliteration":"fī","translation_bn":"মধ্যে","root":"—","lemma":"فِى\r","grammar_bn":"অব্যয় (Preposition)"},{"id":40500,"position":7,"text_uthmani":"ٱلْيَمِّ","transliteration":"l-yami","translation_bn":"নদীর","root":"يمم","lemma":"يَمّ","grammar_bn":"শব্দ"},{"id":40501,"position":8,"text_uthmani":"فَلْيُلْقِهِ","transliteration":"falyul''qihi","translation_bn":"অতঃপর তা ঠেলে দিবে","root":"لقي","lemma":"أَلْقَىٰ^","grammar_bn":"শব্দ"},{"id":40502,"position":9,"text_uthmani":"ٱلْيَمُّ","transliteration":"l-yamu","translation_bn":"নদী","root":"يمم","lemma":"يَمّ","grammar_bn":"শব্দ"},{"id":40503,"position":10,"text_uthmani":"بِٱلسَّاحِلِ","transliteration":"bil-sāḥili","translation_bn":"তীরের দিকে","root":"سحل","lemma":"سَّاحِل","grammar_bn":"অব্যয় (Preposition)"},{"id":40504,"position":11,"text_uthmani":"يَأْخُذْهُ","transliteration":"yakhudh''hu","translation_bn":"তা তুলে নিবে","root":"اخذ","lemma":"أَخَذَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":40505,"position":12,"text_uthmani":"عَدُوٌّۭ","transliteration":"ʿaduwwun","translation_bn":"শত্রু","root":"عدو","lemma":"عَدُوّ","grammar_bn":"বিশেষ্য (Noun)"},{"id":40506,"position":13,"text_uthmani":"لِّى","transliteration":"lī","translation_bn":"আমার","root":"—","lemma":"لِّى","grammar_bn":"অব্যয় (Preposition)"},{"id":40507,"position":14,"text_uthmani":"وَعَدُوٌّۭ","transliteration":"waʿaduwwun","translation_bn":"ও শত্রু","root":"عدو","lemma":"عَدُوّ","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":40508,"position":15,"text_uthmani":"لَّهُۥ ۚ","transliteration":"lahu","translation_bn":"তার\"","root":"—","lemma":"لَّهُۥ ۚ","grammar_bn":"অব্যয় (Preposition)"},{"id":40510,"position":16,"text_uthmani":"وَأَلْقَيْتُ","transliteration":"wa-alqaytu","translation_bn":"এবং আমি ঢেলে দিয়েছিলাম","root":"لقي","lemma":"أَلْقَىٰ^","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":40511,"position":17,"text_uthmani":"عَلَيْكَ","transliteration":"ʿalayka","translation_bn":"তোমার উপর","root":"—","lemma":"عَلَىٰ\r","grammar_bn":"অব্যয় (Preposition)"},{"id":40512,"position":18,"text_uthmani":"مَحَبَّةًۭ","transliteration":"maḥabbatan","translation_bn":"ভালবাসা","root":"حبب","lemma":"مَحَبَّة","grammar_bn":"বিশেষ্য (Noun)"},{"id":40513,"position":19,"text_uthmani":"مِّنِّى","transliteration":"minnī","translation_bn":"আমার পক্ষ হ''তে","root":"—","lemma":"مِن\r","grammar_bn":"অব্যয় (Preposition)"},{"id":40514,"position":20,"text_uthmani":"وَلِتُصْنَعَ","transliteration":"walituṣ''naʿa","translation_bn":"এবং তুমি লালিতপালিত হও যেন","root":"صنع","lemma":"صَنَعُ","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":40515,"position":21,"text_uthmani":"عَلَىٰ","transliteration":"ʿalā","translation_bn":"সামনে","root":"—","lemma":"عَلَىٰ\r","grammar_bn":"অব্যয় (Preposition)"},{"id":40516,"position":22,"text_uthmani":"عَيْنِىٓ","transliteration":"ʿaynī","translation_bn":"আমার চোখের","root":"عين","lemma":"عَيْن","grammar_bn":"বিশেষ্য (Noun)"},{"id":40517,"position":23,"text_uthmani":"٣٩","transliteration":"","translation_bn":"(৩৯)","root":"—","lemma":"٣٩","grammar_bn":"মার্কার"}]'::jsonb, 'ani iq''dhifīhi fī l-tābūti fa-iq''dhifīhi fī l-yami falyul''qihi l-yamu bil-sāḥili yakhudh''hu ʿaduwwun lī waʿaduwwun lahu wa-alqaytu ʿalayka maḥabbatan minnī walituṣ''naʿa ʿalā ʿaynī', 'যে তুমি মূসাকে সিন্দুকের মধ্যে রাখ। তারপর তা দরিয়ায় ভাসিয়ে দাও। অতঃপর দরিয়া তাকে পাড়ে ঠেলে দেবে। তাকে আমার শত্রু ও তার শত্রু উঠিয়ে নেবে। আমি আমার নিকট হতে তোমার প্রতি ভালবাসা ঢেলে দিয়েছিলাম, যাতে তুমি আমার দৃষ্টির সম্মুখে প্রতিপালিত হও।’', '[Saying], ''Cast him into the chest and cast it into the river, and the river will throw it onto the bank; there will take him an enemy to Me and an enemy to him.'' And I bestowed upon you love from Me that you would be brought up under My eye.', 'যে তুমি মূসাকে সিন্দুকের মধ্যে রাখ। তারপর তা দরিয়ায় ভাসিয়ে দাও। অতঃপর দরিয়া তাকে পাড়ে ঠেলে দেবে। তাকে আমার শত্রু ও তার শত্রু উঠিয়ে নেবে। আমি আমার নিকট হতে তোমার প্রতি ভালবাসা ঢেলে দিয়েছিলাম, যাতে তুমি আমার দৃষ্টির সম্মুখে প্রতিপালিত হও।’', '[Saying], ''Cast him into the chest and cast it into the river, and the river will throw it onto the bank; there will take him an enemy to Me and an enemy to him.'' And I bestowed upon you love from Me that you would be brought up under My eye.', NULL, NULL, NULL, NULL, NULL, 'https://everyayah.com/data/Alafasy_128kbps/020039.mp3', now()),
  (20, 40, '', '[{"id":41196,"position":1,"text_uthmani":"إِذْ","transliteration":"idh","translation_bn":"(স্মরণ করো) যখন","root":"—","lemma":"إِذ\r","grammar_bn":"কালবাচক (Time)"},{"id":41197,"position":2,"text_uthmani":"تَمْشِىٓ","transliteration":"tamshī","translation_bn":"চলেছিলো","root":"مشي","lemma":"مَّشَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":41198,"position":3,"text_uthmani":"أُخْتُكَ","transliteration":"ukh''tuka","translation_bn":"তোমার বোন","root":"اخو","lemma":"أُخْت","grammar_bn":"বিশেষ্য (Noun)"},{"id":41199,"position":4,"text_uthmani":"فَتَقُولُ","transliteration":"fataqūlu","translation_bn":"অতঃপর বলেছিলো","root":"قول","lemma":"قَالَ","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":41200,"position":5,"text_uthmani":"هَلْ","transliteration":"hal","translation_bn":"\"কি","root":"—","lemma":"هَل\r","grammar_bn":"প্রশ্নবোধক (Interrogative)"},{"id":41201,"position":6,"text_uthmani":"أَدُلُّكُمْ","transliteration":"adullukum","translation_bn":"তোমাদের খোঁজ দিবো","root":"دلل","lemma":"دَلَّ","grammar_bn":"ক্রিয়া (Verb)"},{"id":41202,"position":7,"text_uthmani":"عَلَىٰ","transliteration":"ʿalā","translation_bn":"এ বিষয়ে (যে)","root":"—","lemma":"عَلَىٰ\r","grammar_bn":"অব্যয় (Preposition)"},{"id":41203,"position":8,"text_uthmani":"مَن","transliteration":"man","translation_bn":"কে","root":"—","lemma":"مَن\r","grammar_bn":"সাপেক্ষ সর্বনাম (Relative)"},{"id":41204,"position":9,"text_uthmani":"يَكْفُلُهُۥ ۖ","transliteration":"yakfuluhu","translation_bn":"তাকে লালন-পালন করতে পারে\"","root":"كفل","lemma":"يَكْفُلُ","grammar_bn":"ক্রিয়া (Verb)"},{"id":41206,"position":10,"text_uthmani":"فَرَجَعْنَـٰكَ","transliteration":"farajaʿnāka","translation_bn":"তখন তোমাকে আমরা ফিরিয়ে দিলাম","root":"رجع","lemma":"رَجَعَ","grammar_bn":"শব্দ"},{"id":41207,"position":11,"text_uthmani":"إِلَىٰٓ","transliteration":"ilā","translation_bn":"কাছে","root":"—","lemma":"إِلَىٰ\r","grammar_bn":"অব্যয় (Preposition)"},{"id":41208,"position":12,"text_uthmani":"أُمِّكَ","transliteration":"ummika","translation_bn":"তোমার মায়ের","root":"امم","lemma":"أُمّ","grammar_bn":"বিশেষ্য (Noun)"},{"id":41209,"position":13,"text_uthmani":"كَىْ","transliteration":"kay","translation_bn":"যেন","root":"—","lemma":"كَى\r","grammar_bn":"অধীনস্থ যোজক (Subordinating)"},{"id":41210,"position":14,"text_uthmani":"تَقَرَّ","transliteration":"taqarra","translation_bn":"জুড়ায়","root":"قرر","lemma":"تَقَرَّ","grammar_bn":"ক্রিয়া (Verb)"},{"id":41211,"position":15,"text_uthmani":"عَيْنُهَا","transliteration":"ʿaynuhā","translation_bn":"তার চোখ","root":"عين","lemma":"عَيْن","grammar_bn":"বিশেষ্য (Noun)"},{"id":41212,"position":16,"text_uthmani":"وَلَا","transliteration":"walā","translation_bn":"এবং না","root":"—","lemma":"لَا\r","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":41213,"position":17,"text_uthmani":"تَحْزَنَ ۚ","transliteration":"taḥzana","translation_bn":"দুঃখ পায়","root":"حزن","lemma":"يَحْزُن","grammar_bn":"ক্রিয়া (Verb)"},{"id":41215,"position":18,"text_uthmani":"وَقَتَلْتَ","transliteration":"waqatalta","translation_bn":"এবং (স্মরণ করো) তুমি হত্যা করেছিলে","root":"قتل","lemma":"قَتَلَ","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":41216,"position":19,"text_uthmani":"نَفْسًۭا","transliteration":"nafsan","translation_bn":"এক ব্যক্তিকে","root":"نفس","lemma":"نَفْس","grammar_bn":"বিশেষ্য (Noun)"},{"id":41217,"position":20,"text_uthmani":"فَنَجَّيْنَـٰكَ","transliteration":"fanajjaynāka","translation_bn":"অতঃপর তোমাকে আমরা মুক্তি দিয়েছিলাম","root":"نجو","lemma":"نَجَّىٰ","grammar_bn":"শব্দ"},{"id":41218,"position":21,"text_uthmani":"مِنَ","transliteration":"mina","translation_bn":"হ''তে","root":"—","lemma":"مِن\r","grammar_bn":"অব্যয় (Preposition)"},{"id":41219,"position":22,"text_uthmani":"ٱلْغَمِّ","transliteration":"l-ghami","translation_bn":"মানসিক কষ্ট","root":"غمم","lemma":"غَمّ","grammar_bn":"শব্দ"},{"id":41220,"position":23,"text_uthmani":"وَفَتَنَّـٰكَ","transliteration":"wafatannāka","translation_bn":"এবং তোমাকে আমরা পরীক্ষা করেছি","root":"فتن","lemma":"فَتَنُ","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":41221,"position":24,"text_uthmani":"فُتُونًۭا ۚ","transliteration":"futūnan","translation_bn":"(কঠিন) পরীক্ষা","root":"فتن","lemma":"فُتُون","grammar_bn":"বিশেষ্য (Noun)"},{"id":41223,"position":25,"text_uthmani":"فَلَبِثْتَ","transliteration":"falabith''ta","translation_bn":"অতঃপর তুমি অবস্থান করেছিলে","root":"لبث","lemma":"لَبِثَ","grammar_bn":"শব্দ"},{"id":41224,"position":26,"text_uthmani":"سِنِينَ","transliteration":"sinīna","translation_bn":"(কয়েক) বছর","root":"سنو","lemma":"سِنِين","grammar_bn":"কালবাচক (Time)"},{"id":41225,"position":27,"text_uthmani":"فِىٓ","transliteration":"fī","translation_bn":"মধ্যে","root":"—","lemma":"فِى\r","grammar_bn":"অব্যয় (Preposition)"},{"id":41226,"position":28,"text_uthmani":"أَهْلِ","transliteration":"ahli","translation_bn":"অধিবাসীদের","root":"اهل","lemma":"أَهْل","grammar_bn":"বিশেষ্য (Noun)"},{"id":41227,"position":29,"text_uthmani":"مَدْيَنَ","transliteration":"madyana","translation_bn":"মা''দয়ানের","root":"—","lemma":"مَدْيَن","grammar_bn":"নামবাচক বিশেষ্য (Proper Noun)"},{"id":41228,"position":30,"text_uthmani":"ثُمَّ","transliteration":"thumma","translation_bn":"এরপর","root":"—","lemma":"ثُمّ\r","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":41229,"position":31,"text_uthmani":"جِئْتَ","transliteration":"ji''ta","translation_bn":"তুমি এসেছো","root":"جيا","lemma":"جَا^ءَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":41230,"position":32,"text_uthmani":"عَلَىٰ","transliteration":"ʿalā","translation_bn":"উপর","root":"—","lemma":"عَلَىٰ\r","grammar_bn":"অব্যয় (Preposition)"},{"id":41231,"position":33,"text_uthmani":"قَدَرٍۢ","transliteration":"qadarin","translation_bn":"নির্ধারিত সময়ের","root":"قدر","lemma":"قَدَر","grammar_bn":"বিশেষ্য (Noun)"},{"id":41232,"position":34,"text_uthmani":"يَـٰمُوسَىٰ","transliteration":"yāmūsā","translation_bn":"হে মূসা","root":"—","lemma":"مُوسَىٰ","grammar_bn":"সম্বোধন পদ (Vocative)"},{"id":41233,"position":35,"text_uthmani":"٤٠","transliteration":"","translation_bn":"(৪০)","root":"—","lemma":"٤٠","grammar_bn":"মার্কার"}]'::jsonb, 'idh tamshī ukh''tuka fataqūlu hal adullukum ʿalā man yakfuluhu farajaʿnāka ilā ummika kay taqarra ʿaynuhā walā taḥzana waqatalta nafsan fanajjaynāka mina l-ghami wafatannāka futūnan falabith''ta sinīna fī ahli madyana thumma ji''ta ʿalā qadarin yāmūsā', 'যখন তোমার বোন গিয়ে বলল, ‘তোমাদেরকে কি বলে দেব কে এই শিশুর তত্ত্বাবধান ও প্রতিপালনের ভার নেবে?’ এভাবে আমি তোমাকে তোমার মায়ের কাছে ফিরিয়ে আনলাম যাতে তার চোখ জুড়ায় আর সে দুঃখ না পায়। আর তুমি এক লোককে হত্যা করেছিলে, অতঃপর আমি তোমাকে মনোবেদনা থেকে মুক্তি দিয়েছি। আমি তোমাকে অনেক পরীক্ষা করেছি। অতঃপর তুমি কয়েক বছর মাদ্ইয়ানবাসীদের মধ্যে অবস্থান করলে, এরপর হে মূসা! তুমি নির্ধারিত সময়ে এসে হাযির হয়েছ।', '[And We favored you] when your sister went and said, ''Shall I direct you to someone who will be responsible for him?'' So We restored you to your mother that she might be content and not grieve. And you killed someone, but We saved you from retaliation and tried you with a [severe] trial. And you remained [some] years among the people of Madyan. Then you came [here] at the decreed time, O Moses.', 'যখন তোমার বোন গিয়ে বলল, ‘তোমাদেরকে কি বলে দেব কে এই শিশুর তত্ত্বাবধান ও প্রতিপালনের ভার নেবে?’ এভাবে আমি তোমাকে তোমার মায়ের কাছে ফিরিয়ে আনলাম যাতে তার চোখ জুড়ায় আর সে দুঃখ না পায়। আর তুমি এক লোককে হত্যা করেছিলে, অতঃপর আমি তোমাকে মনোবেদনা থেকে মুক্তি দিয়েছি। আমি তোমাকে অনেক পরীক্ষা করেছি। অতঃপর তুমি কয়েক বছর মাদ্ইয়ানবাসীদের মধ্যে অবস্থান করলে, এরপর হে মূসা! তুমি নির্ধারিত সময়ে এসে হাযির হয়েছ।', '[And We favored you] when your sister went and said, ''Shall I direct you to someone who will be responsible for him?'' So We restored you to your mother that she might be content and not grieve. And you killed someone, but We saved you from retaliation and tried you with a [severe] trial. And you remained [some] years among the people of Madyan. Then you came [here] at the decreed time, O Moses.', NULL, NULL, NULL, NULL, NULL, 'https://everyayah.com/data/Alafasy_128kbps/020040.mp3', now()),
  (20, 41, '', '[{"id":42077,"position":1,"text_uthmani":"وَٱصْطَنَعْتُكَ","transliteration":"wa-iṣ''ṭanaʿtuka","translation_bn":"এবং তোমাকে আমি প্রস্তুত করেছি","root":"صنع","lemma":"ٱصْطَنَعْ","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":42078,"position":2,"text_uthmani":"لِنَفْسِى","transliteration":"linafsī","translation_bn":"আমার নিজের (কাজের) জন্যে","root":"نفس","lemma":"نَفْس","grammar_bn":"অব্যয় (Preposition)"},{"id":42079,"position":3,"text_uthmani":"٤١","transliteration":"","translation_bn":"(৪১)","root":"—","lemma":"٤١","grammar_bn":"মার্কার"}]'::jsonb, 'wa-iṣ''ṭanaʿtuka linafsī', 'আমি তোমাকে আমার নিজের জন্য তৈরি করেছি।', 'And I produced you for Myself.', 'আমি তোমাকে আমার নিজের জন্য তৈরি করেছি।', 'And I produced you for Myself.', NULL, NULL, NULL, NULL, NULL, 'https://everyayah.com/data/Alafasy_128kbps/020041.mp3', now()),
  (20, 42, '', '[{"id":42865,"position":1,"text_uthmani":"ٱذْهَبْ","transliteration":"idh''hab","translation_bn":"যাও","root":"ذهب","lemma":"ذَهَبَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":42866,"position":2,"text_uthmani":"أَنتَ","transliteration":"anta","translation_bn":"তুমি","root":"—","lemma":"أَنتَ","grammar_bn":"সর্বনাম (Pronoun)"},{"id":42867,"position":3,"text_uthmani":"وَأَخُوكَ","transliteration":"wa-akhūka","translation_bn":"ও তোমার ভাই","root":"اخو","lemma":"أَخ","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":42868,"position":4,"text_uthmani":"بِـَٔايَـٰتِى","transliteration":"biāyātī","translation_bn":"নিয়ে আমার নির্দেশনাবলী","root":"ايي","lemma":"ءَايَة","grammar_bn":"অব্যয় (Preposition)"},{"id":42869,"position":5,"text_uthmani":"وَلَا","transliteration":"walā","translation_bn":"এবং না","root":"—","lemma":"لَا\r","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":42870,"position":6,"text_uthmani":"تَنِيَا","transliteration":"taniyā","translation_bn":"তোমরা দু''জনে আসল্য করো","root":"وني","lemma":"تَنِيَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":42871,"position":7,"text_uthmani":"فِى","transliteration":"fī","translation_bn":"ক্ষেত্রে","root":"—","lemma":"فِى\r","grammar_bn":"অব্যয় (Preposition)"},{"id":42872,"position":8,"text_uthmani":"ذِكْرِى","transliteration":"dhik''rī","translation_bn":"আমার স্মরণের","root":"ذكر","lemma":"ذِكْر","grammar_bn":"বিশেষ্য (Noun)"},{"id":42873,"position":9,"text_uthmani":"٤٢","transliteration":"","translation_bn":"(৪২)","root":"—","lemma":"٤٢","grammar_bn":"মার্কার"}]'::jsonb, 'idh''hab anta wa-akhūka biāyātī walā taniyā fī dhik''rī', 'তুমি আর তোমার ভাই আমার নিদর্শন নিয়ে যাও আর তোমরা আমাকে স্মরণ করার বিষয়ে শৈথিল্য করো না।', 'Go, you and your brother, with My signs and do not slacken in My remembrance.', 'তুমি আর তোমার ভাই আমার নিদর্শন নিয়ে যাও আর তোমরা আমাকে স্মরণ করার বিষয়ে শৈথিল্য করো না।', 'Go, you and your brother, with My signs and do not slacken in My remembrance.', NULL, NULL, NULL, NULL, NULL, 'https://everyayah.com/data/Alafasy_128kbps/020042.mp3', now()),
  (20, 43, '', '[{"id":43602,"position":1,"text_uthmani":"ٱذْهَبَآ","transliteration":"idh''habā","translation_bn":"দু''জনে যাও","root":"ذهب","lemma":"ذَهَبَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":43603,"position":2,"text_uthmani":"إِلَىٰ","transliteration":"ilā","translation_bn":"নিকট","root":"—","lemma":"إِلَىٰ\r","grammar_bn":"অব্যয় (Preposition)"},{"id":43604,"position":3,"text_uthmani":"فِرْعَوْنَ","transliteration":"fir''ʿawna","translation_bn":"ফিরআউনের","root":"—","lemma":"فِرْعَوْن","grammar_bn":"নামবাচক বিশেষ্য (Proper Noun)"},{"id":43605,"position":4,"text_uthmani":"إِنَّهُۥ","transliteration":"innahu","translation_bn":"সে নিশ্চয়ই","root":"—","lemma":"إِنّ","grammar_bn":"অভিঘাত পদ (Accusative)"},{"id":43606,"position":5,"text_uthmani":"طَغَىٰ","transliteration":"ṭaghā","translation_bn":"সীমালঙ্ঘন করেছে","root":"طغي","lemma":"طَغَىٰ","grammar_bn":"ক্রিয়া (Verb)"},{"id":43607,"position":6,"text_uthmani":"٤٣","transliteration":"","translation_bn":"(৪৩)","root":"—","lemma":"٤٣","grammar_bn":"মার্কার"}]'::jsonb, 'idh''habā ilā fir''ʿawna innahu ṭaghā', 'তোমরা দু’জন ফেরাউনের নিকট যাও, বস্তুতঃ সে সীমালঙ্ঘন করেছে।', 'Go, both of you, to Pharaoh. Indeed, he has transgressed.', 'তোমরা দু’জন ফেরাউনের নিকট যাও, বস্তুতঃ সে সীমালঙ্ঘন করেছে।', 'Go, both of you, to Pharaoh. Indeed, he has transgressed.', NULL, NULL, NULL, NULL, NULL, 'https://everyayah.com/data/Alafasy_128kbps/020043.mp3', now()),
  (20, 44, '', '[{"id":44704,"position":1,"text_uthmani":"فَقُولَا","transliteration":"faqūlā","translation_bn":"অতঃপর দু''জনে বলবে","root":"قول","lemma":"قَالَ","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":44705,"position":2,"text_uthmani":"لَهُۥ","transliteration":"lahu","translation_bn":"তার সাথে","root":"—","lemma":"لَهُۥ","grammar_bn":"অব্যয় (Preposition)"},{"id":44706,"position":3,"text_uthmani":"قَوْلًۭا","transliteration":"qawlan","translation_bn":"কথা","root":"قول","lemma":"قَوْل","grammar_bn":"বিশেষ্য (Noun)"},{"id":44707,"position":4,"text_uthmani":"لَّيِّنًۭا","transliteration":"layyinan","translation_bn":"নম্রভাবে","root":"لين","lemma":"لَّيِّن","grammar_bn":"বিশেষণ (Adjective)"},{"id":44708,"position":5,"text_uthmani":"لَّعَلَّهُۥ","transliteration":"laʿallahu","translation_bn":"সে সম্ভবতঃ","root":"—","lemma":"لَعَلّ","grammar_bn":"অভিঘাত পদ (Accusative)"},{"id":44709,"position":6,"text_uthmani":"يَتَذَكَّرُ","transliteration":"yatadhakkaru","translation_bn":"উপদেশ গ্রহণ করবে","root":"ذكر","lemma":"تَذَكَّرَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":44710,"position":7,"text_uthmani":"أَوْ","transliteration":"aw","translation_bn":"অথবা","root":"—","lemma":"أَو\r","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":44711,"position":8,"text_uthmani":"يَخْشَىٰ","transliteration":"yakhshā","translation_bn":"ভয় করবে\"","root":"خشي","lemma":"خَشِىَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":44712,"position":9,"text_uthmani":"٤٤","transliteration":"","translation_bn":"(৪৪)","root":"—","lemma":"٤٤","grammar_bn":"মার্কার"}]'::jsonb, 'faqūlā lahu qawlan layyinan laʿallahu yatadhakkaru aw yakhshā', 'তার সঙ্গে তোমরা নম্রভাবে কথা বলবে, হয়তো সে উপদেশ গ্রহণ করবে কিংবা (আল্লাহর) ভয় করবে।’', 'And speak to him with gentle speech that perhaps he may be reminded or fear [Allah]."', 'তার সঙ্গে তোমরা নম্রভাবে কথা বলবে, হয়তো সে উপদেশ গ্রহণ করবে কিংবা (আল্লাহর) ভয় করবে।’', 'And speak to him with gentle speech that perhaps he may be reminded or fear [Allah]."', NULL, NULL, NULL, NULL, NULL, 'https://everyayah.com/data/Alafasy_128kbps/020044.mp3', now()),
  (20, 45, '', '[{"id":45366,"position":1,"text_uthmani":"قَالَا","transliteration":"qālā","translation_bn":"তারা (দু''জনে) বললো","root":"قول","lemma":"قَالَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":45367,"position":2,"text_uthmani":"رَبَّنَآ","transliteration":"rabbanā","translation_bn":"\"হে আমাদের রব","root":"ربب","lemma":"رَبّ","grammar_bn":"বিশেষ্য (Noun)"},{"id":45368,"position":3,"text_uthmani":"إِنَّنَا","transliteration":"innanā","translation_bn":"নিশ্চয়ই আমরা","root":"—","lemma":"إِنّ","grammar_bn":"অভিঘাত পদ (Accusative)"},{"id":45369,"position":4,"text_uthmani":"نَخَافُ","transliteration":"nakhāfu","translation_bn":"আশংকা করি আমরা","root":"خوف","lemma":"خَافَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":45370,"position":5,"text_uthmani":"أَن","transliteration":"an","translation_bn":"যে","root":"—","lemma":"أَن\r","grammar_bn":"অধীনস্থ যোজক (Subordinating)"},{"id":45371,"position":6,"text_uthmani":"يَفْرُطَ","transliteration":"yafruṭa","translation_bn":"ফিরআউন দুর্ব্যবহার করবে","root":"فرط","lemma":"يَفْرُطَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":45372,"position":7,"text_uthmani":"عَلَيْنَآ","transliteration":"ʿalaynā","translation_bn":"আমাদের সাথে","root":"—","lemma":"عَلَىٰ\r","grammar_bn":"অব্যয় (Preposition)"},{"id":45373,"position":8,"text_uthmani":"أَوْ","transliteration":"aw","translation_bn":"অথবা","root":"—","lemma":"أَو\r","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":45374,"position":9,"text_uthmani":"أَن","transliteration":"an","translation_bn":"যে","root":"—","lemma":"أَن\r","grammar_bn":"অধীনস্থ যোজক (Subordinating)"},{"id":45375,"position":10,"text_uthmani":"يَطْغَىٰ","transliteration":"yaṭghā","translation_bn":"সে সীমালংঘন করবে\"","root":"طغي","lemma":"طَغَىٰ","grammar_bn":"ক্রিয়া (Verb)"},{"id":45376,"position":11,"text_uthmani":"٤٥","transliteration":"","translation_bn":"(৪৫)","root":"—","lemma":"٤٥","grammar_bn":"মার্কার"}]'::jsonb, 'qālā rabbanā innanā nakhāfu an yafruṭa ʿalaynā aw an yaṭghā', 'তারা বলল, ‘হে আমাদের প্রতিপালক! আমাদের ভয় হচ্ছে সে আমাদের প্রতি হঠাৎ উত্তেজিত হয়ে উঠবে কিংবা আমাদের প্রতি আচরণে বাড়াবাড়ি করবে।’', 'They said, "Our Lord, indeed we are afraid that he will hasten [punishment] against us or that he will transgress."', 'তারা বলল, ‘হে আমাদের প্রতিপালক! আমাদের ভয় হচ্ছে সে আমাদের প্রতি হঠাৎ উত্তেজিত হয়ে উঠবে কিংবা আমাদের প্রতি আচরণে বাড়াবাড়ি করবে।’', 'They said, "Our Lord, indeed we are afraid that he will hasten [punishment] against us or that he will transgress."', NULL, NULL, NULL, NULL, NULL, 'https://everyayah.com/data/Alafasy_128kbps/020045.mp3', now()),
  (20, 46, '', '[{"id":46205,"position":1,"text_uthmani":"قَالَ","transliteration":"qāla","translation_bn":"তিনি বললেন","root":"قول","lemma":"قَالَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":46206,"position":2,"text_uthmani":"لَا","transliteration":"lā","translation_bn":"\"না","root":"—","lemma":"لَا\r","grammar_bn":"নিষেধবাচক (Prohibition)"},{"id":46207,"position":3,"text_uthmani":"تَخَافَآ ۖ","transliteration":"takhāfā","translation_bn":"তোমরা দু''জনে ভয় করো","root":"خوف","lemma":"خَافَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":46209,"position":4,"text_uthmani":"إِنَّنِى","transliteration":"innanī","translation_bn":"আমি নিশ্চয়ই","root":"—","lemma":"إِنّ","grammar_bn":"অভিঘাত পদ (Accusative)"},{"id":46210,"position":5,"text_uthmani":"مَعَكُمَآ","transliteration":"maʿakumā","translation_bn":"তোমাদের দু''জনের সাথে (আছি)","root":"—","lemma":"مَع","grammar_bn":"স্থানবাচক (Location)"},{"id":46211,"position":6,"text_uthmani":"أَسْمَعُ","transliteration":"asmaʿu","translation_bn":"আমি শুনি (সবকিছু)","root":"سمع","lemma":"سَمِعَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":46212,"position":7,"text_uthmani":"وَأَرَىٰ","transliteration":"wa-arā","translation_bn":"ও আমি দেখি (সবকিছু)","root":"راي","lemma":"رَءَا","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":46213,"position":8,"text_uthmani":"٤٦","transliteration":"","translation_bn":"(৪৬)","root":"—","lemma":"٤٦","grammar_bn":"মার্কার"}]'::jsonb, 'qāla lā takhāfā innanī maʿakumā asmaʿu wa-arā', 'তিনি বললেন, ‘তোমরা ভয় করো না, আমি তোমাদের সাথেই আছি, আমি (সব কিছু) শুনি আর দেখি।', '[Allah] said, "Fear not. Indeed, I am with you both; I hear and I see.', 'তিনি বললেন, ‘তোমরা ভয় করো না, আমি তোমাদের সাথেই আছি, আমি (সব কিছু) শুনি আর দেখি।', '[Allah] said, "Fear not. Indeed, I am with you both; I hear and I see.', NULL, NULL, NULL, NULL, NULL, 'https://everyayah.com/data/Alafasy_128kbps/020046.mp3', now()),
  (20, 47, '', '[{"id":46737,"position":1,"text_uthmani":"فَأْتِيَاهُ","transliteration":"fatiyāhu","translation_bn":"সুতরাং তার কাছে দু''জনে যাও","root":"اتي","lemma":"أَتَى","grammar_bn":"শব্দ"},{"id":46738,"position":2,"text_uthmani":"فَقُولَآ","transliteration":"faqūlā","translation_bn":"অতঃপর দু''জনে বলো","root":"قول","lemma":"قَالَ","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":46739,"position":3,"text_uthmani":"إِنَّا","transliteration":"innā","translation_bn":"\"নিশ্চয়ই আমরা","root":"—","lemma":"إِنّ","grammar_bn":"অভিঘাত পদ (Accusative)"},{"id":46740,"position":4,"text_uthmani":"رَسُولَا","transliteration":"rasūlā","translation_bn":"দুই রাসূল","root":"رسل","lemma":"رَسُول","grammar_bn":"বিশেষ্য (Noun)"},{"id":46741,"position":5,"text_uthmani":"رَبِّكَ","transliteration":"rabbika","translation_bn":"তোমার রবের","root":"ربب","lemma":"رَبّ","grammar_bn":"বিশেষ্য (Noun)"},{"id":46742,"position":6,"text_uthmani":"فَأَرْسِلْ","transliteration":"fa-arsil","translation_bn":"সুতরাং পাঠাও","root":"رسل","lemma":"أَرْسَلَ","grammar_bn":"শব্দ"},{"id":46743,"position":7,"text_uthmani":"مَعَنَا","transliteration":"maʿanā","translation_bn":"আমাদের সাথে","root":"—","lemma":"مَع","grammar_bn":"স্থানবাচক (Location)"},{"id":46744,"position":8,"text_uthmani":"بَنِىٓ","transliteration":"banī","translation_bn":"বনী","root":"بني","lemma":"بُنَىّ","grammar_bn":"বিশেষ্য (Noun)"},{"id":46745,"position":9,"text_uthmani":"إِسْرَٰٓءِيلَ","transliteration":"is''rāīla","translation_bn":"ইসরাঈলকে","root":"—","lemma":"إِسْرَائِيل","grammar_bn":"নামবাচক বিশেষ্য (Proper Noun)"},{"id":46746,"position":10,"text_uthmani":"وَلَا","transliteration":"walā","translation_bn":"এবং না","root":"—","lemma":"لَا\r","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":46747,"position":11,"text_uthmani":"تُعَذِّبْهُمْ ۖ","transliteration":"tuʿadhib''hum","translation_bn":"তাদেরকে শাস্তি দিও","root":"عذب","lemma":"عَذَّبَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":46749,"position":12,"text_uthmani":"قَدْ","transliteration":"qad","translation_bn":"নিশ্চয়ই","root":"—","lemma":"قَد\r","grammar_bn":"নিশ্চয়তাবোধক (Certainty)"},{"id":46750,"position":13,"text_uthmani":"جِئْنَـٰكَ","transliteration":"ji''nāka","translation_bn":"তোমার কাছে আমরা এসেছি","root":"جيا","lemma":"جَا^ءَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":46751,"position":14,"text_uthmani":"بِـَٔايَةٍۢ","transliteration":"biāyatin","translation_bn":"নিয়ে নিদর্শন","root":"ايي","lemma":"ءَايَة","grammar_bn":"অব্যয় (Preposition)"},{"id":46752,"position":15,"text_uthmani":"مِّن","transliteration":"min","translation_bn":"পক্ষ হ''তে","root":"—","lemma":"مِن\r","grammar_bn":"অব্যয় (Preposition)"},{"id":46753,"position":16,"text_uthmani":"رَّبِّكَ ۖ","transliteration":"rabbika","translation_bn":"তোমার রবের","root":"ربب","lemma":"رَبّ","grammar_bn":"বিশেষ্য (Noun)"},{"id":46755,"position":17,"text_uthmani":"وَٱلسَّلَـٰمُ","transliteration":"wal-salāmu","translation_bn":"এবং শান্তি","root":"سلم","lemma":"سَلَٰم","grammar_bn":"শব্দ"},{"id":46756,"position":18,"text_uthmani":"عَلَىٰ","transliteration":"ʿalā","translation_bn":"উপর","root":"—","lemma":"عَلَىٰ\r","grammar_bn":"অব্যয় (Preposition)"},{"id":46757,"position":19,"text_uthmani":"مَنِ","transliteration":"mani","translation_bn":"(তার) যে","root":"—","lemma":"مَن\r","grammar_bn":"সাপেক্ষ সর্বনাম (Relative)"},{"id":46758,"position":20,"text_uthmani":"ٱتَّبَعَ","transliteration":"ittabaʿa","translation_bn":"অনুসরণ করে","root":"تبع","lemma":"ٱتَّبَعَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":46759,"position":21,"text_uthmani":"ٱلْهُدَىٰٓ","transliteration":"l-hudā","translation_bn":"সঠিক পথের","root":"هدي","lemma":"هُدًى","grammar_bn":"শব্দ"},{"id":46760,"position":22,"text_uthmani":"٤٧","transliteration":"","translation_bn":"(৪৭)","root":"—","lemma":"٤٧","grammar_bn":"মার্কার"}]'::jsonb, 'fatiyāhu faqūlā innā rasūlā rabbika fa-arsil maʿanā banī is''rāīla walā tuʿadhib''hum qad ji''nāka biāyatin min rabbika wal-salāmu ʿalā mani ittabaʿa l-hudā', 'কাজেই তোমরা দু’জন তার কাছে এসো আর বল- আমরা তোমার প্রতিপালকের রসূল, কাজেই বানী ইসরাঈলকে আমাদের সঙ্গে পাঠিয়ে দাও, তাদের প্রতি উৎপীড়ন করো না। তোমার প্রতিপালকের নিদর্শনসহই আমরা তোমার কাছে এসেছি, আর শান্তি বর্ষিত হোক তাদের প্রতি যারা সৎ পথ অনুসরণ করে।', 'So go to him and say, ''Indeed, we are messengers of your Lord, so send with us the Children of Israel and do not torment them. We have come to you with a sign from your Lord. And peace will be upon he who follows the guidance.', 'কাজেই তোমরা দু’জন তার কাছে এসো আর বল- আমরা তোমার প্রতিপালকের রসূল, কাজেই বানী ইসরাঈলকে আমাদের সঙ্গে পাঠিয়ে দাও, তাদের প্রতি উৎপীড়ন করো না। তোমার প্রতিপালকের নিদর্শনসহই আমরা তোমার কাছে এসেছি, আর শান্তি বর্ষিত হোক তাদের প্রতি যারা সৎ পথ অনুসরণ করে।', 'So go to him and say, ''Indeed, we are messengers of your Lord, so send with us the Children of Israel and do not torment them. We have come to you with a sign from your Lord. And peace will be upon he who follows the guidance.', NULL, NULL, NULL, NULL, NULL, 'https://everyayah.com/data/Alafasy_128kbps/020047.mp3', now()),
  (20, 48, '', '[{"id":47248,"position":1,"text_uthmani":"إِنَّا","transliteration":"innā","translation_bn":"আমরা নিশ্চয়ই (এমন যে)","root":"—","lemma":"إِنّ","grammar_bn":"অভিঘাত পদ (Accusative)"},{"id":47249,"position":2,"text_uthmani":"قَدْ","transliteration":"qad","translation_bn":"নিশ্চয়ই","root":"—","lemma":"قَد\r","grammar_bn":"নিশ্চয়তাবোধক (Certainty)"},{"id":47250,"position":3,"text_uthmani":"أُوحِىَ","transliteration":"ūḥiya","translation_bn":"ওহী করা হয়েছে","root":"وحي","lemma":"أَوْحَىٰ^","grammar_bn":"ক্রিয়া (Verb)"},{"id":47251,"position":4,"text_uthmani":"إِلَيْنَآ","transliteration":"ilaynā","translation_bn":"প্রতি আমাদের","root":"—","lemma":"إِلَىٰ\r","grammar_bn":"অব্যয় (Preposition)"},{"id":47252,"position":5,"text_uthmani":"أَنَّ","transliteration":"anna","translation_bn":"যে","root":"—","lemma":"أَنّ","grammar_bn":"অভিঘাত পদ (Accusative)"},{"id":47253,"position":6,"text_uthmani":"ٱلْعَذَابَ","transliteration":"l-ʿadhāba","translation_bn":"শাস্তি","root":"عذب","lemma":"عَذَاب","grammar_bn":"শব্দ"},{"id":47254,"position":7,"text_uthmani":"عَلَىٰ","transliteration":"ʿalā","translation_bn":"উপর","root":"—","lemma":"عَلَىٰ\r","grammar_bn":"অব্যয় (Preposition)"},{"id":47255,"position":8,"text_uthmani":"مَن","transliteration":"man","translation_bn":"(তার) যে","root":"—","lemma":"مَن\r","grammar_bn":"সাপেক্ষ সর্বনাম (Relative)"},{"id":47256,"position":9,"text_uthmani":"كَذَّبَ","transliteration":"kadhaba","translation_bn":"মিথ্যারোপ করবে","root":"كذب","lemma":"كَذَّبَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":47257,"position":10,"text_uthmani":"وَتَوَلَّىٰ","transliteration":"watawallā","translation_bn":"ও মুখ ফিরাবে (অমান্য করবে)\"","root":"ولي","lemma":"تَوَلَّىٰ","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":47258,"position":11,"text_uthmani":"٤٨","transliteration":"","translation_bn":"(৪৮)","root":"—","lemma":"٤٨","grammar_bn":"মার্কার"}]'::jsonb, 'innā qad ūḥiya ilaynā anna l-ʿadhāba ʿalā man kadhaba watawallā', 'আমাদের কাছে ওয়াহী করা হয়েছে যে শাস্তি (অপেক্ষা করছে) তার জন্য যে (সত্য) প্রত্যাখ্যান করে আর মুখ ফিরিয়ে নেয়।’', 'Indeed, it has been revealed to us that the punishment will be upon whoever denies and turns away.'' "', 'আমাদের কাছে ওয়াহী করা হয়েছে যে শাস্তি (অপেক্ষা করছে) তার জন্য যে (সত্য) প্রত্যাখ্যান করে আর মুখ ফিরিয়ে নেয়।’', 'Indeed, it has been revealed to us that the punishment will be upon whoever denies and turns away.'' "', NULL, NULL, NULL, NULL, NULL, 'https://everyayah.com/data/Alafasy_128kbps/020048.mp3', now()),
  (20, 49, '', '[{"id":47869,"position":1,"text_uthmani":"قَالَ","transliteration":"qāla","translation_bn":"(ফিরআউন) বললো","root":"قول","lemma":"قَالَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":47870,"position":2,"text_uthmani":"فَمَن","transliteration":"faman","translation_bn":"\"তাহ''লে কে","root":"—","lemma":"مَن\r","grammar_bn":"শব্দ"},{"id":47871,"position":3,"text_uthmani":"رَّبُّكُمَا","transliteration":"rabbukumā","translation_bn":"তোমাদের দু''জনের রব","root":"ربب","lemma":"رَبّ","grammar_bn":"বিশেষ্য (Noun)"},{"id":47872,"position":4,"text_uthmani":"يَـٰمُوسَىٰ","transliteration":"yāmūsā","translation_bn":"হে মূসা\"","root":"—","lemma":"مُوسَىٰ","grammar_bn":"সম্বোধন পদ (Vocative)"},{"id":47873,"position":5,"text_uthmani":"٤٩","transliteration":"","translation_bn":"(৪৯)","root":"—","lemma":"٤٩","grammar_bn":"মার্কার"}]'::jsonb, 'qāla faman rabbukumā yāmūsā', 'ফেরাউন বলল, ‘হে মূসা! কে তোমাদের প্রতিপালক?’', '[Pharaoh] said, "So who is the Lord of you two, O Moses?"', 'ফেরাউন বলল, ‘হে মূসা! কে তোমাদের প্রতিপালক?’', '[Pharaoh] said, "So who is the Lord of you two, O Moses?"', NULL, NULL, NULL, NULL, NULL, 'https://everyayah.com/data/Alafasy_128kbps/020049.mp3', now()),
  (20, 50, '', '[{"id":48953,"position":1,"text_uthmani":"قَالَ","transliteration":"qāla","translation_bn":"মূসা বললো","root":"قول","lemma":"قَالَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":48954,"position":2,"text_uthmani":"رَبُّنَا","transliteration":"rabbunā","translation_bn":"\"আমাদের রব","root":"ربب","lemma":"رَبّ","grammar_bn":"বিশেষ্য (Noun)"},{"id":48955,"position":3,"text_uthmani":"ٱلَّذِىٓ","transliteration":"alladhī","translation_bn":"(তিনি) যিনি","root":"—","lemma":"ٱلَّذِى","grammar_bn":"সাপেক্ষ সর্বনাম (Relative)"},{"id":48956,"position":4,"text_uthmani":"أَعْطَىٰ","transliteration":"aʿṭā","translation_bn":"দিয়েছেন","root":"عطو","lemma":"أَعْطَىٰ","grammar_bn":"ক্রিয়া (Verb)"},{"id":48957,"position":5,"text_uthmani":"كُلَّ","transliteration":"kulla","translation_bn":"প্রত্যেক","root":"كلل","lemma":"كُلّ","grammar_bn":"বিশেষ্য (Noun)"},{"id":48958,"position":6,"text_uthmani":"شَىْءٍ","transliteration":"shayin","translation_bn":"বস্তুকে","root":"شيا","lemma":"شَىْء","grammar_bn":"বিশেষ্য (Noun)"},{"id":48959,"position":7,"text_uthmani":"خَلْقَهُۥ","transliteration":"khalqahu","translation_bn":"তার সৃষ্টি কাঠামো","root":"خلق","lemma":"خَلْق","grammar_bn":"বিশেষ্য (Noun)"},{"id":48960,"position":8,"text_uthmani":"ثُمَّ","transliteration":"thumma","translation_bn":"এরপর","root":"—","lemma":"ثُمّ\r","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":48961,"position":9,"text_uthmani":"هَدَىٰ","transliteration":"hadā","translation_bn":"পথ দেখিয়েছেন\"","root":"هدي","lemma":"هَدَى","grammar_bn":"ক্রিয়া (Verb)"},{"id":48962,"position":10,"text_uthmani":"٥٠","transliteration":"","translation_bn":"(৫০)","root":"—","lemma":"٥٠","grammar_bn":"মার্কার"}]'::jsonb, 'qāla rabbunā alladhī aʿṭā kulla shayin khalqahu thumma hadā', 'মূসা বলল, ‘আমাদের প্রতিপালক তিনি যিনি সকল (সৃষ্ট) বস্তুকে আকৃতি দান করেছেন, অতঃপর পথ প্রদর্শন করেছেন।’', 'He said, "Our Lord is He who gave each thing its form and then guided [it]."', 'মূসা বলল, ‘আমাদের প্রতিপালক তিনি যিনি সকল (সৃষ্ট) বস্তুকে আকৃতি দান করেছেন, অতঃপর পথ প্রদর্শন করেছেন।’', 'He said, "Our Lord is He who gave each thing its form and then guided [it]."', NULL, NULL, NULL, NULL, NULL, 'https://everyayah.com/data/Alafasy_128kbps/020050.mp3', now()),
  (20, 51, '', '[{"id":49177,"position":1,"text_uthmani":"قَالَ","transliteration":"qāla","translation_bn":"সে বললো","root":"قول","lemma":"قَالَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":49178,"position":2,"text_uthmani":"فَمَا","transliteration":"famā","translation_bn":"\"তাহ''লে কি (হবে)","root":"—","lemma":"مَا\r","grammar_bn":"শব্দ"},{"id":49179,"position":3,"text_uthmani":"بَالُ","transliteration":"bālu","translation_bn":"অবস্থা","root":"بول","lemma":"بَال","grammar_bn":"বিশেষ্য (Noun)"},{"id":49180,"position":4,"text_uthmani":"ٱلْقُرُونِ","transliteration":"l-qurūni","translation_bn":"শত শত বছরের বংশধরদের","root":"قرن","lemma":"قَرْن","grammar_bn":"শব্দ"},{"id":49181,"position":5,"text_uthmani":"ٱلْأُولَىٰ","transliteration":"l-ūlā","translation_bn":"পূর্বের\"","root":"اول","lemma":"أَوَّل","grammar_bn":"শব্দ"},{"id":49182,"position":6,"text_uthmani":"٥١","transliteration":"","translation_bn":"(৫১)","root":"—","lemma":"٥١","grammar_bn":"মার্কার"}]'::jsonb, 'qāla famā bālu l-qurūni l-ūlā', 'ফেরাউন বলল, ‘তাহলে আগের যুগের লোকেদের অবস্থা কী?’', '[Pharaoh] said, "Then what is the case of the former generations?"', 'ফেরাউন বলল, ‘তাহলে আগের যুগের লোকেদের অবস্থা কী?’', '[Pharaoh] said, "Then what is the case of the former generations?"', NULL, NULL, NULL, NULL, NULL, 'https://everyayah.com/data/Alafasy_128kbps/020051.mp3', now()),
  (20, 52, '', '[{"id":49844,"position":1,"text_uthmani":"قَالَ","transliteration":"qāla","translation_bn":"সে বললো","root":"قول","lemma":"قَالَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":49845,"position":2,"text_uthmani":"عِلْمُهَا","transliteration":"ʿil''muhā","translation_bn":"\"তার জ্ঞান","root":"علم","lemma":"عِلْم","grammar_bn":"বিশেষ্য (Noun)"},{"id":49846,"position":3,"text_uthmani":"عِندَ","transliteration":"ʿinda","translation_bn":"নিকট (আছে)","root":"عند","lemma":"عِند","grammar_bn":"স্থানবাচক (Location)"},{"id":49847,"position":4,"text_uthmani":"رَبِّى","transliteration":"rabbī","translation_bn":"আমার রবের","root":"ربب","lemma":"رَبّ","grammar_bn":"বিশেষ্য (Noun)"},{"id":49848,"position":5,"text_uthmani":"فِى","transliteration":"fī","translation_bn":"মধ্যে","root":"—","lemma":"فِى\r","grammar_bn":"অব্যয় (Preposition)"},{"id":49849,"position":6,"text_uthmani":"كِتَـٰبٍۢ ۖ","transliteration":"kitābin","translation_bn":"একটি কিতাবের (সংরক্ষিত)","root":"كتب","lemma":"كِتَٰب","grammar_bn":"বিশেষ্য (Noun)"},{"id":49851,"position":7,"text_uthmani":"لَّا","transliteration":"lā","translation_bn":"না","root":"—","lemma":"لَا\r","grammar_bn":"না-বোধক (Negative)"},{"id":49852,"position":8,"text_uthmani":"يَضِلُّ","transliteration":"yaḍillu","translation_bn":"ভুল করেন","root":"ضلل","lemma":"ضَلَّ","grammar_bn":"ক্রিয়া (Verb)"},{"id":49853,"position":9,"text_uthmani":"رَبِّى","transliteration":"rabbī","translation_bn":"আমার রব","root":"ربب","lemma":"رَبّ","grammar_bn":"বিশেষ্য (Noun)"},{"id":49854,"position":10,"text_uthmani":"وَلَا","transliteration":"walā","translation_bn":"আর না","root":"—","lemma":"لَا\r","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":49855,"position":11,"text_uthmani":"يَنسَى","transliteration":"yansā","translation_bn":"ভুলে যান\"","root":"نسي","lemma":"نَسِىَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":49856,"position":12,"text_uthmani":"٥٢","transliteration":"","translation_bn":"(৫২)","root":"—","lemma":"٥٢","grammar_bn":"মার্কার"}]'::jsonb, 'qāla ʿil''muhā ʿinda rabbī fī kitābin lā yaḍillu rabbī walā yansā', 'মূসা বলল, ‘তার জ্ঞান আমার প্রতিপালকের কাছে (রক্ষিত) কিতাবে আছে, আমার প্রতিপালক ভুল করেন না, ভুলেও যান না।’', '[Moses] said, "The knowledge thereof is with my Lord in a record. My Lord neither errs nor forgets."', 'মূসা বলল, ‘তার জ্ঞান আমার প্রতিপালকের কাছে (রক্ষিত) কিতাবে আছে, আমার প্রতিপালক ভুল করেন না, ভুলেও যান না।’', '[Moses] said, "The knowledge thereof is with my Lord in a record. My Lord neither errs nor forgets."', NULL, NULL, NULL, NULL, NULL, 'https://everyayah.com/data/Alafasy_128kbps/020052.mp3', now()),
  (20, 53, '', '[{"id":50485,"position":1,"text_uthmani":"ٱلَّذِى","transliteration":"alladhī","translation_bn":"যিনি","root":"—","lemma":"ٱلَّذِى","grammar_bn":"সাপেক্ষ সর্বনাম (Relative)"},{"id":50486,"position":2,"text_uthmani":"جَعَلَ","transliteration":"jaʿala","translation_bn":"করেছেন","root":"جعل","lemma":"جَعَلَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":50487,"position":3,"text_uthmani":"لَكُمُ","transliteration":"lakumu","translation_bn":"জন্যে তোমাদের","root":"—","lemma":"لَكُمُ","grammar_bn":"অব্যয় (Preposition)"},{"id":50488,"position":4,"text_uthmani":"ٱلْأَرْضَ","transliteration":"l-arḍa","translation_bn":"পৃথিবীকে","root":"ارض","lemma":"أَرْض","grammar_bn":"শব্দ"},{"id":50489,"position":5,"text_uthmani":"مَهْدًۭا","transliteration":"mahdan","translation_bn":"বিছানা","root":"مهد","lemma":"مَهْد","grammar_bn":"বিশেষ্য (Noun)"},{"id":50490,"position":6,"text_uthmani":"وَسَلَكَ","transliteration":"wasalaka","translation_bn":"ও চালিয়ে দিয়েছেন","root":"سلك","lemma":"سَلَكَ","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":50491,"position":7,"text_uthmani":"لَكُمْ","transliteration":"lakum","translation_bn":"তোমাদের জন্য","root":"—","lemma":"لَكُمْ","grammar_bn":"অব্যয় (Preposition)"},{"id":50492,"position":8,"text_uthmani":"فِيهَا","transliteration":"fīhā","translation_bn":"তার মধ্যে","root":"—","lemma":"فِى\r","grammar_bn":"অব্যয় (Preposition)"},{"id":50493,"position":9,"text_uthmani":"سُبُلًۭا","transliteration":"subulan","translation_bn":"পথসমূহ","root":"سبل","lemma":"سَبِيل","grammar_bn":"বিশেষ্য (Noun)"},{"id":50494,"position":10,"text_uthmani":"وَأَنزَلَ","transliteration":"wa-anzala","translation_bn":"এবং বর্ষণ করেছেন","root":"نزل","lemma":"أَنزَلَ","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":50495,"position":11,"text_uthmani":"مِنَ","transliteration":"mina","translation_bn":"থেকে","root":"—","lemma":"مِن\r","grammar_bn":"অব্যয় (Preposition)"},{"id":50496,"position":12,"text_uthmani":"ٱلسَّمَآءِ","transliteration":"l-samāi","translation_bn":"আকাশ","root":"سمو","lemma":"سَمَا^ء","grammar_bn":"শব্দ"},{"id":50497,"position":13,"text_uthmani":"مَآءًۭ","transliteration":"māan","translation_bn":"পানি","root":"موه","lemma":"مَا^ء","grammar_bn":"বিশেষ্য (Noun)"},{"id":50498,"position":14,"text_uthmani":"فَأَخْرَجْنَا","transliteration":"fa-akhrajnā","translation_bn":"(আল্লাহ বলেন) অতঃপর আমরা বের করেছি","root":"خرج","lemma":"أَخْرَجَ","grammar_bn":"শব্দ"},{"id":50499,"position":15,"text_uthmani":"بِهِۦٓ","transliteration":"bihi","translation_bn":"তা দিয়ে","root":"—","lemma":"بِهِۦٓ","grammar_bn":"অব্যয় (Preposition)"},{"id":50500,"position":16,"text_uthmani":"أَزْوَٰجًۭا","transliteration":"azwājan","translation_bn":"জোড়া জোড়া","root":"زوج","lemma":"زَوْج","grammar_bn":"বিশেষ্য (Noun)"},{"id":50501,"position":17,"text_uthmani":"مِّن","transliteration":"min","translation_bn":"থেকে","root":"—","lemma":"مِن\r","grammar_bn":"অব্যয় (Preposition)"},{"id":50502,"position":18,"text_uthmani":"نَّبَاتٍۢ","transliteration":"nabātin","translation_bn":"উদ্ভিদ","root":"نبت","lemma":"نَبَات","grammar_bn":"বিশেষ্য (Noun)"},{"id":50503,"position":19,"text_uthmani":"شَتَّىٰ","transliteration":"shattā","translation_bn":"বিভিন্ন","root":"شتت","lemma":"شَتَّىٰ","grammar_bn":"বিশেষণ (Adjective)"},{"id":50504,"position":20,"text_uthmani":"٥٣","transliteration":"","translation_bn":"(৫৩)","root":"—","lemma":"٥٣","grammar_bn":"মার্কার"}]'::jsonb, 'alladhī jaʿala lakumu l-arḍa mahdan wasalaka lakum fīhā subulan wa-anzala mina l-samāi māan fa-akhrajnā bihi azwājan min nabātin shattā', 'যিনি তোমাদের জন্য যমীনকে করেছেন বিছানা, আর তাতে তোমাদের জন্য ক’রে দিয়েছেন চলার পথ। আর আকাশ থেকে তিনি পানি বর্ষণ করেন আর তা দিয়ে আমি বিভিন্ন লতা-যুগল উদগত করি যার প্রত্যেকটি অন্যটি থেকে আলাদা।', '[It is He] who has made for you the earth as a bed [spread out] and inserted therein for you roadways and sent down from the sky, rain and produced thereby categories of various plants.', 'যিনি তোমাদের জন্য যমীনকে করেছেন বিছানা, আর তাতে তোমাদের জন্য ক’রে দিয়েছেন চলার পথ। আর আকাশ থেকে তিনি পানি বর্ষণ করেন আর তা দিয়ে আমি বিভিন্ন লতা-যুগল উদগত করি যার প্রত্যেকটি অন্যটি থেকে আলাদা।', '[It is He] who has made for you the earth as a bed [spread out] and inserted therein for you roadways and sent down from the sky, rain and produced thereby categories of various plants.', NULL, NULL, NULL, NULL, NULL, 'https://everyayah.com/data/Alafasy_128kbps/020053.mp3', now()),
  (20, 54, '', '[{"id":50963,"position":1,"text_uthmani":"كُلُوا۟","transliteration":"kulū","translation_bn":"তোমরা খাও","root":"اكل","lemma":"أَكَلَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":50964,"position":2,"text_uthmani":"وَٱرْعَوْا۟","transliteration":"wa-ir''ʿaw","translation_bn":"ও তোমরা চড়াও","root":"رعي","lemma":"رَعَ","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":50965,"position":3,"text_uthmani":"أَنْعَـٰمَكُمْ ۗ","transliteration":"anʿāmakum","translation_bn":"তোমাদের গবাদি পশুগুলোকে","root":"نعم","lemma":"نَّعَم","grammar_bn":"বিশেষ্য (Noun)"},{"id":50967,"position":4,"text_uthmani":"إِنَّ","transliteration":"inna","translation_bn":"নিশ্চয়ই","root":"—","lemma":"إِنّ","grammar_bn":"অভিঘাত পদ (Accusative)"},{"id":50968,"position":5,"text_uthmani":"فِى","transliteration":"fī","translation_bn":"মধ্যে (রয়েছে)","root":"—","lemma":"فِى\r","grammar_bn":"অব্যয় (Preposition)"},{"id":50969,"position":6,"text_uthmani":"ذَٰلِكَ","transliteration":"dhālika","translation_bn":"এর","root":"—","lemma":"ذَٰلِك","grammar_bn":"নির্দেশক সর্বনাম (Demonstrative)"},{"id":50970,"position":7,"text_uthmani":"لَـَٔايَـٰتٍۢ","transliteration":"laāyātin","translation_bn":"অবশ্যই নিদর্শনাবলী","root":"ايي","lemma":"ءَايَة","grammar_bn":"দৃঢ়তাবোধক (Emphatic)"},{"id":50971,"position":8,"text_uthmani":"لِّأُو۟لِى","transliteration":"li-ulī","translation_bn":"সম্পন্নদেরদের জন্যে","root":"اول","lemma":"أُولِى","grammar_bn":"অব্যয় (Preposition)"},{"id":50972,"position":9,"text_uthmani":"ٱلنُّهَىٰ","transliteration":"l-nuhā","translation_bn":"বিবেক","root":"نهي","lemma":"نُّهَىٰ","grammar_bn":"শব্দ"},{"id":50973,"position":10,"text_uthmani":"٥٤","transliteration":"","translation_bn":"(৫৪)","root":"—","lemma":"٥٤","grammar_bn":"মার্কার"}]'::jsonb, 'kulū wa-ir''ʿaw anʿāmakum inna fī dhālika laāyātin li-ulī l-nuhā', 'তোমরা খাও আর তোমাদের গবাদি পশু চরাও, এতে বিবেকবানদের জন্য বহু নিদর্শন আছে।', 'Eat [therefrom] and pasture your livestock. Indeed, in that are signs for those of intelligence.', 'তোমরা খাও আর তোমাদের গবাদি পশু চরাও, এতে বিবেকবানদের জন্য বহু নিদর্শন আছে।', 'Eat [therefrom] and pasture your livestock. Indeed, in that are signs for those of intelligence.', NULL, NULL, NULL, NULL, NULL, 'https://everyayah.com/data/Alafasy_128kbps/020054.mp3', now()),
  (20, 55, '', '[{"id":51796,"position":1,"text_uthmani":"۞ مِنْهَا","transliteration":"min''hā","translation_bn":"তা (অর্থাৎ মাটি) হ''তে","root":"—","lemma":"مِن\r","grammar_bn":"অব্যয় (Preposition)"},{"id":51797,"position":2,"text_uthmani":"خَلَقْنَـٰكُمْ","transliteration":"khalaqnākum","translation_bn":"তোমাদের আমরা সৃষ্টি করেছি","root":"خلق","lemma":"خَلَقَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":51798,"position":3,"text_uthmani":"وَفِيهَا","transliteration":"wafīhā","translation_bn":"ও তার মধ্যে","root":"—","lemma":"فِى\r","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":51799,"position":4,"text_uthmani":"نُعِيدُكُمْ","transliteration":"nuʿīdukum","translation_bn":"তোমাদের ফিরিয়ে আনবো আমরা","root":"عود","lemma":"أُعِيدُ","grammar_bn":"ক্রিয়া (Verb)"},{"id":51800,"position":5,"text_uthmani":"وَمِنْهَا","transliteration":"wamin''hā","translation_bn":"এবং তার মধ্য হ''তে","root":"—","lemma":"مِن\r","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":51801,"position":6,"text_uthmani":"نُخْرِجُكُمْ","transliteration":"nukh''rijukum","translation_bn":"তোমাদের বের করবো আমরা","root":"خرج","lemma":"أَخْرَجَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":51802,"position":7,"text_uthmani":"تَارَةً","transliteration":"tāratan","translation_bn":"একবার","root":"تور","lemma":"تَارَة","grammar_bn":"বিশেষ্য (Noun)"},{"id":51803,"position":8,"text_uthmani":"أُخْرَىٰ","transliteration":"ukh''rā","translation_bn":"আরও","root":"اخر","lemma":"ا^خَر","grammar_bn":"বিশেষণ (Adjective)"},{"id":51804,"position":9,"text_uthmani":"٥٥","transliteration":"","translation_bn":"(৫৫)","root":"—","lemma":"٥٥","grammar_bn":"মার্কার"}]'::jsonb, 'min''hā khalaqnākum wafīhā nuʿīdukum wamin''hā nukh''rijukum tāratan ukh''rā', 'মাটি থেকে আমি তোমাদেরকে সৃষ্টি করেছি, তাতেই আমি তোমাদেরকে ফিরিয়ে নেব, আর তাত্থেকে তোমাদেরকে আবার বের করব।', 'From the earth We created you, and into it We will return you, and from it We will extract you another time.', 'মাটি থেকে আমি তোমাদেরকে সৃষ্টি করেছি, তাতেই আমি তোমাদেরকে ফিরিয়ে নেব, আর তাত্থেকে তোমাদেরকে আবার বের করব।', 'From the earth We created you, and into it We will return you, and from it We will extract you another time.', NULL, NULL, NULL, NULL, NULL, 'https://everyayah.com/data/Alafasy_128kbps/020055.mp3', now()),
  (20, 56, '', '[{"id":52339,"position":1,"text_uthmani":"وَلَقَدْ","transliteration":"walaqad","translation_bn":"এবং নিশ্চয়ই","root":"—","lemma":"قَد\r","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":52340,"position":2,"text_uthmani":"أَرَيْنَـٰهُ","transliteration":"araynāhu","translation_bn":"(ফিরআউনকে) তাকে আমরা দেখিয়েছি","root":"راي","lemma":"أَرَيْ","grammar_bn":"ক্রিয়া (Verb)"},{"id":52341,"position":3,"text_uthmani":"ءَايَـٰتِنَا","transliteration":"āyātinā","translation_bn":"আমাদের নিদর্শনাবলী","root":"ايي","lemma":"ءَايَة","grammar_bn":"বিশেষ্য (Noun)"},{"id":52342,"position":4,"text_uthmani":"كُلَّهَا","transliteration":"kullahā","translation_bn":"তা সবই","root":"كلل","lemma":"كُلّ","grammar_bn":"বিশেষ্য (Noun)"},{"id":52343,"position":5,"text_uthmani":"فَكَذَّبَ","transliteration":"fakadhaba","translation_bn":"কিন্তু সে মিথ্যারোপ করেছে","root":"كذب","lemma":"كَذَّبَ","grammar_bn":"শব্দ"},{"id":52344,"position":6,"text_uthmani":"وَأَبَىٰ","transliteration":"wa-abā","translation_bn":"ও অমান্য করেছে","root":"ابي","lemma":"أَبَى","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":52345,"position":7,"text_uthmani":"٥٦","transliteration":"","translation_bn":"(৫৬)","root":"—","lemma":"٥٦","grammar_bn":"মার্কার"}]'::jsonb, 'walaqad araynāhu āyātinā kullahā fakadhaba wa-abā', 'আমি তাকে (অর্থাৎ ফেরাউনকে) আমার যাবতীয় নিদর্শন দেখিয়েছিলাম কিন্তু সে মিথ্যে মনে ক’রে প্রত্যাখ্যান করেছে ও অমান্য করেছে।', 'And We certainly showed Pharaoh Our signs - all of them - but he denied and refused.', 'আমি তাকে (অর্থাৎ ফেরাউনকে) আমার যাবতীয় নিদর্শন দেখিয়েছিলাম কিন্তু সে মিথ্যে মনে ক’রে প্রত্যাখ্যান করেছে ও অমান্য করেছে।', 'And We certainly showed Pharaoh Our signs - all of them - but he denied and refused.', NULL, NULL, NULL, NULL, NULL, 'https://everyayah.com/data/Alafasy_128kbps/020056.mp3', now()),
  (20, 57, '', '[{"id":52753,"position":1,"text_uthmani":"قَالَ","transliteration":"qāla","translation_bn":"(ফিরআউন) বললো","root":"قول","lemma":"قَالَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":52754,"position":2,"text_uthmani":"أَجِئْتَنَا","transliteration":"aji''tanā","translation_bn":"\"আমাদের কাছে তুমি এসেছ কি","root":"جيا","lemma":"جَا^ءَ","grammar_bn":"প্রশ্নবোধক (Interrogative)"},{"id":52755,"position":3,"text_uthmani":"لِتُخْرِجَنَا","transliteration":"litukh''rijanā","translation_bn":"আমাদের তুমি বের করার জন্যে","root":"خرج","lemma":"أَخْرَجَ","grammar_bn":"শব্দ"},{"id":52756,"position":4,"text_uthmani":"مِنْ","transliteration":"min","translation_bn":"থেকে","root":"—","lemma":"مِن\r","grammar_bn":"অব্যয় (Preposition)"},{"id":52757,"position":5,"text_uthmani":"أَرْضِنَا","transliteration":"arḍinā","translation_bn":"আমাদের দেশ","root":"ارض","lemma":"أَرْض","grammar_bn":"বিশেষ্য (Noun)"},{"id":52758,"position":6,"text_uthmani":"بِسِحْرِكَ","transliteration":"bisiḥ''rika","translation_bn":"তোমার জাদুর বলে","root":"سحر","lemma":"سِحْر","grammar_bn":"অব্যয় (Preposition)"},{"id":52759,"position":7,"text_uthmani":"يَـٰمُوسَىٰ","transliteration":"yāmūsā","translation_bn":"হে মূসা","root":"—","lemma":"مُوسَىٰ","grammar_bn":"সম্বোধন পদ (Vocative)"},{"id":52760,"position":8,"text_uthmani":"٥٧","transliteration":"","translation_bn":"(৫৭)","root":"—","lemma":"٥٧","grammar_bn":"মার্কার"}]'::jsonb, 'qāla aji''tanā litukh''rijanā min arḍinā bisiḥ''rika yāmūsā', 'সে বলল, ‘হে মূসা! তুমি কি তোমার যাদুর বলে আমাদেরকে আমাদের দেশ থেকে বের করে দেয়ার জন্য এসেছ?', 'He said, "Have you come to us to drive us out of our land with your magic, O Moses?', 'সে বলল, ‘হে মূসা! তুমি কি তোমার যাদুর বলে আমাদেরকে আমাদের দেশ থেকে বের করে দেয়ার জন্য এসেছ?', 'He said, "Have you come to us to drive us out of our land with your magic, O Moses?', NULL, NULL, NULL, NULL, NULL, 'https://everyayah.com/data/Alafasy_128kbps/020057.mp3', now()),
  (20, 58, '', '[{"id":53401,"position":1,"text_uthmani":"فَلَنَأْتِيَنَّكَ","transliteration":"falanatiyannaka","translation_bn":"সুতরাং আমরা তোমার কাছে অবশ্যই আসবো","root":"اتي","lemma":"أَتَى","grammar_bn":"শব্দ"},{"id":53402,"position":2,"text_uthmani":"بِسِحْرٍۢ","transliteration":"bisiḥ''rin","translation_bn":"জাদু নিয়ে","root":"سحر","lemma":"سِحْر","grammar_bn":"অব্যয় (Preposition)"},{"id":53403,"position":3,"text_uthmani":"مِّثْلِهِۦ","transliteration":"mith''lihi","translation_bn":"তার অনুরূপ","root":"مثل","lemma":"مِثْل","grammar_bn":"বিশেষ্য (Noun)"},{"id":53404,"position":4,"text_uthmani":"فَٱجْعَلْ","transliteration":"fa-ij''ʿal","translation_bn":"অতএব স্থির করো","root":"جعل","lemma":"جَعَلَ","grammar_bn":"শব্দ"},{"id":53405,"position":5,"text_uthmani":"بَيْنَنَا","transliteration":"baynanā","translation_bn":"আমাদের মাঝে","root":"بين","lemma":"بَيْن","grammar_bn":"স্থানবাচক (Location)"},{"id":53406,"position":6,"text_uthmani":"وَبَيْنَكَ","transliteration":"wabaynaka","translation_bn":"ও তোমার মাঝে","root":"بين","lemma":"بَيْن","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":53407,"position":7,"text_uthmani":"مَوْعِدًۭا","transliteration":"mawʿidan","translation_bn":"নির্দিষ্ট সময়","root":"وعد","lemma":"مَّوْعِد","grammar_bn":"বিশেষ্য (Noun)"},{"id":53408,"position":8,"text_uthmani":"لَّا","transliteration":"lā","translation_bn":"না","root":"—","lemma":"لَا\r","grammar_bn":"না-বোধক (Negative)"},{"id":53409,"position":9,"text_uthmani":"نُخْلِفُهُۥ","transliteration":"nukh''lifuhu","translation_bn":"তা আমরা ব্যতিক্রম করবো","root":"خلف","lemma":"أَخْلَفُ","grammar_bn":"ক্রিয়া (Verb)"},{"id":53410,"position":10,"text_uthmani":"نَحْنُ","transliteration":"naḥnu","translation_bn":"(না) আমরা","root":"—","lemma":"نَحْنُ","grammar_bn":"সর্বনাম (Pronoun)"},{"id":53411,"position":11,"text_uthmani":"وَلَآ","transliteration":"walā","translation_bn":"আর না","root":"—","lemma":"لَا\r","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":53412,"position":12,"text_uthmani":"أَنتَ","transliteration":"anta","translation_bn":"তুমি","root":"—","lemma":"أَنتَ","grammar_bn":"সর্বনাম (Pronoun)"},{"id":53413,"position":13,"text_uthmani":"مَكَانًۭا","transliteration":"makānan","translation_bn":"প্রান্তর","root":"كون","lemma":"مَّكَان","grammar_bn":"বিশেষ্য (Noun)"},{"id":53414,"position":14,"text_uthmani":"سُوًۭى","transliteration":"suwan","translation_bn":"সমতল\"","root":"سوي","lemma":"سُوًى","grammar_bn":"বিশেষণ (Adjective)"},{"id":53415,"position":15,"text_uthmani":"٥٨","transliteration":"","translation_bn":"(৫৮)","root":"—","lemma":"٥٨","grammar_bn":"মার্কার"}]'::jsonb, 'falanatiyannaka bisiḥ''rin mith''lihi fa-ij''ʿal baynanā wabaynaka mawʿidan lā nukh''lifuhu naḥnu walā anta makānan suwan', 'তাহলে আমরাও অবশ্য অবশ্যই তোমার কাছে অনুরূপ যাদু হাযির করব, কাজেই একটা মধ্যবর্তী স্থানে আমাদের ও তোমাদের মিলিত হওয়ার জন্য একটা নির্দিষ্ট সময় নির্ধারণ কর যার খেলাফ আমরাও করব না, আর তুমিও করবে না।’', 'Then we will surely bring you magic like it, so make between us and you an appointment, which we will not fail to keep and neither will you, in a place assigned."', 'তাহলে আমরাও অবশ্য অবশ্যই তোমার কাছে অনুরূপ যাদু হাযির করব, কাজেই একটা মধ্যবর্তী স্থানে আমাদের ও তোমাদের মিলিত হওয়ার জন্য একটা নির্দিষ্ট সময় নির্ধারণ কর যার খেলাফ আমরাও করব না, আর তুমিও করবে না।’', 'Then we will surely bring you magic like it, so make between us and you an appointment, which we will not fail to keep and neither will you, in a place assigned."', NULL, NULL, NULL, NULL, NULL, 'https://everyayah.com/data/Alafasy_128kbps/020058.mp3', now()),
  (20, 59, '', '[{"id":53864,"position":1,"text_uthmani":"قَالَ","transliteration":"qāla","translation_bn":"(মূসা) বললো","root":"قول","lemma":"قَالَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":53865,"position":2,"text_uthmani":"مَوْعِدُكُمْ","transliteration":"mawʿidukum","translation_bn":"\"নির্দিষ্ট সময় তোমাদের","root":"وعد","lemma":"مَّوْعِد","grammar_bn":"বিশেষ্য (Noun)"},{"id":53866,"position":3,"text_uthmani":"يَوْمُ","transliteration":"yawmu","translation_bn":"দিন","root":"يوم","lemma":"يَوْم","grammar_bn":"বিশেষ্য (Noun)"},{"id":53867,"position":4,"text_uthmani":"ٱلزِّينَةِ","transliteration":"l-zīnati","translation_bn":"উৎসবের","root":"زين","lemma":"زِينَة","grammar_bn":"শব্দ"},{"id":53868,"position":5,"text_uthmani":"وَأَن","transliteration":"wa-an","translation_bn":"এবং (এও) যে","root":"—","lemma":"أَن\r","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":53869,"position":6,"text_uthmani":"يُحْشَرَ","transliteration":"yuḥ''shara","translation_bn":"জমায়েত হবে","root":"حشر","lemma":"حَشَرَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":53870,"position":7,"text_uthmani":"ٱلنَّاسُ","transliteration":"l-nāsu","translation_bn":"জনতা","root":"نوس","lemma":"نَّاس","grammar_bn":"শব্দ"},{"id":53871,"position":8,"text_uthmani":"ضُحًۭى","transliteration":"ḍuḥan","translation_bn":"সূর্যোদয়ের সাথে\"","root":"ضحو","lemma":"ضُحًى","grammar_bn":"কালবাচক (Time)"},{"id":53872,"position":9,"text_uthmani":"٥٩","transliteration":"","translation_bn":"(৫৯)","root":"—","lemma":"٥٩","grammar_bn":"মার্কার"}]'::jsonb, 'qāla mawʿidukum yawmu l-zīnati wa-an yuḥ''shara l-nāsu ḍuḥan', 'মূসা বলল, ‘তোমাদের (সঙ্গে) ওয়া‘দার নির্ধারিত সময় হল উৎসবের দিন আর দুপুরের আগেই মানুষ যেন পৌঁছে যায়।’', '[Moses] said, "Your appointment is on the day of the festival when the people assemble at mid-morning."', 'মূসা বলল, ‘তোমাদের (সঙ্গে) ওয়া‘দার নির্ধারিত সময় হল উৎসবের দিন আর দুপুরের আগেই মানুষ যেন পৌঁছে যায়।’', '[Moses] said, "Your appointment is on the day of the festival when the people assemble at mid-morning."', NULL, NULL, NULL, NULL, NULL, 'https://everyayah.com/data/Alafasy_128kbps/020059.mp3', now()),
  (20, 60, '', '[{"id":54547,"position":1,"text_uthmani":"فَتَوَلَّىٰ","transliteration":"fatawallā","translation_bn":"অতঃপর চলে গেলো","root":"ولي","lemma":"تَوَلَّىٰ","grammar_bn":"শব্দ"},{"id":54548,"position":2,"text_uthmani":"فِرْعَوْنُ","transliteration":"fir''ʿawnu","translation_bn":"ফিরআউন","root":"—","lemma":"فِرْعَوْن","grammar_bn":"নামবাচক বিশেষ্য (Proper Noun)"},{"id":54549,"position":3,"text_uthmani":"فَجَمَعَ","transliteration":"fajamaʿa","translation_bn":"অতঃপর একত্র করলো","root":"جمع","lemma":"جَمَعَ","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":54550,"position":4,"text_uthmani":"كَيْدَهُۥ","transliteration":"kaydahu","translation_bn":"তার কলাকৌশল","root":"كيد","lemma":"كَيْد","grammar_bn":"বিশেষ্য (Noun)"},{"id":54551,"position":5,"text_uthmani":"ثُمَّ","transliteration":"thumma","translation_bn":"এরপর","root":"—","lemma":"ثُمّ\r","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":54552,"position":6,"text_uthmani":"أَتَىٰ","transliteration":"atā","translation_bn":"আসলো","root":"اتي","lemma":"أَتَى","grammar_bn":"ক্রিয়া (Verb)"},{"id":54553,"position":7,"text_uthmani":"٦٠","transliteration":"","translation_bn":"(৬০)","root":"—","lemma":"٦٠","grammar_bn":"মার্কার"}]'::jsonb, 'fatawallā fir''ʿawnu fajamaʿa kaydahu thumma atā', 'তখন ফেরাউন উঠে গেল, অতঃপর তার কলা-কৌশল একত্র করল, তারপর ফিরে এল।', 'So Pharaoh went away, put together his plan, and then came [to Moses].', 'তখন ফেরাউন উঠে গেল, অতঃপর তার কলা-কৌশল একত্র করল, তারপর ফিরে এল।', 'So Pharaoh went away, put together his plan, and then came [to Moses].', NULL, NULL, NULL, NULL, NULL, 'https://everyayah.com/data/Alafasy_128kbps/020060.mp3', now()),
  (20, 61, '', '[{"id":55072,"position":1,"text_uthmani":"قَالَ","transliteration":"qāla","translation_bn":"বললো","root":"قول","lemma":"قَالَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":55073,"position":2,"text_uthmani":"لَهُم","transliteration":"lahum","translation_bn":"তাদেরকে","root":"—","lemma":"لَهُم","grammar_bn":"অব্যয় (Preposition)"},{"id":55074,"position":3,"text_uthmani":"مُّوسَىٰ","transliteration":"mūsā","translation_bn":"মূসা","root":"—","lemma":"مُوسَىٰ","grammar_bn":"নামবাচক বিশেষ্য (Proper Noun)"},{"id":55075,"position":4,"text_uthmani":"وَيْلَكُمْ","transliteration":"waylakum","translation_bn":"\"তোমাদের জন্যে দুর্ভোগ","root":"—","lemma":"وَيْل","grammar_bn":"বিশেষ্য (Noun)"},{"id":55076,"position":5,"text_uthmani":"لَا","transliteration":"lā","translation_bn":"না","root":"—","lemma":"لَا\r","grammar_bn":"নিষেধবাচক (Prohibition)"},{"id":55077,"position":6,"text_uthmani":"تَفْتَرُوا۟","transliteration":"taftarū","translation_bn":"তোমরা আরোপ করো","root":"فري","lemma":"ٱفْتَرَىٰ","grammar_bn":"ক্রিয়া (Verb)"},{"id":55078,"position":7,"text_uthmani":"عَلَى","transliteration":"ʿalā","translation_bn":"প্রতি","root":"—","lemma":"عَلَىٰ\r","grammar_bn":"অব্যয় (Preposition)"},{"id":55079,"position":8,"text_uthmani":"ٱللَّهِ","transliteration":"l-lahi","translation_bn":"আল্লাহর","root":"اله","lemma":"ٱللَّه","grammar_bn":"নামবাচক বিশেষ্য (Proper Noun)"},{"id":55080,"position":9,"text_uthmani":"كَذِبًۭا","transliteration":"kadhiban","translation_bn":"মিথ্যা","root":"كذب","lemma":"كَذِب","grammar_bn":"বিশেষ্য (Noun)"},{"id":55081,"position":10,"text_uthmani":"فَيُسْحِتَكُم","transliteration":"fayus''ḥitakum","translation_bn":"তাহ''লে তোমাদের  ধ্বংস করে দিবেন","root":"سحت","lemma":"يُسْحِتَ","grammar_bn":"কারণবাচক (Cause)"},{"id":55082,"position":11,"text_uthmani":"بِعَذَابٍۢ ۖ","transliteration":"biʿadhābin","translation_bn":"শাস্তি দিয়ে","root":"عذب","lemma":"عَذَاب","grammar_bn":"অব্যয় (Preposition)"},{"id":55084,"position":12,"text_uthmani":"وَقَدْ","transliteration":"waqad","translation_bn":"এবং নিশ্চয়ই","root":"—","lemma":"قَد\r","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":55085,"position":13,"text_uthmani":"خَابَ","transliteration":"khāba","translation_bn":"ব্যর্থ হয়েছে","root":"خيب","lemma":"خَابَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":55086,"position":14,"text_uthmani":"مَنِ","transliteration":"mani","translation_bn":"(সে) যে","root":"—","lemma":"مَن\r","grammar_bn":"সাপেক্ষ সর্বনাম (Relative)"},{"id":55087,"position":15,"text_uthmani":"ٱفْتَرَىٰ","transliteration":"if''tarā","translation_bn":"মিথ্যা রচনা করেছে\"","root":"فري","lemma":"ٱفْتَرَىٰ","grammar_bn":"ক্রিয়া (Verb)"},{"id":55088,"position":16,"text_uthmani":"٦١","transliteration":"","translation_bn":"(৬১)","root":"—","lemma":"٦١","grammar_bn":"মার্কার"}]'::jsonb, 'qāla lahum mūsā waylakum lā taftarū ʿalā l-lahi kadhiban fayus''ḥitakum biʿadhābin waqad khāba mani if''tarā', 'মূসা তাদেরকে বলল, ‘হায় তোমাদের দুর্ভাগ্য! তোমরা আল্লাহর প্রতি মিথ্যে আরোপ করো না, করলে তিনি তোমাদেরকে ভয়ানক শাস্তি দ্বারা ধ্বংস করে দেবেন। যে মিথ্যে আরোপ করে সে-ই ব্যর্থ হয়।’', 'Moses said to the magicians summoned by Pharaoh, "Woe to you! Do not invent a lie against Allah or He will exterminate you with a punishment; and he has failed who invents [such falsehood]."', 'মূসা তাদেরকে বলল, ‘হায় তোমাদের দুর্ভাগ্য! তোমরা আল্লাহর প্রতি মিথ্যে আরোপ করো না, করলে তিনি তোমাদেরকে ভয়ানক শাস্তি দ্বারা ধ্বংস করে দেবেন। যে মিথ্যে আরোপ করে সে-ই ব্যর্থ হয়।’', 'Moses said to the magicians summoned by Pharaoh, "Woe to you! Do not invent a lie against Allah or He will exterminate you with a punishment; and he has failed who invents [such falsehood]."', NULL, NULL, NULL, NULL, NULL, 'https://everyayah.com/data/Alafasy_128kbps/020061.mp3', now()),
  (20, 62, '', '[{"id":55670,"position":1,"text_uthmani":"فَتَنَـٰزَعُوٓا۟","transliteration":"fatanāzaʿū","translation_bn":"অতঃপর তারা মতবিরোধ করলো","root":"نزع","lemma":"تَنَٰزَعُ","grammar_bn":"শব্দ"},{"id":55671,"position":2,"text_uthmani":"أَمْرَهُم","transliteration":"amrahum","translation_bn":"কাজে তাদের","root":"امر","lemma":"أَمْر","grammar_bn":"বিশেষ্য (Noun)"},{"id":55672,"position":3,"text_uthmani":"بَيْنَهُمْ","transliteration":"baynahum","translation_bn":"মাঝে তাদের","root":"بين","lemma":"بَيْن","grammar_bn":"স্থানবাচক (Location)"},{"id":55673,"position":4,"text_uthmani":"وَأَسَرُّوا۟","transliteration":"wa-asarrū","translation_bn":"এবং গোপনে করলো","root":"سرر","lemma":"أَسَرَّ","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":55674,"position":5,"text_uthmani":"ٱلنَّجْوَىٰ","transliteration":"l-najwā","translation_bn":"পরামর্শ","root":"نجو","lemma":"نَجْوَىٰ^","grammar_bn":"শব্দ"},{"id":55675,"position":6,"text_uthmani":"٦٢","transliteration":"","translation_bn":"(৬২)","root":"—","lemma":"٦٢","grammar_bn":"মার্কার"}]'::jsonb, 'fatanāzaʿū amrahum baynahum wa-asarrū l-najwā', 'তখন তারা তাদের কাজ-কর্ম নিয়ে নিজেদের মধ্যে বাদানুবাদ করল আর তারা গোপনে পরামর্শ করল।', 'So they disputed over their affair among themselves and concealed their private conversation.', 'তখন তারা তাদের কাজ-কর্ম নিয়ে নিজেদের মধ্যে বাদানুবাদ করল আর তারা গোপনে পরামর্শ করল।', 'So they disputed over their affair among themselves and concealed their private conversation.', NULL, NULL, NULL, NULL, NULL, 'https://everyayah.com/data/Alafasy_128kbps/020062.mp3', now()),
  (20, 63, '', '[{"id":56079,"position":1,"text_uthmani":"قَالُوٓا۟","transliteration":"qālū","translation_bn":"(অবশেষে কিছু লোক) বললো","root":"قول","lemma":"قَالَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":56080,"position":2,"text_uthmani":"إِنْ","transliteration":"in","translation_bn":"\"নিশ্চয়ই","root":"—","lemma":"إِن\r","grammar_bn":"নিশ্চয়তাবোধক (Certainty)"},{"id":56081,"position":3,"text_uthmani":"هَـٰذَٰنِ","transliteration":"hādhāni","translation_bn":"এ দু''জন","root":"—","lemma":"هَٰذَٰن","grammar_bn":"নির্দেশক সর্বনাম (Demonstrative)"},{"id":56082,"position":4,"text_uthmani":"لَسَـٰحِرَٰنِ","transliteration":"lasāḥirāni","translation_bn":"অবশ্যই দুই জাদুকর","root":"سحر","lemma":"سَٰحِر","grammar_bn":"দৃঢ়তাবোধক (Emphatic)"},{"id":56083,"position":5,"text_uthmani":"يُرِيدَانِ","transliteration":"yurīdāni","translation_bn":"দু''জনে চায়","root":"رود","lemma":"أَرَادَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":56084,"position":6,"text_uthmani":"أَن","transliteration":"an","translation_bn":"যে","root":"—","lemma":"أَن\r","grammar_bn":"অধীনস্থ যোজক (Subordinating)"},{"id":56085,"position":7,"text_uthmani":"يُخْرِجَاكُم","transliteration":"yukh''rijākum","translation_bn":"দু''জনে বের করে দিবে তোমাদেরকে","root":"خرج","lemma":"أَخْرَجَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":56086,"position":8,"text_uthmani":"مِّنْ","transliteration":"min","translation_bn":"থেকে","root":"—","lemma":"مِن\r","grammar_bn":"অব্যয় (Preposition)"},{"id":56087,"position":9,"text_uthmani":"أَرْضِكُم","transliteration":"arḍikum","translation_bn":"তোমাদের দেশ","root":"ارض","lemma":"أَرْض","grammar_bn":"বিশেষ্য (Noun)"},{"id":56088,"position":10,"text_uthmani":"بِسِحْرِهِمَا","transliteration":"bisiḥ''rihimā","translation_bn":"জাদুর বলে তাদের দু''জনের","root":"سحر","lemma":"سِحْر","grammar_bn":"অব্যয় (Preposition)"},{"id":56089,"position":11,"text_uthmani":"وَيَذْهَبَا","transliteration":"wayadhhabā","translation_bn":"এবং দু''জনে যাবে (নসাৎ করবে)","root":"ذهب","lemma":"ذَهَبَ","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":56090,"position":12,"text_uthmani":"بِطَرِيقَتِكُمُ","transliteration":"biṭarīqatikumu","translation_bn":"নিয়ে তোমাদের জীবন ব্যবস্থাকে","root":"طرق","lemma":"طَرِيقَة","grammar_bn":"অব্যয় (Preposition)"},{"id":56091,"position":13,"text_uthmani":"ٱلْمُثْلَىٰ","transliteration":"l-muth''lā","translation_bn":"(যা হলো) আদর্শ","root":"مثل","lemma":"مُثْلَىٰ","grammar_bn":"শব্দ"},{"id":56092,"position":14,"text_uthmani":"٦٣","transliteration":"","translation_bn":"(৬৩)","root":"—","lemma":"٦٣","grammar_bn":"মার্কার"}]'::jsonb, 'qālū in hādhāni lasāḥirāni yurīdāni an yukh''rijākum min arḍikum bisiḥ''rihimā wayadhhabā biṭarīqatikumu l-muth''lā', 'তারা বলল, ‘এ দু’জন নিশ্চিতই যাদুকর, তারা তাদের যাদুর বলে তোমাদেরকে তোমাদের দেশ থেকে বের করে দিতে চায় আর তোমাদের উৎকৃষ্ট জীবন পদ্ধতি মুছে ফেলতে চায়।', 'They said, "Indeed, these are two magicians who want to drive you out of your land with their magic and do away with your most exemplary way.', 'তারা বলল, ‘এ দু’জন নিশ্চিতই যাদুকর, তারা তাদের যাদুর বলে তোমাদেরকে তোমাদের দেশ থেকে বের করে দিতে চায় আর তোমাদের উৎকৃষ্ট জীবন পদ্ধতি মুছে ফেলতে চায়।', 'They said, "Indeed, these are two magicians who want to drive you out of your land with their magic and do away with your most exemplary way.', NULL, NULL, NULL, NULL, NULL, 'https://everyayah.com/data/Alafasy_128kbps/020063.mp3', now()),
  (20, 64, '', '[{"id":56583,"position":1,"text_uthmani":"فَأَجْمِعُوا۟","transliteration":"fa-ajmiʿū","translation_bn":"সুতরাং তোমরা একত্র করো","root":"جمع","lemma":"أَجْمَعُ","grammar_bn":"শব্দ"},{"id":56584,"position":2,"text_uthmani":"كَيْدَكُمْ","transliteration":"kaydakum","translation_bn":"কলাকৌশল তোমাদের","root":"كيد","lemma":"كَيْد","grammar_bn":"বিশেষ্য (Noun)"},{"id":56585,"position":3,"text_uthmani":"ثُمَّ","transliteration":"thumma","translation_bn":"এরপর","root":"—","lemma":"ثُمّ\r","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":56586,"position":4,"text_uthmani":"ٱئْتُوا۟","transliteration":"i''tū","translation_bn":"আসো","root":"اتي","lemma":"أَتَى","grammar_bn":"ক্রিয়া (Verb)"},{"id":56587,"position":5,"text_uthmani":"صَفًّۭا ۚ","transliteration":"ṣaffan","translation_bn":"সারি বেঁধে (একত্রিত হয়ে)","root":"صفف","lemma":"صَفّ","grammar_bn":"বিশেষ্য (Noun)"},{"id":56589,"position":6,"text_uthmani":"وَقَدْ","transliteration":"waqad","translation_bn":"এবং নিশ্চয়ই","root":"—","lemma":"قَد\r","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":56590,"position":7,"text_uthmani":"أَفْلَحَ","transliteration":"aflaḥa","translation_bn":"সফল হবে","root":"فلح","lemma":"أَفْلَحَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":56591,"position":8,"text_uthmani":"ٱلْيَوْمَ","transliteration":"l-yawma","translation_bn":"আজ","root":"يوم","lemma":"يَوْم","grammar_bn":"শব্দ"},{"id":56592,"position":9,"text_uthmani":"مَنِ","transliteration":"mani","translation_bn":"যে","root":"—","lemma":"مَن\r","grammar_bn":"সাপেক্ষ সর্বনাম (Relative)"},{"id":56593,"position":10,"text_uthmani":"ٱسْتَعْلَىٰ","transliteration":"is''taʿlā","translation_bn":"প্রাধান্য বিস্তার করবে\"","root":"علو","lemma":"ٱسْتَعْلَىٰ","grammar_bn":"ক্রিয়া (Verb)"},{"id":56594,"position":11,"text_uthmani":"٦٤","transliteration":"","translation_bn":"(৬৪)","root":"—","lemma":"٦٤","grammar_bn":"মার্কার"}]'::jsonb, 'fa-ajmiʿū kaydakum thumma i''tū ṣaffan waqad aflaḥa l-yawma mani is''taʿlā', 'কাজেই তোমরা তোমাদের কলা-কৌশল একত্রিত কর, অতঃপর সারিবদ্ধ হয়ে হাজির হয়ে যাও। আজ যে বিজয় লাভ করবে, সে-ই (বরাবর) সফল হবে।’', 'So resolve upon your plan and then come [forward] in line. And he has succeeded today who overcomes."', 'কাজেই তোমরা তোমাদের কলা-কৌশল একত্রিত কর, অতঃপর সারিবদ্ধ হয়ে হাজির হয়ে যাও। আজ যে বিজয় লাভ করবে, সে-ই (বরাবর) সফল হবে।’', 'So resolve upon your plan and then come [forward] in line. And he has succeeded today who overcomes."', NULL, NULL, NULL, NULL, NULL, 'https://everyayah.com/data/Alafasy_128kbps/020064.mp3', now()),
  (20, 65, '', '[{"id":57178,"position":1,"text_uthmani":"قَالُوا۟","transliteration":"qālū","translation_bn":"(জাদুকররা) বললো","root":"قول","lemma":"قَالَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":57179,"position":2,"text_uthmani":"يَـٰمُوسَىٰٓ","transliteration":"yāmūsā","translation_bn":"\"হে মূসা","root":"—","lemma":"مُوسَىٰ","grammar_bn":"সম্বোধন পদ (Vocative)"},{"id":57180,"position":3,"text_uthmani":"إِمَّآ","transliteration":"immā","translation_bn":"হয়","root":"—","lemma":"إِمَّا\r","grammar_bn":"শব্দ"},{"id":57181,"position":4,"text_uthmani":"أَن","transliteration":"an","translation_bn":"যে","root":"—","lemma":"أَن\r","grammar_bn":"অধীনস্থ যোজক (Subordinating)"},{"id":57182,"position":5,"text_uthmani":"تُلْقِىَ","transliteration":"tul''qiya","translation_bn":"তুমি নিক্ষেপ করবে","root":"لقي","lemma":"أَلْقَىٰ^","grammar_bn":"ক্রিয়া (Verb)"},{"id":57183,"position":6,"text_uthmani":"وَإِمَّآ","transliteration":"wa-immā","translation_bn":"আর (না) হয়","root":"—","lemma":"إِمَّا\r","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":57184,"position":7,"text_uthmani":"أَن","transliteration":"an","translation_bn":"যে","root":"—","lemma":"أَن\r","grammar_bn":"অধীনস্থ যোজক (Subordinating)"},{"id":57185,"position":8,"text_uthmani":"نَّكُونَ","transliteration":"nakūna","translation_bn":"আমরা হবো","root":"كون","lemma":"كَانَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":57186,"position":9,"text_uthmani":"أَوَّلَ","transliteration":"awwala","translation_bn":"প্রথম","root":"اول","lemma":"أَوَّل","grammar_bn":"বিশেষ্য (Noun)"},{"id":57187,"position":10,"text_uthmani":"مَنْ","transliteration":"man","translation_bn":"যে","root":"—","lemma":"مَن\r","grammar_bn":"সাপেক্ষ সর্বনাম (Relative)"},{"id":57188,"position":11,"text_uthmani":"أَلْقَىٰ","transliteration":"alqā","translation_bn":"নিক্ষেপ করবে\"","root":"لقي","lemma":"أَلْقَىٰ^","grammar_bn":"ক্রিয়া (Verb)"},{"id":57189,"position":12,"text_uthmani":"٦٥","transliteration":"","translation_bn":"(৬৫)","root":"—","lemma":"٦٥","grammar_bn":"মার্কার"}]'::jsonb, 'qālū yāmūsā immā an tul''qiya wa-immā an nakūna awwala man alqā', 'তারা বলল, ‘হে মূসা! তুমিই (প্রথমে) নিক্ষেপ করবে, না আমরাই প্রথমে নিক্ষেপ করব?’', 'They said, "O Moses, either you throw or we will be the first to throw."', 'তারা বলল, ‘হে মূসা! তুমিই (প্রথমে) নিক্ষেপ করবে, না আমরাই প্রথমে নিক্ষেপ করব?’', 'They said, "O Moses, either you throw or we will be the first to throw."', NULL, NULL, NULL, NULL, NULL, 'https://everyayah.com/data/Alafasy_128kbps/020065.mp3', now()),
