  (20, 67, '', '[{"id":58115,"position":1,"text_uthmani":"فَأَوْجَسَ","transliteration":"fa-awjasa","translation_bn":"অতঃপর অনুভব করলো","root":"وجس","lemma":"أَوْجَسَ","grammar_bn":"শব্দ"},{"id":58116,"position":2,"text_uthmani":"فِى","transliteration":"fī","translation_bn":"মধ্যে","root":"—","lemma":"فِى\r","grammar_bn":"অব্যয় (Preposition)"},{"id":58117,"position":3,"text_uthmani":"نَفْسِهِۦ","transliteration":"nafsihi","translation_bn":"তার নিজের","root":"نفس","lemma":"نَفْس","grammar_bn":"বিশেষ্য (Noun)"},{"id":58118,"position":4,"text_uthmani":"خِيفَةًۭ","transliteration":"khīfatan","translation_bn":"ভয়","root":"خوف","lemma":"خِيفَة","grammar_bn":"বিশেষ্য (Noun)"},{"id":58119,"position":5,"text_uthmani":"مُّوسَىٰ","transliteration":"mūsā","translation_bn":"মূসা (নিজেও)","root":"—","lemma":"مُوسَىٰ","grammar_bn":"নামবাচক বিশেষ্য (Proper Noun)"},{"id":58120,"position":6,"text_uthmani":"٦٧","transliteration":"","translation_bn":"(৬৭)","root":"—","lemma":"٦٧","grammar_bn":"মার্কার"}]'::jsonb, 'fa-awjasa fī nafsihi khīfatan mūsā', 'তখন মূসা তার মনে ভীতি অনুভব করল।', 'And he sensed within himself apprehension, did Moses.', 'তখন মূসা তার মনে ভীতি অনুভব করল।', 'And he sensed within himself apprehension, did Moses.', NULL, NULL, NULL, NULL, NULL, 'https://everyayah.com/data/Alafasy_128kbps/020067.mp3', now()),
  (20, 68, '', '[{"id":58533,"position":1,"text_uthmani":"قُلْنَا","transliteration":"qul''nā","translation_bn":"আমরা বললাম","root":"قول","lemma":"قَالَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":58534,"position":2,"text_uthmani":"لَا","transliteration":"lā","translation_bn":"\"না","root":"—","lemma":"لَا\r","grammar_bn":"নিষেধবাচক (Prohibition)"},{"id":58535,"position":3,"text_uthmani":"تَخَفْ","transliteration":"takhaf","translation_bn":"ভয় করো","root":"خوف","lemma":"خَافَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":58536,"position":4,"text_uthmani":"إِنَّكَ","transliteration":"innaka","translation_bn":"তুমি নিশ্চয়ই","root":"—","lemma":"إِنّ","grammar_bn":"অভিঘাত পদ (Accusative)"},{"id":58537,"position":5,"text_uthmani":"أَنتَ","transliteration":"anta","translation_bn":"তুমিই","root":"—","lemma":"أَنتَ","grammar_bn":"সর্বনাম (Pronoun)"},{"id":58538,"position":6,"text_uthmani":"ٱلْأَعْلَىٰ","transliteration":"l-aʿlā","translation_bn":"বিজয়ী (হবে)","root":"علو","lemma":"أَعْلَىٰ","grammar_bn":"শব্দ"},{"id":58539,"position":7,"text_uthmani":"٦٨","transliteration":"","translation_bn":"(৬৮)","root":"—","lemma":"٦٨","grammar_bn":"মার্কার"}]'::jsonb, 'qul''nā lā takhaf innaka anta l-aʿlā', 'আমি বললাম, ‘ভয় করো না, তুমিই বিজয়ী হবে।’', 'Allah said, "Fear not. Indeed, it is you who are superior.', 'আমি বললাম, ‘ভয় করো না, তুমিই বিজয়ী হবে।’', 'Allah said, "Fear not. Indeed, it is you who are superior.', NULL, NULL, NULL, NULL, NULL, 'https://everyayah.com/data/Alafasy_128kbps/020068.mp3', now()),
  (20, 69, '', '[{"id":59072,"position":1,"text_uthmani":"وَأَلْقِ","transliteration":"wa-alqi","translation_bn":"এবং নিক্ষেপ করো","root":"لقي","lemma":"أَلْقَىٰ^","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":59073,"position":2,"text_uthmani":"مَا","transliteration":"mā","translation_bn":"যা","root":"—","lemma":"مَا\r","grammar_bn":"সাপেক্ষ সর্বনাম (Relative)"},{"id":59074,"position":3,"text_uthmani":"فِى","transliteration":"fī","translation_bn":"মধ্যে (আছে)","root":"—","lemma":"فِى\r","grammar_bn":"অব্যয় (Preposition)"},{"id":59075,"position":4,"text_uthmani":"يَمِينِكَ","transliteration":"yamīnika","translation_bn":"তোমার ডান হাতের","root":"يمن","lemma":"يَمِين","grammar_bn":"বিশেষ্য (Noun)"},{"id":59076,"position":5,"text_uthmani":"تَلْقَفْ","transliteration":"talqaf","translation_bn":"গ্রাস করবে","root":"لقف","lemma":"تَلْقَفُ","grammar_bn":"ক্রিয়া (Verb)"},{"id":59077,"position":6,"text_uthmani":"مَا","transliteration":"mā","translation_bn":"যা কিছু","root":"—","lemma":"مَا\r","grammar_bn":"সাপেক্ষ সর্বনাম (Relative)"},{"id":59078,"position":7,"text_uthmani":"صَنَعُوٓا۟ ۖ","transliteration":"ṣanaʿū","translation_bn":"তারা বানিয়েছে","root":"صنع","lemma":"صَنَعُ","grammar_bn":"ক্রিয়া (Verb)"},{"id":59080,"position":8,"text_uthmani":"إِنَّمَا","transliteration":"innamā","translation_bn":"মূলতঃ","root":"—","lemma":"إِنّ","grammar_bn":"অভিঘাত পদ (Accusative)"},{"id":59081,"position":9,"text_uthmani":"صَنَعُوا۟","transliteration":"ṣanaʿū","translation_bn":"তারা বানিয়েছে","root":"صنع","lemma":"صَنَعُ","grammar_bn":"ক্রিয়া (Verb)"},{"id":59082,"position":10,"text_uthmani":"كَيْدُ","transliteration":"kaydu","translation_bn":"কলাকৌশল","root":"كيد","lemma":"كَيْد","grammar_bn":"বিশেষ্য (Noun)"},{"id":59083,"position":11,"text_uthmani":"سَـٰحِرٍۢ ۖ","transliteration":"sāḥirin","translation_bn":"জাদুকরের","root":"سحر","lemma":"سَٰحِر","grammar_bn":"বিশেষ্য (Noun)"},{"id":59085,"position":12,"text_uthmani":"وَلَا","transliteration":"walā","translation_bn":"এবং না","root":"—","lemma":"لَا\r","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":59086,"position":13,"text_uthmani":"يُفْلِحُ","transliteration":"yuf''liḥu","translation_bn":"সফল হয়","root":"فلح","lemma":"أَفْلَحَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":59087,"position":14,"text_uthmani":"ٱلسَّاحِرُ","transliteration":"l-sāḥiru","translation_bn":"জাদুকর","root":"سحر","lemma":"سَٰحِر","grammar_bn":"শব্দ"},{"id":59088,"position":15,"text_uthmani":"حَيْثُ","transliteration":"ḥaythu","translation_bn":"যেখান থেকেই","root":"حيث\r","lemma":"حَيْث","grammar_bn":"স্থানবাচক (Location)"},{"id":59089,"position":16,"text_uthmani":"أَتَىٰ","transliteration":"atā","translation_bn":"আসুক (না কেন)\"","root":"اتي","lemma":"أَتَى","grammar_bn":"ক্রিয়া (Verb)"},{"id":59090,"position":17,"text_uthmani":"٦٩","transliteration":"","translation_bn":"(৬৯)","root":"—","lemma":"٦٩","grammar_bn":"মার্কার"}]'::jsonb, 'wa-alqi mā fī yamīnika talqaf mā ṣanaʿū innamā ṣanaʿū kaydu sāḥirin walā yuf''liḥu l-sāḥiru ḥaythu atā', 'তোমার ডান হাতে যা আছে তা নিক্ষেপ কর, তারা যা করেছে এটা তা সব গিলে ফেলবে, তারা যা করেছে তাতো কেবল যাদুকরের কলা-কৌশল। যাদুকর যে রূপ ধরেই আসুক না কেন, সফল হবে না।’', 'And throw what is in your right hand; it will swallow up what they have crafted. What they have crafted is but the trick of a magician, and the magician will not succeed wherever he is."', 'তোমার ডান হাতে যা আছে তা নিক্ষেপ কর, তারা যা করেছে এটা তা সব গিলে ফেলবে, তারা যা করেছে তাতো কেবল যাদুকরের কলা-কৌশল। যাদুকর যে রূপ ধরেই আসুক না কেন, সফল হবে না।’', 'And throw what is in your right hand; it will swallow up what they have crafted. What they have crafted is but the trick of a magician, and the magician will not succeed wherever he is."', NULL, NULL, NULL, NULL, NULL, 'https://everyayah.com/data/Alafasy_128kbps/020069.mp3', now()),
  (20, 70, '', '[{"id":59456,"position":1,"text_uthmani":"فَأُلْقِىَ","transliteration":"fa-ul''qiya","translation_bn":"অতঃপর পড়ে গেল","root":"لقي","lemma":"أَلْقَىٰ^","grammar_bn":"শব্দ"},{"id":59457,"position":2,"text_uthmani":"ٱلسَّحَرَةُ","transliteration":"l-saḥaratu","translation_bn":"জাদুকররা","root":"سحر","lemma":"سَٰحِر","grammar_bn":"শব্দ"},{"id":59458,"position":3,"text_uthmani":"سُجَّدًۭا","transliteration":"sujjadan","translation_bn":"সিজদায়","root":"سجد","lemma":"سَاجِد","grammar_bn":"বিশেষণ (Adjective)"},{"id":59459,"position":4,"text_uthmani":"قَالُوٓا۟","transliteration":"qālū","translation_bn":"তারা বললো","root":"قول","lemma":"قَالَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":59460,"position":5,"text_uthmani":"ءَامَنَّا","transliteration":"āmannā","translation_bn":"\"আমরা ঈমান আনলাম","root":"امن","lemma":"ءَامَنَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":59461,"position":6,"text_uthmani":"بِرَبِّ","transliteration":"birabbi","translation_bn":"রবের উপর","root":"ربب","lemma":"رَبّ","grammar_bn":"অব্যয় (Preposition)"},{"id":59462,"position":7,"text_uthmani":"هَـٰرُونَ","transliteration":"hārūna","translation_bn":"হারূনের","root":"—","lemma":"هَٰرُون","grammar_bn":"নামবাচক বিশেষ্য (Proper Noun)"},{"id":59463,"position":8,"text_uthmani":"وَمُوسَىٰ","transliteration":"wamūsā","translation_bn":"ও মূসার\"","root":"—","lemma":"مُوسَىٰ","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":59464,"position":9,"text_uthmani":"٧٠","transliteration":"","translation_bn":"(৭০)","root":"—","lemma":"٧٠","grammar_bn":"মার্কার"}]'::jsonb, 'fa-ul''qiya l-saḥaratu sujjadan qālū āmannā birabbi hārūna wamūsā', '(মূসার স্পষ্ট নিদর্শন যখন দেখল) তখন যাদুকরেরা (আল্লাহর প্রতি) সাজদায় লুটিয়ে পড়ল। তারা বলল, ‘আমরা হারূন ও মূসার প্রতিপালকের উপর ঈমান আনলাম।’', 'So the magicians fell down in prostration. They said, "We have believed in the Lord of Aaron and Moses."', '(মূসার স্পষ্ট নিদর্শন যখন দেখল) তখন যাদুকরেরা (আল্লাহর প্রতি) সাজদায় লুটিয়ে পড়ল। তারা বলল, ‘আমরা হারূন ও মূসার প্রতিপালকের উপর ঈমান আনলাম।’', 'So the magicians fell down in prostration. They said, "We have believed in the Lord of Aaron and Moses."', NULL, NULL, NULL, NULL, NULL, 'https://everyayah.com/data/Alafasy_128kbps/020070.mp3', now()),
  (20, 71, '', '[{"id":59819,"position":1,"text_uthmani":"قَالَ","transliteration":"qāla","translation_bn":"(ফিরআউন) বললো","root":"قول","lemma":"قَالَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":59820,"position":2,"text_uthmani":"ءَامَنتُمْ","transliteration":"āmantum","translation_bn":"\"তোমরা ঈমান এনেছো","root":"امن","lemma":"ءَامَنَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":59821,"position":3,"text_uthmani":"لَهُۥ","transliteration":"lahu","translation_bn":"তার উপর","root":"—","lemma":"لَهُۥ","grammar_bn":"অব্যয় (Preposition)"},{"id":59822,"position":4,"text_uthmani":"قَبْلَ","transliteration":"qabla","translation_bn":"পূর্বেই","root":"قبل","lemma":"قَبْل","grammar_bn":"কালবাচক (Time)"},{"id":59823,"position":5,"text_uthmani":"أَنْ","transliteration":"an","translation_bn":"যে","root":"—","lemma":"أَن\r","grammar_bn":"অধীনস্থ যোজক (Subordinating)"},{"id":59824,"position":6,"text_uthmani":"ءَاذَنَ","transliteration":"ādhana","translation_bn":"আমি অনুমতি দিবো","root":"اذن","lemma":"أَذِنَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":59825,"position":7,"text_uthmani":"لَكُمْ ۖ","transliteration":"lakum","translation_bn":"তোমাদেরকে","root":"—","lemma":"لَكُمْ ۖ","grammar_bn":"অব্যয় (Preposition)"},{"id":59827,"position":8,"text_uthmani":"إِنَّهُۥ","transliteration":"innahu","translation_bn":"সে নিশ্চয়ই","root":"—","lemma":"إِنّ","grammar_bn":"অভিঘাত পদ (Accusative)"},{"id":59828,"position":9,"text_uthmani":"لَكَبِيرُكُمُ","transliteration":"lakabīrukumu","translation_bn":"অবশ্যই তোমাদের প্রধান","root":"كبر","lemma":"كَبِير","grammar_bn":"দৃঢ়তাবোধক (Emphatic)"},{"id":59829,"position":10,"text_uthmani":"ٱلَّذِى","transliteration":"alladhī","translation_bn":"যে","root":"—","lemma":"ٱلَّذِى","grammar_bn":"সাপেক্ষ সর্বনাম (Relative)"},{"id":59830,"position":11,"text_uthmani":"عَلَّمَكُمُ","transliteration":"ʿallamakumu","translation_bn":"তোমাদেরকে শিখিয়েছে","root":"علم","lemma":"عَلَّمَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":59831,"position":12,"text_uthmani":"ٱلسِّحْرَ ۖ","transliteration":"l-siḥ''ra","translation_bn":"জাদু","root":"سحر","lemma":"سِحْر","grammar_bn":"শব্দ"},{"id":59833,"position":13,"text_uthmani":"فَلَأُقَطِّعَنَّ","transliteration":"fala-uqaṭṭiʿanna","translation_bn":"সুতরাং অবশ্যই আমি কেটে দিবো","root":"قطع","lemma":"قَطَّعَ","grammar_bn":"শব্দ"},{"id":59834,"position":14,"text_uthmani":"أَيْدِيَكُمْ","transliteration":"aydiyakum","translation_bn":"তোমাদের হাতগুলো","root":"يدي","lemma":"يَد","grammar_bn":"বিশেষ্য (Noun)"},{"id":59835,"position":15,"text_uthmani":"وَأَرْجُلَكُم","transliteration":"wa-arjulakum","translation_bn":"ও তোমাদের পাগুলো","root":"رجل","lemma":"رِجْل","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":59836,"position":16,"text_uthmani":"مِّنْ","transliteration":"min","translation_bn":"থেকে","root":"—","lemma":"مِن\r","grammar_bn":"অব্যয় (Preposition)"},{"id":59837,"position":17,"text_uthmani":"خِلَـٰفٍۢ","transliteration":"khilāfin","translation_bn":"বিপরীত দিক","root":"خلف","lemma":"خِلَٰف","grammar_bn":"বিশেষ্য (Noun)"},{"id":59838,"position":18,"text_uthmani":"وَلَأُصَلِّبَنَّكُمْ","transliteration":"wala-uṣallibannakum","translation_bn":"এবং অবশ্যই তোমাদেরকে আমি শুলে চড়াবোই","root":"صلب","lemma":"يُصَلَّبُ","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":59839,"position":19,"text_uthmani":"فِى","transliteration":"fī","translation_bn":"মধ্যে","root":"—","lemma":"فِى\r","grammar_bn":"অব্যয় (Preposition)"},{"id":59840,"position":20,"text_uthmani":"جُذُوعِ","transliteration":"judhūʿi","translation_bn":"কাণ্ডের","root":"جذع","lemma":"جِذْع","grammar_bn":"বিশেষ্য (Noun)"},{"id":59841,"position":21,"text_uthmani":"ٱلنَّخْلِ","transliteration":"l-nakhli","translation_bn":"খেজুরের","root":"نخل","lemma":"نَخْل","grammar_bn":"শব্দ"},{"id":59842,"position":22,"text_uthmani":"وَلَتَعْلَمُنَّ","transliteration":"walataʿlamunna","translation_bn":"এবং তোমরা অবশ্যই জানবেই","root":"علم","lemma":"عَلِمَ","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":59843,"position":23,"text_uthmani":"أَيُّنَآ","transliteration":"ayyunā","translation_bn":"আমাদের মধ্যে কে","root":"—","lemma":"أَىّ","grammar_bn":"প্রশ্নবোধক (Interrogative)"},{"id":59844,"position":24,"text_uthmani":"أَشَدُّ","transliteration":"ashaddu","translation_bn":"কঠোরতর","root":"شدد","lemma":"أَشَدّ","grammar_bn":"বিশেষ্য (Noun)"},{"id":59845,"position":25,"text_uthmani":"عَذَابًۭا","transliteration":"ʿadhāban","translation_bn":"শাস্তি দেওয়াতে","root":"عذب","lemma":"عَذَاب","grammar_bn":"বিশেষ্য (Noun)"},{"id":59846,"position":26,"text_uthmani":"وَأَبْقَىٰ","transliteration":"wa-abqā","translation_bn":"ও অধিক স্থায়ী\"","root":"بقي","lemma":"أَبْقَىٰ^","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":59847,"position":27,"text_uthmani":"٧١","transliteration":"","translation_bn":"(৭১)","root":"—","lemma":"٧١","grammar_bn":"মার্কার"}]'::jsonb, 'qāla āmantum lahu qabla an ādhana lakum innahu lakabīrukumu alladhī ʿallamakumu l-siḥ''ra fala-uqaṭṭiʿanna aydiyakum wa-arjulakum min khilāfin wala-uṣallibannakum fī judhūʿi l-nakhli walataʿlamunna ayyunā ashaddu ʿadhāban wa-abqā', 'ফেরাউন বলল, ‘আমি তোমাদেরকে অনুমতি দেয়ার আগেই তোমরা তার প্রতি বিশ্বাস স্থাপন করলে? নিশ্চয়ই সে তোমাদের প্রধান যে তোমাদেরকে যাদু শিখিয়েছে। কাজেই আমি অবশ্য অবশ্যই তোমাদের হাত আর পা বিপরীত দিক থেকে কেটে ফেলব আর খেজুর গাছের শাখায় তোমাদেরকে অবশ্য অবশ্যই শূলে চড়াব আর তখন তোমরা অবশ্য অবশ্যই জানতে পারবে আমাদের মধ্যে কার ‘আযাব বেশি শক্ত আর বেশি স্থায়ী।', '[Pharaoh] said, "You believed him before I gave you permission. Indeed, he is your leader who has taught you magic. So I will surely cut off your hands and your feet on opposite sides, and I will crucify you on the trunks of palm trees, and you will surely know which of us is more severe in [giving] punishment and more enduring."', 'ফেরাউন বলল, ‘আমি তোমাদেরকে অনুমতি দেয়ার আগেই তোমরা তার প্রতি বিশ্বাস স্থাপন করলে? নিশ্চয়ই সে তোমাদের প্রধান যে তোমাদেরকে যাদু শিখিয়েছে। কাজেই আমি অবশ্য অবশ্যই তোমাদের হাত আর পা বিপরীত দিক থেকে কেটে ফেলব আর খেজুর গাছের শাখায় তোমাদেরকে অবশ্য অবশ্যই শূলে চড়াব আর তখন তোমরা অবশ্য অবশ্যই জানতে পারবে আমাদের মধ্যে কার ‘আযাব বেশি শক্ত আর বেশি স্থায়ী।', '[Pharaoh] said, "You believed him before I gave you permission. Indeed, he is your leader who has taught you magic. So I will surely cut off your hands and your feet on opposite sides, and I will crucify you on the trunks of palm trees, and you will surely know which of us is more severe in [giving] punishment and more enduring."', NULL, NULL, NULL, NULL, NULL, 'https://everyayah.com/data/Alafasy_128kbps/020071.mp3', now()),
  (20, 72, '', '[{"id":60624,"position":1,"text_uthmani":"قَالُوا۟","transliteration":"qālū","translation_bn":"তারা বলেছিলো","root":"قول","lemma":"قَالَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":60625,"position":2,"text_uthmani":"لَن","transliteration":"lan","translation_bn":"\"কখনও না","root":"—","lemma":"لَن\r","grammar_bn":"না-বোধক (Negative)"},{"id":60626,"position":3,"text_uthmani":"نُّؤْثِرَكَ","transliteration":"nu''thiraka","translation_bn":"তোমাকে প্রাধান্য দিবো আমরা","root":"اثر","lemma":"ا^ثَرَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":60627,"position":4,"text_uthmani":"عَلَىٰ","transliteration":"ʿalā","translation_bn":"এর উপর","root":"—","lemma":"عَلَىٰ\r","grammar_bn":"অব্যয় (Preposition)"},{"id":60628,"position":5,"text_uthmani":"مَا","transliteration":"mā","translation_bn":"যা","root":"—","lemma":"مَا\r","grammar_bn":"সাপেক্ষ সর্বনাম (Relative)"},{"id":60629,"position":6,"text_uthmani":"جَآءَنَا","transliteration":"jāanā","translation_bn":"আমাদের কাছে এসেছে","root":"جيا","lemma":"جَا^ءَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":60630,"position":7,"text_uthmani":"مِنَ","transliteration":"mina","translation_bn":"থেকে","root":"—","lemma":"مِن\r","grammar_bn":"অব্যয় (Preposition)"},{"id":60631,"position":8,"text_uthmani":"ٱلْبَيِّنَـٰتِ","transliteration":"l-bayināti","translation_bn":"সুস্পষ্ট নিদর্শনাবলী","root":"بين","lemma":"بَيِّنَة","grammar_bn":"শব্দ"},{"id":60632,"position":9,"text_uthmani":"وَٱلَّذِى","transliteration":"wa-alladhī","translation_bn":"এবং যিনি","root":"—","lemma":"ٱلَّذِى","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":60633,"position":10,"text_uthmani":"فَطَرَنَا ۖ","transliteration":"faṭaranā","translation_bn":"আমাদের সৃষ্টি করেছেন","root":"فطر","lemma":"فَطَرَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":60635,"position":11,"text_uthmani":"فَٱقْضِ","transliteration":"fa-iq''ḍi","translation_bn":"তাই তুমি বিচার করো","root":"قضي","lemma":"قَضَىٰ^","grammar_bn":"শব্দ"},{"id":60636,"position":12,"text_uthmani":"مَآ","transliteration":"mā","translation_bn":"যা কিছু","root":"—","lemma":"مَا\r","grammar_bn":"সাপেক্ষ সর্বনাম (Relative)"},{"id":60637,"position":13,"text_uthmani":"أَنتَ","transliteration":"anta","translation_bn":"তুমি","root":"—","lemma":"أَنتَ","grammar_bn":"সর্বনাম (Pronoun)"},{"id":60638,"position":14,"text_uthmani":"قَاضٍ ۖ","transliteration":"qāḍin","translation_bn":"বিচারক (করতে চাও)","root":"قضي","lemma":"قَاض","grammar_bn":"বিশেষ্য (Noun)"},{"id":60640,"position":15,"text_uthmani":"إِنَّمَا","transliteration":"innamā","translation_bn":"মূলতঃ","root":"—","lemma":"إِنّ","grammar_bn":"অভিঘাত পদ (Accusative)"},{"id":60641,"position":16,"text_uthmani":"تَقْضِى","transliteration":"taqḍī","translation_bn":"তুমি তো বিচার করতে পারবে","root":"قضي","lemma":"قَضَىٰ^","grammar_bn":"ক্রিয়া (Verb)"},{"id":60642,"position":17,"text_uthmani":"هَـٰذِهِ","transliteration":"hādhihi","translation_bn":"এই","root":"—","lemma":"هَٰذَا","grammar_bn":"নির্দেশক সর্বনাম (Demonstrative)"},{"id":60643,"position":18,"text_uthmani":"ٱلْحَيَوٰةَ","transliteration":"l-ḥayata","translation_bn":"জীবনে","root":"حيي","lemma":"حَيَوٰة","grammar_bn":"শব্দ"},{"id":60644,"position":19,"text_uthmani":"ٱلدُّنْيَآ","transliteration":"l-dun''yā","translation_bn":"দুনিয়ার","root":"دنو","lemma":"دُّنْيَا","grammar_bn":"শব্দ"},{"id":60645,"position":20,"text_uthmani":"٧٢","transliteration":"","translation_bn":"(৭২)","root":"—","lemma":"٧٢","grammar_bn":"মার্কার"}]'::jsonb, 'qālū lan nu''thiraka ʿalā mā jāanā mina l-bayināti wa-alladhī faṭaranā fa-iq''ḍi mā anta qāḍin innamā taqḍī hādhihi l-ḥayata l-dun''yā', 'তারা বলল, ‘আমাদের নিকট যে স্পষ্ট নিদর্শন এসেছে এবং যিনি আমাদেরকে সৃষ্টি করেছেন তার উপর আমরা তোমাকে কক্ষনো প্রাধান্য দেব না। কাজেই তুমি যা করতে চাও তাই কর। কেননা তুমি কেবল এ পার্থিব জীবনেই কর্তৃত্ব খাটাতে পার।', 'They said, "Never will we prefer you over what has come to us of clear proofs and [over] He who created us. So decree whatever you are to decree. You can only decree for this worldly life.', 'তারা বলল, ‘আমাদের নিকট যে স্পষ্ট নিদর্শন এসেছে এবং যিনি আমাদেরকে সৃষ্টি করেছেন তার উপর আমরা তোমাকে কক্ষনো প্রাধান্য দেব না। কাজেই তুমি যা করতে চাও তাই কর। কেননা তুমি কেবল এ পার্থিব জীবনেই কর্তৃত্ব খাটাতে পার।', 'They said, "Never will we prefer you over what has come to us of clear proofs and [over] He who created us. So decree whatever you are to decree. You can only decree for this worldly life.', NULL, NULL, NULL, NULL, NULL, 'https://everyayah.com/data/Alafasy_128kbps/020072.mp3', now()),
  (20, 73, '', '[{"id":60973,"position":1,"text_uthmani":"إِنَّآ","transliteration":"innā","translation_bn":"নিশ্চয়ই আমরা","root":"—","lemma":"إِنّ","grammar_bn":"অভিঘাত পদ (Accusative)"},{"id":60974,"position":2,"text_uthmani":"ءَامَنَّا","transliteration":"āmannā","translation_bn":"আমরা ঈমান এনেছি","root":"امن","lemma":"ءَامَنَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":60975,"position":3,"text_uthmani":"بِرَبِّنَا","transliteration":"birabbinā","translation_bn":"আমাদের রবের উপর","root":"ربب","lemma":"رَبّ","grammar_bn":"অব্যয় (Preposition)"},{"id":60976,"position":4,"text_uthmani":"لِيَغْفِرَ","transliteration":"liyaghfira","translation_bn":"যেন তিনি ক্ষমা করেন","root":"غفر","lemma":"غَفَرَ","grammar_bn":"শব্দ"},{"id":60977,"position":5,"text_uthmani":"لَنَا","transliteration":"lanā","translation_bn":"আমাদের","root":"—","lemma":"لَنَا","grammar_bn":"অব্যয় (Preposition)"},{"id":60978,"position":6,"text_uthmani":"خَطَـٰيَـٰنَا","transliteration":"khaṭāyānā","translation_bn":"আমাদের পাপসমূহকে","root":"خطا","lemma":"خَطِي^ـ#َة","grammar_bn":"বিশেষ্য (Noun)"},{"id":60979,"position":7,"text_uthmani":"وَمَآ","transliteration":"wamā","translation_bn":"এবং যা","root":"—","lemma":"مَا\r","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":60980,"position":8,"text_uthmani":"أَكْرَهْتَنَا","transliteration":"akrahtanā","translation_bn":"আমাদেরকে তুমি বাধ্য করেছো","root":"كره","lemma":"أُكْرِهَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":60981,"position":9,"text_uthmani":"عَلَيْهِ","transliteration":"ʿalayhi","translation_bn":"তার উপর","root":"—","lemma":"عَلَىٰ\r","grammar_bn":"অব্যয় (Preposition)"},{"id":60982,"position":10,"text_uthmani":"مِنَ","transliteration":"mina","translation_bn":"কারণে","root":"—","lemma":"مِن\r","grammar_bn":"অব্যয় (Preposition)"},{"id":60983,"position":11,"text_uthmani":"ٱلسِّحْرِ ۗ","transliteration":"l-siḥ''ri","translation_bn":"জাদুর","root":"سحر","lemma":"سِحْر","grammar_bn":"শব্দ"},{"id":60985,"position":12,"text_uthmani":"وَٱللَّهُ","transliteration":"wal-lahu","translation_bn":"এবং আল্লাহ","root":"اله","lemma":"ٱللَّه","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":60986,"position":13,"text_uthmani":"خَيْرٌۭ","transliteration":"khayrun","translation_bn":"উত্তম","root":"خير","lemma":"خَيْر","grammar_bn":"বিশেষণ (Adjective)"},{"id":60987,"position":14,"text_uthmani":"وَأَبْقَىٰٓ","transliteration":"wa-abqā","translation_bn":"ও চিরস্থায়ী\"","root":"بقي","lemma":"أَبْقَىٰ^","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":60988,"position":15,"text_uthmani":"٧٣","transliteration":"","translation_bn":"(৭৩)","root":"—","lemma":"٧٣","grammar_bn":"মার্কার"}]'::jsonb, 'innā āmannā birabbinā liyaghfira lanā khaṭāyānā wamā akrahtanā ʿalayhi mina l-siḥ''ri wal-lahu khayrun wa-abqā', 'আমরা আমাদের প্রতিপালকের উপর ঈমান এনেছি যাতে তিনি আমাদের অপরাধ ক্ষমা করেন আর যে যাদু করতে তুমি আমাদেরকে বাধ্য করেছ তাও (ক্ষমা করেন), আল্লাহই সর্বশ্রেষ্ঠ ও স্থায়ী।’', 'Indeed, we have believed in our Lord that He may forgive us our sins and what you compelled us [to do] of magic. And Allah is better and more enduring."', 'আমরা আমাদের প্রতিপালকের উপর ঈমান এনেছি যাতে তিনি আমাদের অপরাধ ক্ষমা করেন আর যে যাদু করতে তুমি আমাদেরকে বাধ্য করেছ তাও (ক্ষমা করেন), আল্লাহই সর্বশ্রেষ্ঠ ও স্থায়ী।’', 'Indeed, we have believed in our Lord that He may forgive us our sins and what you compelled us [to do] of magic. And Allah is better and more enduring."', NULL, NULL, NULL, NULL, NULL, 'https://everyayah.com/data/Alafasy_128kbps/020073.mp3', now()),
  (20, 74, '', '[{"id":61394,"position":1,"text_uthmani":"إِنَّهُۥ","transliteration":"innahu","translation_bn":"(প্রকৃত কথা) তাই নিশ্চয়ই","root":"—","lemma":"إِنّ","grammar_bn":"অভিঘাত পদ (Accusative)"},{"id":61395,"position":2,"text_uthmani":"مَن","transliteration":"man","translation_bn":"যে কেউ","root":"—","lemma":"مَن\r","grammar_bn":"শর্তবাচক (Conditional)"},{"id":61396,"position":3,"text_uthmani":"يَأْتِ","transliteration":"yati","translation_bn":"আসবে","root":"اتي","lemma":"أَتَى","grammar_bn":"ক্রিয়া (Verb)"},{"id":61397,"position":4,"text_uthmani":"رَبَّهُۥ","transliteration":"rabbahu","translation_bn":"তাদের রবের কাছে","root":"ربب","lemma":"رَبّ","grammar_bn":"বিশেষ্য (Noun)"},{"id":61398,"position":5,"text_uthmani":"مُجْرِمًۭا","transliteration":"muj''riman","translation_bn":"অপরাধী হয়ে","root":"جرم","lemma":"مُجْرِم","grammar_bn":"বিশেষ্য (Noun)"},{"id":61399,"position":6,"text_uthmani":"فَإِنَّ","transliteration":"fa-inna","translation_bn":"অতঃপর নিশ্চয়ই","root":"—","lemma":"إِنّ","grammar_bn":"শব্দ"},{"id":61400,"position":7,"text_uthmani":"لَهُۥ","transliteration":"lahu","translation_bn":"তার জন্যে","root":"—","lemma":"لَهُۥ","grammar_bn":"অব্যয় (Preposition)"},{"id":61401,"position":8,"text_uthmani":"جَهَنَّمَ","transliteration":"jahannama","translation_bn":"জাহান্নাম","root":"—","lemma":"جَهَنَّم","grammar_bn":"নামবাচক বিশেষ্য (Proper Noun)"},{"id":61402,"position":9,"text_uthmani":"لَا","transliteration":"lā","translation_bn":"না","root":"—","lemma":"لَا\r","grammar_bn":"না-বোধক (Negative)"},{"id":61403,"position":10,"text_uthmani":"يَمُوتُ","transliteration":"yamūtu","translation_bn":"সে মরবে","root":"موت","lemma":"مَّاتَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":61404,"position":11,"text_uthmani":"فِيهَا","transliteration":"fīhā","translation_bn":"তার মধ্যে","root":"—","lemma":"فِى\r","grammar_bn":"অব্যয় (Preposition)"},{"id":61405,"position":12,"text_uthmani":"وَلَا","transliteration":"walā","translation_bn":"আর না","root":"—","lemma":"لَا\r","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":61406,"position":13,"text_uthmani":"يَحْيَىٰ","transliteration":"yaḥyā","translation_bn":"বাঁচবে","root":"حيي","lemma":"حَىَّ","grammar_bn":"ক্রিয়া (Verb)"},{"id":61407,"position":14,"text_uthmani":"٧٤","transliteration":"","translation_bn":"(৭৪)","root":"—","lemma":"٧٤","grammar_bn":"মার্কার"}]'::jsonb, 'innahu man yati rabbahu muj''riman fa-inna lahu jahannama lā yamūtu fīhā walā yaḥyā', 'যে কেউ তার প্রতিপালকের নিকট অপরাধী অবস্থায় হাযির হবে তার জন্যে আছে জাহান্নাম, সেখানে সে না মরবে, আর না বাঁচবে।', 'Indeed, whoever comes to his Lord as a criminal - indeed, for him is Hell; he will neither die therein nor live.', 'যে কেউ তার প্রতিপালকের নিকট অপরাধী অবস্থায় হাযির হবে তার জন্যে আছে জাহান্নাম, সেখানে সে না মরবে, আর না বাঁচবে।', 'Indeed, whoever comes to his Lord as a criminal - indeed, for him is Hell; he will neither die therein nor live.', NULL, NULL, NULL, NULL, NULL, 'https://everyayah.com/data/Alafasy_128kbps/020074.mp3', now()),
  (20, 75, '', '[{"id":61895,"position":1,"text_uthmani":"وَمَن","transliteration":"waman","translation_bn":"এবং যে","root":"—","lemma":"مَن\r","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":61896,"position":2,"text_uthmani":"يَأْتِهِۦ","transliteration":"yatihi","translation_bn":"তাঁর কাছে আসবে","root":"اتي","lemma":"أَتَى","grammar_bn":"ক্রিয়া (Verb)"},{"id":61897,"position":3,"text_uthmani":"مُؤْمِنًۭا","transliteration":"mu''minan","translation_bn":"মু''মিন হয়ে","root":"امن","lemma":"مُؤْمِن","grammar_bn":"বিশেষ্য (Noun)"},{"id":61898,"position":4,"text_uthmani":"قَدْ","transliteration":"qad","translation_bn":"নিশ্চয়ই","root":"—","lemma":"قَد\r","grammar_bn":"নিশ্চয়তাবোধক (Certainty)"},{"id":61899,"position":5,"text_uthmani":"عَمِلَ","transliteration":"ʿamila","translation_bn":"সে কাজ করেছে","root":"عمل","lemma":"عَمِلَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":61900,"position":6,"text_uthmani":"ٱلصَّـٰلِحَـٰتِ","transliteration":"l-ṣāliḥāti","translation_bn":"সৎ","root":"صلح","lemma":"صَّٰلِحَٰت","grammar_bn":"শব্দ"},{"id":61901,"position":7,"text_uthmani":"فَأُو۟لَـٰٓئِكَ","transliteration":"fa-ulāika","translation_bn":"অতঃপর ঐসব লোক","root":"—","lemma":"أُولَٰ^ئِك","grammar_bn":"শব্দ"},{"id":61902,"position":8,"text_uthmani":"لَهُمُ","transliteration":"lahumu","translation_bn":"তাদের জন্যে (রয়েছে)","root":"—","lemma":"لَهُمُ","grammar_bn":"অব্যয় (Preposition)"},{"id":61903,"position":9,"text_uthmani":"ٱلدَّرَجَـٰتُ","transliteration":"l-darajātu","translation_bn":"মর্যাদাসমূহ","root":"درج","lemma":"دَرَجَة","grammar_bn":"শব্দ"},{"id":61904,"position":10,"text_uthmani":"ٱلْعُلَىٰ","transliteration":"l-ʿulā","translation_bn":"সমুচ্চ","root":"علو","lemma":"عُلْيَا","grammar_bn":"শব্দ"},{"id":61905,"position":11,"text_uthmani":"٧٥","transliteration":"","translation_bn":"(৭৫)","root":"—","lemma":"٧٥","grammar_bn":"মার্কার"}]'::jsonb, 'waman yatihi mu''minan qad ʿamila l-ṣāliḥāti fa-ulāika lahumu l-darajātu l-ʿulā', 'যে কেউ সৎ ‘আমাল ক’রে মু’মিন অবস্থায় তাঁর নিকট হাযির হবে, তাদের জন্য আছে সুউচ্চ মর্যাদা।', 'But whoever comes to Him as a believer having done righteous deeds - for those will be the highest degrees [in position]:', 'যে কেউ সৎ ‘আমাল ক’রে মু’মিন অবস্থায় তাঁর নিকট হাযির হবে, তাদের জন্য আছে সুউচ্চ মর্যাদা।', 'But whoever comes to Him as a believer having done righteous deeds - for those will be the highest degrees [in position]:', NULL, NULL, NULL, NULL, NULL, 'https://everyayah.com/data/Alafasy_128kbps/020075.mp3', now()),
  (20, 76, '', '[{"id":62380,"position":1,"text_uthmani":"جَنَّـٰتُ","transliteration":"jannātu","translation_bn":"জান্নাত","root":"جنن","lemma":"جَنَّة","grammar_bn":"বিশেষ্য (Noun)"},{"id":62381,"position":2,"text_uthmani":"عَدْنٍۢ","transliteration":"ʿadnin","translation_bn":"স্থায়ী","root":"—","lemma":"عَدْن","grammar_bn":"নামবাচক বিশেষ্য (Proper Noun)"},{"id":62382,"position":3,"text_uthmani":"تَجْرِى","transliteration":"tajrī","translation_bn":"প্রবাহিত হয়","root":"جري","lemma":"جَرَيْ","grammar_bn":"ক্রিয়া (Verb)"},{"id":62383,"position":4,"text_uthmani":"مِن","transliteration":"min","translation_bn":"থেকে","root":"—","lemma":"مِن\r","grammar_bn":"অব্যয় (Preposition)"},{"id":62384,"position":5,"text_uthmani":"تَحْتِهَا","transliteration":"taḥtihā","translation_bn":"তার নিচ","root":"تحت","lemma":"تَحْت","grammar_bn":"বিশেষ্য (Noun)"},{"id":62385,"position":6,"text_uthmani":"ٱلْأَنْهَـٰرُ","transliteration":"l-anhāru","translation_bn":"ঝর্ণাসমূহ","root":"نهر","lemma":"نَهَر","grammar_bn":"শব্দ"},{"id":62386,"position":7,"text_uthmani":"خَـٰلِدِينَ","transliteration":"khālidīna","translation_bn":"তারা স্থায়ী হবে","root":"خلد","lemma":"خَٰلِد","grammar_bn":"বিশেষ্য (Noun)"},{"id":62387,"position":8,"text_uthmani":"فِيهَا ۚ","transliteration":"fīhā","translation_bn":"তার মধ্যে","root":"—","lemma":"فِى\r","grammar_bn":"অব্যয় (Preposition)"},{"id":62389,"position":9,"text_uthmani":"وَذَٰلِكَ","transliteration":"wadhālika","translation_bn":"এবং এটা","root":"—","lemma":"ذَٰلِك","grammar_bn":"শব্দ"},{"id":62390,"position":10,"text_uthmani":"جَزَآءُ","transliteration":"jazāu","translation_bn":"পুরস্কার","root":"جزي","lemma":"جَزَا^ء","grammar_bn":"বিশেষ্য (Noun)"},{"id":62391,"position":11,"text_uthmani":"مَن","transliteration":"man","translation_bn":"(তার) যে","root":"—","lemma":"مَن\r","grammar_bn":"সাপেক্ষ সর্বনাম (Relative)"},{"id":62392,"position":12,"text_uthmani":"تَزَكَّىٰ","transliteration":"tazakkā","translation_bn":"পরিশুদ্ধ হবে","root":"زكو","lemma":"تَزَكَّىٰ","grammar_bn":"ক্রিয়া (Verb)"},{"id":62393,"position":13,"text_uthmani":"٧٦","transliteration":"","translation_bn":"(৭৬)","root":"—","lemma":"٧٦","grammar_bn":"মার্কার"}]'::jsonb, 'jannātu ʿadnin tajrī min taḥtihā l-anhāru khālidīna fīhā wadhālika jazāu man tazakkā', 'স্থায়ী জান্নাত, যার পাদদেশে বয়ে চলছে নির্ঝরিণী, সেখানে তারা চিরকাল থাকবে। যারা নিজেদেরকে পবিত্র করে তাদের এটাই পুরস্কার।', 'Gardens of perpetual residence beneath which rivers flow, wherein they abide eternally. And that is the reward of one who purifies himself.', 'স্থায়ী জান্নাত, যার পাদদেশে বয়ে চলছে নির্ঝরিণী, সেখানে তারা চিরকাল থাকবে। যারা নিজেদেরকে পবিত্র করে তাদের এটাই পুরস্কার।', 'Gardens of perpetual residence beneath which rivers flow, wherein they abide eternally. And that is the reward of one who purifies himself.', NULL, NULL, NULL, NULL, NULL, 'https://everyayah.com/data/Alafasy_128kbps/020076.mp3', now()),
  (20, 77, '', '[{"id":62824,"position":1,"text_uthmani":"وَلَقَدْ","transliteration":"walaqad","translation_bn":"এবং নিশ্চয়ই","root":"—","lemma":"قَد\r","grammar_bn":"শব্দ"},{"id":62825,"position":2,"text_uthmani":"أَوْحَيْنَآ","transliteration":"awḥaynā","translation_bn":"আমরা ওহী করেছিলাম","root":"وحي","lemma":"أَوْحَىٰ^","grammar_bn":"ক্রিয়া (Verb)"},{"id":62826,"position":3,"text_uthmani":"إِلَىٰ","transliteration":"ilā","translation_bn":"প্রতি","root":"—","lemma":"إِلَىٰ\r","grammar_bn":"অব্যয় (Preposition)"},{"id":62827,"position":4,"text_uthmani":"مُوسَىٰٓ","transliteration":"mūsā","translation_bn":"মূসার","root":"—","lemma":"مُوسَىٰ","grammar_bn":"নামবাচক বিশেষ্য (Proper Noun)"},{"id":62828,"position":5,"text_uthmani":"أَنْ","transliteration":"an","translation_bn":"যে","root":"—","lemma":"أَن\r","grammar_bn":"উদ্দেশ্যবাচক (Intention)"},{"id":62829,"position":6,"text_uthmani":"أَسْرِ","transliteration":"asri","translation_bn":"\"রাতে বেরিয়ে পড়ো","root":"سري","lemma":"أَسْرَىٰ","grammar_bn":"ক্রিয়া (Verb)"},{"id":62830,"position":7,"text_uthmani":"بِعِبَادِى","transliteration":"biʿibādī","translation_bn":"নিয়ে আমার দাসদের","root":"عبد","lemma":"عَبْد","grammar_bn":"অব্যয় (Preposition)"},{"id":62831,"position":8,"text_uthmani":"فَٱضْرِبْ","transliteration":"fa-iḍ''rib","translation_bn":"অতঃপর (লাঠির) আঘাত করো (অবলম্বন করো)","root":"ضرب","lemma":"ضَرَبَ","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":62832,"position":9,"text_uthmani":"لَهُمْ","transliteration":"lahum","translation_bn":"তাদের জন্যে","root":"—","lemma":"لَهُمْ","grammar_bn":"অব্যয় (Preposition)"},{"id":62833,"position":10,"text_uthmani":"طَرِيقًۭا","transliteration":"ṭarīqan","translation_bn":"পথ","root":"طرق","lemma":"طَرِيق","grammar_bn":"বিশেষ্য (Noun)"},{"id":62834,"position":11,"text_uthmani":"فِى","transliteration":"fī","translation_bn":"মধ্যে","root":"—","lemma":"فِى\r","grammar_bn":"অব্যয় (Preposition)"},{"id":62835,"position":12,"text_uthmani":"ٱلْبَحْرِ","transliteration":"l-baḥri","translation_bn":"সাগরের","root":"بحر","lemma":"بَحْر","grammar_bn":"শব্দ"},{"id":62836,"position":13,"text_uthmani":"يَبَسًۭا","transliteration":"yabasan","translation_bn":"শুকনো","root":"يبس","lemma":"يَبَس","grammar_bn":"বিশেষণ (Adjective)"},{"id":62837,"position":14,"text_uthmani":"لَّا","transliteration":"lā","translation_bn":"না","root":"—","lemma":"لَا\r","grammar_bn":"না-বোধক (Negative)"},{"id":62838,"position":15,"text_uthmani":"تَخَـٰفُ","transliteration":"takhāfu","translation_bn":"ভয় করো তুমি","root":"خوف","lemma":"خَافَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":62839,"position":16,"text_uthmani":"دَرَكًۭا","transliteration":"darakan","translation_bn":"ধরা পড়ার","root":"درك","lemma":"دَرَك","grammar_bn":"বিশেষ্য (Noun)"},{"id":62840,"position":17,"text_uthmani":"وَلَا","transliteration":"walā","translation_bn":"আর না","root":"—","lemma":"لَا\r","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":62841,"position":18,"text_uthmani":"تَخْشَىٰ","transliteration":"takhshā","translation_bn":"ঘাবড়ে যাও তুমি (ডুবে যাওয়ার)\"","root":"خشي","lemma":"خَشِىَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":62842,"position":19,"text_uthmani":"٧٧","transliteration":"","translation_bn":"(৭৭)","root":"—","lemma":"٧٧","grammar_bn":"মার্কার"}]'::jsonb, 'walaqad awḥaynā ilā mūsā an asri biʿibādī fa-iḍ''rib lahum ṭarīqan fī l-baḥri yabasan lā takhāfu darakan walā takhshā', 'আমি মূসাকে ওয়াহী করলাম যে, আমার বান্দাহদেরকে নিয়ে রাতের বেলা যাত্রা কর আর তাদের জন্য সমুদ্রের ভিতর একটা শুকনো পথ বানিয়ে নাও। আর পেছন থেকে (ফেরাউন) ধরে ফেলবে এ ভয় করো না, আর (অন্য কোন) আশঙ্কাও করো না।', 'And We had inspired to Moses, "Travel by night with My servants and strike for them a dry path through the sea; you will not fear being overtaken [by Pharaoh] nor be afraid [of drowning]."', 'আমি মূসাকে ওয়াহী করলাম যে, আমার বান্দাহদেরকে নিয়ে রাতের বেলা যাত্রা কর আর তাদের জন্য সমুদ্রের ভিতর একটা শুকনো পথ বানিয়ে নাও। আর পেছন থেকে (ফেরাউন) ধরে ফেলবে এ ভয় করো না, আর (অন্য কোন) আশঙ্কাও করো না।', 'And We had inspired to Moses, "Travel by night with My servants and strike for them a dry path through the sea; you will not fear being overtaken [by Pharaoh] nor be afraid [of drowning]."', NULL, NULL, NULL, NULL, NULL, 'https://everyayah.com/data/Alafasy_128kbps/020077.mp3', now()),
