  (21, 1, '', '[{"id":284,"position":1,"text_uthmani":"ٱقْتَرَبَ","transliteration":"iq''taraba","translation_bn":"নিকটে এসেছে","root":"قرب","lemma":"ٱقْتَرَبَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":285,"position":2,"text_uthmani":"لِلنَّاسِ","transliteration":"lilnnāsi","translation_bn":"জন্যে মানুষের","root":"نوس","lemma":"نَّاس","grammar_bn":"অব্যয় (Preposition)"},{"id":286,"position":3,"text_uthmani":"حِسَابُهُمْ","transliteration":"ḥisābuhum","translation_bn":"তাদের হিসাব (নেয়ার সময়)","root":"حسب","lemma":"حِسَاب","grammar_bn":"বিশেষ্য (Noun)"},{"id":287,"position":4,"text_uthmani":"وَهُمْ","transliteration":"wahum","translation_bn":"অথচ তারা","root":"—","lemma":"وَهُمْ","grammar_bn":"অবস্থাবাচক (Circumstantial)"},{"id":288,"position":5,"text_uthmani":"فِى","transliteration":"fī","translation_bn":"মধ্যে","root":"—","lemma":"فِى\r","grammar_bn":"অব্যয় (Preposition)"},{"id":289,"position":6,"text_uthmani":"غَفْلَةٍۢ","transliteration":"ghaflatin","translation_bn":"উদাসীনতার","root":"غفل","lemma":"غَفْلَة","grammar_bn":"বিশেষ্য (Noun)"},{"id":290,"position":7,"text_uthmani":"مُّعْرِضُونَ","transliteration":"muʿ''riḍūna","translation_bn":"পড়ে আছে বিমুখ হয়ে","root":"عرض","lemma":"مُّعْرِضُون","grammar_bn":"বিশেষ্য (Noun)"},{"id":291,"position":8,"text_uthmani":"١","transliteration":"","translation_bn":"(১)","root":"—","lemma":"١","grammar_bn":"মার্কার"}]'::jsonb, 'iq''taraba lilnnāsi ḥisābuhum wahum fī ghaflatin muʿ''riḍūna', 'মানুষের হিসাব গ্রহণের কাল ক্রমশঃ ঘনিয়ে আসছে কিন্তু তারা গাফলতিতে মুখ ফিরিয়ে রেখেছে।', '[The time of] their account has approached for the people, while they are in heedlessness turning away.', 'মানুষের হিসাব গ্রহণের কাল ক্রমশঃ ঘনিয়ে আসছে কিন্তু তারা গাফলতিতে মুখ ফিরিয়ে রেখেছে।', '[The time of] their account has approached for the people, while they are in heedlessness turning away.', NULL, NULL, NULL, NULL, NULL, 'https://everyayah.com/data/Alafasy_128kbps/021001.mp3', now()),
  (21, 2, '', '[{"id":1225,"position":1,"text_uthmani":"مَا","transliteration":"mā","translation_bn":"না","root":"—","lemma":"مَا\r","grammar_bn":"না-বোধক (Negative)"},{"id":1226,"position":2,"text_uthmani":"يَأْتِيهِم","transliteration":"yatīhim","translation_bn":"তাদের কাছে আসে","root":"اتي","lemma":"أَتَى","grammar_bn":"ক্রিয়া (Verb)"},{"id":1227,"position":3,"text_uthmani":"مِّن","transliteration":"min","translation_bn":"কোন","root":"—","lemma":"مِن\r","grammar_bn":"অব্যয় (Preposition)"},{"id":1228,"position":4,"text_uthmani":"ذِكْرٍۢ","transliteration":"dhik''rin","translation_bn":"উপদেশ","root":"ذكر","lemma":"ذِكْر","grammar_bn":"বিশেষ্য (Noun)"},{"id":1229,"position":5,"text_uthmani":"مِّن","transliteration":"min","translation_bn":"পক্ষ হ''তে","root":"—","lemma":"مِن\r","grammar_bn":"অব্যয় (Preposition)"},{"id":1230,"position":6,"text_uthmani":"رَّبِّهِم","transliteration":"rabbihim","translation_bn":"তাদের রবের","root":"ربب","lemma":"رَبّ","grammar_bn":"বিশেষ্য (Noun)"},{"id":1231,"position":7,"text_uthmani":"مُّحْدَثٍ","transliteration":"muḥ''dathin","translation_bn":"নতুন","root":"حدث","lemma":"مُحْدَث","grammar_bn":"বিশেষ্য (Noun)"},{"id":1232,"position":8,"text_uthmani":"إِلَّا","transliteration":"illā","translation_bn":"এ ছাড়া যে","root":"—","lemma":"إِلَّا\r","grammar_bn":"সীমাবদ্ধতা (Restriction)"},{"id":1233,"position":9,"text_uthmani":"ٱسْتَمَعُوهُ","transliteration":"is''tamaʿūhu","translation_bn":"তা তারা শুনে","root":"سمع","lemma":"ٱسْتَمَعَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":1234,"position":10,"text_uthmani":"وَهُمْ","transliteration":"wahum","translation_bn":"এমতাবস্হায় যে তারা","root":"—","lemma":"وَهُمْ","grammar_bn":"অবস্থাবাচক (Circumstantial)"},{"id":1235,"position":11,"text_uthmani":"يَلْعَبُونَ","transliteration":"yalʿabūna","translation_bn":"খেলায় মেতে থাকে","root":"لعب","lemma":"يَلْعَبْ","grammar_bn":"ক্রিয়া (Verb)"},{"id":1236,"position":12,"text_uthmani":"٢","transliteration":"","translation_bn":"(২)","root":"—","lemma":"٢","grammar_bn":"মার্কার"}]'::jsonb, 'mā yatīhim min dhik''rin min rabbihim muḥ''dathin illā is''tamaʿūhu wahum yalʿabūna', 'তাদের কাছে তাদের প্রতিপালকের পক্ষ হতে যখনই কোন নতুন উপদেশ আসে, তখন তারা তা হাসি-তামাশার বস্তু মনে করেই শোনে।', 'No mention comes to them anew from their Lord except that they listen to it while they are at play', 'তাদের কাছে তাদের প্রতিপালকের পক্ষ হতে যখনই কোন নতুন উপদেশ আসে, তখন তারা তা হাসি-তামাশার বস্তু মনে করেই শোনে।', 'No mention comes to them anew from their Lord except that they listen to it while they are at play', NULL, NULL, NULL, NULL, NULL, 'https://everyayah.com/data/Alafasy_128kbps/021002.mp3', now()),
  (21, 3, '', '[{"id":2260,"position":1,"text_uthmani":"لَاهِيَةًۭ","transliteration":"lāhiyatan","translation_bn":"অমনোযোগী থাকে","root":"لهو","lemma":"لَاهِيَة","grammar_bn":"বিশেষ্য (Noun)"},{"id":2261,"position":2,"text_uthmani":"قُلُوبُهُمْ ۗ","transliteration":"qulūbuhum","translation_bn":"তাদের অন্তরগুলো","root":"قلب","lemma":"قَلْب","grammar_bn":"বিশেষ্য (Noun)"},{"id":2263,"position":3,"text_uthmani":"وَأَسَرُّوا۟","transliteration":"wa-asarrū","translation_bn":"এবং তারা গোপনে করে","root":"سرر","lemma":"أَسَرَّ","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":2264,"position":4,"text_uthmani":"ٱلنَّجْوَى","transliteration":"l-najwā","translation_bn":"পরামর্শ","root":"نجو","lemma":"نَجْوَىٰ^","grammar_bn":"শব্দ"},{"id":2265,"position":5,"text_uthmani":"ٱلَّذِينَ","transliteration":"alladhīna","translation_bn":"যারা","root":"—","lemma":"ٱلَّذِى","grammar_bn":"সাপেক্ষ সর্বনাম (Relative)"},{"id":2266,"position":6,"text_uthmani":"ظَلَمُوا۟","transliteration":"ẓalamū","translation_bn":"সীমালঙ্ঘন করেছে","root":"ظلم","lemma":"ظَلَمَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":2267,"position":7,"text_uthmani":"هَلْ","transliteration":"hal","translation_bn":"\"(তারা বলে) নয় কি","root":"—","lemma":"هَل\r","grammar_bn":"প্রশ্নবোধক (Interrogative)"},{"id":2268,"position":8,"text_uthmani":"هَـٰذَآ","transliteration":"hādhā","translation_bn":"এই (ব্যক্তি)","root":"—","lemma":"هَٰذَا","grammar_bn":"নির্দেশক সর্বনাম (Demonstrative)"},{"id":2269,"position":9,"text_uthmani":"إِلَّا","transliteration":"illā","translation_bn":"এছাড়া","root":"—","lemma":"إِلَّا\r","grammar_bn":"সীমাবদ্ধতা (Restriction)"},{"id":2270,"position":10,"text_uthmani":"بَشَرٌۭ","transliteration":"basharun","translation_bn":"একজন মানুষ","root":"بشر","lemma":"بَشَر","grammar_bn":"বিশেষ্য (Noun)"},{"id":2271,"position":11,"text_uthmani":"مِّثْلُكُمْ ۖ","transliteration":"mith''lukum","translation_bn":"তোমাদেরই মতো","root":"مثل","lemma":"مِثْل","grammar_bn":"বিশেষ্য (Noun)"},{"id":2273,"position":12,"text_uthmani":"أَفَتَأْتُونَ","transliteration":"afatatūna","translation_bn":"তবে কি তোমরা এসে পড়বে","root":"اتي","lemma":"أَتَى","grammar_bn":"প্রশ্নবোধক (Interrogative)"},{"id":2274,"position":13,"text_uthmani":"ٱلسِّحْرَ","transliteration":"l-siḥ''ra","translation_bn":"জাদুর (খপ্পরে)","root":"سحر","lemma":"سِحْر","grammar_bn":"শব্দ"},{"id":2275,"position":14,"text_uthmani":"وَأَنتُمْ","transliteration":"wa-antum","translation_bn":"অথচ তোমরা","root":"—","lemma":"وَأَنتُمْ","grammar_bn":"অবস্থাবাচক (Circumstantial)"},{"id":2276,"position":15,"text_uthmani":"تُبْصِرُونَ","transliteration":"tub''ṣirūna","translation_bn":"দেখছো\"","root":"بصر","lemma":"أَبْصَرَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":2277,"position":16,"text_uthmani":"٣","transliteration":"","translation_bn":"(৩)","root":"—","lemma":"٣","grammar_bn":"মার্কার"}]'::jsonb, 'lāhiyatan qulūbuhum wa-asarrū l-najwā alladhīna ẓalamū hal hādhā illā basharun mith''lukum afatatūna l-siḥ''ra wa-antum tub''ṣirūna', 'তাদের অন্তর থাকে খেলায় মগ্ন। যালিমরা গোপনে পরামর্শ করে- এটা তোমাদেরই মত মানুষ ছাড়া কি অন্য কিছু? তোমরা কি দেখে-শুনে যাদুর কবলে পড়বে?', 'With their hearts distracted. And those who do wrong conceal their private conversation, [saying], "Is this [Prophet] except a human being like you? So would you approach magic while you are aware [of it]?"', 'তাদের অন্তর থাকে খেলায় মগ্ন। যালিমরা গোপনে পরামর্শ করে- এটা তোমাদেরই মত মানুষ ছাড়া কি অন্য কিছু? তোমরা কি দেখে-শুনে যাদুর কবলে পড়বে?', 'With their hearts distracted. And those who do wrong conceal their private conversation, [saying], "Is this [Prophet] except a human being like you? So would you approach magic while you are aware [of it]?"', NULL, NULL, NULL, NULL, NULL, 'https://everyayah.com/data/Alafasy_128kbps/021003.mp3', now()),
  (21, 4, '', '[{"id":3587,"position":1,"text_uthmani":"قَالَ","transliteration":"qāla","translation_bn":"(নাবী) বললো","root":"قول","lemma":"قَالَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":3588,"position":2,"text_uthmani":"رَبِّى","transliteration":"rabbī","translation_bn":"\"আমার রব","root":"ربب","lemma":"رَبّ","grammar_bn":"বিশেষ্য (Noun)"},{"id":3589,"position":3,"text_uthmani":"يَعْلَمُ","transliteration":"yaʿlamu","translation_bn":"জানেন","root":"علم","lemma":"عَلِمَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":3590,"position":4,"text_uthmani":"ٱلْقَوْلَ","transliteration":"l-qawla","translation_bn":"(সেই সব) কথা","root":"قول","lemma":"قَوْل","grammar_bn":"শব্দ"},{"id":3591,"position":5,"text_uthmani":"فِى","transliteration":"fī","translation_bn":"(যা হয়) মধ্যে","root":"—","lemma":"فِى\r","grammar_bn":"অব্যয় (Preposition)"},{"id":3592,"position":6,"text_uthmani":"ٱلسَّمَآءِ","transliteration":"l-samāi","translation_bn":"আকাশমন্ডলীর","root":"سمو","lemma":"سَمَا^ء","grammar_bn":"শব্দ"},{"id":3593,"position":7,"text_uthmani":"وَٱلْأَرْضِ ۖ","transliteration":"wal-arḍi","translation_bn":"ও পৃথিবীর","root":"ارض","lemma":"أَرْض","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":3595,"position":8,"text_uthmani":"وَهُوَ","transliteration":"wahuwa","translation_bn":"এবং তিনিই","root":"—","lemma":"وَهُوَ","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":3596,"position":9,"text_uthmani":"ٱلسَّمِيعُ","transliteration":"l-samīʿu","translation_bn":"সবকিছু শুনেন","root":"سمع","lemma":"سَمِيع","grammar_bn":"শব্দ"},{"id":3597,"position":10,"text_uthmani":"ٱلْعَلِيمُ","transliteration":"l-ʿalīmu","translation_bn":"সবকিছু জানেন\"","root":"علم","lemma":"عَلِيم","grammar_bn":"শব্দ"},{"id":3598,"position":11,"text_uthmani":"٤","transliteration":"","translation_bn":"(৪)","root":"—","lemma":"٤","grammar_bn":"মার্কার"}]'::jsonb, 'qāla rabbī yaʿlamu l-qawla fī l-samāi wal-arḍi wahuwa l-samīʿu l-ʿalīmu', 'বল, ‘আমার প্রতিপালক আসমান ও যমীনে (উচ্চারিত প্রতিটি) কথাই জানেন, আর তিনি সব কিছু শোনেন, সব কিছু জানেন।’', 'The Prophet said, "My Lord knows whatever is said throughout the heaven and earth, and He is the Hearing, the Knowing."', 'বল, ‘আমার প্রতিপালক আসমান ও যমীনে (উচ্চারিত প্রতিটি) কথাই জানেন, আর তিনি সব কিছু শোনেন, সব কিছু জানেন।’', 'The Prophet said, "My Lord knows whatever is said throughout the heaven and earth, and He is the Hearing, the Knowing."', NULL, NULL, NULL, NULL, NULL, 'https://everyayah.com/data/Alafasy_128kbps/021004.mp3', now()),
  (21, 5, '', '[{"id":4930,"position":1,"text_uthmani":"بَلْ","transliteration":"bal","translation_bn":"বরং","root":"—","lemma":"بَل\r","grammar_bn":"প্রত্যাহার পদ (Retraction)"},{"id":4931,"position":2,"text_uthmani":"قَالُوٓا۟","transliteration":"qālū","translation_bn":"তারা বলে","root":"قول","lemma":"قَالَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":4932,"position":3,"text_uthmani":"أَضْغَـٰثُ","transliteration":"aḍghāthu","translation_bn":"\"(এসব) অলীক","root":"ضغث","lemma":"ضِغْث","grammar_bn":"বিশেষ্য (Noun)"},{"id":4933,"position":4,"text_uthmani":"أَحْلَـٰمٍۭ","transliteration":"aḥlāmin","translation_bn":"স্বপ্নসমূহ","root":"حلم","lemma":"حُلُم","grammar_bn":"বিশেষ্য (Noun)"},{"id":4934,"position":5,"text_uthmani":"بَلِ","transliteration":"bali","translation_bn":"বরং","root":"—","lemma":"بَل\r","grammar_bn":"প্রত্যাহার পদ (Retraction)"},{"id":4935,"position":6,"text_uthmani":"ٱفْتَرَىٰهُ","transliteration":"if''tarāhu","translation_bn":"তা সে উদ্ভাবন করেছে","root":"فري","lemma":"ٱفْتَرَىٰ","grammar_bn":"ক্রিয়া (Verb)"},{"id":4936,"position":7,"text_uthmani":"بَلْ","transliteration":"bal","translation_bn":"বরং","root":"—","lemma":"بَل\r","grammar_bn":"প্রত্যাহার পদ (Retraction)"},{"id":4937,"position":8,"text_uthmani":"هُوَ","transliteration":"huwa","translation_bn":"সে","root":"—","lemma":"هُوَ","grammar_bn":"সর্বনাম (Pronoun)"},{"id":4938,"position":9,"text_uthmani":"شَاعِرٌۭ","transliteration":"shāʿirun","translation_bn":"একজন কবি","root":"شعر","lemma":"شَاعِر","grammar_bn":"বিশেষ্য (Noun)"},{"id":4939,"position":10,"text_uthmani":"فَلْيَأْتِنَا","transliteration":"falyatinā","translation_bn":"তাহ''লে আসুক আমাদের কাছে","root":"اتي","lemma":"أَتَى","grammar_bn":"শব্দ"},{"id":4940,"position":11,"text_uthmani":"بِـَٔايَةٍۢ","transliteration":"biāyatin","translation_bn":"কোন নিদর্শন","root":"ايي","lemma":"ءَايَة","grammar_bn":"অব্যয় (Preposition)"},{"id":4941,"position":12,"text_uthmani":"كَمَآ","transliteration":"kamā","translation_bn":"যেমন","root":"—","lemma":"مَا\r","grammar_bn":"অব্যয় (Preposition)"},{"id":4942,"position":13,"text_uthmani":"أُرْسِلَ","transliteration":"ur''sila","translation_bn":"পাঠানো হয়েছিলো","root":"رسل","lemma":"أَرْسَلَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":4943,"position":14,"text_uthmani":"ٱلْأَوَّلُونَ","transliteration":"l-awalūna","translation_bn":"পূর্ববর্তীগণকে (নিদর্শনসহ)\"","root":"اول","lemma":"أَوَّل","grammar_bn":"শব্দ"},{"id":4944,"position":15,"text_uthmani":"٥","transliteration":"","translation_bn":"(৫)","root":"—","lemma":"٥","grammar_bn":"মার্কার"}]'::jsonb, 'bal qālū aḍghāthu aḥlāmin bali if''tarāhu bal huwa shāʿirun falyatinā biāyatin kamā ur''sila l-awalūna', 'তারা এও বলে, ‘এসব অলীক স্বপ্ন, না হয় সে মিথ্যে উদ্ভাবন করেছে, না হয় সে একজন কবি। কাজেই সে আমাদের কাছে এমন নিদর্শন নিয়ে আসুক যেমন পূর্ববর্তী (নবী)-গণের কাছে পাঠানো হয়েছিল।', 'But they say, "[The revelation is but] a mixture of false dreams; rather, he has invented it; rather, he is a poet. So let him bring us a sign just as the previous [messengers] were sent [with miracles]."', 'তারা এও বলে, ‘এসব অলীক স্বপ্ন, না হয় সে মিথ্যে উদ্ভাবন করেছে, না হয় সে একজন কবি। কাজেই সে আমাদের কাছে এমন নিদর্শন নিয়ে আসুক যেমন পূর্ববর্তী (নবী)-গণের কাছে পাঠানো হয়েছিল।', 'But they say, "[The revelation is but] a mixture of false dreams; rather, he has invented it; rather, he is a poet. So let him bring us a sign just as the previous [messengers] were sent [with miracles]."', NULL, NULL, NULL, NULL, NULL, 'https://everyayah.com/data/Alafasy_128kbps/021005.mp3', now()),
  (21, 6, '', '[{"id":6185,"position":1,"text_uthmani":"مَآ","transliteration":"mā","translation_bn":"নি","root":"—","lemma":"مَا\r","grammar_bn":"না-বোধক (Negative)"},{"id":6186,"position":2,"text_uthmani":"ءَامَنَتْ","transliteration":"āmanat","translation_bn":"ঈমান আনে","root":"امن","lemma":"ءَامَنَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":6187,"position":3,"text_uthmani":"قَبْلَهُم","transliteration":"qablahum","translation_bn":"তাদের পূর্বে","root":"قبل","lemma":"قَبْل","grammar_bn":"কালবাচক (Time)"},{"id":6188,"position":4,"text_uthmani":"مِّن","transliteration":"min","translation_bn":"কোন","root":"—","lemma":"مِن\r","grammar_bn":"অব্যয় (Preposition)"},{"id":6189,"position":5,"text_uthmani":"قَرْيَةٍ","transliteration":"qaryatin","translation_bn":"জনবসতিই","root":"قري","lemma":"قَرْيَة","grammar_bn":"বিশেষ্য (Noun)"},{"id":6190,"position":6,"text_uthmani":"أَهْلَكْنَـٰهَآ ۖ","transliteration":"ahlaknāhā","translation_bn":"যাকে আমরা ধ্বংস করেছি","root":"هلك","lemma":"أَهْلَكَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":6192,"position":7,"text_uthmani":"أَفَهُمْ","transliteration":"afahum","translation_bn":"তবে কি এরা","root":"—","lemma":"أَفَهُمْ","grammar_bn":"প্রশ্নবোধক (Interrogative)"},{"id":6193,"position":8,"text_uthmani":"يُؤْمِنُونَ","transliteration":"yu''minūna","translation_bn":"ঈমান আনবে (এখন)","root":"امن","lemma":"ءَامَنَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":6194,"position":9,"text_uthmani":"٦","transliteration":"","translation_bn":"(৬)","root":"—","lemma":"٦","grammar_bn":"মার্কার"}]'::jsonb, 'mā āmanat qablahum min qaryatin ahlaknāhā afahum yu''minūna', 'তাদের পূর্বে আমি যে সমস্ত জনপদ ধ্বংস করেছি তাদের একটিও ঈমান আনেনি, তাহলে এরা কি ঈমান আনবে?', 'Not a [single] city which We destroyed believed before them, so will they believe?', 'তাদের পূর্বে আমি যে সমস্ত জনপদ ধ্বংস করেছি তাদের একটিও ঈমান আনেনি, তাহলে এরা কি ঈমান আনবে?', 'Not a [single] city which We destroyed believed before them, so will they believe?', NULL, NULL, NULL, NULL, NULL, 'https://every