  (21, 7, '', '[{"id":7555,"position":1,"text_uthmani":"وَمَآ","transliteration":"wamā","translation_bn":"এবং না (হে নবী)","root":"—","lemma":"مَا\r","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":7556,"position":2,"text_uthmani":"أَرْسَلْنَا","transliteration":"arsalnā","translation_bn":"আমরা পাঠিয়েছি","root":"رسل","lemma":"أَرْسَلَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":7557,"position":3,"text_uthmani":"قَبْلَكَ","transliteration":"qablaka","translation_bn":"তোমার পূর্বে (কোন রাসূলকে)","root":"قبل","lemma":"قَبْل","grammar_bn":"কালবাচক (Time)"},{"id":7558,"position":4,"text_uthmani":"إِلَّا","transliteration":"illā","translation_bn":"এ ছাড়া যে","root":"—","lemma":"إِلَّا\r","grammar_bn":"সীমাবদ্ধতা (Restriction)"},{"id":7559,"position":5,"text_uthmani":"رِجَالًۭا","transliteration":"rijālan","translation_bn":"(সে ছিলো) পুরুষ","root":"رجل","lemma":"رِجَال","grammar_bn":"বিশেষ্য (Noun)"},{"id":7560,"position":6,"text_uthmani":"نُّوحِىٓ","transliteration":"nūḥī","translation_bn":"ওহী করতাম আমরা","root":"وحي","lemma":"أَوْحَىٰ^","grammar_bn":"ক্রিয়া (Verb)"},{"id":7561,"position":7,"text_uthmani":"إِلَيْهِمْ ۖ","transliteration":"ilayhim","translation_bn":"তাদের কাছে","root":"—","lemma":"إِلَىٰ\r","grammar_bn":"অব্যয় (Preposition)"},{"id":7563,"position":8,"text_uthmani":"فَسْـَٔلُوٓا۟","transliteration":"fasalū","translation_bn":"অতএব জিজ্ঞেস করো","root":"سال","lemma":"سَأَلَ","grammar_bn":"শব্দ"},{"id":7564,"position":9,"text_uthmani":"أَهْلَ","transliteration":"ahla","translation_bn":"অধিকারীদের","root":"اهل","lemma":"أَهْل","grammar_bn":"বিশেষ্য (Noun)"},{"id":7565,"position":10,"text_uthmani":"ٱلذِّكْرِ","transliteration":"l-dhik''ri","translation_bn":"জ্ঞানের","root":"ذكر","lemma":"ذِكْر","grammar_bn":"শব্দ"},{"id":7566,"position":11,"text_uthmani":"إِن","transliteration":"in","translation_bn":"যদি","root":"—","lemma":"إِن\r","grammar_bn":"শর্তবাচক (Conditional)"},{"id":7567,"position":12,"text_uthmani":"كُنتُمْ","transliteration":"kuntum","translation_bn":"তোমরা","root":"كون","lemma":"كَانَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":7568,"position":13,"text_uthmani":"لَا","transliteration":"lā","translation_bn":"না","root":"—","lemma":"لَا\r","grammar_bn":"না-বোধক (Negative)"},{"id":7569,"position":14,"text_uthmani":"تَعْلَمُونَ","transliteration":"taʿlamūna","translation_bn":"জানো","root":"علم","lemma":"عَلِمَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":7570,"position":15,"text_uthmani":"٧","transliteration":"","translation_bn":"(৭)","root":"—","lemma":"٧","grammar_bn":"মার্কার"}]'::jsonb, 'wamā arsalnā qablaka illā rijālan nūḥī ilayhim fasalū ahla l-dhik''ri in kuntum lā taʿlamūna', 'তোমার পূর্বে যে সব রসূল পাঠিয়েছিলাম যাদের প্রতি আমি ওয়াহী করতাম তারা মানুষই ছিল, তোমরা যদি না জান তবে (অবতীর্ণ) কিতাবের জ্ঞান যাদের আছে তাদেরকে জিজ্ঞেস কর।', 'And We sent not before you, [O Muhammad], except men to whom We revealed [the message], so ask the people of the message if you do not know.', 'তোমার পূর্বে যে সব রসূল পাঠিয়েছিলাম যাদের প্রতি আমি ওয়াহী করতাম তারা মানুষই ছিল, তোমরা যদি না জান তবে (অবতীর্ণ) কিতাবের জ্ঞান যাদের আছে তাদেরকে জিজ্ঞেস কর।', 'And We sent not before you, [O Muhammad], except men to whom We revealed [the message], so ask the people of the message if you do not know.', NULL, NULL, NULL, NULL, NULL, 'https://everyayah.com/data/Alafasy_128kbps/021007.mp3', now()),
  (21, 8, '', '[{"id":8769,"position":1,"text_uthmani":"وَمَا","transliteration":"wamā","translation_bn":"এবং নি","root":"—","lemma":"مَا\r","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":8770,"position":2,"text_uthmani":"جَعَلْنَـٰهُمْ","transliteration":"jaʿalnāhum","translation_bn":"তাদের আমরা বানাই","root":"جعل","lemma":"جَعَلَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":8771,"position":3,"text_uthmani":"جَسَدًۭا","transliteration":"jasadan","translation_bn":"(এমন) দেহ বিশিষ্ট","root":"جسد","lemma":"جَسَد","grammar_bn":"বিশেষ্য (Noun)"},{"id":8772,"position":4,"text_uthmani":"لَّا","transliteration":"lā","translation_bn":"যে না","root":"—","lemma":"لَا\r","grammar_bn":"না-বোধক (Negative)"},{"id":8773,"position":5,"text_uthmani":"يَأْكُلُونَ","transliteration":"yakulūna","translation_bn":"তারা খেতো","root":"اكل","lemma":"أَكَلَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":8774,"position":6,"text_uthmani":"ٱلطَّعَامَ","transliteration":"l-ṭaʿāma","translation_bn":"খাবার","root":"طعم","lemma":"طَعَام","grammar_bn":"শব্দ"},{"id":8775,"position":7,"text_uthmani":"وَمَا","transliteration":"wamā","translation_bn":"আর না","root":"—","lemma":"مَا\r","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":8776,"position":8,"text_uthmani":"كَانُوا۟","transliteration":"kānū","translation_bn":"তারা ছিলো","root":"كون","lemma":"كَانَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":8777,"position":9,"text_uthmani":"خَـٰلِدِينَ","transliteration":"khālidīna","translation_bn":"চিরস্থায়ী","root":"خلد","lemma":"خَٰلِد","grammar_bn":"বিশেষ্য (Noun)"},{"id":8778,"position":10,"text_uthmani":"٨","transliteration":"","translation_bn":"(৮)","root":"—","lemma":"٨","grammar_bn":"মার্কার"}]'::jsonb, 'wamā jaʿalnāhum jasadan lā yakulūna l-ṭaʿāma wamā kānū khālidīna', 'তাদেরকে এমন দেহবিশিষ্ট করিনি যে তারা খাদ্য খেত না আর তারা ছিল না চিরস্থায়ী।', 'And We did not make the prophets forms not eating food, nor were they immortal [on earth].', 'তাদেরকে এমন দেহবিশিষ্ট করিনি যে তারা খাদ্য খেত না আর তারা ছিল না চিরস্থায়ী।', 'And We did not make the prophets forms not eating food, nor were they immortal [on earth].', NULL, NULL, NULL, NULL, NULL, 'https://everyayah.com/data/Alafasy_128kbps/021008.mp3', now()),
  (21, 9, '', '[{"id":9982,"position":1,"text_uthmani":"ثُمَّ","transliteration":"thumma","translation_bn":"এরপর","root":"—","lemma":"ثُمّ\r","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":9983,"position":2,"text_uthmani":"صَدَقْنَـٰهُمُ","transliteration":"ṣadaqnāhumu","translation_bn":"তাদের প্রতি আমরা সত্য করে দেখালাম","root":"صدق","lemma":"صَدَقَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":9984,"position":3,"text_uthmani":"ٱلْوَعْدَ","transliteration":"l-waʿda","translation_bn":"প্রতিশ্রুতি","root":"وعد","lemma":"وَعْد","grammar_bn":"শব্দ"},{"id":9985,"position":4,"text_uthmani":"فَأَنجَيْنَـٰهُمْ","transliteration":"fa-anjaynāhum","translation_bn":"অতঃপর তাদেরকে আমরা রক্ষা করেছি","root":"نجو","lemma":"أَنجَىٰ","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":9986,"position":5,"text_uthmani":"وَمَن","transliteration":"waman","translation_bn":"ও যাদেরকে","root":"—","lemma":"مَن\r","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":9987,"position":6,"text_uthmani":"نَّشَآءُ","transliteration":"nashāu","translation_bn":"চেয়েছি আমরা","root":"شيا","lemma":"شَا^ءَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":9988,"position":7,"text_uthmani":"وَأَهْلَكْنَا","transliteration":"wa-ahlaknā","translation_bn":"এবং আমরা ধ্বংস করেছি","root":"هلك","lemma":"أَهْلَكَ","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":9989,"position":8,"text_uthmani":"ٱلْمُسْرِفِينَ","transliteration":"l-mus''rifīna","translation_bn":"সীমালঙ্ঘনকারীদেরকে","root":"سرف","lemma":"مُسْرِف","grammar_bn":"শব্দ"},{"id":9990,"position":9,"text_uthmani":"٩","transliteration":"","translation_bn":"(৯)","root":"—","lemma":"٩","grammar_bn":"মার্কার"}]'::jsonb, 'thumma ṣadaqnāhumu l-waʿda fa-anjaynāhum waman nashāu wa-ahlaknā l-mus''rifīna', 'অতঃপর আমি তাদেরকে দেয়া আমার ওয়া‘দা সত্যে পরিণত করলাম। ফলতঃ আমি তাদেরকে এবং আরো যাদেরকে চাইলাম রক্ষা করলাম আর সীমালঙ্ঘনকারীদেরকে ধ্বংস করে দিলাম।', 'Then We fulfilled for them the promise, and We saved them and whom We willed and destroyed the transgressors.', 'অতঃপর আমি তাদেরকে দেয়া আমার ওয়া‘দা সত্যে পরিণত করলাম। ফলতঃ আমি তাদেরকে এবং আরো যাদেরকে চাইলাম রক্ষা করলাম আর সীমালঙ্ঘনকারীদেরকে ধ্বংস করে দিলাম।', 'Then We fulfilled for them the promise, and We saved them and whom We willed and destroyed the transgressors.', NULL, NULL, NULL, NULL, NULL, 'https://everyayah.com/data/Alafasy_128kbps/021009.mp3', now()),
  (21, 10, '', '[{"id":11192,"position":1,"text_uthmani":"لَقَدْ","transliteration":"laqad","translation_bn":"নিশ্চয়ই","root":"—","lemma":"قَد\r","grammar_bn":"দৃঢ়তাবোধক (Emphatic)"},{"id":11193,"position":2,"text_uthmani":"أَنزَلْنَآ","transliteration":"anzalnā","translation_bn":"আমরা অবতীর্ণ করেছি","root":"نزل","lemma":"أَنزَلَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":11194,"position":3,"text_uthmani":"إِلَيْكُمْ","transliteration":"ilaykum","translation_bn":"তোমাদের প্রতি","root":"—","lemma":"إِلَىٰ\r","grammar_bn":"অব্যয় (Preposition)"},{"id":11195,"position":4,"text_uthmani":"كِتَـٰبًۭا","transliteration":"kitāban","translation_bn":"কিতাব","root":"كتب","lemma":"كِتَٰب","grammar_bn":"বিশেষ্য (Noun)"},{"id":11196,"position":5,"text_uthmani":"فِيهِ","transliteration":"fīhi","translation_bn":"তার মধ্যে (রয়েছে)","root":"—","lemma":"فِى\r","grammar_bn":"অব্যয় (Preposition)"},{"id":11197,"position":6,"text_uthmani":"ذِكْرُكُمْ ۖ","transliteration":"dhik''rukum","translation_bn":"তোমাদেরই বর্ণনা","root":"ذكر","lemma":"ذِكْر","grammar_bn":"বিশেষ্য (Noun)"},{"id":11199,"position":7,"text_uthmani":"أَفَلَا","transliteration":"afalā","translation_bn":"তবে কি না","root":"—","lemma":"لَا\r","grammar_bn":"প্রশ্নবোধক (Interrogative)"},{"id":11200,"position":8,"text_uthmani":"تَعْقِلُونَ","transliteration":"taʿqilūna","translation_bn":"তোমরা বুঝবে","root":"عقل","lemma":"عَقَلُ","grammar_bn":"ক্রিয়া (Verb)"},{"id":11201,"position":9,"text_uthmani":"١٠","transliteration":"","translation_bn":"(১০)","root":"—","lemma":"١٠","grammar_bn":"মার্কার"}]'::jsonb, 'laqad anzalnā ilaykum kitāban fīhi dhik''rukum afalā taʿqilūna', 'আমি তোমাদের প্রতি নাযিল করেছি এক কিতাব যাতে তোমাদের জন্য আছে উপদেশ, তোমরা কি তবুও বুঝবে না?', 'We have certainly sent down to you a Book in which is your mention. Then will you not reason?', 'আমি তোমাদের প্রতি নাযিল করেছি এক কিতাব যাতে তোমাদের জন্য আছে উপদেশ, তোমরা কি তবুও বুঝবে না?', 'We have certainly sent down to you a Book in which is your mention. Then will you not reason?', NULL, NULL, NULL, NULL, NULL, 'https://everyayah.com/data/Alafasy_128kbps/021010.mp3', now()),
  (21, 11, '', '[{"id":12502,"position":1,"text_uthmani":"وَكَمْ","transliteration":"wakam","translation_bn":"এবং কত","root":"—","lemma":"كَم\r","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":12503,"position":2,"text_uthmani":"قَصَمْنَا","transliteration":"qaṣamnā","translation_bn":"আমরা ধ্বংস করেছি","root":"قصم","lemma":"قَصَمْ","grammar_bn":"ক্রিয়া (Verb)"},{"id":12504,"position":3,"text_uthmani":"مِن","transliteration":"min","translation_bn":"থেকে","root":"—","lemma":"مِن\r","grammar_bn":"অব্যয় (Preposition)"},{"id":12505,"position":4,"text_uthmani":"قَرْيَةٍۢ","transliteration":"qaryatin","translation_bn":"জনবসতি","root":"قري","lemma":"قَرْيَة","grammar_bn":"বিশেষ্য (Noun)"},{"id":12506,"position":5,"text_uthmani":"كَانَتْ","transliteration":"kānat","translation_bn":"যা ছিল","root":"كون","lemma":"كَانَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":12507,"position":6,"text_uthmani":"ظَالِمَةًۭ","transliteration":"ẓālimatan","translation_bn":"সীমালঙ্ঘনকারী","root":"ظلم","lemma":"ظَالِمَة","grammar_bn":"বিশেষ্য (Noun)"},{"id":12508,"position":7,"text_uthmani":"وَأَنشَأْنَا","transliteration":"wa-anshanā","translation_bn":"এবং আমরা সৃষ্টি করেছি","root":"نشا","lemma":"أَنشَأَ","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":12509,"position":8,"text_uthmani":"بَعْدَهَا","transliteration":"baʿdahā","translation_bn":"পরে তার","root":"بعد","lemma":"بَعْد","grammar_bn":"কালবাচক (Time)"},{"id":12510,"position":9,"text_uthmani":"قَوْمًا","transliteration":"qawman","translation_bn":"জাতি","root":"قوم","lemma":"قَوْم","grammar_bn":"বিশেষ্য (Noun)"},{"id":12511,"position":10,"text_uthmani":"ءَاخَرِينَ","transliteration":"ākharīna","translation_bn":"অপর","root":"اخر","lemma":"ا^خَر","grammar_bn":"বিশেষণ (Adjective)"},{"id":12512,"position":11,"text_uthmani":"١١","transliteration":"","translation_bn":"(১১)","root":"—","lemma":"١١","grammar_bn":"মার্কার"}]'::jsonb, 'wakam qaṣamnā min qaryatin kānat ẓālimatan wa-anshanā baʿdahā qawman ākharīna', 'কত জনপদ ছিল যেগুলোকে আমি পুরোপুরি ধ্বংস করে দিয়েছি যার অধিবাসীরা ছিল যালিম। তাদের পরে আমি অন্য জাতি সৃষ্টি করেছি।', 'And how many a city which was unjust have We shattered and produced after it another people.', 'কত জনপদ ছিল যেগুলোকে আমি পুরোপুরি ধ্বংস করে দিয়েছি যার অধিবাসীরা ছিল যালিম। তাদের পরে আমি অন্য জাতি সৃষ্টি করেছি।', 'And how many a city which was unjust have We shattered and produced after it another people.', NULL, NULL, NULL, NULL, NULL, 'https://everyayah.com/data/Alafasy_128kbps/021011.mp3', now()),
  (21, 12, '', '[{"id":13829,"position":1,"text_uthmani":"فَلَمَّآ","transliteration":"falammā","translation_bn":"অতঃপর যখন","root":"—","lemma":"لَمَّا\r","grammar_bn":"শব্দ"},{"id":13830,"position":2,"text_uthmani":"أَحَسُّوا۟","transliteration":"aḥassū","translation_bn":"তারা অনুভবব করলো","root":"حسس","lemma":"أَحَسَّ","grammar_bn":"ক্রিয়া (Verb)"},{"id":13831,"position":3,"text_uthmani":"بَأْسَنَآ","transliteration":"basanā","translation_bn":"আমাদের শাস্তি","root":"باس","lemma":"بَأْس","grammar_bn":"বিশেষ্য (Noun)"},{"id":13832,"position":4,"text_uthmani":"إِذَا","transliteration":"idhā","translation_bn":"তখন","root":"—","lemma":"إِذَا\r","grammar_bn":"কালবাচক (Time)"},{"id":13833,"position":5,"text_uthmani":"هُم","transliteration":"hum","translation_bn":"তারা","root":"—","lemma":"هُم","grammar_bn":"সর্বনাম (Pronoun)"},{"id":13834,"position":6,"text_uthmani":"مِّنْهَا","transliteration":"min''hā","translation_bn":"তা থেকে","root":"—","lemma":"مِن\r","grammar_bn":"অব্যয় (Preposition)"},{"id":13835,"position":7,"text_uthmani":"يَرْكُضُونَ","transliteration":"yarkuḍūna","translation_bn":"পালাতে লাগলো","root":"ركض","lemma":"يَرْكُضُ","grammar_bn":"ক্রিয়া (Verb)"},{"id":13836,"position":8,"text_uthmani":"١٢","transliteration":"","translation_bn":"(১২)","root":"—","lemma":"١٢","grammar_bn":"মার্কার"}]'::jsonb, 'falammā aḥassū basanā idhā hum min''hā yarkuḍūna', 'তারা যখন আমার শাস্তি (’র আগমন) অনুভব করল, তখন তারা তাত্থেকে পালিয়ে যেতে (চেষ্টা) করল।', 'And when its inhabitants perceived Our punishment, at once they fled from it.', 'তারা যখন আমার শাস্তি (’র আগমন) অনুভব করল, তখন তারা তাত্থেকে পালিয়ে যেতে (চেষ্টা) করল।', 'And when its inhabitants perceived Our punishment, at once they fled from it.', NULL, NULL, NULL, NULL, NULL, 'https://everyayah.com/data/Alafasy_128kbps/021012.mp3', now()),
  (21, 13, '', '[{"id":14979,"position":1,"text_uthmani":"لَا","transliteration":"lā","translation_bn":"(বলা হলো) না","root":"—","lemma":"لَا\r","grammar_bn":"নিষেধবাচক (Prohibition)"},{"id":14980,"position":2,"text_uthmani":"تَرْكُضُوا۟","transliteration":"tarkuḍū","translation_bn":"তোমরা পালাবে","root":"ركض","lemma":"يَرْكُضُ","grammar_bn":"ক্রিয়া (Verb)"},{"id":14981,"position":3,"text_uthmani":"وَٱرْجِعُوٓا۟","transliteration":"wa-ir''jiʿū","translation_bn":"বরং তোমরা ফিরে যাও","root":"رجع","lemma":"رَجَعَ","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":14982,"position":4,"text_uthmani":"إِلَىٰ","transliteration":"ilā","translation_bn":"দিকে","root":"—","lemma":"إِلَىٰ\r","grammar_bn":"অব্যয় (Preposition)"},{"id":14983,"position":5,"text_uthmani":"مَآ","transliteration":"mā","translation_bn":"তার","root":"—","lemma":"مَا\r","grammar_bn":"সাপেক্ষ সর্বনাম (Relative)"},{"id":14984,"position":6,"text_uthmani":"أُتْرِفْتُمْ","transliteration":"ut''rif''tum","translation_bn":"তোমাদের সম্ভোগ দেয়া হয়েছিলো","root":"ترف","lemma":"أُتْرِفُ","grammar_bn":"ক্রিয়া (Verb)"},{"id":14985,"position":7,"text_uthmani":"فِيهِ","transliteration":"fīhi","translation_bn":"যার মধ্যে","root":"—","lemma":"فِى\r","grammar_bn":"অব্যয় (Preposition)"},{"id":14986,"position":8,"text_uthmani":"وَمَسَـٰكِنِكُمْ","transliteration":"wamasākinikum","translation_bn":"ও ঘরবাড়িগুলোতে তোমাদের","root":"سكن","lemma":"مَسْكَن","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":14987,"position":9,"text_uthmani":"لَعَلَّكُمْ","transliteration":"laʿallakum","translation_bn":"যাতে তোমাদের","root":"—","lemma":"لَعَلّ","grammar_bn":"অভিঘাত পদ (Accusative)"},{"id":14988,"position":10,"text_uthmani":"تُسْـَٔلُونَ","transliteration":"tus''alūna","translation_bn":"জিজ্ঞাসাবাদ করা যেতে পারে","root":"سال","lemma":"سَأَلَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":14989,"position":11,"text_uthmani":"١٣","transliteration":"","translation_bn":"(১৩)","root":"—","lemma":"١٣","grammar_bn":"মার্কার"}]'::jsonb, 'lā tarkuḍū wa-ir''jiʿū ilā mā ut''rif''tum fīhi wamasākinikum laʿallakum tus''alūna', '(ফেরেশতারা তাদেরকে ঠাট্টা করে বলেছিল) পালিয়ে যেয়ো না, ফিরে এসো তোমরা যে ভোগ-বিলাসে মত্ত ছিলে তার দিকে আর তোমাদের আবাসগুলোতে, যাতে তোমাদেরকে জিজ্ঞাসাবাদ করা যায় (‘আযাবের রূপটা কেমন দেখলে?)।', '[Some angels said], "Do not flee but return to where you were given luxury and to your homes - perhaps you will be questioned."', '(ফেরেশতারা তাদেরকে ঠাট্টা করে বলেছিল) পালিয়ে যেয়ো না, ফিরে এসো তোমরা যে ভোগ-বিলাসে মত্ত ছিলে তার দিকে আর তোমাদের আবাসগুলোতে, যাতে তোমাদেরকে জিজ্ঞাসাবাদ করা যায় (‘আযাবের রূপটা কেমন দেখলে?)।', '[Some angels said], "Do not flee but return to where you were given luxury and to your homes - perhaps you will be questioned."', NULL, NULL, NULL, NULL, NULL, 'https://everyayah.com/data/Alafasy_128kbps/021013.mp3', now()),
  (21, 14, '', '[{"id":16625,"position":1,"text_uthmani":"قَالُوا۟","transliteration":"qālū","translation_bn":"তারা বলেছিলো","root":"قول","lemma":"قَالَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":16626,"position":2,"text_uthmani":"يَـٰوَيْلَنَآ","transliteration":"yāwaylanā","translation_bn":"\"হায় আমাদের দুর্ভোগ","root":"—","lemma":"وَيْل","grammar_bn":"সম্বোধন পদ (Vocative)"},{"id":16627,"position":3,"text_uthmani":"إِنَّا","transliteration":"innā","translation_bn":"নিশ্চয়ই আমরা","root":"—","lemma":"إِنّ","grammar_bn":"অভিঘাত পদ (Accusative)"},{"id":16628,"position":4,"text_uthmani":"كُنَّا","transliteration":"kunnā","translation_bn":"ছিলাম","root":"كون","lemma":"كَانَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":16629,"position":5,"text_uthmani":"ظَـٰلِمِينَ","transliteration":"ẓālimīna","translation_bn":"অত্যাচারী\"","root":"ظلم","lemma":"ظَالِم","grammar_bn":"বিশেষ্য (Noun)"},{"id":16630,"position":6,"text_uthmani":"١٤","transliteration":"","translation_bn":"(১৪)","root":"—","lemma":"١٤","grammar_bn":"মার্কার"}]'::jsonb, 'qālū yāwaylanā innā kunnā ẓālimīna', 'তারা বলল, ‘হায় আমাদের দুর্ভাগ্য! আমরা সত্যিই অন্যায়কারী ছিলাম।’', 'They said, "O woe to us! Indeed, we were wrongdoers."', 'তারা বলল, ‘হায় আমাদের দুর্ভাগ্য! আমরা সত্যিই অন্যায়কারী ছিলাম।’', 'They said, "O woe to us! Indeed, we were wrongdoers."', NULL, NULL, NULL, NULL, NULL, 'https://everyayah.com/data/Alafasy_128kbps/021014.mp3', now()),
  (21, 15, '', '[{"id":17296,"position":1,"text_uthmani":"فَمَا","transliteration":"famā","translation_bn":"অতঃপর","root":"—","lemma":"مَا\r","grammar_bn":"শব্দ"},{"id":17297,"position":2,"text_uthmani":"زَالَت","transliteration":"zālat","translation_bn":"চলতে থাকে","root":"زيل","lemma":"زَالَت","grammar_bn":"ক্রিয়া (Verb)"},{"id":17298,"position":3,"text_uthmani":"تِّلْكَ","transliteration":"til''ka","translation_bn":"এই","root":"—","lemma":"ذَٰلِك","grammar_bn":"নির্দেশক সর্বনাম (Demonstrative)"},{"id":17299,"position":4,"text_uthmani":"دَعْوَىٰهُمْ","transliteration":"daʿwāhum","translation_bn":"তাদের আর্তনাদ","root":"دعو","lemma":"دَعْوَىٰ","grammar_bn":"বিশেষ্য (Noun)"},{"id":17300,"position":5,"text_uthmani":"حَتَّىٰ","transliteration":"ḥattā","translation_bn":"যতক্ষণ না","root":"—","lemma":"حَتَّىٰ\r","grammar_bn":"অব্যয় (Preposition)"},{"id":17301,"position":6,"text_uthmani":"جَعَلْنَـٰهُمْ","transliteration":"jaʿalnāhum","translation_bn":"তাদেরকে আমরা পরিণত করি","root":"جعل","lemma":"جَعَلَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":17302,"position":7,"text_uthmani":"حَصِيدًا","transliteration":"ḥaṣīdan","translation_bn":"কাটা শস্য","root":"حصد","lemma":"حَصِيد","grammar_bn":"বিশেষ্য (Noun)"},{"id":17303,"position":8,"text_uthmani":"خَـٰمِدِينَ","transliteration":"khāmidīna","translation_bn":"নেভানো আগুনের মতো","root":"خمد","lemma":"خَٰمِدِين","grammar_bn":"বিশেষ্য (Noun)"},{"id":17304,"position":9,"text_uthmani":"١٥","transliteration":"","translation_bn":"(১৫)","root":"—","lemma":"١٥","grammar_bn":"মার্কার"}]'::jsonb, 'famā zālat til''ka daʿwāhum ḥattā jaʿalnāhum ḥaṣīdan khāmidīna', 'তাদের এ আর্তনাদ বন্ধ হয়নি যতক্ষণ না আমি তাদেরকে করেছিলাম কাটা শস্য ও নিভানো আগুনের মত।', 'And that declaration of theirs did not cease until We made them [as] a harvest [mowed down], extinguished [like a fire].', 'তাদের এ আর্তনাদ বন্ধ হয়নি যতক্ষণ না আমি তাদেরকে করেছিলাম কাটা শস্য ও নিভানো আগুনের মত।', 'And that declaration of theirs did not cease until We made them [as] a harvest [mowed down], extinguished [like a fire].', NULL, NULL, NULL, NULL, NULL, 'https://everyayah.com/data/Alafasy_128kbps/021015.mp3', now()),
  (21, 16, '', '[{"id":18349,"position":1,"text_uthmani":"وَمَا","transliteration":"wamā","translation_bn":"এবং না","root":"—","lemma":"مَا\r","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":18350,"position":2,"text_uthmani":"خَلَقْنَا","transliteration":"khalaqnā","translation_bn":"আমরা সৃষ্টি করেছি","root":"خلق","lemma":"خَلَقَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":18351,"position":3,"text_uthmani":"ٱلسَّمَآءَ","transliteration":"l-samāa","translation_bn":"আকাশ","root":"سمو","lemma":"سَمَا^ء","grammar_bn":"শব্দ"},{"id":18352,"position":4,"text_uthmani":"وَٱلْأَرْضَ","transliteration":"wal-arḍa","translation_bn":"ও পৃথিবীকে","root":"ارض","lemma":"أَرْض","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":18353,"position":5,"text_uthmani":"وَمَا","transliteration":"wamā","translation_bn":"আর যা কিছু","root":"—","lemma":"مَا\r","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":18354,"position":6,"text_uthmani":"بَيْنَهُمَا","transliteration":"baynahumā","translation_bn":"উভয়ের মাঝে","root":"بين","lemma":"بَيْن","grammar_bn":"স্থানবাচক (Location)"},{"id":18355,"position":7,"text_uthmani":"لَـٰعِبِينَ","transliteration":"lāʿibīna","translation_bn":"খেলার ছলে","root":"لعب","lemma":"لَٰعِبِين","grammar_bn":"বিশেষ্য (Noun)"},{"id":18356,"position":8,"text_uthmani":"١٦","transliteration":"","translation_bn":"(১৬)","root":"—","lemma":"١٦","grammar_bn":"মার্কার"}]'::jsonb, 'wamā khalaqnā l-samāa wal-arḍa wamā baynahumā lāʿibīna', 'আসমান, যমীন আর এ দু’য়ের মধ্যে যা কিছু আছে তা আমি খেলতে খেলতে বানাইনি।', 'And We did not create the heaven and earth and that between them in play.', 'আসমান, যমীন আর এ দু’য়ের মধ্যে যা কিছু আছে তা আমি খেলতে খেলতে বানাইনি।', 'And We did not create the heaven and earth and that between them in play.', NULL, NULL, NULL, NULL, NULL, 'https://everyayah.com/data/Alafasy_128kbps/021016.mp3', now()),
  (21, 17, '', '[{"id":19369,"position":1,"text_uthmani":"لَوْ","transliteration":"law","translation_bn":"যদি","root":"—","lemma":"لَو\r","grammar_bn":"শর্তবাচক (Conditional)"},{"id":19370,"position":2,"text_uthmani":"أَرَدْنَآ","transliteration":"aradnā","translation_bn":"আমরা চাইতাম","root":"رود","lemma":"أَرَادَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":19371,"position":3,"text_uthmani":"أَن","transliteration":"an","translation_bn":"যে","root":"—","lemma":"أَن\r","grammar_bn":"অধীনস্থ যোজক (Subordinating)"},{"id":19372,"position":4,"text_uthmani":"نَّتَّخِذَ","transliteration":"nattakhidha","translation_bn":"আমরা গ্রহণ করবো","root":"اخذ","lemma":"ٱتَّخَذَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":19373,"position":5,"text_uthmani":"لَهْوًۭا","transliteration":"lahwan","translation_bn":"(এসব সৃষ্টি) খেলা রূপে","root":"لهو","lemma":"لَهْو","grammar_bn":"বিশেষ্য (Noun)"},{"id":19374,"position":6,"text_uthmani":"لَّٱتَّخَذْنَـٰهُ","transliteration":"la-ittakhadhnāhu","translation_bn":"অবশ্যই তা আমরা (খেলা হিসেবে) নিতাম","root":"اخذ","lemma":"ٱتَّخَذَ","grammar_bn":"দৃঢ়তাবোধক (Emphatic)"},{"id":19375,"position":7,"text_uthmani":"مِن","transliteration":"min","translation_bn":"থেকে","root":"—","lemma":"مِن\r","grammar_bn":"অব্যয় (Preposition)"},{"id":19376,"position":8,"text_uthmani":"لَّدُنَّآ","transliteration":"ladunnā","translation_bn":"আমাদের কাছ (সীমাবদ্ধ রেখে)","root":"لدن","lemma":"لَّدُن","grammar_bn":"বিশেষ্য (Noun)"},{"id":19377,"position":9,"text_uthmani":"إِن","transliteration":"in","translation_bn":"যদি","root":"—","lemma":"إِن\r","grammar_bn":"শর্তবাচক (Conditional)"},{"id":19378,"position":10,"text_uthmani":"كُنَّا","transliteration":"kunnā","translation_bn":"আমরা হতাম","root":"كون","lemma":"كَانَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":19379,"position":11,"text_uthmani":"فَـٰعِلِينَ","transliteration":"fāʿilīna","translation_bn":"(খেলা) করার","root":"فعل","lemma":"فَاعِل","grammar_bn":"বিশেষ্য (Noun)"},{"id":19380,"position":12,"text_uthmani":"١٧","transliteration":"","translation_bn":"(১৭)","root":"—","lemma":"١٧","grammar_bn":"মার্কার"}]'::jsonb, 'law aradnā an nattakhidha lahwan la-ittakhadhnāhu min ladunnā in kunnā fāʿilīna', 'আমি যদি খেলাধূলার বস্তু বানাতে চাইতাম তাহলে আমার কাছে যা আছে তা নিয়েই তা করতাম, যদি আমাকে করতে হত!', 'Had We intended to take a diversion, We could have taken it from [what is] with Us - if [indeed] We were to do so.', 'আমি যদি খেলাধূলার বস্তু বানাতে চাইতাম তাহলে আমার কাছে যা আছে তা নিয়েই তা করতাম, যদি আমাকে করতে হত!', 'Had We intended to take a diversion, We could have taken it from [what is] with Us - if [indeed] We were to do so.', NULL, NULL, NULL, NULL, NULL, 'https://everyayah.com/data/Alafasy_128kbps/021017.mp3', now()),
  (21, 18, '', '[{"id":20426,"position":1,"text_uthmani":"بَلْ","transliteration":"bal","translation_bn":"(ব্যাপার তা নয়) বরং","root":"—","lemma":"بَل\r","grammar_bn":"প্রত্যাহার পদ (Retraction)"},{"id":20427,"position":2,"text_uthmani":"نَقْذِفُ","transliteration":"naqdhifu","translation_bn":"আঘাত হানি আমরা","root":"قذف","lemma":"قَذَفَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":20428,"position":3,"text_uthmani":"بِٱلْحَقِّ","transliteration":"bil-ḥaqi","translation_bn":"দিয়ে সত্য","root":"حقق","lemma":"حَقّ","grammar_bn":"অব্যয় (Preposition)"},{"id":20429,"position":4,"text_uthmani":"عَلَى","transliteration":"ʿalā","translation_bn":"উপর","root":"—","lemma":"عَلَىٰ\r","grammar_bn":"অব্যয় (Preposition)"},{"id":20430,"position":5,"text_uthmani":"ٱلْبَـٰطِلِ","transliteration":"l-bāṭili","translation_bn":"মিথ্যার","root":"بطل","lemma":"بَٰطِل","grammar_bn":"শব্দ"},{"id":20431,"position":6,"text_uthmani":"فَيَدْمَغُهُۥ","transliteration":"fayadmaghuhu","translation_bn":"ফলে তাকে চূর্ণবিচূর্ণ করে দেয়","root":"دمغ","lemma":"يَدْمَغُ","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":20432,"position":7,"text_uthmani":"فَإِذَا","transliteration":"fa-idhā","translation_bn":"অতঃপর তখন","root":"—","lemma":"إِذَا\r","grammar_bn":"শব্দ"},{"id":20433,"position":8,"text_uthmani":"هُوَ","transliteration":"huwa","translation_bn":"তা","root":"—","lemma":"هُوَ","grammar_bn":"সর্বনাম (Pronoun)"},{"id":20434,"position":9,"text_uthmani":"زَاهِقٌۭ ۚ","transliteration":"zāhiqun","translation_bn":"নিশ্চিহ্ন হয়ে যায়","root":"زهق","lemma":"زَاهِق","grammar_bn":"বিশেষ্য (Noun)"},{"id":20436,"position":10,"text_uthmani":"وَلَكُمُ","transliteration":"walakumu","translation_bn":"আর তোমাদের জন্যে আছে","root":"—","lemma":"وَلَكُمُ","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":20437,"position":11,"text_uthmani":"ٱلْوَيْلُ","transliteration":"l-waylu","translation_bn":"দুর্ভোগ","root":"—","lemma":"وَيْل","grammar_bn":"শব্দ"},{"id":20438,"position":12,"text_uthmani":"مِمَّا","transliteration":"mimmā","translation_bn":"সে কারণে যা","root":"—","lemma":"مِن\r","grammar_bn":"অব্যয় (Preposition)"},{"id":20439,"position":13,"text_uthmani":"تَصِفُونَ","transliteration":"taṣifūna","translation_bn":"তোমরা রচনা করছো","root":"وصف","lemma":"يَصِفُ","grammar_bn":"ক্রিয়া (Verb)"},{"id":20440,"position":14,"text_uthmani":"١٨","transliteration":"","translation_bn":"(১৮)","root":"—","lemma":"١٨","grammar_bn":"মার্কার"}]'::jsonb, 'bal naqdhifu bil-ḥaqi ʿalā l-bāṭili fayadmaghuhu fa-idhā huwa zāhiqun walakumu l-waylu mimmā taṣifūna', 'বরং আমি সত্যকে মিথ্যের উপর নিক্ষেপ করি, অতঃপর তা মিথ্যের মস্তক চূর্ণ-বিচূর্ণ করে দেয়, তৎক্ষণাৎ মিথ্যে নিশ্চিহ্ন হয়ে যায়। তোমরা (আল্লাহ সম্পর্কে অযথা বহু মিথ্যে কথা বানিয়ে নিয়ে) যা বলছ এ কারণে তোমাদের জন্য দুর্ভোগ।', 'Rather, We dash the truth upon falsehood, and it destroys it, and thereupon it departs. And for you is destruction from that which you describe.', 'বরং আমি সত্যকে মিথ্যের উপর নিক্ষেপ করি, অতঃপর তা মিথ্যের মস্তক চূর্ণ-বিচূর্ণ করে দেয়, তৎক্ষণাৎ মিথ্যে নিশ্চিহ্ন হয়ে যায়। তোমরা (আল্লাহ সম্পর্কে অযথা বহু মিথ্যে কথা বানিয়ে নিয়ে) যা বলছ এ কারণে তোমাদের জন্য দুর্ভোগ।', 'Rather, We dash the truth upon falsehood, and it destroys it, and thereupon it departs. And for you is destruction from that which you describe.', NULL, NULL, NULL, NULL, NULL, 'https://everyayah.com/data/Alafasy_128kbps/021018.mp3', now()),
  (21, 19, '', '[{"id":21529,"position":1,"text_uthmani":"وَلَهُۥ","transliteration":"walahu","translation_bn":"এবং তাঁরই (রয়েছে)","root":"—","lemma":"وَلَهُۥ","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":21530,"position":2,"text_uthmani":"مَن","transliteration":"man","translation_bn":"যা কিছু","root":"—","lemma":"مَن\r","grammar_bn":"সাপেক্ষ সর্বনাম (Relative)"},{"id":21531,"position":3,"text_uthmani":"فِى","transliteration":"fī","translation_bn":"মধ্যে আছে","root":"—","lemma":"فِى\r","grammar_bn":"অব্যয় (Preposition)"},{"id":21532,"position":4,"text_uthmani":"ٱلسَّمَـٰوَٰتِ","transliteration":"l-samāwāti","translation_bn":"আকাশমন্ডলীর","root":"سمو","lemma":"سَمَا^ء","grammar_bn":"শব্দ"},{"id":21533,"position":5,"text_uthmani":"وَٱلْأَرْضِ ۚ","transliteration":"wal-arḍi","translation_bn":"এবং পৃথিবীর","root":"ارض","lemma":"أَرْض","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":21535,"position":6,"text_uthmani":"وَمَنْ","transliteration":"waman","translation_bn":"এবং যারা আছে","root":"—","lemma":"مَن\r","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":21536,"position":7,"text_uthmani":"عِندَهُۥ","transliteration":"ʿindahu","translation_bn":"তাঁর কাছে","root":"عند","lemma":"عِند","grammar_bn":"স্থানবাচক (Location)"},{"id":21537,"position":8,"text_uthmani":"لَا","transliteration":"lā","translation_bn":"না","root":"—","lemma":"لَا\r","grammar_bn":"না-বোধক (Negative)"},{"id":21538,"position":9,"text_uthmani":"يَسْتَكْبِرُونَ","transliteration":"yastakbirūna","translation_bn":"তারা অহংকার বশে বিরত থাকে","root":"كبر","lemma":"ٱسْتَكْبَرَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":21539,"position":10,"text_uthmani":"عَنْ","transliteration":"ʿan","translation_bn":"থেকে","root":"—","lemma":"عَن\r","grammar_bn":"অব্যয় (Preposition)"},{"id":21540,"position":11,"text_uthmani":"عِبَادَتِهِۦ","transliteration":"ʿibādatihi","translation_bn":"তাঁর ইবাদাত","root":"عبد","lemma":"عِبَادَت","grammar_bn":"বিশেষ্য (Noun)"},{"id":21541,"position":12,"text_uthmani":"وَلَا","transliteration":"walā","translation_bn":"আর না","root":"—","lemma":"لَا\r","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":21542,"position":13,"text_uthmani":"يَسْتَحْسِرُونَ","transliteration":"yastaḥsirūna","translation_bn":"তারা পরিশ্রান্ত হয়","root":"حسر","lemma":"يَسْتَحْسِرُ","grammar_bn":"ক্রিয়া (Verb)"},{"id":21543,"position":14,"text_uthmani":"١٩","transliteration":"","translation_bn":"(১৯)","root":"—","lemma":"١٩","grammar_bn":"মার্কার"}]'::jsonb, 'walahu man fī l-samāwāti wal-arḍi waman ʿindahu lā yastakbirūna ʿan ʿibādatihi walā yastaḥsirūna', 'আসমান ও যমীনে যারা আছে তারা তাঁরই মালিকানাধীন, আর যারা তাঁর সন্নিকটে আছে তারা গর্বভরে তাঁর ‘ইবাদাত থেকে বিমুখ হয় না, আর তারা (কক্ষনো তাঁর ‘ইবাদাত করার ব্যাপারে) ক্লান্তিবোধ করে না।', 'To Him belongs whoever is in the heavens and the earth. And those near Him are not prevented by arrogance from His worship, nor do they tire.', 'আসমান ও যমীনে যারা আছে তারা তাঁরই মালিকানাধীন, আর যারা তাঁর সন্নিকটে আছে তারা গর্বভরে তাঁর ‘ইবাদাত থেকে বিমুখ হয় না, আর তারা (কক্ষনো তাঁর ‘ইবাদাত করার ব্যাপারে) ক্লান্তিবোধ করে না।', 'To Him belongs whoever is in the heavens and the earth. And those near Him are not prevented by arrogance from His worship, nor do they tire.', NULL, NULL, NULL, NULL, NULL, 'https://everyayah.com/data/Alafasy_128kbps/021019.mp3', now()),
  (21, 20, '', '[{"id":22597,"position":1,"text_uthmani":"يُسَبِّحُونَ","transliteration":"yusabbiḥūna","translation_bn":"তারা পবিত্রতা ঘোষণা করে","root":"سبح","lemma":"سَبَّحَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":22598,"position":2,"text_uthmani":"ٱلَّيْلَ","transliteration":"al-layla","translation_bn":"রাতে","root":"ليل","lemma":"لَيْل","grammar_bn":"শব্দ"},{"id":22599,"position":3,"text_uthmani":"وَٱلنَّهَارَ","transliteration":"wal-nahāra","translation_bn":"ও দিনে","root":"نهر","lemma":"نَهَار","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":22600,"position":4,"text_uthmani":"لَا","transliteration":"lā","translation_bn":"না","root":"—","lemma":"لَا\r","grammar_bn":"না-বোধক (Negative)"},{"id":22601,"position":5,"text_uthmani":"يَفْتُرُونَ","transliteration":"yafturūna","translation_bn":"তারা থামে","root":"فتر","lemma":"يَفْتُرُ","grammar_bn":"ক্রিয়া (Verb)"},{"id":22602,"position":6,"text_uthmani":"٢٠","transliteration":"","translation_bn":"(২০)","root":"—","lemma":"٢٠","grammar_bn":"মার্কার"}]'::jsonb, 'yusabbiḥūna al-layla wal-nahāra lā yafturūna', 'তারা রাত-দিন তাঁর পবিত্রতা ঘোষণা করতে থাকে, তারা কক্ষনো শিথিলতা করে না বা আগ্রহ হারায় না।', 'They exalt [Him] night and day [and] do not slacken.', 'তারা রাত-দিন তাঁর পবিত্রতা ঘোষণা করতে থাকে, তারা কক্ষনো শিথিলতা করে না বা আগ্রহ হারায় না।', 'They exalt [Him] night and day [and] do not slacken.', NULL, NULL, NULL, NULL, NULL, 'https://everyayah.com/data/Alafasy_128kbps/021020.mp3', now()),
  (21, 21, '', '[{"id":23777,"position":1,"text_uthmani":"أَمِ","transliteration":"ami","translation_bn":"কি","root":"—","lemma":"أَم\r","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":23778,"position":2,"text_uthmani":"ٱتَّخَذُوٓا۟","transliteration":"ittakhadhū","translation_bn":"তারা বানিয়ে নিয়েছে","root":"اخذ","lemma":"ٱتَّخَذَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":23779,"position":3,"text_uthmani":"ءَالِهَةًۭ","transliteration":"ālihatan","translation_bn":"(অন্যান্যদেরকে) দেবতারূপে","root":"اله","lemma":"إِلَٰه","grammar_bn":"বিশেষ্য (Noun)"},{"id":23780,"position":4,"text_uthmani":"مِّنَ","transliteration":"mina","translation_bn":"মধ্য হ''তে","root":"—","lemma":"مِن\r","grammar_bn":"অব্যয় (Preposition)"},{"id":23781,"position":5,"text_uthmani":"ٱلْأَرْضِ","transliteration":"l-arḍi","translation_bn":"পৃথিবীর","root":"ارض","lemma":"أَرْض","grammar_bn":"শব্দ"},{"id":23782,"position":6,"text_uthmani":"هُمْ","transliteration":"hum","translation_bn":"তারা","root":"—","lemma":"هُمْ","grammar_bn":"সর্বনাম (Pronoun)"},{"id":23783,"position":7,"text_uthmani":"يُنشِرُونَ","transliteration":"yunshirūna","translation_bn":"মৃতকে উঠাতে পারে (কি)","root":"نشر","lemma":"أَنشَرَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":23784,"position":8,"text_uthmani":"٢١","transliteration":"","translation_bn":"(২১)","root":"—","lemma":"٢١","grammar_bn":"মার্কার"}]'::jsonb, 'ami ittakhadhū ālihatan mina l-arḍi hum yunshirūna', 'তারা (অর্থাৎ মুশরিকরা) মাটি থেকে (তৈরী) যে সব দেবতা গ্রহণ করেছে তারা কি (মৃতদেরকে) জীবিত করতে সক্ষম?', 'Or have men taken for themselves gods from the earth who resurrect [the dead]?', 'তারা (অর্থাৎ মুশরিকরা) মাটি থেকে (তৈরী) যে সব দেবতা গ্রহণ করেছে তারা কি (মৃতদেরকে) জীবিত করতে সক্ষম?', 'Or have men taken for themselves gods from the earth who resurrect [the dead]?', NULL, NULL, NULL, NULL, NULL, 'https://everyayah.com/data/Alafasy_128kbps/021021.mp3', now()),
  (21, 22, '', '[{"id":24759,"position":1,"text_uthmani":"لَوْ","transliteration":"law","translation_bn":"যদি","root":"—","lemma":"لَو\r","grammar_bn":"শর্তবাচক (Conditional)"},{"id":24760,"position":2,"text_uthmani":"كَانَ","transliteration":"kāna","translation_bn":"হতো","root":"كون","lemma":"كَانَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":24761,"position":3,"text_uthmani":"فِيهِمَآ","transliteration":"fīhimā","translation_bn":"তাদের উভয়ের মধ্যে","root":"—","lemma":"فِى\r","grammar_bn":"অব্যয় (Preposition)"},{"id":24762,"position":4,"text_uthmani":"ءَالِهَةٌ","transliteration":"ālihatun","translation_bn":"(আরো অনেক) ইলাহ","root":"اله","lemma":"إِلَٰه","grammar_bn":"বিশেষ্য (Noun)"},{"id":24763,"position":5,"text_uthmani":"إِلَّا","transliteration":"illā","translation_bn":"ছাড়া","root":"—","lemma":"إِلَّا\r","grammar_bn":"সীমাবদ্ধতা (Restriction)"},{"id":24764,"position":6,"text_uthmani":"ٱللَّهُ","transliteration":"l-lahu","translation_bn":"আল্লাহ","root":"اله","lemma":"ٱللَّه","grammar_bn":"নামবাচক বিশেষ্য (Proper Noun)"},{"id":24765,"position":7,"text_uthmani":"لَفَسَدَتَا ۚ","transliteration":"lafasadatā","translation_bn":"অবশ্যই উভয়ই ধ্বংস হতো","root":"فسد","lemma":"فَسَدَتِ","grammar_bn":"দৃঢ়তাবোধক (Emphatic)"},{"id":24767,"position":8,"text_uthmani":"فَسُبْحَـٰنَ","transliteration":"fasub''ḥāna","translation_bn":"অতএব পবিত্র","root":"سبح","lemma":"سُبْحَٰن","grammar_bn":"শব্দ"},{"id":24768,"position":9,"text_uthmani":"ٱللَّهِ","transliteration":"l-lahi","translation_bn":"আল্লাহ্‌","root":"اله","lemma":"ٱللَّه","grammar_bn":"নামবাচক বিশেষ্য (Proper Noun)"},{"id":24769,"position":10,"text_uthmani":"رَبِّ","transliteration":"rabbi","translation_bn":"রব","root":"ربب","lemma":"رَبّ","grammar_bn":"বিশেষ্য (Noun)"},{"id":24770,"position":11,"text_uthmani":"ٱلْعَرْشِ","transliteration":"l-ʿarshi","translation_bn":"আরশের","root":"عرش","lemma":"عَرْش","grammar_bn":"শব্দ"},{"id":24771,"position":12,"text_uthmani":"عَمَّا","transliteration":"ʿammā","translation_bn":"তা হ''তে যা","root":"—","lemma":"عَن\r","grammar_bn":"অব্যয় (Preposition)"},{"id":24772,"position":13,"text_uthmani":"يَصِفُونَ","transliteration":"yaṣifūna","translation_bn":"তারা বর্ণনা করে","root":"وصف","lemma":"يَصِفُ","grammar_bn":"ক্রিয়া (Verb)"},{"id":24773,"position":14,"text_uthmani":"٢٢","transliteration":"","translation_bn":"(২২)","root":"—","lemma":"٢٢","grammar_bn":"মার্কার"}]'::jsonb, 'law kāna fīhimā ālihatun illā l-lahu lafasadatā fasub''ḥāna l-lahi rabbi l-ʿarshi ʿammā yaṣifūna', 'আসমান ও যমীনে যদি আল্লাহ ছাড়া আরো অনেক ইলাহ থাকত তবে (আসমান ও যমীন) উভয়ই ধ্বংস হয়ে যেত। কাজেই আরশের অধিপতি আল্লাহ মহান ও পবিত্র সে সব থেকে যা তারা তাঁর প্রতি আরোপ করে।', 'Had there been within the heavens and earth gods besides Allah, they both would have been ruined. So exalted is Allah, Lord of the Throne, above what they describe.', 'আসমান ও যমীনে যদি আল্লাহ ছাড়া আরো অনেক ইলাহ থাকত তবে (আসমান ও যমীন) উভয়ই ধ্বংস হয়ে যেত। কাজেই আরশের অধিপতি আল্লাহ মহান ও পবিত্র সে সব থেকে যা তারা তাঁর প্রতি আরোপ করে।', 'Had there been within the heavens and earth gods besides Allah, they both would have been ruined. So exalted is Allah, Lord of the Throne, above what they describe.', NULL, NULL, NULL, NULL, NULL, 'https://everyayah.com/data/Alafasy_128kbps/021022.mp3', now()),
  (21, 23, '', '[{"id":25805,"position":1,"text_uthmani":"لَا","transliteration":"lā","translation_bn":"না","root":"—","lemma":"لَا\r","grammar_bn":"না-বোধক (Negative)"},{"id":25806,"position":2,"text_uthmani":"يُسْـَٔلُ","transliteration":"yus''alu","translation_bn":"তাঁকে জিজ্ঞেস করা হবে","root":"سال","lemma":"سَأَلَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":25807,"position":3,"text_uthmani":"عَمَّا","transliteration":"ʿammā","translation_bn":"ঐ বিষয়ে যা","root":"—","lemma":"عَن\r","grammar_bn":"অব্যয় (Preposition)"},{"id":25808,"position":4,"text_uthmani":"يَفْعَلُ","transliteration":"yafʿalu","translation_bn":"তিনি করেন","root":"فعل","lemma":"فَعَلَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":25809,"position":5,"text_uthmani":"وَهُمْ","transliteration":"wahum","translation_bn":"বরং তারা","root":"—","lemma":"وَهُمْ","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":25810,"position":6,"text_uthmani":"يُسْـَٔلُونَ","transliteration":"yus''alūna","translation_bn":"জিজ্ঞাসিত হবে","root":"سال","lemma":"سَأَلَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":25811,"position":7,"text_uthmani":"٢٣","transliteration":"","translation_bn":"(২৩)","root":"—","lemma":"٢٣","grammar_bn":"মার্কার"}]'::jsonb, 'lā yus''alu ʿammā yafʿalu wahum yus''alūna', 'তিনি যা করেন সে ব্যাপারে তিনি জিজ্ঞাসিত হবেন না, বরং তারা জিজ্ঞাসিত হবে (তাদের কাজের ব্যাপারে)।', 'He is not questioned about what He does, but they will be questioned.', 'তিনি যা করেন সে ব্যাপারে তিনি জিজ্ঞাসিত হবেন না, বরং তারা জিজ্ঞাসিত হবে (তাদের কাজের ব্যাপারে)।', 'He is not questioned about what He does, but they will be questioned.', NULL, NULL, NULL, NULL, NULL, 'https://everyayah.com/data/Alafasy_128kbps/021023.mp3', now()),
  (21, 24, '', '[{"id":26881,"position":1,"text_uthmani":"أَمِ","transliteration":"ami","translation_bn":"কি","root":"—","lemma":"أَم\r","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":26882,"position":2,"text_uthmani":"ٱتَّخَذُوا۟","transliteration":"ittakhadhū","translation_bn":"তারা গ্রহণ করেছে","root":"اخذ","lemma":"ٱتَّخَذَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":26883,"position":3,"text_uthmani":"مِن","transliteration":"min","translation_bn":"মধ্য হতে","root":"—","lemma":"مِن\r","grammar_bn":"অব্যয় (Preposition)"},{"id":26884,"position":4,"text_uthmani":"دُونِهِۦٓ","transliteration":"dūnihi","translation_bn":"তাঁকে ছাড়া","root":"دون","lemma":"دُون","grammar_bn":"বিশেষ্য (Noun)"},{"id":26885,"position":5,"text_uthmani":"ءَالِهَةًۭ ۖ","transliteration":"ālihatan","translation_bn":"(অন্যান্যদেরকে) ইলাহরূপে","root":"اله","lemma":"إِلَٰه","grammar_bn":"বিশেষ্য (Noun)"},{"id":26887,"position":6,"text_uthmani":"قُلْ","transliteration":"qul","translation_bn":"(হে নাবী) বলো","root":"قول","lemma":"قَالَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":26888,"position":7,"text_uthmani":"هَاتُوا۟","transliteration":"hātū","translation_bn":"\"পেশ করো","root":"هات","lemma":"هَاتُ","grammar_bn":"ক্রিয়া (Verb)"},{"id":26889,"position":8,"text_uthmani":"بُرْهَـٰنَكُمْ ۖ","transliteration":"bur''hānakum","translation_bn":"তোমাদের প্রমাণ","root":"برهن","lemma":"بُرْهَٰن","grammar_bn":"বিশেষ্য (Noun)"},{"id":26891,"position":9,"text_uthmani":"هَـٰذَا","transliteration":"hādhā","translation_bn":"এটা","root":"—","lemma":"هَٰذَا","grammar_bn":"নির্দেশক সর্বনাম (Demonstrative)"},{"id":26892,"position":10,"text_uthmani":"ذِكْرُ","transliteration":"dhik''ru","translation_bn":"উপদেশ (কিতাব)","root":"ذكر","lemma":"ذِكْر","grammar_bn":"বিশেষ্য (Noun)"},{"id":26893,"position":11,"text_uthmani":"مَن","transliteration":"man","translation_bn":"(তাদের জন্য) যারা","root":"—","lemma":"مَن\r","grammar_bn":"সাপেক্ষ সর্বনাম (Relative)"},{"id":26894,"position":12,"text_uthmani":"مَّعِىَ","transliteration":"m