  (22, 1, '', '[{"id":347,"position":1,"text_uthmani":"يَـٰٓأَيُّهَا","transliteration":"yāayyuhā","translation_bn":"হে","root":"—","lemma":"أَيُّهَا","grammar_bn":"সম্বোধন পদ (Vocative)"},{"id":348,"position":2,"text_uthmani":"ٱلنَّاسُ","transliteration":"l-nāsu","translation_bn":"মানবজাতি","root":"نوس","lemma":"نَّاس","grammar_bn":"শব্দ"},{"id":349,"position":3,"text_uthmani":"ٱتَّقُوا۟","transliteration":"ittaqū","translation_bn":"তোমরা ভয় করো","root":"وقي","lemma":"ٱتَّقَىٰ","grammar_bn":"ক্রিয়া (Verb)"},{"id":350,"position":4,"text_uthmani":"رَبَّكُمْ ۚ","transliteration":"rabbakum","translation_bn":"তোমাদের রবকে","root":"ربب","lemma":"رَبّ","grammar_bn":"বিশেষ্য (Noun)"},{"id":352,"position":5,"text_uthmani":"إِنَّ","transliteration":"inna","translation_bn":"নিশ্চয়ই","root":"—","lemma":"إِنّ","grammar_bn":"অভিঘাত পদ (Accusative)"},{"id":353,"position":6,"text_uthmani":"زَلْزَلَةَ","transliteration":"zalzalata","translation_bn":"প্রকম্পন","root":"زلزل","lemma":"زَلْزَلَة","grammar_bn":"বিশেষ্য (Noun)"},{"id":354,"position":7,"text_uthmani":"ٱلسَّاعَةِ","transliteration":"l-sāʿati","translation_bn":"ক্বিয়ামাতের","root":"سوع","lemma":"سَاعَة","grammar_bn":"শব্দ"},{"id":355,"position":8,"text_uthmani":"شَىْءٌ","transliteration":"shayon","translation_bn":"ব্যাপার","root":"شيا","lemma":"شَىْء","grammar_bn":"বিশেষ্য (Noun)"},{"id":356,"position":9,"text_uthmani":"عَظِيمٌۭ","transliteration":"ʿaẓīmun","translation_bn":"ভয়ংকর","root":"عظم","lemma":"عَظِيم","grammar_bn":"বিশেষণ (Adjective)"},{"id":357,"position":10,"text_uthmani":"١","transliteration":"","translation_bn":"(১)","root":"—","lemma":"١","grammar_bn":"মার্কার"}]'::jsonb, 'yāayyuhā l-nāsu ittaqū rabbakum inna zalzalata l-sāʿati shayon ʿaẓīmun', 'হে মানুষ! তোমরা তোমাদের প্রতিপালককে ভয় কর, কিয়ামাতের কম্পন এক ভয়ানক জিনিস।', 'O mankind, fear your Lord. Indeed, the convulsion of the [final] Hour is a terrible thing.', 'হে মানুষ! তোমরা তোমাদের প্রতিপালককে ভয় কর, কিয়ামাতের কম্পন এক ভয়ানক জিনিস।', 'O mankind, fear your Lord. Indeed, the convulsion of the [final] Hour is a terrible thing.', NULL, NULL, NULL, NULL, NULL, 'https://everyayah.com/data/Alafasy_128kbps/022001.mp3', now()),
  (22, 2, '', '[{"id":1425,"position":1,"text_uthmani":"يَوْمَ","transliteration":"yawma","translation_bn":"যেদিন","root":"يوم","lemma":"يَوْم","grammar_bn":"বিশেষ্য (Noun)"},{"id":1426,"position":2,"text_uthmani":"تَرَوْنَهَا","transliteration":"tarawnahā","translation_bn":"তা তোমরা দেখবে (সেদিন)","root":"راي","lemma":"رَءَا","grammar_bn":"ক্রিয়া (Verb)"},{"id":1427,"position":3,"text_uthmani":"تَذْهَلُ","transliteration":"tadhhalu","translation_bn":"বিস্মৃত হবে","root":"ذهل","lemma":"تَذْهَلُ","grammar_bn":"ক্রিয়া (Verb)"},{"id":1428,"position":4,"text_uthmani":"كُلُّ","transliteration":"kullu","translation_bn":"প্রত্যেক","root":"كلل","lemma":"كُلّ","grammar_bn":"বিশেষ্য (Noun)"},{"id":1429,"position":5,"text_uthmani":"مُرْضِعَةٍ","transliteration":"mur''ḍiʿatin","translation_bn":"স্তন্যদাত্রী (মা)","root":"رضع","lemma":"مُرْضِعَة","grammar_bn":"বিশেষ্য (Noun)"},{"id":1430,"position":6,"text_uthmani":"عَمَّآ","transliteration":"ʿammā","translation_bn":"তাহ''তে যাকে","root":"—","lemma":"عَن\r","grammar_bn":"অব্যয় (Preposition)"},{"id":1431,"position":7,"text_uthmani":"أَرْضَعَتْ","transliteration":"arḍaʿat","translation_bn":"সে দুধপান করিয়েছে (অর্থাৎ দুগ্ধপোষ্যকে)","root":"رضع","lemma":"أَرْضَعَتْ","grammar_bn":"ক্রিয়া (Verb)"},{"id":1432,"position":8,"text_uthmani":"وَتَضَعُ","transliteration":"wataḍaʿu","translation_bn":"ও গর্ভপাত করবে","root":"وضع","lemma":"وَضَعَ","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":1433,"position":9,"text_uthmani":"كُلُّ","transliteration":"kullu","translation_bn":"প্রত্যেক","root":"كلل","lemma":"كُلّ","grammar_bn":"বিশেষ্য (Noun)"},{"id":1434,"position":10,"text_uthmani":"ذَاتِ","transliteration":"dhāti","translation_bn":"সম্পন্ন","root":"—","lemma":"ذُو","grammar_bn":"বিশেষ্য (Noun)"},{"id":1435,"position":11,"text_uthmani":"حَمْلٍ","transliteration":"ḥamlin","translation_bn":"গর্ভ (গর্ভবতী)","root":"حمل","lemma":"حَمْل","grammar_bn":"বিশেষ্য (Noun)"},{"id":1436,"position":12,"text_uthmani":"حَمْلَهَا","transliteration":"ḥamlahā","translation_bn":"তার গর্ভকে","root":"حمل","lemma":"حَمْل","grammar_bn":"বিশেষ্য (Noun)"},{"id":1437,"position":13,"text_uthmani":"وَتَرَى","transliteration":"watarā","translation_bn":"এবং দেখবে","root":"راي","lemma":"رَءَا","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":1438,"position":14,"text_uthmani":"ٱلنَّاسَ","transliteration":"l-nāsa","translation_bn":"লোকদেরকে","root":"نوس","lemma":"نَّاس","grammar_bn":"শব্দ"},{"id":1439,"position":15,"text_uthmani":"سُكَـٰرَىٰ","transliteration":"sukārā","translation_bn":"মাতালের মতো","root":"سكر","lemma":"سُكَٰرَىٰ","grammar_bn":"বিশেষ্য (Noun)"},{"id":1440,"position":16,"text_uthmani":"وَمَا","transliteration":"wamā","translation_bn":"অথচ না","root":"—","lemma":"مَا\r","grammar_bn":"অবস্থাবাচক (Circumstantial)"},{"id":1441,"position":17,"text_uthmani":"هُم","transliteration":"hum","translation_bn":"তারা (হবে)","root":"—","lemma":"هُم","grammar_bn":"সর্বনাম (Pronoun)"},{"id":1442,"position":18,"text_uthmani":"بِسُكَـٰرَىٰ","transliteration":"bisukārā","translation_bn":"মাতাল","root":"سكر","lemma":"سُكَٰرَىٰ","grammar_bn":"অব্যয় (Preposition)"},{"id":1443,"position":19,"text_uthmani":"وَلَـٰكِنَّ","transliteration":"walākinna","translation_bn":"কিন্তু","root":"—","lemma":"لَٰكِنّ","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":1444,"position":20,"text_uthmani":"عَذَابَ","transliteration":"ʿadhāba","translation_bn":"শাস্তি","root":"عذب","lemma":"عَذَاب","grammar_bn":"বিশেষ্য (Noun)"},{"id":1445,"position":21,"text_uthmani":"ٱللَّهِ","transliteration":"l-lahi","translation_bn":"আল্লাহ্‌র","root":"اله","lemma":"ٱللَّه","grammar_bn":"নামবাচক বিশেষ্য (Proper Noun)"},{"id":1446,"position":22,"text_uthmani":"شَدِيدٌۭ","transliteration":"shadīdun","translation_bn":"কঠিন (শাস্তি)","root":"شدد","lemma":"شَدِيد","grammar_bn":"বিশেষণ (Adjective)"},{"id":1447,"position":23,"text_uthmani":"٢","transliteration":"","translation_bn":"(২)","root":"—","lemma":"٢","grammar_bn":"মার্কার"}]'::jsonb, 'yawma tarawnahā tadhhalu kullu mur''ḍiʿatin ʿammā arḍaʿat wataḍaʿu kullu dhāti ḥamlin ḥamlahā watarā l-nāsa sukārā wamā hum bisukārā walākinna ʿadhāba l-lahi shadīdun', 'সেদিন তুমি দেখবে প্রতিটি দুগ্ধদায়িনী ভুলে যাবে তার দুগ্ধপোষ্য শিশুকে, আর প্রত্যেক গর্ভবতী গর্ভপাত করে ফেলবে, আর মানুষকে দেখবে মাতাল, যদিও তারা প্রকৃতপক্ষে মাতাল নয়, কিন্তু আল্লাহর শাস্তি বড়ই কঠিন (যার কারণে তাদের ঐ অবস্থা ঘটবে)।', 'On the Day you see it every nursing mother will be distracted from that [child] she was nursing, and every pregnant woman will abort her pregnancy, and you will see the people [appearing] intoxicated while they are not intoxicated; but the punishment of Allah is severe.', 'সেদিন তুমি দেখবে প্রতিটি দুগ্ধদায়িনী ভুলে যাবে তার দুগ্ধপোষ্য শিশুকে, আর প্রত্যেক গর্ভবতী গর্ভপাত করে ফেলবে, আর মানুষকে দেখবে মাতাল, যদিও তারা প্রকৃতপক্ষে মাতাল নয়, কিন্তু আল্লাহর শাস্তি বড়ই কঠিন (যার কারণে তাদের ঐ অবস্থা ঘটবে)।', 'On the Day you see it every nursing mother will be distracted from that [child] she was nursing, and every pregnant woman will abort her pregnancy, and you will see the people [appearing] intoxicated while they are not intoxicated; but the punishment of Allah is severe.', NULL, NULL, NULL, NULL, NULL, 'https://everyayah.com/data/Alafasy_128kbps/022002.mp3', now()),
  (22, 3, '', '[{"id":2480,"position":1,"text_uthmani":"وَمِنَ","transliteration":"wamina","translation_bn":"আর কেউ কেউ (মধ্য হ''তে)","root":"—","lemma":"مِن\r","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":2481,"position":2,"text_uthmani":"ٱلنَّاسِ","transliteration":"l-nāsi","translation_bn":"মানুষের","root":"نوس","lemma":"نَّاس","grammar_bn":"শব্দ"},{"id":2482,"position":3,"text_uthmani":"مَن","transliteration":"man","translation_bn":"যারা","root":"—","lemma":"مَن\r","grammar_bn":"সাপেক্ষ সর্বনাম (Relative)"},{"id":2483,"position":4,"text_uthmani":"يُجَـٰدِلُ","transliteration":"yujādilu","translation_bn":"(যারা) বিতর্ক করে","root":"جدل","lemma":"جَٰدَلُ","grammar_bn":"ক্রিয়া (Verb)"},{"id":2484,"position":5,"text_uthmani":"فِى","transliteration":"fī","translation_bn":"সম্বন্ধে","root":"—","lemma":"فِى\r","grammar_bn":"অব্যয় (Preposition)"},{"id":2485,"position":6,"text_uthmani":"ٱللَّهِ","transliteration":"l-lahi","translation_bn":"আল্লাহর","root":"اله","lemma":"ٱللَّه","grammar_bn":"নামবাচক বিশেষ্য (Proper Noun)"},{"id":2486,"position":7,"text_uthmani":"بِغَيْرِ","transliteration":"bighayri","translation_bn":"ব্যতীত","root":"غير","lemma":"غَيْر","grammar_bn":"অব্যয় (Preposition)"},{"id":2487,"position":8,"text_uthmani":"عِلْمٍۢ","transliteration":"ʿil''min","translation_bn":"কোন জ্ঞান","root":"علم","lemma":"عِلْم","grammar_bn":"বিশেষ্য (Noun)"},{"id":2488,"position":9,"text_uthmani":"وَيَتَّبِعُ","transliteration":"wayattabiʿu","translation_bn":"এবং অনুসরণ করে","root":"تبع","lemma":"ٱتَّبَعَ","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":2489,"position":10,"text_uthmani":"كُلَّ","transliteration":"kulla","translation_bn":"প্রত্যেক","root":"كلل","lemma":"كُلّ","grammar_bn":"বিশেষ্য (Noun)"},{"id":2490,"position":11,"text_uthmani":"شَيْطَـٰنٍۢ","transliteration":"shayṭānin","translation_bn":"শয়তানকে","root":"شطن","lemma":"شَيْطَٰن","grammar_bn":"বিশেষ্য (Noun)"},{"id":2491,"position":12,"text_uthmani":"مَّرِيدٍۢ","transliteration":"marīdin","translation_bn":"উদ্ধত","root":"مرد","lemma":"مَّرِيد","grammar_bn":"বিশেষণ (Adjective)"},{"id":2492,"position":13,"text_uthmani":"٣","transliteration":"","translation_bn":"(৩)","root":"—","lemma":"٣","grammar_bn":"মার্কার"}]'::jsonb, 'wamina l-nāsi man yujādilu fī l-lahi bighayri ʿil''min wayattabiʿu kulla shayṭānin marīdin', 'কতক মানুষ জ্ঞান ছাড়াই আল্লাহ সম্বন্ধে বাদানুবাদ করে, আর প্রত্যেক অবাধ্য শয়ত্বানের অনুসরণ করে।', 'And of the people is he who disputes about Allah without knowledge and follows every rebellious devil.', 'কতক মানুষ জ্ঞান ছাড়াই আল্লাহ সম্বন্ধে বাদানুবাদ করে, আর প্রত্যেক অবাধ্য শয়ত্বানের অনুসরণ করে।', 'And of the people is he who disputes about Allah without knowledge and follows every rebellious devil.', NULL, NULL, NULL, NULL, NULL, 'https://everyayah.com/data/Alafasy_128kbps/022003.mp3', now()),
  (22, 4, '', '[{"id":3953,"position":1,"text_uthmani":"كُتِبَ","transliteration":"kutiba","translation_bn":"লিখে দেয়া হয়েছে","root":"كتب","lemma":"كَتَبَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":3954,"position":2,"text_uthmani":"عَلَيْهِ","transliteration":"ʿalayhi","translation_bn":"তার সম্পর্কে","root":"—","lemma":"عَلَىٰ\r","grammar_bn":"অব্যয় (Preposition)"},{"id":3955,"position":3,"text_uthmani":"أَنَّهُۥ","transliteration":"annahu","translation_bn":"যে তা (এমন)","root":"—","lemma":"أَنّ","grammar_bn":"অভিঘাত পদ (Accusative)"},{"id":3956,"position":4,"text_uthmani":"مَن","transliteration":"man","translation_bn":"যে কেউ","root":"—","lemma":"مَن\r","grammar_bn":"সাপেক্ষ সর্বনাম (Relative)"},{"id":3957,"position":5,"text_uthmani":"تَوَلَّاهُ","transliteration":"tawallāhu","translation_bn":"তাকে বন্ধু বানাবে","root":"ولي","lemma":"تَوَلَّىٰ","grammar_bn":"ক্রিয়া (Verb)"},{"id":3958,"position":6,"text_uthmani":"فَأَنَّهُۥ","transliteration":"fa-annahu","translation_bn":"তখন সে নিশ্চয়ই","root":"—","lemma":"أَنّ","grammar_bn":"শব্দ"},{"id":3959,"position":7,"text_uthmani":"يُضِلُّهُۥ","transliteration":"yuḍilluhu","translation_bn":"তাকে বিভ্রান্ত করবে","root":"ضلل","lemma":"أَضَلَّ","grammar_bn":"ক্রিয়া (Verb)"},{"id":3960,"position":8,"text_uthmani":"وَيَهْدِيهِ","transliteration":"wayahdīhi","translation_bn":"ও তাকে পরিচালিত করবে","root":"هدي","lemma":"هَدَى","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":3961,"position":9,"text_uthmani":"إِلَىٰ","transliteration":"ilā","translation_bn":"দিকে","root":"—","lemma":"إِلَىٰ\r","grammar_bn":"অব্যয় (Preposition)"},{"id":3962,"position":10,"text_uthmani":"عَذَابِ","transliteration":"ʿadhābi","translation_bn":"শাস্তির","root":"عذب","lemma":"عَذَاب","grammar_bn":"বিশেষ্য (Noun)"},{"id":3963,"position":11,"text_uthmani":"ٱلسَّعِيرِ","transliteration":"l-saʿīri","translation_bn":"জ্বলন্ত অাগুনের","root":"سعر","lemma":"سَعِير","grammar_bn":"শব্দ"},{"id":3964,"position":12,"text_uthmani":"٤","transliteration":"","translation_bn":"(৪)","root":"—","lemma":"٤","grammar_bn":"মার্কার"}]'::jsonb, 'kutiba ʿalayhi annahu man tawallāhu fa-annahu yuḍilluhu wayahdīhi ilā ʿadhābi l-saʿīri', 'যার (অর্থাৎ শয়ত্বানের) সম্পর্কে বিধান করা হয়েছে যে, যে কেউ তার সঙ্গে বন্ধুত্ব গড়বে, সে তাকে বিপথগামী করবে, আর তাকে প্রজ্জ্বলিত অগ্নি শাস্তির দিকে পরিচালিত করবে।', 'It has been decreed for every devil that whoever turns to him - he will misguide him and will lead him to the punishment of the Blaze.', 'যার (অর্থাৎ শয়ত্বানের) সম্পর্কে বিধান করা হয়েছে যে, যে কেউ তার সঙ্গে বন্ধুত্ব গড়বে, সে তাকে বিপথগামী করবে, আর তাকে প্রজ্জ্বলিত অগ্নি শাস্তির দিকে পরিচালিত করবে।', 'It has been decreed for every devil that whoever turns to him - he will misguide him and will lead him to the punishment of the Blaze.', NULL, NULL, NULL, NULL, NULL, 'https://everyayah.com/data/Alafasy_128kbps/022004.mp3', now()),
