  (23, 14, '', '[{"id":16306,"position":1,"text_uthmani":"ثُمَّ","transliteration":"thumma","translation_bn":"এরপর (এই প্রক্রিয়ায়)","root":"—","lemma":"ثُمّ\r","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":16307,"position":2,"text_uthmani":"خَلَقْنَا","transliteration":"khalaqnā","translation_bn":"আমরা সৃষ্টি করি","root":"خلق","lemma":"خَلَقَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":16308,"position":3,"text_uthmani":"ٱلنُّطْفَةَ","transliteration":"l-nuṭ''fata","translation_bn":"শুক্রবিন্দুকে","root":"نطف","lemma":"نُّطْفَة","grammar_bn":"শব্দ"},{"id":16309,"position":4,"text_uthmani":"عَلَقَةًۭ","transliteration":"ʿalaqatan","translation_bn":"জমাট রক্তরূপে","root":"علق","lemma":"عَلَقَة","grammar_bn":"বিশেষ্য (Noun)"},{"id":16310,"position":5,"text_uthmani":"فَخَلَقْنَا","transliteration":"fakhalaqnā","translation_bn":"অতঃপর আমরা সৃষ্টি করি","root":"خلق","lemma":"خَلَقَ","grammar_bn":"শব্দ"},{"id":16311,"position":6,"text_uthmani":"ٱلْعَلَقَةَ","transliteration":"l-ʿalaqata","translation_bn":"জমাট রক্তকে","root":"علق","lemma":"عَلَقَة","grammar_bn":"শব্দ"},{"id":16312,"position":7,"text_uthmani":"مُضْغَةًۭ","transliteration":"muḍ''ghatan","translation_bn":"মাংসপিন্ডে","root":"مضغ","lemma":"مُضْغَة","grammar_bn":"বিশেষ্য (Noun)"},{"id":16313,"position":8,"text_uthmani":"فَخَلَقْنَا","transliteration":"fakhalaqnā","translation_bn":"অতঃপর আমরা সৃষ্টি করি","root":"خلق","lemma":"خَلَقَ","grammar_bn":"শব্দ"},{"id":16314,"position":9,"text_uthmani":"ٱلْمُضْغَةَ","transliteration":"l-muḍ''ghata","translation_bn":"মাংসপিন্ডকে","root":"مضغ","lemma":"مُضْغَة","grammar_bn":"শব্দ"},{"id":16315,"position":10,"text_uthmani":"عِظَـٰمًۭا","transliteration":"ʿiẓāman","translation_bn":"হাড়ে","root":"عظم","lemma":"عَظِيم","grammar_bn":"বিশেষ্য (Noun)"},{"id":16316,"position":11,"text_uthmani":"فَكَسَوْنَا","transliteration":"fakasawnā","translation_bn":"অতঃপর আমরা ঢেকে দিই","root":"كسو","lemma":"كَسَوْ","grammar_bn":"শব্দ"},{"id":16317,"position":12,"text_uthmani":"ٱلْعِظَـٰمَ","transliteration":"l-ʿiẓāma","translation_bn":"হাড়কে","root":"عظم","lemma":"عَظِيم","grammar_bn":"শব্দ"},{"id":16318,"position":13,"text_uthmani":"لَحْمًۭا","transliteration":"laḥman","translation_bn":"গোশত (দ্বারা)","root":"لحم","lemma":"لَحْم","grammar_bn":"বিশেষ্য (Noun)"},{"id":16319,"position":14,"text_uthmani":"ثُمَّ","transliteration":"thumma","translation_bn":"এরপর","root":"—","lemma":"ثُمّ\r","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":16320,"position":15,"text_uthmani":"أَنشَأْنَـٰهُ","transliteration":"anshanāhu","translation_bn":"তাকে আমরা গড়ে তুলি","root":"نشا","lemma":"أَنشَأَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":16321,"position":16,"text_uthmani":"خَلْقًا","transliteration":"khalqan","translation_bn":"সৃষ্টিরূপে","root":"خلق","lemma":"خَلْق","grammar_bn":"বিশেষ্য (Noun)"},{"id":16322,"position":17,"text_uthmani":"ءَاخَرَ ۚ","transliteration":"ākhara","translation_bn":"অন্য এক","root":"اخر","lemma":"ا^خَر","grammar_bn":"বিশেষণ (Adjective)"},{"id":16324,"position":18,"text_uthmani":"فَتَبَارَكَ","transliteration":"fatabāraka","translation_bn":"অতএব কত মহান","root":"برك","lemma":"تَبَارَكَ","grammar_bn":"শব্দ"},{"id":16325,"position":19,"text_uthmani":"ٱللَّهُ","transliteration":"l-lahu","translation_bn":"আল্লাহ্‌","root":"اله","lemma":"ٱللَّه","grammar_bn":"নামবাচক বিশেষ্য (Proper Noun)"},{"id":16326,"position":20,"text_uthmani":"أَحْسَنُ","transliteration":"aḥsanu","translation_bn":"(যিনি) সর্বোত্তম","root":"حسن","lemma":"أَحْسَن","grammar_bn":"বিশেষণ (Adjective)"},{"id":16327,"position":21,"text_uthmani":"ٱلْخَـٰلِقِينَ","transliteration":"l-khāliqīna","translation_bn":"(সব) স্রষ্টাদের","root":"خلق","lemma":"خَٰلِق","grammar_bn":"শব্দ"},{"id":16328,"position":22,"text_uthmani":"١٤","transliteration":"","translation_bn":"(১৪)","root":"—","lemma":"١٤","grammar_bn":"মার্কার"}]'::jsonb, 'thumma khalaqnā l-nuṭ''fata ʿalaqatan fakhalaqnā l-ʿalaqata muḍ''ghatan fakhalaqnā l-muḍ''ghata ʿiẓāman fakasawnā l-ʿiẓāma laḥman thumma anshanāhu khalqan ākhara fatabāraka l-lahu aḥsanu l-khāliqīna', 'পরে আমি শুক্রবিন্দুকে পরিণত করি জমাট বাঁধা রক্তে, অতঃপর মাংসপিন্ডকে পরিণত করি হাড্ডিতে, অতঃপর হাড্ডিকে আবৃত করি মাংস দিয়ে, অতঃপর তাকে এক নতুন সৃষ্টিতে উন্নীত করি। কাজেই সর্বোত্তম স্রষ্টা আল্লাহ কতই না মহান!', 'Then We made the sperm-drop into a clinging clot, and We made the clot into a lump [of flesh], and We made [from] the lump, bones, and We covered the bones with flesh; then We developed him into another creation. So blessed is Allah, the best of creators.', 'পরে আমি শুক্রবিন্দুকে পরিণত করি জমাট বাঁধা রক্তে, অতঃপর মাংসপিন্ডকে পরিণত করি হাড্ডিতে, অতঃপর হাড্ডিকে আবৃত করি মাংস দিয়ে, অতঃপর তাকে এক নতুন সৃষ্টিতে উন্নীত করি। কাজেই সর্বোত্তম স্রষ্টা আল্লাহ কতই না মহান!', 'Then We made the sperm-drop into a clinging clot, and We made the clot into a lump [of flesh], and We made [from] the lump, bones, and We covered the bones with flesh; then We developed him into another creation. So blessed is Allah, the best of creators.', NULL, NULL, NULL, NULL, NULL, 'https://everyayah.com/data/Alafasy_128kbps/023014.mp3', now()),
  (23, 15, '', '[{"id":17484,"position":1,"text_uthmani":"ثُمَّ","transliteration":"thumma","translation_bn":"এরপর","root":"—","lemma":"ثُمّ\r","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":17485,"position":2,"text_uthmani":"إِنَّكُم","transliteration":"innakum","translation_bn":"নিশ্চয়ই তোমরা","root":"—","lemma":"إِنّ","grammar_bn":"অভিঘাত পদ (Accusative)"},{"id":17486,"position":3,"text_uthmani":"بَعْدَ","transliteration":"baʿda","translation_bn":"পরে","root":"بعد","lemma":"بَعْد","grammar_bn":"কালবাচক (Time)"},{"id":17487,"position":4,"text_uthmani":"ذَٰلِكَ","transliteration":"dhālika","translation_bn":"এর","root":"—","lemma":"ذَٰلِك","grammar_bn":"নির্দেশক সর্বনাম (Demonstrative)"},{"id":17488,"position":5,"text_uthmani":"لَمَيِّتُونَ","transliteration":"lamayyitūna","translation_bn":"অবশ্যই মৃত্যুবরণ করবে","root":"موت","lemma":"مَّيِّت","grammar_bn":"দৃঢ়তাবোধক (Emphatic)"},{"id":17489,"position":6,"text_uthmani":"١٥","transliteration":"","translation_bn":"(১৫)","root":"—","lemma":"١٥","grammar_bn":"মার্কার"}]'::jsonb, 'thumma innakum baʿda dhālika lamayyitūna', 'এরপর তোমরা অবশ্যই মরবে।', 'Then indeed, after that you are to die.', 'এরপর তোমরা অবশ্যই মরবে।', 'Then indeed, after that you are to die.', NULL, NULL, NULL, NULL, NULL, 'https://everyayah.com/data/Alafasy_128kbps/023015.mp3', now()),
  (23, 16, '', '[{"id":18527,"position":1,"text_uthmani":"ثُمَّ","transliteration":"thumma","translation_bn":"এরপর","root":"—","lemma":"ثُمّ\r","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":18528,"position":2,"text_uthmani":"إِنَّكُمْ","transliteration":"innakum","translation_bn":"নিশ্চয়ই তোমাদের","root":"—","lemma":"إِنّ","grammar_bn":"অভিঘাত পদ (Accusative)"},{"id":18529,"position":3,"text_uthmani":"يَوْمَ","transliteration":"yawma","translation_bn":"দিনে","root":"يوم","lemma":"يَوْم","grammar_bn":"বিশেষ্য (Noun)"},{"id":18530,"position":4,"text_uthmani":"ٱلْقِيَـٰمَةِ","transliteration":"l-qiyāmati","translation_bn":"ক্বিয়ামাতের","root":"قوم","lemma":"قِيَٰمَة","grammar_bn":"শব্দ"},{"id":18531,"position":5,"text_uthmani":"تُبْعَثُونَ","transliteration":"tub''ʿathūna","translation_bn":"ওঠানো হবে","root":"بعث","lemma":"بَعَثَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":18532,"position":6,"text_uthmani":"١٦","transliteration":"","translation_bn":"(১৬)","root":"—","lemma":"١٦","grammar_bn":"মার্কার"}]'::jsonb, 'thumma innakum yawma l-qiyāmati tub''ʿathūna', 'তারপর কিয়ামাতের দিন তোমাদেরকে পুনরুত্থিত করা হবে।', 'Then indeed you, on the Day of Resurrection, will be resurrected.', 'তারপর কিয়ামাতের দিন তোমাদেরকে পুনরুত্থিত করা হবে।', 'Then indeed you, on the Day of Resurrection, will be resurrected.', NULL, NULL, NULL, NULL, NULL, 'https://everyayah.com/data/Alafasy_128kbps/023016.mp3', now()),
  (23, 17, '', '[{"id":19516,"position":1,"text_uthmani":"وَلَقَدْ","transliteration":"walaqad","translation_bn":"আর নিশ্চয়ই","root":"—","lemma":"قَد\r","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":19517,"position":2,"text_uthmani":"خَلَقْنَا","transliteration":"khalaqnā","translation_bn":"আমরা সৃষ্টি করেছি","root":"خلق","lemma":"خَلَقَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":19518,"position":3,"text_uthmani":"فَوْقَكُمْ","transliteration":"fawqakum","translation_bn":"তোমাদের ওপরে","root":"فوق","lemma":"فَوْق","grammar_bn":"বিশেষ্য (Noun)"},{"id":19519,"position":4,"text_uthmani":"سَبْعَ","transliteration":"sabʿa","translation_bn":"সাতটি","root":"سبع","lemma":"سَبْع","grammar_bn":"বিশেষ্য (Noun)"},{"id":19520,"position":5,"text_uthmani":"طَرَآئِقَ","transliteration":"ṭarāiqa","translation_bn":"পথ","root":"طرق","lemma":"طَرِيقَة","grammar_bn":"বিশেষ্য (Noun)"},{"id":19521,"position":6,"text_uthmani":"وَمَا","transliteration":"wamā","translation_bn":"এবং না","root":"—","lemma":"مَا\r","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":19522,"position":7,"text_uthmani":"كُنَّا","transliteration":"kunnā","translation_bn":"আমরা ছিলাম","root":"كون","lemma":"كَانَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":19523,"position":8,"text_uthmani":"عَنِ","transliteration":"ʿani","translation_bn":"সম্পর্কে","root":"—","lemma":"عَن\r","grammar_bn":"অব্যয় (Preposition)"},{"id":19524,"position":9,"text_uthmani":"ٱلْخَلْقِ","transliteration":"l-khalqi","translation_bn":"সৃষ্টি","root":"خلق","lemma":"خَلْق","grammar_bn":"শব্দ"},{"id":19525,"position":10,"text_uthmani":"غَـٰفِلِينَ","transliteration":"ghāfilīna","translation_bn":"অমনোযোগী","root":"غفل","lemma":"غَٰفِل","grammar_bn":"বিশেষ্য (Noun)"},{"id":19526,"position":11,"text_uthmani":"١٧","transliteration":"","translation_bn":"(১৭)","root":"—","lemma":"١٧","grammar_bn":"মার্কার"}]'::jsonb, 'walaqad khalaqnā fawqakum sabʿa ṭarāiqa wamā kunnā ʿani l-khalqi ghāfilīna', 'আমি তোমাদের উপরে সপ্ত স্তর সৃষ্টি করেছি, আমি (আমার) সৃষ্টির ব্যাপারে অমনোযোগী নই।', 'And We have created above you seven layered heavens, and never have We been of [Our] creation unaware.', 'আমি তোমাদের উপরে সপ্ত স্তর সৃষ্টি করেছি, আমি (আমার) সৃষ্টির ব্যাপারে অমনোযোগী নই।', 'And We have created above you seven layered heavens, and never have We been of [Our] creation unaware.', NULL, NULL, NULL, NULL, NULL, 'https://everyayah.com/data/Alafasy_128kbps/023017.mp3', now()),
  (23, 18, '', '[{"id":20609,"position":1,"text_uthmani":"وَأَنزَلْنَا","transliteration":"wa-anzalnā","translation_bn":"আর আমরা বর্ষণ করি","root":"نزل","lemma":"أَنزَلَ","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":20610,"position":2,"text_uthmani":"مِنَ","transliteration":"mina","translation_bn":"হ''তে","root":"—","lemma":"مِن\r","grammar_bn":"অব্যয় (Preposition)"},{"id":20611,"position":3,"text_uthmani":"ٱلسَّمَآءِ","transliteration":"l-samāi","translation_bn":"আকাশ","root":"سمو","lemma":"سَمَا^ء","grammar_bn":"শব্দ"},{"id":20612,"position":4,"text_uthmani":"مَآءًۢ","transliteration":"māan","translation_bn":"পানি","root":"موه","lemma":"مَا^ء","grammar_bn":"বিশেষ্য (Noun)"},{"id":20613,"position":5,"text_uthmani":"بِقَدَرٍۢ","transliteration":"biqadarin","translation_bn":"পরিমাণ মতো","root":"قدر","lemma":"قَدَر","grammar_bn":"অব্যয় (Preposition)"},{"id":20614,"position":6,"text_uthmani":"فَأَسْكَنَّـٰهُ","transliteration":"fa-askannāhu","translation_bn":"অতঃপর তা আমরা সংরক্ষণ করি","root":"سكن","lemma":"أَسْكَن","grammar_bn":"শব্দ"},{"id":20615,"position":7,"text_uthmani":"فِى","transliteration":"fī","translation_bn":"মধ্যে","root":"—","lemma":"فِى\r","grammar_bn":"অব্যয় (Preposition)"},{"id":20616,"position":8,"text_uthmani":"ٱلْأَرْضِ ۖ","transliteration":"l-arḍi","translation_bn":"মাটির","root":"ارض","lemma":"أَرْض","grammar_bn":"শব্দ"},{"id":20618,"position":9,"text_uthmani":"وَإِنَّا","transliteration":"wa-innā","translation_bn":"আর নিশ্চয়ই আমরা","root":"—","lemma":"إِنّ","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":20619,"position":10,"text_uthmani":"عَلَىٰ","transliteration":"ʿalā","translation_bn":"ব্যাপারে","root":"—","lemma":"عَلَىٰ\r","grammar_bn":"অব্যয় (Preposition)"},{"id":20620,"position":11,"text_uthmani":"ذَهَابٍۭ","transliteration":"dhahābin","translation_bn":"(অন্যত্র) যাওয়ার","root":"ذهب","lemma":"ذَهَاب","grammar_bn":"বিশেষ্য (Noun)"},{"id":20621,"position":12,"text_uthmani":"بِهِۦ","transliteration":"bihi","translation_bn":"নিয়ে তা","root":"—","lemma":"بِهِۦ","grammar_bn":"অব্যয় (Preposition)"},{"id":20622,"position":13,"text_uthmani":"لَقَـٰدِرُونَ","transliteration":"laqādirūna","translation_bn":"অবশ্যই সক্ষম","root":"قدر","lemma":"قَادِر","grammar_bn":"দৃঢ়তাবোধক (Emphatic)"},{"id":20623,"position":14,"text_uthmani":"١٨","transliteration":"","translation_bn":"(১৮)","root":"—","lemma":"١٨","grammar_bn":"মার্কার"}]'::jsonb, 'wa-anzalnā mina l-samāi māan biqadarin fa-askannāhu fī l-arḍi wa-innā ʿalā dhahābin bihi laqādirūna', 'আমি আকাশ থেকে পরিমিত বৃষ্টি বর্ষণ করি, অতঃপর আমি তা যমীনে সংরক্ষণ করি আর আমি পানিকে সরিয়ে দিতে অবশ্যই সক্ষম।', 'And We have sent down rain from the sky in a measured amount and settled it in the earth. And indeed, We are Able to take it away.', 'আমি আকাশ থেকে পরিমিত বৃষ্টি বর্ষণ করি, অতঃপর আমি তা যমীনে সংরক্ষণ করি আর আমি পানিকে সরিয়ে দিতে অবশ্যই সক্ষম।', 'And We have sent down rain from the sky in a measured amount and settled it in the earth. And indeed, We are Able to take it away.', NULL, NULL, NULL, NULL, NULL, 'https://everyayah.com/data/Alafasy_128kbps/023018.mp3', now()),
  (23, 19, '', '[{"id":21671,"position":1,"text_uthmani":"فَأَنشَأْنَا","transliteration":"fa-anshanā","translation_bn":"অতঃপর আমরা সৃষ্টি করি","root":"نشا","lemma":"أَنشَأَ","grammar_bn":"শব্দ"},{"id":21672,"position":2,"text_uthmani":"لَكُم","transliteration":"lakum","translation_bn":"জন্যে তোমাদের","root":"—","lemma":"لَكُم","grammar_bn":"অব্যয় (Preposition)"},{"id":21673,"position":3,"text_uthmani":"بِهِۦ","transliteration":"bihi","translation_bn":"দিয়ে তা","root":"—","lemma":"بِهِۦ","grammar_bn":"অব্যয় (Preposition)"},{"id":21674,"position":4,"text_uthmani":"جَنَّـٰتٍۢ","transliteration":"jannātin","translation_bn":"বাগান","root":"جنن","lemma":"جَنَّة","grammar_bn":"বিশেষ্য (Noun)"},{"id":21675,"position":5,"text_uthmani":"مِّن","transliteration":"min","translation_bn":"(দিয়ে) তৈরি","root":"—","lemma":"مِن\r","grammar_bn":"অব্যয় (Preposition)"},{"id":21676,"position":6,"text_uthmani":"نَّخِيلٍۢ","transliteration":"nakhīlin","translation_bn":"খেজুরের (গাছ)","root":"نخل","lemma":"نَّخِيل","grammar_bn":"বিশেষ্য (Noun)"},{"id":21677,"position":7,"text_uthmani":"وَأَعْنَـٰبٍۢ","transliteration":"wa-aʿnābin","translation_bn":"ও আঙ্গুরের","root":"عنب","lemma":"عِنَب","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":21678,"position":8,"text_uthmani":"لَّكُمْ","transliteration":"lakum","translation_bn":"জন্যে তোমাদের","root":"—","lemma":"لَّكُمْ","grammar_bn":"অব্যয় (Preposition)"},{"id":21679,"position":9,"text_uthmani":"فِيهَا","transliteration":"fīhā","translation_bn":"তার মধ্যে (আছে)","root":"—","lemma":"فِى\r","grammar_bn":"অব্যয় (Preposition)"},{"id":21680,"position":10,"text_uthmani":"فَوَٰكِهُ","transliteration":"fawākihu","translation_bn":"ফলমূল","root":"فكه","lemma":"فَوَٰكِه","grammar_bn":"বিশেষ্য (Noun)"},{"id":21681,"position":11,"text_uthmani":"كَثِيرَةٌۭ","transliteration":"kathīratun","translation_bn":"প্রচুর","root":"كثر","lemma":"كَثِيرَة","grammar_bn":"বিশেষণ (Adjective)"},{"id":21682,"position":12,"text_uthmani":"وَمِنْهَا","transliteration":"wamin''hā","translation_bn":"আর তা হ''তে","root":"—","lemma":"مِن\r","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":21683,"position":13,"text_uthmani":"تَأْكُلُونَ","transliteration":"takulūna","translation_bn":"তোমরা খাও","root":"اكل","lemma":"أَكَلَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":21684,"position":14,"text_uthmani":"١٩","transliteration":"","translation_bn":"(১৯)","root":"—","lemma":"١٩","grammar_bn":"মার্কার"}]'::jsonb, 'fa-anshanā lakum bihi jannātin min nakhīlin wa-aʿnābin lakum fīhā fawākihu kathīratun wamin''hā takulūna', 'অতঃপর আমি তা দিয়ে তোমাদের জন্য খেজুর ও আঙ্গুরের বাগান সৃষ্টি করি, ওতে তোমাদের জন্য আছে পর্যাপ্ত ফল, যাথেকে তোমরা খাও (আর সুখভোগ কর)।', 'And We brought forth for you thereby gardens of palm trees and grapevines in which for you are abundant fruits and from which you eat.', 'অতঃপর আমি তা দিয়ে তোমাদের জন্য খেজুর ও আঙ্গুরের বাগান সৃষ্টি করি, ওতে তোমাদের জন্য আছে পর্যাপ্ত ফল, যাথেকে তোমরা খাও (আর সুখভোগ কর)।', 'And We brought forth for you thereby gardens of palm trees and grapevines in which for you are abundant fruits and from which you eat.', NULL, NULL, NULL, NULL, NULL, 'https://everyayah.com/data/Alafasy_128kbps/023019.mp3', now()),
  (23, 20, '', '[{"id":22756,"position":1,"text_uthmani":"وَشَجَرَةًۭ","transliteration":"washajaratan","translation_bn":"এবং গাছ (জয়তুনের)","root":"شجر","lemma":"شَجَرَة","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":22757,"position":2,"text_uthmani":"تَخْرُجُ","transliteration":"takhruju","translation_bn":"বের হয়","root":"خرج","lemma":"خَرَجَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":22758,"position":3,"text_uthmani":"مِن","transliteration":"min","translation_bn":"হ''তে","root":"—","lemma":"مِن\r","grammar_bn":"অব্যয় (Preposition)"},{"id":22759,"position":4,"text_uthmani":"طُورِ","transliteration":"ṭūri","translation_bn":"পাহাড়","root":"طور","lemma":"طُور","grammar_bn":"বিশেষ্য (Noun)"},{"id":22760,"position":5,"text_uthmani":"سَيْنَآءَ","transliteration":"saynāa","translation_bn":"সিনাইয়ের","root":"—","lemma":"سَيْنَا^ء","grammar_bn":"নামবাচক বিশেষ্য (Proper Noun)"},{"id":22761,"position":6,"text_uthmani":"تَنۢبُتُ","transliteration":"tanbutu","translation_bn":"উৎপন্ন হয়","root":"نبت","lemma":"تَن[بُتُ","grammar_bn":"ক্রিয়া (Verb)"},{"id":22762,"position":7,"text_uthmani":"بِٱلدُّهْنِ","transliteration":"bil-duh''ni","translation_bn":"তেল নিয়ে","root":"دهن","lemma":"دُّهْن","grammar_bn":"অব্যয় (Preposition)"},{"id":22763,"position":8,"text_uthmani":"وَصِبْغٍۢ","transliteration":"waṣib''ghin","translation_bn":"এবং খাবার (তরকারিসহ)","root":"صبغ","lemma":"صِبْغ","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":22764,"position":9,"text_uthmani":"لِّلْـَٔاكِلِينَ","transliteration":"lil''ākilīna","translation_bn":"জন্যে খাদ্যগ্রহণকারীদের","root":"اكل","lemma":"ءَاكِلُون","grammar_bn":"অব্যয় (Preposition)"},{"id":22765,"position":10,"text_uthmani":"٢٠","transliteration":"","translation_bn":"(২০)","root":"—","lemma":"٢٠","grammar_bn":"মার্কার"}]'::jsonb, 'washajaratan takhruju min ṭūri saynāa tanbutu bil-duh''ni waṣib''ghin lil''ākilīna', 'আর (আমি সৃষ্টি করি) এক বৃক্ষ যা সিনাই পর্বতে জন্মে, যাথেকে তেল উৎপন্ন হয়, আর ভক্ষণকারীদের জন্য রসনা তৃপ্তিকর।', 'And [We brought forth] a tree issuing from Mount Sinai which produces oil and food for those who eat.', 'আর (আমি সৃষ্টি করি) এক বৃক্ষ যা সিনাই পর্বতে জন্মে, যাথেকে তেল উৎপন্ন হয়, আর ভক্ষণকারীদের জন্য রসনা তৃপ্তিকর।', 'And [We brought forth] a tree issuing from Mount Sinai which produces oil and food for those who eat.', NULL, NULL, NULL, NULL, NULL, 'https://everyayah.com/data/Alafasy_128kbps/023020.mp3', now()),
  (23, 21, '', '[{"id":23928,"position":1,"text_uthmani":"وَإِنَّ","transliteration":"wa-inna","translation_bn":"এবং নিশ্চয়ই","root":"—","lemma":"إِنّ","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":23929,"position":2,"text_uthmani":"لَكُمْ","transliteration":"lakum","translation_bn":"জন্যে তোমাদের","root":"—","lemma":"لَكُمْ","grammar_bn":"অব্যয় (Preposition)"},{"id":23930,"position":3,"text_uthmani":"فِى","transliteration":"fī","translation_bn":"মধ্যে (আছে)","root":"—","lemma":"فِى\r","grammar_bn":"অব্যয় (Preposition)"},{"id":23931,"position":4,"text_uthmani":"ٱلْأَنْعَـٰمِ","transliteration":"l-anʿāmi","translation_bn":"গৃহপালিত পশুদের","root":"نعم","lemma":"نَّعَم","grammar_bn":"শব্দ"},{"id":23932,"position":5,"text_uthmani":"لَعِبْرَةًۭ ۖ","transliteration":"laʿib''ratan","translation_bn":"অবশ্যই শিক্ষা","root":"عبر","lemma":"عِبْرَة","grammar_bn":"দৃঢ়তাবোধক (Emphatic)"},{"id":23934,"position":6,"text_uthmani":"نُّسْقِيكُم","transliteration":"nus''qīkum","translation_bn":"তোমাদেরকে পান করাই আমরা","root":"سقي","lemma":"أَسْقَيْ","grammar_bn":"ক্রিয়া (Verb)"},{"id":23935,"position":7,"text_uthmani":"مِّمَّا","transliteration":"mimmā","translation_bn":"তা হ''তে যা","root":"—","lemma":"مِن\r","grammar_bn":"অব্যয় (Preposition)"},{"id":23936,"position":8,"text_uthmani":"فِى","transliteration":"fī","translation_bn":"রয়েছে","root":"—","lemma":"فِى\r","grammar_bn":"অব্যয় (Preposition)"},{"id":23937,"position":9,"text_uthmani":"بُطُونِهَا","transliteration":"buṭūnihā","translation_bn":"তাদের পেটে (অর্থাৎ দুধ)","root":"بطن","lemma":"بَطْن","grammar_bn":"বিশেষ্য (Noun)"},{"id":23938,"position":10,"text_uthmani":"وَلَكُمْ","transliteration":"walakum","translation_bn":"আর জন্যে তোমাদের (রয়েছে)","root":"—","lemma":"وَلَكُمْ","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":23939,"position":11,"text_uthmani":"فِيهَا","transliteration":"fīhā","translation_bn":"তাদের মধ্যে","root":"—","lemma":"فِى\r","grammar_bn":"অব্যয় (Preposition)"},{"id":23940,"position":12,"text_uthmani":"مَنَـٰفِعُ","transliteration":"manāfiʿu","translation_bn":"উপকারিতা","root":"نفع","lemma":"مَنَٰفِع","grammar_bn":"বিশেষ্য (Noun)"},{"id":23941,"position":13,"text_uthmani":"كَثِيرَةٌۭ","transliteration":"kathīratun","translation_bn":"প্রচুর","root":"كثر","lemma":"كَثِيرَة","grammar_bn":"বিশেষণ (Adjective)"},{"id":23942,"position":14,"text_uthmani":"وَمِنْهَا","transliteration":"wamin''hā","translation_bn":"আর তাদের মধ্য হ''তে","root":"—","lemma":"مِن\r","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":23943,"position":15,"text_uthmani":"تَأْكُلُونَ","transliteration":"takulūna","translation_bn":"তোমরা খাও (গোশত)","root":"اكل","lemma":"أَكَلَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":23944,"position":16,"text_uthmani":"٢١","transliteration":"","translation_bn":"(২১)","root":"—","lemma":"٢١","grammar_bn":"মার্কার"}]'::jsonb, 'wa-inna lakum fī l-anʿāmi laʿib''ratan nus''qīkum mimmā fī buṭūnihā walakum fīhā manāfiʿu kathīratun wamin''hā takulūna', 'আর গবাদি পশুর ভিতরে তোমাদের জন্য আছে অবশ্যই শিক্ষণীয় দৃষ্টান্ত। তাদের পেটে যা আছে তাত্থেকে আমি তোমাদেরকে পান করাই (দুধ) আর ওতে তোমাদের জন্য আছে বহুবিধ উপকার। তোমরা তাথেকে খাও (গোশত)।', 'And indeed, for you in livestock is a lesson. We give you drink from that which is in their bellies, and for you in them are numerous benefits, and from them you eat.', 'আর গবাদি পশুর ভিতরে তোমাদের জন্য আছে অবশ্যই শিক্ষণীয় দৃষ্টান্ত। তাদের পেটে যা আছে তাত্থেকে আমি তোমাদেরকে পান করাই (দুধ) আর ওতে তোমাদের জন্য আছে বহুবিধ উপকার। তোমরা তাথেকে খাও (গোশত)।', 'And indeed, for you in livestock is a lesson. We give you drink from that which is in their bellies, and for you in them are numerous benefits, and from them you eat.', NULL, NULL, NULL, NULL, NULL, 'https://everyayah.com/data/Alafasy_128kbps/023021.mp3', now()),
  (23, 22, '', '[{"id":24912,"position":1,"text_uthmani":"وَعَلَيْهَا","transliteration":"waʿalayhā","translation_bn":"এবং তাদের উপর","root":"—","lemma":"عَلَىٰ\r","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":24913,"position":2,"text_uthmani":"وَعَلَى","transliteration":"waʿalā","translation_bn":"ও উপর","root":"—","lemma":"عَلَىٰ\r","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":24914,"position":3,"text_uthmani":"ٱلْفُلْكِ","transliteration":"l-ful''ki","translation_bn":"নৌযানের","root":"فلك","lemma":"فُلْك","grammar_bn":"শব্দ"},{"id":24915,"position":4,"text_uthmani":"تُحْمَلُونَ","transliteration":"tuḥ''malūna","translation_bn":"তোমাদের বহন করা হয়","root":"حمل","lemma":"حَمَلَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":24916,"position":5,"text_uthmani":"٢٢","transliteration":"","translation_bn":"(২২)","root":"—","lemma":"٢٢","grammar_bn":"মার্কার"}]'::jsonb, 'waʿalayhā waʿalā l-ful''ki tuḥ''malūna', 'আর ওতে আর নৌযানে তোমরা আরোহণ কর।', 'And upon them and on ships you are carried.', 'আর ওতে আর নৌযানে তোমরা আরোহণ কর।', 'And upon them and on ships you are carried.', NULL, NULL, NULL, NULL, NULL, 'https://everyayah.com/data/Alafasy_128kbps/023022.mp3', now()),
  (23, 23, '', '[{"id":25875,"position":1,"text_uthmani":"وَلَقَدْ","transliteration":"walaqad","translation_bn":"আর নিশ্চয়ই","root":"—","lemma":"قَد\r","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":25876,"position":2,"text_uthmani":"أَرْسَلْنَا","transliteration":"arsalnā","translation_bn":"আমরা পাঠিয়েছি","root":"رسل","lemma":"أَرْسَلَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":25877,"position":3,"text_uthmani":"نُوحًا","transliteration":"nūḥan","translation_bn":"নূহকে","root":"—","lemma":"نُوح","grammar_bn":"নামবাচক বিশেষ্য (Proper Noun)"},{"id":25878,"position":4,"text_uthmani":"إِلَىٰ","transliteration":"ilā","translation_bn":"প্রতি","root":"—","lemma":"إِلَىٰ\r","grammar_bn":"অব্যয় (Preposition)"},{"id":25879,"position":5,"text_uthmani":"قَوْمِهِۦ","transliteration":"qawmihi","translation_bn":"তার জাতির","root":"قوم","lemma":"قَوْم","grammar_bn":"বিশেষ্য (Noun)"},{"id":25880,"position":6,"text_uthmani":"فَقَالَ","transliteration":"faqāla","translation_bn":"তখন সে বলেছিলো","root":"قول","lemma":"قَالَ","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":25881,"position":7,"text_uthmani":"يَـٰقَوْمِ","transliteration":"yāqawmi","translation_bn":"\"হে আমার জাতি","root":"قوم","lemma":"قَوْم","grammar_bn":"সম্বোধন পদ (Vocative)"},{"id":25882,"position":8,"text_uthmani":"ٱعْبُدُوا۟","transliteration":"uʿ''budū","translation_bn":"তোমরা ইবাদাত করো","root":"عبد","lemma":"عَبَدَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":25883,"position":9,"text_uthmani":"ٱللَّهَ","transliteration":"l-laha","translation_bn":"আল্লাহর","root":"اله","lemma":"ٱللَّه","grammar_bn":"নামবাচক বিশেষ্য (Proper Noun)"},{"id":25884,"position":10,"text_uthmani":"مَا","transliteration":"mā","translation_bn":"নেই","root":"—","lemma":"مَا\r","grammar_bn":"না-বোধক (Negative)"},{"id":25885,"position":11,"text_uthmani":"لَكُم","transliteration":"lakum","translation_bn":"জন্যে তোমাদের","root":"—","lemma":"لَكُم","grammar_bn":"অব্যয় (Preposition)"},{"id":25886,"position":12,"text_uthmani":"مِّنْ","transliteration":"min","translation_bn":"কোন","root":"—","lemma":"مِن\r","grammar_bn":"অব্যয় (Preposition)"},{"id":25887,"position":13,"text_uthmani":"إِلَـٰهٍ","transliteration":"ilāhin","translation_bn":"ইলাহ","root":"اله","lemma":"إِلَٰه","grammar_bn":"বিশেষ্য (Noun)"},{"id":25888,"position":14,"text_uthmani":"غَيْرُهُۥٓ ۖ","transliteration":"ghayruhu","translation_bn":"তিনি ছাড়া","root":"غير","lemma":"غَيْر","grammar_bn":"বিশেষ্য (Noun)"},{"id":25890,"position":15,"text_uthmani":"أَفَلَا","transliteration":"afalā","translation_bn":"কি তবুও না","root":"—","lemma":"لَا\r","grammar_bn":"প্রশ্নবোধক (Interrogative)"},{"id":25891,"position":16,"text_uthmani":"تَتَّقُونَ","transliteration":"tattaqūna","translation_bn":"তোমরা সাবধান হবে\"","root":"وقي","lemma":"ٱتَّقَىٰ","grammar_bn":"ক্রিয়া (Verb)"},{"id":25892,"position":17,"text_uthmani":"٢٣","transliteration":"","translation_bn":"(২৩)","root":"—","lemma":"٢٣","grammar_bn":"মার্কার"}]'::jsonb, 'walaqad arsalnā nūḥan ilā qawmihi faqāla yāqawmi uʿ''budū l-laha mā lakum min ilāhin ghayruhu afalā tattaqūna', 'আমি নূহকে তাঁর সম্প্রদায়ের কাছে পাঠিয়েছিলাম। সে বলেছিল : ‘হে আমার জাতি! তোমরা আল্লাহর ‘ইবাদাত কর, তিনি ছাড়া তোমাদের কোন ইলাহ নেই, তোমরা কি (তাঁকে) ভয় করবে না?’', 'And We had certainly sent Noah to his people, and he said, "O my people, worship Allah; you have no deity other than Him; then will you not fear Him?"', 'আমি নূহকে তাঁর সম্প্রদায়ের কাছে পাঠিয়েছিলাম। সে বলেছিল : ‘হে আমার জাতি! তোমরা আল্লাহর ‘ইবাদাত কর, তিনি ছাড়া তোমাদের কোন ইলাহ নেই, তোমরা কি (তাঁকে) ভয় করবে না?’', 'And We had certainly sent Noah to his people, and he said, "O my people, worship Allah; you have no deity other than Him; then will you not fear Him?"', NULL, NULL, NULL, NULL, NULL, 'https://everyayah.com/data/Alafasy_128kbps/023023.mp3', now()),
  (23, 24, '', '[{"id":27045,"position":1,"text_uthmani":"فَقَالَ","transliteration":"faqāla","translation_bn":"তখন বলেছিলো","root":"قول","lemma":"قَالَ","grammar_bn":"শব্দ"},{"id":27046,"position":2,"text_uthmani":"ٱلْمَلَؤُا۟","transliteration":"l-mala-u","translation_bn":"প্রধান ব্যক্তিরা","root":"ملا","lemma":"مَلَأ","grammar_bn":"শব্দ"},{"id":27047,"position":3,"text_uthmani":"ٱلَّذِينَ","transliteration":"alladhīna","translation_bn":"(তাদের) যারা","root":"—","lemma":"ٱلَّذِى","grammar_bn":"সাপেক্ষ সর্বনাম (Relative)"},{"id":27048,"position":4,"text_uthmani":"كَفَرُوا۟","transliteration":"kafarū","translation_bn":"অস্বীকার করেছিলো","root":"كفر","lemma":"كَفَرَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":27049,"position":5,"text_uthmani":"مِن","transliteration":"min","translation_bn":"মধ্য হ''তে","root":"—","lemma":"مِن\r","grammar_bn":"অব্যয় (Preposition)"},{"id":27050,"position":6,"text_uthmani":"قَوْمِهِۦ","transliteration":"qawmihi","translation_bn":"তার জাতির","root":"قوم","lemma":"قَوْم","grammar_bn":"বিশেষ্য (Noun)"},{"id":27051,"position":7,"text_uthmani":"مَا","transliteration":"mā","translation_bn":"\"নয়","root":"—","lemma":"مَا\r","grammar_bn":"না-বোধক (Negative)"},{"id":27052,"position":8,"text_uthmani":"هَـٰذَآ","transliteration":"hādhā","translation_bn":"\"এই (ব্যক্তি)","root":"—","lemma":"هَٰذَا","grammar_bn":"নির্দেশক সর্বনাম (Demonstrative)"},{"id":27053,"position":9,"text_uthmani":"إِلَّا","transliteration":"illā","translation_bn":"এ ছাড়া যে","root":"—","lemma":"إِلَّا\r","grammar_bn":"সীমাবদ্ধতা (Restriction)"},{"id":27054,"position":10,"text_uthmani":"بَشَرٌۭ","transliteration":"basharun","translation_bn":"একজন মানুষ","root":"بشر","lemma":"بَشَر","grammar_bn":"বিশেষ্য (Noun)"},{"id":27055,"position":11,"text_uthmani":"مِّثْلُكُمْ","transliteration":"mith''lukum","translation_bn":"তোমাদেরই মতো","root":"مثل","lemma":"مِثْل","grammar_bn":"বিশেষ্য (Noun)"},{"id":27056,"position":12,"text_uthmani":"يُرِيدُ","transliteration":"yurīdu","translation_bn":"সে চায়","root":"رود","lemma":"أَرَادَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":27057,"position":13,"text_uthmani":"أَن","transliteration":"an","translation_bn":"যে","root":"—","lemma":"أَن\r","grammar_bn":"অধীনস্থ যোজক (Subordinating)"},{"id":27058,"position":14,"text_uthmani":"يَتَفَضَّلَ","transliteration":"yatafaḍḍala","translation_bn":"শ্রেষ্ঠত্ব লাভ করবে","root":"فضل","lemma":"يَتَفَضَّلَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":27059,"position":15,"text_uthmani":"عَلَيْكُمْ","transliteration":"ʿalaykum","translation_bn":"তোমাদের উপর","root":"—","lemma":"عَلَىٰ\r","grammar_bn":"অব্যয় (Preposition)"},{"id":27060,"position":16,"text_uthmani":"وَلَوْ","transliteration":"walaw","translation_bn":"আর যদি","root":"—","lemma":"لَو\r","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":27061,"position":17,"text_uthmani":"شَآءَ","transliteration":"shāa","translation_bn":"চাইতেন","root":"شيا","lemma":"شَا^ءَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":27062,"position":18,"text_uthmani":"ٱللَّهُ","transliteration":"l-lahu","translation_bn":"আল্লাহ্‌","root":"اله","lemma":"ٱللَّه","grammar_bn":"নামবাচক বিশেষ্য (Proper Noun)"},{"id":27063,"position":19,"text_uthmani":"لَأَنزَلَ","transliteration":"la-anzala","translation_bn":"অবশ্যই পাঠাতেন","root":"نزل","lemma":"أَنزَلَ","grammar_bn":"দৃঢ়তাবোধক (Emphatic)"},{"id":27064,"position":20,"text_uthmani":"مَلَـٰٓئِكَةًۭ","transliteration":"malāikatan","translation_bn":"ফেরেশতা","root":"ملك","lemma":"مَلَك","grammar_bn":"বিশেষ্য (Noun)"},{"id":27065,"position":21,"text_uthmani":"مَّا","transliteration":"mā","translation_bn":"না","root":"—","lemma":"مَا\r","grammar_bn":"না-বোধক (Negative)"},{"id":27066,"position":22,"text_uthmani":"سَمِعْنَا","transliteration":"samiʿ''nā","translation_bn":"আমরা শুনেছি","root":"سمع","lemma":"سَمِعَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":27067,"position":23,"text_uthmani":"بِهَـٰذَا","transliteration":"bihādhā","translation_bn":"ধরণের এ (কথা)","root":"—","lemma":"هَٰذَا","grammar_bn":"অব্যয় (Preposition)"},{"id":27068,"position":24,"text_uthmani":"فِىٓ","transliteration":"fī","translation_bn":"মধ্যে","root":"—","lemma":"فِى\r","grammar_bn":"অব্যয় (Preposition)"},{"id":27069,"position":25,"text_uthmani":"ءَابَآئِنَا","transliteration":"ābāinā","translation_bn":"আমাদের পিতৃপুরুষদের","root":"ابو","lemma":"ا^بَاء","grammar_bn":"বিশেষ্য (Noun)"},{"id":27070,"position":26,"text_uthmani":"ٱلْأَوَّلِينَ","transliteration":"l-awalīna","translation_bn":"পূর্বকালের","root":"اول","lemma":"أَوَّل","grammar_bn":"শব্দ"},{"id":27071,"position":27,"text_uthmani":"٢٤","transliteration":"","translation_bn":"(২৪)","root":"—","lemma":"٢٤","grammar_bn":"মার্কার"}]'::jsonb, 'faqāla l-mala-u alladhīna kafarū min qawmihi mā hādhā illā basharun mith''lukum yurīdu an yatafaḍḍala ʿalaykum walaw shāa l-lahu la-anzala malāikatan mā samiʿ''nā bihādhā fī ābāinā l-awalīna', 'তার সম্প্রদায়ের প্রধানগণ যারা কুফুরী করেছিল- বলেছিল : ‘এতো তোমাদের মত মানুষ ছাড়া কিছুই না, সে তোমাদের উপর প্রাধান্য লাভ করতে চায়, আল্লাহ (কাউকে নবীরূপে পাঠানোর) ইচ্ছে করলে তো তিনি ফেরেশতা পাঠাতেন, আমরা আমাদের পূর্ব পুরুষদের সময়ে এ সব কথা তো শুনিনি।’', 'But the eminent among those who disbelieved from his people said, "This is not but a man like yourselves who wishes to take precedence over you; and if Allah had willed [to send a messenger], He would have sent down angels. We have not heard of this among our forefathers.', 'তার সম্প্রদায়ের প্রধানগণ যারা কুফুরী করেছিল- বলেছিল : ‘এতো তোমাদের মত মানুষ ছাড়া কিছুই না, সে তোমাদের উপর প্রাধান্য লাভ করতে চায়, আল্লাহ (কাউকে নবীরূপে পাঠানোর) ইচ্ছে করলে তো তিনি ফেরেশতা পাঠাতেন, আমরা আমাদের পূর্ব পুরুষদের সময়ে এ সব কথা তো শুনিনি।’', 'But the eminent among those who disbelieved from his people said, "This is not but a man like yourselves who wishes to take precedence over you; and if Allah had willed [to send a messenger], He would have sent down angels. We have not heard of this among our forefathers.', NULL, NULL, NULL, NULL, NULL, 'https://everyayah.com/data/Alafasy_128kbps/023024.mp3', now()),
  (23, 25, '', '[{"id":28046,"position":1,"text_uthmani":"إِنْ","transliteration":"in","translation_bn":"নয়","root":"—","lemma":"إِن\r","grammar_bn":"না-বোধক (Negative)"},{"id":28047,"position":2,"text_uthmani":"هُوَ","transliteration":"huwa","translation_bn":"সে","root":"—","lemma":"هُوَ","grammar_bn":"সর্বনাম (Pronoun)"},{"id":28048,"position":3,"text_uthmani":"إِلَّا","transliteration":"illā","translation_bn":"এ ছাড়া যে","root":"—","lemma":"إِلَّا\r","grammar_bn":"সীমাবদ্ধতা (Restriction)"},{"id":28049,"position":4,"text_uthmani":"رَجُلٌۢ","transliteration":"rajulun","translation_bn":"একজন মানুষ","root":"رجل","lemma":"رَجُل","grammar_bn":"বিশেষ্য (Noun)"},{"id":28050,"position":5,"text_uthmani":"بِهِۦ","transliteration":"bihi","translation_bn":"সাথে তার (আছে)","root":"—","lemma":"بِهِۦ","grammar_bn":"অব্যয় (Preposition)"},{"id":28051,"position":6,"text_uthmani":"جِنَّةٌۭ","transliteration":"jinnatun","translation_bn":"জ্বিন","root":"جنن","lemma":"جِنَّة","grammar_bn":"বিশেষ্য (Noun)"},{"id":28052,"position":7,"text_uthmani":"فَتَرَبَّصُوا۟","transliteration":"fatarabbaṣū","translation_bn":"অতএব তোমরা অপেক্ষা করো","root":"ربص","lemma":"تَرَبَّصْ","grammar_bn":"শব্দ"},{"id":28053,"position":8,"text_uthmani":"بِهِۦ","transliteration":"bihi","translation_bn":"সম্পর্কে তার","root":"—","lemma":"بِهِۦ","grammar_bn":"অব্যয় (Preposition)"},{"id":28054,"position":9,"text_uthmani":"حَتَّىٰ","transliteration":"ḥattā","translation_bn":"পর্যন্ত","root":"—","lemma":"حَتَّىٰ\r","grammar_bn":"অব্যয় (Preposition)"},{"id":28055,"position":10,"text_uthmani":"حِينٍۢ","transliteration":"ḥīnin","translation_bn":"কিছুকাল\"","root":"حين","lemma":"حِين","grammar_bn":"বিশেষ্য (Noun)"},{"id":28056,"position":11,"text_uthmani":"٢٥","transliteration":"","translation_bn":"(২৫)","root":"—","lemma":"٢٥","grammar_bn":"মার্কার"}]'::jsonb, 'in huwa illā rajulun bihi jinnatun fatarabbaṣū bihi ḥattā ḥīnin', 'এতো এমন লোক যাকে পাগলামিতে পেয়েছে, কাজেই তার ব্যাপারে তোমরা কিছু কাল অপেক্ষা কর।', 'He is not but a man possessed with madness, so wait concerning him for a time."', 'এতো এমন লোক যাকে পাগলামিতে পেয়েছে, কাজেই তার ব্যাপারে তোমরা কিছু কাল অপেক্ষা কর।', 'He is not but a man possessed with madness, so wait concerning him for a time."', NULL, NULL, NULL, NULL, NULL, 'https://everyayah.com/data/Alafasy_128kbps/023025.mp3', now()),
  (23, 26, '', '[{"id":29044,"position":1,"text_uthmani":"قَالَ","transliteration":"qāla","translation_bn":"(নূহ) বললো","root":"قول","lemma":"قَالَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":29045,"position":2,"text_uthmani":"رَبِّ","transliteration":"rabbi","translation_bn":"\"হে আমার রব","root":"ربب","lemma":"رَبّ","grammar_bn":"বিশেষ্য (Noun)"},{"id":29046,"position":3,"text_uthmani":"ٱنصُرْنِى","transliteration":"unṣur''nī","translation_bn":"আমাকে সাহায্য করো","root":"نصر","lemma":"نَصَرَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":29047,"position":4,"text_uthmani":"بِمَا","transliteration":"bimā","translation_bn":"এ কারণে যে","root":"—","lemma":"مَا\r","grammar_bn":"অব্যয় (Preposition)"},{"id":29048,"position":5,"text_uthmani":"كَذَّبُونِ","transliteration":"kadhabūni","translation_bn":"আমাকে তারা মিথ্যা সাব্যস্ত করেছে\"","root":"كذب","lemma":"كَذَّبَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":29049,"position":6,"text_uthmani":"٢٦","transliteration":"","translation_bn":"(২৬)","root":"—","lemma":"٢٦","grammar_bn":"মার্কার"}]'::jsonb, 'qāla rabbi unṣur''nī bimā kadhabūni', 'নূহ বলল : ‘হে আমার প্রতিপালক! তুমি আমাকে সাহায্য কর, কারণ তারা আমাকে মিথ্যেবাদী বলছে।’', '[Noah] said, "My Lord, support me because they have denied me."', 'নূহ বলল : ‘হে আমার প্রতিপালক! তুমি আমাকে সাহায্য কর, কারণ তারা আমাকে মিথ্যেবাদী বলছে।’', '[Noah] said, "My Lord, support me because they have denied me."', NULL, NULL, NULL, NULL, NULL, 'https://everyayah.com/data/Alafasy_128kbps/023026.mp3', now()),
  (23, 27, '', '[{"id":29812,"position":1,"text_uthmani":"فَأَوْحَيْنَآ","transliteration":"fa-awḥaynā","translation_bn":"অতঃপর আমরা ওহী করলাম","root":"وحي","lemma":"أَوْحَىٰ^","grammar_bn":"শব্দ"},{"id":29813,"position":2,"text_uthmani":"إِلَيْهِ","transliteration":"ilayhi","translation_bn":"তার প্রতি","root":"—","lemma":"إِلَىٰ\r","grammar_bn":"অব্যয় (Preposition)"},{"id":29814,"position":3,"text_uthmani":"أَنِ","transliteration":"ani","translation_bn":"\"যে","root":"—","lemma":"أَن\r","grammar_bn":"উদ্দেশ্যবাচক (Intention)"},{"id":29815,"position":4,"text_uthmani":"ٱصْنَعِ","transliteration":"iṣ''naʿi","translation_bn":"নির্মাণ করো","root":"صنع","lemma":"صَنَعُ","grammar_bn":"ক্রিয়া (Verb)"},{"id":29816,"position":5,"text_uthmani":"ٱلْفُلْكَ","transliteration":"l-ful''ka","translation_bn":"নৌকা","root":"فلك","lemma":"فُلْك","grammar_bn":"শব্দ"},{"id":29817,"position":6,"text_uthmani":"بِأَعْيُنِنَا","transliteration":"bi-aʿyuninā","translation_bn":"সামনে আমাদের চোখের","root":"عين","lemma":"عَيْن","grammar_bn":"অব্যয় (Preposition)"},{"id":29818,"position":7,"text_uthmani":"وَوَحْيِنَا","transliteration":"wawaḥyinā","translation_bn":"ও আমাদের ওহীর ভিত্তিতে","root":"وحي","lemma":"وَحْى","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":29819,"position":8,"text_uthmani":"فَإِذَا","transliteration":"fa-idhā","translation_bn":"অতঃপর যখন","root":"—","lemma":"إِذَا\r","grammar_bn":"শব্দ"},{"id":29820,"position":9,"text_uthmani":"جَآءَ","transliteration":"jāa","translation_bn":"আসবে","root":"جيا","lemma":"جَا^ءَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":29821,"position":10,"text_uthmani":"أَمْرُنَا","transliteration":"amrunā","translation_bn":"আমাদের নির্দেশ","root":"امر","lemma":"أَمْر","grammar_bn":"বিশেষ্য (Noun)"},{"id":29822,"position":11,"text_uthmani":"وَفَارَ","transliteration":"wafāra","translation_bn":"ও উথলে উঠবে","root":"فور","lemma":"فَارَ","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":29823,"position":12,"text_uthmani":"ٱلتَّنُّورُ ۙ","transliteration":"l-tanūru","translation_bn":"চুলাটি","root":"—","lemma":"تَّنُّور","grammar_bn":"শব্দ"},{"id":29825,"position":13,"text_uthmani":"فَٱسْلُكْ","transliteration":"fa-us''luk","translation_bn":"(নৌকাতে) তখন উঠিয়ে নিবে","root":"سلك","lemma":"سَلَكَ","grammar_bn":"শব্দ"},{"id":29826,"position":14,"text_uthmani":"فِيهَا","transliteration":"fīhā","translation_bn":"তার মধ্যে","root":"—","lemma":"فِى\r","grammar_bn":"অব্যয় (Preposition)"},{"id":29827,"position":15,"text_uthmani":"مِن","transliteration":"min","translation_bn":"ধরণের","root":"—","lemma":"مِن\r","grammar_bn":"অব্যয় (Preposition)"},{"id":29828,"position":16,"text_uthmani":"كُلٍّۢ","transliteration":"kullin","translation_bn":"প্রত্যেক (জীব জন্তুর)","root":"كلل","lemma":"كُلّ","grammar_bn":"বিশেষ্য (Noun)"},{"id":29829,"position":17,"text_uthmani":"زَوْجَيْنِ","transliteration":"zawjayni","translation_bn":"জোড়া","root":"زوج","lemma":"زَوْج","grammar_bn":"বিশেষ্য (Noun)"},{"id":29830,"position":18,"text_uthmani":"ٱثْنَيْنِ","transliteration":"ith''nayni","translation_bn":"দুইটার (অর্থাৎ নর ও নারী)","root":"ثني","lemma":"ٱثْنَيْن","grammar_bn":"বিশেষ্য (Noun)"},{"id":29831,"position":19,"text_uthmani":"وَأَهْلَكَ","transliteration":"wa-ahlaka","translation_bn":"ও তোমার পরিবারকে","root":"اهل","lemma":"أَهْل","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":29832,"position":20,"text_uthmani":"إِلَّا","transliteration":"illā","translation_bn":"ছাড়া","root":"—","lemma":"إِلَّا\r","grammar_bn":"সীমাবদ্ধতা (Restriction)"},{"id":29833,"position":21,"text_uthmani":"مَن","transliteration":"man","translation_bn":"তাদের","root":"—","lemma":"مَن\r","grammar_bn":"সাপেক্ষ সর্বনাম (Relative)"},{"id":29834,"position":22,"text_uthmani":"سَبَقَ","transliteration":"sabaqa","translation_bn":"পূর্বে নির্ধারিত হয়েছে","root":"سبق","lemma":"سَبَقَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":29835,"position":23,"text_uthmani":"عَلَيْهِ","transliteration":"ʿalayhi","translation_bn":"যাদের সম্পর্কে","root":"—","lemma":"عَلَىٰ\r","grammar_bn":"অব্যয় (Preposition)"},{"id":29836,"position":24,"text_uthmani":"ٱلْقَوْلُ","transliteration":"l-qawlu","translation_bn":"বাণী (সিদ্ধান্ত)","root":"قول","lemma":"قَوْل","grammar_bn":"শব্দ"},{"id":29837,"position":25,"text_uthmani":"مِنْهُمْ ۖ","transliteration":"min''hum","translation_bn":"তাদের মধ্য হ''তে","root":"—","lemma":"مِن\r","grammar_bn":"অব্যয় (Preposition)"},{"id":29839,"position":26,"text_uthmani":"وَلَا","transliteration":"walā","translation_bn":"এবং না","root":"—","lemma":"لَا\r","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":29840,"position":27,"text_uthmani":"تُخَـٰطِبْنِى","transliteration":"tukhāṭib''nī","translation_bn":"আমাকে কিছু বলো","root":"خطب","lemma":"خَاطَبَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":29841,"position":28,"text_uthmani":"فِى","transliteration":"fī","translation_bn":"সম্পর্কে","root":"—","lemma":"فِى\r","grammar_bn":"অব্যয় (Preposition)"},{"id":29842,"position":29,"text_uthmani":"ٱلَّذِينَ","transliteration":"alladhīna","translation_bn":"(তাদের) যারা","root":"—","lemma":"ٱلَّذِى","grammar_bn":"সাপেক্ষ সর্বনাম (Relative)"},{"id":29843,"position":30,"text_uthmani":"ظَلَمُوٓا۟ ۖ","transliteration":"ẓalamū","translation_bn":"অত্যাচার করেছে","root":"ظلم","lemma":"ظَلَمَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":29845,"position":31,"text_uthmani":"إِنَّهُم","transliteration":"innahum","translation_bn":"তারা নিশ্চয়ই","root":"—","lemma":"إِنّ","grammar_bn":"অভিঘাত পদ (Accusative)"},{"id":29846,"position":32,"text_uthmani":"مُّغْرَقُونَ","transliteration":"mugh''raqūna","translation_bn":"নিমজ্জিত হবে","root":"غرق","lemma":"مُّغْرَقُون","grammar_bn":"বিশেষ্য (Noun)"},{"id":29847,"position":33,"text_uthmani":"٢٧","transliteration":"","translation_bn":"(২৭)","root":"—","lemma":"٢٧","grammar_bn":"মার্কার"}]'::jsonb, 'fa-awḥaynā ilayhi ani iṣ''naʿi l-ful''ka bi-aʿyuninā wawaḥyinā fa-idhā jāa amrunā wafāra l-tanūru fa-us''luk fīhā min kullin zawjayni ith''nayni wa-ahlaka illā man sabaqa ʿalayhi l-qawlu min''hum walā tukhāṭib''nī fī alladhīna ẓalamū innahum mugh''raqūna', 'তখন আমি তার কাছে ওয়াহী পাঠালাম- আমার দৃষ্টির সম্মুখে আমার নির্দেশ অনুযায়ী নৌযান তৈরি কর, অতঃপর যখন আমার নির্দেশ আসবে আর উনুন (পানিতে) উথলে উঠবে, তখন নৌকায় তুলে নাও প্রত্যেক জীবের এক এক জোড়া আর তোমার পরিবারবর্গকে, তাদের মধ্যে যাদের বিপক্ষে পূর্বে সিদ্ধান্ত হয়ে গেছে তাদেরকে বাদ দিয়ে। আর অন্যায়কারীদের পক্ষে আমার নিকট আবেদন করো না, তারা (বানে) ডুববেই।', 'So We inspired to him, "Construct the ship under Our observation, and Our inspiration, and when Our command comes and the oven overflows, put into the ship from each [creature] two mates and your family, except those for whom the decree [of destruction] has proceeded. And do not address Me concerning those who have wronged; indeed, they are to be drowned.', 'তখন আমি তার কাছে ওয়াহী পাঠালাম- আমার দৃষ্টির সম্মুখে আমার নির্দেশ অনুযায়ী নৌযান তৈরি কর, অতঃপর যখন আমার নির্দেশ আসবে আর উনুন (পানিতে) উথলে উঠবে, তখন নৌকায় তুলে নাও প্রত্যেক জীবের এক এক জোড়া আর তোমার পরিবারবর্গকে, তাদের মধ্যে যাদের বিপক্ষে পূর্বে সিদ্ধান্ত হয়ে গেছে তাদেরকে বাদ দিয়ে। আর অন্যায়কারীদের পক্ষে আমার নিকট আবেদন করো না, তারা (বানে) ডুববেই।', 'So We inspired to him, "Construct the ship under Our observation, and Our inspiration, and when Our command comes and the oven overflows, put into the ship from each [creature] two mates and your family, except those for whom the decree [of destruction] has proceeded. And do not address Me concerning those who have wronged; indeed, they are to be drowned.', NULL, NULL, NULL, NULL, NULL, 'https://everyayah.com/data/Alafasy_128kbps/023027.mp3', now()),
  (23, 28, '', '[{"id":30972,"position":1,"text_uthmani":"فَإِذَا","transliteration":"fa-idhā","translation_bn":"অতঃপর যখন","root":"—","lemma":"إِذَا\r","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":30973,"position":2,"text_uthmani":"ٱسْتَوَيْتَ","transliteration":"is''tawayta","translation_bn":"তুমি স্হির হবে","root":"سوي","lemma":"ٱسْتَوَىٰ^","grammar_bn":"ক্রিয়া (Verb)"},{"id":30974,"position":3,"text_uthmani":"أَنتَ","transliteration":"anta","translation_bn":"তুমি","root":"—","lemma":"أَنتَ","grammar_bn":"সর্বনাম (Pronoun)"},{"id":30975,"position":4,"text_uthmani":"وَمَن","transliteration":"waman","translation_bn":"ও যারা","root":"—","lemma":"مَن\r","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":30976,"position":5,"text_uthmani":"مَّعَكَ","transliteration":"maʿaka","translation_bn":"তোমার সাথে","root":"—","lemma":"مَع","grammar_bn":"স্থানবাচক (Location)"},{"id":30977,"position":6,"text_uthmani":"عَلَى","transliteration":"ʿalā","translation_bn":"উপর","root":"—","lemma":"عَلَىٰ\r","grammar_bn":"অব্যয় (Preposition)"},{"id":30978,"position":7,"text_uthmani":"ٱلْفُلْكِ","transliteration":"l-ful''ki","translation_bn":"নৌকার","root":"فلك","lemma":"فُلْك","grammar_bn":"শব্দ"},{"id":30979,"position":8,"text_uthmani":"فَقُلِ","transliteration":"faquli","translation_bn":"তখন বলো","root":"قول","lemma":"قَالَ","grammar_bn":"শব্দ"},{"id":30980,"position":9,"text_uthmani":"ٱلْحَمْدُ","transliteration":"l-ḥamdu","translation_bn":"\"সব প্রশংসা","root":"حمد","lemma":"حَمْد","grammar_bn":"শব্দ"},{"id":30981,"position":10,"text_uthmani":"لِلَّهِ","transliteration":"lillahi","translation_bn":"জন্যে আল্লাহরই","root":"اله","lemma":"ٱللَّه","grammar_bn":"অব্যয় (Preposition)"},{"id":30982,"position":11,"text_uthmani":"ٱلَّذِى","transliteration":"alladhī","translation_bn":"যিনি","root":"—","lemma":"ٱلَّذِى","grammar_bn":"সাপেক্ষ সর্বনাম (Relative)"},{"id":30983,"position":12,"text_uthmani":"نَجَّىٰنَا","transliteration":"najjānā","translation_bn":"আমাদেরকে উদ্ধার করেছেন","root":"نجو","lemma":"نَجَّىٰ","grammar_bn":"ক্রিয়া (Verb)"},{"id":30984,"position":13,"text_uthmani":"مِنَ","transliteration":"mina","translation_bn":"হ''তে","root":"—","lemma":"مِن\r","grammar_bn":"অব্যয় (Preposition)"},{"id":30985,"position":14,"text_uthmani":"ٱلْقَوْمِ","transliteration":"l-qawmi","translation_bn":"জাতি","root":"قوم","lemma":"قَوْم","grammar_bn":"শব্দ"},{"id":30986,"position":15,"text_uthmani":"ٱلظَّـٰلِمِينَ","transliteration":"l-ẓālimīna","translation_bn":"সীমালঙ্ঘনকারী\"","root":"ظلم","lemma":"ظَالِم","grammar_bn":"শব্দ"},{"id":30987,"position":16,"text_uthmani":"٢٨","transliteration":"","translation_bn":"(২৮)","root":"—","lemma":"٢٨","grammar_bn":"মার্কার"}]'::jsonb, 'fa-idhā is''tawayta anta waman maʿaka ʿalā l-ful''ki faquli l-ḥamdu lillahi alladhī najjānā mina l-qawmi l-ẓālimīna', 'যখন তুমি নৌযানে উঠে যাবে, তুমি আর তোমার সঙ্গীরা- তখন বলবে : ‘সকল প্রশংসা আল্লাহরই যিনি আমাদেরকে যালিম সম্প্রদায় থেকে উদ্ধার করেছেন।’', 'And when you have boarded the ship, you and those with you, then say, ''Praise to Allah who has saved us from the wrongdoing people.''', 'যখন তুমি নৌযানে উঠে যাবে, তুমি আর তোমার সঙ্গীরা- তখন বলবে : ‘সকল প্রশংসা আল্লাহরই যিনি আমাদেরকে যালিম সম্প্রদায় থেকে উদ্ধার করেছেন।’', 'And when you have boarded the ship, you and those with you, then say, ''Praise to Allah who has saved us from the wrongdoing people.''', NULL, NULL, NULL, NULL, NULL, 'https://everyayah.com/data/Alafasy_128kbps/023028.mp3', now()),
  (23, 29, '', '[{"id":31847,"position":1,"text_uthmani":"وَقُل","transliteration":"waqul","translation_bn":"এবং বলো","root":"قول","lemma":"قَالَ","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":31848,"position":2,"text_uthmani":"رَّبِّ","transliteration":"rabbi","translation_bn":"\"হে আমার রব","root":"ربب","lemma":"رَبّ","grammar_bn":"বিশেষ্য (Noun)"},{"id":31849,"position":3,"text_uthmani":"أَنزِلْنِى","transliteration":"anzil''nī","translation_bn":"আমাকে অবতরণ করাও","root":"نزل","lemma":"أَنزَلَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":31850,"position":4,"text_uthmani":"مُنزَلًۭا","transliteration":"munzalan","translation_bn":"অবতরণস্থানে","root":"نزل","lemma":"مُنزَل","grammar_bn":"বিশেষ্য (Noun)"},{"id":31851,"position":5,"text_uthmani":"مُّبَارَكًۭا","transliteration":"mubārakan","translation_bn":"কল্যাণকর","root":"برك","lemma":"مُبَارَك","grammar_bn":"বিশেষ্য (Noun)"},{"id":31852,"position":6,"text_uthmani":"وَأَنتَ","transliteration":"wa-anta","translation_bn":"আর তুমি","root":"—","lemma":"وَأَنتَ","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":31853,"position":7,"text_uthmani":"خَيْرُ","transliteration":"khayru","translation_bn":"উত্তম","root":"خير","lemma":"خَيْر","grammar_bn":"বিশেষ্য (Noun)"},{"id":31854,"position":8,"text_uthmani":"ٱلْمُنزِلِينَ","transliteration":"l-munzilīna","translation_bn":"অবতীর্ণকারীদের (মধ্যে)\"","root":"نزل","lemma":"مُنزِلِين","grammar_bn":"শব্দ"},{"id":31855,"position":9,"text_uthmani":"٢٩","transliteration":"","translation_bn":"(২৯)","root":"—","lemma":"٢٩","grammar_bn":"মার্কার"}]'::jsonb, 'waqul rabbi anzil''nī munzalan mubārakan wa-anta khayru l-munzilīna', 'আর বলো : হে আমার প্রতিপালক! আমাকে কল্যাণকরভাবে নামিয়ে দাও, নামানোতে তুমিই সর্বোত্তম।', 'And say, ''My Lord, let me land at a blessed landing place, and You are the best to accommodate [us].'' "', 'আর বলো : হে আমার প্রতিপালক! আমাকে কল্যাণকরভাবে নামিয়ে দাও, নামানোতে তুমিই সর্বোত্তম।', 'And say, ''My Lord, let me land at a blessed landing place, and You are the best to accommodate [us].'' "', NULL, NULL, NULL, NULL, NULL, 'https://everyayah.com/data/Alafasy_128kbps/023029.mp3', now()),
  (23, 30, '', '[{"id":32636,"position":1,"text_uthmani":"إِنَّ","transliteration":"inna","translation_bn":"নিশ্চয়ই","root":"—","lemma":"إِنّ","grammar_bn":"অভিঘাত পদ (Accusative)"},{"id":32637,"position":2,"text_uthmani":"فِى","transliteration":"fī","translation_bn":"মধ্যে (রয়েছে)","root":"—","lemma":"فِى\r","grammar_bn":"অব্যয় (Preposition)"},{"id":32638,"position":3,"text_uthmani":"ذَٰلِكَ","transliteration":"dhālika","translation_bn":"এর","root":"—","lemma":"ذَٰلِك","grammar_bn":"নির্দেশক সর্বনাম (Demonstrative)"},{"id":32639,"position":4,"text_uthmani":"لَـَٔايَـٰتٍۢ","transliteration":"laāyātin","translation_bn":"অবশ্যই নিদর্শন","root":"ايي","lemma":"ءَايَة","grammar_bn":"দৃঢ়তাবোধক (Emphatic)"},{"id":32640,"position":5,"text_uthmani":"وَإِن","transliteration":"wa-in","translation_bn":"আর নিশ্চয়ই","root":"—","lemma":"إِن\r","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":32641,"position":6,"text_uthmani":"كُنَّا","transliteration":"kunnā","translation_bn":"আমরাই ছিলাম","root":"كون","lemma":"كَانَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":32642,"position":7,"text_uthmani":"لَمُبْتَلِينَ","transliteration":"lamub''talīna","translation_bn":"অবশ্যই পরীক্ষাকারী","root":"بلو","lemma":"مُبْتَلِي","grammar_bn":"দৃঢ়তাবোধক (Emphatic)"},{"id":32643,"position":8,"text_uthmani":"٣٠","transliteration":"","translation_bn":"(৩০)","root":"—","lemma":"٣٠","grammar_bn":"মার্কার"}]'::jsonb, 'inna fī dhālika laāyātin wa-in kunnā lamub''talīna', 'এতে অবশ্যই নিদর্শন রয়েছে (মানুষের বুঝার জন্য), আমি (মানুষকে) পরীক্ষা করি।', 'Indeed in that are signs, and indeed, We are ever testing [Our servants].', 'এতে অবশ্যই নিদর্শন রয়েছে (মানুষের বুঝার জন্য), আমি (মানুষকে) পরীক্ষা করি।', 'Indeed in that are signs, and indeed, We are ever testing [Our servants].', NULL, NULL, NULL, NULL, NULL, 'https://everyayah.com/data/Alafasy_128kbps/023030.mp3', now()),
  (23, 31, '', '[{"id":33509,"position":1,"text_uthmani":"ثُمَّ","transliteration":"thumma","translation_bn":"এরপর","root":"—","lemma":"ثُمّ\r","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":33510,"position":2,"text_uthmani":"أَنشَأْنَا","transliteration":"anshanā","translation_bn":"আমরা সৃষ্টি করেছি","root":"نشا","lemma":"أَنشَأَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":33511,"position":3,"text_uthmani":"مِنۢ","transliteration":"min","translation_bn":"থেকে","root":"—","lemma":"مِن\r","grammar_bn":"অব্যয় (Preposition)"},{"id":33512,"position":4,"text_uthmani":"بَعْدِهِمْ","transliteration":"baʿdihim","translation_bn":"পর তাদের","root":"بعد","lemma":"بَعْد","grammar_bn":"বিশেষ্য (Noun)"},{"id":33513,"position":5,"text_uthmani":"قَرْنًا","transliteration":"qarnan","translation_bn":"জাতি","root":"قرن","lemma":"قَرْن","grammar_bn":"বিশেষ্য (Noun)"},{"id":33514,"position":6,"text_uthmani":"ءَاخَرِينَ","transliteration":"ākharīna","translation_bn":"অন্য এক","root":"اخر","lemma":"ا^خَر","grammar_bn":"বিশেষণ (Adjective)"},{"id":33515,"position":7,"text_uthmani":"٣١","transliteration":"","translation_bn":"(৩১)","root":"—","lemma":"٣١","grammar_bn":"মার্কার"}]'::jsonb, 'thumma anshanā min baʿdihim qarnan ākharīna', 'অতঃপর তাদের পর আরেক মানব বংশ (‘আদ সম্প্রদায়কে) সৃষ্টি করেছিলাম।', 'Then We produced after them a generation of others.', 'অতঃপর তাদের পর আরেক মানব বংশ (‘আদ সম্প্রদায়কে) সৃষ্টি করেছিলাম।', 'Then We produced after them a generation of others.', NULL, NULL, NULL, NULL, NULL, 'https://everyayah.com/data/Alafasy_128kbps/023031.mp3', now()),
  (23, 32, '', '[{"id":34727,"position":1,"text_uthmani":"فَأَرْسَلْنَا","transliteration":"fa-arsalnā","translation_bn":"অতঃপর আমরা পাঠিয়েছি","root":"رسل","lemma":"أَرْسَلَ","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":34728,"position":2,"text_uthmani":"فِيهِمْ","transliteration":"fīhim","translation_bn":"তাদের মধ্যে","root":"—","lemma":"فِى\r","grammar_bn":"অব্যয় (Preposition)"},{"id":34729,"position":3,"text_uthmani":"رَسُولًۭا","transliteration":"rasūlan","translation_bn":"একজনকে রাসূলরূপে","root":"رسل","lemma":"رَسُول","grammar_bn":"বিশেষ্য (Noun)"},{"id":34730,"position":4,"text_uthmani":"مِّنْهُمْ","transliteration":"min''hum","translation_bn":"তাদেরই মধ্য হ''তে","root":"—","lemma":"مِن\r","grammar_bn":"অব্যয় (Preposition)"},{"id":34731,"position":5,"text_uthmani":"أَنِ","transliteration":"ani","translation_bn":"(তার দাওয়াত এ ছিলো) যে","root":"—","lemma":"أَن\r","grammar_bn":"উদ্দেশ্যবাচক (Intention)"},{"id":34732,"position":6,"text_uthmani":"ٱعْبُدُوا۟","transliteration":"uʿ''budū","translation_bn":"\"তোমরা ইবাদাত করো","root":"عبد","lemma":"عَبَدَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":34733,"position":7,"text_uthmani":"ٱللَّهَ","transliteration":"l-laha","translation_bn":"আল্লাহর","root":"اله","lemma":"ٱللَّه","grammar_bn":"নামবাচক বিশেষ্য (Proper Noun)"},{"id":34734,"position":8,"text_uthmani":"مَا","transliteration":"mā","translation_bn":"নেই","root":"—","lemma":"مَا\r","grammar_bn":"না-বোধক (Negative)"},{"id":34735,"position":9,"text_uthmani":"لَكُم","transliteration":"lakum","translation_bn":"জন্যে তোমাদের","root":"—","lemma":"لَكُم","grammar_bn":"অব্যয় (Preposition)"},{"id":34736,"position":10,"text_uthmani":"مِّنْ","transliteration":"min","translation_bn":"কোন","root":"—","lemma":"مِن\r","grammar_bn":"অব্যয় (Preposition)"},{"id":34737,"position":11,"text_uthmani":"إِلَـٰهٍ","transliteration":"ilāhin","translation_bn":"ইলাহ","root":"اله","lemma":"إِلَٰه","grammar_bn":"বিশেষ্য (Noun)"},{"id":34738,"position":12,"text_uthmani":"غَيْرُهُۥٓ ۖ","transliteration":"ghayruhu","translation_bn":"তিনি ছাড়া","root":"غير","lemma":"غَيْر","grammar_bn":"বিশেষ্য (Noun)"},{"id":34740,"position":13,"text_uthmani":"أَفَلَا","transliteration":"afalā","translation_bn":"কি তবুও না","root":"—","lemma":"لَا\r","grammar_bn":"প্রশ্নবোধক (Interrogative)"},{"id":34741,"position":14,"text_uthmani":"تَتَّقُونَ","transliteration":"tattaqūna","translation_bn":"তোমরা সাবধান হবে\"","root":"وقي","lemma":"ٱتَّقَىٰ","grammar_bn":"ক্রিয়া (Verb)"},{"id":34742,"position":15,"text_uthmani":"٣٢","transliteration":"","translation_bn":"(৩২)","root":"—","lemma":"٣٢","grammar_bn":"মার্কার"}]'::jsonb, 'fa-arsalnā fīhim rasūlan min''hum ani uʿ''budū l-laha mā lakum min ilāhin ghayruhu afalā tattaqūna', 'আর তাদের মাঝে তাদেরই একজনকে রসূল করে পাঠিয়েছিলাম এই বলে যে, তোমরা আল্লাহর ‘ইবাদাত কর, তিনি ছাড়া তোমাদের কোন ইলাহ নেই, তবুও কি তোমরা (তাঁকে) ভয় করবে না?', 'And We sent among them a messenger from themselves, [saying], "Worship Allah; you have no deity other than Him; then will you not fear Him?"', 'আর তাদের মাঝে তাদেরই একজনকে রসূল করে পাঠিয়েছিলাম এই বলে যে, তোমরা আল্লাহর ‘ইবাদাত কর, তিনি ছাড়া তোমাদের কোন ইলাহ নেই, তবুও কি তোমরা (তাঁকে) ভয় করবে না?', 'And We sent among them a messenger from themselves, [saying], "Worship Allah; you have no deity other than Him; then will you not fear Him?"', NULL, NULL, NULL, NULL, NULL, 'https://everyayah.com/data/Alafasy_128kbps/023032.mp3', now()),
  (23, 33, '', '[{"id":35275,"position":1,"text_uthmani":"وَقَالَ","transliteration":"waqāla","translation_bn":"এবং বলেছিলো","root":"قول","lemma":"قَالَ","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":35276,"position":2,"text_uthmani":"ٱلْمَلَأُ","transliteration":"l-mala-u","translation_bn":"প্রধান ব্যক্তিরা","root":"ملا","lemma":"مَلَأ","grammar_bn":"শব্দ"},{"id":35277,"position":3,"text_uthmani":"مِن","transliteration":"min","translation_bn":"মধ্য হ''তে","root":"—","lemma":"مِن\r","grammar_bn":"অব্যয় (Preposition)"},{"id":35278,"position":4,"text_uthmani":"قَوْمِهِ","transliteration":"qawmihi","translation_bn":"তার জাতির","root":"قوم","lemma":"قَوْم","grammar_bn":"বিশেষ্য (Noun)"},{"id":35279,"position":5,"text_uthmani":"ٱلَّذِينَ","transliteration":"alladhīna","translation_bn":"যারা","root":"—","lemma":"ٱلَّذِى","grammar_bn":"সাপেক্ষ সর্বনাম (Relative)"},{"id":35280,"position":6,"text_uthmani":"كَفَرُوا۟","transliteration":"kafarū","translation_bn":"অস্বীকার করেছিলো","root":"كفر","lemma":"كَفَرَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":35281,"position":7,"text_uthmani":"وَكَذَّبُوا۟","transliteration":"wakadhabū","translation_bn":"ও মিথ্যারোপ করেছিলো","root":"كذب","lemma":"كَذَّبَ","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":35282,"position":8,"text_uthmani":"بِلِقَآءِ","transliteration":"biliqāi","translation_bn":"প্রতি সাক্ষাতের","root":"لقي","lemma":"لِقَا^ء","grammar_bn":"অব্যয় (Preposition)"},{"id":35283,"position":9,"text_uthmani":"ٱلْـَٔاخِرَةِ","transliteration":"l-ākhirati","translation_bn":"পরকালের","root":"اخر","lemma":"ا^خِر","grammar_bn":"শব্দ"},{"id":35284,"position":10,"text_uthmani":"وَأَتْرَفْنَـٰهُمْ","transliteration":"wa-atrafnāhum","translation_bn":"এবং তাদেরকে আমরা স্বাচ্ছন্দ্য দিয়েছিলাম","root":"ترف","lemma":"أُتْرِفُ","grammar_bn":"অবস্থাবাচক (Circumstantial)"},{"id":35285,"position":11,"text_uthmani":"فِى","transliteration":"fī","translation_bn":"মধ্যে","root":"—","lemma":"فِى\r","grammar_bn":"অব্যয় (Preposition)"},{"id":35286,"position":12,"text_uthmani":"ٱلْحَيَوٰةِ","transliteration":"l-ḥayati","translation_bn":"জীবনের","root":"حيي","lemma":"حَيَوٰة","grammar_bn":"শব্দ"},{"id":35287,"position":13,"text_uthmani":"ٱلدُّنْيَا","transliteration":"l-dun''yā","translation_bn":"দুনিয়ার","root":"دنو","lemma":"دُّنْيَا","grammar_bn":"শব্দ"},{"id":35288,"position":14,"text_uthmani":"مَا","transliteration":"mā","translation_bn":"\"নয়","root":"—","lemma":"مَا\r","grammar_bn":"না-বোধক (Negative)"},{"id":35289,"position":15,"text_uthmani":"هَـٰذَآ","transliteration":"hādhā","translation_bn":"সে","root":"—","lemma":"هَٰذَا","grammar_bn":"নির্দেশক সর্বনাম (Demonstrative)"},{"id":35290,"position":16,"text_uthmani":"إِلَّا","transliteration":"illā","translation_bn":"এ ছাড়া","root":"—","lemma":"إِلَّا\r","grammar_bn":"সীমাবদ্ধতা (Restriction)"},{"id":35291,"position":17,"text_uthmani":"بَشَرٌۭ","transliteration":"basharun","translation_bn":"একজন মানুষ","root":"بشر","lemma":"بَشَر","grammar_bn":"বিশেষ্য (Noun)"},{"id":35292,"position":18,"text_uthmani":"مِّثْلُكُمْ","transliteration":"mith''lukum","translation_bn":"তোমাদেরই মতো","root":"مثل","lemma":"مِثْل","grammar_bn":"বিশেষ্য (Noun)"},{"id":35293,"position":19,"text_uthmani":"يَأْكُلُ","transliteration":"yakulu","translation_bn":"সে খায়","root":"اكل","lemma":"أَكَلَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":35294,"position":20,"text_uthmani":"مِمَّا","transliteration":"mimmā","translation_bn":"তা হ''তে","root":"—","lemma":"مِن\r","grammar_bn":"অব্যয় (Preposition)"},{"id":35295,"position":21,"text_uthmani":"تَأْكُلُونَ","transliteration":"takulūna","translation_bn":"তোমরা খাও","root":"اكل","lemma":"أَكَلَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":35296,"position":22,"text_uthmani":"مِنْهُ","transliteration":"min''hu","translation_bn":"যা হ''তে","root":"—","lemma":"مِن\r","grammar_bn":"অব্যয় (Preposition)"},{"id":35297,"position":23,"text_uthmani":"وَيَشْرَبُ","transliteration":"wayashrabu","translation_bn":"এবং পান করে","root":"شرب","lemma":"شَرِبَ","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":35298,"position":24,"text_uthmani":"مِمَّا","transliteration":"mimmā","translation_bn":"তা হ''তে যা","root":"—","lemma":"مِن\r","grammar_bn":"অব্যয় (Preposition)"},{"id":35299,"position":25,"text_uthmani":"تَشْرَبُونَ","transliteration":"tashrabūna","translation_bn":"তোমরা পান করো","root":"شرب","lemma":"شَرِبَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":35300,"position":26,"text_uthmani":"٣٣","transliteration":"","translation_bn":"(৩৩)","root":"—","lemma":"٣٣","grammar_bn":"মার্কার"}]'::jsonb, 'waqāla l-mala-u min qawmihi alladhīna kafarū wakadhabū biliqāi l-ākhirati wa-atrafnāhum fī l-ḥayati l-dun''yā mā hādhā illā basharun mith''lukum yakulu mimmā takulūna min''hu wayashrabu mimmā tashrabūna', 'কিন্তু তার সম্প্রদায়ের প্রধানগণ- যারা কুফুরী করেছিল, আর আখিরাতের সাক্ষাৎকে মিথ্যা বলে প্রত্যাখ্যান করেছিল, যাদেরকে আমি পার্থিব জীবনে সুখ স্বাচ্ছন্দ্য দিয়েছিলাম- বলেছিল : ‘সে তো তোমাদের মত মানুষ ছাড়া কিছু নয়। তোমরা যা খাও, সেও তাই খায়, তোমরা যা পান কর, সেও তাই পান করে।', 'And the eminent among his people who disbelieved and denied the meeting of the Hereafter while We had given them luxury in the worldly life said, "This is not but a man like yourselves. He eats of that from which you eat and drinks of what you drink.', 'কিন্তু তার সম্প্রদায়ের প্রধানগণ- যারা কুফুরী করেছিল, আর আখিরাতের সাক্ষাৎকে মিথ্যা বলে প্রত্যাখ্যান করেছিল, যাদেরকে আমি পার্থিব জীবনে সুখ স্বাচ্ছন্দ্য দিয়েছিলাম- বলেছিল : ‘সে তো তোমাদের মত মানুষ ছাড়া কিছু নয়। তোমরা যা খাও, সেও তাই খায়, তোমরা যা পান কর, সেও তাই পান করে।', 'And the eminent among his people who disbelieved and denied the meeting of the Hereafter while We had given them luxury in the worldly life said, "This is not but a man like yourselves. He eats of that from which you eat and drinks of what you drink.', NULL, NULL, NULL, NULL, NULL, 'https://everyayah.com/data/Alafasy_128kbps/023033.mp3', now()),
  (23, 34, '', '[{"id":36267,"position":1,"text_uthmani":"وَلَئِنْ","transliteration":"wala-in","translation_bn":"আর অবশ্যই যদি","root":"—","lemma":"إِن\r","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":36268,"position":2,"text_uthmani":"أَطَعْتُم","transliteration":"aṭaʿtum","translation_bn":"তোমরা আনুগত্য করো","root":"طوع","lemma":"أَطَاعَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":36269,"position":3,"text_uthmani":"بَشَرًۭا","transliteration":"basharan","translation_bn":"একজন মানুষের","root":"بشر","lemma":"بَشَر","grammar_bn":"বিশেষ্য (Noun)"},{"id":36270,"position":4,"text_uthmani":"مِّثْلَكُمْ","transliteration":"mith''lakum","translation_bn":"তোমাদের মতো","root":"مثل","lemma":"مِثْل","grammar_bn":"বিশেষ্য (Noun)"},{"id":36271,"position":5,"text_uthmani":"إِنَّكُمْ","transliteration":"innakum","translation_bn":"নিশ্চয়ই তোমরা","root":"—","lemma":"إِنّ","grammar_bn":"অভিঘাত পদ (Accusative)"},{"id":36272,"position":6,"text_uthmani":"إِذًۭا","transliteration":"idhan","translation_bn":"তাহ''লে","root":"—","lemma":"إِذًا\r","grammar_bn":"আশ্চর্যসূচক (Surprise)"},{"id":36273,"position":7,"text_uthmani":"لَّخَـٰسِرُونَ","transliteration":"lakhāsirūna","translation_bn":"ক্ষতিগ্রস্ত হবে","root":"خسر","lemma":"خَٰسِرِين","grammar_bn":"দৃঢ়তাবোধক (Emphatic)"},{"id":36274,"position":8,"text_uthmani":"٣٤","transliteration":"","translation_bn":"(৩৪)","root":"—","lemma":"٣٤","grammar_bn":"মার্কার"}]'::jsonb, 'wala-in aṭaʿtum basharan mith''lakum innakum idhan lakhāsirūna', 'তোমরা যদি তোমাদের মতই একজন মানুষের আনুগত্য কর, তাহলে তোমরা অবশ্যই ক্ষতিগ্রস্ত হবে।', 'And if you should obey a man like yourselves, indeed, you would then be losers.', 'তোমরা যদি তোমাদের মতই একজন মানুষের আনুগত্য কর, তাহলে তোমরা অবশ্যই ক্ষতিগ্রস্ত হবে।', 'And if you should obey a man like yourselves, indeed, you would then be losers.', NULL, NULL, NULL, NULL, NULL, 'https://everyayah.com/data/Alafasy_128kbps/023034.mp3', now()),
  (23, 35, '', '[{"id":37340,"position":1,"text_uthmani":"أَيَعِدُكُمْ","transliteration":"ayaʿidukum","translation_bn":"কি তোমাদেরকে প্রতিশ্রুতি দেয়","root":"وعد","lemma":"وَعَدَ","grammar_bn":"প্রশ্নবোধক (Interrogative)"},{"id":37341,"position":2,"text_uthmani":"أَنَّكُمْ","transliteration":"annakum","translation_bn":"যে তোমরা","root":"—","lemma":"أَنّ","grammar_bn":"অভিঘাত পদ (Accusative)"},{"id":37342,"position":3,"text_uthmani":"إِذَا","transliteration":"idhā","translation_bn":"যখন","root":"—","lemma":"إِذَا\r","grammar_bn":"কালবাচক (Time)"},{"id":37343,"position":4,"text_uthmani":"مِتُّمْ","transliteration":"mittum","translation_bn":"মরে যাবে","root":"موت","lemma":"مَّاتَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":37344,"position":5,"text_uthmani":"وَكُنتُمْ","transliteration":"wakuntum","translation_bn":"ও তোমরা হবে","root":"كون","lemma":"كَانَ","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":37345,"position":6,"text_uthmani":"تُرَابًۭا","transliteration":"turāban","translation_bn":"মাটি","root":"ترب","lemma":"تُرَاب","grammar_bn":"বিশেষ্য (Noun)"},{"id":37346,"position":7,"text_uthmani":"وَعِظَـٰمًا","transliteration":"waʿiẓāman","translation_bn":"ও হাড়","root":"عظم","lemma":"عَظِيم","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":37347,"position":8,"text_uthmani":"أَنَّكُم","transliteration":"annakum","translation_bn":"নিশ্চয়ই তোমরা","root":"—","lemma":"أَنّ","grammar_bn":"অভিঘাত পদ (Accusative)"},{"id":37348,"position":9,"text_uthmani":"مُّخْرَجُونَ","transliteration":"mukh''rajūna","translation_bn":"(কবর হ''তে) তোমাদেরকে বের করা হবে","root":"خرج","lemma":"مُخْرَج","grammar_bn":"বিশেষ্য (Noun)"},{"id":37349,"position":10,"text_uthmani":"٣٥","transliteration":"","translation_bn":"(৩৫)","root":"—","lemma":"٣٥","grammar_bn":"মার্কার"}]'::jsonb, 'ayaʿidukum annakum idhā mittum wakuntum turāban waʿiẓāman annakum mukh''rajūna', 'সে কি তোমাদের সঙ্গে এই ওয়া‘দা করে যে, যখন তোমরা মরে যাবে আর মাটি ও হাড্ডিতে পরিণত হবে তখন তোমাদেরকে আবার জীবিত করা হবে।', 'Does he promise you that when you have died and become dust and bones that you will be brought forth [once more]?', 'সে কি তোমাদের সঙ্গে এই ওয়া‘দা করে যে, যখন তোমরা মরে যাবে আর মাটি ও হাড্ডিতে পরিণত হবে তখন তোমাদেরকে আবার জীবিত করা হবে।', 'Does he promise you that when you have died and become dust and bones that you will be brought forth [once more]?', NULL, NULL, NULL, NULL, NULL, 'https://everyayah.com/data/Alafasy_128kbps/023035.mp3', now()),
  (23, 36, '', '[{"id":37875,"position":1,"text_uthmani":"۞ هَيْهَاتَ","transliteration":"hayhāta","translation_bn":"(অসম্ভব) দূরে","root":"—","lemma":"هَيْهَات","grammar_bn":"বিশেষ্য (Noun)"},{"id":37876,"position":2,"text_uthmani":"هَيْهَاتَ","transliteration":"hayhāta","translation_bn":"(অসম্ভব) বহুদূরে","root":"—","lemma":"هَيْهَات","grammar_bn":"বিশেষ্য (Noun)"},{"id":37877,"position":3,"text_uthmani":"لِمَا","transliteration":"limā","translation_bn":"বিষয়ে যার","root":"—","lemma":"مَا\r","grammar_bn":"অব্যয় (Preposition)"},{"id":37878,"position":4,"text_uthmani":"تُوعَدُونَ","transliteration":"tūʿadūna","translation_bn":"তোমাদের প্রতিশ্রুতি দেয়া হচ্ছে","root":"وعد","lemma":"وَعَدَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":37879,"position":5,"text_uthmani":"٣٦","transliteration":"","translation_bn":"(৩৬)","root":"—","lemma":"٣٦","grammar_bn":"মার্কার"}]'::jsonb, 'hayhāta hayhāta limā tūʿadūna', 'দূরে ওটা, বহু দূরে যার ওয়া‘দা তোমাদেরকে দেয়া হচ্ছে।', 'How far, how far, is that which you are promised.', 'দূরে ওটা, বহু দূরে যার ওয়া‘দা তোমাদেরকে দেয়া হচ্ছে।', 'How far, how far, is that which you are promised.', NULL, NULL, NULL, NULL, NULL, 'https://everyayah.com/data/Alafasy_128kbps/023036.mp3', now()),
  (23, 37, '', '[{"id":38960,"position":1,"text_uthmani":"إِنْ","transliteration":"in","translation_bn":"না","root":"—","lemma":"إِن\r","grammar_bn":"না-বোধক (Negative)"},{"id":38961,"position":2,"text_uthmani":"هِىَ","transliteration":"hiya","translation_bn":"তা","root":"—","lemma":"هِىَ","grammar_bn":"সর্বনাম (Pronoun)"},{"id":38962,"position":3,"text_uthmani":"إِلَّا","transliteration":"illā","translation_bn":"এ ছাড়া যে","root":"—","lemma":"إِلَّا\r","grammar_bn":"সীমাবদ্ধতা (Restriction)"},{"id":38963,"position":4,"text_uthmani":"حَيَاتُنَا","transliteration":"ḥayātunā","translation_bn":"আমাদের জীবন","root":"حيي","lemma":"حَيَوٰة","grammar_bn":"বিশেষ্য (Noun)"},{"id":38964,"position":5,"text_uthmani":"ٱلدُّنْيَا","transliteration":"l-dun''yā","translation_bn":"দুুনিয়ারই","root":"دنو","lemma":"دُّنْيَا","grammar_bn":"শব্দ"},{"id":38965,"position":6,"text_uthmani":"نَمُوتُ","transliteration":"namūtu","translation_bn":"(শুধু এখানেই) আমরা মরি","root":"موت","lemma":"مَّاتَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":38966,"position":7,"text_uthmani":"وَنَحْيَا","transliteration":"wanaḥyā","translation_bn":"ও আমরা বাঁচি","root":"حيي","lemma":"حَىَّ","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":38967,"position":8,"text_uthmani":"وَمَا","transliteration":"wamā","translation_bn":"এবং না","root":"—","lemma":"مَا\r","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":38968,"position":9,"text_uthmani":"نَحْنُ","transliteration":"naḥnu","translation_bn":"আমরা","root":"—","lemma":"نَحْنُ","grammar_bn":"সর্বনাম (Pronoun)"},{"id":38969,"position":10,"text_uthmani":"بِمَبْعُوثِينَ","transliteration":"bimabʿūthīna","translation_bn":"উত্থিত হবো","root":"بعث","lemma":"مَّبْعُوثُون","grammar_bn":"অব্যয় (Preposition)"},{"id":38970,"position":11,"text_uthmani":"٣٧","transliteration":"","translation_bn":"(৩৭)","root":"—","lemma":"٣٧","grammar_bn":"মার্কার"}]'::jsonb, 'in hiya illā ḥayātunā l-dun''yā namūtu wanaḥyā wamā naḥnu bimabʿūthīna', 'আমাদের এ দুনিয়ার জীবন ছাড়া কিছুই নেই, এখানেই আমরা মরি বাঁচি, আমাদেরকে কক্ষনো আবার উঠানো হবে না।', 'Life is not but our worldly life - we die and live, but we will not be resurrected.', 'আমাদের এ দুনিয়ার জীবন ছাড়া কিছুই নেই, এখানেই আমরা মরি বাঁচি, আমাদেরকে কক্ষনো আবার উঠানো হবে না।', 'Life is not but our worldly life - we die and live, but we will not be resurrected.', NULL, NULL, NULL, NULL, NULL, 'https://everyayah.com/data/Alafasy_128kbps/023037.mp3', now()),
  (23, 38, '', '[{"id":39826,"position":1,"text_uthmani":"إِنْ","transliteration":"in","translation_bn":"নয়","root":"—","lemma":"إِن\r","grammar_bn":"না-বোধক (Negative)"},{"id":39827,"position":2,"text_uthmani":"هُوَ","transliteration":"huwa","translation_bn":"সে","root":"—","lemma":"هُوَ","grammar_bn":"সর্বনাম (Pronoun)"},{"id":39828,"position":3,"text_uthmani":"إِلَّا","transliteration":"illā","translation_bn":"এ ছাড়া","root":"—","lemma":"إِلَّا\r","grammar_bn":"সীমাবদ্ধতা (Restriction)"},{"id":39829,"position":4,"text_uthmani":"رَجُلٌ","transliteration":"rajulun","translation_bn":"এক ব্যক্তি","root":"رجل","lemma":"رَجُل","grammar_bn":"বিশেষ্য (Noun)"},{"id":39830,"position":5,"text_uthmani":"ٱفْتَرَىٰ","transliteration":"if''tarā","translation_bn":"রচনা করেছে","root":"فري","lemma":"ٱفْتَرَىٰ","grammar_bn":"ক্রিয়া (Verb)"},{"id":39831,"position":6,"text_uthmani":"عَلَى","transliteration":"ʿalā","translation_bn":"সম্পর্কে","root":"—","lemma":"عَلَىٰ\r","grammar_bn":"অব্যয় (Preposition)"},{"id":39832,"position":7,"text_uthmani":"ٱللَّهِ","transliteration":"l-lahi","translation_bn":"আল্লাহ","root":"اله","lemma":"ٱللَّه","grammar_bn":"নামবাচক বিশেষ্য (Proper Noun)"},{"id":39833,"position":8,"text_uthmani":"كَذِبًۭا","transliteration":"kadhiban","translation_bn":"মিথ্যা","root":"كذب","lemma":"كَذِب","grammar_bn":"বিশেষ্য (Noun)"},{"id":39834,"position":9,"text_uthmani":"وَمَا","transliteration":"wamā","translation_bn":"আর নই","root":"—","lemma":"مَا\r","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":39835,"position":10,"text_uthmani":"نَحْنُ","transliteration":"naḥnu","translation_bn":"আমরা","root":"—","lemma":"نَحْنُ","grammar_bn":"সর্বনাম (Pronoun)"},{"id":39836,"position":11,"text_uthmani":"لَهُۥ","transliteration":"lahu","translation_bn":"উপর তার","root":"—","lemma":"لَهُۥ","grammar_bn":"অব্যয় (Preposition)"},{"id":39837,"position":12,"text_uthmani":"بِمُؤْمِنِينَ","transliteration":"bimu''minīna","translation_bn":"মু''মিন\"","root":"امن","lemma":"مُؤْمِن","grammar_bn":"অব্যয় (Preposition)"},{"id":39838,"position":13,"text_uthmani":"٣٨","transliteration":"","translation_bn":"(৩৮)","root":"—","lemma":"٣٨","grammar_bn":"মার্কার"}]'::jsonb, 'in huwa illā rajulun if''tarā ʿalā l-lahi kadhiban wamā naḥnu lahu bimu''minīna', 'সে তো এমন এক ব্যক্তি যে আল্লাহ সম্পর্কে মিথ্যে বানিয়ে নিয়েছে। আমরা তাকে বিশ্বাস করি না।’', 'He is not but a man who has invented a lie about Allah, and we will not believe him."', 'সে তো এমন এক ব্যক্তি যে আল্লাহ সম্পর্কে মিথ্যে বানিয়ে নিয়েছে। আমরা তাকে বিশ্বাস করি না।’', 'He is not but a man who has invented a lie about Allah, and we will not believe him."', NULL, NULL, NULL, NULL, NULL, 'https://everyayah.com/data/Alafasy_128kbps/023038.mp3', now()),
  (23, 39, '', '[{"id":40960,"position":1,"text_uthmani":"قَالَ","transliteration":"qāla","translation_bn":"(রাসূল) বলল","root":"قول","lemma":"قَالَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":40961,"position":2,"text_uthmani":"رَبِّ","transliteration":"rabbi","translation_bn":"\"হে আমার রব","root":"ربب","lemma":"رَبّ","grammar_bn":"বিশেষ্য (Noun)"},{"id":40962,"position":3,"text_uthmani":"ٱنصُرْنِى","transliteration":"unṣur''nī","translation_bn":"আমাকে সাহায্য করো","root":"نصر","lemma":"نَصَرَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":40963,"position":4,"text_uthmani":"بِمَا","transliteration":"bimā","translation_bn":"এ কারণে যে","root":"—","lemma":"مَا\r","grammar_bn":"অব্যয় (Preposition)"},{"id":40964,"position":5,"text_uthmani":"كَذَّبُونِ","transliteration":"kadhabūni","translation_bn":"আমার উপর তারা মিথ্যারোপ করেছে\"","root":"كذب","lemma":"كَذَّبَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":40965,"position":6,"text_uthmani":"٣٩","transliteration":"","translation_bn":"(৩৯)","root":"—","lemma":"٣٩","grammar_bn":"মার্কার"}]'::jsonb, 'qāla rabbi unṣur''nī bimā kadhabūni', '(নবী) বলল : ‘হে আমার প্রতিপালক! তারা আমাকে মিথ্যেবাদী বলে দোষারোপ করছে- এ ব্যাপারে তুমি আমাকে সাহায্য কর।’', 'He said, "My Lord, support me because they have denied me."', '(নবী) বলল : ‘হে আমার প্রতিপালক! তারা আমাকে মিথ্যেবাদী বলে দোষারোপ করছে- এ ব্যাপারে তুমি আমাকে সাহায্য কর।’', 'He said, "My Lord, support me because they have denied me."', NULL, NULL, NULL, NULL, NULL, 'https://everyayah.com/data/Alafasy_128kbps/023039.mp3', now()),
  (23, 40, '', '[{"id":41401,"position":1,"text_uthmani":"قَالَ","transliteration":"qāla","translation_bn":"(আল্লাহ) বললেন","root":"قول","lemma":"قَالَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":41402,"position":2,"text_uthmani":"عَمَّا","transliteration":"ʿammā","translation_bn":"\"হ''তে ঐবিষয়","root":"—","lemma":"عَن\r","grammar_bn":"অব্যয় (Preposition)"},{"id":41403,"position":3,"text_uthmani":"قَلِيلٍۢ","transliteration":"qalīlin","translation_bn":"\"অল্প পরে (অচিরেই)","root":"قلل","lemma":"قَلِيل","grammar_bn":"বিশেষ্য (Noun)"},{"id":41404,"position":4,"text_uthmani":"لَّيُصْبِحُنَّ","transliteration":"layuṣ''biḥunna","translation_bn":"অবশ্যই তারা হবে","root":"صبح","lemma":"أَصْبَحَ","grammar_bn":"দৃঢ়তাবোধক (Emphatic)"},{"id":41405,"position":5,"text_uthmani":"نَـٰدِمِينَ","transliteration":"nādimīna","translation_bn":"অনুতপ্ত\"","root":"ندم","lemma":"نَٰدِمِين","grammar_bn":"বিশেষ্য (Noun)"},{"id":41406,"position":6,"text_uthmani":"٤٠","transliteration":"","translation_bn":"(৪০)","root":"—","lemma":"٤٠","grammar_bn":"মার্কার"}]'::jsonb, 'qāla ʿammā qalīlin layuṣ''biḥunna nādimīna', 'আল্লাহ বললেন, ‘অল্প সময়ের মধ্যেই তারা অনুতপ্ত হবে।’', '[Allah] said, "After a little, they will surely become regretful."', 'আল্লাহ বললেন, ‘অল্প সময়ের মধ্যেই তারা অনুতপ্ত হবে।’', '[Allah] said, "After a little, they will surely become regretful."', NULL, NULL, NULL, NULL, NULL, 'https://everyayah.com/data/Alafasy_128kbps/023040.mp3', now()),
  (23, 41, '', '[{"id":42216,"position":1,"text_uthmani":"فَأَخَذَتْهُمُ","transliteration":"fa-akhadhathumu","translation_bn":"অতঃপর তাদেরকে ধরলো","root":"اخذ","lemma":"أَخَذَ","grammar_bn":"শব্দ"},{"id":42217,"position":2,"text_uthmani":"ٱلصَّيْحَةُ","transliteration":"l-ṣayḥatu","translation_bn":"এক মহাগর্জন","root":"صيح","lemma":"صَيْحَة","grammar_bn":"শব্দ"},{"id":42218,"position":3,"text_uthmani":"بِٱلْحَقِّ","transliteration":"bil-ḥaqi","translation_bn":"সাথে ন্যায়ের","root":"حقق","lemma":"حَقّ","grammar_bn":"অব্যয় (Preposition)"},{"id":42219,"position":4,"text_uthmani":"فَجَعَلْنَـٰهُمْ","transliteration":"fajaʿalnāhum","translation_bn":"অতঃপর তাদেরকে আমরা করেছিলাম","root":"جعل","lemma":"جَعَلَ","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":42220,"position":5,"text_uthmani":"غُثَآءًۭ ۚ","transliteration":"ghuthāan","translation_bn":"ঢেউ তাড়িত আবর্জনার (মতো)","root":"غثو","lemma":"غُثَا^ء","grammar_bn":"বিশেষ্য (Noun)"},{"id":42222,"position":6,"text_uthmani":"فَبُعْدًۭا","transliteration":"fabuʿ''dan","translation_bn":"সুতরাং দূর হোক (অর্থাৎ ধ্বংস আসুক)","root":"بعد","lemma":"بُعْد","grammar_bn":"শব্দ"},{"id":42223,"position":7,"text_uthmani":"لِّلْقَوْمِ","transliteration":"lil''qawmi","translation_bn":"জন্যে (এমন) জাতির","root":"قوم","lemma":"قَوْم","grammar_bn":"অব্যয় (Preposition)"},{"id":42224,"position":8,"text_uthmani":"ٱلظَّـٰلِمِينَ","transliteration":"l-ẓālimīna","translation_bn":"(যারা) সীমালঙ্ঘনকারী","root":"ظلم","lemma":"ظَالِم","grammar_bn":"শব্দ"},{"id":42225,"position":9,"text_uthmani":"٤١","transliteration":"","translation_bn":"(৪১)","root":"—","lemma":"٤١","grammar_bn":"মার্কার"}]'::jsonb, 'fa-akhadhathumu l-ṣayḥatu bil-ḥaqi fajaʿalnāhum ghuthāan fabuʿ''dan lil''qawmi l-ẓālimīna', 'অতঃপর সত্যি সত্যিই এক ভয়ঙ্কর শব্দ তাদেরকে আঘাত করল আর তাদেরকে ভাগাড়ে পরিণত করলাম, কাজেই ধ্বংস হোক পাপী সম্প্রদায়।', 'So the shriek seized them in truth, and We made them as [plant] stubble. Then away with the wrongdoing people.', 'অতঃপর সত্যি সত্যিই এক ভয়ঙ্কর শব্দ তাদেরকে আঘাত করল আর তাদেরকে ভাগাড়ে পরিণত করলাম, কাজেই ধ্বংস হোক পাপী সম্প্রদায়।', 'So the shriek seized them in truth, and We made them as [plant] stubble. Then away with the wrongdoing people.', NULL, NULL, NULL, NULL, NULL, 'https://everyayah.com/data/Alafasy_128kbps/023041.mp3', now()),
  (23, 42, '', '[{"id":43340,"position":1,"text_uthmani":"ثُمَّ","transliteration":"thumma","translation_bn":"এরপর","root":"—","lemma":"ثُمّ\r","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":43341,"position":2,"text_uthmani":"أَنشَأْنَا","transliteration":"anshanā","translation_bn":"আমরা সৃষ্টি করলাম","root":"نشا","lemma":"أَنشَأَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":43342,"position":3,"text_uthmani":"مِنۢ","transliteration":"min","translation_bn":"থেকে","root":"—","lemma":"مِن\r","grammar_bn":"অব্যয় (Preposition)"},{"id":43343,"position":4,"text_uthmani":"بَعْدِهِمْ","transliteration":"baʿdihim","translation_bn":"পর তাদের","root":"بعد","lemma":"بَعْد","grammar_bn":"বিশেষ্য (Noun)"},{"id":43344,"position":5,"text_uthmani":"قُرُونًا","transliteration":"qurūnan","translation_bn":"(বহু) জাতি","root":"قرن","lemma":"قَرْن","grammar_bn":"বিশেষ্য (Noun)"},{"id":43345,"position":6,"text_uthmani":"ءَاخَرِينَ","transliteration":"ākharīna","translation_bn":"অন্যান্য","root":"اخر","lemma":"ا^خَر","grammar_bn":"বিশেষণ (Adjective)"},{"id":43346,"position":7,"text_uthmani":"٤٢","transliteration":"","translation_bn":"(৪২)","root":"—","lemma":"٤٢","grammar_bn":"মার্কার"}]'::jsonb, 'thumma anshanā min baʿdihim qurūnan ākharīna', 'অতঃপর তাদের পরে আমি বহু জাতি সৃষ্টি করেছিলাম।', 'Then We produced after them other generations.', 'অতঃপর তাদের পরে আমি বহু জাতি সৃষ্টি করেছিলাম।', 'Then We produced after them other generations.', NULL, NULL, NULL, NULL, NULL, 'https://everyayah.com/data/Alafasy_128kbps/023042.mp3', now()),
  (23, 43, '', '[{"id":43715,"position":1,"text_uthmani":"مَا","transliteration":"mā","translation_bn":"না","root":"—","lemma":"مَا\r","grammar_bn":"না-বোধক (Negative)"},{"id":43716,"position":2,"text_uthmani":"تَسْبِقُ","transliteration":"tasbiqu","translation_bn":"তাড়াতাড়ি এগিয়ে আনতে পারে","root":"سبق","lemma":"سَبَقَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":43717,"position":3,"text_uthmani":"مِنْ","transliteration":"min","translation_bn":"কোন","root":"—","lemma":"مِن\r","grammar_bn":"অব্যয় (Preposition)"},{"id":43718,"position":4,"text_uthmani":"أُمَّةٍ","transliteration":"ummatin","translation_bn":"জাতি","root":"امم","lemma":"أُمَّة","grammar_bn":"বিশেষ্য (Noun)"},{"id":43719,"position":5,"text_uthmani":"أَجَلَهَا","transliteration":"ajalahā","translation_bn":"তার নির্ধারিত সময়","root":"اجل","lemma":"أَجَل","grammar_bn":"বিশেষ্য (Noun)"},{"id":43720,"position":6,"text_uthmani":"وَمَا","transliteration":"wamā","translation_bn":"আর না","root":"—","lemma":"مَا\r","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":43721,"position":7,"text_uthmani":"يَسْتَـْٔخِرُونَ","transliteration":"yastakhirūna","translation_bn":"দেরি করতে পারে","root":"اخر","lemma":"يَسْتَأْخِرُ","grammar_bn":"ক্রিয়া (Verb)"},{"id":43722,"position":8,"text_uthmani":"٤٣","transliteration":"","translation_bn":"(৪৩)","root":"—","lemma":"٤٣","grammar_bn":"মার্কার"}]'::jsonb, 'mā tasbiqu min ummatin ajalahā wamā yastakhirūna', 'কোন জাতিই তাদের নির্দিষ্ট কালকে অগ্র পশ্চাৎ করতে পারে না।', 'No nation will precede its time [of termination], nor will they remain [thereafter].', 'কোন জাতিই তাদের নির্দিষ্ট কালকে অগ্র পশ্চাৎ করতে পারে না।', 'No nation will precede its time [of termination], nor will they remain [thereafter].', NULL, NULL, NULL, NULL, NULL, 'https://everyayah.com/data/Alafasy_128kbps/023043.mp3', now()),
  (23, 44, '', '[{"id":44788,"position":1,"text_uthmani":"ثُمَّ","transliteration":"thumma","translation_bn":"এরপর","root":"—","lemma":"ثُمّ\r","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":44789,"position":2,"text_uthmani":"أَرْسَلْنَا","transliteration":"arsalnā","translation_bn":"আমরা পাঠিয়েছি","root":"رسل","lemma":"أَرْسَلَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":44790,"position":3,"text_uthmani":"رُسُلَنَا","transliteration":"rusulanā","translation_bn":"আমাদের রাসূলগণকে","root":"رسل","lemma":"رَسُول","grammar_bn":"বিশেষ্য (Noun)"},{"id":44791,"position":4,"text_uthmani":"تَتْرَا ۖ","transliteration":"tatrā","translation_bn":"একের পর এক","root":"وتر","lemma":"تَتْرَا","grammar_bn":"বিশেষ্য (Noun)"},{"id":44793,"position":5,"text_uthmani":"كُلَّ","transliteration":"kulla","translation_bn":"যখনই","root":"كلل","lemma":"كُلّ","grammar_bn":"বিশেষ্য (Noun)"},{"id":44794,"position":6,"text_uthmani":"مَا","transliteration":"mā","translation_bn":"যা","root":"—","lemma":"مَا\r","grammar_bn":"অধীনস্থ যোজক (Subordinating)"},{"id":44795,"position":7,"text_uthmani":"جَآءَ","transliteration":"jāa","translation_bn":"এসেছে","root":"جيا","lemma":"جَا^ءَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":44796,"position":8,"text_uthmani":"أُمَّةًۭ","transliteration":"ummatan","translation_bn":"কোন জাতির (নিকট)","root":"امم","lemma":"أُمَّة","grammar_bn":"বিশেষ্য (Noun)"},{"id":44797,"position":9,"text_uthmani":"رَّسُولُهَا","transliteration":"rasūluhā","translation_bn":"তার রাসূল","root":"رسل","lemma":"رَسُول","grammar_bn":"বিশেষ্য (Noun)"},{"id":44798,"position":10,"text_uthmani":"كَذَّبُوهُ ۚ","transliteration":"kadhabūhu","translation_bn":"তাকে তারা মিথ্যাবাদী বলেছে","root":"كذب","lemma":"كَذَّبَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":44800,"position":11,"text_uthmani":"فَأَتْبَعْنَا","transliteration":"fa-atbaʿnā","translation_bn":"অতঃপর আমরা পিছনে চললাম (অর্থাৎ ধ্বংস করলাম)","root":"تبع","lemma":"أَتْبَعَ","grammar_bn":"শব্দ"},{"id":44801,"position":12,"text_uthmani":"بَعْضَهُم","transliteration":"baʿḍahum","translation_bn":"তাদের একের পর","root":"بعض","lemma":"بَعْض","grammar_bn":"বিশেষ্য (Noun)"},{"id":44802,"position":13,"text_uthmani":"بَعْضًۭا","transliteration":"baʿḍan","translation_bn":"এক","root":"بعض","lemma":"بَعْض","grammar_bn":"বিশেষ্য (Noun)"},{"id":44803,"position":14,"text_uthmani":"وَجَعَلْنَـٰهُمْ","transliteration":"wajaʿalnāhum","translation_bn":"ও আমরা বানিয়েছি তাদেরকে","root":"جعل","lemma":"جَعَلَ","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":44804,"position":15,"text_uthmani":"أَحَادِيثَ ۚ","transliteration":"aḥādītha","translation_bn":"কাহিনীর (মতো)","root":"حدث","lemma":"حَدِيث","grammar_bn":"বিশেষ্য (Noun)"},{"id":44806,"position":16,"text_uthmani":"فَبُعْدًۭا","transliteration":"fabuʿ''dan","translation_bn":"সুতরাং দূর হোক (অর্থাৎ ধ্বংস আসুক)","root":"بعد","lemma":"بُعْد","grammar_bn":"শব্দ"},{"id":44807,"position":17,"text_uthmani":"لِّقَوْمٍۢ","transliteration":"liqawmin","translation_bn":"জন্যে (এমন) জাতির","root":"قوم","lemma":"قَوْم","grammar_bn":"অব্যয় (Preposition)"},{"id":44808,"position":18,"text_uthmani":"لَّا","transliteration":"lā","translation_bn":"(যারা) না","root":"—","lemma":"لَا\r","grammar_bn":"না-বোধক (Negative)"},{"id":44809,"position":19,"text_uthmani":"يُؤْمِنُونَ","transliteration":"yu''minūna","translation_bn":"ঈমান আনে","root":"امن","lemma":"ءَامَنَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":44810,"position":20,"text_uthmani":"٤٤","transliteration":"","translation_bn":"(৪৪)","root":"—","lemma":"٤٤","grammar_bn":"মার্কার"}]'::jsonb, 'thumma arsalnā rusulanā tatrā kulla mā jāa ummatan rasūluhā kadhabūhu fa-atbaʿnā baʿḍahum baʿḍan wajaʿalnāhum aḥādītha fabuʿ''dan liqawmin lā yu''minūna', 'এরপর একাদিক্রমে আমি আমার রসূলদেরকে পাঠিয়েছি। যখনই কোন জাতির কাছে তাদের রসূল এসেছে, তারা তাকে মিথ্যে বলে প্রত্যাখ্যান করেছে, অতঃপর শাস্তি প্রাপ্তির ব্যাপারে তারা একে অন্যের অনুসরণ করেছে, অতঃপর তাদেরকে কাহিনী বানিয়ে দিলাম। কাজেই যে জাতি ঈমান আনে না তারা ধ্বংস হোক!', 'Then We sent Our messengers in succession. Every time there came to a nation its messenger, they denied him, so We made them follow one another [to destruction], and We made them narrations. So away with a people who do not believe.', 'এরপর একাদিক্রমে আমি আমার রসূলদেরকে পাঠিয়েছি। যখনই কোন জাতির কাছে তাদের রসূল এসেছে, তারা তাকে মিথ্যে বলে প্রত্যাখ্যান করেছে, অতঃপর শাস্তি প্রাপ্তির ব্যাপারে তারা একে অন্যের অনুসরণ করেছে, অতঃপর তাদেরকে কাহিনী বানিয়ে দিলাম। কাজেই যে জাতি ঈমান আনে না তারা ধ্বংস হোক!', 'Then We sent Our messengers in succession. Every time there came to a nation its messenger, they denied him, so We made them follow one another [to destruction], and We made them narrations. So away with a people who do not believe.', NULL, NULL, NULL, NULL, NULL, 'https://everyayah.com/data/Alafasy_128kbps/023044.mp3', now()),
  (23, 45, '', '[{"id":45465,"position":1,"text_uthmani":"ثُمَّ","transliteration":"thumma","translation_bn":"এরপর","root":"—","lemma":"ثُمّ\r","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":45466,"position":2,"text_uthmani":"أَرْسَلْنَا","transliteration":"arsalnā","translation_bn":"আমরা পাঠালাম","root":"رسل","lemma":"أَرْسَلَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":45467,"position":3,"text_uthmani":"مُوسَىٰ","transliteration":"mūsā","translation_bn":"মূসাকে","root":"—","lemma":"مُوسَىٰ","grammar_bn":"নামবাচক বিশেষ্য (Proper Noun)"},{"id":45468,"position":4,"text_uthmani":"وَأَخَاهُ","transliteration":"wa-akhāhu","translation_bn":"ও তার ভাই","root":"اخو","lemma":"أَخ","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":45469,"position":5,"text_uthmani":"هَـٰرُونَ","transliteration":"hārūna","translation_bn":"হারূনকে","root":"—","lemma":"هَٰرُون","grammar_bn":"নামবাচক বিশেষ্য (Proper Noun)"},{"id":45470,"position":6,"text_uthmani":"بِـَٔايَـٰتِنَا","transliteration":"biāyātinā","translation_bn":"সহ আমাদের নিদর্শনাবলী","root":"ايي","lemma":"ءَايَة","grammar_bn":"অব্যয় (Preposition)"},{"id":45471,"position":7,"text_uthmani":"وَسُلْطَـٰنٍۢ","transliteration":"wasul''ṭānin","translation_bn":"ও প্রমাণ (সহ)","root":"سلط","lemma":"سُلْطَٰن","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":45472,"position":8,"text_uthmani":"مُّبِينٍ","transliteration":"mubīnin","translation_bn":"সুস্পষ্ট","root":"بين","lemma":"مُّبِين","grammar_bn":"বিশেষ্য (Noun)"},{"id":45473,"position":9,"text_uthmani":"٤٥","transliteration":"","translation_bn":"(৪৫)","root":"—","lemma":"٤٥","grammar_bn":"মার্কার"}]'::jsonb, 'thumma arsalnā mūsā wa-akhāhu hārūna biāyātinā wasul''ṭānin mubīnin', 'অতঃপর আমি মূসা ও তার ভাই হারূনকে পাঠিয়েছিলাম নিদর্শন আর সুস্পষ্ট প্রমাণ সহকারে।', 'Then We sent Moses and his brother Aaron with Our signs and a clear authority', 'অতঃপর আমি মূসা ও তার ভাই হারূনকে পাঠিয়েছিলাম নিদর্শন আর সুস্পষ্ট প্রমাণ সহকারে।', 'Then We sent Moses and his brother Aaron with Our signs and a clear authority', NULL, NULL, NULL, NULL, NULL, 'https://everyayah.com/data/Alafasy_128kbps/023045.mp3', now()),
  (23, 46, '', '[{"id":46221,"position":1,"text_uthmani":"إِلَىٰ","transliteration":"ilā","translation_bn":"প্রতি","root":"—","lemma":"إِلَىٰ\r","grammar_bn":"অব্যয় (Preposition)"},{"id":46222,"position":2,"text_uthmani":"فِرْعَوْنَ","transliteration":"fir''ʿawna","translation_bn":"ফিরআউনের","root":"—","lemma":"فِرْعَوْن","grammar_bn":"নামবাচক বিশেষ্য (Proper Noun)"},{"id":46223,"position":3,"text_uthmani":"وَمَلَإِي۟هِۦ","transliteration":"wamala-ihi","translation_bn":"ও তার সভাষদদের (প্রতি)","root":"ملا","lemma":"مَلَأ","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":46224,"position":4,"text_uthmani":"فَٱسْتَكْبَرُوا۟","transliteration":"fa-is''takbarū","translation_bn":"কিন্তু তারা অহংকার করলো","root":"كبر","lemma":"ٱسْتَكْبَرَ","grammar_bn":"শব্দ"},{"id":46225,"position":5,"text_uthmani":"وَكَانُوا۟","transliteration":"wakānū","translation_bn":"ও তারা ছিলো","root":"كون","lemma":"كَانَ","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":46226,"position":6,"text_uthmani":"قَوْمًا","transliteration":"qawman","translation_bn":"জাতি","root":"قوم","lemma":"قَوْم","grammar_bn":"বিশেষ্য (Noun)"},{"id":46227,"position":7,"text_uthmani":"عَالِينَ","transliteration":"ʿālīna","translation_bn":"উদ্ধত","root":"علو","lemma":"عَالِين","grammar_bn":"বিশেষণ (Adjective)"},{"id":46228,"position":8,"text_uthmani":"٤٦","transliteration":"","translation_bn":"(৪৬)","root":"—","lemma":"٤٦","grammar_bn":"মার্কার"}]'::jsonb, 'ilā fir''ʿawna wamala-ihi fa-is''takbarū wakānū qawman ʿālīna', 'ফেরাউন ও তার প্রধানগণের কাছে। কিন্তু তারা অহংকার করল, তারা ছিল এক উদ্ধত জাতি।', 'To Pharaoh and his establishment, but they were arrogant and were a haughty people.', 'ফেরাউন ও তার প্রধানগণের কাছে। কিন্তু তারা অহংকার করল, তারা ছিল এক উদ্ধত জাতি।', 'To Pharaoh and his establishment, but they were arrogant and were a haughty people.', NULL, NULL, NULL, NULL, NULL, 'https://everyayah.com/data/Alafasy_128kbps/023046.mp3', now()),
  (23, 47, '', '[{"id":46835,"position":1,"text_uthmani":"فَقَالُوٓا۟","transliteration":"faqālū","translation_bn":"অতঃপর তারা বললো","root":"قول","lemma":"قَالَ","grammar_bn":"শব্দ"},{"id":46836,"position":2,"text_uthmani":"أَنُؤْمِنُ","transliteration":"anu''minu","translation_bn":"\"কি ঈমান আনবো আমরা","root":"امن","lemma":"ءَامَنَ","grammar_bn":"প্রশ্নবোধক (Interrogative)"},{"id":46837,"position":3,"text_uthmani":"لِبَشَرَيْنِ","transliteration":"libasharayni","translation_bn":"মানুষের উপর দুজন","root":"بشر","lemma":"بَشَر","grammar_bn":"অব্যয় (Preposition)"},{"id":46838,"position":4,"text_uthmani":"مِثْلِنَا","transliteration":"mith''linā","translation_bn":"আমাদের মতো","root":"مثل","lemma":"مِثْل","grammar_bn":"বিশেষ্য (Noun)"},{"id":46839,"position":5,"text_uthmani":"وَقَوْمُهُمَا","transliteration":"waqawmuhumā","translation_bn":"অথচ তাদের উভয়ের জাতি","root":"قوم","lemma":"قَوْم","grammar_bn":"অবস্থাবাচক (Circumstantial)"},{"id":46840,"position":6,"text_uthmani":"لَنَا","transliteration":"lanā","translation_bn":"জন্যে আমাদের","root":"—","lemma":"لَنَا","grammar_bn":"অব্যয় (Preposition)"},{"id":46841,"position":7,"text_uthmani":"عَـٰبِدُونَ","transliteration":"ʿābidūna","translation_bn":"দাস-দাসী (হয়ে আছে)\"","root":"عبد","lemma":"عَابِد","grammar_bn":"বিশেষ্য (Noun)"},{"id":46842,"position":8,"text_uthmani":"٤٧","transliteration":"","translation_bn":"(৪৭)","root":"—","lemma":"٤٧","grammar_bn":"মার্কার"}]'::jsonb, 'faqālū anu''minu libasharayni mith''linā waqawmuhumā lanā ʿābidūna', 'তারা বলল, ‘আমরা কি আমাদেরই মত দু’জন লোকের প্রতি বিশ্বাস স্থাপন করব, অথচ তাদের সম্প্রদায় আমাদের দাস?’', 'They said, "Should we believe two men like ourselves while their people are for us in servitude?"', 'তারা বলল, ‘আমরা কি আমাদেরই মত দু’জন লোকের প্রতি বিশ্বাস স্থাপন করব, অথচ তাদের সম্প্রদায় আমাদের দাস?’', 'They said, "Should we believe two men like ourselves while their people are for us in servitude?"', NULL, NULL, NULL, NULL, NULL, 'https://everyayah.com/data/Alafasy_128kbps/023047.mp3', now()),
  (23, 48, '', '[{"id":47372,"position":1,"text_uthmani":"فَكَذَّبُوهُمَا","transliteration":"fakadhabūhumā","translation_bn":"অতএব উভয়কে তারা মিথ্যারোপ করলো","root":"كذب","lemma":"كَذَّبَ","grammar_bn":"শব্দ"},{"id":47373,"position":2,"text_uthmani":"فَكَانُوا۟","transliteration":"fakānū","translation_bn":"অতঃপর তারা হলো","root":"كون","lemma":"كَانَ","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":47374,"position":3,"text_uthmani":"مِنَ","transliteration":"mina","translation_bn":"অন্তর্ভুক্ত","root":"—","lemma":"مِن\r","grammar_bn":"অব্যয় (Preposition)"},{"id":47375,"position":4,"text_uthmani":"ٱلْمُهْلَكِينَ","transliteration":"l-muh''lakīna","translation_bn":"ধ্বংসপ্রাপ্তদের","root":"هلك","lemma":"مُهْلَكِين","grammar_bn":"শব্দ"},{"id":47376,"position":5,"text_uthmani":"٤٨","transliteration":"","translation_bn":"(৪৮)","root":"—","lemma":"٤٨","grammar_bn":"মার্কার"}]'::jsonb, 'fakadhabūhumā fakānū mina l-muh''lakīna', 'তারা তাদের দু’জনকে মিথ্যে বলে প্রত্যাখ্যান করল, ফলে তারা ধ্বংসপ্রাপ্তদের অন্তর্ভুক্ত হয়ে গেল।', 'So they denied them and were of those destroyed.', 'তারা তাদের দু’জনকে মিথ্যে বলে প্রত্যাখ্যান করল, ফলে তারা ধ্বংসপ্রাপ্তদের অন্তর্ভুক্ত হয়ে গেল।', 'So they denied them and were of those destroyed.', NULL, NULL, NULL, NULL, NULL, 'https://everyayah.com/data/Alafasy_128kbps/023048.mp3', now()),
  (23, 49, '', '[{"id":47940,"position":1,"text_uthmani":"وَلَقَدْ","transliteration":"walaqad","translation_bn":"আর নিশ্চয়ই","root":"—","lemma":"قَد\r","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":47941,"position":2,"text_uthmani":"ءَاتَيْنَا","transliteration":"ātaynā","translation_bn":"আমরা দিয়েছিলাম","root":"اتي","lemma":"ا^تَى","grammar_bn":"ক্রিয়া (Verb)"},{"id":47942,"position":3,"text_uthmani":"مُوسَى","transliteration":"mūsā","translation_bn":"মূসাকে","root":"—","lemma":"مُوسَىٰ","grammar_bn":"নামবাচক বিশেষ্য (Proper Noun)"},{"id":47943,"position":4,"text_uthmani":"ٱلْكِتَـٰبَ","transliteration":"l-kitāba","translation_bn":"কিতাব","root":"كتب","lemma":"كِتَٰب","grammar_bn":"শব্দ"},{"id":47944,"position":5,"text_uthmani":"لَعَلَّهُمْ","transliteration":"laʿallahum","translation_bn":"যাতে তারা","root":"—","lemma":"لَعَلّ","grammar_bn":"অভিঘাত পদ (Accusative)"},{"id":47945,"position":6,"text_uthmani":"يَهْتَدُونَ","transliteration":"yahtadūna","translation_bn":"সৎ পথ পায়","root":"هدي","lemma":"ٱهْتَدَىٰ","grammar_bn":"ক্রিয়া (Verb)"},{"id":47946,"position":7,"text_uthmani":"٤٩","transliteration":"","translation_bn":"(৪৯)","root":"—","lemma":"٤٩","grammar_bn":"মার্কার"}]'::jsonb, 'walaqad ātaynā mūsā l-kitāba laʿallahum yahtadūna', 'আমি মূসাকে কিতাব দিয়েছিলাম যাতে তারা সঠিক পথ পেতে পারে।', 'And We certainly gave Moses the Scripture that perhaps they would be guided.', 'আমি মূসাকে কিতাব দিয়েছিলাম যাতে তারা সঠিক পথ পেতে পারে।', 'And We certainly gave Moses the Scripture that perhaps they would be guided.', NULL, NULL, NULL, NULL, NULL, 'https://everyayah.com/data/Alafasy_128kbps/023049.mp3', now()),
  (23, 50, '', '[{"id":48941,"position":1,"text_uthmani":"وَجَعَلْنَا","transliteration":"wajaʿalnā","translation_bn":"আর আমরা করেছি","root":"جعل","lemma":"جَعَلَ","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":48942,"position":2,"text_uthmani":"ٱبْنَ","transliteration":"ib''na","translation_bn":"পুত্রকে","root":"بني","lemma":"ٱبْن","grammar_bn":"বিশেষ্য (Noun)"},{"id":48943,"position":3,"text_uthmani":"مَرْيَمَ","transliteration":"maryama","translation_bn":"মারইয়ামের","root":"—","lemma":"مَرْيَم","grammar_bn":"নামবাচক বিশেষ্য (Proper Noun)"},{"id":48944,"position":4,"text_uthmani":"وَأُمَّهُۥٓ","transliteration":"wa-ummahu","translation_bn":"ও তার মাকে","root":"امم","lemma":"أُمّ","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":48945,"position":5,"text_uthmani":"ءَايَةًۭ","transliteration":"āyatan","translation_bn":"এক নিদর্শন","root":"ايي","lemma":"ءَايَة","grammar_bn":"বিশেষ্য (Noun)"},{"id":48946,"position":6,"text_uthmani":"وَءَاوَيْنَـٰهُمَآ","transliteration":"waāwaynāhumā","translation_bn":"এবং উভয়কে আশ্রয় দিয়েছিলাম আমরা","root":"اوي","lemma":"ءَاوَىٰ^","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":48947,"position":7,"text_uthmani":"إِلَىٰ","transliteration":"ilā","translation_bn":"দিকে","root":"—","lemma":"إِلَىٰ\r","grammar_bn":"অব্যয় (Preposition)"},{"id":48948,"position":8,"text_uthmani":"رَبْوَةٍۢ","transliteration":"rabwatin","translation_bn":"উচ্চভূমির","root":"ربو","lemma":"رَبْوَة","grammar_bn":"বিশেষ্য (Noun)"},{"id":48949,"position":9,"text_uthmani":"ذَاتِ","transliteration":"dhāti","translation_bn":"উপযোগী","root":"—","lemma":"ذُو","grammar_bn":"বিশেষ্য (Noun)"},{"id":48950,"position":10,"text_uthmani":"قَرَارٍۢ","transliteration":"qarārin","translation_bn":"অবস্থানের","root":"قرر","lemma":"قَرَار","grammar_bn":"বিশেষ্য (Noun)"},{"id":48951,"position":11,"text_uthmani":"وَمَعِينٍۢ","transliteration":"wamaʿīnin","translation_bn":"ও ঝর্ণা (বিশিষ্ট)","root":"عين","lemma":"مَّعِين","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":48952,"position":12,"text_uthmani":"٥٠","transliteration":"","translation_bn":"(৫০)","root":"—","lemma":"٥٠","grammar_bn":"মার্কার"}]'::jsonb, 'wajaʿalnā ib''na maryama wa-ummahu āyatan waāwaynāhumā ilā rabwatin dhāti qarārin wamaʿīnin', 'আমি মারইয়াম-পুত্র আর তার মাকে নিদর্শন করেছিলাম আর তাদেরকে স্বস্তি নিরাপত্তা ও ঝর্ণা বিশিষ্ট উচ্চ স্থানে আশ্রয় দিয়েছিলাম।', 'And We made the son of Mary and his mother a sign and sheltered them within a high ground having level [areas] and flowing water.', 'আমি মারইয়াম-পুত্র আর তার মাকে নিদর্শন করেছিলাম আর তাদেরকে স্বস্তি নিরাপত্তা ও ঝর্ণা বিশিষ্ট উচ্চ স্থানে আশ্রয় দিয়েছিলাম।', 'And We made the son of Mary and his mother a sign and sheltered them within a high ground having level [areas] and flowing water.', NULL, NULL, NULL, NULL, NULL, 'https://everyayah.com/data/Alafasy_128kbps/023050.mp3', now()),
  (23, 51, '', '[{"id":49268,"position":1,"text_uthmani":"يَـٰٓأَيُّهَا","transliteration":"yāayyuhā","translation_bn":"(আর বলেছিলাম) হে","root":"—","lemma":"أَيُّهَا","grammar_bn":"সম্বোধন পদ (Vocative)"},{"id":49269,"position":2,"text_uthmani":"ٱلرُّسُلُ","transliteration":"l-rusulu","translation_bn":"রাসূলরা","root":"رسل","lemma":"رَسُول","grammar_bn":"শব্দ"},{"id":49270,"position":3,"text_uthmani":"كُلُوا۟","transliteration":"kulū","translation_bn":"তোমরা খাও","root":"اكل","lemma":"أَكَلَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":49271,"position":4,"text_uthmani":"مِنَ","transliteration":"mina","translation_bn":"হ''তে","root":"—","lemma":"مِن\r","grammar_bn":"অব্যয় (Preposition)"},{"id":49272,"position":5,"text_uthmani":"ٱلطَّيِّبَـٰتِ","transliteration":"l-ṭayibāti","translation_bn":"পবিত্র (বস্তু)","root":"طيب","lemma":"طَيِّبَٰت","grammar_bn":"শব্দ"},{"id":49273,"position":6,"text_uthmani":"وَٱعْمَلُوا۟","transliteration":"wa-iʿ''malū","translation_bn":"ও তোমরা কাজ করো","root":"عمل","lemma":"عَمِلَ","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":49274,"position":7,"text_uthmani":"صَـٰلِحًا ۖ","transliteration":"ṣāliḥan","translation_bn":"সৎ","root":"صلح","lemma":"صَٰلِح","grammar_bn":"বিশেষ্য (Noun)"},{"id":49276,"position":8,"text_uthmani":"إِنِّى","transliteration":"innī","translation_bn":"নিশ্চয়ই আমি","root":"—","lemma":"إِنّ","grammar_bn":"অভিঘাত পদ (Accusative)"},{"id":49277,"position":9,"text_uthmani":"بِمَا","transliteration":"bimā","translation_bn":"সে সম্পর্কে যা","root":"—","lemma":"مَا\r","grammar_bn":"অব্যয় (Preposition)"},{"id":49278,"position":10,"text_uthmani":"تَعْمَلُونَ","transliteration":"taʿmalūna","translation_bn":"তোমরা কাজ করো","root":"عمل","lemma":"عَمِلَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":49279,"position":11,"text_uthmani":"عَلِيمٌۭ","transliteration":"ʿalīmun","translation_bn":"খুব অবহিত","root":"علم","lemma":"عَلِيم","grammar_bn":"বিশেষ্য (Noun)"},{"id":49280,"position":12,"text_uthmani":"٥١","transliteration":"","translation_bn":"(৫১)","root":"—","lemma":"٥١","grammar_bn":"মার্কার"}]'::jsonb, 'yāayyuhā l-rusulu kulū mina l-ṭayibāti wa-iʿ''malū ṣāliḥan innī bimā taʿmalūna ʿalīmun', 'হে রসূলগণ! পবিত্র বস্তু আহার কর, আর সৎ কাজ কর, তোমরা যা কর সে সম্পর্কে আমি পূর্ণরূপে অবগত।', '[Allah said], "O messengers, eat from the good foods and work righteousness. Indeed, I, of what you do, am Knowing.', 'হে রসূলগণ! পবিত্র বস্তু আহার কর, আর সৎ কাজ কর, তোমরা যা কর সে সম্পর্কে আমি পূর্ণরূপে অবগত।', '[Allah said], "O messengers, eat from the good foods and work righteousness. Indeed, I, of what you do, am Knowing.', NULL, NULL, NULL, NULL, NULL, 'https://everyayah.com/data/Alafasy_128kbps/023051.mp3', now()),
  (23, 52, '', '[{"id":50121,"position":1,"text_uthmani":"وَإِنَّ","transliteration":"wa-inna","translation_bn":"এবং নিশ্চয়ই","root":"—","lemma":"إِنّ","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":50122,"position":2,"text_uthmani":"هَـٰذِهِۦٓ","transliteration":"hādhihi","translation_bn":"এই","root":"—","lemma":"هَٰذَا","grammar_bn":"নির্দেশক সর্বনাম (Demonstrative)"},{"id":50123,"position":3,"text_uthmani":"أُمَّتُكُمْ","transliteration":"ummatukum","translation_bn":"তোমাদের জাতি","root":"امم","lemma":"أُمَّة","grammar_bn":"বিশেষ্য (Noun)"},{"id":50124,"position":4,"text_uthmani":"أُمَّةًۭ","transliteration":"ummatan","translation_bn":"জাতি","root":"امم","lemma":"أُمَّة","grammar_bn":"বিশেষ্য (Noun)"},{"id":50125,"position":5,"text_uthmani":"وَٰحِدَةًۭ","transliteration":"wāḥidatan","translation_bn":"একই","root":"وحد","lemma":"وَٰحِدَة","grammar_bn":"বিশেষ্য (Noun)"},{"id":50126,"position":6,"text_uthmani":"وَأَنَا۠","transliteration":"wa-anā","translation_bn":"আর আমি","root":"—","lemma":"وَأَنَا۠","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":50127,"position":7,"text_uthmani":"رَبُّكُمْ","transliteration":"rabbukum","translation_bn":"তোমাদে্র রব","root":"ربب","lemma":"رَبّ","grammar_bn":"বিশেষ্য (Noun)"},{"id":50128,"position":8,"text_uthmani":"فَٱتَّقُونِ","transliteration":"fa-ittaqūni","translation_bn":"সুতরাং আমাকেই তোমরা ভয় করো","root":"وقي","lemma":"ٱتَّقَىٰ","grammar_bn":"শব্দ"},{"id":50129,"position":9,"text_uthmani":"٥٢","transliteration":"","translation_bn":"(৫২)","root":"—","lemma":"٥٢","grammar_bn":"মার্কার"}]'::jsonb, 'wa-inna hādhihi ummatukum ummatan wāḥidatan wa-anā rabbukum fa-ittaqūni', 'তোমাদের এসব উম্মাত তো একই উম্মাত, আর আমিই তোমাদের প্রতিপালক, কাজেই আমাকেই ভয় কর।', 'And indeed this, your religion, is one religion, and I am your Lord, so fear Me."', 'তোমাদের এসব উম্মাত তো একই উম্মাত, আর আমিই তোমাদের প্রতিপালক, কাজেই আমাকেই ভয় কর।', 'And indeed this, your religion, is one religion, and I am your Lord, so fear Me."', NULL, NULL, NULL, NULL, NULL, 'https://everyayah.com/data/Alafasy_128kbps/023052.mp3', now()),
  (23, 53, '', '[{"id":50576,"position":1,"text_uthmani":"فَتَقَطَّعُوٓا۟","transliteration":"fataqaṭṭaʿū","translation_bn":"কিন্তু (লোকেরা) বিভক্ত করলো","root":"قطع","lemma":"تَّقَطَّعَ","grammar_bn":"শব্দ"},{"id":50577,"position":2,"text_uthmani":"أَمْرَهُم","transliteration":"amrahum","translation_bn":"তাদের কাজকে","root":"امر","lemma":"أَمْر","grammar_bn":"বিশেষ্য (Noun)"},{"id":50578,"position":3,"text_uthmani":"بَيْنَهُمْ","transliteration":"baynahum","translation_bn":"তাদের মাঝে","root":"بين","lemma":"بَيْن","grammar_bn":"স্থানবাচক (Location)"},{"id":50579,"position":4,"text_uthmani":"زُبُرًۭا ۖ","transliteration":"zuburan","translation_bn":"টুকরো টুকরো করে","root":"زبر","lemma":"زُبُر","grammar_bn":"বিশেষ্য (Noun)"},{"id":50581,"position":5,"text_uthmani":"كُلُّ","transliteration":"kullu","translation_bn":"প্রত্যেক","root":"كلل","lemma":"كُلّ","grammar_bn":"বিশেষ্য (Noun)"},{"id":50582,"position":6,"text_uthmani":"حِزْبٍۭ","transliteration":"ḥiz''bin","translation_bn":"দলই","root":"حزب","lemma":"حِزْب","grammar_bn":"বিশেষ্য (Noun)"},{"id":50583,"position":7,"text_uthmani":"بِمَا","transliteration":"bimā","translation_bn":"যা","root":"—","lemma":"مَا\r","grammar_bn":"অব্যয় (Preposition)"},{"id":50584,"position":8,"text_uthmani":"لَدَيْهِمْ","transliteration":"ladayhim","translation_bn":"কাছে তাদের (আছে)","root":"—","lemma":"لَدَي\r","grammar_bn":"স্থানবাচক (Location)"},{"id":50585,"position":9,"text_uthmani":"فَرِحُونَ","transliteration":"fariḥūna","translation_bn":"(তা নিয়েই) আনন্দিত","root":"فرح","lemma":"فَرِح","grammar_bn":"বিশেষ্য (Noun)"},{"id":50586,"position":10,"text_uthmani":"٥٣","transliteration":"","translation_bn":"(৫৩)","root":"—","lemma":"٥٣","grammar_bn":"মার্কার"}]'::jsonb, 'fataqaṭṭaʿū amrahum baynahum zuburan kullu ḥiz''bin bimā ladayhim fariḥūna', 'কিন্তু মানুষ তাদের কর্তব্য কর্মকে বহুধা বিভক্ত করে ফেলেছে, আর প্রত্যেক দলই তাদের কাছে যা আছে তাই নিয়ে আনন্দিত।', 'But the people divided their religion among them into sects - each faction, in what it has, rejoicing.', 'কিন্তু মানুষ তাদের কর্তব্য কর্মকে বহুধা বিভক্ত করে ফেলেছে, আর প্রত্যেক দলই তাদের কাছে যা আছে তাই নিয়ে আনন্দিত।', 'But the people divided their religion among them into sects - each faction, in what it has, rejoicing.', NULL, NULL, NULL, NULL, NULL, 'https://everyayah.com/data/Alafasy_128kbps/023053.mp3', now()),
  (23, 54, '', '[{"id":51298,"position":1,"text_uthmani":"فَذَرْهُمْ","transliteration":"fadharhum","translation_bn":"সুতরাং ছেড়ে দাও তাদেরকে","root":"وذر","lemma":"يَذَرَ","grammar_bn":"শব্দ"},{"id":51299,"position":2,"text_uthmani":"فِى","transliteration":"fī","translation_bn":"মধ্যে","root":"—","lemma":"فِى\r","grammar_bn":"অব্যয় (Preposition)"},{"id":51300,"position":3,"text_uthmani":"غَمْرَتِهِمْ","transliteration":"ghamratihim","translation_bn":"তাদের বিভ্রান্তির","root":"غمر","lemma":"غَمْرَة","grammar_bn":"বিশেষ্য (Noun)"},{"id":51301,"position":4,"text_uthmani":"حَتَّىٰ","transliteration":"ḥattā","translation_bn":"পর্যন্ত","root":"—","lemma":"حَتَّىٰ\r","grammar_bn":"অব্যয় (Preposition)"},{"id":51302,"position":5,"text_uthmani":"حِينٍ","transliteration":"ḥīnin","translation_bn":"এক নির্দিষ্ট সময়","root":"حين","lemma":"حِين","grammar_bn":"বিশেষ্য (Noun)"},{"id":51303,"position":6,"text_uthmani":"٥٤","transliteration":"","translation_bn":"(৫৪)","root":"—","lemma":"٥٤","grammar_bn":"মার্কার"}]'::jsonb, 'fadharhum fī ghamratihim ḥattā ḥīnin', 'কাজেই তাদেরকে কিছুকাল তাদের অজ্ঞানতাপ্রসূত বিভ্রান্তিতে থাকতে দাও।', 'So leave them in their confusion for a time.', 'কাজেই তাদেরকে কিছুকাল তাদের অজ্ঞানতাপ্রসূত বিভ্রান্তিতে থাকতে দাও।', 'So leave them in their confusion for a time.', NULL, NULL, NULL, NULL, NULL, 'https://everyayah.com/data/Alafasy_128kbps/023054.mp3', now()),
  (23, 55, '', '[{"id":51774,"position":1,"text_uthmani":"أَيَحْسَبُونَ","transliteration":"ayaḥsabūna","translation_bn":"কি তারা মনে করেছে","root":"حسب","lemma":"حَسِبَ","grammar_bn":"প্রশ্নবোধক (Interrogative)"},{"id":51775,"position":2,"text_uthmani":"أَنَّمَا","transliteration":"annamā","translation_bn":"যেহেতু","root":"—","lemma":"أَنّ","grammar_bn":"অভিঘাত পদ (Accusative)"},{"id":51776,"position":3,"text_uthmani":"نُمِدُّهُم","transliteration":"numidduhum","translation_bn":"সাহায্য করে যাচ্ছি আমরা তাদের","root":"مدد","lemma":"أَمَدَّ","grammar_bn":"ক্রিয়া (Verb)"},{"id":51777,"position":4,"text_uthmani":"بِهِۦ","transliteration":"bihi","translation_bn":"মাধ্যমে তার","root":"—","lemma":"بِهِۦ","grammar_bn":"অব্যয় (Preposition)"},{"id":51778,"position":5,"text_uthmani":"مِن","transliteration":"min","translation_bn":"দিয়ে","root":"—","lemma":"مِن\r","grammar_bn":"অব্যয় (Preposition)"},{"id":51779,"position":6,"text_uthmani":"مَّالٍۢ","transliteration":"mālin","translation_bn":"ধন-সম্পদ","root":"مول","lemma":"مَال","grammar_bn":"বিশেষ্য (Noun)"},{"id":51780,"position":7,"text_uthmani":"وَبَنِينَ","transliteration":"wabanīna","translation_bn":"ও সন্তান-সন্তুতি","root":"بني","lemma":"بُنَىّ","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":51781,"position":8,"text_uthmani":"٥٥","transliteration":"","translation_bn":"(৫৫)","root":"—","lemma":"٥٥","grammar_bn":"মার্কার"}]'::jsonb, 'ayaḥsabūna annamā numidduhum bihi min mālin wabanīna', 'তারা কি ভেবে নিয়েছে, আমি যে তাদেরকে ধনৈশ্বর্য ও সন্তানাদির প্রাচুর্য দিয়ে সাহায্য করেছি', 'Do they think that what We extend to them of wealth and children', 'তারা কি ভেবে নিয়েছে, আমি যে তাদেরকে ধনৈশ্বর্য ও সন্তানাদির প্রাচুর্য দিয়ে সাহায্য করেছি', 'Do they think that what We extend to them of wealth and children', NULL, NULL, NULL, NULL, NULL, 'https://everyayah.com/data/Alafasy_128kbps/023055.mp3', now()),
  (23, 56, '', '[{"id":52258,"position":1,"text_uthmani":"نُسَارِعُ","transliteration":"nusāriʿu","translation_bn":"আমরা দ্রুত নিয়ে যাচ্ছি","root":"سرع","lemma":"يُسَٰرِعُ","grammar_bn":"ক্রিয়া (Verb)"},{"id":52259,"position":2,"text_uthmani":"لَهُمْ","transliteration":"lahum","translation_bn":"তাদেরকে","root":"—","lemma":"لَهُمْ","grammar_bn":"অব্যয় (Preposition)"},{"id":52260,"position":3,"text_uthmani":"فِى","transliteration":"fī","translation_bn":"দিকে","root":"—","lemma":"فِى\r","grammar_bn":"অব্যয় (Preposition)"},{"id":52261,"position":4,"text_uthmani":"ٱلْخَيْرَٰتِ ۚ","transliteration":"l-khayrāti","translation_bn":"কল্যাণের","root":"خير","lemma":"خَيْرَٰت","grammar_bn":"শব্দ"},{"id":52263,"position":5,"text_uthmani":"بَل","transliteration":"bal","translation_bn":"বরং","root":"—","lemma":"بَل\r","grammar_bn":"প্রত্যাহার পদ (Retraction)"},{"id":52264,"position":6,"text_uthmani":"لَّا","transliteration":"lā","translation_bn":"না","root":"—","lemma":"لَا\r","grammar_bn":"না-বোধক (Negative)"},{"id":52265,"position":7,"text_uthmani":"يَشْعُرُونَ","transliteration":"yashʿurūna","translation_bn":"তারা বুঝে","root":"شعر","lemma":"يَشْعُرُ","grammar_bn":"ক্রিয়া (Verb)"},{"id":52266,"position":8,"text_uthmani":"٥٦","transliteration":"","translation_bn":"(৫৬)","root":"—","lemma":"٥٦","grammar_bn":"মার্কার"}]'::jsonb, 'nusāriʿu lahum fī l-khayrāti bal lā yashʿurūna', 'এর দ্বারা কি তাদের কল্যাণ ত্বরান্বিত করছি? না, তারা বুঝে না।', 'Is [because] We hasten for them good things? Rather, they do not perceive.', 'এর দ্বারা কি তাদের কল্যাণ ত্বরান্বিত করছি? না, তারা বুঝে না।', 'Is [because] We hasten for them good things? Rather, they do not perceive.', NULL, NULL, NULL, NULL, NULL, 'https://everyayah.com/data/Alafasy_128kbps/023056.mp3', now()),
  (23, 57, '', '[{"id":52846,"position":1,"text_uthmani":"إِنَّ","transliteration":"inna","translation_bn":"নিশ্চয়ই","root":"—","lemma":"إِنّ","grammar_bn":"অভিঘাত পদ (Accusative)"},{"id":52847,"position":2,"text_uthmani":"ٱلَّذِينَ","transliteration":"alladhīna","translation_bn":"যাদের (অবস্থা এই যে)","root":"—","lemma":"ٱلَّذِى","grammar_bn":"সাপেক্ষ সর্বনাম (Relative)"},{"id":52848,"position":3,"text_uthmani":"هُم","transliteration":"hum","translation_bn":"তারা","root":"—","lemma":"هُم","grammar_bn":"সর্বনাম (Pronoun)"},{"id":52849,"position":4,"text_uthmani":"مِّنْ","transliteration":"min","translation_bn":"কারণে","root":"—","lemma":"مِن\r","grammar_bn":"অব্যয় (Preposition)"},{"id":52850,"position":5,"text_uthmani":"خَشْيَةِ","transliteration":"khashyati","translation_bn":"ভয়ের","root":"خشي","lemma":"خَشْيَة","grammar_bn":"বিশেষ্য (Noun)"},{"id":52851,"position":6,"text_uthmani":"رَبِّهِم","transliteration":"rabbihim","translation_bn":"তাদের রবের","root":"ربب","lemma":"رَبّ","grammar_bn":"বিশেষ্য (Noun)"},{"id":52852,"position":7,"text_uthmani":"مُّشْفِقُونَ","transliteration":"mush''fiqūna","translation_bn":"ভীত-সন্ত্রস্ত","root":"شفق","lemma":"مُشْفِقُون","grammar_bn":"বিশেষ্য (Noun)"},{"id":52853,"position":8,"text_uthmani":"٥٧","transliteration":"","translation_bn":"(৫৭)","root":"—","lemma":"٥٧","grammar_bn":"মার্কার"}]'::jsonb, 'inna alladhīna hum min khashyati rabbihim mush''fiqūna', 'নিশ্চয় যারা তাদের প্রতিপালকের ভয়ে ভীত-সন্ত্রস্ত হয়ে থাকে,', 'Indeed, they who are apprehensive from fear of their Lord', 'নিশ্চয় যারা তাদের প্রতিপালকের ভয়ে ভীত-সন্ত্রস্ত হয়ে থাকে,', 'Indeed, they who are apprehensive from fear of their Lord', NULL, NULL, NULL, NULL, NULL, 'https://everyayah.com/data/Alafasy_128kbps/023057.mp3', now()),
