  (23, 59, '', '[{"id":53944,"position":1,"text_uthmani":"وَٱلَّذِينَ","transliteration":"wa-alladhīna","translation_bn":"এবং যাদের (অবস্থা এই যে)","root":"—","lemma":"ٱلَّذِى","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":53945,"position":2,"text_uthmani":"هُم","transliteration":"hum","translation_bn":"তারা","root":"—","lemma":"هُم","grammar_bn":"সর্বনাম (Pronoun)"},{"id":53946,"position":3,"text_uthmani":"بِرَبِّهِمْ","transliteration":"birabbihim","translation_bn":"সাথে তাদের রবের","root":"ربب","lemma":"رَبّ","grammar_bn":"অব্যয় (Preposition)"},{"id":53947,"position":4,"text_uthmani":"لَا","transliteration":"lā","translation_bn":"না","root":"—","lemma":"لَا\r","grammar_bn":"না-বোধক (Negative)"},{"id":53948,"position":5,"text_uthmani":"يُشْرِكُونَ","transliteration":"yush''rikūna","translation_bn":"শরীক করে (কাউকে)","root":"شرك","lemma":"أَشْرَكَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":53949,"position":6,"text_uthmani":"٥٩","transliteration":"","translation_bn":"(৫৯)","root":"—","lemma":"٥٩","grammar_bn":"মার্কার"}]'::jsonb, 'wa-alladhīna hum birabbihim lā yush''rikūna', 'যারা তাদের প্রতিপালকের সঙ্গে শরীক করে না,', 'And they who do not associate anything with their Lord', 'যারা তাদের প্রতিপালকের সঙ্গে শরীক করে না,', 'And they who do not associate anything with their Lord', NULL, NULL, NULL, NULL, NULL, 'https://everyayah.com/data/Alafasy_128kbps/023059.mp3', now()),
  (23, 60, '', '[{"id":54510,"position":1,"text_uthmani":"وَٱلَّذِينَ","transliteration":"wa-alladhīna","translation_bn":"এবং যারা (এমন যে)","root":"—","lemma":"ٱلَّذِى","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":54511,"position":2,"text_uthmani":"يُؤْتُونَ","transliteration":"yu''tūna","translation_bn":"(যখন) দান করে","root":"اتي","lemma":"ا^تَى","grammar_bn":"ক্রিয়া (Verb)"},{"id":54512,"position":3,"text_uthmani":"مَآ","transliteration":"mā","translation_bn":"যা কিছু","root":"—","lemma":"مَا\r","grammar_bn":"সাপেক্ষ সর্বনাম (Relative)"},{"id":54513,"position":4,"text_uthmani":"ءَاتَوا۟","transliteration":"ātaw","translation_bn":"দান করার","root":"اتي","lemma":"ا^تَى","grammar_bn":"ক্রিয়া (Verb)"},{"id":54514,"position":5,"text_uthmani":"وَّقُلُوبُهُمْ","transliteration":"waqulūbuhum","translation_bn":"এ অবস্থায় যে তাদের অন্তর","root":"قلب","lemma":"قَلْب","grammar_bn":"অবস্থাবাচক (Circumstantial)"},{"id":54515,"position":6,"text_uthmani":"وَجِلَةٌ","transliteration":"wajilatun","translation_bn":"কম্পিত থাকে","root":"وجل","lemma":"وَجِلَة","grammar_bn":"বিশেষণ (Adjective)"},{"id":54516,"position":7,"text_uthmani":"أَنَّهُمْ","transliteration":"annahum","translation_bn":"(এ ভেবে) যে তারা","root":"—","lemma":"أَنّ","grammar_bn":"অভিঘাত পদ (Accusative)"},{"id":54517,"position":8,"text_uthmani":"إِلَىٰ","transliteration":"ilā","translation_bn":"দিকে","root":"—","lemma":"إِلَىٰ\r","grammar_bn":"অব্যয় (Preposition)"},{"id":54518,"position":9,"text_uthmani":"رَبِّهِمْ","transliteration":"rabbihim","translation_bn":"তাদের রবের","root":"ربب","lemma":"رَبّ","grammar_bn":"বিশেষ্য (Noun)"},{"id":54519,"position":10,"text_uthmani":"رَٰجِعُونَ","transliteration":"rājiʿūna","translation_bn":"প্রত্যাবর্তনকারী","root":"رجع","lemma":"رَٰجِعُون","grammar_bn":"বিশেষ্য (Noun)"},{"id":54520,"position":11,"text_uthmani":"٦٠","transliteration":"","translation_bn":"(৬০)","root":"—","lemma":"٦٠","grammar_bn":"মার্কার"}]'::jsonb, 'wa-alladhīna yu''tūna mā ātaw waqulūbuhum wajilatun annahum ilā rabbihim rājiʿūna', 'যারা তাদের দানের বস্তু দান করে আর তাদের অন্তর ভীত শংকিত থাকে এ জন্যে যে, তাদেরকে তাদের প্রতিপালকের কাছে ফিরে যেতে হবে।', 'And they who give what they give while their hearts are fearful because they will be returning to their Lord -', 'যারা তাদের দানের বস্তু দান করে আর তাদের অন্তর ভীত শংকিত থাকে এ জন্যে যে, তাদেরকে তাদের প্রতিপালকের কাছে ফিরে যেতে হবে।', 'And they who give what they give while their hearts are fearful because they will be returning to their Lord -', NULL, NULL, NULL, NULL, NULL, 'https://everyayah.com/data/Alafasy_128kbps/023060.mp3', now()),
  (23, 61, '', '[{"id":55089,"position":1,"text_uthmani":"أُو۟لَـٰٓئِكَ","transliteration":"ulāika","translation_bn":"ঐসবলোক","root":"—","lemma":"أُولَٰ^ئِك","grammar_bn":"নির্দেশক সর্বনাম (Demonstrative)"},{"id":55090,"position":2,"text_uthmani":"يُسَـٰرِعُونَ","transliteration":"yusāriʿūna","translation_bn":"দ্রুত সম্পাদন করে","root":"سرع","lemma":"يُسَٰرِعُ","grammar_bn":"ক্রিয়া (Verb)"},{"id":55091,"position":3,"text_uthmani":"فِى","transliteration":"fī","translation_bn":"দিকে","root":"—","lemma":"فِى\r","grammar_bn":"অব্যয় (Preposition)"},{"id":55092,"position":4,"text_uthmani":"ٱلْخَيْرَٰتِ","transliteration":"l-khayrāti","translation_bn":"কল্যাণের","root":"خير","lemma":"خَيْرَٰت","grammar_bn":"শব্দ"},{"id":55093,"position":5,"text_uthmani":"وَهُمْ","transliteration":"wahum","translation_bn":"আর তারাই","root":"—","lemma":"وَهُمْ","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":55094,"position":6,"text_uthmani":"لَهَا","transliteration":"lahā","translation_bn":"জন্যে তার","root":"—","lemma":"لَهَا","grammar_bn":"অব্যয় (Preposition)"},{"id":55095,"position":7,"text_uthmani":"سَـٰبِقُونَ","transliteration":"sābiqūna","translation_bn":"অগ্রগামী হয়","root":"سبق","lemma":"سَابِق","grammar_bn":"বিশেষ্য (Noun)"},{"id":55096,"position":8,"text_uthmani":"٦١","transliteration":"","translation_bn":"(৬১)","root":"—","lemma":"٦١","grammar_bn":"মার্কার"}]'::jsonb, 'ulāika yusāriʿūna fī l-khayrāti wahum lahā sābiqūna', 'এরাই কল্যাণকাজে দ্রুতগতি, আর তাতে তারা অগ্রগামী।', 'It is those who hasten to good deeds, and they outstrip [others] therein.', 'এরাই কল্যাণকাজে দ্রুতগতি, আর তাতে তারা অগ্রগামী।', 'It is those who hasten to good deeds, and they outstrip [others] therein.', NULL, NULL, NULL, NULL, NULL, 'https://everyayah.com/data/Alafasy_128kbps/023061.mp3', now()),
  (23, 62, '', '[{"id":55655,"position":1,"text_uthmani":"وَلَا","transliteration":"walā","translation_bn":"এবং না","root":"—","lemma":"لَا\r","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":55656,"position":2,"text_uthmani":"نُكَلِّفُ","transliteration":"nukallifu","translation_bn":"দায়িত্ব দিই আমরা","root":"كلف","lemma":"يُكَلِّفُ","grammar_bn":"ক্রিয়া (Verb)"},{"id":55657,"position":3,"text_uthmani":"نَفْسًا","transliteration":"nafsan","translation_bn":"কাউকে","root":"نفس","lemma":"نَفْس","grammar_bn":"বিশেষ্য (Noun)"},{"id":55658,"position":4,"text_uthmani":"إِلَّا","transliteration":"illā","translation_bn":"এ ছাড়া","root":"—","lemma":"إِلَّا\r","grammar_bn":"সীমাবদ্ধতা (Restriction)"},{"id":55659,"position":5,"text_uthmani":"وُسْعَهَا ۖ","transliteration":"wus''ʿahā","translation_bn":"তার সাধ্য","root":"وسع","lemma":"وُسْع","grammar_bn":"বিশেষ্য (Noun)"},{"id":55661,"position":6,"text_uthmani":"وَلَدَيْنَا","transliteration":"waladaynā","translation_bn":"আর আমাদের কাছে (আছে)","root":"—","lemma":"لَدَي\r","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":55662,"position":7,"text_uthmani":"كِتَـٰبٌۭ","transliteration":"kitābun","translation_bn":"এক কিতাব (আমলনামা)","root":"كتب","lemma":"كِتَٰب","grammar_bn":"বিশেষ্য (Noun)"},{"id":55663,"position":8,"text_uthmani":"يَنطِقُ","transliteration":"yanṭiqu","translation_bn":"ব্যক্ত করে (যা)","root":"نطق","lemma":"يَنطِقُ","grammar_bn":"ক্রিয়া (Verb)"},{"id":55664,"position":9,"text_uthmani":"بِٱلْحَقِّ ۚ","transliteration":"bil-ḥaqi","translation_bn":"ভাবে যথাযথ","root":"حقق","lemma":"حَقّ","grammar_bn":"অব্যয় (Preposition)"},{"id":55666,"position":10,"text_uthmani":"وَهُمْ","transliteration":"wahum","translation_bn":"এবং তাদেরকে","root":"—","lemma":"وَهُمْ","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":55667,"position":11,"text_uthmani":"لَا","transliteration":"lā","translation_bn":"না","root":"—","lemma":"لَا\r","grammar_bn":"না-বোধক (Negative)"},{"id":55668,"position":12,"text_uthmani":"يُظْلَمُونَ","transliteration":"yuẓ''lamūna","translation_bn":"অত্যাচার করা হবে","root":"ظلم","lemma":"ظَلَمَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":55669,"position":13,"text_uthmani":"٦٢","transliteration":"","translation_bn":"(৬২)","root":"—","lemma":"٦٢","grammar_bn":"মার্কার"}]'::jsonb, 'walā nukallifu nafsan illā wus''ʿahā waladaynā kitābun yanṭiqu bil-ḥaqi wahum lā yuẓ''lamūna', 'আমি কাউকে তার সাধ্যাতীত কষ্ট দেই না, আর আমার কাছে এমন এক কিতাব আছে যা সত্য বলে, আর তাদের প্রতি মোটেই যুলম করা হবে না।', 'And We charge no soul except [with that within] its capacity, and with Us is a record which speaks with truth; and they will not be wronged.', 'আমি কাউকে তার সাধ্যাতীত কষ্ট দেই না, আর আমার কাছে এমন এক কিতাব আছে যা সত্য বলে, আর তাদের প্রতি মোটেই যুলম করা হবে না।', 'And We charge no soul except [with that within] its capacity, and with Us is a record which speaks with truth; and they will not be wronged.', NULL, NULL, NULL, NULL, NULL, 'https://everyayah.com/data/Alafasy_128kbps/023062.mp3', now()),
  (23, 63, '', '[{"id":56172,"position":1,"text_uthmani":"بَلْ","transliteration":"bal","translation_bn":"বরং","root":"—","lemma":"بَل\r","grammar_bn":"প্রত্যাহার পদ (Retraction)"},{"id":56173,"position":2,"text_uthmani":"قُلُوبُهُمْ","transliteration":"qulūbuhum","translation_bn":"তাদের অন্তর (রয়েছে)","root":"قلب","lemma":"قَلْب","grammar_bn":"বিশেষ্য (Noun)"},{"id":56174,"position":3,"text_uthmani":"فِى","transliteration":"fī","translation_bn":"মধ্যে","root":"—","lemma":"فِى\r","grammar_bn":"অব্যয় (Preposition)"},{"id":56175,"position":4,"text_uthmani":"غَمْرَةٍۢ","transliteration":"ghamratin","translation_bn":"অজ্ঞানতার","root":"غمر","lemma":"غَمْرَة","grammar_bn":"বিশেষ্য (Noun)"},{"id":56176,"position":5,"text_uthmani":"مِّنْ","transliteration":"min","translation_bn":"হ''তে","root":"—","lemma":"مِن\r","grammar_bn":"অব্যয় (Preposition)"},{"id":56177,"position":6,"text_uthmani":"هَـٰذَا","transliteration":"hādhā","translation_bn":"এ (বিষয়ে)","root":"—","lemma":"هَٰذَا","grammar_bn":"নির্দেশক সর্বনাম (Demonstrative)"},{"id":56178,"position":7,"text_uthmani":"وَلَهُمْ","transliteration":"walahum","translation_bn":"আর রয়েছে তাদের","root":"—","lemma":"وَلَهُمْ","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":56179,"position":8,"text_uthmani":"أَعْمَـٰلٌۭ","transliteration":"aʿmālun","translation_bn":"অনেক কাজ","root":"عمل","lemma":"عَمَل","grammar_bn":"বিশেষ্য (Noun)"},{"id":56180,"position":9,"text_uthmani":"مِّن","transliteration":"min","translation_bn":"থেকে","root":"—","lemma":"مِن\r","grammar_bn":"অব্যয় (Preposition)"},{"id":56181,"position":10,"text_uthmani":"دُونِ","transliteration":"dūni","translation_bn":"ছাড়া","root":"دون","lemma":"دُون","grammar_bn":"বিশেষ্য (Noun)"},{"id":56182,"position":11,"text_uthmani":"ذَٰلِكَ","transliteration":"dhālika","translation_bn":"এই (পূর্ব বর্ণিত নিয়মের)","root":"—","lemma":"ذَٰلِك","grammar_bn":"নির্দেশক সর্বনাম (Demonstrative)"},{"id":56183,"position":12,"text_uthmani":"هُمْ","transliteration":"hum","translation_bn":"তারা","root":"—","lemma":"هُمْ","grammar_bn":"সর্বনাম (Pronoun)"},{"id":56184,"position":13,"text_uthmani":"لَهَا","transliteration":"lahā","translation_bn":"জন্যে যার","root":"—","lemma":"لَهَا","grammar_bn":"অব্যয় (Preposition)"},{"id":56185,"position":14,"text_uthmani":"عَـٰمِلُونَ","transliteration":"ʿāmilūna","translation_bn":"করে যাচ্ছে","root":"عمل","lemma":"عَٰمِل","grammar_bn":"বিশেষ্য (Noun)"},{"id":56186,"position":15,"text_uthmani":"٦٣","transliteration":"","translation_bn":"(৬৩)","root":"—","lemma":"٦٣","grammar_bn":"মার্কার"}]'::jsonb, 'bal qulūbuhum fī ghamratin min hādhā walahum aʿmālun min dūni dhālika hum lahā ʿāmilūna', 'বরং তাদের অন্তর এ বিষয়ে অজ্ঞানতায় আচ্ছন্ন হয়ে আছে, এছাড়া তাদের আরো (মন্দ) কাজ আছে যা তারা করতে থাকবে।', 'But their hearts are covered with confusion over this, and they have [evil] deeds besides disbelief which they are doing,', 'বরং তাদের অন্তর এ বিষয়ে অজ্ঞানতায় আচ্ছন্ন হয়ে আছে, এছাড়া তাদের আরো (মন্দ) কাজ আছে যা তারা করতে থাকবে।', 'But their hearts are covered with confusion over this, and they have [evil] deeds besides disbelief which they are doing,', NULL, NULL, NULL, NULL, NULL, 'https://everyayah.com/data/Alafasy_128kbps/023063.mp3', now()),
  (23, 64, '', '[{"id":56636,"position":1,"text_uthmani":"حَتَّىٰٓ","transliteration":"ḥattā","translation_bn":"শেষ পর্যন্ত","root":"—","lemma":"حَتَّىٰ\r","grammar_bn":"অসম্পূর্ণ (Inceptive)"},{"id":56637,"position":2,"text_uthmani":"إِذَآ","transliteration":"idhā","translation_bn":"যখন","root":"—","lemma":"إِذَا\r","grammar_bn":"কালবাচক (Time)"},{"id":56638,"position":3,"text_uthmani":"أَخَذْنَا","transliteration":"akhadhnā","translation_bn":"আমরা পাকড়াও করবো","root":"اخذ","lemma":"أَخَذَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":56639,"position":4,"text_uthmani":"مُتْرَفِيهِم","transliteration":"mut''rafīhim","translation_bn":"তাদের ঐশ্বর্যশালীদেরকে","root":"ترف","lemma":"مُتْرَفِين","grammar_bn":"বিশেষ্য (Noun)"},{"id":56640,"position":5,"text_uthmani":"بِٱلْعَذَابِ","transliteration":"bil-ʿadhābi","translation_bn":"দিয়ে শাস্তি","root":"عذب","lemma":"عَذَاب","grammar_bn":"অব্যয় (Preposition)"},{"id":56641,"position":6,"text_uthmani":"إِذَا","transliteration":"idhā","translation_bn":"তখন","root":"—","lemma":"إِذَا\r","grammar_bn":"কালবাচক (Time)"},{"id":56642,"position":7,"text_uthmani":"هُمْ","transliteration":"hum","translation_bn":"তারা","root":"—","lemma":"هُمْ","grammar_bn":"সর্বনাম (Pronoun)"},{"id":56643,"position":8,"text_uthmani":"يَجْـَٔرُونَ","transliteration":"yajarūna","translation_bn":"চিৎকার করে উঠবে","root":"جار","lemma":"يَجْـ#َرُ","grammar_bn":"ক্রিয়া (Verb)"},{"id":56644,"position":9,"text_uthmani":"٦٤","transliteration":"","translation_bn":"(৬৪)","root":"—","lemma":"٦٤","grammar_bn":"মার্কার"}]'::jsonb, 'ḥattā idhā akhadhnā mut''rafīhim bil-ʿadhābi idhā hum yajarūna', 'অবশেষে আমি যখন তাদের (অর্থাৎ কাফিরদের) মধ্যে বিত্ত সম্পদশালীদেরকে শাস্তি দ্বারা পাকড়াও করব, তখন তারা চিৎকার জুড়ে দেবে।', 'Until when We seize their affluent ones with punishment, at once they are crying [to Allah] for help.', 'অবশেষে আমি যখন তাদের (অর্থাৎ কাফিরদের) মধ্যে বিত্ত সম্পদশালীদেরকে শাস্তি দ্বারা পাকড়াও করব, তখন তারা চিৎকার জুড়ে দেবে।', 'Until when We seize their affluent ones with punishment, at once they are crying [to Allah] for help.', NULL, NULL, NULL, NULL, NULL, 'https://everyayah.com/data/Alafasy_128kbps/023064.mp3', now()),
  (23, 65, '', '[{"id":57210,"position":1,"text_uthmani":"لَا","transliteration":"lā","translation_bn":"\"না","root":"—","lemma":"لَا\r","grammar_bn":"নিষেধবাচক (Prohibition)"},{"id":57211,"position":2,"text_uthmani":"تَجْـَٔرُوا۟","transliteration":"tajarū","translation_bn":"(বলা হবে) চিৎকার করো","root":"جار","lemma":"يَجْـ#َرُ","grammar_bn":"ক্রিয়া (Verb)"},{"id":57212,"position":3,"text_uthmani":"ٱلْيَوْمَ ۖ","transliteration":"l-yawma","translation_bn":"আজ","root":"يوم","lemma":"يَوْم","grammar_bn":"শব্দ"},{"id":57214,"position":4,"text_uthmani":"إِنَّكُم","transliteration":"innakum","translation_bn":"নিশ্চয়ই তোমাদেরকে","root":"—","lemma":"إِنّ","grammar_bn":"অভিঘাত পদ (Accusative)"},{"id":57215,"position":5,"text_uthmani":"مِّنَّا","transliteration":"minnā","translation_bn":"আমাদের হ''তে","root":"—","lemma":"مِن\r","grammar_bn":"অব্যয় (Preposition)"},{"id":57216,"position":6,"text_uthmani":"لَا","transliteration":"lā","translation_bn":"না","root":"—","lemma":"لَا\r","grammar_bn":"না-বোধক (Negative)"},{"id":57217,"position":7,"text_uthmani":"تُنصَرُونَ","transliteration":"tunṣarūna","translation_bn":"সাহায্য করা হবে","root":"نصر","lemma":"نَصَرَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":57218,"position":8,"text_uthmani":"٦٥","transliteration":"","translation_bn":"(৬৫)","root":"—","lemma":"٦٥","grammar_bn":"মার্কার"}]'::jsonb, 'lā tajarū l-yawma innakum minnā lā tunṣarūna', '(বলা হবে) ‘আজ চিৎকার করো না, আমার কাছ থেকে তোমরা সাহায্য পাবে না।’', 'Do not cry out today. Indeed, by Us you will not be helped.', '(বলা হবে) ‘আজ চিৎকার করো না, আমার কাছ থেকে তোমরা সাহায্য পাবে না।’', 'Do not cry out today. Indeed, by Us you will not be helped.', NULL, NULL, NULL, NULL, NULL, 'https://everyayah.com/data/Alafasy_128kbps/023065.mp3', now()),
  (23, 66, '', '[{"id":57712,"position":1,"text_uthmani":"قَدْ","transliteration":"qad","translation_bn":"নিশ্চয়ই","root":"—","lemma":"قَد\r","grammar_bn":"নিশ্চয়তাবোধক (Certainty)"},{"id":57713,"position":2,"text_uthmani":"كَانَتْ","transliteration":"kānat","translation_bn":"হতো","root":"كون","lemma":"كَانَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":57714,"position":3,"text_uthmani":"ءَايَـٰتِى","transliteration":"āyātī","translation_bn":"আমার আয়াতগুলোকে","root":"ايي","lemma":"ءَايَة","grammar_bn":"বিশেষ্য (Noun)"},{"id":57715,"position":4,"text_uthmani":"تُتْلَىٰ","transliteration":"tut''lā","translation_bn":"তিলাওয়াত করা হতো","root":"تلو","lemma":"تَلَىٰ","grammar_bn":"ক্রিয়া (Verb)"},{"id":57716,"position":5,"text_uthmani":"عَلَيْكُمْ","transliteration":"ʿalaykum","translation_bn":"তোমাদের কাছে","root":"—","lemma":"عَلَىٰ\r","grammar_bn":"অব্যয় (Preposition)"},{"id":57717,"position":6,"text_uthmani":"فَكُنتُمْ","transliteration":"fakuntum","translation_bn":"তখন তোমরা ছিলে","root":"كون","lemma":"كَانَ","grammar_bn":"শব্দ"},{"id":57718,"position":7,"text_uthmani":"عَلَىٰٓ","transliteration":"ʿalā","translation_bn":"উপর","root":"—","lemma":"عَلَىٰ\r","grammar_bn":"অব্যয় (Preposition)"},{"id":57719,"position":8,"text_uthmani":"أَعْقَـٰبِكُمْ","transliteration":"aʿqābikum","translation_bn":"তোমাদের গোড়ালির (পিছনে)","root":"عقب","lemma":"عَقِب","grammar_bn":"বিশেষ্য (Noun)"},{"id":57720,"position":9,"text_uthmani":"تَنكِصُونَ","transliteration":"tankiṣūna","translation_bn":"পিছিয়ে আসতে","root":"نكص","lemma":"نَكَصَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":57721,"position":10,"text_uthmani":"٦٦","transliteration":"","translation_bn":"(৬৬)","root":"—","lemma":"٦٦","grammar_bn":"মার্কার"}]'::jsonb, 'qad kānat āyātī tut''lā ʿalaykum fakuntum ʿalā aʿqābikum tankiṣūna', 'আমার আয়াত তোমাদের কাছে পড়ে শোনানো হত, কিন্তু তোমরা গোড়ালির ভরে পিছনে ঘুরে দাঁড়াতে।', 'My verses had already been recited to you, but you were turning back on your heels', 'আমার আয়াত তোমাদের কাছে পড়ে শোনানো হত, কিন্তু তোমরা গোড়ালির ভরে পিছনে ঘুরে দাঁড়াতে।', 'My verses had already been recited to you, but you were turning back on your heels', NULL, NULL, NULL, NULL, NULL, 'https://everyayah.com/data/Alafasy_128kbps/023066.mp3', now()),
  (23, 67, '', '[{"id":58128,"position":1,"text_uthmani":"مُسْتَكْبِرِينَ","transliteration":"mus''takbirīna","translation_bn":"অহংকারী হয়ে (গুরুত্ব দিতে না)","root":"كبر","lemma":"مُسْتَكْبِر","grammar_bn":"বিশেষ্য (Noun)"},{"id":58129,"position":2,"text_uthmani":"بِهِۦ","transliteration":"bihi","translation_bn":"সম্পর্কে এ","root":"—","lemma":"بِهِۦ","grammar_bn":"অব্যয় (Preposition)"},{"id":58130,"position":3,"text_uthmani":"سَـٰمِرًۭا","transliteration":"sāmiran","translation_bn":"গল্পগুজবে মেতে","root":"سمر","lemma":"سَٰمِر","grammar_bn":"বিশেষ্য (Noun)"},{"id":58131,"position":4,"text_uthmani":"تَهْجُرُونَ","transliteration":"tahjurūna","translation_bn":"তোমরা অর্থহীন কথা বলতে\"","root":"هجر","lemma":"ٱهْجُرْ","grammar_bn":"ক্রিয়া (Verb)"},{"id":58132,"position":5,"text_uthmani":"٦٧","transliteration":"","translation_bn":"(৬৭)","root":"—","lemma":"٦٧","grammar_bn":"মার্কার"}]'::jsonb, 'mus''takbirīna bihi sāmiran tahjurūna', 'অহংকারবশতঃ (কুরআন) সম্পর্কে অর্থহীন কথা বলতে যেমন কেউ রাতে গল্প বলে।', 'In arrogance regarding it, conversing by night, speaking evil.', 'অহংকারবশতঃ (কুরআন) সম্পর্কে অর্থহীন কথা বলতে যেমন কেউ রাতে গল্প বলে।', 'In arrogance regarding it, conversing by night, speaking evil.', NULL, NULL, NULL, NULL, NULL, 'https://everyayah.com/data/Alafasy_128kbps/023067.mp3', now()),
  (23, 68, '', '[{"id":58703,"position":1,"text_uthmani":"أَفَلَمْ","transliteration":"afalam","translation_bn":"কি তবে না","root":"—","lemma":"لَم\r","grammar_bn":"প্রশ্নবোধক (Interrogative)"},{"id":58704,"position":2,"text_uthmani":"يَدَّبَّرُوا۟","transliteration":"yaddabbarū","translation_bn":"তারা চিন্তা ভাবনা করে","root":"دبر","lemma":"يَتَدَبَّرُ","grammar_bn":"ক্রিয়া (Verb)"},{"id":58705,"position":3,"text_uthmani":"ٱلْقَوْلَ","transliteration":"l-qawla","translation_bn":"(এই) বাণী (সম্পর্কে)","root":"قول","lemma":"قَوْل","grammar_bn":"শব্দ"},{"id":58706,"position":4,"text_uthmani":"أَمْ","transliteration":"am","translation_bn":"অথবা","root":"—","lemma":"أَم\r","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":58707,"position":5,"text_uthmani":"جَآءَهُم","transliteration":"jāahum","translation_bn":"(সে) এসেছে তাদের (কাছে)","root":"جيا","lemma":"جَا^ءَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":58708,"position":6,"text_uthmani":"مَّا","transliteration":"mā","translation_bn":"(এমন কিছু নিয়ে) যা","root":"—","lemma":"مَا\r","grammar_bn":"সাপেক্ষ সর্বনাম (Relative)"},{"id":58709,"position":7,"text_uthmani":"لَمْ","transliteration":"lam","translation_bn":"নি","root":"—","lemma":"لَم\r","grammar_bn":"না-বোধক (Negative)"},{"id":58710,"position":8,"text_uthmani":"يَأْتِ","transliteration":"yati","translation_bn":"আসে","root":"اتي","lemma":"أَتَى","grammar_bn":"ক্রিয়া (Verb)"},{"id":58711,"position":9,"text_uthmani":"ءَابَآءَهُمُ","transliteration":"ābāahumu","translation_bn":"তাদের পিতৃপুরুষদের (কাছে)","root":"ابو","lemma":"ا^بَاء","grammar_bn":"বিশেষ্য (Noun)"},{"id":58712,"position":10,"text_uthmani":"ٱلْأَوَّلِينَ","transliteration":"l-awalīna","translation_bn":"পূর্বেকার","root":"اول","lemma":"أَوَّل","grammar_bn":"শব্দ"},{"id":58713,"position":11,"text_uthmani":"٦٨","transliteration":"","translation_bn":"(৬৮)","root":"—","lemma":"٦٨","grammar_bn":"মার্কার"}]'::jsonb, 'afalam yaddabbarū l-qawla am jāahum mā lam yati ābāahumu l-awalīna', 'তাহলে তারা কি (আল্লাহর) এ বাণী সম্পর্কে চিন্তা-ভাবনা করে না? কিংবা তাদের কাছে এমন কিছু (নতুন বস্তু) এসেছে যা তাদের পূর্বপুরুষদের কাছে আসেনি?', 'Then have they not reflected over the Qur''an, or has there come to them that which had not come to their forefathers?', 'তাহলে তারা কি (আল্লাহর) এ বাণী সম্পর্কে চিন্তা-ভাবনা করে না? কিংবা তাদের কাছে এমন কিছু (নতুন বস্তু) এসেছে যা তাদের পূর্বপুরুষদের কাছে আসেনি?', 'Then have they not reflected over the Qur''an, or has there come to them that which had not come to their forefathers?', NULL, NULL, NULL, NULL, NULL, 'https://everyayah.com/data/Alafasy_128kbps/023068.mp3', now()),
  (23, 69, '', '[{"id":59119,"position":1,"text_uthmani":"أَمْ","transliteration":"am","translation_bn":"অথবা","root":"—","lemma":"أَم\r","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":59120,"position":2,"text_uthmani":"لَمْ","transliteration":"lam","translation_bn":"না","root":"—","lemma":"لَم\r","grammar_bn":"না-বোধক (Negative)"},{"id":59121,"position":3,"text_uthmani":"يَعْرِفُوا۟","transliteration":"yaʿrifū","translation_bn":"তারা চিনে","root":"عرف","lemma":"عَرَفَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":59122,"position":4,"text_uthmani":"رَسُولَهُمْ","transliteration":"rasūlahum","translation_bn":"তাদের রাসূলকে","root":"رسل","lemma":"رَسُول","grammar_bn":"বিশেষ্য (Noun)"},{"id":59123,"position":5,"text_uthmani":"فَهُمْ","transliteration":"fahum","translation_bn":"তাই তারা","root":"—","lemma":"فَهُمْ","grammar_bn":"শব্দ"},{"id":59124,"position":6,"text_uthmani":"لَهُۥ","transliteration":"lahu","translation_bn":"প্রতি তার","root":"—","lemma":"لَهُۥ","grammar_bn":"অব্যয় (Preposition)"},{"id":59125,"position":7,"text_uthmani":"مُنكِرُونَ","transliteration":"munkirūna","translation_bn":"অস্বীকারকারী হয়েছে","root":"نكر","lemma":"مُنكِرُون","grammar_bn":"বিশেষ্য (Noun)"},{"id":59126,"position":8,"text_uthmani":"٦٩","transliteration":"","translation_bn":"(৬৯)","root":"—","lemma":"٦٩","grammar_bn":"মার্কার"}]'::jsonb, 'am lam yaʿrifū rasūlahum fahum lahu munkirūna', 'কিংবা তারা কি তাদের রসূলকে চিনতে পারে না এজন্য তারা তাকে অস্বীকার করছে', 'Or did they not know their Messenger, so they are toward him disacknowledging?', 'কিংবা তারা কি তাদের রসূলকে চিনতে পারে না এজন্য তারা তাকে অস্বীকার করছে', 'Or did they not know their Messenger, so they are toward him disacknowledging?', NULL, NULL, NULL, NULL, NULL, 'https://everyayah.com/data/Alafasy_128kbps/023069.mp3', now()),
  (23, 70, '', '[{"id":59541,"position":1,"text_uthmani":"أَمْ","transliteration":"am","translation_bn":"অথবা","root":"—","lemma":"أَم\r","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":59542,"position":2,"text_uthmani":"يَقُولُونَ","transliteration":"yaqūlūna","translation_bn":"তারা বলে","root":"قول","lemma":"قَالَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":59543,"position":3,"text_uthmani":"بِهِۦ","transliteration":"bihi","translation_bn":"\"তার সাথে (আছে)","root":"—","lemma":"بِهِۦ","grammar_bn":"অব্যয় (Preposition)"},{"id":59544,"position":4,"text_uthmani":"جِنَّةٌۢ ۚ","transliteration":"jinnatun","translation_bn":"জ্বিন\"","root":"جنن","lemma":"جِنَّة","grammar_bn":"বিশেষ্য (Noun)"},{"id":59546,"position":5,"text_uthmani":"بَلْ","transliteration":"bal","translation_bn":"বরং","root":"—","lemma":"بَل\r","grammar_bn":"প্রত্যাহার পদ (Retraction)"},{"id":59547,"position":6,"text_uthmani":"جَآءَهُم","transliteration":"jāahum","translation_bn":"সে এসেছে তাদের (নিকট)","root":"جيا","lemma":"جَا^ءَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":59548,"position":7,"text_uthmani":"بِٱلْحَقِّ","transliteration":"bil-ḥaqi","translation_bn":"নিয়ে সত্যকে","root":"حقق","lemma":"حَقّ","grammar_bn":"অব্যয় (Preposition)"},{"id":59549,"position":8,"text_uthmani":"وَأَكْثَرُهُمْ","transliteration":"wa-aktharuhum","translation_bn":"অথচ অধিকাংশ তাদের","root":"كثر","lemma":"أَكْثَر","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":59550,"position":9,"text_uthmani":"لِلْحَقِّ","transliteration":"lil''ḥaqqi","translation_bn":"প্রতি সত্যের","root":"حقق","lemma":"حَقّ","grammar_bn":"অব্যয় (Preposition)"},{"id":59551,"position":10,"text_uthmani":"كَـٰرِهُونَ","transliteration":"kārihūna","translation_bn":"অপছন্দকারী","root":"كره","lemma":"كَٰرِهُون","grammar_bn":"বিশেষ্য (Noun)"},{"id":59552,"position":11,"text_uthmani":"٧٠","transliteration":"","translation_bn":"(৭০)","root":"—","lemma":"٧٠","grammar_bn":"মার্কার"}]'::jsonb, 'am yaqūlūna bihi jinnatun bal jāahum bil-ḥaqi wa-aktharuhum lil''ḥaqqi kārihūna', 'অথবা তারা কি বলে যে, সে উন্মাদ? না, প্রকৃতপক্ষে সে তাদের কাছে সত্য নিয়ে এসেছে, কিন্তু তাদের অধিকাংশই সত্যকে অপছন্দ করে।', 'Or do they say, "In him is madness?" Rather, he brought them the truth, but most of them, to the truth, are averse.', 'অথবা তারা কি বলে যে, সে উন্মাদ? না, প্রকৃতপক্ষে সে তাদের কাছে সত্য নিয়ে এসেছে, কিন্তু তাদের অধিকাংশই সত্যকে অপছন্দ করে।', 'Or do they say, "In him is madness?" Rather, he brought them the truth, but most of them, to the truth, are averse.', NULL, NULL, NULL, NULL, NULL, 'https://everyayah.com/data/Alafasy_128kbps/023070.mp3', now()),
  (23, 71, '', '[{"id":59998,"position":1,"text_uthmani":"وَلَوِ","transliteration":"walawi","translation_bn":"আর যদি","root":"—","lemma":"لَو\r","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":59999,"position":2,"text_uthmani":"ٱتَّبَعَ","transliteration":"ittabaʿa","translation_bn":"অনুসরণ করতো","root":"تبع","lemma":"ٱتَّبَعَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":60000,"position":3,"text_uthmani":"ٱلْحَقُّ","transliteration":"l-ḥaqu","translation_bn":"সত্য্","root":"حقق","lemma":"حَقّ","grammar_bn":"শব্দ"},{"id":60001,"position":4,"text_uthmani":"أَهْوَآءَهُمْ","transliteration":"ahwāahum","translation_bn":"কামনা-বাসনার তাদের","root":"هوي","lemma":"أَهْوَا^ء","grammar_bn":"বিশেষ্য (Noun)"},{"id":60002,"position":5,"text_uthmani":"لَفَسَدَتِ","transliteration":"lafasadati","translation_bn":"অবশ্যই বিশৃঙ্খল হয়ে পড়তো","root":"فسد","lemma":"فَسَدَتِ","grammar_bn":"দৃঢ়তাবোধক (Emphatic)"},{"id":60003,"position":6,"text_uthmani":"ٱلسَّمَـٰوَٰتُ","transliteration":"l-samāwātu","translation_bn":"আকাশমন্ডলি","root":"سمو","lemma":"سَمَا^ء","grammar_bn":"শব্দ"},{"id":60004,"position":7,"text_uthmani":"وَٱلْأَرْضُ","transliteration":"wal-arḍu","translation_bn":"ও পৃথিবী","root":"ارض","lemma":"أَرْض","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":60005,"position":8,"text_uthmani":"وَمَن","transliteration":"waman","translation_bn":"আর যাকিছু (আছে)","root":"—","lemma":"مَن\r","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":60006,"position":9,"text_uthmani":"فِيهِنَّ ۚ","transliteration":"fīhinna","translation_bn":"তাদের মাঝে","root":"—","lemma":"فِى\r","grammar_bn":"অব্যয় (Preposition)"},{"id":60008,"position":10,"text_uthmani":"بَلْ","transliteration":"bal","translation_bn":"বরং","root":"—","lemma":"بَل\r","grammar_bn":"প্রত্যাহার পদ (Retraction)"},{"id":60009,"position":11,"text_uthmani":"أَتَيْنَـٰهُم","transliteration":"ataynāhum","translation_bn":"তাদেরকে আমরা দিয়েছি","root":"اتي","lemma":"أَتَى","grammar_bn":"ক্রিয়া (Verb)"},{"id":60010,"position":12,"text_uthmani":"بِذِكْرِهِمْ","transliteration":"bidhik''rihim","translation_bn":"বিষয়কে তাদের উপদেশের (অর্থাৎ কুরআন)","root":"ذكر","lemma":"ذِكْر","grammar_bn":"অব্যয় (Preposition)"},{"id":60011,"position":13,"text_uthmani":"فَهُمْ","transliteration":"fahum","translation_bn":"কিন্তু তারা","root":"—","lemma":"فَهُمْ","grammar_bn":"শব্দ"},{"id":60012,"position":14,"text_uthmani":"عَن","transliteration":"ʿan","translation_bn":"হ''তে","root":"—","lemma":"عَن\r","grammar_bn":"অব্যয় (Preposition)"},{"id":60013,"position":15,"text_uthmani":"ذِكْرِهِم","transliteration":"dhik''rihim","translation_bn":"উপদেশ তাদের","root":"ذكر","lemma":"ذِكْر","grammar_bn":"বিশেষ্য (Noun)"},{"id":60014,"position":16,"text_uthmani":"مُّعْرِضُونَ","transliteration":"muʿ''riḍūna","translation_bn":"মুখ ফিরিয়ে নিচ্ছে","root":"عرض","lemma":"مُّعْرِضُون","grammar_bn":"বিশেষ্য (Noun)"},{"id":60015,"position":17,"text_uthmani":"٧١","transliteration":"","translation_bn":"(৭১)","root":"—","lemma":"٧١","grammar_bn":"মার্কার"}]'::jsonb, 'walawi ittabaʿa l-ḥaqu ahwāahum lafasadati l-samāwātu wal-arḍu waman fīhinna bal ataynāhum bidhik''rihim fahum ʿan dhik''rihim muʿ''riḍūna', 'সত্য যদি তাদের ইচ্ছে-আকাঙ্ক্ষার অনুসারী হত তাহলে আকাশ পৃথিবী আর এ দু’য়ের মাঝে যা আছে সব লন্ডভন্ড হয়ে যেত। (তাদের কামনা-বাসনার) বিপরীতে আমি তাদেরকে দিয়েছি তাদের জন্য উপদেশবাণী কিন্তু তারা উপদেশবাণী থেকে মুখ ফিরিয়ে রাখে।', 'But if the Truth had followed their inclinations, the heavens and the earth and whoever is in them would have been ruined. Rather, We have brought them their message, but they, from their message, are turning away.', 'সত্য যদি তাদের ইচ্ছে-আকাঙ্ক্ষার অনুসারী হত তাহলে আকাশ পৃথিবী আর এ দু’য়ের মাঝে যা আছে সব লন্ডভন্ড হয়ে যেত। (তাদের কামনা-বাসনার) বিপরীতে আমি তাদেরকে দিয়েছি তাদের জন্য উপদেশবাণী কিন্তু তারা উপদেশবাণী থেকে মুখ ফিরিয়ে রাখে।', 'But if the Truth had followed their inclinations, the heavens and the earth and whoever is in them would have been ruined. Rather, We have brought them their message, but they, from their message, are turning away.', NULL, NULL, NULL, NULL, NULL, 'https://everyayah.com/data/Alafasy_128kbps/023071.mp3', now()),
  (23, 72, '', '[{"id":60441,"position":1,"text_uthmani":"أَمْ","transliteration":"am","translation_bn":"অথবা কি","root":"—","lemma":"أَم\r","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":60442,"position":2,"text_uthmani":"تَسْـَٔلُهُمْ","transliteration":"tasaluhum","translation_bn":"তাদের (নিকট) তুমি চাচ্ছো","root":"سال","lemma":"سَأَلَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":60443,"position":3,"text_uthmani":"خَرْجًۭا","transliteration":"kharjan","translation_bn":"কোন প্রতিদান","root":"خرج","lemma":"خَرْج","grammar_bn":"বিশেষ্য (Noun)"},{"id":60444,"position":4,"text_uthmani":"فَخَرَاجُ","transliteration":"fakharāju","translation_bn":"অথচ প্রতিদান","root":"خرج","lemma":"خَرَاج","grammar_bn":"শব্দ"},{"id":60445,"position":5,"text_uthmani":"رَبِّكَ","transliteration":"rabbika","translation_bn":"তোমার রবেরই","root":"ربب","lemma":"رَبّ","grammar_bn":"বিশেষ্য (Noun)"},{"id":60446,"position":6,"text_uthmani":"خَيْرٌۭ ۖ","transliteration":"khayrun","translation_bn":"উত্তম","root":"خير","lemma":"خَيْر","grammar_bn":"বিশেষণ (Adjective)"},{"id":60448,"position":7,"text_uthmani":"وَهُوَ","transliteration":"wahuwa","translation_bn":"আর তিনিই","root":"—","lemma":"وَهُوَ","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":60449,"position":8,"text_uthmani":"خَيْرُ","transliteration":"khayru","translation_bn":"উত্তম","root":"خير","lemma":"خَيْر","grammar_bn":"বিশেষ্য (Noun)"},{"id":60450,"position":9,"text_uthmani":"ٱلرَّٰزِقِينَ","transliteration":"l-rāziqīna","translation_bn":"জীবিকাদাতাদের","root":"رزق","lemma":"رَّٰزِقِين","grammar_bn":"শব্দ"},{"id":60451,"position":10,"text_uthmani":"٧٢","transliteration":"","translation_bn":"(৭২)","root":"—","lemma":"٧٢","grammar_bn":"মার্কার"}]'::jsonb, 'am tasaluhum kharjan fakharāju rabbika khayrun wahuwa khayru l-rāziqīna', 'অথবা তুমি কি তাদের কাছ থেকে কোন প্রতিদান চাও? তোমার প্রতিপালকের প্রতিদানই সর্বোত্তম, আর তিনিই সর্বশ্রেষ্ঠ রিযকদাতা।', 'Or do you, [O Muhammad], ask them for payment? But the reward of your Lord is best, and He is the best of providers.', 'অথবা তুমি কি তাদের কাছ থেকে কোন প্রতিদান চাও? তোমার প্রতিপালকের প্রতিদানই সর্বোত্তম, আর তিনিই সর্বশ্রেষ্ঠ রিযকদাতা।', 'Or do you, [O Muhammad], ask them for payment? But the reward of your Lord is best, and He is the best of providers.', NULL, NULL, NULL, NULL, NULL, 'https://everyayah.com/data/Alafasy_128kbps/023072.mp3', now()),
  (23, 73, '', '[{"id":60888,"position":1,"text_uthmani":"وَإِنَّكَ","transliteration":"wa-innaka","translation_bn":"আর তুমি নিশ্চয়ই","root":"—","lemma":"إِنّ","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":60889,"position":2,"text_uthmani":"لَتَدْعُوهُمْ","transliteration":"latadʿūhum","translation_bn":"অবশ্যই ডাকছো তাদেরকে","root":"دعو","lemma":"دَعَا","grammar_bn":"দৃঢ়তাবোধক (Emphatic)"},{"id":60890,"position":3,"text_uthmani":"إِلَىٰ","transliteration":"ilā","translation_bn":"দিকে","root":"—","lemma":"إِلَىٰ\r","grammar_bn":"অব্যয় (Preposition)"},{"id":60891,"position":4,"text_uthmani":"صِرَٰطٍۢ","transliteration":"ṣirāṭin","translation_bn":"পথের","root":"صرط","lemma":"صِرَٰط","grammar_bn":"বিশেষ্য (Noun)"},{"id":60892,"position":5,"text_uthmani":"مُّسْتَقِيمٍۢ","transliteration":"mus''taqīmin","translation_bn":"সরল-সোজা","root":"قوم","lemma":"مُّسْتَقِيم","grammar_bn":"বিশেষ্য (Noun)"},{"id":60893,"position":6,"text_uthmani":"٧٣","transliteration":"","translation_bn":"(৭৩)","root":"—","lemma":"٧٣","grammar_bn":"মার্কার"}]'::jsonb, 'wa-innaka latadʿūhum ilā ṣirāṭin mus''taqīmin', 'তুমি তো নিশ্চিতই তাদেরকে সরল সুদৃঢ় পথের দিকে ডাকছ।', 'And indeed, you invite them to a straight path.', 'তুমি তো নিশ্চিতই তাদেরকে সরল সুদৃঢ় পথের দিকে ডাকছ।', 'And indeed, you invite them to a straight path.', NULL, NULL, NULL, NULL, NULL, 'https://everyayah.com/data/Alafasy_128kbps/023073.mp3', now()),
  (23, 74, '', '[{"id":61479,"position":1,"text_uthmani":"وَإِنَّ","transliteration":"wa-inna","translation_bn":"এবং নিশ্চয়ই","root":"—","lemma":"إِنّ","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":61480,"position":2,"text_uthmani":"ٱلَّذِينَ","transliteration":"alladhīna","translation_bn":"যারা","root":"—","lemma":"ٱلَّذِى","grammar_bn":"সাপেক্ষ সর্বনাম (Relative)"},{"id":61481,"position":3,"text_uthmani":"لَا","transliteration":"lā","translation_bn":"না","root":"—","lemma":"لَا\r","grammar_bn":"না-বোধক (Negative)"},{"id":61482,"position":4,"text_uthmani":"يُؤْمِنُونَ","transliteration":"yu''minūna","translation_bn":"ঈমান আনে","root":"امن","lemma":"ءَامَنَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":61483,"position":5,"text_uthmani":"بِٱلْـَٔاخِرَةِ","transliteration":"bil-ākhirati","translation_bn":"প্রতি আখিরাতের","root":"اخر","lemma":"ا^خِر","grammar_bn":"অব্যয় (Preposition)"},{"id":61484,"position":6,"text_uthmani":"عَنِ","transliteration":"ʿani","translation_bn":"(তারাই) হ''তে","root":"—","lemma":"عَن\r","grammar_bn":"অব্যয় (Preposition)"},{"id":61485,"position":7,"text_uthmani":"ٱلصِّرَٰطِ","transliteration":"l-ṣirāṭi","translation_bn":"সরল সঠিক পথ","root":"صرط","lemma":"صِرَٰط","grammar_bn":"শব্দ"},{"id":61486,"position":8,"text_uthmani":"لَنَـٰكِبُونَ","transliteration":"lanākibūna","translation_bn":"অবশ্যই বিচ্যুত","root":"نكب","lemma":"نَٰكِبُون","grammar_bn":"দৃঢ়তাবোধক (Emphatic)"},{"id":61487,"position":9,"text_uthmani":"٧٤","transliteration":"","translation_bn":"(৭৪)","root":"—","lemma":"٧٤","grammar_bn":"মার্কার"}]'::jsonb, 'wa-inna alladhīna lā yu''minūna bil-ākhirati ʿani l-ṣirāṭi lanākibūna', 'যারা আখিরাতে বিশ্বাস করে না তারা সরল পথ থেকে বিচ্যুত হয়ে গেছে।', 'But indeed, those who do not believe in the Hereafter are deviating from the path.', 'যারা আখিরাতে বিশ্বাস করে না তারা সরল পথ থেকে বিচ্যুত হয়ে গেছে।', 'But indeed, those who do not believe in the Hereafter are deviating from the path.', NULL, NULL, NULL, NULL, NULL, 'https://everyayah.com/data/Alafasy_128kbps/023074.mp3', now()),
  (23, 75, '', '[{"id":62278,"position":1,"text_uthmani":"۞ وَلَوْ","transliteration":"walaw","translation_bn":"আর যদি","root":"—","lemma":"لَو\r","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":62279,"position":2,"text_uthmani":"رَحِمْنَـٰهُمْ","transliteration":"raḥim''nāhum","translation_bn":"তাদেরকে আমরা দয়া করি","root":"رحم","lemma":"رَّحِمَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":62280,"position":3,"text_uthmani":"وَكَشَفْنَا","transliteration":"wakashafnā","translation_bn":"ও আমরা দূর করে দিই","root":"كشف","lemma":"كَشَفَ","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":62281,"position":4,"text_uthmani":"مَا","transliteration":"mā","translation_bn":"যা (আছে)","root":"—","lemma":"مَا\r","grammar_bn":"সাপেক্ষ সর্বনাম (Relative)"},{"id":62282,"position":5,"text_uthmani":"بِهِم","transliteration":"bihim","translation_bn":"উপর তাদের","root":"—","lemma":"بِهِم","grammar_bn":"অব্যয় (Preposition)"},{"id":62283,"position":6,"text_uthmani":"مِّن","transliteration":"min","translation_bn":"থেকে","root":"—","lemma":"مِن\r","grammar_bn":"অব্যয় (Preposition)"},{"id":62284,"position":7,"text_uthmani":"ضُرٍّۢ","transliteration":"ḍurrin","translation_bn":"দুঃখ কষ্ট (তবুও)","root":"ضرر","lemma":"ضُرّ","grammar_bn":"বিশেষ্য (Noun)"},{"id":62285,"position":8,"text_uthmani":"لَّلَجُّوا۟","transliteration":"lalajjū","translation_bn":"লেগে থাকবেই তারা","root":"لجج","lemma":"لَّجُّ","grammar_bn":"দৃঢ়তাবোধক (Emphatic)"},{"id":62286,"position":9,"text_uthmani":"فِى","transliteration":"fī","translation_bn":"মধ্যে","root":"—","lemma":"فِى\r","grammar_bn":"অব্যয় (Preposition)"},{"id":62287,"position":10,"text_uthmani":"طُغْيَـٰنِهِمْ","transliteration":"ṭugh''yānihim","translation_bn":"তাদের অবাধ্যতার","root":"طغي","lemma":"طُغْيَٰن","grammar_bn":"বিশেষ্য (Noun)"},{"id":62288,"position":11,"text_uthmani":"يَعْمَهُونَ","transliteration":"yaʿmahūna","translation_bn":"দিশেহারা হয়ে ঘুরবে","root":"عمه","lemma":"يَعْمَهُ","grammar_bn":"ক্রিয়া (Verb)"},{"id":62289,"position":12,"text_uthmani":"٧٥","transliteration":"","translation_bn":"(৭৫)","root":"—","lemma":"٧٥","grammar_bn":"মার্কার"}]'::jsonb, 'walaw raḥim''nāhum wakashafnā mā bihim min ḍurrin lalajjū fī ṭugh''yānihim yaʿmahūna', 'আমি তাদের প্রতি দয়া করলেও আর তাদের দুঃখ দুর্দশা দূর করলেও তারা তাদের অবাধ্যতায় ঘুরপাক খেতে থাকবে।', 'And even if We gave them mercy and removed what was upon them of affliction, they would persist in their transgression, wandering blindly.', 'আমি তাদের প্রতি দয়া করলেও আর তাদের দুঃখ দুর্দশা দূর করলেও তারা তাদের অবাধ্যতায় ঘুরপাক খেতে থাকবে।', 'And even if We gave them mercy and removed what was upon them of affliction, they would persist in their transgression, wandering blindly.', NULL, NULL, NULL, NULL, NULL, 'https://everyayah.com/data/Alafasy_128kbps/023075.mp3', now()),
  (23, 76, '', '[{"id":62426,"position":1,"text_uthmani":"وَلَقَدْ","transliteration":"walaqad","translation_bn":"এবং নিশ্চয়ই","root":"—","lemma":"قَد\r","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":62427,"position":2,"text_uthmani":"أَخَذْنَـٰهُم","transliteration":"akhadhnāhum","translation_bn":"তাদেরকে আমরা ধরেছি","root":"اخذ","lemma":"أَخَذَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":62428,"position":3,"text_uthmani":"بِٱلْعَذَابِ","transliteration":"bil-ʿadhābi","translation_bn":"দিয়ে শাস্তি","root":"عذب","lemma":"عَذَاب","grammar_bn":"অব্যয় (Preposition)"},{"id":62429,"position":4,"text_uthmani":"فَمَا","transliteration":"famā","translation_bn":"কিন্তু না","root":"—","lemma":"مَا\r","grammar_bn":"শব্দ"},{"id":62430,"position":5,"text_uthmani":"ٱسْتَكَانُوا۟","transliteration":"is''takānū","translation_bn":"তারা বিনত হলো","root":"كين","lemma":"ٱسْتَكَانُ","grammar_bn":"ক্রিয়া (Verb)"},{"id":62431,"position":6,"text_uthmani":"لِرَبِّهِمْ","transliteration":"lirabbihim","translation_bn":"প্রতি তাদের রবের","root":"ربب","lemma":"رَبّ","grammar_bn":"অব্যয় (Preposition)"},{"id":62432,"position":7,"text_uthmani":"وَمَا","transliteration":"wamā","translation_bn":"আর না","root":"—","lemma":"مَا\r","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":62433,"position":8,"text_uthmani":"يَتَضَرَّعُونَ","transliteration":"yataḍarraʿūna","translation_bn":"তারা কাতর প্রার্থনা করলো","root":"ضرع","lemma":"يَتَضَرَّعُ","grammar_bn":"ক্রিয়া (Verb)"},{"id":62434,"position":9,"text_uthmani":"٧٦","transliteration":"","translation_bn":"(৭৬)","root":"—","lemma":"٧٦","grammar_bn":"মার্কার"}]'::jsonb, 'walaqad akhadhnāhum bil-ʿadhābi famā is''takānū lirabbihim wamā yataḍarraʿūna', 'আমি তাদেরকে শাস্তি দ্বারা পাকড়াও করেছিলাম, কিন্তু তারা তাদের প্রতিপালকের নিকট নত হল না, আর তারা কাকুতি মিনতিও করল না।', 'And We had gripped them with suffering [as a warning], but they did not yield to their Lord, nor did they humbly supplicate, [and will continue thus]', 'আমি তাদেরকে শাস্তি দ্বারা পাকড়াও করেছিলাম, কিন্তু তারা তাদের প্রতিপালকের নিকট নত হল না, আর তারা কাকুতি মিনতিও করল না।', 'And We had gripped them with suffering [as a warning], but they did not yield to their Lord, nor did they humbly supplicate, [and will continue thus]', NULL, NULL, NULL, NULL, NULL, 'https://everyayah.com/data/Alafasy_128kbps/023076.mp3', now()),
  (23, 77, '', '[{"id":63184,"position":1,"text_uthmani":"حَتَّىٰٓ","transliteration":"ḥattā","translation_bn":"শেষ পর্যন্ত","root":"—","lemma":"حَتَّىٰ\r","grammar_bn":"অসম্পূর্ণ (Inceptive)"},{"id":63185,"position":2,"text_uthmani":"إِذَا","transliteration":"idhā","translation_bn":"যখন","root":"—","lemma":"إِذَا\r","grammar_bn":"কালবাচক (Time)"},{"id":63186,"position":3,"text_uthmani":"فَتَحْنَا","transliteration":"fataḥnā","translation_bn":"আমরা খুলে দিই","root":"فتح","lemma":"فَتَحَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":63187,"position":4,"text_uthmani":"عَلَيْهِم","transliteration":"ʿalayhim","translation_bn":"তাদের উপর","root":"—","lemma":"عَلَىٰ\r","grammar_bn":"অব্যয় (Preposition)"},{"id":63188,"position":5,"text_uthmani":"بَابًۭا","transliteration":"bāban","translation_bn":"দরজা","root":"بوب","lemma":"بَاب","grammar_bn":"বিশেষ্য (Noun)"},{"id":63189,"position":6,"text_uthmani":"ذَا","transliteration":"dhā","translation_bn":"সম্পন্ন","root":"—","lemma":"ذَا","grammar_bn":"বিশেষ্য (Noun)"},{"id":63190,"position":7,"text_uthmani":"عَذَابٍۢ","transliteration":"ʿadhābin","translation_bn":"শাস্তি","root":"عذب","lemma":"عَذَاب","grammar_bn":"বিশেষ্য (Noun)"},{"id":63191,"position":8,"text_uthmani":"شَدِيدٍ","transliteration":"shadīdin","translation_bn":"কঠিন","root":"شدد","lemma":"شَدِيد","grammar_bn":"বিশেষণ (Adjective)"},{"id":63192,"position":9,"text_uthmani":"إِذَا","transliteration":"idhā","translation_bn":"তখন","root":"—","lemma":"إِذَا\r","grammar_bn":"কালবাচক (Time)"},{"id":63193,"position":10,"text_uthmani":"هُمْ","transliteration":"hum","translation_bn":"তারা","root":"—","lemma":"هُمْ","grammar_bn":"সর্বনাম (Pronoun)"},{"id":63194,"position":11,"text_uthmani":"فِيهِ","transliteration":"fīhi","translation_bn":"তারা মধ্যে","root":"—","lemma":"فِى\r","grammar_bn":"অব্যয় (Preposition)"},{"id":63195,"position":12,"text_uthmani":"مُبْلِسُونَ","transliteration":"mub''lisūna","translation_bn":"হতাশ হয়ে পড়বে","root":"بلس","lemma":"مُبْلِسُون","grammar_bn":"বিশেষ্য (Noun)"},{"id":63196,"position":13,"text_uthmani":"٧٧","transliteration":"","translation_bn":"(৭৭)","root":"—","lemma":"٧٧","grammar_bn":"মার্কার"}]'::jsonb, 'ḥattā idhā fataḥnā ʿalayhim bāban dhā ʿadhābin shadīdin idhā hum fīhi mub''lisūna', 'অবশেষে আমি তাদের জন্য কঠিন শাস্তির দরজা খুলে দেব, তখন তারা তাতে হতাশ হয়ে পড়বে।', 'Until when We have opened before them a door of severe punishment, immediately they will be therein in despair.', 'অবশেষে আমি তাদের জন্য কঠিন শাস্তির দরজা খুলে দেব, তখন তারা তাতে হতাশ হয়ে পড়বে।', 'Until when We have opened before them a door of severe punishment, immediately they will be therein in despair.', NULL, NULL, NULL, NULL, NULL, 'https://everyayah.com/data/Alafasy_128kbps/023077.mp3', now()),
  (23, 78, '', '[{"id":63428,"position":1,"text_uthmani":"وَهُوَ","transliteration":"wahuwa","translation_bn":"এবং তিনিই (আল্লাহ)","root":"—","lemma":"وَهُوَ","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":63429,"position":2,"text_uthmani":"ٱلَّذِىٓ","transliteration":"alladhī","translation_bn":"যিনি","root":"—","lemma":"ٱلَّذِى","grammar_bn":"সাপেক্ষ সর্বনাম (Relative)"},{"id":63430,"position":3,"text_uthmani":"أَنشَأَ","transliteration":"ansha-a","translation_bn":"সৃষ্টি করেছেন","root":"نشا","lemma":"أَنشَأَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":63431,"position":4,"text_uthmani":"لَكُمُ","transliteration":"lakumu","translation_bn":"জন্যে তোমাদের","root":"—","lemma":"لَكُمُ","grammar_bn":"অব্যয় (Preposition)"},{"id":63432,"position":5,"text_uthmani":"ٱلسَّمْعَ","transliteration":"l-samʿa","translation_bn":"(শ্রবণশক্তির) কান","root":"سمع","lemma":"سَمْع","grammar_bn":"শব্দ"},{"id":63433,"position":6,"text_uthmani":"وَٱلْأَبْصَـٰرَ","transliteration":"wal-abṣāra","translation_bn":"ও (দর্শনশক্তির) চোখ","root":"بصر","lemma":"بَصَر","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":63434,"position":7,"text_uthmani":"وَٱلْأَفْـِٔدَةَ ۚ","transliteration":"wal-afidata","translation_bn":"হৃদয়","root":"فاد","lemma":"فُؤَاد","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":63436,"position":8,"text_uthmani":"قَلِيلًۭا","transliteration":"qalīlan","translation_bn":"কমই","root":"قلل","lemma":"قَلِيل","grammar_bn":"বিশেষণ (Adjective)"},{"id":63437,"position":9,"text_uthmani":"مَّا","transliteration":"mā","translation_bn":"যা","root":"—","lemma":"مَا\r","grammar_bn":"সাপেক্ষ সর্বনাম (Relative)"},{"id":63438,"position":10,"text_uthmani":"تَشْكُرُونَ","transliteration":"tashkurūna","translation_bn":"তোমরা কৃতজ্ঞতা প্রকাশ করো","root":"شكر","lemma":"شَكَرَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":63439,"position":11,"text_uthmani":"٧٨","transliteration":"","translation_bn":"(৭৮)","root":"—","lemma":"٧٨","grammar_bn":"মার্কার"}]'::jsonb, 'wahuwa alladhī ansha-a lakumu l-samʿa wal-abṣāra wal-afidata qalīlan mā tashkurūna', 'তিনিই তোমাদের জন্য সৃষ্টি করেছেন কান, চোখ ও অন্তর; তোমরা কৃতজ্ঞতা অল্পই করে থাক।', 'And it is He who produced for you hearing and vision and hearts; little are you grateful.', 'তিনিই তোমাদের জন্য সৃষ্টি করেছেন কান, চোখ ও অন্তর; তোমরা কৃতজ্ঞতা অল্পই করে থাক।', 'And it is He who produced for you hearing and vision and hearts; little are you grateful.', NULL, NULL, NULL, NULL, NULL, 'https://everyayah.com/data/Alafasy_128kbps/023078.mp3', now()),
  (23, 79, '', '[{"id":63770,"position":1,"text_uthmani":"وَهُوَ","transliteration":"wahuwa","translation_bn":"এবং তিনিই (আল্লাহ)","root":"—","lemma":"وَهُوَ","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":63771,"position":2,"text_uthmani":"ٱلَّذِى","transliteration":"alladhī","translation_bn":"যিনি","root":"—","lemma":"ٱلَّذِى","grammar_bn":"সাপেক্ষ সর্বনাম (Relative)"},{"id":63772,"position":3,"text_uthmani":"ذَرَأَكُمْ","transliteration":"dhara-akum","translation_bn":"তোমাদেরকে ছড়িয়ে দিয়েছেন","root":"ذرا","lemma":"ذَرَأَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":63773,"position":4,"text_uthmani":"فِى","transliteration":"fī","translation_bn":"মধ্যে","root":"—","lemma":"فِى\r","grammar_bn":"অব্যয় (Preposition)"},{"id":63774,"position":5,"text_uthmani":"ٱلْأَرْضِ","transliteration":"l-arḍi","translation_bn":"জমিনের","root":"ارض","lemma":"أَرْض","grammar_bn":"শব্দ"},{"id":63775,"position":6,"text_uthmani":"وَإِلَيْهِ","transliteration":"wa-ilayhi","translation_bn":"আর তাঁরই দিকে","root":"—","lemma":"إِلَىٰ\r","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":63776,"position":7,"text_uthmani":"تُحْشَرُونَ","transliteration":"tuḥ''sharūna","translation_bn":"তোমাদেরকে একত্র করা হবে","root":"حشر","lemma":"حَشَرَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":63777,"position":8,"text_uthmani":"٧٩","transliteration":"","translation_bn":"(৭৯)","root":"—","lemma":"٧٩","grammar_bn":"মার্কার"}]'::jsonb, 'wahuwa alladhī dhara-akum fī l-arḍi wa-ilayhi tuḥ''sharūna', 'তিনিই তোমাদেরকে পৃথিবীতে ছড়িয়ে দিয়েছেন আর তাঁর কাছেই তোমাদেরকে একত্রিত করা হবে।', 'And it is He who has multiplied you throughout the earth, and to Him you will be gathered.', 'তিনিই তোমাদেরকে পৃথিবীতে ছড়িয়ে দিয়েছেন আর তাঁর কাছেই তোমাদেরকে একত্রিত করা হবে।', 'And it is He who has multiplied you throughout the earth, and to Him you will be gathered.', NULL, NULL, NULL, NULL, NULL, 'https://everyayah.com/data/Alafasy_128kbps/023079.mp3', now()),
  (23, 80, '', '[{"id":64378,"position":1,"text_uthmani":"وَهُوَ","transliteration":"wahuwa","translation_bn":"এবং তিনিই (আল্লাহ)","root":"—","lemma":"وَهُوَ","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":64379,"position":2,"text_uthmani":"ٱلَّذِى","transliteration":"alladhī","translation_bn":"যিনি","root":"—","lemma":"ٱلَّذِى","grammar_bn":"সাপেক্ষ সর্বনাম (Relative)"},{"id":64380,"position":3,"text_uthmani":"يُحْىِۦ","transliteration":"yuḥ''yī","translation_bn":"জীবনদান করেন","root":"حيي","lemma":"أَحْيَا","grammar_bn":"ক্রিয়া (Verb)"},{"id":64381,"position":4,"text_uthmani":"وَيُمِيتُ","transliteration":"wayumītu","translation_bn":"ও মৃত্যু দেন","root":"موت","lemma":"أَمَاتَ","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":64382,"position":5,"text_uthmani":"وَلَهُ","transliteration":"walahu","translation_bn":"আর  রয়েছে তাঁরই (কর্তৃত্ব)","root":"—","lemma":"وَلَهُ","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":64383,"position":6,"text_uthmani":"ٱخْتِلَـٰفُ","transliteration":"ikh''tilāfu","translation_bn":"আবর্তন","root":"خلف","lemma":"ٱخْتِلَٰف","grammar_bn":"বিশেষ্য (Noun)"},{"id":64384,"position":7,"text_uthmani":"ٱلَّيْلِ","transliteration":"al-layli","translation_bn":"রাতের","root":"ليل","lemma":"لَيْل","grammar_bn":"শব্দ"},{"id":64385,"position":8,"text_uthmani":"وَٱلنَّهَارِ ۚ","transliteration":"wal-nahāri","translation_bn":"ও দিনের","root":"نهر","lemma":"نَهَار","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":64387,"position":9,"text_uthmani":"أَفَلَا","transliteration":"afalā","translation_bn":"কি তবুও না","root":"—","lemma":"لَا\r","grammar_bn":"প্রশ্নবোধক (Interrogative)"},{"id":64388,"position":10,"text_uthmani":"تَعْقِلُونَ","transliteration":"taʿqilūna","translation_bn":"তোমরা বুঝবে","root":"عقل","lemma":"عَقَلُ","grammar_bn":"ক্রিয়া (Verb)"},{"id":64389,"position":11,"text_uthmani":"٨٠","transliteration":"","translation_bn":"(৮০)","root":"—","lemma":"٨٠","grammar_bn":"মার্কার"}]'::jsonb, 'wahuwa alladhī yuḥ''yī wayumītu walahu ikh''tilāfu al-layli wal-nahāri afalā taʿqilūna', 'তিনিই জীবন দেন ও মৃত্যু ঘটান আর দিন-রাতের পরিবর্তন তাঁর দ্বারাই হয়, তবুও কি তোমরা বুঝবে না?', 'And it is He who gives life and causes death, and His is the alternation of the night and the day. Then will you not reason?', 'তিনিই জীবন দেন ও মৃত্যু ঘটান আর দিন-রাতের পরিবর্তন তাঁর দ্বারাই হয়, তবুও কি তোমরা বুঝবে না?', 'And it is He who gives life and causes death, and His is the alternation of the night and the day. Then will you not reason?', NULL, NULL, NULL, NULL, NULL, 'https://everyayah.com/data/Alafasy_128kbps/023080.mp3', now()),
  (23, 81, '', '[{"id":64860,"position":1,"text_uthmani":"بَلْ","transliteration":"bal","translation_bn":"বরং","root":"—","lemma":"بَل\r","grammar_bn":"প্রত্যাহার পদ (Retraction)"},{"id":64861,"position":2,"text_uthmani":"قَالُوا۟","transliteration":"qālū","translation_bn":"তারা বলে","root":"قول","lemma":"قَالَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":64862,"position":3,"text_uthmani":"مِثْلَ","transliteration":"mith''la","translation_bn":"তেমনই","root":"مثل","lemma":"مِثْل","grammar_bn":"বিশেষ্য (Noun)"},{"id":64863,"position":4,"text_uthmani":"مَا","transliteration":"mā","translation_bn":"যা","root":"—","lemma":"مَا\r","grammar_bn":"সাপেক্ষ সর্বনাম (Relative)"},{"id":64864,"position":5,"text_uthmani":"قَالَ","transliteration":"qāla","translation_bn":"বলেছিলো","root":"قول","lemma":"قَالَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":64865,"position":6,"text_uthmani":"ٱلْأَوَّلُونَ","transliteration":"l-awalūna","translation_bn":"পূর্ববর্তীরা","root":"اول","lemma":"أَوَّل","grammar_bn":"শব্দ"},{"id":64866,"position":7,"text_uthmani":"٨١","transliteration":"","translation_bn":"(৮১)","root":"—","lemma":"٨١","grammar_bn":"মার্কার"}]'::jsonb, 'bal qālū mith''la mā qāla l-awalūna', 'বরং তারা তাই বলেছিল যা বলেছিল আগের লোকেরা।', 'Rather, they say like what the former peoples said.', 'বরং তারা তাই বলেছিল যা বলেছিল আগের লোকেরা।', 'Rather, they say like what the former peoples said.', NULL, NULL, NULL, NULL, NULL, 'https://everyayah.com/data/Alafasy_128kbps/023081.mp3', now()),
  (23, 82, '', '[{"id":65052,"position":1,"text_uthmani":"قَالُوٓا۟","transliteration":"qālū","translation_bn":"তারা বলে","root":"قول","lemma":"قَالَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":65053,"position":2,"text_uthmani":"أَءِذَا","transliteration":"a-idhā","translation_bn":"\"কি যখন","root":"—","lemma":"إِذَا\r","grammar_bn":"প্রশ্নবোধক (Interrogative)"},{"id":65054,"position":3,"text_uthmani":"مِتْنَا","transliteration":"mit''nā","translation_bn":"আমরা মরে যাবো","root":"موت","lemma":"مَّاتَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":65055,"position":4,"text_uthmani":"وَكُنَّا","transliteration":"wakunnā","translation_bn":"ও আমরা হয়ে যাবো","root":"كون","lemma":"كَانَ","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":65056,"position":5,"text_uthmani":"تُرَابًۭا","transliteration":"turāban","translation_bn":"মাটি","root":"ترب","lemma":"تُرَاب","grammar_bn":"বিশেষ্য (Noun)"},{"id":65057,"position":6,"text_uthmani":"وَعِظَـٰمًا","transliteration":"waʿiẓāman","translation_bn":"ও হাড়","root":"عظم","lemma":"عَظِيم","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":65058,"position":7,"text_uthmani":"أَءِنَّا","transliteration":"a-innā","translation_bn":"কি নিশ্চয়ই আমরা","root":"—","lemma":"إِنّ","grammar_bn":"প্রশ্নবোধক (Interrogative)"},{"id":65059,"position":8,"text_uthmani":"لَمَبْعُوثُونَ","transliteration":"lamabʿūthūna","translation_bn":"অবশ্যই উত্থিত হবো","root":"بعث","lemma":"مَّبْعُوثُون","grammar_bn":"দৃঢ়তাবোধক (Emphatic)"},{"id":65060,"position":9,"text_uthmani":"٨٢","transliteration":"","translation_bn":"(৮২)","root":"—","lemma":"٨٢","grammar_bn":"মার্কার"}]'::jsonb, 'qālū a-idhā mit''nā wakunnā turāban waʿiẓāman a-innā lamabʿūthūna', 'তারা বলে- ‘আমরা যখন মরে মাটি ও হাড়-হাড্ডি হয়ে যাব (তারপরেও কি) আমাদেরকে আসলেই আবার উঠানো হবে?', 'They said, "When we have died and become dust and bones, are we indeed to be resurrected?', 'তারা বলে- ‘আমরা যখন মরে মাটি ও হাড়-হাড্ডি হয়ে যাব (তারপরেও কি) আমাদেরকে আসলেই আবার উঠানো হবে?', 'They said, "When we have died and become dust and bones, are we indeed to be resurrected?', NULL, NULL, NULL, NULL, NULL, 'https://everyayah.com/data/Alafasy_128kbps/023082.mp3', now()),
