  (23, 87, '', '[{"id":66739,"position":1,"text_uthmani":"سَيَقُولُونَ","transliteration":"sayaqūlūna","translation_bn":"তারা বলবে","root":"قول","lemma":"قَالَ","grammar_bn":"ভবিষ্যদ্বাচক (Future)"},{"id":66740,"position":2,"text_uthmani":"لِلَّهِ ۚ","transliteration":"lillahi","translation_bn":"\"জন্যে আল্লাহর (উলুহিয়াত)\"","root":"اله","lemma":"ٱللَّه","grammar_bn":"অব্যয় (Preposition)"},{"id":66742,"position":3,"text_uthmani":"قُلْ","transliteration":"qul","translation_bn":"বলো","root":"قول","lemma":"قَالَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":66743,"position":4,"text_uthmani":"أَفَلَا","transliteration":"afalā","translation_bn":"\"কি তবুও না","root":"—","lemma":"لَا\r","grammar_bn":"প্রশ্নবোধক (Interrogative)"},{"id":66744,"position":5,"text_uthmani":"تَتَّقُونَ","transliteration":"tattaqūna","translation_bn":"তোমরা ভয় করবে\"","root":"وقي","lemma":"ٱتَّقَىٰ","grammar_bn":"ক্রিয়া (Verb)"},{"id":66745,"position":6,"text_uthmani":"٨٧","transliteration":"","translation_bn":"(৮৭)","root":"—","lemma":"٨٧","grammar_bn":"মার্কার"}]'::jsonb, 'sayaqūlūna lillahi qul afalā tattaqūna', 'তারা বলবেঃ (এগুলোর মালিকানা) আল্লাহর। বলঃ তবুও কি তোমরা (আল্লাহকে) ভয় করবে না?', 'They will say, "[They belong] to Allah." Say, "Then will you not fear Him?"', 'তারা বলবেঃ (এগুলোর মালিকানা) আল্লাহর। বলঃ তবুও কি তোমরা (আল্লাহকে) ভয় করবে না?', 'They will say, "[They belong] to Allah." Say, "Then will you not fear Him?"', NULL, NULL, NULL, NULL, NULL, 'https://everyayah.com/data/Alafasy_128kbps/023087.mp3', now()),
  (23, 88, '', '[{"id":67184,"position":1,"text_uthmani":"قُلْ","transliteration":"qul","translation_bn":"বলো","root":"قول","lemma":"قَالَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":67185,"position":2,"text_uthmani":"مَنۢ","transliteration":"man","translation_bn":"কে (এমন)","root":"—","lemma":"مَن\r","grammar_bn":"সাপেক্ষ সর্বনাম (Relative)"},{"id":67186,"position":3,"text_uthmani":"بِيَدِهِۦ","transliteration":"biyadihi","translation_bn":"যার হাতে (রয়েছে)","root":"يدي","lemma":"يَد","grammar_bn":"অব্যয় (Preposition)"},{"id":67187,"position":4,"text_uthmani":"مَلَكُوتُ","transliteration":"malakūtu","translation_bn":"কর্তৃত্ব","root":"ملك","lemma":"مَلَكُوت","grammar_bn":"বিশেষ্য (Noun)"},{"id":67188,"position":5,"text_uthmani":"كُلِّ","transliteration":"kulli","translation_bn":"সব","root":"كلل","lemma":"كُلّ","grammar_bn":"বিশেষ্য (Noun)"},{"id":67189,"position":6,"text_uthmani":"شَىْءٍۢ","transliteration":"shayin","translation_bn":"কিছুর","root":"شيا","lemma":"شَىْء","grammar_bn":"বিশেষ্য (Noun)"},{"id":67190,"position":7,"text_uthmani":"وَهُوَ","transliteration":"wahuwa","translation_bn":"এবং তিনিই","root":"—","lemma":"وَهُوَ","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":67191,"position":8,"text_uthmani":"يُجِيرُ","transliteration":"yujīru","translation_bn":"আশ্রয় দেন","root":"جور","lemma":"يُجِيرُ","grammar_bn":"ক্রিয়া (Verb)"},{"id":67192,"position":9,"text_uthmani":"وَلَا","transliteration":"walā","translation_bn":"অথচ না","root":"—","lemma":"لَا\r","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":67193,"position":10,"text_uthmani":"يُجَارُ","transliteration":"yujāru","translation_bn":"আশ্রয় দিতে পারে কেউ","root":"جور","lemma":"يُجِيرُ","grammar_bn":"ক্রিয়া (Verb)"},{"id":67194,"position":11,"text_uthmani":"عَلَيْهِ","transliteration":"ʿalayhi","translation_bn":"তাঁর বিপক্ষে","root":"—","lemma":"عَلَىٰ\r","grammar_bn":"অব্যয় (Preposition)"},{"id":67195,"position":12,"text_uthmani":"إِن","transliteration":"in","translation_bn":"যদি","root":"—","lemma":"إِن\r","grammar_bn":"শর্তবাচক (Conditional)"},{"id":67196,"position":13,"text_uthmani":"كُنتُمْ","transliteration":"kuntum","translation_bn":"তোমরা থাকো","root":"كون","lemma":"كَانَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":67197,"position":14,"text_uthmani":"تَعْلَمُونَ","transliteration":"taʿlamūna","translation_bn":"তোমরা জেনে\"","root":"علم","lemma":"عَلِمَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":67198,"position":15,"text_uthmani":"٨٨","transliteration":"","translation_bn":"(৮৮)","root":"—","lemma":"٨٨","grammar_bn":"মার্কার"}]'::jsonb, 'qul man biyadihi malakūtu kulli shayin wahuwa yujīru walā yujāru ʿalayhi in kuntum taʿlamūna', 'বলঃ সব কিছুর একচ্ছত্র কর্তৃত্ব কার হাতে? তিনি (সকলকে) আশ্রয় দেন, তাঁর উপর কোন আশ্রয় দাতা নেই, (বল) তোমরা যদি জান।', 'Say, "In whose hand is the realm of all things - and He protects while none can protect against Him - if you should know?"', 'বলঃ সব কিছুর একচ্ছত্র কর্তৃত্ব কার হাতে? তিনি (সকলকে) আশ্রয় দেন, তাঁর উপর কোন আশ্রয় দাতা নেই, (বল) তোমরা যদি জান।', 'Say, "In whose hand is the realm of all things - and He protects while none can protect against Him - if you should know?"', NULL, NULL, NULL, NULL, NULL, 'https://everyayah.com/data/Alafasy_128kbps/023088.mp3', now()),
  (23, 89, '', '[{"id":67511,"position":1,"text_uthmani":"سَيَقُولُونَ","transliteration":"sayaqūlūna","translation_bn":"অচিরেই তারা বলবে","root":"قول","lemma":"قَالَ","grammar_bn":"ভবিষ্যদ্বাচক (Future)"},{"id":67512,"position":2,"text_uthmani":"لِلَّهِ ۚ","transliteration":"lillahi","translation_bn":"\"জন্যে আল্লাহ্‌রই\"","root":"اله","lemma":"ٱللَّه","grammar_bn":"অব্যয় (Preposition)"},{"id":67514,"position":3,"text_uthmani":"قُلْ","transliteration":"qul","translation_bn":"বলো","root":"قول","lemma":"قَالَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":67515,"position":4,"text_uthmani":"فَأَنَّىٰ","transliteration":"fa-annā","translation_bn":"\"তাহ''লে কোথা (হ''তে)","root":"اني\r","lemma":"أَنَّىٰ","grammar_bn":"শব্দ"},{"id":67516,"position":5,"text_uthmani":"تُسْحَرُونَ","transliteration":"tus''ḥarūna","translation_bn":"তোমাদেরকে জাদু করা হচ্ছে\"","root":"سحر","lemma":"سَحَرُ","grammar_bn":"ক্রিয়া (Verb)"},{"id":67517,"position":6,"text_uthmani":"٨٩","transliteration":"","translation_bn":"(৮৯)","root":"—","lemma":"٨٩","grammar_bn":"মার্কার"}]'::jsonb, 'sayaqūlūna lillahi qul fa-annā tus''ḥarūna', 'তারা বলবে (সকল কিছুর কর্তৃত্ব) আল্লাহর। তাহলে কেমন করে তোমরা যাদুগ্রস্ত হয়ে পড়ছ?', 'They will say, "[All belongs] to Allah." Say, "Then how are you deluded?"', 'তারা বলবে (সকল কিছুর কর্তৃত্ব) আল্লাহর। তাহলে কেমন করে তোমরা যাদুগ্রস্ত হয়ে পড়ছ?', 'They will say, "[All belongs] to Allah." Say, "Then how are you deluded?"', NULL, NULL, NULL, NULL, NULL, 'https://everyayah.com/data/Alafasy_128kbps/023089.mp3', now()),
  (23, 90, '', '[{"id":68087,"position":1,"text_uthmani":"بَلْ","transliteration":"bal","translation_bn":"বরং","root":"—","lemma":"بَل\r","grammar_bn":"প্রত্যাহার পদ (Retraction)"},{"id":68088,"position":2,"text_uthmani":"أَتَيْنَـٰهُم","transliteration":"ataynāhum","translation_bn":"আমরা এসেছি তাদের কাছে","root":"اتي","lemma":"أَتَى","grammar_bn":"ক্রিয়া (Verb)"},{"id":68089,"position":3,"text_uthmani":"بِٱلْحَقِّ","transliteration":"bil-ḥaqi","translation_bn":"নিয়ে মহাসত্যকে","root":"حقق","lemma":"حَقّ","grammar_bn":"অব্যয় (Preposition)"},{"id":68090,"position":4,"text_uthmani":"وَإِنَّهُمْ","transliteration":"wa-innahum","translation_bn":"আর নিশ্চয়ই তারা","root":"—","lemma":"إِنّ","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":68091,"position":5,"text_uthmani":"لَكَـٰذِبُونَ","transliteration":"lakādhibūna","translation_bn":"অবশ্যই মিথ্যাবাদী","root":"كذب","lemma":"كَٰذِب","grammar_bn":"দৃঢ়তাবোধক (Emphatic)"},{"id":68092,"position":6,"text_uthmani":"٩٠","transliteration":"","translation_bn":"(৯০)","root":"—","lemma":"٩٠","grammar_bn":"মার্কার"}]'::jsonb, 'bal ataynāhum bil-ḥaqi wa-innahum lakādhibūna', 'কিছুই না, আমি তাদের নিকট সত্য পাঠিয়েছি কিন্তু তারা বাস্তবিকই মিথ্যেবাদী।', 'Rather, We have brought them the truth, and indeed they are liars.', 'কিছুই না, আমি তাদের নিকট সত্য পাঠিয়েছি কিন্তু তারা বাস্তবিকই মিথ্যেবাদী।', 'Rather, We have brought them the truth, and indeed they are liars.', NULL, NULL, NULL, NULL, NULL, 'https://everyayah.com/data/Alafasy_128kbps/023090.mp3', now()),
  (23, 91, '', '[{"id":68409,"position":1,"text_uthmani":"مَا","transliteration":"mā","translation_bn":"নি","root":"—","lemma":"مَا\r","grammar_bn":"না-বোধক (Negative)"},{"id":68410,"position":2,"text_uthmani":"ٱتَّخَذَ","transliteration":"ittakhadha","translation_bn":"গ্রহণ করেন","root":"اخذ","lemma":"ٱتَّخَذَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":68411,"position":3,"text_uthmani":"ٱللَّهُ","transliteration":"l-lahu","translation_bn":"আল্লাহ","root":"اله","lemma":"ٱللَّه","grammar_bn":"নামবাচক বিশেষ্য (Proper Noun)"},{"id":68412,"position":4,"text_uthmani":"مِن","transliteration":"min","translation_bn":"(কাউকে) কোন","root":"—","lemma":"مِن\r","grammar_bn":"অব্যয় (Preposition)"},{"id":68413,"position":5,"text_uthmani":"وَلَدٍۢ","transliteration":"waladin","translation_bn":"সন্তান (হিসেবে)","root":"ولد","lemma":"وَلَد","grammar_bn":"বিশেষ্য (Noun)"},{"id":68414,"position":6,"text_uthmani":"وَمَا","transliteration":"wamā","translation_bn":"আর না","root":"—","lemma":"مَا\r","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":68415,"position":7,"text_uthmani":"كَانَ","transliteration":"kāna","translation_bn":"ছিলো (শরীক)","root":"كون","lemma":"كَانَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":68416,"position":8,"text_uthmani":"مَعَهُۥ","transliteration":"maʿahu","translation_bn":"তাঁর সাথে","root":"—","lemma":"مَع","grammar_bn":"স্থানবাচক (Location)"},{"id":68417,"position":9,"text_uthmani":"مِنْ","transliteration":"min","translation_bn":"কোন","root":"—","lemma":"مِن\r","grammar_bn":"অব্যয় (Preposition)"},{"id":68418,"position":10,"text_uthmani":"إِلَـٰهٍ ۚ","transliteration":"ilāhin","translation_bn":"ইলাহর","root":"اله","lemma":"إِلَٰه","grammar_bn":"বিশেষ্য (Noun)"},{"id":68420,"position":11,"text_uthmani":"إِذًۭا","transliteration":"idhan","translation_bn":"যদি হতো (তবে)","root":"—","lemma":"إِذًا\r","grammar_bn":"আশ্চর্যসূচক (Surprise)"},{"id":68421,"position":12,"text_uthmani":"لَّذَهَبَ","transliteration":"ladhahaba","translation_bn":"অবশ্যই নিয়ে যেতো","root":"ذهب","lemma":"ذَهَبَ","grammar_bn":"দৃঢ়তাবোধক (Emphatic)"},{"id":68422,"position":13,"text_uthmani":"كُلُّ","transliteration":"kullu","translation_bn":"প্রত্যেক","root":"كلل","lemma":"كُلّ","grammar_bn":"বিশেষ্য (Noun)"},{"id":68423,"position":14,"text_uthmani":"إِلَـٰهٍۭ","transliteration":"ilāhin","translation_bn":"ইলাহ","root":"اله","lemma":"إِلَٰه","grammar_bn":"বিশেষ্য (Noun)"},{"id":68424,"position":15,"text_uthmani":"بِمَا","transliteration":"bimā","translation_bn":"ঐসব যা কিছু","root":"—","lemma":"مَا\r","grammar_bn":"অব্যয় (Preposition)"},{"id":68425,"position":16,"text_uthmani":"خَلَقَ","transliteration":"khalaqa","translation_bn":"সে সৃষ্টি করেছে","root":"خلق","lemma":"خَلَقَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":68426,"position":17,"text_uthmani":"وَلَعَلَا","transliteration":"walaʿalā","translation_bn":"ও প্রাধান্য বিস্তার করতো","root":"علو","lemma":"تَعَٰلَىٰ","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":68427,"position":18,"text_uthmani":"بَعْضُهُمْ","transliteration":"baʿḍuhum","translation_bn":"তাদের একে","root":"بعض","lemma":"بَعْض","grammar_bn":"বিশেষ্য (Noun)"},{"id":68428,"position":19,"text_uthmani":"عَلَىٰ","transliteration":"ʿalā","translation_bn":"উপর","root":"—","lemma":"عَلَىٰ\r","grammar_bn":"অব্যয় (Preposition)"},{"id":68429,"position":20,"text_uthmani":"بَعْضٍۢ ۚ","transliteration":"baʿḍin","translation_bn":"অপরের","root":"بعض","lemma":"بَعْض","grammar_bn":"বিশেষ্য (Noun)"},{"id":68431,"position":21,"text_uthmani":"سُبْحَـٰنَ","transliteration":"sub''ḥāna","translation_bn":"পবিত্র","root":"سبح","lemma":"سُبْحَٰن","grammar_bn":"বিশেষ্য (Noun)"},{"id":68432,"position":22,"text_uthmani":"ٱللَّهِ","transliteration":"l-lahi","translation_bn":"আল্লাহ্‌","root":"اله","lemma":"ٱللَّه","grammar_bn":"নামবাচক বিশেষ্য (Proper Noun)"},{"id":68433,"position":23,"text_uthmani":"عَمَّا","transliteration":"ʿammā","translation_bn":"(তা) হ''তে যা","root":"—","lemma":"عَن\r","grammar_bn":"অব্যয় (Preposition)"},{"id":68434,"position":24,"text_uthmani":"يَصِفُونَ","transliteration":"yaṣifūna","translation_bn":"তারা রচনা করে","root":"وصف","lemma":"يَصِفُ","grammar_bn":"ক্রিয়া (Verb)"},{"id":68435,"position":25,"text_uthmani":"٩١","transliteration":"","translation_bn":"(৯১)","root":"—","lemma":"٩١","grammar_bn":"মার্কার"}]'::jsonb, 'mā ittakhadha l-lahu min waladin wamā kāna maʿahu min ilāhin idhan ladhahaba kullu ilāhin bimā khalaqa walaʿalā baʿḍuhum ʿalā baʿḍin sub''ḥāna l-lahi ʿammā yaṣifūna', 'আল্লাহ কোন সন্তান গ্রহণ করেননি, আর তাঁর সাথে অন্য কোন ইলাহ নেই, (থাকলে) প্রত্যেক ইলাহ আপন সৃষ্টি নিয়ে অবশ্যই চলে যেত, আর অবশ্যই একে অপরের উপর চড়াও হত, তারা তাঁর প্রতি যা আরোপ করে তাত্থেকে তিনি কত মহান ও পবিত্র!', 'Allah has not taken any son, nor has there ever been with Him any deity. [If there had been], then each deity would have taken what it created, and some of them would have sought to overcome others. Exalted is Allah above what they describe [concerning Him].', 'আল্লাহ কোন সন্তান গ্রহণ করেননি, আর তাঁর সাথে অন্য কোন ইলাহ নেই, (থাকলে) প্রত্যেক ইলাহ আপন সৃষ্টি নিয়ে অবশ্যই চলে যেত, আর অবশ্যই একে অপরের উপর চড়াও হত, তারা তাঁর প্রতি যা আরোপ করে তাত্থেকে তিনি কত মহান ও পবিত্র!', 'Allah has not taken any son, nor has there ever been with Him any deity. [If there had been], then each deity would have taken what it created, and some of them would have sought to overcome others. Exalted is Allah above what they describe [concerning Him].', NULL, NULL, NULL, NULL, NULL, 'https://everyayah.com/data/Alafasy_128kbps/023091.mp3', now()),
  (23, 92, '', '[{"id":68787,"position":1,"text_uthmani":"عَـٰلِمِ","transliteration":"ʿālimi","translation_bn":"অবহিত","root":"علم","lemma":"عَٰلِم","grammar_bn":"বিশেষ্য (Noun)"},{"id":68788,"position":2,"text_uthmani":"ٱلْغَيْبِ","transliteration":"l-ghaybi","translation_bn":"অদৃশ্যের","root":"غيب","lemma":"غَيْب","grammar_bn":"শব্দ"},{"id":68789,"position":3,"text_uthmani":"وَٱلشَّهَـٰدَةِ","transliteration":"wal-shahādati","translation_bn":"ও দৃশ্যের","root":"شهد","lemma":"شَهَٰدَة","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":68790,"position":4,"text_uthmani":"فَتَعَـٰلَىٰ","transliteration":"fataʿālā","translation_bn":"অতএব তিনি উর্দ্ধে","root":"علو","lemma":"تَعَٰلَىٰ","grammar_bn":"শব্দ"},{"id":68791,"position":5,"text_uthmani":"عَمَّا","transliteration":"ʿammā","translation_bn":"তা হ''তে যা কিছু","root":"—","lemma":"عَن\r","grammar_bn":"অব্যয় (Preposition)"},{"id":68792,"position":6,"text_uthmani":"يُشْرِكُونَ","transliteration":"yush''rikūna","translation_bn":"তারা শরীক করছে","root":"شرك","lemma":"أَشْرَكَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":68793,"position":7,"text_uthmani":"٩٢","transliteration":"","translation_bn":"(৯২)","root":"—","lemma":"٩٢","grammar_bn":"মার্কার"}]'::jsonb, 'ʿālimi l-ghaybi wal-shahādati fataʿālā ʿammā yush''rikūna', 'তিনি দৃশ্য ও অদৃশ্যের জ্ঞানের অধিকারী, তারা যা তাঁর শরীক বানায়, তাত্থেকে তিনি বহু ঊর্ধ্বে।', '[He is] Knower of the unseen and the witnessed, so high is He above what they associate [with Him].', 'তিনি দৃশ্য ও অদৃশ্যের জ্ঞানের অধিকারী, তারা যা তাঁর শরীক বানায়, তাত্থেকে তিনি বহু ঊর্ধ্বে।', '[He is] Knower of the unseen and the witnessed, so high is He above what they associate [with Him].', NULL, NULL, NULL, NULL, NULL, 'https://everyayah.com/data/Alafasy_128kbps/023092.mp3', now()),
  (23, 93, '', '[{"id":69266,"position":1,"text_uthmani":"قُل","transliteration":"qul","translation_bn":"বলো (দোয়া করো)","root":"قول","lemma":"قَالَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":69267,"position":2,"text_uthmani":"رَّبِّ","transliteration":"rabbi","translation_bn":"\"হে আমার রব","root":"ربب","lemma":"رَبّ","grammar_bn":"বিশেষ্য (Noun)"},{"id":69268,"position":3,"text_uthmani":"إِمَّا","transliteration":"immā","translation_bn":"যদি","root":"—","lemma":"إِمَّا\r","grammar_bn":"শব্দ"},{"id":69269,"position":4,"text_uthmani":"تُرِيَنِّى","transliteration":"turiyannī","translation_bn":"আমাকে দেখাও","root":"راي","lemma":"أَرَيْ","grammar_bn":"ক্রিয়া (Verb)"},{"id":69270,"position":5,"text_uthmani":"مَا","transliteration":"mā","translation_bn":"যা","root":"—","lemma":"مَا\r","grammar_bn":"সাপেক্ষ সর্বনাম (Relative)"},{"id":69271,"position":6,"text_uthmani":"يُوعَدُونَ","transliteration":"yūʿadūna","translation_bn":"তাদের প্রতিশ্রুতি দেয়া হচ্ছে","root":"وعد","lemma":"وَعَدَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":69272,"position":7,"text_uthmani":"٩٣","transliteration":"","translation_bn":"(৯৩)","root":"—","lemma":"٩٣","grammar_bn":"মার্কার"}]'::jsonb, 'qul rabbi immā turiyannī mā yūʿadūna', 'বল, ‘হে আমার প্রতিপালক! তুমি যদি আমাকে দেখাও (আমার জীবদ্দশায়) যার প্রতিশ্রুতি তাদেরকে দেয়া হয়েছে,', 'Say, [O Muhammad], "My Lord, if You should show me that which they are promised,', 'বল, ‘হে আমার প্রতিপালক! তুমি যদি আমাকে দেখাও (আমার জীবদ্দশায়) যার প্রতিশ্রুতি তাদেরকে দেয়া হয়েছে,', 'Say, [O Muhammad], "My Lord, if You should show me that which they are promised,', NULL, NULL, NULL, NULL, NULL, 'https://everyayah.com/data/Alafasy_128kbps/023093.mp3', now()),
  (23, 94, '', '[{"id":69664,"position":1,"text_uthmani":"رَبِّ","transliteration":"rabbi","translation_bn":"হে আমার রব","root":"ربب","lemma":"رَبّ","grammar_bn":"বিশেষ্য (Noun)"},{"id":69665,"position":2,"text_uthmani":"فَلَا","transliteration":"falā","translation_bn":"তবে না","root":"—","lemma":"لَا\r","grammar_bn":"শব্দ"},{"id":69666,"position":3,"text_uthmani":"تَجْعَلْنِى","transliteration":"tajʿalnī","translation_bn":"আমাকে করো তুমি","root":"جعل","lemma":"جَعَلَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":69667,"position":4,"text_uthmani":"فِى","transliteration":"fī","translation_bn":"অন্তর্ভুক্ত","root":"—","lemma":"فِى\r","grammar_bn":"অব্যয় (Preposition)"},{"id":69668,"position":5,"text_uthmani":"ٱلْقَوْمِ","transliteration":"l-qawmi","translation_bn":"সম্প্রদায়ের","root":"قوم","lemma":"قَوْم","grammar_bn":"শব্দ"},{"id":69669,"position":6,"text_uthmani":"ٱلظَّـٰلِمِينَ","transliteration":"l-ẓālimīna","translation_bn":"সীমালঙ্ঘনকারী\"","root":"ظلم","lemma":"ظَالِم","grammar_bn":"শব্দ"},{"id":69670,"position":7,"text_uthmani":"٩٤","transliteration":"","translation_bn":"(৯৪)","root":"—","lemma":"٩٤","grammar_bn":"মার্কার"}]'::jsonb, 'rabbi falā tajʿalnī fī l-qawmi l-ẓālimīna', 'তাহলে হে আমার প্রতিপালক! তুমি আমাকে যালিম সম্প্রদায়ের অন্তর্ভুক্ত করো না’।', 'My Lord, then do not place me among the wrongdoing people."', 'তাহলে হে আমার প্রতিপালক! তুমি আমাকে যালিম সম্প্রদায়ের অন্তর্ভুক্ত করো না’।', 'My Lord, then do not place me among the wrongdoing people."', NULL, NULL, NULL, NULL, NULL, 'https://everyayah.com/data/Alafasy_128kbps/023094.mp3', now()),
  (23, 95, '', '[{"id":69963,"position":1,"text_uthmani":"وَإِنَّا","transliteration":"wa-innā","translation_bn":"এবং নিশ্চয়ই আমরা","root":"—","lemma":"إِنّ","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":69964,"position":2,"text_uthmani":"عَلَىٰٓ","transliteration":"ʿalā","translation_bn":"এক্ষেত্রে","root":"—","lemma":"عَلَىٰ\r","grammar_bn":"অব্যয় (Preposition)"},{"id":69965,"position":3,"text_uthmani":"أَن","transliteration":"an","translation_bn":"যে","root":"—","lemma":"أَن\r","grammar_bn":"অধীনস্থ যোজক (Subordinating)"},{"id":69966,"position":4,"text_uthmani":"نُّرِيَكَ","transliteration":"nuriyaka","translation_bn":"তোমাকে দেখাবো আমরা","root":"راي","lemma":"أَرَيْ","grammar_bn":"ক্রিয়া (Verb)"},{"id":69967,"position":5,"text_uthmani":"مَا","transliteration":"mā","translation_bn":"যা","root":"—","lemma":"مَا\r","grammar_bn":"সাপেক্ষ সর্বনাম (Relative)"},{"id":69968,"position":6,"text_uthmani":"نَعِدُهُمْ","transliteration":"naʿiduhum","translation_bn":"আমরা প্রতিশ্রুতি দিয়েছি তাদেরকে","root":"وعد","lemma":"وَعَدَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":69969,"position":7,"text_uthmani":"لَقَـٰدِرُونَ","transliteration":"laqādirūna","translation_bn":"অবশ্যই (তা দেখাতে) সক্ষম","root":"قدر","lemma":"قَادِر","grammar_bn":"দৃঢ়তাবোধক (Emphatic)"},{"id":69970,"position":8,"text_uthmani":"٩٥","transliteration":"","translation_bn":"(৯৫)","root":"—","lemma":"٩٥","grammar_bn":"মার্কার"}]'::jsonb, 'wa-innā ʿalā an nuriyaka mā naʿiduhum laqādirūna', 'আমি তাদেরকে (শাস্তি প্রদানের) যে ওয়াদা করেছি তা আমি তোমাকে দেখাতে অবশ্যই সক্ষম।', 'And indeed, We are able to show you what We have promised them.', 'আমি তাদেরকে (শাস্তি প্রদানের) যে ওয়াদা করেছি তা আমি তোমাকে দেখাতে অবশ্যই সক্ষম।', 'And indeed, We are able to show you what We have promised them.', NULL, NULL, NULL, NULL, NULL, 'https://everyayah.com/data/Alafasy_128kbps/023095.mp3', now()),
  (23, 96, '', '[{"id":70021,"position":1,"text_uthmani":"ٱدْفَعْ","transliteration":"id''faʿ","translation_bn":"প্রতিহত করো","root":"دفع","lemma":"دَفَعْ","grammar_bn":"ক্রিয়া (Verb)"},{"id":70022,"position":2,"text_uthmani":"بِٱلَّتِى","transliteration":"bi-allatī","translation_bn":"দিয়ে তা","root":"—","lemma":"ٱلَّذِى","grammar_bn":"অব্যয় (Preposition)"},{"id":70023,"position":3,"text_uthmani":"هِىَ","transliteration":"hiya","translation_bn":"যা","root":"—","lemma":"هِىَ","grammar_bn":"সর্বনাম (Pronoun)"},{"id":70024,"position":4,"text_uthmani":"أَحْسَنُ","transliteration":"aḥsanu","translation_bn":"উত্তম","root":"حسن","lemma":"أَحْسَن","grammar_bn":"বিশেষ্য (Noun)"},{"id":70025,"position":5,"text_uthmani":"ٱلسَّيِّئَةَ ۚ","transliteration":"l-sayi-ata","translation_bn":"মন্দের (মোকাবিলায়)","root":"سوا","lemma":"سَيِّئَة","grammar_bn":"শব্দ"},{"id":70027,"position":6,"text_uthmani":"نَحْنُ","transliteration":"naḥnu","translation_bn":"আমরা","root":"—","lemma":"نَحْنُ","grammar_bn":"সর্বনাম (Pronoun)"},{"id":70028,"position":7,"text_uthmani":"أَعْلَمُ","transliteration":"aʿlamu","translation_bn":"খুব জানি","root":"علم","lemma":"أَعْلَم","grammar_bn":"বিশেষ্য (Noun)"},{"id":70029,"position":8,"text_uthmani":"بِمَا","transliteration":"bimā","translation_bn":"ঐ বিষয় যা","root":"—","lemma":"مَا\r","grammar_bn":"অব্যয় (Preposition)"},{"id":70030,"position":9,"text_uthmani":"يَصِفُونَ","transliteration":"yaṣifūna","translation_bn":"তারা বর্ণনা করে","root":"وصف","lemma":"يَصِفُ","grammar_bn":"ক্রিয়া (Verb)"},{"id":70031,"position":10,"text_uthmani":"٩٦","transliteration":"","translation_bn":"(৯৬)","root":"—","lemma":"٩٦","grammar_bn":"মার্কার"}]'::jsonb, 'id''faʿ bi-allatī hiya aḥsanu l-sayi-ata naḥnu aʿlamu bimā yaṣifūna', 'মন্দের মুকাবিলা কর যা উত্তম তাই দিয়ে, তারা যা বলে সে সম্পর্কে আমি সবিশেষ অবগত।', 'Repel, by [means of] what is best, [their] evil. We are most knowing of what they describe.', 'মন্দের মুকাবিলা কর যা উত্তম তাই দিয়ে, তারা যা বলে সে সম্পর্কে আমি সবিশেষ অবগত।', 'Repel, by [means of] what is best, [their] evil. We are most knowing of what they describe.', NULL, NULL, NULL, NULL, NULL, 'https://everyayah.com/data/Alafasy_128kbps/023096.mp3', now()),
  (23, 97, '', '[{"id":70334,"position":1,"text_uthmani":"وَقُل","transliteration":"waqul","translation_bn":"এবং বলো (দু''আ করো)","root":"قول","lemma":"قَالَ","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":70335,"position":2,"text_uthmani":"رَّبِّ","transliteration":"rabbi","translation_bn":"\"হে আমার রব","root":"ربب","lemma":"رَبّ","grammar_bn":"বিশেষ্য (Noun)"},{"id":70336,"position":3,"text_uthmani":"أَعُوذُ","transliteration":"aʿūdhu","translation_bn":"আমি আশ্রয় চাই","root":"عوذ","lemma":"عُذْ","grammar_bn":"ক্রিয়া (Verb)"},{"id":70337,"position":4,"text_uthmani":"بِكَ","transliteration":"bika","translation_bn":"তোমার নিকট","root":"—","lemma":"بِكَ","grammar_bn":"অব্যয় (Preposition)"},{"id":70338,"position":5,"text_uthmani":"مِنْ","transliteration":"min","translation_bn":"হ''তে","root":"—","lemma":"مِن\r","grammar_bn":"অব্যয় (Preposition)"},{"id":70339,"position":6,"text_uthmani":"هَمَزَٰتِ","transliteration":"hamazāti","translation_bn":"প্ররোচনা","root":"همز","lemma":"هَمَزَٰت","grammar_bn":"বিশেষ্য (Noun)"},{"id":70340,"position":7,"text_uthmani":"ٱلشَّيَـٰطِينِ","transliteration":"l-shayāṭīni","translation_bn":"শয়তানদের","root":"شطن","lemma":"شَيْطَٰن","grammar_bn":"শব্দ"},{"id":70341,"position":8,"text_uthmani":"٩٧","transliteration":"","translation_bn":"(৯৭)","root":"—","lemma":"٩٧","grammar_bn":"মার্কার"}]'::jsonb, 'waqul rabbi aʿūdhu bika min hamazāti l-shayāṭīni', 'আর বল : ‘হে আমার প্রতিপালক! আমি শয়ত্বানের কুমন্ত্রণা হতে তোমার নিকট আশ্রয় প্রার্থনা করছি।', 'And say, "My Lord, I seek refuge in You from the incitements of the devils,', 'আর বল : ‘হে আমার প্রতিপালক! আমি শয়ত্বানের কুমন্ত্রণা হতে তোমার নিকট আশ্রয় প্রার্থনা করছি।', 'And say, "My Lord, I seek refuge in You from the incitements of the devils,', NULL, NULL, NULL, NULL, NULL, 'https://everyayah.com/data/Alafasy_128kbps/023097.mp3', now()),
  (23, 98, '', '[{"id":70737,"position":1,"text_uthmani":"وَأَعُوذُ","transliteration":"wa-aʿūdhu","translation_bn":"ও আশ্রয় চাই আমি","root":"عوذ","lemma":"عُذْ","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":70738,"position":2,"text_uthmani":"بِكَ","transliteration":"bika","translation_bn":"নিকট তোমার","root":"—","lemma":"بِكَ","grammar_bn":"অব্যয় (Preposition)"},{"id":70739,"position":3,"text_uthmani":"رَبِّ","transliteration":"rabbi","translation_bn":"হে আমার রব","root":"ربب","lemma":"رَبّ","grammar_bn":"বিশেষ্য (Noun)"},{"id":70740,"position":4,"text_uthmani":"أَن","transliteration":"an","translation_bn":"যে","root":"—","lemma":"أَن\r","grammar_bn":"অধীনস্থ যোজক (Subordinating)"},{"id":70741,"position":5,"text_uthmani":"يَحْضُرُونِ","transliteration":"yaḥḍurūni","translation_bn":"আমার নিকট (শয়তান) উপস্থিত হবে\"","root":"حضر","lemma":"حَضَرَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":70742,"position":6,"text_uthmani":"٩٨","transliteration":"","translation_bn":"(৯৮)","root":"—","lemma":"٩٨","grammar_bn":"মার্কার"}]'::jsonb, 'wa-aʿūdhu bika rabbi an yaḥḍurūni', 'আর আমি তোমার নিকট আশ্রয় প্রার্থনা করছি, হে আমার প্রতিপালক! যাতে তারা আমার কাছে আসতে না পারে।’', 'And I seek refuge in You, my Lord, lest they be present with me."', 'আর আমি তোমার নিকট আশ্রয় প্রার্থনা করছি, হে আমার প্রতিপালক! যাতে তারা আমার কাছে আসতে না পারে।’', 'And I seek refuge in You, my Lord, lest they be present with me."', NULL, NULL, NULL, NULL, NULL, 'https://everyayah.com/data/Alafasy_128kbps/023098.mp3', now()),
  (23, 99, '', '[{"id":70925,"position":1,"text_uthmani":"حَتَّىٰٓ","transliteration":"ḥattā","translation_bn":"শেষ পর্যন্ত","root":"—","lemma":"حَتَّىٰ\r","grammar_bn":"অসম্পূর্ণ (Inceptive)"},{"id":70926,"position":2,"text_uthmani":"إِذَا","transliteration":"idhā","translation_bn":"যখন","root":"—","lemma":"إِذَا\r","grammar_bn":"কালবাচক (Time)"},{"id":70927,"position":3,"text_uthmani":"جَآءَ","transliteration":"jāa","translation_bn":"আসবে","root":"جيا","lemma":"جَا^ءَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":70928,"position":4,"text_uthmani":"أَحَدَهُمُ","transliteration":"aḥadahumu","translation_bn":"কারো তাদের","root":"احد","lemma":"أَحَد","grammar_bn":"বিশেষ্য (Noun)"},{"id":70929,"position":5,"text_uthmani":"ٱلْمَوْتُ","transliteration":"l-mawtu","translation_bn":"মৃত্যু","root":"موت","lemma":"مَوْت","grammar_bn":"শব্দ"},{"id":70930,"position":6,"text_uthmani":"قَالَ","transliteration":"qāla","translation_bn":"সে বলবে","root":"قول","lemma":"قَالَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":70931,"position":7,"text_uthmani":"رَبِّ","transliteration":"rabbi","translation_bn":"\"হে আমার রব","root":"ربب","lemma":"رَبّ","grammar_bn":"বিশেষ্য (Noun)"},{"id":70932,"position":8,"text_uthmani":"ٱرْجِعُونِ","transliteration":"ir''jiʿūni","translation_bn":"আমাকে ফেরত পাঠাও","root":"رجع","lemma":"رَجَعَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":70933,"position":9,"text_uthmani":"٩٩","transliteration":"","translation_bn":"(৯৯)","root":"—","lemma":"٩٩","grammar_bn":"মার্কার"}]'::jsonb, 'ḥattā idhā jāa aḥadahumu l-mawtu qāla rabbi ir''jiʿūni', 'এমনকি যখন তাদের কারো কাছে মৃত্যু এসে হাজির হয় তখন সে বলে : ‘হে আমার প্রতিপালক! আমাকে আবার (দুনিয়াতে) পাঠিয়ে দাও।', '[For such is the state of the disbelievers], until, when death comes to one of them, he says, "My Lord, send me back', 'এমনকি যখন তাদের কারো কাছে মৃত্যু এসে হাজির হয় তখন সে বলে : ‘হে আমার প্রতিপালক! আমাকে আবার (দুনিয়াতে) পাঠিয়ে দাও।', '[For such is the state of the disbelievers], until, when death comes to one of them, he says, "My Lord, send me back', NULL, NULL, NULL, NULL, NULL, 'https://everyayah.com/data/Alafasy_128kbps/023099.mp3', now()),
  (23, 100, '', '[{"id":71375,"position":1,"text_uthmani":"لَعَلِّىٓ","transliteration":"laʿallī","translation_bn":"যাতে আমি","root":"—","lemma":"لَّعَلّ","grammar_bn":"অভিঘাত পদ (Accusative)"},{"id":71376,"position":2,"text_uthmani":"أَعْمَلُ","transliteration":"aʿmalu","translation_bn":"কাজ করি","root":"عمل","lemma":"عَمِلَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":71377,"position":3,"text_uthmani":"صَـٰلِحًۭا","transliteration":"ṣāliḥan","translation_bn":"সৎ","root":"صلح","lemma":"صَٰلِح","grammar_bn":"বিশেষ্য (Noun)"},{"id":71378,"position":4,"text_uthmani":"فِيمَا","transliteration":"fīmā","translation_bn":"(তার) মধ্যে যা","root":"—","lemma":"فِى\r","grammar_bn":"অব্যয় (Preposition)"},{"id":71379,"position":5,"text_uthmani":"تَرَكْتُ ۚ","transliteration":"taraktu","translation_bn":"আমি ছেড়ে এসেছি\"","root":"ترك","lemma":"تَرَكَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":71381,"position":6,"text_uthmani":"كَلَّآ ۚ","transliteration":"kallā","translation_bn":"কখনও না","root":"—","lemma":"كَلَّا\r","grammar_bn":"অনিচ্ছা পদ (Aversion)"},{"id":71383,"position":7,"text_uthmani":"إِنَّهَا","transliteration":"innahā","translation_bn":"নিশ্চয়ই তা","root":"—","lemma":"إِنّ","grammar_bn":"অভিঘাত পদ (Accusative)"},{"id":71384,"position":8,"text_uthmani":"كَلِمَةٌ","transliteration":"kalimatun","translation_bn":"একটি কথা (মাত্র)","root":"كلم","lemma":"كَلِمَة","grammar_bn":"বিশেষ্য (Noun)"},{"id":71385,"position":9,"text_uthmani":"هُوَ","transliteration":"huwa","translation_bn":"সে","root":"—","lemma":"هُوَ","grammar_bn":"সর্বনাম (Pronoun)"},{"id":71386,"position":10,"text_uthmani":"قَآئِلُهَا ۖ","transliteration":"qāiluhā","translation_bn":"যার উক্তিকারী","root":"قول","lemma":"قَا^ئِل","grammar_bn":"বিশেষ্য (Noun)"},{"id":71388,"position":11,"text_uthmani":"وَمِن","transliteration":"wamin","translation_bn":"এবং থেকে","root":"—","lemma":"مِن\r","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":71389,"position":12,"text_uthmani":"وَرَآئِهِم","transliteration":"warāihim","translation_bn":"তাদের পিছনে (আছে)","root":"وري","lemma":"وَرَا^ء","grammar_bn":"বিশেষ্য (Noun)"},{"id":71390,"position":13,"text_uthmani":"بَرْزَخٌ","transliteration":"barzakhun","translation_bn":"অন্তরায়","root":"—","lemma":"بَرْزَخ","grammar_bn":"বিশেষ্য (Noun)"},{"id":71391,"position":14,"text_uthmani":"إِلَىٰ","transliteration":"ilā","translation_bn":"পর্যন্ত","root":"—","lemma":"إِلَىٰ\r","grammar_bn":"অব্যয় (Preposition)"},{"id":71392,"position":15,"text_uthmani":"يَوْمِ","transliteration":"yawmi","translation_bn":"সেদিন (যেদিন)","root":"يوم","lemma":"يَوْم","grammar_bn":"বিশেষ্য (Noun)"},{"id":71393,"position":16,"text_uthmani":"يُبْعَثُونَ","transliteration":"yub''ʿathūna","translation_bn":"তারা উত্থিত হবে","root":"بعث","lemma":"بَعَثَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":71394,"position":17,"text_uthmani":"١٠٠","transliteration":"","translation_bn":"(১০০)","root":"—","lemma":"١٠٠","grammar_bn":"মার্কার"}]'::jsonb, 'laʿallī aʿmalu ṣāliḥan fīmā taraktu kallā innahā kalimatun huwa qāiluhā wamin warāihim barzakhun ilā yawmi yub''ʿathūna', 'যাতে আমি সৎ কাজ করতে পারি যা আমি করিনি। কক্ষনো না, এটা তো তার একটা কথার কথা মাত্র। তাদের সামনে পর্দা থাকবে পুনরুত্থানের দিন পর্যন্ত।', 'That I might do righteousness in that which I left behind." No! It is only a word he is saying; and behind them is a barrier until the Day they are resurrected.', 'যাতে আমি সৎ কাজ করতে পারি যা আমি করিনি। কক্ষনো না, এটা তো তার একটা কথার কথা মাত্র। তাদের সামনে পর্দা থাকবে পুনরুত্থানের দিন পর্যন্ত।', 'That I might do righteousness in that which I left behind." No! It is only a word he is saying; and behind them is a barrier until the Day they are resurrected.', NULL, NULL, NULL, NULL, NULL, 'https://everyayah.com/data/Alafasy_128kbps/023100.mp3', now()),
  (23, 101, '', '[{"id":71755,"position":1,"text_uthmani":"فَإِذَا","transliteration":"fa-idhā","translation_bn":"অতঃপর যখন","root":"—","lemma":"إِذَا\r","grammar_bn":"শব্দ"},{"id":71756,"position":2,"text_uthmani":"نُفِخَ","transliteration":"nufikha","translation_bn":"ফুঁ দেয়া হবে","root":"نفخ","lemma":"نَفَخَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":71757,"position":3,"text_uthmani":"فِى","transliteration":"fī","translation_bn":"মধ্যে","root":"—","lemma":"فِى\r","grammar_bn":"অব্যয় (Preposition)"},{"id":71758,"position":4,"text_uthmani":"ٱلصُّورِ","transliteration":"l-ṣūri","translation_bn":"শিঙ্গার","root":"صور","lemma":"صُّور","grammar_bn":"শব্দ"},{"id":71759,"position":5,"text_uthmani":"فَلَآ","transliteration":"falā","translation_bn":"তখন না","root":"—","lemma":"لَا\r","grammar_bn":"শব্দ"},{"id":71760,"position":6,"text_uthmani":"أَنسَابَ","transliteration":"ansāba","translation_bn":"আত্মীয়তার বন্ধন (থাকবে)","root":"نسب","lemma":"نَسَب","grammar_bn":"বিশেষ্য (Noun)"},{"id":71761,"position":7,"text_uthmani":"بَيْنَهُمْ","transliteration":"baynahum","translation_bn":"মাঝে তাদের","root":"بين","lemma":"بَيْن","grammar_bn":"স্থানবাচক (Location)"},{"id":71762,"position":8,"text_uthmani":"يَوْمَئِذٍۢ","transliteration":"yawma-idhin","translation_bn":"সেদিন","root":"—","lemma":"يَوْمَئِذ\r","grammar_bn":"কালবাচক (Time)"},{"id":71763,"position":9,"text_uthmani":"وَلَا","transliteration":"walā","translation_bn":"আর না","root":"—","lemma":"لَا\r","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":71764,"position":10,"text_uthmani":"يَتَسَآءَلُونَ","transliteration":"yatasāalūna","translation_bn":"তারা পরস্পরে খোঁজখবর করবে","root":"سال","lemma":"يَتَسَا^ءَلُ","grammar_bn":"ক্রিয়া (Verb)"},{"id":71765,"position":11,"text_uthmani":"١٠١","transliteration":"","translation_bn":"(১০১)","root":"—","lemma":"١٠١","grammar_bn":"মার্কার"}]'::jsonb, 'fa-idhā nufikha fī l-ṣūri falā ansāba baynahum yawma-idhin walā yatasāalūna', 'অতঃপর যখন শিঙ্গায় ফুঁ দেয়া হবে সেদিন তাদের পরস্পরের মাঝে আত্মীয় বন্ধন থাকবে না। একে অপরের কাছে জিজ্ঞেসও করবে না।', 'So when the Horn is blown, no relationship will there be among them that Day, nor will they ask about one another.', 'অতঃপর যখন শিঙ্গায় ফুঁ দেয়া হবে সেদিন তাদের পরস্পরের মাঝে আত্মীয় বন্ধন থাকবে না। একে অপরের কাছে জিজ্ঞেসও করবে না।', 'So when the Horn is blown, no relationship will there be among them that Day, nor will they ask about one another.', NULL, NULL, NULL, NULL, NULL, 'https://everyayah.com/data/Alafasy_128kbps/023101.mp3', now()),
  (23, 102, '', '[{"id":71783,"position":1,"text_uthmani":"فَمَن","transliteration":"faman","translation_bn":"অতঃপর যার","root":"—","lemma":"مَن\r","grammar_bn":"শব্দ"},{"id":71784,"position":2,"text_uthmani":"ثَقُلَتْ","transliteration":"thaqulat","translation_bn":"ভারী হবে","root":"ثقل","lemma":"ثَقُلَتْ","grammar_bn":"ক্রিয়া (Verb)"},{"id":71785,"position":3,"text_uthmani":"مَوَٰزِينُهُۥ","transliteration":"mawāzīnuhu","translation_bn":"তার পাল্লা","root":"وزن","lemma":"مِيزَان","grammar_bn":"বিশেষ্য (Noun)"},{"id":71786,"position":4,"text_uthmani":"فَأُو۟لَـٰٓئِكَ","transliteration":"fa-ulāika","translation_bn":"তখন ঐসবলোক","root":"—","lemma":"أُولَٰ^ئِك","grammar_bn":"শব্দ"},{"id":71787,"position":5,"text_uthmani":"هُمُ","transliteration":"humu","translation_bn":"তারাই","root":"—","lemma":"هُمُ","grammar_bn":"সর্বনাম (Pronoun)"},{"id":71788,"position":6,"text_uthmani":"ٱلْمُفْلِحُونَ","transliteration":"l-muf''liḥūna","translation_bn":"সফলকাম (হবে)","root":"فلح","lemma":"مُفْلِحُون","grammar_bn":"শব্দ"},{"id":71789,"position":7,"text_uthmani":"١٠٢","transliteration":"","translation_bn":"(১০২)","root":"—","lemma":"١٠٢","grammar_bn":"মার্কার"}]'::jsonb, 'faman thaqulat mawāzīnuhu fa-ulāika humu l-muf''liḥūna', 'যাদের (সৎ কাজের) পাল্লা ভারী হবে তারাই হবে সফলকাম।', 'And those whose scales are heavy [with good deeds] - it is they who are the successful.', 'যাদের (সৎ কাজের) পাল্লা ভারী হবে তারাই হবে সফলকাম।', 'And those whose scales are heavy [with good deeds] - it is they who are the successful.', NULL, NULL, NULL, NULL, NULL, 'https://everyayah.com/data/Alafasy_128kbps/023102.mp3', now()),
  (23, 103, '', '[{"id":72322,"position":1,"text_uthmani":"وَمَنْ","transliteration":"waman","translation_bn":"আর যার","root":"—","lemma":"مَن\r","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":72323,"position":2,"text_uthmani":"خَفَّتْ","transliteration":"khaffat","translation_bn":"হালকা হবে","root":"خفف","lemma":"خَفَّتْ","grammar_bn":"ক্রিয়া (Verb)"},{"id":72324,"position":3,"text_uthmani":"مَوَٰزِينُهُۥ","transliteration":"mawāzīnuhu","translation_bn":"তার পাল্লা","root":"وزن","lemma":"مِيزَان","grammar_bn":"বিশেষ্য (Noun)"},{"id":72325,"position":4,"text_uthmani":"فَأُو۟لَـٰٓئِكَ","transliteration":"fa-ulāika","translation_bn":"অতঃপর ঐসবলোক (হবে)","root":"—","lemma":"أُولَٰ^ئِك","grammar_bn":"শব্দ"},{"id":72326,"position":5,"text_uthmani":"ٱلَّذِينَ","transliteration":"alladhīna","translation_bn":"(তারাই) যারা","root":"—","lemma":"ٱلَّذِى","grammar_bn":"সাপেক্ষ সর্বনাম (Relative)"},{"id":72327,"position":6,"text_uthmani":"خَسِرُوٓا۟","transliteration":"khasirū","translation_bn":"ক্ষতিগ্রস্ত করেছে","root":"خسر","lemma":"خَسِرَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":72328,"position":7,"text_uthmani":"أَنفُسَهُمْ","transliteration":"anfusahum","translation_bn":"তাদের নিজেদেরকে","root":"نفس","lemma":"نَفْس","grammar_bn":"বিশেষ্য (Noun)"},{"id":72329,"position":8,"text_uthmani":"فِى","transliteration":"fī","translation_bn":"মধ্যে","root":"—","lemma":"فِى\r","grammar_bn":"অব্যয় (Preposition)"},{"id":72330,"position":9,"text_uthmani":"جَهَنَّمَ","transliteration":"jahannama","translation_bn":"জাহান্নামের","root":"—","lemma":"جَهَنَّم","grammar_bn":"নামবাচক বিশেষ্য (Proper Noun)"},{"id":72331,"position":10,"text_uthmani":"خَـٰلِدُونَ","transliteration":"khālidūna","translation_bn":"তারা চিরস্থায়ী হবে (সেখানে)","root":"خلد","lemma":"خَٰلِد","grammar_bn":"বিশেষ্য (Noun)"},{"id":72332,"position":11,"text_uthmani":"١٠٣","transliteration":"","translation_bn":"(১০৩)","root":"—","lemma":"١٠٣","grammar_bn":"মার্কার"}]'::jsonb, 'waman khaffat mawāzīnuhu fa-ulāika alladhīna khasirū anfusahum fī jahannama khālidūna', 'যাদের পাল্লা হালকা হবে তারাই ওরা যারা নিজেদের ক্ষতিসাধন করেছে, জাহান্নামে তারা চিরস্থায়ী হবে।', 'But those whose scales are light - those are the ones who have lost their souls, [being] in Hell, abiding eternally.', 'যাদের পাল্লা হালকা হবে তারাই ওরা যারা নিজেদের ক্ষতিসাধন করেছে, জাহান্নামে তারা চিরস্থায়ী হবে।', 'But those whose scales are light - those are the ones who have lost their souls, [being] in Hell, abiding eternally.', NULL, NULL, NULL, NULL, NULL, 'https://everyayah.com/data/Alafasy_128kbps/023103.mp3', now()),
  (23, 104, '', '[{"id":72570,"position":1,"text_uthmani":"تَلْفَحُ","transliteration":"talfaḥu","translation_bn":"জ্বালিয়ে দিবে","root":"لفح","lemma":"تَلْفَحُ","grammar_bn":"ক্রিয়া (Verb)"},{"id":72571,"position":2,"text_uthmani":"وُجُوهَهُمُ","transliteration":"wujūhahumu","translation_bn":"তাদের মুখমন্ডলকে","root":"وجه","lemma":"وَجْه","grammar_bn":"বিশেষ্য (Noun)"},{"id":72572,"position":3,"text_uthmani":"ٱلنَّارُ","transliteration":"l-nāru","translation_bn":"আগুন","root":"نور","lemma":"نَار","grammar_bn":"শব্দ"},{"id":72573,"position":4,"text_uthmani":"وَهُمْ","transliteration":"wahum","translation_bn":"আর তারা","root":"—","lemma":"وَهُمْ","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":72574,"position":5,"text_uthmani":"فِيهَا","transliteration":"fīhā","translation_bn":"তার মধ্যে","root":"—","lemma":"فِى\r","grammar_bn":"অব্যয় (Preposition)"},{"id":72575,"position":6,"text_uthmani":"كَـٰلِحُونَ","transliteration":"kāliḥūna","translation_bn":"বীভৎস হবে (চেহারায়)","root":"كلح","lemma":"كَٰلِحُون","grammar_bn":"বিশেষ্য (Noun)"},{"id":72576,"position":7,"text_uthmani":"١٠٤","transliteration":"","translation_bn":"(১০৪)","root":"—","lemma":"١٠٤","grammar_bn":"মার্কার"}]'::jsonb, 'talfaḥu wujūhahumu l-nāru wahum fīhā kāliḥūna', 'আগুন তাদের মুখমন্ডল দগ্ধ করবে আর তারা বীভৎস চেহারা নিয়ে তার ভিতরে দাঁত কটমট করতে থাকবে।', 'The Fire will sear their faces, and they therein will have taut smiles.', 'আগুন তাদের মুখমন্ডল দগ্ধ করবে আর তারা বীভৎস চেহারা নিয়ে তার ভিতরে দাঁত কটমট করতে থাকবে।', 'The Fire will sear their faces, and they therein will have taut smiles.', NULL, NULL, NULL, NULL, NULL, 'https://everyayah.com/data/Alafasy_128kbps/023104.mp3', now()),
  (23, 105, '', '[{"id":72847,"position":1,"text_uthmani":"أَلَمْ","transliteration":"alam","translation_bn":"\"(বলা হবে) কি না","root":"—","lemma":"لَم\r","grammar_bn":"প্রশ্নবোধক (Interrogative)"},{"id":72848,"position":2,"text_uthmani":"تَكُنْ","transliteration":"takun","translation_bn":"\"হচ্ছিল","root":"كون","lemma":"كَانَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":72849,"position":3,"text_uthmani":"ءَايَـٰتِى","transliteration":"āyātī","translation_bn":"আমার আয়াতগুলোকে","root":"ايي","lemma":"ءَايَة","grammar_bn":"বিশেষ্য (Noun)"},{"id":72850,"position":4,"text_uthmani":"تُتْلَىٰ","transliteration":"tut''lā","translation_bn":"তিলাওয়াত করা হতো","root":"تلو","lemma":"تَلَىٰ","grammar_bn":"ক্রিয়া (Verb)"},{"id":72851,"position":5,"text_uthmani":"عَلَيْكُمْ","transliteration":"ʿalaykum","translation_bn":"তোমাদের নিকট","root":"—","lemma":"عَلَىٰ\r","grammar_bn":"অব্যয় (Preposition)"},{"id":72852,"position":6,"text_uthmani":"فَكُنتُم","transliteration":"fakuntum","translation_bn":"তখন তোমরা ছিলে","root":"كون","lemma":"كَانَ","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":72853,"position":7,"text_uthmani":"بِهَا","transliteration":"bihā","translation_bn":"সম্পর্কে তা\"","root":"—","lemma":"بِهَا","grammar_bn":"অব্যয় (Preposition)"},{"id":72854,"position":8,"text_uthmani":"تُكَذِّبُونَ","transliteration":"tukadhibūna","translation_bn":"মিথ্যারোপ করতে\"","root":"كذب","lemma":"كَذَّبَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":72855,"position":9,"text_uthmani":"١٠٥","transliteration":"","translation_bn":"(১০৫)","root":"—","lemma":"١٠٥","grammar_bn":"মার্কার"}]'::jsonb, 'alam takun āyātī tut''lā ʿalaykum fakuntum bihā tukadhibūna', '(তাদেরকে বলা হবে) ‘তোমাদের নিকট কি আমার আয়াতগুলো আবৃত্তি করা হত না? তোমরা সেগুলোকে মিথ্যে জেনে প্রত্যাখ্যান করেছিলে।', '[It will be said]. "Were not My verses recited to you and you used to deny them?"', '(তাদেরকে বলা হবে) ‘তোমাদের নিকট কি আমার আয়াতগুলো আবৃত্তি করা হত না? তোমরা সেগুলোকে মিথ্যে জেনে প্রত্যাখ্যান করেছিলে।', '[It will be said]. "Were not My verses recited to you and you used to deny them?"', NULL, NULL, NULL, NULL, NULL, 'https://everyayah.com/data/Alafasy_128kbps/023105.mp3', now()),
  (23, 106, '', '[{"id":73049,"position":1,"text_uthmani":"قَالُوا۟","transliteration":"qālū","translation_bn":"তারা বলবে","root":"قول","lemma":"قَالَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":73050,"position":2,"text_uthmani":"رَبَّنَا","transliteration":"rabbanā","translation_bn":"\"হে আমার রব","root":"ربب","lemma":"رَبّ","grammar_bn":"বিশেষ্য (Noun)"},{"id":73051,"position":3,"text_uthmani":"غَلَبَتْ","transliteration":"ghalabat","translation_bn":"বিজয় লাভ করেছিলো","root":"غلب","lemma":"غَلَبُ","grammar_bn":"ক্রিয়া (Verb)"},{"id":73052,"position":4,"text_uthmani":"عَلَيْنَا","transliteration":"ʿalaynā","translation_bn":"উপর আমাদের","root":"—","lemma":"عَلَىٰ\r","grammar_bn":"অব্যয় (Preposition)"},{"id":73053,"position":5,"text_uthmani":"شِقْوَتُنَا","transliteration":"shiq''watunā","translation_bn":"আমাদের দুর্ভাগ্য","root":"شقو","lemma":"شِقْوَت","grammar_bn":"বিশেষ্য (Noun)"},{"id":73054,"position":6,"text_uthmani":"وَكُنَّا","transliteration":"wakunnā","translation_bn":"এবং আমরা ছিলাম","root":"كون","lemma":"كَانَ","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":73055,"position":7,"text_uthmani":"قَوْمًۭا","transliteration":"qawman","translation_bn":"জাতি","root":"قوم","lemma":"قَوْم","grammar_bn":"বিশেষ্য (Noun)"},{"id":73056,"position":8,"text_uthmani":"ضَآلِّينَ","transliteration":"ḍāllīna","translation_bn":"পথভ্রষ্ট","root":"ضلل","lemma":"ضَا^لّ","grammar_bn":"বিশেষণ (Adjective)"},{"id":73057,"position":9,"text_uthmani":"١٠٦","transliteration":"","translation_bn":"(১০৬)","root":"—","lemma":"١٠٦","grammar_bn":"মার্কার"}]'::jsonb, 'qālū rabbanā ghalabat ʿalaynā shiq''watunā wakunnā qawman ḍāllīna', 'তারা বলবে- ‘হে আমাদের প্রতিপালক! দুর্ভাগ্য আমাদেরকে পরাস্ত করেছিল, আর আমরা ছিলাম এক পথভ্রষ্ট জাতি।', 'They will say, "Our Lord, our wretchedness overcame us, and we were a people astray.', 'তারা বলবে- ‘হে আমাদের প্রতিপালক! দুর্ভাগ্য আমাদেরকে পরাস্ত করেছিল, আর আমরা ছিলাম এক পথভ্রষ্ট জাতি।', 'They will say, "Our Lord, our wretchedness overcame us, and we were a people astray.', NULL, NULL, NULL, NULL, NULL, 'https://everyayah.com/data/Alafasy_128kbps/023106.mp3', now()),
  (23, 107, '', '[{"id":73187,"position":1,"text_uthmani":"رَبَّنَآ","transliteration":"rabbanā","translation_bn":"হে আমার রব","root":"ربب","lemma":"رَبّ","grammar_bn":"বিশেষ্য (Noun)"},{"id":73188,"position":2,"text_uthmani":"أَخْرِجْنَا","transliteration":"akhrij''nā","translation_bn":"আমাদেরকে বের করে দাও","root":"خرج","lemma":"أَخْرَجَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":73189,"position":3,"text_uthmani":"مِنْهَا","transliteration":"min''hā","translation_bn":"তা হ''তে","root":"—","lemma":"مِن\r","grammar_bn":"অব্যয় (Preposition)"},{"id":73190,"position":4,"text_uthmani":"فَإِنْ","transliteration":"fa-in","translation_bn":"অতঃপর যদি","root":"—","lemma":"إِن\r","grammar_bn":"শব্দ"},{"id":73191,"position":5,"text_uthmani":"عُدْنَا","transliteration":"ʿud''nā","translation_bn":"আমরা পুনরায় করি","root":"عود","lemma":"عَادَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":73192,"position":6,"text_uthmani":"فَإِنَّا","transliteration":"fa-innā","translation_bn":"তবে আমরা নিশ্চয়ই","root":"—","lemma":"إِنّ","grammar_bn":"শব্দ"},{"id":73193,"position":7,"text_uthmani":"ظَـٰلِمُونَ","transliteration":"ẓālimūna","translation_bn":"সীমালঙ্ঘনকারী (প্রমাণিত হবো)\"","root":"ظلم","lemma":"ظَالِم","grammar_bn":"বিশেষ্য (Noun)"},{"id":73194,"position":8,"text_uthmani":"١٠٧","transliteration":"","translation_bn":"(১০৭)","root":"—","lemma":"١٠٧","grammar_bn":"মার্কার"}]'::jsonb, 'rabbanā akhrij''nā min''hā fa-in ʿud''nā fa-innā ẓālimūna', 'হে আমাদের প্রতিপালক! আমাদেরকে এত্থেকে বের করে নাও, আমরা যদি আবার কুফুরী করি তাহলে আমরা তো যালিম হিসেবে পরিগণিত হব।', 'Our Lord, remove us from it, and if we were to return [to evil], we would indeed be wrongdoers."', 'হে আমাদের প্রতিপালক! আমাদেরকে এত্থেকে বের করে নাও, আমরা যদি আবার কুফুরী করি তাহলে আমরা তো যালিম হিসেবে পরিগণিত হব।', 'Our Lord, remove us from it, and if we were to return [to evil], we would indeed be wrongdoers."', NULL, NULL, NULL, NULL, NULL, 'https://everyayah.com/data/Alafasy_128kbps/023107.mp3', now()),
  (23, 108, '', '[{"id":73700,"position":1,"text_uthmani":"قَالَ","transliteration":"qāla","translation_bn":"তিনি বলবেন","root":"قول","lemma":"قَالَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":73701,"position":2,"text_uthmani":"ٱخْسَـُٔوا۟","transliteration":"ikh''saū","translation_bn":"\"পড়ে থাকো অপদস্হ হয়ে","root":"خسا","lemma":"ٱخْسَـ#ُ","grammar_bn":"ক্রিয়া (Verb)"},{"id":73702,"position":3,"text_uthmani":"فِيهَا","transliteration":"fīhā","translation_bn":"তার মধ্যে","root":"—","lemma":"فِى\r","grammar_bn":"অব্যয় (Preposition)"},{"id":73703,"position":4,"text_uthmani":"وَلَا","transliteration":"walā","translation_bn":"এবং না","root":"—","lemma":"لَا\r","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":73704,"position":5,"text_uthmani":"تُكَلِّمُونِ","transliteration":"tukallimūni","translation_bn":"আমার সাথে তোমরা কথা বলবে","root":"كلم","lemma":"كَلَّمَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":73705,"position":6,"text_uthmani":"١٠٨","transliteration":"","translation_bn":"(১০৮)","root":"—","lemma":"١٠٨","grammar_bn":"মার্কার"}]'::jsonb, 'qāla ikh''saū fīhā walā tukallimūni', 'আল্লাহ বলবেন- ‘তোমরা ধিকৃত অবস্থায় এখানেই পড়ে থাক, আমার সঙ্গে কোন কথা বল না।’', 'He will say, "Remain despised therein and do not speak to Me.', 'আল্লাহ বলবেন- ‘তোমরা ধিকৃত অবস্থায় এখানেই পড়ে থাক, আমার সঙ্গে কোন কথা বল না।’', 'He will say, "Remain despised therein and do not speak to Me.', NULL, NULL, NULL, NULL, NULL, 'https://everyayah.com/data/Alafasy_128kbps/023108.mp3', now()),
  (23, 109, '', '[{"id":73870,"position":1,"text_uthmani":"إِنَّهُۥ","transliteration":"innahu","translation_bn":"নিশ্চয়ই","root":"—","lemma":"إِنّ","grammar_bn":"অভিঘাত পদ (Accusative)"},{"id":73871,"position":2,"text_uthmani":"كَانَ","transliteration":"kāna","translation_bn":"ছিলো","root":"كون","lemma":"كَانَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":73872,"position":3,"text_uthmani":"فَرِيقٌۭ","transliteration":"farīqun","translation_bn":"একদল","root":"فرق","lemma":"فَرِيق","grammar_bn":"বিশেষ্য (Noun)"},{"id":73873,"position":4,"text_uthmani":"مِّنْ","transliteration":"min","translation_bn":"মধ্যে","root":"—","lemma":"مِن\r","grammar_bn":"অব্যয় (Preposition)"},{"id":73874,"position":5,"text_uthmani":"عِبَادِى","transliteration":"ʿibādī","translation_bn":"আমার দাসদের","root":"عبد","lemma":"عَبْد","grammar_bn":"বিশেষ্য (Noun)"},{"id":73875,"position":6,"text_uthmani":"يَقُولُونَ","transliteration":"yaqūlūna","translation_bn":"(যারা) বলতো","root":"قول","lemma":"قَالَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":73876,"position":7,"text_uthmani":"رَبَّنَآ","transliteration":"rabbanā","translation_bn":"\"হে আমাদের রব","root":"ربب","lemma":"رَبّ","grammar_bn":"বিশেষ্য (Noun)"},{"id":73877,"position":8,"text_uthmani":"ءَامَنَّا","transliteration":"āmannā","translation_bn":"আমরা ঈমান এনেছি","root":"امن","lemma":"ءَامَنَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":73878,"position":9,"text_uthmani":"فَٱغْفِرْ","transliteration":"fa-igh''fir","translation_bn":"তাই ক্ষমা করো","root":"غفر","lemma":"غَفَرَ","grammar_bn":"শব্দ"},{"id":73879,"position":10,"text_uthmani":"لَنَا","transliteration":"lanā","translation_bn":"আমাদেরকে","root":"—","lemma":"لَنَا","grammar_bn":"অব্যয় (Preposition)"},{"id":73880,"position":11,"text_uthmani":"وَٱرْحَمْنَا","transliteration":"wa-ir''ḥamnā","translation_bn":"ও আমাদের উপর দয়া করো","root":"رحم","lemma":"رَّحِمَ","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":73881,"position":12,"text_uthmani":"وَأَنتَ","transliteration":"wa-anta","translation_bn":"আর তুমিই","root":"—","lemma":"وَأَنتَ","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":73882,"position":13,"text_uthmani":"خَيْرُ","transliteration":"khayru","translation_bn":"অতি উত্তম","root":"خير","lemma":"خَيْر","grammar_bn":"বিশেষ্য (Noun)"},{"id":73883,"position":14,"text_uthmani":"ٱلرَّٰحِمِينَ","transliteration":"l-rāḥimīna","translation_bn":"দয়াকারীদের","root":"رحم","lemma":"رَّٰحِمِين","grammar_bn":"শব্দ"},{"id":73884,"position":15,"text_uthmani":"١٠٩","transliteration":"","translation_bn":"(১০৯)","root":"—","lemma":"١٠٩","grammar_bn":"মার্কার"}]'::jsonb, 'innahu kāna farīqun min ʿibādī yaqūlūna rabbanā āmannā fa-igh''fir lanā wa-ir''ḥamnā wa-anta khayru l-rāḥimīna', 'আমার বান্দাহদের একদল বলত- ‘হে আমাদের প্রতিপালক! আমরা ঈমান এনেছি, তুমি আমাদেরকে ক্ষমা কর, আমাদের প্রতি দয়া কর, তুমি তো সর্বশ্রেষ্ঠ দয়ালু।’', 'Indeed, there was a party of My servants who said, ''Our Lord, we have believed, so forgive us and have mercy upon us, and You are the best of the merciful.''', 'আমার বান্দাহদের একদল বলত- ‘হে আমাদের প্রতিপালক! আমরা ঈমান এনেছি, তুমি আমাদেরকে ক্ষমা কর, আমাদের প্রতি দয়া কর, তুমি তো সর্বশ্রেষ্ঠ দয়ালু।’', 'Indeed, there was a party of My servants who said, ''Our Lord, we have believed, so forgive us and have mercy upon us, and You are the best of the merciful.''', NULL, NULL, NULL, NULL, NULL, 'https://everyayah.com/data/Alafasy_128kbps/023109.mp3', now()),
  (23, 110, '', '[{"id":74041,"position":1,"text_uthmani":"فَٱتَّخَذْتُمُوهُمْ","transliteration":"fa-ittakhadhtumūhum","translation_bn":"তখন তোমরা গ্রহণ করেছিলে তাদেরকে","root":"اخذ","lemma":"ٱتَّخَذَ","grammar_bn":"শব্দ"},{"id":74042,"position":2,"text_uthmani":"سِخْرِيًّا","transliteration":"sikh''riyyan","translation_bn":"ঠাট্টার পাত্ররূপে","root":"سخر","lemma":"سِخْرِيّ","grammar_bn":"বিশেষ্য (Noun)"},{"id":74043,"position":3,"text_uthmani":"حَتَّىٰٓ","transliteration":"ḥattā","translation_bn":"এমনকি (তা)","root":"—","lemma":"حَتَّىٰ\r","grammar_bn":"অব্যয় (Preposition)"},{"id":74044,"position":4,"text_uthmani":"أَنسَوْكُمْ","transliteration":"ansawkum","translation_bn":"তোমাদেরকে ভুলিয়ে দিয়েছিলো","root":"نسي","lemma":"أَنسَىٰ","grammar_bn":"ক্রিয়া (Verb)"},{"id":74045,"position":5,"text_uthmani":"ذِكْرِى","transliteration":"dhik''rī","translation_bn":"আমার স্মরণ","root":"ذكر","lemma":"ذِكْر","grammar_bn":"বিশেষ্য (Noun)"},{"id":74046,"position":6,"text_uthmani":"وَكُنتُم","transliteration":"wakuntum","translation_bn":"আর তোমরা ছিলে","root":"كون","lemma":"كَانَ","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":74047,"position":7,"text_uthmani":"مِّنْهُمْ","transliteration":"min''hum","translation_bn":"সাথে তাদের","root":"—","lemma":"مِن\r","grammar_bn":"অব্যয় (Preposition)"},{"id":74048,"position":8,"text_uthmani":"تَضْحَكُونَ","transliteration":"taḍḥakūna","translation_bn":"ঠাট্টা-বিদ্রুপ করতে","root":"ضحك","lemma":"ضَحِكَتْ","grammar_bn":"ক্রিয়া (Verb)"},{"id":74049,"position":9,"text_uthmani":"١١٠","transliteration":"","translation_bn":"(১১০)","root":"—","lemma":"١١٠","grammar_bn":"মার্কার"}]'::jsonb, 'fa-ittakhadhtumūhum sikh''riyyan ḥattā ansawkum dhik''rī wakuntum min''hum taḍḥakūna', 'কিন্তু তাদেরকে নিয়ে তোমরা হাসি তামাশা করতে এমনকি তা তোমাদেরকে আমার কথা ভুলিয়ে দিয়েছিল, তোমরা তাদেরকে নিয়ে হাসি-ঠাট্টাই করতে।', 'But you took them in mockery to the point that they made you forget My remembrance, and you used to laugh at them.', 'কিন্তু তাদেরকে নিয়ে তোমরা হাসি তামাশা করতে এমনকি তা তোমাদেরকে আমার কথা ভুলিয়ে দিয়েছিল, তোমরা তাদেরকে নিয়ে হাসি-ঠাট্টাই করতে।', 'But you took them in mockery to the point that they made you forget My remembrance, and you used to laugh at them.', NULL, NULL, NULL, NULL, NULL, 'https://everyayah.com/data/Alafasy_128kbps/023110.mp3', now()),
  (23, 111, '', '[{"id":74468,"position":1,"text_uthmani":"إِنِّى","transliteration":"innī","translation_bn":"নিশ্চয়ই আমি","root":"—","lemma":"إِنّ","grammar_bn":"অভিঘাত পদ (Accusative)"},{"id":74469,"position":2,"text_uthmani":"جَزَيْتُهُمُ","transliteration":"jazaytuhumu","translation_bn":"আমি পুরস্কার দিলাম তাদেরকে","root":"جزي","lemma":"جَزَىٰ","grammar_bn":"ক্রিয়া (Verb)"},{"id":74470,"position":3,"text_uthmani":"ٱلْيَوْمَ","transliteration":"l-yawma","translation_bn":"আজ","root":"يوم","lemma":"يَوْم","grammar_bn":"শব্দ"},{"id":74471,"position":4,"text_uthmani":"بِمَا","transliteration":"bimā","translation_bn":"এ কারণে যে","root":"—","lemma":"مَا\r","grammar_bn":"অব্যয় (Preposition)"},{"id":74472,"position":5,"text_uthmani":"صَبَرُوٓا۟","transliteration":"ṣabarū","translation_bn":"তারা ধৈর্য ধরেছিলো","root":"صبر","lemma":"صَبَرَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":74473,"position":6,"text_uthmani":"أَنَّهُمْ","transliteration":"annahum","translation_bn":"(ফল এই) যে তারা","root":"—","lemma":"أَنّ","grammar_bn":"অভিঘাত পদ (Accusative)"},{"id":74474,"position":7,"text_uthmani":"هُمُ","transliteration":"humu","translation_bn":"তারাই","root":"—","lemma":"هُمُ","grammar_bn":"সর্বনাম (Pronoun)"},{"id":74475,"position":8,"text_uthmani":"ٱلْفَآئِزُونَ","transliteration":"l-fāizūna","translation_bn":"সফলকাম (হলো)","root":"فوز","lemma":"فَا^ئِزُون","grammar_bn":"শব্দ"},{"id":74476,"position":9,"text_uthmani":"١١١","transliteration":"","translation_bn":"(১১১)","root":"—","lemma":"١١١","grammar_bn":"মার্কার"}]'::jsonb, 'innī jazaytuhumu l-yawma bimā ṣabarū annahum humu l-fāizūna', 'আজ আমি তাদেরকে পুরস্কৃত করলাম তাদের ধৈর্য ধারণের কারণে, আজ তারাই তো সফলকাম।', 'Indeed, I have rewarded them this Day for their patient endurance - that they are the attainers [of success]."', 'আজ আমি তাদেরকে পুরস্কৃত করলাম তাদের ধৈর্য ধারণের কারণে, আজ তারাই তো সফলকাম।', 'Indeed, I have rewarded them this Day for their patient endurance - that they are the attainers [of success]."', NULL, NULL, NULL, NULL, NULL, 'https://everyayah.com/data/Alafasy_128kbps/023111.mp3', now()),
  (23, 112, '', '[{"id":74825,"position":1,"text_uthmani":"قَـٰلَ","transliteration":"qāla","translation_bn":"(আল্লাহ) বলবেন","root":"قول","lemma":"قَالَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":74826,"position":2,"text_uthmani":"كَمْ","transliteration":"kam","translation_bn":"\"কত (কাল)","root":"—","lemma":"كَم\r","grammar_bn":"প্রশ্নবোধক (Interrogative)"},{"id":74827,"position":3,"text_uthmani":"لَبِثْتُمْ","transliteration":"labith''tum","translation_bn":"তোমরা অবস্থান করেছিলে","root":"لبث","lemma":"لَبِثَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":74828,"position":4,"text_uthmani":"فِى","transliteration":"fī","translation_bn":"মধ্যে","root":"—","lemma":"فِى\r","grammar_bn":"অব্যয় (Preposition)"},{"id":74829,"position":5,"text_uthmani":"ٱلْأَرْضِ","transliteration":"l-arḍi","translation_bn":"পৃথিবীর","root":"ارض","lemma":"أَرْض","grammar_bn":"শব্দ"},{"id":74830,"position":6,"text_uthmani":"عَدَدَ","transliteration":"ʿadada","translation_bn":"হিসেবে","root":"عدد","lemma":"عَدَد","grammar_bn":"বিশেষ্য (Noun)"},{"id":74831,"position":7,"text_uthmani":"سِنِينَ","transliteration":"sinīna","translation_bn":"বছরের\"","root":"سنو","lemma":"سِنِين","grammar_bn":"বিশেষ্য (Noun)"},{"id":74832,"position":8,"text_uthmani":"١١٢","transliteration":"","translation_bn":"(১১২)","root":"—","lemma":"١١٢","grammar_bn":"মার্কার"}]'::jsonb, 'qāla kam labith''tum fī l-arḍi ʿadada sinīna', 'আল্লাহ বলবেন : ‘পৃথিবীতে কয় বছর তোমরা অবস্থান করেছিলে?’', '[Allah] will say, "How long did you remain on earth in number of years?"', 'আল্লাহ বলবেন : ‘পৃথিবীতে কয় বছর তোমরা অবস্থান করেছিলে?’', '[Allah] will say, "How long did you remain on earth in number of years?"', NULL, NULL, NULL, NULL, NULL, 'https://everyayah.com/data/Alafasy_128kbps/023112.mp3', now()),
  (23, 113, '', '[{"id":75022,"position":1,"text_uthmani":"قَالُوا۟","transliteration":"qālū","translation_bn":"তারা বলবে","root":"قول","lemma":"قَالَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":75023,"position":2,"text_uthmani":"لَبِثْنَا","transliteration":"labith''nā","translation_bn":"\"আমরা অবস্থান করেছিলাম","root":"لبث","lemma":"لَبِثَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":75024,"position":3,"text_uthmani":"يَوْمًا","transliteration":"yawman","translation_bn":"একদিন","root":"يوم","lemma":"يَوْم","grammar_bn":"বিশেষ্য (Noun)"},{"id":75025,"position":4,"text_uthmani":"أَوْ","transliteration":"aw","translation_bn":"অথবা","root":"—","lemma":"أَو\r","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":75026,"position":5,"text_uthmani":"بَعْضَ","transliteration":"baʿḍa","translation_bn":"কিছু অংশ","root":"بعض","lemma":"بَعْض","grammar_bn":"বিশেষ্য (Noun)"},{"id":75027,"position":6,"text_uthmani":"يَوْمٍۢ","transliteration":"yawmin","translation_bn":"দিনের","root":"يوم","lemma":"يَوْم","grammar_bn":"বিশেষ্য (Noun)"},{"id":75028,"position":7,"text_uthmani":"فَسْـَٔلِ","transliteration":"fasali","translation_bn":"তবে জিজ্ঞেস করুন","root":"سال","lemma":"سَأَلَ","grammar_bn":"শব্দ"},{"id":75029,"position":8,"text_uthmani":"ٱلْعَآدِّينَ","transliteration":"l-ʿādīna","translation_bn":"গণনাকারীদেরকে\"","root":"عدد","lemma":"عَا^دِّين","grammar_bn":"শব্দ"},{"id":75030,"position":9,"text_uthmani":"١١٣","transliteration":"","translation_bn":"(১১৩)","root":"—","lemma":"١١٣","grammar_bn":"মার্কার"}]'::jsonb, 'qālū labith''nā yawman aw baʿḍa yawmin fasali l-ʿādīna', 'তারা বলবে : ‘আমরা একদিন বা এক দিনের কিছু অংশ অবস্থান করেছি। অতএব তুমি গণনাকারীদের জিজ্ঞেস কর।’', 'They will say, "We remained a day or part of a day; ask those who enumerate."', 'তারা বলবে : ‘আমরা একদিন বা এক দিনের কিছু অংশ অবস্থান করেছি। অতএব তুমি গণনাকারীদের জিজ্ঞেস কর।’', 'They will say, "We remained a day or part of a day; ask those who enumerate."', NULL, NULL, NULL, NULL, NULL, 'https://everyayah.com/data/Alafasy_128kbps/023113.mp3', now()),
  (23, 114, '', '[{"id":75185,"position":1,"text_uthmani":"قَـٰلَ","transliteration":"qāla","translation_bn":"(আল্লাহ) বলবেন","root":"قول","lemma":"قَالَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":75186,"position":2,"text_uthmani":"إِن","transliteration":"in","translation_bn":"\"না","root":"—","lemma":"إِن\r","grammar_bn":"না-বোধক (Negative)"},{"id":75187,"position":3,"text_uthmani":"لَّبِثْتُمْ","transliteration":"labith''tum","translation_bn":"অবস্থান করেছিলে তোমরা","root":"لبث","lemma":"لَبِثَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":75188,"position":4,"text_uthmani":"إِلَّا","transliteration":"illā","translation_bn":"এ ছাড়া","root":"—","lemma":"إِلَّا\r","grammar_bn":"সীমাবদ্ধতা (Restriction)"},{"id":75189,"position":5,"text_uthmani":"قَلِيلًۭا ۖ","transliteration":"qalīlan","translation_bn":"অল্প (কালই)","root":"قلل","lemma":"قَلِيل","grammar_bn":"বিশেষ্য (Noun)"},{"id":75191,"position":6,"text_uthmani":"لَّوْ","transliteration":"law","translation_bn":"যদি","root":"—","lemma":"لَو\r","grammar_bn":"শর্তবাচক (Conditional)"},{"id":75192,"position":7,"text_uthmani":"أَنَّكُمْ","transliteration":"annakum","translation_bn":"(এমন হতো) যে তোমরা","root":"—","lemma":"أَنّ","grammar_bn":"অভিঘাত পদ (Accusative)"},{"id":75193,"position":8,"text_uthmani":"كُنتُمْ","transliteration":"kuntum","translation_bn":"তোমরা ছিলে","root":"كون","lemma":"كَانَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":75194,"position":9,"text_uthmani":"تَعْلَمُونَ","transliteration":"taʿlamūna","translation_bn":"তোমরা জানতে","root":"علم","lemma":"عَلِمَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":75195,"position":10,"text_uthmani":"١١٤","transliteration":"","translation_bn":"(১১৪)","root":"—","lemma":"١١٤","grammar_bn":"মার্কার"}]'::jsonb, 'qāla in labith''tum illā qalīlan law annakum kuntum taʿlamūna', 'তিনি বলবেন : ‘তোমরা অল্প সময়ই অবস্থান করেছিলে, তোমরা যদি জানতে!', 'He will say, "You stayed not but a little - if only you had known.', 'তিনি বলবেন : ‘তোমরা অল্প সময়ই অবস্থান করেছিলে, তোমরা যদি জানতে!', 'He will say, "You stayed not but a little - if only you had known.', NULL, NULL, NULL, NULL, NULL, 'https://everyayah.com/data/Alafasy_128kbps/023114.mp3', now()),
  (23, 115, '', '[{"id":75383,"position":1,"text_uthmani":"أَفَحَسِبْتُمْ","transliteration":"afaḥasib''tum","translation_bn":"কি তবে তোমরা মনে করেছিলে","root":"حسب","lemma":"حَسِبَ","grammar_bn":"প্রশ্নবোধক (Interrogative)"},{"id":75384,"position":2,"text_uthmani":"أَنَّمَا","transliteration":"annamā","translation_bn":"যে প্রকৃতপক্ষে","root":"—","lemma":"أَنّ","grammar_bn":"অভিঘাত পদ (Accusative)"},{"id":75385,"position":3,"text_uthmani":"خَلَقْنَـٰكُمْ","transliteration":"khalaqnākum","translation_bn":"তোমাদেরকে আমরা সৃষ্টি করেছি","root":"خلق","lemma":"خَلَقَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":75386,"position":4,"text_uthmani":"عَبَثًۭا","transliteration":"ʿabathan","translation_bn":"অনর্থক","root":"عبث","lemma":"عَبَث","grammar_bn":"বিশেষ্য (Noun)"},{"id":75387,"position":5,"text_uthmani":"وَأَنَّكُمْ","transliteration":"wa-annakum","translation_bn":"আর (এও বুঝেছিলে) যে তোমরা","root":"—","lemma":"أَنّ","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":75388,"position":6,"text_uthmani":"إِلَيْنَا","transliteration":"ilaynā","translation_bn":"আমাদের কাছে","root":"—","lemma":"إِلَىٰ\r","grammar_bn":"অব্যয় (Preposition)"},{"id":75389,"position":7,"text_uthmani":"لَا","transliteration":"lā","translation_bn":"না","root":"—","lemma":"لَا\r","grammar_bn":"না-বোধক (Negative)"},{"id":75390,"position":8,"text_uthmani":"تُرْجَعُونَ","transliteration":"tur''jaʿūna","translation_bn":"তোমরা প্রত্যাবর্তিত হবে\"","root":"رجع","lemma":"رَجَعَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":75391,"position":9,"text_uthmani":"١١٥","transliteration":"","translation_bn":"(১১৫)","root":"—","lemma":"١١٥","grammar_bn":"মার্কার"}]'::jsonb, 'afaḥasib''tum annamā khalaqnākum ʿabathan wa-annakum ilaynā lā tur''jaʿūna', 'তোমরা কি ভেবেছিলে যে, আমি তোমাদেরকে তামাশার বস্তু হিসেবে সৃষ্টি করেছি আর তোমাদেরকে আমার কাছে ফিরিয়ে আনা হবে না?', 'Then did you think that We created you uselessly and that to Us you would not be returned?"', 'তোমরা কি ভেবেছিলে যে, আমি তোমাদেরকে তামাশার বস্তু হিসেবে সৃষ্টি করেছি আর তোমাদেরকে আমার কাছে ফিরিয়ে আনা হবে না?', 'Then did you think that We created you uselessly and that to Us you would not be returned?"', NULL, NULL, NULL, NULL, NULL, 'https://everyayah.com/data/Alafasy_128kbps/023115.mp3', now()),
  (23, 116, '', '[{"id":75653,"position":1,"text_uthmani":"فَتَعَـٰلَى","transliteration":"fataʿālā","translation_bn":"অতএব মহান শ্রেষ্ঠ","root":"علو","lemma":"تَعَٰلَىٰ","grammar_bn":"শব্দ"},{"id":75654,"position":2,"text_uthmani":"ٱللَّهُ","transliteration":"l-lahu","translation_bn":"আল্লাহ","root":"اله","lemma":"ٱللَّه","grammar_bn":"নামবাচক বিশেষ্য (Proper Noun)"},{"id":75655,"position":3,"text_uthmani":"ٱلْمَلِكُ","transliteration":"l-maliku","translation_bn":"(যিনি) অধিপতি","root":"ملك","lemma":"مَلِك","grammar_bn":"শব্দ"},{"id":75656,"position":4,"text_uthmani":"ٱلْحَقُّ ۖ","transliteration":"l-ḥaqu","translation_bn":"প্রকৃত","root":"حقق","lemma":"حَقّ","grammar_bn":"শব্দ"},{"id":75658,"position":5,"text_uthmani":"لَآ","transliteration":"lā","translation_bn":"নেই","root":"—","lemma":"لَا\r","grammar_bn":"না-বোধক (Negative)"},{"id":75659,"position":6,"text_uthmani":"إِلَـٰهَ","transliteration":"ilāha","translation_bn":"কোন ইলাহ","root":"اله","lemma":"إِلَٰه","grammar_bn":"বিশেষ্য (Noun)"},{"id":75660,"position":7,"text_uthmani":"إِلَّا","transliteration":"illā","translation_bn":"ছাড়া","root":"—","lemma":"إِلَّا\r","grammar_bn":"সীমাবদ্ধতা (Restriction)"},{"id":75661,"position":8,"text_uthmani":"هُوَ","transliteration":"huwa","translation_bn":"তিনি","root":"—","lemma":"هُوَ","grammar_bn":"সর্বনাম (Pronoun)"},{"id":75662,"position":9,"text_uthmani":"رَبُّ","transliteration":"rabbu","translation_bn":"রব (মালিক)","root":"ربب","lemma":"رَبّ","grammar_bn":"বিশেষ্য (Noun)"},{"id":75663,"position":10,"text_uthmani":"ٱلْعَرْشِ","transliteration":"l-ʿarshi","translation_bn":"আরশের","root":"عرش","lemma":"عَرْش","grammar_bn":"শব্দ"},{"id":75664,"position":11,"text_uthmani":"ٱلْكَرِيمِ","transliteration":"l-karīmi","translation_bn":"মর্যাদাবান","root":"كرم","lemma":"كَرِيم","grammar_bn":"শব্দ"},{"id":75665,"position":12,"text_uthmani":"١١٦","transliteration":"","translation_bn":"(১১৬)","root":"—","lemma":"١١٦","grammar_bn":"মার্কার"}]'::jsonb, 'fataʿālā l-lahu l-maliku l-ḥaqu lā ilāha illā huwa rabbu l-ʿarshi l-karīmi', 'সুউচ্চ মহান আল্লাহ যিনি প্রকৃত মালিক, তিনি ছাড়া সত্যিকারের কোন ইলাহ নেই, সম্মানিত আরশের অধিপতি।', 'So exalted is Allah, the Sovereign, the Truth; there is no deity except Him, Lord of the Noble Throne.', 'সুউচ্চ মহান আল্লাহ যিনি প্রকৃত মালিক, তিনি ছাড়া সত্যিকারের কোন ইলাহ নেই, সম্মানিত আরশের অধিপতি।', 'So exalted is Allah, the Sovereign, the Truth; there is no deity except Him, Lord of the Noble Throne.', NULL, NULL, NULL, NULL, NULL, 'https://everyayah.com/data/Alafasy_128kbps/023116.mp3', now()),
  (23, 117, '', '[{"id":75821,"position":1,"text_uthmani":"وَمَن","transliteration":"waman","translation_bn":"আর যে কেউ","root":"—","lemma":"مَن\r","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":75822,"position":2,"text_uthmani":"يَدْعُ","transliteration":"yadʿu","translation_bn":"ডাকবে","root":"دعو","lemma":"دَعَا","grammar_bn":"ক্রিয়া (Verb)"},{"id":75823,"position":3,"text_uthmani":"مَعَ","transliteration":"maʿa","translation_bn":"সাথে","root":"—","lemma":"مَع","grammar_bn":"স্থানবাচক (Location)"},{"id":75824,"position":4,"text_uthmani":"ٱللَّهِ","transliteration":"l-lahi","translation_bn":"আল্লাহর","root":"اله","lemma":"ٱللَّه","grammar_bn":"নামবাচক বিশেষ্য (Proper Noun)"},{"id":75825,"position":5,"text_uthmani":"إِلَـٰهًا","transliteration":"ilāhan","translation_bn":"ইলাহ (হিসেবে)","root":"اله","lemma":"إِلَٰه","grammar_bn":"বিশেষ্য (Noun)"},{"id":75826,"position":6,"text_uthmani":"ءَاخَرَ","transliteration":"ākhara","translation_bn":"অন্য (কাউকে)","root":"اخر","lemma":"ا^خَر","grammar_bn":"বিশেষণ (Adjective)"},{"id":75827,"position":7,"text_uthmani":"لَا","transliteration":"lā","translation_bn":"নেই","root":"—","lemma":"لَا\r","grammar_bn":"না-বোধক (Negative)"},{"id":75828,"position":8,"text_uthmani":"بُرْهَـٰنَ","transliteration":"bur''hāna","translation_bn":"কোন প্রমাণ","root":"برهن","lemma":"بُرْهَٰن","grammar_bn":"বিশেষ্য (Noun)"},{"id":75829,"position":9,"text_uthmani":"لَهُۥ","transliteration":"lahu","translation_bn":"জন্যে তার","root":"—","lemma":"لَهُۥ","grammar_bn":"অব্যয় (Preposition)"},{"id":75830,"position":10,"text_uthmani":"بِهِۦ","transliteration":"bihi","translation_bn":"উপর এর","root":"—","lemma":"بِهِۦ","grammar_bn":"অব্যয় (Preposition)"},{"id":75831,"position":11,"text_uthmani":"فَإِنَّمَا","transliteration":"fa-innamā","translation_bn":"তবে প্রকৃতপক্ষে","root":"—","lemma":"إِنّ","grammar_bn":"শব্দ"},{"id":75832,"position":12,"text_uthmani":"حِسَابُهُۥ","transliteration":"ḥisābuhu","translation_bn":"তার হিসেব (হবে)","root":"حسب","lemma":"حِسَاب","grammar_bn":"বিশেষ্য (Noun)"},{"id":75833,"position":13,"text_uthmani":"عِندَ","transliteration":"ʿinda","translation_bn":"কাছে","root":"عند","lemma":"عِند","grammar_bn":"স্থানবাচক (Location)"},{"id":75834,"position":14,"text_uthmani":"رَبِّهِۦٓ ۚ","transliteration":"rabbihi","translation_bn":"তার রবের","root":"ربب","lemma":"رَبّ","grammar_bn":"বিশেষ্য (Noun)"},{"id":75836,"position":15,"text_uthmani":"إِنَّهُۥ","transliteration":"innahu","translation_bn":"নিশ্চয়ই","root":"—","lemma":"إِنّ","grammar_bn":"অভিঘাত পদ (Accusative)"},{"id":75837,"position":16,"text_uthmani":"لَا","transliteration":"lā","translation_bn":"না","root":"—","lemma":"لَا\r","grammar_bn":"না-বোধক (Negative)"},{"id":75838,"position":17,"text_uthmani":"يُفْلِحُ","transliteration":"yuf''liḥu","translation_bn":"সফলকাম হবে","root":"فلح","lemma":"أَفْلَحَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":75839,"position":18,"text_uthmani":"ٱلْكَـٰفِرُونَ","transliteration":"l-kāfirūna","translation_bn":"কাফিররা","root":"كفر","lemma":"كَٰفِرُون","grammar_bn":"শব্দ"},{"id":75840,"position":19,"text_uthmani":"١١٧","transliteration":"","translation_bn":"(১১৭)","root":"—","lemma":"١١٧","grammar_bn":"মার্কার"}]'::jsonb, 'waman yadʿu maʿa l-lahi ilāhan ākhara lā bur''hāna lahu bihi fa-innamā ḥisābuhu ʿinda rabbihi innahu lā yuf''liḥu l-kāfirūna', 'যে ব্যক্তি আল্লাহর সঙ্গে অন্য ইলাহকেও ডাকে, এ ব্যাপারে তার কাছে কোন দলীল প্রমাণ নেই, একমাত্র তার প্রতিপালকের কাছেই তার হিসাব হবে, কাফিরগণ অবশ্যই সফলকাম হবে না।', 'And whoever invokes besides Allah another deity for which he has no proof - then his account is only with his Lord. Indeed, the disbelievers will not succeed.', 'যে ব্যক্তি আল্লাহর সঙ্গে অন্য ইলাহকেও ডাকে, এ ব্যাপারে তার কাছে কোন দলীল প্রমাণ নেই, একমাত্র তার প্রতিপালকের কাছেই তার হিসাব হবে, কাফিরগণ অবশ্যই সফলকাম হবে না।', 'And whoever invokes besides Allah another deity for which he has no proof - then his account is only with his Lord. Indeed, the disbelievers will not succeed.', NULL, NULL, NULL, NULL, NULL, 'https://everyayah.com/data/Alafasy_128kbps/023117.mp3', now()),
  (23, 118, '', '[{"id":76095,"position":1,"text_uthmani":"وَقُل","transliteration":"waqul","translation_bn":"আর (হে নাবী) বলো","root":"قول","lemma":"قَالَ","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":76096,"position":2,"text_uthmani":"رَّبِّ","transliteration":"rabbi","translation_bn":"\"হে আমার রব","root":"ربب","lemma":"رَبّ","grammar_bn":"বিশেষ্য (Noun)"},{"id":76097,"position":3,"text_uthmani":"ٱغْفِرْ","transliteration":"igh''fir","translation_bn":"ক্ষমা করো","root":"غفر","lemma":"غَفَرَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":76098,"position":4,"text_uthmani":"وَٱرْحَمْ","transliteration":"wa-ir''ḥam","translation_bn":"আর দয়া করো","root":"رحم","lemma":"رَّحِمَ","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":76099,"position":5,"text_uthmani":"وَأَنتَ","transliteration":"wa-anta","translation_bn":"আর তুমিই","root":"—","lemma":"وَأَنتَ","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":76100,"position":6,"text_uthmani":"خَيْرُ","transliteration":"khayru","translation_bn":"উত্তম","root":"خير","lemma":"خَيْر","grammar_bn":"বিশেষ্য (Noun)"},{"id":76101,"position":7,"text_uthmani":"ٱلرَّٰحِمِينَ","transliteration":"l-rāḥimīna","translation_bn":"দয়াকারীদের","root":"رحم","lemma":"رَّٰحِمِين","grammar_bn":"শব্দ"},{"id":76102,"position":8,"text_uthmani":"١١٨","transliteration":"","translation_bn":"(১১৮)","root":"—","lemma":"١١٨","grammar_bn":"মার্কার"}]'::jsonb, 'waqul rabbi igh''fir wa-ir''ḥam wa-anta khayru l-rāḥimīna', 'কাজেই বল : ‘হে আমার প্রতিপালক! ক্ষমা কর ও রহম কর, তুমি রহমকারীদের মধ্যে সর্বশ্রেষ্ঠ।’', 'And, [O Muhammad], say, "My Lord, forgive and have mercy, and You are the best of the merciful."', 'কাজেই বল : ‘হে আমার প্রতিপালক! ক্ষমা কর ও রহম কর, তুমি রহমকারীদের মধ্যে সর্বশ্রেষ্ঠ।’', 'And, [O Muhammad], say, "My Lord, forgive and have mercy, and You are the best of the merciful."', NULL, NULL, NULL, NULL, NULL, 'https://everyayah.com/data/Alafasy_128kbps/023118.mp3', now())
