  (24, 1, '', '[{"id":663,"position":1,"text_uthmani":"سُورَةٌ","transliteration":"sūratun","translation_bn":"(এটা) একটি সূরা","root":"سور","lemma":"سُورَة","grammar_bn":"বিশেষ্য (Noun)"},{"id":664,"position":2,"text_uthmani":"أَنزَلْنَـٰهَا","transliteration":"anzalnāhā","translation_bn":"তা আমরা অবতীর্ণ করেছি","root":"نزل","lemma":"أَنزَلَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":665,"position":3,"text_uthmani":"وَفَرَضْنَـٰهَا","transliteration":"wafaraḍnāhā","translation_bn":"ও এর (বিধানকে) আমরা ফরজ করেছি","root":"فرض","lemma":"فَرَضَ","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":666,"position":4,"text_uthmani":"وَأَنزَلْنَا","transliteration":"wa-anzalnā","translation_bn":"এবং আমরা অবতীর্ণ করেছি","root":"نزل","lemma":"أَنزَلَ","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":667,"position":5,"text_uthmani":"فِيهَآ","transliteration":"fīhā","translation_bn":"তার মধ্যে","root":"—","lemma":"فِى\r","grammar_bn":"অব্যয় (Preposition)"},{"id":668,"position":6,"text_uthmani":"ءَايَـٰتٍۭ","transliteration":"āyātin","translation_bn":"আয়াতসমূহ","root":"ايي","lemma":"ءَايَة","grammar_bn":"বিশেষ্য (Noun)"},{"id":669,"position":7,"text_uthmani":"بَيِّنَـٰتٍۢ","transliteration":"bayyinātin","translation_bn":"সুস্পষ্ট","root":"بين","lemma":"بَيِّنَة","grammar_bn":"বিশেষণ (Adjective)"},{"id":670,"position":8,"text_uthmani":"لَّعَلَّكُمْ","transliteration":"laʿallakum","translation_bn":"সম্ভবতঃ তোমরা","root":"—","lemma":"لَعَلّ","grammar_bn":"অভিঘাত পদ (Accusative)"},{"id":671,"position":9,"text_uthmani":"تَذَكَّرُونَ","transliteration":"tadhakkarūna","translation_bn":"উপদেশ গ্রহণ করবে","root":"ذكر","lemma":"تَذَكَّرَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":672,"position":10,"text_uthmani":"١","transliteration":"","translation_bn":"(১)","root":"—","lemma":"١","grammar_bn":"মার্কার"}]'::jsonb, 'sūratun anzalnāhā wafaraḍnāhā wa-anzalnā fīhā āyātin bayyinātin laʿallakum tadhakkarūna', 'একটি সূরাহ যা আমি নাযিল করেছি আর তা ফরয করে দিয়েছি, আর তার ভেতরে আমি সুস্পষ্ট আয়াত নাযিল করেছি, যাতে তোমরা উপদেশ গ্রহণ কর।', '[This is] a surah which We have sent down and made [that within it] obligatory and revealed therein verses of clear evidence that you might remember.', 'একটি সূরাহ যা আমি নাযিল করেছি আর তা ফরয করে দিয়েছি, আর তার ভেতরে আমি সুস্পষ্ট আয়াত নাযিল করেছি, যাতে তোমরা উপদেশ গ্রহণ কর।', '[This is] a surah which We have sent down and made [that within it] obligatory and revealed therein verses of clear evidence that you might remember.', NULL, NULL, NULL, NULL, NULL, 'https://everyayah.com/data/Alafasy_128kbps/024001.mp3', now()),
  (24, 2, '', '[{"id":1662,"position":1,"text_uthmani":"ٱلزَّانِيَةُ","transliteration":"al-zāniyatu","translation_bn":"ব্যভিচারিণী","root":"زني","lemma":"زَانِيَة","grammar_bn":"শব্দ"},{"id":1663,"position":2,"text_uthmani":"وَٱلزَّانِى","transliteration":"wal-zānī","translation_bn":"ও ব্যভিচারী","root":"زني","lemma":"زَان","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":1664,"position":3,"text_uthmani":"فَٱجْلِدُوا۟","transliteration":"fa-ij''lidū","translation_bn":"অতঃপর তোমরা দোররা মারবে","root":"جلد","lemma":"ٱجْلِدُ","grammar_bn":"শব্দ"},{"id":1665,"position":4,"text_uthmani":"كُلَّ","transliteration":"kulla","translation_bn":"প্রত্যেক","root":"كلل","lemma":"كُلّ","grammar_bn":"বিশেষ্য (Noun)"},{"id":1666,"position":5,"text_uthmani":"وَٰحِدٍۢ","transliteration":"wāḥidin","translation_bn":"একজনকে","root":"وحد","lemma":"وَٰحِد","grammar_bn":"বিশেষণ (Adjective)"},{"id":1667,"position":6,"text_uthmani":"مِّنْهُمَا","transliteration":"min''humā","translation_bn":"তাদের দুজনার মধ্য হ''তে","root":"—","lemma":"مِن\r","grammar_bn":"অব্যয় (Preposition)"},{"id":1668,"position":7,"text_uthmani":"مِا۟ئَةَ","transliteration":"mi-ata","translation_bn":"একশত","root":"ماي","lemma":"مِائَة","grammar_bn":"বিশেষ্য (Noun)"},{"id":1669,"position":8,"text_uthmani":"جَلْدَةٍۢ ۖ","transliteration":"jaldatin","translation_bn":"দোররা","root":"جلد","lemma":"جَلْدَة","grammar_bn":"বিশেষ্য (Noun)"},{"id":1671,"position":9,"text_uthmani":"وَلَا","transliteration":"walā","translation_bn":"আর না (যেন)","root":"—","lemma":"لَا\r","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":1672,"position":10,"text_uthmani":"تَأْخُذْكُم","transliteration":"takhudh''kum","translation_bn":"তোমাদেরকে প্রভাবিত করে","root":"اخذ","lemma":"أَخَذَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":1673,"position":11,"text_uthmani":"بِهِمَا","transliteration":"bihimā","translation_bn":"প্রতি তাদের দু''জনের","root":"—","lemma":"بِهِمَا","grammar_bn":"অব্যয় (Preposition)"},{"id":1674,"position":12,"text_uthmani":"رَأْفَةٌۭ","transliteration":"rafatun","translation_bn":"দয়া অনুকম্পা","root":"راف","lemma":"رَأْفَة","grammar_bn":"বিশেষ্য (Noun)"},{"id":1675,"position":13,"text_uthmani":"فِى","transliteration":"fī","translation_bn":"ব্যাপারে","root":"—","lemma":"فِى\r","grammar_bn":"অব্যয় (Preposition)"},{"id":1676,"position":14,"text_uthmani":"دِينِ","transliteration":"dīni","translation_bn":"দ্বীনের","root":"دين","lemma":"دِين","grammar_bn":"বিশেষ্য (Noun)"},{"id":1677,"position":15,"text_uthmani":"ٱللَّهِ","transliteration":"l-lahi","translation_bn":"আল্লাহর","root":"اله","lemma":"ٱللَّه","grammar_bn":"নামবাচক বিশেষ্য (Proper Noun)"},{"id":1678,"position":16,"text_uthmani":"إِن","transliteration":"in","translation_bn":"যদি","root":"—","lemma":"إِن\r","grammar_bn":"শর্তবাচক (Conditional)"},{"id":1679,"position":17,"text_uthmani":"كُنتُمْ","transliteration":"kuntum","translation_bn":"তোমরা থাকো","root":"كون","lemma":"كَانَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":1680,"position":18,"text_uthmani":"تُؤْمِنُونَ","transliteration":"tu''minūna","translation_bn":"তোমরা ঈমান আনো","root":"امن","lemma":"ءَامَنَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":1681,"position":19,"text_uthmani":"بِٱللَّهِ","transliteration":"bil-lahi","translation_bn":"প্রতি আল্লাহর","root":"اله","lemma":"ٱللَّه","grammar_bn":"অব্যয় (Preposition)"},{"id":1682,"position":20,"text_uthmani":"وَٱلْيَوْمِ","transliteration":"wal-yawmi","translation_bn":"ও দিনের","root":"يوم","lemma":"يَوْم","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":1683,"position":21,"text_uthmani":"ٱلْـَٔاخِرِ ۖ","transliteration":"l-ākhiri","translation_bn":"শেষ (প্রতি)","root":"اخر","lemma":"ا^خِر","grammar_bn":"শব্দ"},{"id":1685,"position":22,"text_uthmani":"وَلْيَشْهَدْ","transliteration":"walyashhad","translation_bn":"আর যেন প্রত্যক্ষ করে","root":"شهد","lemma":"شَهِدَ","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":1686,"position":23,"text_uthmani":"عَذَابَهُمَا","transliteration":"ʿadhābahumā","translation_bn":"দু''জনের শাস্তি তাদের","root":"عذب","lemma":"عَذَاب","grammar_bn":"বিশেষ্য (Noun)"},{"id":1687,"position":24,"text_uthmani":"طَآئِفَةٌۭ","transliteration":"ṭāifatun","translation_bn":"একদল","root":"طوف","lemma":"طَا^ئِفَة","grammar_bn":"বিশেষণ (Adjective)"},{"id":1688,"position":25,"text_uthmani":"مِّنَ","transliteration":"mina","translation_bn":"মধ্য হ''তে","root":"—","lemma":"مِن\r","grammar_bn":"অব্যয় (Preposition)"},{"id":1689,"position":26,"text_uthmani":"ٱلْمُؤْمِنِينَ","transliteration":"l-mu''minīna","translation_bn":"মু''মিনদের","root":"امن","lemma":"مُؤْمِن","grammar_bn":"শব্দ"},{"id":1690,"position":27,"text_uthmani":"٢","transliteration":"","translation_bn":"(২)","root":"—","lemma":"٢","grammar_bn":"মার্কার"}]'::jsonb, 'al-zāniyatu wal-zānī fa-ij''lidū kulla wāḥidin min''humā mi-ata jaldatin walā takhudh''kum bihimā rafatun fī dīni l-lahi in kuntum tu''minūna bil-lahi wal-yawmi l-ākhiri walyashhad ʿadhābahumā ṭāifatun mina l-mu''minīna', 'ব্যভিচারিণী ও ব্যভিচারী তাদের প্রত্যেককে একশত করে বেত্রাঘাত কর। আল্লাহর আইন কার্যকর করার ব্যাপারে তাদের প্রতি দয়ামায়া তোমাদেরকে যেন প্রভাবিত না করে, যদি তোমরা আল্লাহ ও আখিরাত দিনের প্রতি বিশ্বাস স্থাপন করে থাক। একদল মু’মিন যেন তাদের শাস্তি প্রত্যক্ষ করে।', 'The [unmarried] woman or [unmarried] man found guilty of sexual intercourse - lash each one of them with a hundred lashes, and do not be taken by pity for them in the religion of Allah, if you should believe in Allah and the Last Day. And let a group of the believers witness their punishment.', 'ব্যভিচারিণী ও ব্যভিচারী তাদের প্রত্যেককে একশত করে বেত্রাঘাত কর। আল্লাহর আইন কার্যকর করার ব্যাপারে তাদের প্রতি দয়ামায়া তোমাদেরকে যেন প্রভাবিত না করে, যদি তোমরা আল্লাহ ও আখিরাত দিনের প্রতি বিশ্বাস স্থাপন করে থাক। একদল মু’মিন যেন তাদের শাস্তি প্রত্যক্ষ করে।', 'The [unmarried] woman or [unmarried] man found guilty of sexual intercourse - lash each one of them with a hundred lashes, and do not be taken by pity for them in the religion of Allah, if you should believe in Allah and the Last Day. And let a group of the believers witness their punishment.', NULL, NULL, NULL, NULL, NULL, 'https://everyayah.com/data/Alafasy_128kbps/024002.mp3', now()),
  (24, 3, '', '[{"id":2862,"position":1,"text_uthmani":"ٱلزَّانِى","transliteration":"al-zānī","translation_bn":"ব্যভিচারী","root":"زني","lemma":"زَان","grammar_bn":"শব্দ"},{"id":2863,"position":2,"text_uthmani":"لَا","transliteration":"lā","translation_bn":"না","root":"—","lemma":"لَا\r","grammar_bn":"না-বোধক (Negative)"},{"id":2864,"position":3,"text_uthmani":"يَنكِحُ","transliteration":"yankiḥu","translation_bn":"বিয়ে করবে (অন্য কাউকে)","root":"نكح","lemma":"نَكَحَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":2865,"position":4,"text_uthmani":"إِلَّا","transliteration":"illā","translation_bn":"ছাড়া","root":"—","lemma":"إِلَّا\r","grammar_bn":"সীমাবদ্ধতা (Restriction)"},{"id":2866,"position":5,"text_uthmani":"زَانِيَةً","transliteration":"zāniyatan","translation_bn":"ব্যভিচারিণীকে","root":"زني","lemma":"زَانِيَة","grammar_bn":"বিশেষ্য (Noun)"},{"id":2867,"position":6,"text_uthmani":"أَوْ","transliteration":"aw","translation_bn":"অথবা","root":"—","lemma":"أَو\r","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":2868,"position":7,"text_uthmani":"مُشْرِكَةًۭ","transliteration":"mush''rikatan","translation_bn":"মুশরিক নারীকে","root":"شرك","lemma":"مُشْرِكَة","grammar_bn":"বিশেষ্য (Noun)"},{"id":2869,"position":8,"text_uthmani":"وَٱلزَّانِيَةُ","transliteration":"wal-zāniyatu","translation_bn":"আর ব্যভিচারিণী","root":"زني","lemma":"زَانِيَة","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":2870,"position":9,"text_uthmani":"لَا","transliteration":"lā","translation_bn":"না","root":"—","lemma":"لَا\r","grammar_bn":"না-বোধক (Negative)"},{"id":2871,"position":10,"text_uthmani":"يَنكِحُهَآ","transliteration":"yankiḥuhā","translation_bn":"তাকে বিয়ে করবে (অন্য কেউ)","root":"نكح","lemma":"نَكَحَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":2872,"position":11,"text_uthmani":"إِلَّا","transliteration":"illā","translation_bn":"ছাড়া","root":"—","lemma":"إِلَّا\r","grammar_bn":"সীমাবদ্ধতা (Restriction)"},{"id":2873,"position":12,"text_uthmani":"زَانٍ","transliteration":"zānin","translation_bn":"ব্যভিচারী","root":"زني","lemma":"زَان","grammar_bn":"বিশেষ্য (Noun)"},{"id":2874,"position":13,"text_uthmani":"أَوْ","transliteration":"aw","translation_bn":"অথবা","root":"—","lemma":"أَو\r","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":2875,"position":14,"text_uthmani":"مُشْرِكٌۭ ۚ","transliteration":"mush''rikun","translation_bn":"মুশরিক","root":"شرك","lemma":"مُشْرِك","grammar_bn":"বিশেষ্য (Noun)"},{"id":2877,"position":15,"text_uthmani":"وَحُرِّمَ","transliteration":"waḥurrima","translation_bn":"এবং নিষিদ্ধ করা হলো","root":"حرم","lemma":"حَرَّمَ","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":2878,"position":16,"text_uthmani":"ذَٰلِكَ","transliteration":"dhālika","translation_bn":"এটা","root":"—","lemma":"ذَٰلِك","grammar_bn":"নির্দেশক সর্বনাম (Demonstrative)"},{"id":2879,"position":17,"text_uthmani":"عَلَى","transliteration":"ʿalā","translation_bn":"জন্যে","root":"—","lemma":"عَلَىٰ\r","grammar_bn":"অব্যয় (Preposition)"},{"id":2880,"position":18,"text_uthmani":"ٱلْمُؤْمِنِينَ","transliteration":"l-mu''minīna","translation_bn":"মু''মিনদের","root":"امن","lemma":"مُؤْمِن","grammar_bn":"শব্দ"},{"id":2881,"position":19,"text_uthmani":"٣","transliteration":"","translation_bn":"(৩)","root":"—","lemma":"٣","grammar_bn":"মার্কার"}]'::jsonb, 'al-zānī lā yankiḥu illā zāniyatan aw mush''rikatan wal-zāniyatu lā yankiḥuhā illā zānin aw mush''rikun waḥurrima dhālika ʿalā l-mu''minīna', 'ব্যভিচারী বিয়ে করে না ব্যভিচারিণী বা মুশরিকা নারী ছাড়া। আর ব্যভিচারিণী- তাকে বিয়ে করে না ব্যভিচারী বা মুশরিক পুরুষ ছাড়া, মু’মিনদের জন্য এটা নিষিদ্ধ করা হয়েছে।', 'The fornicator does not marry except a [female] fornicator or polytheist, and none marries her except a fornicator or a polytheist, and that has been made unlawful to the believers.', 'ব্যভিচারী বিয়ে করে না ব্যভিচারিণী বা মুশরিকা নারী ছাড়া। আর ব্যভিচারিণী- তাকে বিয়ে করে না ব্যভিচারী বা মুশরিক পুরুষ ছাড়া, মু’মিনদের জন্য এটা নিষিদ্ধ করা হয়েছে।', 'The fornicator does not marry except a [female] fornicator or polytheist, and none marries her except a fornicator or a polytheist, and that has been made unlawful to the believers.', NULL, NULL, NULL, NULL, NULL, 'https://everyayah.com/data/Alafasy_128kbps/024003.mp3', now()),
  (24, 4, '', '[{"id":4145,"position":1,"text_uthmani":"وَٱلَّذِينَ","transliteration":"wa-alladhīna","translation_bn":"এবং যারা","root":"—","lemma":"ٱلَّذِى","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":4146,"position":2,"text_uthmani":"يَرْمُونَ","transliteration":"yarmūna","translation_bn":"অপবাদ দেয়","root":"رمي","lemma":"رَمَىٰ","grammar_bn":"ক্রিয়া (Verb)"},{"id":4147,"position":3,"text_uthmani":"ٱلْمُحْصَنَـٰتِ","transliteration":"l-muḥ''ṣanāti","translation_bn":"পবিত্র রমণীদেরকে","root":"حصن","lemma":"مُحْصَنَٰت","grammar_bn":"শব্দ"},{"id":4148,"position":4,"text_uthmani":"ثُمَّ","transliteration":"thumma","translation_bn":"এরপর","root":"—","lemma":"ثُمّ\r","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":4149,"position":5,"text_uthmani":"لَمْ","transliteration":"lam","translation_bn":"না","root":"—","lemma":"لَم\r","grammar_bn":"না-বোধক (Negative)"},{"id":4150,"position":6,"text_uthmani":"يَأْتُوا۟","transliteration":"yatū","translation_bn":"তারা আসে","root":"اتي","lemma":"أَتَى","grammar_bn":"ক্রিয়া (Verb)"},{"id":4151,"position":7,"text_uthmani":"بِأَرْبَعَةِ","transliteration":"bi-arbaʿati","translation_bn":"নিয়ে চারজন","root":"ربع","lemma":"أَرْبَعَة","grammar_bn":"অব্যয় (Preposition)"},{"id":4152,"position":8,"text_uthmani":"شُهَدَآءَ","transliteration":"shuhadāa","translation_bn":"সাক্ষী","root":"شهد","lemma":"شَهِيد","grammar_bn":"বিশেষ্য (Noun)"},{"id":4153,"position":9,"text_uthmani":"فَٱجْلِدُوهُمْ","transliteration":"fa-ij''lidūhum","translation_bn":"তখন দোররা লাগাও তাদেরকে","root":"جلد","lemma":"ٱجْلِدُ","grammar_bn":"শব্দ"},{"id":4154,"position":10,"text_uthmani":"ثَمَـٰنِينَ","transliteration":"thamānīna","translation_bn":"আশি","root":"ثمن","lemma":"ثَمَٰنِين","grammar_bn":"বিশেষ্য (Noun)"},{"id":4155,"position":11,"text_uthmani":"جَلْدَةًۭ","transliteration":"jaldatan","translation_bn":"দোররা","root":"جلد","lemma":"جَلْدَة","grammar_bn":"বিশেষ্য (Noun)"},{"id":4156,"position":12,"text_uthmani":"وَلَا","transliteration":"walā","tran