  (25, 1, '', '[{"id":682,"position":1,"text_uthmani":"تَبَارَكَ","transliteration":"tabāraka","translation_bn":"অতীব কল্যাণময়","root":"برك","lemma":"تَبَارَكَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":683,"position":2,"text_uthmani":"ٱلَّذِى","transliteration":"alladhī","translation_bn":"(সেই সত্ত্বা) যিনি","root":"—","lemma":"ٱلَّذِى","grammar_bn":"সাপেক্ষ সর্বনাম (Relative)"},{"id":684,"position":3,"text_uthmani":"نَزَّلَ","transliteration":"nazzala","translation_bn":"অবতীর্ণ করেছেন","root":"نزل","lemma":"نَزَّلَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":685,"position":4,"text_uthmani":"ٱلْفُرْقَانَ","transliteration":"l-fur''qāna","translation_bn":"সত্য-মিথ্যার মাপকাঠি","root":"فرق","lemma":"فُرْقَان","grammar_bn":"শব্দ"},{"id":686,"position":5,"text_uthmani":"عَلَىٰ","transliteration":"ʿalā","translation_bn":"উপর","root":"—","lemma":"عَلَىٰ\r","grammar_bn":"অব্যয় (Preposition)"},{"id":687,"position":6,"text_uthmani":"عَبْدِهِۦ","transliteration":"ʿabdihi","translation_bn":"তাঁর দাসের","root":"عبد","lemma":"عَبْد","grammar_bn":"বিশেষ্য (Noun)"},{"id":688,"position":7,"text_uthmani":"لِيَكُونَ","transliteration":"liyakūna","translation_bn":"যেন সে হয়","root":"كون","lemma":"كَانَ","grammar_bn":"শব্দ"},{"id":689,"position":8,"text_uthmani":"لِلْعَـٰلَمِينَ","transliteration":"lil''ʿālamīna","translation_bn":"জন্যে বিশ্ববাসীর","root":"علم","lemma":"عَٰلَمِين","grammar_bn":"অব্যয় (Preposition)"},{"id":690,"position":9,"text_uthmani":"نَذِيرًا","transliteration":"nadhīran","translation_bn":"সতর্ককারী","root":"نذر","lemma":"نَذِير","grammar_bn":"বিশেষ্য (Noun)"},{"id":691,"position":10,"text_uthmani":"١","transliteration":"","translation_bn":"(১)","root":"—","lemma":"١","grammar_bn":"মার্কার"}]'::jsonb, 'tabāraka alladhī nazzala l-fur''qāna ʿalā ʿabdihi liyakūna lil''ʿālamīna nadhīran', 'মহা কল্যাণময় তিনি যিনি তাঁর বান্দাহর উপর সত্য-মিথ্যার পার্থক্যকারী (কিতাব) নাযিল করেছেন যাতে সে বিশ্বজগতের জন্য সতর্ককারী হতে পারে।', 'Blessed is He who sent down the Criterion upon His Servant that he may be to the worlds a warner -', 'মহা কল্যাণময় তিনি যিনি তাঁর বান্দাহর উপর সত্য-মিথ্যার পার্থক্যকারী (কিতাব) নাযিল করেছেন যাতে সে বিশ্বজগতের জন্য সতর্ককারী হতে পারে।', 'Blessed is He who sent down the Criterion upon His Servant that he may be to the worlds a warner -', NULL, NULL, NULL, NULL, NULL, 'https://everyayah.com/data/Alafasy_128kbps/025001.mp3', now()),
  (25, 2, '', '[{"id":1698,"position":1,"text_uthmani":"ٱلَّذِى","transliteration":"alladhī","translation_bn":"যিনি (এমন সত্ত্বা যে)","root":"—","lemma":"ٱلَّذِى","grammar_bn":"সাপেক্ষ সর্বনাম (Relative)"},{"id":1699,"position":2,"text_uthmani":"لَهُۥ","transliteration":"lahu","translation_bn":"জন্যে তাঁরই","root":"—","lemma":"لَهُۥ","grammar_bn":"অব্যয় (Preposition)"},{"id":1700,"position":3,"text_uthmani":"مُلْكُ","transliteration":"mul''ku","translation_bn":"সার্বভৌমত্ব","root":"ملك","lemma":"مُلْك","grammar_bn":"বিশেষ্য (Noun)"},{"id":1701,"position":4,"text_uthmani":"ٱلسَّمَـٰوَٰتِ","transliteration":"l-samāwāti","translation_bn":"আকাশমন্ডলীর","root":"سمو","lemma":"سَمَا^ء","grammar_bn":"শব্দ"},{"id":1702,"position":5,"text_uthmani":"وَٱلْأَرْضِ","transliteration":"wal-arḍi","translation_bn":"ও পৃথিবীর","root":"ارض","lemma":"أَرْض","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":1703,"position":6,"text_uthmani":"وَلَمْ","transliteration":"walam","translation_bn":"এবং নি","root":"—","lemma":"لَم\r","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":1704,"position":7,"text_uthmani":"يَتَّخِذْ","transliteration":"yattakhidh","translation_bn":"তিনি গ্রহন করেন","root":"اخذ","lemma":"ٱتَّخَذَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":1705,"position":8,"text_uthmani":"وَلَدًۭا","transliteration":"waladan","translation_bn":"কোন সন্তান","root":"ولد","lemma":"وَلَد","grammar_bn":"বিশেষ্য (Noun)"},{"id":1706,"position":9,"text_uthmani":"وَلَمْ","transliteration":"walam","translation_bn":"আর না","root":"—","lemma":"لَم\r","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":1707,"position":10,"text_uthmani":"يَكُن","transliteration":"yakun","translation_bn":"আছে","root":"كون","lemma":"كَانَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":1708,"position":11,"text_uthmani":"لَّهُۥ","transliteration":"lahu","translation_bn":"জন্যে তাঁর","root":"—","lemma":"لَّهُۥ","grammar_bn":"অব্যয় (Preposition)"},{"id":1709,"position":12,"text_uthmani":"شَرِيكٌۭ","transliteration":"sharīkun","translation_bn":"কোন শরীক","root":"شرك","lemma":"شَرِيك","grammar_bn":"বিশেষ্য (Noun)"},{"id":1710,"position":13,"text_uthmani":"فِى","transliteration":"fī","translation_bn":"মধ্যে","root":"—","lemma":"فِى\r","grammar_bn":"অব্যয় (Preposition)"},{"id":1711,"position":14,"text_uthmani":"ٱلْمُلْكِ","transliteration":"l-mul''ki","translation_bn":"সার্বভৌমত্বের","root":"ملك","lemma":"مُلْك","grammar_bn":"শব্দ"},{"id":1712,"position":15,"text_uthmani":"وَخَلَقَ","transliteration":"wakhalaqa","translation_bn":"এবং তিনি সৃষ্টি করেছেন","root":"خلق","lemma":"خَلَقَ","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":1713,"position":16,"text_uthmani":"كُلَّ","transliteration":"kulla","translation_bn":"প্রত্যেক","root":"كلل","lemma":"كُلّ","grammar_bn":"বিশেষ্য (Noun)"},{"id":1714,"position":17,"text_uthmani":"شَىْءٍۢ","transliteration":"shayin","translation_bn":"জিনিসকে","root":"شيا","lemma":"شَىْء","grammar_bn":"বিশেষ্য (Noun)"},{"id":1715,"position":18,"text_uthmani":"فَقَدَّرَهُۥ","transliteration":"faqaddarahu","translation_bn":"অতঃপর তা পরিমিত করেছেন","root":"قدر","lemma":"قَدَّرَ","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":1716,"position":19,"text_uthmani":"تَقْدِيرًۭا","transliteration":"taqdīran","translation_bn":"(যথাযথ) পরিমাণে","root":"قدر","lemma":"تَقْدِير","grammar_bn":"বিশেষ্য (Noun)"},{"id":1717,"position":20,"text_uthmani":"٢","transliteration":"","translation_bn":"(২)","root":"—","lemma":"٢","grammar_bn":"মার্কার"}]'::jsonb, 'alladhī lahu mul''ku l-samāwāti wal-arḍi walam yattakhidh waladan walam yakun lahu sharīkun fī l-mul''ki wakhalaqa kulla shayin faqaddarahu taqdīran', 'যিনি যমীন ও আসমানের রাজত্বের মালিক, তিনি কোন সন্তান গ্রহণ করেননি, রাজত্বে তাঁর কোন অংশীদার নেই, তিনি সমস্ত কিছু সৃষ্টি করেছেন, আর সেগুলোকে যথাযথ করেছেন পরিমিত অনুপাতে।', 'He to whom belongs the dominion of the heavens and the earth and who has not taken a son and has not had a partner in dominion and has created each thing and determined it with [precise] determination.', 'যিনি যমীন ও আসমানের রাজত্বের মালিক, তিনি কোন সন্তান গ্রহণ করেননি, রাজত্বে তাঁর কোন অংশীদার নেই, তিনি সমস্ত কিছু সৃষ্টি করেছেন, আর সেগুলোকে যথাযথ করেছেন পরিমিত অনুপাতে।', 'He to whom belongs the dominion of the heavens and the earth and who has not taken a son and has not had a partner in dominion and has created each thing and determined it with [precise] determination.', NULL, NULL, NULL, NULL, NULL, 'https://everyayah.com/data/Alafasy_128kbps/025002.mp3', now()),
  (25, 3, '', '[{"id":2822,"position":1,"text_uthmani":"وَٱتَّخَذُوا۟","transliteration":"wa-ittakhadhū","translation_bn":"আর (কিছু লোক) তারা গ্রহণ করেছে","root":"اخذ","lemma":"ٱتَّخَذَ","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":2823,"position":2,"text_uthmani":"مِن","transliteration":"min","translation_bn":"মধ্য হতে","root":"—","lemma":"مِن\r","grammar_bn":"অব্যয় (Preposition)"},{"id":2824,"position":3,"text_uthmani":"دُونِهِۦٓ","transliteration":"dūnihi","translation_bn":"তাঁর পরিবর্তে","root":"دون","lemma":"دُون","grammar_bn":"বিশেষ্য (Noun)"},{"id":2825,"position":4,"text_uthmani":"ءَالِهَةًۭ","transliteration":"ālihatan","translation_bn":"ইলাহরূপে (অন্যদেরকে)","root":"اله","lemma":"إِلَٰه","grammar_bn":"বিশেষ্য (Noun)"},{"id":2826,"position":5,"text_uthmani":"لَّا","transliteration":"lā","translation_bn":"না","root":"—","lemma":"لَا\r","grammar_bn":"না-বোধক (Negative)"},{"id":2827,"position":6,"text_uthmani":"يَخْلُقُونَ","transliteration":"yakhluqūna","translation_bn":"( সেই ইলাহরা) সৃষ্টি করে","root":"خلق","lemma":"خَلَقَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":2828,"position":7,"text_uthmani":"شَيْـًۭٔا","transliteration":"shayan","translation_bn":"কোন কিছু","root":"شيا","lemma":"شَىْء","grammar_bn":"বিশেষ্য (Noun)"},{"id":2829,"position":8,"text_uthmani":"وَهُمْ","transliteration":"wahum","translation_bn":"অথচ তাদেরকেই","root":"—","lemma":"وَهُمْ","grammar_bn":"অবস্থাবাচক (Circumstantial)"},{"id":2830,"position":9,"text_uthmani":"يُخْلَقُونَ","transliteration":"yukh''laqūna","translation_bn":"সৃষ্টি করা হয়েছে","root":"خلق","lemma":"خَلَقَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":2831,"position":10,"text_uthmani":"وَلَا","transliteration":"walā","translation_bn":"আর না","root":"—","lemma":"لَا\r","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":2832,"position":11,"text_uthmani":"يَمْلِكُونَ","transliteration":"yamlikūna","translation_bn":"তারা ক্ষমতা রাখে","root":"ملك","lemma":"مَلَكَتْ","grammar_bn":"ক্রিয়া (Verb)"},{"id":2833,"position":12,"text_uthmani":"لِأَنفُسِهِمْ","transliteration":"li-anfusihim","translation_bn":"জন্যেও তাদের নিজেদের","root":"نفس","lemma":"نَفْس","grammar_bn":"অব্যয় (Preposition)"},{"id":2834,"position":13,"text_uthmani":"ضَرًّۭا","transliteration":"ḍarran","translation_bn":"কোন ক্ষতির","root":"ضرر","lemma":"ضَرّ","grammar_bn":"বিশেষ্য (Noun)"},{"id":2835,"position":14,"text_uthmani":"وَلَا","transliteration":"walā","translation_bn":"আর না","root":"—","lemma":"لَا\r","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":2836,"position":15,"text_uthmani":"نَفْعًۭا","transliteration":"nafʿan","translation_bn":"উপকারের","root":"نفع","lemma":"نَفْع","grammar_bn":"বিশেষ্য (Noun)"},{"id":2837,"position":16,"text_uthmani":"وَلَا","transliteration":"walā","translation_bn":"এবং না","root":"—","lemma":"لَا\r","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":2838,"position":17,"text_uthmani":"يَمْلِكُونَ","transliteration":"yamlikūna","translation_bn":"তারা ক্ষমতা রাখে","root":"ملك","lemma":"مَلَكَتْ","grammar_bn":"ক্রিয়া (Verb)"},{"id":2839,"position":18,"text_uthmani":"مَوْتًۭا","transliteration":"mawtan","translation_bn":"মৃত্যুর","root":"موت","lemma":"مَوْت","grammar_bn":"বিশেষ্য (Noun)"},{"id":2840,"position":19,"text_uthmani":"وَلَا","transliteration":"walā","translation_bn":"আর না","root":"—","lemma":"لَا\r","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":2841,"position":20,"text_uthmani":"حَيَوٰةًۭ","transliteration":"ḥayatan","translation_bn":"জীবনের","root":"حيي","lemma":"حَيَوٰة","grammar_bn":"বিশেষ্য (Noun)"},{"id":2842,"position":21,"text_uthmani":"وَلَا","transliteration":"walā","translation_bn":"আর না","root":"—","lemma":"لَا\r","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":2843,"position":22,"text_uthmani":"نُشُورًۭا","transliteration":"nushūran","translation_bn":"উত্থানের","root":"نشر","lemma":"نُشُور","grammar_bn":"বিশেষ্য (Noun)"},{"id":2844,"position":23,"text_uthmani":"٣","transliteration":"","translation_bn":"(৩)","root":"—","lemma":"٣","grammar_bn":"মার্কার"}]'::jsonb, 'wa-ittakhadhū min dūnihi ālihatan lā yakhluqūna shayan wahum yukh''laqūna walā yamlikūna li-anfusihim ḍarran walā nafʿan walā yamlikūna mawtan walā ḥayatan walā nushūran', 'আর তারা তাঁকে বাদ দিয়ে ইলাহরূপে গ্রহণ করেছে অন্য কিছুকে যারা কিছুই সৃষ্টি করে না, বরং তারা নিজেরাই সৃষ্টি হয়েছে। তারা ক্ষমতা রাখে না নিজেদের ক্ষতি বা উপকার করার আর ক্ষমতা রাখে না মৃত্যু, জীবন ও পুনরুত্থানের উপর।', 'But they have taken besides Him gods which create nothing, while they are created, and possess not for themselves any harm or benefit and possess not [power to cause] death or life or resurrection.', 'আর তারা তাঁকে বাদ দিয়ে ইলাহরূপে গ্রহণ করেছে অন্য কিছুকে যারা কিছুই সৃষ্টি করে না, বরং তারা নিজেরাই সৃষ্টি হয়েছে। তারা ক্ষমতা রাখে না নিজেদের ক্ষতি বা উপকার করার আর ক্ষমতা রাখে না মৃত্যু, জীবন ও পুনরুত্থানের উপর।', 'But they have taken besides Him gods which create nothing, while they are created, and possess not for themselves any harm or benefit and possess not [power to cause] death or life or resurrection.', NULL, NULL, NULL, NULL, NULL, 'https://everyayah.com/data/Alafasy_128kbps/025003.mp3', now()),
  (25, 4, '', '[{"id":4192,"position":1,"text_uthmani":"وَقَالَ","transliteration":"waqāla","translation_bn":"এবং বলে","root":"قول","lemma":"قَالَ","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":4193,"position":2,"text_uthmani":"ٱلَّذِينَ","transliteration":"alladhīna","translation_bn":"যারা","root":"—","lemma":"ٱلَّذِى","grammar_bn":"সাপেক্ষ সর্বনাম (Relative)"},{"id":4194,"position":3,"text_uthmani":"كَفَرُوٓا۟","transliteration":"kafarū","translation_bn":"অস্বীকার করেছে","root":"كفر","lemma":"كَفَرَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":4195,"position":4,"text_uthmani":"إِنْ","transliteration":"in","translation_bn":"\"নয়","root":"—","lemma":"إِن\r","grammar_bn":"না-বোধক (Negative)"},{"id":4196,"position":5,"text_uthmani":"هَـٰذَآ","transliteration":"hādhā","translation_bn":"এই (কুরআন)","root":"—","lemma":"هَٰذَا","grammar_bn":"নির্দেশক সর্বনাম (Demonstrative)"},{"id":4197,"position":6,"text_uthmani":"إِلَّآ","transliteration":"illā","translation_bn":"এ ছাড়া","root":"—","lemma":"إِلَّا\r","grammar_bn":"সীমাবদ্ধতা (Restriction)"},{"id":4198,"position":7,"text_uthmani":"إِفْكٌ","transliteration":"if''kun","translation_bn":"মনগড়া জিনিস","root":"افك","lemma":"إِفْك","grammar_bn":"বিশেষ্য (Noun)"},{"id":4199,"position":8,"text_uthmani":"ٱفْتَرَىٰهُ","transliteration":"if''tarāhu","translation_bn":"তা (মুহাম্মাদ সাল্লাল্লাহু ''অালাইহি ওয়া সাল্লাম) রচনা করেছে","root":"فري","lemma":"ٱفْتَرَىٰ","grammar_bn":"ক্রিয়া (Verb)"},{"id":4200,"position":9,"text_uthmani":"وَأَعَانَهُۥ","transliteration":"wa-aʿānahu","translation_bn":"ও তাকে সাহায্য করেছে","root":"عون","lemma":"أَعَانَ","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":4201,"position":10,"text_uthmani":"عَلَيْهِ","transliteration":"ʿalayhi","translation_bn":"এক্ষেত্রে","root":"—","lemma":"عَلَىٰ\r","grammar_bn":"অব্যয় (Preposition)"},{"id":4202,"position":11,"text_uthmani":"قَوْمٌ","transliteration":"qawmun","translation_bn":"লোকেরা","root":"قوم","lemma":"قَوْم","grammar_bn":"বিশেষ্য (Noun)"},{"id":4203,"position":12,"text_uthmani":"ءَاخَرُونَ ۖ","transliteration":"ākharūna","translation_bn":"অন্য সব\"","root":"اخر","lemma":"ا^خَر","grammar_bn":"বিশেষণ (Adjective)"},{"id":4205,"position":13,"text_uthmani":"فَقَدْ","transliteration":"faqad","translation_bn":"এভাবে নিশ্চয়ই","root":"—","lemma":"قَد\r","grammar_bn":"শব্দ"},{"id":4206,"position":14,"text_uthmani":"جَآءُو","transliteration":"jāū","translation_bn":"তারা এসেছে","root":"جيا","lemma":"جَا^ءَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":4207,"position":15,"text_uthmani":"ظُلْمًۭا","transliteration":"ẓul''man","translation_bn":"সীমালঙ্ঘনে","root":"ظلم","lemma":"ظُلْم","grammar_bn":"বিশেষ্য (Noun)"},{"id":4208,"position":16,"text_uthmani":"وَزُورًۭا","transliteration":"wazūran","translation_bn":"ও মিথ্যায়","root":"زور","lemma":"زُّور","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":4209,"position":17,"text_uthmani":"٤","transliteration":"","translation_bn":"(৪)","root":"—","lemma":"٤","grammar_bn":"মার্কার"}]'::jsonb, 'waqāla alladhīna kafarū in hādhā illā if''kun if''tarāhu wa-aʿānahu ʿalayhi qawmun ākharūna faqad jāū ẓul''man wazūran', 'কাফিররা বলে- ‘এটা মিথ্যে ছাড়া আর কিছুই নয়, সে তা (অর্থাৎ কুরআন) উদ্ভাবণ করেছে এবং ভিন্ন জাতির লোক এ ব্যাপারে তাকে সাহায্য করেছে।’ আসলে তারা অন্যায় ও মিথ্যের আশ্রয় নিয়েছে।', 'And those who disbelieve say, "This [Qur''an] is not except a falsehood he invented, and another people assisted him in it." But they have committed an injustice and a lie.', 'কাফিররা বলে- ‘এটা মিথ্যে ছাড়া আর কিছুই নয়, সে তা (অর্থাৎ কুরআন) উদ্ভাবণ করেছে এবং ভিন্ন জাতির লোক এ ব্যাপারে তাকে সাহায্য করেছে।’ আসলে তারা অন্যায় ও মিথ্যের আশ্রয় নিয়েছে।', 'And those who disbelieve say, "This [Qur''an] is not except a falsehood he invented, and another people assisted him in it." But they have committed an injustice and a lie.', NULL, NULL, NULL, NULL, NULL, 'https://everyayah.com/data/Alafasy_128kbps/025004.mp3', now()),
  (25, 5, '', '[{"id":5459,"position":1,"text_uthmani":"وَقَالُوٓا۟","transliteration":"waqālū","translation_bn":"এবং তারা বলে","root":"قول","lemma":"قَالَ","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":5460,"position":2,"text_uthmani":"أَسَـٰطِيرُ","transliteration":"asāṭīru","translation_bn":"\"(এই কুরআন) উপকথার সমাহার","root":"سطر","lemma":"أَسَٰطِير","grammar_bn":"বিশেষ্য (Noun)"},{"id":5461,"position":3,"text_uthmani":"ٱلْأَوَّلِينَ","transliteration":"l-awalīna","translation_bn":"পূর্বকালের","root":"اول","lemma":"أَوَّل","grammar_bn":"শব্দ"},{"id":5462,"position":4,"text_uthmani":"ٱكْتَتَبَهَا","transliteration":"ik''tatabahā","translation_bn":"তা সে লিখিয়ে নিয়েছে","root":"كتب","lemma":"ٱكْتَتَبَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":5463,"position":5,"text_uthmani":"فَهِىَ","transliteration":"fahiya","translation_bn":"অতঃপর তা","root":"—","lemma":"فَهِىَ","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":5464,"position":6,"text_uthmani":"تُمْلَىٰ","transliteration":"tum''lā","translation_bn":"তিলাওয়াত করা হয়","root":"ملو","lemma":"أَمْلَىٰ","grammar_bn":"ক্রিয়া (Verb)"},{"id":5465,"position":7,"text_uthmani":"عَلَيْهِ","transliteration":"ʿalayhi","translation_bn":"তার নিকট","root":"—","lemma":"عَلَىٰ\r","grammar_bn":"অব্যয় (Preposition)"},{"id":5466,"position":8,"text_uthmani":"بُكْرَةًۭ","transliteration":"buk''ratan","translation_bn":"সকালে","root":"بكر","lemma":"بُكْرَة","grammar_bn":"কালবাচক (Time)"},{"id":5467,"position":9,"text_uthmani":"وَأَصِيلًۭا","transliteration":"wa-aṣīlan","translation_bn":"ও সন্ধ্যায়\"","root":"اصل","lemma":"أَصِيل","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":5468,"position":10,"text_uthmani":"٥","transliteration":"","translation_bn":"(৫)","root":"—","lemma":"٥","grammar_bn":"মার্কার"}]'::jsonb, 'waqālū asāṭīru l-awalīna ik''tatabahā fahiya tum''lā ʿalayhi buk''ratan wa-aṣīlan', 'তারা বলে- ‘এগুলো পূর্ব যুগের কাহিনী যা সে [অর্থাৎ মুহাম্মাদ (সা.)] লিখিয়ে নিয়েছে আর এগুলোই তার কাছে সকাল-সন্ধ্যা শোনানো হয়।’', 'And they say, "Legends of the former peoples which he has written down, and they are dictated to him morning and afternoon."', 'তারা বলে- ‘এগুলো পূর্ব যুগের কাহিনী যা সে [অর্থাৎ মুহাম্মাদ (সা.)] লিখিয়ে নিয়েছে আর এগুলোই তার কাছে সকাল-সন্ধ্যা শোনানো হয়।’', 'And they say, "Legends of the former peoples which he has written down, and they are dictated to him morning and afternoon."', NULL, NULL, NULL, NULL, NULL, 'https://everyayah.com/data/Alafasy_128kbps/025005.mp3', now()),
  (25, 6, '', '[{"id":6693,"position":1,"text_uthmani":"قُلْ","transliteration":"qul","translation_bn":"বলো (হে নাবী)","root":"قول","lemma":"قَالَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":6694,"position":2,"text_uthmani":"أَنزَلَهُ","transliteration":"anzalahu","translation_bn":"\"তা অবতীর্ণ করেছেন","root":"نزل","lemma":"أَنزَلَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":6695,"position":3,"text_uthmani":"ٱلَّذِى","transliteration":"alladhī","translation_bn":"(এমন সত্ত্বা) যিনি","root":"—","lemma":"ٱلَّذِى","grammar_bn":"সাপেক্ষ সর্বনাম (Relative)"},{"id":6696,"position":4,"text_uthmani":"يَعْلَمُ","transliteration":"yaʿlamu","translation_bn":"জানেন","root":"علم","lemma":"عَلِمَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":6697,"position":5,"text_uthmani":"ٱلسِّرَّ","transliteration":"l-sira","translation_bn":"(সমুদয়) রহস্য (গোপন)","root":"سرر","lemma":"سِرّ","grammar_bn":"শব্দ"},{"id":6698,"position":6,"text_uthmani":"فِى","transliteration":"fī","translation_bn":"মধ্যকার","root":"—","lemma":"فِى\r","grammar_bn":"অব্যয় (Preposition)"},{"id":6699,"position":7,"text_uthmani":"ٱلسَّمَـٰوَٰتِ","transliteration":"l-samāwāti","translation_bn":"আকাশমন্ডলীর","root":"سمو","lemma":"سَمَا^ء","grammar_bn":"শব্দ"},{"id":6700,"position":8,"text_uthmani":"وَٱلْأَرْضِ ۚ","transliteration":"wal-arḍi","translation_bn":"ও পৃথিবীর","root":"ارض","lemma":"أَرْض","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":6702,"position":9,"text_uthmani":"إِنَّهُۥ","transliteration":"innahu","translation_bn":"নিশ্চয়ই তিনি","root":"—","lemma":"إِنّ","grammar_bn":"অভিঘাত পদ (Accusative)"},{"id":6703,"position":10,"text_uthmani":"كَانَ","transliteration":"kāna","translation_bn":"হলেন","root":"كون","lemma":"كَانَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":6704,"position":11,"text_uthmani":"غَفُورًۭا","transliteration":"ghafūran","translation_bn":"ক্ষমাশীল","root":"غفر","lemma":"غَفُور","grammar_bn":"বিশেষ্য (Noun)"},{"id":6705,"position":12,"text_uthmani":"رَّحِيمًۭا","transliteration":"raḥīman","translation_bn":"পরম দয়ালু\"","root":"رحم","lemma":"رَّحِيم","grammar_bn":"বিশেষণ (Adjective)"},{"id":6706,"position":13,"text_uthmani":"٦","transliteration":"","translation_bn":"(৬)","root":"—","lemma":"٦","grammar_bn":"মার্কার"}]'::jsonb, 'qul anzalahu alladhī yaʿlamu l-sira fī l-samāwāti wal-arḍi innahu kāna ghafūran raḥīman', 'বল : ‘তা তিনিই নাযিল করেছেন যিনি আসমান-যমীনের যাবতীয় গোপন বিষয় অবগত আছেন। তিনি বড়ই ক্ষমাশীল, অতি দয়ালু।', 'Say, [O Muhammad], "It has been revealed by He who knows [every] secret within the heavens and the earth. Indeed, He is ever Forgiving and Merciful."', 'বল : ‘তা তিনিই নাযিল করেছেন যিনি আসমান-যমীনের যাবতীয় গোপন বিষয় অবগত আছেন। তিনি বড়ই ক্ষমাশীল, অতি দয়ালু।', 'Say, [O Muhammad], "It has been revealed by He who knows [every] secret within the heavens and the earth. Indeed, He is ever Forgiving and Merciful."', NULL, NULL, NULL, NULL, NULL, 'https://everyayah.com/data/Alafasy_128kbps/025006.mp3', now()),
  (25, 7, '', '[{"id":8034,"position":1,"text_uthmani":"وَقَالُوا۟","transliteration":"waqālū","translation_bn":"এবং তারা বলে","root":"قول","lemma":"قَالَ","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":8035,"position":2,"text_uthmani":"مَالِ","transliteration":"māli","translation_bn":"\"কেমন","root":"—","lemma":"مَا\r","grammar_bn":"প্রশ্নবোধক (Interrogative)"},{"id":8036,"position":3,"text_uthmani":"هَـٰذَا","transliteration":"hādhā","translation_bn":"এই","root":"—","lemma":"هَٰذَا","grammar_bn":"নির্দেশক সর্বনাম (Demonstrative)"},{"id":8037,"position":4,"text_uthmani":"ٱلرَّسُولِ","transliteration":"l-rasūli","translation_bn":"রাসূল","root":"رسل","lemma":"رَسُول","grammar_bn":"শব্দ"},{"id":8038,"position":5,"text_uthmani":"يَأْكُلُ","transliteration":"yakulu","translation_bn":"সে খায়","root":"اكل","lemma":"أَكَلَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":8039,"position":6,"text_uthmani":"ٱلطَّعَامَ","transliteration":"l-ṭaʿāma","translation_bn":"খাবার","root":"طعم","lemma":"طَعَام","grammar_bn":"শব্দ"},{"id":8040,"position":7,"text_uthmani":"وَيَمْشِى","transliteration":"wayamshī","translation_bn":"ও চলাফেরা করে","root":"مشي","lemma":"مَّشَ","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":8041,"position":8,"text_uthmani":"فِى","transliteration":"fī","translation_bn":"মধ্যে","root":"—","lemma":"فِى\r","grammar_bn":"অব্যয় (Preposition)"},{"id":8042,"position":9,"text_uthmani":"ٱلْأَسْوَاقِ ۙ","transliteration":"l-aswāqi","translation_bn":"হাট বাজারসমূহে","root":"سوق","lemma":"سُّوق","grammar_bn":"শব্দ"},{"id":8044,"position":10,"text_uthmani":"لَوْلَآ","transliteration":"lawlā","translation_bn":"কেন না","root":"—","lemma":"لَوْلَا^\r","grammar_bn":"উৎসাহবাচক (Exhortation)"},{"id":8045,"position":11,"text_uthmani":"أُنزِلَ","transliteration":"unzila","translation_bn":"অবতীর্ণ করা হলো","root":"نزل","lemma":"أَنزَلَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":8046,"position":12,"text_uthmani":"إِلَيْهِ","transliteration":"ilayhi","translation_bn":"তার কাছে","root":"—","lemma":"إِلَىٰ\r","grammar_bn":"অব্যয় (Preposition)"},{"id":8047,"position":13,"text_uthmani":"مَلَكٌۭ","transliteration":"malakun","translation_bn":"কোন ফেরেশতা","root":"ملك","lemma":"مَلَك","grammar_bn":"বিশেষ্য (Noun)"},{"id":8048,"position":14,"text_uthmani":"فَيَكُونَ","transliteration":"fayakūna","translation_bn":"অতঃপর সে হতো","root":"كون","lemma":"كَانَ","grammar_bn":"কারণবাচক (Cause)"},{"id":8049,"position":15,"text_uthmani":"مَعَهُۥ","transliteration":"maʿahu","translation_bn":"তার সাথে","root":"—","lemma":"مَع","grammar_bn":"স্থানবাচক (Location)"},{"id":8050,"position":16,"text_uthmani":"نَذِيرًا","transliteration":"nadhīran","translation_bn":"ভীতি প্রদর্শনকারী","root":"نذر","lemma":"نَذِير","grammar_bn":"বিশেষ্য (Noun)"},{"id":8051,"position":17,"text_uthmani":"٧","transliteration":"","translation_bn":"(৭)","root":"—","lemma":"٧","grammar_bn":"মার্কার"}]'::jsonb, 'waqālū māli hādhā l-rasūli yakulu l-ṭaʿāma wayamshī fī l-aswāqi lawlā unzila ilayhi malakun fayakūna maʿahu nadhīran', 'তারা বলে- ‘এ কেমন রসূল যে খাবার খায়, আর হাট-বাজারে চলাফেরা করে? তার কাছে ফেরেশতা অবতীর্ণ হয় না কেন যে তার সঙ্গে থাকত সতর্ককারী হয়ে?', 'And they say, "What is this messenger that eats food and walks in the markets? Why was there not sent down to him an angel so he would be with him a warner?', 'তারা বলে- ‘এ কেমন রসূল যে খাবার খায়, আর হাট-বাজারে চলাফেরা করে? তার কাছে ফেরেশতা অবতীর্ণ হয় না কেন যে তার সঙ্গে থাকত সতর্ককারী হয়ে?', 'And they say, "What is this messenger that eats food and walks in the markets? Why was there not sent down to him an angel so he would be with him a warner?', NULL, NULL, NULL, NULL, NULL, 'https://everyayah.com/data/Alafasy_128kbps/025007.mp3', now()),
  (25, 8, '', '[{"id":9207,"position":1,"text_uthmani":"أَوْ","transliteration":"aw","translation_bn":"অথবা","root":"—","lemma":"أَو\r","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":9208,"position":2,"text_uthmani":"يُلْقَىٰٓ","transliteration":"yul''qā","translation_bn":"নিক্ষেপ করা হতো","root":"لقي","lemma":"أَلْقَىٰ^","grammar_bn":"ক্রিয়া (Verb)"},{"id":9209,"position":3,"text_uthmani":"إِلَيْهِ","transliteration":"ilayhi","translation_bn":"তার কাছে","root":"—","lemma":"إِلَىٰ\r","grammar_bn":"অব্যয় (Preposition)"},{"id":9210,"position":4,"text_uthmani":"كَنزٌ","transliteration":"kanzun","translation_bn":"কোন ধনভান্ডার","root":"كنز","lemma":"كَنز","grammar_bn":"বিশেষ্য (Noun)"},{"id":9211,"position":5,"text_uthmani":"أَوْ","transliteration":"aw","translation_bn":"অথবা","root":"—","lemma":"أَو\r","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":9212,"position":6,"text_uthmani":"تَكُونُ","transliteration":"takūnu","translation_bn":"হতো","root":"كون","lemma":"كَانَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":9213,"position":7,"text_uthmani":"لَهُۥ","transliteration":"lahu","translation_bn":"জন্যে তার","root":"—","lemma":"لَهُۥ","grammar_bn":"অব্যয় (Preposition)"},{"id":9214,"position":8,"text_uthmani":"جَنَّةٌۭ","transliteration":"jannatun","translation_bn":"একটি বাগান","root":"جنن","lemma":"جَنَّة","grammar_bn":"বিশেষ্য (Noun)"},{"id":9215,"position":9,"text_uthmani":"يَأْكُلُ","transliteration":"yakulu","translation_bn":"সে খেতো","root":"اكل","lemma":"أَكَلَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":9216,"position":10,"text_uthmani":"مِنْهَا ۚ","transliteration":"min''hā","translation_bn":"তা হ''তে","root":"—","lemma":"مِن\r","grammar_bn":"অব্যয় (Preposition)"},{"id":9218,"position":11,"text_uthmani":"وَقَالَ","transliteration":"waqāla","translation_bn":"এবং বলেে","root":"قول","lemma":"قَالَ","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":9219,"position":12,"text_uthmani":"ٱلظَّـٰلِمُونَ","transliteration":"l-ẓālimūna","translation_bn":"সীমালঙ্ঘনকারীরা","root":"ظلم","lemma":"ظَالِم","grammar_bn":"শব্দ"},{"id":9220,"position":13,"text_uthmani":"إِن","transliteration":"in","translation_bn":"\"না","root":"—","lemma":"إِن\r","grammar_bn":"না-বোধক (Negative)"},{"id":9221,"position":14,"text_uthmani":"تَتَّبِعُونَ","transliteration":"tattabiʿūna","translation_bn":"তোমরা অনুসরণ করছো","root":"تبع","lemma":"ٱتَّبَعَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":9222,"position":15,"text_uthmani":"إِلَّا","transliteration":"illā","translation_bn":"এ ছাড়া","root":"—","lemma":"إِلَّا\r","grammar_bn":"সীমাবদ্ধতা (Restriction)"},{"id":9223,"position":16,"text_uthmani":"رَجُلًۭا","transliteration":"rajulan","translation_bn":"এক ব্যক্তিকে","root":"رجل","lemma":"رَجُل","grammar_bn":"বিশেষ্য (Noun)"},{"id":9224,"position":17,"text_uthmani":"مَّسْحُورًا","transliteration":"masḥūran","translation_bn":"জাদুগ্রস্ত\"","root":"سحر","lemma":"مَّسْحُور","grammar_bn":"বিশেষ্য (Noun)"},{"id":9225,"position":18,"text_uthmani":"٨","transliteration":"","translation_bn":"(৮)","root":"—","lemma":"٨","grammar_bn":"মার্কার"}]'::jsonb, 'aw yul''qā ilayhi kanzun aw takūnu lahu jannatun yakulu min''hā waqāla l-ẓālimūna in tattabiʿūna illā rajulan masḥūran', 'কিংবা তাকে ধন-ভান্ডার দেয়া হয় না কেন, অথবা তার জন্য একটা বাগান হয় না কেন যাত্থেকে সে আহার করত?’ যালিমরা বলে- ‘তোমরা তো এক যাদুগ্রস্ত লোকেরই অনুসরণ করছ।’', 'Or [why is not] a treasure presented to him [from heaven], or does he [not] have a garden from which he eats?" And the wrongdoers say, "You follow not but a man affected by magic."', 'কিংবা তাকে ধন-ভান্ডার দেয়া হয় না কেন, অথবা তার জন্য একটা বাগান হয় না কেন যাত্থেকে সে আহার করত?’ যালিমরা বলে- ‘তোমরা তো এক যাদুগ্রস্ত লোকেরই অনুসরণ করছ।’', 'Or [why is not] a treasure presented to him [from heaven], or does he [not] have a garden from which he eats?" And the wrongdoers say, "You follow not but a man affected by magic."', NULL, NULL, NULL, NULL, NULL, 'https://everyayah.com/data/Alafasy_128kbps/025008.mp3', now()),
  (25, 9, '', '[{"id":10411,"position":1,"text_uthmani":"ٱنظُرْ","transliteration":"unẓur","translation_bn":"লক্ষ্য করো","root":"نظر","lemma":"نَّظَرَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":10412,"position":2,"text_uthmani":"كَيْفَ","transliteration":"kayfa","translation_bn":"কেমন","root":"كيف\r","lemma":"كَيْف","grammar_bn":"প্রশ্নবোধক (Interrogative)"},{"id":10413,"position":3,"text_uthmani":"ضَرَبُوا۟","transliteration":"ḍarabū","translation_bn":"পেশ করেছে","root":"ضرب","lemma":"ضَرَبَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":10414,"position":4,"text_uthmani":"لَكَ","transliteration":"laka","translation_bn":"জন্যে তোমার","root":"—","lemma":"لَكَ","grammar_bn":"অব্যয় (Preposition)"},{"id":10415,"position":5,"text_uthmani":"ٱلْأَمْثَـٰلَ","transliteration":"l-amthāla","translation_bn":"উপমাসমূহ","root":"مثل","lemma":"مَثَل","grammar_bn":"শব্দ"},{"id":10416,"position":6,"text_uthmani":"فَضَلُّوا۟","transliteration":"faḍallū","translation_bn":"এভাবে তারা বিভ্রান্ত হয়েছে","root":"ضلل","lemma":"ضَلَّ","grammar_bn":"শব্দ"},{"id":10417,"position":7,"text_uthmani":"فَلَا","transliteration":"falā","translation_bn":"অতএব না","root":"—","lemma":"لَا\r","grammar_bn":"শব্দ"},{"id":10418,"position":8,"text_uthmani":"يَسْتَطِيعُونَ","transliteration":"yastaṭīʿūna","translation_bn":"তারা পেতে পারে","root":"طوع","lemma":"ٱسْتَطَاعَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":10419,"position":9,"text_uthmani":"سَبِيلًۭا","transliteration":"sabīlan","translation_bn":"কোন (সঠিক) পথ","root":"سبل","lemma":"سَبِيل","grammar_bn":"বিশেষ্য (Noun)"},{"id":10420,"position":10,"text_uthmani":"٩","transliteration":"","translation_bn":"(৯)","root":"—","lemma":"٩","grammar_bn":"মার্কার"}]'::jsonb, 'unẓur kayfa ḍarabū laka l-amthāla faḍallū falā yastaṭīʿūna sabīlan', 'দেখ, তারা তোমার ব্যাপারে কেমন সব উপমা পেশ করছে! যার ফলে তারা পথভ্রষ্ট হয়ে গেছে, অতএব তারা কোন ক্রমেই পথ পাবে না।', 'Look how they strike for you comparisons; but they have strayed, so they cannot [find] a way.', 'দেখ, তারা তোমার ব্যাপারে কেমন সব উপমা পেশ করছে! যার ফলে তারা পথভ্রষ্ট হয়ে গেছে, অতএব তারা কোন ক্রমেই পথ পাবে না।', 'Look how they strike for you comparisons; but they have strayed, so they cannot [find] a way.', NULL, NULL, NULL, NULL, NULL, 'https://everyayah.com/data/Alafasy_128kbps/025009.mp3', now()),
  (25, 10, '', '[{"id":11638,"position":1,"text_uthmani":"تَبَارَكَ","transliteration":"tabāraka","translation_bn":"অতীব কল্যাণময়","root":"برك","lemma":"تَبَارَكَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":11639,"position":2,"text_uthmani":"ٱلَّذِىٓ","transliteration":"alladhī","translation_bn":"(সেই সত্ত্বা) যিনি","root":"—","lemma":"ٱلَّذِى","grammar_bn":"সাপেক্ষ সর্বনাম (Relative)"},{"id":11640,"position":3,"text_uthmani":"إِن","transliteration":"in","translation_bn":"যদি","root":"—","lemma":"إِن\r","grammar_bn":"শর্তবাচক (Conditional)"},{"id":11641,"position":4,"text_uthmani":"شَآءَ","transliteration":"shāa","translation_bn":"চান তিনি","root":"شيا","lemma":"شَا^ءَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":11642,"position":5,"text_uthmani":"جَعَلَ","transliteration":"jaʿala","translation_bn":"দিতে পারেন","root":"جعل","lemma":"جَعَلَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":11643,"position":6,"text_uthmani":"لَكَ","transliteration":"laka","translation_bn":"জন্যে তোমার","root":"—","lemma":"لَكَ","grammar_bn":"অব্যয় (Preposition)"},{"id":11644,"position":7,"text_uthmani":"خَيْرًۭا","transliteration":"khayran","translation_bn":"(আরও) উত্তম","root":"خير","lemma":"خَيْر","grammar_bn":"বিশেষ্য (Noun)"},{"id":11645,"position":8,"text_uthmani":"مِّن","transliteration":"min","translation_bn":"চেয়েও","root":"—","lemma":"مِن\r","grammar_bn":"অব্যয় (Preposition)"},{"id":11646,"position":9,"text_uthmani":"ذَٰلِكَ","transliteration":"dhālika","translation_bn":"এর","root":"—","lemma":"ذَٰلِك","grammar_bn":"নির্দেশক সর্বনাম (Demonstrative)"},{"id":11647,"position":10,"text_uthmani":"جَنَّـٰتٍۢ","transliteration":"jannātin","translation_bn":"(অনেক) বাগান","root":"جنن","lemma":"جَنَّة","grammar_bn":"বিশেষ্য (Noun)"},{"id":11648,"position":11,"text_uthmani":"تَجْرِى","transliteration":"tajrī","translation_bn":"প্রবাহিত হয়","root":"جري","lemma":"جَرَيْ","grammar_bn":"ক্রিয়া (Verb)"},{"id":11649,"position":12,"text_uthmani":"مِن","transliteration":"min","translation_bn":"থেকে","root":"—","lemma":"مِن\r","grammar_bn":"অব্যয় (Preposition)"},{"id":11650,"position":13,"text_uthmani":"تَحْتِهَا","transliteration":"taḥtihā","translation_bn":"তার নিচ","root":"تحت","lemma":"تَحْت","grammar_bn":"বিশেষ্য (Noun)"},{"id":11651,"position":14,"text_uthmani":"ٱلْأَنْهَـٰرُ","transliteration":"l-anhāru","translation_bn":"ঝর্ণাধারাসমূহ","root":"نهر","lemma":"نَهَر","grammar_bn":"শব্দ"},{"id":11652,"position":15,"text_uthmani":"وَيَجْعَل","transliteration":"wayajʿal","translation_bn":"এবং দিতে পারেন","root":"جعل","lemma":"جَعَلَ","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":11653,"position":16,"text_uthmani":"لَّكَ","transliteration":"laka","translation_bn":"জন্যে তোমার","root":"—","lemma":"لَّكَ","grammar_bn":"অব্যয় (Preposition)"},{"id":11654,"position":17,"text_uthmani":"قُصُورًۢا","transliteration":"quṣūran","translation_bn":"(অনেক) প্রাসাদ","root":"قصر","lemma":"قَصْر","grammar_bn":"বিশেষ্য (Noun)"},{"id":11655,"position":18,"text_uthmani":"١٠","transliteration":"","translation_bn":"(১০)","root":"—","lemma":"١٠","grammar_bn":"মার্কার"}]'::jsonb, 'tabāraka alladhī in shāa jaʿala laka khayran min dhālika jannātin tajrī min taḥtihā l-anhāru wayajʿal laka quṣūran', 'মহা কল্যাণময় তিনি যিনি ইচ্ছে করলে তোমাকে ওগুলোর চেয়েও উৎকৃষ্ট জিনিস দিতে পারেন- বাগ-বাগিচা, যার নিচ দিয়ে বয়ে চলেছে নির্ঝরিণী, দিতে পারেন তিনি তোমাকে প্রাসাদরাজি।', 'Blessed is He who, if He willed, could have made for you [something] better than that - gardens beneath which rivers flow - and could make for you palaces.', 'মহা কল্যাণময় তিনি যিনি ইচ্ছে করলে তোমাকে ওগুলোর চেয়েও উৎকৃষ্ট জিনিস দিতে পারেন- বাগ-বাগিচা, যার নিচ দিয়ে বয়ে চলেছে নির্ঝরিণী, দিতে পারেন তিনি তোমাকে প্রাসাদরাজি।', 'Blessed is He who, if He willed, could have made for you [something] better than that - gardens beneath which rivers flow - and could make for you palaces.', NULL, NULL, NULL, NULL, NULL, 'https://everyayah.com/data/Alafasy_128kbps/025010.mp3', now()),
  (25, 11, '', '[{"id":12992,"position":1,"text_uthmani":"بَلْ","transliteration":"bal","translation_bn":"কিন্তু","root":"—","lemma":"بَل\r","grammar_bn":"প্রত্যাহার পদ (Retraction)"},{"id":12993,"position":2,"text_uthmani":"كَذَّبُوا۟","transliteration":"kadhabū","translation_bn":"তারা মিথ্যা ভাবছে","root":"كذب","lemma":"كَذَّبَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":12994,"position":3,"text_uthmani":"بِٱلسَّاعَةِ ۖ","transliteration":"bil-sāʿati","translation_bn":"ব্যাপারকে ক্বিয়ামাতের","root":"سوع","lemma":"سَاعَة","grammar_bn":"অব্যয় (Preposition)"},{"id":12996,"position":4,"text_uthmani":"وَأَعْتَدْنَا","transliteration":"wa-aʿtadnā","translation_bn":"আর আমরা প্রস্তুত করে রেখেছি","root":"عتد","lemma":"أَعْتَدَتْ","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":12997,"position":5,"text_uthmani":"لِمَن","transliteration":"liman","translation_bn":"জন্যে (তার) যে","root":"—","lemma":"مَن\r","grammar_bn":"অব্যয় (Preposition)"},{"id":12998,"position":6,"text_uthmani":"كَذَّبَ","transliteration":"kadhaba","translation_bn":"মিথ্যারোপ করেছে","root":"كذب","lemma":"كَذَّبَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":12999,"position":7,"text_uthmani":"بِٱلسَّاعَةِ","transliteration":"bil-sāʿati","translation_bn":"ব্যাপারকে ক্বিয়ামাতের","root":"سوع","lemma":"سَاعَة","grammar_bn":"অব্যয় (Preposition)"},{"id":13000,"position":8,"text_uthmani":"سَعِيرًا","transliteration":"saʿīran","translation_bn":"জ্বলন্ত অাগুন","root":"سعر","lemma":"سَعِير","grammar_bn":"বিশেষ্য (Noun)"},{"id":13001,"position":9,"text_uthmani":"١١","transliteration":"","translation_bn":"(১১)","root":"—","lemma":"١١","grammar_bn":"মার্কার"}]'::jsonb, 'bal kadhabū bil-sāʿati wa-aʿtadnā liman kadhaba bil-sāʿati saʿīran', 'আসলে তারা কিয়ামাতকে অস্বীকার করে, আর যারা কিয়ামাতকে অস্বীকার করে, তাদের জন্য আমি প্রস্তুত করে রেখেছি জ্বলন্ত আগুন।', 'But they have denied the Hour, and We have prepared for those who deny the Hour a Blaze.', 'আসলে তারা কিয়ামাতকে অস্বীকার করে, আর যারা কিয়ামাতকে অস্বীকার করে, তাদের জন্য আমি প্রস্তুত করে রেখেছি জ্বলন্ত আগুন।', 'But they have denied the Hour, and We have prepared for those who deny the Hour a Blaze.', NULL, NULL, NULL, NULL, NULL, 'https://everyayah.com/data/Alafasy_128kbps/025011.mp3', now()),
  (25, 12, '', '[{"id":14253,"position":1,"text_uthmani":"إِذَا","transliteration":"idhā","translation_bn":"যখন (আগুন )","root":"—","lemma":"إِذَا\r","grammar_bn":"কালবাচক (Time)"},{"id":14254,"position":2,"text_uthmani":"رَأَتْهُم","transliteration":"ra-athum","translation_bn":"তুমি দেখবে তাদেরকে","root":"راي","lemma":"رَءَا","grammar_bn":"ক্রিয়া (Verb)"},{"id":14255,"position":3,"text_uthmani":"مِّن","transliteration":"min","translation_bn":"হ''তে","root":"—","lemma":"مِن\r","grammar_bn":"অব্যয় (Preposition)"},{"id":14256,"position":4,"text_uthmani":"مَّكَانٍۭ","transliteration":"makānin","translation_bn":"জায়গা","root":"كون","lemma":"مَّكَان","grammar_bn":"বিশেষ্য (Noun)"},{"id":14257,"position":5,"text_uthmani":"بَعِيدٍۢ","transliteration":"baʿīdin","translation_bn":"দূরবর্তী","root":"بعد","lemma":"بَعِيد","grammar_bn":"বিশেষণ (Adjective)"},{"id":14258,"position":6,"text_uthmani":"سَمِعُوا۟","transliteration":"samiʿū","translation_bn":"তারা শুনতে পাবে (তখন)","root":"سمع","lemma":"سَمِعَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":14259,"position":7,"text_uthmani":"لَهَا","transliteration":"lahā","translation_bn":"প্রতি তার","root":"—","lemma":"لَهَا","grammar_bn":"অব্যয় (Preposition)"},{"id":14260,"position":8,"text_uthmani":"تَغَيُّظًۭا","transliteration":"taghayyuẓan","translation_bn":"ক্রোধের গর্জন","root":"غيظ","lemma":"تَغَيُّظ","grammar_bn":"বিশেষ্য (Noun)"},{"id":14261,"position":9,"text_uthmani":"وَزَفِيرًۭا","transliteration":"wazafīran","translation_bn":"ও চীৎকার","root":"زفر","lemma":"زَفِير","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":14262,"position":10,"text_uthmani":"١٢","transliteration":"","translation_bn":"(১২)","root":"—","lemma":"١٢","grammar_bn":"মার্কার"}]'::jsonb, 'idhā ra-athum min makānin baʿīdin samiʿū lahā taghayyuẓan wazafīran', 'আগুন যখন তাদেরকে বহু দূরবর্তী স্থান থেকে দেখবে, তখন তারা শুনতে পারে তার ক্রুদ্ধ গর্জন ও হুঙ্কার।', 'When the Hellfire sees them from a distant place, they will hear its fury and roaring.', 'আগুন যখন তাদেরকে বহু দূরবর্তী স্থান থেকে দেখবে, তখন তারা শুনতে পারে তার ক্রুদ্ধ গর্জন ও হুঙ্কার।', 'When the Hellfire sees them from a distant place, they will hear its fury and roaring.', NULL, NULL, NULL, NULL, NULL, 'https://everyayah.com/data/Alafasy_128kbps/025012.mp3', now()),
  (25, 13, '', '[{"id":15365,"position":1,"text_uthmani":"وَإِذَآ","transliteration":"wa-idhā","translation_bn":"এবং যখন","root":"—","lemma":"إِذَا\r","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":15366,"position":2,"text_uthmani":"أُلْقُوا۟","transliteration":"ul''qū","translation_bn":"নিক্ষেপ করা হবে","root":"لقي","lemma":"أَلْقَىٰ^","grammar_bn":"ক্রিয়া (Verb)"},{"id":15367,"position":3,"text_uthmani":"مِنْهَا","transliteration":"min''hā","translation_bn":"তার মধ্যে","root":"—","lemma":"مِن\r","grammar_bn":"অব্যয় (Preposition)"},{"id":15368,"position":4,"text_uthmani":"مَكَانًۭا","transliteration":"makānan","translation_bn":"জায়গায়","root":"كون","lemma":"مَّكَان","grammar_bn":"বিশেষ্য (Noun)"},{"id":15369,"position":5,"text_uthmani":"ضَيِّقًۭا","transliteration":"ḍayyiqan","translation_bn":"সংকীর্ণ","root":"ضيق","lemma":"ضَيِّق","grammar_bn":"বিশেষণ (Adjective)"},{"id":15370,"position":6,"text_uthmani":"مُّقَرَّنِينَ","transliteration":"muqarranīna","translation_bn":"শিকল পরা অবস্থায়","root":"قرن","lemma":"مُّقَرَّنِين","grammar_bn":"বিশেষ্য (Noun)"},{"id":15371,"position":7,"text_uthmani":"دَعَوْا۟","transliteration":"daʿaw","translation_bn":"তারা ডাকবে","root":"دعو","lemma":"دَعَا","grammar_bn":"ক্রিয়া (Verb)"},{"id":15372,"position":8,"text_uthmani":"هُنَالِكَ","transliteration":"hunālika","translation_bn":"সেখানে","root":"—","lemma":"هُنَالِك\r","grammar_bn":"কালবাচক (Time)"},{"id":15373,"position":9,"text_uthmani":"ثُبُورًۭا","transliteration":"thubūran","translation_bn":"মৃত্যুকে (ধ্বংস)","root":"ثبر","lemma":"ثُبُور","grammar_bn":"বিশেষ্য (Noun)"},{"id":15374,"position":10,"text_uthmani":"١٣","transliteration":"","translation_bn":"(১৩)","root":"—","lemma":"١٣","grammar_bn":"মার্কার"}]'::jsonb, 'wa-idhā ul''qū min''hā makānan ḍayyiqan muqarranīna daʿaw hunālika thubūran', 'যখন তাদেরকে এক সঙ্গে বেঁধে জাহান্নামের কোন সংকীর্ণ স্থানে নিক্ষেপ করা হবে, তখন সেখানে তারা মৃত্যুকে ডাকবে।', 'And when they are thrown into a narrow place therein bound in chains, they will cry out thereupon for destruction.', 'যখন তাদেরকে এক সঙ্গে বেঁধে জাহান্নামের কোন সংকীর্ণ স্থানে নিক্ষেপ করা হবে, তখন সেখানে তারা মৃত্যুকে ডাকবে।', 'And when they are thrown into a narrow place therein bound in chains, they will cry out thereupon for destruction.', NULL, NULL, NULL, NULL, NULL, 'https://everyayah.com/data/Alafasy_128kbps/025013.mp3', now()),
  (25, 14, '', '[{"id":16423,"position":1,"text_uthmani":"لَّا","transliteration":"lā","translation_bn":"\"(বলা হবে) না","root":"—","lemma":"لَا\r","grammar_bn":"নিষেধবাচক (Prohibition)"},{"id":16424,"position":2,"text_uthmani":"تَدْعُوا۟","transliteration":"tadʿū","translation_bn":"তোমরা ডাকো","root":"دعو","lemma":"دَعَا","grammar_bn":"ক্রিয়া (Verb)"},{"id":16425,"position":3,"text_uthmani":"ٱلْيَوْمَ","transliteration":"l-yawma","translation_bn":"আজ","root":"يوم","lemma":"يَوْم","grammar_bn":"শব্দ"},{"id":16426,"position":4,"text_uthmani":"ثُبُورًۭا","transliteration":"thubūran","translation_bn":"মৃত্যুকে (ধ্বংস)","root":"ثبر","lemma":"ثُبُور","grammar_bn":"বিশেষ্য (Noun)"},{"id":16427,"position":5,"text_uthmani":"وَٰحِدًۭا","transliteration":"wāḥidan","translation_bn":"এক (বার)","root":"وحد","lemma":"وَٰحِد","grammar_bn":"বিশেষণ (Adjective)"},{"id":16428,"position":6,"text_uthmani":"وَٱدْعُوا۟","transliteration":"wa-id''ʿū","translation_bn":"বরং তোমরা ডাকো","root":"دعو","lemma":"دَعَا","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":16429,"position":7,"text_uthmani":"ثُبُورًۭا","transliteration":"thubūran","translation_bn":"মৃত্যু","root":"ثبر","lemma":"ثُبُور","grammar_bn":"বিশেষ্য (Noun)"},{"id":16430,"position":8,"text_uthmani":"كَثِيرًۭا","transliteration":"kathīran","translation_bn":"বহুবার\"","root":"كثر","lemma":"كَثِير","grammar_bn":"বিশেষণ (Adjective)"},{"id":16431,"position":9,"text_uthmani":"١٤","transliteration":"","translation_bn":"(১৪)","root":"—","lemma":"١٤","grammar_bn":"মার্কার"}]'::jsonb, 'lā tadʿū l-yawma thubūran wāḥidan wa-id''ʿū thubūran kathīran', '(বলা হবে) ‘তোমরা আজ এক মৃত্যুকে ডেক না, অনেক মৃত্যুকে ডাক।’', '[They will be told], "Do not cry this Day for one destruction but cry for much destruction."', '(বলা হবে) ‘তোমরা আজ এক মৃত্যুকে ডেক না, অনেক মৃত্যুকে ডাক।’', '[They will be told], "Do not cry this Day for one destruction but cry for much destruction."', NULL, NULL, NULL, NULL, NULL, 'https://everyayah.com/data/Alafasy_128kbps/025014.mp3', now()),
  (25, 15, '', '[{"id":17658,"position":1,"text_uthmani":"قُلْ","transliteration":"qul","translation_bn":"বলো","root":"قول","lemma":"قَالَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":17659,"position":2,"text_uthmani":"أَذَٰلِكَ","transliteration":"adhālika","translation_bn":"\"কি এটা","root":"—","lemma":"ذَٰلِك","grammar_bn":"প্রশ্নবোধক (Interrogative)"},{"id":17660,"position":3,"text_uthmani":"خَيْرٌ","transliteration":"khayrun","translation_bn":"উত্তম","root":"خير","lemma":"خَيْر","grammar_bn":"বিশেষ্য (Noun)"},{"id":17661,"position":4,"text_uthmani":"أَمْ","transliteration":"am","translation_bn":"না","root":"—","lemma":"أَم\r","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":17662,"position":5,"text_uthmani":"جَنَّةُ","transliteration":"jannatu","translation_bn":"জান্নাত","root":"جنن","lemma":"جَنَّة","grammar_bn":"বিশেষ্য (Noun)"},{"id":17663,"position":6,"text_uthmani":"ٱلْخُلْدِ","transliteration":"l-khul''di","translation_bn":"চিরস্থায়ী","root":"خلد","lemma":"خُلْد","grammar_bn":"শব্দ"},{"id":17664,"position":7,"text_uthmani":"ٱلَّتِى","transliteration":"allatī","translation_bn":"যা","root":"—","lemma":"ٱلَّذِى","grammar_bn":"সাপেক্ষ সর্বনাম (Relative)"},{"id":17665,"position":8,"text_uthmani":"وُعِدَ","transliteration":"wuʿida","translation_bn":"প্রতিশ্রুতি দেয়া হয়েছে","root":"وعد","lemma":"وَعَدَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":17666,"position":9,"text_uthmani":"ٱلْمُتَّقُونَ ۚ","transliteration":"l-mutaqūna","translation_bn":"মুত্তাকীদেরকে","root":"وقي","lemma":"مُتَّقِين","grammar_bn":"শব্দ"},{"id":17668,"position":10,"text_uthmani":"كَانَتْ","transliteration":"kānat","translation_bn":"(সেটা) হবে","root":"كون","lemma":"كَانَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":17669,"position":11,"text_uthmani":"لَهُمْ","transliteration":"lahum","translation_bn":"জন্যে তাদের","root":"—","lemma":"لَهُمْ","grammar_bn":"অব্যয় (Preposition)"},{"id":17670,"position":12,"text_uthmani":"جَزَآءًۭ","transliteration":"jazāan","translation_bn":"পুরস্কার","root":"جزي","lemma":"جَزَا^ء","grammar_bn":"বিশেষ্য (Noun)"},{"id":17671,"position":13,"text_uthmani":"وَمَصِيرًۭا","transliteration":"wamaṣīran","translation_bn":"ও প্রত্যাবর্তনস্থল","root":"صير","lemma":"مَصِير","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":17672,"position":14,"text_uthmani":"١٥","transliteration":"","translation_bn":"(১৫)","root":"—","lemma":"١٥","grammar_bn":"মার্কার"}]'::jsonb, 'qul adhālika khayrun am jannatu l-khul''di allatī wuʿida l-mutaqūna kānat lahum jazāan wamaṣīran', 'তাদেরকে জিজ্ঞেস কর- এটাই উত্তম না চিরস্থায়ী জান্নাত, মুত্তাকীদেরকে যার ওয়াদা দেয়া হয়েছে? তাদের জন্য এটা হবে প্রতিদান ও শেষ আবাসস্থল।', 'Say, "Is that better or the Garden of Eternity which is promised to the righteous? It will be for them a reward and destination.', 'তাদেরকে জিজ্ঞেস কর- এটাই উত্তম না চিরস্থায়ী জান্নাত, মুত্তাকীদেরকে যার ওয়াদা দেয়া হয়েছে? তাদের জন্য এটা হবে প্রতিদান ও শেষ আবাসস্থল।', 'Say, "Is that better or the Garden of Eternity which is promised to the righteous? It will be for them a reward and destination.', NULL, NULL, NULL, NULL, NULL, 'https://everyayah.com/data/Alafasy_128kbps/025015.mp3', now()),
  (25, 16, '', '[{"id":18616,"position":1,"text_uthmani":"لَّهُمْ","transliteration":"lahum","translation_bn":"জন্যে তাদের (থাকবে)","root":"—","lemma":"لَّهُمْ","grammar_bn":"অব্যয় (Preposition)"},{"id":18617,"position":2,"text_uthmani":"فِيهَا","transliteration":"fīhā","translation_bn":"তার মধ্যে","root":"—","lemma":"فِى\r","grammar_bn":"অব্যয় (Preposition)"},{"id":18618,"position":3,"text_uthmani":"مَا","transliteration":"mā","translation_bn":"যা","root":"—","lemma":"مَا\r","grammar_bn":"সাপেক্ষ সর্বনাম (Relative)"},{"id":18619,"position":4,"text_uthmani":"يَشَآءُونَ","transliteration":"yashāūna","translation_bn":"তারা চাইবে","root":"شيا","lemma":"شَا^ءَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":18620,"position":5,"text_uthmani":"خَـٰلِدِينَ ۚ","transliteration":"khālidīna","translation_bn":"তারা স্থায়ী হবে (সেখানে)","root":"خلد","lemma":"خَٰلِد","grammar_bn":"বিশেষ্য (Noun)"},{"id":18622,"position":6,"text_uthmani":"كَانَ","transliteration":"kāna","translation_bn":"(এটা) হলো","root":"كون","lemma":"كَانَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":18623,"position":7,"text_uthmani":"عَلَىٰ","transliteration":"ʿalā","translation_bn":"উপর","root":"—","lemma":"عَلَىٰ\r","grammar_bn":"অব্যয় (Preposition)"},{"id":18624,"position":8,"text_uthmani":"رَبِّكَ","transliteration":"rabbika","translation_bn":"তোমার রবের","root":"ربب","lemma":"رَبّ","grammar_bn":"বিশেষ্য (Noun)"},{"id":18625,"position":9,"text_uthmani":"وَعْدًۭا","transliteration":"waʿdan","translation_bn":"প্রতিশ্রুতি","root":"وعد","lemma":"وَعْد","grammar_bn":"বিশেষ্য (Noun)"},{"id":18626,"position":10,"text_uthmani":"مَّسْـُٔولًۭا","transliteration":"masūlan","translation_bn":"অবশ্য পালনীয়\"","root":"سال","lemma":"مَسْـ#ُول","grammar_bn":"বিশেষ্য (Noun)"},{"id":18627,"position":11,"text_uthmani":"١٦","transliteration":"","translation_bn":"(১৬)","root":"—","lemma":"١٦","grammar_bn":"মার্কার"}]'::jsonb, 'lahum fīhā mā yashāūna khālidīna kāna ʿalā rabbika waʿdan masūlan', 'সেখানে তাদের জন্য তা-ই থাকবে যা তারা ইচ্ছে করবে। সেখানে তারা চিরকাল থাকবে। এটা একটা ওয়াদা যা পূরণ করা তোমার প্রতিপালকের দায়িত্ব।', 'For them therein is whatever they wish, [while] abiding eternally. It is ever upon your Lord a promise [worthy to be] requested.', 'সেখানে তাদের জন্য তা-ই থাকবে যা তারা ইচ্ছে করবে। সেখানে তারা চিরকাল থাকবে। এটা একটা ওয়াদা যা পূরণ করা তোমার প্রতিপালকের দায়িত্ব।', 'For them therein is whatever they wish, [while] abiding eternally. It is ever upon your Lord a promise [worthy to be] requested.', NULL, NULL, NULL, NULL, NULL, 'https://everyayah.com/data/Alafasy_128kbps/025016.mp3', now()),
  (25, 17, '', '[{"id":19664,"position":1,"text_uthmani":"وَيَوْمَ","transliteration":"wayawma","translation_bn":"আর যেদিন","root":"يوم","lemma":"يَوْم","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":19665,"position":2,"text_uthmani":"يَحْشُرُهُمْ","transliteration":"yaḥshuruhum","translation_bn":"তিনি একত্র করবেন তাদেরকে","root":"حشر","lemma":"حَشَرَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":19666,"position":3,"text_uthmani":"وَمَا","transliteration":"wamā","translation_bn":"এবং যাদেরকে","root":"—","lemma":"مَا\r","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":19667,"position":4,"text_uthmani":"يَعْبُدُونَ","transliteration":"yaʿbudūna","translation_bn":"তারা ইবাদাত করতো","root":"عبد","lemma":"عَبَدَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":19668,"position":5,"text_uthmani":"مِن","transliteration":"min","translation_bn":"থেকে","root":"—","lemma":"مِن\r","grammar_bn":"অব্যয় (Preposition)"},{"id":19669,"position":6,"text_uthmani":"دُونِ","transliteration":"dūni","translation_bn":"পরিবর্তে","root":"دون","lemma":"دُون","grammar_bn":"বিশেষ্য (Noun)"},{"id":19670,"position":7,"text_uthmani":"ٱللَّهِ","transliteration":"l-lahi","translation_bn":"আল্লাহর","root":"اله","lemma":"ٱللَّه","grammar_bn":"নামবাচক বিশেষ্য (Proper Noun)"},{"id":19671,"position":8,"text_uthmani":"فَيَقُولُ","transliteration":"fayaqūlu","translation_bn":"তখন তিনি বলবেন","root":"قول","lemma":"قَالَ","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":19672,"position":9,"text_uthmani":"ءَأَنتُمْ","transliteration":"a-antum","translation_bn":"\"কি তোমরাই","root":"—","lemma":"ءَأَنتُمْ","grammar_bn":"প্রশ্নবোধক (Interrogative)"},{"id":19673,"position":10,"text_uthmani":"أَضْلَلْتُمْ","transliteration":"aḍlaltum","translation_bn":"তোমরা বিভ্রান্ত করেছিলে","root":"ضلل","lemma":"أَضَلَّ","grammar_bn":"ক্রিয়া (Verb)"},{"id":19674,"position":11,"text_uthmani":"عِبَادِى","transliteration":"ʿibādī","translation_bn":"আমার দাসদেরকে","root":"عبد","lemma":"عَبْد","grammar_bn":"বিশেষ্য (Noun)"},{"id":19675,"position":12,"text_uthmani":"هَـٰٓؤُلَآءِ","transliteration":"hāulāi","translation_bn":"এসব","root":"—","lemma":"هَٰذَا","grammar_bn":"নির্দেশক সর্বনাম (Demonstrative)"},{"id":19676,"position":13,"text_uthmani":"أَمْ","transliteration":"am","translation_bn":"না","root":"—","lemma":"أَم\r","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":19677,"position":14,"text_uthmani":"هُمْ","transliteration":"hum","translation_bn":"তারাই","root":"—","lemma":"هُمْ","grammar_bn":"সর্বনাম (Pronoun)"},{"id":19678,"position":15,"text_uthmani":"ضَلُّوا۟","transliteration":"ḍallū","translation_bn":"ভ্রান্ত হয়েছিলো","root":"ضلل","lemma":"ضَلَّ","grammar_bn":"ক্রিয়া (Verb)"},{"id":19679,"position":16,"text_uthmani":"ٱلسَّبِيلَ","transliteration":"l-sabīla","translation_bn":"পথ\"","root":"سبل","lemma":"سَبِيل","grammar_bn":"শব্দ"},{"id":19680,"position":17,"text_uthmani":"١٧","transliteration":"","translation_bn":"(১৭)","root":"—","lemma":"١٧","grammar_bn":"মার্কার"}]'::jsonb, 'wayawma yaḥshuruhum wamā yaʿbudūna min dūni l-lahi fayaqūlu a-antum aḍlaltum ʿibādī hāulāi am hum ḍallū l-sabīla', 'যেদিন তিনি তাদেরকে আর আল্লাহকে বাদ দিয়ে তারা যেগুলোর ‘ইবাদাত করত সেগুলোকে একত্র করবেন, সেদিন তিনি জিজ্ঞেস করবেন- ‘তোমরাই কি আমার এ সব বান্দাহদেরকে পথভ্রষ্ট করেছিলে? না তারা নিজেরাই পথ থেকে বিচ্যুত হয়েছিল?’', 'And [mention] the Day He will gather them and that which they worship besides Allah and will say, "Did you mislead these, My servants, or did they [themselves] stray from the way?"', 'যেদিন তিনি তাদেরকে আর আল্লাহকে বাদ দিয়ে তারা যেগুলোর ‘ইবাদাত করত সেগুলোকে একত্র করবেন, সেদিন তিনি জিজ্ঞেস করবেন- ‘তোমরাই কি আমার এ সব বান্দাহদেরকে পথভ্রষ্ট করেছিলে? না তারা নিজেরাই পথ থেকে বিচ্যুত হয়েছিল?’', 'And [mention] the Day He will gather them and that which they worship besides Allah and will say, "Did you mislead these, My servants, or did they [themselves] stray from the way?"', NULL, NULL, NULL, NULL, NULL, 'https://everyayah.com/data/Alafasy_128kbps/025017.mp3', now()),
  (25, 18, '', '[{"id":20757,"position":1,"text_uthmani":"قَالُوا۟","transliteration":"qālū","translation_bn":"তারা বলবে","root":"قول","lemma":"قَالَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":20758,"position":2,"text_uthmani":"سُبْحَـٰنَكَ","transliteration":"sub''ḥānaka","translation_bn":"\"সত্ত্বা আপনার পবিত্র মহান","root":"سبح","lemma":"سُبْحَٰن","grammar_bn":"বিশেষ্য (Noun)"},{"id":20759,"position":3,"text_uthmani":"مَا","transliteration":"mā","translation_bn":"না","root":"—","lemma":"مَا\r","grammar_bn":"না-বোধক (Negative)"},{"id":20760,"position":4,"text_uthmani":"كَانَ","transliteration":"kāna","translation_bn":"ছিলো","root":"كون","lemma":"كَانَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":20761,"position":5,"text_uthmani":"يَنۢبَغِى","transliteration":"yanbaghī","translation_bn":"উচিত","root":"بغي","lemma":"يَن[بَغِى","grammar_bn":"ক্রিয়া (Verb)"},{"id":20762,"position":6,"text_uthmani":"لَنَآ","transliteration":"lanā","translation_bn":"জন্যে আমাদের","root":"—","lemma":"لَنَآ","grammar_bn":"অব্যয় (Preposition)"},{"id":20763,"position":7,"text_uthmani":"أَن","transliteration":"an","translation_bn":"যে","root":"—","lemma":"أَن\r","grammar_bn":"অধীনস্থ যোজক (Subordinating)"},{"id":20764,"position":8,"text_uthmani":"نَّتَّخِذَ","transliteration":"nattakhidha","translation_bn":"গ্রহণ করবো আমরা","root":"اخذ","lemma":"ٱتَّخَذَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":20765,"position":9,"text_uthmani":"مِن","transliteration":"min","translation_bn":"থেকে","root":"—","lemma":"مِن\r","grammar_bn":"অব্যয় (Preposition)"},{"id":20766,"position":10,"text_uthmani":"دُونِكَ","transliteration":"dūnika","translation_bn":"আপনার পরিবর্তে","root":"دون","lemma":"دُون","grammar_bn":"বিশেষ্য (Noun)"},{"id":20767,"position":11,"text_uthmani":"مِنْ","transliteration":"min","translation_bn":"কোন","root":"—","lemma":"مِن\r","grammar_bn":"অব্যয় (Preposition)"},{"id":20768,"position":12,"text_uthmani":"أَوْلِيَآءَ","transliteration":"awliyāa","translation_bn":"অভিভাবক","root":"ولي","lemma":"وَلِىّ","grammar_bn":"বিশেষ্য (Noun)"},{"id":20769,"position":13,"text_uthmani":"وَلَـٰكِن","transliteration":"walākin","translation_bn":"কিন্তু","root":"—","lemma":"لَٰكِن\r","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":20770,"position":14,"text_uthmani":"مَّتَّعْتَهُمْ","transliteration":"mattaʿtahum","translation_bn":"আপনি ভোগ-সম্ভার দিয়েছেলেন তাদেরকে","root":"متع","lemma":"مَّتَّعْ","grammar_bn":"ক্রিয়া (Verb)"},{"id":20771,"position":15,"text_uthmani":"وَءَابَآءَهُمْ","transliteration":"waābāahum","translation_bn":"এবং তাদের পিতৃ পুরুষদেরকেও","root":"ابو","lemma":"ا^بَاء","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":20772,"position":16,"text_uthmani":"حَتَّىٰ","transliteration":"ḥattā","translation_bn":"শেষ পর্যন্ত","root":"—","lemma":"حَتَّىٰ\r","grammar_bn":"অব্যয় (Preposition)"},{"id":20773,"position":17,"text_uthmani":"نَسُوا۟","transliteration":"nasū","translation_bn":"তারা ভুলে গিয়েছিলো","root":"نسي","lemma":"نَسِىَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":20774,"position":18,"text_uthmani":"ٱلذِّكْرَ","transliteration":"l-dhik''ra","translation_bn":"(আপনার) স্মরণ","root":"ذكر","lemma":"ذِكْر","grammar_bn":"শব্দ"},{"id":20775,"position":19,"text_uthmani":"وَكَانُوا۟","transliteration":"wakānū","translation_bn":"এবং তারা হয়েছিলো","root":"كون","lemma":"كَانَ","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":20776,"position":20,"text_uthmani":"قَوْمًۢا","transliteration":"qawman","translation_bn":"জাতিতে","root":"قوم","lemma":"قَوْم","grammar_bn":"বিশেষ্য (Noun)"},{"id":20777,"position":21,"text_uthmani":"بُورًۭا","transliteration":"būran","translation_bn":"ধ্বংসপ্রাপ্ত\"","root":"بور","lemma":"بُور","grammar_bn":"বিশেষণ (Adjective)"},{"id":20778,"position":22,"text_uthmani":"١٨","transliteration":"","translation_bn":"(১৮)","root":"—","lemma":"١٨","grammar_bn":"মার্কার"}]'::jsonb, 'qālū sub''ḥānaka mā kāna yanbaghī lanā an nattakhidha min dūnika min awliyāa walākin mattaʿtahum waābāahum ḥattā nasū l-dhik''ra wakānū qawman būran', 'তারা বলবে : ‘পবিত্র ও মহান তুমি। আমাদের জন্য শোভনীয় ছিল না যে তোমাকে বাদ দিয়ে অন্যান্য ইলাহ গ্রহণ করব, বরং তুমি ওদেরকে আর ওদের পিতৃপুরুষদেরকে দিয়েছিলে পার্থিব ভোগ সম্ভার, পরিণামে তারা ভুলে গিয়েছিল (তোমার প্রেরিত) বাণী, যার ফলে তারা পরিণত হল এক ধ্বংসপ্রাপ্ত জাতিতে।', 'They will say, "Exalted are You! It was not for us to take besides You any allies. But You provided comforts for them and their fathers until they forgot the message and became a people ruined."', 'তারা বলবে : ‘পবিত্র ও মহান তুমি। আমাদের জন্য শোভনীয় ছিল না যে তোমাকে বাদ দিয়ে অন্যান্য ইলাহ গ্রহণ করব, বরং তুমি ওদেরকে আর ওদের পিতৃপুরুষদেরকে দিয়েছিলে পার্থিব ভোগ সম্ভার, পরিণামে তারা ভুলে গিয়েছিল (তোমার প্রেরিত) বাণী, যার ফলে তারা পরিণত হল এক ধ্বংসপ্রাপ্ত জাতিতে।', 'They will say, "Exalted are You! It was not for us to take besides You any allies. But You provided comforts for them and their fathers until they forgot the message and became a people ruined."', NULL, NULL, NULL, NULL, NULL, 'https://everyayah.com/data/Alafasy_128kbps/025018.mp3', now()),
  (25, 19, '', '[{"id":21897,"position":1,"text_uthmani":"فَقَدْ","transliteration":"faqad","translation_bn":"\"তখন নিশ্চয়ই","root":"—","lemma":"قَد\r","grammar_bn":"শব্দ"},{"id":21898,"position":2,"text_uthmani":"كَذَّبُوكُم","transliteration":"kadhabūkum","translation_bn":"তারা মিথ্যা সাব্যস্ত করেছে তোমাদেরকে","root":"كذب","lemma":"كَذَّبَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":21899,"position":3,"text_uthmani":"بِمَا","transliteration":"bimā","translation_bn":"ঐবিষয় যা","root":"—","lemma":"مَا\r","grammar_bn":"অব্যয় (Preposition)"},{"id":21900,"position":4,"text_uthmani":"تَقُولُونَ","transliteration":"taqūlūna","translation_bn":"তোমরা বলছো","root":"قول","lemma":"قَالَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":21901,"position":5,"text_uthmani":"فَمَا","transliteration":"famā","translation_bn":"সুতরাং না","root":"—","lemma":"مَا\r","grammar_bn":"শব্দ"},{"id":21902,"position":6,"text_uthmani":"تَسْتَطِيعُونَ","transliteration":"tastaṭīʿūna","translation_bn":"তোমরা পারবে","root":"طوع","lemma":"ٱسْتَطَاعَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":21903,"position":7,"text_uthmani":"صَرْفًۭا","transliteration":"ṣarfan","translation_bn":"ফিরাতে (শাস্তি)","root":"صرف","lemma":"صَرْف","grammar_bn":"বিশেষ্য (Noun)"},{"id":21904,"position":8,"text_uthmani":"وَلَا","transliteration":"walā","translation_bn":"আর না","root":"—","lemma":"لَا\r","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":21905,"position":9,"text_uthmani":"نَصْرًۭا ۚ","transliteration":"naṣran","translation_bn":"সাহায্যও (পাবে)\"","root":"نصر","lemma":"نَصْر","grammar_bn":"বিশেষ্য (Noun)"},{"id":21907,"position":10,"text_uthmani":"وَمَن","transliteration":"waman","translation_bn":"আর যে","root":"—","lemma":"مَن\r","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":21908,"position":11,"text_uthmani":"يَظْلِم","transliteration":"yaẓlim","translation_bn":"সীমালঙ্ঘন করবে","root":"ظلم","lemma":"ظَلَمَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":21909,"position":12,"text_uthmani":"مِّنكُمْ","transliteration":"minkum","translation_bn":"তোমাদের মধ্য হ''তে","root":"—","lemma":"مِن\r","grammar_bn":"অব্যয় (Preposition)"},{"id":21910,"position":13,"text_uthmani":"نُذِقْهُ","transliteration":"nudhiq''hu","translation_bn":"তাকে আস্বাদ করাবো আমরা","root":"ذوق","lemma":"أَذَاقَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":21911,"position":14,"text_uthmani":"عَذَابًۭا","transliteration":"ʿadhāban","translation_bn":"শাস্তি","root":"عذب","lemma":"عَذَاب","grammar_bn":"বিশেষ্য (Noun)"},{"id":21912,"position":15,"text_uthmani":"كَبِيرًۭا","transliteration":"kabīran","translation_bn":"গুরুতর","root":"كبر","lemma":"كَبِير","grammar_bn":"বিশেষণ (Adjective)"},{"id":21913,"position":16,"text_uthmani":"١٩","transliteration":"","translation_bn":"(১৯)","root":"—","lemma":"١٩","grammar_bn":"মার্কার"}]'::jsonb, 'faqad kadhabūkum bimā taqūlūna famā tastaṭīʿūna ṣarfan walā naṣran waman yaẓlim minkum nudhiq''hu ʿadhāban kabīran', '(আল্লাহ মুশরিকদেরকে বলবেন) ‘তোমরা যা বলতে সে ব্যাপারে তারা তোমাদেরকে মিথ্যে প্রমাণিত করেছে। কাজেই তোমরা না পারবে (তোমাদের শাস্তি) প্রতিরোধ করতে আর না পাবে সাহায্য। তোমাদের মধ্যে যে অন্যায়কারী আমি তাকে গুরুতর শাস্তি আস্বাদন করাব।', 'So they will deny you, [disbelievers], in what you say, and you cannot avert [punishment] or [find] help. And whoever commits injustice among you - We will make him taste a great punishment.', '(আল্লাহ মুশরিকদেরকে বলবেন) ‘তোমরা যা বলতে সে ব্যাপারে তারা তোমাদেরকে মিথ্যে প্রমাণিত করেছে। কাজেই তোমরা না পারবে (তোমাদের শাস্তি) প্রতিরোধ করতে আর না পাবে সাহায্য। তোমাদের মধ্যে যে অন্যায়কারী আমি তাকে গুরুতর শাস্তি আস্বাদন করাব।', 'So they will deny you, [disbelievers], in what you say, and you cannot avert [punishment] or [find] help. And whoever commits injustice among you - We will make him taste a great punishment.', NULL, NULL, NULL, NULL, NULL, 'https://everyayah.com/data/Alafasy_128kbps/025019.mp3', now()),
  (25, 20, '', '[{"id":22941,"position":1,"text_uthmani":"وَمَآ","transliteration":"wamā","translation_bn":"আর (হে নাবী) না","root":"—","lemma":"مَا\r","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":22942,"position":2,"text_uthmani":"أَرْسَلْنَا","transliteration":"arsalnā","translation_bn":"আমরা পাঠিয়েছি","root":"رسل","lemma":"أَرْسَلَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":22943,"position":3,"text_uthmani":"قَبْلَكَ","transliteration":"qablaka","translation_bn":"তোমার পূর্বে (কাউকে)","root":"قبل","lemma":"قَبْل","grammar_bn":"কালবাচক (Time)"},{"id":22944,"position":4,"text_uthmani":"مِنَ","transliteration":"mina","translation_bn":"মধ্য হ''তে","root":"—","lemma":"مِن\r","grammar_bn":"অব্যয় (Preposition)"},{"id":22945,"position":5,"text_uthmani":"ٱلْمُرْسَلِينَ","transliteration":"l-mur''salīna","translation_bn":"রাসূলদের","root":"رسل","lemma":"مُّرْسَل","grammar_bn":"শব্দ"},{"id":22946,"position":6,"text_uthmani":"إِلَّآ","transliteration":"illā","translation_bn":"এ ছাড়া যে","root":"—","lemma":"إِلَّا\r","grammar_bn":"সীমাবদ্ধতা (Restriction)"},{"id":22947,"position":7,"text_uthmani":"إِنَّهُمْ","transliteration":"innahum","translation_bn":"নিশ্চয়ই তারা","root":"—","lemma":"إِنّ","grammar_bn":"অভিঘাত পদ (Accusative)"},{"id":22948,"position":8,"text_uthmani":"لَيَأْكُلُونَ","transliteration":"layakulūna","translation_bn":"অবশ্যই তারা খায়","root":"اكل","lemma":"أَكَلَ","grammar_bn":"দৃঢ়তাবোধক (Emphatic)"},{"id":22949,"position":9,"text_uthmani":"ٱلطَّعَامَ","transliteration":"l-ṭaʿāma","translation_bn":"খাবার","root":"طعم","lemma":"طَعَام","grammar_bn":"শব্দ"},{"id":22950,"position":10,"text_uthmani":"وَيَمْشُونَ","transliteration":"wayamshūna","translation_bn":"ও চলাফেরা করে","root":"مشي","lemma":"مَّشَ","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":22951,"position":11,"text_uthmani":"فِى","transliteration":"fī","translation_bn":"মধ্যে","root":"—","lemma":"فِى\r","grammar_bn":"অব্যয় (Preposition)"},{"id":22952,"position":12,"text_uthmani":"ٱلْأَسْوَاقِ ۗ","transliteration":"l-aswāqi","translation_bn":"হাট-বাজারগুলোর","root":"سوق","lemma":"سُّوق","grammar_bn":"শব্দ"},{"id":22954,"position":13,"text_uthmani":"وَجَعَلْنَا","transliteration":"wajaʿalnā","translation_bn":"আর আমরা করেছি","root":"جعل","lemma":"جَعَلَ","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":22955,"position":14,"text_uthmani":"بَعْضَكُمْ","transliteration":"baʿḍakum","translation_bn":"একে তোমাদের","root":"بعض","lemma":"بَعْض","grammar_bn":"বিশেষ্য (Noun)"},{"id":22956,"position":15,"text_uthmani":"لِبَعْضٍۢ","transliteration":"libaʿḍin","translation_bn":"জন্যে অপরের","root":"بعض","lemma":"بَعْض","grammar_bn":"অব্যয় (Preposition)"},{"id":22957,"position":16,"text_uthmani":"فِتْنَةً","transliteration":"fit''natan","translation_bn":"পরীক্ষাস্বরূপ","root":"فتن","lemma":"فِتْنَة","grammar_bn":"বিশেষ্য (Noun)"},{"id":22958,"position":17,"text_uthmani":"أَتَصْبِرُونَ ۗ","transliteration":"ataṣbirūna","translation_bn":"তোমরা ধৈর্য ধারণ করবে কি","root":"صبر","lemma":"صَبَرَ","grammar_bn":"প্রশ্নবোধক (Interrogative)"},{"id":22960,"position":18,"text_uthmani":"وَكَانَ","transliteration":"wakāna","translation_bn":"আর (জেনে রেখো) হলেন","root":"كون","lemma":"كَانَ","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":22961,"position":19,"text_uthmani":"رَبُّكَ","transliteration":"rabbuka","translation_bn":"তোমার রব (এমন যে)","root":"ربب","lemma":"رَبّ","grammar_bn":"বিশেষ্য (Noun)"},{"id":22962,"position":20,"text_uthmani":"بَصِيرًۭا","transliteration":"baṣīran","translation_bn":"তিনি সবকিছু দেখেন","root":"بصر","lemma":"بَصِير","grammar_bn":"বিশেষণ (Adjective)"},{"id":22963,"position":21,"text_uthmani":"٢٠","transliteration":"","translation_bn":"(২০)","root":"—","lemma":"٢٠","grammar_bn":"মার্কার"}]'::jsonb, 'wamā arsalnā qablaka mina l-mur''salīna illā innahum layakulūna l-ṭaʿāma wayamshūna fī l-aswāqi wajaʿalnā baʿḍakum libaʿḍin fit''natan ataṣbirūna wakāna rabbuka baṣīran', 'আমি তোমার পূর্বে যে সব রসূল পাঠিয়েছিলাম তারা সবাই খাদ্য গ্রহণ করত, আর হাট-বাজারে চলাফেরা করত। আমি তোমাদের এককে অপরের জন্য করেছি পরীক্ষাস্বরূপ (কাউকে করেছি ধনী, কাউকে গরীব, কাউকে সবল, কাউকে দুর্বল, কাউকে রুগ্ন, কাউকে সুস্থ), দেখি, তোমরা (নিজ নিজ অবস্থার উপর) ধৈর্য ধারণ কর কিনা। তোমার প্রতিপালক সব কিছু দেখেন।', 'And We did not send before you, [O Muhammad], any of the messengers except that they ate food and walked in the markets. And We have made some of you [people] as trial for others - will you have patience? And ever is your Lord, Seeing.', 'আমি তোমার পূর্বে যে সব রসূল পাঠিয়েছিলাম তারা সবাই খাদ্য গ্রহণ করত, আর হাট-বাজারে চলাফেরা করত। আমি তোমাদের এককে অপরের জন্য করেছি পরীক্ষাস্বরূপ (কাউকে করেছি ধনী, কাউকে গরীব, কাউকে সবল, কাউকে দুর্বল, কাউকে রুগ্ন, কাউকে সুস্থ), দেখি, তোমরা (নিজ নিজ অবস্থার উপর) ধৈর্য ধারণ কর কিনা। তোমার প্রতিপালক সব কিছু দেখেন।', 'And We did not send before you, [O Muhammad], any of the messengers except that they ate food and walked in the markets. And We have made some of you [people] as trial for others - will you have patience? And ever is your Lord, Seeing.', NULL, NULL, NULL, NULL, NULL, 'https://everyayah.com/data/Alafasy_128kbps/025020.mp3', now()),
  (25, 21, '', '[{"id":24183,"position":1,"text_uthmani":"۞ وَقَالَ","transliteration":"waqāla","translation_bn":"এবং বলবে","root":"قول","lemma":"قَالَ","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":24184,"position":2,"text_uthmani":"ٱلَّذِينَ","transliteration":"alladhīna","translation_bn":"(তারা) যারা","root":"—","lemma":"ٱلَّذِى","grammar_bn":"সাপেক্ষ সর্বনাম (Relative)"},{"id":24185,"position":3,"text_uthmani":"لَا","transliteration":"lā","translation_bn":"না","root":"—","lemma":"لَا\r","grammar_bn":"না-বোধক (Negative)"},{"id":24186,"position":4,"text_uthmani":"يَرْجُونَ","transliteration":"yarjūna","translation_bn":"আশা করে","root":"رجو","lemma":"يَرْجُوا@","grammar_bn":"ক্রিয়া (Verb)"},{"id":24187,"position":5,"text_uthmani":"لِقَآءَنَا","transliteration":"liqāanā","translation_bn":"প্রতি আমাদের সাক্ষাতের","root":"لقي","lemma":"لِقَا^ء","grammar_bn":"বিশেষ্য (Noun)"},{"id":24188,"position":6,"text_uthmani":"لَوْلَآ","transliteration":"lawlā","translation_bn":"\"কেন না","root":"—","lemma":"لَوْلَا^\r","grammar_bn":"উৎসাহবাচক (Exhortation)"},{"id":24189,"position":7,"text_uthmani":"أُنزِلَ","transliteration":"unzila","translation_bn":"অবতীর্ণ করা হলো","root":"نزل","lemma":"أَنزَلَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":24190,"position":8,"text_uthmani":"عَلَيْنَا","transliteration":"ʿalaynā","translation_bn":"আমাদের উপর","root":"—","lemma":"عَلَىٰ\r","grammar_bn":"অব্যয় (Preposition)"},{"id":24191,"position":9,"text_uthmani":"ٱلْمَلَـٰٓئِكَةُ","transliteration":"l-malāikatu","translation_bn":"ফেরেশতাদের","root":"ملك","lemma":"مَلَك","grammar_bn":"শব্দ"},{"id":24192,"position":10,"text_uthmani":"أَوْ","transliteration":"aw","translation_bn":"অথবা","root":"—","lemma":"أَو\r","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":24193,"position":11,"text_uthmani":"نَرَىٰ","transliteration":"narā","translation_bn":"আমরা প্রত্যক্ষ করি","root":"راي","lemma":"رَءَا","grammar_bn":"ক্রিয়া (Verb)"},{"id":24194,"position":12,"text_uthmani":"رَبَّنَا ۗ","transliteration":"rabbanā","translation_bn":"আমাদের রবকে\"","root":"ربب","lemma":"رَبّ","grammar_bn":"বিশেষ্য (Noun)"},{"id":24196,"position":13,"text_uthmani":"لَقَدِ","transliteration":"laqadi","translation_bn":"নিশ্চয়ই","root":"—","lemma":"قَد\r","grammar_bn":"দৃঢ়তাবোধক (Emphatic)"},{"id":24197,"position":14,"text_uthmani":"ٱسْتَكْبَرُوا۟","transliteration":"is''takbarū","translation_bn":"তারা অহঙ্কার করেছে","root":"كبر","lemma":"ٱسْتَكْبَرَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":24198,"position":15,"text_uthmani":"فِىٓ","transliteration":"fī","translation_bn":"মধ্যে","root":"—","lemma":"فِى\r","grammar_bn":"অব্যয় (Preposition)"},{"id":24199,"position":16,"text_uthmani":"أَنفُسِهِمْ","transliteration":"anfusihim","translation_bn":"নিজেদের মনের তাদের","root":"نفس","lemma":"نَفْس","grammar_bn":"বিশেষ্য (Noun)"},{"id":24200,"position":17,"text_uthmani":"وَعَتَوْ","transliteration":"waʿataw","translation_bn":"ও  অবাধ্য হয়েছে","root":"عتو","lemma":"عَتَ","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":24201,"position":18,"text_uthmani":"عُتُوًّۭا","transliteration":"ʿutuwwan","translation_bn":"অবাধ্য","root":"عتو","lemma":"عُتُوّ","grammar_bn":"বিশেষ্য (Noun)"},{"id":24202,"position":19,"text_uthmani":"كَبِيرًۭا","transliteration":"kabīran","translation_bn":"গুরুতর","root":"كبر","lemma":"كَبِير","grammar_bn":"বিশেষণ (Adjective)"},{"id":24203,"position":20,"text_uthmani":"٢١","transliteration":"","translation_bn":"(২১)","root":"—","lemma":"٢١","grammar_bn":"মার্কার"}]'::jsonb, 'waqāla alladhīna lā yarjūna liqāanā lawlā unzila ʿalaynā l-malāikatu aw narā rabbanā laqadi is''takbarū fī anfusihim waʿataw ʿutuwwan kabīran', 'যারা আমার সাক্ষাৎ আশা করে না তারা বলে, আমাদের কাছে ফেরেশতা নাযিল করা হয় না কেন? অথবা আমরা আমাদের প্রতিপালককে দেখতে পাই না কেন? তারা নিজেদের অন্তরে অহংকার পোষণ করে আর তারা মেতে উঠেছে গুরুতর অবাধ্যতায়।', 'And those who do not expect the meeting with Us say, "Why were not angels sent down to us, or [why] do we [not] see our Lord?" They have certainly become arrogant within themselves and [become] insolent with great insolence.', 'যারা আমার সাক্ষাৎ আশা করে না তারা বলে, আমাদের কাছে ফেরেশতা নাযিল করা হয় না কেন? অথবা আমরা আমাদের প্রতিপালককে দেখতে পাই না কেন? তারা নিজেদের অন্তরে অহংকার পোষণ করে আর তারা মেতে উঠেছে গুরুতর অবাধ্যতায়।', 'And those who do not expect the meeting with Us say, "Why were not angels sent down to us, or [why] do we [not] see our Lord?" They have certainly become arrogant within themselves and [become] insolent with great insolence.', NULL, NULL, NULL, NULL, NULL, 'https://everyayah.com/data/Alafasy_128kbps/025021.mp3', now()),
  (25, 22, '', '[{"id":25007,"position":1,"text_uthmani":"يَوْمَ","transliteration":"yawma","translation_bn":"যেদিন","root":"يوم","lemma":"يَوْم","grammar_bn":"বিশেষ্য (Noun)"},{"id":25008,"position":2,"text_uthmani":"يَرَوْنَ","transliteration":"yarawna","translation_bn":"তারা দেখবে","root":"راي","lemma":"رَءَا","grammar_bn":"ক্রিয়া (Verb)"},{"id":25009,"position":3,"text_uthmani":"ٱلْمَلَـٰٓئِكَةَ","transliteration":"l-malāikata","translation_bn":"ফেরেশতাদেরকে","root":"ملك","lemma":"مَلَك","grammar_bn":"শব্দ"},{"id":25010,"position":4,"text_uthmani":"لَا","transliteration":"lā","translation_bn":"না","root":"—","lemma":"لَا\r","grammar_bn":"না-বোধক (Negative)"},{"id":25011,"position":5,"text_uthmani":"بُشْرَىٰ","transliteration":"bush''rā","translation_bn":"সুসংবাদ (থাকবে)","root":"بشر","lemma":"بُشْرَىٰ","grammar_bn":"বিশেষ্য (Noun)"},{"id":25012,"position":6,"text_uthmani":"يَوْمَئِذٍۢ","transliteration":"yawma-idhin","translation_bn":"সেদিন","root":"—","lemma":"يَوْمَئِذ\r","grammar_bn":"কালবাচক (Time)"},{"id":25013,"position":7,"text_uthmani":"لِّلْمُجْرِمِينَ","transliteration":"lil''muj''rimīna","translation_bn":"জন্যে অপরাধীদের","root":"جرم","lemma":"مُجْرِم","grammar_bn":"অব্যয় (Preposition)"},{"id":25014,"position":8,"text_uthmani":"وَيَقُولُونَ","transliteration":"wayaqūlūna","translation_bn":"এবং তারা বলবে (আছে কি)","root":"قول","lemma":"قَالَ","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":25015,"position":9,"text_uthmani":"حِجْرًۭا","transliteration":"ḥij''ran","translation_bn":"\"কোন আড়াল","root":"حجر","lemma":"حِجْر","grammar_bn":"বিশেষ্য (Noun)"},{"id":25016,"position":10,"text_uthmani":"مَّحْجُورًۭا","transliteration":"maḥjūran","translation_bn":"দুর্ভেদ্য\"","root":"حجر","lemma":"مَّحْجُور","grammar_bn":"বিশেষ্য (Noun)"},{"id":25017,"position":11,"text_uthmani":"٢٢","transliteration":"","translation_bn":"(২২)","root":"—","lemma":"٢٢","grammar_bn":"মার্কার"}]'::jsonb, 'yawma yarawna l-malāikata lā bush''rā yawma-idhin lil''muj''rimīna wayaqūlūna ḥij''ran maḥjūran', 'যেদিন তারা ফেরেশতাদেরকে দেখতে পাবে, অপরাধীদের জন্য সেদিন কোন সুখবর থাকবে না, আর (ফেরেশতাগণ বলবে তোমাদের সুখ-শান্তির পথে আছে) দুর্লঙ্ঘ বাধা।', 'The day they see the angels - no good tidings will there be that day for the criminals, and [the angels] will say, "Prevented and inaccessible."', 'যেদিন তারা ফেরেশতাদেরকে দেখতে পাবে, অপরাধীদের জন্য সেদিন কোন সুখবর থাকবে না, আর (ফেরেশতাগণ বলবে তোমাদের সুখ-শান্তির পথে আছে) দুর্লঙ্ঘ বাধা।', 'The day they see the angels - no good tidings will there be that day for the criminals, and [the angels] will say, "Prevented and inaccessible."', NULL, NULL, NULL, NULL, NULL, 'https://everyayah.com/data/Alafasy_128kbps/025022.mp3', now()),
  (25, 23, '', '[{"id":26074,"position":1,"text_uthmani":"وَقَدِمْنَآ","transliteration":"waqadim''nā","translation_bn":"এবং আমরা অগ্রসর হবো (বিবেচনা করবো)","root":"قدم","lemma":"قَدِمْ","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":26075,"position":2,"text_uthmani":"إِلَىٰ","transliteration":"ilā","translation_bn":"(তার) প্রতি","root":"—","lemma":"إِلَىٰ\r","grammar_bn":"অব্যয় (Preposition)"},{"id":26076,"position":3,"text_uthmani":"مَا","transliteration":"mā","translation_bn":"যা","root":"—","lemma":"مَا\r","grammar_bn":"সাপেক্ষ সর্বনাম (Relative)"},{"id":26077,"position":4,"text_uthmani":"عَمِلُوا۟","transliteration":"ʿamilū","translation_bn":"তারা করেছে","root":"عمل","lemma":"عَمِلَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":26078,"position":5,"text_uthmani":"مِنْ","transliteration":"min","translation_bn":"কোন","root":"—","lemma":"مِن\r","grammar_bn":"অব্যয় (Preposition)"},{"id":26079,"position":6,"text_uthmani":"عَمَلٍۢ","transliteration":"ʿamalin","translation_bn":"কাজ","root":"عمل","lemma":"عَمَل","grammar_bn":"বিশেষ্য (Noun)"},{"id":26080,"position":7,"text_uthmani":"فَجَعَلْنَـٰهُ","transliteration":"fajaʿalnāhu","translation_bn":"অতঃপর তা আমরা পরিণত করবো","root":"جعل","lemma":"جَعَلَ","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":26081,"position":8,"text_uthmani":"هَبَآءًۭ","transliteration":"habāan","translation_bn":"ধুলিকণায়","root":"هبو","lemma":"هَبَا^ء","grammar_bn":"বিশেষ্য (Noun)"},{"id":26082,"position":9,"text_uthmani":"مَّنثُورًا","transliteration":"manthūran","translation_bn":"বিক্ষিপ্ত","root":"نثر","lemma":"مَّنثُور","grammar_bn":"বিশেষ্য (Noun)"},{"id":26083,"position":10,"text_uthmani":"٢٣","transliteration":"","translation_bn":"(২৩)","root":"—","lemma":"٢٣","grammar_bn":"মার্কার"}]'::jsonb, 'waqadim''nā ilā mā ʿamilū min ʿamalin fajaʿalnāhu habāan manthūran', 'তারা (দুনিয়ায়) যে ‘আমাল করেছিল আমি সেদিকে অগ্রসর হব, অতঃপর তাকে বানিয়ে দেব ছড়ানো ছিটানো ধূলিকণা (সদৃশ)।', 'And We will regard what they have done of deeds and make them as dust dispersed.', 'তারা (দুনিয়ায়) যে ‘আমাল করেছিল আমি সেদিকে অগ্রসর হব, অতঃপর তাকে বানিয়ে দেব ছড়ানো ছিটানো ধূলিকণা (সদৃশ)।', 'And We will regard what they have done of deeds and make them as dust dispersed.', NULL, NULL, NULL, NULL, NULL, 'https://everyayah.com/data/Alafasy_128kbps/025023.mp3', now()),
  (25, 24, '', '[{"id":26908,"position":1,"text_uthmani":"أَصْحَـٰبُ","transliteration":"aṣḥābu","translation_bn":"অধিবাসীদের (জন্যে)","root":"صحب","lemma":"أَصْحَٰب","grammar_bn":"বিশেষ্য (Noun)"},{"id":26909,"position":2,"text_uthmani":"ٱلْجَنَّةِ","transliteration":"l-janati","translation_bn":"জান্নাতের","root":"جنن","lemma":"جَنَّة","grammar_bn":"শব্দ"},{"id":26910,"position":3,"text_uthmani":"يَوْمَئِذٍ","transliteration":"yawma-idhin","translation_bn":"সেদিন","root":"—","lemma":"يَوْمَئِذ\r","grammar_bn":"কালবাচক (Time)"},{"id":26911,"position":4,"text_uthmani":"خَيْرٌۭ","transliteration":"khayrun","translation_bn":"উত্তম","root":"خير","lemma":"خَيْر","grammar_bn":"বিশেষ্য (Noun)"},{"id":26912,"position":5,"text_uthmani":"مُّسْتَقَرًّۭا","transliteration":"mus''taqarran","translation_bn":"বাসস্থান (থাকবে)","root":"قرر","lemma":"مُسْتَقَرّ","grammar_bn":"বিশেষ্য (Noun)"},{"id":26913,"position":6,"text_uthmani":"وَأَحْسَنُ","transliteration":"wa-aḥsanu","translation_bn":"ও উৎকৃষ্ট","root":"حسن","lemma":"أَحْسَن","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":26914,"position":7,"text_uthmani":"مَقِيلًۭا","transliteration":"maqīlan","translation_bn":"(দুপুরের) বিশ্রামস্থল","root":"قيل","lemma":"مَقِيل","grammar_bn":"বিশেষ্য (Noun)"},{"id":26915,"position":8,"text_uthmani":"٢٤","transliteration":"","translation_bn":"(২৪)","root":"—","lemma":"٢٤","grammar_bn":"মার্কার"}]'::jsonb, 'aṣḥābu l-janati yawma-idhin khayrun mus''taqarran wa-aḥsanu maqīlan', 'সেদিন জান্নাতবাসীরা স্থায়ী বাসস্থান হিসেবে উত্তম আর বিশ্রামস্থল হিসেবে উৎকৃষ্ট অবস্থায় থাকবে।', 'The companions of Paradise, that Day, are [in] a better settlement and better resting place.', 'সেদিন জান্নাতবাসীরা স্থায়ী বাসস্থান হিসেবে উত্তম আর বিশ্রামস্থল হিসেবে উৎকৃষ্ট অবস্থায় থাকবে।', 'The companions of Paradise, that Day, are [in] a better settlement and better resting place.', NULL, NULL, NULL, NULL, NULL, 'https://everyayah.com/data/Alafasy_128kbps/025024.mp3', now()),
  (25, 25, '', '[{"id":28107,"position":1,"text_uthmani":"وَيَوْمَ","transliteration":"wayawma","translation_bn":"এবং সেদিন","root":"يوم","lemma":"يَوْم","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":28108,"position":2,"text_uthmani":"تَشَقَّقُ","transliteration":"tashaqqaqu","translation_bn":"বিদীর্ণ হবে","root":"شقق","lemma":"يَشَّقَّقُ","grammar_bn":"ক্রিয়া (Verb)"},{"id":28109,"position":3,"text_uthmani":"ٱلسَّمَآءُ","transliteration":"l-samāu","translation_bn":"আকাশ","root":"سمو","lemma":"سَمَا^ء","grammar_bn":"শব্দ"},{"id":28110,"position":4,"text_uthmani":"بِٱلْغَمَـٰمِ","transliteration":"bil-ghamāmi","translation_bn":"সহ মেঘ","root":"غمم","lemma":"غَمَٰم","grammar_bn":"অব্যয় (Preposition)"},{"id":28111,"position":5,"text_uthmani":"وَنُزِّلَ","transliteration":"wanuzzila","translation_bn":"ও অবতীর্ণ করা হবে","root":"نزل","lemma":"نَزَّلَ","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":28112,"position":6,"text_uthmani":"ٱلْمَلَـٰٓئِكَةُ","transliteration":"l-malāikatu","translation_bn":"ফেরেশতাদেরকে","root":"ملك","lemma":"مَلَك","grammar_bn":"শব্দ"},{"id":28113,"position":7,"text_uthmani":"تَنزِيلًا","transliteration":"tanzīlan","translation_bn":"অবতরণ (ক্রমাগতভাবে)","root":"نزل","lemma":"تَنزِيل","grammar_bn":"বিশেষ্য (Noun)"},{"id":28114,"position":8,"text_uthmani":"٢٥","transliteration":"","translation_bn":"(২৫)","root":"—","lemma":"٢٥","grammar_bn":"মার্কার"}]'::jsonb, 'wayawma tashaqqaqu l-samāu bil-ghamāmi wanuzzila l-malāikatu tanzīlan', 'সেদিন মেঘমালা সহ আকাশ বিদীর্ণ হবে আর ফেরেশতাদেরকে ধীরে ধীরে নীচে নামিয়ে দেয়া হবে।', 'And [mention] the Day when the heaven will split open with [emerging] clouds, and the angels will be sent down in successive descent.', 'সেদিন মেঘমালা সহ আকাশ বিদীর্ণ হবে আর ফেরেশতাদেরকে ধীরে ধীরে নীচে নামিয়ে দেয়া হবে।', 'And [mention] the Day when the heaven will split open with [emerging] clouds, and the angels will be sent down in successive descent.', NULL, NULL, NULL, NULL, NULL, 'https://everyayah.com/data/Alafasy_128kbps/025025.mp3', now()),
  (25, 26, '', '[{"id":29120,"position":1,"text_uthmani":"ٱلْمُلْكُ","transliteration":"al-mul''ku","translation_bn":"কর্তৃত্ব (হবে)","root":"ملك","lemma":"مُلْك","grammar_bn":"শব্দ"},{"id":29121,"position":2,"text_uthmani":"يَوْمَئِذٍ","transliteration":"yawma-idhin","translation_bn":"সেদিন","root":"—","lemma":"يَوْمَئِذ\r","grammar_bn":"কালবাচক (Time)"},{"id":29122,"position":3,"text_uthmani":"ٱلْحَقُّ","transliteration":"l-ḥaqu","translation_bn":"প্রকৃত (কর্তৃত্ব)","root":"حقق","lemma":"حَقّ","grammar_bn":"শব্দ"},{"id":29123,"position":4,"text_uthmani":"لِلرَّحْمَـٰنِ ۚ","transliteration":"lilrraḥmāni","translation_bn":"জন্যে দয়াময়ের","root":"رحم","lemma":"رَّحْمَٰن","grammar_bn":"অব্যয় (Preposition)"},{"id":29125,"position":5,"text_uthmani":"وَكَانَ","transliteration":"wakāna","translation_bn":"আর হবে","root":"كون","lemma":"كَانَ","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":29126,"position":6,"text_uthmani":"يَوْمًا","transliteration":"yawman","translation_bn":"সেদিন","root":"يوم","lemma":"يَوْم","grammar_bn":"বিশেষ্য (Noun)"},{"id":29127,"position":7,"text_uthmani":"عَلَى","transliteration":"ʿalā","translation_bn":"জন্যে","root":"—","lemma":"عَلَىٰ\r","grammar_bn":"অব্যয় (Preposition)"},{"id":29128,"position":8,"text_uthmani":"ٱلْكَـٰفِرِينَ","transliteration":"l-kāfirīna","translation_bn":"কাফিরদের","root":"كفر","lemma":"كَٰفِرُون","grammar_bn":"শব্দ"},{"id":29129,"position":9,"text_uthmani":"عَسِيرًۭا","transliteration":"ʿasīran","translation_bn":"কঠিন","root":"عسر","lemma":"عَسِير","grammar_bn":"বিশেষণ (Adjective)"},{"id":29130,"position":10,"text_uthmani":"٢٦","transliteration":"","translation_bn":"(২৬)","root":"—","lemma":"٢٦","grammar_bn":"মার্কার"}]'::jsonb, 'al-mul''ku yawma-idhin l-ḥaqu lilrraḥmāni wakāna yawman ʿalā l-kāfirīna ʿasīran', 'সেদিন সত্যিকারের কর্তৃত্ব হবে দয়াময় (আল্লাহ)’র এবং কাফিরদের জন্য দিনটি হবে কঠিন।', 'True sovereignty, that Day, is for the Most Merciful. And it will be upon the disbelievers a difficult Day.', 'সেদিন সত্যিকারের কর্তৃত্ব হবে দয়াময় (আল্লাহ)’র এবং কাফিরদের জন্য দিনটি হবে কঠিন।', 'True sovereignty, that Day, is for the Most Merciful. And it will be upon the disbelievers a difficult Day.', NULL, NULL, NULL, NULL, NULL, 'https://everyayah.com/data/Alafasy_128kbps/025026.mp3', now()),
  (25, 27, '', '[{"id":30030,"position":1,"text_uthmani":"وَيَوْمَ","transliteration":"wayawma","translation_bn":"এবং সেদিন","root":"يوم","lemma":"يَوْم","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":30031,"position":2,"text_uthmani":"يَعَضُّ","transliteration":"yaʿaḍḍu","translation_bn":"কামড়াবে","root":"عضض","lemma":"عَضُّ","grammar_bn":"ক্রিয়া (Verb)"},{"id":30032,"position":3,"text_uthmani":"ٱلظَّالِمُ","transliteration":"l-ẓālimu","translation_bn":"সীমালঙ্ঘনকারী","root":"ظلم","lemma":"ظَالِم","grammar_bn":"শব্দ"},{"id":30033,"position":4,"text_uthmani":"عَلَىٰ","transliteration":"ʿalā","translation_bn":"উপর","root":"—","lemma":"عَلَىٰ\r","grammar_bn":"অব্যয় (Preposition)"},{"id":30034,"position":5,"text_uthmani":"يَدَيْهِ","transliteration":"yadayhi","translation_bn":"তার দু''হাতের","root":"يدي","lemma":"يَد","grammar_bn":"বিশেষ্য (Noun)"},{"id":30035,"position":6,"text_uthmani":"يَقُولُ","transliteration":"yaqūlu","translation_bn":"বলবে","root":"قول","lemma":"قَالَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":30036,"position":7,"text_uthmani":"يَـٰلَيْتَنِى","transliteration":"yālaytanī","translation_bn":"\"হায়! আমার দুর্ভোগ","root":"—","lemma":"لَيْت","grammar_bn":"সম্বোধন পদ (Vocative)"},{"id":30037,"position":8,"text_uthmani":"ٱتَّخَذْتُ","transliteration":"ittakhadhtu","translation_bn":"আমি ধরতাম (যদি)","root":"اخذ","lemma":"ٱتَّخَذَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":30038,"position":9,"text_uthmani":"مَعَ","transliteration":"maʿa","translation_bn":"সাথে","root":"—","lemma":"مَع","grammar_bn":"স্থানবাচক (Location)"},{"id":30039,"position":10,"text_uthmani":"ٱلرَّسُولِ","transliteration":"l-rasūli","translation_bn":"রাসূলের","root":"رسل","lemma":"رَسُول","grammar_bn":"শব্দ"},{"id":30040,"position":11,"text_uthmani":"سَبِيلًۭا","transliteration":"sabīlan","translation_bn":"পথ","root":"سبل","lemma":"سَبِيل","grammar_bn":"বিশেষ্য (Noun)"},{"id":30041,"position":12,"text_uthmani":"٢٧","transliteration":"","translation_bn":"(২৭)","root":"—","lemma":"٢٧","grammar_bn":"মার্কার"}]'::jsonb, 'wayawma yaʿaḍḍu l-ẓālimu ʿalā yadayhi yaqūlu yālaytanī ittakhadhtu maʿa l-rasūli sabīlan', 'অপরাধী সেদিন স্বীয় হস্তদ্বয় দংশন করতে করতে বলবে, ‘হায় আফসোস! আমি যদি রসূলের সাথে পথ অবলম্বন করতাম।', 'And the Day the wrongdoer will bite on his hands [in regret] he will say, "Oh, I wish I had taken with the Messenger a way.', 'অপরাধী সেদিন স্বীয় হস্তদ্বয় দংশন করতে করতে বলবে, ‘হায় আফসোস! আমি যদি রসূলের সাথে পথ অবলম্বন করতাম।', 'And the Day the wrongdoer will bite on his hands [in regret] he will say, "Oh, I wish I had taken with the Messenger a way.', NULL, NULL, NULL, NULL, NULL, 'https://everyayah.com/data/Alafasy_128kbps/025027.mp3', now()),
  (25, 28, '', '[{"id":31080,"position":1,"text_uthmani":"يَـٰوَيْلَتَىٰ","transliteration":"yāwaylatā","translation_bn":"হায়! আমার দুর্ভাগ্য","root":"—","lemma":"وَيْل","grammar_bn":"সম্বোধন পদ (Vocative)"},{"id":31081,"position":2,"text_uthmani":"لَيْتَنِى","transliteration":"laytanī","translation_bn":"আমার দুর্ভোগ","root":"—","lemma":"لَيْت","grammar_bn":"অভিঘাত পদ (Accusative)"},{"id":31082,"position":3,"text_uthmani":"لَمْ","transliteration":"lam","translation_bn":"না","root":"—","lemma":"لَم\r","grammar_bn":"না-বোধক (Negative)"},{"id":31083,"position":4,"text_uthmani":"أَتَّخِذْ","transliteration":"attakhidh","translation_bn":"গ্রহণ করতাম","root":"اخذ","lemma":"ٱتَّخَذَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":31084,"position":5,"text_uthmani":"فُلَانًا","transliteration":"fulānan","translation_bn":"অমুককে","root":"فلن","lemma":"فُلَان","grammar_bn":"বিশেষ্য (Noun)"},{"id":31085,"position":6,"text_uthmani":"خَلِيلًۭا","transliteration":"khalīlan","translation_bn":"বন্ধুরূপে","root":"خلل","lemma":"خَلِيل","grammar_bn":"বিশেষ্য (Noun)"},{"id":31086,"position":7,"text_uthmani":"٢٨","transliteration":"","translation_bn":"(২৮)","root":"—","lemma":"٢٨","grammar_bn":"মার্কার"}]'::jsonb, 'yāwaylatā laytanī lam attakhidh fulānan khalīlan', 'হায় আমার দুর্ভাগ্য! আমি যদি অমুককে বন্ধুরূপে গ্রহণ না করতাম!', 'Oh, woe to me! I wish I had not taken that one as a friend.', 'হায় আমার দুর্ভাগ্য! আমি যদি অমুককে বন্ধুরূপে গ্রহণ না করতাম!', 'Oh, woe to me! I wish I had not taken that one as a friend.', NULL, NULL, NULL, NULL, NULL, 'https://everyayah.com/data/Alafasy_128kbps/025028.mp3', now()),
  (25, 29, '', '[{"id":32058,"position":1,"text_uthmani":"لَّقَدْ","transliteration":"laqad","translation_bn":"নিশ্চয়ই","root":"—","lemma":"قَد\r","grammar_bn":"দৃঢ়তাবোধক (Emphatic)"},{"id":32059,"position":2,"text_uthmani":"أَضَلَّنِى","transliteration":"aḍallanī","translation_bn":"আমাকে সে বিভ্রান্ত করেছে","root":"ضلل","lemma":"أَضَلَّ","grammar_bn":"ক্রিয়া (Verb)"},{"id":32060,"position":3,"text_uthmani":"عَنِ","transliteration":"ʿani","translation_bn":"হ''তে","root":"—","lemma":"عَن\r","grammar_bn":"অব্যয় (Preposition)"},{"id":32061,"position":4,"text_uthmani":"ٱلذِّكْرِ","transliteration":"l-dhik''ri","translation_bn":"উপদেশ (কুরআন)","root":"ذكر","lemma":"ذِكْر","grammar_bn":"শব্দ"},{"id":32062,"position":5,"text_uthmani":"بَعْدَ","transliteration":"baʿda","translation_bn":"এরপরও","root":"بعد","lemma":"بَعْد","grammar_bn":"কালবাচক (Time)"},{"id":32063,"position":6,"text_uthmani":"إِذْ","transliteration":"idh","translation_bn":"যখন","root":"—","lemma":"إِذ\r","grammar_bn":"কালবাচক (Time)"},{"id":32064,"position":7,"text_uthmani":"جَآءَنِى ۗ","transliteration":"jāanī","translation_bn":"আমার (নিকট) এসেছিলো","root":"جيا","lemma":"جَا^ءَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":32066,"position":8,"text_uthmani":"وَكَانَ","transliteration":"wakāna","translation_bn":"আর হলো","root":"كون","lemma":"كَانَ","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":32067,"position":9,"text_uthmani":"ٱلشَّيْطَـٰنُ","transliteration":"l-shayṭānu","translation_bn":"শয়তান","root":"شطن","lemma":"شَيْطَٰن","grammar_bn":"শব্দ"},{"id":32068,"position":10,"text_uthmani":"لِلْإِنسَـٰنِ","transliteration":"lil''insāni","translation_bn":"জন্যে মানুষের","root":"انس","lemma":"إِنسَٰن","grammar_bn":"অব্যয় (Preposition)"},{"id":32069,"position":11,"text_uthmani":"خَذُولًۭا","transliteration":"khadhūlan","translation_bn":"প্রতারক\"","root":"خذل","lemma":"خَذُول","grammar_bn":"বিশেষণ (Adjective)"},{"id":32070,"position":12,"text_uthmani":"٢٩","transliteration":"","translation_bn":"(২৯)","root":"—","lemma":"٢٩","grammar_bn":"মার্কার"}]'::jsonb, 'laqad aḍallanī ʿani l-dhik''ri baʿda idh jāanī wakāna l-shayṭānu lil''insāni khadhūlan', 'সে তো আমাকে উপদেশ বাণী থেকে বিভ্রান্ত করেছিল আমার কাছে তা আসার পর, শয়ত্বান মানুষের প্রতি বিশ্বাসঘাতক।', 'He led me away from the remembrance after it had come to me. And ever is Satan, to man, a deserter."', 'সে তো আমাকে উপদেশ বাণী থেকে বিভ্রান্ত করেছিল আমার কাছে তা আসার পর, শয়ত্বান মানুষের প্রতি বিশ্বাসঘাতক।', 'He led me away from the remembrance after it had come to me. And ever is Satan, to man, a deserter."', NULL, NULL, NULL, NULL, NULL, 'https://everyayah.com/data/Alafasy_128kbps/025029.mp3', now()),
  (25, 30, '', '[{"id":32586,"position":1,"text_uthmani":"وَقَالَ","transliteration":"waqāla","translation_bn":"এবং বলবে","root":"قول","lemma":"قَالَ","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":32587,"position":2,"text_uthmani":"ٱلرَّسُولُ","transliteration":"l-rasūlu","translation_bn":"রাসূল","root":"رسل","lemma":"رَسُول","grammar_bn":"শব্দ"},{"id":32588,"position":3,"text_uthmani":"يَـٰرَبِّ","transliteration":"yārabbi","translation_bn":"\"হে আমার রব","root":"ربب","lemma":"رَبّ","grammar_bn":"সম্বোধন পদ (Vocative)"},{"id":32589,"position":4,"text_uthmani":"إِنَّ","transliteration":"inna","translation_bn":"নিশ্চয়ই","root":"—","lemma":"إِنّ","grammar_bn":"অভিঘাত পদ (Accusative)"},{"id":32590,"position":5,"text_uthmani":"قَوْمِى","transliteration":"qawmī","translation_bn":"আমার জাতি","root":"قوم","lemma":"قَوْم","grammar_bn":"বিশেষ্য (Noun)"},{"id":32591,"position":6,"text_uthmani":"ٱتَّخَذُوا۟","transliteration":"ittakhadhū","translation_bn":"গ্রহণ করেছিলো","root":"اخذ","lemma":"ٱتَّخَذَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":32592,"position":7,"text_uthmani":"هَـٰذَا","transliteration":"hādhā","translation_bn":"এই","root":"—","lemma":"هَٰذَا","grammar_bn":"নির্দেশক সর্বনাম (Demonstrative)"},{"id":32593,"position":8,"text_uthmani":"ٱلْقُرْءَانَ","transliteration":"l-qur''āna","translation_bn":"কুরআনকে","root":"قرا","lemma":"قُرْءَان","grammar_bn":"শব্দ"},{"id":32594,"position":9,"text_uthmani":"مَهْجُورًۭا","transliteration":"mahjūran","translation_bn":"পরিত্যাজ্য\"","root":"هجر","lemma":"مَهْجُور","grammar_bn":"বিশেষ্য (Noun)"},{"id":32595,"position":10,"text_uthmani":"٣٠","transliteration":"","translation_bn":"(৩০)","root":"—","lemma":"٣٠","grammar_bn":"মার্কার"}]'::jsonb, 'waqāla l-rasūlu yārabbi inna qawmī ittakhadhū hādhā l-qur''āna mahjūran', 'রসূল বলবে- ‘হে আমার প্রতিপালক! আমার জাতির লোকেরা এ কুরআনকে পরিত্যক্ত গণ্য করেছিল।’', 'And the Messenger has said, "O my Lord, indeed my people have taken this Qur''an as [a thing] abandoned."', 'রসূল বলবে- ‘হে আমার প্রতিপালক! আমার জাতির লোকেরা এ কুরআনকে পরিত্যক্ত গণ্য করেছিল।’', 'And the Messenger has said, "O my Lord, indeed my people have taken this Qur''an as [a thing] abandoned."', NULL, NULL, NULL, NULL, NULL, 'https://everyayah.com/data/Alafasy_128kbps/025030.mp3', now()),
  (25, 31, '', '[{"id":33787,"position":1,"text_uthmani":"وَكَذَٰلِكَ","transliteration":"wakadhālika","translation_bn":"এবং এভাবে","root":"—","lemma":"ذَٰلِك","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":33788,"position":2,"text_uthmani":"جَعَلْنَا","transliteration":"jaʿalnā","translation_bn":"আমরা করেছি","root":"جعل","lemma":"جَعَلَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":33789,"position":3,"text_uthmani":"لِكُلِّ","transliteration":"likulli","translation_bn":"জন্যে প্রত্যেক","root":"كلل","lemma":"كُلّ","grammar_bn":"অব্যয় (Preposition)"},{"id":33790,"position":4,"text_uthmani":"نَبِىٍّ","transliteration":"nabiyyin","translation_bn":"নাবীর","root":"نبا","lemma":"نَّبِىّ","grammar_bn":"বিশেষ্য (Noun)"},{"id":33791,"position":5,"text_uthmani":"عَدُوًّۭا","transliteration":"ʿaduwwan","translation_bn":"শত্রু","root":"عدو","lemma":"عَدُوّ","grammar_bn":"বিশেষ্য (Noun)"},{"id":33792,"position":6,"text_uthmani":"مِّنَ","transliteration":"mina","translation_bn":"থেকে","root":"—","lemma":"مِن\r","grammar_bn":"অব্যয় (Preposition)"},{"id":33793,"position":7,"text_uthmani":"ٱلْمُجْرِمِينَ ۗ","transliteration":"l-muj''rimīna","translation_bn":"দুষ্কৃতিকারীদেরকে","root":"جرم","lemma":"مُجْرِم","grammar_bn":"শব্দ"},{"id":33795,"position":8,"text_uthmani":"وَكَفَىٰ","transliteration":"wakafā","translation_bn":"এবং যথেষ্ট","root":"كفي","lemma":"كَفَىٰ","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":33796,"position":9,"text_uthmani":"بِرَبِّكَ","transliteration":"birabbika","translation_bn":"তোমার রব (তোমার জন্যে)","root":"ربب","lemma":"رَبّ","grammar_bn":"অব্যয় (Preposition)"},{"id":33797,"position":10,"text_uthmani":"هَادِيًۭا","transliteration":"hādiyan","translation_bn":"পথপ্রদর্শক","root":"هدي","lemma":"هَادِي","grammar_bn":"বিশেষ্য (Noun)"},{"id":33798,"position":11,"text_uthmani":"وَنَصِيرًۭا","transliteration":"wanaṣīran","translation_bn":"ও সাহায্যকারীরূপে","root":"نصر","lemma":"نَصِير","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":33799,"position":12,"text_uthmani":"٣١","transliteration":"","translation_bn":"(৩১)","root":"—","lemma":"٣١","grammar_bn":"মার্কার"}]'::jsonb, 'wakadhālika jaʿalnā likulli nabiyyin ʿaduwwan mina l-muj''rimīna wakafā birabbika hādiyan wanaṣīran', 'এভাবেই আমি প্রত্যেক নবীর জন্য অপরাধীদের মধ্য হতে শত্রু বানিয়ে দিয়েছি, পথ প্রদর্শক ও সাহায্যকারী হিসেবে তোমার প্রতিপালকই যথেষ্ট।', 'And thus have We made for every prophet an enemy from among the criminals. But sufficient is your Lord as a guide and a helper.', 'এভাবেই আমি প্রত্যেক নবীর জন্য অপরাধীদের মধ্য হতে শত্রু বানিয়ে দিয়েছি, পথ প্রদর্শক ও সাহায্যকারী হিসেবে তোমার প্রতিপালকই যথেষ্ট।', 'And thus have We made for every prophet an enemy from among the criminals. But sufficient is your Lord as a guide and a helper.', NULL, NULL, NULL, NULL, NULL, 'https://everyayah.com/data/Alafasy_128kbps/025031.mp3', now()),
  (25, 32, '', '[{"id":35017,"position":1,"text_uthmani":"وَقَالَ","transliteration":"waqāla","translation_bn":"এবং বলে","root":"قول","lemma":"قَالَ","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":35018,"position":2,"text_uthmani":"ٱلَّذِينَ","transliteration":"alladhīna","translation_bn":"যারা","root":"—","lemma":"ٱلَّذِى","grammar_bn":"সাপেক্ষ সর্বনাম (Relative)"},{"id":35019,"position":3,"text_uthmani":"كَفَرُوا۟","transliteration":"kafarū","translation_bn":"অস্বীকার করেছে","root":"كفر","lemma":"كَفَرَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":35020,"position":4,"text_uthmani":"لَوْلَا","transliteration":"lawlā","translation_bn":"\"কেন না","root":"—","lemma":"لَوْلَا^\r","grammar_bn":"উৎসাহবাচক (Exhortation)"},{"id":35021,"position":5,"text_uthmani":"نُزِّلَ","transliteration":"nuzzila","translation_bn":"অবতীর্ণ হলো","root":"نزل","lemma":"نَزَّلَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":35022,"position":6,"text_uthmani":"عَلَيْهِ","transliteration":"ʿalayhi","translation_bn":"তার উপর","root":"—","lemma":"عَلَىٰ\r","grammar_bn":"অব্যয় (Preposition)"},{"id":35023,"position":7,"text_uthmani":"ٱلْقُرْءَانُ","transliteration":"l-qur''ānu","translation_bn":"কুরআন","root":"قرا","lemma":"قُرْءَان","grammar_bn":"শব্দ"},{"id":35024,"position":8,"text_uthmani":"جُمْلَةًۭ","transliteration":"jum''latan","translation_bn":"সমগ্র\"","root":"جمل","lemma":"جُمْلَة","grammar_bn":"বিশেষ্য (Noun)"},{"id":35025,"position":9,"text_uthmani":"وَٰحِدَةًۭ ۚ","transliteration":"wāḥidatan","translation_bn":"একবারে\"","root":"وحد","lemma":"وَٰحِدَة","grammar_bn":"বিশেষ্য (Noun)"},{"id":35027,"position":10,"text_uthmani":"كَذَٰلِكَ","transliteration":"kadhālika","translation_bn":"এভাবে (করেছি)","root":"—","lemma":"ذَٰلِك","grammar_bn":"অব্যয় (Preposition)"},{"id":35028,"position":11,"text_uthmani":"لِنُثَبِّتَ","transliteration":"linuthabbita","translation_bn":"যেন আমরা দৃঢ় করি","root":"ثبت","lemma":"ثَبَّتْ","grammar_bn":"শব্দ"},{"id":35029,"position":12,"text_uthmani":"بِهِۦ","transliteration":"bihi","translation_bn":"এদ্বারা","root":"—","lemma":"بِهِۦ","grammar_bn":"অব্যয় (Preposition)"},{"id":35030,"position":13,"text_uthmani":"فُؤَادَكَ ۖ","transliteration":"fuādaka","translation_bn":"তোমার অন্তরকে","root":"فاد","lemma":"فُؤَاد","grammar_bn":"বিশেষ্য (Noun)"},{"id":35032,"position":14,"text_uthmani":"وَرَتَّلْنَـٰهُ","transliteration":"warattalnāhu","translation_bn":"এবং তা আমরা আবৃত্তি করেছি (সাজিয়েছি)","root":"رتل","lemma":"رَتَّلْ","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":35033,"position":15,"text_uthmani":"تَرْتِيلًۭا","transliteration":"tartīlan","translation_bn":"থেমে থেমে আবৃত্তি (স্পষ্টভাবে সাজানো)","root":"رتل","lemma":"تَرْتِيل","grammar_bn":"বিশেষ্য (Noun)"},{"id":35034,"position":16,"text_uthmani":"٣٢","transliteration":"","translation_bn":"(৩২)","root":"—","lemma":"٣٢","grammar_bn":"মার্কার"}]'::jsonb, 'waqāla alladhīna kafarū lawlā nuzzila ʿalayhi l-qur''ānu jum''latan wāḥidatan kadhālika linuthabbita bihi fuādaka warattalnāhu tartīlan', 'কাফিররা বলে- তার কাছে পুরো কুরআন এক সাথে অবতীর্ণ করা হল না কেন? আমি এভাবেই অবতীর্ণ করেছি। তোমার হৃদয়কে তা দ্বারা সুদৃঢ় করার জন্য আমি তোমার কাছে তা ধীরে ধীরে পরিকল্পিত স্তরে ক্রমশঃ আবৃত্তি করিয়েছি।', 'And those who disbelieve say, "Why was the Qur''an not revealed to him all at once?" Thus [it is] that We may strengthen thereby your heart. And We have spaced it distinctly.', 'কাফিররা বলে- তার কাছে পুরো কুরআন এক সাথে অবতীর্ণ করা হল না কেন? আমি এভাবেই অবতীর্ণ করেছি। তোমার হৃদয়কে তা দ্বারা সুদৃঢ় করার জন্য আমি তোমার কাছে তা ধীরে ধীরে পরিকল্পিত স্তরে ক্রমশঃ আবৃত্তি করিয়েছি।', 'And those who disbelieve say, "Why was the Qur''an not revealed to him all at once?" Thus [it is] that We may strengthen thereby your heart. And We have spaced it distinctly.', NULL, NULL, NULL, NULL, NULL, 'https://everyayah.com/data/Alafasy_128kbps/025032.mp3', now()),
  (25, 33, '', '[{"id":35594,"position":1,"text_uthmani":"وَلَا","transliteration":"walā","translation_bn":"এবং না","root":"—","lemma":"لَا\r","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":35595,"position":2,"text_uthmani":"يَأْتُونَكَ","transliteration":"yatūnaka","translation_bn":"তোমার (কাছে) তারা আসে","root":"اتي","lemma":"أَتَى","grammar_bn":"ক্রিয়া (Verb)"},{"id":35596,"position":3,"text_uthmani":"بِمَثَلٍ","transliteration":"bimathalin","translation_bn":"নিয়ে কোন সমস্যাকে","root":"مثل","lemma":"مَثَل","grammar_bn":"অব্যয় (Preposition)"},{"id":35597,"position":4,"text_uthmani":"إِلَّا","transliteration":"illā","translation_bn":"এ ছাড়া যে","root":"—","lemma":"إِلَّا\r","grammar_bn":"সীমাবদ্ধতা (Restriction)"},{"id":35598,"position":5,"text_uthmani":"جِئْنَـٰكَ","transliteration":"ji''nāka","translation_bn":"তোমার কাছে আসি আমরা","root":"جيا","lemma":"جَا^ءَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":35599,"position":6,"text_uthmani":"بِٱلْحَقِّ","transliteration":"bil-ḥaqi","translation_bn":"ভাবে সঠিক (সমাধান)","root":"حقق","lemma":"حَقّ","grammar_bn":"অব্যয় (Preposition)"},{"id":35600,"position":7,"text_uthmani":"وَأَحْسَنَ","transliteration":"wa-aḥsana","translation_bn":"ও অতি উত্তম","root":"حسن","lemma":"أَحْسَن","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":35601,"position":8,"text_uthmani":"تَفْسِيرًا","transliteration":"tafsīran","translation_bn":"ব্যাখ্যা (প্রদান করি)","root":"فسر","lemma":"تَفْسِير","grammar_bn":"বিশেষ্য (Noun)"},{"id":35602,"position":9,"text_uthmani":"٣٣","transliteration":"","translation_bn":"(৩৩)","root":"—","lemma":"٣٣","grammar_bn":"মার্কার"}]'::jsonb, 'walā yatūnaka bimathalin illā ji''nāka bil-ḥaqi wa-aḥsana tafsīran', 'তোমার কাছে তারা এমন কোন সমস্যাই নিয়ে আসে না যার সঠিক সমাধান ও সুন্দর ব্যাখ্যা আমি তোমাকে দান করিনি।', 'And they do not come to you with an argument except that We bring you the truth and the best explanation.', 'তোমার কাছে তারা এমন কোন সমস্যাই নিয়ে আসে না যার সঠিক সমাধান ও সুন্দর ব্যাখ্যা আমি তোমাকে দান করিনি।', 'And they do not come to you with an argument except that We bring you the truth and the best explanation.', NULL, NULL, NULL, NULL, NULL, 'https://everyayah.com/data/Alafasy_128kbps/025033.mp3', now()),
  (25, 34, '', '[{"id":36415,"position":1,"text_uthmani":"ٱلَّذِينَ","transliteration":"alladhīna","translation_bn":"যাদেরকে","root":"—","lemma":"ٱلَّذِى","grammar_bn":"সাপেক্ষ সর্বনাম (Relative)"},{"id":36416,"position":2,"text_uthmani":"يُحْشَرُونَ","transliteration":"yuḥ''sharūna","translation_bn":"একত্র করা হবে","root":"حشر","lemma":"حَشَرَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":36417,"position":3,"text_uthmani":"عَلَىٰ","transliteration":"ʿalā","translation_bn":"উপর (ভর করে)","root":"—","lemma":"عَلَىٰ\r","grammar_bn":"অব্যয় (Preposition)"},{"id":36418,"position":4,"text_uthmani":"وُجُوهِهِمْ","transliteration":"wujūhihim","translation_bn":"মুখমণ্ডলের তাদের","root":"وجه","lemma":"وَجْه","grammar_bn":"বিশেষ্য (Noun)"},{"id":36419,"position":5,"text_uthmani":"إِلَىٰ","transliteration":"ilā","translation_bn":"দিকে","root":"—","lemma":"إِلَىٰ\r","grammar_bn":"অব্যয় (Preposition)"},{"id":36420,"position":6,"text_uthmani":"جَهَنَّمَ","transliteration":"jahannama","translation_bn":"জাহান্নামের","root":"—","lemma":"جَهَنَّم","grammar_bn":"নামবাচক বিশেষ্য (Proper Noun)"},{"id":36421,"position":7,"text_uthmani":"أُو۟لَـٰٓئِكَ","transliteration":"ulāika","translation_bn":"ঐসব লোকের  (জন্যে হবে)","root":"—","lemma":"أُولَٰ^ئِك","grammar_bn":"নির্দেশক সর্বনাম (Demonstrative)"},{"id":36422,"position":8,"text_uthmani":"شَرٌّۭ","transliteration":"sharrun","translation_bn":"নিকৃষ্ট","root":"شرر","lemma":"شَرّ","grammar_bn":"বিশেষ্য (Noun)"},{"id":36423,"position":9,"text_uthmani":"مَّكَانًۭا","transliteration":"makānan","translation_bn":"অবস্থান","root":"كون","lemma":"مَّكَان","grammar_bn":"বিশেষ্য (Noun)"},{"id":36424,"position":10,"text_uthmani":"وَأَضَلُّ","transliteration":"wa-aḍallu","translation_bn":"ও চূড়ান্তভাবে ভ্রষ্ট হয়েছে","root":"ضلل","lemma":"أَضَلّ","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":36425,"position":11,"text_uthmani":"سَبِيلًۭا","transliteration":"sabīlan","translation_bn":"পথ","root":"سبل","lemma":"سَبِيل","grammar_bn":"বিশেষ্য (Noun)"},{"id":36426,"position":12,"text_uthmani":"٣٤","transliteration":"","translation_bn":"(৩৪)","root":"—","lemma":"٣٤","grammar_bn":"মার্কার"}]'::jsonb, 'alladhīna yuḥ''sharūna ʿalā wujūhihim ilā jahannama ulāika sharrun makānan wa-aḍallu sabīlan', 'যাদেরকে মুখের ভরে জাহান্নামের পানে একত্রিত করা হবে, তারা মর্যাদার ক্ষেত্রে সবচেয়ে নিকৃষ্ট আর পথের দিক থেকে সবচেয়ে গুমরাহ্।', 'The ones who are gathered on their faces to Hell - those are the worst in position and farthest astray in [their] way.', 'যাদেরকে মুখের ভরে জাহান্নামের পানে একত্রিত করা হবে, তারা মর্যাদার ক্ষেত্রে সবচেয়ে নিকৃষ্ট আর পথের দিক থেকে সবচেয়ে গুমরাহ্।', 'The ones who are gathered on their faces to Hell - those are the worst in position and farthest astray in [their] way.', NULL, NULL, NULL, NULL, NULL, 'https://everyayah.com/data/Alafasy_128kbps/025034.mp3', now()),
  (25, 35, '', '[{"id":37378,"position":1,"text_uthmani":"وَلَقَدْ","transliteration":"walaqad","translation_bn":"এবং  নিশ্চয়ই","root":"—","lemma":"قَد\r","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":37379,"position":2,"text_uthmani":"ءَاتَيْنَا","transliteration":"ātaynā","translation_bn":"আমরা দিয়েছিলাম","root":"اتي","lemma":"ا^تَى","grammar_bn":"ক্রিয়া (Verb)"},{"id":37380,"position":3,"text_uthmani":"مُوسَى","transliteration":"mūsā","translation_bn":"মূসাকে","root":"—","lemma":"مُوسَىٰ","grammar_bn":"নামবাচক বিশেষ্য (Proper Noun)"},{"id":37381,"position":4,"text_uthmani":"ٱلْكِتَـٰبَ","transliteration":"l-kitāba","translation_bn":"কিতাব","root":"كتب","lemma":"كِتَٰب","grammar_bn":"শব্দ"},{"id":37382,"position":5,"text_uthmani":"وَجَعَلْنَا","transliteration":"wajaʿalnā","translation_bn":"ও আমরা করেছিলাম","root":"جعل","lemma":"جَعَلَ","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":37383,"position":6,"text_uthmani":"مَعَهُۥٓ","transliteration":"maʿahu","translation_bn":"তার সাথে","root":"—","lemma":"مَع","grammar_bn":"স্থানবাচক (Location)"},{"id":37384,"position":7,"text_uthmani":"أَخَاهُ","transliteration":"akhāhu","translation_bn":"তার ভাই","root":"اخو","lemma":"أَخ","grammar_bn":"বিশেষ্য (Noun)"},{"id":37385,"position":8,"text_uthmani":"هَـٰرُونَ","transliteration":"hārūna","translation_bn":"হারুনকে","root":"—","lemma":"هَٰرُون","grammar_bn":"নামবাচক বিশেষ্য (Proper Noun)"},{"id":37386,"position":9,"text_uthmani":"وَزِيرًۭا","transliteration":"wazīran","translation_bn":"সাহায্যকারী","root":"وزر","lemma":"وَزِير","grammar_bn":"বিশেষ্য (Noun)"},{"id":37387,"position":10,"text_uthmani":"٣٥","transliteration":"","translation_bn":"(৩৫)","root":"—","lemma":"٣٥","grammar_bn":"মার্কার"}]'::jsonb, 'walaqad ātaynā mūsā l-kitāba wajaʿalnā maʿahu akhāhu hārūna wazīran', 'আমি মূসাকে কিতাব দিয়েছিলাম আর তার সাথে তার ভাই হারূনকে আমি সাহায্যকারী বানিয়েছিলাম।', 'And We had certainly given Moses the Scripture and appointed with him his brother Aaron as an assistant.', 'আমি মূসাকে কিতাব দিয়েছিলাম আর তার সাথে তার ভাই হারূনকে আমি সাহায্যকারী বানিয়েছিলাম।', 'And We had certainly given Moses the Scripture and appointed with him his brother Aaron as an assistant.', NULL, NULL, NULL, NULL, NULL, 'https://everyayah.com/data/Alafasy_128kbps/025035.mp3', now()),
  (25, 36, '', '[{"id":38161,"position":1,"text_uthmani":"فَقُلْنَا","transliteration":"faqul''nā","translation_bn":"অতঃপর আমরা বলেছিলাম","root":"قول","lemma":"قَالَ","grammar_bn":"শব্দ"},{"id":38162,"position":2,"text_uthmani":"ٱذْهَبَآ","transliteration":"idh''habā","translation_bn":"\"দু''জনে যাও","root":"ذهب","lemma":"ذَهَبَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":38163,"position":3,"text_uthmani":"إِلَى","transliteration":"ilā","translation_bn":"প্রতি","root":"—","lemma":"إِلَىٰ\r","grammar_bn":"অব্যয় (Preposition)"},{"id":38164,"position":4,"text_uthmani":"ٱلْقَوْمِ","transliteration":"l-qawmi","translation_bn":"(সে জাতির) লোকদের","root":"قوم","lemma":"قَوْم","grammar_bn":"শব্দ"},{"id":38165,"position":5,"text_uthmani":"ٱلَّذِينَ","transliteration":"alladhīna","translation_bn":"যারা","root":"—","lemma":"ٱلَّذِى","grammar_bn":"সাপেক্ষ সর্বনাম (Relative)"},{"id":38166,"position":6,"text_uthmani":"كَذَّبُوا۟","transliteration":"kadhabū","translation_bn":"মিথ্যারোপ করেছে","root":"كذب","lemma":"كَذَّبَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":38167,"position":7,"text_uthmani":"بِـَٔايَـٰتِنَا","transliteration":"biāyātinā","translation_bn":"প্রতি আমার নির্দেশনাবলীর\"","root":"ايي","lemma":"ءَايَة","grammar_bn":"অব্যয় (Preposition)"},{"id":38168,"position":8,"text_uthmani":"فَدَمَّرْنَـٰهُمْ","transliteration":"fadammarnāhum","translation_bn":"ফলে আমরা ধ্বংস করে দিয়েছি তাদেরকে","root":"دمر","lemma":"دَمَّرَ","grammar_bn":"শব্দ"},{"id":38169,"position":9,"text_uthmani":"تَدْمِيرًۭا","transliteration":"tadmīran","translation_bn":"ধ্বংস (সম্পূর্ণ রূপে)","root":"دمر","lemma":"تَدْمِير","grammar_bn":"বিশেষ্য (Noun)"},{"id":38170,"position":10,"text_uthmani":"٣٦","transliteration":"","translation_bn":"(৩৬)","root":"—","lemma":"٣٦","grammar_bn":"মার্কার"}]'::jsonb, 'faqul''nā idh''habā ilā l-qawmi alladhīna kadhabū biāyātinā fadammarnāhum tadmīran', 'অতঃপর তাদেরকে বলেছিলাম, ‘তোমরা সেই জাতির নিকট যাও যারা আমার নিদর্শনকে প্রত্যাখ্যান করেছে।’ অতঃপর আমি তাদেরকে পূর্ণ বিধ্বস্তিতে বিধ্বস্ত করে দিয়েছিলাম।', 'And We said, "Go both of you to the people who have denied Our signs." Then We destroyed them with [complete] destruction.', 'অতঃপর তাদেরকে বলেছিলাম, ‘তোমরা সেই জাতির নিকট যাও যারা আমার নিদর্শনকে প্রত্যাখ্যান করেছে।’ অতঃপর আমি তাদেরকে পূর্ণ বিধ্বস্তিতে বিধ্বস্ত করে দিয়েছিলাম।', 'And We said, "Go both of you to the people who have denied Our signs." Then We destroyed them with [complete] destruction.', NULL, NULL, NULL, NULL, NULL, 'https://everyayah.com/data/Alafasy_128kbps/025036.mp3', now()),
  (25, 37, '', '[{"id":38776,"position":1,"text_uthmani":"وَقَوْمَ","transliteration":"waqawma","translation_bn":"এবং জাতি","root":"قوم","lemma":"قَوْم","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":38777,"position":2,"text_uthmani":"نُوحٍۢ","transliteration":"nūḥin","translation_bn":"নূহের","root":"—","lemma":"نُوح","grammar_bn":"নামবাচক বিশেষ্য (Proper Noun)"},{"id":38778,"position":3,"text_uthmani":"لَّمَّا","transliteration":"lammā","translation_bn":"যখন","root":"—","lemma":"لَمَّا\r","grammar_bn":"কালবাচক (Time)"},{"id":38779,"position":4,"text_uthmani":"كَذَّبُوا۟","transliteration":"kadhabū","translation_bn":"মিথ্যারোপ করেছিলো","root":"كذب","lemma":"كَذَّبَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":38780,"position":5,"text_uthmani":"ٱلرُّسُلَ","transliteration":"l-rusula","translation_bn":"রাসুলদেরকে","root":"رسل","lemma":"رَسُول","grammar_bn":"শব্দ"},{"id":38781,"position":6,"text_uthmani":"أَغْرَقْنَـٰهُمْ","transliteration":"aghraqnāhum","translation_bn":"আমরা ডুবিয়ে দিয়েছি তাদেরকে","root":"غرق","lemma":"أُغْرِقُ","grammar_bn":"ক্রিয়া (Verb)"},{"id":38782,"position":7,"text_uthmani":"وَجَعَلْنَـٰهُمْ","transliteration":"wajaʿalnāhum","translation_bn":"এবং আমরা করেছিলাম তাদেরকে","root":"جعل","lemma":"جَعَلَ","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":38783,"position":8,"text_uthmani":"لِلنَّاسِ","transliteration":"lilnnāsi","translation_bn":"জন্যে মানুষের","root":"نوس","lemma":"نَّاس","grammar_bn":"অব্যয় (Preposition)"},{"id":38784,"position":9,"text_uthmani":"ءَايَةًۭ ۖ","transliteration":"āyatan","translation_bn":"নিদর্শন","root":"ايي","lemma":"ءَايَة","grammar_bn":"বিশেষ্য (Noun)"},{"id":38786,"position":10,"text_uthmani":"وَأَعْتَدْنَا","transliteration":"wa-aʿtadnā","translation_bn":"আর আমরা প্রস্তুত করে রেখেছি","root":"عتد","lemma":"أَعْتَدَتْ","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":38787,"position":11,"text_uthmani":"لِلظَّـٰلِمِينَ","transliteration":"lilẓẓālimīna","translation_bn":"জন্যে সীমালঙ্ঘনকারীদের","root":"ظلم","lemma":"ظَالِم","grammar_bn":"অব্যয় (Preposition)"},{"id":38788,"position":12,"text_uthmani":"عَذَابًا","transliteration":"ʿadhāban","translation_bn":"শাস্তি","root":"عذب","lemma":"عَذَاب","grammar_bn":"বিশেষ্য (Noun)"},{"id":38789,"position":13,"text_uthmani":"أَلِيمًۭا","transliteration":"alīman","translation_bn":"নিদারুণ","root":"الم","lemma":"أَلِيم","grammar_bn":"বিশেষণ (Adjective)"},{"id":38790,"position":14,"text_uthmani":"٣٧","transliteration":"","translation_bn":"(৩৭)","root":"—","lemma":"٣٧","grammar_bn":"মার্কার"}]'::jsonb, 'waqawma nūḥin lammā kadhabū l-rusula aghraqnāhum wajaʿalnāhum lilnnāsi āyatan wa-aʿtadnā lilẓẓālimīna ʿadhāban alīman', 'আর নূহের জাতি যখন রসূলদেরকে মিথ্যারোপ করল, আমি তাদেরকে ডুবিয়ে দিলাম, আর মানুষের জন্য তাদেরকে নিদর্শন বানিয়ে দিলাম। আমি যালিমদের জন্য ভয়াবহ শাস্তি প্রস্তুত করে রেখেছি।', 'And the people of Noah - when they denied the messengers, We drowned them, and We made them for mankind a sign. And We have prepared for the wrongdoers a painful punishment.', 'আর নূহের জাতি যখন রসূলদেরকে মিথ্যারোপ করল, আমি তাদেরকে ডুবিয়ে দিলাম, আর মানুষের জন্য তাদেরকে নিদর্শন বানিয়ে দিলাম। আমি যালিমদের জন্য ভয়াবহ শাস্তি প্রস্তুত করে রেখেছি।', 'And the people of Noah - when they denied the messengers, We drowned them, and We made them for mankind a sign. And We have prepared for the wrongdoers a painful punishment.', NULL, NULL, NULL, NULL, NULL, 'https://everyayah.com/data/Alafasy_128kbps/025037.mp3', now()),
