  (26, 1, '', '[{"id":710,"position":1,"text_uthmani":"طسٓمٓ","transliteration":"tta-seen-meem","translation_bn":"ত্বা-সীন-মীম","root":"—","lemma":"طسٓمٓ","grammar_bn":"শব্দ"},{"id":711,"position":2,"text_uthmani":"١","transliteration":"","translation_bn":"(১)","root":"—","lemma":"١","grammar_bn":"মার্কার"}]'::jsonb, 'tta-seen-meem', 'ত্ব-সীন-মীম।', 'Ta, Seen, Meem.', 'ত্ব-সীন-মীম।', 'Ta, Seen, Meem.', NULL, NULL, NULL, NULL, NULL, 'https://everyayah.com/data/Alafasy_128kbps/026001.mp3', now()),
  (26, 2, '', '[{"id":1769,"position":1,"text_uthmani":"تِلْكَ","transliteration":"til''ka","translation_bn":"এই","root":"—","lemma":"ذَٰلِك","grammar_bn":"নির্দেশক সর্বনাম (Demonstrative)"},{"id":1770,"position":2,"text_uthmani":"ءَايَـٰتُ","transliteration":"āyātu","translation_bn":"আয়াতগুলো","root":"ايي","lemma":"ءَايَة","grammar_bn":"বিশেষ্য (Noun)"},{"id":1771,"position":3,"text_uthmani":"ٱلْكِتَـٰبِ","transliteration":"l-kitābi","translation_bn":"কিতাবের","root":"كتب","lemma":"كِتَٰب","grammar_bn":"শব্দ"},{"id":1772,"position":4,"text_uthmani":"ٱلْمُبِينِ","transliteration":"l-mubīni","translation_bn":"(যা) সুস্পষ্ট","root":"بين","lemma":"مُّبِين","grammar_bn":"শব্দ"},{"id":1773,"position":5,"text_uthmani":"٢","transliteration":"","translation_bn":"(২)","root":"—","lemma":"٢","grammar_bn":"মার্কার"}]'::jsonb, 'til''ka āyātu l-kitābi l-mubīni', 'এগুলো সুস্পষ্ট (বা সুস্পষ্টকারী) কিতাবের আয়াত।', 'These are the verses of the clear Book.', 'এগুলো সুস্পষ্ট (বা সুস্পষ্টকারী) কিতাবের আয়াত।', 'These are the verses of the clear Book.', NULL, NULL, NULL, NULL, NULL, 'https://everyayah.com/data/Alafasy_128kbps/026002.mp3', now()),
  (26, 3, '', '[{"id":2807,"position":1,"text_uthmani":"لَعَلَّكَ","transliteration":"laʿallaka","translation_bn":"হয়তো তুমি (হে নাবী)","root":"—","lemma":"لَعَلّ","grammar_bn":"অভিঘাত পদ (Accusative)"},{"id":2808,"position":2,"text_uthmani":"بَـٰخِعٌۭ","transliteration":"bākhiʿun","translation_bn":"ধ্বংসকারী","root":"بخع","lemma":"بَٰخِع","grammar_bn":"বিশেষ্য (Noun)"},{"id":2809,"position":3,"text_uthmani":"نَّفْسَكَ","transliteration":"nafsaka","translation_bn":"তোমার প্রাণ (এ চিন্তায়)","root":"نفس","lemma":"نَفْس","grammar_bn":"বিশেষ্য (Noun)"},{"id":2810,"position":4,"text_uthmani":"أَلَّا","transliteration":"allā","translation_bn":"যে না","root":"—","lemma":"أَن\r","grammar_bn":"অধীনস্থ যোজক (Subordinating)"},{"id":2811,"position":5,"text_uthmani":"يَكُونُوا۟","transliteration":"yakūnū","translation_bn":"তারা হচ্ছে","root":"كون","lemma":"كَانَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":2812,"position":6,"text_uthmani":"مُؤْمِنِينَ","transliteration":"mu''minīna","translation_bn":"মু''মিন","root":"امن","lemma":"مُؤْمِن","grammar_bn":"বিশেষ্য (Noun)"},{"id":2813,"position":7,"text_uthmani":"٣","transliteration":"","translation_bn":"(৩)","root":"—","lemma":"٣","grammar_bn":"মার্কার"}]'::jsonb, 'laʿallaka bākhiʿun nafsaka allā yakūnū mu''minīna', 'তুমি হয়ত এ দুঃখে তোমার প্রাণনাশ করবে যে, তারা মু’মিন হচ্ছে না।', 'Perhaps, [O Muhammad], you would kill yourself with grief that they will not be believers.', 'তুমি হয়ত এ দুঃখে তোমার প্রাণনাশ করবে যে, তারা মু’মিন হচ্ছে না।', 'Perhaps, [O Muhammad], you would kill yourself with grief that they will not be believers.', NULL, NULL, NULL, NULL, NULL, 'https://everyayah.com/data/Alafasy_128kbps/026003.mp3', now()),
  (26, 4, '', '[{"id":3727,"position":1,"text_uthmani":"إِن","transliteration":"in","translation_bn":"যদি","root":"—","lemma":"إِن\r","grammar_bn":"শর্তবাচক (Conditional)"},{"id":3728,"position":2,"text_uthmani":"نَّشَأْ","transliteration":"nasha","translation_bn":"আমরা চাইতাম","root":"شيا","lemma":"شَا^ءَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":3729,"position":3,"text_uthmani":"نُنَزِّلْ","transliteration":"nunazzil","translation_bn":"অবতীর্ণ করতাম আমরা","root":"نزل","lemma":"نَزَّلَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":3730,"position":4,"text_uthmani":"عَلَيْهِم","transliteration":"ʿalayhim","translation_bn":"উপর তাদের","root":"—","lemma":"عَلَىٰ\r","grammar_bn":"অব্যয় (Preposition)"},{"id":3731,"position":5,"text_uthmani":"مِّنَ","transliteration":"mina","translation_bn":"হ''তে","root":"—","lemma":"مِن\r","grammar_bn":"অব্যয় (Preposition)"},{"id":3732,"position":6,"text_uthmani":"ٱلسَّمَآءِ","transliteration":"l-samāi","translation_bn":"আকাশ","root":"سمو","lemma":"سَمَا^ء","grammar_bn":"শব্দ"},{"id":3733,"position":7,"text_uthmani":"ءَايَةًۭ","transliteration":"āyatan","translation_bn":"(এমন) কোনো নিদর্শন","root":"ايي","lemma":"ءَايَة","grammar_bn":"বিশেষ্য (Noun)"},{"id":3734,"position":8,"text_uthmani":"فَظَلَّتْ","transliteration":"faẓallat","translation_bn":"ফলে হয়ে পড়তো","root":"ظلل","lemma":"ظَلَّ","grammar_bn":"শব্দ"},{"id":3735,"position":9,"text_uthmani":"أَعْنَـٰقُهُمْ","transliteration":"aʿnāquhum","translation_bn":"ঘাড়গুলো তাদের","root":"عنق","lemma":"عُنُق","grammar_bn":"বিশেষ্য (Noun)"},{"id":3736,"position":10,"text_uthmani":"لَهَا","transliteration":"lahā","translation_bn":"প্রতি তাঁর","root":"—","lemma":"لَهَا","grammar_bn":"অব্যয় (Preposition)"},{"id":3737,"position":11,"text_uthmani":"خَـٰضِعِينَ","transliteration":"khāḍiʿīna","translation_bn":"অবনত","root":"خضع","lemma":"خَٰضِعِين","grammar_bn":"বিশেষ্য (Noun)"},{"id":3738,"position":12,"text_uthmani":"٤","transliteration":"","translation_bn":"(৪)","root":"—","lemma":"٤","grammar_bn":"মার্কার"}]'::jsonb, 'in nasha nunazzil ʿalayhim mina l-samāi āyatan faẓallat aʿnāquhum lahā khāḍiʿīna', 'আমি ইচ্ছে করলে তাদের কাছে আসমান থেকে এমন নিদর্শন পাঠাতাম যে তার সামনে তাদের মাথা নত হয়ে যেত (অর্থাৎ তারা ঈমান আনতে বাধ্য হত)।', 'If We willed, We could send down to them from the sky a sign for which their necks would remain humbled.', 'আমি ইচ্ছে করলে তাদের কাছে আসমান থেকে এমন নিদর্শন পাঠাতাম যে তার সামনে তাদের মাথা নত হয়ে যেত (অর্থাৎ তারা ঈমান আনতে বাধ্য হত)।', 'If We willed, We could send down to them from the sky a sign for which their necks would remain humbled.', NULL, NULL, NULL, NULL, NULL, 'https://everyayah.com/data/Alafasy_128kbps/026004.mp3', now()),
  (26, 5, '', '[{"id":4698,"position":1,"text_uthmani":"وَمَا","transliteration":"wamā","translation_bn":"এবং না","root":"—","lemma":"مَا\r","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":4699,"position":2,"text_uthmani":"يَأْتِيهِم","transliteration":"yatīhim","translation_bn":"আসে তাদের (কাছে)","root":"اتي","lemma":"أَتَى","grammar_bn":"ক্রিয়া (Verb)"},{"id":4700,"position":3,"text_uthmani":"مِّن","transliteration":"min","translation_bn":"কোনো","root":"—","lemma":"مِن\r","grammar_bn":"অব্যয় (Preposition)"},{"id":4701,"position":4,"text_uthmani":"ذِكْرٍۢ","transliteration":"dhik''rin","translation_bn":"উপদেশ","root":"ذكر","lemma":"ذِكْر","grammar_bn":"বিশেষ্য (Noun)"},{"id":4702,"position":5,"text_uthmani":"مِّنَ","transliteration":"mina","translation_bn":"হ''তে","root":"—","lemma":"مِن\r","grammar_bn":"অব্যয় (Preposition)"},{"id":4703,"position":6,"text_uthmani":"ٱلرَّحْمَـٰنِ","transliteration":"l-raḥmāni","translation_bn":"দয়াময়","root":"رحم","lemma":"رَّحْمَٰن","grammar_bn":"শব্দ"},{"id":4704,"position":7,"text_uthmani":"مُحْدَثٍ","transliteration":"muḥ''dathin","translation_bn":"(উপদেশ) নতুন","root":"حدث","lemma":"مُحْدَث","grammar_bn":"বিশেষ্য (Noun)"},{"id":4705,"position":8,"text_uthmani":"إِلَّا","transliteration":"illā","translation_bn":"এ ছাড়া যে","root":"—","lemma":"إِلَّا\r","grammar_bn":"সীমাবদ্ধতা (Restriction)"},{"id":4706,"position":9,"text_uthmani":"كَانُوا۟","transliteration":"kānū","translation_bn":"তারা ছিলো","root":"كون","lemma":"كَانَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":4707,"position":10,"text_uthmani":"عَنْهُ","transliteration":"ʿanhu","translation_bn":"তা হতে","root":"—","lemma":"عَن\r","grammar_bn":"অব্যয় (Preposition)"},{"id":4708,"position":11,"text_uthmani":"مُعْرِضِينَ","transliteration":"muʿ''riḍīna","translation_bn":"মুখ ফিরিয়ে নিতো","root":"عرض","lemma":"مُّعْرِضُون","grammar_bn":"বিশেষ্য (Noun)"},{"id":4709,"position":12,"text_uthmani":"٥","transliteration":"","translation_bn":"(৫)","root":"—","lemma":"٥","grammar_bn":"মার্কার"}]'::jsonb, 'wamā yatīhim min dhik''rin mina l-raḥmāni muḥ''dathin illā kānū ʿanhu muʿ''riḍīna', 'তাদের কাছে যখনই দয়াময় আল্লাহর পক্ষ হতে নতুন কোন নসীহত আসে তখনই তারা তাত্থেকে মুখ ফিরিয়ে নেয়।', 'And no revelation comes to them anew from the Most Merciful except that they turn away from it.', 'তাদের কাছে যখনই দয়াময় আল্লাহর পক্ষ হতে নতুন কোন নসীহত আসে তখনই তারা তাত্থেকে মুখ ফিরিয়ে নেয়।', 'And no revelation comes to them anew from the Most Merciful except that they turn away from it.', NULL, NULL, NULL, NULL, NULL, 'https://everyayah.com/data/Alafasy_128kbps/026005.mp3', now()),
  (26, 6, '', '[{"id":5968,"position":1,"text_uthmani":"فَقَدْ","transliteration":"faqad","translation_bn":"এখন নিশ্চয়ই","root":"—","lemma":"قَد\r","grammar_bn":"শব্দ"},{"id":5969,"position":2,"text_uthmani":"كَذَّبُوا۟","transliteration":"kadhabū","translation_bn":"তারা মিথ্যারোপ করেছে","root":"كذب","lemma":"كَذَّبَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":5970,"position":3,"text_uthmani":"فَسَيَأْتِيهِمْ","transliteration":"fasayatīhim","translation_bn":"সুতরাং শীঘ্রই আসবে তাদের (কাছে)","root":"اتي","lemma":"أَتَى","grammar_bn":"শব্দ"},{"id":5971,"position":4,"text_uthmani":"أَنۢبَـٰٓؤُا۟","transliteration":"anbāu","translation_bn":"সংবাদ","root":"نبا","lemma":"نَبَأ","grammar_bn":"বিশেষ্য (Noun)"},{"id":5972,"position":5,"text_uthmani":"مَا","transliteration":"mā","translation_bn":"যা কিছু","root":"—","lemma":"مَا\r","grammar_bn":"সাপেক্ষ সর্বনাম (Relative)"},{"id":5973,"position":6,"text_uthmani":"كَانُوا۟","transliteration":"kānū","translation_bn":"তারা ছিলো","root":"كون","lemma":"كَانَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":5974,"position":7,"text_uthmani":"بِهِۦ","transliteration":"bihi","translation_bn":"সম্পর্কে সে","root":"—","lemma":"بِهِۦ","grammar_bn":"অব্যয় (Preposition)"},{"id":5975,"position":8,"text_uthmani":"يَسْتَهْزِءُونَ","transliteration":"yastahziūna","translation_bn":"ঠাট্টা-বিদ্রুপ করতো","root":"هزا","lemma":"ٱسْتُهْزِئَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":5976,"position":9,"text_uthmani":"٦","transliteration":"","translation_bn":"(৬)","root":"—","lemma":"٦","grammar_bn":"মার্কার"}]'::jsonb, 'faqad kadhabū fasayatīhim anbāu mā kānū bihi yastahziūna', 'তারা (আল্লাহর বাণীকে) অস্বীকারই করেছে, শীঘ্রই তাদের কাছে তার সত্য উদঘাটিত হবে যা নিয়ে তারা ঠাট্টা-বিদ্রূপ করত।', 'For they have already denied, but there will come to them the news of that which they used to ridicule.', 'তারা (আল্লাহর বাণীকে) অস্বীকারই করেছে, শীঘ্রই তাদের কাছে তার সত্য উদঘাটিত হবে যা নিয়ে তারা ঠাট্টা-বিদ্রূপ করত।', 'For they have already denied, but there will come to them the news of that which they used to ridicule.', NULL, NULL, NULL, NULL, NULL, 'https://everyayah.com/data/Alafasy_128kbps/026006.mp3', now()),
  (26, 7, '', '[{"id":7192,"position":1,"text_uthmani":"أَوَلَمْ","transliteration":"awalam","translation_bn":"কি নি","root":"—","lemma":"لَم\r","grammar_bn":"প্রশ্নবোধক (Interrogative)"},{"id":7193,"position":2,"text_uthmani":"يَرَوْا۟","transliteration":"yaraw","translation_bn":"তারা লক্ষ্য করে","root":"راي","lemma":"رَءَا","grammar_bn":"ক্রিয়া (Verb)"},{"id":7194,"position":3,"text_uthmani":"إِلَى","transliteration":"ilā","translation_bn":"প্রতি","root":"—","lemma":"إِلَىٰ\r","grammar_bn":"অব্যয় (Preposition)"},{"id":7195,"position":4,"text_uthmani":"ٱلْأَرْضِ","transliteration":"l-arḍi","translation_bn":"পৃথিবীর","root":"ارض","lemma":"أَرْض","grammar_bn":"শব্দ"},{"id":7196,"position":5,"text_uthmani":"كَمْ","transliteration":"kam","translation_bn":"কত (বিপুল পরিমাণ)","root":"—","lemma":"كَم\r","grammar_bn":"প্রশ্নবোধক (Interrogative)"},{"id":7197,"position":6,"text_uthmani":"أَنۢبَتْنَا","transliteration":"anbatnā","translation_bn":"উদ্গত করেছি আমরা","root":"نبت","lemma":"أَن[بَتَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":7198,"position":7,"text_uthmani":"فِيهَا","transliteration":"fīhā","translation_bn":"মধ্যে তার","root":"—","lemma":"فِى\r","grammar_bn":"অব্যয় (Preposition)"},{"id":7199,"position":8,"text_uthmani":"مِن","transliteration":"min","translation_bn":"থেকে","root":"—","lemma":"مِن\r","grammar_bn":"অব্যয় (Preposition)"},{"id":7200,"position":9,"text_uthmani":"كُلِّ","transliteration":"kulli","translation_bn":"প্রত্যেক","root":"كلل","lemma":"كُلّ","grammar_bn":"বিশেষ্য (Noun)"},{"id":7201,"position":10,"text_uthmani":"زَوْجٍۢ","transliteration":"zawjin","translation_bn":"প্রকার (উদ্ভিদ)","root":"زوج","lemma":"زَوْج","grammar_bn":"বিশেষ্য (Noun)"},{"id":7202,"position":11,"text_uthmani":"كَرِيمٍ","transliteration":"karīmin","translation_bn":"চমৎকার","root":"كرم","lemma":"كَرِيم","grammar_bn":"বিশেষণ (Adjective)"},{"id":7203,"position":12,"text_uthmani":"٧","transliteration":"","translation_bn":"(৭)","root":"—","lemma":"٧","grammar_bn":"মার্কার"}]'::jsonb, 'awalam yaraw ilā l-arḍi kam anbatnā fīhā min kulli zawjin karīmin', 'তারা কি যমীনের দিকে চেয়ে দেখে না, আমি তাতে সব ধরনের উৎকৃষ্ট উদ্ভিদ পয়দা করেছি।', 'Did they not look at the earth - how much We have produced therein from every noble kind?', 'তারা কি যমীনের দিকে চেয়ে দেখে না, আমি তাতে সব ধরনের উৎকৃষ্ট উদ্ভিদ পয়দা করেছি।', 'Did they not look at the earth - how much We have produced therein from every noble kind?', NULL, NULL, NULL, NULL, NULL, 'https://everyayah.com/data/Alafasy_128kbps/026007.mp3', now()),
  (26, 8, '', '[{"id":9266,"position":1,"text_uthmani":"إِنَّ","transliteration":"inna","translation_bn":"নিশ্চয়ই","root":"—","lemma":"إِنّ","grammar_bn":"অভিঘাত পদ (Accusative)"},{"id":9267,"position":2,"text_uthmani":"فِى","transliteration":"fī","translation_bn":"মধ্যে (রয়েছে)","root":"—","lemma":"فِى\r","grammar_bn":"অব্যয় (Preposition)"},{"id":9268,"position":3,"text_uthmani":"ذَٰلِكَ","transliteration":"dhālika","translation_bn":"এর","root":"—","lemma":"ذَٰلِك","grammar_bn":"নির্দেশক সর্বনাম (Demonstrative)"},{"id":9269,"position":4,"text_uthmani":"لَـَٔايَةًۭ ۖ","transliteration":"laāyatan","translation_bn":"অবশ্যই নিদর্শন","root":"ايي","lemma":"ءَايَة","grammar_bn":"দৃঢ়তাবোধক (Emphatic)"},{"id":9271,"position":5,"text_uthmani":"وَمَا","transliteration":"wamā","translation_bn":"কিন্তু না","root":"—","lemma":"مَا\r","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":9272,"position":6,"text_uthmani":"كَانَ","transliteration":"kāna","translation_bn":"ছিলো","root":"كون","lemma":"كَانَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":9273,"position":7,"text_uthmani":"أَكْثَرُهُم","transliteration":"aktharuhum","translation_bn":"অধিকাংশ তাদের","root":"كثر","lemma":"أَكْثَر","grammar_bn":"বিশেষ্য (Noun)"},{"id":9274,"position":8,"text_uthmani":"مُّؤْمِنِينَ","transliteration":"mu''minīna","translation_bn":"মু''মিন","root":"امن","lemma":"مُؤْمِن","grammar_bn":"বিশেষ্য (Noun)"},{"id":9275,"position":9,"text_uthmani":"٨","transliteration":"","translation_bn":"(৮)","root":"—","lemma":"٨","grammar_bn":"মার্কার"}]'::jsonb, 'inna fī dhālika laāyatan wamā kāna aktharuhum mu''minīna', 'অবশ্যই এতে নিদর্শন আছে (আল্লাহ সম্পর্কে চিন্তা ক’রে ঈমান আনার জন্য), কিন্তু তাদের অধিকাংশই ঈমান আনে না।', 'Indeed in that is a sign, but most of them were not to be believers.', 'অবশ্যই এতে নিদর্শন আছে (আল্লাহ সম্পর্কে চিন্তা ক’রে ঈমান আনার জন্য), কিন্তু তাদের অধিকাংশই ঈমান আনে না।', 'Indeed in that is a sign, but most of them were not to be believers.', NULL, NULL, NULL, NULL, NULL, 'https://everyayah.com/data/Alafasy_128kbps/026008.mp3', now()),
  (26, 9, '', '[{"id":10462,"position":1,"text_uthmani":"وَإِنَّ","transliteration":"wa-inna","translation_bn":"এবং নিশ্চয়ই","root":"—","lemma":"إِنّ","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":10463,"position":2,"text_uthmani":"رَبَّكَ","transliteration":"rabbaka","translation_bn":"তোমার রব","root":"ربب","lemma":"رَبّ","grammar_bn":"বিশেষ্য (Noun)"},{"id":10464,"position":3,"text_uthmani":"لَهُوَ","transliteration":"lahuwa","translation_bn":"অবশ্যই তিনি","root":"—","lemma":"لَهُوَ","grammar_bn":"দৃঢ়তাবোধক (Emphatic)"},{"id":10465,"position":4,"text_uthmani":"ٱلْعَزِيزُ","transliteration":"l-ʿazīzu","translation_bn":"পরাক্রমশালী","root":"عزز","lemma":"عَزِيز","grammar_bn":"শব্দ"},{"id":10466,"position":5,"text_uthmani":"ٱلرَّحِيمُ","transliteration":"l-raḥīmu","translation_bn":"পরম দয়ালুও","root":"رحم","lemma":"رَّحِيم","grammar_bn":"শব্দ"},{"id":10467,"position":6,"text_uthmani":"٩","transliteration":"","translation_bn":"(৯)","root":"—","lemma":"٩","grammar_bn":"মার্কার"}]'::jsonb, 'wa-inna rabbaka lahuwa l-ʿazīzu l-raḥīmu', 'নিশ্চয় তোমার প্রতিপালক মহা পরাক্রমশালী, অতি দয়ালু।', 'And indeed, your Lord - He is the Exalted in Might, the Merciful.', 'নিশ্চয় তোমার প্রতিপালক মহা পরাক্রমশালী, অতি দয়ালু।', 'And indeed, your Lord - He is the Exalted in Might, the Merciful.', NULL, NULL, NULL, NULL, NULL, 'https://everyayah.com/data/Alafasy_128kbps/026009.mp3', now()),
  (26, 10, '', '[{"id":11675,"position":1,"text_uthmani":"وَإِذْ","transliteration":"wa-idh","translation_bn":"এবং (স্মরণ করো) যখন","root":"—","lemma":"إِذ\r","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":11676,"position":2,"text_uthmani":"نَادَىٰ","transliteration":"nādā","translation_bn":"ডেকেছিলেন","root":"ندو","lemma":"نَادَىٰ","grammar_bn":"ক্রিয়া (Verb)"},{"id":11677,"position":3,"text_uthmani":"رَبُّكَ","transliteration":"rabbuka","translation_bn":"তোমার রব","root":"ربب","lemma":"رَبّ","grammar_bn":"বিশেষ্য (Noun)"},{"id":11678,"position":4,"text_uthmani":"مُوسَىٰٓ","transliteration":"mūsā","translation_bn":"মূসাকে","root":"—","lemma":"مُوسَىٰ","grammar_bn":"নামবাচক বিশেষ্য (Proper Noun)"},{"id":11679,"position":5,"text_uthmani":"أَنِ","transliteration":"ani","translation_bn":"যে","root":"—","lemma":"أَن\r","grammar_bn":"উদ্দেশ্যবাচক (Intention)"},{"id":11680,"position":6,"text_uthmani":"ٱئْتِ","transliteration":"i''ti","translation_bn":"\"যাও তুমি","root":"اتي","lemma":"أَتَى","grammar_bn":"ক্রিয়া (Verb)"},{"id":11681,"position":7,"text_uthmani":"ٱلْقَوْمَ","transliteration":"l-qawma","translation_bn":"জাতির (নিকট)","root":"قوم","lemma":"قَوْم","grammar_bn":"শব্দ"},{"id":11682,"position":8,"text_uthmani":"ٱلظَّـٰلِمِينَ","transliteration":"l-ẓālimīna","translation_bn":"সীমালঙ্ঘনকারী","root":"ظلم","lemma":"ظَالِم","grammar_bn":"শব্দ"},{"id":11683,"position":9,"text_uthmani":"١٠","transliteration":"","translation_bn":"(১০)","root":"—","lemma":"١٠","grammar_bn":"মার্কার"}]'::jsonb, 'wa-idh nādā rabbuka mūsā ani i''ti l-qawma l-ẓālimīna', 'স্মরণ কর, যখন তোমার প্রতিপালক মূসাকে ডাক দিয়ে বললেন, ‘তুমি যালিম সম্প্রদায়ের কাছে যাও,', 'And [mention] when your Lord called Moses, [saying], "Go to the wrongdoing people -', 'স্মরণ কর, যখন তোমার প্রতিপালক মূসাকে ডাক দিয়ে বললেন, ‘তুমি যালিম সম্প্রদায়ের কাছে যাও,', 'And [mention] when your Lord called Moses, [saying], "Go to the wrongdoing people -', NULL, NULL, NULL, NULL, NULL, 'https://everyayah.com/data/Alafasy_128kb