  (26, 35, '', '[{"id":37402,"position":1,"text_uthmani":"يُرِيدُ","transliteration":"yurīdu","translation_bn":"সে চায়","root":"رود","lemma":"أَرَادَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":37403,"position":2,"text_uthmani":"أَن","transliteration":"an","translation_bn":"যে","root":"—","lemma":"أَن\r","grammar_bn":"অধীনস্থ যোজক (Subordinating)"},{"id":37404,"position":3,"text_uthmani":"يُخْرِجَكُم","transliteration":"yukh''rijakum","translation_bn":"সে বের করবে তোমাদেরকে","root":"خرج","lemma":"أَخْرَجَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":37405,"position":4,"text_uthmani":"مِّنْ","transliteration":"min","translation_bn":"হ''তে","root":"—","lemma":"مِن\r","grammar_bn":"অব্যয় (Preposition)"},{"id":37406,"position":5,"text_uthmani":"أَرْضِكُم","transliteration":"arḍikum","translation_bn":"দেশ তোমাদের","root":"ارض","lemma":"أَرْض","grammar_bn":"বিশেষ্য (Noun)"},{"id":37407,"position":6,"text_uthmani":"بِسِحْرِهِۦ","transliteration":"bisiḥ''rihi","translation_bn":"সাহায্যে তাঁর জাদুর","root":"سحر","lemma":"سِحْر","grammar_bn":"অব্যয় (Preposition)"},{"id":37408,"position":7,"text_uthmani":"فَمَاذَا","transliteration":"famādhā","translation_bn":"অতঃপর কি","root":"—","lemma":"مَاذَا\r","grammar_bn":"শব্দ"},{"id":37409,"position":8,"text_uthmani":"تَأْمُرُونَ","transliteration":"tamurūna","translation_bn":"তোমরা পরামর্শ দিচ্ছো\"","root":"امر","lemma":"أَمَرَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":37410,"position":9,"text_uthmani":"٣٥","transliteration":"","translation_bn":"(৩৫)","root":"—","lemma":"٣٥","grammar_bn":"মার্কার"}]'::jsonb, 'yurīdu an yukh''rijakum min arḍikum bisiḥ''rihi famādhā tamurūna', 'যাদুর বলে সে তোমাদেরকে তোমাদের দেশ থেকে বের করে দিতে চায়। এখন বল তোমাদের নির্দেশ কী?’', 'He wants to drive you out of your land by his magic, so what do you advise?"', 'যাদুর বলে সে তোমাদেরকে তোমাদের দেশ থেকে বের করে দিতে চায়। এখন বল তোমাদের নির্দেশ কী?’', 'He wants to drive you out of your land by his magic, so what do you advise?"', NULL, NULL, NULL, NULL, NULL, 'https://everyayah.com/data/Alafasy_128kbps/026035.mp3', now()),
  (26, 36, '', '[{"id":38275,"position":1,"text_uthmani":"قَالُوٓا۟","transliteration":"qālū","translation_bn":"তারা বললো","root":"قول","lemma":"قَالَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":38276,"position":2,"text_uthmani":"أَرْجِهْ","transliteration":"arjih","translation_bn":"\"তাঁর (ব্যাপার) স্থগিত রাখুন","root":"رجو","lemma":"تُرْجِى","grammar_bn":"ক্রিয়া (Verb)"},{"id":38277,"position":3,"text_uthmani":"وَأَخَاهُ","transliteration":"wa-akhāhu","translation_bn":"ও তাঁর ভায়ের (ব্যাপারে)","root":"اخو","lemma":"أَخ","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":38278,"position":4,"text_uthmani":"وَٱبْعَثْ","transliteration":"wa-ib''ʿath","translation_bn":"এবং পাঠিয়ে দিন","root":"بعث","lemma":"بَعَثَ","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":38279,"position":5,"text_uthmani":"فِى","transliteration":"fī","translation_bn":"মধ্যে","root":"—","lemma":"فِى\r","grammar_bn":"অব্যয় (Preposition)"},{"id":38280,"position":6,"text_uthmani":"ٱلْمَدَآئِنِ","transliteration":"l-madāini","translation_bn":"শহরে শহরে","root":"مدن","lemma":"مَدَا^ئِن","grammar_bn":"শব্দ"},{"id":38281,"position":7,"text_uthmani":"حَـٰشِرِينَ","transliteration":"ḥāshirīna","translation_bn":"সংগ্রহকারীদেরকে","root":"حشر","lemma":"حَٰشِرِين","grammar_bn":"বিশেষ্য (Noun)"},{"id":38282,"position":8,"text_uthmani":"٣٦","transliteration":"","translation_bn":"(৩৬)","root":"—","lemma":"٣٦","grammar_bn":"মার্কার"}]'::jsonb, 'qālū arjih wa-akhāhu wa-ib''ʿath fī l-madāini ḥāshirīna', 'তারা বলল : ‘তাকে ও তার ভাইকে (কিছু সময়) অপেক্ষায় ফেলে রাখুন আর জড়ো করার জন্য ঘোষকদেরকে নগরে নগরে পাঠিয়ে দিন।', 'They said, "Postpone [the matter of] him and his brother and send among the cities gatherers', 'তারা বলল : ‘তাকে ও তার ভাইকে (কিছু সময়) অপেক্ষায় ফেলে রাখুন আর জড়ো করার জন্য ঘোষকদেরকে নগরে নগরে পাঠিয়ে দিন।', 'They said, "Postpone [the matter of] him and his brother and send among the cities gatherers', NULL, NULL, NULL, NULL, NULL, 'https://everyayah.com/data/Alafasy_128kbps/026036.mp3', now()),
  (26, 37, '', '[{"id":39122,"position":1,"text_uthmani":"يَأْتُوكَ","transliteration":"yatūka","translation_bn":"আপনার নিকট আসবে তারা","root":"اتي","lemma":"أَتَى","grammar_bn":"ক্রিয়া (Verb)"},{"id":39123,"position":2,"text_uthmani":"بِكُلِّ","transliteration":"bikulli","translation_bn":"নিয়ে প্রত্যেক","root":"كلل","lemma":"كُلّ","grammar_bn":"অব্যয় (Preposition)"},{"id":39124,"position":3,"text_uthmani":"سَحَّارٍ","transliteration":"saḥḥārin","translation_bn":"বড় জাদুকরকে","root":"سحر","lemma":"سَحَّار","grammar_bn":"বিশেষ্য (Noun)"},{"id":39125,"position":4,"text_uthmani":"عَلِيمٍۢ","transliteration":"ʿalīmin","translation_bn":"সূদক্ষ\"","root":"علم","lemma":"عَلِيم","grammar_bn":"বিশেষণ (Adjective)"},{"id":39126,"position":5,"text_uthmani":"٣٧","transliteration":"","translation_bn":"(৩৭)","root":"—","lemma":"٣٧","grammar_bn":"মার্কার"}]'::jsonb, 'yatūka bikulli saḥḥārin ʿalīmin', 'তারা আপনার কাছে প্রত্যেকটি অভিজ্ঞ যাদুকরকে নিয়ে আসবে।’', 'Who will bring you every learned, skilled magician."', 'তারা আপনার কাছে প্রত্যেকটি অভিজ্ঞ যাদুকরকে নিয়ে আসবে।’', 'Who will bring you every learned, skilled magician."', NULL, NULL, NULL, NULL, NULL, 'https://everyayah.com/data/Alafasy_128kbps/026037.mp3', now()),
  (26, 38, '', '[{"id":39914,"position":1,"text_uthmani":"فَجُمِعَ","transliteration":"fajumiʿa","translation_bn":"অতঃপর জড়ো করা হলো","root":"جمع","lemma":"جَمَعَ","grammar_bn":"শব্দ"},{"id":39915,"position":2,"text_uthmani":"ٱلسَّحَرَةُ","transliteration":"l-saḥaratu","translation_bn":"জাদুকরদেরকে","root":"سحر","lemma":"سَٰحِر","grammar_bn":"শব্দ"},{"id":39916,"position":3,"text_uthmani":"لِمِيقَـٰتِ","transliteration":"limīqāti","translation_bn":"জন্যে নির্দিষ্ট সময়ের","root":"وقت","lemma":"مِيقَٰت","grammar_bn":"অব্যয় (Preposition)"},{"id":39917,"position":4,"text_uthmani":"يَوْمٍۢ","transliteration":"yawmin","translation_bn":"দিনের","root":"يوم","lemma":"يَوْم","grammar_bn":"বিশেষ্য (Noun)"},{"id":39918,"position":5,"text_uthmani":"مَّعْلُومٍۢ","transliteration":"maʿlūmin","translation_bn":"নির্ধারিত","root":"علم","lemma":"مَّعْلُوم","grammar_bn":"বিশেষ্য (Noun)"},{"id":39919,"position":6,"text_uthmani":"٣٨","transliteration":"","translation_bn":"(৩৮)","root":"—","lemma":"٣٨","grammar_bn":"মার্কার"}]'::jsonb, 'fajumiʿa l-saḥaratu limīqāti yawmin maʿlūmin', 'কাজেই যাদুকরদেরকে একত্রিত করা হল একটি নির্দিষ্ট দিন ক্ষণের জন্য যা ছিল সুবিদিত।', 'So the magicians were assembled for the appointment of a well-known day.', 'কাজেই যাদুকরদেরকে একত্রিত করা হল একটি নির্দিষ্ট দিন ক্ষণের জন্য যা ছিল সুবিদিত।', 'So the magicians were assembled for the appointment of a well-known day.', NULL, NULL, NULL, NULL, NULL, 'https://everyayah.com/data/Alafasy_128kbps/026038.mp3', now()),
  (26, 39, '', '[{"id":40732,"position":1,"text_uthmani":"وَقِيلَ","transliteration":"waqīla","translation_bn":"এবং বলা হলো","root":"قول","lemma":"قَالَ","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":40733,"position":2,"text_uthmani":"لِلنَّاسِ","transliteration":"lilnnāsi","translation_bn":"লোকদেরকে","root":"نوس","lemma":"نَّاس","grammar_bn":"অব্যয় (Preposition)"},{"id":40734,"position":3,"text_uthmani":"هَلْ","transliteration":"hal","translation_bn":"\"(তাহ''লে) কি","root":"—","lemma":"هَل\r","grammar_bn":"প্রশ্নবোধক (Interrogative)"},{"id":40735,"position":4,"text_uthmani":"أَنتُم","transliteration":"antum","translation_bn":"তোমরা","root":"—","lemma":"أَنتُم","grammar_bn":"সর্বনাম (Pronoun)"},{"id":40736,"position":5,"text_uthmani":"مُّجْتَمِعُونَ","transliteration":"muj''tamiʿūna","translation_bn":"(সম্মেলনে) সমবেত হচ্ছো","root":"جمع","lemma":"مُّجْتَمِعُون","grammar_bn":"বিশেষ্য (Noun)"},{"id":40737,"position":6,"text_uthmani":"٣٩","transliteration":"","translation_bn":"(৩৯)","root":"—","lemma":"٣٩","grammar_bn":"মার্কার"}]'::jsonb, 'waqīla lilnnāsi hal antum muj''tamiʿūna', 'আর জনগণকে বলা হল- ‘তোমরা কি সম্মিলিত হবে?', 'And it was said to the people, "Will you congregate', 'আর জনগণকে বলা হল- ‘তোমরা কি সম্মিলিত হবে?', 'And it was said to the people, "Will you congregate', NULL, NULL, NULL, NULL, NULL, 'https://everyayah.com/data/Alafasy_128kbps/026039.mp3', now()),
  (26, 40, '', '[{"id":41559,"position":1,"text_uthmani":"لَعَلَّنَا","transliteration":"laʿallanā","translation_bn":"সম্ভবতঃ আমরা","root":"—","lemma":"لَعَلّ","grammar_bn":"অভিঘাত পদ (Accusative)"},{"id":41560,"position":2,"text_uthmani":"نَتَّبِعُ","transliteration":"nattabiʿu","translation_bn":"অনুসরণ করবো","root":"تبع","lemma":"ٱتَّبَعَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":41561,"position":3,"text_uthmani":"ٱلسَّحَرَةَ","transliteration":"l-saḥarata","translation_bn":"জাদুকরদের (দ্বীনকে)","root":"سحر","lemma":"سَٰحِر","grammar_bn":"শব্দ"},{"id":41562,"position":4,"text_uthmani":"إِن","transliteration":"in","translation_bn":"যদি","root":"—","lemma":"إِن\r","grammar_bn":"শর্তবাচক (Conditional)"},{"id":41563,"position":5,"text_uthmani":"كَانُوا۟","transliteration":"kānū","translation_bn":"তারা হয়","root":"كون","lemma":"كَانَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":41564,"position":6,"text_uthmani":"هُمُ","transliteration":"humu","translation_bn":"তারা","root":"—","lemma":"هُمُ","grammar_bn":"সর্বনাম (Pronoun)"},{"id":41565,"position":7,"text_uthmani":"ٱلْغَـٰلِبِينَ","transliteration":"l-ghālibīna","translation_bn":"বিজয়ী\"","root":"غلب","lemma":"غَالِب","grammar_bn":"শব্দ"},{"id":41566,"position":8,"text_uthmani":"٤٠","transliteration":"","translation_bn":"(৪০)","root":"—","lemma":"٤٠","grammar_bn":"মার্কার"}]'::jsonb, 'laʿallanā nattabiʿu l-saḥarata in kānū humu l-ghālibīna', 'যাতে আমরা যাদুকরদের (এবং তাদের প্রধান পৃষ্ঠপোষক ফেরাউনের) দীন অনুসরণ করতে পারি যদি তারা বিজয়ী হয়।', 'That we might follow the magicians if they are the predominant?"', 'যাতে আমরা যাদুকরদের (এবং তাদের প্রধান পৃষ্ঠপোষক ফেরাউনের) দীন অনুসরণ করতে পারি যদি তারা বিজয়ী হয়।', 'That we might follow the magicians if they are the predominant?"', NULL, NULL, NULL, NULL, NULL, 'https://everyayah.com/data/Alafasy_128kbps/026040.mp3', now()),
  (26, 41, '', '[{"id":42411,"position":1,"text_uthmani":"فَلَمَّا","transliteration":"falammā","translation_bn":"অতঃপর যখন","root":"—","lemma":"لَمَّا\r","grammar_bn":"শব্দ"},{"id":42412,"position":2,"text_uthmani":"جَآءَ","transliteration":"jāa","translation_bn":"আসলো (ময়দানে)","root":"جيا","lemma":"جَا^ءَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":42413,"position":3,"text_uthmani":"ٱلسَّحَرَةُ","transliteration":"l-saḥaratu","translation_bn":"জাদুকররা","root":"سحر","lemma":"سَٰحِر","grammar_bn":"শব্দ"},{"id":42414,"position":4,"text_uthmani":"قَالُوا۟","transliteration":"qālū","translation_bn":"তারা বললো","root":"قول","lemma":"قَالَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":42415,"position":5,"text_uthmani":"لِفِرْعَوْنَ","transliteration":"lifir''ʿawna","translation_bn":"উদ্দেশ্যে ফিরআউনের","root":"—","lemma":"فِرْعَوْن","grammar_bn":"অব্যয় (Preposition)"},{"id":42416,"position":6,"text_uthmani":"أَئِنَّ","transliteration":"a-inna","translation_bn":"\"কি নিশ্চয়ই (আছে)","root":"—","lemma":"إِنّ","grammar_bn":"প্রশ্নবোধক (Interrogative)"},{"id":42417,"position":7,"text_uthmani":"لَنَا","transliteration":"lanā","translation_bn":"জন্যে আমাদের","root":"—","lemma":"لَنَا","grammar_bn":"অব্যয় (Preposition)"},{"id":42418,"position":8,"text_uthmani":"لَأَجْرًا","transliteration":"la-ajran","translation_bn":"অবশ্যই পুরস্কার","root":"اجر","lemma":"أَجْر","grammar_bn":"দৃঢ়তাবোধক (Emphatic)"},{"id":42419,"position":9,"text_uthmani":"إِن","transliteration":"in","translation_bn":"যদি","root":"—","lemma":"إِن\r","grammar_bn":"শর্তবাচক (Conditional)"},{"id":42420,"position":10,"text_uthmani":"كُنَّا","transliteration":"kunnā","translation_bn":"আমরা হই","root":"كون","lemma":"كَانَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":42421,"position":11,"text_uthmani":"نَحْنُ","transliteration":"naḥnu","translation_bn":"আমরা","root":"—","lemma":"نَحْنُ","grammar_bn":"সর্বনাম (Pronoun)"},{"id":42422,"position":12,"text_uthmani":"ٱلْغَـٰلِبِينَ","transliteration":"l-ghālibīna","translation_bn":"বিজয়ী\"","root":"غلب","lemma":"غَالِب","grammar_bn":"শব্দ"},{"id":42423,"position":13,"text_uthmani":"٤١","transliteration":"","translation_bn":"(৪১)","root":"—","lemma":"٤١","grammar_bn":"মার্কার"}]'::jsonb, 'falammā jāa l-saḥaratu qālū lifir''ʿawna a-inna lanā la-ajran in kunnā naḥnu l-ghālibīna', 'যাদুকররা যখন আসলো, তারা ফেরাউনকে বলল : ‘আমরা জয়ী হলে আমাদেরকে পুরস্কার দেয়া হবে তো?’', 'And when the magicians arrived, they said to Pharaoh, "Is there indeed for us a reward if we are the predominant?"', 'যাদুকররা যখন আসলো, তারা ফেরাউনকে বলল : ‘আমরা জয়ী হলে আমাদেরকে পুরস্কার দেয়া হবে তো?’', 'And when the magicians arrived, they said to Pharaoh, "Is there indeed for us a reward if we are the predominant?"', NULL, NULL, NULL, NULL, NULL, 'https://everyayah.com/data/Alafasy_128kbps/026041.mp3', now()),
