  (26, 46, '', '[{"id":46025,"position":1,"text_uthmani":"فَأُلْقِىَ","transliteration":"fa-ul''qiya","translation_bn":"তখন পড়ে গেলো","root":"لقي","lemma":"أَلْقَىٰ^","grammar_bn":"শব্দ"},{"id":46026,"position":2,"text_uthmani":"ٱلسَّحَرَةُ","transliteration":"l-saḥaratu","translation_bn":"জাদুকররা","root":"سحر","lemma":"سَٰحِر","grammar_bn":"শব্দ"},{"id":46027,"position":3,"text_uthmani":"سَـٰجِدِينَ","transliteration":"sājidīna","translation_bn":"সিজদাকারী হিসেবে","root":"سجد","lemma":"سَاجِد","grammar_bn":"বিশেষ্য (Noun)"},{"id":46028,"position":4,"text_uthmani":"٤٦","transliteration":"","translation_bn":"(৪৬)","root":"—","lemma":"٤٦","grammar_bn":"মার্কার"}]'::jsonb, 'fa-ul''qiya l-saḥaratu sājidīna', 'তখন যাদুকররা সিজদায় লুটিয়ে পড়ল।', 'So the magicians fell down in prostration [to Allah].', 'তখন যাদুকররা সিজদায় লুটিয়ে পড়ল।', 'So the magicians fell down in prostration [to Allah].', NULL, NULL, NULL, NULL, NULL, 'https://everyayah.com/data/Alafasy_128kbps/026046.mp3', now()),
  (26, 47, '', '[{"id":46645,"position":1,"text_uthmani":"قَالُوٓا۟","transliteration":"qālū","translation_bn":"তারা বললো","root":"قول","lemma":"قَالَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":46646,"position":2,"text_uthmani":"ءَامَنَّا","transliteration":"āmannā","translation_bn":"\"আমরা ঈমান এনেছি","root":"امن","lemma":"ءَامَنَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":46647,"position":3,"text_uthmani":"بِرَبِّ","transliteration":"birabbi","translation_bn":"উপর রবের","root":"ربب","lemma":"رَبّ","grammar_bn":"অব্যয় (Preposition)"},{"id":46648,"position":4,"text_uthmani":"ٱلْعَـٰلَمِينَ","transliteration":"l-ʿālamīna","translation_bn":"বিশ্ব্বজগতের","root":"علم","lemma":"عَٰلَمِين","grammar_bn":"শব্দ"},{"id":46649,"position":5,"text_uthmani":"٤٧","transliteration":"","translation_bn":"(৪৭)","root":"—","lemma":"٤٧","grammar_bn":"মার্কার"}]'::jsonb, 'qālū āmannā birabbi l-ʿālamīna', 'তারা বলল- ‘আমরা বিশ্বাস স্থাপন করলাম রাব্বুল ‘আলামীনের প্রতি,', 'They said, "We have believed in the Lord of the worlds,', 'তারা বলল- ‘আমরা বিশ্বাস স্থাপন করলাম রাব্বুল ‘আলামীনের প্রতি,', 'They said, "We have believed in the Lord of the worlds,', NULL, NULL, NULL, NULL, NULL, 'https://everyayah.com/data/Alafasy_128kbps/026047.mp3', now()),
  (26, 48, '', '[{"id":47092,"position":1,"text_uthmani":"رَبِّ","transliteration":"rabbi","translation_bn":"(যিনি) রব","root":"ربب","lemma":"رَبّ","grammar_bn":"বিশেষ্য (Noun)"},{"id":47093,"position":2,"text_uthmani":"مُوسَىٰ","transliteration":"mūsā","translation_bn":"মূসার","root":"—","lemma":"مُوسَىٰ","grammar_bn":"নামবাচক বিশেষ্য (Proper Noun)"},{"id":47094,"position":3,"text_uthmani":"وَهَـٰرُونَ","transliteration":"wahārūna","translation_bn":"ও হারুনের\"","root":"—","lemma":"هَٰرُون","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":47095,"position":4,"text_uthmani":"٤٨","transliteration":"","translation_bn":"(৪৮)","root":"—","lemma":"٤٨","grammar_bn":"মার্কার"}]'::jsonb, 'rabbi mūsā wahārūna', 'যিনি মূসা ও হারুনের প্রতিপালক।’', 'The Lord of Moses and Aaron."', 'যিনি মূসা ও হারুনের প্রতিপালক।’', 'The Lord of Moses and Aaron."', NULL, NULL, NULL, NULL, NULL, 'https://everyayah.com/data/Alafasy_128kbps/026048.mp3', now()),
  (26, 49, '', '[{"id":48095,"position":1,"text_uthmani":"قَالَ","transliteration":"qāla","translation_bn":"(ফিরআউন) বললো","root":"قول","lemma":"قَالَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":48096,"position":2,"text_uthmani":"ءَامَنتُمْ","transliteration":"āmantum","translation_bn":"\"কি তোমরা ঈমান আনলে","root":"امن","lemma":"ءَامَنَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":48097,"position":3,"text_uthmani":"لَهُۥ","transliteration":"lahu","translation_bn":"প্রতি তাঁর","root":"—","lemma":"لَهُۥ","grammar_bn":"অব্যয় (Preposition)"},{"id":48098,"position":4,"text_uthmani":"قَبْلَ","transliteration":"qabla","translation_bn":"এর পূর্বেই","root":"قبل","lemma":"قَبْل","grammar_bn":"কালবাচক (Time)"},{"id":48099,"position":5,"text_uthmani":"أَنْ","transliteration":"an","translation_bn":"যে","root":"—","lemma":"أَن\r","grammar_bn":"অধীনস্থ যোজক (Subordinating)"},{"id":48100,"position":6,"text_uthmani":"ءَاذَنَ","transliteration":"ādhana","translation_bn":"আমি দিবো অনুমতি","root":"اذن","lemma":"أَذِنَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":48101,"position":7,"text_uthmani":"لَكُمْ ۖ","transliteration":"lakum","translation_bn":"জন্যে তোমাদের","root":"—","lemma":"لَكُمْ ۖ","grammar_bn":"অব্যয় (Preposition)"},{"id":48103,"position":8,"text_uthmani":"إِنَّهُۥ","transliteration":"innahu","translation_bn":"নিশ্চয়ই সে","root":"—","lemma":"إِنّ","grammar_bn":"অভিঘাত পদ (Accusative)"},{"id":48104,"position":9,"text_uthmani":"لَكَبِيرُكُمُ","transliteration":"lakabīrukumu","translation_bn":"অবশ্যই প্রধান (নেতা) তোমাদের","root":"كبر","lemma":"كَبِير","grammar_bn":"দৃঢ়তাবোধক (Emphatic)"},{"id":48105,"position":10,"text_uthmani":"ٱلَّذِى","transliteration":"alladhī","translation_bn":"যে","root":"—","lemma":"ٱلَّذِى","grammar_bn":"সাপেক্ষ সর্বনাম (Relative)"},{"id":48106,"position":11,"text_uthmani":"عَلَّمَكُمُ","transliteration":"ʿallamakumu","translation_bn":"তোমাদেরকে শিখিয়েছে","root":"علم","lemma":"عَلَّمَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":48107,"position":12,"text_uthmani":"ٱلسِّحْرَ","transliteration":"l-siḥ''ra","translation_bn":"জাদু","root":"سحر","lemma":"سِحْر","grammar_bn":"শব্দ"},{"id":48108,"position":13,"text_uthmani":"فَلَسَوْفَ","transliteration":"falasawfa","translation_bn":"অতএব শীঘ্রই","root":"—","lemma":"سَوْف\r","grammar_bn":"শব্দ"},{"id":48109,"position":14,"text_uthmani":"تَعْلَمُونَ ۚ","transliteration":"taʿlamūna","translation_bn":"তোমরা জানতে পারবে (পরিণাম)","root":"علم","lemma":"عَلِمَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":48111,"position":15,"text_uthmani":"لَأُقَطِّعَنَّ","transliteration":"la-uqaṭṭiʿanna","translation_bn":"অবশ্যই আমি কাটবোই","root":"قطع","lemma":"قَطَّعَ","grammar_bn":"দৃঢ়তাবোধক (Emphatic)"},{"id":48112,"position":16,"text_uthmani":"أَيْدِيَكُمْ","transliteration":"aydiyakum","translation_bn":"হাতগুলোকে তোমাদের","root":"يدي","lemma":"يَد","grammar_bn":"বিশেষ্য (Noun)"},{"id":48113,"position":17,"text_uthmani":"وَأَرْجُلَكُم","transliteration":"wa-arjulakum","translation_bn":"ও পাগুলোকে তোমাদের","root":"رجل","lemma":"رِجْل","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":48114,"position":18,"text_uthmani":"مِّنْ","transliteration":"min","translation_bn":"হ''তে","root":"—","lemma":"مِن\r","grammar_bn":"অব্যয় (Preposition)"},{"id":48115,"position":19,"text_uthmani":"خِلَـٰفٍۢ","transliteration":"khilāfin","translation_bn":"বিপরীত দিক","root":"خلف","lemma":"خِلَٰف","grammar_bn":"বিশেষ্য (Noun)"},{"id":48116,"position":20,"text_uthmani":"وَلَأُصَلِّبَنَّكُمْ","transliteration":"wala-uṣallibannakum","translation_bn":"আর অবশ্যই তোমাদেরকে শূলে চড়াবো","root":"صلب","lemma":"يُصَلَّبُ","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":48117,"position":21,"text_uthmani":"أَجْمَعِينَ","transliteration":"ajmaʿīna","translation_bn":"সবাইকে\"","root":"جمع","lemma":"أَجْمَعِين","grammar_bn":"বিশেষ্য (Noun)"},{"id":48118,"position":22,"text_uthmani":"٤٩","transliteration":"","translation_bn":"(৪৯)","root":"—","lemma":"٤٩","grammar_bn":"মার্কার"}]'::jsonb, 'qāla āmantum lahu qabla an ādhana lakum innahu lakabīrukumu alladhī ʿallamakumu l-siḥ''ra falasawfa taʿlamūna la-uqaṭṭiʿanna aydiyakum wa-arjulakum min khilāfin wala-uṣallibannakum ajmaʿīna', 'ফেরাউন বলল- ‘আমি তোমাদেরকে অনুমতি দেয়ার আগেই তোমরা তাতে বিশ্বাস আনলে? নিশ্চয়ই সে তোমাদের ওস্তাদ যে তোমাদেরকে যাদু শিখিয়েছে। শীঘ্রই তোমরা (এর পরিণাম) জানতে পারবে। আমি অবশ্য অবশ্যই তোমাদের হাত-পাগুলোকে বিপরীত দিক থেকে কেটে ফেলব আর তোমাদের সব্বাইকে অবশ্য অবশ্যই ‘শূলে চড়াব।', '[Pharaoh] said, "You believed Moses before I gave you permission. Indeed, he is your leader who has taught you magic, but you are going to know. I will surely cut off your hands and your feet on opposite sides, and I will surely crucify you all."', 'ফেরাউন বলল- ‘আমি তোমাদেরকে অনুমতি দেয়ার আগেই তোমরা তাতে বিশ্বাস আনলে? নিশ্চয়ই সে তোমাদের ওস্তাদ যে তোমাদেরকে যাদু শিখিয়েছে। শীঘ্রই তোমরা (এর পরিণাম) জানতে পারবে। আমি অবশ্য অবশ্যই তোমাদের হাত-পাগুলোকে বিপরীত দিক থেকে কেটে ফেলব আর তোমাদের সব্বাইকে অবশ্য অবশ্যই ‘শূলে চড়াব।', '[Pharaoh] said, "You believed Moses before I gave you permission. Indeed, he is your leader who has taught you magic, but you are going to know. I will surely cut off your hands and your feet on opposite sides, and I will surely crucify you all."', NULL, NULL, NULL, NULL, NULL, 'https://everyayah.com/data/Alafasy_128kbps/026049.mp3', now()),
  (26, 50, '', '[{"id":48788,"position":1,"text_uthmani":"قَالُوا۟","transliteration":"qālū","translation_bn":"তারা বললো","root":"قول","lemma":"قَالَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":48789,"position":2,"text_uthmani":"لَا","transliteration":"lā","translation_bn":"\"নেই","root":"—","lemma":"لَا\r","grammar_bn":"না-বোধক (Negative)"},{"id":48790,"position":3,"text_uthmani":"ضَيْرَ ۖ","transliteration":"ḍayra","translation_bn":"কোনো ক্ষতি","root":"ضير","lemma":"ضَيْر","grammar_bn":"বিশেষ্য (Noun)"},{"id":48792,"position":4,"text_uthmani":"إِنَّآ","transliteration":"innā","translation_bn":"নিশ্চয়ই আমরা","root":"—","lemma":"إِنّ","grammar_bn":"অভিঘাত পদ (Accusative)"},{"id":48793,"position":5,"text_uthmani":"إِلَىٰ","transliteration":"ilā","translation_bn":"দিকে","root":"—","lemma":"إِلَىٰ\r","grammar_bn":"অব্যয় (Preposition)"},{"id":48794,"position":6,"text_uthmani":"رَبِّنَا","transliteration":"rabbinā","translation_bn":"আমাদের রবের","root":"ربب","lemma":"رَبّ","grammar_bn":"বিশেষ্য (Noun)"},{"id":48795,"position":7,"text_uthmani":"مُنقَلِبُونَ","transliteration":"munqalibūna","translation_bn":"প্রত্যাবর্তনকারী","root":"قلب","lemma":"مُنقَلِبُون","grammar_bn":"বিশেষ্য (Noun)"},{"id":48796,"position":8,"text_uthmani":"٥٠","transliteration":"","translation_bn":"(৫০)","root":"—","lemma":"٥٠","grammar_bn":"মার্কার"}]'::jsonb, 'qālū lā ḍayra innā ilā rabbinā munqalibūna', 'তারা বলল- কোনই ক্ষতি নেই, আমরা আমাদের প্রতিপালকের পানে প্রত্যাবর্তন করব।', 'They said, "No harm. Indeed, to our Lord we will return.', 'তারা বলল- কোনই ক্ষতি নেই, আমরা আমাদের প্রতিপালকের পানে প্রত্যাবর্তন করব।', 'They said, "No harm. Indeed, to our Lord we will return.', NULL, NULL, NULL, NULL, NULL, 'https://everyayah.com/data/Alafasy_128kbps/026050.mp3', now()),
  (26, 51, '', '[{"id":49351,"position":1,"text_uthmani":"إِنَّا","transliteration":"innā","translation_bn":"নিশ্চয়ই  আমরা","root":"—","lemma":"إِنّ","grammar_bn":"অভিঘাত পদ (Accusative)"},{"id":49352,"position":2,"text_uthmani":"نَطْمَعُ","transliteration":"naṭmaʿu","translation_bn":"আশা করি","root":"طمع","lemma":"يَطْمَعُ","grammar_bn":"ক্রিয়া (Verb)"},{"id":49353,"position":3,"text_uthmani":"أَن","transliteration":"an","translation_bn":"যে","root":"—","lemma":"أَن\r","grammar_bn":"অধীনস্থ যোজক (Subordinating)"},{"id":49354,"position":4,"text_uthmani":"يَغْفِرَ","transliteration":"yaghfira","translation_bn":"ক্ষমা করবেন","root":"غفر","lemma":"غَفَرَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":49355,"position":5,"text_uthmani":"لَنَا","transliteration":"lanā","translation_bn":"আমাদেরকে","root":"—","lemma":"لَنَا","grammar_bn":"অব্যয় (Preposition)"},{"id":49356,"position":6,"text_uthmani":"رَبُّنَا","transliteration":"rabbunā","translation_bn":"রব আমাদের","root":"ربب","lemma":"رَبّ","grammar_bn":"বিশেষ্য (Noun)"},{"id":49357,"position":7,"text_uthmani":"خَطَـٰيَـٰنَآ","transliteration":"khaṭāyānā","translation_bn":"ভুলক্রটিগুলোকে আমাদের","root":"خطا","lemma":"خَطِي^ـ#َة","grammar_bn":"বিশেষ্য (Noun)"},{"id":49358,"position":8,"text_uthmani":"أَن","transliteration":"an","translation_bn":"(এজন্য) যে","root":"—","lemma":"أَن\r","grammar_bn":"অধীনস্থ যোজক (Subordinating)"},{"id":49359,"position":9,"text_uthmani":"كُنَّآ","transliteration":"kunnā","translation_bn":"আমরা হলাম","root":"كون","lemma":"كَانَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":49360,"position":10,"text_uthmani":"أَوَّلَ","transliteration":"awwala","translation_bn":"প্রথম","root":"اول","lemma":"أَوَّل","grammar_bn":"বিশেষ্য (Noun)"},{"id":49361,"position":11,"text_uthmani":"ٱلْمُؤْمِنِينَ","transliteration":"l-mu''minīna","translation_bn":"মু''মিন\"","root":"امن","lemma":"مُؤْمِن","grammar_bn":"শব্দ"},{"id":49362,"position":12,"text_uthmani":"٥١","transliteration":"","translation_bn":"(৫১)","root":"—","lemma":"٥١","grammar_bn":"মার্কার"}]'::jsonb, 'innā naṭmaʿu an yaghfira lanā rabbunā khaṭāyānā an kunnā awwala l-mu''minīna', 'আমাদের একমাত্র আশা এই যে, আমাদের প্রতিপালক আমাদের ত্রুটি-বিচ্যুতি ক্ষমা করবেন, কারণ আমরা বিশ্বাস স্থাপনকারীদের মধ্যে প্রথম।’', 'Indeed, we aspire that our Lord will forgive us our sins because we were the first of the believers."', 'আমাদের একমাত্র আশা এই যে, আমাদের প্রতিপালক আমাদের ত্রুটি-বিচ্যুতি ক্ষমা করবেন, কারণ আমরা বিশ্বাস স্থাপনকারীদের মধ্যে প্রথম।’', 'Indeed, we aspire that our Lord will forgive us our sins because we were the first of the believers."', NULL, NULL, NULL, NULL, NULL, 'https://everyayah.com/data/Alafasy_128kbps/026051.mp3', now()),
