  (26, 57, '', '[{"id":52881,"position":1,"text_uthmani":"فَأَخْرَجْنَـٰهُم","transliteration":"fa-akhrajnāhum","translation_bn":"এরপর আমরা বের করলাম তাদেরকে","root":"خرج","lemma":"أَخْرَجَ","grammar_bn":"শব্দ"},{"id":52882,"position":2,"text_uthmani":"مِّن","transliteration":"min","translation_bn":"হ''তে","root":"—","lemma":"مِن\r","grammar_bn":"অব্যয় (Preposition)"},{"id":52883,"position":3,"text_uthmani":"جَنَّـٰتٍۢ","transliteration":"jannātin","translation_bn":"বাগান","root":"جنن","lemma":"جَنَّة","grammar_bn":"বিশেষ্য (Noun)"},{"id":52884,"position":4,"text_uthmani":"وَعُيُونٍۢ","transliteration":"waʿuyūnin","translation_bn":"ও ঝর্ণাসমূহ","root":"عين","lemma":"عَيْن","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":52885,"position":5,"text_uthmani":"٥٧","transliteration":"","translation_bn":"(৫৭)","root":"—","lemma":"٥٧","grammar_bn":"মার্কার"}]'::jsonb, 'fa-akhrajnāhum min jannātin waʿuyūnin', 'এভাবে আমি ফেরাউন গোষ্ঠীকে (তাদের নিজেদেরই) উদ্যানরাজি আর ঝর্ণাসমূহ থেকে বহিস্কার করলাম।', 'So We removed them from gardens and springs', 'এভাবে আমি ফেরাউন গোষ্ঠীকে (তাদের নিজেদেরই) উদ্যানরাজি আর ঝর্ণাসমূহ থেকে বহিস্কার করলাম।', 'So We removed them from gardens and springs', NULL, NULL, NULL, NULL, NULL, 'https://everyayah.com/data/Alafasy_128kbps/026057.mp3', now()),
  (26, 58, '', '[{"id":53579,"position":1,"text_uthmani":"وَكُنُوزٍۢ","transliteration":"wakunūzin","translation_bn":"এবং ধন-ভান্ডার","root":"كنز","lemma":"كَنز","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":53580,"position":2,"text_uthmani":"وَمَقَامٍۢ","transliteration":"wamaqāmin","translation_bn":"ও (হ''তে) স্থানসমূহ","root":"قوم","lemma":"مَقَام","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":53581,"position":3,"text_uthmani":"كَرِيمٍۢ","transliteration":"karīmin","translation_bn":"সম্মানের","root":"كرم","lemma":"كَرِيم","grammar_bn":"বিশেষণ (Adjective)"},{"id":53582,"position":4,"text_uthmani":"٥٨","transliteration":"","translation_bn":"(৫৮)","root":"—","lemma":"٥٨","grammar_bn":"মার্কার"}]'::jsonb, 'wakunūzin wamaqāmin karīmin', 'আর ধনভন্ডারসমূহ ও সম্মানজনক অবস্থান থেকে।', 'And treasures and honorable station -', 'আর ধনভন্ডারসমূহ ও সম্মানজনক অবস্থান থেকে।', 'And treasures and honorable station -', NULL, NULL, NULL, NULL, NULL, 'https://everyayah.com/data/Alafasy_128kbps/026058.mp3', now()),
  (26, 59, '', '[{"id":53903,"position":1,"text_uthmani":"كَذَٰلِكَ","transliteration":"kadhālika","translation_bn":"এরূপই (ঘটেছিলো)","root":"—","lemma":"ذَٰلِك","grammar_bn":"অব্যয় (Preposition)"},{"id":53904,"position":2,"text_uthmani":"وَأَوْرَثْنَـٰهَا","transliteration":"wa-awrathnāhā","translation_bn":"আর আমরা উত্তরাধিকারী করেছিলাম তার","root":"ورث","lemma":"أَوْرَثَ","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":53905,"position":3,"text_uthmani":"بَنِىٓ","transliteration":"banī","translation_bn":"বনী","root":"بني","lemma":"بُنَىّ","grammar_bn":"বিশেষ্য (Noun)"},{"id":53906,"position":4,"text_uthmani":"إِسْرَٰٓءِيلَ","transliteration":"is''rāīla","translation_bn":"ইসরাঈলদেরকে","root":"—","lemma":"إِسْرَائِيل","grammar_bn":"নামবাচক বিশেষ্য (Proper Noun)"},{"id":53907,"position":5,"text_uthmani":"٥٩","transliteration":"","translation_bn":"(৫৯)","root":"—","lemma":"٥٩","grammar_bn":"মার্কার"}]'::jsonb, 'kadhālika wa-awrathnāhā banī is''rāīla', 'এভাবেই ঘটেছিল, আমি বানী ইসরাঈলকে এসব কিছুর উত্তরাধিকারী করে দিয়েছিলাম।', 'Thus. And We caused to inherit it the Children of Israel.', 'এভাবেই ঘটেছিল, আমি বানী ইসরাঈলকে এসব কিছুর উত্তরাধিকারী করে দিয়েছিলাম।', 'Thus. And We caused to inherit it the Children of Israel.', NULL, NULL, NULL, NULL, NULL, 'https://everyayah.com/data/Alafasy_128kbps/026059.mp3', now()),
  (26, 60, '', '[{"id":54554,"position":1,"text_uthmani":"فَأَتْبَعُوهُم","transliteration":"fa-atbaʿūhum","translation_bn":"অতঃপর তারা পিছু নিলো তাদেরকে","root":"تبع","lemma":"أَتْبَعَ","grammar_bn":"শব্দ"},{"id":54555,"position":2,"text_uthmani":"مُّشْرِقِينَ","transliteration":"mush''riqīna","translation_bn":"সূর্যোদয়ের সময়","root":"شرق","lemma":"مُّشْرِقِين","grammar_bn":"বিশেষ্য (Noun)"},{"id":54556,"position":3,"text_uthmani":"٦٠","transliteration":"","translation_bn":"(৬০)","root":"—","lemma":"٦٠","grammar_bn":"মার্কার"}]'::jsonb, 'fa-atbaʿūhum mush''riqīna', 'কাজেই তারা (অর্থাৎ ফেরাউন গোষ্ঠী) সূর্যোদয়কালে তাদের পশ্চাদ্ধাবন করল।', 'So they pursued them at sunrise.', 'কাজেই তারা (অর্থাৎ ফেরাউন গোষ্ঠী) সূর্যোদয়কালে তাদের পশ্চাদ্ধাবন করল।', 'So they pursued them at sunrise.', NULL, NULL, NULL, NULL, NULL, 'https://everyayah.com/data/Alafasy_128kbps/026060.mp3', now()),
