  (26, 80, '', '[{"id":64222,"position":1,"text_uthmani":"وَإِذَا","transliteration":"wa-idhā","translation_bn":"এবং যখন","root":"—","lemma":"إِذَا\r","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":64223,"position":2,"text_uthmani":"مَرِضْتُ","transliteration":"mariḍ''tu","translation_bn":"আমি অসুস্থ হই","root":"مرض","lemma":"مَرِضْ","grammar_bn":"ক্রিয়া (Verb)"},{"id":64224,"position":3,"text_uthmani":"فَهُوَ","transliteration":"fahuwa","translation_bn":"তখন তিনিই","root":"—","lemma":"فَهُوَ","grammar_bn":"শব্দ"},{"id":64225,"position":4,"text_uthmani":"يَشْفِينِ","transliteration":"yashfīni","translation_bn":"আমাকে আরোগ্য দান করেন","root":"شفي","lemma":"يَشْفِ","grammar_bn":"ক্রিয়া (Verb)"},{"id":64226,"position":5,"text_uthmani":"٨٠","transliteration":"","translation_bn":"(৮০)","root":"—","lemma":"٨٠","grammar_bn":"মার্কার"}]'::jsonb, 'wa-idhā mariḍ''tu fahuwa yashfīni', 'আর আমি যখন পীড়িত হই তখন তিনিই আমাকে আরোগ্য করেন।', 'And when I am ill, it is He who cures me', 'আর আমি যখন পীড়িত হই তখন তিনিই আমাকে আরোগ্য করেন।', 'And when I am ill, it is He who cures me', NULL, NULL, NULL, NULL, NULL, 'https://everyayah.com/data/Alafasy_128kbps/026080.mp3', now()),
  (26, 81, '', '[{"id":64536,"position":1,"text_uthmani":"وَٱلَّذِى","transliteration":"wa-alladhī","translation_bn":"এবং (তিনিই) যিনি","root":"—","lemma":"ٱلَّذِى","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":64537,"position":2,"text_uthmani":"يُمِيتُنِى","transliteration":"yumītunī","translation_bn":"আমাকে মৃত্যু দিবেন","root":"موت","lemma":"أَمَاتَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":64538,"position":3,"text_uthmani":"ثُمَّ","transliteration":"thumma","translation_bn":"এরপর","root":"—","lemma":"ثُمّ\r","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":64539,"position":4,"text_uthmani":"يُحْيِينِ","transliteration":"yuḥ''yīni","translation_bn":"জীবিত করবেন","root":"حيي","lemma":"أَحْيَا","grammar_bn":"ক্রিয়া (Verb)"},{"id":64540,"position":5,"text_uthmani":"٨١","transliteration":"","translation_bn":"(৮১)","root":"—","lemma":"٨١","grammar_bn":"মার্কার"}]'::jsonb, 'wa-alladhī yumītunī thumma yuḥ''yīni', 'যিনি আমার মৃত্যু ঘটাবেন, পুনরায় আমাকে জীবিত করবেন।', 'And who will cause me to die and then bring me to life', 'যিনি আমার মৃত্যু ঘটাবেন, পুনরায় আমাকে জীবিত করবেন।', 'And who will cause me to die and then bring me to life', NULL, NULL, NULL, NULL, NULL, 'https://everyayah.com/data/Alafasy_128kbps/026081.mp3', now()),
  (26, 82, '', '[{"id":65097,"position":1,"text_uthmani":"وَٱلَّذِىٓ","transliteration":"wa-alladhī","translation_bn":"(তিনিই) যার (নিকট)","root":"—","lemma":"ٱلَّذِى","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":65098,"position":2,"text_uthmani":"أَطْمَعُ","transliteration":"aṭmaʿu","translation_bn":"আশা করি আমি","root":"طمع","lemma":"يَطْمَعُ","grammar_bn":"ক্রিয়া (Verb)"},{"id":65099,"position":3,"text_uthmani":"أَن","transliteration":"an","translation_bn":"যে","root":"—","lemma":"أَن\r","grammar_bn":"অধীনস্থ যোজক (Subordinating)"},{"id":65100,"position":4,"text_uthmani":"يَغْفِرَ","transliteration":"yaghfira","translation_bn":"ক্ষমা করবেন","root":"غفر","lemma":"غَفَرَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":65101,"position":5,"text_uthmani":"لِى","transliteration":"lī","translation_bn":"আমাকে","root":"—","lemma":"لِى","grammar_bn":"অব্যয় (Preposition)"},{"id":65102,"position":6,"text_uthmani":"خَطِيٓـَٔتِى","transliteration":"khaṭīatī","translation_bn":"আমার ভুলত্রুটি","root":"خطا","lemma":"خَطِي^ـ#َة","grammar_bn":"বিশেষ্য (Noun)"},{"id":65103,"position":7,"text_uthmani":"يَوْمَ","transliteration":"yawma","translation_bn":"দিনে","root":"يوم","lemma":"يَوْم","grammar_bn":"বিশেষ্য (Noun)"},{"id":65104,"position":8,"text_uthmani":"ٱلدِّينِ","transliteration":"l-dīni","translation_bn":"বিচারের","root":"دين","lemma":"دِين","grammar_bn":"শব্দ"},{"id":65105,"position":9,"text_uthmani":"٨٢","transliteration":"","translation_bn":"(৮২)","root":"—","lemma":"٨٢","grammar_bn":"মার্কার"}]'::jsonb, 'wa-alladhī aṭmaʿu an yaghfira lī khaṭīatī yawma l-dīni', 'আর যিনি, আমি আশা করি- কিয়ামাতের দিন আমার দোষ-ত্রুটি ক্ষমা করে দেবেন।', 'And who I aspire that He will forgive me my sin on the Day of Recompense."', 'আর যিনি, আমি আশা করি- কিয়ামাতের দিন আমার দোষ-ত্রুটি ক্ষমা করে দেবেন।', 'And who I aspire that He will forgive me my sin on the Day of Recompense."', NULL, NULL, NULL, NULL, NULL, 'https://everyayah.com/data/Alafasy_128kbps/026082.mp3', now()),
  (26, 83, '', '[{"id":65425,"position":1,"text_uthmani":"رَبِّ","transliteration":"rabbi","translation_bn":"(পরে বললেন) হে আমার রব","root":"ربب","lemma":"رَبّ","grammar_bn":"বিশেষ্য (Noun)"},{"id":65426,"position":2,"text_uthmani":"هَبْ","transliteration":"hab","translation_bn":"দান করো","root":"وهب","lemma":"وَهَبَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":65427,"position":3,"text_uthmani":"لِى","transliteration":"lī","translation_bn":"জন্যে আমার","root":"—","lemma":"لِى","grammar_bn":"অব্যয় (Preposition)"},{"id":65428,"position":4,"text_uthmani":"حُكْمًۭا","transliteration":"ḥuk''man","translation_bn":"প্রজ্ঞা","root":"حكم","lemma":"حُكْم","grammar_bn":"বিশেষ্য (Noun)"},{"id":65429,"position":5,"text_uthmani":"وَأَلْحِقْنِى","transliteration":"wa-alḥiq''nī","translation_bn":"ও মিলিত করো","root":"لحق","lemma":"أَلْحَقْ","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":65430,"position":6,"text_uthmani":"بِٱلصَّـٰلِحِينَ","transliteration":"bil-ṣāliḥīna","translation_bn":"সাথে সৎকর্মশীলদের","root":"صلح","lemma":"صَٰلِح","grammar_bn":"অব্যয় (Preposition)"},{"id":65431,"position":7,"text_uthmani":"٨٣","transliteration":"","translation_bn":"(৮৩)","root":"—","lemma":"٨٣","grammar_bn":"মার্কার"}]'::jsonb, 'rabbi hab lī ḥuk''man wa-alḥiq''nī bil-ṣāliḥīna', 'হে আমার পালনকর্তা! আমাকে প্রজ্ঞা দান কর এবং আমাকে সৎকর্মশীলদের অর্ন্তভুক্ত কর।', '[And he said], "My Lord, grant me authority and join me with the righteous.', 'হে আমার পালনকর্তা! আমাকে প্রজ্ঞা দান কর এবং আমাকে সৎকর্মশীলদের অর্ন্তভুক্ত কর।', '[And he said], "My Lord, grant me authority and join me with the righteous.', NULL, NULL, NULL, NULL, NULL, 'https://everyayah.com/data/Alafasy_128kbps/026083.mp3', now()),
