  (26, 102, '', '[{"id":71853,"position":1,"text_uthmani":"فَلَوْ","transliteration":"falaw","translation_bn":"অতএব যদি (থাকতো)","root":"—","lemma":"لَو\r","grammar_bn":"শব্দ"},{"id":71854,"position":2,"text_uthmani":"أَنَّ","transliteration":"anna","translation_bn":"নিশ্চিত","root":"—","lemma":"أَنّ","grammar_bn":"অভিঘাত পদ (Accusative)"},{"id":71855,"position":3,"text_uthmani":"لَنَا","transliteration":"lanā","translation_bn":"জন্যে আমাদের (সম্ভব হতো)","root":"—","lemma":"لَنَا","grammar_bn":"অব্যয় (Preposition)"},{"id":71856,"position":4,"text_uthmani":"كَرَّةًۭ","transliteration":"karratan","translation_bn":"একবার (ফিরে যাওয়া)","root":"كرر","lemma":"كَرَّة","grammar_bn":"বিশেষ্য (Noun)"},{"id":71857,"position":5,"text_uthmani":"فَنَكُونَ","transliteration":"fanakūna","translation_bn":"তবে আমরা হতাম","root":"كون","lemma":"كَانَ","grammar_bn":"কারণবাচক (Cause)"},{"id":71858,"position":6,"text_uthmani":"مِنَ","transliteration":"mina","translation_bn":"অন্তর্ভুক্ত","root":"—","lemma":"مِن\r","grammar_bn":"অব্যয় (Preposition)"},{"id":71859,"position":7,"text_uthmani":"ٱلْمُؤْمِنِينَ","transliteration":"l-mu''minīna","translation_bn":"মু''মিনদের\"","root":"امن","lemma":"مُؤْمِن","grammar_bn":"শব্দ"},{"id":71860,"position":8,"text_uthmani":"١٠٢","transliteration":"","translation_bn":"(১০২)","root":"—","lemma":"١٠٢","grammar_bn":"মার্কার"}]'::jsonb, 'falaw anna lanā karratan fanakūna mina l-mu''minīna', 'আমাদের যদি একটিবার পৃথিবীতে ফিরে যাওয়ার সুযোগ হত, তাহলে আমরা মু’মিনদের অর্ন্তভুক্ত হয়ে যেতাম।', 'Then if we only had a return [to the world] and could be of the believers... "', 'আমাদের যদি একটিবার পৃথিবীতে ফিরে যাওয়ার সুযোগ হত, তাহলে আমরা মু’মিনদের অর্ন্তভুক্ত হয়ে যেতাম।', 'Then if we only had a return [to the world] and could be of the believers... "', NULL, NULL, NULL, NULL, NULL, 'https://everyayah.com/data/Alafasy_128kbps/026102.mp3', now()),
  (26, 103, '', '[{"id":72261,"position":1,"text_uthmani":"إِنَّ","transliteration":"inna","translation_bn":"নিশ্চয়ই","root":"—","lemma":"إِنّ","grammar_bn":"অভিঘাত পদ (Accusative)"},{"id":72262,"position":2,"text_uthmani":"فِى","transliteration":"fī","translation_bn":"মধ্যে (আছে)","root":"—","lemma":"فِى\r","grammar_bn":"অব্যয় (Preposition)"},{"id":72263,"position":3,"text_uthmani":"ذَٰلِكَ","transliteration":"dhālika","translation_bn":"এর","root":"—","lemma":"ذَٰلِك","grammar_bn":"নির্দেশক সর্বনাম (Demonstrative)"},{"id":72264,"position":4,"text_uthmani":"لَـَٔايَةًۭ ۖ","transliteration":"laāyatan","translation_bn":"অবশ্যই নিদর্শন","root":"ايي","lemma":"ءَايَة","grammar_bn":"দৃঢ়তাবোধক (Emphatic)"},{"id":72266,"position":5,"text_uthmani":"وَمَا","transliteration":"wamā","translation_bn":"কিন্তু না","root":"—","lemma":"مَا\r","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":72267,"position":6,"text_uthmani":"كَانَ","transliteration":"kāna","translation_bn":"ছিলো","root":"كون","lemma":"كَانَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":72268,"position":7,"text_uthmani":"أَكْثَرُهُم","transliteration":"aktharuhum","translation_bn":"অধিকাংশ তাদের","root":"كثر","lemma":"أَكْثَر","grammar_bn":"বিশেষ্য (Noun)"},{"id":72269,"position":8,"text_uthmani":"مُّؤْمِنِينَ","transliteration":"mu''minīna","translation_bn":"মু''মিন","root":"امن","lemma":"مُؤْمِن","grammar_bn":"বিশেষ্য (Noun)"},{"id":72270,"position":9,"text_uthmani":"١٠٣","transliteration":"","translation_bn":"(১০৩)","root":"—","lemma":"١٠٣","grammar_bn":"মার্কার"}]'::jsonb, 'inna fī dhālika laāyatan wamā kāna aktharuhum mu''minīna', 'এতে অবশ্যই নিদর্শন আছে, কিন্তু তাদের অধিকাংশই ঈমান আনে না।', 'Indeed in that is a sign, but most of them were not to be believers.', 'এতে অবশ্যই নিদর্শন আছে, কিন্তু তাদের অধিকাংশই ঈমান আনে না।', 'Indeed in that is a sign, but most of them were not to be believers.', NULL, NULL, NULL, NULL, NULL, 'https://everyayah.com/data/Alafasy_128kbps/026103.mp3', now()),
  (26, 104, '', '[{"id":72552,"position":1,"text_uthmani":"وَإِنَّ","transliteration":"wa-inna","translation_bn":"এবং নিশ্চয়ই","root":"—","lemma":"إِنّ","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":72553,"position":2,"text_uthmani":"رَبَّكَ","transliteration":"rabbaka","translation_bn":"তোমার রব","root":"ربب","lemma":"رَبّ","grammar_bn":"বিশেষ্য (Noun)"},{"id":72554,"position":3,"text_uthmani":"لَهُوَ","transliteration":"lahuwa","translation_bn":"অবশ্যই তিনি","root":"—","lemma":"لَهُوَ","grammar_bn":"দৃঢ়তাবোধক (Emphatic)"},{"id":72555,"position":4,"text_uthmani":"ٱلْعَزِيزُ","transliteration":"l-ʿazīzu","translation_bn":"পরাক্রমশালী","root":"عزز","lemma":"عَزِيز","grammar_bn":"শব্দ"},{"id":72556,"position":5,"text_uthmani":"ٱلرَّحِيمُ","transliteration":"l-raḥīmu","translation_bn":"পরম দয়ালু","root":"رحم","lemma":"رَّحِيم","grammar_bn":"শব্দ"},{"id":72557,"position":6,"text_uthmani":"١٠٤","transliteration":"","translation_bn":"(১০৪)","root":"—","lemma":"١٠٤","grammar_bn":"মার্কার"}]'::jsonb, 'wa-inna rabbaka lahuwa l-ʿazīzu l-raḥīmu', 'তোমার প্রতিপালক, তিনি অবশ্যই মহা পরাক্রমশালী, পরম দয়ালু।', 'And indeed, your Lord - He is the Exalted in Might, the Merciful.', 'তোমার প্রতিপালক, তিনি অবশ্যই মহা পরাক্রমশালী, পরম দয়ালু।', 'And indeed, your Lord - He is the Exalted in Might, the Merciful.', NULL, NULL, NULL, NULL, NULL, 'https://everyayah.com/data/Alafasy_128kbps/026104.mp3', now()),
  (26, 105, '', '[{"id":72689,"position":1,"text_uthmani":"كَذَّبَتْ","transliteration":"kadhabat","translation_bn":"মিথ্যারোপ করেছিলো","root":"كذب","lemma":"كَذَّبَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":72690,"position":2,"text_uthmani":"قَوْمُ","transliteration":"qawmu","translation_bn":"জাতি","root":"قوم","lemma":"قَوْم","grammar_bn":"বিশেষ্য (Noun)"},{"id":72691,"position":3,"text_uthmani":"نُوحٍ","transliteration":"nūḥin","translation_bn":"নূহের","root":"—","lemma":"نُوح","grammar_bn":"নামবাচক বিশেষ্য (Proper Noun)"},{"id":72692,"position":4,"text_uthmani":"ٱلْمُرْسَلِينَ","transliteration":"l-mur''salīna","translation_bn":"রাসূলদেরকে","root":"رسل","lemma":"مُّرْسَل","grammar_bn":"শব্দ"},{"id":72693,"position":5,"text_uthmani":"١٠٥","transliteration":"","translation_bn":"(১০৫)","root":"—","lemma":"١٠٥","grammar_bn":"মার্কার"}]'::jsonb, 'kadhabat qawmu nūḥin l-mur''salīna', 'নূহের কওম রসুলগণকে মিথ্যে ব’লে প্রত্যাখান করেছিল।', 'The people of Noah denied the messengers', 'নূহের কওম রসুলগণকে মিথ্যে ব’লে প্রত্যাখান করেছিল।', 'The people of Noah denied the messengers', NULL, NULL, NULL, NULL, NULL, 'https://everyayah.com/data/Alafasy_128kbps/026105.mp3', now()),
  (26, 106, '', '[{"id":73058,"position":1,"text_uthmani":"إِذْ","transliteration":"idh","translation_bn":"(স্মরণ করো) যখন","root":"—","lemma":"إِذ\r","grammar_bn":"কালবাচক (Time)"},{"id":73059,"position":2,"text_uthmani":"قَالَ","transliteration":"qāla","translation_bn":"বলেছিলো","root":"قول","lemma":"قَالَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":73060,"position":3,"text_uthmani":"لَهُمْ","transliteration":"lahum","translation_bn":"উদ্দেশ্যে তাদের","root":"—","lemma":"لَهُمْ","grammar_bn":"অব্যয় (Preposition)"},{"id":73061,"position":4,"text_uthmani":"أَخُوهُمْ","transliteration":"akhūhum","translation_bn":"ভাই তাদের","root":"اخو","lemma":"أَخ","grammar_bn":"বিশেষ্য (Noun)"},{"id":73062,"position":5,"text_uthmani":"نُوحٌ","transliteration":"nūḥun","translation_bn":"নূহ","root":"—","lemma":"نُوح","grammar_bn":"নামবাচক বিশেষ্য (Proper Noun)"},{"id":73063,"position":6,"text_uthmani":"أَلَا","transliteration":"alā","translation_bn":"\"কি না","root":"—","lemma":"لَا\r","grammar_bn":"প্রশ্নবোধক (Interrogative)"},{"id":73064,"position":7,"text_uthmani":"تَتَّقُونَ","transliteration":"tattaqūna","translation_bn":"তোমরা ভয় করো","root":"وقي","lemma":"ٱتَّقَىٰ","grammar_bn":"ক্রিয়া (Verb)"},{"id":73065,"position":8,"text_uthmani":"١٠٦","transliteration":"","translation_bn":"(১০৬)","root":"—","lemma":"١٠٦","grammar_bn":"মার্কার"}]'::jsonb, 'idh qāla lahum akhūhum nūḥun alā tattaqūna', 'যখন তাদের ভ্রাতা নূহ তাদেরকে বলেছিল- ‘তোমরা কি ভয় করবে না (আল্লাহকে)?', 'When their brother Noah said to them, "Will you not fear Allah?', 'যখন তাদের ভ্রাতা নূহ তাদেরকে বলেছিল- ‘তোমরা কি ভয় করবে না (আল্লাহকে)?', 'When their brother Noah said to them, "Will you not fear Allah?', NULL, NULL, NULL, NULL, NULL, 'https://everyayah.com/data/Alafasy_128kbps/026106.mp3', now()),
  (26, 107, '', '[{"id":73283,"position":1,"text_uthmani":"إِنِّى","transliteration":"innī","translation_bn":"নিশ্চয়ই আমি","root":"—","lemma":"إِنّ","grammar_bn":"অভিঘাত পদ (Accusative)"},{"id":73284,"position":2,"text_uthmani":"لَكُمْ","transliteration":"lakum","translation_bn":"জন্যে তোমাদের","root":"—","lemma":"لَكُمْ","grammar_bn":"অব্যয় (Preposition)"},{"id":73285,"position":3,"text_uthmani":"رَسُولٌ","transliteration":"rasūlun","translation_bn":"একজন রাসূল","root":"رسل","lemma":"رَسُول","grammar_bn":"বিশেষ্য (Noun)"},{"id":73286,"position":4,"text_uthmani":"أَمِينٌۭ","transliteration":"amīnun","translation_bn":"বিশ্বস্ত","root":"امن","lemma":"أَمِين","grammar_bn":"বিশেষণ (Adjective)"},{"id":73287,"position":5,"text_uthmani":"١٠٧","transliteration":"","translation_bn":"(১০৭)","root":"—","lemma":"١٠٧","grammar_bn":"মার্কার"}]'::jsonb, 'innī lakum rasūlun amīnun', 'আমি তোমাদের জন্য (প্রেরিত) বিশ্বস্ত রাসুল।', 'Indeed, I am to you a trustworthy messenger.', 'আমি তোমাদের জন্য (প্রেরিত) বিশ্বস্ত রাসুল।', 'Indeed, I am to you a trustworthy messenger.', NULL, NULL, NULL, NULL, NULL, 'https://everyayah.com/data/Alafasy_128kbps/026107.mp3', now()),
  (26, 108, '', '[{"id":73652,"position":1,"text_uthmani":"فَٱتَّقُوا۟","transliteration":"fa-ittaqū","translation_bn":"অতএব তোমরা ভয় করো","root":"وقي","lemma":"ٱتَّقَىٰ","grammar_bn":"শব্দ"},{"id":73653,"position":2,"text_uthmani":"ٱللَّهَ","transliteration":"l-laha","translation_bn":"আল্লাহকে","root":"اله","lemma":"ٱللَّه","grammar_bn":"নামবাচক বিশেষ্য (Proper Noun)"},{"id":73654,"position":3,"text_uthmani":"وَأَطِيعُونِ","transliteration":"wa-aṭīʿūni","translation_bn":"ও আমার আনুগত্য করো","root":"طوع","lemma":"أَطَاعَ","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":73655,"position":4,"text_uthmani":"١٠٨","transliteration":"","translation_bn":"(১০৮)","root":"—","lemma":"١٠٨","grammar_bn":"মার্কার"}]'::jsonb, 'fa-ittaqū l-laha wa-aṭīʿūni', 'কাজেই তোমরা আল্লাহকে ভয় কর ও আমার অনুসরণ কর।', 'So fear Allah and obey me.', 'কাজেই তোমরা আল্লাহকে ভয় কর ও আমার অনুসরণ কর।', 'So fear Allah and obey me.', NULL, NULL, NULL, NULL, NULL, 'https://everyayah.com/data/Alafasy_128kbps/026108.mp3', now()),
  (26, 109, '', '[{"id":73996,"position":1,"text_uthmani":"وَمَآ","transliteration":"wamā","translation_bn":"আর না","root":"—","lemma":"مَا\r","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":73997,"position":2,"text_uthmani":"أَسْـَٔلُكُمْ","transliteration":"asalukum","translation_bn":"আমি চাচ্ছি তোমাদের (নিকট)","root":"سال","lemma":"سَأَلَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":73998,"position":3,"text_uthmani":"عَلَيْهِ","transliteration":"ʿalayhi","translation_bn":"জন্যে এর","root":"—","lemma":"عَلَىٰ\r","grammar_bn":"অব্যয় (Preposition)"},{"id":73999,"position":4,"text_uthmani":"مِنْ","transliteration":"min","translation_bn":"কোনো","root":"—","lemma":"مِن\r","grammar_bn":"অব্যয় (Preposition)"},{"id":74000,"position":5,"text_uthmani":"أَجْرٍ ۖ","transliteration":"ajrin","translation_bn":"প্রতিদান","root":"اجر","lemma":"أَجْر","grammar_bn":"বিশেষ্য (Noun)"},{"id":74002,"position":6,"text_uthmani":"إِنْ","transliteration":"in","translation_bn":"নেই","root":"—","lemma":"إِن\r","grammar_bn":"না-বোধক (Negative)"},{"id":74003,"position":7,"text_uthmani":"أَجْرِىَ","transliteration":"ajriya","translation_bn":"আমার প্রতিদান (অন্য কারো নিকট)","root":"اجر","lemma":"أَجْر","grammar_bn":"বিশেষ্য (Noun)"},{"id":74004,"position":8,"text_uthmani":"إِلَّا","transliteration":"illā","translation_bn":"এ ছাড়া","root":"—","lemma":"إِلَّا\r","grammar_bn":"সীমাবদ্ধতা (Restriction)"},{"id":74005,"position":9,"text_uthmani":"عَلَىٰ","transliteration":"ʿalā","translation_bn":"নিকট","root":"—","lemma":"عَلَىٰ\r","grammar_bn":"অব্যয় (Preposition)"},{"id":74006,"position":10,"text_uthmani":"رَبِّ","transliteration":"rabbi","translation_bn":"রবের","root":"ربب","lemma":"رَبّ","grammar_bn":"বিশেষ্য (Noun)"},{"id":74007,"position":11,"text_uthmani":"ٱلْعَـٰلَمِينَ","transliteration":"l-ʿālamīna","translation_bn":"বিশ্বজগতের","root":"علم","lemma":"عَٰلَمِين","grammar_bn":"শব্দ"},{"id":74008,"position":12,"text_uthmani":"١٠٩","transliteration":"","translation_bn":"(১০৯)","root":"—","lemma":"١٠٩","grammar_bn":"মার্কার"}]'::jsonb, 'wamā asalukum ʿalayhi min ajrin in ajriya illā ʿalā rabbi l-ʿālamīna', 'আমি তার জন্য তোমাদের কাছে কোন প্রতিদান চাই না। আমার প্রতিদান একমাত্র বিশ্বজগতের প্রতিপালকের কাছেই আছে।’', 'And I do not ask you for it any payment. My payment is only from the Lord of the worlds.', 'আমি তার জন্য তোমাদের কাছে কোন প্রতিদান চাই না। আমার প্রতিদান একমাত্র বিশ্বজগতের প্রতিপালকের কাছেই আছে।’', 'And I do not ask you for it any payment. My payment is only from the Lord of the worlds.', NULL, NULL, NULL, NULL, NULL, 'https://everyayah.com/data/Alafasy_128kbps/026109.mp3', now()),
  (26, 110, '', '[{"id":74197,"position":1,"text_uthmani":"فَٱتَّقُوا۟","transliteration":"fa-ittaqū","translation_bn":"সুতরাং তোমরা ভয় করো","root":"وقي","lemma":"ٱتَّقَىٰ","grammar_bn":"শব্দ"},{"id":74198,"position":2,"text_uthmani":"ٱللَّهَ","transliteration":"l-laha","translation_bn":"আল্লাহকে","root":"اله","lemma":"ٱللَّه","grammar_bn":"নামবাচক বিশেষ্য (Proper Noun)"},{"id":74199,"position":3,"text_uthmani":"وَأَطِيعُونِ","transliteration":"wa-aṭīʿūni","translation_bn":"ও তোমরা আমার আনুগত্য করো\"","root":"طوع","lemma":"أَطَاعَ","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":74200,"position":4,"text_uthmani":"١١٠","transliteration":"","translation_bn":"(১১০)","root":"—","lemma":"١١٠","grammar_bn":"মার্কার"}]'::jsonb, 'fa-ittaqū l-laha wa-aṭīʿūni', 'কাজেই তোমরা আল্লাহকে ভয় কর এবং আমার অনুসরণ কর।', 'So fear Allah and obey me."', 'কাজেই তোমরা আল্লাহকে ভয় কর এবং আমার অনুসরণ কর।', 'So fear Allah and obey me."', NULL, NULL, NULL, NULL, NULL, 'https://everyayah.com/data/Alafasy_128kbps/026110.mp3', now()),
  (26, 111, '', '[{"id":74386,"position":1,"text_uthmani":"۞ قَالُوٓا۟","transliteration":"qālū","translation_bn":"তারা বললো","root":"قول","lemma":"قَالَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":74387,"position":2,"text_uthmani":"أَنُؤْمِنُ","transliteration":"anu''minu","translation_bn":"\"কি আমরা ঈমান আনবো","root":"امن","lemma":"ءَامَنَ","grammar_bn":"প্রশ্নবোধক (Interrogative)"},{"id":74388,"position":3,"text_uthmani":"لَكَ","transliteration":"laka","translation_bn":"প্রতি তোমার","root":"—","lemma":"لَكَ","grammar_bn":"অব্যয় (Preposition)"},{"id":74389,"position":4,"text_uthmani":"وَٱتَّبَعَكَ","transliteration":"wa-ittabaʿaka","translation_bn":"অথচ তোমাকে অনুসরণ করেছে","root":"تبع","lemma":"ٱتَّبَعَ","grammar_bn":"অবস্থাবাচক (Circumstantial)"},{"id":74390,"position":5,"text_uthmani":"ٱلْأَرْذَلُونَ","transliteration":"l-ardhalūna","translation_bn":"নিকৃষ্টতম লোকেরা\"","root":"رذل","lemma":"أَرْذَل","grammar_bn":"শব্দ"},{"id":74391,"position":6,"text_uthmani":"١١١","transliteration":"","translation_bn":"(১১১)","root":"—","lemma":"١١١","grammar_bn":"মার্কার"}]'::jsonb, 'qālū anu''minu laka wa-ittabaʿaka l-ardhalūna', 'তারা বলল- ‘আমরা কি তোমার প্রতি বিশ্বাস করব যখন তোমার অনুসরণ করছে একেবারে নিম্নশ্রেণীর লোকেরা।’', 'They said, "Should we believe you while you are followed by the lowest [class of people]?"', 'তারা বলল- ‘আমরা কি তোমার প্রতি বিশ্বাস করব যখন তোমার অনুসরণ করছে একেবারে নিম্নশ্রেণীর লোকেরা।’', 'They said, "Should we believe you while you are followed by the lowest [class of people]?"', NULL, NULL, NULL, NULL, NULL, 'https://everyayah.com/data/Alafasy_128kbps/026111.mp3', now()),
  (26, 112, '', '[{"id":74737,"position":1,"text_uthmani":"قَالَ","transliteration":"qāla","translation_bn":"(নূহ) বললো","root":"قول","lemma":"قَالَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":74738,"position":2,"text_uthmani":"وَمَا","transliteration":"wamā","translation_bn":"\"আর নেই","root":"—","lemma":"مَا\r","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":74739,"position":3,"text_uthmani":"عِلْمِى","transliteration":"ʿil''mī","translation_bn":"আমার জানা","root":"علم","lemma":"عِلْم","grammar_bn":"বিশেষ্য (Noun)"},{"id":74740,"position":4,"text_uthmani":"بِمَا","transliteration":"bimā","translation_bn":"ঐ বিষয়ে যা","root":"—","lemma":"مَا\r","grammar_bn":"অব্যয় (Preposition)"},{"id":74741,"position":5,"text_uthmani":"كَانُوا۟","transliteration":"kānū","translation_bn":"তারা ছিলো","root":"كون","lemma":"كَانَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":74742,"position":6,"text_uthmani":"يَعْمَلُونَ","transliteration":"yaʿmalūna","translation_bn":"তারা কাজ করে","root":"عمل","lemma":"عَمِلَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":74743,"position":7,"text_uthmani":"١١٢","transliteration":"","translation_bn":"(১১২)","root":"—","lemma":"١١٢","grammar_bn":"মার্কার"}]'::jsonb, 'qāla wamā ʿil''mī bimā kānū yaʿmalūna', 'নূহ বলল- ‘তারা কী করত সেটা আমার জানা নেই।', 'He said, "And what is my knowledge of what they used to do?', 'নূহ বলল- ‘তারা কী করত সেটা আমার জানা নেই।', 'He said, "And what is my knowledge of what they used to do?', NULL, NULL, NULL, NULL, NULL, 'https://everyayah.com/data/Alafasy_128kbps/026112.mp3', now()),
