  (26, 124, '', '[{"id":76976,"position":1,"text_uthmani":"إِذْ","transliteration":"idh","translation_bn":"(স্মরণ করো) যখন","root":"—","lemma":"إِذ\r","grammar_bn":"কালবাচক (Time)"},{"id":76977,"position":2,"text_uthmani":"قَالَ","transliteration":"qāla","translation_bn":"বলেছিলো","root":"قول","lemma":"قَالَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":76978,"position":3,"text_uthmani":"لَهُمْ","transliteration":"lahum","translation_bn":"উদ্দেশ্যে তাদের","root":"—","lemma":"لَهُمْ","grammar_bn":"অব্যয় (Preposition)"},{"id":76979,"position":4,"text_uthmani":"أَخُوهُمْ","transliteration":"akhūhum","translation_bn":"ভাই তাদের","root":"اخو","lemma":"أَخ","grammar_bn":"বিশেষ্য (Noun)"},{"id":76980,"position":5,"text_uthmani":"هُودٌ","transliteration":"hūdun","translation_bn":"হূদ","root":"هود","lemma":"هُود","grammar_bn":"নামবাচক বিশেষ্য (Proper Noun)"},{"id":76981,"position":6,"text_uthmani":"أَلَا","transliteration":"alā","translation_bn":"\"কি না","root":"—","lemma":"لَا\r","grammar_bn":"প্রশ্নবোধক (Interrogative)"},{"id":76982,"position":7,"text_uthmani":"تَتَّقُونَ","transliteration":"tattaqūna","translation_bn":"তোমরা ভয় করবে","root":"وقي","lemma":"ٱتَّقَىٰ","grammar_bn":"ক্রিয়া (Verb)"},{"id":76983,"position":8,"text_uthmani":"١٢٤","transliteration":"","translation_bn":"(১২৪)","root":"—","lemma":"١٢٤","grammar_bn":"মার্কার"}]'::jsonb, 'idh qāla lahum akhūhum hūdun alā tattaqūna', 'যখন তাদের ভাই হূদ তাদেরকে বলল- ‘তোমরা কি (আল্লাহকে) ভয় করবে না?', 'When their brother Hud said to them, "Will you not fear Allah?', 'যখন তাদের ভাই হূদ তাদেরকে বলল- ‘তোমরা কি (আল্লাহকে) ভয় করবে না?', 'When their brother Hud said to them, "Will you not fear Allah?', NULL, NULL, NULL, NULL, NULL, 'https://everyayah.com/data/Alafasy_128kbps/026124.mp3', now()),
  (26, 125, '', '[{"id":77196,"position":1,"text_uthmani":"إِنِّى","transliteration":"innī","translation_bn":"নিশ্চয়ই আমি","root":"—","lemma":"إِنّ","grammar_bn":"অভিঘাত পদ (Accusative)"},{"id":77197,"position":2,"text_uthmani":"لَكُمْ","transliteration":"lakum","translation_bn":"জন্যে তোমাদের","root":"—","lemma":"لَكُمْ","grammar_bn":"অব্যয় (Preposition)"},{"id":77198,"position":3,"text_uthmani":"رَسُولٌ","transliteration":"rasūlun","translation_bn":"একজন রাসূল","root":"رسل","lemma":"رَسُول","grammar_bn":"বিশেষ্য (Noun)"},{"id":77199,"position":4,"text_uthmani":"أَمِينٌۭ","transliteration":"amīnun","translation_bn":"বিশ্বস্ত","root":"امن","lemma":"أَمِين","grammar_bn":"বিশেষণ (Adjective)"},{"id":77200,"position":5,"text_uthmani":"١٢٥","transliteration":"","translation_bn":"(১২৫)","root":"—","lemma":"١٢٥","grammar_bn":"মার্কার"}]'::jsonb, 'innī lakum rasūlun amīnun', 'আমি তোমাদের জন্য (প্রেরিত) এক বিশ্বস্ত রসুল।', 'Indeed, I am to you a trustworthy messenger.', 'আমি তোমাদের জন্য (প্রেরিত) এক বিশ্বস্ত রসুল।', 'Indeed, I am to you a trustworthy messenger.', NULL, NULL, NULL, NULL, NULL, 'https://everyayah.com/data/Alafasy_128kbps/026125.mp3', now()),
  (26, 126, '', '[{"id":77291,"position":1,"text_uthmani":"فَٱتَّقُوا۟","transliteration":"fa-ittaqū","translation_bn":"অতএব তোমরা ভয় করো","root":"وقي","lemma":"ٱتَّقَىٰ","grammar_bn":"শব্দ"},{"id":77292,"position":2,"text_uthmani":"ٱللَّهَ","transliteration":"l-laha","translation_bn":"আল্লাহকে","root":"اله","lemma":"ٱللَّه","grammar_bn":"নামবাচক বিশেষ্য (Proper Noun)"},{"id":77293,"position":3,"text_uthmani":"وَأَطِيعُونِ","transliteration":"wa-aṭīʿūni","translation_bn":"ও তোমরা আমার আনুগত্য করো","root":"طوع","lemma":"أَطَاعَ","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":77294,"position":4,"text_uthmani":"١٢٦","transliteration":"","translation_bn":"(১২৬)","root":"—","lemma":"١٢٦","grammar_bn":"মার্কার"}]'::jsonb, 'fa-ittaqū l-laha wa-aṭīʿūni', 'কাজেই তোমরা আল্লাহকে ভয় কর এবং আমাকে মান্য কর।', 'So fear Allah and obey me.', 'কাজেই তোমরা আল্লাহকে ভয় কর এবং আমাকে মান্য কর।', 'So fear Allah and obey me.', NULL, NULL, NULL, NULL, NULL, 'https://everyayah.com/data/Alafasy_128kbps/026126.mp3', now()),
  (26, 127, '', '[{"id":77556,"position":1,"text_uthmani":"وَمَآ","transliteration":"wamā","translation_bn":"আর না","root":"—","lemma":"مَا\r","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":77557,"position":2,"text_uthmani":"أَسْـَٔلُكُمْ","transliteration":"asalukum","translation_bn":"তোমাদের (নিকট) আমি চাচ্ছি","root":"سال","lemma":"سَأَلَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":77558,"position":3,"text_uthmani":"عَلَيْهِ","transliteration":"ʿalayhi","translation_bn":"জন্যে এর","root":"—","lemma":"عَلَىٰ\r","grammar_bn":"অব্যয় (Preposition)"},{"id":77559,"position":4,"text_uthmani":"مِنْ","transliteration":"min","translation_bn":"কোনো","root":"—","lemma":"مِن\r","grammar_bn":"অব্যয় (Preposition)"},{"id":77560,"position":5,"text_uthmani":"أَجْرٍ ۖ","transliteration":"ajrin","translation_bn":"প্রতিদান","root":"اجر","lemma":"أَجْر","grammar_bn":"বিশেষ্য (Noun)"},{"id":77562,"position":6,"text_uthmani":"إِنْ","transliteration":"in","translation_bn":"নেই","root":"—","lemma":"إِن\r","grammar_bn":"না-বোধক (Negative)"},{"id":77563,"position":7,"text_uthmani":"أَجْرِىَ","transliteration":"ajriya","translation_bn":"আমার প্রতিদান (অন্য কারো নিকট)","root":"اجر","lemma":"أَجْر","grammar_bn":"বিশেষ্য (Noun)"},{"id":77564,"position":8,"text_uthmani":"إِلَّا","transliteration":"illā","translation_bn":"ছাড়া","root":"—","lemma":"إِلَّا\r","grammar_bn":"সীমাবদ্ধতা (Restriction)"},{"id":77565,"position":9,"text_uthmani":"عَلَىٰ","transliteration":"ʿalā","translation_bn":"নিকট","root":"—","lemma":"عَلَىٰ\r","grammar_bn":"অব্যয় (Preposition)"},{"id":77566,"position":10,"text_uthmani":"رَبِّ","transliteration":"rabbi","translation_bn":"রবের","root":"ربب","lemma":"رَبّ","grammar_bn":"বিশেষ্য (Noun)"},{"id":77567,"position":11,"text_uthmani":"ٱلْعَـٰلَمِينَ","transliteration":"l-ʿālamīna","translation_bn":"বিশ্বজগতের","root":"علم","lemma":"عَٰلَمِين","grammar_bn":"শব্দ"},{"id":77568,"position":12,"text_uthmani":"١٢٧","transliteration":"","translation_bn":"(১২৭)","root":"—","lemma":"١٢٧","grammar_bn":"মার্কার"}]'::jsonb, 'wamā asalukum ʿalayhi min ajrin in ajriya illā ʿalā rabbi l-ʿālamīna', 'আর এ জন্য আমি তোমাদের কাছে কোন প্রতিদান চাই না, আমার প্রতিদান আছে কেবল বিশ্বজগতের প্রতিপালকের নিকট।', 'And I do not ask you for it any payment. My payment is only from the Lord of the worlds.', 'আর এ জন্য আমি তোমাদের কাছে কোন প্রতিদান চাই না, আমার প্রতিদান আছে কেবল বিশ্বজগতের প্রতিপালকের নিকট।', 'And I do not ask you for it any payment. My payment is only from the Lord of the worlds.', NULL, NULL, NULL, NULL, NULL, 'https://everyayah.com/data/Alafasy_128kbps/026127.mp3', now()),
  (26, 128, '', '[{"id":77683,"position":1,"text_uthmani":"أَتَبْنُونَ","transliteration":"atabnūna","translation_bn":"কি তোমরা নির্মাণ করছো","root":"بني","lemma":"بَنَىٰ","grammar_bn":"প্রশ্নবোধক (Interrogative)"},{"id":77684,"position":2,"text_uthmani":"بِكُلِّ","transliteration":"bikulli","translation_bn":"স্হানে প্রত্যক","root":"كلل","lemma":"كُلّ","grammar_bn":"অব্যয় (Preposition)"},{"id":77685,"position":3,"text_uthmani":"رِيعٍ","transliteration":"rīʿin","translation_bn":"উঁচু","root":"ريع","lemma":"رِيع","grammar_bn":"বিশেষ্য (Noun)"},{"id":77686,"position":4,"text_uthmani":"ءَايَةًۭ","transliteration":"āyatan","translation_bn":"(স্মৃতিচিহ্ন) নিদর্শন","root":"ايي","lemma":"ءَايَة","grammar_bn":"বিশেষ্য (Noun)"},{"id":77687,"position":5,"text_uthmani":"تَعْبَثُونَ","transliteration":"taʿbathūna","translation_bn":"তোমরা নিরর্থক কাজ করছো","root":"عبث","lemma":"تَعْبَثُ","grammar_bn":"ক্রিয়া (Verb)"},{"id":77688,"position":6,"text_uthmani":"١٢٨","transliteration":"","translation_bn":"(১২৮)","root":"—","lemma":"١٢٨","grammar_bn":"মার্কার"}]'::jsonb, 'atabnūna bikulli rīʿin āyatan taʿbathūna', 'তোমরা কি প্রতিটি উচ্চস্থানে অনর্থক স্মৃতিস্তম্ভ নির্মাণ করছ?', 'Do you construct on every elevation a sign, amusing yourselves,', 'তোমরা কি প্রতিটি উচ্চস্থানে অনর্থক স্মৃতিস্তম্ভ নির্মাণ করছ?', 'Do you construct on every elevation a sign, amusing yourselves,', NULL, NULL, NULL, NULL, NULL, 'https://everyayah.com/data/Alafasy_128kbps/026128.mp3', now()),
  (26, 129, '', '[{"id":77828,"position":1,"text_uthmani":"وَتَتَّخِذُونَ","transliteration":"watattakhidhūna","translation_bn":"ও তোমরা তৈরী করছো","root":"اخذ","lemma":"ٱتَّخَذَ","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":77829,"position":2,"text_uthmani":"مَصَانِعَ","transliteration":"maṣāniʿa","translation_bn":"প্রাসাদ","root":"صنع","lemma":"مَصَانِع","grammar_bn":"বিশেষ্য (Noun)"},{"id":77830,"position":3,"text_uthmani":"لَعَلَّكُمْ","transliteration":"laʿallakum","translation_bn":"যেন তোমরা","root":"—","lemma":"لَعَلّ","grammar_bn":"অভিঘাত পদ (Accusative)"},{"id":77831,"position":4,"text_uthmani":"تَخْلُدُونَ","transliteration":"takhludūna","translation_bn":"চিরস্থায়ী হবে","root":"خلد","lemma":"يَخْلُدْ","grammar_bn":"ক্রিয়া (Verb)"},{"id":77832,"position":5,"text_uthmani":"١٢٩","transliteration":"","translation_bn":"(১২৯)","root":"—","lemma":"١٢٩","grammar_bn":"মার্কার"}]'::jsonb, 'watattakhidhūna maṣāniʿa laʿallakum takhludūna', 'আর বড় বড় প্রাসাদ নির্মাণ করছ. যেন তোমরা চিরদিন থাকবে?', 'And take for yourselves palaces and fortresses that you might abide eternally?', 'আর বড় বড় প্রাসাদ নির্মাণ করছ. যেন তোমরা চিরদিন থাকবে?', 'And take for yourselves palaces and fortresses that you might abide eternally?', NULL, NULL, NULL, NULL, NULL, 'https://everyayah.com/data/Alafasy_128kbps/026129.mp3', now()),
  (26, 130, '', '[{"id":78024,"position":1,"text_uthmani":"وَإِذَا","transliteration":"wa-idhā","translation_bn":"এবং যখন","root":"—","lemma":"إِذَا\r","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":78025,"position":2,"text_uthmani":"بَطَشْتُم","transliteration":"baṭashtum","translation_bn":"তোমরা আঘাত করো","root":"بطش","lemma":"بَطَشْ","grammar_bn":"ক্রিয়া (Verb)"},{"id":78026,"position":3,"text_uthmani":"بَطَشْتُمْ","transliteration":"baṭashtum","translation_bn":"তোমরা আঘাত করো","root":"بطش","lemma":"بَطَشْ","grammar_bn":"ক্রিয়া (Verb)"},{"id":78027,"position":4,"text_uthmani":"جَبَّارِينَ","transliteration":"jabbārīna","translation_bn":"স্বেচ্ছাচারী হয়ে","root":"جبر","lemma":"جَبَّار","grammar_bn":"বিশেষ্য (Noun)"},{"id":78028,"position":5,"text_uthmani":"١٣٠","transliteration":"","translation_bn":"(১৩০)","root":"—","lemma":"١٣٠","grammar_bn":"মার্কার"}]'::jsonb, 'wa-idhā baṭashtum baṭashtum jabbārīna', 'আর যখন তোমরা (দুর্বল শ্রেণীর লোকদের উপর) আঘাত হান, তখন আঘাত হান নিষ্ঠুর মালিকের মত।', 'And when you strike, you strike as tyrants.', 'আর যখন তোমরা (দুর্বল শ্রেণীর লোকদের উপর) আঘাত হান, তখন আঘাত হান নিষ্ঠুর মালিকের মত।', 'And when you strike, you strike as tyrants.', NULL, NULL, NULL, NULL, NULL, 'https://everyayah.com/data/Alafasy_128kbps/026130.mp3', now()),
