  (26, 132, '', '[{"id":78214,"position":1,"text_uthmani":"وَٱتَّقُوا۟","transliteration":"wa-ittaqū","translation_bn":"এবং তোমরা ভয় করো","root":"وقي","lemma":"ٱتَّقَىٰ","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":78215,"position":2,"text_uthmani":"ٱلَّذِىٓ","transliteration":"alladhī","translation_bn":"(তাকে) যিনি","root":"—","lemma":"ٱلَّذِى","grammar_bn":"সাপেক্ষ সর্বনাম (Relative)"},{"id":78216,"position":3,"text_uthmani":"أَمَدَّكُم","transliteration":"amaddakum","translation_bn":"সাহায্য করেছেন তোমাদেরকে","root":"مدد","lemma":"أَمَدَّ","grammar_bn":"ক্রিয়া (Verb)"},{"id":78217,"position":4,"text_uthmani":"بِمَا","transliteration":"bimā","translation_bn":"যা কিছু(তা)","root":"—","lemma":"مَا\r","grammar_bn":"অব্যয় (Preposition)"},{"id":78218,"position":5,"text_uthmani":"تَعْلَمُونَ","transliteration":"taʿlamūna","translation_bn":"তোমরা জানো","root":"علم","lemma":"عَلِمَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":78219,"position":6,"text_uthmani":"١٣٢","transliteration":"","translation_bn":"(১৩২)","root":"—","lemma":"١٣٢","grammar_bn":"মার্কার"}]'::jsonb, 'wa-ittaqū alladhī amaddakum bimā taʿlamūna', 'ভয় কর তাঁকে যিনি তোমাদেরকে যাবতীয় বস্তু দান করেছেন যা তোমাদের জানা আছে।', 'And fear He who provided you with that which you know,', 'ভয় কর তাঁকে যিনি তোমাদেরকে যাবতীয় বস্তু দান করেছেন যা তোমাদের জানা আছে।', 'And fear He who provided you with that which you know,', NULL, NULL, NULL, NULL, NULL, 'https://everyayah.com/data/Alafasy_128kbps/026132.mp3', now()),
  (26, 133, '', '[{"id":78280,"position":1,"text_uthmani":"أَمَدَّكُم","transliteration":"amaddakum","translation_bn":"সাহায্য করেছেন তোমাদেরকে","root":"مدد","lemma":"أَمَدَّ","grammar_bn":"ক্রিয়া (Verb)"},{"id":78281,"position":2,"text_uthmani":"بِأَنْعَـٰمٍۢ","transliteration":"bi-anʿāmin","translation_bn":"দিয়ে গবাদিপশু","root":"نعم","lemma":"نَّعَم","grammar_bn":"অব্যয় (Preposition)"},{"id":78282,"position":3,"text_uthmani":"وَبَنِينَ","transliteration":"wabanīna","translation_bn":"ও সন্তান সন্তুতি","root":"بني","lemma":"بُنَىّ","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":78283,"position":4,"text_uthmani":"١٣٣","transliteration":"","translation_bn":"(১৩৩)","root":"—","lemma":"١٣٣","grammar_bn":"মার্কার"}]'::jsonb, 'amaddakum bi-anʿāmin wabanīna', 'যিনি তোমাদেরকে দান করেছেন গবাদি পশু ও সন্তান-সন্তুতি।', 'Provided you with grazing livestock and children', 'যিনি তোমাদেরকে দান করেছেন গবাদি পশু ও সন্তান-সন্তুতি।', 'Provided you with grazing livestock and children', NULL, NULL, NULL, NULL, NULL, 'https://everyayah.com/data/Alafasy_128kbps/026133.mp3', now()),
  (26, 134, '', '[{"id":78391,"position":1,"text_uthmani":"وَجَنَّـٰتٍۢ","transliteration":"wajannātin","translation_bn":"এবং বাগান","root":"جنن","lemma":"جَنَّة","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":78392,"position":2,"text_uthmani":"وَعُيُونٍ","transliteration":"waʿuyūnin","translation_bn":"ও ঝর্ণাসমূহ (দিয়ে)","root":"عين","lemma":"عَيْن","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":78393,"position":3,"text_uthmani":"١٣٤","transliteration":"","translation_bn":"(১৩৪)","root":"—","lemma":"١٣٤","grammar_bn":"মার্কার"}]'::jsonb, 'wajannātin waʿuyūnin', 'আর উদ্যানরাজি ও ঝর্ণাসমূহ।', 'And gardens and springs.', 'আর উদ্যানরাজি ও ঝর্ণাসমূহ।', 'And gardens and springs.', NULL, NULL, NULL, NULL, NULL, 'https://everyayah.com/data/Alafasy_128kbps/026134.mp3', now()),
