  (26, 139, '', '[{"id":78994,"position":1,"text_uthmani":"فَكَذَّبُوهُ","transliteration":"fakadhabūhu","translation_bn":"তারা তাকে মিথ্যা সাব্যস্ত করলো","root":"كذب","lemma":"كَذَّبَ","grammar_bn":"শব্দ"},{"id":78995,"position":2,"text_uthmani":"فَأَهْلَكْنَـٰهُمْ ۗ","transliteration":"fa-ahlaknāhum","translation_bn":"তখন আমরা ধ্বংস করলাম তাদেরকে","root":"هلك","lemma":"أَهْلَكَ","grammar_bn":"শব্দ"},{"id":78997,"position":3,"text_uthmani":"إِنَّ","transliteration":"inna","translation_bn":"নিশ্চয়ই","root":"—","lemma":"إِنّ","grammar_bn":"অভিঘাত পদ (Accusative)"},{"id":78998,"position":4,"text_uthmani":"فِى","transliteration":"fī","translation_bn":"মধ্যে (আছে)","root":"—","lemma":"فِى\r","grammar_bn":"অব্যয় (Preposition)"},{"id":78999,"position":5,"text_uthmani":"ذَٰلِكَ","transliteration":"dhālika","translation_bn":"এর","root":"—","lemma":"ذَٰلِك","grammar_bn":"নির্দেশক সর্বনাম (Demonstrative)"},{"id":79000,"position":6,"text_uthmani":"لَـَٔايَةًۭ ۖ","transliteration":"laāyatan","translation_bn":"অবশ্যই নিদর্শন","root":"ايي","lemma":"ءَايَة","grammar_bn":"দৃঢ়তাবোধক (Emphatic)"},{"id":79002,"position":7,"text_uthmani":"وَمَا","transliteration":"wamā","translation_bn":"কিন্তু না","root":"—","lemma":"مَا\r","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":79003,"position":8,"text_uthmani":"كَانَ","transliteration":"kāna","translation_bn":"ছিলো","root":"كون","lemma":"كَانَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":79004,"position":9,"text_uthmani":"أَكْثَرُهُم","transliteration":"aktharuhum","translation_bn":"অধিকাংশ তাদের","root":"كثر","lemma":"أَكْثَر","grammar_bn":"বিশেষ্য (Noun)"},{"id":79005,"position":10,"text_uthmani":"مُّؤْمِنِينَ","transliteration":"mu''minīna","translation_bn":"মু''মিন","root":"امن","lemma":"مُؤْمِن","grammar_bn":"বিশেষ্য (Noun)"},{"id":79006,"position":11,"text_uthmani":"١٣٩","transliteration":"","translation_bn":"(১৩৯)","root":"—","lemma":"١٣٩","grammar_bn":"মার্কার"}]'::jsonb, 'fakadhabūhu fa-ahlaknāhum inna fī dhālika laāyatan wamā kāna aktharuhum mu''minīna', 'অতঃপর তারা তাকে মিথ্যে ব’লে প্রত্যাখ্যান করল। তখন আমি তাদেরকে ধ্বংস করে দিলাম। অবশ্যই এতে নিদর্শন রয়েছে, কিন্তু তাদের অধিকাংশই বিশ্বাস করে না।', 'And they denied him, so We destroyed them. Indeed in that is a sign, but most of them were not to be believers.', 'অতঃপর তারা তাকে মিথ্যে ব’লে প্রত্যাখ্যান করল। তখন আমি তাদেরকে ধ্বংস করে দিলাম। অবশ্যই এতে নিদর্শন রয়েছে, কিন্তু তাদের অধিকাংশই বিশ্বাস করে না।', 'And they denied him, so We destroyed them. Indeed in that is a sign, but most of them were not to be believers.', NULL, NULL, NULL, NULL, NULL, 'https://everyayah.com/data/Alafasy_128kbps/026139.mp3', now()),
  (26, 140, '', '[{"id":79082,"position":1,"text_uthmani":"وَإِنَّ","transliteration":"wa-inna","translation_bn":"আর নিশ্চয়ই","root":"—","lemma":"إِنّ","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":79083,"position":2,"text_uthmani":"رَبَّكَ","transliteration":"rabbaka","translation_bn":"তোমার রব","root":"ربب","lemma":"رَبّ","grammar_bn":"বিশেষ্য (Noun)"},{"id":79084,"position":3,"text_uthmani":"لَهُوَ","transliteration":"lahuwa","translation_bn":"অবশ্যই তিনি","root":"—","lemma":"لَهُوَ","grammar_bn":"দৃঢ়তাবোধক (Emphatic)"},{"id":79085,"position":4,"text_uthmani":"ٱلْعَزِيزُ","transliteration":"l-ʿazīzu","translation_bn":"পরাক্রমশালী","root":"عزز","lemma":"عَزِيز","grammar_bn":"শব্দ"},{"id":79086,"position":5,"text_uthmani":"ٱلرَّحِيمُ","transliteration":"l-raḥīmu","translation_bn":"পরম দয়ালু","root":"رحم","lemma":"رَّحِيم","grammar_bn":"শব্দ"},{"id":79087,"position":6,"text_uthmani":"١٤٠","transliteration":"","translation_bn":"(১৪০)","root":"—","lemma":"١٤٠","grammar_bn":"মার্কার"}]'::jsonb, 'wa-inna rabbaka lahuwa l-ʿazīzu l-raḥīmu', 'এবং তোমার প্রতিপালক, তিনি মহা প্রতাপশালী, বড়ই দয়ালু।', 'And indeed, your Lord - He is the Exalted in Might, the Merciful.', 'এবং তোমার প্রতিপালক, তিনি মহা প্রতাপশালী, বড়ই দয়ালু।', 'And indeed, your Lord - He is the Exalted in Might, the Merciful.', NULL, NULL, NULL, NULL, NULL, 'https://everyayah.com/data/Alafasy_128kbps/026140.mp3', now()),
  (26, 141, '', '[{"id":79189,"position":1,"text_uthmani":"كَذَّبَتْ","transliteration":"kadhabat","translation_bn":"মিথ্যারোপ করেছিলো","root":"كذب","lemma":"كَذَّبَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":79190,"position":2,"text_uthmani":"ثَمُودُ","transliteration":"thamūdu","translation_bn":"সামূদ জাতি","root":"—","lemma":"ثَمُود","grammar_bn":"নামবাচক বিশেষ্য (Proper Noun)"},{"id":79191,"position":3,"text_uthmani":"ٱلْمُرْسَلِينَ","transliteration":"l-mur''salīna","translation_bn":"রাসূলদেরকে","root":"رسل","lemma":"مُّرْسَل","grammar_bn":"শব্দ"},{"id":79192,"position":4,"text_uthmani":"١٤١","transliteration":"","translation_bn":"(১৪১)","root":"—","lemma":"١٤١","grammar_bn":"মার্কার"}]'::jsonb, 'kadhabat thamūdu l-mur''salīna', 'সামূদ জাতি রসূলগণকে প্রত্যাখ্যান করেছিল।', 'Thamud denied the messengers', 'সামূদ জাতি রসূলগণকে প্রত্যাখ্যান করেছিল।', 'Thamud denied the messengers', NULL, NULL, NULL, NULL, NULL, 'https://everyayah.com/data/Alafasy_128kbps/026141.mp3', now()),
  (26, 142, '', '[{"id":79359,"position":1,"text_uthmani":"إِذْ","transliteration":"idh","translation_bn":"(স্মরণ করো) যখন","root":"—","lemma":"إِذ\r","grammar_bn":"কালবাচক (Time)"},{"id":79360,"position":2,"text_uthmani":"قَالَ","transliteration":"qāla","translation_bn":"বলেছিলো","root":"قول","lemma":"قَالَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":79361,"position":3,"text_uthmani":"لَهُمْ","transliteration":"lahum","translation_bn":"উদ্দেশ্যে তাদের","root":"—","lemma":"لَهُمْ","grammar_bn":"অব্যয় (Preposition)"},{"id":79362,"position":4,"text_uthmani":"أَخُوهُمْ","transliteration":"akhūhum","translation_bn":"ভাই তাদের","root":"اخو","lemma":"أَخ","grammar_bn":"বিশেষ্য (Noun)"},{"id":79363,"position":5,"text_uthmani":"صَـٰلِحٌ","transliteration":"ṣāliḥun","translation_bn":"সালেহ","root":"صلح","lemma":"صَٰلِح2","grammar_bn":"নামবাচক বিশেষ্য (Proper Noun)"},{"id":79364,"position":6,"text_uthmani":"أَلَا","transliteration":"alā","translation_bn":"\"কি না","root":"—","lemma":"لَا\r","grammar_bn":"প্রশ্নবোধক (Interrogative)"},{"id":79365,"position":7,"text_uthmani":"تَتَّقُونَ","transliteration":"tattaqūna","translation_bn":"তোমরা করবে ভয়","root":"وقي","lemma":"ٱتَّقَىٰ","grammar_bn":"ক্রিয়া (Verb)"},{"id":79366,"position":8,"text_uthmani":"١٤٢","transliteration":"","translation_bn":"(১৪২)","root":"—","lemma":"١٤٢","grammar_bn":"মার্কার"}]'::jsonb, 'idh qāla lahum akhūhum ṣāliḥun alā tattaqūna', 'যখন তাদের ভাই সালিহ তাদেরকে বলেছিল- তোমরা কি (আল্লাহকে) ভয় করবে না?', 'When their brother Salih said to them, "Will you not fear Allah?', 'যখন তাদের ভাই সালিহ তাদেরকে বলেছিল- তোমরা কি (আল্লাহকে) ভয় করবে না?', 'When their brother Salih said to them, "Will you not fear Allah?', NULL, NULL, NULL, NULL, NULL, 'https://everyayah.com/data/Alafasy_128kbps/026142.mp3', now()),
  (26, 143, '', '[{"id":79454,"position":1,"text_uthmani":"إِنِّى","transliteration":"innī","translation_bn":"নিশ্চয়ই আমি","root":"—","lemma":"إِنّ","grammar_bn":"অভিঘাত পদ (Accusative)"},{"id":79455,"position":2,"text_uthmani":"لَكُمْ","transliteration":"lakum","translation_bn":"জন্যে তোমাদের","root":"—","lemma":"لَكُمْ","grammar_bn":"অব্যয় (Preposition)"},{"id":79456,"position":3,"text_uthmani":"رَسُولٌ","transliteration":"rasūlun","translation_bn":"রাসূল","root":"رسل","lemma":"رَسُول","grammar_bn":"বিশেষ্য (Noun)"},{"id":79457,"position":4,"text_uthmani":"أَمِينٌۭ","transliteration":"amīnun","translation_bn":"বিশ্বস্ত","root":"امن","lemma":"أَمِين","grammar_bn":"বিশেষণ (Adjective)"},{"id":79458,"position":5,"text_uthmani":"١٤٣","transliteration":"","translation_bn":"(১৪৩)","root":"—","lemma":"١٤٣","grammar_bn":"মার্কার"}]'::jsonb, 'innī lakum rasūlun amīnun', 'আমি তোমাদের জন্য (প্রেরিত) বিশ্বস্ত রসূল।', 'Indeed, I am to you a trustworthy messenger.', 'আমি তোমাদের জন্য (প্রেরিত) বিশ্বস্ত রসূল।', 'Indeed, I am to you a trustworthy messenger.', NULL, NULL, NULL, NULL, NULL, 'https://everyayah.com/data/Alafasy_128kbps/026143.mp3', now()),
  (26, 144, '', '[{"id":79702,"position":1,"text_uthmani":"فَٱتَّقُوا۟","transliteration":"fa-ittaqū","translation_bn":"অতএব তোমরা ভয় করো","root":"وقي","lemma":"ٱتَّقَىٰ","grammar_bn":"শব্দ"},{"id":79703,"position":2,"text_uthmani":"ٱللَّهَ","transliteration":"l-laha","translation_bn":"আল্লাহকে","root":"اله","lemma":"ٱللَّه","grammar_bn":"নামবাচক বিশেষ্য (Proper Noun)"},{"id":79704,"position":3,"text_uthmani":"وَأَطِيعُونِ","transliteration":"wa-aṭīʿūni","translation_bn":"আর তোমরা আমার আনুগত্য করো","root":"طوع","lemma":"أَطَاعَ","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":79705,"position":4,"text_uthmani":"١٤٤","transliteration":"","translation_bn":"(১৪৪)","root":"—","lemma":"١٤٤","grammar_bn":"মার্কার"}]'::jsonb, 'fa-ittaqū l-laha wa-aṭīʿūni', 'কাজেই তোমরা আল্লাহকে ভয় কর ও আমাকে মান্য কর।', 'So fear Allah and obey me.', 'কাজেই তোমরা আল্লাহকে ভয় কর ও আমাকে মান্য কর।', 'So fear Allah and obey me.', NULL, NULL, NULL, NULL, NULL, 'https://everyayah.com/data/Alafasy_128kbps/026144.mp3', now()),
