  (26, 153, '', '[{"id":80809,"position":1,"text_uthmani":"قَالُوٓا۟","transliteration":"qālū","translation_bn":"তারা বললো","root":"قول","lemma":"قَالَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":80810,"position":2,"text_uthmani":"إِنَّمَآ","transliteration":"innamā","translation_bn":"\"মূলতঃ","root":"—","lemma":"إِنّ","grammar_bn":"অভিঘাত পদ (Accusative)"},{"id":80811,"position":3,"text_uthmani":"أَنتَ","transliteration":"anta","translation_bn":"তুমি","root":"—","lemma":"أَنتَ","grammar_bn":"সর্বনাম (Pronoun)"},{"id":80812,"position":4,"text_uthmani":"مِنَ","transliteration":"mina","translation_bn":"অন্তর্ভুক্ত","root":"—","lemma":"مِن\r","grammar_bn":"অব্যয় (Preposition)"},{"id":80813,"position":5,"text_uthmani":"ٱلْمُسَحَّرِينَ","transliteration":"l-musaḥarīna","translation_bn":"জাদুগ্রস্তদের","root":"سحر","lemma":"مُسَحَّرِين","grammar_bn":"শব্দ"},{"id":80814,"position":6,"text_uthmani":"١٥٣","transliteration":"","translation_bn":"(১৫৩)","root":"—","lemma":"١٥٣","grammar_bn":"মার্কার"}]'::jsonb, 'qālū innamā anta mina l-musaḥarīna', 'তারা বলল- ‘তুমি তো কেবল যাদুগ্রস্তদের একজন।', 'They said, "You are only of those affected by magic.', 'তারা বলল- ‘তুমি তো কেবল যাদুগ্রস্তদের একজন।', 'They said, "You are only of those affected by magic.', NULL, NULL, NULL, NULL, NULL, 'https://everyayah.com/data/Alafasy_128kbps/026153.mp3', now()),
  (26, 154, '', '[{"id":80919,"position":1,"text_uthmani":"مَآ","transliteration":"mā","translation_bn":"নও","root":"—","lemma":"مَا\r","grammar_bn":"না-বোধক (Negative)"},{"id":80920,"position":2,"text_uthmani":"أَنتَ","transliteration":"anta","translation_bn":"তুমি","root":"—","lemma":"أَنتَ","grammar_bn":"সর্বনাম (Pronoun)"},{"id":80921,"position":3,"text_uthmani":"إِلَّا","transliteration":"illā","translation_bn":"এ ছাড়া","root":"—","lemma":"إِلَّا\r","grammar_bn":"সীমাবদ্ধতা (Restriction)"},{"id":80922,"position":4,"text_uthmani":"بَشَرٌۭ","transliteration":"basharun","translation_bn":"একজন মানুষ","root":"بشر","lemma":"بَشَر","grammar_bn":"বিশেষ্য (Noun)"},{"id":80923,"position":5,"text_uthmani":"مِّثْلُنَا","transliteration":"mith''lunā","translation_bn":"মতো আমাদেরই","root":"مثل","lemma":"مِثْل","grammar_bn":"বিশেষ্য (Noun)"},{"id":80924,"position":6,"text_uthmani":"فَأْتِ","transliteration":"fati","translation_bn":"কাজেই আসো","root":"اتي","lemma":"أَتَى","grammar_bn":"শব্দ"},{"id":80925,"position":7,"text_uthmani":"بِـَٔايَةٍ","transliteration":"biāyatin","translation_bn":"নিয়ে একটি নিদর্শন","root":"ايي","lemma":"ءَايَة","grammar_bn":"অব্যয় (Preposition)"},{"id":80926,"position":8,"text_uthmani":"إِن","transliteration":"in","translation_bn":"যদি","root":"—","lemma":"إِن\r","grammar_bn":"শর্তবাচক (Conditional)"},{"id":80927,"position":9,"text_uthmani":"كُنتَ","transliteration":"kunta","translation_bn":"তুমি হও","root":"كون","lemma":"كَانَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":80928,"position":10,"text_uthmani":"مِنَ","transliteration":"mina","translation_bn":"অন্তর্ভুক্ত","root":"—","lemma":"مِن\r","grammar_bn":"অব্যয় (Preposition)"},{"id":80929,"position":11,"text_uthmani":"ٱلصَّـٰدِقِينَ","transliteration":"l-ṣādiqīna","translation_bn":"সত্যবাদীদের\"","root":"صدق","lemma":"صَادِق","grammar_bn":"শব্দ"},{"id":80930,"position":12,"text_uthmani":"١٥٤","transliteration":"","translation_bn":"(১৫৪)","root":"—","lemma":"١٥٤","grammar_bn":"মার্কার"}]'::jsonb, 'mā anta illā basharun mith''lunā fati biāyatin in kunta mina l-ṣādiqīna', 'তুমি আমাদের মত মানুষ ছাড়া আর কিছুই না। কাজেই তুমি সত্যবাদী হলে একটা নিদর্শন হাজির কর।', 'You are but a man like ourselves, so bring a sign, if you should be of the truthful."', 'তুমি আমাদের মত মানুষ ছাড়া আর কিছুই না। কাজেই তুমি সত্যবাদী হলে একটা নিদর্শন হাজির কর।', 'You are but a man like ourselves, so bring a sign, if you should be of the truthful."', NULL, NULL, NULL, NULL, NULL, 'https://everyayah.com/data/Alafasy_128kbps/026154.mp3', now()),
  (26, 155, '', '[{"id":81119,"position":1,"text_uthmani":"قَالَ","transliteration":"qāla","translation_bn":"(সালেহ) বললো","root":"قول","lemma":"قَالَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":81120,"position":2,"text_uthmani":"هَـٰذِهِۦ","transliteration":"hādhihi","translation_bn":"\"এই","root":"—","lemma":"هَٰذَا","grammar_bn":"নির্দেশক সর্বনাম (Demonstrative)"},{"id":81121,"position":3,"text_uthmani":"نَاقَةٌۭ","transliteration":"nāqatun","translation_bn":"একটি মাদি উট","root":"نوق","lemma":"نَاقَة","grammar_bn":"বিশেষ্য (Noun)"},{"id":81122,"position":4,"text_uthmani":"لَّهَا","transliteration":"lahā","translation_bn":"জন্যে তার (রয়েছে)","root":"—","lemma":"لَّهَا","grammar_bn":"অব্যয় (Preposition)"},{"id":81123,"position":5,"text_uthmani":"شِرْبٌۭ","transliteration":"shir''bun","translation_bn":"পানি পান করার পালা","root":"شرب","lemma":"شِرْب","grammar_bn":"বিশেষ্য (Noun)"},{"id":81124,"position":6,"text_uthmani":"وَلَكُمْ","transliteration":"walakum","translation_bn":"এবং জন্যে তোমাদের","root":"—","lemma":"وَلَكُمْ","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":81125,"position":7,"text_uthmani":"شِرْبُ","transliteration":"shir''bu","translation_bn":"পানি পান করার পালা","root":"شرب","lemma":"شِرْب","grammar_bn":"বিশেষ্য (Noun)"},{"id":81126,"position":8,"text_uthmani":"يَوْمٍۢ","transliteration":"yawmin","translation_bn":"দিন","root":"يوم","lemma":"يَوْم","grammar_bn":"বিশেষ্য (Noun)"},{"id":81127,"position":9,"text_uthmani":"مَّعْلُومٍۢ","transliteration":"maʿlūmin","translation_bn":"নির্দিষ্ট","root":"علم","lemma":"مَّعْلُوم","grammar_bn":"বিশেষ্য (Noun)"},{"id":81128,"position":10,"text_uthmani":"١٥٥","transliteration":"","translation_bn":"(১৫৫)","root":"—","lemma":"١٥٥","grammar_bn":"মার্কার"}]'::jsonb, 'qāla hādhihi nāqatun lahā shir''bun walakum shir''bu yawmin maʿlūmin', 'সালিহ বলল- ‘এই একটি উটনি, এর জন্য আছে পানি পানের পালা আর তোমাদের জন্য আছে পানি পানের পালা নির্ধারিত দিনে।', 'He said, "This is a she-camel. For her is a [time of] drink, and for you is a [time of] drink, [each] on a known day.', 'সালিহ বলল- ‘এই একটি উটনি, এর জন্য আছে পানি পানের পালা আর তোমাদের জন্য আছে পানি পানের পালা নির্ধারিত দিনে।', 'He said, "This is a she-camel. For her is a [time of] drink, and for you is a [time of] drink, [each] on a known day.', NULL, NULL, NULL, NULL, NULL, 'https://everyayah.com/data/Alafasy_128kbps/026155.mp3', now()),
  (26, 156, '', '[{"id":81226,"position":1,"text_uthmani":"وَلَا","transliteration":"walā","translation_bn":"আর না","root":"—","lemma":"لَا\r","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":81227,"position":2,"text_uthmani":"تَمَسُّوهَا","transliteration":"tamassūhā","translation_bn":"স্পর্শ করো তাকে","root":"مسس","lemma":"مَسَّ","grammar_bn":"ক্রিয়া (Verb)"},{"id":81228,"position":3,"text_uthmani":"بِسُوٓءٍۢ","transliteration":"bisūin","translation_bn":"মন্দভাবে","root":"سوا","lemma":"سُو^ء","grammar_bn":"অব্যয় (Preposition)"},{"id":81229,"position":4,"text_uthmani":"فَيَأْخُذَكُمْ","transliteration":"fayakhudhakum","translation_bn":"তাহলে ধরবে তোমাদেরকে","root":"اخذ","lemma":"أَخَذَ","grammar_bn":"কারণবাচক (Cause)"},{"id":81230,"position":5,"text_uthmani":"عَذَابُ","transliteration":"ʿadhābu","translation_bn":"শাস্তি","root":"عذب","lemma":"عَذَاب","grammar_bn":"বিশেষ্য (Noun)"},{"id":81231,"position":6,"text_uthmani":"يَوْمٍ","transliteration":"yawmin","translation_bn":"দিনের","root":"يوم","lemma":"يَوْم","grammar_bn":"বিশেষ্য (Noun)"},{"id":81232,"position":7,"text_uthmani":"عَظِيمٍۢ","transliteration":"ʿaẓīmin","translation_bn":"কঠিন\"","root":"عظم","lemma":"عَظِيم","grammar_bn":"বিশেষণ (Adjective)"},{"id":81233,"position":8,"text_uthmani":"١٥٦","transliteration":"","translation_bn":"(১৫৬)","root":"—","lemma":"١٥٦","grammar_bn":"মার্কার"}]'::jsonb, 'walā tamassūhā bisūin fayakhudhakum ʿadhābu yawmin ʿaẓīmin', 'অনিষ্ট সাধনের নিমিত্তে তাকে স্পর্শ কর না, তাহলে তোমাদেরকে মহা দিবসের আযাব পাকড়াও করবে।', 'And do not touch her with harm, lest you be seized by the punishment of a terrible day."', 'অনিষ্ট সাধনের নিমিত্তে তাকে স্পর্শ কর না, তাহলে তোমাদেরকে মহা দিবসের আযাব পাকড়াও করবে।', 'And do not touch her with harm, lest you be seized by the punishment of a terrible day."', NULL, NULL, NULL, NULL, NULL, 'https://everyayah.com/data/Alafasy_128kbps/026156.mp3', now()),
  (26, 157, '', '[{"id":81388,"position":1,"text_uthmani":"فَعَقَرُوهَا","transliteration":"faʿaqarūhā","translation_bn":"কিন্তু তার পায়ের রগ কেটে দিয়ে হত্যা করলো","root":"عقر","lemma":"عَقَرَ","grammar_bn":"শব্দ"},{"id":81389,"position":2,"text_uthmani":"فَأَصْبَحُوا۟","transliteration":"fa-aṣbaḥū","translation_bn":"পরিণামে তারা হলো","root":"صبح","lemma":"أَصْبَحَ","grammar_bn":"শব্দ"},{"id":81390,"position":3,"text_uthmani":"نَـٰدِمِينَ","transliteration":"nādimīna","translation_bn":"অনুতপ্ত","root":"ندم","lemma":"نَٰدِمِين","grammar_bn":"বিশেষ্য (Noun)"},{"id":81391,"position":4,"text_uthmani":"١٥٧","transliteration":"","translation_bn":"(১৫৭)","root":"—","lemma":"١٥٧","grammar_bn":"মার্কার"}]'::jsonb, 'faʿaqarūhā fa-aṣbaḥū nādimīna', 'কিন্তু তারা তাকে বধ করল, ফলে তারা অনুতপ্ত হল।', 'But they hamstrung her and so became regretful.', 'কিন্তু তারা তাকে বধ করল, ফলে তারা অনুতপ্ত হল।', 'But they hamstrung her and so became regretful.', NULL, NULL, NULL, NULL, NULL, 'https://everyayah.com/data/Alafasy_128kbps/026157.mp3', now()),
  (26, 158, '', '[{"id":81516,"position":1,"text_uthmani":"فَأَخَذَهُمُ","transliteration":"fa-akhadhahumu","translation_bn":"অতঃপর গ্রাস করলো তাদেরকে","root":"اخذ","lemma":"أَخَذَ","grammar_bn":"শব্দ"},{"id":81517,"position":2,"text_uthmani":"ٱلْعَذَابُ ۗ","transliteration":"l-ʿadhābu","translation_bn":"শাস্তি","root":"عذب","lemma":"عَذَاب","grammar_bn":"শব্দ"},{"id":81519,"position":3,"text_uthmani":"إِنَّ","transliteration":"inna","translation_bn":"নিশ্চয়ই","root":"—","lemma":"إِنّ","grammar_bn":"অভিঘাত পদ (Accusative)"},{"id":81520,"position":4,"text_uthmani":"فِى","transliteration":"fī","translation_bn":"মধ্যে (আছে)","root":"—","lemma":"فِى\r","grammar_bn":"অব্যয় (Preposition)"},{"id":81521,"position":5,"text_uthmani":"ذَٰلِكَ","transliteration":"dhālika","translation_bn":"এর","root":"—","lemma":"ذَٰلِك","grammar_bn":"নির্দেশক সর্বনাম (Demonstrative)"},{"id":81522,"position":6,"text_uthmani":"لَـَٔايَةًۭ ۖ","transliteration":"laāyatan","translation_bn":"অবশ্যই নিদর্শন","root":"ايي","lemma":"ءَايَة","grammar_bn":"দৃঢ়তাবোধক (Emphatic)"},{"id":81524,"position":7,"text_uthmani":"وَمَا","transliteration":"wamā","translation_bn":"আর না","root":"—","lemma":"مَا\r","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":81525,"position":8,"text_uthmani":"كَانَ","transliteration":"kāna","translation_bn":"ছিলো","root":"كون","lemma":"كَانَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":81526,"position":9,"text_uthmani":"أَكْثَرُهُم","transliteration":"aktharuhum","translation_bn":"অধিকাংশ তাদের","root":"كثر","lemma":"أَكْثَر","grammar_bn":"বিশেষ্য (Noun)"},{"id":81527,"position":10,"text_uthmani":"مُّؤْمِنِينَ","transliteration":"mu''minīna","translation_bn":"মু''মিন","root":"امن","lemma":"مُؤْمِن","grammar_bn":"বিশেষ্য (Noun)"},{"id":81528,"position":11,"text_uthmani":"١٥٨","transliteration":"","translation_bn":"(১৫৮)","root":"—","lemma":"١٥٨","grammar_bn":"মার্কার"}]'::jsonb, 'fa-akhadhahumu l-ʿadhābu inna fī dhālika laāyatan wamā kāna aktharuhum mu''minīna', 'অতঃপর আযাব তাদেরকে পাকড়াও করল। এতে অবশ্যই নিদর্শন রয়েছে, কিন্তু তাদের অধিকাংশই বিশ্বাস করে না।', 'And the punishment seized them. Indeed in that is a sign, but most of them were not to be believers.', 'অতঃপর আযাব তাদেরকে পাকড়াও করল। এতে অবশ্যই নিদর্শন রয়েছে, কিন্তু তাদের অধিকাংশই বিশ্বাস করে না।', 'And the punishment seized them. Indeed in that is a sign, but most of them were not to be believers.', NULL, NULL, NULL, NULL, NULL, 'https://everyayah.com/data/Alafasy_128kbps/026158.mp3', now()),
  (26, 159, '', '[{"id":81679,"position":1,"text_uthmani":"وَإِنَّ","transliteration":"wa-inna","translation_bn":"অথচ নিশ্চয়ই","root":"—","lemma":"إِنّ","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":81680,"position":2,"text_uthmani":"رَبَّكَ","transliteration":"rabbaka","translation_bn":"তোমার রব","root":"ربب","lemma":"رَبّ","grammar_bn":"বিশেষ্য (Noun)"},{"id":81681,"position":3,"text_uthmani":"لَهُوَ","transliteration":"lahuwa","translation_bn":"অবশ্যই তিনি","root":"—","lemma":"لَهُوَ","grammar_bn":"দৃঢ়তাবোধক (Emphatic)"},{"id":81682,"position":4,"text_uthmani":"ٱلْعَزِيزُ","transliteration":"l-ʿazīzu","translation_bn":"পরাক্রমশালী","root":"عزز","lemma":"عَزِيز","grammar_bn":"শব্দ"},{"id":81683,"position":5,"text_uthmani":"ٱلرَّحِيمُ","transliteration":"l-raḥīmu","translation_bn":"পরম দয়ালু","root":"رحم","lemma":"رَّحِيم","grammar_bn":"শব্দ"},{"id":81684,"position":6,"text_uthmani":"١٥٩","transliteration":"","translation_bn":"(১৫৯)","root":"—","lemma":"١٥٩","grammar_bn":"মার্কার"}]'::jsonb, 'wa-inna rabbaka lahuwa l-ʿazīzu l-raḥīmu', 'আর তোমার প্রতিপালক তিনি তো মহা পরাক্রমশালী, বড়ই দয়ালু।', 'And indeed, your Lord - He is the Exalted in Might, the Merciful.', 'আর তোমার প্রতিপালক তিনি তো মহা পরাক্রমশালী, বড়ই দয়ালু।', 'And indeed, your Lord - He is the Exalted in Might, the Merciful.', NULL, NULL, NULL, NULL, NULL, 'https://everyayah.com/data/Alafasy_128kbps/026159.mp3', now()),
  (26, 160, '', '[{"id":81848,"position":1,"text_uthmani":"كَذَّبَتْ","transliteration":"kadhabat","translation_bn":"মিথ্যারোপ করেছিলো","root":"كذب","lemma":"كَذَّبَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":81849,"position":2,"text_uthmani":"قَوْمُ","transliteration":"qawmu","translation_bn":"জাতি","root":"قوم","lemma":"قَوْم","grammar_bn":"বিশেষ্য (Noun)"},{"id":81850,"position":3,"text_uthmani":"لُوطٍ","transliteration":"lūṭin","translation_bn":"লুতের","root":"—","lemma":"لُوط","grammar_bn":"নামবাচক বিশেষ্য (Proper Noun)"},{"id":81851,"position":4,"text_uthmani":"ٱلْمُرْسَلِينَ","transliteration":"l-mur''salīna","translation_bn":"রাসূলদেরকে","root":"رسل","lemma":"مُّرْسَل","grammar_bn":"শব্দ"},{"id":81852,"position":5,"text_uthmani":"١٦٠","transliteration":"","translation_bn":"(১৬০)","root":"—","lemma":"١٦٠","grammar_bn":"মার্কার"}]'::jsonb, 'kadhabat qawmu lūṭin l-mur''salīna', 'লূতের সম্প্রদায় রসুলদেরকে মিথ্যে বলে প্রত্যাখ্যান করেছিল।', 'The people of Lot denied the messengers', 'লূতের সম্প্রদায় রসুলদেরকে মিথ্যে বলে প্রত্যাখ্যান করেছিল।', 'The people of Lot denied the messengers', NULL, NULL, NULL, NULL, NULL, 'https://everyayah.com/data/Alafasy_128kbps/026160.mp3', now()),
  (26, 161, '', '[{"id":81888,"position":1,"text_uthmani":"إِذْ","transliteration":"idh","translation_bn":"(স্মরণ করো) যখন","root":"—","lemma":"إِذ\r","grammar_bn":"কালবাচক (Time)"},{"id":81889,"position":2,"text_uthmani":"قَالَ","transliteration":"qāla","translation_bn":"বলেছিলো","root":"قول","lemma":"قَالَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":81890,"position":3,"text_uthmani":"لَهُمْ","transliteration":"lahum","translation_bn":"উদ্দেশ্যে তাদের","root":"—","lemma":"لَهُمْ","grammar_bn":"অব্যয় (Preposition)"},{"id":81891,"position":4,"text_uthmani":"أَخُوهُمْ","transliteration":"akhūhum","translation_bn":"ভাই তাদের","root":"اخو","lemma":"أَخ","grammar_bn":"বিশেষ্য (Noun)"},{"id":81892,"position":5,"text_uthmani":"لُوطٌ","transliteration":"lūṭun","translation_bn":"লুত","root":"—","lemma":"لُوط","grammar_bn":"নামবাচক বিশেষ্য (Proper Noun)"},{"id":81893,"position":6,"text_uthmani":"أَلَا","transliteration":"alā","translation_bn":"\"কি না","root":"—","lemma":"لَا\r","grammar_bn":"প্রশ্নবোধক (Interrogative)"},{"id":81894,"position":7,"text_uthmani":"تَتَّقُونَ","transliteration":"tattaqūna","translation_bn":"তোমরা ভয় করবে","root":"وقي","lemma":"ٱتَّقَىٰ","grammar_bn":"ক্রিয়া (Verb)"},{"id":81895,"position":8,"text_uthmani":"١٦١","transliteration":"","translation_bn":"(১৬১)","root":"—","lemma":"١٦١","grammar_bn":"মার্কার"}]'::jsonb, 'idh qāla lahum akhūhum lūṭun alā tattaqūna', 'যখন তাদের ভাই লূত তাদেরকে বলেছিল- ‘তোমরা কি (আল্লাহকে) ভয় করবে না?', 'When their brother Lot said to them, "Will you not fear Allah?', 'যখন তাদের ভাই লূত তাদেরকে বলেছিল- ‘তোমরা কি (আল্লাহকে) ভয় করবে না?', 'When their brother Lot said to them, "Will you not fear Allah?', NULL, NULL, NULL, NULL, NULL, 'https://everyayah.com/data/Alafasy_128kbps/026161.mp3', now()),
  (26, 162, '', '[{"id":81989,"position":1,"text_uthmani":"إِنِّى","transliteration":"innī","translation_bn":"নিশ্চয়ই আমি","root":"—","lemma":"إِنّ","grammar_bn":"অভিঘাত পদ (Accusative)"},{"id":81990,"position":2,"text_uthmani":"لَكُمْ","transliteration":"lakum","translation_bn":"জন্যে তোমাদের","root":"—","lemma":"لَكُمْ","grammar_bn":"অব্যয় (Preposition)"},{"id":81991,"position":3,"text_uthmani":"رَسُولٌ","transliteration":"rasūlun","translation_bn":"একজন রাসূল","root":"رسل","lemma":"رَسُول","grammar_bn":"বিশেষ্য (Noun)"},{"id":81992,"position":4,"text_uthmani":"أَمِينٌۭ","transliteration":"amīnun","translation_bn":"বিশ্বস্ত","root":"امن","lemma":"أَمِين","grammar_bn":"বিশেষণ (Adjective)"},{"id":81993,"position":5,"text_uthmani":"١٦٢","transliteration":"","translation_bn":"(১৬২)","root":"—","lemma":"١٦٢","grammar_bn":"মার্কার"}]'::jsonb, 'innī lakum rasūlun amīnun', 'আমি তো তোমাদের জন্য (প্রেরিত) একজন বিশ্বস্ত রসূল।', 'Indeed, I am to you a trustworthy messenger.', 'আমি তো তোমাদের জন্য (প্রেরিত) একজন বিশ্বস্ত রসূল।', 'Indeed, I am to you a trustworthy messenger.', NULL, NULL, NULL, NULL, NULL, 'https://everyayah.com/data/Alafasy_128kbps/026162.mp3', now()),
  (26, 163, '', '[{"id":82096,"position":1,"text_uthmani":"فَٱتَّقُوا۟","transliteration":"fa-ittaqū","translation_bn":"অতএব তোমরা ভয় করো","root":"وقي","lemma":"ٱتَّقَىٰ","grammar_bn":"শব্দ"},{"id":82097,"position":2,"text_uthmani":"ٱللَّهَ","transliteration":"l-laha","translation_bn":"আল্লাহকে","root":"اله","lemma":"ٱللَّه","grammar_bn":"নামবাচক বিশেষ্য (Proper Noun)"},{"id":82098,"position":3,"text_uthmani":"وَأَطِيعُونِ","transliteration":"wa-aṭīʿūni","translation_bn":"ও আমার আনুগত্য করো","root":"طوع","lemma":"أَطَاعَ","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":82099,"position":4,"text_uthmani":"١٦٣","transliteration":"","translation_bn":"(১৬৩)","root":"—","lemma":"١٦٣","grammar_bn":"মার্কার"}]'::jsonb, 'fa-ittaqū l-laha wa-aṭīʿūni', 'কাজেই তোমরা আল্লাহকে ভয় কর ও আমাকে মান্য কর।', 'So fear Allah and obey me.', 'কাজেই তোমরা আল্লাহকে ভয় কর ও আমাকে মান্য কর।', 'So fear Allah and obey me.', NULL, NULL, NULL, NULL, NULL, 'https://everyayah.com/data/Alafasy_128kbps/026163.mp3', now()),
  (26, 164, '', '[{"id":82216,"position":1,"text_uthmani":"وَمَآ","transliteration":"wamā","translation_bn":"আর না","root":"—","lemma":"مَا\r","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":82217,"position":2,"text_uthmani":"أَسْـَٔلُكُمْ","transliteration":"asalukum","translation_bn":"তোমাদের (নিকট) আমি চাচ্ছি","root":"سال","lemma":"سَأَلَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":82218,"position":3,"text_uthmani":"عَلَيْهِ","transliteration":"ʿalayhi","translation_bn":"জন্যে এর","root":"—","lemma":"عَلَىٰ\r","grammar_bn":"অব্যয় (Preposition)"},{"id":82219,"position":4,"text_uthmani":"مِنْ","transliteration":"min","translation_bn":"কোনো","root":"—","lemma":"مِن\r","grammar_bn":"অব্যয় (Preposition)"},{"id":82220,"position":5,"text_uthmani":"أَجْرٍ ۖ","transliteration":"ajrin","translation_bn":"পারিশ্রমিক","root":"اجر","lemma":"أَجْر","grammar_bn":"বিশেষ্য (Noun)"},{"id":82222,"position":6,"text_uthmani":"إِنْ","transliteration":"in","translation_bn":"নেই","root":"—","lemma":"إِن\r","grammar_bn":"না-বোধক (Negative)"},{"id":82223,"position":7,"text_uthmani":"أَجْرِىَ","transliteration":"ajriya","translation_bn":"আমার প্রতিদান (কারো নিকট)","root":"اجر","lemma":"أَجْر","grammar_bn":"বিশেষ্য (Noun)"},{"id":82224,"position":8,"text_uthmani":"إِلَّا","transliteration":"illā","translation_bn":"এ ছাড়া","root":"—","lemma":"إِلَّا\r","grammar_bn":"সীমাবদ্ধতা (Restriction)"},{"id":82225,"position":9,"text_uthmani":"عَلَىٰ","transliteration":"ʿalā","translation_bn":"নিকট","root":"—","lemma":"عَلَىٰ\r","grammar_bn":"অব্যয় (Preposition)"},{"id":82226,"position":10,"text_uthmani":"رَبِّ","transliteration":"rabbi","translation_bn":"রবের","root":"ربب","lemma":"رَبّ","grammar_bn":"বিশেষ্য (Noun)"},{"id":82227,"position":11,"text_uthmani":"ٱلْعَـٰلَمِينَ","transliteration":"l-ʿālamīna","translation_bn":"বিশ্বজগতের","root":"علم","lemma":"عَٰلَمِين","grammar_bn":"শব্দ"},{"id":82228,"position":12,"text_uthmani":"١٦٤","transliteration":"","translation_bn":"(১৬৪)","root":"—","lemma":"١٦٤","grammar_bn":"মার্কার"}]'::jsonb, 'wamā asalukum ʿalayhi min ajrin in ajriya illā ʿalā rabbi l-ʿālamīna', 'আমি এজন্য তোমাদের কাছে কোন প্রতিদান চাই না, আমার প্রতিদান একমাত্র জগতসমূহের প্রতিপালকের নিকট রয়েছে।', 'And I do not ask you for it any payment. My payment is only from the Lord of the worlds.', 'আমি এজন্য তোমাদের কাছে কোন প্রতিদান চাই না, আমার প্রতিদান একমাত্র জগতসমূহের প্রতিপালকের নিকট রয়েছে।', 'And I do not ask you for it any payment. My payment is only from the Lord of the worlds.', NULL, NULL, NULL, NULL, NULL, 'https://everyayah.com/data/Alafasy_128kbps/026164.mp3', now()),
  (26, 165, '', '[{"id":82328,"position":1,"text_uthmani":"أَتَأْتُونَ","transliteration":"atatūna","translation_bn":"কি তোমরা উপগত হও","root":"اتي","lemma":"أَتَى","grammar_bn":"প্রশ্নবোধক (Interrogative)"},{"id":82329,"position":2,"text_uthmani":"ٱلذُّكْرَانَ","transliteration":"l-dhuk''rāna","translation_bn":"পুরুষদের (নিকট)","root":"ذكر","lemma":"ذَكَر","grammar_bn":"শব্দ"},{"id":82330,"position":3,"text_uthmani":"مِنَ","transliteration":"mina","translation_bn":"মধ্য হ''তে","root":"—","lemma":"مِن\r","grammar_bn":"অব্যয় (Preposition)"},{"id":82331,"position":4,"text_uthmani":"ٱلْعَـٰلَمِينَ","transliteration":"l-ʿālamīna","translation_bn":"বিশ্বজগতের","root":"علم","lemma":"عَٰلَمِين","grammar_bn":"শব্দ"},{"id":82332,"position":5,"text_uthmani":"١٦٥","transliteration":"","translation_bn":"(১৬৫)","root":"—","lemma":"١٦٥","grammar_bn":"মার্কার"}]'::jsonb, 'atatūna l-dhuk''rāna mina l-ʿālamīna', 'জগতের সকল প্রাণীর মধ্যে তোমরাই কি পুরুষদের সঙ্গে উপগত হও,', 'Do you approach males among the worlds', 'জগতের সকল প্রাণীর মধ্যে তোমরাই কি পুরুষদের সঙ্গে উপগত হও,', 'Do you approach males among the worlds', NULL, NULL, NULL, NULL, NULL, 'https://everyayah.com/data/Alafasy_128kbps/026165.mp3', now()),
  (26, 166, '', '[{"id":82476,"position":1,"text_uthmani":"وَتَذَرُونَ","transliteration":"watadharūna","translation_bn":"ও তোমরা পরিহার করছো","root":"وذر","lemma":"يَذَرَ","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":82477,"position":2,"text_uthmani":"مَا","transliteration":"mā","translation_bn":"যা","root":"—","lemma":"مَا\r","grammar_bn":"সাপেক্ষ সর্বনাম (Relative)"},{"id":82478,"position":3,"text_uthmani":"خَلَقَ","transliteration":"khalaqa","translation_bn":"সৃষ্টি করেছেন","root":"خلق","lemma":"خَلَقَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":82479,"position":4,"text_uthmani":"لَكُمْ","transliteration":"lakum","translation_bn":"জন্যে তোমাদের","root":"—","lemma":"لَكُمْ","grammar_bn":"অব্যয় (Preposition)"},{"id":82480,"position":5,"text_uthmani":"رَبُّكُم","transliteration":"rabbukum","translation_bn":"রব তোমাদের","root":"ربب","lemma":"رَبّ","grammar_bn":"বিশেষ্য (Noun)"},{"id":82481,"position":6,"text_uthmani":"مِّنْ","transliteration":"min","translation_bn":"মধ্য থেকে","root":"—","lemma":"مِن\r","grammar_bn":"অব্যয় (Preposition)"},{"id":82482,"position":7,"text_uthmani":"أَزْوَٰجِكُم ۚ","transliteration":"azwājikum","translation_bn":"তোমাদের স্ত্রীদের","root":"زوج","lemma":"زَوْج","grammar_bn":"বিশেষ্য (Noun)"},{"id":82484,"position":8,"text_uthmani":"بَلْ","transliteration":"bal","translation_bn":"বরং","root":"—","lemma":"بَل\r","grammar_bn":"প্রত্যাহার পদ (Retraction)"},{"id":82485,"position":9,"text_uthmani":"أَنتُمْ","transliteration":"antum","translation_bn":"তোমরা","root":"—","lemma":"أَنتُمْ","grammar_bn":"সর্বনাম (Pronoun)"},{"id":82486,"position":10,"text_uthmani":"قَوْمٌ","transliteration":"qawmun","translation_bn":"জাতি","root":"قوم","lemma":"قَوْم","grammar_bn":"বিশেষ্য (Noun)"},{"id":82487,"position":11,"text_uthmani":"عَادُونَ","transliteration":"ʿādūna","translation_bn":"সীমালঙ্ঘনকারী\"","root":"عدو","lemma":"عَاد","grammar_bn":"বিশেষ্য (Noun)"},{"id":82488,"position":12,"text_uthmani":"١٦٦","transliteration":"","translation_bn":"(১৬৬)","root":"—","lemma":"١٦٦","grammar_bn":"মার্কার"}]'::jsonb, 'watadharūna mā khalaqa lakum rabbukum min azwājikum bal antum qawmun ʿādūna', 'এবং তোমাদের প্রতিপালক তোমাদের জন্য যে স্ত্রীগণকে সৃষ্টি করেছেন তাদেরকে ত্যাগ কর? রবং তোমরা এক সীমালঙ্ঘনকারী সম্প্রদায়।’', 'And leave what your Lord has created for you as mates? But you are a people transgressing."', 'এবং তোমাদের প্রতিপালক তোমাদের জন্য যে স্ত্রীগণকে সৃষ্টি করেছেন তাদেরকে ত্যাগ কর? রবং তোমরা এক সীমালঙ্ঘনকারী সম্প্রদায়।’', 'And leave what your Lord has created for you as mates? But you are a people transgressing."', NULL, NULL, NULL, NULL, NULL, 'https://everyayah.com/data/Alafasy_128kbps/026166.mp3', now()),
  (26, 167, '', '[{"id":82522,"position":1,"text_uthmani":"قَالُوا۟","transliteration":"qālū","translation_bn":"তারা বললো","root":"قول","lemma":"قَالَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":82523,"position":2,"text_uthmani":"لَئِن","transliteration":"la-in","translation_bn":"\"অবশ্যই যদি","root":"—","lemma":"إِن\r","grammar_bn":"দৃঢ়তাবোধক (Emphatic)"},{"id":82524,"position":3,"text_uthmani":"لَّمْ","transliteration":"lam","translation_bn":"না","root":"—","lemma":"لَم\r","grammar_bn":"না-বোধক (Negative)"},{"id":82525,"position":4,"text_uthmani":"تَنتَهِ","transliteration":"tantahi","translation_bn":"বিরত হও","root":"نهي","lemma":"ٱنتَهَىٰ","grammar_bn":"ক্রিয়া (Verb)"},{"id":82526,"position":5,"text_uthmani":"يَـٰلُوطُ","transliteration":"yālūṭu","translation_bn":"হে লুত","root":"—","lemma":"لُوط","grammar_bn":"সম্বোধন পদ (Vocative)"},{"id":82527,"position":6,"text_uthmani":"لَتَكُونَنَّ","transliteration":"latakūnanna","translation_bn":"অবশ্যই তুমি হবে","root":"كون","lemma":"كَانَ","grammar_bn":"দৃঢ়তাবোধক (Emphatic)"},{"id":82528,"position":7,"text_uthmani":"مِنَ","transliteration":"mina","translation_bn":"অন্তর্ভুক্ত","root":"—","lemma":"مِن\r","grammar_bn":"অব্যয় (Preposition)"},{"id":82529,"position":8,"text_uthmani":"ٱلْمُخْرَجِينَ","transliteration":"l-mukh''rajīna","translation_bn":"বহিষ্কৃতদের\"","root":"خرج","lemma":"مُخْرَج","grammar_bn":"শব্দ"},{"id":82530,"position":9,"text_uthmani":"١٦٧","transliteration":"","translation_bn":"(১৬৭)","root":"—","lemma":"١٦٧","grammar_bn":"মার্কার"}]'::jsonb, 'qālū la-in lam tantahi yālūṭu latakūnanna mina l-mukh''rajīna', 'তারা বলল- ‘হে লূত! তুমি যদি বিরত না হও তবে তুমি অবশ্য অবশ্যই বহিস্কৃত হবে।’', 'They said, "If you do not desist, O Lot, you will surely be of those evicted."', 'তারা বলল- ‘হে লূত! তুমি যদি বিরত না হও তবে তুমি অবশ্য অবশ্যই বহিস্কৃত হবে।’', 'They said, "If you do not desist, O Lot, you will surely be of those evicted."', NULL, NULL, NULL, NULL, NULL, 'https://everyayah.com/data/Alafasy_128kbps/026167.mp3', now()),
  (26, 168, '', '[{"id":82671,"position":1,"text_uthmani":"قَالَ","transliteration":"qāla","translation_bn":"(লুত) বললো","root":"قول","lemma":"قَالَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":82672,"position":2,"text_uthmani":"إِنِّى","transliteration":"innī","translation_bn":"\"নিশ্চয়ই আমি","root":"—","lemma":"إِنّ","grammar_bn":"অভিঘাত পদ (Accusative)"},{"id":82673,"position":3,"text_uthmani":"لِعَمَلِكُم","transliteration":"liʿamalikum","translation_bn":"জন্যে তোমাদের কাজের","root":"عمل","lemma":"عَمَل","grammar_bn":"অব্যয় (Preposition)"},{"id":82674,"position":4,"text_uthmani":"مِّنَ","transliteration":"mina","translation_bn":"অন্তর্ভুক্ত","root":"—","lemma":"مِن\r","grammar_bn":"অব্যয় (Preposition)"},{"id":82675,"position":5,"text_uthmani":"ٱلْقَالِينَ","transliteration":"l-qālīna","translation_bn":"ঘৃণাকারীদের","root":"قلي","lemma":"قَالِين","grammar_bn":"শব্দ"},{"id":82676,"position":6,"text_uthmani":"١٦٨","transliteration":"","translation_bn":"(১৬৮)","root":"—","lemma":"١٦٨","grammar_bn":"মার্কার"}]'::jsonb, 'qāla innī liʿamalikum mina l-qālīna', 'লূত বলল- ‘আমি তোমাদের এ কাজকে ঘৃণা করি।', 'He said, "Indeed, I am, toward your deed, of those who detest [it].', 'লূত বলল- ‘আমি তোমাদের এ কাজকে ঘৃণা করি।', 'He said, "Indeed, I am, toward your deed, of those who detest [it].', NULL, NULL, NULL, NULL, NULL, 'https://everyayah.com/data/Alafasy_128kbps/026168.mp3', now()),
  (26, 169, '', '[{"id":82713,"position":1,"text_uthmani":"رَبِّ","transliteration":"rabbi","translation_bn":"হে আমার রব","root":"ربب","lemma":"رَبّ","grammar_bn":"বিশেষ্য (Noun)"},{"id":82714,"position":2,"text_uthmani":"نَجِّنِى","transliteration":"najjinī","translation_bn":"আমাকে রক্ষা করো","root":"نجو","lemma":"نَجَّىٰ","grammar_bn":"ক্রিয়া (Verb)"},{"id":82715,"position":3,"text_uthmani":"وَأَهْلِى","transliteration":"wa-ahlī","translation_bn":"ও আমার পরিবারকে","root":"اهل","lemma":"أَهْل","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":82716,"position":4,"text_uthmani":"مِمَّا","transliteration":"mimmā","translation_bn":"(তা) হ''তে যা","root":"—","lemma":"مِن\r","grammar_bn":"অব্যয় (Preposition)"},{"id":82717,"position":5,"text_uthmani":"يَعْمَلُونَ","transliteration":"yaʿmalūna","translation_bn":"তারা করেছে\"","root":"عمل","lemma":"عَمِلَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":82718,"position":6,"text_uthmani":"١٦٩","transliteration":"","translation_bn":"(১৬৯)","root":"—","lemma":"١٦٩","grammar_bn":"মার্কার"}]'::jsonb, 'rabbi najjinī wa-ahlī mimmā yaʿmalūna', 'হে আমার প্রতিপালক! তারা যা করে তা থেকে তুমি আমাকে ও আমার পরিবারবর্গকে রক্ষা কর।’', 'My Lord, save me and my family from [the consequence of] what they do."', 'হে আমার প্রতিপালক! তারা যা করে তা থেকে তুমি আমাকে ও আমার পরিবারবর্গকে রক্ষা কর।’', 'My Lord, save me and my family from [the consequence of] what they do."', NULL, NULL, NULL, NULL, NULL, 'https://everyayah.com/data/Alafasy_128kbps/026169.mp3', now()),
  (26, 170, '', '[{"id":82869,"position":1,"text_uthmani":"فَنَجَّيْنَـٰهُ","transliteration":"fanajjaynāhu","translation_bn":"অতঃপর তাকে আমরা রক্ষা করলাম","root":"نجو","lemma":"نَجَّىٰ","grammar_bn":"শব্দ"},{"id":82870,"position":2,"text_uthmani":"وَأَهْلَهُۥٓ","transliteration":"wa-ahlahu","translation_bn":"ও তার পরিবারকে","root":"اهل","lemma":"أَهْل","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":82871,"position":3,"text_uthmani":"أَجْمَعِينَ","transliteration":"ajmaʿīna","translation_bn":"সবাইকে (একযোগে)","root":"جمع","lemma":"أَجْمَعِين","grammar_bn":"বিশেষ্য (Noun)"},{"id":82872,"position":4,"text_uthmani":"١٧٠","transliteration":"","translation_bn":"(১৭০)","root":"—","lemma":"١٧٠","grammar_bn":"মার্কার"}]'::jsonb, 'fanajjaynāhu wa-ahlahu ajmaʿīna', 'অতঃপর আমি তাকে ও তার পরিবারবর্গের সকলকে রক্ষা করলাম', 'So We saved him and his family, all,', 'অতঃপর আমি তাকে ও তার পরিবারবর্গের সকলকে রক্ষা করলাম', 'So We saved him and his family, all,', NULL, NULL, NULL, NULL, NULL, 'https://everyayah.com/data/Alafasy_128kbps/026170.mp3', now()),
  (26, 171, '', '[{"id":82899,"position":1,"text_uthmani":"إِلَّا","transliteration":"illā","translation_bn":"ছাড়া","root":"—","lemma":"إِلَّا\r","grammar_bn":"সীমাবদ্ধতা (Restriction)"},{"id":82900,"position":2,"text_uthmani":"عَجُوزًۭا","transliteration":"ʿajūzan","translation_bn":"এক বৃদ্ধা (তার স্ত্রী)","root":"عجز","lemma":"عَجُوز","grammar_bn":"বিশেষ্য (Noun)"},{"id":82901,"position":3,"text_uthmani":"فِى","transliteration":"fī","translation_bn":"(সে ছিলো) অন্তর্ভুক্ত","root":"—","lemma":"فِى\r","grammar_bn":"অব্যয় (Preposition)"},{"id":82902,"position":4,"text_uthmani":"ٱلْغَـٰبِرِينَ","transliteration":"l-ghābirīna","translation_bn":"পিছনে অবস্থানকারীদের","root":"غبر","lemma":"غَٰبِرِين","grammar_bn":"শব্দ"},{"id":82903,"position":5,"text_uthmani":"١٧١","transliteration":"","translation_bn":"(১৭১)","root":"—","lemma":"١٧١","grammar_bn":"মার্কার"}]'::jsonb, 'illā ʿajūzan fī l-ghābirīna', 'এক বৃদ্ধা ছাড়া। সে ছিল পেছনে অবস্থানকারীদের অন্তর্ভুক্ত।', 'Except an old woman among those who remained behind.', 'এক বৃদ্ধা ছাড়া। সে ছিল পেছনে অবস্থানকারীদের অন্তর্ভুক্ত।', 'Except an old woman among those who remained behind.', NULL, NULL, NULL, NULL, NULL, 'https://everyayah.com/data/Alafasy_128kbps/026171.mp3', now()),
  (26, 172, '', '[{"id":83075,"position":1,"text_uthmani":"ثُمَّ","transliteration":"thumma","translation_bn":"এরপর","root":"—","lemma":"ثُمّ\r","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":83076,"position":2,"text_uthmani":"دَمَّرْنَا","transliteration":"dammarnā","translation_bn":"আমরা ধ্বংস করলাম","root":"دمر","lemma":"دَمَّرَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":83077,"position":3,"text_uthmani":"ٱلْـَٔاخَرِينَ","transliteration":"l-ākharīna","translation_bn":"অন্যদেরকে","root":"اخر","lemma":"ا^خَر","grammar_bn":"শব্দ"},{"id":83078,"position":4,"text_uthmani":"١٧٢","transliteration":"","translation_bn":"(১৭২)","root":"—","lemma":"١٧٢","grammar_bn":"মার্কার"}]'::jsonb, 'thumma dammarnā l-ākharīna', 'অতঃপর অন্যদের সকলকে পুরোপুরি ধ্বংস করে দিলাম।', 'Then We destroyed the others.', 'অতঃপর অন্যদের সকলকে পুরোপুরি ধ্বংস করে দিলাম।', 'Then We destroyed the others.', NULL, NULL, NULL, NULL, NULL, 'https://everyayah.com/data/Alafasy_128kbps/026172.mp3', now()),
  (26, 173, '', '[{"id":83207,"position":1,"text_uthmani":"وَأَمْطَرْنَا","transliteration":"wa-amṭarnā","translation_bn":"এবং আমরা বর্ষণ করেছিলাম","root":"مطر","lemma":"أُمْطِرَتْ","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":83208,"position":2,"text_uthmani":"عَلَيْهِم","transliteration":"ʿalayhim","translation_bn":"উপর তাদের","root":"—","lemma":"عَلَىٰ\r","grammar_bn":"অব্যয় (Preposition)"},{"id":83209,"position":3,"text_uthmani":"مَّطَرًۭا ۖ","transliteration":"maṭaran","translation_bn":"এক বর্ষণ (শাস্তিমূলক)","root":"مطر","lemma":"مَّطَر","grammar_bn":"বিশেষ্য (Noun)"},{"id":83211,"position":4,"text_uthmani":"فَسَآءَ","transliteration":"fasāa","translation_bn":"অতএব কত নিকৃষ্ট","root":"سوا","lemma":"سَا^ءَ","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":83212,"position":5,"text_uthmani":"مَطَرُ","transliteration":"maṭaru","translation_bn":"বর্ষণ","root":"مطر","lemma":"مَّطَر","grammar_bn":"বিশেষ্য (Noun)"},{"id":83213,"position":6,"text_uthmani":"ٱلْمُنذَرِينَ","transliteration":"l-mundharīna","translation_bn":"সতর্ককৃতদের (জন্যে)","root":"نذر","lemma":"مُنذَرِين","grammar_bn":"শব্দ"},{"id":83214,"position":7,"text_uthmani":"١٧٣","transliteration":"","translation_bn":"(১৭৩)","root":"—","lemma":"١٧٣","grammar_bn":"মার্কার"}]'::jsonb, 'wa-amṭarnā ʿalayhim maṭaran fasāa maṭaru l-mundharīna', 'তাদের উপর বর্ষণ করলাম (শাস্তির) বৃষ্টি, ভয় প্রদর্শিতদের জন্য এ বৃষ্টি ছিল কতই না মন্দ!', 'And We rained upon them a rain [of stones], and evil was the rain of those who were warned.', 'তাদের উপর বর্ষণ করলাম (শাস্তির) বৃষ্টি, ভয় প্রদর্শিতদের জন্য এ বৃষ্টি ছিল কতই না মন্দ!', 'And We rained upon them a rain [of stones], and evil was the rain of those who were warned.', NULL, NULL, NULL, NULL, NULL, 'https://everyayah.com/data/Alafasy_128kbps/026173.mp3', now()),
  (26, 174, '', '[{"id":83286,"position":1,"text_uthmani":"إِنَّ","transliteration":"inna","translation_bn":"নিশ্চয়ই","root":"—","lemma":"إِنّ","grammar_bn":"অভিঘাত পদ (Accusative)"},{"id":83287,"position":2,"text_uthmani":"فِى","transliteration":"fī","translation_bn":"মধ্যে (আছে)","root":"—","lemma":"فِى\r","grammar_bn":"অব্যয় (Preposition)"},{"id":83288,"position":3,"text_uthmani":"ذَٰلِكَ","transliteration":"dhālika","translation_bn":"এর","root":"—","lemma":"ذَٰلِك","grammar_bn":"নির্দেশক সর্বনাম (Demonstrative)"},{"id":83289,"position":4,"text_uthmani":"لَـَٔايَةًۭ ۖ","transliteration":"laāyatan","translation_bn":"অবশ্যই নিদর্শন","root":"ايي","lemma":"ءَايَة","grammar_bn":"দৃঢ়তাবোধক (Emphatic)"},{"id":83291,"position":5,"text_uthmani":"وَمَا","transliteration":"wamā","translation_bn":"আর না","root":"—","lemma":"مَا\r","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":83292,"position":6,"text_uthmani":"كَانَ","transliteration":"kāna","translation_bn":"ছিলো","root":"كون","lemma":"كَانَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":83293,"position":7,"text_uthmani":"أَكْثَرُهُم","transliteration":"aktharuhum","translation_bn":"অধিকাংশই তাদের","root":"كثر","lemma":"أَكْثَر","grammar_bn":"বিশেষ্য (Noun)"},{"id":83294,"position":8,"text_uthmani":"مُّؤْمِنِينَ","transliteration":"mu''minīna","translation_bn":"মু''মিন","root":"امن","lemma":"مُؤْمِن","grammar_bn":"বিশেষ্য (Noun)"},{"id":83295,"position":9,"text_uthmani":"١٧٤","transliteration":"","translation_bn":"(১৭৪)","root":"—","lemma":"١٧٤","grammar_bn":"মার্কার"}]'::jsonb, 'inna fī dhālika laāyatan wamā kāna aktharuhum mu''minīna', 'নিশ্চয়ই এতে নিদর্শন রয়েছে, কিন্তু অধিকাংশই বিশ্বাস করে না।', 'Indeed in that is a sign, but most of them were not to be believers.', 'নিশ্চয়ই এতে নিদর্শন রয়েছে, কিন্তু অধিকাংশই বিশ্বাস করে না।', 'Indeed in that is a sign, but most of them were not to be believers.', NULL, NULL, NULL, NULL, NULL, 'https://everyayah.com/data/Alafasy_128kbps/026174.mp3', now()),
  (26, 175, '', '[{"id":83305,"position":1,"text_uthmani":"وَإِنَّ","transliteration":"wa-inna","translation_bn":"অথচ নিশ্চয়ই","root":"—","lemma":"إِنّ","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":83306,"position":2,"text_uthmani":"رَبَّكَ","transliteration":"rabbaka","translation_bn":"তোমার রব","root":"ربب","lemma":"رَبّ","grammar_bn":"বিশেষ্য (Noun)"},{"id":83307,"position":3,"text_uthmani":"لَهُوَ","transliteration":"lahuwa","translation_bn":"অবশ্যই তিনি","root":"—","lemma":"لَهُوَ","grammar_bn":"দৃঢ়তাবোধক (Emphatic)"},{"id":83308,"position":4,"text_uthmani":"ٱلْعَزِيزُ","transliteration":"l-ʿazīzu","translation_bn":"পরাক্রমশালী","root":"عزز","lemma":"عَزِيز","grammar_bn":"শব্দ"},{"id":83309,"position":5,"text_uthmani":"ٱلرَّحِيمُ","transliteration":"l-raḥīmu","translation_bn":"পরম দয়ালু","root":"رحم","lemma":"رَّحِيم","grammar_bn":"শব্দ"},{"id":83310,"position":6,"text_uthmani":"١٧٥","transliteration":"","translation_bn":"(১৭৫)","root":"—","lemma":"١٧٥","grammar_bn":"মার্কার"}]'::jsonb, 'wa-inna rabbaka lahuwa l-ʿazīzu l-raḥīmu', 'তোমার প্রতিপালক, তিনি মহা প্রতাপশালী, বড়ই দয়ালু।', 'And indeed, your Lord - He is the Exalted in Might, the Merciful.', 'তোমার প্রতিপালক, তিনি মহা প্রতাপশালী, বড়ই দয়ালু।', 'And indeed, your Lord - He is the Exalted in Might, the Merciful.', NULL, NULL, NULL, NULL, NULL, 'https://everyayah.com/data/Alafasy_128kbps/026175.mp3', now()),
  (26, 176, '', '[{"id":83502,"position":1,"text_uthmani":"كَذَّبَ","transliteration":"kadhaba","translation_bn":"মিথ্যারোপ করেছিলো","root":"كذب","lemma":"كَذَّبَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":83503,"position":2,"text_uthmani":"أَصْحَـٰبُ","transliteration":"aṣḥābu","translation_bn":"অধিবাসীরাও","root":"صحب","lemma":"أَصْحَٰب","grammar_bn":"বিশেষ্য (Noun)"},{"id":83504,"position":3,"text_uthmani":"لْـَٔيْكَةِ","transliteration":"al''aykati","translation_bn":"আইকার","root":"—","lemma":"أَيْكَة","grammar_bn":"শব্দ"},{"id":83505,"position":4,"text_uthmani":"ٱلْمُرْسَلِينَ","transliteration":"l-mur''salīna","translation_bn":"রাসূলদেরকে","root":"رسل","lemma":"مُّرْسَل","grammar_bn":"শব্দ"},{"id":83506,"position":5,"text_uthmani":"١٧٦","transliteration":"","translation_bn":"(১৭৬)","root":"—","lemma":"١٧٦","grammar_bn":"মার্কার"}]'::jsonb, 'kadhaba aṣḥābu al''aykati l-mur''salīna', 'বনের অধিবাসীরা রসূলদেরকে মিথ্যে বলে প্রত্যাখ্যান করেছিল।', 'The companions of the thicket denied the messengers', 'বনের অধিবাসীরা রসূলদেরকে মিথ্যে বলে প্রত্যাখ্যান করেছিল।', 'The companions of the thicket denied the messengers', NULL, NULL, NULL, NULL, NULL, 'https://everyayah.com/data/Alafasy_128kbps/026176.mp3', now()),
  (26, 177, '', '[{"id":83507,"position":1,"text_uthmani":"إِذْ","transliteration":"idh","translation_bn":"(স্মরণ করো) যখন","root":"—","lemma":"إِذ\r","grammar_bn":"কালবাচক (Time)"},{"id":83508,"position":2,"text_uthmani":"قَالَ","transliteration":"qāla","translation_bn":"বলেছিলো","root":"قول","lemma":"قَالَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":83509,"position":3,"text_uthmani":"لَهُمْ","transliteration":"lahum","translation_bn":"উদ্দেশ্যে তাদের","root":"—","lemma":"لَهُمْ","grammar_bn":"অব্যয় (Preposition)"},{"id":83510,"position":4,"text_uthmani":"شُعَيْبٌ","transliteration":"shuʿaybun","translation_bn":"শু''আইব","root":"—","lemma":"شُعَيْب","grammar_bn":"নামবাচক বিশেষ্য (Proper Noun)"},{"id":83511,"position":5,"text_uthmani":"أَلَا","transliteration":"alā","translation_bn":"\"কি না","root":"—","lemma":"لَا\r","grammar_bn":"প্রশ্নবোধক (Interrogative)"},{"id":83512,"position":6,"text_uthmani":"تَتَّقُونَ","transliteration":"tattaqūna","translation_bn":"তোমরা ভয় করবে","root":"وقي","lemma":"ٱتَّقَىٰ","grammar_bn":"ক্রিয়া (Verb)"},{"id":83513,"position":7,"text_uthmani":"١٧٧","transliteration":"","translation_bn":"(১৭৭)","root":"—","lemma":"١٧٧","grammar_bn":"মার্কার"}]'::jsonb, 'idh qāla lahum shuʿaybun alā tattaqūna', 'যখন শু‘আয়ব তাদেরকে বলেছিল- ‘তোমরা কি (আল্লাহকে) ভয় করবে না?', 'When Shu''ayb said to them, "Will you not fear Allah?', 'যখন শু‘আয়ব তাদেরকে বলেছিল- ‘তোমরা কি (আল্লাহকে) ভয় করবে না?', 'When Shu''ayb said to them, "Will you not fear Allah?', NULL, NULL, NULL, NULL, NULL, 'https://everyayah.com/data/Alafasy_128kbps/026177.mp3', now()),
  (26, 178, '', '[{"id":83600,"position":1,"text_uthmani":"إِنِّى","transliteration":"innī","translation_bn":"নিশ্চয়ই আমি","root":"—","lemma":"إِنّ","grammar_bn":"অভিঘাত পদ (Accusative)"},{"id":83601,"position":2,"text_uthmani":"لَكُمْ","transliteration":"lakum","translation_bn":"জন্যে তোমাদের","root":"—","lemma":"لَكُمْ","grammar_bn":"অব্যয় (Preposition)"},{"id":83602,"position":3,"text_uthmani":"رَسُولٌ","transliteration":"rasūlun","translation_bn":"একজন রাসূল","root":"رسل","lemma":"رَسُول","grammar_bn":"বিশেষ্য (Noun)"},{"id":83603,"position":4,"text_uthmani":"أَمِينٌۭ","transliteration":"amīnun","translation_bn":"বিশ্বস্ত","root":"امن","lemma":"أَمِين","grammar_bn":"বিশেষণ (Adjective)"},{"id":83604,"position":5,"text_uthmani":"١٧٨","transliteration":"","translation_bn":"(১৭৮)","root":"—","lemma":"١٧٨","grammar_bn":"মার্কার"}]'::jsonb, 'innī lakum rasūlun amīnun', 'আমি তোমাদের জন্য (প্রেরিত) বিশ্বস্ত রাসুল।', 'Indeed, I am to you a trustworthy messenger.', 'আমি তোমাদের জন্য (প্রেরিত) বিশ্বস্ত রাসুল।', 'Indeed, I am to you a trustworthy messenger.', NULL, NULL, NULL, NULL, NULL, 'https://everyayah.com/data/Alafasy_128kbps/026178.mp3', now()),
  (26, 179, '', '[{"id":83733,"position":1,"text_uthmani":"فَٱتَّقُوا۟","transliteration":"fa-ittaqū","translation_bn":"অতঃপর তোমরা ভয় করো","root":"وقي","lemma":"ٱتَّقَىٰ","grammar_bn":"শব্দ"},{"id":83734,"position":2,"text_uthmani":"ٱللَّهَ","transliteration":"l-laha","translation_bn":"আল্লাহকে","root":"اله","lemma":"ٱللَّه","grammar_bn":"নামবাচক বিশেষ্য (Proper Noun)"},{"id":83735,"position":3,"text_uthmani":"وَأَطِيعُونِ","transliteration":"wa-aṭīʿūni","translation_bn":"ও তোমরা আমার আনুগত্য করো","root":"طوع","lemma":"أَطَاعَ","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":83736,"position":4,"text_uthmani":"١٧٩","transliteration":"","translation_bn":"(১৭৯)","root":"—","lemma":"١٧٩","grammar_bn":"মার্কার"}]'::jsonb, 'fa-ittaqū l-laha wa-aṭīʿūni', 'কাজেই তোমরা আল্লাহকে ভয় কর এবং আমাকে মান্য কর।', 'So fear Allah and obey me.', 'কাজেই তোমরা আল্লাহকে ভয় কর এবং আমাকে মান্য কর।', 'So fear Allah and obey me.', NULL, NULL, NULL, NULL, NULL, 'https://everyayah.com/data/Alafasy_128kbps/026179.mp3', now()),
  (26, 180, '', '[{"id":83792,"position":1,"text_uthmani":"وَمَآ","transliteration":"wamā","translation_bn":"আর না","root":"—","lemma":"مَا\r","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":83793,"position":2,"text_uthmani":"أَسْـَٔلُكُمْ","transliteration":"asalukum","translation_bn":"তোমাদের (নিকট) আমি চাচ্ছি","root":"سال","lemma":"سَأَلَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":83794,"position":3,"text_uthmani":"عَلَيْهِ","transliteration":"ʿalayhi","translation_bn":"জন্যে এর","root":"—","lemma":"عَلَىٰ\r","grammar_bn":"অব্যয় (Preposition)"},{"id":83795,"position":4,"text_uthmani":"مِنْ","transliteration":"min","translation_bn":"কোনো","root":"—","lemma":"مِن\r","grammar_bn":"অব্যয় (Preposition)"},{"id":83796,"position":5,"text_uthmani":"أَجْرٍ ۖ","transliteration":"ajrin","translation_bn":"প্রতিদান","root":"اجر","lemma":"أَجْر","grammar_bn":"বিশেষ্য (Noun)"},{"id":83798,"position":6,"text_uthmani":"إِنْ","transliteration":"in","translation_bn":"নেই","root":"—","lemma":"إِن\r","grammar_bn":"না-বোধক (Negative)"},{"id":83799,"position":7,"text_uthmani":"أَجْرِىَ","transliteration":"ajriya","translation_bn":"আমার প্রতিদান (অন্য কারো নিকট)","root":"اجر","lemma":"أَجْر","grammar_bn":"বিশেষ্য (Noun)"},{"id":83800,"position":8,"text_uthmani":"إِلَّا","transliteration":"illā","translation_bn":"ছাড়া","root":"—","lemma":"إِلَّا\r","grammar_bn":"সীমাবদ্ধতা (Restriction)"},{"id":83801,"position":9,"text_uthmani":"عَلَىٰ","transliteration":"ʿalā","translation_bn":"নিকট","root":"—","lemma":"عَلَىٰ\r","grammar_bn":"অব্যয় (Preposition)"},{"id":83802,"position":10,"text_uthmani":"رَبِّ","transliteration":"rabbi","translation_bn":"রবের","root":"ربب","lemma":"رَبّ","grammar_bn":"বিশেষ্য (Noun)"},{"id":83803,"position":11,"text_uthmani":"ٱلْعَـٰلَمِينَ","transliteration":"l-ʿālamīna","translation_bn":"বিশ্বজগতের","root":"علم","lemma":"عَٰلَمِين","grammar_bn":"শব্দ"},{"id":83804,"position":12,"text_uthmani":"١٨٠","transliteration":"","translation_bn":"(১৮০)","root":"—","lemma":"١٨٠","grammar_bn":"মার্কার"}]'::jsonb, 'wamā asalukum ʿalayhi min ajrin in ajriya illā ʿalā rabbi l-ʿālamīna', 'এ জন্য আমি তোমাদের কাছে কোন প্রতিদান চাই না, আমার প্রতিদান তো রয়েছে একমাত্র জগতসমূহের প্রতিপালকের নিকট।', 'And I do not ask you for it any payment. My payment is only from the Lord of the worlds.', 'এ জন্য আমি তোমাদের কাছে কোন প্রতিদান চাই না, আমার প্রতিদান তো রয়েছে একমাত্র জগতসমূহের প্রতিপালকের নিকট।', 'And I do not ask you for it any payment. My payment is only from the Lord of the worlds.', NULL, NULL, NULL, NULL, NULL, 'https://everyayah.com/data/Alafasy_128kbps/026180.mp3', now()),
  (26, 181, '', '[{"id":83914,"position":1,"text_uthmani":"۞ أَوْفُوا۟","transliteration":"awfū","translation_bn":"তোমরা পূর্ণ দাও","root":"وفي","lemma":"أَوْفَىٰ","grammar_bn":"ক্রিয়া (Verb)"},{"id":83915,"position":2,"text_uthmani":"ٱلْكَيْلَ","transliteration":"l-kayla","translation_bn":"মাপ","root":"كيل","lemma":"كَيْل","grammar_bn":"শব্দ"},{"id":83916,"position":3,"text_uthmani":"وَلَا","transliteration":"walā","translation_bn":"ও না","root":"—","lemma":"لَا\r","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":83917,"position":4,"text_uthmani":"تَكُونُوا۟","transliteration":"takūnū","translation_bn":"তোমরা হয়ো","root":"كون","lemma":"كَانَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":83918,"position":5,"text_uthmani":"مِنَ","transliteration":"mina","translation_bn":"অন্তর্ভুক্ত","root":"—","lemma":"مِن\r","grammar_bn":"অব্যয় (Preposition)"},{"id":83919,"position":6,"text_uthmani":"ٱلْمُخْسِرِينَ","transliteration":"l-mukh''sirīna","translation_bn":"মাপে কমদানকারীদের","root":"خسر","lemma":"مُخْسِرِين","grammar_bn":"শব্দ"},{"id":83920,"position":7,"text_uthmani":"١٨١","transliteration":"","translation_bn":"(১৮১)","root":"—","lemma":"١٨١","grammar_bn":"মার্কার"}]'::jsonb, 'awfū l-kayla walā takūnū mina l-mukh''sirīna', 'মাপে পূর্ণ মাত্রায় দাও আর যারা মাপে কম দেয় তাদের অন্তর্ভুক্ত হয়ো না।', 'Give full measure and do not be of those who cause loss.', 'মাপে পূর্ণ মাত্রায় দাও আর যারা মাপে কম দেয় তাদের অন্তর্ভুক্ত হয়ো না।', 'Give full measure and do not be of those who cause loss.', NULL, NULL, NULL, NULL, NULL, 'https://everyayah.com/data/Alafasy_128kbps/026181.mp3', now()),
  (26, 182, '', '[{"id":83943,"position":1,"text_uthmani":"وَزِنُوا۟","transliteration":"wazinū","translation_bn":"এবং তোমরা ওজন করবে","root":"وزن","lemma":"وَّزَنُ","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":83944,"position":2,"text_uthmani":"بِٱلْقِسْطَاسِ","transliteration":"bil-qis''ṭāsi","translation_bn":"দিয়ে দাঁড়িপাল্লা","root":"قسطس","lemma":"قِسْطَاس","grammar_bn":"অব্যয় (Preposition)"},{"id":83945,"position":3,"text_uthmani":"ٱلْمُسْتَقِيمِ","transliteration":"l-mus''taqīmi","translation_bn":"সঠিক","root":"قوم","lemma":"مُّسْتَقِيم","grammar_bn":"শব্দ"},{"id":83946,"position":4,"text_uthmani":"١٨٢","transliteration":"","translation_bn":"(১৮২)","root":"—","lemma":"١٨٢","grammar_bn":"মার্কার"}]'::jsonb, 'wazinū bil-qis''ṭāsi l-mus''taqīmi', 'সঠিক দাঁড়িপাল্লায় ওজন করবে।', 'And weigh with an even balance.', 'সঠিক দাঁড়িপাল্লায় ওজন করবে।', 'And weigh with an even balance.', NULL, NULL, NULL, NULL, NULL, 'https://everyayah.com/data/Alafasy_128kbps/026182.mp3', now()),
  (26, 183, '', '[{"id":84016,"position":1,"text_uthmani":"وَلَا","transliteration":"walā","translation_bn":"আর না","root":"—","lemma":"لَا\r","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":84017,"position":2,"text_uthmani":"تَبْخَسُوا۟","transliteration":"tabkhasū","translation_bn":"তোমরা কম দিবে","root":"بخس","lemma":"يَبْخَسْ","grammar_bn":"ক্রিয়া (Verb)"},{"id":84018,"position":3,"text_uthmani":"ٱلنَّاسَ","transliteration":"l-nāsa","translation_bn":"মানুষকে","root":"نوس","lemma":"نَّاس","grammar_bn":"শব্দ"},{"id":84019,"position":4,"text_uthmani":"أَشْيَآءَهُمْ","transliteration":"ashyāahum","translation_bn":"জিনিসগুলোকে তাদের","root":"شيا","lemma":"شَىْء","grammar_bn":"বিশেষ্য (Noun)"},{"id":84020,"position":5,"text_uthmani":"وَلَا","transliteration":"walā","translation_bn":"আর না","root":"—","lemma":"لَا\r","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":84021,"position":6,"text_uthmani":"تَعْثَوْا۟","transliteration":"taʿthaw","translation_bn":"গোলযোগ সৃষ্টি করো","root":"عثو","lemma":"تَعْثَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":84022,"position":7,"text_uthmani":"فِى","transliteration":"fī","translation_bn":"মধ্যে","root":"—","lemma":"فِى\r","grammar_bn":"অব্যয় (Preposition)"},{"id":84023,"position":8,"text_uthmani":"ٱلْأَرْضِ","transliteration":"l-arḍi","translation_bn":"পৃথিবীর","root":"ارض","lemma":"أَرْض","grammar_bn":"শব্দ"},{"id":84024,"position":9,"text_uthmani":"مُفْسِدِينَ","transliteration":"muf''sidīna","translation_bn":"বিপর্যয় সৃষ্টিকারী হিসেবে","root":"فسد","lemma":"مُفْسِد","grammar_bn":"বিশেষ্য (Noun)"},{"id":84025,"position":10,"text_uthmani":"١٨٣","transliteration":"","translation_bn":"(১৮৩)","root":"—","lemma":"١٨٣","grammar_bn":"মার্কার"}]'::jsonb, 'walā tabkhasū l-nāsa ashyāahum walā taʿthaw fī l-arḍi muf''sidīna', 'মানুষকে তাদের প্রাপ্যবস্তু কম দিবে না। আর পৃথিবীতে বিশৃঙ্খলা সৃষ্টি করো না।', 'And do not deprive people of their due and do not commit abuse on earth, spreading corruption.', 'মানুষকে তাদের প্রাপ্যবস্তু কম দিবে না। আর পৃথিবীতে বিশৃঙ্খলা সৃষ্টি করো না।', 'And do not deprive people of their due and do not commit abuse on earth, spreading corruption.', NULL, NULL, NULL, NULL, NULL, 'https://everyayah.com/data/Alafasy_128kbps/026183.mp3', now()),
  (26, 184, '', '[{"id":84033,"position":1,"text_uthmani":"وَٱتَّقُوا۟","transliteration":"wa-ittaqū","translation_bn":"এবং তোমরা ভয় করো","root":"وقي","lemma":"ٱتَّقَىٰ","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":84034,"position":2,"text_uthmani":"ٱلَّذِى","transliteration":"alladhī","translation_bn":"(তাঁকে) যিনি","root":"—","lemma":"ٱلَّذِى","grammar_bn":"সাপেক্ষ সর্বনাম (Relative)"},{"id":84035,"position":3,"text_uthmani":"خَلَقَكُمْ","transliteration":"khalaqakum","translation_bn":"সৃষ্টি করেছেন তোমাদেরকে","root":"خلق","lemma":"خَلَقَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":84036,"position":4,"text_uthmani":"وَٱلْجِبِلَّةَ","transliteration":"wal-jibilata","translation_bn":"জনগোষ্ঠীকেও","root":"جبل","lemma":"جِبِلَّة","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":84037,"position":5,"text_uthmani":"ٱلْأَوَّلِينَ","transliteration":"l-awalīna","translation_bn":"পুর্ববর্তী\"","root":"اول","lemma":"أَوَّل","grammar_bn":"শব্দ"},{"id":84038,"position":6,"text_uthmani":"١٨٤","transliteration":"","translation_bn":"(১৮৪)","root":"—","lemma":"١٨٤","grammar_bn":"মার্কার"}]'::jsonb, 'wa-ittaqū alladhī khalaqakum wal-jibilata l-awalīna', 'এবং ভয় কর তাঁকে যিনি তোমাদেরকে এবং তোমাদের পূর্ববর্তী বংশাবলীকে সৃষ্টি করেছেন।’', 'And fear He who created you and the former creation."', 'এবং ভয় কর তাঁকে যিনি তোমাদেরকে এবং তোমাদের পূর্ববর্তী বংশাবলীকে সৃষ্টি করেছেন।’', 'And fear He who created you and the former creation."', NULL, NULL, NULL, NULL, NULL, 'https://everyayah.com/data/Alafasy_128kbps/026184.mp3', now()),
  (26, 185, '', '[{"id":84179,"position":1,"text_uthmani":"قَالُوٓا۟","transliteration":"qālū","translation_bn":"তারা বলেছিলো","root":"قول","lemma":"قَالَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":84180,"position":2,"text_uthmani":"إِنَّمَآ","transliteration":"innamā","translation_bn":"\"মূলতঃ","root":"—","lemma":"إِنّ","grammar_bn":"অভিঘাত পদ (Accusative)"},{"id":84181,"position":3,"text_uthmani":"أَنتَ","transliteration":"anta","translation_bn":"তুমি","root":"—","lemma":"أَنتَ","grammar_bn":"সর্বনাম (Pronoun)"},{"id":84182,"position":4,"text_uthmani":"مِنَ","transliteration":"mina","translation_bn":"অন্তর্ভুক্ত","root":"—","lemma":"مِن\r","grammar_bn":"অব্যয় (Preposition)"},{"id":84183,"position":5,"text_uthmani":"ٱلْمُسَحَّرِينَ","transliteration":"l-musaḥarīna","translation_bn":"জাদুগ্রস্তদের","root":"سحر","lemma":"مُسَحَّرِين","grammar_bn":"শব্দ"},{"id":84184,"position":6,"text_uthmani":"١٨٥","transliteration":"","translation_bn":"(১৮৫)","root":"—","lemma":"١٨٥","grammar_bn":"মার্কার"}]'::jsonb, 'qālū innamā anta mina l-musaḥarīna', 'তারা বলল- ‘তুমি তো কেবল যাদুগ্রস্তদের একজন।', 'They said, "You are only of those affected by magic.', 'তারা বলল- ‘তুমি তো কেবল যাদুগ্রস্তদের একজন।', 'They said, "You are only of those affected by magic.', NULL, NULL, NULL, NULL, NULL, 'https://everyayah.com/data/Alafasy_128kbps/026185.mp3', now()),
  (26, 186, '', '[{"id":84236,"position":1,"text_uthmani":"وَمَآ","transliteration":"wamā","translation_bn":"আর না","root":"—","lemma":"مَا\r","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":84237,"position":2,"text_uthmani":"أَنتَ","transliteration":"anta","translation_bn":"তুমি","root":"—","lemma":"أَنتَ","grammar_bn":"সর্বনাম (Pronoun)"},{"id":84238,"position":3,"text_uthmani":"إِلَّا","transliteration":"illā","translation_bn":"এ ছাড়া","root":"—","lemma":"إِلَّا\r","grammar_bn":"সীমাবদ্ধতা (Restriction)"},{"id":84239,"position":4,"text_uthmani":"بَشَرٌۭ","transliteration":"basharun","translation_bn":"একজন মানুষ","root":"بشر","lemma":"بَشَر","grammar_bn":"বিশেষ্য (Noun)"},{"id":84240,"position":5,"text_uthmani":"مِّثْلُنَا","transliteration":"mith''lunā","translation_bn":"মতো আমাদেরই","root":"مثل","lemma":"مِثْل","grammar_bn":"বিশেষ্য (Noun)"},{"id":84241,"position":6,"text_uthmani":"وَإِن","transliteration":"wa-in","translation_bn":"আর নিশ্চয়ই","root":"—","lemma":"إِن\r","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":84242,"position":7,"text_uthmani":"نَّظُنُّكَ","transliteration":"naẓunnuka","translation_bn":"তোমাকে আমরা মনেকরি","root":"ظنن","lemma":"ظَنَّ","grammar_bn":"ক্রিয়া (Verb)"},{"id":84243,"position":8,"text_uthmani":"لَمِنَ","transliteration":"lamina","translation_bn":"অবশ্যই অন্তর্ভুক্ত","root":"—","lemma":"مِن\r","grammar_bn":"দৃঢ়তাবোধক (Emphatic)"},{"id":84244,"position":9,"text_uthmani":"ٱلْكَـٰذِبِينَ","transliteration":"l-kādhibīna","translation_bn":"মিথ্যাবাদীদের","root":"كذب","lemma":"كَٰذِب","grammar_bn":"শব্দ"},{"id":84245,"position":10,"text_uthmani":"١٨٦","transliteration":"","translation_bn":"(১৮৬)","root":"—","lemma":"١٨٦","grammar_bn":"মার্কার"}]'::jsonb, 'wamā anta illā basharun mith''lunā wa-in naẓunnuka lamina l-kādhibīna', 'তুমি আমাদের মতই মানুষ বৈ নও, আমরা মনে করি তুমি অবশ্য মিথ্যাবাদীদের অন্তর্ভুক্ত।', 'You are but a man like ourselves, and indeed, we think you are among the liars.', 'তুমি আমাদের মতই মানুষ বৈ নও, আমরা মনে করি তুমি অবশ্য মিথ্যাবাদীদের অন্তর্ভুক্ত।', 'You are but a man like ourselves, and indeed, we think you are among the liars.', NULL, NULL, NULL, NULL, NULL, 'https://everyayah.com/data/Alafasy_128kbps/026186.mp3', now()),
  (26, 187, '', '[{"id":84278,"position":1,"text_uthmani":"فَأَسْقِطْ","transliteration":"fa-asqiṭ","translation_bn":"অতএব ফেলে দাও","root":"سقط","lemma":"تُسْقِطَ","grammar_bn":"শব্দ"},{"id":84279,"position":2,"text_uthmani":"عَلَيْنَا","transliteration":"ʿalaynā","translation_bn":"উপর আমাদের","root":"—","lemma":"عَلَىٰ\r","grammar_bn":"অব্যয় (Preposition)"},{"id":84280,"position":3,"text_uthmani":"كِسَفًۭا","transliteration":"kisafan","translation_bn":"এক টুকরো","root":"كسف","lemma":"كِسَف","grammar_bn":"বিশেষ্য (Noun)"},{"id":84281,"position":4,"text_uthmani":"مِّنَ","transliteration":"mina","translation_bn":"থেকে","root":"—","lemma":"مِن\r","grammar_bn":"অব্যয় (Preposition)"},{"id":84282,"position":5,"text_uthmani":"ٱلسَّمَآءِ","transliteration":"l-samāi","translation_bn":"আকাশের","root":"سمو","lemma":"سَمَا^ء","grammar_bn":"শব্দ"},{"id":84283,"position":6,"text_uthmani":"إِن","transliteration":"in","translation_bn":"যদি","root":"—","lemma":"إِن\r","grammar_bn":"শর্তবাচক (Conditional)"},{"id":84284,"position":7,"text_uthmani":"كُنتَ","transliteration":"kunta","translation_bn":"তুমি হও","root":"كون","lemma":"كَانَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":84285,"position":8,"text_uthmani":"مِنَ","transliteration":"mina","translation_bn":"অন্তর্ভুক্ত","root":"—","lemma":"مِن\r","grammar_bn":"অব্যয় (Preposition)"},{"id":84286,"position":9,"text_uthmani":"ٱلصَّـٰدِقِينَ","transliteration":"l-ṣādiqīna","translation_bn":"সত্যবাদীদের\"","root":"صدق","lemma":"صَادِق","grammar_bn":"শব্দ"},{"id":84287,"position":10,"text_uthmani":"١٨٧","transliteration":"","translation_bn":"(১৮৭)","root":"—","lemma":"١٨٧","grammar_bn":"মার্কার"}]'::jsonb, 'fa-asqiṭ ʿalaynā kisafan mina l-samāi in kunta mina l-ṣādiqīna', 'তুমি সত্যবাদী হলে আকাশের এক টুকরো আমাদের উপর ফেলে দাও।’', 'So cause to fall upon us fragments of the sky, if you should be of the truthful."', 'তুমি সত্যবাদী হলে আকাশের এক টুকরো আমাদের উপর ফেলে দাও।’', 'So cause to fall upon us fragments of the sky, if you should be of the truthful."', NULL, NULL, NULL, NULL, NULL, 'https://everyayah.com/data/Alafasy_128kbps/026187.mp3', now()),
  (26, 188, '', '[{"id":84469,"position":1,"text_uthmani":"قَالَ","transliteration":"qāla","translation_bn":"(শু''আইব) বললো","root":"قول","lemma":"قَالَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":84470,"position":2,"text_uthmani":"رَبِّىٓ","transliteration":"rabbī","translation_bn":"\"আমার রব","root":"ربب","lemma":"رَبّ","grammar_bn":"বিশেষ্য (Noun)"},{"id":84471,"position":3,"text_uthmani":"أَعْلَمُ","transliteration":"aʿlamu","translation_bn":"খুব জানেন","root":"علم","lemma":"أَعْلَم","grammar_bn":"বিশেষণ (Adjective)"},{"id":84472,"position":4,"text_uthmani":"بِمَا","transliteration":"bimā","translation_bn":"ঐ বিষয়ে যা","root":"—","lemma":"مَا\r","grammar_bn":"অব্যয় (Preposition)"},{"id":84473,"position":5,"text_uthmani":"تَعْمَلُونَ","transliteration":"taʿmalūna","translation_bn":"তোমরা করছো\"","root":"عمل","lemma":"عَمِلَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":84474,"position":6,"text_uthmani":"١٨٨","transliteration":"","translation_bn":"(১৮৮)","root":"—","lemma":"١٨٨","grammar_bn":"মার্কার"}]'::jsonb, 'qāla rabbī aʿlamu bimā taʿmalūna', 'শু‘আয়ব বলল- ‘তোমরা যা কর, আমার প্রতিপালক সে সম্পর্কে বেশি অবগত।’', 'He said, "My Lord is most knowing of what you do."', 'শু‘আয়ব বলল- ‘তোমরা যা কর, আমার প্রতিপালক সে সম্পর্কে বেশি অবগত।’', 'He said, "My Lord is most knowing of what you do."', NULL, NULL, NULL, NULL, NULL, 'https://everyayah.com/data/Alafasy_128kbps/026188.mp3', now()),
  (26, 189, '', '[{"id":84583,"position":1,"text_uthmani":"فَكَذَّبُوهُ","transliteration":"fakadhabūhu","translation_bn":"অতঃপর তারা তাকে মিথ্যা সাব্যস্ত করলো","root":"كذب","lemma":"كَذَّبَ","grammar_bn":"শব্দ"},{"id":84584,"position":2,"text_uthmani":"فَأَخَذَهُمْ","transliteration":"fa-akhadhahum","translation_bn":"তখন ধরলো তাদেরকে","root":"اخذ","lemma":"أَخَذَ","grammar_bn":"শব্দ"},{"id":84585,"position":3,"text_uthmani":"عَذَابُ","transliteration":"ʿadhābu","translation_bn":"শাস্তি","root":"عذب","lemma":"عَذَاب","grammar_bn":"বিশেষ্য (Noun)"},{"id":84586,"position":4,"text_uthmani":"يَوْمِ","transliteration":"yawmi","translation_bn":"দিনের","root":"يوم","lemma":"يَوْم","grammar_bn":"বিশেষ্য (Noun)"},{"id":84587,"position":5,"text_uthmani":"ٱلظُّلَّةِ ۚ","transliteration":"l-ẓulati","translation_bn":"(ছায়াওয়ালা) মেঘাচ্ছন্ন","root":"ظلل","lemma":"ظُلَّة","grammar_bn":"শব্দ"},{"id":84589,"position":6,"text_uthmani":"إِنَّهُۥ","transliteration":"innahu","translation_bn":"নিশ্চয়ই তা","root":"—","lemma":"إِنّ","grammar_bn":"অভিঘাত পদ (Accusative)"},{"id":84590,"position":7,"text_uthmani":"كَانَ","transliteration":"kāna","translation_bn":"ছিলো","root":"كون","lemma":"كَانَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":84591,"position":8,"text_uthmani":"عَذَابَ","transliteration":"ʿadhāba","translation_bn":"শাস্তি","root":"عذب","lemma":"عَذَاب","grammar_bn":"বিশেষ্য (Noun)"},{"id":84592,"position":9,"text_uthmani":"يَوْمٍ","transliteration":"yawmin","translation_bn":"দিনের","root":"يوم","lemma":"يَوْم","grammar_bn":"বিশেষ্য (Noun)"},{"id":84593,"position":10,"text_uthmani":"عَظِيمٍ","transliteration":"ʿaẓīmin","translation_bn":"ভয়াবহ","root":"عظم","lemma":"عَظِيم","grammar_bn":"বিশেষণ (Adjective)"},{"id":84594,"position":11,"text_uthmani":"١٨٩","transliteration":"","translation_bn":"(১৮৯)","root":"—","lemma":"١٨٩","grammar_bn":"মার্কার"}]'::jsonb, 'fakadhabūhu fa-akhadhahum ʿadhābu yawmi l-ẓulati innahu kāna ʿadhāba yawmin ʿaẓīmin', 'কিন্তু তারা তাকে প্রত্যাখ্যান করল। ফলে তাদেরকে এক মেঘাচ্ছন্ন দিবসের শাস্তি পাকড়াও করল। তা ছিল এক মহা দিবসের ‘আযাব।', 'And they denied him, so the punishment of the day of the black cloud seized them. Indeed, it was the punishment of a terrible day.', 'কিন্তু তারা তাকে প্রত্যাখ্যান করল। ফলে তাদেরকে এক মেঘাচ্ছন্ন দিবসের শাস্তি পাকড়াও করল। তা ছিল এক মহা দিবসের ‘আযাব।', 'And they denied him, so the punishment of the day of the black cloud seized them. Indeed, it was the punishment of a terrible day.', NULL, NULL, NULL, NULL, NULL, 'https://everyayah.com/data/Alafasy_128kbps/026189.mp3', now()),
  (26, 190, '', '[{"id":84621,"position":1,"text_uthmani":"إِنَّ","transliteration":"inna","translation_bn":"নিশ্চয়ই","root":"—","lemma":"إِنّ","grammar_bn":"অভিঘাত পদ (Accusative)"},{"id":84622,"position":2,"text_uthmani":"فِى","transliteration":"fī","translation_bn":"মধ্যে (আছে)","root":"—","lemma":"فِى\r","grammar_bn":"অব্যয় (Preposition)"},{"id":84623,"position":3,"text_uthmani":"ذَٰلِكَ","transliteration":"dhālika","translation_bn":"এর","root":"—","lemma":"ذَٰلِك","grammar_bn":"নির্দেশক সর্বনাম (Demonstrative)"},{"id":84624,"position":4,"text_uthmani":"لَـَٔايَةًۭ ۖ","transliteration":"laāyatan","translation_bn":"অবশ্যই নিদর্শন","root":"ايي","lemma":"ءَايَة","grammar_bn":"দৃঢ়তাবোধক (Emphatic)"},{"id":84626,"position":5,"text_uthmani":"وَمَا","transliteration":"wamā","translation_bn":"কিন্তু না","root":"—","lemma":"مَا\r","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":84627,"position":6,"text_uthmani":"كَانَ","transliteration":"kāna","translation_bn":"ছিলো","root":"كون","lemma":"كَانَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":84628,"position":7,"text_uthmani":"أَكْثَرُهُم","transliteration":"aktharuhum","translation_bn":"অধিকাংশ তাদের","root":"كثر","lemma":"أَكْثَر","grammar_bn":"বিশেষ্য (Noun)"},{"id":84629,"position":8,"text_uthmani":"مُّؤْمِنِينَ","transliteration":"mu''minīna","translation_bn":"মু''মিন","root":"امن","lemma":"مُؤْمِن","grammar_bn":"বিশেষ্য (Noun)"},{"id":84630,"position":9,"text_uthmani":"١٩٠","transliteration":"","translation_bn":"(১৯০)","root":"—","lemma":"١٩٠","grammar_bn":"মার্কার"}]'::jsonb, 'inna fī dhālika laāyatan wamā kāna aktharuhum mu''minīna', 'এতে অবশ্যই নিদর্শন রয়েছে। কিন্তু তাদের অধিকাংশই বিশ্বাস করে না।', 'Indeed in that is a sign, but most of them were not to be believers.', 'এতে অবশ্যই নিদর্শন রয়েছে। কিন্তু তাদের অধিকাংশই বিশ্বাস করে না।', 'Indeed in that is a sign, but most of them were not to be believers.', NULL, NULL, NULL, NULL, NULL, 'https://everyayah.com/data/Alafasy_128kbps/026190.mp3', now()),
  (26, 191, '', '[{"id":84698,"position":1,"text_uthmani":"وَإِنَّ","transliteration":"wa-inna","translation_bn":"আর নিশ্চয়ই","root":"—","lemma":"إِنّ","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":84699,"position":2,"text_uthmani":"رَبَّكَ","transliteration":"rabbaka","translation_bn":"তোমার রব","root":"ربب","lemma":"رَبّ","grammar_bn":"বিশেষ্য (Noun)"},{"id":84700,"position":3,"text_uthmani":"لَهُوَ","transliteration":"lahuwa","translation_bn":"অবশ্যই তিনি","root":"—","lemma":"لَهُوَ","grammar_bn":"দৃঢ়তাবোধক (Emphatic)"},{"id":84701,"position":4,"text_uthmani":"ٱلْعَزِيزُ","transliteration":"l-ʿazīzu","translation_bn":"পরাক্রমশালী","root":"عزز","lemma":"عَزِيز","grammar_bn":"শব্দ"},{"id":84702,"position":5,"text_uthmani":"ٱلرَّحِيمُ","transliteration":"l-raḥīmu","translation_bn":"পরম দয়ালু","root":"رحم","lemma":"رَّحِيم","grammar_bn":"শব্দ"},{"id":84703,"position":6,"text_uthmani":"١٩١","transliteration":"","translation_bn":"(১৯১)","root":"—","lemma":"١٩١","grammar_bn":"মার্কার"}]'::jsonb, 'wa-inna rabbaka lahuwa l-ʿazīzu l-raḥīmu', 'আর তোমার প্রতিপালক, তিনি অবশ্যই মহা প্রতাপশালী, বড়ই দয়ালু।', 'And indeed, your Lord - He is the Exalted in Might, the Merciful.', 'আর তোমার প্রতিপালক, তিনি অবশ্যই মহা প্রতাপশালী, বড়ই দয়ালু।', 'And indeed, your Lord - He is the Exalted in Might, the Merciful.', NULL, NULL, NULL, NULL, NULL, 'https://everyayah.com/data/Alafasy_128kbps/026191.mp3', now()),
  (26, 192, '', '[{"id":84732,"position":1,"text_uthmani":"وَإِنَّهُۥ","transliteration":"wa-innahu","translation_bn":"এবং নিশ্চয়ই তা","root":"—","lemma":"إِنّ","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":84733,"position":2,"text_uthmani":"لَتَنزِيلُ","transliteration":"latanzīlu","translation_bn":"অবশ্যই অবতীর্ণ","root":"نزل","lemma":"تَنزِيل","grammar_bn":"দৃঢ়তাবোধক (Emphatic)"},{"id":84734,"position":3,"text_uthmani":"رَبِّ","transliteration":"rabbi","translation_bn":"রবের (পক্ষ হ''তে)","root":"ربب","lemma":"رَبّ","grammar_bn":"বিশেষ্য (Noun)"},{"id":84735,"position":4,"text_uthmani":"ٱلْعَـٰلَمِينَ","transliteration":"l-ʿālamīna","translation_bn":"বিশ্বজগতের","root":"علم","lemma":"عَٰلَمِين","grammar_bn":"শব্দ"},{"id":84736,"position":5,"text_uthmani":"١٩٢","transliteration":"","translation_bn":"(১৯২)","root":"—","lemma":"١٩٢","grammar_bn":"মার্কার"}]'::jsonb, 'wa-innahu latanzīlu rabbi l-ʿālamīna', 'অবশ্যই এ কুরআন জগতসমূহের প্রতিপালকের নিকট হতে অবতীর্ণ।', 'And indeed, the Qur''an is the revelation of the Lord of the worlds.', 'অবশ্যই এ কুরআন জগতসমূহের প্রতিপালকের নিকট হতে অবতীর্ণ।', 'And indeed, the Qur''an is the revelation of the Lord of the worlds.', NULL, NULL, NULL, NULL, NULL, 'https://everyayah.com/data/Alafasy_128kbps/026192.mp3', now()),
  (26, 193, '', '[{"id":84745,"position":1,"text_uthmani":"نَزَلَ","transliteration":"nazala","translation_bn":"অবতরণ করেছে","root":"نزل","lemma":"نَزَلَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":84746,"position":2,"text_uthmani":"بِهِ","transliteration":"bihi","translation_bn":"নিয়ে তা","root":"—","lemma":"بِهِ","grammar_bn":"অব্যয় (Preposition)"},{"id":84747,"position":3,"text_uthmani":"ٱلرُّوحُ","transliteration":"l-rūḥu","translation_bn":"রূহ (জিবরাঈল)","root":"روح","lemma":"رُوح","grammar_bn":"শব্দ"},{"id":84748,"position":4,"text_uthmani":"ٱلْأَمِينُ","transliteration":"l-amīnu","translation_bn":"বিশ্বস্ত","root":"امن","lemma":"أَمِين","grammar_bn":"শব্দ"},{"id":84749,"position":5,"text_uthmani":"١٩٣","transliteration":"","translation_bn":"(১৯৩)","root":"—","lemma":"١٩٣","grammar_bn":"মার্কার"}]'::jsonb, 'nazala bihi l-rūḥu l-amīnu', 'বিশ্বস্ত আত্মা (জিবরাঈল) একে নিয়ে অবতরণ করেছে', 'The Trustworthy Spirit has brought it down', 'বিশ্বস্ত আত্মা (জিবরাঈল) একে নিয়ে অবতরণ করেছে', 'The Trustworthy Spirit has brought it down', NULL, NULL, NULL, NULL, NULL, 'https://everyayah.com/data/Alafasy_128kbps/026193.mp3', now()),
  (26, 194, '', '[{"id":84803,"position":1,"text_uthmani":"عَلَىٰ","transliteration":"ʿalā","translation_bn":"উপর","root":"—","lemma":"عَلَىٰ\r","grammar_bn":"অব্যয় (Preposition)"},{"id":84804,"position":2,"text_uthmani":"قَلْبِكَ","transliteration":"qalbika","translation_bn":"তোমার অন্তরের","root":"قلب","lemma":"قَلْب","grammar_bn":"বিশেষ্য (Noun)"},{"id":84805,"position":3,"text_uthmani":"لِتَكُونَ","transliteration":"litakūna","translation_bn":"যেন তুমি হও","root":"كون","lemma":"كَانَ","grammar_bn":"শব্দ"},{"id":84806,"position":4,"text_uthmani":"مِنَ","transliteration":"mina","translation_bn":"অন্তর্ভুক্ত","root":"—","lemma":"مِن\r","grammar_bn":"অব্যয় (Preposition)"},{"id":84807,"position":5,"text_uthmani":"ٱلْمُنذِرِينَ","transliteration":"l-mundhirīna","translation_bn":"সতর্ককারীদের","root":"نذر","lemma":"مُنذِر","grammar_bn":"শব্দ"},{"id":84808,"position":6,"text_uthmani":"١٩٤","transliteration":"","translation_bn":"(১৯৪)","root":"—","lemma":"١٩٤","grammar_bn":"মার্কার"}]'::jsonb, 'ʿalā qalbika litakūna mina l-mundhirīna', 'তোমার অন্তরে যাতে তুমি সতর্ককারীদের অন্তর্ভুক্ত হও।', 'Upon your heart, [O Muhammad] - that you may be of the warners -', 'তোমার অন্তরে যাতে তুমি সতর্ককারীদের অন্তর্ভুক্ত হও।', 'Upon your heart, [O Muhammad] - that you may be of the warners -', NULL, NULL, NULL, NULL, NULL, 'https://everyayah.com/data/Alafasy_128kbps/026194.mp3', now()),
