  (26, 196, '', '[{"id":84965,"position":1,"text_uthmani":"وَإِنَّهُۥ","transliteration":"wa-innahu","translation_bn":"এবং নিশ্চয়ই তা","root":"—","lemma":"إِنّ","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":84966,"position":2,"text_uthmani":"لَفِى","transliteration":"lafī","translation_bn":"অবশ্যই মধ্যে (আছে)","root":"—","lemma":"فِى\r","grammar_bn":"দৃঢ়তাবোধক (Emphatic)"},{"id":84967,"position":3,"text_uthmani":"زُبُرِ","transliteration":"zuburi","translation_bn":"কিতাবসমূহের","root":"زبر","lemma":"زُبُر","grammar_bn":"বিশেষ্য (Noun)"},{"id":84968,"position":4,"text_uthmani":"ٱلْأَوَّلِينَ","transliteration":"l-awalīna","translation_bn":"পুর্ববর্তী","root":"اول","lemma":"أَوَّل","grammar_bn":"শব্দ"},{"id":84969,"position":5,"text_uthmani":"١٩٦","transliteration":"","translation_bn":"(১৯৬)","root":"—","lemma":"١٩٦","grammar_bn":"মার্কার"}]'::jsonb, 'wa-innahu lafī zuburi l-awalīna', 'পূর্ববর্তী কিতাবসমূহেও নিশ্চয় এর উল্লেখ আছে।', 'And indeed, it is [mentioned] in the scriptures of former peoples.', 'পূর্ববর্তী কিতাবসমূহেও নিশ্চয় এর উল্লেখ আছে।', 'And indeed, it is [mentioned] in the scriptures of former peoples.', NULL, NULL, NULL, NULL, NULL, 'https://everyayah.com/data/Alafasy_128kbps/026196.mp3', now()),
  (26, 197, '', '[{"id":85116,"position":1,"text_uthmani":"أَوَلَمْ","transliteration":"awalam","translation_bn":"কি নি","root":"—","lemma":"لَم\r","grammar_bn":"প্রশ্নবোধক (Interrogative)"},{"id":85117,"position":2,"text_uthmani":"يَكُن","transliteration":"yakun","translation_bn":"হয়","root":"كون","lemma":"كَانَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":85118,"position":3,"text_uthmani":"لَّهُمْ","transliteration":"lahum","translation_bn":"জন্যে তাদের","root":"—","lemma":"لَّهُمْ","grammar_bn":"অব্যয় (Preposition)"},{"id":85119,"position":4,"text_uthmani":"ءَايَةً","transliteration":"āyatan","translation_bn":"একটি নিদর্শন","root":"ايي","lemma":"ءَايَة","grammar_bn":"বিশেষ্য (Noun)"},{"id":85120,"position":5,"text_uthmani":"أَن","transliteration":"an","translation_bn":"যে","root":"—","lemma":"أَن\r","grammar_bn":"অধীনস্থ যোজক (Subordinating)"},{"id":85121,"position":6,"text_uthmani":"يَعْلَمَهُۥ","transliteration":"yaʿlamahu","translation_bn":"তা জানে","root":"علم","lemma":"عَلِمَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":85122,"position":7,"text_uthmani":"عُلَمَـٰٓؤُا۟","transliteration":"ʿulamāu","translation_bn":"পন্ডিতরা","root":"علم","lemma":"عَلِيم","grammar_bn":"বিশেষ্য (Noun)"},{"id":85123,"position":8,"text_uthmani":"بَنِىٓ","transliteration":"banī","translation_bn":"বনী","root":"بني","lemma":"بُنَىّ","grammar_bn":"বিশেষ্য (Noun)"},{"id":85124,"position":9,"text_uthmani":"إِسْرَٰٓءِيلَ","transliteration":"is''rāīla","translation_bn":"ইসরাঈলের","root":"—","lemma":"إِسْرَائِيل","grammar_bn":"নামবাচক বিশেষ্য (Proper Noun)"},{"id":85125,"position":10,"text_uthmani":"١٩٧","transliteration":"","translation_bn":"(১৯৭)","root":"—","lemma":"١٩٧","grammar_bn":"মার্কার"}]'::jsonb, 'awalam yakun lahum āyatan an yaʿlamahu ʿulamāu banī is''rāīla', 'এটা কি তাদের জন্য নিদর্শন নয় যে, বানী ইসরাঈলের পন্ডিতগণ তা জানত (যে তা সত্য)।', 'And has it not been a sign to them that it is recognized by the scholars of the Children of Israel?', 'এটা কি তাদের জন্য নিদর্শন নয় যে, বানী ইসরাঈলের পন্ডিতগণ তা জানত (যে তা সত্য)।', 'And has it not been a sign to them that it is recognized by the scholars of the Children of Israel?', NULL, NULL, NULL, NULL, NULL, 'https://everyayah.com/data/Alafasy_128kbps/026197.mp3', now()),
  (26, 198, '', '[{"id":85187,"position":1,"text_uthmani":"وَلَوْ","transliteration":"walaw","translation_bn":"আর যদি","root":"—","lemma":"لَو\r","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":85188,"position":2,"text_uthmani":"نَزَّلْنَـٰهُ","transliteration":"nazzalnāhu","translation_bn":"তা আমরা অবতীর্ণ করতাম","root":"نزل","lemma":"نَزَّلَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":85189,"position":3,"text_uthmani":"عَلَىٰ","transliteration":"ʿalā","translation_bn":"উপর","root":"—","lemma":"عَلَىٰ\r","grammar_bn":"অব্যয় (Preposition)"},{"id":85190,"position":4,"text_uthmani":"بَعْضِ","transliteration":"baʿḍi","translation_bn":"কারোও","root":"بعض","lemma":"بَعْض","grammar_bn":"বিশেষ্য (Noun)"},{"id":85191,"position":5,"text_uthmani":"ٱلْأَعْجَمِينَ","transliteration":"l-aʿjamīna","translation_bn":"অনারবদের","root":"عجم","lemma":"أَعْجَمِين","grammar_bn":"শব্দ"},{"id":85192,"position":6,"text_uthmani":"١٩٨","transliteration":"","translation_bn":"(১৯৮)","root":"—","lemma":"١٩٨","grammar_bn":"মার্কার"}]'::jsonb, 'walaw nazzalnāhu ʿalā baʿḍi l-aʿjamīna', 'আমি যদি তা কোন অনারবের প্রতি অবতীর্ণ করতাম,', 'And even if We had revealed it to one among the foreigners', 'আমি যদি তা কোন অনারবের প্রতি অবতীর্ণ করতাম,', 'And even if We had revealed it to one among the foreigners', NULL, NULL, NULL, NULL, NULL, 'https://everyayah.com/data/Alafasy_128kbps/026198.mp3', now()),
  (26, 199, '', '[{"id":85262,"position":1,"text_uthmani":"فَقَرَأَهُۥ","transliteration":"faqara-ahu","translation_bn":"অতঃপর পাঠ করতো তা","root":"قرا","lemma":"قَرَأَ","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":85263,"position":2,"text_uthmani":"عَلَيْهِم","transliteration":"ʿalayhim","translation_bn":"কাছে তাদের","root":"—","lemma":"عَلَىٰ\r","grammar_bn":"অব্যয় (Preposition)"},{"id":85264,"position":3,"text_uthmani":"مَّا","transliteration":"mā","translation_bn":"না","root":"—","lemma":"مَا\r","grammar_bn":"না-বোধক (Negative)"},{"id":85265,"position":4,"text_uthmani":"كَانُوا۟","transliteration":"kānū","translation_bn":"তারা হতো","root":"كون","lemma":"كَانَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":85266,"position":5,"text_uthmani":"بِهِۦ","transliteration":"bihi","translation_bn":"প্রতি তার","root":"—","lemma":"بِهِۦ","grammar_bn":"অব্যয় (Preposition)"},{"id":85267,"position":6,"text_uthmani":"مُؤْمِنِينَ","transliteration":"mu''minīna","translation_bn":"মু''মিন","root":"امن","lemma":"مُؤْمِن","grammar_bn":"বিশেষ্য (Noun)"},{"id":85268,"position":7,"text_uthmani":"١٩٩","transliteration":"","translation_bn":"(১৯৯)","root":"—","lemma":"١٩٩","grammar_bn":"মার্কার"}]'::jsonb, 'faqara-ahu ʿalayhim mā kānū bihi mu''minīna', 'অতঃপর সে তা তাদের নিকট পাঠ করত, তাহলে তারা তাতে বিশ্বাস আনত না।', 'And he had recited it to them [perfectly], they would [still] not have been believers in it.', 'অতঃপর সে তা তাদের নিকট পাঠ করত, তাহলে তারা তাতে বিশ্বাস আনত না।', 'And he had recited it to them [perfectly], they would [still] not have been believers in it.', NULL, NULL, NULL, NULL, NULL, 'https://everyayah.com/data/Alafasy_128kbps/026199.mp3', now()),
  (26, 200, '', '[{"id":85269,"position":1,"text_uthmani":"كَذَٰلِكَ","transliteration":"kadhālika","translation_bn":"এরূপেই","root":"—","lemma":"ذَٰلِك","grammar_bn":"অব্যয় (Preposition)"},{"id":85270,"position":2,"text_uthmani":"سَلَكْنَـٰهُ","transliteration":"salaknāhu","translation_bn":"তা আমরা সঞ্চার করেছি","root":"سلك","lemma":"سَلَكَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":85271,"position":3,"text_uthmani":"فِى","transliteration":"fī","translation_bn":"মধ্যে","root":"—","lemma":"فِى\r","grammar_bn":"অব্যয় (Preposition)"},{"id":85272,"position":4,"text_uthmani":"قُلُوبِ","transliteration":"qulūbi","translation_bn":"অন্তরসমূহের","root":"قلب","lemma":"قَلْب","grammar_bn":"বিশেষ্য (Noun)"},{"id":85273,"position":5,"text_uthmani":"ٱلْمُجْرِمِينَ","transliteration":"l-muj''rimīna","translation_bn":"অপরাধীদের","root":"جرم","lemma":"مُجْرِم","grammar_bn":"শব্দ"},{"id":85274,"position":6,"text_uthmani":"٢٠٠","transliteration":"","translation_bn":"(২০০)","root":"—","lemma":"٢٠٠","grammar_bn":"মার্কার"}]'::jsonb, 'kadhālika salaknāhu fī qulūbi l-muj''rimīna', 'এভাবে আমি অপরাধীদের অন্তরে অবিশ্বাস সঞ্চার করেছি।', 'Thus have We inserted disbelief into the hearts of the criminals.', 'এভাবে আমি অপরাধীদের অন্তরে অবিশ্বাস সঞ্চার করেছি।', 'Thus have We inserted disbelief into the hearts of the criminals.', NULL, NULL, NULL, NULL, NULL, 'https://everyayah.com/data/Alafasy_128kbps/026200.mp3', now()),
  (26, 201, '', '[{"id":85352,"position":1,"text_uthmani":"لَا","transliteration":"lā","translation_bn":"না","root":"—","lemma":"لَا\r","grammar_bn":"না-বোধক (Negative)"},{"id":85353,"position":2,"text_uthmani":"يُؤْمِنُونَ","transliteration":"yu''minūna","translation_bn":"তারা ঈমান আনবে","root":"امن","lemma":"ءَامَنَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":85354,"position":3,"text_uthmani":"بِهِۦ","transliteration":"bihi","translation_bn":"প্রতি তার","root":"—","lemma":"بِهِۦ","grammar_bn":"অব্যয় (Preposition)"},{"id":85355,"position":4,"text_uthmani":"حَتَّىٰ","transliteration":"ḥattā","translation_bn":"যতক্ষণ না","root":"—","lemma":"حَتَّىٰ\r","grammar_bn":"অব্যয় (Preposition)"},{"id":85356,"position":5,"text_uthmani":"يَرَوُا۟","transliteration":"yarawū","translation_bn":"তারা দেখবে","root":"راي","lemma":"رَءَا","grammar_bn":"ক্রিয়া (Verb)"},{"id":85357,"position":6,"text_uthmani":"ٱلْعَذَابَ","transliteration":"l-ʿadhāba","translation_bn":"শাস্তি","root":"عذب","lemma":"عَذَاب","grammar_bn":"শব্দ"},{"id":85358,"position":7,"text_uthmani":"ٱلْأَلِيمَ","transliteration":"l-alīma","translation_bn":"নিদারুণ","root":"الم","lemma":"أَلِيم","grammar_bn":"শব্দ"},{"id":85359,"position":8,"text_uthmani":"٢٠١","transliteration":"","translation_bn":"(২০১)","root":"—","lemma":"٢٠١","grammar_bn":"মার্কার"}]'::jsonb, 'lā yu''minūna bihi ḥattā yarawū l-ʿadhāba l-alīma', 'তারা এর প্রতি ঈমান আনবে না যতক্ষণ না তারা ভয়াবহ শাস্তি প্রত্যক্ষ করে।', 'They will not believe in it until they see the painful punishment.', 'তারা এর প্রতি ঈমান আনবে না যতক্ষণ না তারা ভয়াবহ শাস্তি প্রত্যক্ষ করে।', 'They will not believe in it until they see the painful punishment.', NULL, NULL, NULL, NULL, NULL, 'https://everyayah.com/data/Alafasy_128kbps/026201.mp3', now()),
  (26, 202, '', '[{"id":85370,"position":1,"text_uthmani":"فَيَأْتِيَهُم","transliteration":"fayatiyahum","translation_bn":"অতঃপর তাদের (উপর) এসে পড়বে","root":"اتي","lemma":"أَتَى","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":85371,"position":2,"text_uthmani":"بَغْتَةًۭ","transliteration":"baghtatan","translation_bn":"হঠাৎ করে","root":"بغت","lemma":"بَغْتَة","grammar_bn":"বিশেষ্য (Noun)"},{"id":85372,"position":3,"text_uthmani":"وَهُمْ","transliteration":"wahum","translation_bn":"এমতাবস্হায় যে তারা","root":"—","lemma":"وَهُمْ","grammar_bn":"অবস্থাবাচক (Circumstantial)"},{"id":85373,"position":4,"text_uthmani":"لَا","transliteration":"lā","translation_bn":"না","root":"—","lemma":"لَا\r","grammar_bn":"না-বোধক (Negative)"},{"id":85374,"position":5,"text_uthmani":"يَشْعُرُونَ","transliteration":"yashʿurūna","translation_bn":"অনুভবও করবে","root":"شعر","lemma":"يَشْعُرُ","grammar_bn":"ক্রিয়া (Verb)"},{"id":85375,"position":6,"text_uthmani":"٢٠٢","transliteration":"","translation_bn":"(২০২)","root":"—","lemma":"٢٠٢","grammar_bn":"মার্কার"}]'::jsonb, 'fayatiyahum baghtatan wahum lā yashʿurūna', 'কাজেই তা তাদের কাছে হঠাৎ এসে পড়বে, তারা কিছুই বুঝতে পারবে না।', 'And it will come to them suddenly while they perceive [it] not.', 'কাজেই তা তাদের কাছে হঠাৎ এসে পড়বে, তারা কিছুই বুঝতে পারবে না।', 'And it will come to them suddenly while they perceive [it] not.', NULL, NULL, NULL, NULL, NULL, 'https://everyayah.com/data/Alafasy_128kbps/026202.mp3', now()),
  (26, 203, '', '[{"id":85440,"position":1,"text_uthmani":"فَيَقُولُوا۟","transliteration":"fayaqūlū","translation_bn":"তখন তারা বলবে","root":"قول","lemma":"قَالَ","grammar_bn":"শব্দ"},{"id":85441,"position":2,"text_uthmani":"هَلْ","transliteration":"hal","translation_bn":"\"কি","root":"—","lemma":"هَل\r","grammar_bn":"প্রশ্নবোধক (Interrogative)"},{"id":85442,"position":3,"text_uthmani":"نَحْنُ","transliteration":"naḥnu","translation_bn":"আমরা","root":"—","lemma":"نَحْنُ","grammar_bn":"সর্বনাম (Pronoun)"},{"id":85443,"position":4,"text_uthmani":"مُنظَرُونَ","transliteration":"munẓarūna","translation_bn":"অবকাশপ্রাপ্ত\"","root":"نظر","lemma":"مُنظَرُون","grammar_bn":"বিশেষ্য (Noun)"},{"id":85444,"position":5,"text_uthmani":"٢٠٣","transliteration":"","translation_bn":"(২০৩)","root":"—","lemma":"٢٠٣","grammar_bn":"মার্কার"}]'::jsonb, 'fayaqūlū hal naḥnu munẓarūna', 'তারা তখন বলবে- ‘আমাদেরকে কি অবকাশ দেয়া হবে?’', 'And they will say, "May we be reprieved?"', 'তারা তখন বলবে- ‘আমাদেরকে কি অবকাশ দেয়া হবে?’', 'And they will say, "May we be reprieved?"', NULL, NULL, NULL, NULL, NULL, 'https://everyayah.com/data/Alafasy_128kbps/026203.mp3', now()),
  (26, 204, '', '[{"id":85463,"position":1,"text_uthmani":"أَفَبِعَذَابِنَا","transliteration":"afabiʿadhābinā","translation_bn":"কি তবে শাস্তি সম্পর্কে আমাদের","root":"عذب","lemma":"عَذَاب","grammar_bn":"প্রশ্নবোধক (Interrogative)"},{"id":85464,"position":2,"text_uthmani":"يَسْتَعْجِلُونَ","transliteration":"yastaʿjilūna","translation_bn":"তারা তাড়াহুড়া করছে","root":"عجل","lemma":"ٱسْتَعْجَلَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":85465,"position":3,"text_uthmani":"٢٠٤","transliteration":"","translation_bn":"(২০৪)","root":"—","lemma":"٢٠٤","grammar_bn":"মার্কার"}]'::jsonb, 'afabiʿadhābinā yastaʿjilūna', 'তারা কি আমার শাস্তি দ্রুত কামনা করে?', 'So for Our punishment are they impatient?', 'তারা কি আমার শাস্তি দ্রুত কামনা করে?', 'So for Our punishment are they impatient?', NULL, NULL, NULL, NULL, NULL, 'https://everyayah.com/data/Alafasy_128kbps/026204.mp3', now()),
  (26, 205, '', '[{"id":85475,"position":1,"text_uthmani":"أَفَرَءَيْتَ","transliteration":"afara-ayta","translation_bn":"কি তবে তুমি ভেবে দেখেছো","root":"راي","lemma":"رَءَا","grammar_bn":"প্রশ্নবোধক (Interrogative)"},{"id":85476,"position":2,"text_uthmani":"إِن","transliteration":"in","translation_bn":"যদি","root":"—","lemma":"إِن\r","grammar_bn":"শর্তবাচক (Conditional)"},{"id":85477,"position":3,"text_uthmani":"مَّتَّعْنَـٰهُمْ","transliteration":"mattaʿnāhum","translation_bn":"আমরা ভোগবিলাস করতে দিই তাদেরকে","root":"متع","lemma":"مَّتَّعْ","grammar_bn":"ক্রিয়া (Verb)"},{"id":85478,"position":4,"text_uthmani":"سِنِينَ","transliteration":"sinīna","translation_bn":"(বহু) বছর","root":"سنو","lemma":"سِنِين","grammar_bn":"বিশেষ্য (Noun)"},{"id":85479,"position":5,"text_uthmani":"٢٠٥","transliteration":"","translation_bn":"(২০৫)","root":"—","lemma":"٢٠٥","grammar_bn":"মার্কার"}]'::jsonb, 'afara-ayta in mattaʿnāhum sinīna', 'তুমি কি ভেবে দেখেছ আমি যদি তাদেরকে কতক বছর ভোগ বিলাস করতে দেই,', 'Then have you considered if We gave them enjoyment for years', 'তুমি কি ভেবে দেখেছ আমি যদি তাদেরকে কতক বছর ভোগ বিলাস করতে দেই,', 'Then have you considered if We gave them enjoyment for years', NULL, NULL, NULL, NULL, NULL, 'https://everyayah.com/data/Alafasy_128kbps/026205.mp3', now()),
  (26, 206, '', '[{"id":85513,"position":1,"text_uthmani":"ثُمَّ","transliteration":"thumma","translation_bn":"এরপরও","root":"—","lemma":"ثُمّ\r","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":85514,"position":2,"text_uthmani":"جَآءَهُم","transliteration":"jāahum","translation_bn":"আসে তাদের (নিকট)","root":"جيا","lemma":"جَا^ءَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":85515,"position":3,"text_uthmani":"مَّا","transliteration":"mā","translation_bn":"যা","root":"—","lemma":"مَا\r","grammar_bn":"সাপেক্ষ সর্বনাম (Relative)"},{"id":85516,"position":4,"text_uthmani":"كَانُوا۟","transliteration":"kānū","translation_bn":"তারা ছিলো","root":"كون","lemma":"كَانَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":85517,"position":5,"text_uthmani":"يُوعَدُونَ","transliteration":"yūʿadūna","translation_bn":"তাদেরকে সতর্ক করা হচ্ছে","root":"وعد","lemma":"وَعَدَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":85518,"position":6,"text_uthmani":"٢٠٦","transliteration":"","translation_bn":"(২০৬)","root":"—","lemma":"٢٠٦","grammar_bn":"মার্কার"}]'::jsonb, 'thumma jāahum mā kānū yūʿadūna', 'অতঃপর তাদেরকে যে বিষয়ের ও‘য়াদা দেয়া হত তা তাদের কাছে এসে পড়ে।', 'And then there came to them that which they were promised?', 'অতঃপর তাদেরকে যে বিষয়ের ও‘য়াদা দেয়া হত তা তাদের কাছে এসে পড়ে।', 'And then there came to them that which they were promised?', NULL, NULL, NULL, NULL, NULL, 'https://everyayah.com/data/Alafasy_128kbps/026206.mp3', now()),
  (26, 207, '', '[{"id":85547,"position":1,"text_uthmani":"مَآ","transliteration":"mā","translation_bn":"(তাহ''লেও) কি","root":"—","lemma":"مَا\r","grammar_bn":"না-বোধক (Negative)"},{"id":85548,"position":2,"text_uthmani":"أَغْنَىٰ","transliteration":"aghnā","translation_bn":"উপকারে আসবে","root":"غني","lemma":"أَغْنَىٰ","grammar_bn":"ক্রিয়া (Verb)"},{"id":85549,"position":3,"text_uthmani":"عَنْهُم","transliteration":"ʿanhum","translation_bn":"জন্যে তাদের","root":"—","lemma":"عَن\r","grammar_bn":"অব্যয় (Preposition)"},{"id":85550,"position":4,"text_uthmani":"مَّا","transliteration":"mā","translation_bn":"যা কিছু","root":"—","lemma":"مَا\r","grammar_bn":"সাপেক্ষ সর্বনাম (Relative)"},{"id":85551,"position":5,"text_uthmani":"كَانُوا۟","transliteration":"kānū","translation_bn":"তারা ছিলো","root":"كون","lemma":"كَانَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":85552,"position":6,"text_uthmani":"يُمَتَّعُونَ","transliteration":"yumattaʿūna","translation_bn":"তারা উপভোগ করে","root":"متع","lemma":"مَّتَّعْ","grammar_bn":"ক্রিয়া (Verb)"},{"id":85553,"position":7,"text_uthmani":"٢٠٧","transliteration":"","translation_bn":"(২০৭)","root":"—","lemma":"٢٠٧","grammar_bn":"মার্কার"}]'::jsonb, 'mā aghnā ʿanhum mā kānū yumattaʿūna', 'তখন তাদের বিলাসের সামগ্রী তাদের কোন উপকারে আসবে না।', 'They would not be availed by the enjoyment with which they were provided.', 'তখন তাদের বিলাসের সামগ্রী তাদের কোন উপকারে আসবে না।', 'They would not be availed by the enjoyment with which they were provided.', NULL, NULL, NULL, NULL, NULL, 'https://everyayah.com/data/Alafasy_128kbps/026207.mp3', now()),
  (26, 208, '', '[{"id":85584,"position":1,"text_uthmani":"وَمَآ","transliteration":"wamā","translation_bn":"আর না","root":"—","lemma":"مَا\r","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":85585,"position":2,"text_uthmani":"أَهْلَكْنَا","transliteration":"ahlaknā","translation_bn":"আমরা ধ্বংস করেছি","root":"هلك","lemma":"أَهْلَكَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":85586,"position":3,"text_uthmani":"مِن","transliteration":"min","translation_bn":"কোনো","root":"—","lemma":"مِن\r","grammar_bn":"অব্যয় (Preposition)"},{"id":85587,"position":4,"text_uthmani":"قَرْيَةٍ","transliteration":"qaryatin","translation_bn":"জনপদ","root":"قري","lemma":"قَرْيَة","grammar_bn":"বিশেষ্য (Noun)"},{"id":85588,"position":5,"text_uthmani":"إِلَّا","transliteration":"illā","translation_bn":"এ ছাড়া (যে)","root":"—","lemma":"إِلَّا\r","grammar_bn":"সীমাবদ্ধতা (Restriction)"},{"id":85589,"position":6,"text_uthmani":"لَهَا","transliteration":"lahā","translation_bn":"জন্যে তার (এসেছে)","root":"—","lemma":"لَهَا","grammar_bn":"অব্যয় (Preposition)"},{"id":85590,"position":7,"text_uthmani":"مُنذِرُونَ","transliteration":"mundhirūna","translation_bn":"সতর্ককারীরা","root":"نذر","lemma":"مُنذِر","grammar_bn":"বিশেষ্য (Noun)"},{"id":85591,"position":8,"text_uthmani":"٢٠٨","transliteration":"","translation_bn":"(২০৮)","root":"—","lemma":"٢٠٨","grammar_bn":"মার্কার"}]'::jsonb, 'wamā ahlaknā min qaryatin illā lahā mundhirūna', 'আমি এমন কোন জনপদ ধ্বংস করিনি যার জন্য কোন ভয় প্রদর্শনকারী ছিল না', 'And We did not destroy any city except that it had warners', 'আমি এমন কোন জনপদ ধ্বংস করিনি যার জন্য কোন ভয় প্রদর্শনকারী ছিল না', 'And We did not destroy any city except that it had warners', NULL, NULL, NULL, NULL, NULL, 'https://everyayah.com/data/Alafasy_128kbps/026208.mp3', now()),
  (26, 209, '', '[{"id":85605,"position":1,"text_uthmani":"ذِكْرَىٰ","transliteration":"dhik''rā","translation_bn":"উপদেশস্বরূপ","root":"ذكر","lemma":"ذِكْرَىٰ","grammar_bn":"বিশেষ্য (Noun)"},{"id":85606,"position":2,"text_uthmani":"وَمَا","transliteration":"wamā","translation_bn":"আর না","root":"—","lemma":"مَا\r","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":85607,"position":3,"text_uthmani":"كُنَّا","transliteration":"kunnā","translation_bn":"আমরা ছিলাম","root":"كون","lemma":"كَانَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":85608,"position":4,"text_uthmani":"ظَـٰلِمِينَ","transliteration":"ẓālimīna","translation_bn":"সীমালঙ্ঘনকারী","root":"ظلم","lemma":"ظَالِم","grammar_bn":"বিশেষ্য (Noun)"},{"id":85609,"position":5,"text_uthmani":"٢٠٩","transliteration":"","translation_bn":"(২০৯)","root":"—","lemma":"٢٠٩","grammar_bn":"মার্কার"}]'::jsonb, 'dhik''rā wamā kunnā ẓālimīna', 'স্মরণ করানোর জন্য। আমি কখনো অন্যায়কারী নই।', 'As a reminder; and never have We been unjust.', 'স্মরণ করানোর জন্য। আমি কখনো অন্যায়কারী নই।', 'As a reminder; and never have We been unjust.', NULL, NULL, NULL, NULL, NULL, 'https://everyayah.com/data/Alafasy_128kbps/026209.mp3', now()),
  (26, 210, '', '[{"id":85629,"position":1,"text_uthmani":"وَمَا","transliteration":"wamā","translation_bn":"এবং না","root":"—","lemma":"مَا\r","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":85630,"position":2,"text_uthmani":"تَنَزَّلَتْ","transliteration":"tanazzalat","translation_bn":"অবতীর্ণ করেছে","root":"نزل","lemma":"تَنَزَّلَتْ","grammar_bn":"ক্রিয়া (Verb)"},{"id":85631,"position":3,"text_uthmani":"بِهِ","transliteration":"bihi","translation_bn":"নিয়ে তা","root":"—","lemma":"بِهِ","grammar_bn":"অব্যয় (Preposition)"},{"id":85632,"position":4,"text_uthmani":"ٱلشَّيَـٰطِينُ","transliteration":"l-shayāṭīnu","translation_bn":"শয়তানরা","root":"شطن","lemma":"شَيْطَٰن","grammar_bn":"শব্দ"},{"id":85633,"position":5,"text_uthmani":"٢١٠","transliteration":"","translation_bn":"(২১০)","root":"—","lemma":"٢١٠","grammar_bn":"মার্কার"}]'::jsonb, 'wamā tanazzalat bihi l-shayāṭīnu', 'শয়ত্বানরা তা (অর্থাৎ কুরআন) নিয়ে অবতরণ করেনি।', 'And the devils have not brought the revelation down.', 'শয়ত্বানরা তা (অর্থাৎ কুরআন) নিয়ে অবতরণ করেনি।', 'And the devils have not brought the revelation down.', NULL, NULL, NULL, NULL, NULL, 'https://everyayah.com/data/Alafasy_128kbps/026210.mp3', now()),
  (26, 211, '', '[{"id":85656,"position":1,"text_uthmani":"وَمَا","transliteration":"wamā","translation_bn":"আর না","root":"—","lemma":"مَا\r","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":85657,"position":2,"text_uthmani":"يَنۢبَغِى","transliteration":"yanbaghī","translation_bn":"উচিত","root":"بغي","lemma":"يَن[بَغِى","grammar_bn":"ক্রিয়া (Verb)"},{"id":85658,"position":3,"text_uthmani":"لَهُمْ","transliteration":"lahum","translation_bn":"জন্যে তাদের","root":"—","lemma":"لَهُمْ","grammar_bn":"অব্যয় (Preposition)"},{"id":85659,"position":4,"text_uthmani":"وَمَا","transliteration":"wamā","translation_bn":"আর না","root":"—","lemma":"مَا\r","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":85660,"position":5,"text_uthmani":"يَسْتَطِيعُونَ","transliteration":"yastaṭīʿūna","translation_bn":"তারা সামর্থ্য রাখে","root":"طوع","lemma":"ٱسْتَطَاعَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":85661,"position":6,"text_uthmani":"٢١١","transliteration":"","translation_bn":"(২১১)","root":"—","lemma":"٢١١","grammar_bn":"মার্কার"}]'::jsonb, 'wamā yanbaghī lahum wamā yastaṭīʿūna', 'তারা এ কাজের যোগ্য নয় আর তারা এর সামর্থ্যও রাখে না।', 'It is not allowable for them, nor would they be able.', 'তারা এ কাজের যোগ্য নয় আর তারা এর সামর্থ্যও রাখে না।', 'It is not allowable for them, nor would they be able.', NULL, NULL, NULL, NULL, NULL, 'https://everyayah.com/data/Alafasy_128kbps/026211.mp3', now()),
  (26, 212, '', '[{"id":85662,"position":1,"text_uthmani":"إِنَّهُمْ","transliteration":"innahum","translation_bn":"নিশ্চয়ই তাদেরকে","root":"—","lemma":"إِنّ","grammar_bn":"অভিঘাত পদ (Accusative)"},{"id":85663,"position":2,"text_uthmani":"عَنِ","transliteration":"ʿani","translation_bn":"হ''তে","root":"—","lemma":"عَن\r","grammar_bn":"অব্যয় (Preposition)"},{"id":85664,"position":3,"text_uthmani":"ٱلسَّمْعِ","transliteration":"l-samʿi","translation_bn":"শোনা","root":"سمع","lemma":"سَمْع","grammar_bn":"শব্দ"},{"id":85665,"position":4,"text_uthmani":"لَمَعْزُولُونَ","transliteration":"lamaʿzūlūna","translation_bn":"অবশ্যই দূরে রাখা হয়েছে","root":"عزل","lemma":"مَعْزُولُون","grammar_bn":"দৃঢ়তাবোধক (Emphatic)"},{"id":85666,"position":5,"text_uthmani":"٢١٢","transliteration":"","translation_bn":"(২১২)","root":"—","lemma":"٢١٢","grammar_bn":"মার্কার"}]'::jsonb, 'innahum ʿani l-samʿi lamaʿzūlūna', 'তাদেরকে এটা শোনা থেকে অবশ্যই দূরে রাখা হয়েছে।', 'Indeed they, from [its] hearing, are removed.', 'তাদেরকে এটা শোনা থেকে অবশ্যই দূরে রাখা হয়েছে।', 'Indeed they, from [its] hearing, are removed.', NULL, NULL, NULL, NULL, NULL, 'https://everyayah.com/data/Alafasy_128kbps/026212.mp3', now()),
  (26, 213, '', '[{"id":85743,"position":1,"text_uthmani":"فَلَا","transliteration":"falā","translation_bn":"অতএব না","root":"—","lemma":"لَا\r","grammar_bn":"শব্দ"},{"id":85744,"position":2,"text_uthmani":"تَدْعُ","transliteration":"tadʿu","translation_bn":"তুমি ডেকো","root":"دعو","lemma":"دَعَا","grammar_bn":"ক্রিয়া (Verb)"},{"id":85745,"position":3,"text_uthmani":"مَعَ","transliteration":"maʿa","translation_bn":"সাথে","root":"—","lemma":"مَع","grammar_bn":"স্থানবাচক (Location)"},{"id":85746,"position":4,"text_uthmani":"ٱللَّهِ","transliteration":"l-lahi","translation_bn":"আল্লাহর","root":"اله","lemma":"ٱللَّه","grammar_bn":"নামবাচক বিশেষ্য (Proper Noun)"},{"id":85747,"position":5,"text_uthmani":"إِلَـٰهًا","transliteration":"ilāhan","translation_bn":"কোনো ইলাহ","root":"اله","lemma":"إِلَٰه","grammar_bn":"বিশেষ্য (Noun)"},{"id":85748,"position":6,"text_uthmani":"ءَاخَرَ","transliteration":"ākhara","translation_bn":"অন্য","root":"اخر","lemma":"ا^خَر","grammar_bn":"বিশেষণ (Adjective)"},{"id":85749,"position":7,"text_uthmani":"فَتَكُونَ","transliteration":"fatakūna","translation_bn":"তাহ''লে তুমি হবে","root":"كون","lemma":"كَانَ","grammar_bn":"কারণবাচক (Cause)"},{"id":85750,"position":8,"text_uthmani":"مِنَ","transliteration":"mina","translation_bn":"অন্তর্ভুক্ত","root":"—","lemma":"مِن\r","grammar_bn":"অব্যয় (Preposition)"},{"id":85751,"position":9,"text_uthmani":"ٱلْمُعَذَّبِينَ","transliteration":"l-muʿadhabīna","translation_bn":"শাস্তিপ্রাপ্তদের","root":"عذب","lemma":"مُعَذَّبِين","grammar_bn":"শব্দ"},{"id":85752,"position":10,"text_uthmani":"٢١٣","transliteration":"","translation_bn":"(২১৩)","root":"—","lemma":"٢١٣","grammar_bn":"মার্কার"}]'::jsonb, 'falā tadʿu maʿa l-lahi ilāhan ākhara fatakūna mina l-muʿadhabīna', 'কাজেই তুমি অন্য কোন ইলাহ্কে আল্লাহর সঙ্গে ডেক না। ডাকলে তুমি শাস্তিপ্রাপ্তদের অন্তর্ভুক্ত হয়ে যাবে।', 'So do not invoke with Allah another deity and [thus] be among the punished.', 'কাজেই তুমি অন্য কোন ইলাহ্কে আল্লাহর সঙ্গে ডেক না। ডাকলে তুমি শাস্তিপ্রাপ্তদের অন্তর্ভুক্ত হয়ে যাবে।', 'So do not invoke with Allah another deity and [thus] be among the punished.', NULL, NULL, NULL, NULL, NULL, 'https://everyayah.com/data/Alafasy_128kbps/026213.mp3', now()),
  (26, 214, '', '[{"id":85753,"position":1,"text_uthmani":"وَأَنذِرْ","transliteration":"wa-andhir","translation_bn":"এবং সতর্ক করো","root":"نذر","lemma":"أَنذَرَ","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":85754,"position":2,"text_uthmani":"عَشِيرَتَكَ","transliteration":"ʿashīrataka","translation_bn":"তোমার আত্মীয় স্বজনদেরকে","root":"عشر","lemma":"عَشِيرَت","grammar_bn":"বিশেষ্য (Noun)"},{"id":85755,"position":3,"text_uthmani":"ٱلْأَقْرَبِينَ","transliteration":"l-aqrabīna","translation_bn":"নিকটতম","root":"قرب","lemma":"أَقْرَب","grammar_bn":"শব্দ"},{"id":85756,"position":4,"text_uthmani":"٢١٤","transliteration":"","translation_bn":"(২১৪)","root":"—","lemma":"٢١٤","grammar_bn":"মার্কার"}]'::jsonb, 'wa-andhir ʿashīrataka l-aqrabīna', 'আর তুমি সতর্ক কর তোমার নিকটাত্মীয় স্বজনদের', 'And warn, [O Muhammad], your closest kindred.', 'আর তুমি সতর্ক কর তোমার নিকটাত্মীয় স্বজনদের', 'And warn, [O Muhammad], your closest kindred.', NULL, NULL, NULL, NULL, NULL, 'https://everyayah.com/data/Alafasy_128kbps/026214.mp3', now()),
  (26, 215, '', '[{"id":85790,"position":1,"text_uthmani":"وَٱخْفِضْ","transliteration":"wa-ikh''fiḍ","translation_bn":"আর অবনত করো (অর্থাৎ বিনয়ী হও)","root":"خفض","lemma":"ٱخْفِضْ","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":85791,"position":2,"text_uthmani":"جَنَاحَكَ","transliteration":"janāḥaka","translation_bn":"তোমার বাহু","root":"جنح","lemma":"جَنَاح","grammar_bn":"বিশেষ্য (Noun)"},{"id":85792,"position":3,"text_uthmani":"لِمَنِ","transliteration":"limani","translation_bn":"জন্যে তাদের (যারা)","root":"—","lemma":"مَن\r","grammar_bn":"অব্যয় (Preposition)"},{"id":85793,"position":4,"text_uthmani":"ٱتَّبَعَكَ","transliteration":"ittabaʿaka","translation_bn":"তোমার অনুসরন করে","root":"تبع","lemma":"ٱتَّبَعَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":85794,"position":5,"text_uthmani":"مِنَ","transliteration":"mina","translation_bn":"মধ্য হ''তে","root":"—","lemma":"مِن\r","grammar_bn":"অব্যয় (Preposition)"},{"id":85795,"position":6,"text_uthmani":"ٱلْمُؤْمِنِينَ","transliteration":"l-mu''minīna","translation_bn":"মু''মিনদের","root":"امن","lemma":"مُؤْمِن","grammar_bn":"শব্দ"},{"id":85796,"position":7,"text_uthmani":"٢١٥","transliteration":"","translation_bn":"(২১৫)","root":"—","lemma":"٢١٥","grammar_bn":"মার্কার"}]'::jsonb, 'wa-ikh''fiḍ janāḥaka limani ittabaʿaka mina l-mu''minīna', 'যে সকল বিশ্বাসীরা তোমার আনুগত্য করে তাদের জন্য তুমি তোমার অনুকম্পার বাহু প্রসারিত কর।', 'And lower your wing to those who follow you of the believers.', 'যে সকল বিশ্বাসীরা তোমার আনুগত্য করে তাদের জন্য তুমি তোমার অনুকম্পার বাহু প্রসারিত কর।', 'And lower your wing to those who follow you of the believers.', NULL, NULL, NULL, NULL, NULL, 'https://everyayah.com/data/Alafasy_128kbps/026215.mp3', now()),
  (26, 216, '', '[{"id":85851,"position":1,"text_uthmani":"فَإِنْ","transliteration":"fa-in","translation_bn":"কিন্তু যদি","root":"—","lemma":"إِن\r","grammar_bn":"শব্দ"},{"id":85852,"position":2,"text_uthmani":"عَصَوْكَ","transliteration":"ʿaṣawka","translation_bn":"তোমার তারা অবাধ্য হয়","root":"عصي","lemma":"عَصَا","grammar_bn":"ক্রিয়া (Verb)"},{"id":85853,"position":3,"text_uthmani":"فَقُلْ","transliteration":"faqul","translation_bn":"তবে বলো","root":"قول","lemma":"قَالَ","grammar_bn":"শব্দ"},{"id":85854,"position":4,"text_uthmani":"إِنِّى","transliteration":"innī","translation_bn":"\"নিশ্চয়ই আমি","root":"—","lemma":"إِنّ","grammar_bn":"অভিঘাত পদ (Accusative)"},{"id":85855,"position":5,"text_uthmani":"بَرِىٓءٌۭ","transliteration":"barīon","translation_bn":"দায়মুক্ত","root":"برا","lemma":"بَرِى^ء","grammar_bn":"বিশেষ্য (Noun)"},{"id":85856,"position":6,"text_uthmani":"مِّمَّا","transliteration":"mimmā","translation_bn":"(তা) হ''তে যা","root":"—","lemma":"مِن\r","grammar_bn":"অব্যয় (Preposition)"},{"id":85857,"position":7,"text_uthmani":"تَعْمَلُونَ","transliteration":"taʿmalūna","translation_bn":"তোমরা কাজ করছো\"","root":"عمل","lemma":"عَمِلَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":85858,"position":8,"text_uthmani":"٢١٦","transliteration":"","translation_bn":"(২১৬)","root":"—","lemma":"٢١٦","grammar_bn":"মার্কার"}]'::jsonb, 'fa-in ʿaṣawka faqul innī barīon mimmā taʿmalūna', 'তারা যদি তোমার অবাধ্যতা করে তাহলে তুমি বলে দাও- তোমরা যা কর তার সঙ্গে আমি সম্পর্কহীন।', 'And if they disobey you, then say, "Indeed, I am disassociated from what you are doing."', 'তারা যদি তোমার অবাধ্যতা করে তাহলে তুমি বলে দাও- তোমরা যা কর তার সঙ্গে আমি সম্পর্কহীন।', 'And if they disobey you, then say, "Indeed, I am disassociated from what you are doing."', NULL, NULL, NULL, NULL, NULL, 'https://everyayah.com/data/Alafasy_128kbps/026216.mp3', now()),
  (26, 217, '', '[{"id":85924,"position":1,"text_uthmani":"وَتَوَكَّلْ","transliteration":"watawakkal","translation_bn":"এবং নির্ভর করো","root":"وكل","lemma":"تَوَكَّلْ","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":85925,"position":2,"text_uthmani":"عَلَى","transliteration":"ʿalā","translation_bn":"(আল্লাহর) উপর","root":"—","lemma":"عَلَىٰ\r","grammar_bn":"অব্যয় (Preposition)"},{"id":85926,"position":3,"text_uthmani":"ٱلْعَزِيزِ","transliteration":"l-ʿazīzi","translation_bn":"(যিনি) পরাক্রমশালী","root":"عزز","lemma":"عَزِيز","grammar_bn":"শব্দ"},{"id":85927,"position":4,"text_uthmani":"ٱلرَّحِيمِ","transliteration":"l-raḥīmi","translation_bn":"পরম দয়ালু","root":"رحم","lemma":"رَّحِيم","grammar_bn":"শব্দ"},{"id":85928,"position":5,"text_uthmani":"٢١٧","transliteration":"","translation_bn":"(২১৭)","root":"—","lemma":"٢١٧","grammar_bn":"মার্কার"}]'::jsonb, 'watawakkal ʿalā l-ʿazīzi l-raḥīmi', 'আর তুমি প্রবল পরাক্রান্ত পরম দয়ালুর উপর নির্ভর কর;', 'And rely upon the Exalted in Might, the Merciful,', 'আর তুমি প্রবল পরাক্রান্ত পরম দয়ালুর উপর নির্ভর কর;', 'And rely upon the Exalted in Might, the Merciful,', NULL, NULL, NULL, NULL, NULL, 'https://everyayah.com/data/Alafasy_128kbps/026217.mp3', now()),
  (26, 218, '', '[{"id":85929,"position":1,"text_uthmani":"ٱلَّذِى","transliteration":"alladhī","translation_bn":"যিনি","root":"—","lemma":"ٱلَّذِى","grammar_bn":"সাপেক্ষ সর্বনাম (Relative)"},{"id":85930,"position":2,"text_uthmani":"يَرَىٰكَ","transliteration":"yarāka","translation_bn":"তোমাকে দেখছেন","root":"راي","lemma":"رَءَا","grammar_bn":"ক্রিয়া (Verb)"},{"id":85931,"position":3,"text_uthmani":"حِينَ","transliteration":"ḥīna","translation_bn":"যখন","root":"حين","lemma":"حِين","grammar_bn":"বিশেষ্য (Noun)"},{"id":85932,"position":4,"text_uthmani":"تَقُومُ","transliteration":"taqūmu","translation_bn":"তুমি দাঁড়াও","root":"قوم","lemma":"قَامَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":85933,"position":5,"text_uthmani":"٢١٨","transliteration":"","translation_bn":"(২১৮)","root":"—","lemma":"٢١٨","grammar_bn":"মার্কার"}]'::jsonb, 'alladhī yarāka ḥīna taqūmu', 'যিনি তোমাকে দেখেন যখন তুমি (নামাযের জন্য) দন্ডায়মান হও।', 'Who sees you when you arise', 'যিনি তোমাকে দেখেন যখন তুমি (নামাযের জন্য) দন্ডায়মান হও।', 'Who sees you when you arise', NULL, NULL, NULL, NULL, NULL, 'https://everyayah.com/data/Alafasy_128kbps/026218.mp3', now()),
  (26, 219, '', '[{"id":85952,"position":1,"text_uthmani":"وَتَقَلُّبَكَ","transliteration":"wataqallubaka","translation_bn":"তোমার গতিবিধি","root":"قلب","lemma":"تَقَلُّب","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":85953,"position":2,"text_uthmani":"فِى","transliteration":"fī","translation_bn":"মধ্যে","root":"—","lemma":"فِى\r","grammar_bn":"অব্যয় (Preposition)"},{"id":85954,"position":3,"text_uthmani":"ٱلسَّـٰجِدِينَ","transliteration":"l-sājidīna","translation_bn":"সিজদাকারীদের","root":"سجد","lemma":"سَاجِد","grammar_bn":"শব্দ"},{"id":85955,"position":4,"text_uthmani":"٢١٩","transliteration":"","translation_bn":"(২১৯)","root":"—","lemma":"٢١٩","grammar_bn":"মার্কার"}]'::jsonb, 'wataqallubaka fī l-sājidīna', 'আর (তিনি দেখেন) সাজদাকারীদের সঙ্গে তোমার চলাফিরা।', 'And your movement among those who prostrate.', 'আর (তিনি দেখেন) সাজদাকারীদের সঙ্গে তোমার চলাফিরা।', 'And your movement among those who prostrate.', NULL, NULL, NULL, NULL, NULL, 'https://everyayah.com/data/Alafasy_128kbps/026219.mp3', now()),
  (26, 220, '', '[{"id":85987,"position":1,"text_uthmani":"إِنَّهُۥ","transliteration":"innahu","translation_bn":"নিশ্চয়ই তিনি","root":"—","lemma":"إِنّ","grammar_bn":"অভিঘাত পদ (Accusative)"},{"id":85988,"position":2,"text_uthmani":"هُوَ","transliteration":"huwa","translation_bn":"তিনিই","root":"—","lemma":"هُوَ","grammar_bn":"সর্বনাম (Pronoun)"},{"id":85989,"position":3,"text_uthmani":"ٱلسَّمِيعُ","transliteration":"l-samīʿu","translation_bn":"সবকিছু শুনেন","root":"سمع","lemma":"سَمِيع","grammar_bn":"শব্দ"},{"id":85990,"position":4,"text_uthmani":"ٱلْعَلِيمُ","transliteration":"l-ʿalīmu","translation_bn":"সবকিছু জানেন","root":"علم","lemma":"عَلِيم","grammar_bn":"শব্দ"},{"id":85991,"position":5,"text_uthmani":"٢٢٠","transliteration":"","translation_bn":"(২২০)","root":"—","lemma":"٢٢٠","grammar_bn":"মার্কার"}]'::jsonb, 'innahu huwa l-samīʿu l-ʿalīmu', 'তিনি সব কিছু শোনেন, সব কিছু জানেন।', 'Indeed, He is the Hearing, the Knowing.', 'তিনি সব কিছু শোনেন, সব কিছু জানেন।', 'Indeed, He is the Hearing, the Knowing.', NULL, NULL, NULL, NULL, NULL, 'https://everyayah.com/data/Alafasy_128kbps/026220.mp3', now()),
  (26, 221, '', '[{"id":86071,"position":1,"text_uthmani":"هَلْ","transliteration":"hal","translation_bn":"কি","root":"—","lemma":"هَل\r","grammar_bn":"প্রশ্নবোধক (Interrogative)"},{"id":86072,"position":2,"text_uthmani":"أُنَبِّئُكُمْ","transliteration":"unabbi-ukum","translation_bn":"জানাবো তোমাদেরকে","root":"نبا","lemma":"نَبَّأَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":86073,"position":3,"text_uthmani":"عَلَىٰ","transliteration":"ʿalā","translation_bn":"উপর","root":"—","lemma":"عَلَىٰ\r","grammar_bn":"অব্যয় (Preposition)"},{"id":86074,"position":4,"text_uthmani":"مَن","transliteration":"man","translation_bn":"কার","root":"—","lemma":"مَن\r","grammar_bn":"সাপেক্ষ সর্বনাম (Relative)"},{"id":86075,"position":5,"text_uthmani":"تَنَزَّلُ","transliteration":"tanazzalu","translation_bn":"অবতীর্ণ হয়","root":"نزل","lemma":"تَنَزَّلَتْ","grammar_bn":"ক্রিয়া (Verb)"},{"id":86076,"position":6,"text_uthmani":"ٱلشَّيَـٰطِينُ","transliteration":"l-shayāṭīnu","translation_bn":"শয়তানরা","root":"شطن","lemma":"شَيْطَٰن","grammar_bn":"শব্দ"},{"id":86077,"position":7,"text_uthmani":"٢٢١","transliteration":"","translation_bn":"(২২১)","root":"—","lemma":"٢٢١","grammar_bn":"মার্কার"}]'::jsonb, 'hal unabbi-ukum ʿalā man tanazzalu l-shayāṭīnu', 'আমি কি তোমাদেরকে জানাব কাদের নিকট শয়ত্বানরা অবতীর্ণ হয়।', 'Shall I inform you upon whom the devils descend?', 'আমি কি তোমাদেরকে জানাব কাদের নিকট শয়ত্বানরা অবতীর্ণ হয়।', 'Shall I inform you upon whom the devils descend?', NULL, NULL, NULL, NULL, NULL, 'https://everyayah.com/data/Alafasy_128kbps/026221.mp3', now()),
  (26, 222, '', '[{"id":86110,"position":1,"text_uthmani":"تَنَزَّلُ","transliteration":"tanazzalu","translation_bn":"অবতীর্ণ হয়","root":"نزل","lemma":"تَنَزَّلَتْ","grammar_bn":"ক্রিয়া (Verb)"},{"id":86111,"position":2,"text_uthmani":"عَلَىٰ","transliteration":"ʿalā","translation_bn":"উপর","root":"—","lemma":"عَلَىٰ\r","grammar_bn":"অব্যয় (Preposition)"},{"id":86112,"position":3,"text_uthmani":"كُلِّ","transliteration":"kulli","translation_bn":"প্রত্যেক","root":"كلل","lemma":"كُلّ","grammar_bn":"বিশেষ্য (Noun)"},{"id":86113,"position":4,"text_uthmani":"أَفَّاكٍ","transliteration":"affākin","translation_bn":"ঘোর মিথ্যাবাদী","root":"افك","lemma":"أَفَّاك","grammar_bn":"বিশেষ্য (Noun)"},{"id":86114,"position":5,"text_uthmani":"أَثِيمٍۢ","transliteration":"athīmin","translation_bn":"পাপীর","root":"اثم","lemma":"أَثِيم","grammar_bn":"বিশেষণ (Adjective)"},{"id":86115,"position":6,"text_uthmani":"٢٢٢","transliteration":"","translation_bn":"(২২২)","root":"—","lemma":"٢٢٢","grammar_bn":"মার্কার"}]'::jsonb, 'tanazzalu ʿalā kulli affākin athīmin', 'তারা অবতীর্ণ হয় প্রত্যেকটি চরম মিথ্যুক ও পাপীর নিকট।', 'They descend upon every sinful liar.', 'তারা অবতীর্ণ হয় প্রত্যেকটি চরম মিথ্যুক ও পাপীর নিকট।', 'They descend upon every sinful liar.', NULL, NULL, NULL, NULL, NULL, 'https://everyayah.com/data/Alafasy_128kbps/026222.mp3', now()),
  (26, 223, '', '[{"id":86116,"position":1,"text_uthmani":"يُلْقُونَ","transliteration":"yul''qūna","translation_bn":"(যারা) পেতে রাখে","root":"لقي","lemma":"أَلْقَىٰ^","grammar_bn":"ক্রিয়া (Verb)"},{"id":86117,"position":2,"text_uthmani":"ٱلسَّمْعَ","transliteration":"l-samʿa","translation_bn":"কান (শয়তানের কথায়)","root":"سمع","lemma":"سَمْع","grammar_bn":"শব্দ"},{"id":86118,"position":3,"text_uthmani":"وَأَكْثَرُهُمْ","transliteration":"wa-aktharuhum","translation_bn":"আর অধিকাংশ তাদের","root":"كثر","lemma":"أَكْثَر","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":86119,"position":4,"text_uthmani":"كَـٰذِبُونَ","transliteration":"kādhibūna","translation_bn":"মিথ্যাবাদী","root":"كذب","lemma":"كَٰذِب","grammar_bn":"বিশেষ্য (Noun)"},{"id":86120,"position":5,"text_uthmani":"٢٢٣","transliteration":"","translation_bn":"(২২৩)","root":"—","lemma":"٢٢٣","grammar_bn":"মার্কার"}]'::jsonb, 'yul''qūna l-samʿa wa-aktharuhum kādhibūna', 'ওরা কান পেতে থাকে আর তাদের অধিকাংশই মিথ্যাবাদী।', 'They pass on what is heard, and most of them are liars.', 'ওরা কান পেতে থাকে আর তাদের অধিকাংশই মিথ্যাবাদী।', 'They pass on what is heard, and most of them are liars.', NULL, NULL, NULL, NULL, NULL, 'https://everyayah.com/data/Alafasy_128kbps/026223.mp3', now()),
  (26, 224, '', '[{"id":86141,"position":1,"text_uthmani":"وَٱلشُّعَرَآءُ","transliteration":"wal-shuʿarāu","translation_bn":"এবং কবিদের (কথা)","root":"شعر","lemma":"شَاعِر","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":86142,"position":2,"text_uthmani":"يَتَّبِعُهُمُ","transliteration":"yattabiʿuhumu","translation_bn":"অনুসরণ করে তাদেরকে","root":"تبع","lemma":"ٱتَّبَعَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":86143,"position":3,"text_uthmani":"ٱلْغَاوُۥنَ","transliteration":"l-ghāwūna","translation_bn":"বিভ্রান্তলোকেরা","root":"غوي","lemma":"غَٰوِين","grammar_bn":"শব্দ"},{"id":86144,"position":4,"text_uthmani":"٢٢٤","transliteration":"","translation_bn":"(২২৪)","root":"—","lemma":"٢٢٤","grammar_bn":"মার্কার"}]'::jsonb, 'wal-shuʿarāu yattabiʿuhumu l-ghāwūna', 'বিভ্রান্তরাই কবিদের অনুসরণ করে,', 'And the poets - [only] the deviators follow them;', 'বিভ্রান্তরাই কবিদের অনুসরণ করে,', 'And the poets - [only] the deviators follow them;', NULL, NULL, NULL, NULL, NULL, 'https://everyayah.com/data/Alafasy_128kbps/026224.mp3', now()),
  (26, 225, '', '[{"id":86177,"position":1,"text_uthmani":"أَلَمْ","transliteration":"alam","translation_bn":"কি নি","root":"—","lemma":"لَم\r","grammar_bn":"প্রশ্নবোধক (Interrogative)"},{"id":86178,"position":2,"text_uthmani":"تَرَ","transliteration":"tara","translation_bn":"তুমি দেখো","root":"راي","lemma":"رَءَا","grammar_bn":"ক্রিয়া (Verb)"},{"id":86179,"position":3,"text_uthmani":"أَنَّهُمْ","transliteration":"annahum","translation_bn":"যে তারা","root":"—","lemma":"أَنّ","grammar_bn":"অভিঘাত পদ (Accusative)"},{"id":86180,"position":4,"text_uthmani":"فِى","transliteration":"fī","translation_bn":"মধ্যে","root":"—","lemma":"فِى\r","grammar_bn":"অব্যয় (Preposition)"},{"id":86181,"position":5,"text_uthmani":"كُلِّ","transliteration":"kulli","translation_bn":"প্রত্যেক","root":"كلل","lemma":"كُلّ","grammar_bn":"বিশেষ্য (Noun)"},{"id":86182,"position":6,"text_uthmani":"وَادٍۢ","transliteration":"wādin","translation_bn":"উপত্যকার","root":"ودي","lemma":"وَاد","grammar_bn":"বিশেষ্য (Noun)"},{"id":86183,"position":7,"text_uthmani":"يَهِيمُونَ","transliteration":"yahīmūna","translation_bn":"উদভ্রান্ত হয়ে ঘুরছে","root":"هيم","lemma":"يَهِيمُ","grammar_bn":"ক্রিয়া (Verb)"},{"id":86184,"position":8,"text_uthmani":"٢٢٥","transliteration":"","translation_bn":"(২২৫)","root":"—","lemma":"٢٢٥","grammar_bn":"মার্কার"}]'::jsonb, 'alam tara annahum fī kulli wādin yahīmūna', 'তুমি কি দেখ না যে, তারা প্রতি ময়দানেই উদভ্রান্ত হয়ে ফিরে?', 'Do you not see that in every valley they roam', 'তুমি কি দেখ না যে, তারা প্রতি ময়দানেই উদভ্রান্ত হয়ে ফিরে?', 'Do you not see that in every valley they roam', NULL, NULL, NULL, NULL, NULL, 'https://everyayah.com/data/Alafasy_128kbps/026225.mp3', now()),
  (26, 226, '', '[{"id":86200,"position":1,"text_uthmani":"وَأَنَّهُمْ","transliteration":"wa-annahum","translation_bn":"এবং (এও) যে তারা","root":"—","lemma":"أَنّ","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":86201,"position":2,"text_uthmani":"يَقُولُونَ","transliteration":"yaqūlūna","translation_bn":"বলে (এমন কথা)","root":"قول","lemma":"قَالَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":86202,"position":3,"text_uthmani":"مَا","transliteration":"mā","translation_bn":"যা","root":"—","lemma":"مَا\r","grammar_bn":"সাপেক্ষ সর্বনাম (Relative)"},{"id":86203,"position":4,"text_uthmani":"لَا","transliteration":"lā","translation_bn":"না","root":"—","lemma":"لَا\r","grammar_bn":"না-বোধক (Negative)"},{"id":86204,"position":5,"text_uthmani":"يَفْعَلُونَ","transliteration":"yafʿalūna","translation_bn":"(নিজেরা) তারা করে","root":"فعل","lemma":"فَعَلَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":86205,"position":6,"text_uthmani":"٢٢٦","transliteration":"","translation_bn":"(২২৬)","root":"—","lemma":"٢٢٦","grammar_bn":"মার্কার"}]'::jsonb, 'wa-annahum yaqūlūna mā lā yafʿalūna', 'আর তারা যা বলে তা তারা নিজেরা করে না।', 'And that they say what they do not do? -', 'আর তারা যা বলে তা তারা নিজেরা করে না।', 'And that they say what they do not do? -', NULL, NULL, NULL, NULL, NULL, 'https://everyayah.com/data/Alafasy_128kbps/026226.mp3', now()),
  (26, 227, '', '[{"id":86214,"position":1,"text_uthmani":"إِلَّا","transliteration":"illā","translation_bn":"তবে (ব্যতিক্রম)","root":"—","lemma":"إِلَّا\r","grammar_bn":"সীমাবদ্ধতা (Restriction)"},{"id":86215,"position":2,"text_uthmani":"ٱلَّذِينَ","transliteration":"alladhīna","translation_bn":"(তারা) যারা","root":"—","lemma":"ٱلَّذِى","grammar_bn":"সাপেক্ষ সর্বনাম (Relative)"},{"id":86216,"position":3,"text_uthmani":"ءَامَنُوا۟","transliteration":"āmanū","translation_bn":"ঈমান আনে","root":"امن","lemma":"ءَامَنَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":86217,"position":4,"text_uthmani":"وَعَمِلُوا۟","transliteration":"waʿamilū","translation_bn":"ও কাজ করে","root":"عمل","lemma":"عَمِلَ","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":86218,"position":5,"text_uthmani":"ٱلصَّـٰلِحَـٰتِ","transliteration":"l-ṣāliḥāti","translation_bn":"সৎ","root":"صلح","lemma":"صَّٰلِحَٰت","grammar_bn":"শব্দ"},{"id":86219,"position":6,"text_uthmani":"وَذَكَرُوا۟","transliteration":"wadhakarū","translation_bn":"এবং স্মরণ করে","root":"ذكر","lemma":"ذَكَرَ","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":86220,"position":7,"text_uthmani":"ٱللَّهَ","transliteration":"l-laha","translation_bn":"আল্লাহকে","root":"اله","lemma":"ٱللَّه","grammar_bn":"নামবাচক বিশেষ্য (Proper Noun)"},{"id":86221,"position":8,"text_uthmani":"كَثِيرًۭا","transliteration":"kathīran","translation_bn":"বেশী বেশী","root":"كثر","lemma":"كَثِير","grammar_bn":"বিশেষণ (Adjective)"},{"id":86222,"position":9,"text_uthmani":"وَٱنتَصَرُوا۟","transliteration":"wa-intaṣarū","translation_bn":"এবং প্রতিশোধ নেয়","root":"نصر","lemma":"ٱنتَصَرَ","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":86223,"position":10,"text_uthmani":"مِنۢ","transliteration":"min","translation_bn":"থেকে","root":"—","lemma":"مِن\r","grammar_bn":"অব্যয় (Preposition)"},{"id":86224,"position":11,"text_uthmani":"بَعْدِ","transliteration":"baʿdi","translation_bn":"পর","root":"بعد","lemma":"بَعْد","grammar_bn":"বিশেষ্য (Noun)"},{"id":86225,"position":12,"text_uthmani":"مَا","transliteration":"mā","translation_bn":"যা","root":"—","lemma":"مَا\r","grammar_bn":"সাপেক্ষ সর্বনাম (Relative)"},{"id":86226,"position":13,"text_uthmani":"ظُلِمُوا۟ ۗ","transliteration":"ẓulimū","translation_bn":"তারা নির্যাতিত হ''লে","root":"ظلم","lemma":"ظَلَمَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":86228,"position":14,"text_uthmani":"وَسَيَعْلَمُ","transliteration":"wasayaʿlamu","translation_bn":"এবং শীঘ্রই জানবে","root":"علم","lemma":"عَلِمَ","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":86229,"position":15,"text_uthmani":"ٱلَّذِينَ","transliteration":"alladhīna","translation_bn":"যারা","root":"—","lemma":"ٱلَّذِى","grammar_bn":"সাপেক্ষ সর্বনাম (Relative)"},{"id":86230,"position":16,"text_uthmani":"ظَلَمُوٓا۟","transliteration":"ẓalamū","translation_bn":"নির্যাতন করেছে","root":"ظلم","lemma":"ظَلَمَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":86231,"position":17,"text_uthmani":"أَىَّ","transliteration":"ayya","translation_bn":"কোনো","root":"—","lemma":"أَىّ\r","grammar_bn":"প্রশ্নবোধক (Interrogative)"},{"id":86232,"position":18,"text_uthmani":"مُنقَلَبٍۢ","transliteration":"munqalabin","translation_bn":"প্রত্যাবর্তনস্থলে","root":"قلب","lemma":"مُنقَلَب","grammar_bn":"বিশেষ্য (Noun)"},{"id":86233,"position":19,"text_uthmani":"يَنقَلِبُونَ","transliteration":"yanqalibūna","translation_bn":"তারা প্রত্যাবর্তন করছে","root":"قلب","lemma":"ٱنقَلَبَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":86234,"position":20,"text_uthmani":"٢٢٧","transliteration":"","translation_bn":"(২২৭)","root":"—","lemma":"٢٢٧","grammar_bn":"মার্কার"}]'::jsonb, 'illā alladhīna āmanū waʿamilū l-ṣāliḥāti wadhakarū l-laha kathīran wa-intaṣarū min baʿdi mā ẓulimū wasayaʿlamu alladhīna ẓalamū ayya munqalabin yanqalibūna', 'কিন্তু ওরা ব্যতীত যারা ঈমান আনে ও সৎকাজ করে আর আল্লাহকে খুব বেশি স্মরণ করে আর নির্যাতিত হওয়ার পর নিজেদের প্রতিরক্ষার ব্যবস্থা করে। যালিমরা শীঘ্রই জানতে পারবে কোন্ (মহা সংকটময়) জায়গায় তারা ফিরে যাচ্ছে।', 'Except those [poets] who believe and do righteous deeds and remember Allah often and defend [the Muslims] after they were wronged. And those who have wronged are going to know to what [kind of] return they will be returned.', 'কিন্তু ওরা ব্যতীত যারা ঈমান আনে ও সৎকাজ করে আর আল্লাহকে খুব বেশি স্মরণ করে আর নির্যাতিত হওয়ার পর নিজেদের প্রতিরক্ষার ব্যবস্থা করে। যালিমরা শীঘ্রই জানতে পারবে কোন্ (মহা সংকটময়) জায়গায় তারা ফিরে যাচ্ছে।', 'Except those [poets] who believe and do righteous deeds and remember Allah often and defend [the Muslims] after they were wronged. And those who have wronged are going to know to what [kind of] return they will be returned.', NULL, NULL, NULL, NULL, NULL, 'https://everyayah.com/data/Alafasy_128kbps/026227.mp3', now())
