  (27, 1, '', '[{"id":759,"position":1,"text_uthmani":"طسٓ ۚ","transliteration":"tta-seen","translation_bn":"ত্বা-সীন","root":"—","lemma":"طسٓ ۚ","grammar_bn":"শব্দ"},{"id":761,"position":2,"text_uthmani":"تِلْكَ","transliteration":"til''ka","translation_bn":"এই","root":"—","lemma":"ذَٰلِك","grammar_bn":"নির্দেশক সর্বনাম (Demonstrative)"},{"id":762,"position":3,"text_uthmani":"ءَايَـٰتُ","transliteration":"āyātu","translation_bn":"আয়াতসমূহ","root":"ايي","lemma":"ءَايَة","grammar_bn":"বিশেষ্য (Noun)"},{"id":763,"position":4,"text_uthmani":"ٱلْقُرْءَانِ","transliteration":"l-qur''āni","translation_bn":"কুরআনের","root":"قرا","lemma":"قُرْءَان","grammar_bn":"শব্দ"},{"id":764,"position":5,"text_uthmani":"وَكِتَابٍۢ","transliteration":"wakitābin","translation_bn":"ও কিতাবের","root":"كتب","lemma":"كِتَٰب","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":765,"position":6,"text_uthmani":"مُّبِينٍ","transliteration":"mubīnin","translation_bn":"(যা) সুস্পষ্ট","root":"بين","lemma":"مُّبِين","grammar_bn":"বিশেষ্য (Noun)"},{"id":766,"position":7,"text_uthmani":"١","transliteration":"","translation_bn":"(১)","root":"—","lemma":"١","grammar_bn":"মার্কার"}]'::jsonb, 'tta-seen til''ka āyātu l-qur''āni wakitābin mubīnin', 'তা-সীন, এগুলো কুরআনের আয়াত ও সুস্পষ্ট কিতাবের;', 'Ta, Seen. These are the verses of the Qur''an and a clear Book', 'তা-সীন, এগুলো কুরআনের আয়াত ও সুস্পষ্ট কিতাবের;', 'Ta, Seen. These are the verses of the Qur''an and a clear Book', NULL, NULL, NULL, NULL, NULL, 'https://everyayah.com/data/Alafasy_128kbps/027001.mp3', now()),
  (27, 2, '', '[{"id":1819,"position":1,"text_uthmani":"هُدًۭى","transliteration":"hudan","translation_bn":"(এটা) পথ নির্দেশ","root":"هدي","lemma":"هُدًى","grammar_bn":"বিশেষ্য (Noun)"},{"id":1820,"position":2,"text_uthmani":"وَبُشْرَىٰ","transliteration":"wabush''rā","translation_bn":"ও সুসংবাদ","root":"بشر","lemma":"بُشْرَىٰ","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":1821,"position":3,"text_uthmani":"لِلْمُؤْمِنِينَ","transliteration":"lil''mu''minīna","translation_bn":"জন্যে মু''মিনদের","root":"امن","lemma":"مُؤْمِن","grammar_bn":"অব্যয় (Preposition)"},{"id":1822,"position":4,"text_uthmani":"٢","transliteration":"","translation_bn":"(২)","root":"—","lemma":"٢","grammar_bn":"মার্কার"}]'::jsonb, 'hudan wabush''rā lil''mu''minīna', 'মু’মিনদের জন্য পথের দিশা ও সুসংবাদ', 'As guidance and good tidings for the believers', 'মু’মিনদের জন্য পথের দিশা ও সুসংবাদ', 'As guidance and good tidings for the believers', NULL, NULL, NULL, NULL, NULL, 'https://everyayah.com/data/Alafasy_128kbps/027002.mp3', now()),
  (27, 3, '', '[{"id":2943,"position":1,"text_uthmani":"ٱلَّذِينَ","transliteration":"alladhīna","translation_bn":"যারা","root":"—","lemma":"ٱلَّذِى","grammar_bn":"সাপেক্ষ সর্বনাম (Relative)"},{"id":2944,"position":2,"text_uthmani":"يُقِيمُونَ","transliteration":"yuqīmūna","translation_bn":"প্রতিষ্ঠা করে","root":"قوم","lemma":"أَقَامَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":2945,"position":3,"text_uthmani":"ٱلصَّلَوٰةَ","transliteration":"l-ṣalata","translation_bn":"সালাত","root":"صلو","lemma":"صَلَوٰة","grammar_bn":"শব্দ"},{"id":2946,"position":4,"text_uthmani":"وَيُؤْتُونَ","transliteration":"wayu''tūna","translation_bn":"ও আদায় করে","root":"اتي","lemma":"ا^تَى","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":2947,"position":5,"text_uthmani":"ٱلزَّكَوٰةَ","transliteration":"l-zakata","translation_bn":"যাকাত","root":"زكو","lemma":"زَكَوٰة","grammar_bn":"শব্দ"},{"id":2948,"position":6,"text_uthmani":"وَهُم","transliteration":"wahum","translation_bn":"এবং তারা","root":"—","lemma":"وَهُم","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":2949,"position":7,"text_uthmani":"بِٱلْـَٔاخِرَةِ","transliteration":"bil-ākhirati","translation_bn":"উপর আখেরাতের","root":"اخر","lemma":"ا^خِر","grammar_bn":"অব্যয় (Preposition)"},{"id":2950,"position":8,"text_uthmani":"هُمْ","transliteration":"hum","translation_bn":"তারা","root":"—","lemma":"هُمْ","grammar_bn":"সর্বনাম (Pronoun)"},{"id":2951,"position":9,"text_uthmani":"يُوقِنُونَ","transliteration":"yūqinūna","translation_bn":"দৃঢ় বিশ্বাস রাখে","root":"يقن","lemma":"يُوقِنُ","grammar_bn":"ক্রিয়া (Verb)"},{"id":2952,"position":10,"text_uthmani":"٣","transliteration":"","translation_bn":"(৩)","root":"—","lemma":"٣","grammar_bn":"মার্কার"}]'::jsonb, 'alladhīna yuqīmūna l-ṣalata wayu''tūna l-zakata wahum bil-ākhirati hum yūqinūna', 'যারা নামায কায়েম করে, যাকাত আদায় করে আর তারা আখিরাতে বিশ্বাসী।', 'Who establish prayer and give zakah, and of the Hereafter they are certain [in faith].', 'যারা নামায কায়েম করে, যাকাত আদায় করে আর তারা আখিরাতে বিশ্বাসী।', 'Who establish prayer and give zakah, and of the Hereafter they are certain [in faith].', NULL, NULL, NULL, NULL, NULL, 'https://everyayah.com/data/Alafasy_128kbps/027003.mp3', now()),
  (27, 4, '', '[{"id":4269,"position":1,"text_uthmani":"إِنَّ","transliteration":"inna","translation_bn":"নিশ্চয়ই","root":"—","lemma":"إِنّ","grammar_bn":"অভিঘাত পদ (Accusative)"},{"id":4270,"position":2,"text_uthmani":"ٱلَّذِينَ","transliteration":"alladhīna","translation_bn":"যারা","root":"—","lemma":"ٱلَّذِى","grammar_bn":"সাপেক্ষ সর্বনাম (Relative)"},{"id":4271,"position":3,"text_uthmani":"لَا","transliteration":"lā","translation_bn":"না","root":"—","lemma":"لَا\r","grammar_bn":"না-বোধক (Negative)"},{"id":4272,"position":4,"text_uthmani":"يُؤْمِنُونَ","transliteration":"yu''minūna","translation_bn":"বিশ্বাস করে","root":"امن","lemma":"ءَامَنَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":4273,"position":5,"text_uthmani":"بِٱلْـَٔاخِرَةِ","transliteration":"bil-ākhirati","translation_bn":"উপর আখেরাতের","root":"اخر","lemma":"ا^خِر","grammar_bn":"অব্যয় (Preposition)"},{"id":4274,"position":6,"text_uthmani":"زَيَّنَّا","transliteration":"zayyannā","translation_bn":"আমরা সুশোভন করেছি","root":"زين","lemma":"زَيَّنَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":4275,"position":7,"text_uthmani":"لَهُمْ","transliteration":"lahum","translation_bn":"জন্যে তাদের","root":"—","lemma":"لَهُمْ","grammar_bn":"অব্যয় (Preposition)"},{"id":4276,"position":8,"text_uthmani":"أَعْمَـٰلَهُمْ","transliteration":"aʿmālahum","translation_bn":"কাজকর্মসমূহকে তাদের","root":"عمل","lemma":"عَمَل","grammar_bn":"বিশেষ্য (Noun)"},{"id":4277,"position":9,"text_uthmani":"فَهُمْ","transliteration":"fahum","translation_bn":"ফলে তারা","root":"—","lemma":"فَهُمْ","grammar_bn":"শব্দ"},{"id":4278,"position":10,"text_uthmani":"يَعْمَهُونَ","transliteration":"yaʿmahūna","translation_bn":"বিভ্রান্তিতে ঘুরে বেড়াচ্ছে","root":"عمه","lemma":"يَعْمَهُ","grammar_bn":"ক্রিয়া (Verb)"},{"id":4279,"position":11,"text_uthmani":"٤","transliteration":"","translation_bn":"(৪)","root":"—","lemma":"٤","grammar_bn":"মার্কার"}]'::jsonb, 'inna alladhīna lā yu''minūna bil-ākhirati zayyannā lahum aʿmālahum fahum yaʿmahūna', 'যারা আখিরাতে বিশ্বাস করে না, তাদের (চোখে) তাদের কর্মকান্ডকে আমি সুশোভিত করেছি, কাজেই তারা উদভ্রান্ত হয়ে ঘুরে বেড়ায়,', 'Indeed, for those who do not believe in the Hereafter, We have made pleasing to them their deeds, so they wander blindly.', 'যারা আখিরাতে বিশ্বাস করে না, তাদের (চোখে) তাদের কর্মকান্ডকে আমি সুশোভিত করেছি, কাজেই তারা উদভ্রান্ত হয়ে ঘুরে বেড়ায়,', 'Indeed, for those who do not believe in the Hereafter, We have made pleasing to them their deeds, so they wander blindly.', NULL, NULL, NULL, NULL, NULL, 'https://everyayah.com/data/Alafasy_128kbps/027004.mp3', now()),
  (27, 5, '', '[{"id":5533,"position":1,"text_uthmani":"أُو۟لَـٰٓئِكَ","transliteration":"ulāika","translation_bn":"ঐসব (লোক)","root":"—","lemma":"أُولَٰ^ئِك","grammar_bn":"নির্দেশক সর্বনাম (Demonstrative)"},{"id":5534,"position":2,"text_uthmani":"ٱلَّذِينَ","transliteration":"alladhīna","translation_bn":"তারাই","root":"—","lemma":"ٱلَّذِى","grammar_bn":"সাপেক্ষ সর্বনাম (Relative)"},{"id":5535,"position":3,"text_uthmani":"لَهُمْ","transliteration":"lahum","translation_bn":"জন্যে যাদের (রয়েছে)","root":"—","lemma":"لَهُمْ","grammar_bn":"অব্যয় (Preposition)"},{"id":5536,"position":4,"text_uthmani":"سُوٓءُ","transliteration":"sūu","translation_bn":"(অত্যন্ত) খারাপ","root":"سوا","lemma":"سُو^ء","grammar_bn":"বিশেষ্য (Noun)"},{"id":5537,"position":5,"text_uthmani":"ٱلْعَذَابِ","transliteration":"l-ʿadhābi","translation_bn":"শাস্তি","root":"عذب","lemma":"عَذَاب","grammar_bn":"শব্দ"},{"id":5538,"position":6,"text_uthmani":"وَهُمْ","transliteration":"wahum","translation_bn":"এবং তারা হবে","root":"—","lemma":"وَهُمْ","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":5539,"position":7,"text_uthmani":"فِى","transliteration":"fī","translation_bn":"মধ্যে","root":"—","lemma":"فِى\r","grammar_bn":"অব্যয় (Preposition)"},{"id":5540,"position":8,"text_uthmani":"ٱلْـَٔاخِرَةِ","transliteration":"l-ākhirati","translation_bn":"আখেরাতে","root":"اخر","lemma":"ا^خِر","grammar_bn":"শব্দ"},{"id":5541,"position":9,"text_uthmani":"هُمُ","transliteration":"humu","translation_bn":"তারাই","root":"—","lemma":"هُمُ","grammar_bn":"সর্বনাম (Pronoun)"},{"id":5542,"position":10,"text_uthmani":"ٱلْأَخْسَرُونَ","transliteration":"l-akhsarūna","translation_bn":"সর্বাধিক ক্ষতিগ্রস্ত","root":"خسر","lemma":"أَخْسَرِين","grammar_bn":"শব্দ"},{"id":5543,"position":11,"text_uthmani":"٥","transliteration":"","translation_bn":"(৫)","root":"—","lemma":"٥","grammar_bn":"মার্কার"}]'::jsonb, 'ulāika alladhīna lahum sūu l-ʿadhābi wahum fī l-ākhirati humu l-akhsarūna', 'এরাই হল যাদের জন্য রয়েছে কঠিন শাস্তি আর এরাই আখিরাতে সবচেয়ে ক্ষতিগ্রস্ত।', 'Those are the ones for whom there will be the worst of punishment, and in the Hereafter they are the greatest losers.', 'এরাই হল যাদের জন্য রয়েছে কঠিন শাস্তি আর এরাই আখিরাতে সবচেয়ে ক্ষতিগ্রস্ত।', 'Those are the ones for whom there will be the worst of punishment, and in the Hereafter they are the greatest losers.', NULL, NULL, NULL, NULL, NULL, 'https://everyayah.com/data/Alafasy_128kbps/027005.mp3', now()),
  (27, 6, '', '[{"id":6789,"position":1,"text_uthmani":"وَإِنَّكَ","transliteration":"wa-innaka","translation_bn":"আর (হে নাবী) নিশ্চয়ই তুমি","root":"—","lemma":"إِنّ","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":6790,"position":2,"text_uthmani":"لَتُلَقَّى","transliteration":"latulaqqā","translation_bn":"অবশ্যই লাভ করেছো","root":"لقي","lemma":"لَقَّىٰ","grammar_bn":"দৃঢ়তাবোধক (Emphatic)"},{"id":6791,"position":3,"text_uthmani":"ٱلْقُرْءَانَ","transliteration":"l-qur''āna","translation_bn":"(এই) কুরআন","root":"قرا","lemma":"قُرْءَان","grammar_bn":"শব্দ"},{"id":6792,"position":4,"text_uthmani":"مِن","transliteration":"min","translation_bn":"হ''তে","root":"—","lemma":"مِن\r","grammar_bn":"অব্যয় (Preposition)"},{"id":6793,"position":5,"text_uthmani":"لَّدُنْ","transliteration":"ladun","translation_bn":"পক্ষ","root":"لدن","lemma":"لَّدُن","grammar_bn":"বিশেষ্য (Noun)"},{"id":6794,"position":6,"text_uthmani":"حَكِيمٍ","transliteration":"ḥakīmin","translation_bn":"মহাবিজ্ঞ","root":"حكم","lemma":"حَكِيم","grammar_bn":"বিশেষ্য (Noun)"},{"id":6795,"position":7,"text_uthmani":"عَلِيمٍ","transliteration":"ʿalīmin","translation_bn":"সর্বাধিক জ্ঞানী (আল্লাহর)","root":"علم","lemma":"عَلِيم","grammar_bn":"বিশেষণ (Adjective)"},{"id":6796,"position":8,"text_uthmani":"٦","transliteration":"","translation_bn":"(৬)","root":"—","lemma":"٦","grammar_bn":"মার্কার"}]'::jsonb, 'wa-innaka latulaqqā l-qur''āna min ladun ḥakīmin ʿalīmin', 'নিশ্চয় তোমাকে কুরআন দেয়া হয়েছে মহাবিজ্ঞ সর্বজ্ঞের নিকট হতে।', 'And indeed, [O Muhammad], you receive the Qur''an from one Wise and Knowing.', 'নিশ্চয় তোমাকে কুরআন দেয়া হয়েছে মহাবিজ্ঞ সর্বজ্ঞের নিকট হতে।', 'And indeed, [O Muhammad], you receive the Qur''an from one Wise and Knowing.', NULL, NULL, NULL, NULL, NULL, 'https://everyayah.com/data/Alafasy_128kbps/027006.mp3', now()),
  (27, 7, '', '[{"id":8131,"position":1,"text_uthmani":"إِذْ","transliteration":"idh","translation_bn":"(স্মরণ করো) যখন","root":"—","lemma":"إِذ\r","grammar_bn":"কালবাচক (Time)"},{"id":8132,"position":2,"text_uthmani":"قَالَ","transliteration":"qāla","translation_bn":"বলেছিলো","root":"قول","lemma":"قَالَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":8133,"position":3,"text_uthmani":"مُوسَىٰ","transliteration":"mūsā","translation_bn":"মূসা","root":"—","lemma":"مُوسَىٰ","grammar_bn":"নামবাচক বিশেষ্য (Proper Noun)"},{"id":8134,"position":4,"text_uthmani":"لِأَهْلِهِۦٓ","transliteration":"li-ahlihi","translation_bn":"উদ্দেশ্যে তার পরিবারের","root":"اهل","lemma":"أَهْل","grammar_bn":"অব্যয় (Preposition)"},{"id":8135,"position":5,"text_uthmani":"إِنِّىٓ","transliteration":"innī","translation_bn":"\"নিশ্চয়ই আমি","root":"—","lemma":"إِنّ","grammar_bn":"অভিঘাত পদ (Accusative)"},{"id":8136,"position":6,"text_uthmani":"ءَانَسْتُ","transliteration":"ānastu","translation_bn":"দেখেছি","root":"انس","lemma":"ءَانَسَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":8137,"position":7,"text_uthmani":"نَارًۭا","transliteration":"nāran","translation_bn":"আগুন","root":"نور","lemma":"نَار","grammar_bn":"বিশেষ্য (Noun)"},{"id":8138,"position":8,"text_uthmani":"سَـَٔاتِيكُم","transliteration":"saātīkum","translation_bn":"অচিরেই তোমাদের (কাছে) আসবো আমি","root":"اتي","lemma":"أَتَى","grammar_bn":"ভবিষ্যদ্বাচক (Future)"},{"id":8139,"position":9,"text_uthmani":"مِّنْهَا","transliteration":"min''hā","translation_bn":"তা হ''তে","root":"—","lemma":"مِن\r","grammar_bn":"অব্যয় (Preposition)"},{"id":8140,"position":10,"text_uthmani":"بِخَبَرٍ","transliteration":"bikhabarin","translation_bn":"নিয়ে কোনো সংবাদ","root":"خبر","lemma":"خَبَر","grammar_bn":"অব্যয় (Preposition)"},{"id":8141,"position":11,"text_uthmani":"أَوْ","transliteration":"aw","translation_bn":"অথবা","root":"—","lemma":"أَو\r","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":8142,"position":12,"text_uthmani":"ءَاتِيكُم","transliteration":"ātīkum","translation_bn":"তোমাদের (কাছে) আসবো আমি","root":"اتي","lemma":"أَتَى","grammar_bn":"ক্রিয়া (Verb)"},{"id":8143,"position":13,"text_uthmani":"بِشِهَابٍۢ","transliteration":"bishihābin","translation_bn":"নিয়ে জ্বলন্ত","root":"شهب","lemma":"شِهَاب","grammar_bn":"অব্যয় (Preposition)"},{"id":8144,"position":14,"text_uthmani":"قَبَسٍۢ","transliteration":"qabasin","translation_bn":"অঙ্গার","root":"قبس","lemma":"قَبَس","grammar_bn":"বিশেষ্য (Noun)"},{"id":8145,"position":15,"text_uthmani":"لَّعَلَّكُمْ","transliteration":"laʿallakum","translation_bn":"যাতে তোমরা","root":"—","lemma":"لَعَلّ","grammar_bn":"অভিঘাত পদ (Accusative)"},{"id":8146,"position":16,"text_uthmani":"تَصْطَلُونَ","transliteration":"taṣṭalūna","translation_bn":"আগুন পোহাতে পারো\"","root":"صلي","lemma":"تَصْطَلُ","grammar_bn":"ক্রিয়া (Verb)"},{"id":8147,"position":17,"text_uthmani":"٧","transliteration":"","translation_bn":"(৭)","root":"—","lemma":"٧","grammar_bn":"মার্কার"}]'::jsonb, 'idh qāla mūsā li-ahlihi innī ānastu nāran saātīkum min''hā bikhabarin aw ātīkum bishihābin qabasin laʿallakum taṣṭalūna', 'স্মরণ কর যখন মূসা তার পরিবারবর্গকে বলেছিল- ‘আমি আগুন দেখেছি, কাজেই আমি শীঘ্রই সেখান থেকে তোমাদের জন্য খবর নিয়ে আসব কিংবা তোমাদের কাছে জ্বলন্ত আগুন নিয়ে আসব যাতে তোমরা আগুন পোহাতে পার।’', '[Mention] when Moses said to his family, "Indeed, I have perceived a fire. I will bring you from there information or will bring you a burning torch that you may warm yourselves."', 'স্মরণ কর যখন মূসা তার পরিবারবর্গকে বলেছিল- ‘আমি আগুন দেখেছি, কাজেই আমি শীঘ্রই সেখান থেকে তোমাদের জন্য খবর নিয়ে আসব কিংবা তোমাদের কাছে জ্বলন্ত আগুন নিয়ে আসব যাতে তোমরা আগুন পোহাতে পার।’', '[Mention] when Moses said to his family, "Indeed, I have perceived a fire. I will bring you from there information or will bring you a burning torch that you may warm yourselves."', NULL, NULL, NULL, NULL, NULL, 'https://everyayah.com/data/Alafasy_128kbps/027007.mp3', now()),
  (27, 8, '', '[{"id":9300,"position":1,"text_uthmani":"فَلَمَّا","transliteration":"falammā","translation_bn":"অতঃপর যখন","root":"—","lemma":"لَمَّا\r","grammar_bn":"শব্দ"},{"id":9301,"position":2,"text_uthmani":"جَآءَهَا","transliteration":"jāahā","translation_bn":"সেখানে সে আসলো","root":"جيا","lemma":"جَا^ءَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":9302,"position":3,"text_uthmani":"نُودِىَ","transliteration":"nūdiya","translation_bn":"ডাক দেয়া হলো","root":"ندو","lemma":"نَادَىٰ","grammar_bn":"ক্রিয়া (Verb)"},{"id":9303,"position":4,"text_uthmani":"أَنۢ","transliteration":"an","translation_bn":"যে","root":"—","lemma":"أَن\r","grammar_bn":"উদ্দেশ্যবাচক (Intention)"},{"id":9304,"position":5,"text_uthmani":"بُورِكَ","transliteration":"būrika","translation_bn":"\"সে হয়েছে ধন্য","root":"برك","lemma":"بَٰرَكَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":9305,"position":6,"text_uthmani":"مَن","transliteration":"man","translation_bn":"যে (আছে)","root":"—","lemma":"مَن\r","grammar_bn":"সাপেক্ষ সর্বনাম (Relative)"},{"id":9306,"position":7,"text_uthmani":"فِى","transliteration":"fī","translation_bn":"মধ্যে","root":"—","lemma":"فِى\r","grammar_bn":"অব্যয় (Preposition)"},{"id":9307,"position":8,"text_uthmani":"ٱلنَّارِ","transliteration":"l-nāri","translation_bn":"আগুনের (আলোর)","root":"نور","lemma":"نَار","grammar_bn":"শব্দ"},{"id":9308,"position":9,"text_uthmani":"وَمَنْ","transliteration":"waman","translation_bn":"এবং যে (আছে)","root":"—","lemma":"مَن\r","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":9309,"position":10,"text_uthmani":"حَوْلَهَا","transliteration":"ḥawlahā","translation_bn":"তার চারপাশে","root":"حول","lemma":"حَوْل","grammar_bn":"বিশেষ্য (Noun)"},{"id":9310,"position":11,"text_uthmani":"وَسُبْحَـٰنَ","transliteration":"wasub''ḥāna","translation_bn":"এবং পবিত্র মহান","root":"سبح","lemma":"سُبْحَٰن","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":9311,"position":12,"text_uthmani":"ٱللَّهِ","transliteration":"l-lahi","translation_bn":"আল্লাহ","root":"اله","lemma":"ٱللَّه","grammar_bn":"নামবাচক বিশেষ্য (Proper Noun)"},{"id":9312,"position":13,"text_uthmani":"رَبِّ","transliteration":"rabbi","translation_bn":"রব","root":"ربب","lemma":"رَبّ","grammar_bn":"বিশেষ্য (Noun)"},{"id":9313,"position":14,"text_uthmani":"ٱلْعَـٰلَمِينَ","transliteration":"l-ʿālamīna","translation_bn":"বিশ্বজগতের","root":"علم","lemma":"عَٰلَمِين","grammar_bn":"শব্দ"},{"id":9314,"position":15,"text_uthmani":"٨","transliteration":"","translation_bn":"(৮)","root":"—","lemma":"٨","grammar_bn":"মার্কার"}]'::jsonb, 'falammā jāahā nūdiya an būrika man fī l-nāri waman ḥawlahā wasub''ḥāna l-lahi rabbi l-ʿālamīna', 'অতঃপর সে যখন আগুনের কাছে আসল তখন আওয়াজ হল- ‘ধন্য, যারা আছে এই আলোর মধ্যে আর তার আশেপাশে, বিশ্বজাহানের প্রতিপালক পবিত্র, মহিমান্বিত।', 'But when he came to it, he was called, "Blessed is whoever is at the fire and whoever is around it. And exalted is Allah, Lord of the worlds.', 'অতঃপর সে যখন আগুনের কাছে আসল তখন আওয়াজ হল- ‘ধন্য, যারা আছে এই আলোর মধ্যে আর তার আশেপাশে, বিশ্বজাহানের প্রতিপালক পবিত্র, মহিমান্বিত।', 'But when he came to it, he was called, "Blessed is whoever is at the fire and whoever is around it. And exalted is Allah, Lord of the worlds.', NULL, NULL, NULL, NULL, NULL, 'https://everyayah.com/data/Alafasy_128kbps/027008.mp3', now()),
  (27, 9, '', '[{"id":10490,"position":1,"text_uthmani":"يَـٰمُوسَىٰٓ","transliteration":"yāmūsā","translation_bn":"হে মূসা (প্রকৃত ব্যাপার হলো)","root":"—","lemma":"مُوسَىٰ","grammar_bn":"সম্বোধন পদ (Vocative)"},{"id":10491,"position":2,"text_uthmani":"إِنَّهُۥٓ","transliteration":"innahu","translation_bn":"নিশ্চয়ই তিনি","root":"—","lemma":"إِنّ","grammar_bn":"অভিঘাত পদ (Accusative)"},{"id":10492,"position":3,"text_uthmani":"أَنَا","transliteration":"anā","translation_bn":"আমি","root":"—","lemma":"أَنَا","grammar_bn":"সর্বনাম (Pronoun)"},{"id":10493,"position":4,"text_uthmani":"ٱللَّهُ","transliteration":"l-lahu","translation_bn":"আল্লাহ","root":"اله","lemma":"ٱللَّه","grammar_bn":"নামবাচক বিশেষ্য (Proper Noun)"},{"id":10494,"position":5,"text_uthmani":"ٱلْعَزِيزُ","transliteration":"l-ʿazīzu","translation_bn":"মহাপরাক্রমশালী","root":"عزز","lemma":"عَزِيز","grammar_bn":"শব্দ"},{"id":10495,"position":6,"text_uthmani":"ٱلْحَكِيمُ","transliteration":"l-ḥakīmu","translation_bn":"প্রজ্ঞামময়\"","root":"حكم","lemma":"حَكِيم","grammar_bn":"শব্দ"},{"id":10496,"position":7,"text_uthmani":"٩","transliteration":"","translation_bn":"(৯)","root":"—","lemma":"٩","grammar_bn":"মার্কার"}]'::jsonb, 'yāmūsā innahu anā l-lahu l-ʿazīzu l-ḥakīmu', 'হে মূসা! আমি মহা পরাক্রান্ত প্রজ্ঞাময় আল্লাহ।', 'O Moses, indeed it is I - Allah, the Exalted in Might, the Wise."', 'হে মূসা! আমি মহা পরাক্রান্ত প্রজ্ঞাময় আল্লাহ।', 'O Moses, indeed it is I - Allah, the Exalted in Might, the Wise."', NULL, NULL, NULL, NULL, NULL, 'https://everyayah.com/data/Alafasy_128kbps/027009.mp3', now()),
  (27, 10, '', '[{"id":11699,"position":1,"text_uthmani":"وَأَلْقِ","transliteration":"wa-alqi","translation_bn":"আর (হে মূসা) তুমি ছোঁড়ো","root":"لقي","lemma":"أَلْقَىٰ^","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":11700,"position":2,"text_uthmani":"عَصَاكَ ۚ","transliteration":"ʿaṣāka","translation_bn":"তোমার লাঠি\"","root":"عصو","lemma":"عَصَا2","grammar_bn":"বিশেষ্য (Noun)"},{"id":11702,"position":3,"text_uthmani":"فَلَمَّا","transliteration":"falammā","translation_bn":"অতঃপর যখন","root":"—","lemma":"لَمَّا\r","grammar_bn":"শব্দ"},{"id":11703,"position":4,"text_uthmani":"رَءَاهَا","transliteration":"raāhā","translation_bn":"সে দেখলো তা","root":"راي","lemma":"رَءَا","grammar_bn":"ক্রিয়া (Verb)"},{"id":11704,"position":5,"text_uthmani":"تَهْتَزُّ","transliteration":"tahtazzu","translation_bn":"গড়িয়ে চলছে","root":"هزز","lemma":"ٱهْتَزَّتْ","grammar_bn":"ক্রিয়া (Verb)"},{"id":11705,"position":6,"text_uthmani":"كَأَنَّهَا","transliteration":"ka-annahā","translation_bn":"যেন তা","root":"—","lemma":"كَأَنّ","grammar_bn":"অভিঘাত পদ (Accusative)"},{"id":11706,"position":7,"text_uthmani":"جَآنٌّۭ","transliteration":"jānnun","translation_bn":"সাপ","root":"جنن","lemma":"جَا^نّ","grammar_bn":"বিশেষ্য (Noun)"},{"id":11707,"position":8,"text_uthmani":"وَلَّىٰ","transliteration":"wallā","translation_bn":"সে ফিরে পালালো","root":"ولي","lemma":"وَلَّىٰ","grammar_bn":"ক্রিয়া (Verb)"},{"id":11708,"position":9,"text_uthmani":"مُدْبِرًۭا","transliteration":"mud''biran","translation_bn":"পিছন দিকে","root":"دبر","lemma":"مُدْبِر","grammar_bn":"বিশেষ্য (Noun)"},{"id":11709,"position":10,"text_uthmani":"وَلَمْ","transliteration":"walam","translation_bn":"আর না","root":"—","lemma":"لَم\r","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":11710,"position":11,"text_uthmani":"يُعَقِّبْ ۚ","transliteration":"yuʿaqqib","translation_bn":"পিছন দিকে দেখলো","root":"عقب","lemma":"يُعَقِّبْ","grammar_bn":"ক্রিয়া (Verb)"},{"id":11712,"position":12,"text_uthmani":"يَـٰمُوسَىٰ","transliteration":"yāmūsā","translation_bn":"\"(বলা হলো) হে মূসা","root":"—","lemma":"مُوسَىٰ","grammar_bn":"সম্বোধন পদ (Vocative)"},{"id":11713,"position":13,"text_uthmani":"لَا","transliteration":"lā","translation_bn":"না","root":"—","lemma":"لَا\r","grammar_bn":"নিষেধবাচক (Prohibition)"},{"id":11714,"position":14,"text_uthmani":"تَخَفْ","transliteration":"takhaf","translation_bn":"ভয় করো","root":"خوف","lemma":"خَافَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":11715,"position":15,"text_uthmani":"إِنِّى","transliteration":"innī","translation_bn":"আমি নিশ্চয়ই (এমন যে)","root":"—","lemma":"إِنّ","grammar_bn":"অভিঘাত পদ (Accusative)"},{"id":11716,"position":16,"text_uthmani":"لَا","transliteration":"lā","translation_bn":"না","root":"—","lemma":"لَا\r","grammar_bn":"না-বোধক (Negative)"},{"id":11717,"position":17,"text_uthmani":"يَخَافُ","transliteration":"yakhāfu","translation_bn":"ভয় করে","root":"خوف","lemma":"خَافَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":11718,"position":18,"text_uthmani":"لَدَىَّ","transliteration":"ladayya","translation_bn":"নিকট আমার","root":"—","lemma":"لَدَي\r","grammar_bn":"স্থানবাচক (Location)"},{"id":11719,"position":19,"text_uthmani":"ٱلْمُرْسَلُونَ","transliteration":"l-mur''salūna","translation_bn":"রাসূলরা","root":"رسل","lemma":"مُّرْسَل","grammar_bn":"শব্দ"},{"id":11720,"position":20,"text_uthmani":"١٠","transliteration":"","translation_bn":"(১০)","root":"—","lemma":"١٠","grammar_bn":"মার্কার"}]'::jsonb, 'wa-alqi ʿaṣāka falammā raāhā tahtazzu ka-annahā jānnun wallā mud''biran walam yuʿaqqib yāmūsā lā takhaf innī lā yakhāfu ladayya l-mur''salūna', 'তুমি তোমার লাঠি নিক্ষেপ কর; অতঃপর যখন সে ওটাকে ছুটাছুটি করতে দেখল যেন ওটা একটা সাপ, তখন সে পেছনের দিকে ছুটতে লাগল এবং ফিরেও দেখল না। (তখন বলা হল) হে মূসা! তুমি ভয় করো না, নিশ্চয়ই আমার কাছে রসূলগণ ভয় পায় না।', 'And [he was told], "Throw down your staff." But when he saw it writhing as if it were a snake, he turned in flight and did not return. [Allah said], "O Moses, fear not. Indeed, in My presence the messengers do not fear.', 'তুমি তোমার লাঠি নিক্ষেপ কর; অতঃপর যখন সে ওটাকে ছুটাছুটি করতে দেখল যেন ওটা একটা সাপ, তখন সে পেছনের দিকে ছুটতে লাগল এবং ফিরেও দেখল না। (তখন বলা হল) হে মূসা! তুমি ভয় করো না, নিশ্চয়ই আমার কাছে রসূলগণ ভয় পায় না।', 'And [he was told], "Throw down your staff." But when he saw it writhing as if it were a snake, he turned in flight and did not return. [Allah said], "O Moses, fear not. Indeed, in My presence the messengers do not fear.', NULL, NULL, NULL, NULL, NULL, 'https://everyayah.com/data/Alafasy_128kbps/027010.mp3', now()),
  (27, 11, '', '[{"id":13064,"position":1,"text_uthmani":"إِلَّا","transliteration":"illā","translation_bn":"কিন্তু","root":"—","lemma":"إِلَّا\r","grammar_bn":"সীমাবদ্ধতা (Restriction)"},{"id":13065,"position":2,"text_uthmani":"مَن","transliteration":"man","translation_bn":"যে","root":"—","lemma":"مَن\r","grammar_bn":"সাপেক্ষ সর্বনাম (Relative)"},{"id":13066,"position":3,"text_uthmani":"ظَلَمَ","transliteration":"ẓalama","translation_bn":"সীমালঙ্ঘন করে","root":"ظلم","lemma":"ظَلَمَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":13067,"position":4,"text_uthmani":"ثُمَّ","transliteration":"thumma","translation_bn":"এরপর","root":"—","lemma":"ثُمّ\r","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":13068,"position":5,"text_uthmani":"بَدَّلَ","transliteration":"baddala","translation_bn":"বদলে নেয় (নিজের কর্মকে)","root":"بدل","lemma":"بَدَّلَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":13069,"position":6,"text_uthmani":"حُسْنًۢا","transliteration":"ḥus''nan","translation_bn":"সৎকর্ম (দিয়ে)","root":"حسن","lemma":"حُسْن","grammar_bn":"বিশেষ্য (Noun)"},{"id":13070,"position":7,"text_uthmani":"بَعْدَ","transliteration":"baʿda","translation_bn":"পরে","root":"بعد","lemma":"بَعْد","grammar_bn":"কালবাচক (Time)"},{"id":13071,"position":8,"text_uthmani":"سُوٓءٍۢ","transliteration":"sūin","translation_bn":"মন্দ কর্মের","root":"سوا","lemma":"سُو^ء","grammar_bn":"বিশেষ্য (Noun)"},{"id":13072,"position":9,"text_uthmani":"فَإِنِّى","transliteration":"fa-innī","translation_bn":"সেক্ষেত্রে আমি নিশ্চয়ই","root":"—","lemma":"إِنّ","grammar_bn":"শব্দ"},{"id":13073,"position":10,"text_uthmani":"غَفُورٌۭ","transliteration":"ghafūrun","translation_bn":"ক্ষমাশীল","root":"غفر","lemma":"غَفُور","grammar_bn":"বিশেষ্য (Noun)"},{"id":13074,"position":11,"text_uthmani":"رَّحِيمٌۭ","transliteration":"raḥīmun","translation_bn":"পরম দয়ালু","root":"رحم","lemma":"رَّحِيم","grammar_bn":"বিশেষণ (Adjective)"},{"id":13075,"position":12,"text_uthmani":"١١","transliteration":"","translation_bn":"(১১)","root":"—","lemma":"١١","grammar_bn":"মার্কার"}]'::jsonb, 'illā man ẓalama thumma baddala ḥus''nan baʿda sūin fa-innī ghafūrun raḥīmun', 'তবে যে অত্যাচার করে অতঃপর মন্দ কাজের পরিবর্তে সৎ কাজ করে, তাহলে নিশ্চয় আমি ক্ষমাশীল, বড়ই দয়ালু।', 'Otherwise, he who wrongs, then substitutes good after evil - indeed, I am Forgiving and Merciful.', 'তবে যে অত্যাচার করে অতঃপর মন্দ কাজের পরিবর্তে সৎ কাজ করে, তাহলে নিশ্চয় আমি ক্ষমাশীল, বড়ই দয়ালু।', 'Otherwise, he who wrongs, then substitutes good after evil - indeed, I am Forgiving and Merciful.', NULL, NULL, NULL, NULL, NULL, 'https://everyayah.com/data/Alafasy_128kbps/027011.mp3', now()),
  (27, 12, '', '[{"id":14328,"position":1,"text_uthmani":"وَأَدْخِلْ","transliteration":"wa-adkhil","translation_bn":"এবং (হে মূসা) প্রবেশ করাও","root":"دخل","lemma":"أُدْخِلَ","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":14329,"position":2,"text_uthmani":"يَدَكَ","transliteration":"yadaka","translation_bn":"তোমার হাত","root":"يدي","lemma":"يَد","grammar_bn":"বিশেষ্য (Noun)"},{"id":14330,"position":3,"text_uthmani":"فِى","transliteration":"fī","translation_bn":"মধ্যে","root":"—","lemma":"فِى\r","grammar_bn":"অব্যয় (Preposition)"},{"id":14331,"position":4,"text_uthmani":"جَيْبِكَ","transliteration":"jaybika","translation_bn":"তোমার বক্ষপাশে (অর্থাৎ বগলে)","root":"جيب","lemma":"جَيْب","grammar_bn":"বিশেষ্য (Noun)"},{"id":14332,"position":5,"text_uthmani":"تَخْرُجْ","transliteration":"takhruj","translation_bn":"তা বের হয়ে আসবে","root":"خرج","lemma":"خَرَجَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":14333,"position":6,"text_uthmani":"بَيْضَآءَ","transliteration":"bayḍāa","translation_bn":"শুভ্র উজ্জ্বল হয়ে","root":"بيض","lemma":"أَبْيَض","grammar_bn":"বিশেষ্য (Noun)"},{"id":14334,"position":7,"text_uthmani":"مِنْ","transliteration":"min","translation_bn":"কোনো","root":"—","lemma":"مِن\r","grammar_bn":"অব্যয় (Preposition)"},{"id":14335,"position":8,"text_uthmani":"غَيْرِ","transliteration":"ghayri","translation_bn":"ছাড়াই","root":"غير","lemma":"غَيْر","grammar_bn":"বিশেষ্য (Noun)"},{"id":14336,"position":9,"text_uthmani":"سُوٓءٍۢ ۖ","transliteration":"sūin","translation_bn":"অনিষ্ট","root":"سوا","lemma":"سُو^ء","grammar_bn":"বিশেষ্য (Noun)"},{"id":14338,"position":10,"text_uthmani":"فِى","transliteration":"fī","translation_bn":"(এটা) অন্তর্গত","root":"—","lemma":"فِى\r","grammar_bn":"অব্যয় (Preposition)"},{"id":14339,"position":11,"text_uthmani":"تِسْعِ","transliteration":"tis''ʿi","translation_bn":"নয়টি","root":"تسع","lemma":"تِسْع","grammar_bn":"বিশেষ্য (Noun)"},{"id":14340,"position":12,"text_uthmani":"ءَايَـٰتٍ","transliteration":"āyātin","translation_bn":"নিদর্শনের","root":"ايي","lemma":"ءَايَة","grammar_bn":"বিশেষ্য (Noun)"},{"id":14341,"position":13,"text_uthmani":"إِلَىٰ","transliteration":"ilā","translation_bn":"(এ নিয়ে যাও) প্রতি","root":"—","lemma":"إِلَىٰ\r","grammar_bn":"অব্যয় (Preposition)"},{"id":14342,"position":14,"text_uthmani":"فِرْعَوْنَ","transliteration":"fir''ʿawna","translation_bn":"ফিরআউনের","root":"—","lemma":"فِرْعَوْن","grammar_bn":"নামবাচক বিশেষ্য (Proper Noun)"},{"id":14343,"position":15,"text_uthmani":"وَقَوْمِهِۦٓ ۚ","transliteration":"waqawmihi","translation_bn":"ও তার জাতির (কাছে)","root":"قوم","lemma":"قَوْم","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":14345,"position":16,"text_uthmani":"إِنَّهُمْ","transliteration":"innahum","translation_bn":"তারা নিশ্চয়ই","root":"—","lemma":"إِنّ","grammar_bn":"অভিঘাত পদ (Accusative)"},{"id":14346,"position":17,"text_uthmani":"كَانُوا۟","transliteration":"kānū","translation_bn":"হলো","root":"كون","lemma":"كَانَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":14347,"position":18,"text_uthmani":"قَوْمًۭا","transliteration":"qawman","translation_bn":"লোক","root":"قوم","lemma":"قَوْم","grammar_bn":"বিশেষ্য (Noun)"},{"id":14348,"position":19,"text_uthmani":"فَـٰسِقِينَ","transliteration":"fāsiqīna","translation_bn":"(দুষ্কর্মপরায়ন) সত্য-ত্যাগী\"","root":"فسق","lemma":"فَاسِق","grammar_bn":"বিশেষণ (Adjective)"},{"id":14349,"position":20,"text_uthmani":"١٢","transliteration":"","translation_bn":"(১২)","root":"—","lemma":"١٢","grammar_bn":"মার্কার"}]'::jsonb, 'wa-adkhil yadaka fī jaybika takhruj bayḍāa min ghayri sūin fī tis''ʿi āyātin ilā fir''ʿawna waqawmihi innahum kānū qawman fāsiqīna', 'আর তুমি তোমার হাত বগলে ঢুকাও, তা শুভ্র হয়ে বের হয়ে আসবে দোষমুক্ত অবস্থায়, তা হল ফেরাউন ও তার সম্প্রদায়ের নিকট নিয়ে আসা নয়টি নিদর্শনের অন্তর্ভুক্ত। নিশ্চয় তারা ছিল পাপাচারী সম্প্রদায়।', 'And put your hand into the opening of your garment [at the breast]; it will come out white without disease. [These are] among the nine signs [you will take] to Pharaoh and his people. Indeed, they have been a people defiantly disobedient."', 'আর তুমি তোমার হাত বগলে ঢুকাও, তা শুভ্র হয়ে বের হয়ে আসবে দোষমুক্ত অবস্থায়, তা হল ফেরাউন ও তার সম্প্রদায়ের নিকট নিয়ে আসা নয়টি নিদর্শনের অন্তর্ভুক্ত। নিশ্চয় তারা ছিল পাপাচারী সম্প্রদায়।', 'And put your hand into the opening of your garment [at the breast]; it will come out white without disease. [These are] among the nine signs [you will take] to Pharaoh and his people. Indeed, they have been a people defiantly disobedient."', NULL, NULL, NULL, NULL, NULL, 'https://everyayah.com/data/Alafasy_128kbps/027012.mp3', now()),
  (27, 13, '', '[{"id":15442,"position":1,"text_uthmani":"فَلَمَّا","transliteration":"falammā","translation_bn":"অতঃপর যখন","root":"—","lemma":"لَمَّا\r","grammar_bn":"শব্দ"},{"id":15443,"position":2,"text_uthmani":"جَآءَتْهُمْ","transliteration":"jāathum","translation_bn":"তাদের (নিকট) আসলো","root":"جيا","lemma":"جَا^ءَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":15444,"position":3,"text_uthmani":"ءَايَـٰتُنَا","transliteration":"āyātunā","translation_bn":"নিদর্শনাবলী আমাদের","root":"ايي","lemma":"ءَايَة","grammar_bn":"বিশেষ্য (Noun)"},{"id":15445,"position":4,"text_uthmani":"مُبْصِرَةًۭ","transliteration":"mub''ṣiratan","translation_bn":"উজ্জ্বল হয়ে","root":"بصر","lemma":"مُبْصِرَة","grammar_bn":"বিশেষ্য (Noun)"},{"id":15446,"position":5,"text_uthmani":"قَالُوا۟","transliteration":"qālū","translation_bn":"তারা বললো","root":"قول","lemma":"قَالَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":15447,"position":6,"text_uthmani":"هَـٰذَا","transliteration":"hādhā","translation_bn":"\"এটা","root":"—","lemma":"هَٰذَا","grammar_bn":"নির্দেশক সর্বনাম (Demonstrative)"},{"id":15448,"position":7,"text_uthmani":"سِحْرٌۭ","transliteration":"siḥ''run","translation_bn":"জাদু","root":"سحر","lemma":"سِحْر","grammar_bn":"বিশেষ্য (Noun)"},{"id":15449,"position":8,"text_uthmani":"مُّبِينٌۭ","transliteration":"mubīnun","translation_bn":"সুস্পষ্ট\"","root":"بين","lemma":"مُّبِين","grammar_bn":"বিশেষণ (Adjective)"},{"id":15450,"position":9,"text_uthmani":"١٣","transliteration":"","translation_bn":"(১৩)","root":"—","lemma":"١٣","grammar_bn":"মার্কার"}]'::jsonb, 'falammā jāathum āyātunā mub''ṣiratan qālū hādhā siḥ''run mubīnun', 'অতঃপর যখন তাদের কাছে আমার দৃশ্যমান নিদর্শন আসল, তারা বলল- ‘এটা স্পষ্ট যাদু।', 'But when there came to them Our visible signs, they said, "This is obvious magic."', 'অতঃপর যখন তাদের কাছে আমার দৃশ্যমান নিদর্শন আসল, তারা বলল- ‘এটা স্পষ্ট যাদু।', 'But when there came to them Our visible signs, they said, "This is obvious magic."', NULL, NULL, NULL, NULL, NULL, 'https://everyayah.com/data/Alafasy_128kbps/027013.mp3', now()),
  (27, 14, '', '[{"id":16492,"position":1,"text_uthmani":"وَجَحَدُوا۟","transliteration":"wajaḥadū","translation_bn":"এবং তারা প্রত্যাখ্যান করলো","root":"جحد","lemma":"جَحَدُ","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":16493,"position":2,"text_uthmani":"بِهَا","transliteration":"bihā","translation_bn":"প্রতি সেগুলোর","root":"—","lemma":"بِهَا","grammar_bn":"অব্যয় (Preposition)"},{"id":16494,"position":3,"text_uthmani":"وَٱسْتَيْقَنَتْهَآ","transliteration":"wa-is''tayqanathā","translation_bn":"অথচ সেগুলো মেনে নিয়েছিলো","root":"يقن","lemma":"ٱسْتَيْقَنَتْ","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":16495,"position":4,"text_uthmani":"أَنفُسُهُمْ","transliteration":"anfusuhum","translation_bn":"তাদের অন্তরগুলো (কিন্তু অমান্য করলো)","root":"نفس","lemma":"نَفْس","grammar_bn":"বিশেষ্য (Noun)"},{"id":16496,"position":5,"text_uthmani":"ظُلْمًۭا","transliteration":"ẓul''man","translation_bn":"অন্যায়ভাবে","root":"ظلم","lemma":"ظُلْم","grammar_bn":"বিশেষ্য (Noun)"},{"id":16497,"position":6,"text_uthmani":"وَعُلُوًّۭا ۚ","transliteration":"waʿuluwwan","translation_bn":"ও অহংকারবশত","root":"علو","lemma":"عُلُوّ","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":16499,"position":7,"text_uthmani":"فَٱنظُرْ","transliteration":"fa-unẓur","translation_bn":"তাই দেখো","root":"نظر","lemma":"نَّظَرَ","grammar_bn":"শব্দ"},{"id":16500,"position":8,"text_uthmani":"كَيْفَ","transliteration":"kayfa","translation_bn":"কেমন","root":"كيف\r","lemma":"كَيْف","grammar_bn":"প্রশ্নবোধক (Interrogative)"},{"id":16501,"position":9,"text_uthmani":"كَانَ","transliteration":"kāna","translation_bn":"ছিলো","root":"كون","lemma":"كَانَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":16502,"position":10,"text_uthmani":"عَـٰقِبَةُ","transliteration":"ʿāqibatu","translation_bn":"পরিণাম","root":"عقب","lemma":"عَٰقِبَة","grammar_bn":"বিশেষ্য (Noun)"},{"id":16503,"position":11,"text_uthmani":"ٱلْمُفْسِدِينَ","transliteration":"l-muf''sidīna","translation_bn":"বিপর্যয় সৃষ্টিকারীদের","root":"فسد","lemma":"مُفْسِد","grammar_bn":"শব্দ"},{"id":16504,"position":12,"text_uthmani":"١٤","transliteration":"","translation_bn":"(১৪)","root":"—","lemma":"١٤","grammar_bn":"মার্কার"}]'::jsonb, 'wajaḥadū bihā wa-is''tayqanathā anfusuhum ẓul''man waʿuluwwan fa-unẓur kayfa kāna ʿāqibatu l-muf''sidīna', 'তারা অন্যায় ঔদ্ধত্যভরে নিদর্শনগুলোকে প্রত্যাখ্যান করল যদিও তাদের অন্তর এগুলোকে সত্য বলে বিশ্বাস করেছিল। অতএব দেখ, ফাসাদ সৃষ্টিকারীদের পরিণতি কেমন হয়েছিল!', 'And they rejected them, while their [inner] selves were convinced thereof, out of injustice and haughtiness. So see how was the end of the corrupters.', 'তারা অন্যায় ঔদ্ধত্যভরে নিদর্শনগুলোকে প্রত্যাখ্যান করল যদিও তাদের অন্তর এগুলোকে সত্য বলে বিশ্বাস করেছিল। অতএব দেখ, ফাসাদ সৃষ্টিকারীদের পরিণতি কেমন হয়েছিল!', 'And they rejected them, while their [inner] selves were convinced thereof, out of injustice and haughtiness. So see how was the end of the corrupters.', NULL, NULL, NULL, NULL, NULL, 'https://everyayah.com/data/Alafasy_128kbps/027014.mp3', now()),
  (27, 15, '', '[{"id":17641,"position":1,"text_uthmani":"وَلَقَدْ","transliteration":"walaqad","translation_bn":"এবং নিশ্চয়ই","root":"—","lemma":"قَد\r","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":17642,"position":2,"text_uthmani":"ءَاتَيْنَا","transliteration":"ātaynā","translation_bn":"দান করেছিলাম আমরা","root":"اتي","lemma":"ا^تَى","grammar_bn":"ক্রিয়া (Verb)"},{"id":17643,"position":3,"text_uthmani":"دَاوُۥدَ","transliteration":"dāwūda","translation_bn":"দাউদকে","root":"—","lemma":"دَاوُد","grammar_bn":"নামবাচক বিশেষ্য (Proper Noun)"},{"id":17644,"position":4,"text_uthmani":"وَسُلَيْمَـٰنَ","transliteration":"wasulaymāna","translation_bn":"ও সুলায়মানকে","root":"—","lemma":"سُلَيْمَٰن","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":17645,"position":5,"text_uthmani":"عِلْمًۭا ۖ","transliteration":"ʿil''man","translation_bn":"জ্ঞান","root":"علم","lemma":"عِلْم","grammar_bn":"বিশেষ্য (Noun)"},{"id":17647,"position":6,"text_uthmani":"وَقَالَا","transliteration":"waqālā","translation_bn":"এবং তারা দু''জনে বলেছিলো","root":"قول","lemma":"قَالَ","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":17648,"position":7,"text_uthmani":"ٱلْحَمْدُ","transliteration":"l-ḥamdu","translation_bn":"\"সব প্রশংসা","root":"حمد","lemma":"حَمْد","grammar_bn":"শব্দ"},{"id":17649,"position":8,"text_uthmani":"لِلَّهِ","transliteration":"lillahi","translation_bn":"জন্যে আল্লাহর","root":"اله","lemma":"ٱللَّه","grammar_bn":"অব্যয় (Preposition)"},{"id":17650,"position":9,"text_uthmani":"ٱلَّذِى","transliteration":"alladhī","translation_bn":"যিনি","root":"—","lemma":"ٱلَّذِى","grammar_bn":"সাপেক্ষ সর্বনাম (Relative)"},{"id":17651,"position":10,"text_uthmani":"فَضَّلَنَا","transliteration":"faḍḍalanā","translation_bn":"শ্রেষ্টত্ব দিয়েছেন আমাদেরকে","root":"فضل","lemma":"فَضَّلَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":17652,"position":11,"text_uthmani":"عَلَىٰ","transliteration":"ʿalā","translation_bn":"উপর","root":"—","lemma":"عَلَىٰ\r","grammar_bn":"অব্যয় (Preposition)"},{"id":17653,"position":12,"text_uthmani":"كَثِيرٍۢ","transliteration":"kathīrin","translation_bn":"অনেকের","root":"كثر","lemma":"كَثِير","grammar_bn":"বিশেষ্য (Noun)"},{"id":17654,"position":13,"text_uthmani":"مِّنْ","transliteration":"min","translation_bn":"মধ্য হ''তে","root":"—","lemma":"مِن\r","grammar_bn":"অব্যয় (Preposition)"},{"id":17655,"position":14,"text_uthmani":"عِبَادِهِ","transliteration":"ʿibādihi","translation_bn":"দাসদের","root":"عبد","lemma":"عَبْد","grammar_bn":"বিশেষ্য (Noun)"},{"id":17656,"position":15,"text_uthmani":"ٱلْمُؤْمِنِينَ","transliteration":"l-mu''minīna","translation_bn":"মু''মিন\"","root":"امن","lemma":"مُؤْمِن","grammar_bn":"শব্দ"},{"id":17657,"position":16,"text_uthmani":"١٥","transliteration":"","translation_bn":"(১৫)","root":"—","lemma":"١٥","grammar_bn":"মার্কার"}]'::jsonb, 'walaqad ātaynā dāwūda wasulaymāna ʿil''man waqālā l-ḥamdu lillahi alladhī faḍḍalanā ʿalā kathīrin min ʿibādihi l-mu''minīna', 'আমি দাঊদ ও সুলাইমানকে জ্ঞান দান করেছিলাম। তারা উভয়ে বলেছিল, ‘সকল প্রশংসা আল্লাহর যিনি তাঁর বহু মু’মিন বান্দাদের উপর আমাদেরকে মর্যাদা দান করেছেন।’', 'And We had certainly given to David and Solomon knowledge, and they said, "Praise [is due] to Allah, who has favored us over many of His believing servants."', 'আমি দাঊদ ও সুলাইমানকে জ্ঞান দান করেছিলাম। তারা উভয়ে বলেছিল, ‘সকল প্রশংসা আল্লাহর যিনি তাঁর বহু মু’মিন বান্দাদের উপর আমাদেরকে মর্যাদা দান করেছেন।’', 'And We had certainly given to David and Solomon knowledge, and they said, "Praise [is due] to Allah, who has favored us over many of His believing servants."', NULL, NULL, NULL, NULL, NULL, 'https://everyayah.com/data/Alafasy_128kbps/027015.mp3', now()),
  (27, 16, '', '[{"id":18688,"position":1,"text_uthmani":"وَوَرِثَ","transliteration":"wawaritha","translation_bn":"এবং উত্তরাধিকারী হয়েছে","root":"ورث","lemma":"وَرِثَ","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":18689,"position":2,"text_uthmani":"سُلَيْمَـٰنُ","transliteration":"sulaymānu","translation_bn":"সুলায়মান","root":"—","lemma":"سُلَيْمَٰن","grammar_bn":"নামবাচক বিশেষ্য (Proper Noun)"},{"id":18690,"position":3,"text_uthmani":"دَاوُۥدَ ۖ","transliteration":"dāwūda","translation_bn":"দাউদের","root":"—","lemma":"دَاوُد","grammar_bn":"নামবাচক বিশেষ্য (Proper Noun)"},{"id":18692,"position":4,"text_uthmani":"وَقَالَ","transliteration":"waqāla","translation_bn":"এবং (সুলাইমান) বলেছিলো","root":"قول","lemma":"قَالَ","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":18693,"position":5,"text_uthmani":"يَـٰٓأَيُّهَا","transliteration":"yāayyuhā","translation_bn":"\"হে","root":"—","lemma":"أَيُّهَا","grammar_bn":"সম্বোধন পদ (Vocative)"},{"id":18694,"position":6,"text_uthmani":"ٱلنَّاسُ","transliteration":"l-nāsu","translation_bn":"মানুষ","root":"نوس","lemma":"نَّاس","grammar_bn":"শব্দ"},{"id":18695,"position":7,"text_uthmani":"عُلِّمْنَا","transliteration":"ʿullim''nā","translation_bn":"শিখানো হয়েছে আমাদেরকে","root":"علم","lemma":"عَلَّمَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":18696,"position":8,"text_uthmani":"مَنطِقَ","transliteration":"manṭiqa","translation_bn":"ভাষা","root":"نطق","lemma":"مَنطِق","grammar_bn":"বিশেষ্য (Noun)"},{"id":18697,"position":9,"text_uthmani":"ٱلطَّيْرِ","transliteration":"l-ṭayri","translation_bn":"পাখীদের","root":"طير","lemma":"طَيْر","grammar_bn":"শব্দ"},{"id":18698,"position":10,"text_uthmani":"وَأُوتِينَا","transliteration":"waūtīnā","translation_bn":"এবং দেয়া হয়েছে আমাদেরকে","root":"اتي","lemma":"ا^تَى","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":18699,"position":11,"text_uthmani":"مِن","transliteration":"min","translation_bn":"থেকে","root":"—","lemma":"مِن\r","grammar_bn":"অব্যয় (Preposition)"},{"id":18700,"position":12,"text_uthmani":"كُلِّ","transliteration":"kulli","translation_bn":"সব","root":"كلل","lemma":"كُلّ","grammar_bn":"বিশেষ্য (Noun)"},{"id":18701,"position":13,"text_uthmani":"شَىْءٍ ۖ","transliteration":"shayin","translation_bn":"কিছুই","root":"شيا","lemma":"شَىْء","grammar_bn":"বিশেষ্য (Noun)"},{"id":18703,"position":14,"text_uthmani":"إِنَّ","transliteration":"inna","translation_bn":"নিশ্চয়ই","root":"—","lemma":"إِنّ","grammar_bn":"অভিঘাত পদ (Accusative)"},{"id":18704,"position":15,"text_uthmani":"هَـٰذَا","transliteration":"hādhā","translation_bn":"এটা","root":"—","lemma":"هَٰذَا","grammar_bn":"নির্দেশক সর্বনাম (Demonstrative)"},{"id":18705,"position":16,"text_uthmani":"لَهُوَ","transliteration":"lahuwa","translation_bn":"অবশ্যই তা","root":"—","lemma":"لَهُوَ","grammar_bn":"দৃঢ়তাবোধক (Emphatic)"},{"id":18706,"position":17,"text_uthmani":"ٱلْفَضْلُ","transliteration":"l-faḍlu","translation_bn":"অনুগ্রহ","root":"فضل","lemma":"فَضْل","grammar_bn":"শব্দ"},{"id":18707,"position":18,"text_uthmani":"ٱلْمُبِينُ","transliteration":"l-mubīnu","translation_bn":"সুস্পষ্ট\"","root":"بين","lemma":"مُّبِين","grammar_bn":"শব্দ"},{"id":18708,"position":19,"text_uthmani":"١٦","transliteration":"","translation_bn":"(১৬)","root":"—","lemma":"١٦","grammar_bn":"মার্কার"}]'::jsonb, 'wawaritha sulaymānu dāwūda waqāla yāayyuhā l-nāsu ʿullim''nā manṭiqa l-ṭayri waūtīnā min kulli shayin inna hādhā lahuwa l-faḍlu l-mubīnu', 'সুলাইমান দাঊদের উত্তরাধিকারী হয়েছিল। সে বলেছিল- ‘হে মানুষেরা! আমাকে পক্ষীকুলের ভাষা শিক্ষা দেয়া হয়েছে আর আমাদেরকে সব কিছু দেয়া হয়েছে, এটা (আল্লাহর পক্ষ হতে) অবশ্যই সুস্পষ্ট অনুগ্রহ।’', 'And Solomon inherited David. He said, "O people, we have been taught the language of birds, and we have been given from all things. Indeed, this is evident bounty."', 'সুলাইমান দাঊদের উত্তরাধিকারী হয়েছিল। সে বলেছিল- ‘হে মানুষেরা! আমাকে পক্ষীকুলের ভাষা শিক্ষা দেয়া হয়েছে আর আমাদেরকে সব কিছু দেয়া হয়েছে, এটা (আল্লাহর পক্ষ হতে) অবশ্যই সুস্পষ্ট অনুগ্রহ।’', 'And Solomon inherited David. He said, "O people, we have been taught the language of birds, and we have been given from all things. Indeed, this is evident bounty."', NULL, NULL, NULL, NULL, NULL, 'https://everyayah.com/data/Alafasy_128kbps/027016.mp3', now()),
  (27, 17, '', '[{"id":19784,"position":1,"text_uthmani":"وَحُشِرَ","transliteration":"waḥushira","translation_bn":"আর একত্র করা হয়েছিলো","root":"حشر","lemma":"حَشَرَ","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":19785,"position":2,"text_uthmani":"لِسُلَيْمَـٰنَ","transliteration":"lisulaymāna","translation_bn":"জন্যে সুলায়মানের","root":"—","lemma":"سُلَيْمَٰن","grammar_bn":"অব্যয় (Preposition)"},{"id":19786,"position":3,"text_uthmani":"جُنُودُهُۥ","transliteration":"junūduhu","translation_bn":"সৈন্যবাহিনী তার","root":"جند","lemma":"جُند","grammar_bn":"বিশেষ্য (Noun)"},{"id":19787,"position":4,"text_uthmani":"مِنَ","transliteration":"mina","translation_bn":"মধ্য হ''তে","root":"—","lemma":"مِن\r","grammar_bn":"অব্যয় (Preposition)"},{"id":19788,"position":5,"text_uthmani":"ٱلْجِنِّ","transliteration":"l-jini","translation_bn":"জিনদের","root":"جنن","lemma":"جِنّ","grammar_bn":"শব্দ"},{"id":19789,"position":6,"text_uthmani":"وَٱلْإِنسِ","transliteration":"wal-insi","translation_bn":"ও মানুষদের","root":"انس","lemma":"إِنس","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":19790,"position":7,"text_uthmani":"وَٱلطَّيْرِ","transliteration":"wal-ṭayri","translation_bn":"এবং পাখীদের (মধ্য হ''তেও)","root":"طير","lemma":"طَيْر","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":19791,"position":8,"text_uthmani":"فَهُمْ","transliteration":"fahum","translation_bn":"অতঃপর তাদেরকে","root":"—","lemma":"فَهُمْ","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":19792,"position":9,"text_uthmani":"يُوزَعُونَ","transliteration":"yūzaʿūna","translation_bn":"বিন্যস্ত করা হতো (বিভিন্ন বুহ্যে)","root":"وزع","lemma":"يُوزَعُ","grammar_bn":"ক্রিয়া (Verb)"},{"id":19793,"position":10,"text_uthmani":"١٧","transliteration":"","translation_bn":"(১৭)","root":"—","lemma":"١٧","grammar_bn":"মার্কার"}]'::jsonb, 'waḥushira lisulaymāna junūduhu mina l-jini wal-insi wal-ṭayri fahum yūzaʿūna', 'সুলাইমানের সামনে তার সেনাবাহিনীকে সমবেত করা হল, জ্বিন, মানুষ ও পক্ষীকুলকে; অতঃপর তাদেরকে বিভিন্ন বুহ্যে বিন্যস্ত করা হল।', 'And gathered for Solomon were his soldiers of the jinn and men and birds, and they were [marching] in rows.', 'সুলাইমানের সামনে তার সেনাবাহিনীকে সমবেত করা হল, জ্বিন, মানুষ ও পক্ষীকুলকে; অতঃপর তাদেরকে বিভিন্ন বুহ্যে বিন্যস্ত করা হল।', 'And gathered for Solomon were his soldiers of the jinn and men and birds, and they were [marching] in rows.', NULL, NULL, NULL, NULL, NULL, 'https://everyayah.com/data/Alafasy_128kbps/027017.mp3', now()),
  (27, 18, '', '[{"id":20836,"position":1,"text_uthmani":"حَتَّىٰٓ","transliteration":"ḥattā","translation_bn":"শেষ পর্যন্ত (এক যাত্রায়)","root":"—","lemma":"حَتَّىٰ\r","grammar_bn":"অসম্পূর্ণ (Inceptive)"},{"id":20837,"position":2,"text_uthmani":"إِذَآ","transliteration":"idhā","translation_bn":"যখন","root":"—","lemma":"إِذَا\r","grammar_bn":"কালবাচক (Time)"},{"id":20838,"position":3,"text_uthmani":"أَتَوْا۟","transliteration":"ataw","translation_bn":"পৌঁছুল","root":"اتي","lemma":"أَتَى","grammar_bn":"ক্রিয়া (Verb)"},{"id":20839,"position":4,"text_uthmani":"عَلَىٰ","transliteration":"ʿalā","translation_bn":"নিকট","root":"—","lemma":"عَلَىٰ\r","grammar_bn":"অব্যয় (Preposition)"},{"id":20840,"position":5,"text_uthmani":"وَادِ","transliteration":"wādi","translation_bn":"উপত্যকার","root":"ودي","lemma":"وَاد","grammar_bn":"বিশেষ্য (Noun)"},{"id":20841,"position":6,"text_uthmani":"ٱلنَّمْلِ","transliteration":"l-namli","translation_bn":"পিঁপড়েদের","root":"نمل","lemma":"نَّمْل","grammar_bn":"শব্দ"},{"id":20842,"position":7,"text_uthmani":"قَالَتْ","transliteration":"qālat","translation_bn":"(তখন) বললো","root":"قول","lemma":"قَالَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":20843,"position":8,"text_uthmani":"نَمْلَةٌۭ","transliteration":"namlatun","translation_bn":"এক পিঁপড়ে","root":"نمل","lemma":"نَمْلَة","grammar_bn":"বিশেষ্য (Noun)"},{"id":20844,"position":9,"text_uthmani":"يَـٰٓأَيُّهَا","transliteration":"yāayyuhā","translation_bn":"\"হে","root":"—","lemma":"أَيُّهَا","grammar_bn":"সম্বোধন পদ (Vocative)"},{"id":20845,"position":10,"text_uthmani":"ٱلنَّمْلُ","transliteration":"l-namlu","translation_bn":"পিঁপড়েরা (দল)","root":"نمل","lemma":"نَّمْل","grammar_bn":"শব্দ"},{"id":20846,"position":11,"text_uthmani":"ٱدْخُلُوا۟","transliteration":"ud''khulū","translation_bn":"তোমরা ঢোকো","root":"دخل","lemma":"دَخَلَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":20847,"position":12,"text_uthmani":"مَسَـٰكِنَكُمْ","transliteration":"masākinakum","translation_bn":"ঘরে তোমাদের","root":"سكن","lemma":"مَسْكَن","grammar_bn":"বিশেষ্য (Noun)"},{"id":20848,"position":13,"text_uthmani":"لَا","transliteration":"lā","translation_bn":"না (যেন)","root":"—","lemma":"لَا\r","grammar_bn":"না-বোধক (Negative)"},{"id":20849,"position":14,"text_uthmani":"يَحْطِمَنَّكُمْ","transliteration":"yaḥṭimannakum","translation_bn":"পিষে ফেলে তোমাদেরকে","root":"حطم","lemma":"يَحْطِمَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":20850,"position":15,"text_uthmani":"سُلَيْمَـٰنُ","transliteration":"sulaymānu","translation_bn":"সুলায়মান","root":"—","lemma":"سُلَيْمَٰن","grammar_bn":"নামবাচক বিশেষ্য (Proper Noun)"},{"id":20851,"position":16,"text_uthmani":"وَجُنُودُهُۥ","transliteration":"wajunūduhu","translation_bn":"ও সৈন্যবাহিনী তার","root":"جند","lemma":"جُند","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":20852,"position":17,"text_uthmani":"وَهُمْ","transliteration":"wahum","translation_bn":"এমতাবস্হায় যে তারা","root":"—","lemma":"وَهُمْ","grammar_bn":"অবস্থাবাচক (Circumstantial)"},{"id":20853,"position":18,"text_uthmani":"لَا","transliteration":"lā","translation_bn":"না\"","root":"—","lemma":"لَا\r","grammar_bn":"না-বোধক (Negative)"},{"id":20854,"position":19,"text_uthmani":"يَشْعُرُونَ","transliteration":"yashʿurūna","translation_bn":"টেরও পাবে\"","root":"شعر","lemma":"يَشْعُرُ","grammar_bn":"ক্রিয়া (Verb)"},{"id":20855,"position":20,"text_uthmani":"١٨","transliteration":"","translation_bn":"(১৮)","root":"—","lemma":"١٨","grammar_bn":"মার্কার"}]'::jsonb, 'ḥattā idhā ataw ʿalā wādi l-namli qālat namlatun yāayyuhā l-namlu ud''khulū masākinakum lā yaḥṭimannakum sulaymānu wajunūduhu wahum lā yashʿurūna', 'যখন তারা পিপীলিকার উপত্যকায় আসল তখন একটি পিপীলিকা বলল- ‘ওহে পিঁপড়ার দল! তোমাদের বাসস্থানে ঢুকে পড়, যাতে সুলাইমান ও তার সৈন্যবাহিনী তাদের অগোচরে তোমাদেরকে পদপিষ্ট ক’রে না ফেলে।', 'Until, when they came upon the valley of the ants, an ant said, "O ants, enter your dwellings that you not be crushed by Solomon and his soldiers while they perceive not."', 'যখন তারা পিপীলিকার উপত্যকায় আসল তখন একটি পিপীলিকা বলল- ‘ওহে পিঁপড়ার দল! তোমাদের বাসস্থানে ঢুকে পড়, যাতে সুলাইমান ও তার সৈন্যবাহিনী তাদের অগোচরে তোমাদেরকে পদপিষ্ট ক’রে না ফেলে।', 'Until, when they came upon the valley of the ants, an ant said, "O ants, enter your dwellings that you not be crushed by Solomon and his soldiers while they perceive not."', NULL, NULL, NULL, NULL, NULL, 'https://everyayah.com/data/Alafasy_128kbps/027018.mp3', now()),
  (27, 19, '', '[{"id":21872,"position":1,"text_uthmani":"فَتَبَسَّمَ","transliteration":"fatabassama","translation_bn":"তখন (সুলায়মান) মুচকি হাসলো","root":"بسم","lemma":"تَبَسَّمَ","grammar_bn":"শব্দ"},{"id":21873,"position":2,"text_uthmani":"ضَاحِكًۭا","transliteration":"ḍāḥikan","translation_bn":"হাসি","root":"ضحك","lemma":"ضَاحِك","grammar_bn":"বিশেষ্য (Noun)"},{"id":21874,"position":3,"text_uthmani":"مِّن","transliteration":"min","translation_bn":"কারণে","root":"—","lemma":"مِن\r","grammar_bn":"অব্যয় (Preposition)"},{"id":21875,"position":4,"text_uthmani":"قَوْلِهَا","transliteration":"qawlihā","translation_bn":"কথার তার","root":"قول","lemma":"قَوْل","grammar_bn":"বিশেষ্য (Noun)"},{"id":21876,"position":5,"text_uthmani":"وَقَالَ","transliteration":"waqāla","translation_bn":"এবং বললো","root":"قول","lemma":"قَالَ","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":21877,"position":6,"text_uthmani":"رَبِّ","transliteration":"rabbi","translation_bn":"\"হে আমার রব","root":"ربب","lemma":"رَبّ","grammar_bn":"বিশেষ্য (Noun)"},{"id":21878,"position":7,"text_uthmani":"أَوْزِعْنِىٓ","transliteration":"awziʿ''nī","translation_bn":"সামর্থ্য দাও","root":"وزع","lemma":"أَوْزِعْ","grammar_bn":"ক্রিয়া (Verb)"},{"id":21879,"position":8,"text_uthmani":"أَنْ","transliteration":"an","translation_bn":"যেন","root":"—","lemma":"أَن\r","grammar_bn":"অধীনস্থ যোজক (Subordinating)"},{"id":21880,"position":9,"text_uthmani":"أَشْكُرَ","transliteration":"ashkura","translation_bn":"কৃতজ্ঞতা প্রকাশ করতে পারি আমি","root":"شكر","lemma":"شَكَرَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":21881,"position":10,"text_uthmani":"نِعْمَتَكَ","transliteration":"niʿ''mataka","translation_bn":"অনুগ্রহের তোমার","root":"نعم","lemma":"نِعْمَة","grammar_bn":"বিশেষ্য (Noun)"},{"id":21882,"position":11,"text_uthmani":"ٱلَّتِىٓ","transliteration":"allatī","translation_bn":"যা","root":"—","lemma":"ٱلَّذِى","grammar_bn":"সাপেক্ষ সর্বনাম (Relative)"},{"id":21883,"position":12,"text_uthmani":"أَنْعَمْتَ","transliteration":"anʿamta","translation_bn":"অনুগ্রহ করেছো তুমি","root":"نعم","lemma":"أَنْعَمَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":21884,"position":13,"text_uthmani":"عَلَىَّ","transliteration":"ʿalayya","translation_bn":"আমার উপর","root":"—","lemma":"عَلَىٰ\r","grammar_bn":"অব্যয় (Preposition)"},{"id":21885,"position":14,"text_uthmani":"وَعَلَىٰ","transliteration":"waʿalā","translation_bn":"ও উপর","root":"—","lemma":"عَلَىٰ\r","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":21886,"position":15,"text_uthmani":"وَٰلِدَىَّ","transliteration":"wālidayya","translation_bn":"আমার পিতা মাতার","root":"ولد","lemma":"وَٰلِدَي","grammar_bn":"বিশেষ্য (Noun)"},{"id":21887,"position":16,"text_uthmani":"وَأَنْ","transliteration":"wa-an","translation_bn":"এবং যেন","root":"—","lemma":"أَن\r","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":21888,"position":17,"text_uthmani":"أَعْمَلَ","transliteration":"aʿmala","translation_bn":"আমি করি","root":"عمل","lemma":"عَمِلَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":21889,"position":18,"text_uthmani":"صَـٰلِحًۭا","transliteration":"ṣāliḥan","translation_bn":"(এমন) সৎ কাজ","root":"صلح","lemma":"صَٰلِح","grammar_bn":"বিশেষ্য (Noun)"},{"id":21890,"position":19,"text_uthmani":"تَرْضَىٰهُ","transliteration":"tarḍāhu","translation_bn":"যা পছন্দ করো তুমি","root":"رضو","lemma":"رَّضِىَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":21891,"position":20,"text_uthmani":"وَأَدْخِلْنِى","transliteration":"wa-adkhil''nī","translation_bn":"এবং অন্তর্ভুক্ত করো আমাকে","root":"دخل","lemma":"أُدْخِلَ","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":21892,"position":21,"text_uthmani":"بِرَحْمَتِكَ","transliteration":"biraḥmatika","translation_bn":"দ্বারা অনুগ্রহ তোমার","root":"رحم","lemma":"رَحْمَة","grammar_bn":"অব্যয় (Preposition)"},{"id":21893,"position":22,"text_uthmani":"فِى","transliteration":"fī","translation_bn":"মধ্যে","root":"—","lemma":"فِى\r","grammar_bn":"অব্যয় (Preposition)"},{"id":21894,"position":23,"text_uthmani":"عِبَادِكَ","transliteration":"ʿibādika","translation_bn":"তোমাদের দাসদের","root":"عبد","lemma":"عَبْد","grammar_bn":"বিশেষ্য (Noun)"},{"id":21895,"position":24,"text_uthmani":"ٱلصَّـٰلِحِينَ","transliteration":"l-ṣāliḥīna","translation_bn":"(যারা) সৎকর্মপরায়ণ\"","root":"صلح","lemma":"صَٰلِح","grammar_bn":"শব্দ"},{"id":21896,"position":25,"text_uthmani":"١٩","transliteration":"","translation_bn":"(১৯)","root":"—","lemma":"١٩","grammar_bn":"মার্কার"}]'::jsonb, 'fatabassama ḍāḥikan min qawlihā waqāla rabbi awziʿ''nī an ashkura niʿ''mataka allatī anʿamta ʿalayya waʿalā wālidayya wa-an aʿmala ṣāliḥan tarḍāhu wa-adkhil''nī biraḥmatika fī ʿibādika l-ṣāliḥīna', 'সুলাইমান তার কথায় খুশিতে মুচকি হাসল আর বলল- ‘হে আমার প্রতিপালক! তুমি আমার প্রতি ও আমার পিতামাতার প্রতি যে অনুগ্রহ দান করেছ তার জন্য কৃতজ্ঞতা প্রকাশের আমাকে শক্তি দান কর আর যাতে এমন সৎকাজ করতে পারি যাতে তুমি সন্তুষ্ট হও আর তোমার দয়ায় আমাকে তোমার সৎকর্মশীল বান্দাদের অন্তর্ভুক্ত কর।’', 'So [Solomon] smiled, amused at her speech, and said, "My Lord, enable me to be grateful for Your favor which You have bestowed upon me and upon my parents and to do righteousness of which You approve. And admit me by Your mercy into [the ranks of] Your righteous servants."', 'সুলাইমান তার কথায় খুশিতে মুচকি হাসল আর বলল- ‘হে আমার প্রতিপালক! তুমি আমার প্রতি ও আমার পিতামাতার প্রতি যে অনুগ্রহ দান করেছ তার জন্য কৃতজ্ঞতা প্রকাশের আমাকে শক্তি দান কর আর যাতে এমন সৎকাজ করতে পারি যাতে তুমি সন্তুষ্ট হও আর তোমার দয়ায় আমাকে তোমার সৎকর্মশীল বান্দাদের অন্তর্ভুক্ত কর।’', 'So [Solomon] smiled, amused at her speech, and said, "My Lord, enable me to be grateful for Your favor which You have bestowed upon me and upon my parents and to do righteousness of which You approve. And admit me by Your mercy into [the ranks of] Your righteous servants."', NULL, NULL, NULL, NULL, NULL, 'https://everyayah.com/data/Alafasy_128kbps/027019.mp3', now()),
  (27, 20, '', '[{"id":23004,"position":1,"text_uthmani":"وَتَفَقَّدَ","transliteration":"watafaqqada","translation_bn":"এবং (একবার) সে সন্ধান নিলো","root":"فقد","lemma":"تَفَقَّدَ","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":23005,"position":2,"text_uthmani":"ٱلطَّيْرَ","transliteration":"l-ṭayra","translation_bn":"পাখীকে (দলের)","root":"طير","lemma":"طَيْر","grammar_bn":"শব্দ"},{"id":23006,"position":3,"text_uthmani":"فَقَالَ","transliteration":"faqāla","translation_bn":"অতঃপর বললো","root":"قول","lemma":"قَالَ","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":23007,"position":4,"text_uthmani":"مَا","transliteration":"mā","translation_bn":"\"কি (হলো)","root":"—","lemma":"مَا\r","grammar_bn":"প্রশ্নবোধক (Interrogative)"},{"id":23008,"position":5,"text_uthmani":"لِىَ","transliteration":"liya","translation_bn":"\"আমার","root":"—","lemma":"لِىَ","grammar_bn":"অব্যয় (Preposition)"},{"id":23009,"position":6,"text_uthmani":"لَآ","transliteration":"lā","translation_bn":"না","root":"—","lemma":"لَا\r","grammar_bn":"না-বোধক (Negative)"},{"id":23010,"position":7,"text_uthmani":"أَرَى","transliteration":"arā","translation_bn":"দেখছি আমি","root":"راي","lemma":"رَءَا","grammar_bn":"ক্রিয়া (Verb)"},{"id":23011,"position":8,"text_uthmani":"ٱلْهُدْهُدَ","transliteration":"l-hud''huda","translation_bn":"হুদহুদ পাখীকে","root":"هدهد","lemma":"هُدْهُد","grammar_bn":"শব্দ"},{"id":23012,"position":9,"text_uthmani":"أَمْ","transliteration":"am","translation_bn":"কি","root":"—","lemma":"أَم\r","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":23013,"position":10,"text_uthmani":"كَانَ","transliteration":"kāna","translation_bn":"সে হয়েছে","root":"كون","lemma":"كَانَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":23014,"position":11,"text_uthmani":"مِنَ","transliteration":"mina","translation_bn":"অন্তর্ভুক্ত","root":"—","lemma":"مِن\r","grammar_bn":"অব্যয় (Preposition)"},{"id":23015,"position":12,"text_uthmani":"ٱلْغَآئِبِينَ","transliteration":"l-ghāibīna","translation_bn":"অনুপস্থিতদের","root":"غيب","lemma":"غَا^ئِبِين","grammar_bn":"শব্দ"},{"id":23016,"position":13,"text_uthmani":"٢٠","transliteration":"","translation_bn":"(২০)","root":"—","lemma":"٢٠","grammar_bn":"মার্কার"}]'::jsonb, 'watafaqqada l-ṭayra faqāla mā liya lā arā l-hud''huda am kāna mina l-ghāibīna', 'অতঃপর সুলাইমান পাখীদের খোঁজ খবর নিল। সে বলল, কী ব্যাপার, হুদহুদকে তো দেখছি না, নাকি সে অনুপস্থিত?', 'And he took attendance of the birds and said, "Why do I not see the hoopoe - or is he among the absent?', 'অতঃপর সুলাইমান পাখীদের খোঁজ খবর নিল। সে বলল, কী ব্যাপার, হুদহুদকে তো দেখছি না, নাকি সে অনুপস্থিত?', 'And he took attendance of the birds and said, "Why do I not see the hoopoe - or is he among the absent?', NULL, NULL, NULL, NULL, NULL, 'https://everyayah.com/data/Alafasy_128kbps/027020.mp3', now()),
  (27, 21, '', '[{"id":24025,"position":1,"text_uthmani":"لَأُعَذِّبَنَّهُۥ","transliteration":"la-uʿadhibannahu","translation_bn":"অবশ্যই শাস্তি দিবো আমি তাকে","root":"عذب","lemma":"عَذَّبَ","grammar_bn":"দৃঢ়তাবোধক (Emphatic)"},{"id":24026,"position":2,"text_uthmani":"عَذَابًۭا","transliteration":"ʿadhāban","translation_bn":"শাস্তি","root":"عذب","lemma":"عَذَاب","grammar_bn":"বিশেষ্য (Noun)"},{"id":24027,"position":3,"text_uthmani":"شَدِيدًا","transliteration":"shadīdan","translation_bn":"কঠিন","root":"شدد","lemma":"شَدِيد","grammar_bn":"বিশেষণ (Adjective)"},{"id":24028,"position":4,"text_uthmani":"أَوْ","transliteration":"aw","translation_bn":"অথবা","root":"—","lemma":"أَو\r","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":24029,"position":5,"text_uthmani":"لَأَا۟ذْبَحَنَّهُۥٓ","transliteration":"laādh''baḥannahu","translation_bn":"অবশ্যই জবেহ করবোই আমি তাকে","root":"ذبح","lemma":"ذُبِحَ","grammar_bn":"দৃঢ়তাবোধক (Emphatic)"},{"id":24030,"position":6,"text_uthmani":"أَوْ","transliteration":"aw","translation_bn":"অথবা","root":"—","lemma":"أَو\r","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":24031,"position":7,"text_uthmani":"لَيَأْتِيَنِّى","transliteration":"layatiyannī","translation_bn":"অবশ্যই আমার কাছে আসবে","root":"اتي","lemma":"أَتَى","grammar_bn":"দৃঢ়তাবোধক (Emphatic)"},{"id":24032,"position":8,"text_uthmani":"بِسُلْطَـٰنٍۢ","transliteration":"bisul''ṭānin","translation_bn":"নিয়ে প্রমাণ","root":"سلط","lemma":"سُلْطَٰن","grammar_bn":"অব্যয় (Preposition)"},{"id":24033,"position":9,"text_uthmani":"مُّبِينٍۢ","transliteration":"mubīnin","translation_bn":"সুস্পষ্ট\"","root":"بين","lemma":"مُّبِين","grammar_bn":"বিশেষণ (Adjective)"},{"id":24034,"position":10,"text_uthmani":"٢١","transliteration":"","translation_bn":"(২১)","root":"—","lemma":"٢١","grammar_bn":"মার্কার"}]'::jsonb, 'la-uʿadhibannahu ʿadhāban shadīdan aw laādh''baḥannahu aw layatiyannī bisul''ṭānin mubīnin', 'আমি তাকে অবশ্য অবশ্যই শাস্তি দেব কঠিন শাস্তি কিংবা তাকে অবশ্য অবশ্যই হত্যা করব অথবা সে অবশ্য অবশ্যই আমাকে তার (অনুপস্থিতির) উপযুক্ত কারণ দর্শাবে।’', 'I will surely punish him with a severe punishment or slaughter him unless he brings me clear authorization."', 'আমি তাকে অবশ্য অবশ্যই শাস্তি দেব কঠিন শাস্তি কিংবা তাকে অবশ্য অবশ্যই হত্যা করব অথবা সে অবশ্য অবশ্যই আমাকে তার (অনুপস্থিতির) উপযুক্ত কারণ দর্শাবে।’', 'I will surely punish him with a severe punishment or slaughter him unless he brings me clear authorization."', NULL, NULL, NULL, NULL, NULL, 'https://everyayah.com/data/Alafasy_128kbps/027021.mp3', now()),
  (27, 22, '', '[{"id":25040,"position":1,"text_uthmani":"فَمَكَثَ","transliteration":"famakatha","translation_bn":"অতঃপর (পাখীটি) অতিবাহিত করলো","root":"مكث","lemma":"مَكَثَ","grammar_bn":"শব্দ"},{"id":25041,"position":2,"text_uthmani":"غَيْرَ","transliteration":"ghayra","translation_bn":"নয়","root":"غير","lemma":"غَيْر","grammar_bn":"বিশেষ্য (Noun)"},{"id":25042,"position":3,"text_uthmani":"بَعِيدٍۢ","transliteration":"baʿīdin","translation_bn":"দৃঢ়ে (অতি অল্প সময়)","root":"بعد","lemma":"بَعِيد","grammar_bn":"বিশেষ্য (Noun)"},{"id":25043,"position":4,"text_uthmani":"فَقَالَ","transliteration":"faqāla","translation_bn":"অতঃপর বললো","root":"قول","lemma":"قَالَ","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":25044,"position":5,"text_uthmani":"أَحَطتُ","transliteration":"aḥaṭtu","translation_bn":"\"আমি অবগত হয়েছি","root":"حوط","lemma":"أَحَاطَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":25045,"position":6,"text_uthmani":"بِمَا","transliteration":"bimā","translation_bn":"ঐ বিষয়ে যা","root":"—","lemma":"مَا\r","grammar_bn":"অব্যয় (Preposition)"},{"id":25046,"position":7,"text_uthmani":"لَمْ","transliteration":"lam","translation_bn":"নি","root":"—","lemma":"لَم\r","grammar_bn":"না-বোধক (Negative)"},{"id":25047,"position":8,"text_uthmani":"تُحِطْ","transliteration":"tuḥiṭ","translation_bn":"আপনি অবগত হন","root":"حوط","lemma":"أَحَاطَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":25048,"position":9,"text_uthmani":"بِهِۦ","transliteration":"bihi","translation_bn":"সম্পর্কে সে","root":"—","lemma":"بِهِۦ","grammar_bn":"অব্যয় (Preposition)"},{"id":25049,"position":10,"text_uthmani":"وَجِئْتُكَ","transliteration":"waji''tuka","translation_bn":"এবং আপনার কাছে এসেছি","root":"جيا","lemma":"جَا^ءَ","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":25050,"position":11,"text_uthmani":"مِن","transliteration":"min","translation_bn":"সম্পর্কে","root":"—","lemma":"مِن\r","grammar_bn":"অব্যয় (Preposition)"},{"id":25051,"position":12,"text_uthmani":"سَبَإٍۭ","transliteration":"saba-in","translation_bn":"সাবা''","root":"—","lemma":"سَبَإ","grammar_bn":"নামবাচক বিশেষ্য (Proper Noun)"},{"id":25052,"position":13,"text_uthmani":"بِنَبَإٍۢ","transliteration":"binaba-in","translation_bn":"নিয়ে (কিছু) তথ্য","root":"نبا","lemma":"نَبَأ","grammar_bn":"অব্যয় (Preposition)"},{"id":25053,"position":14,"text_uthmani":"يَقِينٍ","transliteration":"yaqīnin","translation_bn":"নিশ্চিত","root":"يقن","lemma":"يَقِين","grammar_bn":"বিশেষণ (Adjective)"},{"id":25054,"position":15,"text_uthmani":"٢٢","transliteration":"","translation_bn":"(২২)","root":"—","lemma":"٢٢","grammar_bn":"মার্কার"}]'::jsonb, 'famakatha ghayra baʿīdin faqāla aḥaṭtu bimā lam tuḥiṭ bihi waji''tuka min saba-in binaba-in yaqīnin', 'অতঃপর হুদহুদ অবিলম্বে এসে বলল- ‘আমি যা অবগত হয়েছি আপনি তা অবগত নন, আমি সাবা থেকে নিশ্চিত খবর নিয়ে আপনার কাছে এসেছি।', 'But the hoopoe stayed not long and said, "I have encompassed [in knowledge] that which you have not encompassed, and I have come to you from Sheba with certain news.', 'অতঃপর হুদহুদ অবিলম্বে এসে বলল- ‘আমি যা অবগত হয়েছি আপনি তা অবগত নন, আমি সাবা থেকে নিশ্চিত খবর নিয়ে আপনার কাছে এসেছি।', 'But the hoopoe stayed not long and said, "I have encompassed [in knowledge] that which you have not encompassed, and I have come to you from Sheba with certain news.', NULL, NULL, NULL, NULL, NULL, 'https://everyayah.com/data/Alafasy_128kbps/027022.mp3', now()),
  (27, 23, '', '[{"id":26124,"position":1,"text_uthmani":"إِنِّى","transliteration":"innī","translation_bn":"নিশ্চয়ই আমি","root":"—","lemma":"إِنّ","grammar_bn":"অভিঘাত পদ (Accusative)"},{"id":26125,"position":2,"text_uthmani":"وَجَدتُّ","transliteration":"wajadttu","translation_bn":"আমি (দেখতে) পেয়েছি","root":"وجد","lemma":"وَجَدَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":26126,"position":3,"text_uthmani":"ٱمْرَأَةًۭ","transliteration":"im''ra-atan","translation_bn":"একজন মহিলা","root":"مرا","lemma":"ٱمْرَأَت","grammar_bn":"বিশেষ্য (Noun)"},{"id":26127,"position":4,"text_uthmani":"تَمْلِكُهُمْ","transliteration":"tamlikuhum","translation_bn":"শাসন করে সে তাদেরকে","root":"ملك","lemma":"مَلَكَتْ","grammar_bn":"ক্রিয়া (Verb)"},{"id":26128,"position":5,"text_uthmani":"وَأُوتِيَتْ","transliteration":"waūtiyat","translation_bn":"এবং তাকে দেওয়া হয়েছে","root":"اتي","lemma":"ا^تَى","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":26129,"position":6,"text_uthmani":"مِن","transliteration":"min","translation_bn":"থেকে","root":"—","lemma":"مِن\r","grammar_bn":"অব্যয় (Preposition)"},{"id":26130,"position":7,"text_uthmani":"كُلِّ","transliteration":"kulli","translation_bn":"সব","root":"كلل","lemma":"كُلّ","grammar_bn":"বিশেষ্য (Noun)"},{"id":26131,"position":8,"text_uthmani":"شَىْءٍۢ","transliteration":"shayin","translation_bn":"কিছুই","root":"شيا","lemma":"شَىْء","grammar_bn":"বিশেষ্য (Noun)"},{"id":26132,"position":9,"text_uthmani":"وَلَهَا","transliteration":"walahā","translation_bn":"আর আছে তার","root":"—","lemma":"وَلَهَا","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":26133,"position":10,"text_uthmani":"عَرْشٌ","transliteration":"ʿarshun","translation_bn":"একটি সিংহাসন","root":"عرش","lemma":"عَرْش","grammar_bn":"বিশেষ্য (Noun)"},{"id":26134,"position":11,"text_uthmani":"عَظِيمٌۭ","transliteration":"ʿaẓīmun","translation_bn":"বিরাট","root":"عظم","lemma":"عَظِيم","grammar_bn":"বিশেষণ (Adjective)"},{"id":26135,"position":12,"text_uthmani":"٢٣","transliteration":"","translation_bn":"(২৩)","root":"—","lemma":"٢٣","grammar_bn":"মার্কার"}]'::jsonb, 'innī wajadttu im''ra-atan tamlikuhum waūtiyat min kulli shayin walahā ʿarshun ʿaẓīmun', 'আমি দেখলাম এক নারী তাদের উপর রাজত্ব করছে আর তাকে সব কিছুই দেয়া হয়েছে আর তার আছে এক বিরাট সিংহাসন।', 'Indeed, I found [there] a woman ruling them, and she has been given of all things, and she has a great throne.', 'আমি দেখলাম এক নারী তাদের উপর রাজত্ব করছে আর তাকে সব কিছুই দেয়া হয়েছে আর তার আছে এক বিরাট সিংহাসন।', 'Indeed, I found [there] a woman ruling them, and she has been given of all things, and she has a great throne.', NULL, NULL, NULL, NULL, NULL, 'https://everyayah.com/data/Alafasy_128kbps/027023.mp3', now()),
  (27, 24, '', '[{"id":27178,"position":1,"text_uthmani":"وَجَدتُّهَا","transliteration":"wajadttuhā","translation_bn":"আমি (দেখতে) পেয়েছি তাকে","root":"وجد","lemma":"وَجَدَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":27179,"position":2,"text_uthmani":"وَقَوْمَهَا","transliteration":"waqawmahā","translation_bn":"ও জাতিকে তার","root":"قوم","lemma":"قَوْم","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":27180,"position":3,"text_uthmani":"يَسْجُدُونَ","transliteration":"yasjudūna","translation_bn":"সিজদা করে তারা","root":"سجد","lemma":"سَجَدَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":27181,"position":4,"text_uthmani":"لِلشَّمْسِ","transliteration":"lilshamsi","translation_bn":"উদ্দেশ্যে সূর্যের","root":"شمس","lemma":"شَمْس","grammar_bn":"অব্যয় (Preposition)"},{"id":27182,"position":5,"text_uthmani":"مِن","transliteration":"min","translation_bn":"মধ্য হতে","root":"—","lemma":"مِن\r","grammar_bn":"অব্যয় (Preposition)"},{"id":27183,"position":6,"text_uthmani":"دُونِ","transliteration":"dūni","translation_bn":"পরিবর্তে","root":"دون","lemma":"دُون","grammar_bn":"বিশেষ্য (Noun)"},{"id":27184,"position":7,"text_uthmani":"ٱللَّهِ","transliteration":"l-lahi","translation_bn":"আল্লাহর","root":"اله","lemma":"ٱللَّه","grammar_bn":"নামবাচক বিশেষ্য (Proper Noun)"},{"id":27185,"position":8,"text_uthmani":"وَزَيَّنَ","transliteration":"wazayyana","translation_bn":"এবং সুশোভন করেছে","root":"زين","lemma":"زَيَّنَ","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":27186,"position":9,"text_uthmani":"لَهُمُ","transliteration":"lahumu","translation_bn":"কাছে তাদের","root":"—","lemma":"لَهُمُ","grammar_bn":"অব্যয় (Preposition)"},{"id":27187,"position":10,"text_uthmani":"ٱلشَّيْطَـٰنُ","transliteration":"l-shayṭānu","translation_bn":"শয়তান","root":"شطن","lemma":"شَيْطَٰن","grammar_bn":"শব্দ"},{"id":27188,"position":11,"text_uthmani":"أَعْمَـٰلَهُمْ","transliteration":"aʿmālahum","translation_bn":"কাজগুলোকে তাদের","root":"عمل","lemma":"عَمَل","grammar_bn":"বিশেষ্য (Noun)"},{"id":27189,"position":12,"text_uthmani":"فَصَدَّهُمْ","transliteration":"faṣaddahum","translation_bn":"অতঃপর বিরত করেছে তাদেরকে","root":"صدد","lemma":"صَدَّ","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":27190,"position":13,"text_uthmani":"عَنِ","transliteration":"ʿani","translation_bn":"হ''তে","root":"—","lemma":"عَن\r","grammar_bn":"অব্যয় (Preposition)"},{"id":27191,"position":14,"text_uthmani":"ٱلسَّبِيلِ","transliteration":"l-sabīli","translation_bn":"(সৎ) পথ","root":"سبل","lemma":"سَبِيل","grammar_bn":"শব্দ"},{"id":27192,"position":15,"text_uthmani":"فَهُمْ","transliteration":"fahum","translation_bn":"তাই তারা","root":"—","lemma":"فَهُمْ","grammar_bn":"শব্দ"},{"id":27193,"position":16,"text_uthmani":"لَا","transliteration":"lā","translation_bn":"না","root":"—","lemma":"لَا\r","grammar_bn":"না-বোধক (Negative)"},{"id":27194,"position":17,"text_uthmani":"يَهْتَدُونَ","transliteration":"yahtadūna","translation_bn":"(সৎ) পথ পায়","root":"هدي","lemma":"ٱهْتَدَىٰ","grammar_bn":"ক্রিয়া (Verb)"},{"id":27195,"position":18,"text_uthmani":"٢٤","transliteration":"","translation_bn":"(২৪)","root":"—","lemma":"٢٤","grammar_bn":"মার্কার"}]'::jsonb, 'wajadttuhā waqawmahā yasjudūna lilshamsi min dūni l-lahi wazayyana lahumu l-shayṭānu aʿmālahum faṣaddahum ʿani l-sabīli fahum lā yahtadūna', 'এবং আমি তাকে আর তার সম্প্রদায়কে দেখলাম আল্লাহর পরিবর্তে সূর্যকে সেজদা করতে। শয়ত্বান তাদের কাজকে তাদের জন্য শোভন করে দিয়েছে এবং তাদেরকে সৎপথ থেকে বাধা দিয়ে রেখেছে কাজেই তারা সৎপথ পায় না।', 'I found her and her people prostrating to the sun instead of Allah, and Satan has made their deeds pleasing to them and averted them from [His] way, so they are not guided,', 'এবং আমি তাকে আর তার সম্প্রদায়কে দেখলাম আল্লাহর পরিবর্তে সূর্যকে সেজদা করতে। শয়ত্বান তাদের কাজকে তাদের জন্য শোভন করে দিয়েছে এবং তাদেরকে সৎপথ থেকে বাধা দিয়ে রেখেছে কাজেই তারা সৎপথ পায় না।', 'I found her and her people prostrating to the sun instead of Allah, and Satan has made their deeds pleasing to them and averted them from [His] way, so they are not guided,', NULL, NULL, NULL, NULL, NULL, 'https://everyayah.com/data/Alafasy_128kbps/027024.mp3', now()),
  (27, 25, '', '[{"id":28195,"position":1,"text_uthmani":"أَلَّا","transliteration":"allā","translation_bn":"(বিরত করেছে) যেন না","root":"—","lemma":"أَن\r","grammar_bn":"অধীনস্থ যোজক (Subordinating)"},{"id":28196,"position":2,"text_uthmani":"يَسْجُدُوا۟","transliteration":"yasjudū","translation_bn":"তারা সিজদা করে","root":"سجد","lemma":"سَجَدَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":28197,"position":3,"text_uthmani":"لِلَّهِ","transliteration":"lillahi","translation_bn":"উদ্দেশ্যে আল্লাহর","root":"اله","lemma":"ٱللَّه","grammar_bn":"অব্যয় (Preposition)"},{"id":28198,"position":4,"text_uthmani":"ٱلَّذِى","transliteration":"alladhī","translation_bn":"যিনি","root":"—","lemma":"ٱلَّذِى","grammar_bn":"সাপেক্ষ সর্বনাম (Relative)"},{"id":28199,"position":5,"text_uthmani":"يُخْرِجُ","transliteration":"yukh''riju","translation_bn":"বের করেন","root":"خرج","lemma":"أَخْرَجَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":28200,"position":6,"text_uthmani":"ٱلْخَبْءَ","transliteration":"l-khaba-a","translation_bn":"লুকায়িত বস্তুকে","root":"خبا","lemma":"خَبْء","grammar_bn":"শব্দ"},{"id":28201,"position":7,"text_uthmani":"فِى","transliteration":"fī","translation_bn":"মধ্যে","root":"—","lemma":"فِى\r","grammar_bn":"অব্যয় (Preposition)"},{"id":28202,"position":8,"text_uthmani":"ٱلسَّمَـٰوَٰتِ","transliteration":"l-samāwāti","translation_bn":"আকাশমন্ডলীর","root":"سمو","lemma":"سَمَا^ء","grammar_bn":"শব্দ"},{"id":28203,"position":9,"text_uthmani":"وَٱلْأَرْضِ","transliteration":"wal-arḍi","translation_bn":"ও পৃথিবীর","root":"ارض","lemma":"أَرْض","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":28204,"position":10,"text_uthmani":"وَيَعْلَمُ","transliteration":"wayaʿlamu","translation_bn":"আর তিনি জানেন","root":"علم","lemma":"عَلِمَ","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":28205,"position":11,"text_uthmani":"مَا","transliteration":"mā","translation_bn":"যা কিছু","root":"—","lemma":"مَا\r","grammar_bn":"সাপেক্ষ সর্বনাম (Relative)"},{"id":28206,"position":12,"text_uthmani":"تُخْفُونَ","transliteration":"tukh''fūna","translation_bn":"তোমরা গোপন করো","root":"خفي","lemma":"أُخْفِىَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":28207,"position":13,"text_uthmani":"وَمَا","transliteration":"wamā","translation_bn":"এবং যা কিছু","root":"—","lemma":"مَا\r","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":28208,"position":14,"text_uthmani":"تُعْلِنُونَ","transliteration":"tuʿ''linūna","translation_bn":"তোমরা প্রকাশ করো","root":"علن","lemma":"أَعْلَن","grammar_bn":"ক্রিয়া (Verb)"},{"id":28209,"position":15,"text_uthmani":"٢٥","transliteration":"","translation_bn":"(২৫)","root":"—","lemma":"٢٥","grammar_bn":"মার্কার"}]'::jsonb, 'allā yasjudū lillahi alladhī yukh''riju l-khaba-a fī l-samāwāti wal-arḍi wayaʿlamu mā tukh''fūna wamā tuʿ''linūna', '(শয়ত্বান বাধা দিয়ে রেখেছে) যাতে তারা আল্লাহকে সেজদা না করে যিনি আকাশমন্ডলী ও পৃথিবীর লুক্কায়িত বস্তুকে প্রকাশ করেন, যিনি জানেন তোমরা যা গোপন কর আর তোমরা যা প্রকাশ কর।', '[And] so they do not prostrate to Allah, who brings forth what is hidden within the heavens and the earth and knows what you conceal and what you declare -', '(শয়ত্বান বাধা দিয়ে রেখেছে) যাতে তারা আল্লাহকে সেজদা না করে যিনি আকাশমন্ডলী ও পৃথিবীর লুক্কায়িত বস্তুকে প্রকাশ করেন, যিনি জানেন তোমরা যা গোপন কর আর তোমরা যা প্রকাশ কর।', '[And] so they do not prostrate to Allah, who brings forth what is hidden within the heavens and the earth and knows what you conceal and what you declare -', NULL, NULL, NULL, NULL, NULL, 'https://everyayah.com/data/Alafasy_128kbps/027025.mp3', now()),
  (27, 26, '', '[{"id":29170,"position":1,"text_uthmani":"ٱللَّهُ","transliteration":"al-lahu","translation_bn":"আল্লাহ (এমন যে)","root":"اله","lemma":"ٱللَّه","grammar_bn":"নামবাচক বিশেষ্য (Proper Noun)"},{"id":29171,"position":2,"text_uthmani":"لَآ","transliteration":"lā","translation_bn":"নেই","root":"—","lemma":"لَا\r","grammar_bn":"না-বোধক (Negative)"},{"id":29172,"position":3,"text_uthmani":"إِلَـٰهَ","transliteration":"ilāha","translation_bn":"কোনো ইলাহ","root":"اله","lemma":"إِلَٰه","grammar_bn":"বিশেষ্য (Noun)"},{"id":29173,"position":4,"text_uthmani":"إِلَّا","transliteration":"illā","translation_bn":"ছাড়া","root":"—","lemma":"إِلَّا\r","grammar_bn":"সীমাবদ্ধতা (Restriction)"},{"id":29174,"position":5,"text_uthmani":"هُوَ","transliteration":"huwa","translation_bn":"তিনি","root":"—","lemma":"هُوَ","grammar_bn":"সর্বনাম (Pronoun)"},{"id":29175,"position":6,"text_uthmani":"رَبُّ","transliteration":"rabbu","translation_bn":"অধিপতি","root":"ربب","lemma":"رَبّ","grammar_bn":"বিশেষ্য (Noun)"},{"id":29176,"position":7,"text_uthmani":"ٱلْعَرْشِ","transliteration":"l-ʿarshi","translation_bn":"আরশের","root":"عرش","lemma":"عَرْش","grammar_bn":"শব্দ"},{"id":29177,"position":8,"text_uthmani":"ٱلْعَظِيمِ ۩‏","transliteration":"l-ʿaẓīmi","translation_bn":"মহান\"","root":"عظم","lemma":"عَظِيم","grammar_bn":"শব্দ"},{"id":29179,"position":9,"text_uthmani":"٢٦","transliteration":"","translation_bn":"(২৬)","root":"—","lemma":"٢٦","grammar_bn":"মার্কার"}]'::jsonb, 'al-lahu lā ilāha illā huwa rabbu l-ʿarshi l-ʿaẓīmi', 'আল্লাহ, তিনি ছাড়া সত্যিকারের কোন ইলাহ্ নেই, (তিনি) মহান ‘আরশের অধিপতি।’[সাজদাহ]', 'Allah - there is no deity except Him, Lord of the Great Throne."', 'আল্লাহ, তিনি ছাড়া সত্যিকারের কোন ইলাহ্ নেই, (তিনি) মহান ‘আরশের অধিপতি।’[সাজদাহ]', 'Allah - there is no deity except Him, Lord of the Great Throne."', NULL, NULL, NULL, NULL, NULL, 'https://everyayah.com/data/Alafasy_128kbps/027026.mp3', now()),
  (27, 27, '', '[{"id":30073,"position":1,"text_uthmani":"۞ قَالَ","transliteration":"qāla","translation_bn":"(সুলায়মান) বললো","root":"قول","lemma":"قَالَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":30074,"position":2,"text_uthmani":"سَنَنظُرُ","transliteration":"sananẓuru","translation_bn":"\"শীঘ্রই আমরা দেখবো","root":"نظر","lemma":"نَّظَرَ","grammar_bn":"ভবিষ্যদ্বাচক (Future)"},{"id":30075,"position":3,"text_uthmani":"أَصَدَقْتَ","transliteration":"aṣadaqta","translation_bn":"কি তুমি সত্য বলেছো","root":"صدق","lemma":"صَدَقَ","grammar_bn":"প্রশ্নবোধক (Interrogative)"},{"id":30076,"position":4,"text_uthmani":"أَمْ","transliteration":"am","translation_bn":"না","root":"—","lemma":"أَم\r","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":30077,"position":5,"text_uthmani":"كُنتَ","transliteration":"kunta","translation_bn":"তুমি","root":"كون","lemma":"كَانَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":30078,"position":6,"text_uthmani":"مِنَ","transliteration":"mina","translation_bn":"অন্তর্ভুক্ত","root":"—","lemma":"مِن\r","grammar_bn":"অব্যয় (Preposition)"},{"id":30079,"position":7,"text_uthmani":"ٱلْكَـٰذِبِينَ","transliteration":"l-kādhibīna","translation_bn":"মিথ্যাবাদীদের","root":"كذب","lemma":"كَٰذِب","grammar_bn":"শব্দ"},{"id":30080,"position":8,"text_uthmani":"٢٧","transliteration":"","translation_bn":"(২৭)","root":"—","lemma":"٢٧","grammar_bn":"মার্কার"}]'::jsonb, 'qāla sananẓuru aṣadaqta am kunta mina l-kādhibīna', 'সুলাইমান বলল- ‘এখন আমি দেখব, তুমি সত্য বলেছ, না তুমি মিথ্যেবাদী।', '[Solomon] said, "We will see whether you were truthful or were of the liars.', 'সুলাইমান বলল- ‘এখন আমি দেখব, তুমি সত্য বলেছ, না তুমি মিথ্যেবাদী।', '[Solomon] said, "We will see whether you were truthful or were of the liars.', NULL, NULL, NULL, NULL, NULL, 'https://everyayah.com/data/Alafasy_128kbps/027027.mp3', now()),
  (27, 28, '', '[{"id":31129,"position":1,"text_uthmani":"ٱذْهَب","transliteration":"idh''hab","translation_bn":"তুমি যাও","root":"ذهب","lemma":"ذَهَبَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":31130,"position":2,"text_uthmani":"بِّكِتَـٰبِى","transliteration":"bikitābī","translation_bn":"নিয়ে আমার চিঠি","root":"كتب","lemma":"كِتَٰبِى","grammar_bn":"অব্যয় (Preposition)"},{"id":31131,"position":3,"text_uthmani":"هَـٰذَا","transliteration":"hādhā","translation_bn":"এই","root":"—","lemma":"هَٰذَا","grammar_bn":"নির্দেশক সর্বনাম (Demonstrative)"},{"id":31132,"position":4,"text_uthmani":"فَأَلْقِهْ","transliteration":"fa-alqih","translation_bn":"অতঃপর অর্পণ করো তা","root":"لقي","lemma":"أَلْقَىٰ^","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":31133,"position":5,"text_uthmani":"إِلَيْهِمْ","transliteration":"ilayhim","translation_bn":"নিকট তাদের","root":"—","lemma":"إِلَىٰ\r","grammar_bn":"অব্যয় (Preposition)"},{"id":31134,"position":6,"text_uthmani":"ثُمَّ","transliteration":"thumma","translation_bn":"এরপর","root":"—","lemma":"ثُمّ\r","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":31135,"position":7,"text_uthmani":"تَوَلَّ","transliteration":"tawalla","translation_bn":"সরে দাঁড়াও","root":"ولي","lemma":"تَوَلَّىٰ","grammar_bn":"ক্রিয়া (Verb)"},{"id":31136,"position":8,"text_uthmani":"عَنْهُمْ","transliteration":"ʿanhum","translation_bn":"হ''তে তাদের","root":"—","lemma":"عَن\r","grammar_bn":"অব্যয় (Preposition)"},{"id":31137,"position":9,"text_uthmani":"فَٱنظُرْ","transliteration":"fa-unẓur","translation_bn":"অতঃপর লক্ষ্য করো","root":"نظر","lemma":"نَّظَرَ","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":31138,"position":10,"text_uthmani":"مَاذَا","transliteration":"mādhā","translation_bn":"কি","root":"—","lemma":"مَاذَا\r","grammar_bn":"প্রশ্নবোধক (Interrogative)"},{"id":31139,"position":11,"text_uthmani":"يَرْجِعُونَ","transliteration":"yarjiʿūna","translation_bn":"প্রতিক্রিয়া দেখায়\"","root":"رجع","lemma":"رَجَعَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":31140,"position":12,"text_uthmani":"٢٨","transliteration":"","translation_bn":"(২৮)","root":"—","lemma":"٢٨","grammar_bn":"মার্কার"}]'::jsonb, 'idh''hab bikitābī hādhā fa-alqih ilayhim thumma tawalla ʿanhum fa-unẓur mādhā yarjiʿūna', 'আমার এই পত্র নিয়ে যাও আর এটা তাদের কাছে অর্পণ কর। অতঃপর তাদের কাছ থেকে সরে পড় তারপর দেখ, তারা কী জবাব দেয়।’', 'Take this letter of mine and deliver it to them. Then leave them and see what [answer] they will return."', 'আমার এই পত্র নিয়ে যাও আর এটা তাদের কাছে অর্পণ কর। অতঃপর তাদের কাছ থেকে সরে পড় তারপর দেখ, তারা কী জবাব দেয়।’', 'Take this letter of mine and deliver it to them. Then leave them and see what [answer] they will return."', NULL, NULL, NULL, NULL, NULL, 'https://everyayah.com/data/Alafasy_128kbps/027028.mp3', now()),
  (27, 29, '', '[{"id":32119,"position":1,"text_uthmani":"قَالَتْ","transliteration":"qālat","translation_bn":"(রানী) বললো","root":"قول","lemma":"قَالَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":32120,"position":2,"text_uthmani":"يَـٰٓأَيُّهَا","transliteration":"yāayyuhā","translation_bn":"\"হে","root":"—","lemma":"أَيُّهَا","grammar_bn":"সম্বোধন পদ (Vocative)"},{"id":32121,"position":3,"text_uthmani":"ٱلْمَلَؤُا۟","transliteration":"l-mala-u","translation_bn":"সভাসদবৃন্দ","root":"ملا","lemma":"مَلَأ","grammar_bn":"শব্দ"},{"id":32122,"position":4,"text_uthmani":"إِنِّىٓ","transliteration":"innī","translation_bn":"নিশ্চয়ই আমাকে","root":"—","lemma":"إِنّ","grammar_bn":"অভিঘাত পদ (Accusative)"},{"id":32123,"position":5,"text_uthmani":"أُلْقِىَ","transliteration":"ul''qiya","translation_bn":"অর্পণ করা হয়েছে","root":"لقي","lemma":"أَلْقَىٰ^","grammar_bn":"ক্রিয়া (Verb)"},{"id":32124,"position":6,"text_uthmani":"إِلَىَّ","transliteration":"ilayya","translation_bn":"আমার প্রতি","root":"—","lemma":"إِلَىٰ\r","grammar_bn":"অব্যয় (Preposition)"},{"id":32125,"position":7,"text_uthmani":"كِتَـٰبٌۭ","transliteration":"kitābun","translation_bn":"একটি চিঠি","root":"كتب","lemma":"كِتَٰب","grammar_bn":"বিশেষ্য (Noun)"},{"id":32126,"position":8,"text_uthmani":"كَرِيمٌ","transliteration":"karīmun","translation_bn":"সম্মানিত","root":"كرم","lemma":"كَرِيم","grammar_bn":"বিশেষণ (Adjective)"},{"id":32127,"position":9,"text_uthmani":"٢٩","transliteration":"","translation_bn":"(২৯)","root":"—","lemma":"٢٩","grammar_bn":"মার্কার"}]'::jsonb, 'qālat yāayyuhā l-mala-u innī ul''qiya ilayya kitābun karīmun', 'সেই নারী বলল- ‘ওহে সভাসদগণ! এই যে আমাকে এক সম্মানযোগ্য পত্র দেয়া হয়েছে।', 'She said, "O eminent ones, indeed, to me has been delivered a noble letter.', 'সেই নারী বলল- ‘ওহে সভাসদগণ! এই যে আমাকে এক সম্মানযোগ্য পত্র দেয়া হয়েছে।', 'She said, "O eminent ones, indeed, to me has been delivered a noble letter.', NULL, NULL, NULL, NULL, NULL, 'https://everyayah.com/data/Alafasy_128kbps/027029.mp3', 