  (27, 31, '', '[{"id":33866,"position":1,"text_uthmani":"أَلَّا","transliteration":"allā","translation_bn":"(তা এই) যে না","root":"—","lemma":"أَن\r","grammar_bn":"উদ্দেশ্যবাচক (Intention)"},{"id":33867,"position":2,"text_uthmani":"تَعْلُوا۟","transliteration":"taʿlū","translation_bn":"তোমরা বিদ্রোহ করো","root":"علو","lemma":"تَعَٰلَىٰ","grammar_bn":"ক্রিয়া (Verb)"},{"id":33868,"position":3,"text_uthmani":"عَلَىَّ","transliteration":"ʿalayya","translation_bn":"আমার বিরুদ্ধে","root":"—","lemma":"عَلَىٰ\r","grammar_bn":"অব্যয় (Preposition)"},{"id":33869,"position":4,"text_uthmani":"وَأْتُونِى","transliteration":"watūnī","translation_bn":"এবং আমার (নিকট) চলে এসো","root":"اتي","lemma":"أَتَى","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":33870,"position":5,"text_uthmani":"مُسْلِمِينَ","transliteration":"mus''limīna","translation_bn":"আত্মসমর্পণকারী হয়ে\"","root":"سلم","lemma":"مُسْلِم","grammar_bn":"বিশেষ্য (Noun)"},{"id":33871,"position":6,"text_uthmani":"٣١","transliteration":"","translation_bn":"(৩১)","root":"—","lemma":"٣١","grammar_bn":"মার্কার"}]'::jsonb, 'allā taʿlū ʿalayya watūnī mus''limīna', 'আমার প্রতি উদ্ধত হয়ো না, অনুগত হয়ে আমার কাছে হাজির হও।', 'Be not haughty with me but come to me in submission [as Muslims].'' "', 'আমার প্রতি উদ্ধত হয়ো না, অনুগত হয়ে আমার কাছে হাজির হও।', 'Be not haughty with me but come to me in submission [as Muslims].'' "', NULL, NULL, NULL, NULL, NULL, 'https://everyayah.com/data/Alafasy_128kbps/027031.mp3', now()),
