  (28, 3, '', '[{"id":2987,"position":1,"text_uthmani":"نَتْلُوا۟","transliteration":"natlū","translation_bn":"আমরা তিলাওয়াত করছি","root":"تلو","lemma":"تَلَىٰ","grammar_bn":"ক্রিয়া (Verb)"},{"id":2988,"position":2,"text_uthmani":"عَلَيْكَ","transliteration":"ʿalayka","translation_bn":"নিকট তোমার","root":"—","lemma":"عَلَىٰ\r","grammar_bn":"অব্যয় (Preposition)"},{"id":2989,"position":3,"text_uthmani":"مِن","transliteration":"min","translation_bn":"কিছু","root":"—","lemma":"مِن\r","grammar_bn":"অব্যয় (Preposition)"},{"id":2990,"position":4,"text_uthmani":"نَّبَإِ","transliteration":"naba-i","translation_bn":"বৃত্তান্ত","root":"نبا","lemma":"نَبَأ","grammar_bn":"বিশেষ্য (Noun)"},{"id":2991,"position":5,"text_uthmani":"مُوسَىٰ","transliteration":"mūsā","translation_bn":"মূসার","root":"—","lemma":"مُوسَىٰ","grammar_bn":"নামবাচক বিশেষ্য (Proper Noun)"},{"id":2992,"position":6,"text_uthmani":"وَفِرْعَوْنَ","transliteration":"wafir''ʿawna","translation_bn":"ও ফিরআউনের","root":"—","lemma":"فِرْعَوْن","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":2993,"position":7,"text_uthmani":"بِٱلْحَقِّ","transliteration":"bil-ḥaqi","translation_bn":"ভাবে যথাযথ","root":"حقق","lemma":"حَقّ","grammar_bn":"অব্যয় (Preposition)"},{"id":2994,"position":8,"text_uthmani":"لِقَوْمٍۢ","transliteration":"liqawmin","translation_bn":"জন্যে (এমন) সম্প্রদায়ের (যারা)","root":"قوم","lemma":"قَوْم","grammar_bn":"অব্যয় (Preposition)"},{"id":2995,"position":9,"text_uthmani":"يُؤْمِنُونَ","transliteration":"yu''minūna","translation_bn":"ঈমান আনে","root":"امن","lemma":"ءَامَنَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":2996,"position":10,"text_uthmani":"٣","transliteration":"","translation_bn":"(৩)","root":"—","lemma":"٣","grammar_bn":"মার্কার"}]'::jsonb, 'natlū ʿalayka min naba-i mūsā wafir''ʿawna bil-ḥaqi liqawmin yu''minūna', 'আমি মূসা ও ফিরআউনের কাহিনী হতে কিছু তোমার কাছে সত্যিকারভাবে বিবৃত করছি বিশ্বাসী সম্প্রদায়ের উদ্দেশ্যে।', 'We recite to you from the news of Moses and Pharaoh in truth for a people who believe.', 'আমি মূসা ও ফিরআউনের কাহিনী হতে কিছু তোমার কাছে সত্যিকারভাবে বিবৃত করছি বিশ্বাসী সম্প্রদায়ের উদ্দেশ্যে।', 'We recite to you from the news of Moses and Pharaoh in truth for a people who believe.', NULL, NULL, NULL, NULL, NULL, 'https://everyayah.com/data/Alafasy_128kbps/028003.mp3', now()),
  (28, 4, '', '[{"id":4308,"position":1,"text_uthmani":"إِنَّ","transliteration":"inna","translation_bn":"নিশ্চয়ই","root":"—","lemma":"إِنّ","grammar_bn":"অভিঘাত পদ (Accusative)"},{"id":4309,"position":2,"text_uthmani":"فِرْعَوْنَ","transliteration":"fir''ʿawna","translation_bn":"ফিরআউন","root":"—","lemma":"فِرْعَوْن","grammar_bn":"নামবাচক বিশেষ্য (Proper Noun)"},{"id":4310,"position":3,"text_uthmani":"عَلَا","transliteration":"ʿalā","translation_bn":"উদ্ধৃত হয়েছিলো","root":"علو","lemma":"تَعَٰلَىٰ","grammar_bn":"ক্রিয়া (Verb)"},{"id":4311,"position":4,"text_uthmani":"فِى","transliteration":"fī","translation_bn":"মধ্যে","root":"—","lemma":"فِى\r","grammar_bn":"অব্যয় (Preposition)"},{"id":4312,"position":5,"text_uthmani":"ٱلْأَرْضِ","transliteration":"l-arḍi","translation_bn":"দেশের (অর্থাৎ মিশরে)","root":"ارض","lemma":"أَرْض","grammar_bn":"শব্দ"},{"id":4313,"position":6,"text_uthmani":"وَجَعَلَ","transliteration":"wajaʿala","translation_bn":"এবং (বিভক্ত) করেছিলো","root":"جعل","lemma":"جَعَلَ","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":4314,"position":7,"text_uthmani":"أَهْلَهَا","transliteration":"ahlahā","translation_bn":"অধিবাসীদেরকে তার","root":"اهل","lemma":"أَهْل","grammar_bn":"বিশেষ্য (Noun)"},{"id":4315,"position":8,"text_uthmani":"شِيَعًۭا","transliteration":"shiyaʿan","translation_bn":"(বিভিন্ন) দলে","root":"شيع","lemma":"شِيعَة","grammar_bn":"বিশেষ্য (Noun)"},{"id":4316,"position":9,"text_uthmani":"يَسْتَضْعِفُ","transliteration":"yastaḍʿifu","translation_bn":"দূর্বল করে রেখে","root":"ضعف","lemma":"ٱسْتَضْعَفُ","grammar_bn":"ক্রিয়া (Verb)"},{"id":4317,"position":10,"text_uthmani":"طَآئِفَةًۭ","transliteration":"ṭāifatan","translation_bn":"একটি দলকে","root":"طوف","lemma":"طَا^ئِفَة","grammar_bn":"বিশেষ্য (Noun)"},{"id":4318,"position":11,"text_uthmani":"مِّنْهُمْ","transliteration":"min''hum","translation_bn":"মধ্যে হ''তে তাদের","root":"—","lemma":"مِن\r","grammar_bn":"অব্যয় (Preposition)"},{"id":4319,"position":12,"text_uthmani":"يُذَبِّحُ","transliteration":"yudhabbiḥu","translation_bn":"সে জবেহ করতো","root":"ذبح","lemma":"يُذَبِّحُ","grammar_bn":"ক্রিয়া (Verb)"},{"id":4320,"position":13,"text_uthmani":"أَبْنَآءَهُمْ","transliteration":"abnāahum","translation_bn":"পুত্রসন্তানদেরকে তাদের","root":"بني","lemma":"ٱبْن","grammar_bn":"বিশেষ্য (Noun)"},{"id":4321,"position":14,"text_uthmani":"وَيَسْتَحْىِۦ","transliteration":"wayastaḥyī","translation_bn":"ও জীবিত রাখতো","root":"حيي","lemma":"يَسْتَحْىِ.^","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":4322,"position":15,"text_uthmani":"نِسَآءَهُمْ ۚ","transliteration":"nisāahum","translation_bn":"নারীদেরকে তাদের","root":"نسو","lemma":"نِسَا^ء","grammar_bn":"বিশেষ্য (Noun)"},{"id":4324,"position":16,"text_uthmani":"إِنَّهُۥ","transliteration":"innahu","translation_bn":"নিশ্চয়ই সে","root":"—","lemma":"إِنّ","grammar_bn":"অভিঘাত পদ (Accusative)"},{"id":4325,"position":17,"text_uthmani":"كَانَ","transliteration":"kāna","translation_bn":"ছিলো","root":"كون","lemma":"كَانَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":4326,"position":18,"text_uthmani":"مِنَ","transliteration":"mina","translation_bn":"অন্তর্ভুক্ত","root":"—","lemma":"مِن\r","grammar_bn":"অব্যয় (Preposition)"},{"id":4327,"position":19,"text_uthmani":"ٱلْمُفْسِدِينَ","transliteration":"l-muf''sidīna","translation_bn":"বিপর্যয় সৃষ্টিকারীদের","root":"فسد","lemma":"مُفْسِد","grammar_bn":"শব্দ"},{"id":4328,"position":20,"text_uthmani":"٤","transliteration":"","translation_bn":"(৪)","root":"—","lemma":"٤","grammar_bn":"মার্কার"}]'::jsonb, 'inna fir''ʿawna ʿalā fī l-arḍi wajaʿala ahlahā shiyaʿan yastaḍʿifu ṭāifatan min''hum yudhabbiḥu abnāahum wayastaḥyī nisāahum innahu kāna mina l-muf''sidīna', 'বস্তুতঃ ফেরাউন দেশে উদ্ধত হয়ে গিয়েছিল আর সেখানকার অধিবাসীদেরকে বিভিন্ন শ্রেণীতে বিভক্ত করে তাদের একটি শ্রেণীকে দুর্বল করে রেখেছিল, তাদের পুত্রদেরকে সে হত্যা করত আর তাদের নারীদেরকে জীবিত রাখত; সে ছিল ফাসাদ সৃষ্টিকারী।', 'Indeed, Pharaoh exalted himself in the land and made its people into factions, oppressing a sector among them, slaughtering their [newborn] sons and keeping their females alive. Indeed, he was of the corrupters.', 'বস্তুতঃ ফেরাউন দেশে উদ্ধত হয়ে গিয়েছিল আর সেখানকার অধিবাসীদেরকে বিভিন্ন শ্রেণীতে বিভক্ত করে তাদের একটি শ্রেণীকে দুর্বল করে রেখেছিল, তাদের পুত্রদেরকে সে হত্যা করত আর তাদের নারীদেরকে জীবিত রাখত; সে ছিল ফাসাদ সৃষ্টিকারী।', 'Indeed, Pharaoh exalted himself in the land and made its people into factions, oppressing a sector among them, slaughtering their [newborn] sons and keeping their females alive. Indeed, he was of the corrupters.', NULL, NULL, NULL, NULL, NULL, 'https://everyayah.com/data/Alafasy_128kbps/028004.mp3', now()),
  (28, 5, '', '[{"id":5571,"position":1,"text_uthmani":"وَنُرِيدُ","transliteration":"wanurīdu","translation_bn":"এবং আমরা চাই","root":"رود","lemma":"أَرَادَ","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":5572,"position":2,"text_uthmani":"أَن","transliteration":"an","translation_bn":"যে","root":"—","lemma":"أَن\r","grammar_bn":"অধীনস্থ যোজক (Subordinating)"},{"id":5573,"position":3,"text_uthmani":"نَّمُنَّ","transliteration":"namunna","translation_bn":"আমরা অনুগ্রহ করবো","root":"منن","lemma":"مَنَّ","grammar_bn":"ক্রিয়া (Verb)"},{"id":5574,"position":4,"text_uthmani":"عَلَى","transliteration":"ʿalā","translation_bn":"(তাদের) উপর","root":"—","lemma":"عَلَىٰ\r","grammar_bn":"অব্যয় (Preposition)"},{"id":5575,"position":5,"text_uthmani":"ٱلَّذِينَ","transliteration":"alladhīna","translation_bn":"যাদেরকে","root":"—","lemma":"ٱلَّذِى","grammar_bn":"সাপেক্ষ সর্বনাম (Relative)"},{"id":5576,"position":6,"text_uthmani":"ٱسْتُضْعِفُوا۟","transliteration":"us''tuḍ''ʿifū","translation_bn":"দূর্বল করে রাখা হয়েছিলো","root":"ضعف","lemma":"ٱسْتَضْعَفُ","grammar_bn":"ক্রিয়া (Verb)"},{"id":5577,"position":7,"text_uthmani":"فِى","transliteration":"fī","translation_bn":"মধ্যে","root":"—","lemma":"فِى\r","grammar_bn":"অব্যয় (Preposition)"},{"id":5578,"position":8,"text_uthmani":"ٱلْأَرْضِ","transliteration":"l-arḍi","translation_bn":"দেশের","root":"ارض","lemma":"أَرْض","grammar_bn":"শব্দ"},{"id":5579,"position":9,"text_uthmani":"وَنَجْعَلَهُمْ","transliteration":"wanajʿalahum","translation_bn":"এবং আমরা করবো তাদেরকে","root":"جعل","lemma":"جَعَلَ","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":5580,"position":10,"text_uthmani":"أَئِمَّةًۭ","transliteration":"a-immatan","translation_bn":"নেতা","root":"امم","lemma":"إِمَام","grammar_bn":"বিশেষ্য (Noun)"},{"id":5581,"position":11,"text_uthmani":"وَنَجْعَلَهُمُ","transliteration":"wanajʿalahumu","translation_bn":"ও আমরা বানাবো তাদেরকে","root":"جعل","lemma":"جَعَلَ","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":5582,"position":12,"text_uthmani":"ٱلْوَٰرِثِينَ","transliteration":"l-wārithīna","translation_bn":"উত্তরাধিকারী","root":"ورث","lemma":"وَارِث","grammar_bn":"শব্দ"},{"id":5583,"position":13,"text_uthmani":"٥","transliteration":"","translation_bn":"(৫)","root":"—","lemma":"٥","grammar_bn":"মার্কার"}]'::jsonb, 'wanurīdu an namunna ʿalā alladhīna us''tuḍ''ʿifū fī l-arḍi wanajʿalahum a-immatan wanajʿalahumu l-wārithīna', 'দেশে যাদেরকে দুর্বল করে রাখা হয়েছিল আমি তাদের প্রতি অনুগ্রহ করার ইচ্ছে করলাম, আর তাদেরকে নেতা ও উত্তরাধিকারী করার (ইচ্ছে করলাম)।', 'And We wanted to confer favor upon those who were oppressed in the land and make them leaders and make them inheritors', 'দেশে যাদেরকে দুর্বল করে রাখা হয়েছিল আমি তাদের প্রতি অনুগ্রহ করার ইচ্ছে করলাম, আর তাদেরকে নেতা ও উত্তরাধিকারী করার (ইচ্ছে করলাম)।', 'And We wanted to confer favor upon those who were oppressed in the land and make them leaders and make them inheritors', NULL, NULL, NULL, NULL, NULL, 'https://everyayah.com/data/Alafasy_128kbps/028005.mp3', now()),
  (28, 6, '', '[{"id":6831,"position":1,"text_uthmani":"وَنُمَكِّنَ","transliteration":"wanumakkina","translation_bn":"এবং আমরা ক্ষমতাসীন করবো","root":"مكن","lemma":"مَكَّ","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":6832,"position":2,"text_uthmani":"لَهُمْ","transliteration":"lahum","translation_bn":"তাদেরকে","root":"—","lemma":"لَهُمْ","grammar_bn":"অব্যয় (Preposition)"},{"id":6833,"position":3,"text_uthmani":"فِى","transliteration":"fī","translation_bn":"মধ্যে","root":"—","lemma":"فِى\r","grammar_bn":"অব্যয় (Preposition)"},{"id":6834,"position":4,"text_uthmani":"ٱلْأَرْضِ","transliteration":"l-arḍi","translation_bn":"পৃথিবীর","root":"ارض","lemma":"أَرْض","grammar_bn":"শব্দ"},{"id":6835,"position":5,"text_uthmani":"وَنُرِىَ","transliteration":"wanuriya","translation_bn":"এবং আমরা দেখাবো","root":"راي","lemma":"أَرَيْ","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":6836,"position":6,"text_uthmani":"فِرْعَوْنَ","transliteration":"fir''ʿawna","translation_bn":"ফিরআউনকে","root":"—","lemma":"فِرْعَوْن","grammar_bn":"নামবাচক বিশেষ্য (Proper Noun)"},{"id":6837,"position":7,"text_uthmani":"وَهَـٰمَـٰنَ","transliteration":"wahāmāna","translation_bn":"ও হামানকে","root":"—","lemma":"هَٰمَٰن","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":6838,"position":8,"text_uthmani":"وَجُنُودَهُمَا","transliteration":"wajunūdahumā","translation_bn":"ও উভয়ের সৈন্য বাহিনীকে তাদের","root":"جند","lemma":"جُند","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":6839,"position":9,"text_uthmani":"مِنْهُم","transliteration":"min''hum","translation_bn":"হ''তে তাদের (অর্থাৎ বনি ঈসরাঈল)","root":"—","lemma":"مِن\r","grammar_bn":"অব্যয় (Preposition)"},{"id":6840,"position":10,"text_uthmani":"مَّا","transliteration":"mā","translation_bn":"(সেইসব) যা","root":"—","lemma":"مَا\r","grammar_bn":"সাপেক্ষ সর্বনাম (Relative)"},{"id":6841,"position":11,"text_uthmani":"كَانُوا۟","transliteration":"kānū","translation_bn":"তারা ছিলো","root":"كون","lemma":"كَانَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":6842,"position":12,"text_uthmani":"يَحْذَرُونَ","transliteration":"yaḥdharūna","translation_bn":"আশংকা করে তারা","root":"حذر","lemma":"يَحْذَرُ","grammar_bn":"ক্রিয়া (Verb)"},{"id":6843,"position":13,"text_uthmani":"٦","transliteration":"","translation_bn":"(৬)","root":"—","lemma":"٦","grammar_bn":"মার্কার"}]'::jsonb, 'wanumakkina lahum fī l-arḍi wanuriya fir''ʿawna wahāmāna wajunūdahumā min''hum mā kānū yaḥdharūna', 'আর (ইচ্ছে করলাম) তাদেরকে দেশে প্রতিষ্ঠিত করতে, আর ফেরাউন, হামান ও তাদের সৈন্য বাহিনীকে দেখিয়ে দিতে যা তারা তাদের (অর্থাৎ মূসার সম্প্রদায়ের) থেকে আশঙ্কা করত।', 'And establish them in the land and show Pharaoh and [his minister] Haman and their soldiers through them that which they had feared.', 'আর (ইচ্ছে করলাম) তাদেরকে দেশে প্রতিষ্ঠিত করতে, আর ফেরাউন, হামান ও তাদের সৈন্য বাহিনীকে দেখিয়ে দিতে যা তারা তাদের (অর্থাৎ মূসার সম্প্রদায়ের) থেকে আশঙ্কা করত।', 'And establish them in the land and show Pharaoh and [his minister] Haman and their soldiers through them that which they had feared.', NULL, NULL, NULL, NULL, NULL, 'https://everyayah.com/data/Alafasy_128kbps/028006.mp3', now()),
  (28, 7, '', '[{"id":8157,"position":1,"text_uthmani":"وَأَوْحَيْنَآ","transliteration":"wa-awḥaynā","translation_bn":"এবং ইঙ্গিতে বলেছিলাম আমরা","root":"وحي","lemma":"أَوْحَىٰ^","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":8158,"position":2,"text_uthmani":"إِلَىٰٓ","transliteration":"ilā","translation_bn":"প্রতি","root":"—","lemma":"إِلَىٰ\r","grammar_bn":"অব্যয় (Preposition)"},{"id":8159,"position":3,"text_uthmani":"أُمِّ","transliteration":"ummi","translation_bn":"মায়ের","root":"امم","lemma":"أُمّ","grammar_bn":"বিশেষ্য (Noun)"},{"id":8160,"position":4,"text_uthmani":"مُوسَىٰٓ","transliteration":"mūsā","translation_bn":"মূসার","root":"—","lemma":"مُوسَىٰ","grammar_bn":"নামবাচক বিশেষ্য (Proper Noun)"},{"id":8161,"position":5,"text_uthmani":"أَنْ","transliteration":"an","translation_bn":"যে","root":"—","lemma":"أَن\r","grammar_bn":"উদ্দেশ্যবাচক (Intention)"},{"id":8162,"position":6,"text_uthmani":"أَرْضِعِيهِ ۖ","transliteration":"arḍiʿīhi","translation_bn":"\"দুধপান করাও তাকে","root":"رضع","lemma":"أَرْضَعَتْ","grammar_bn":"ক্রিয়া (Verb)"},{"id":8164,"position":7,"text_uthmani":"فَإِذَا","transliteration":"fa-idhā","translation_bn":"অতঃপর যখন","root":"—","lemma":"إِذَا\r","grammar_bn":"শব্দ"},{"id":8165,"position":8,"text_uthmani":"خِفْتِ","transliteration":"khif''ti","translation_bn":"তুমি আশংকা করবে","root":"خوف","lemma":"خَافَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":8166,"position":9,"text_uthmani":"عَلَيْهِ","transliteration":"ʿalayhi","translation_bn":"সম্পর্কে তার","root":"—","lemma":"عَلَىٰ\r","grammar_bn":"অব্যয় (Preposition)"},{"id":8167,"position":10,"text_uthmani":"فَأَلْقِيهِ","transliteration":"fa-alqīhi","translation_bn":"তখন (ফেলে) দাও তাকে","root":"لقي","lemma":"أَلْقَىٰ^","grammar_bn":"শব্দ"},{"id":8168,"position":11,"text_uthmani":"فِى","transliteration":"fī","translation_bn":"মধ্যে","root":"—","lemma":"فِى\r","grammar_bn":"অব্যয় (Preposition)"},{"id":8169,"position":12,"text_uthmani":"ٱلْيَمِّ","transliteration":"l-yami","translation_bn":"সাগরের","root":"يمم","lemma":"يَمّ","grammar_bn":"শব্দ"},{"id":8170,"position":13,"text_uthmani":"وَلَا","transliteration":"walā","translation_bn":"এবং না","root":"—","lemma":"لَا\r","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":8171,"position":14,"text_uthmani":"تَخَافِى","transliteration":"takhāfī","translation_bn":"ভয় করো","root":"خوف","lemma":"خَافَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":8172,"position":15,"text_uthmani":"وَلَا","transliteration":"walā","translation_bn":"আর না","root":"—","lemma":"لَا\r","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":8173,"position":16,"text_uthmani":"تَحْزَنِىٓ ۖ","transliteration":"taḥzanī","translation_bn":"দুঃশ্চিন্তা করো","root":"حزن","lemma":"يَحْزُن","grammar_bn":"ক্রিয়া (Verb)"},{"id":8175,"position":17,"text_uthmani":"إِنَّا","transliteration":"innā","translation_bn":"নিশ্চয়ই আমরা","root":"—","lemma":"إِنّ","grammar_bn":"অভিঘাত পদ (Accusative)"},{"id":8176,"position":18,"text_uthmani":"رَآدُّوهُ","transliteration":"rāddūhu","translation_bn":"ফিরিয়ে দিবো তাকে","root":"ردد","lemma":"رَا^دّ","grammar_bn":"বিশেষ্য (Noun)"},{"id":8177,"position":19,"text_uthmani":"إِلَيْكِ","transliteration":"ilayki","translation_bn":"কাছে তোমার","root":"—","lemma":"إِلَىٰ\r","grammar_bn":"অব্যয় (Preposition)"},{"id":8178,"position":20,"text_uthmani":"وَجَاعِلُوهُ","transliteration":"wajāʿilūhu","translation_bn":"ও করবো তাকে","root":"جعل","lemma":"جَاعِل","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":8179,"position":21,"text_uthmani":"مِنَ","transliteration":"mina","translation_bn":"অন্তর্ভুক্ত","root":"—","lemma":"مِن\r","grammar_bn":"অব্যয় (Preposition)"},{"id":8180,"position":22,"text_uthmani":"ٱلْمُرْسَلِينَ","transliteration":"l-mur''salīna","translation_bn":"রাসূলদের\"","root":"رسل","lemma":"مُّرْسَل","grammar_bn":"শব্দ"},{"id":8181,"position":23,"text_uthmani":"٧","transliteration":"","translation_bn":"(৭)","root":"—","lemma":"٧","grammar_bn":"মার্কার"}]'::jsonb, 'wa-awḥaynā ilā ummi mūsā an arḍiʿīhi fa-idhā khif''ti ʿalayhi fa-alqīhi fī l-yami walā takhāfī walā taḥzanī innā rāddūhu ilayki wajāʿilūhu mina l-mur''salīna', 'আমি মূসার মায়ের প্রতি ওয়াহী করলাম যে, তাকে স্তন্য পান করাতে থাক। যখন তুমি তার সম্পর্কে আশঙ্কা করবে, তখন তুমি তাকে দরিয়ায় নিক্ষেপ করবে, আর তুমি ভয় করবে না, দুঃখও করবে না, আমি তাকে অবশ্যই তোমার কাছে ফিরিয়ে দেব আর তাকে রসূলদের একজন করব।', 'And We inspired to the mother of Moses, "Suckle him; but when you fear for him, cast him into the river and do not fear and do not grieve. Indeed, We will return him to you and will make him [one] of the messengers."', 'আমি মূসার মায়ের প্রতি ওয়াহী করলাম যে, তাকে স্তন্য পান করাতে থাক। যখন তুমি তার সম্পর্কে আশঙ্কা করবে, তখন তুমি তাকে দরিয়ায় নিক্ষেপ করবে, আর তুমি ভয় করবে না, দুঃখও করবে না, আমি তাকে অবশ্যই তোমার কাছে ফিরিয়ে দেব আর তাকে রসূলদের একজন করব।', 'And We inspired to the mother of Moses, "Suckle him; but when you fear for him, cast him into the river and do not fear and do not grieve. Indeed, We will return him to you and will make him [one] of the messengers."', NULL, NULL, NULL, NULL, NULL, 'https://everyayah.com/data/Alafasy_128kbps/028007.mp3', now()),
  (28, 8, '', '[{"id":9331,"position":1,"text_uthmani":"فَٱلْتَقَطَهُۥٓ","transliteration":"fal-taqaṭahu","translation_bn":"অতঃপর তুলে নিলো তাকে","root":"لقط","lemma":"ٱلْتَقَطَ","grammar_bn":"শব্দ"},{"id":9332,"position":2,"text_uthmani":"ءَالُ","transliteration":"ālu","translation_bn":"পরিবার","root":"اول","lemma":"ءَال","grammar_bn":"বিশেষ্য (Noun)"},{"id":9333,"position":3,"text_uthmani":"فِرْعَوْنَ","transliteration":"fir''ʿawna","translation_bn":"ফিরআউনের","root":"—","lemma":"فِرْعَوْن","grammar_bn":"নামবাচক বিশেষ্য (Proper Noun)"},{"id":9334,"position":4,"text_uthmani":"لِيَكُونَ","transliteration":"liyakūna","translation_bn":"যেন হয় সে","root":"كون","lemma":"كَانَ","grammar_bn":"শব্দ"},{"id":9335,"position":5,"text_uthmani":"لَهُمْ","transliteration":"lahum","translation_bn":"জন্যে তাদের","root":"—","lemma":"لَهُمْ","grammar_bn":"অব্যয় (Preposition)"},{"id":9336,"position":6,"text_uthmani":"عَدُوًّۭا","transliteration":"ʿaduwwan","translation_bn":"শত্রু","root":"عدو","lemma":"عَدُوّ","grammar_bn":"বিশেষ্য (Noun)"},{"id":9337,"position":7,"text_uthmani":"وَحَزَنًا ۗ","transliteration":"waḥazanan","translation_bn":"ও দুঃশ্চিন্তার কারণ","root":"حزن","lemma":"حَزَن","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":9339,"position":8,"text_uthmani":"إِنَّ","transliteration":"inna","translation_bn":"নিশ্চয়ই","root":"—","lemma":"إِنّ","grammar_bn":"অভিঘাত পদ (Accusative)"},{"id":9340,"position":9,"text_uthmani":"فِرْعَوْنَ","transliteration":"fir''ʿawna","translation_bn":"ফিরআউন","root":"—","lemma":"فِرْعَوْن","grammar_bn":"নামবাচক বিশেষ্য (Proper Noun)"},{"id":9341,"position":10,"text_uthmani":"وَهَـٰمَـٰنَ","transliteration":"wahāmāna","translation_bn":"ও হামান","root":"—","lemma":"هَٰمَٰن","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":9342,"position":11,"text_uthmani":"وَجُنُودَهُمَا","transliteration":"wajunūdahumā","translation_bn":"ও উভয়ের সেনাবাহিনী তাদের","root":"جند","lemma":"جُند","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":9343,"position":12,"text_uthmani":"كَانُوا۟","transliteration":"kānū","translation_bn":"তারা ছিলো","root":"كون","lemma":"كَانَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":9344,"position":13,"text_uthmani":"خَـٰطِـِٔينَ","transliteration":"khāṭiīna","translation_bn":"অপরাধী","root":"خطا","lemma":"خَٰطِـ#ِين","grammar_bn":"বিশেষ্য (Noun)"},{"id":9345,"position":14,"text_uthmani":"٨","transliteration":"","translation_bn":"(৮)","root":"—","lemma":"٨","grammar_bn":"মার্কার"}]'::jsonb, 'fal-taqaṭahu ālu fir''ʿawna liyakūna lahum ʿaduwwan waḥazanan inna fir''ʿawna wahāmāna wajunūdahumā kānū khāṭiīna', 'অতঃপর ফেরাউনের লোকজন তাকে উঠিয়ে নিল যাতে সে তাদের জন্য শত্রু হতে ও দুঃখের কারণ হতে পারে। ফেরাউন, হামান ও তাদের বাহিনীর লোকেরা তো ছিল অপরাধী।', 'And the family of Pharaoh picked him up [out of the river] so that he would become to them an enemy and a [cause of] grief. Indeed, Pharaoh and Haman and their soldiers were deliberate sinners.', 'অতঃপর ফেরাউনের লোকজন তাকে উঠিয়ে নিল যাতে সে তাদের জন্য শত্রু হতে ও দুঃখের কারণ হতে পারে। ফেরাউন, হামান ও তাদের বাহিনীর লোকেরা তো ছিল অপরাধী।', 'And the family of Pharaoh picked him up [out of the river] so that he would become to them an enemy and a [cause of] grief. Indeed, Pharaoh and Haman and their soldiers were deliberate sinners.', NULL, NULL, NULL, NULL, NULL, 'https://everyayah.com/data/Alafasy_128kbps/028008.mp3', now()),
  (28, 9, '', '[{"id":10512,"position":1,"text_uthmani":"وَقَالَتِ","transliteration":"waqālati","translation_bn":"এবং বললো","root":"قول","lemma":"قَالَ","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":10513,"position":2,"text_uthmani":"ٱمْرَأَتُ","transliteration":"im''ra-atu","translation_bn":"স্ত্রী","root":"مرا","lemma":"ٱمْرَأَت","grammar_bn":"বিশেষ্য (Noun)"},{"id":10514,"position":3,"text_uthmani":"فِرْعَوْنَ","transliteration":"fir''ʿawna","translation_bn":"ফিরআউনের","root":"—","lemma":"فِرْعَوْن","grammar_bn":"নামবাচক বিশেষ্য (Proper Noun)"},{"id":10515,"position":4,"text_uthmani":"قُرَّتُ","transliteration":"qurratu","translation_bn":"\"(এই বালক) প্রশান্তি","root":"قرر","lemma":"قُرَّة","grammar_bn":"বিশেষ্য (Noun)"},{"id":10516,"position":5,"text_uthmani":"عَيْنٍۢ","transliteration":"ʿaynin","translation_bn":"নয়নের","root":"عين","lemma":"عَيْن","grammar_bn":"বিশেষ্য (Noun)"},{"id":10517,"position":6,"text_uthmani":"لِّى","transliteration":"lī","translation_bn":"জন্যে আমার","root":"—","lemma":"لِّى","grammar_bn":"অব্যয় (Preposition)"},{"id":10518,"position":7,"text_uthmani":"وَلَكَ ۖ","transliteration":"walaka","translation_bn":"ও জন্যে তোমার","root":"—","lemma":"وَلَكَ ۖ","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":10520,"position":8,"text_uthmani":"لَا","transliteration":"lā","translation_bn":"না","root":"—","lemma":"لَا\r","grammar_bn":"নিষেধবাচক (Prohibition)"},{"id":10521,"position":9,"text_uthmani":"تَقْتُلُوهُ","transliteration":"taqtulūhu","translation_bn":"তোমরা হত্যা করো তাকে","root":"قتل","lemma":"قَتَلَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":10522,"position":10,"text_uthmani":"عَسَىٰٓ","transliteration":"ʿasā","translation_bn":"হয়তো","root":"عسي","lemma":"عَسَى","grammar_bn":"ক্রিয়া (Verb)"},{"id":10523,"position":11,"text_uthmani":"أَن","transliteration":"an","translation_bn":"সে","root":"—","lemma":"أَن\r","grammar_bn":"অধীনস্থ যোজক (Subordinating)"},{"id":10524,"position":12,"text_uthmani":"يَنفَعَنَآ","transliteration":"yanfaʿanā","translation_bn":"উপকারে আসবে আমাদের","root":"نفع","lemma":"نَفَعَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":10525,"position":13,"text_uthmani":"أَوْ","transliteration":"aw","translation_bn":"অথবা","root":"—","lemma":"أَو\r","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":10526,"position":14,"text_uthmani":"نَتَّخِذَهُۥ","transliteration":"nattakhidhahu","translation_bn":"আমরা গ্রহন করবো তাকে","root":"اخذ","lemma":"ٱتَّخَذَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":10527,"position":15,"text_uthmani":"وَلَدًۭا","transliteration":"waladan","translation_bn":"পুত্রসন্তান হিসেবে\"","root":"ولد","lemma":"وَلَد","grammar_bn":"বিশেষ্য (Noun)"},{"id":10528,"position":16,"text_uthmani":"وَهُمْ","transliteration":"wahum","translation_bn":"অথচ তারা","root":"—","lemma":"وَهُمْ","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":10529,"position":17,"text_uthmani":"لَا","transliteration":"lā","translation_bn":"না","root":"—","lemma":"لَا\r","grammar_bn":"না-বোধক (Negative)"},{"id":10530,"position":18,"text_uthmani":"يَشْعُرُونَ","transliteration":"yashʿurūna","translation_bn":"টেরও পায় (এর পরিমাণ)","root":"شعر","lemma":"يَشْعُرُ","grammar_bn":"ক্রিয়া (Verb)"},{"id":10531,"position":19,"text_uthmani":"٩","transliteration":"","translation_bn":"(৯)","root":"—","lemma":"٩","grammar_bn":"মার্কার"}]'::jsonb, 'waqālati im''ra-atu fir''ʿawna qurratu ʿaynin lī walaka lā taqtulūhu ʿasā an yanfaʿanā aw nattakhidhahu waladan wahum lā yashʿurūna', 'ফেরাঊনের স্ত্রী বলল- ‘এ শিশু আমার ও তোমার চক্ষু শীতলকারী, তাকে হত্যা কর না, সে আমাদের উপকারে লাগতে পারে অথবা তাকে আমরা পুত্র হিসেবেও গ্রহণ করতে পারি আর তারা কিছুই বুঝতে পারল না (তাদের এ কাজের পরিণাম কী)।', 'And the wife of Pharaoh said, "[He will be] a comfort of the eye for me and for you. Do not kill him; perhaps he may benefit us, or we may adopt him as a son." And they perceived not.', 'ফেরাঊনের স্ত্রী বলল- ‘এ শিশু আমার ও তোমার চক্ষু শীতলকারী, তাকে হত্যা কর না, সে আমাদের উপকারে লাগতে পারে অথবা তাকে আমরা পুত্র হিসেবেও গ্রহণ করতে পারি আর তারা কিছুই বুঝতে পারল না (তাদের এ কাজের পরিণাম কী)।', 'And the wife of Pharaoh said, "[He will be] a comfort of the eye for me and for you. Do not kill him; perhaps he may benefit us, or we may adopt him as a son." And they perceived not.', NULL, NULL, NULL, NULL, NULL, 'https://everyayah.com/data/Alafasy_128kbps/028009.mp3', now()),
  (28, 10, '', '[{"id":11748,"position":1,"text_uthmani":"وَأَصْبَحَ","transliteration":"wa-aṣbaḥa","translation_bn":"এবং হয়ে পড়লো","root":"صبح","lemma":"أَصْبَحَ","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":11749,"position":2,"text_uthmani":"فُؤَادُ","transliteration":"fuādu","translation_bn":"অন্তর","root":"فاد","lemma":"فُؤَاد","grammar_bn":"বিশেষ্য (Noun)"},{"id":11750,"position":3,"text_uthmani":"أُمِّ","transliteration":"ummi","translation_bn":"মায়ের","root":"امم","lemma":"أُمّ","grammar_bn":"বিশেষ্য (Noun)"},{"id":11751,"position":4,"text_uthmani":"مُوسَىٰ","transliteration":"mūsā","translation_bn":"মূসার","root":"—","lemma":"مُوسَىٰ","grammar_bn":"নামবাচক বিশেষ্য (Proper Noun)"},{"id":11752,"position":5,"text_uthmani":"فَـٰرِغًا ۖ","transliteration":"fārighan","translation_bn":"বিচলিত","root":"فرغ","lemma":"فَٰرِغ","grammar_bn":"বিশেষ্য (Noun)"},{"id":11754,"position":6,"text_uthmani":"إِن","transliteration":"in","translation_bn":"নিশ্চয়ই","root":"—","lemma":"إِن\r","grammar_bn":"শর্তবাচক (Conditional)"},{"id":11755,"position":7,"text_uthmani":"كَادَتْ","transliteration":"kādat","translation_bn":"উপক্রম হয়েছিলো যে","root":"كود","lemma":"كَادَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":11756,"position":8,"text_uthmani":"لَتُبْدِى","transliteration":"latub''dī","translation_bn":"অবশ্যই সে প্রকাশ করবে","root":"بدو","lemma":"يُبْدِىَ","grammar_bn":"দৃঢ়তাবোধক (Emphatic)"},{"id":11757,"position":9,"text_uthmani":"بِهِۦ","transliteration":"bihi","translation_bn":"সম্পর্কে সে","root":"—","lemma":"بِهِۦ","grammar_bn":"অব্যয় (Preposition)"},{"id":11758,"position":10,"text_uthmani":"لَوْلَآ","transliteration":"lawlā","translation_bn":"যদি না","root":"—","lemma":"لَوْلَا^\r","grammar_bn":"শর্তবাচক (Conditional)"},{"id":11759,"position":11,"text_uthmani":"أَن","transliteration":"an","translation_bn":"যে","root":"—","lemma":"أَن\r","grammar_bn":"অধীনস্থ যোজক (Subordinating)"},{"id":11760,"position":12,"text_uthmani":"رَّبَطْنَا","transliteration":"rabaṭnā","translation_bn":"দৃঢ় করতাম আমরা","root":"ربط","lemma":"رَّبَطْ","grammar_bn":"ক্রিয়া (Verb)"},{"id":11761,"position":13,"text_uthmani":"عَلَىٰ","transliteration":"ʿalā","translation_bn":"ওপর","root":"—","lemma":"عَلَىٰ\r","grammar_bn":"অব্যয় (Preposition)"},{"id":11762,"position":14,"text_uthmani":"قَلْبِهَا","transliteration":"qalbihā","translation_bn":"অন্তরের তার","root":"قلب","lemma":"قَلْب","grammar_bn":"বিশেষ্য (Noun)"},{"id":11763,"position":15,"text_uthmani":"لِتَكُونَ","transliteration":"litakūna","translation_bn":"যেন সে হয় (আমাদের প্রতিশ্রুতির প্রতি)","root":"كون","lemma":"كَانَ","grammar_bn":"শব্দ"},{"id":11764,"position":16,"text_uthmani":"مِنَ","transliteration":"mina","translation_bn":"অন্তর্ভুক্ত","root":"—","lemma":"مِن\r","grammar_bn":"অব্যয় (Preposition)"},{"id":11765,"position":17,"text_uthmani":"ٱلْمُؤْمِنِينَ","transliteration":"l-mu''minīna","translation_bn":"মু''মিনদের","root":"امن","lemma":"مُؤْمِن","grammar_bn":"শব্দ"},{"id":11766,"position":18,"text_uthmani":"١٠","transliteration":"","translation_bn":"(১০)","root":"—","lemma":"١٠","grammar_bn":"মার্কার"}]'::jsonb, 'wa-aṣbaḥa fuādu ummi mūsā fārighan in kādat latub''dī bihi lawlā an rabaṭnā ʿalā qalbihā litakūna mina l-mu''minīna', 'মূসার মায়ের অন্তর বিচলিত হয়ে উঠল। সে তো তার পরিচয় প্রকাশ করেই ফেলত যদি না আমি তার চিত্তকে দৃঢ় করতাম যাতে সে আস্থাশীল হয়।', 'And the heart of Moses'' mother became empty [of all else]. She was about to disclose [the matter concerning] him had We not bound fast her heart that she would be of the believers.', 'মূসার মায়ের অন্তর বিচলিত হয়ে উঠল। সে তো তার পরিচয় প্রকাশ করেই ফেলত যদি না আমি তার চিত্তকে দৃঢ় করতাম যাতে সে আস্থাশীল হয়।', 'And the heart of Moses'' mother became empty [of all else]. She was about to disclose [the matter concerning] him had We not bound fast her heart that she would be of the believers.', NULL, NULL, NULL, NULL, NULL, 'https://everyayah.com/data/Alafasy_128kbps/028010.mp3', now()),
  (28, 11, '', '[{"id":13080,"position":1,"text_uthmani":"وَقَالَتْ","transliteration":"waqālat","translation_bn":"এবং (তার মা) বললো","root":"قول","lemma":"قَالَ","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":13081,"position":2,"text_uthmani":"لِأُخْتِهِۦ","transliteration":"li-ukh''tihi","translation_bn":"উদ্দেশ্যে তার বোনের","root":"اخو","lemma":"أُخْت","grammar_bn":"অব্যয় (Preposition)"},{"id":13082,"position":3,"text_uthmani":"قُصِّيهِ ۖ","transliteration":"quṣṣīhi","translation_bn":"\"পিছনে পিছনে যাও তার\"","root":"قصص","lemma":"قَصَّ","grammar_bn":"ক্রিয়া (Verb)"},{"id":13084,"position":4,"text_uthmani":"فَبَصُرَتْ","transliteration":"fabaṣurat","translation_bn":"তাই সে দেখে যেতে থাকলো","root":"بصر","lemma":"بَصُرَتْ","grammar_bn":"শব্দ"},{"id":13085,"position":5,"text_uthmani":"بِهِۦ","transliteration":"bihi","translation_bn":"প্রতি তার","root":"—","lemma":"بِهِۦ","grammar_bn":"অব্যয় (Preposition)"},{"id":13086,"position":6,"text_uthmani":"عَن","transliteration":"ʿan","translation_bn":"হ''তে","root":"—","lemma":"عَن\r","grammar_bn":"অব্যয় (Preposition)"},{"id":13087,"position":7,"text_uthmani":"جُنُبٍۢ","transliteration":"junubin","translation_bn":"দূর","root":"جنب","lemma":"جُنُب","grammar_bn":"বিশেষ্য (Noun)"},{"id":13088,"position":8,"text_uthmani":"وَهُمْ","transliteration":"wahum","translation_bn":"অথচ তারা","root":"—","lemma":"وَهُمْ","grammar_bn":"অবস্থাবাচক (Circumstantial)"},{"id":13089,"position":9,"text_uthmani":"لَا","transliteration":"lā","translation_bn":"না","root":"—","lemma":"لَا\r","grammar_bn":"না-বোধক (Negative)"},{"id":13090,"position":10,"text_uthmani":"يَشْعُرُونَ","transliteration":"yashʿurūna","translation_bn":"টেরও পেলো","root":"شعر","lemma":"يَشْعُرُ","grammar_bn":"ক্রিয়া (Verb)"},{"id":13091,"position":11,"text_uthmani":"١١","transliteration":"","translation_bn":"(১১)","root":"—","lemma":"١١","grammar_bn":"মার্কার"}]'::jsonb, 'waqālat li-ukh''tihi quṣṣīhi fabaṣurat bihi ʿan junubin wahum lā yashʿurūna', 'মূসার মা মূসার বোনকে বলল- ‘তার পিছনে পিছনে যাও।’ সে দূর থেকে তাকে দেখছিল কিন্তু তারা টের পায়নি।', 'And she said to his sister, "Follow him"; so she watched him from a distance while they perceived not.', 'মূসার মা মূসার বোনকে বলল- ‘তার পিছনে পিছনে যাও।’ সে দূর থেকে তাকে দেখছিল কিন্তু তারা টের পায়নি।', 'And she said to his sister, "Follow him"; so she watched him from a distance while they perceived not.', NULL, NULL, NULL, NULL, NULL, 'https://everyayah.com/data/Alafasy_128kbps/028011.mp3', now()),
  (28, 12, '', '[{"id":14351,"position":1,"text_uthmani":"۞ وَحَرَّمْنَا","transliteration":"waḥarramnā","translation_bn":"এবং হারাম করে দিয়েছিলাম আমরা","root":"حرم","lemma":"حَرَّمَ","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":14352,"position":2,"text_uthmani":"عَلَيْهِ","transliteration":"ʿalayhi","translation_bn":"উপর তার","root":"—","lemma":"عَلَىٰ\r","grammar_bn":"অব্যয় (Preposition)"},{"id":14353,"position":3,"text_uthmani":"ٱلْمَرَاضِعَ","transliteration":"l-marāḍiʿa","translation_bn":"স্তন্যদানকারিনীদেরকে","root":"رضع","lemma":"مَرَاضِع","grammar_bn":"শব্দ"},{"id":14354,"position":4,"text_uthmani":"مِن","transliteration":"min","translation_bn":"থেকেই","root":"—","lemma":"مِن\r","grammar_bn":"অব্যয় (Preposition)"},{"id":14355,"position":5,"text_uthmani":"قَبْلُ","transliteration":"qablu","translation_bn":"পূর্ব","root":"قبل","lemma":"قَبْل","grammar_bn":"বিশেষ্য (Noun)"},{"id":14356,"position":6,"text_uthmani":"فَقَالَتْ","transliteration":"faqālat","translation_bn":"অতঃপর বললো (তার বোন)","root":"قول","lemma":"قَالَ","grammar_bn":"শব্দ"},{"id":14357,"position":7,"text_uthmani":"هَلْ","transliteration":"hal","translation_bn":"\"কি","root":"—","lemma":"هَل\r","grammar_bn":"প্রশ্নবোধক (Interrogative)"},{"id":14358,"position":8,"text_uthmani":"أَدُلُّكُمْ","transliteration":"adullukum","translation_bn":"আমি সন্ধান দেবো তোমাদেরকে","root":"دلل","lemma":"دَلَّ","grammar_bn":"ক্রিয়া (Verb)"},{"id":14359,"position":9,"text_uthmani":"عَلَىٰٓ","transliteration":"ʿalā","translation_bn":"সম্বন্ধে","root":"—","lemma":"عَلَىٰ\r","grammar_bn":"অব্যয় (Preposition)"},{"id":14360,"position":10,"text_uthmani":"أَهْلِ","transliteration":"ahli","translation_bn":"বাসিন্দাদের","root":"اهل","lemma":"أَهْل","grammar_bn":"বিশেষ্য (Noun)"},{"id":14361,"position":11,"text_uthmani":"بَيْتٍۢ","transliteration":"baytin","translation_bn":"এক ঘরের","root":"بيت","lemma":"بَيْت","grammar_bn":"বিশেষ্য (Noun)"},{"id":14362,"position":12,"text_uthmani":"يَكْفُلُونَهُۥ","transliteration":"yakfulūnahu","translation_bn":"তারা লালন পালন করবে তাকে","root":"كفل","lemma":"يَكْفُلُ","grammar_bn":"ক্রিয়া (Verb)"},{"id":14363,"position":13,"text_uthmani":"لَكُمْ","transliteration":"lakum","translation_bn":"জন্যে তোমাদের","root":"—","lemma":"لَكُمْ","grammar_bn":"অব্যয় (Preposition)"},{"id":14364,"position":14,"text_uthmani":"وَهُمْ","transliteration":"wahum","translation_bn":"এবং তারা (হবে)","root":"—","lemma":"وَهُمْ","grammar_bn":"অবস্থাবাচক (Circumstantial)"},{"id":14365,"position":15,"text_uthmani":"لَهُۥ","transliteration":"lahu","translation_bn":"জন্যে তার","root":"—","lemma":"لَهُۥ","grammar_bn":"অব্যয় (Preposition)"},{"id":14366,"position":16,"text_uthmani":"نَـٰصِحُونَ","transliteration":"nāṣiḥūna","translation_bn":"কল্যাণকামী\"","root":"نصح","lemma":"نَاصِح","grammar_bn":"বিশেষ্য (Noun)"},{"id":14367,"position":17,"text_uthmani":"١٢","transliteration":"","translation_bn":"(১২)","root":"—","lemma":"١٢","grammar_bn":"মার্কার"}]'::jsonb, 'waḥarramnā ʿalayhi l-marāḍiʿa min qablu faqālat hal adullukum ʿalā ahli baytin yakfulūnahu lakum wahum lahu nāṣiḥūna', 'আগে থেকে আমি তাকে ধাত্রী-স্তন্য পান থেকে বিরত রেখেছিলাম। মূসার বোন বলল- ‘আমি কি তোমাদেরকে এমন একটা পরিবারের খোঁজ দেব যারা তাকে তোমাদের পক্ষে লালন পালন করবে আর তারা হবে তার হিতাকাঙ্ক্ষী।’', 'And We had prevented from him [all] wet nurses before, so she said, "Shall I direct you to a household that will be responsible for him for you while they are to him [for his upbringing] sincere?"', 'আগে থেকে আমি তাকে ধাত্রী-স্তন্য পান থেকে বিরত রেখেছিলাম। মূসার বোন বলল- ‘আমি কি তোমাদেরকে এমন একটা পরিবারের খোঁজ দেব যারা তাকে তোমাদের পক্ষে লালন পালন করবে আর তারা হবে তার হিতাকাঙ্ক্ষী।’', 'And We had prevented from him [all] wet nurses before, so she said, "Shall I direct you to a household that will be responsible for him for you while they are to him [for his upbringing] sincere?"', NULL, NULL, NULL, NULL, NULL, 'https://everyayah.com/data/Alafasy_128kbps/028012.mp3', now()),
  (28, 13, '', '[{"id":15462,"position":1,"text_uthmani":"فَرَدَدْنَـٰهُ","transliteration":"faradadnāhu","translation_bn":"অতঃপর আমরা ফিরিয়ে দিই তাকে","root":"ردد","lemma":"رَدَّ","grammar_bn":"শব্দ"},{"id":15463,"position":2,"text_uthmani":"إِلَىٰٓ","transliteration":"ilā","translation_bn":"নিকট","root":"—","lemma":"إِلَىٰ\r","grammar_bn":"অব্যয় (Preposition)"},{"id":15464,"position":3,"text_uthmani":"أُمِّهِۦ","transliteration":"ummihi","translation_bn":"মায়ের তার","root":"امم","lemma":"أُمّ","grammar_bn":"বিশেষ্য (Noun)"},{"id":15465,"position":4,"text_uthmani":"كَىْ","transliteration":"kay","translation_bn":"যেন","root":"—","lemma":"كَى\r","grammar_bn":"অধীনস্থ যোজক (Subordinating)"},{"id":15466,"position":5,"text_uthmani":"تَقَرَّ","transliteration":"taqarra","translation_bn":"জুড়ায়","root":"قرر","lemma":"تَقَرَّ","grammar_bn":"ক্রিয়া (Verb)"},{"id":15467,"position":6,"text_uthmani":"عَيْنُهَا","transliteration":"ʿaynuhā","translation_bn":"চক্ষু তার","root":"عين","lemma":"عَيْن","grammar_bn":"বিশেষ্য (Noun)"},{"id":15468,"position":7,"text_uthmani":"وَلَا","transliteration":"walā","translation_bn":"এবং না","root":"—","lemma":"لَا\r","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":15469,"position":8,"text_uthmani":"تَحْزَنَ","transliteration":"taḥzana","translation_bn":"দুশ্চিন্তা করে","root":"حزن","lemma":"يَحْزُن","grammar_bn":"ক্রিয়া (Verb)"},{"id":15470,"position":9,"text_uthmani":"وَلِتَعْلَمَ","transliteration":"walitaʿlama","translation_bn":"এবং যেন জানতে পারে","root":"علم","lemma":"عَلِمَ","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":15471,"position":10,"text_uthmani":"أَنَّ","transliteration":"anna","translation_bn":"যে","root":"—","lemma":"أَنّ","grammar_bn":"অভিঘাত পদ (Accusative)"},{"id":15472,"position":11,"text_uthmani":"وَعْدَ","transliteration":"waʿda","translation_bn":"প্রতিশ্রুতি","root":"وعد","lemma":"وَعْد","grammar_bn":"বিশেষ্য (Noun)"},{"id":15473,"position":12,"text_uthmani":"ٱللَّهِ","transliteration":"l-lahi","translation_bn":"আল্লাহর","root":"اله","lemma":"ٱللَّه","grammar_bn":"নামবাচক বিশেষ্য (Proper Noun)"},{"id":15474,"position":13,"text_uthmani":"حَقٌّۭ","transliteration":"ḥaqqun","translation_bn":"সত্য","root":"حقق","lemma":"حَقّ","grammar_bn":"বিশেষ্য (Noun)"},{"id":15475,"position":14,"text_uthmani":"وَلَـٰكِنَّ","transliteration":"walākinna","translation_bn":"কিন্তু","root":"—","lemma":"لَٰكِنّ","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":15476,"position":15,"text_uthmani":"أَكْثَرَهُمْ","transliteration":"aktharahum","translation_bn":"অধিকাংশই তাদের","root":"كثر","lemma":"أَكْثَر","grammar_bn":"বিশেষ্য (Noun)"},{"id":15477,"position":16,"text_uthmani":"لَا","transliteration":"lā","translation_bn":"না","root":"—","lemma":"لَا\r","grammar_bn":"না-বোধক (Negative)"},{"id":15478,"position":17,"text_uthmani":"يَعْلَمُونَ","transliteration":"yaʿlamūna","translation_bn":"জানে","root":"علم","lemma":"عَلِمَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":15479,"position":18,"text_uthmani":"١٣","transliteration":"","translation_bn":"(১৩)","root":"—","lemma":"١٣","grammar_bn":"মার্কার"}]'::jsonb, 'faradadnāhu ilā ummihi kay taqarra ʿaynuhā walā taḥzana walitaʿlama anna waʿda l-lahi ḥaqqun walākinna aktharahum lā yaʿlamūna', 'এভাবে আমি তাকে তার মায়ের কাছে ফিরিয়ে আনলাম যাতে তার চোখ জুড়ায়, সে দুঃখ না করে আর জানতে পারে যে, আল্লাহর ও‘য়াদা সত্য; কিন্তু অধিকাংশ মানুষ তা জানে না।', 'So We restored him to his mother that she might be content and not grieve and that she would know that the promise of Allah is true. But most of the people do not know.', 'এভাবে আমি তাকে তার মায়ের কাছে ফিরিয়ে আনলাম যাতে তার চোখ জুড়ায়, সে দুঃখ না করে আর জানতে পারে যে, আল্লাহর ও‘য়াদা সত্য; কিন্তু অধিকাংশ মানুষ তা জানে না।', 'So We restored him to his mother that she might be content and not grieve and that she would know that the promise of Allah is true. But most of the people do not know.', NULL, NULL, NULL, NULL, NULL, 'https://everyayah.com/data/Alafasy_128kbps/028013.mp3', now()),
  (28, 14, '', '[{"id":16505,"position":1,"text_uthmani":"وَلَمَّا","transliteration":"walammā","translation_bn":"এবং যখন","root":"—","lemma":"لَمَّا\r","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":16506,"position":2,"text_uthmani":"بَلَغَ","transliteration":"balagha","translation_bn":"সে পৌঁছে","root":"بلغ","lemma":"بَلَغَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":16507,"position":3,"text_uthmani":"أَشُدَّهُۥ","transliteration":"ashuddahu","translation_bn":"পূর্ণ যৌবনে তার","root":"شدد","lemma":"أَشُدّ","grammar_bn":"বিশেষ্য (Noun)"},{"id":16508,"position":4,"text_uthmani":"وَٱسْتَوَىٰٓ","transliteration":"wa-is''tawā","translation_bn":"ও পরিণত বয়স্ক হলো","root":"سوي","lemma":"ٱسْتَوَىٰ^","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":16509,"position":5,"text_uthmani":"ءَاتَيْنَـٰهُ","transliteration":"ātaynāhu","translation_bn":"আমরা দান করলাম তাকে","root":"اتي","lemma":"ا^تَى","grammar_bn":"ক্রিয়া (Verb)"},{"id":16510,"position":6,"text_uthmani":"حُكْمًۭا","transliteration":"ḥuk''man","translation_bn":"প্রজ্ঞা","root":"حكم","lemma":"حُكْم","grammar_bn":"বিশেষ্য (Noun)"},{"id":16511,"position":7,"text_uthmani":"وَعِلْمًۭا ۚ","transliteration":"waʿil''man","translation_bn":"ও জ্ঞান","root":"علم","lemma":"عِلْم","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":16513,"position":8,"text_uthmani":"وَكَذَٰلِكَ","transliteration":"wakadhālika","translation_bn":"এবং এভাবে","root":"—","lemma":"ذَٰلِك","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":16514,"position":9,"text_uthmani":"نَجْزِى","transliteration":"najzī","translation_bn":"আমরা পুরস্কার দিই","root":"جزي","lemma":"جَزَىٰ","grammar_bn":"ক্রিয়া (Verb)"},{"id":16515,"position":10,"text_uthmani":"ٱلْمُحْسِنِينَ","transliteration":"l-muḥ''sinīna","translation_bn":"সৎকর্মশীলদেরকে","root":"حسن","lemma":"مُحْسِن","grammar_bn":"শব্দ"},{"id":16516,"position":11,"text_uthmani":"١٤","transliteration":"","translation_bn":"(১৪)","root":"—","lemma":"١٤","grammar_bn":"মার্কার"}]'::jsonb, 'walammā balagha ashuddahu wa-is''tawā ātaynāhu ḥuk''man waʿil''man wakadhālika najzī l-muḥ''sinīna', 'মূসা যখন যৌবনে পদার্পণ করল আর পূর্ণ পরিণত হল, তখন আমি তাকে হিকমত ও জ্ঞান দান করলাম; আমি সৎকর্মশীলদেরকে এভাবেই পুরস্কৃত করে থাকি।', 'And when he attained his full strength and was [mentally] mature, We bestowed upon him judgement and knowledge. And thus do We reward the doers of good.', 'মূসা যখন যৌবনে পদার্পণ করল আর পূর্ণ পরিণত হল, তখন আমি তাকে হিকমত ও জ্ঞান দান করলাম; আমি সৎকর্মশীলদেরকে এভাবেই পুরস্কৃত করে থাকি।', 'And when he attained his full strength and was [mentally] mature, We bestowed upon him judgement and knowledge. And thus do We reward the doers of good.', NULL, NULL, NULL, NULL, NULL, 'https://everyayah.com/data/Alafasy_128kbps/028014.mp3', now()),
