  (29, 1, '', '[{"id":787,"position":1,"text_uthmani":"الٓمٓ","transliteration":"alif-lam-meem","translation_bn":"আলিফ-লাম-মীম","root":"—","lemma":"الٓمٓ","grammar_bn":"শব্দ"},{"id":788,"position":2,"text_uthmani":"١","transliteration":"","translation_bn":"(১)","root":"—","lemma":"١","grammar_bn":"মার্কার"}]'::jsonb, 'alif-lam-meem', 'আলিফ-লাম-মীম', 'Alif, Lam, Meem', 'আলিফ-লাম-মীম', 'Alif, Lam, Meem', NULL, NULL, NULL, NULL, NULL, 'https://everyayah.com/data/Alafasy_128kbps/029001.mp3', now()),
  (29, 2, '', '[{"id":1828,"position":1,"text_uthmani":"أَحَسِبَ","transliteration":"aḥasiba","translation_bn":"কি মনে করেছে","root":"حسب","lemma":"حَسِبَ","grammar_bn":"প্রশ্নবোধক (Interrogative)"},{"id":1829,"position":2,"text_uthmani":"ٱلنَّاسُ","transliteration":"l-nāsu","translation_bn":"মানুষ","root":"نوس","lemma":"نَّاس","grammar_bn":"শব্দ"},{"id":1830,"position":3,"text_uthmani":"أَن","transliteration":"an","translation_bn":"যে","root":"—","lemma":"أَن\r","grammar_bn":"অধীনস্থ যোজক (Subordinating)"},{"id":1831,"position":4,"text_uthmani":"يُتْرَكُوٓا۟","transliteration":"yut''rakū","translation_bn":"তাদেরকে ছেড়ে দেয়া হবে","root":"ترك","lemma":"تَرَكَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":1832,"position":5,"text_uthmani":"أَن","transliteration":"an","translation_bn":"(এ কথায়) যে","root":"—","lemma":"أَن\r","grammar_bn":"অধীনস্থ যোজক (Subordinating)"},{"id":1833,"position":6,"text_uthmani":"يَقُولُوٓا۟","transliteration":"yaqūlū","translation_bn":"তারা বলবে","root":"قول","lemma":"قَالَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":1834,"position":7,"text_uthmani":"ءَامَنَّا","transliteration":"āmannā","translation_bn":"\"ঈমান এনেছি আমরা\"","root":"امن","lemma":"ءَامَنَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":1835,"position":8,"text_uthmani":"وَهُمْ","transliteration":"wahum","translation_bn":"আর তাদেরকে","root":"—","lemma":"وَهُمْ","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":1836,"position":9,"text_uthmani":"لَا","transliteration":"lā","translation_bn":"না","root":"—","lemma":"لَا\r","grammar_bn":"না-বোধক (Negative)"},{"id":1837,"position":10,"text_uthmani":"يُفْتَنُونَ","transliteration":"yuf''tanūna","translation_bn":"পরীক্ষা করা হবে","root":"فتن","lemma":"فَتَنُ","grammar_bn":"ক্রিয়া (Verb)"},{"id":1838,"position":11,"text_uthmani":"٢","transliteration":"","translation_bn":"(২)","root":"—","lemma":"٢","grammar_bn":"মার্কার"}]'::jsonb, 'aḥasiba l-nāsu an yut''rakū an yaqūlū āmannā wahum lā yuf''tanūna', 'লোকেরা কি মনে করে যে ‘আমরা ঈমান এনেছি’ বললেই তাদেরকে অব্যাহতি দিয়ে দেয়া হবে, আর তাদেরকে পরীক্ষা করা হবে না?', 'Do the people think that they will be left to say, "We believe" and they will not be tried?', 'লোকেরা কি মনে করে যে ‘আমরা ঈমান এনেছি’ বললেই তাদেরকে অব্যাহতি দিয়ে দেয়া হবে, আর তাদেরকে পরীক্ষা করা হবে না?', 'Do the people think that they will be left to say, "We believe" and they will not be tried?', NULL, NULL, NULL, NULL, NULL, 'https://everyayah.com/data/Alafasy_128kbps/029002.mp3', now()),
  (29, 3, '', '[{"id":2997,"position":1,"text_uthmani":"وَلَقَدْ","transliteration":"walaqad","translation_bn":"অথচ নিশ্চয়ই","root":"—","lemma":"قَد\r","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":2998,"position":2,"text_uthmani":"فَتَنَّا","transliteration":"fatannā","translation_bn":"পরীক্ষা করেছি আমরা","root":"فتن","lemma":"فَتَنُ","grammar_bn":"ক্রিয়া (Verb)"},{"id":2999,"position":3,"text_uthmani":"ٱلَّذِينَ","transliteration":"alladhīna","translation_bn":"(তাদেরকে) যারা","root":"—","lemma":"ٱلَّذِى","grammar_bn":"সাপেক্ষ সর্বনাম (Relative)"},{"id":3000,"position":4,"text_uthmani":"مِن","transliteration":"min","translation_bn":"থেকে","root":"—","lemma":"مِن\r","grammar_bn":"অব্যয় (Preposition)"},{"id":3001,"position":5,"text_uthmani":"قَبْلِهِمْ ۖ","transliteration":"qablihim","translation_bn":"পূর্ব ছিলো তাদের","root":"قبل","lemma":"قَبْل","grammar_bn":"বিশেষ্য (Noun)"},{"id":3003,"position":6,"text_uthmani":"فَلَيَعْلَمَنَّ","transliteration":"falayaʿlamanna","translation_bn":"অতএব অবশ্যই জেনে নিবেন","root":"علم","lemma":"عَلِمَ","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":3004,"position":7,"text_uthmani":"ٱللَّهُ","transliteration":"l-lahu","translation_bn":"আল্লাহ্","root":"اله","lemma":"ٱللَّه","grammar_bn":"নামবাচক বিশেষ্য (Proper Noun)"},{"id":3005,"position":8,"text_uthmani":"ٱلَّذِينَ","transliteration":"alladhīna","translation_bn":"(তাদেরকে) যারা","root":"—","lemma":"ٱلَّذِى","grammar_bn":"সাপেক্ষ সর্বনাম (Relative)"},{"id":3006,"position":9,"text_uthmani":"صَدَقُوا۟","transliteration":"ṣadaqū","translation_bn":"সত্য বলেছে","root":"صدق","lemma":"صَدَقَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":3007,"position":10,"text_uthmani":"وَلَيَعْلَمَنَّ","transliteration":"walayaʿlamanna","translation_bn":"আর অবশ্যই জেনে নিবেন","root":"علم","lemma":"عَلِمَ","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":3008,"position":11,"text_uthmani":"ٱلْكَـٰذِبِينَ","transliteration":"l-kādhibīna","translation_bn":"মিথ্যাবাদীদেরকে","root":"كذب","lemma":"كَٰذِب","grammar_bn":"শব্দ"},{"id":3009,"position":12,"text_uthmani":"٣","transliteration":"","translation_bn":"(৩)","root":"—","lemma":"٣","grammar_bn":"মার্কার"}]'::jsonb, 'walaqad fatannā alladhīna min qablihim falayaʿlamanna l-lahu alladhīna ṣadaqū walayaʿlamanna l-kādhibīna', 'তাদের পূর্বে যারা ছিল আমি তাদেরকে পরীক্ষা করেছিলাম; অতঃপর আল্লাহ অবশ্য অবশ্যই জেনে নেবেন কারা সত্যবাদী আর কারা মিথ্যেবাদী।', 'But We have certainly tried those before them, and Allah will surely make evident those who are truthful, and He will surely make evident the liars.', 'তাদের পূর্বে যারা ছিল আমি তাদেরকে পরীক্ষা করেছিলাম; অতঃপর আল্লাহ অবশ্য অবশ্যই জেনে নেবেন কারা সত্যবাদী আর কারা মিথ্যেবাদী।', 'But We have certainly tried those before them, and Allah will surely make evident those who are truthful, and He will surely make evident the liars.', NULL, NULL, NULL, NULL, NULL, 'https://everyayah.com/data/Alafasy_128kbps/029003.mp3', now()),
  (29, 4, '', '[{"id":4329,"position":1,"text_uthmani":"أَمْ","transliteration":"am","translation_bn":"কি","root":"—","lemma":"أَم\r","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":4330,"position":2,"text_uthmani":"حَسِبَ","transliteration":"ḥasiba","translation_bn":"মনে করেছে","root":"حسب","lemma":"حَسِبَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":4331,"position":3,"text_uthmani":"ٱلَّذِينَ","transliteration":"alladhīna","translation_bn":"(তারা) যারা","root":"—","lemma":"ٱلَّذِى","grammar_bn":"সাপেক্ষ সর্বনাম (Relative)"},{"id":4332,"position":4,"text_uthmani":"يَعْمَلُونَ","transliteration":"yaʿmalūna","translation_bn":"কাজ করে","root":"عمل","lemma":"عَمِلَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":4333,"position":5,"text_uthmani":"ٱلسَّيِّـَٔاتِ","transliteration":"l-sayiāti","translation_bn":"মন্দ","root":"سوا","lemma":"سَيِّـ#َات","grammar_bn":"শব্দ"},{"id":4334,"position":6,"text_uthmani":"أَن","transliteration":"an","translation_bn":"যে","root":"—","lemma":"أَن\r","grammar_bn":"অধীনস্থ যোজক (Subordinating)"},{"id":4335,"position":7,"text_uthmani":"يَسْبِقُونَا ۚ","transliteration":"yasbiqūnā","translation_bn":"তারা ছাড়িয়ে যাবে অামাদেরকে","root":"سبق","lemma":"سَبَقَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":4337,"position":8,"text_uthmani":"سَآءَ","transliteration":"sāa","translation_bn":"কত খারাপ","root":"سوا","lemma":"سَا^ءَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":4338,"position":9,"text_uthmani":"مَا","transliteration":"mā","translation_bn":"যা","root":"—","lemma":"مَا\r","grammar_bn":"সাপেক্ষ সর্বনাম (Relative)"},{"id":4339,"position":10,"text_uthmani":"يَحْكُمُونَ","transliteration":"yaḥkumūna","translation_bn":"তারা সিদ্ধান্ত নিয়েছে","root":"حكم","lemma":"حَكَمَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":4340,"position":11,"text_uthmani":"٤","transliteration":"","translation_bn":"(৪)","root":"—","lemma":"٤","grammar_bn":"মার্কার"}]'::jsonb, 'am ḥasiba alladhīna yaʿmalūna l-sayiāti an yasbiqūnā sāa mā yaḥkumūna', 'যারা মন্দ কাজ করে তারা কি ভেবে নিয়েছে যে, তারা আমার আগে বেড়ে যাবে? তাদের ফয়সালা বড়ই খারাপ!', 'Or do those who do evil deeds think they can outrun Us? Evil is what they judge.', 'যারা মন্দ কাজ করে তারা কি ভেবে নিয়েছে যে, তারা আমার আগে বেড়ে যাবে? তাদের ফয়সালা বড়ই খারাপ!', 'Or do those who do evil deeds think they can outrun Us? Evil is what they judge.', NULL, NULL, NULL, NULL, NULL, 'https://everyayah.com/data/Alafasy_128kbps/029004.mp3', now()),
  (29, 5, '', '[{"id":5598,"position":1,"text_uthmani":"مَن","transliteration":"man","translation_bn":"যে","root":"—","lemma":"مَن\r","grammar_bn":"সাপেক্ষ সর্বনাম (Relative)"},{"id":5599,"position":2,"text_uthmani":"كَانَ","transliteration":"kāna","translation_bn":"সে হলো","root":"كون","lemma":"كَانَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":5600,"position":3,"text_uthmani":"يَرْجُوا۟","transliteration":"yarjū","translation_bn":"সে কামনা করে","root":"رجو","lemma":"يَرْجُوا@","grammar_bn":"ক্রিয়া (Verb)"},{"id":5601,"position":4,"text_uthmani":"لِقَآءَ","transliteration":"liqāa","translation_bn":"সাক্ষাত","root":"لقي","lemma":"لِقَا^ء","grammar_bn":"বিশেষ্য (Noun)"},{"id":5602,"position":5,"text_uthmani":"ٱللَّهِ","transliteration":"l-lahi","translation_bn":"আল্লাহ্‌র","root":"اله","lemma":"ٱللَّه","grammar_bn":"নামবাচক বিশেষ্য (Proper Noun)"},{"id":5603,"position":6,"text_uthmani":"فَإِنَّ","transliteration":"fa-inna","translation_bn":"(সে জানুক) তবে নিশ্চয়ই","root":"—","lemma":"إِنّ","grammar_bn":"শব্দ"},{"id":5604,"position":7,"text_uthmani":"أَجَلَ","transliteration":"ajala","translation_bn":"নির্ধারিত সময়","root":"اجل","lemma":"أَجَل","grammar_bn":"বিশেষ্য (Noun)"},{"id":5605,"position":8,"text_uthmani":"ٱللَّهِ","transliteration":"l-lahi","translation_bn":"আল্লাহ্‌র","root":"اله","lemma":"ٱللَّه","grammar_bn":"নামবাচক বিশেষ্য (Proper Noun)"},{"id":5606,"position":9,"text_uthmani":"لَـَٔاتٍۢ ۚ","transliteration":"laātin","translation_bn":"অবশ্যই আসবে","root":"اتي","lemma":"ا^تِي","grammar_bn":"দৃঢ়তাবোধক (Emphatic)"},{"id":5608,"position":10,"text_uthmani":"وَهُوَ","transliteration":"wahuwa","translation_bn":"এবং তিনিই","root":"—","lemma":"وَهُوَ","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":5609,"position":11,"text_uthmani":"ٱلسَّمِيعُ","transliteration":"l-samīʿu","translation_bn":"সবকিছু শুনেন","root":"سمع","lemma":"سَمِيع","grammar_bn":"শব্দ"},{"id":5610,"position":12,"text_uthmani":"ٱلْعَلِيمُ","transliteration":"l-ʿalīmu","translation_bn":"সবকিছু জানেন","root":"علم","lemma":"عَلِيم","grammar_bn":"শব্দ"},{"id":5611,"position":13,"text_uthmani":"٥","transliteration":"","translation_bn":"(৫)","root":"—","lemma":"٥","grammar_bn":"মার্কার"}]'::jsonb, 'man kāna yarjū liqāa l-lahi fa-inna ajala l-lahi laātin wahuwa l-samīʿu l-ʿalīmu', 'যে ব্যক্তি আল্লাহর সাক্ষাতের আকাঙ্ক্ষা করে (সে জেনে রাখুক যে) আল্লাহর নির্ধারিত কাল অবশ্যই আসবে, তিনি সব কিছু শোনেন, সব কিছু জানেন।', 'Whoever should hope for the meeting with Allah - indeed, the term decreed by Allah is coming. And He is the Hearing, the Knowing.', 'যে ব্যক্তি আল্লাহর সাক্ষাতের আকাঙ্ক্ষা করে (সে জেনে রাখুক যে) আল্লাহর নির্ধারিত কাল অবশ্যই আসবে, তিনি সব কিছু শোনেন, সব কিছু জানেন।', 'Whoever should hope for the meeting with Allah - indeed, the term decreed by Allah is coming. And He is the Hearing, the Knowing.', NULL, NULL, NULL, NULL, NULL, 'https://everyayah.com/data/Alafasy_128kbps/029005.mp3', now()),
  (29, 6, '', '[{"id":6880,"position":1,"text_uthmani":"وَمَن","transliteration":"waman","translation_bn":"এবং যে","root":"—","lemma":"مَن\r","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":6881,"position":2,"text_uthmani":"جَـٰهَدَ","transliteration":"jāhada","translation_bn":"জিহাদ (সংগ্রাম সাধনা) করে","root":"جهد","lemma":"جَٰهَدَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":6882,"position":3,"text_uthmani":"فَإِنَّمَا","transliteration":"fa-innamā","translation_bn":"তবে শুধুমাত্র","root":"—","lemma":"إِنّ","grammar_bn":"শব্দ"},{"id":6883,"position":4,"text_uthmani":"يُجَـٰهِدُ","transliteration":"yujāhidu","translation_bn":"সে জিহাদ (সংগ্রাম সাধনা)করে","root":"جهد","lemma":"جَٰهَدَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":6884,"position":5,"text_uthmani":"لِنَفْسِهِۦٓ ۚ","transliteration":"linafsihi","translation_bn":"জন্যে নিজের তার","root":"نفس","lemma":"نَفْس","grammar_bn":"অব্যয় (Preposition)"},{"id":6886,"position":6,"text_uthmani":"إِنَّ","transliteration":"inna","translation_bn":"নিশ্চয়ই","root":"—","lemma":"إِنّ","grammar_bn":"অভিঘাত পদ (Accusative)"},{"id":6887,"position":7,"text_uthmani":"ٱللَّهَ","transliteration":"l-laha","translation_bn":"আল্লাহ্‌","root":"اله","lemma":"ٱللَّه","grammar_bn":"নামবাচক বিশেষ্য (Proper Noun)"},{"id":6888,"position":8,"text_uthmani":"لَغَنِىٌّ","transliteration":"laghaniyyun","translation_bn":"অবশ্যই অমুখাপেক্ষী","root":"غني","lemma":"غَنِىّ","grammar_bn":"দৃঢ়তাবোধক (Emphatic)"},{"id":6889,"position":9,"text_uthmani":"عَنِ","transliteration":"ʿani","translation_bn":"হ''তে","root":"—","lemma":"عَن\r","grammar_bn":"অব্যয় (Preposition)"},{"id":6890,"position":10,"text_uthmani":"ٱلْعَـٰلَمِينَ","transliteration":"l-ʿālamīna","translation_bn":"বিশ্ববাসী","root":"علم","lemma":"عَٰلَمِين","grammar_bn":"শব্দ"},{"id":6891,"position":11,"text_uthmani":"٦","transliteration":"","translation_bn":"(৬)","root":"—","lemma":"٦","grammar_bn":"মার্কার"}]'::jsonb, 'waman jāhada fa-innamā yujāhidu linafsihi inna l-laha laghaniyyun ʿani l-ʿālamīna', 'যে লোক (আল্লাহর পথে) সর্বাত্মক প্রচেষ্টা চালায়, সে তার নিজের কল্যাণেই প্রচেষ্টা চালায়, আল্লাহ সৃষ্টিজগত থেকে অবশ্যই বে-পরওয়া।', 'And whoever strives only strives for [the benefit of] himself. Indeed, Allah is free from need of the worlds.', 'যে লোক (আল্লাহর পথে) সর্বাত্মক প্রচেষ্টা চালায়, সে তার নিজের কল্যাণেই প্রচেষ্টা চালায়, আল্লাহ সৃষ্টিজগত থেকে অবশ্যই বে-পরওয়া।', 'And whoever strives only strives for [the benefit of] himself. Indeed, Allah is free from need of the worlds.', NULL, NULL, NULL, NULL, NULL, 'https://everyayah.com/data/Alafasy_128kbps/029006.mp3', now()),
  (29, 7, '', '[{"id":8209,"position":1,"text_uthmani":"وَٱلَّذِينَ","transliteration":"wa-alladhīna","translation_bn":"এবং যারা","root":"—","lemma":"ٱلَّذِى","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":8210,"position":2,"text_uthmani":"ءَامَنُوا۟","transliteration":"āmanū","translation_bn":"ঈমান আনে","root":"امن","lemma":"ءَامَنَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":8211,"position":3,"text_uthmani":"وَعَمِلُوا۟","transliteration":"waʿamilū","translation_bn":"ও কাজ করে","root":"عمل","lemma":"عَمِلَ","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":8212,"position":4,"text_uthmani":"ٱلصَّـٰلِحَـٰتِ","transliteration":"l-ṣāliḥāti","translation_bn":"সৎ","root":"صلح","lemma":"صَّٰلِحَٰت","grammar_bn":"শব্দ"},{"id":8213,"position":5,"text_uthmani":"لَنُكَفِّرَنَّ","transliteration":"lanukaffiranna","translation_bn":"অবশ্যই মিটিয়ে দিবো আমরা","root":"كفر","lemma":"كَفَّرَ","grammar_bn":"দৃঢ়তাবোধক (Emphatic)"},{"id":8214,"position":6,"text_uthmani":"عَنْهُمْ","transliteration":"ʿanhum","translation_bn":"তাদের হ''তে তাদের","root":"—","lemma":"عَن\r","grammar_bn":"অব্যয় (Preposition)"},{"id":8215,"position":7,"text_uthmani":"سَيِّـَٔاتِهِمْ","transliteration":"sayyiātihim","translation_bn":"দোষগুলো তাদের","root":"سوا","lemma":"سَيِّـ#َات","grammar_bn":"বিশেষ্য (Noun)"},{"id":8216,"position":8,"text_uthmani":"وَلَنَجْزِيَنَّهُمْ","transliteration":"walanajziyannahum","translation_bn":"এবং অবশ্যই আমরা প্রতিফল দিবো তাদেরকে","root":"جزي","lemma":"جَزَىٰ","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":8217,"position":9,"text_uthmani":"أَحْسَنَ","transliteration":"aḥsana","translation_bn":"অতি উত্তম","root":"حسن","lemma":"أَحْسَن","grammar_bn":"বিশেষ্য (Noun)"},{"id":8218,"position":10,"text_uthmani":"ٱلَّذِى","transliteration":"alladhī","translation_bn":"(বদলে) যা","root":"—","lemma":"ٱلَّذِى","grammar_bn":"সাপেক্ষ সর্বনাম (Relative)"},{"id":8219,"position":11,"text_uthmani":"كَانُوا۟","transliteration":"kānū","translation_bn":"তারা ছিলো","root":"كون","lemma":"كَانَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":8220,"position":12,"text_uthmani":"يَعْمَلُونَ","transliteration":"yaʿmalūna","translation_bn":"তারা কাজ করে","root":"عمل","lemma":"عَمِلَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":8221,"position":13,"text_uthmani":"٧","transliteration":"","translation_bn":"(৭)","root":"—","lemma":"٧","grammar_bn":"মার্কার"}]'::jsonb, 'wa-alladhīna āmanū waʿamilū l-ṣāliḥāti lanukaffiranna ʿanhum sayyiātihim walanajziyannahum aḥsana alladhī kānū yaʿmalūna', 'আর যারা ঈমান আনে আর সৎ কাজ করে, আমি অবশ্য অবশ্যই তাদের মন্দ কাজগুলোকে মুছে দেব, আর তাদেরকে অবশ্য অবশ্যই প্রতিদান দেব তাদের উৎকৃষ্ট কাজগুলোর অনুপাতে যা তারা করত।', 'And those who believe and do righteous deeds - We will surely remove from them their misdeeds and will surely reward them according to the best of what they used to do.', 'আর যারা ঈমান আনে আর সৎ কাজ করে, আমি অবশ্য অবশ্যই তাদের মন্দ কাজগুলোকে মুছে দেব, আর তাদেরকে অবশ্য অবশ্যই প্রতিদান দেব তাদের উৎকৃষ্ট কাজগুলোর অনুপাতে যা তারা করত।', 'And those who believe and do righteous deeds - We will surely remove from them their misdeeds and will surely reward them according to the best of what they used to do.', NULL, NULL, NULL, NULL, NULL, 'https://everyayah.com/data/Alafasy_128kbps/029007.mp3', now()),
  (29, 8, '', '[{"id":9361,"position":1,"text_uthmani":"وَوَصَّيْنَا","transliteration":"wawaṣṣaynā","translation_bn":"এবং জোর নির্দেশ দিয়েছি আমরা","root":"وصي","lemma":"وَصَّىٰ","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":9362,"position":2,"text_uthmani":"ٱلْإِنسَـٰنَ","transliteration":"l-insāna","translation_bn":"মানুষকে","root":"انس","lemma":"إِنسَٰن","grammar_bn":"শব্দ"},{"id":9363,"position":3,"text_uthmani":"بِوَٰلِدَيْهِ","transliteration":"biwālidayhi","translation_bn":"কাছে তার পিতা-মাতার প্রতি","root":"ولد","lemma":"وَٰلِدَي","grammar_bn":"অব্যয় (Preposition)"},{"id":9364,"position":4,"text_uthmani":"حُسْنًۭا ۖ","transliteration":"ḥus''nan","translation_bn":"উত্তম (ব্যবহারের)","root":"حسن","lemma":"حُسْن","grammar_bn":"বিশেষ্য (Noun)"},{"id":9366,"position":5,"text_uthmani":"وَإِن","transliteration":"wa-in","translation_bn":"কিন্তু যদি","root":"—","lemma":"إِن\r","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":9367,"position":6,"text_uthmani":"جَـٰهَدَاكَ","transliteration":"jāhadāka","translation_bn":"তোমাকে দু''জনে চাপ দেয়","root":"جهد","lemma":"جَٰهَدَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":9368,"position":7,"text_uthmani":"لِتُشْرِكَ","transliteration":"litush''rika","translation_bn":"যেন তুমি শিরক করো","root":"شرك","lemma":"أَشْرَكَ","grammar_bn":"শব্দ"},{"id":9369,"position":8,"text_uthmani":"بِى","transliteration":"bī","translation_bn":"সাথে আমার","root":"—","lemma":"بِى","grammar_bn":"অব্যয় (Preposition)"},{"id":9370,"position":9,"text_uthmani":"مَا","transliteration":"mā","translation_bn":"যার","root":"—","lemma":"مَا\r","grammar_bn":"সাপেক্ষ সর্বনাম (Relative)"},{"id":9371,"position":10,"text_uthmani":"لَيْسَ","transliteration":"laysa","translation_bn":"নেই","root":"ليس","lemma":"لَّيْسَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":9372,"position":11,"text_uthmani":"لَكَ","transliteration":"laka","translation_bn":"তোমার","root":"—","lemma":"لَكَ","grammar_bn":"অব্যয় (Preposition)"},{"id":9373,"position":12,"text_uthmani":"بِهِۦ","transliteration":"bihi","translation_bn":"সম্পর্কে সে","root":"—","lemma":"بِهِۦ","grammar_bn":"অব্যয় (Preposition)"},{"id":9374,"position":13,"text_uthmani":"عِلْمٌۭ","transliteration":"ʿil''mun","translation_bn":"কোনো জ্ঞান","root":"علم","lemma":"عِلْم","grammar_bn":"বিশেষ্য (Noun)"},{"id":9375,"position":14,"text_uthmani":"فَلَا","transliteration":"falā","translation_bn":"তাহ''লে না","root":"—","lemma":"لَا\r","grammar_bn":"শব্দ"},{"id":9376,"position":15,"text_uthmani":"تُطِعْهُمَآ ۚ","transliteration":"tuṭiʿ''humā","translation_bn":"অনুগত্য করো তাদের দু''য়ের","root":"طوع","lemma":"أَطَاعَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":9378,"position":16,"text_uthmani":"إِلَىَّ","transliteration":"ilayya","translation_bn":"দিকে আমারই","root":"—","lemma":"إِلَىٰ\r","grammar_bn":"অব্যয় (Preposition)"},{"id":9379,"position":17,"text_uthmani":"مَرْجِعُكُمْ","transliteration":"marjiʿukum","translation_bn":"প্রত্যাবর্তন তোমাদের (হবে)","root":"رجع","lemma":"مَرْجِع","grammar_bn":"বিশেষ্য (Noun)"},{"id":9380,"position":18,"text_uthmani":"فَأُنَبِّئُكُم","transliteration":"fa-unabbi-ukum","translation_bn":"তখন আমি জানিয়ে দিবো তোমাদেরকে","root":"نبا","lemma":"نَبَّأَ","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":9381,"position":19,"text_uthmani":"بِمَا","transliteration":"bimā","translation_bn":"ঐ বিষয়ে যা","root":"—","lemma":"مَا\r","grammar_bn":"অব্যয় (Preposition)"},{"id":9382,"position":20,"text_uthmani":"كُنتُمْ","transliteration":"kuntum","translation_bn":"তোমরা ছিলে","root":"كون","lemma":"كَانَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":9383,"position":21,"text_uthmani":"تَعْمَلُونَ","transliteration":"taʿmalūna","translation_bn":"তোমরা কাজ করে","root":"عمل","lemma":"عَمِلَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":9384,"position":22,"text_uthmani":"٨","transliteration":"","translation_bn":"(৮)","root":"—","lemma":"٨","grammar_bn":"মার্কার"}]'::jsonb, 'wawaṣṣaynā l-insāna biwālidayhi ḥus''nan wa-in jāhadāka litush''rika bī mā laysa laka bihi ʿil''mun falā tuṭiʿ''humā ilayya marjiʿukum fa-unabbi-ukum bimā kuntum taʿmalūna', 'পিতা-মাতার প্রতি সদ্ব্যবহার করার জন্য আমি মানুষের প্রতি ফরমান জারি করেছি। তারা যদি তোমার উপর বলপ্রয়োগ করে আমার সঙ্গে শরীক করার জন্য এমন কিছুকে যে সম্পর্কে তোমার কোন জ্ঞান নেই, তাহলে তুমি তাদেরকে মান্য কর না। আমার কাছেই তোমাদের প্রত্যাবর্তন, অতঃপর আমি তোমাদেরকে জানিয়ে দেব যা তোমরা করছিলে।', 'And We have enjoined upon man goodness to parents. But if they endeavor to make you associate with Me that of which you have no knowledge, do not obey them. To Me is your return, and I will inform you about what you used to do.', 'পিতা-মাতার প্রতি সদ্ব্যবহার করার জন্য আমি মানুষের প্রতি ফরমান জারি করেছি। তারা যদি তোমার উপর বলপ্রয়োগ করে আমার সঙ্গে শরীক করার জন্য এমন কিছুকে যে সম্পর্কে তোমার কোন জ্ঞান নেই, তাহলে তুমি তাদেরকে মান্য কর না। আমার কাছেই তোমাদের প্রত্যাবর্তন, অতঃপর আমি তোমাদেরকে জানিয়ে দেব যা তোমরা করছিলে।', 'And We have enjoined upon man goodness to parents. But if they endeavor to make you associate with Me that of which you have no knowledge, do not obey them. To Me is your return, and I will inform you about what you used to do.', NULL, NULL, NULL, NULL, NULL, 'https://everyayah.com/data/Alafasy_128kbps/029008.mp3', now()),
  (29, 9, '', '[{"id":10532,"position":1,"text_uthmani":"وَٱلَّذِينَ","transliteration":"wa-alladhīna","translation_bn":"এবং যারা","root":"—","lemma":"ٱلَّذِى","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":10533,"position":2,"text_uthmani":"ءَامَنُوا۟","transliteration":"āmanū","translation_bn":"ঈমান এনেছে","root":"امن","lemma":"ءَامَنَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":10534,"position":3,"text_uthmani":"وَعَمِلُوا۟","transliteration":"waʿamilū","translation_bn":"ও কাজ করেছে","root":"عمل","lemma":"عَمِلَ","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":10535,"position":4,"text_uthmani":"ٱلصَّـٰلِحَـٰتِ","transliteration":"l-ṣāliḥāti","translation_bn":"সৎ","root":"صلح","lemma":"صَّٰلِحَٰت","grammar_bn":"শব্দ"},{"id":10536,"position":5,"text_uthmani":"لَنُدْخِلَنَّهُمْ","transliteration":"lanud''khilannahum","translation_bn":"অবশ্যই আমরা প্রবেশ করবো তাদেরকে","root":"دخل","lemma":"أُدْخِلَ","grammar_bn":"দৃঢ়তাবোধক (Emphatic)"},{"id":10537,"position":6,"text_uthmani":"فِى","transliteration":"fī","translation_bn":"মধ্যে","root":"—","lemma":"فِى\r","grammar_bn":"অব্যয় (Preposition)"},{"id":10538,"position":7,"text_uthmani":"ٱلصَّـٰلِحِينَ","transliteration":"l-ṣāliḥīna","translation_bn":"সৎকর্মশীলদের","root":"صلح","lemma":"صَٰلِح","grammar_bn":"শব্দ"},{"id":10539,"position":8,"text_uthmani":"٩","transliteration":"","translation_bn":"(৯)","root":"—","lemma":"٩","grammar_bn":"মার্কার"}]'::jsonb, 'wa-alladhīna āmanū waʿamilū l-ṣāliḥāti lanud''khilannahum fī l-ṣāliḥīna', 'যারা ঈমান আনে ও সৎকাজ করে আমি অবশ্য অবশ্যই তাদেরকে সৎকর্মশীলদের অন্তর্ভুক্ত করব।', 'And those who believe and do righteous deeds - We will surely admit them among the righteous [into Paradise].', 'যারা ঈমান আনে ও সৎকাজ করে আমি অবশ্য অবশ্যই তাদেরকে সৎকর্মশীলদের অন্তর্ভুক্ত করব।', 'And those who believe and do righteous deeds - We will surely admit them among the righteous [into Paradise].', NULL, NULL, NULL, NULL, NULL, 'https://everyayah.com/data/Alafasy_128kbps/029009.mp3', now()),
  (29, 10, '', '[{"id":11784,"position":1,"text_uthmani":"وَمِنَ","transliteration":"wamina","translation_bn":"এবং মধ্যে","root":"—","lemma":"مِن\r","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":11785,"position":2,"text_uthmani":"ٱلنَّاسِ","transliteration":"l-nāsi","translation_bn":"মানুষের","root":"نوس","lemma":"نَّاس","grammar_bn":"শব্দ"},{"id":11786,"position":3,"text_uthmani":"مَن","transliteration":"man","translation_bn":"কেউ কেউ","root":"—","lemma":"مَن\r","grammar_bn":"সাপেক্ষ সর্বনাম (Relative)"},{"id":11787,"position":4,"text_uthmani":"يَقُولُ","transliteration":"yaqūlu","translation_bn":"বলে","root":"قول","lemma":"قَالَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":11788,"position":5,"text_uthmani":"ءَامَنَّا","transliteration":"āmannā","translation_bn":"\"ঈমান এনেছি আমরা","root":"امن","lemma":"ءَامَنَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":11789,"position":6,"text_uthmani":"بِٱللَّهِ","transliteration":"bil-lahi","translation_bn":"প্রতি আল্লাহ্‌র\"","root":"اله","lemma":"ٱللَّه","grammar_bn":"অব্যয় (Preposition)"},{"id":11790,"position":7,"text_uthmani":"فَإِذَآ","transliteration":"fa-idhā","translation_bn":"অতঃপর যখন","root":"—","lemma":"إِذَا\r","grammar_bn":"শব্দ"},{"id":11791,"position":8,"text_uthmani":"أُوذِىَ","transliteration":"ūdhiya","translation_bn":"তারা নির্যাতিত হয়","root":"اذي","lemma":"أُوذِىَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":11792,"position":9,"text_uthmani":"فِى","transliteration":"fī","translation_bn":"পথে","root":"—","lemma":"فِى\r","grammar_bn":"অব্যয় (Preposition)"},{"id":11793,"position":10,"text_uthmani":"ٱللَّهِ","transliteration":"l-lahi","translation_bn":"আল্লাহ্‌র","root":"اله","lemma":"ٱللَّه","grammar_bn":"নামবাচক বিশেষ্য (Proper Noun)"},{"id":11794,"position":11,"text_uthmani":"جَعَلَ","transliteration":"jaʿala","translation_bn":"গণ্য করে","root":"جعل","lemma":"جَعَلَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":11795,"position":12,"text_uthmani":"فِتْنَةَ","transliteration":"fit''nata","translation_bn":"পীড়নকে","root":"فتن","lemma":"فِتْنَة","grammar_bn":"বিশেষ্য (Noun)"},{"id":11796,"position":13,"text_uthmani":"ٱلنَّاسِ","transliteration":"l-nāsi","translation_bn":"মানুষের","root":"نوس","lemma":"نَّاس","grammar_bn":"শব্দ"},{"id":11797,"position":14,"text_uthmani":"كَعَذَابِ","transliteration":"kaʿadhābi","translation_bn":"শাস্তির মতো","root":"عذب","lemma":"عَذَاب","grammar_bn":"অব্যয় (Preposition)"},{"id":11798,"position":15,"text_uthmani":"ٱللَّهِ","transliteration":"l-lahi","translation_bn":"আল্লাহ্‌র","root":"اله","lemma":"ٱللَّه","grammar_bn":"নামবাচক বিশেষ্য (Proper Noun)"},{"id":11799,"position":16,"text_uthmani":"وَلَئِن","transliteration":"wala-in","translation_bn":"এবং অবশ্যই যদি","root":"—","lemma":"إِن\r","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":11800,"position":17,"text_uthmani":"جَآءَ","transliteration":"jāa","translation_bn":"আসে","root":"جيا","lemma":"جَا^ءَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":11801,"position":18,"text_uthmani":"نَصْرٌۭ","transliteration":"naṣrun","translation_bn":"কোনো সাহায্য","root":"نصر","lemma":"نَصْر","grammar_bn":"বিশেষ্য (Noun)"},{"id":11802,"position":19,"text_uthmani":"مِّن","transliteration":"min","translation_bn":"পক্ষ হ''তে","root":"—","lemma":"مِن\r","grammar_bn":"অব্যয় (Preposition)"},{"id":11803,"position":20,"text_uthmani":"رَّبِّكَ","transliteration":"rabbika","translation_bn":"তোমার রবের","root":"ربب","lemma":"رَبّ","grammar_bn":"বিশেষ্য (Noun)"},{"id":11804,"position":21,"text_uthmani":"لَيَقُولُنَّ","transliteration":"layaqūlunna","translation_bn":"অবশ্যই তারা বলবেই","root":"قول","lemma":"قَالَ","grammar_bn":"দৃঢ়তাবোধক (Emphatic)"},{"id":11805,"position":22,"text_uthmani":"إِنَّا","transliteration":"innā","translation_bn":"\"নিশ্চয়ই আমরা","root":"—","lemma":"إِنّ","grammar_bn":"অভিঘাত পদ (Accusative)"},{"id":11806,"position":23,"text_uthmani":"كُنَّا","transliteration":"kunnā","translation_bn":"আমরা ছিলাম","root":"كون","lemma":"كَانَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":11807,"position":24,"text_uthmani":"مَعَكُمْ ۚ","transliteration":"maʿakum","translation_bn":"সাথে তোমাদের\"","root":"—","lemma":"مَع","grammar_bn":"স্থানবাচক (Location)"},{"id":11809,"position":25,"text_uthmani":"أَوَلَيْسَ","transliteration":"awalaysa","translation_bn":"কি নন","root":"ليس","lemma":"لَّيْسَ","grammar_bn":"প্রশ্নবোধক (Interrogative)"},{"id":11810,"position":26,"text_uthmani":"ٱللَّهُ","transliteration":"l-lahu","translation_bn":"আল্লাহ্‌","root":"اله","lemma":"ٱللَّه","grammar_bn":"নামবাচক বিশেষ্য (Proper Noun)"},{"id":11811,"position":27,"text_uthmani":"بِأَعْلَمَ","transliteration":"bi-aʿlama","translation_bn":"খুব অবহিত","root":"علم","lemma":"أَعْلَم","grammar_bn":"অব্যয় (Preposition)"},{"id":11812,"position":28,"text_uthmani":"بِمَا","transliteration":"bimā","translation_bn":"ঐ বিষয়ে যা","root":"—","lemma":"مَا\r","grammar_bn":"অব্যয় (Preposition)"},{"id":11813,"position":29,"text_uthmani":"فِى","transliteration":"fī","translation_bn":"মধ্যে (আছে)","root":"—","lemma":"فِى\r","grammar_bn":"অব্যয় (Preposition)"},{"id":11814,"position":30,"text_uthmani":"صُدُورِ","transliteration":"ṣudūri","translation_bn":"অন্তরসমূহের","root":"صدر","lemma":"صَدْر","grammar_bn":"বিশেষ্য (Noun)"},{"id":11815,"position":31,"text_uthmani":"ٱلْعَـٰلَمِينَ","transliteration":"l-ʿālamīna","translation_bn":"বিশ্ববাসীর","root":"علم","lemma":"عَٰلَمِين","grammar_bn":"শব্দ"},{"id":11816,"position":32,"text_uthmani":"١٠","transliteration":"","translation_bn":"(১০)","root":"—","lemma":"١٠","grammar_bn":"মার্কার"}]'::jsonb, 'wamina l-nāsi man yaqūlu āmannā bil-lahi fa-idhā ūdhiya fī l-lahi jaʿala fit''nata l-nāsi kaʿadhābi l-lahi wala-in jāa naṣrun min rabbika layaqūlunna innā kunnā maʿakum awalaysa l-lahu bi-aʿlama bimā fī ṣudūri l-ʿālamīna', 'মানুষের মধ্যে কতক আছে যারা বলে ‘আমরা আল্লাহর প্রতি ঈমান এনেছি।’ অতঃপর তাদেরকে যখন আল্লাহর পথে কষ্ট দেয়া হয়, তখন তারা মানুষের উৎপীড়নকে আল্লাহর ‘আযাবের মত মনে করে। আর যদি (তোমার কাছে) তোমার প্রতিপালকের পক্ষ থেকে সাহায্য আসে তখন তারা অবশ্য অবশ্যই বলে যে, ‘আমরা তো (সব সময়) তোমাদের সাথেই ছিলাম। সকল সৃষ্টির অন্তরে কী আছে সে সম্পর্কে আল্লাহ কি সর্বাধিক অবগত নন?', 'And of the people are some who say, "We believe in Allah," but when one [of them] is harmed for [the cause of] Allah, they consider the trial of the people as [if it were] the punishment of Allah. But if victory comes from your Lord, they say, "Indeed, We were with you." Is not Allah most knowing of what is within the breasts of all creatures?', 'মানুষের মধ্যে কতক আছে যারা বলে ‘আমরা আল্লাহর প্রতি ঈমান এনেছি।’ অতঃপর তাদেরকে যখন আল্লাহর পথে কষ্ট দেয়া হয়, তখন তারা মানুষের উৎপীড়নকে আল্লাহর ‘আযাবের মত মনে করে। আর যদি (তোমার কাছে) তোমার প্রতিপালকের পক্ষ থেকে সাহায্য আসে তখন তারা অবশ্য অবশ্যই বলে যে, ‘আমরা তো (সব সময়) তোমাদের সাথেই ছিলাম। সকল সৃষ্টির অন্তরে কী আছে সে সম্পর্কে আল্লাহ কি সর্বাধিক অবগত নন?', 'And of the people are some who say, "We believe in Allah," but when one [of them] is harmed for [the cause of] Allah, they consider the trial of the people as [if it were] the punishment of Allah. But if victory comes from your Lord, they say, "Indeed, We were with you." Is not Allah most knowing of what is within the breasts of all creatures?', NULL, NULL, NULL, NULL, NULL, 'https://everyayah.com/data/Alafasy_128kbps/029010.mp3', now()),
  (29, 11, '', '[{"id":13115,"position":1,"text_uthmani":"وَلَيَعْلَمَنَّ","transliteration":"walayaʿlamanna","translation_bn":"এবং অবশ্যই জেনে নিবেন","root":"علم","lemma":"عَلِمَ","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":13116,"position":2,"text_uthmani":"ٱللَّهُ","transliteration":"l-lahu","translation_bn":"আল্লাহ্‌ (বাস্তব ময়দানে)","root":"اله","lemma":"ٱللَّه","grammar_bn":"নামবাচক বিশেষ্য (Proper Noun)"},{"id":13117,"position":3,"text_uthmani":"ٱلَّذِينَ","transliteration":"alladhīna","translation_bn":"(তাদেরকে) যারা","root":"—","lemma":"ٱلَّذِى","grammar_bn":"সাপেক্ষ সর্বনাম (Relative)"},{"id":13118,"position":4,"text_uthmani":"ءَامَنُوا۟","transliteration":"āmanū","translation_bn":"ঈমান এনেছে","root":"امن","lemma":"ءَامَنَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":13119,"position":5,"text_uthmani":"وَلَيَعْلَمَنَّ","transliteration":"walayaʿlamanna","translation_bn":"এবং অবশ্যই (বাস্তবে) জেনে নিবেন","root":"علم","lemma":"عَلِمَ","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":13120,"position":6,"text_uthmani":"ٱلْمُنَـٰفِقِينَ","transliteration":"l-munāfiqīna","translation_bn":"মুনাফিকদেরকে","root":"نفق","lemma":"مُنَٰفِقُون","grammar_bn":"শব্দ"},{"id":13121,"position":7,"text_uthmani":"١١","transliteration":"","translation_bn":"(১১)","root":"—","lemma":"١١","grammar_bn":"মার্কার"}]'::jsonb, 'walayaʿlamanna l-lahu alladhīna āmanū walayaʿlamanna l-munāfiqīna', 'আল্লাহ অবশ্য অবশ্যই জেনে নেবেন কারা ঈমান এনেছে আর অবশ্য অবশ্যই জেনে নেবেন কারা মুনাফিক।', 'And Allah will surely make evident those who believe, and He will surely make evident the hypocrites.', 'আল্লাহ অবশ্য অবশ্যই জেনে নেবেন কারা ঈমান এনেছে আর অবশ্য অবশ্যই জেনে নেবেন কারা মুনাফিক।', 'And Allah will surely make evident those who believe, and He will surely make evident the hypocrites.', NULL, NULL, NULL, NULL, NULL, 'https://everyayah.com/data/Alafasy_128kbps/029011.mp3', now()),
  (29, 12, '', '[{"id":14407,"position":1,"text_uthmani":"وَقَالَ","transliteration":"waqāla","translation_bn":"এবং বলে","root":"قول","lemma":"قَالَ","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":14408,"position":2,"text_uthmani":"ٱلَّذِينَ","transliteration":"alladhīna","translation_bn":"যারা","root":"—","lemma":"ٱلَّذِى","grammar_bn":"সাপেক্ষ সর্বনাম (Relative)"},{"id":14409,"position":3,"text_uthmani":"كَفَرُوا۟","transliteration":"kafarū","translation_bn":"অস্বীকার করেছে","root":"كفر","lemma":"كَفَرَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":14410,"position":4,"text_uthmani":"لِلَّذِينَ","transliteration":"lilladhīna","translation_bn":"(তাদের)-কে যারা","root":"—","lemma":"ٱلَّذِى","grammar_bn":"অব্যয় (Preposition)"},{"id":14411,"position":5,"text_uthmani":"ءَامَنُوا۟","transliteration":"āmanū","translation_bn":"ঈমান এনেছে","root":"امن","lemma":"ءَامَنَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":14412,"position":6,"text_uthmani":"ٱتَّبِعُوا۟","transliteration":"ittabiʿū","translation_bn":"\"তোমরা অনুসরণ করো","root":"تبع","lemma":"ٱتَّبَعَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":14413,"position":7,"text_uthmani":"سَبِيلَنَا","transliteration":"sabīlanā","translation_bn":"পথকে আমাদের","root":"سبل","lemma":"سَبِيل","grammar_bn":"বিশেষ্য (Noun)"},{"id":14414,"position":8,"text_uthmani":"وَلْنَحْمِلْ","transliteration":"walnaḥmil","translation_bn":"আর অবশ্যই আমরা বহন করবো","root":"حمل","lemma":"حَمَلَ","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":14415,"position":9,"text_uthmani":"خَطَـٰيَـٰكُمْ","transliteration":"khaṭāyākum","translation_bn":"ত্রুটিগুলোর (পাপরাশিকে)তোমাদের\"","root":"خطا","lemma":"خَطِي^ـ#َة","grammar_bn":"বিশেষ্য (Noun)"},{"id":14416,"position":10,"text_uthmani":"وَمَا","transliteration":"wamā","translation_bn":"কিন্তু না","root":"—","lemma":"مَا\r","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":14417,"position":11,"text_uthmani":"هُم","transliteration":"hum","translation_bn":"তারা","root":"—","lemma":"هُم","grammar_bn":"সর্বনাম (Pronoun)"},{"id":14418,"position":12,"text_uthmani":"بِحَـٰمِلِينَ","transliteration":"biḥāmilīna","translation_bn":"বহনকারী হবে","root":"حمل","lemma":"حَٰمِلِين","grammar_bn":"অব্যয় (Preposition)"},{"id":14419,"position":13,"text_uthmani":"مِنْ","transliteration":"min","translation_bn":"হ''তে","root":"—","lemma":"مِن\r","grammar_bn":"অব্যয় (Preposition)"},{"id":14420,"position":14,"text_uthmani":"خَطَـٰيَـٰهُم","transliteration":"khaṭāyāhum","translation_bn":"ত্রুটিগুলোর (পাপরাশিকে)তোমাদের","root":"خطا","lemma":"خَطِي^ـ#َة","grammar_bn":"বিশেষ্য (Noun)"},{"id":14421,"position":15,"text_uthmani":"مِّن","transliteration":"min","translation_bn":"কোনো","root":"—","lemma":"مِن\r","grammar_bn":"অব্যয় (Preposition)"},{"id":14422,"position":16,"text_uthmani":"شَىْءٍ ۖ","transliteration":"shayin","translation_bn":"কিছুই","root":"شيا","lemma":"شَىْء","grammar_bn":"বিশেষ্য (Noun)"},{"id":14424,"position":17,"text_uthmani":"إِنَّهُمْ","transliteration":"innahum","translation_bn":"নিশ্চয়ই তারা","root":"—","lemma":"إِنّ","grammar_bn":"অভিঘাত পদ (Accusative)"},{"id":14425,"position":18,"text_uthmani":"لَكَـٰذِبُونَ","transliteration":"lakādhibūna","translation_bn":"অবশ্যই মিথ্যাবাদী","root":"كذب","lemma":"كَٰذِب","grammar_bn":"দৃঢ়তাবোধক (Emphatic)"},{"id":14426,"position":19,"text_uthmani":"١٢","transliteration":"","translation_bn":"(১২)","root":"—","lemma":"١٢","grammar_bn":"মার্কার"}]'::jsonb, 'waqāla alladhīna kafarū lilladhīna āmanū ittabiʿū sabīlanā walnaḥmil khaṭāyākum wamā hum biḥāmilīna min khaṭāyāhum min shayin innahum lakādhibūna', 'কাফিররা মু’মিনদেরকে বলে, ‘আমাদের পথ অনুসরণ কর, আমরা তোমাদের পাপের বোঝা বহন করব, মূলতঃ তারা তাদের পাপের কিছুই বহন করবে না, অবশ্যই তারা মিথ্যেবাদী।', 'And those who disbelieve say to those who believe, "Follow our way, and we will carry your sins." But they will not carry anything of their sins. Indeed, they are liars.', 'কাফিররা মু’মিনদেরকে বলে, ‘আমাদের পথ অনুসরণ কর, আমরা তোমাদের পাপের বোঝা বহন করব, মূলতঃ তারা তাদের পাপের কিছুই বহন করবে না, অবশ্যই তারা মিথ্যেবাদী।', 'And those who disbelieve say to those who believe, "Follow our way, and we will carry your sins." But they will not carry anything of their sins. Indeed, they are liars.', NULL, NULL, NULL, NULL, NULL, 'https://everyayah.com/data/Alafasy_128kbps/029012.mp3', now()),
  (29, 13, '', '[{"id":15511,"position":1,"text_uthmani":"وَلَيَحْمِلُنَّ","transliteration":"walayaḥmilunna","translation_bn":"এবং অবশ্যই তারা বহন করবেই","root":"حمل","lemma":"حَمَلَ","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":15512,"position":2,"text_uthmani":"أَثْقَالَهُمْ","transliteration":"athqālahum","translation_bn":"বোঝাসমূহকে তাদের","root":"ثقل","lemma":"ثَّقَلَان","grammar_bn":"বিশেষ্য (Noun)"},{"id":15513,"position":3,"text_uthmani":"وَأَثْقَالًۭا","transliteration":"wa-athqālan","translation_bn":"এবং বোঝাসমূহকে (অন্য অনেক)","root":"ثقل","lemma":"ثَّقَلَان","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":15514,"position":4,"text_uthmani":"مَّعَ","transliteration":"maʿa","translation_bn":"সাথে","root":"—","lemma":"مَع","grammar_bn":"স্থানবাচক (Location)"},{"id":15515,"position":5,"text_uthmani":"أَثْقَالِهِمْ ۖ","transliteration":"athqālihim","translation_bn":"বোঝাসমূহের তাদের","root":"ثقل","lemma":"ثَّقَلَان","grammar_bn":"বিশেষ্য (Noun)"},{"id":15517,"position":6,"text_uthmani":"وَلَيُسْـَٔلُنَّ","transliteration":"walayus''alunna","translation_bn":"এবং অবশ্যই তাদেরকে  জিজ্ঞাসা করা হবে","root":"سال","lemma":"سَأَلَ","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":15518,"position":7,"text_uthmani":"يَوْمَ","transliteration":"yawma","translation_bn":"দিনে","root":"يوم","lemma":"يَوْم","grammar_bn":"বিশেষ্য (Noun)"},{"id":15519,"position":8,"text_uthmani":"ٱلْقِيَـٰمَةِ","transliteration":"l-qiyāmati","translation_bn":"ক্বিয়ামাতের","root":"قوم","lemma":"قِيَٰمَة","grammar_bn":"শব্দ"},{"id":15520,"position":9,"text_uthmani":"عَمَّا","transliteration":"ʿammā","translation_bn":"ঐ সম্পর্কে যা","root":"—","lemma":"عَن\r","grammar_bn":"অব্যয় (Preposition)"},{"id":15521,"position":10,"text_uthmani":"كَانُوا۟","transliteration":"kānū","translation_bn":"তারা ছিলো","root":"كون","lemma":"كَانَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":15522,"position":11,"text_uthmani":"يَفْتَرُونَ","transliteration":"yaftarūna","translation_bn":"তারা মিথ্যা রচনা করে আসছে","root":"فري","lemma":"ٱفْتَرَىٰ","grammar_bn":"ক্রিয়া (Verb)"},{"id":15523,"position":12,"text_uthmani":"١٣","transliteration":"","translation_bn":"(১৩)","root":"—","lemma":"١٣","grammar_bn":"মার্কার"}]'::jsonb, 'walayaḥmilunna athqālahum wa-athqālan maʿa athqālihim walayus''alunna yawma l-qiyāmati ʿammā kānū yaftarūna', 'তারা অবশ্য অবশ্যই তাদের নিজেদের পাপের বোঝা বহন করবে, নিজেদের বোঝার সাথে আরো বোঝা, আর তারা যে সব মিথ্যে উদ্ভাবন করত সে সম্পর্কে ক্বিয়ামত দিবসে তারা অবশ্য অবশ্যই জিজ্ঞাসিত হবে।', 'But they will surely carry their [own] burdens and [other] burdens along with their burdens, and they will surely be questioned on the Day of Resurrection about what they used to invent.', 'তারা অবশ্য অবশ্যই তাদের নিজেদের পাপের বোঝা বহন করবে, নিজেদের বোঝার সাথে আরো বোঝা, আর তারা যে সব মিথ্যে উদ্ভাবন করত সে সম্পর্কে ক্বিয়ামত দিবসে তারা অবশ্য অবশ্যই জিজ্ঞাসিত হবে।', 'But they will surely carry their [own] burdens and [other] burdens along with their burdens, and they will surely be questioned on the Day of Resurrection about what they used to invent.', NULL, NULL, NULL, NULL, NULL, 'https://everyayah.com/data/Alafasy_128kbps/029013.mp3', now()),
  (29, 14, '', '[{"id":16554,"position":1,"text_uthmani":"وَلَقَدْ","transliteration":"walaqad","translation_bn":"এবং নিশ্চয়ই","root":"—","lemma":"قَد\r","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":16555,"position":2,"text_uthmani":"أَرْسَلْنَا","transliteration":"arsalnā","translation_bn":"আমরা পাঠিয়েছিলাম","root":"رسل","lemma":"أَرْسَلَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":16556,"position":3,"text_uthmani":"نُوحًا","transliteration":"nūḥan","translation_bn":"নূহকে","root":"—","lemma":"نُوح","grammar_bn":"নামবাচক বিশেষ্য (Proper Noun)"},{"id":16557,"position":4,"text_uthmani":"إِلَىٰ","transliteration":"ilā","translation_bn":"প্রতি","root":"—","lemma":"إِلَىٰ\r","grammar_bn":"অব্যয় (Preposition)"},{"id":16558,"position":5,"text_uthmani":"قَوْمِهِۦ","transliteration":"qawmihi","translation_bn":"তার জাতির","root":"قوم","lemma":"قَوْم","grammar_bn":"বিশেষ্য (Noun)"},{"id":16559,"position":6,"text_uthmani":"فَلَبِثَ","transliteration":"falabitha","translation_bn":"অতঃপর সে অবস্থান করেছিলো","root":"لبث","lemma":"لَبِثَ","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":16560,"position":7,"text_uthmani":"فِيهِمْ","transliteration":"fīhim","translation_bn":"মধ্যে তাদের","root":"—","lemma":"فِى\r","grammar_bn":"অব্যয় (Preposition)"},{"id":16561,"position":8,"text_uthmani":"أَلْفَ","transliteration":"alfa","translation_bn":"এক হাজার","root":"الف","lemma":"أَلْف","grammar_bn":"বিশেষ্য (Noun)"},{"id":16562,"position":9,"text_uthmani":"سَنَةٍ","transliteration":"sanatin","translation_bn":"ব্ছর","root":"سنو","lemma":"سَنَة","grammar_bn":"বিশেষ্য (Noun)"},{"id":16563,"position":10,"text_uthmani":"إِلَّا","transliteration":"illā","translation_bn":"কম","root":"—","lemma":"إِلَّا\r","grammar_bn":"সীমাবদ্ধতা (Restriction)"},{"id":16564,"position":11,"text_uthmani":"خَمْسِينَ","transliteration":"khamsīna","translation_bn":"পঞ্চাশ","root":"خمس","lemma":"خَمْسِين","grammar_bn":"বিশেষ্য (Noun)"},{"id":16565,"position":12,"text_uthmani":"عَامًۭا","transliteration":"ʿāman","translation_bn":"ব্ছর (অর্থাৎ সাড়ে নয়শত বছর)","root":"عوم","lemma":"عَام","grammar_bn":"বিশেষ্য (Noun)"},{"id":16566,"position":13,"text_uthmani":"فَأَخَذَهُمُ","transliteration":"fa-akhadhahumu","translation_bn":"অতঃপর গ্রাস করেছিলো তাদেরকে","root":"اخذ","lemma":"أَخَذَ","grammar_bn":"শব্দ"},{"id":16567,"position":14,"text_uthmani":"ٱلطُّوفَانُ","transliteration":"l-ṭūfānu","translation_bn":"প্লাবন","root":"طوف","lemma":"طُّوفَان","grammar_bn":"শব্দ"},{"id":16568,"position":15,"text_uthmani":"وَهُمْ","transliteration":"wahum","translation_bn":"এ অবস্থায় যে তারা ছিলো","root":"—","lemma":"وَهُمْ","grammar_bn":"অবস্থাবাচক (Circumstantial)"},{"id":16569,"position":16,"text_uthmani":"ظَـٰلِمُونَ","transliteration":"ẓālimūna","translation_bn":"সীমালঙ্ঘনকারী","root":"ظلم","lemma":"ظَالِم","grammar_bn":"বিশেষ্য (Noun)"},{"id":16570,"position":17,"text_uthmani":"١٤","transliteration":"","translation_bn":"(১৪)","root":"—","lemma":"١٤","grammar_bn":"মার্কার"}]'::jsonb, 'walaqad arsalnā nūḥan ilā qawmihi falabitha fīhim alfa sanatin illā khamsīna ʿāman fa-akhadhahumu l-ṭūfānu wahum ẓālimūna', 'আমি নূহকে তার সম্প্রদায়ের কাছে পাঠিয়েছিলাম, অতঃপর সে পঞ্চাশ বছর কম হাজার বছর তাদের মাঝে অবস্থান করেছিল। অতঃপর মহাপ্লাবন তাদেরকে গ্রাস করল কারণ তারা ছিল সীমালঙ্ঘনকারী।', 'And We certainly sent Noah to his people, and he remained among them a thousand years minus fifty years, and the flood seized them while they were wrongdoers.', 'আমি নূহকে তার সম্প্রদায়ের কাছে পাঠিয়েছিলাম, অতঃপর সে পঞ্চাশ বছর কম হাজার বছর তাদের মাঝে অবস্থান করেছিল। অতঃপর মহাপ্লাবন তাদেরকে গ্রাস করল কারণ তারা ছিল সীমালঙ্ঘনকারী।', 'And We certainly sent Noah to his people, and he remained among them a thousand years minus fifty years, and the flood seized them while they were wrongdoers.', NULL, NULL, NULL, NULL, NULL, 'https://everyayah.com/data/Alafasy_128kbps/029014.mp3', now()),
  (29, 15, '', '[{"id":17744,"position":1,"text_uthmani":"فَأَنجَيْنَـٰهُ","transliteration":"fa-anjaynāhu","translation_bn":"অতঃপর আমরা রক্ষা করলাম তাকে","root":"نجو","lemma":"أَنجَىٰ","grammar_bn":"শব্দ"},{"id":17745,"position":2,"text_uthmani":"وَأَصْحَـٰبَ","transliteration":"wa-aṣḥāba","translation_bn":"এবং সাথীদেরকে (অর্থাৎ আরোহীদেরকেও)","root":"صحب","lemma":"أَصْحَٰب","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":17746,"position":3,"text_uthmani":"ٱلسَّفِينَةِ","transliteration":"l-safīnati","translation_bn":"নৌকার","root":"سفن","lemma":"سَفِينَة","grammar_bn":"শব্দ"},{"id":17747,"position":4,"text_uthmani":"وَجَعَلْنَـٰهَآ","transliteration":"wajaʿalnāhā","translation_bn":"এবং আমরা করেছি তা","root":"جعل","lemma":"جَعَلَ","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":17748,"position":5,"text_uthmani":"ءَايَةًۭ","transliteration":"āyatan","translation_bn":"একটি নিদর্শন","root":"ايي","lemma":"ءَايَة","grammar_bn":"বিশেষ্য (Noun)"},{"id":17749,"position":6,"text_uthmani":"لِّلْعَـٰلَمِينَ","transliteration":"lil''ʿālamīna","translation_bn":"জন্যে বিশ্ববাসীদের","root":"علم","lemma":"عَٰلَمِين","grammar_bn":"অব্যয় (Preposition)"},{"id":17750,"position":7,"text_uthmani":"١٥","transliteration":"","translation_bn":"(১৫)","root":"—","lemma":"١٥","grammar_bn":"মার্কার"}]'::jsonb, 'fa-anjaynāhu wa-aṣḥāba l-safīnati wajaʿalnāhā āyatan lil''ʿālamīna', 'অতঃপর আমি তাকে ও নৌকারোহীদেরকে রক্ষে করলাম আর এটাকে করলাম বিশ্বজগতের জন্য নিদর্শন।', 'But We saved him and the companions of the ship, and We made it a sign for the worlds.', 'অতঃপর আমি তাকে ও নৌকারোহীদেরকে রক্ষে করলাম আর এটাকে করলাম বিশ্বজগতের জন্য নিদর্শন।', 'But We saved him and the companions of the ship, and We made it a sign for the worlds.', NULL, NULL, NULL, NULL, NULL, 'https://everyayah.com/data/Alafasy_128kbps/029015.mp3', now()),
  (29, 16, '', '[{"id":18750,"position":1,"text_uthmani":"وَإِبْرَٰهِيمَ","transliteration":"wa-ib''rāhīma","translation_bn":"এবং (স্মরণ করো) ইবরাহীমের (কথা)","root":"—","lemma":"إِبْرَاهِيم","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":18751,"position":2,"text_uthmani":"إِذْ","transliteration":"idh","translation_bn":"যখন","root":"—","lemma":"إِذ\r","grammar_bn":"কালবাচক (Time)"},{"id":18752,"position":3,"text_uthmani":"قَالَ","transliteration":"qāla","translation_bn":"সে বলেছিলো","root":"قول","lemma":"قَالَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":18753,"position":4,"text_uthmani":"لِقَوْمِهِ","transliteration":"liqawmihi","translation_bn":"উদ্দেশ্যে তার জাতির","root":"قوم","lemma":"قَوْم","grammar_bn":"অব্যয় (Preposition)"},{"id":18754,"position":5,"text_uthmani":"ٱعْبُدُوا۟","transliteration":"uʿ''budū","translation_bn":"\"তোমরা ইবাদাত করো","root":"عبد","lemma":"عَبَدَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":18755,"position":6,"text_uthmani":"ٱللَّهَ","transliteration":"l-laha","translation_bn":"আল্লাহ্‌র","root":"اله","lemma":"ٱللَّه","grammar_bn":"নামবাচক বিশেষ্য (Proper Noun)"},{"id":18756,"position":7,"text_uthmani":"وَٱتَّقُوهُ ۖ","transliteration":"wa-ittaqūhu","translation_bn":"এবং তাঁকেই ভয় করো","root":"وقي","lemma":"ٱتَّقَىٰ","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":18758,"position":8,"text_uthmani":"ذَٰلِكُمْ","transliteration":"dhālikum","translation_bn":"এটাই","root":"—","lemma":"ذَٰلِك","grammar_bn":"নির্দেশক সর্বনাম (Demonstrative)"},{"id":18759,"position":9,"text_uthmani":"خَيْرٌۭ","transliteration":"khayrun","translation_bn":"উত্তম","root":"خير","lemma":"خَيْر","grammar_bn":"বিশেষ্য (Noun)"},{"id":18760,"position":10,"text_uthmani":"لَّكُمْ","transliteration":"lakum","translation_bn":"জন্যে তোমাদের","root":"—","lemma":"لَّكُمْ","grammar_bn":"অব্যয় (Preposition)"},{"id":18761,"position":11,"text_uthmani":"إِن","transliteration":"in","translation_bn":"যদি","root":"—","lemma":"إِن\r","grammar_bn":"শর্তবাচক (Conditional)"},{"id":18762,"position":12,"text_uthmani":"كُنتُمْ","transliteration":"kuntum","translation_bn":"তোমরা ছিলে","root":"كون","lemma":"كَانَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":18763,"position":13,"text_uthmani":"تَعْلَمُونَ","transliteration":"taʿlamūna","translation_bn":"তোমরা জানতে","root":"علم","lemma":"عَلِمَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":18764,"position":14,"text_uthmani":"١٦","transliteration":"","translation_bn":"(১৬)","root":"—","lemma":"١٦","grammar_bn":"মার্কার"}]'::jsonb, 'wa-ib''rāhīma idh qāla liqawmihi uʿ''budū l-laha wa-ittaqūhu dhālikum khayrun lakum in kuntum taʿlamūna', 'স্মরণ কর যখন ইবরাহীম তার সম্প্রদায়কে বলেছিল- ‘তোমরা আল্লাহর ‘ইবাদাত কর আর তাঁকে ভয় কর। এটাই তোমাদের জন্য কল্যাণকর, তোমরা যদি জানতে!', 'And [We sent] Abraham, when he said to his people, "Worship Allah and fear Him. That is best for you, if you should know.', 'স্মরণ কর যখন ইবরাহীম তার সম্প্রদায়কে বলেছিল- ‘তোমরা আল্লাহর ‘ইবাদাত কর আর তাঁকে ভয় কর। এটাই তোমাদের জন্য কল্যাণকর, তোমরা যদি জানতে!', 'And [We sent] Abraham, when he said to his people, "Worship Allah and fear Him. That is best for you, if you should know.', NULL, NULL, NULL, NULL, NULL, 'https://everyayah.com/data/Alafasy_128kbps/029016.mp3', now()),
  (29, 17, '', '[{"id":19843,"position":1,"text_uthmani":"إِنَّمَا","transliteration":"innamā","translation_bn":"কেবল","root":"—","lemma":"إِنّ","grammar_bn":"অভিঘাত পদ (Accusative)"},{"id":19844,"position":2,"text_uthmani":"تَعْبُدُونَ","transliteration":"taʿbudūna","translation_bn":"তোমরা উপাসনা করছো","root":"عبد","lemma":"عَبَدَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":19845,"position":3,"text_uthmani":"مِن","transliteration":"min","translation_bn":"মধ্য হতে","root":"—","lemma":"مِن\r","grammar_bn":"অব্যয় (Preposition)"},{"id":19846,"position":4,"text_uthmani":"دُونِ","transliteration":"dūni","translation_bn":"ছাড়া","root":"دون","lemma":"دُون","grammar_bn":"বিশেষ্য (Noun)"},{"id":19847,"position":5,"text_uthmani":"ٱللَّهِ","transliteration":"l-lahi","translation_bn":"আল্লাহ্‌","root":"اله","lemma":"ٱللَّه","grammar_bn":"নামবাচক বিশেষ্য (Proper Noun)"},{"id":19848,"position":6,"text_uthmani":"أَوْثَـٰنًۭا","transliteration":"awthānan","translation_bn":"মূর্তিগুলোকে","root":"وثن","lemma":"أَوْثَٰن","grammar_bn":"বিশেষ্য (Noun)"},{"id":19849,"position":7,"text_uthmani":"وَتَخْلُقُونَ","transliteration":"watakhluqūna","translation_bn":"এবং তোমরা বানাচ্ছো","root":"خلق","lemma":"خَلَقَ","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":19850,"position":8,"text_uthmani":"إِفْكًا ۚ","transliteration":"if''kan","translation_bn":"মিথ্যা","root":"افك","lemma":"إِفْك","grammar_bn":"বিশেষ্য (Noun)"},{"id":19852,"position":9,"text_uthmani":"إِنَّ","transliteration":"inna","translation_bn":"নিশ্চয়ই","root":"—","lemma":"إِنّ","grammar_bn":"অভিঘাত পদ (Accusative)"},{"id":19853,"position":10,"text_uthmani":"ٱلَّذِينَ","transliteration":"alladhīna","translation_bn":"যাদেরকে","root":"—","lemma":"ٱلَّذِى","grammar_bn":"সাপেক্ষ সর্বনাম (Relative)"},{"id":19854,"position":11,"text_uthmani":"تَعْبُدُونَ","transliteration":"taʿbudūna","translation_bn":"তোমরা উপাসনা করছো","root":"عبد","lemma":"عَبَدَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":19855,"position":12,"text_uthmani":"مِن","transliteration":"min","translation_bn":"মধ্য হতে","root":"—","lemma":"مِن\r","grammar_bn":"অব্যয় (Preposition)"},{"id":19856,"position":13,"text_uthmani":"دُونِ","transliteration":"dūni","translation_bn":"ছাড়া","root":"دون","lemma":"دُون","grammar_bn":"বিশেষ্য (Noun)"},{"id":19857,"position":14,"text_uthmani":"ٱللَّهِ","transliteration":"l-lahi","translation_bn":"আল্লাহ্‌","root":"اله","lemma":"ٱللَّه","grammar_bn":"নামবাচক বিশেষ্য (Proper Noun)"},{"id":19858,"position":15,"text_uthmani":"لَا","transliteration":"lā","translation_bn":"না","root":"—","lemma":"لَا\r","grammar_bn":"না-বোধক (Negative)"},{"id":19859,"position":16,"text_uthmani":"يَمْلِكُونَ","transliteration":"yamlikūna","translation_bn":"তারা ক্ষমতা রাখে","root":"ملك","lemma":"مَلَكَتْ","grammar_bn":"ক্রিয়া (Verb)"},{"id":19860,"position":17,"text_uthmani":"لَكُمْ","transliteration":"lakum","translation_bn":"জন্যে তোমাদের","root":"—","lemma":"لَكُمْ","grammar_bn":"অব্যয় (Preposition)"},{"id":19861,"position":18,"text_uthmani":"رِزْقًۭا","transliteration":"riz''qan","translation_bn":"জীবিকা(দেয়ার)","root":"رزق","lemma":"رِزْق","grammar_bn":"বিশেষ্য (Noun)"},{"id":19862,"position":19,"text_uthmani":"فَٱبْتَغُوا۟","transliteration":"fa-ib''taghū","translation_bn":"সুতরাং তোমরা চাও","root":"بغي","lemma":"ٱبْتَغَىٰ","grammar_bn":"শব্দ"},{"id":19863,"position":20,"text_uthmani":"عِندَ","transliteration":"ʿinda","translation_bn":"নিকট","root":"عند","lemma":"عِند","grammar_bn":"স্থানবাচক (Location)"},{"id":19864,"position":21,"text_uthmani":"ٱللَّهِ","transliteration":"l-lahi","translation_bn":"আল্লাহ্‌র","root":"اله","lemma":"ٱللَّه","grammar_bn":"নামবাচক বিশেষ্য (Proper Noun)"},{"id":19865,"position":22,"text_uthmani":"ٱلرِّزْقَ","transliteration":"l-riz''qa","translation_bn":"জীবিকা","root":"رزق","lemma":"رِزْق","grammar_bn":"শব্দ"},{"id":19866,"position":23,"text_uthmani":"وَٱعْبُدُوهُ","transliteration":"wa-uʿ''budūhu","translation_bn":"এবং তোমরা ইবাদাত করো তাঁরই","root":"عبد","lemma":"عَبَدَ","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":19867,"position":24,"text_uthmani":"وَٱشْكُرُوا۟","transliteration":"wa-ush''kurū","translation_bn":"এবং তোমরা কৃতজ্ঞতা প্রকাশ করো","root":"شكر","lemma":"شَكَرَ","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":19868,"position":25,"text_uthmani":"لَهُۥٓ ۖ","transliteration":"lahu","translation_bn":"তাঁরই","root":"—","lemma":"لَهُۥٓ ۖ","grammar_bn":"অব্যয় (Preposition)"},{"id":19870,"position":26,"text_uthmani":"إِلَيْهِ","transliteration":"ilayhi","translation_bn":"দিকে তাঁরই","root":"—","lemma":"إِلَىٰ\r","grammar_bn":"অব্যয় (Preposition)"},{"id":19871,"position":27,"text_uthmani":"تُرْجَعُونَ","transliteration":"tur''jaʿūna","translation_bn":"তোমরা প্রত্যাবর্তিত হবে","root":"رجع","lemma":"رَجَعَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":19872,"position":28,"text_uthmani":"١٧","transliteration":"","translation_bn":"(১৭)","root":"—","lemma":"١٧","grammar_bn":"মার্কার"}]'::jsonb, 'innamā taʿbudūna min dūni l-lahi awthānan watakhluqūna if''kan inna alladhīna taʿbudūna min dūni l-lahi lā yamlikūna lakum riz''qan fa-ib''taghū ʿinda l-lahi l-riz''qa wa-uʿ''budūhu wa-ush''kurū lahu ilayhi tur''jaʿūna', 'তোমরা আল্লাহকে বাদ দিয়ে প্রতিমার পূজা করছ আর তোমরা মিথ্যে উদ্ভাবন করছ। আল্লাহকে বাদ দিয়ে তোমরা যে সবগুলোর পূজা করছ তারা তোমাদেরকে রিযক দানের কোন ক্ষমতা রাখে না, কাজেই তোমরা আল্লাহর নিকট রিযক তালাশ কর, আর তাঁরই ‘ইবাদাত কর, আর তাঁরই প্রতি কৃতজ্ঞতা প্রকাশ কর, তোমাদেরকে তাঁরই দিকে ফিরিয়ে নেয়া হবে।', 'You only worship, besides Allah, idols, and you produce a falsehood. Indeed, those you worship besides Allah do not possess for you [the power of] provision. So seek from Allah provision and worship Him and be grateful to Him. To Him you will be returned."', 'তোমরা আল্লাহকে বাদ দিয়ে প্রতিমার পূজা করছ আর তোমরা মিথ্যে উদ্ভাবন করছ। আল্লাহকে বাদ দিয়ে তোমরা যে সবগুলোর পূজা করছ তারা তোমাদেরকে রিযক দানের কোন ক্ষমতা রাখে না, কাজেই তোমরা আল্লাহর নিকট রিযক তালাশ কর, আর তাঁরই ‘ইবাদাত কর, আর তাঁরই প্রতি কৃতজ্ঞতা প্রকাশ কর, তোমাদেরকে তাঁরই দিকে ফিরিয়ে নেয়া হবে।', 'You only worship, besides Allah, idols, and you produce a falsehood. Indeed, those you worship besides Allah do not possess for you [the power of] provision. So seek from Allah provision and worship Him and be grateful to Him. To Him you will be returned."', NULL, NULL, NULL, NULL, NULL, 'https://everyayah.com/data/Alafasy_128kbps/029017.mp3', now()),
  (29, 18, '', '[{"id":20912,"position":1,"text_uthmani":"وَإِن","transliteration":"wa-in","translation_bn":"আর যদি","root":"—","lemma":"إِن\r","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":20913,"position":2,"text_uthmani":"تُكَذِّبُوا۟","transliteration":"tukadhibū","translation_bn":"তোমরা মিথ্যা আরোপ করো","root":"كذب","lemma":"كَذَّبَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":20914,"position":3,"text_uthmani":"فَقَدْ","transliteration":"faqad","translation_bn":"নিশ্চয়ই তবে","root":"—","lemma":"قَد\r","grammar_bn":"শব্দ"},{"id":20915,"position":4,"text_uthmani":"كَذَّبَ","transliteration":"kadhaba","translation_bn":"মিথ্যারোপ করেছিলো","root":"كذب","lemma":"كَذَّبَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":20916,"position":5,"text_uthmani":"أُمَمٌۭ","transliteration":"umamun","translation_bn":"(অনেক) জাতি","root":"امم","lemma":"أُمَّة","grammar_bn":"বিশেষ্য (Noun)"},{"id":20917,"position":6,"text_uthmani":"مِّن","transliteration":"min","translation_bn":"থেকেও","root":"—","lemma":"مِن\r","grammar_bn":"অব্যয় (Preposition)"},{"id":20918,"position":7,"text_uthmani":"قَبْلِكُمْ ۖ","transliteration":"qablikum","translation_bn":"তোমাদের পূর্ব","root":"قبل","lemma":"قَبْل","grammar_bn":"বিশেষ্য (Noun)"},{"id":20920,"position":8,"text_uthmani":"وَمَا","transliteration":"wamā","translation_bn":"আর না","root":"—","lemma":"مَا\r","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":20921,"position":9,"text_uthmani":"عَلَى","transliteration":"ʿalā","translation_bn":"উপর","root":"—","lemma":"عَلَىٰ\r","grammar_bn":"অব্যয় (Preposition)"},{"id":20922,"position":10,"text_uthmani":"ٱلرَّسُولِ","transliteration":"l-rasūli","translation_bn":"(দায়িত্ব) রাসূলের","root":"رسل","lemma":"رَسُول","grammar_bn":"শব্দ"},{"id":20923,"position":11,"text_uthmani":"إِلَّا","transliteration":"illā","translation_bn":"এ ছাড়া যে","root":"—","lemma":"إِلَّا\r","grammar_bn":"সীমাবদ্ধতা (Restriction)"},{"id":20924,"position":12,"text_uthmani":"ٱلْبَلَـٰغُ","transliteration":"l-balāghu","translation_bn":"পৌঁছানো","root":"بلغ","lemma":"بَلَٰغ","grammar_bn":"শব্দ"},{"id":20925,"position":13,"text_uthmani":"ٱلْمُبِينُ","transliteration":"l-mubīnu","translation_bn":"সুস্পষ্টভাবে\"","root":"بين","lemma":"مُّبِين","grammar_bn":"শব্দ"},{"id":20926,"position":14,"text_uthmani":"١٨","transliteration":"","translation_bn":"(১৮)","root":"—","lemma":"١٨","grammar_bn":"মার্কার"}]'::jsonb, 'wa-in tukadhibū faqad kadhaba umamun min qablikum wamā ʿalā l-rasūli illā l-balāghu l-mubīnu', 'তোমরা যদি (রাসূলকে) মিথ্যে বলে অস্বীকার কর তবে তোমাদের পূর্বের বংশাবলীও অস্বীকার করেছিল, সুস্পষ্টভাবে প্রচার করা ব্যতীত রসূলের উপর কোন দায়িত্ব নেই।', 'And if you [people] deny [the message] - already nations before you have denied. And there is not upon the Messenger except [the duty of] clear notification.', 'তোমরা যদি (রাসূলকে) মিথ্যে বলে অস্বীকার কর তবে তোমাদের পূর্বের বংশাবলীও অস্বীকার করেছিল, সুস্পষ্টভাবে প্রচার করা ব্যতীত রসূলের উপর কোন দায়িত্ব নেই।', 'And if you [people] deny [the message] - already nations before you have denied. And there is not upon the Messenger except [the duty of] clear notification.', NULL, NULL, NULL, NULL, NULL, 'https://everyayah.com/data/Alafasy_128kbps/029018.mp3', now()),
  (29, 19, '', '[{"id":22012,"position":1,"text_uthmani":"أَوَلَمْ","transliteration":"awalam","translation_bn":"কি না","root":"—","lemma":"لَم\r","grammar_bn":"প্রশ্নবোধক (Interrogative)"},{"id":22013,"position":2,"text_uthmani":"يَرَوْا۟","transliteration":"yaraw","translation_bn":"তারা লক্ষ্য করে","root":"راي","lemma":"رَءَا","grammar_bn":"ক্রিয়া (Verb)"},{"id":22014,"position":3,"text_uthmani":"كَيْفَ","transliteration":"kayfa","translation_bn":"কিভাবে","root":"كيف\r","lemma":"كَيْف","grammar_bn":"প্রশ্নবোধক (Interrogative)"},{"id":22015,"position":4,"text_uthmani":"يُبْدِئُ","transliteration":"yub''di-u","translation_bn":"অস্তিত্ব দেন","root":"بدا","lemma":"يُبْدِئُ","grammar_bn":"ক্রিয়া (Verb)"},{"id":22016,"position":5,"text_uthmani":"ٱللَّهُ","transliteration":"l-lahu","translation_bn":"আল্লাহ্‌","root":"اله","lemma":"ٱللَّه","grammar_bn":"নামবাচক বিশেষ্য (Proper Noun)"},{"id":22017,"position":6,"text_uthmani":"ٱلْخَلْقَ","transliteration":"l-khalqa","translation_bn":"সৃষ্টিকে","root":"خلق","lemma":"خَلْق","grammar_bn":"শব্দ"},{"id":22018,"position":7,"text_uthmani":"ثُمَّ","transliteration":"thumma","translation_bn":"এরপর","root":"—","lemma":"ثُمّ\r","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":22019,"position":8,"text_uthmani":"يُعِيدُهُۥٓ ۚ","transliteration":"yuʿīduhu","translation_bn":"পুনঃসৃষ্টি করবেন তা","root":"عود","lemma":"أُعِيدُ","grammar_bn":"ক্রিয়া (Verb)"},{"id":22021,"position":9,"text_uthmani":"إِنَّ","transliteration":"inna","translation_bn":"নিশ্চয়ই","root":"—","lemma":"إِنّ","grammar_bn":"অভিঘাত পদ (Accusative)"},{"id":22022,"position":10,"text_uthmani":"ذَٰلِكَ","transliteration":"dhālika","translation_bn":"এটা","root":"—","lemma":"ذَٰلِك","grammar_bn":"নির্দেশক সর্বনাম (Demonstrative)"},{"id":22023,"position":11,"text_uthmani":"عَلَى","transliteration":"ʿalā","translation_bn":"জন্যে","root":"—","lemma":"عَلَىٰ\r","grammar_bn":"অব্যয় (Preposition)"},{"id":22024,"position":12,"text_uthmani":"ٱللَّهِ","transliteration":"l-lahi","translation_bn":"আল্লাহ্‌র","root":"اله","lemma":"ٱللَّه","grammar_bn":"নামবাচক বিশেষ্য (Proper Noun)"},{"id":22025,"position":13,"text_uthmani":"يَسِيرٌۭ","transliteration":"yasīrun","translation_bn":"সহজ","root":"يسر","lemma":"يَسِير","grammar_bn":"বিশেষণ (Adjective)"},{"id":22026,"position":14,"text_uthmani":"١٩","transliteration":"","translation_bn":"(১৯)","root":"—","lemma":"١٩","grammar_bn":"মার্কার"}]'::jsonb, 'awalam yaraw kayfa yub''di-u l-lahu l-khalqa thumma yuʿīduhu inna dhālika ʿalā l-lahi yasīrun', 'তারা কি লক্ষ্য করে না যে, আল্লাহ কীভাবে সৃষ্টির সূচনা করেন অতঃপর তার পুনরাবর্তন ঘটান, নিশ্চয় এটা আল্লাহর জন্য সহজ।', 'Have they not considered how Allah begins creation and then repeats it? Indeed that, for Allah, is easy.', 'তারা কি লক্ষ্য করে না যে, আল্লাহ কীভাবে সৃষ্টির সূচনা করেন অতঃপর তার পুনরাবর্তন ঘটান, নিশ্চয় এটা আল্লাহর জন্য সহজ।', 'Have they not considered how Allah begins creation and then repeats it? Indeed that, for Allah, is easy.', NULL, NULL, NULL, NULL, NULL, 'https://everyayah.com/data/Alafasy_128kbps/029019.mp3', now()),
  (29, 20, '', '[{"id":23051,"position":1,"text_uthmani":"قُلْ","transliteration":"qul","translation_bn":"বলো","root":"قول","lemma":"قَالَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":23052,"position":2,"text_uthmani":"سِيرُوا۟","transliteration":"sīrū","translation_bn":"\"তোমরা ভ্রমণ করো","root":"سير","lemma":"سَارَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":23053,"position":3,"text_uthmani":"فِى","transliteration":"fī","translation_bn":"মধ্যে","root":"—","lemma":"فِى\r","grammar_bn":"অব্যয় (Preposition)"},{"id":23054,"position":4,"text_uthmani":"ٱلْأَرْضِ","transliteration":"l-arḍi","translation_bn":"পৃথিবীর","root":"ارض","lemma":"أَرْض","grammar_bn":"শব্দ"},{"id":23055,"position":5,"text_uthmani":"فَٱنظُرُوا۟","transliteration":"fa-unẓurū","translation_bn":"অতঃপর লক্ষ্য করো","root":"نظر","lemma":"نَّظَرَ","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":23056,"position":6,"text_uthmani":"كَيْفَ","transliteration":"kayfa","translation_bn":"কিভাবে","root":"كيف\r","lemma":"كَيْف","grammar_bn":"প্রশ্নবোধক (Interrogative)"},{"id":23057,"position":7,"text_uthmani":"بَدَأَ","transliteration":"bada-a","translation_bn":"তিনি সূচনা করেছেন","root":"بدا","lemma":"بَدَأَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":23058,"position":8,"text_uthmani":"ٱلْخَلْقَ ۚ","transliteration":"l-khalqa","translation_bn":"সৃষ্টির","root":"خلق","lemma":"خَلْق","grammar_bn":"শব্দ"},{"id":23060,"position":9,"text_uthmani":"ثُمَّ","transliteration":"thumma","translation_bn":"এরপর","root":"—","lemma":"ثُمّ\r","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":23061,"position":10,"text_uthmani":"ٱللَّهُ","transliteration":"l-lahu","translation_bn":"আল্লাহ্‌","root":"اله","lemma":"ٱللَّه","grammar_bn":"নামবাচক বিশেষ্য (Proper Noun)"},{"id":23062,"position":11,"text_uthmani":"يُنشِئُ","transliteration":"yunshi-u","translation_bn":"সৃষ্টি করবেন","root":"نشا","lemma":"أَنشَأَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":23063,"position":12,"text_uthmani":"ٱلنَّشْأَةَ","transliteration":"l-nashata","translation_bn":"সৃষ্টি","root":"نشا","lemma":"نَّشْأَة","grammar_bn":"শব্দ"},{"id":23064,"position":13,"text_uthmani":"ٱلْـَٔاخِرَةَ ۚ","transliteration":"l-ākhirata","translation_bn":"পরবর্তী","root":"اخر","lemma":"ا^خِر","grammar_bn":"শব্দ"},{"id":23066,"position":14,"text_uthmani":"إِنَّ","transliteration":"inna","translation_bn":"নিশ্চয়ই","root":"—","lemma":"إِنّ","grammar_bn":"অভিঘাত পদ (Accusative)"},{"id":23067,"position":15,"text_uthmani":"ٱللَّهَ","transliteration":"l-laha","translation_bn":"আল্লাহ্‌","root":"اله","lemma":"ٱللَّه","grammar_bn":"নামবাচক বিশেষ্য (Proper Noun)"},{"id":23068,"position":16,"text_uthmani":"عَلَىٰ","transliteration":"ʿalā","translation_bn":"উপর","root":"—","lemma":"عَلَىٰ\r","grammar_bn":"অব্যয় (Preposition)"},{"id":23069,"position":17,"text_uthmani":"كُلِّ","transliteration":"kulli","translation_bn":"সব","root":"كلل","lemma":"كُلّ","grammar_bn":"বিশেষ্য (Noun)"},{"id":23070,"position":18,"text_uthmani":"شَىْءٍۢ","transliteration":"shayin","translation_bn":"কিছুর","root":"شيا","lemma":"شَىْء","grammar_bn":"বিশেষ্য (Noun)"},{"id":23071,"position":19,"text_uthmani":"قَدِيرٌۭ","transliteration":"qadīrun","translation_bn":"সর্বশক্তিমান\"","root":"قدر","lemma":"قَدِير","grammar_bn":"বিশেষ্য (Noun)"},{"id":23072,"position":20,"text_uthmani":"٢٠","transliteration":"","translation_bn":"(২০)","root":"—","lemma":"٢٠","grammar_bn":"মার্কার"}]'::jsonb, 'qul sīrū fī l-arḍi fa-unẓurū kayfa bada-a l-khalqa thumma l-lahu yunshi-u l-nashata l-ākhirata inna l-laha ʿalā kulli shayin qadīrun', 'বল- ‘তোমরা পৃথিবীতে ভ্রমণ কর, অতঃপর লক্ষ্য কর কীভাবে আল্লাহ সৃষ্টির সূচনা করেছেন, অতঃপর আল্লাহ সৃষ্টি করবেন পরবর্তী সৃষ্টি, আল্লাহ সকল বিষয়ের উপর ক্ষমতাবান।', 'Say, [O Muhammad], "Travel through the land and observe how He began creation. Then Allah will produce the final creation. Indeed Allah, over all things, is competent."', 'বল- ‘তোমরা পৃথিবীতে ভ্রমণ কর, অতঃপর লক্ষ্য কর কীভাবে আল্লাহ সৃষ্টির সূচনা করেছেন, অতঃপর আল্লাহ সৃষ্টি করবেন পরবর্তী সৃষ্টি, আল্লাহ সকল বিষয়ের উপর ক্ষমতাবান।', 'Say, [O Muhammad], "Travel through the land and observe how He began creation. Then Allah will produce the final creation. Indeed Allah, over all things, is competent."', NULL, NULL, NULL, NULL, NULL, 'https://everyayah.com/data/Alafasy_128kbps/029020.mp3', now()),
  (29, 21, '', '[{"id":24098,"position":1,"text_uthmani":"يُعَذِّبُ","transliteration":"yuʿadhibu","translation_bn":"তিনি শাস্তি দিবেন","root":"عذب","lemma":"عَذَّبَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":24099,"position":2,"text_uthmani":"مَن","transliteration":"man","translation_bn":"যাকে","root":"—","lemma":"مَن\r","grammar_bn":"সাপেক্ষ সর্বনাম (Relative)"},{"id":24100,"position":3,"text_uthmani":"يَشَآءُ","transliteration":"yashāu","translation_bn":"তিনি চান","root":"شيا","lemma":"شَا^ءَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":24101,"position":4,"text_uthmani":"وَيَرْحَمُ","transliteration":"wayarḥamu","translation_bn":"ও অনুগ্রহ করবেন","root":"رحم","lemma":"رَّحِمَ","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":24102,"position":5,"text_uthmani":"مَن","transliteration":"man","translation_bn":"যাকে","root":"—","lemma":"مَن\r","grammar_bn":"সাপেক্ষ সর্বনাম (Relative)"},{"id":24103,"position":6,"text_uthmani":"يَشَآءُ ۖ","transliteration":"yashāu","translation_bn":"ইচ্ছে করবেন","root":"شيا","lemma":"شَا^ءَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":24105,"position":7,"text_uthmani":"وَإِلَيْهِ","transliteration":"wa-ilayhi","translation_bn":"এবং দিকে তাঁরই","root":"—","lemma":"إِلَىٰ\r","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":24106,"position":8,"text_uthmani":"تُقْلَبُونَ","transliteration":"tuq''labūna","translation_bn":"তোমরা প্রত্যাবর্তিত হবে","root":"قلب","lemma":"تُقْلَبُ","grammar_bn":"ক্রিয়া (Verb)"},{"id":24107,"position":9,"text_uthmani":"٢١","transliteration":"","translation_bn":"(২১)","root":"—","lemma":"٢١","grammar_bn":"মার্কার"}]'::jsonb, 'yuʿadhibu man yashāu wayarḥamu man yashāu wa-ilayhi tuq''labūna', 'যাকে ইচ্ছে তিনি শাস্তি দেন আর যার প্রতি ইচ্ছে তিনি রহমত বর্ষণ করেন আর তাঁর কাছেই তোমাদেরকে ফিরিয়ে নেয়া হবে।', 'He punishes whom He wills and has mercy upon whom He wills, and to Him you will be returned.', 'যাকে ইচ্ছে তিনি শাস্তি দেন আর যার প্রতি ইচ্ছে তিনি রহমত বর্ষণ করেন আর তাঁর কাছেই তোমাদেরকে ফিরিয়ে নেয়া হবে।', 'He punishes whom He wills and has mercy upon whom He wills, and to Him you will be returned.', NULL, NULL, NULL, NULL, NULL, 'https://everyayah.com/data/Alafasy_128kbps/029021.mp3', now()),
  (29, 22, '', '[{"id":25095,"position":1,"text_uthmani":"وَمَآ","transliteration":"wamā","translation_bn":"এবং না","root":"—","lemma":"مَا\r","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":25096,"position":2,"text_uthmani":"أَنتُم","transliteration":"antum","translation_bn":"তোমরা","root":"—","lemma":"أَنتُم","grammar_bn":"সর্বনাম (Pronoun)"},{"id":25097,"position":3,"text_uthmani":"بِمُعْجِزِينَ","transliteration":"bimuʿ''jizīna","translation_bn":"(আল্লাহকে)অক্ষমকারী","root":"عجز","lemma":"مُعْجِز","grammar_bn":"অব্যয় (Preposition)"},{"id":25098,"position":4,"text_uthmani":"فِى","transliteration":"fī","translation_bn":"(না) মধ্যে","root":"—","lemma":"فِى\r","grammar_bn":"অব্যয় (Preposition)"},{"id":25099,"position":5,"text_uthmani":"ٱلْأَرْضِ","transliteration":"l-arḍi","translation_bn":"পৃথিবীর","root":"ارض","lemma":"أَرْض","grammar_bn":"শব্দ"},{"id":25100,"position":6,"text_uthmani":"وَلَا","transliteration":"walā","translation_bn":"আর না","root":"—","lemma":"لَا\r","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":25101,"position":7,"text_uthmani":"فِى","transliteration":"fī","translation_bn":"মধ্যে","root":"—","lemma":"فِى\r","grammar_bn":"অব্যয় (Preposition)"},{"id":25102,"position":8,"text_uthmani":"ٱلسَّمَآءِ ۖ","transliteration":"l-samāi","translation_bn":"আকাশের","root":"سمو","lemma":"سَمَا^ء","grammar_bn":"শব্দ"},{"id":25104,"position":9,"text_uthmani":"وَمَا","transliteration":"wamā","translation_bn":"এবং না (আছে)","root":"—","lemma":"مَا\r","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":25105,"position":10,"text_uthmani":"لَكُم","transliteration":"lakum","translation_bn":"জন্যে তোমাদের","root":"—","lemma":"لَكُم","grammar_bn":"অব্যয় (Preposition)"},{"id":25106,"position":11,"text_uthmani":"مِّن","transliteration":"min","translation_bn":"থেকে","root":"—","lemma":"مِن\r","grammar_bn":"অব্যয় (Preposition)"},{"id":25107,"position":12,"text_uthmani":"دُونِ","transliteration":"dūni","translation_bn":"ছাড়া","root":"دون","lemma":"دُون","grammar_bn":"বিশেষ্য (Noun)"},{"id":25108,"position":13,"text_uthmani":"ٱللَّهِ","transliteration":"l-lahi","translation_bn":"আল্লাহ্‌","root":"اله","lemma":"ٱللَّه","grammar_bn":"নামবাচক বিশেষ্য (Proper Noun)"},{"id":25109,"position":14,"text_uthmani":"مِن","transliteration":"min","translation_bn":"কোনো","root":"—","lemma":"مِن\r","grammar_bn":"অব্যয় (Preposition)"},{"id":25110,"position":15,"text_uthmani":"وَلِىٍّۢ","transliteration":"waliyyin","translation_bn":"অভিভাবক","root":"ولي","lemma":"وَلِىّ","grammar_bn":"বিশেষ্য (Noun)"},{"id":25111,"position":16,"text_uthmani":"وَلَا","transliteration":"walā","translation_bn":"আর না আছে","root":"—","lemma":"لَا\r","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":25112,"position":17,"text_uthmani":"نَصِيرٍۢ","transliteration":"naṣīrin","translation_bn":"কোনো সাহায্যকারী","root":"نصر","lemma":"نَصِير","grammar_bn":"বিশেষ্য (Noun)"},{"id":25113,"position":18,"text_uthmani":"٢٢","transliteration":"","translation_bn":"(২২)","root":"—","lemma":"٢٢","grammar_bn":"মার্কার"}]'::jsonb, 'wamā antum bimuʿ''jizīna fī l-arḍi walā fī l-samāi wamā lakum min dūni l-lahi min waliyyin walā naṣīrin', 'তোমরা (আল্লাহকে) না পৃথিবীতে ব্যর্থ করতে পারবে আর না আকাশে, আল্লাহ ছাড়া তোমাদের জন্য নেই কোন অভিভাবক, নেই কোন সাহায্যকারী।', 'And you will not cause failure [to Allah] upon the earth or in the heaven. And you have not other than Allah any protector or any helper.', 'তোমরা (আল্লাহকে) না পৃথিবীতে ব্যর্থ করতে পারবে আর না আকাশে, আল্লাহ ছাড়া তোমাদের জন্য নেই কোন অভিভাবক, নেই কোন সাহায্যকারী।', 'And you will not cause failure [to Allah] upon the earth or in the heaven. And you have not other than Allah any protector or any helper.', NULL, NULL, NULL, NULL, NULL, 'https://everyayah.com/data/Alafasy_128kbps/029022.mp3', now()),
  (29, 23, '', '[{"id":26216,"position":1,"text_uthmani":"وَٱلَّذِينَ","transliteration":"wa-alladhīna","translation_bn":"এবং যারা","root":"—","lemma":"ٱلَّذِى","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":26217,"position":2,"text_uthmani":"كَفَرُوا۟","transliteration":"kafarū","translation_bn":"অস্বীকার করেছে","root":"كفر","lemma":"كَفَرَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":26218,"position":3,"text_uthmani":"بِـَٔايَـٰتِ","transliteration":"biāyāti","translation_bn":"প্রতি নিদর্শনসমূহের","root":"ايي","lemma":"ءَايَة","grammar_bn":"অব্যয় (Preposition)"},{"id":26219,"position":4,"text_uthmani":"ٱللَّهِ","transliteration":"l-lahi","translation_bn":"আল্লাহ্‌র","root":"اله","lemma":"ٱللَّه","grammar_bn":"নামবাচক বিশেষ্য (Proper Noun)"},{"id":26220,"position":5,"text_uthmani":"وَلِقَآئِهِۦٓ","transliteration":"waliqāihi","translation_bn":"ও সাক্ষাতের তাঁর","root":"لقي","lemma":"لِقَا^ء","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":26221,"position":6,"text_uthmani":"أُو۟لَـٰٓئِكَ","transliteration":"ulāika","translation_bn":"ঐ সব লোক","root":"—","lemma":"أُولَٰ^ئِك","grammar_bn":"নির্দেশক সর্বনাম (Demonstrative)"},{"id":26222,"position":7,"text_uthmani":"يَئِسُوا۟","transliteration":"ya-isū","translation_bn":"নিরাশ হয়েছে","root":"ياس","lemma":"يَئِسَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":26223,"position":8,"text_uthmani":"مِن","transliteration":"min","translation_bn":"হ''তে","root":"—","lemma":"مِن\r","grammar_bn":"অব্যয় (Preposition)"},{"id":26224,"position":9,"text_uthmani":"رَّحْمَتِى","transliteration":"raḥmatī","translation_bn":"আমার অনুগ্রহ","root":"رحم","lemma":"رَحْمَة","grammar_bn":"বিশেষ্য (Noun)"},{"id":26225,"position":10,"text_uthmani":"وَأُو۟لَـٰٓئِكَ","transliteration":"wa-ulāika","translation_bn":"আর ঐসব লোক","root":"—","lemma":"أُولَٰ^ئِك","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":26226,"position":11,"text_uthmani":"لَهُمْ","transliteration":"lahum","translation_bn":"জন্যে তাদের (রয়েছে)","root":"—","lemma":"لَهُمْ","grammar_bn":"অব্যয় (Preposition)"},{"id":26227,"position":12,"text_uthmani":"عَذَابٌ","transliteration":"ʿadhābun","translation_bn":"শাস্তি","root":"عذب","lemma":"عَذَاب","grammar_bn":"বিশেষ্য (Noun)"},{"id":26228,"position":13,"text_uthmani":"أَلِيمٌۭ","transliteration":"alīmun","translation_bn":"নিদারুণ","root":"الم","lemma":"أَلِيم","grammar_bn":"বিশেষণ (Adjective)"},{"id":26229,"position":14,"text_uthmani":"٢٣","transliteration":"","translation_bn":"(২৩)","root":"—","lemma":"٢٣","grammar_bn":"মার্কার"}]'::jsonb, 'wa-alladhīna kafarū biāyāti l-lahi waliqāihi ulāika ya-isū min raḥmatī wa-ulāika lahum ʿadhābun alīmun', 'যারা আল্লাহর নিদর্শনাবলীকে আর তাঁর সাক্ষাৎকে অস্বীকার করে, তারা আমার রহমত থেকে নিরাশ হবে আর তাদের জন্য আছে ভয়াবহ শাস্তি।', 'And the ones who disbelieve in the signs of Allah and the meeting with Him - those have despaired of My mercy, and they will have a painful punishment.', 'যারা আল্লাহর নিদর্শনাবলীকে আর তাঁর সাক্ষাৎকে অস্বীকার করে, তারা আমার রহমত থেকে নিরাশ হবে আর তাদের জন্য আছে ভয়াবহ শাস্তি।', 'And the ones who disbelieve in the signs of Allah and the meeting with Him - those have despaired of My mercy, and they will have a painful punishment.', NULL, NULL, NULL, NULL, NULL, 'https://everyayah.com/data/Alafasy_128kbps/029023.mp3', now()),
  (29, 24, '', '[{"id":27247,"position":1,"text_uthmani":"فَمَا","transliteration":"famā","translation_bn":"অতঃপর না","root":"—","lemma":"مَا\r","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":27248,"position":2,"text_uthmani":"كَانَ","transliteration":"kāna","translation_bn":"ছিলো","root":"كون","lemma":"كَانَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":27249,"position":3,"text_uthmani":"جَوَابَ","transliteration":"jawāba","translation_bn":"জবাব","root":"جوب","lemma":"جَوَاب","grammar_bn":"বিশেষ্য (Noun)"},{"id":27250,"position":4,"text_uthmani":"قَوْمِهِۦٓ","transliteration":"qawmihi","translation_bn":"জাতির তার","root":"قوم","lemma":"قَوْم","grammar_bn":"বিশেষ্য (Noun)"},{"id":27251,"position":5,"text_uthmani":"إِلَّآ","transliteration":"illā","translation_bn":"এ ছাড়া","root":"—","lemma":"إِلَّا\r","grammar_bn":"সীমাবদ্ধতা (Restriction)"},{"id":27252,"position":6,"text_uthmani":"أَن","transliteration":"an","translation_bn":"যে","root":"—","lemma":"أَن\r","grammar_bn":"অধীনস্থ যোজক (Subordinating)"},{"id":27253,"position":7,"text_uthmani":"قَالُوا۟","transliteration":"qālū","translation_bn":"তারা বললো","root":"قول","lemma":"قَالَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":27254,"position":8,"text_uthmani":"ٱقْتُلُوهُ","transliteration":"uq''tulūhu","translation_bn":"\"তোমরা তাকে হত্যা করো","root":"قتل","lemma":"قَتَلَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":27255,"position":9,"text_uthmani":"أَوْ","transliteration":"aw","translation_bn":"অথবা","root":"—","lemma":"أَو\r","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":27256,"position":10,"text_uthmani":"حَرِّقُوهُ","transliteration":"ḥarriqūhu","translation_bn":"তাকে অাগুনে পোড়াও\"","root":"حرق","lemma":"حَرِّقُ","grammar_bn":"ক্রিয়া (Verb)"},{"id":27257,"position":11,"text_uthmani":"فَأَنجَىٰهُ","transliteration":"fa-anjāhu","translation_bn":"অতঃপর রক্ষা করলেন তাকে","root":"نجو","lemma":"أَنجَىٰ","grammar_bn":"শব্দ"},{"id":27258,"position":12,"text_uthmani":"ٱللَّهُ","transliteration":"l-lahu","translation_bn":"আল্লাহ্‌","root":"اله","lemma":"ٱللَّه","grammar_bn":"নামবাচক বিশেষ্য (Proper Noun)"},{"id":27259,"position":13,"text_uthmani":"مِنَ","transliteration":"mina","translation_bn":"হ''তে","root":"—","lemma":"مِن\r","grammar_bn":"অব্যয় (Preposition)"},{"id":27260,"position":14,"text_uthmani":"ٱلنَّارِ ۚ","transliteration":"l-nāri","translation_bn":"আগুন","root":"نور","lemma":"نَار","grammar_bn":"শব্দ"},{"id":27262,"position":15,"text_uthmani":"إِنَّ","transliteration":"inna","translation_bn":"নিশ্চয়ই","root":"—","lemma":"إِنّ","grammar_bn":"অভিঘাত পদ (Accusative)"},{"id":27263,"position":16,"text_uthmani":"فِى","transliteration":"fī","translation_bn":"মধ্যে (আছে)","root":"—","lemma":"فِى\r","grammar_bn":"অব্যয় (Preposition)"},{"id":27264,"position":17,"text_uthmani":"ذَٰلِكَ","transliteration":"dhālika","translation_bn":"এর","root":"—","lemma":"ذَٰلِك","grammar_bn":"নির্দেশক সর্বনাম (Demonstrative)"},{"id":27265,"position":18,"text_uthmani":"لَـَٔايَـٰتٍۢ","transliteration":"laāyātin","translation_bn":"অবশ্যই নিদর্শনাবলী","root":"ايي","lemma":"ءَايَة","grammar_bn":"দৃঢ়তাবোধক (Emphatic)"},{"id":27266,"position":19,"text_uthmani":"لِّقَوْمٍۢ","transliteration":"liqawmin","translation_bn":"জন্যে সম্প্রদায়ের","root":"قوم","lemma":"قَوْم","grammar_bn":"অব্যয় (Preposition)"},{"id":27267,"position":20,"text_uthmani":"يُؤْمِنُونَ","transliteration":"yu''minūna","translation_bn":"(যারা) ঈমান আনে","root":"امن","lemma":"ءَامَنَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":27268,"position":21,"text_uthmani":"٢٤","transliteration":"","translation_bn":"(২৪)","root":"—","lemma":"٢٤","grammar_bn":"মার্কার"}]'::jsonb, 'famā kāna jawāba qawmihi illā an qālū uq''tulūhu aw ḥarriqūhu fa-anjāhu l-lahu mina l-nāri inna fī dhālika laāyātin liqawmin yu''minūna', 'অতঃপর ইবরাহীমের সম্প্রদায়ের এ কথা বলা ছাড়া কোন জওয়াব ছিল না যে, তাকে হত্যা কর অথবা তাকে অগ্নিদগ্ধ কর।’ অতঃপর আল্লাহ তাকে অগ্নি থেকে রক্ষা করলেন। এতে বিশ্বাসী সম্প্রদায়ের জন্য অবশ্যই নিদর্শন রয়েছে।', 'And the answer of Abraham''s people was not but that they said, "Kill him or burn him," but Allah saved him from the fire. Indeed in that are signs for a people who believe.', 'অতঃপর ইবরাহীমের সম্প্রদায়ের এ কথা বলা ছাড়া কোন জওয়াব ছিল না যে, তাকে হত্যা কর অথবা তাকে অগ্নিদগ্ধ কর।’ অতঃপর আল্লাহ তাকে অগ্নি থেকে রক্ষা করলেন। এতে বিশ্বাসী সম্প্রদায়ের জন্য অবশ্যই নিদর্শন রয়েছে।', 'And the answer of Abraham''s people was not but that they said, "Kill him or burn him," but Allah saved him from the fire. Indeed in that are signs for a people who believe.', NULL, NULL, NULL, NULL, NULL, 'https://everyayah.com/data/Alafasy_128kbps/029024.mp3', now()),
  (29, 25, '', '[{"id":28300,"position":1,"text_uthmani":"وَقَالَ","transliteration":"waqāla","translation_bn":"এবং সে বলেছিলো","root":"قول","lemma":"قَالَ","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":28301,"position":2,"text_uthmani":"إِنَّمَا","transliteration":"innamā","translation_bn":"\"মূলতঃ","root":"—","lemma":"إِنّ","grammar_bn":"অভিঘাত পদ (Accusative)"},{"id":28302,"position":3,"text_uthmani":"ٱتَّخَذْتُم","transliteration":"ittakhadhtum","translation_bn":"তোমরা গ্রহণ করেছো","root":"اخذ","lemma":"ٱتَّخَذَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":28303,"position":4,"text_uthmani":"مِّن","transliteration":"min","translation_bn":"থেকে","root":"—","lemma":"مِن\r","grammar_bn":"অব্যয় (Preposition)"},{"id":28304,"position":5,"text_uthmani":"دُونِ","transliteration":"dūni","translation_bn":"ছাড়া","root":"دون","lemma":"دُون","grammar_bn":"বিশেষ্য (Noun)"},{"id":28305,"position":6,"text_uthmani":"ٱللَّهِ","transliteration":"l-lahi","translation_bn":"আল্লাহ্‌","root":"اله","lemma":"ٱللَّه","grammar_bn":"নামবাচক বিশেষ্য (Proper Noun)"},{"id":28306,"position":7,"text_uthmani":"أَوْثَـٰنًۭا","transliteration":"awthānan","translation_bn":"মূর্তিগুলোকে","root":"وثن","lemma":"أَوْثَٰن","grammar_bn":"বিশেষ্য (Noun)"},{"id":28307,"position":8,"text_uthmani":"مَّوَدَّةَ","transliteration":"mawaddata","translation_bn":"বন্ধুত্ব রক্ষার (উপায় হিসাবে)","root":"ودد","lemma":"مَّوَدَّة","grammar_bn":"বিশেষ্য (Noun)"},{"id":28308,"position":9,"text_uthmani":"بَيْنِكُمْ","transliteration":"baynikum","translation_bn":"মাঝে তোমাদের","root":"بين","lemma":"بَيْن","grammar_bn":"বিশেষ্য (Noun)"},{"id":28309,"position":10,"text_uthmani":"فِى","transliteration":"fī","translation_bn":"মধ্যে","root":"—","lemma":"فِى\r","grammar_bn":"অব্যয় (Preposition)"},{"id":28310,"position":11,"text_uthmani":"ٱلْحَيَوٰةِ","transliteration":"l-ḥayati","translation_bn":"জীবনের","root":"حيي","lemma":"حَيَوٰة","grammar_bn":"শব্দ"},{"id":28311,"position":12,"text_uthmani":"ٱلدُّنْيَا ۖ","transliteration":"