  (30, 2, '', '[{"id":1843,"position":1,"text_uthmani":"غُلِبَتِ","transliteration":"ghulibati","translation_bn":"পরাজিত হয়েছে","root":"غلب","lemma":"غَلَبُ","grammar_bn":"ক্রিয়া (Verb)"},{"id":1844,"position":2,"text_uthmani":"ٱلرُّومُ","transliteration":"l-rūmu","translation_bn":"রোমানরা","root":"—","lemma":"رُّوم","grammar_bn":"শব্দ"},{"id":1845,"position":3,"text_uthmani":"٢","transliteration":"","translation_bn":"(২)","root":"—","lemma":"٢","grammar_bn":"মার্কার"}]'::jsonb, 'ghulibati l-rūmu', 'রোমানরা পরাজিত হয়েছে।', 'The Byzantines have been defeated', 'রোমানরা পরাজিত হয়েছে।', 'The Byzantines have been defeated', NULL, NULL, NULL, NULL, NULL, 'https://everyayah.com/data/Alafasy_128kbps/030002.mp3', now()),
  (30, 3, '', '[{"id":3010,"position":1,"text_uthmani":"فِىٓ","transliteration":"fī","translation_bn":"মধ্যে","root":"—","lemma":"فِى\r","grammar_bn":"অব্যয় (Preposition)"},{"id":3011,"position":2,"text_uthmani":"أَدْنَى","transliteration":"adnā","translation_bn":"নিকটবর্তী","root":"دنو","lemma":"أَدْنَىٰ","grammar_bn":"বিশেষ্য (Noun)"},{"id":3012,"position":3,"text_uthmani":"ٱلْأَرْضِ","transliteration":"l-arḍi","translation_bn":"অঞ্চলের","root":"ارض","lemma":"أَرْض","grammar_bn":"শব্দ"},{"id":3013,"position":4,"text_uthmani":"وَهُم","transliteration":"wahum","translation_bn":"কিন্তু তারা","root":"—","lemma":"وَهُم","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":3014,"position":5,"text_uthmani":"مِّنۢ","transliteration":"min","translation_bn":"থেকে","root":"—","lemma":"مِن\r","grammar_bn":"অব্যয় (Preposition)"},{"id":3015,"position":6,"text_uthmani":"بَعْدِ","transliteration":"baʿdi","translation_bn":"পর","root":"بعد","lemma":"بَعْد","grammar_bn":"বিশেষ্য (Noun)"},{"id":3016,"position":7,"text_uthmani":"غَلَبِهِمْ","transliteration":"ghalabihim","translation_bn":"পরাজয়ের তাদের","root":"غلب","lemma":"غَلَب","grammar_bn":"বিশেষ্য (Noun)"},{"id":3017,"position":8,"text_uthmani":"سَيَغْلِبُونَ","transliteration":"sayaghlibūna","translation_bn":"শীঘ্রই জয়লাভ করবে","root":"غلب","lemma":"غَلَبُ","grammar_bn":"ভবিষ্যদ্বাচক (Future)"},{"id":3018,"position":9,"text_uthmani":"٣","transliteration":"","translation_bn":"(৩)","root":"—","lemma":"٣","grammar_bn":"মার্কার"}]'::jsonb, 'fī adnā l-arḍi wahum min baʿdi ghalabihim sayaghlibūna', 'নিকটস্থ ভূমিতে, কিন্তু তারা তাদের পরাজয়ের পর শীঘ্রই জয়লাভ করবে।', 'In the nearest land. But they, after their defeat, will overcome.', 'নিকটস্থ ভূমিতে, কিন্তু তারা তাদের পরাজয়ের পর শীঘ্রই জয়লাভ করবে।', 'In the nearest land. But they, after their defeat, will overcome.', NULL, NULL, NULL, NULL, NULL, 'https://everyayah.com/data/Alafasy_128kbps/030003.mp3', now()),
  (30, 4, '', '[{"id":4341,"position":1,"text_uthmani":"فِى","transliteration":"fī","translation_bn":"মধ্যে","root":"—","lemma":"فِى\r","grammar_bn":"অব্যয় (Preposition)"},{"id":4342,"position":2,"text_uthmani":"بِضْعِ","transliteration":"biḍ''ʿi","translation_bn":"কয়েক","root":"بضع","lemma":"بِضْع","grammar_bn":"বিশেষ্য (Noun)"},{"id":4343,"position":3,"text_uthmani":"سِنِينَ ۗ","transliteration":"sinīna","translation_bn":"বছরের","root":"سنو","lemma":"سِنِين","grammar_bn":"বিশেষ্য (Noun)"},{"id":4345,"position":4,"text_uthmani":"لِلَّهِ","transliteration":"lillahi","translation_bn":"জন্যে আল্লাহরই","root":"اله","lemma":"ٱللَّه","grammar_bn":"অব্যয় (Preposition)"},{"id":4346,"position":5,"text_uthmani":"ٱلْأَمْرُ","transliteration":"l-amru","translation_bn":"সিদ্ধান্ত","root":"امر","lemma":"أَمْر","grammar_bn":"শব্দ"},{"id":4347,"position":6,"text_uthmani":"مِن","transliteration":"min","translation_bn":"এর","root":"—","lemma":"مِن\r","grammar_bn":"অব্যয় (Preposition)"},{"id":4348,"position":7,"text_uthmani":"قَبْلُ","transliteration":"qablu","translation_bn":"পূর্ব","root":"قبل","lemma":"قَبْل","grammar_bn":"বিশেষ্য (Noun)"},{"id":4349,"position":8,"text_uthmani":"وَمِنۢ","transliteration":"wamin","translation_bn":"এবং এর","root":"—","lemma":"مِن\r","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":4350,"position":9,"text_uthmani":"بَعْدُ ۚ","transliteration":"baʿdu","translation_bn":"এবং পরও","root":"بعد","lemma":"بَعْد","grammar_bn":"বিশেষ্য (Noun)"},{"id":4352,"position":10,"text_uthmani":"وَيَوْمَئِذٍۢ","transliteration":"wayawma-idhin","translation_bn":"এবং সেদিন","root":"—","lemma":"يَوْمَئِذ\r","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":4353,"position":11,"text_uthmani":"يَفْرَحُ","transliteration":"yafraḥu","translation_bn":"উৎফুল্ল হবে","root":"فرح","lemma":"فَرِحَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":4354,"position":12,"text_uthmani":"ٱلْمُؤْمِنُونَ","transliteration":"l-mu''minūna","translation_bn":"মু''মিনরা","root":"امن","lemma":"مُؤْمِن","grammar_bn":"শব্দ"},{"id":4355,"position":13,"text_uthmani":"٤","transliteration":"","translation_bn":"(৪)","root":"—","lemma":"٤","grammar_bn":"মার্কার"}]'::jsonb, 'fī biḍ''ʿi sinīna lillahi l-amru min qablu wamin baʿdu wayawma-idhin yafraḥu l-mu''minūna', 'কয়েক (তিন থেকে নয়) বছরের মধ্যেই; (কোন্ কাজ হবে) আগে ও (কোন্ কাজ হবে) পরে সে ফয়সালা আল্লাহরই। সেদিন মু’মিনরা আনন্দ করবে।', 'Within three to nine years. To Allah belongs the command before and after. And that day the believers will rejoice', 'কয়েক (তিন থেকে নয়) বছরের মধ্যেই; (কোন্ কাজ হবে) আগে ও (কোন্ কাজ হবে) পরে সে ফয়সালা আল্লাহরই। সেদিন মু’মিনরা আনন্দ করবে।', 'Within three to nine years. To Allah belongs the command before and after. And that day the believers will rejoice', NULL, NULL, NULL, NULL, NULL, 'https://everyayah.com/data/Alafasy_128kbps/030004.mp3', now()),
  (30, 5, '', '[{"id":5617,"position":1,"text_uthmani":"بِنَصْرِ","transliteration":"binaṣri","translation_bn":"মাধ্যমে সাহায্যের","root":"نصر","lemma":"نَصْر","grammar_bn":"অব্যয় (Preposition)"},{"id":5618,"position":2,"text_uthmani":"ٱللَّهِ ۚ","transliteration":"l-lahi","translation_bn":"আল্লাহর","root":"اله","lemma":"ٱللَّه","grammar_bn":"নামবাচক বিশেষ্য (Proper Noun)"},{"id":5620,"position":3,"text_uthmani":"يَنصُرُ","transliteration":"yanṣuru","translation_bn":"তিনি সাহায্য করেন","root":"نصر","lemma":"نَصَرَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":5621,"position":4,"text_uthmani":"مَن","transliteration":"man","translation_bn":"যাকে","root":"—","lemma":"مَن\r","grammar_bn":"সাপেক্ষ সর্বনাম (Relative)"},{"id":5622,"position":5,"text_uthmani":"يَشَآءُ ۖ","transliteration":"yashāu","translation_bn":"তিনি চান","root":"شيا","lemma":"شَا^ءَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":5624,"position":6,"text_uthmani":"وَهُوَ","transliteration":"wahuwa","translation_bn":"এবং তিনিই","root":"—","lemma":"وَهُوَ","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":5625,"position":7,"text_uthmani":"ٱلْعَزِيزُ","transliteration":"l-ʿazīzu","translation_bn":"পরাক্রমশালী","root":"عزز","lemma":"عَزِيز","grammar_bn":"শব্দ"},{"id":5626,"position":8,"text_uthmani":"ٱلرَّحِيمُ","transliteration":"l-raḥīmu","translation_bn":"পরম দয়ালু","root":"رحم","lemma":"رَّحِيم","grammar_bn":"শব্দ"},{"id":5627,"position":9,"text_uthmani":"٥","transliteration":"","translation_bn":"(৫)","root":"—","lemma":"٥","grammar_bn":"মার্কার"}]'::jsonb, 'binaṣri l-lahi yanṣuru man yashāu wahuwa l-ʿazīzu l-raḥīmu', '(সে বিজয় অর্জিত হবে) আল্লাহর সাহায্যে। যাকে ইচ্ছে তিনি সাহায্য করেন, তিনি মহাপরাক্রমশালী, বড়ই দয়ালু।', 'In the victory of Allah. He gives victory to whom He wills, and He is the Exalted in Might, the Merciful.', '(সে বিজয় অর্জিত হবে) আল্লাহর সাহায্যে। যাকে ইচ্ছে তিনি সাহায্য করেন, তিনি মহাপরাক্রমশালী, বড়ই দয়ালু।', 'In the victory of Allah. He gives victory to whom He wills, and He is the Exalted in Might, the Merciful.', NULL, NULL, NULL, NULL, NULL, 'https://everyayah.com/data/Alafasy_128kbps/030005.mp3', now()),
  (30, 6, '', '[{"id":6892,"position":1,"text_uthmani":"وَعْدَ","transliteration":"waʿda","translation_bn":"(এটা)প্রতিশ্রুতি","root":"وعد","lemma":"وَعْد","grammar_bn":"বিশেষ্য (Noun)"},{"id":6893,"position":2,"text_uthmani":"ٱللَّهِ ۖ","transliteration":"l-lahi","translation_bn":"আল্লাহর","root":"اله","lemma":"ٱللَّه","grammar_bn":"নামবাচক বিশেষ্য (Proper Noun)"},{"id":6895,"position":3,"text_uthmani":"لَا","transliteration":"lā","translation_bn":"না","root":"—","lemma":"لَا\r","grammar_bn":"না-বোধক (Negative)"},{"id":6896,"position":4,"text_uthmani":"يُخْلِفُ","transliteration":"yukh''lifu","translation_bn":"ভঙ্গ করেন","root":"خلف","lemma":"أَخْلَفُ","grammar_bn":"ক্রিয়া (Verb)"},{"id":6897,"position":5,"text_uthmani":"ٱللَّهُ","transliteration":"l-lahu","translation_bn":"আল্লাহ","root":"اله","lemma":"ٱللَّه","grammar_bn":"নামবাচক বিশেষ্য (Proper Noun)"},{"id":6898,"position":6,"text_uthmani":"وَعْدَهُۥ","transliteration":"waʿdahu","translation_bn":"প্রতিশ্রুতি তাঁর","root":"وعد","lemma":"وَعْد","grammar_bn":"বিশেষ্য (Noun)"},{"id":6899,"position":7,"text_uthmani":"وَلَـٰكِنَّ","transliteration":"walākinna","translation_bn":"কিন্তু","root":"—","lemma":"لَٰكِنّ","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":6900,"position":8,"text_uthmani":"أَكْثَرَ","transliteration":"akthara","translation_bn":"অধিকাংশ","root":"كثر","lemma":"أَكْثَر","grammar_bn":"বিশেষ্য (Noun)"},{"id":6901,"position":9,"text_uthmani":"ٱلنَّاسِ","transliteration":"l-nāsi","translation_bn":"মানুষ","root":"نوس","lemma":"نَّاس","grammar_bn":"শব্দ"},{"id":6902,"position":10,"text_uthmani":"لَا","transliteration":"lā","translation_bn":"না","root":"—","lemma":"لَا\r","grammar_bn":"না-বোধক (Negative)"},{"id":6903,"position":11,"text_uthmani":"يَعْلَمُونَ","transliteration":"yaʿlamūna","translation_bn":"তারা জানে","root":"علم","lemma":"عَلِمَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":6904,"position":12,"text_uthmani":"٦","transliteration":"","translation_bn":"(৬)","root":"—","lemma":"٦","grammar_bn":"মার্কার"}]'::jsonb, 'waʿda l-lahi lā yukh''lifu l-lahu waʿdahu walākinna akthara l-nāsi lā yaʿlamūna', 'এটা আল্লাহর ও‘য়াদা, আল্লাহ তাঁর ও‘য়াদার ব্যতিক্রম করেন না, কিন্তু অধিকাংশ লোকই জানে না।', '[It is] the promise of Allah. Allah does not fail in His promise, but most of the people do not know.', 'এটা আল্লাহর ও‘য়াদা, আল্লাহ তাঁর ও‘য়াদার ব্যতিক্রম করেন না, কিন্তু অধিকাংশ লোকই জানে না।', '[It is] the promise of Allah. Allah does not fail in His promise, but most of the people do not know.', NULL, NULL, NULL, NULL, NULL, 'https://everyayah.com/data/Alafasy_128kbps/030006.mp3', now()),
  (30, 7, '', '[{"id":8222,"position":1,"text_uthmani":"يَعْلَمُونَ","transliteration":"yaʿlamūna","translation_bn":"(কেবল) তারা জানে","root":"علم","lemma":"عَلِمَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":8223,"position":2,"text_uthmani":"ظَـٰهِرًۭا","transliteration":"ẓāhiran","translation_bn":"বাহ্যিক দিক","root":"ظهر","lemma":"ظَٰهِر","grammar_bn":"বিশেষ্য (Noun)"},{"id":8224,"position":3,"text_uthmani":"مِّنَ","transliteration":"mina","translation_bn":"থেকে","root":"—","lemma":"مِن\r","grammar_bn":"অব্যয় (Preposition)"},{"id":8225,"position":4,"text_uthmani":"ٱلْحَيَوٰةِ","transliteration":"l-ḥayati","translation_bn":"জীবনের","root":"حيي","lemma":"حَيَوٰة","grammar_bn":"শব্দ"},{"id":8226,"position":5,"text_uthmani":"ٱلدُّنْيَا","transliteration":"l-dun''yā","translation_bn":"পার্থিব","root":"دنو","lemma":"دُّنْيَا","grammar_bn":"শব্দ"},{"id":8227,"position":6,"text_uthmani":"وَهُمْ","transliteration":"wahum","translation_bn":"আর তারা","root":"—","lemma":"وَهُمْ","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":8228,"position":7,"text_uthmani":"عَنِ","transliteration":"ʿani","translation_bn":"সম্পর্কে","root":"—","lemma":"عَن\r","grammar_bn":"অব্যয় (Preposition)"},{"id":8229,"position":8,"text_uthmani":"ٱلْـَٔاخِرَةِ","transliteration":"l-ākhirati","translation_bn":"আখেরাত","root":"اخر","lemma":"ا^خِر","grammar_bn":"শব্দ"},{"id":8230,"position":9,"text_uthmani":"هُمْ","transliteration":"hum","translation_bn":"তারা","root":"—","lemma":"هُمْ","grammar_bn":"সর্বনাম (Pronoun)"},{"id":8231,"position":10,"text_uthmani":"غَـٰفِلُونَ","transliteration":"ghāfilūna","translation_bn":"অমনোযোগী","root":"غفل","lemma":"غَٰفِل","grammar_bn":"বিশেষ্য (Noun)"},{"id":8232,"position":11,"text_uthmani":"٧","transliteration":"","translation_bn":"(৭)","root":"—","lemma":"٧","grammar_bn":"মার্কার"}]'::jsonb, 'yaʿlamūna ẓāhiran mina l-ḥayati l-dun''yā wahum ʿani l-ākhirati hum ghāfilūna', 'তারা পার্থিব জীবনের বাহ্যিক দিক জানে, আর তারা পরকালের খবর রাখে না।', 'They know what is apparent of the worldly life, but they, of the Hereafter, are unaware.', 'তারা পার্থিব জীবনের বাহ্যিক দিক জানে, আর তারা পরকালের খবর রাখে না।', 'They know what is apparent of the worldly life, but they, of the Hereafter, are unaware.', NULL, NULL, NULL, NULL, NULL, 'https://everyayah.com/data/Alafasy_128kbps/030007.mp3', now()),
  (30, 8, '', '[{"id":9385,"position":1,"text_uthmani":"أَوَلَمْ","transliteration":"awalam","translation_bn":"কি না","root":"—","lemma":"لَم\r","grammar_bn":"প্রশ্নবোধক (Interrogative)"},{"id":9386,"position":2,"text_uthmani":"يَتَفَكَّرُوا۟","transliteration":"yatafakkarū","translation_bn":"তারা চিন্তা করে (মনের)","root":"فكر","lemma":"يَتَفَكَّرُ","grammar_bn":"ক্রিয়া (Verb)"},{"id":9387,"position":3,"text_uthmani":"فِىٓ","transliteration":"fī","translation_bn":"মধ্যে","root":"—","lemma":"فِى\r","grammar_bn":"অব্যয় (Preposition)"},{"id":9388,"position":4,"text_uthmani":"أَنفُسِهِم ۗ","transliteration":"anfusihim","translation_bn":"নিজেদের তাদের","root":"نفس","lemma":"نَفْس","grammar_bn":"বিশেষ্য (Noun)"},{"id":9390,"position":5,"text_uthmani":"مَّا","transliteration":"mā","translation_bn":"না","root":"—","lemma":"مَا\r","grammar_bn":"না-বোধক (Negative)"},{"id":9391,"position":6,"text_uthmani":"خَلَقَ","transliteration":"khalaqa","translation_bn":"সৃষ্টি করেছেন","root":"خلق","lemma":"خَلَقَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":9392,"position":7,"text_uthmani":"ٱللَّهُ","transliteration":"l-lahu","translation_bn":"আল্লাহ্‌","root":"اله","lemma":"ٱللَّه","grammar_bn":"নামবাচক বিশেষ্য (Proper Noun)"},{"id":9393,"position":8,"text_uthmani":"ٱلسَّمَـٰوَٰتِ","transliteration":"l-samāwāti","translation_bn":"আকাশমন্ডলী","root":"سمو","lemma":"سَمَا^ء","grammar_bn":"শব্দ"},{"id":9394,"position":9,"text_uthmani":"وَٱلْأَرْضَ","transliteration":"wal-arḍa","translation_bn":"ও পৃথিবী","root":"ارض","lemma":"أَرْض","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":9395,"position":10,"text_uthmani":"وَمَا","transliteration":"wamā","translation_bn":"এবং যা (আছে)","root":"—","lemma":"مَا\r","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":9396,"position":11,"text_uthmani":"بَيْنَهُمَآ","transliteration":"baynahumā","translation_bn":"দু''য়ের মাঝে তাদের","root":"بين","lemma":"بَيْن","grammar_bn":"স্থানবাচক (Location)"},{"id":9397,"position":12,"text_uthmani":"إِلَّا","transliteration":"illā","translation_bn":"ছাড়া","root":"—","lemma":"إِلَّا\r","grammar_bn":"সীমাবদ্ধতা (Restriction)"},{"id":9398,"position":13,"text_uthmani":"بِٱلْحَقِّ","transliteration":"bil-ḥaqi","translation_bn":"ভাবে যথাযথ","root":"حقق","lemma":"حَقّ","grammar_bn":"অব্যয় (Preposition)"},{"id":9399,"position":14,"text_uthmani":"وَأَجَلٍۢ","transliteration":"wa-ajalin","translation_bn":"এবং একটি কালের (জন্যে)","root":"اجل","lemma":"أَجَل","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":9400,"position":15,"text_uthmani":"مُّسَمًّۭى ۗ","transliteration":"musamman","translation_bn":"নির্দিষ্ট","root":"سمو","lemma":"مُّسَمًّى","grammar_bn":"বিশেষ্য (Noun)"},{"id":9402,"position":16,"text_uthmani":"وَإِنَّ","transliteration":"wa-inna","translation_bn":"এবং নিশ্চয়ই","root":"—","lemma":"إِنّ","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":9403,"position":17,"text_uthmani":"كَثِيرًۭا","transliteration":"kathīran","translation_bn":"অধিকাংশ","root":"كثر","lemma":"كَثِير","grammar_bn":"বিশেষ্য (Noun)"},{"id":9404,"position":18,"text_uthmani":"مِّنَ","transliteration":"mina","translation_bn":"মধ্যে","root":"—","lemma":"مِن\r","grammar_bn":"অব্যয় (Preposition)"},{"id":9405,"position":19,"text_uthmani":"ٱلنَّاسِ","transliteration":"l-nāsi","translation_bn":"মানুষের","root":"نوس","lemma":"نَّاس","grammar_bn":"শব্দ"},{"id":9406,"position":20,"text_uthmani":"بِلِقَآئِ","transliteration":"biliqāi","translation_bn":"সম্পর্কে সাক্ষাৎ","root":"لقي","lemma":"لِقَا^ء","grammar_bn":"অব্যয় (Preposition)"},{"id":9407,"position":21,"text_uthmani":"رَبِّهِمْ","transliteration":"rabbihim","translation_bn":"রবের তাদের","root":"ربب","lemma":"رَبّ","grammar_bn":"বিশেষ্য (Noun)"},{"id":9408,"position":22,"text_uthmani":"لَكَـٰفِرُونَ","transliteration":"lakāfirūna","translation_bn":"অবশ্যই অস্বীকারকারী","root":"كفر","lemma":"كَٰفِرُون","grammar_bn":"দৃঢ়তাবোধক (Emphatic)"},{"id":9409,"position":23,"text_uthmani":"٨","transliteration":"","translation_bn":"(৮)","root":"—","lemma":"٨","grammar_bn":"মার্কার"}]'::jsonb, 'awalam yatafakkarū fī anfusihim mā khalaqa l-lahu l-samāwāti wal-arḍa wamā baynahumā illā bil-ḥaqi wa-ajalin musamman wa-inna kathīran mina l-nāsi biliqāi rabbihim lakāfirūna', 'তারা কি তাদের মনে ভেবে দেখে না যে, আল্লাহ আকাশমন্ডলী, পৃথিবী ও এ দু’এর মধ্যবর্তী সবকিছু সৃষ্টি করেছেন যথাযথভাবে ও নির্দিষ্ট কালের জন্য, কিন্তু অনেক মানুষ তাদের প্রতিপালকের সাক্ষাতে নিশ্চিতই অবিশ্বাসী।', 'Do they not contemplate within themselves? Allah has not created the heavens and the earth and what is between them except in truth and for a specified term. And indeed, many of the people, in [the matter of] the meeting with their Lord, are disbelievers.', 'তারা কি তাদের মনে ভেবে দেখে না যে, আল্লাহ আকাশমন্ডলী, পৃথিবী ও এ দু’এর মধ্যবর্তী সবকিছু সৃষ্টি করেছেন যথাযথভাবে ও নির্দিষ্ট কালের জন্য, কিন্তু অনেক মানুষ তাদের প্রতিপালকের সাক্ষাতে নিশ্চিতই অবিশ্বাসী।', 'Do they not contemplate within themselves? Allah has not created the heavens and the earth and what is between them except in truth and for a specified term. And indeed, many of the people, in [the matter of] the meeting with their Lord, are disbelievers.', NULL, NULL, NULL, NULL, NULL, 'https://everyayah.com/data/Alafasy_128kbps/030008.mp3', now()),
