  (30, 15, '', '[{"id":17755,"position":1,"text_uthmani":"فَأَمَّا","transliteration":"fa-ammā","translation_bn":"অতঃপর (তাদের) ব্যাপার","root":"—","lemma":"أَمَّا\r","grammar_bn":"শব্দ"},{"id":17756,"position":2,"text_uthmani":"ٱلَّذِينَ","transliteration":"alladhīna","translation_bn":"যারা","root":"—","lemma":"ٱلَّذِى","grammar_bn":"শর্তবাচক (Conditional)"},{"id":17757,"position":3,"text_uthmani":"ءَامَنُوا۟","transliteration":"āmanū","translation_bn":"ঈমান এনেছে","root":"امن","lemma":"ءَامَنَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":17758,"position":4,"text_uthmani":"وَعَمِلُوا۟","transliteration":"waʿamilū","translation_bn":"ও কাজ করেছে","root":"عمل","lemma":"عَمِلَ","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":17759,"position":5,"text_uthmani":"ٱلصَّـٰلِحَـٰتِ","transliteration":"l-ṣāliḥāti","translation_bn":"সৎ","root":"صلح","lemma":"صَّٰلِحَٰت","grammar_bn":"শব্দ"},{"id":17760,"position":6,"text_uthmani":"فَهُمْ","transliteration":"fahum","translation_bn":"তখন তারা","root":"—","lemma":"فَهُمْ","grammar_bn":"শব্দ"},{"id":17761,"position":7,"text_uthmani":"فِى","transliteration":"fī","translation_bn":"(হবে) মধ্যে","root":"—","lemma":"فِى\r","grammar_bn":"অব্যয় (Preposition)"},{"id":17762,"position":8,"text_uthmani":"رَوْضَةٍۢ","transliteration":"rawḍatin","translation_bn":"বাগানের","root":"روض","lemma":"رَوْضَة","grammar_bn":"বিশেষ্য (Noun)"},{"id":17763,"position":9,"text_uthmani":"يُحْبَرُونَ","transliteration":"yuḥ''barūna","translation_bn":"আনন্দ করবে","root":"حبر","lemma":"يُحْبَرُ","grammar_bn":"ক্রিয়া (Verb)"},{"id":17764,"position":10,"text_uthmani":"١٥","transliteration":"","translation_bn":"(১৫)","root":"—","lemma":"١٥","grammar_bn":"মার্কার"}]'::jsonb, 'fa-ammā alladhīna āmanū waʿamilū l-ṣāliḥāti fahum fī rawḍatin yuḥ''barūna', 'অতঃপর যারা ঈমান এনেছে ও সৎ কাজ করেছে তাদেরকে জান্নাত দিয়ে পরিতুষ্ট করা হবে।', 'And as for those who had believed and done righteous deeds, they will be in a garden [of Paradise], delighted.', 'অতঃপর যারা ঈমান এনেছে ও সৎ কাজ করেছে তাদেরকে জান্নাত দিয়ে পরিতুষ্ট করা হবে।', 'And as for those who had believed and done righteous deeds, they will be in a garden [of Paradise], delighted.', NULL, NULL, NULL, NULL, NULL, 'https://everyayah.com/data/Alafasy_128kbps/030015.mp3', now()),
  (30, 16, '', '[{"id":18765,"position":1,"text_uthmani":"وَأَمَّا","transliteration":"wa-ammā","translation_bn":"আর (তাদের) ব্যাপার","root":"—","lemma":"أَمَّا\r","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":18766,"position":2,"text_uthmani":"ٱلَّذِينَ","transliteration":"alladhīna","translation_bn":"যারা","root":"—","lemma":"ٱلَّذِى","grammar_bn":"শর্তবাচক (Conditional)"},{"id":18767,"position":3,"text_uthmani":"كَفَرُوا۟","transliteration":"kafarū","translation_bn":"অস্বীকার করেছে","root":"كفر","lemma":"كَفَرَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":18768,"position":4,"text_uthmani":"وَكَذَّبُوا۟","transliteration":"wakadhabū","translation_bn":"ও মিথ্যারোপ করেছে","root":"كذب","lemma":"كَذَّبَ","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":18769,"position":5,"text_uthmani":"بِـَٔايَـٰتِنَا","transliteration":"biāyātinā","translation_bn":"প্রতি নিদর্শনাবলীর আমাদের","root":"ايي","lemma":"ءَايَة","grammar_bn":"অব্যয় (Preposition)"},{"id":18770,"position":6,"text_uthmani":"وَلِقَآئِ","transliteration":"waliqāi","translation_bn":"ও সাক্ষাতকে","root":"لقي","lemma":"لِقَا^ء","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":18771,"position":7,"text_uthmani":"ٱلْـَٔاخِرَةِ","transliteration":"l-ākhirati","translation_bn":"পরকালের","root":"اخر","lemma":"ا^خِر","grammar_bn":"শব্দ"},{"id":18772,"position":8,"text_uthmani":"فَأُو۟لَـٰٓئِكَ","transliteration":"fa-ulāika","translation_bn":"তখন ঐসব (লোককে)","root":"—","lemma":"أُولَٰ^ئِك","grammar_bn":"শব্দ"},{"id":18773,"position":9,"text_uthmani":"فِى","transliteration":"fī","translation_bn":"মধ্যে","root":"—","lemma":"فِى\r","grammar_bn":"অব্যয় (Preposition)"},{"id":18774,"position":10,"text_uthmani":"ٱلْعَذَابِ","transliteration":"l-ʿadhābi","translation_bn":"শাস্তির","root":"عذب","lemma":"عَذَاب","grammar_bn":"শব্দ"},{"id":18775,"position":11,"text_uthmani":"مُحْضَرُونَ","transliteration":"muḥ''ḍarūna","translation_bn":"উপস্থিত করা হবে","root":"حضر","lemma":"مُّحْضَر","grammar_bn":"বিশেষ্য (Noun)"},{"id":18776,"position":12,"text_uthmani":"١٦","transliteration":"","translation_bn":"(১৬)","root":"—","lemma":"١٦","grammar_bn":"মার্কার"}]'::jsonb, 'wa-ammā alladhīna kafarū wakadhabū biāyātinā waliqāi l-ākhirati fa-ulāika fī l-ʿadhābi muḥ''ḍarūna', 'আর যারা কুফুরী করেছে এবং আমার নিদর্শনাবলী ও আখিরাতের সাক্ষাৎকে অস্বীকার করেছে, তাদেরকে ‘আযাবের মধ্যে উপস্থিত করা হবে।', 'But as for those who disbelieved and denied Our verses and the meeting of the Hereafter, those will be brought into the punishment [to remain].', 'আর যারা কুফুরী করেছে এবং আমার নিদর্শনাবলী ও আখিরাতের সাক্ষাৎকে অস্বীকার করেছে, তাদেরকে ‘আযাবের মধ্যে উপস্থিত করা হবে।', 'But as for those who disbelieved and denied Our verses and the meeting of the Hereafter, those will be brought into the punishment [to remain].', NULL, NULL, NULL, NULL, NULL, 'https://everyayah.com/data/Alafasy_128kbps/030016.mp3', now()),
  (30, 17, '', '[{"id":19873,"position":1,"text_uthmani":"فَسُبْحَـٰنَ","transliteration":"fasub''ḥāna","translation_bn":"অতএব মহিমা ঘোষণা করো","root":"سبح","lemma":"سُبْحَٰن","grammar_bn":"শব্দ"},{"id":19874,"position":2,"text_uthmani":"ٱللَّهِ","transliteration":"l-lahi","translation_bn":"আল্লাহর","root":"اله","lemma":"ٱللَّه","grammar_bn":"নামবাচক বিশেষ্য (Proper Noun)"},{"id":19875,"position":3,"text_uthmani":"حِينَ","transliteration":"ḥīna","translation_bn":"যখন","root":"حين","lemma":"حِين","grammar_bn":"বিশেষ্য (Noun)"},{"id":19876,"position":4,"text_uthmani":"تُمْسُونَ","transliteration":"tum''sūna","translation_bn":"তোমরা সন্ধ্যা করো(অর্থাৎ মাগরিব হয়)","root":"مسو","lemma":"تُمْسُ","grammar_bn":"ক্রিয়া (Verb)"},{"id":19877,"position":5,"text_uthmani":"وَحِينَ","transliteration":"waḥīna","translation_bn":"ও যখন","root":"حين","lemma":"حِين","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":19878,"position":6,"text_uthmani":"تُصْبِحُونَ","transliteration":"tuṣ''biḥūna","translation_bn":"তোমরা সকাল করো (অর্থাৎ ফজর হয়)","root":"صبح","lemma":"أَصْبَحَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":19879,"position":7,"text_uthmani":"١٧","transliteration":"","translation_bn":"(১৭)","root":"—","lemma":"١٧","grammar_bn":"মার্কার"}]'::jsonb, 'fasub''ḥāna l-lahi ḥīna tum''sūna waḥīna tuṣ''biḥūna', 'অতএব তোমরা আল্লাহর পবিত্রতা ও মহিমা ঘোষণা কর যখন তোমরা সন্ধ্যায় উপনীত হও আর সকালে,', 'So exalted is Allah when you reach the evening and when you reach the morning.', 'অতএব তোমরা আল্লাহর পবিত্রতা ও মহিমা ঘোষণা কর যখন তোমরা সন্ধ্যায় উপনীত হও আর সকালে,', 'So exalted is Allah when you reach the evening and when you reach the morning.', NULL, NULL, NULL, NULL, NULL, 'https://everyayah.com/data/Alafasy_128kbps/030017.mp3', now()),
  (30, 18, '', '[{"id":20927,"position":1,"text_uthmani":"وَلَهُ","transliteration":"walahu","translation_bn":"এবং জন্যে  তাঁরই","root":"—","lemma":"وَلَهُ","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":20928,"position":2,"text_uthmani":"ٱلْحَمْدُ","transliteration":"l-ḥamdu","translation_bn":"সকল প্রশংসা","root":"حمد","lemma":"حَمْد","grammar_bn":"শব্দ"},{"id":20929,"position":3,"text_uthmani":"فِى","transliteration":"fī","translation_bn":"মধ্যে","root":"—","lemma":"فِى\r","grammar_bn":"অব্যয় (Preposition)"},{"id":20930,"position":4,"text_uthmani":"ٱلسَّمَـٰوَٰتِ","transliteration":"l-samāwāti","translation_bn":"আকাশ মন্ডলীর","root":"سمو","lemma":"سَمَا^ء","grammar_bn":"শব্দ"},{"id":20931,"position":5,"text_uthmani":"وَٱلْأَرْضِ","transliteration":"wal-arḍi","translation_bn":"ও পৃথিবীতে","root":"ارض","lemma":"أَرْض","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":20932,"position":6,"text_uthmani":"وَعَشِيًّۭا","transliteration":"waʿashiyyan","translation_bn":"এবং (মহিমা ঘোষণা করো) বিকেলে  (অর্থাৎ আসরে)","root":"عشو","lemma":"عَشِىّ","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":20933,"position":7,"text_uthmani":"وَحِينَ","transliteration":"waḥīna","translation_bn":"ও যখন","root":"حين","lemma":"حِين","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":20934,"position":8,"text_uthmani":"تُظْهِرُونَ","transliteration":"tuẓ''hirūna","translation_bn":"তোমরা দুপুরে উপনীত হও","root":"ظهر","lemma":"أَظْهَرَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":20935,"position":9,"text_uthmani":"١٨","transliteration":"","translation_bn":"(১৮)","root":"—","lemma":"١٨","grammar_bn":"মার্কার"}]'::jsonb, 'walahu l-ḥamdu fī l-samāwāti wal-arḍi waʿashiyyan waḥīna tuẓ''hirūna', 'এবং অপরাহ্নে ও যুহরের সময়ে; আর আসমানসমূহে ও যমীনে প্রশংসা তো একমাত্র তাঁরই।', 'And to Him is [due all] praise throughout the heavens and the earth. And [exalted is He] at night and when you are at noon.', 'এবং অপরাহ্নে ও যুহরের সময়ে; আর আসমানসমূহে ও যমীনে প্রশংসা তো একমাত্র তাঁরই।', 'And to Him is [due all] praise throughout the heavens and the earth. And [exalted is He] at night and when you are at noon.', NULL, NULL, NULL, NULL, NULL, 'https://everyayah.com/data/Alafasy_128kbps/030018.mp3', now()),
  (30, 19, '', '[{"id":22048,"position":1,"text_uthmani":"يُخْرِجُ","transliteration":"yukh''riju","translation_bn":"তিনি বের করেন","root":"خرج","lemma":"أَخْرَجَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":22049,"position":2,"text_uthmani":"ٱلْحَىَّ","transliteration":"l-ḥaya","translation_bn":"জীবন্তকে","root":"حيي","lemma":"حَيّ","grammar_bn":"শব্দ"},{"id":22050,"position":3,"text_uthmani":"مِنَ","transliteration":"mina","translation_bn":"হ''তে","root":"—","lemma":"مِن\r","grammar_bn":"অব্যয় (Preposition)"},{"id":22051,"position":4,"text_uthmani":"ٱلْمَيِّتِ","transliteration":"l-mayiti","translation_bn":"মৃত","root":"موت","lemma":"مَّيِّت","grammar_bn":"শব্দ"},{"id":22052,"position":5,"text_uthmani":"وَيُخْرِجُ","transliteration":"wayukh''riju","translation_bn":"ও তিনি বের করেন","root":"خرج","lemma":"أَخْرَجَ","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":22053,"position":6,"text_uthmani":"ٱلْمَيِّتَ","transliteration":"l-mayita","translation_bn":"মৃতকে","root":"موت","lemma":"مَّيِّت","grammar_bn":"শব্দ"},{"id":22054,"position":7,"text_uthmani":"مِنَ","transliteration":"mina","translation_bn":"হ''তে","root":"—","lemma":"مِن\r","grammar_bn":"অব্যয় (Preposition)"},{"id":22055,"position":8,"text_uthmani":"ٱلْحَىِّ","transliteration":"l-ḥayi","translation_bn":"জীবন্ত","root":"حيي","lemma":"حَيّ","grammar_bn":"শব্দ"},{"id":22056,"position":9,"text_uthmani":"وَيُحْىِ","transliteration":"wayuḥ''yī","translation_bn":"এবং জীবিত করেন","root":"حيي","lemma":"أَحْيَا","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":22057,"position":10,"text_uthmani":"ٱلْأَرْضَ","transliteration":"l-arḍa","translation_bn":"পৃথিবীকে","root":"ارض","lemma":"أَرْض","grammar_bn":"শব্দ"},{"id":22058,"position":11,"text_uthmani":"بَعْدَ","transliteration":"baʿda","translation_bn":"পরে","root":"بعد","lemma":"بَعْد","grammar_bn":"কালবাচক (Time)"},{"id":22059,"position":12,"text_uthmani":"مَوْتِهَا ۚ","transliteration":"mawtihā","translation_bn":"মৃত্যুর তার","root":"موت","lemma":"مَوْت","grammar_bn":"বিশেষ্য (Noun)"},{"id":22061,"position":13,"text_uthmani":"وَكَذَٰلِكَ","transliteration":"wakadhālika","translation_bn":"এবং এরূপেই","root":"—","lemma":"ذَٰلِك","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":22062,"position":14,"text_uthmani":"تُخْرَجُونَ","transliteration":"tukh''rajūna","translation_bn":"তোমাদের বের করা হবে","root":"خرج","lemma":"أَخْرَجَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":22063,"position":15,"text_uthmani":"١٩","transliteration":"","translation_bn":"(১৯)","root":"—","lemma":"١٩","grammar_bn":"মার্কার"}]'::jsonb, 'yukh''riju l-ḥaya mina l-mayiti wayukh''riju l-mayita mina l-ḥayi wayuḥ''yī l-arḍa baʿda mawtihā wakadhālika tukh''rajūna', 'তিনিই জীবন্তকে বের করেন মৃত থেকে আর মৃতকে বের করেন জীবন্ত থেকে। যমীনকে তিনিই পুনরায় জীবিত করেন তার মৃত্যুর পর, এভাবেই তোমাদেরকে বের করা হবে।', 'He brings the living out of the dead and brings the dead out of the living and brings to life the earth after its lifelessness. And thus will you be brought out.', 'তিনিই জীবন্তকে বের করেন মৃত থেকে আর মৃতকে বের করেন জীবন্ত থেকে। যমীনকে তিনিই পুনরায় জীবিত করেন তার মৃত্যুর পর, এভাবেই তোমাদেরকে বের করা হবে।', 'He brings the living out of the dead and brings the dead out of the living and brings to life the earth after its lifelessness. And thus will you be brought out.', NULL, NULL, NULL, NULL, NULL, 'https://everyayah.com/data/Alafasy_128kbps/030019.mp3', now()),
  (30, 20, '', '[{"id":23106,"position":1,"text_uthmani":"وَمِنْ","transliteration":"wamin","translation_bn":"এবং মধ্যে (রয়েছে)","root":"—","lemma":"مِن\r","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":23107,"position":2,"text_uthmani":"ءَايَـٰتِهِۦٓ","transliteration":"āyātihi","translation_bn":"নিদর্শনাবলীর তাঁর","root":"ايي","lemma":"ءَايَة","grammar_bn":"বিশেষ্য (Noun)"},{"id":23108,"position":3,"text_uthmani":"أَنْ","transliteration":"an","translation_bn":"(এও) যে","root":"—","lemma":"أَن\r","grammar_bn":"অধীনস্থ যোজক (Subordinating)"},{"id":23109,"position":4,"text_uthmani":"خَلَقَكُم","transliteration":"khalaqakum","translation_bn":"তিনি সৃষ্টি করেছেন তোমাদেরকে","root":"خلق","lemma":"خَلَقَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":23110,"position":5,"text_uthmani":"مِّن","transliteration":"min","translation_bn":"হ''তে","root":"—","lemma":"مِن\r","grammar_bn":"অব্যয় (Preposition)"},{"id":23111,"position":6,"text_uthmani":"تُرَابٍۢ","transliteration":"turābin","translation_bn":"মাটি","root":"ترب","lemma":"تُرَاب","grammar_bn":"বিশেষ্য (Noun)"},{"id":23112,"position":7,"text_uthmani":"ثُمَّ","transliteration":"thumma","translation_bn":"এরপর","root":"—","lemma":"ثُمّ\r","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":23113,"position":8,"text_uthmani":"إِذَآ","transliteration":"idhā","translation_bn":"এখন","root":"—","lemma":"إِذَا\r","grammar_bn":"কালবাচক (Time)"},{"id":23114,"position":9,"text_uthmani":"أَنتُم","transliteration":"antum","translation_bn":"তোমরা","root":"—","lemma":"أَنتُم","grammar_bn":"সর্বনাম (Pronoun)"},{"id":23115,"position":10,"text_uthmani":"بَشَرٌۭ","transliteration":"basharun","translation_bn":"মানুষ (হিসেবে)","root":"بشر","lemma":"بَشَر","grammar_bn":"বিশেষ্য (Noun)"},{"id":23116,"position":11,"text_uthmani":"تَنتَشِرُونَ","transliteration":"tantashirūna","translation_bn":"তোমরা ছড়িয়ে পড়ছো","root":"نشر","lemma":"تَنتَشِرُ","grammar_bn":"ক্রিয়া (Verb)"},{"id":23117,"position":12,"text_uthmani":"٢٠","transliteration":"","translation_bn":"(২০)","root":"—","lemma":"٢٠","grammar_bn":"মার্কার"}]'::jsonb, 'wamin āyātihi an khalaqakum min turābin thumma idhā antum basharun tantashirūna', 'তাঁর নিদর্শনের মধ্যে হল এই যে, তিনি তোমাদেরকে মাটি থেকে সৃষ্টি করেছেন, অতঃপর তোমরা এখন মানুষ, সবখানে ছড়িয়ে রয়েছ।', 'And of His signs is that He created you from dust; then, suddenly you were human beings dispersing [throughout the earth].', 'তাঁর নিদর্শনের মধ্যে হল এই যে, তিনি তোমাদেরকে মাটি থেকে সৃষ্টি করেছেন, অতঃপর তোমরা এখন মানুষ, সবখানে ছড়িয়ে রয়েছ।', 'And of His signs is that He created you from dust; then, suddenly you were human beings dispersing [throughout the earth].', NULL, NULL, NULL, NULL, NULL, 'https://everyayah.com/data/Alafasy_128kbps/030020.mp3', now()),
  (30, 21, '', '[{"id":24108,"position":1,"text_uthmani":"وَمِنْ","transliteration":"wamin","translation_bn":"এবং মধ্য হ''তে","root":"—","lemma":"مِن\r","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":24109,"position":2,"text_uthmani":"ءَايَـٰتِهِۦٓ","transliteration":"āyātihi","translation_bn":"নিদর্শনাবলীর তাঁর","root":"ايي","lemma":"ءَايَة","grammar_bn":"বিশেষ্য (Noun)"},{"id":24110,"position":3,"text_uthmani":"أَنْ","transliteration":"an","translation_bn":"এও (যে)","root":"—","lemma":"أَن\r","grammar_bn":"অধীনস্থ যোজক (Subordinating)"},{"id":24111,"position":4,"text_uthmani":"خَلَقَ","transliteration":"khalaqa","translation_bn":"তিনি সৃষ্টি করেছেন","root":"خلق","lemma":"خَلَقَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":24112,"position":5,"text_uthmani":"لَكُم","transliteration":"lakum","translation_bn":"জন্যে তোমাদের","root":"—","lemma":"لَكُم","grammar_bn":"অব্যয় (Preposition)"},{"id":24113,"position":6,"text_uthmani":"مِّنْ","transliteration":"min","translation_bn":"মধ্যে হ''তে","root":"—","lemma":"مِن\r","grammar_bn":"অব্যয় (Preposition)"},{"id":24114,"position":7,"text_uthmani":"أَنفُسِكُمْ","transliteration":"anfusikum","translation_bn":"তোমাদের নিজেদের","root":"نفس","lemma":"نَفْس","grammar_bn":"বিশেষ্য (Noun)"},{"id":24115,"position":8,"text_uthmani":"أَزْوَٰجًۭا","transliteration":"azwājan","translation_bn":"স্ত্রীদেরকে","root":"زوج","lemma":"زَوْج","grammar_bn":"বিশেষ্য (Noun)"},{"id":24116,"position":9,"text_uthmani":"لِّتَسْكُنُوٓا۟","transliteration":"litaskunū","translation_bn":"যেন তোমরা প্রশান্তি পাও","root":"سكن","lemma":"سَكَنَ","grammar_bn":"শব্দ"},{"id":24117,"position":10,"text_uthmani":"إِلَيْهَا","transliteration":"ilayhā","translation_bn":"কাছে তাদের","root":"—","lemma":"إِلَىٰ\r","grammar_bn":"অব্যয় (Preposition)"},{"id":24118,"position":11,"text_uthmani":"وَجَعَلَ","transliteration":"wajaʿala","translation_bn":"এবং সৃষ্টি করেছেন","root":"جعل","lemma":"جَعَلَ","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":24119,"position":12,"text_uthmani":"بَيْنَكُم","transliteration":"baynakum","translation_bn":"মাঝে তোমাদের","root":"بين","lemma":"بَيْن","grammar_bn":"স্থানবাচক (Location)"},{"id":24120,"position":13,"text_uthmani":"مَّوَدَّةًۭ","transliteration":"mawaddatan","translation_bn":"সম্প্রীতি","root":"ودد","lemma":"مَّوَدَّة","grammar_bn":"বিশেষ্য (Noun)"},{"id":24121,"position":14,"text_uthmani":"وَرَحْمَةً ۚ","transliteration":"waraḥmatan","translation_bn":"ও দয়া","root":"رحم","lemma":"رَحْمَة","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":24123,"position":15,"text_uthmani":"إِنَّ","transliteration":"inna","translation_bn":"নিশ্চয়ই","root":"—","lemma":"إِنّ","grammar_bn":"অভিঘাত পদ (Accusative)"},{"id":24124,"position":16,"text_uthmani":"فِى","transliteration":"fī","translation_bn":"মধ্যে (রয়েছে)","root":"—","lemma":"فِى\r","grammar_bn":"অব্যয় (Preposition)"},{"id":24125,"position":17,"text_uthmani":"ذَٰلِكَ","transliteration":"dhālika","translation_bn":"এর","root":"—","lemma":"ذَٰلِك","grammar_bn":"নির্দেশক সর্বনাম (Demonstrative)"},{"id":24126,"position":18,"text_uthmani":"لَـَٔايَـٰتٍۢ","transliteration":"laāyātin","translation_bn":"অবশ্যই নির্দেশনাবলী","root":"ايي","lemma":"ءَايَة","grammar_bn":"দৃঢ়তাবোধক (Emphatic)"},{"id":24127,"position":19,"text_uthmani":"لِّقَوْمٍۢ","transliteration":"liqawmin","translation_bn":"জন্যে সম্প্রদায়ের","root":"قوم","lemma":"قَوْم","grammar_bn":"অব্যয় (Preposition)"},{"id":24128,"position":20,"text_uthmani":"يَتَفَكَّرُونَ","transliteration":"yatafakkarūna","translation_bn":"(যারা ) চিন্তা ভাবনা করে","root":"فكر","lemma":"يَتَفَكَّرُ","grammar_bn":"ক্রিয়া (Verb)"},{"id":24129,"position":21,"text_uthmani":"٢١","transliteration":"","translation_bn":"(২১)","root":"—","lemma":"٢١","grammar_bn":"মার্কার"}]'::jsonb, 'wamin āyātihi an khalaqa lakum min anfusikum azwājan litaskunū ilayhā wajaʿala baynakum mawaddatan waraḥmatan inna fī dhālika laāyātin liqawmin yatafakkarūna', 'তাঁর নিদর্শনের মধ্যে হল এই যে, তিনি তোমাদের জন্য তোমাদের মধ্য হতেই তোমাদের সঙ্গিণী সৃষ্টি করেছেন যাতে তোমরা তার কাছে শান্তি লাভ করতে পার আর তিনি তোমাদের মধ্যে পারস্পরিক ভালবাসা ও দয়া সৃষ্টি করেছেন। এর মাঝে অবশ্যই বহু নিদর্শন আছে সেই সম্প্রদায়ের জন্য যারা চিন্তা করে।', 'And of His signs is that He created for you from yourselves mates that you may find tranquillity in them; and He placed between you affection and mercy. Indeed in that are signs for a people who give thought.', 'তাঁর নিদর্শনের মধ্যে হল এই যে, তিনি তোমাদের জন্য তোমাদের মধ্য হতেই তোমাদের সঙ্গিণী সৃষ্টি করেছেন যাতে তোমরা তার কাছে শান্তি লাভ করতে পার আর তিনি তোমাদের মধ্যে পারস্পরিক ভালবাসা ও দয়া সৃষ্টি করেছেন। এর মাঝে অবশ্যই বহু নিদর্শন আছে সেই সম্প্রদায়ের জন্য যারা চিন্তা করে।', 'And of His signs is that He created for you from yourselves mates that you may find tranquillity in them; and He placed between you affection and mercy. Indeed in that are signs for a people who give thought.', NULL, NULL, NULL, NULL, NULL, 'https://everyayah.com/data/Alafasy_128kbps/030021.mp3', now()),
  (30, 22, '', '[{"id":25114,"position":1,"text_uthmani":"وَمِنْ","transliteration":"wamin","translation_bn":"এবং মধ্যে হ''তে","root":"—","lemma":"مِن\r","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":25115,"position":2,"text_uthmani":"ءَايَـٰتِهِۦ","transliteration":"āyātihi","translation_bn":"নিদর্শনাবলীর তাঁর","root":"ايي","lemma":"ءَايَة","grammar_bn":"বিশেষ্য (Noun)"},{"id":25116,"position":3,"text_uthmani":"خَلْقُ","transliteration":"khalqu","translation_bn":"সৃষ্টি","root":"خلق","lemma":"خَلْق","grammar_bn":"বিশেষ্য (Noun)"},{"id":25117,"position":4,"text_uthmani":"ٱلسَّمَـٰوَٰتِ","transliteration":"l-samāwāti","translation_bn":"আকাশমন্ডলীর","root":"سمو","lemma":"سَمَا^ء","grammar_bn":"শব্দ"},{"id":25118,"position":5,"text_uthmani":"وَٱلْأَرْضِ","transliteration":"wal-arḍi","translation_bn":"ও পৃথিবীর","root":"ارض","lemma":"أَرْض","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":25119,"position":6,"text_uthmani":"وَٱخْتِلَـٰفُ","transliteration":"wa-ikh''tilāfu","translation_bn":"এবং বৈচিত্র্য","root":"خلف","lemma":"ٱخْتِلَٰف","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":25120,"position":7,"text_uthmani":"أَلْسِنَتِكُمْ","transliteration":"alsinatikum","translation_bn":"ভাষাসমূহের তোমাদের","root":"لسن","lemma":"لِسَان","grammar_bn":"বিশেষ্য (Noun)"},{"id":25121,"position":8,"text_uthmani":"وَأَلْوَٰنِكُمْ ۚ","transliteration":"wa-alwānikum","translation_bn":"ও বর্ণসমূহের তোমাদের","root":"لون","lemma":"لَوْن","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":25123,"position":9,"text_uthmani":"إِنَّ","transliteration":"inna","translation_bn":"নিশ্চয়ই","root":"—","lemma":"إِنّ","grammar_bn":"অভিঘাত পদ (Accusative)"},{"id":25124,"position":10,"text_uthmani":"فِى","transliteration":"fī","translation_bn":"মধ্যে (রয়েছে)","root":"—","lemma":"فِى\r","grammar_bn":"অব্যয় (Preposition)"},{"id":25125,"position":11,"text_uthmani":"ذَٰلِكَ","transliteration":"dhālika","translation_bn":"এর","root":"—","lemma":"ذَٰلِك","grammar_bn":"নির্দেশক সর্বনাম (Demonstrative)"},{"id":25126,"position":12,"text_uthmani":"لَـَٔايَـٰتٍۢ","transliteration":"laāyātin","translation_bn":"অবশ্যই নিদর্শনাবলী","root":"ايي","lemma":"ءَايَة","grammar_bn":"দৃঢ়তাবোধক (Emphatic)"},{"id":25127,"position":13,"text_uthmani":"لِّلْعَـٰلِمِينَ","transliteration":"lil''ʿālimīna","translation_bn":"জন্যে জ্ঞানীদের","root":"علم","lemma":"عَٰلِم","grammar_bn":"অব্যয় (Preposition)"},{"id":25128,"position":14,"text_uthmani":"٢٢","transliteration":"","translation_bn":"(২২)","root":"—","lemma":"٢٢","grammar_bn":"মার্কার"}]'::jsonb, 'wamin āyātihi khalqu l-samāwāti wal-arḍi wa-ikh''tilāfu alsinatikum wa-alwānikum inna fī dhālika laāyātin lil''ʿālimīna', 'তাঁর নিদর্শনের মধ্যে হল, আসমানসমূহ ও যমীনের সৃষ্টি এবং তোমাদের ভাষা ও বর্ণের বিভিন্নতা। জ্ঞানীদের জন্য অবশ্যই এতে আছে বহু নিদর্শন।', 'And of His signs is the creation of the heavens and the earth and the diversity of your languages and your colors. Indeed in that are signs for those of knowledge.', 'তাঁর নিদর্শনের মধ্যে হল, আসমানসমূহ ও যমীনের সৃষ্টি এবং তোমাদের ভাষা ও বর্ণের বিভিন্নতা। জ্ঞানীদের জন্য অবশ্যই এতে আছে বহু নিদর্শন।', 'And of His signs is the creation of the heavens and the earth and the diversity of your languages and your colors. Indeed in that are signs for those of knowledge.', NULL, NULL, NULL, NULL, NULL, 'https://everyayah.com/data/Alafasy_128kbps/030022.mp3', now()),
  (30, 23, '', '[{"id":26230,"position":1,"text_uthmani":"وَمِنْ","transliteration":"wamin","translation_bn":"এবং মধ্যে হ''তে","root":"—","lemma":"مِن\r","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":26231,"position":2,"text_uthmani":"ءَايَـٰتِهِۦ","transliteration":"āyātihi","translation_bn":"নিদর্শনাবলীর তাঁর","root":"ايي","lemma":"ءَايَة","grammar_bn":"বিশেষ্য (Noun)"},{"id":26232,"position":3,"text_uthmani":"مَنَامُكُم","transliteration":"manāmukum","translation_bn":"ঘুম তোমাদের","root":"نوم","lemma":"مَنَام","grammar_bn":"বিশেষ্য (Noun)"},{"id":26233,"position":4,"text_uthmani":"بِٱلَّيْلِ","transliteration":"bi-al-layli","translation_bn":"বেলায় রাতের","root":"ليل","lemma":"لَيْل","grammar_bn":"অব্যয় (Preposition)"},{"id":26234,"position":5,"text_uthmani":"وَٱلنَّهَارِ","transliteration":"wal-nahāri","translation_bn":"ও দিনে","root":"نهر","lemma":"نَهَار","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":26235,"position":6,"text_uthmani":"وَٱبْتِغَآؤُكُم","transliteration":"wa-ib''tighāukum","translation_bn":"এবং অনুসন্ধান করা তোমাদের","root":"بغي","lemma":"ٱبْتِغَا^ء","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":26236,"position":7,"text_uthmani":"مِّن","transliteration":"min","translation_bn":"মধ্য হ''তে","root":"—","lemma":"مِن\r","grammar_bn":"অব্যয় (Preposition)"},{"id":26237,"position":8,"text_uthmani":"فَضْلِهِۦٓ ۚ","transliteration":"faḍlihi","translation_bn":"অনুগ্রহের তাঁর","root":"فضل","lemma":"فَضْل","grammar_bn":"বিশেষ্য (Noun)"},{"id":26239,"position":9,"text_uthmani":"إِنَّ","transliteration":"inna","translation_bn":"নিশ্চয়ই","root":"—","lemma":"إِنّ","grammar_bn":"অভিঘাত পদ (Accusative)"},{"id":26240,"position":10,"text_uthmani":"فِى","transliteration":"fī","translation_bn":"মধ্যে (রয়েছে)","root":"—","lemma":"فِى\r","grammar_bn":"অব্যয় (Preposition)"},{"id":26241,"position":11,"text_uthmani":"ذَٰلِكَ","transliteration":"dhālika","translation_bn":"এর","root":"—","lemma":"ذَٰلِك","grammar_bn":"নির্দেশক সর্বনাম (Demonstrative)"},{"id":26242,"position":12,"text_uthmani":"لَـَٔايَـٰتٍۢ","transliteration":"laāyātin","translation_bn":"অবশ্যই নিদর্শনাবলী","root":"ايي","lemma":"ءَايَة","grammar_bn":"দৃঢ়তাবোধক (Emphatic)"},{"id":26243,"position":13,"text_uthmani":"لِّقَوْمٍۢ","transliteration":"liqawmin","translation_bn":"জন্যে সম্প্রদায়ের","root":"قوم","lemma":"قَوْم","grammar_bn":"অব্যয় (Preposition)"},{"id":26244,"position":14,"text_uthmani":"يَسْمَعُونَ","transliteration":"yasmaʿūna","translation_bn":"যারা (শুনে)","root":"سمع","lemma":"سَمِعَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":26245,"position":15,"text_uthmani":"٢٣","transliteration":"","translation_bn":"(২৩)","root":"—","lemma":"٢٣","grammar_bn":"মার্কার"}]'::jsonb, 'wamin āyātihi manāmukum bi-al-layli wal-nahāri wa-ib''tighāukum min faḍlihi inna fī dhālika laāyātin liqawmin yasmaʿūna', 'তাঁর নিদর্শনের মধ্যে হল রাতে ও দিনে তোমাদের ঘুম এবং তোমাদের (দ্বারা) তাঁর অনুগ্রহ তালাশ করা। মনোযোগী লোকেদের জন্য অবশ্যই এতে আছে অনেক নিদর্শন।', 'And of His signs is your sleep by night and day and your seeking of His bounty. Indeed in that are signs for a people who listen.', 'তাঁর নিদর্শনের মধ্যে হল রাতে ও দিনে তোমাদের ঘুম এবং তোমাদের (দ্বারা) তাঁর অনুগ্রহ তালাশ করা। মনোযোগী লোকেদের জন্য অবশ্যই এতে আছে অনেক নিদর্শন।', 'And of His signs is your sleep by night and day and your seeking of His bounty. Indeed in that are signs for a people who listen.', NULL, NULL, NULL, NULL, NULL, 'https://everyayah.com/data/Alafasy_128kbps/030023.mp3', now()),
  (30, 24, '', '[{"id":27269,"position":1,"text_uthmani":"وَمِنْ","transliteration":"wamin","translation_bn":"এবং মধ্য হ''তে","root":"—","lemma":"مِن\r","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":27270,"position":2,"text_uthmani":"ءَايَـٰتِهِۦ","transliteration":"āyātihi","translation_bn":"নিদর্শনাবলীর তাঁর","root":"ايي","lemma":"ءَايَة","grammar_bn":"বিশেষ্য (Noun)"},{"id":27271,"position":3,"text_uthmani":"يُرِيكُمُ","transliteration":"yurīkumu","translation_bn":"তিনি দেখান তোমাদের","root":"راي","lemma":"أَرَيْ","grammar_bn":"ক্রিয়া (Verb)"},{"id":27272,"position":4,"text_uthmani":"ٱلْبَرْقَ","transliteration":"l-barqa","translation_bn":"বিদ্যুৎ","root":"برق","lemma":"بَرْق","grammar_bn":"শব্দ"},{"id":27273,"position":5,"text_uthmani":"خَوْفًۭا","transliteration":"khawfan","translation_bn":"ভয় হিসেবে","root":"خوف","lemma":"خَوْف","grammar_bn":"বিশেষ্য (Noun)"},{"id":27274,"position":6,"text_uthmani":"وَطَمَعًۭا","transliteration":"waṭamaʿan","translation_bn":"ও আশারূপে","root":"طمع","lemma":"طَمَع","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":27275,"position":7,"text_uthmani":"وَيُنَزِّلُ","transliteration":"wayunazzilu","translation_bn":"এবং বর্ষণ করেন","root":"نزل","lemma":"نَزَّلَ","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":27276,"position":8,"text_uthmani":"مِنَ","transliteration":"mina","translation_bn":"হ''তে","root":"—","lemma":"مِن\r","grammar_bn":"অব্যয় (Preposition)"},{"id":27277,"position":9,"text_uthmani":"ٱلسَّمَآءِ","transliteration":"l-samāi","translation_bn":"আকাশ","root":"سمو","lemma":"سَمَا^ء","grammar_bn":"শব্দ"},{"id":27278,"position":10,"text_uthmani":"مَآءًۭ","transliteration":"māan","translation_bn":"পানি","root":"موه","lemma":"مَا^ء","grammar_bn":"বিশেষ্য (Noun)"},{"id":27279,"position":11,"text_uthmani":"فَيُحْىِۦ","transliteration":"fayuḥ''yī","translation_bn":"অতঃপর জীবিত করেন","root":"حيي","lemma":"أَحْيَا","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":27280,"position":12,"text_uthmani":"بِهِ","transliteration":"bihi","translation_bn":"দিয়ে তা","root":"—","lemma":"بِهِ","grammar_bn":"অব্যয় (Preposition)"},{"id":27281,"position":13,"text_uthmani":"ٱلْأَرْضَ","transliteration":"l-arḍa","translation_bn":"জমিনকে","root":"ارض","lemma":"أَرْض","grammar_bn":"শব্দ"},{"id":27282,"position":14,"text_uthmani":"بَعْدَ","transliteration":"baʿda","translation_bn":"পরে","root":"بعد","lemma":"بَعْد","grammar_bn":"কালবাচক (Time)"},{"id":27283,"position":15,"text_uthmani":"مَوْتِهَآ ۚ","transliteration":"mawtihā","translation_bn":"মৃত্যুর তার","root":"موت","lemma":"مَوْت","grammar_bn":"বিশেষ্য (Noun)"},{"id":27285,"position":16,"text_uthmani":"إِنَّ","transliteration":"inna","translation_bn":"নিশ্চয়ই","root":"—","lemma":"إِنّ","grammar_bn":"অভিঘাত পদ (Accusative)"},{"id":27286,"position":17,"text_uthmani":"فِى","transliteration":"fī","translation_bn":"মধ্যে (রয়েছে)","root":"—","lemma":"فِى\r","grammar_bn":"অব্যয় (Preposition)"},{"id":27287,"position":18,"text_uthmani":"ذَٰلِكَ","transliteration":"dhālika","translation_bn":"এর","root":"—","lemma":"ذَٰلِك","grammar_bn":"নির্দেশক সর্বনাম (Demonstrative)"},{"id":27288,"position":19,"text_uthmani":"لَـَٔايَـٰتٍۢ","transliteration":"laāyātin","translation_bn":"অবশ্যই নিদর্শনাবলী","root":"ايي","lemma":"ءَايَة","grammar_bn":"দৃঢ়তাবোধক (Emphatic)"},{"id":27289,"position":20,"text_uthmani":"لِّقَوْمٍۢ","transliteration":"liqawmin","translation_bn":"জন্যে সম্প্রদায়ের","root":"قوم","lemma":"قَوْم","grammar_bn":"অব্যয় (Preposition)"},{"id":27290,"position":21,"text_uthmani":"يَعْقِلُونَ","transliteration":"yaʿqilūna","translation_bn":"(যারা) জ্ঞান-বুদ্ধি রাখে","root":"عقل","lemma":"عَقَلُ","grammar_bn":"ক্রিয়া (Verb)"},{"id":27291,"position":22,"text_uthmani":"٢٤","transliteration":"","translation_bn":"(২৪)","root":"—","lemma":"٢٤","grammar_bn":"মার্কার"}]'::jsonb, 'wamin āyātihi yurīkumu l-barqa khawfan waṭamaʿan wayunazzilu mina l-samāi māan fayuḥ''yī bihi l-arḍa baʿda mawtihā inna fī dhālika laāyātin liqawmin yaʿqilūna', 'তাঁর নিদর্শনের মধ্যে হল এই যে, তিনি তোমাদেরকে দেখান বিদ্যুৎ ভীতি ও ভরসা সঞ্চারীরূপে, আর তিনি আকাশ হতে পানি বর্ষণ করেন যা দিয়ে যমীনকে তার মৃত্যুর পর আবার জীবিত করেন, জ্ঞানবুদ্ধিসম্পন্ন মানুষদের জন্য অবশ্যই এতে বহু নিদর্শন আছে।', 'And of His signs is [that] He shows you the lightning [causing] fear and aspiration, and He sends down rain from the sky by which He brings to life the earth after its lifelessness. Indeed in that are signs for a people who use reason.', 'তাঁর নিদর্শনের মধ্যে হল এই যে, তিনি তোমাদেরকে দেখান বিদ্যুৎ ভীতি ও ভরসা সঞ্চারীরূপে, আর তিনি আকাশ হতে পানি বর্ষণ করেন যা দিয়ে যমীনকে তার মৃত্যুর পর আবার জীবিত করেন, জ্ঞানবুদ্ধিসম্পন্ন মানুষদের জন্য অবশ্যই এতে বহু নিদর্শন আছে।', 'And of His signs is [that] He shows you the lightning [causing] fear and aspiration, and He sends down rain from the sky by which He brings to life the earth after its lifelessness. Indeed in that are signs for a people who use reason.', NULL, NULL, NULL, NULL, NULL, 'https://everyayah.com/data/Alafasy_128kbps/030024.mp3', now()),
  (30, 25, '', '[{"id":28329,"position":1,"text_uthmani":"وَمِنْ","transliteration":"wamin","translation_bn":"এবং মধ্যে হ''তে","root":"—","lemma":"مِن\r","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":28330,"position":2,"text_uthmani":"ءَايَـٰتِهِۦٓ","transliteration":"āyātihi","translation_bn":"নিদর্শনসমূহের তাঁর","root":"ايي","lemma":"ءَايَة","grammar_bn":"বিশেষ্য (Noun)"},{"id":28331,"position":3,"text_uthmani":"أَن","transliteration":"an","translation_bn":"(এও) যে","root":"—","lemma":"أَن\r","grammar_bn":"অধীনস্থ যোজক (Subordinating)"},{"id":28332,"position":4,"text_uthmani":"تَقُومَ","transliteration":"taqūma","translation_bn":"প্রতিষ্ঠিত  রয়েছে","root":"قوم","lemma":"قَامَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":28333,"position":5,"text_uthmani":"ٱلسَّمَآءُ","transliteration":"l-samāu","translation_bn":"আকাশ","root":"سمو","lemma":"سَمَا^ء","grammar_bn":"শব্দ"},{"id":28334,"position":6,"text_uthmani":"وَٱلْأَرْضُ","transliteration":"wal-arḍu","translation_bn":"ও পৃথিবী","root":"ارض","lemma":"أَرْض","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":28335,"position":7,"text_uthmani":"بِأَمْرِهِۦ ۚ","transliteration":"bi-amrihi","translation_bn":"নির্দেশক্রমে তাঁরই","root":"امر","lemma":"أَمْر","grammar_bn":"অব্যয় (Preposition)"},{"id":28337,"position":8,"text_uthmani":"ثُمَّ","transliteration":"thumma","translation_bn":"এরপর","root":"—","lemma":"ثُمّ\r","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":28338,"position":9,"text_uthmani":"إِذَا","transliteration":"idhā","translation_bn":"যখন","root":"—","lemma":"إِذَا\r","grammar_bn":"কালবাচক (Time)"},{"id":28339,"position":10,"text_uthmani":"دَعَاكُمْ","transliteration":"daʿākum","translation_bn":"তিনি ডাক দিবেন তোমাদের","root":"دعو","lemma":"دَعَا","grammar_bn":"ক্রিয়া (Verb)"},{"id":28340,"position":11,"text_uthmani":"دَعْوَةًۭ","transliteration":"daʿwatan","translation_bn":"একটি ডাক","root":"دعو","lemma":"دَعْوَة","grammar_bn":"বিশেষ্য (Noun)"},{"id":28341,"position":12,"text_uthmani":"مِّنَ","transliteration":"mina","translation_bn":"হ''তে","root":"—","lemma":"مِن\r","grammar_bn":"অব্যয় (Preposition)"},{"id":28342,"position":13,"text_uthmani":"ٱلْأَرْضِ","transliteration":"l-arḍi","translation_bn":"জমিন","root":"ارض","lemma":"أَرْض","grammar_bn":"শব্দ"},{"id":28343,"position":14,"text_uthmani":"إِذَآ","transliteration":"idhā","translation_bn":"তখন","root":"—","lemma":"إِذَا2\r","grammar_bn":"আশ্চর্যসূচক (Surprise)"},{"id":28344,"position":15,"text_uthmani":"أَنتُمْ","transliteration":"antum","translation_bn":"তোমরা","root":"—","lemma":"أَنتُمْ","grammar_bn":"সর্বনাম (Pronoun)"},{"id":28345,"position":16,"text_uthmani":"تَخْرُجُونَ","transliteration":"takhrujūna","translation_bn":"বের হয়ে আসবে","root":"خرج","lemma":"خَرَجَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":28346,"position":17,"text_uthmani":"٢٥","transliteration":"","translation_bn":"(২৫)","root":"—","lemma":"٢٥","grammar_bn":"মার্কার"}]'::jsonb, 'wamin āyātihi an taqūma l-samāu wal-arḍu bi-amrihi thumma idhā daʿākum daʿwatan mina l-arḍi idhā antum takhrujūna', 'তাঁর নিদর্শনের মধ্যে হল এই যে, আকাশ ও পৃথিবী তাঁর হুকুমেই দাঁড়িয়ে আছে। অতঃপর তিনি যখন তোমাদেরকে মাটি থেকে উঠার জন্য ডাক দেবেন একটি ডাক, তখন তোমরা উঠে আসবে।', 'And of His signs is that the heaven and earth remain by His command. Then when He calls you with a [single] call from the earth, immediately you will come forth.', 'তাঁর নিদর্শনের মধ্যে হল এই যে, আকাশ ও পৃথিবী তাঁর হুকুমেই দাঁড়িয়ে আছে। অতঃপর তিনি যখন তোমাদেরকে মাটি থেকে উঠার জন্য ডাক দেবেন একটি ডাক, তখন তোমরা উঠে আসবে।', 'And of His signs is that the heaven and earth remain by His command. Then when He calls you with a [single] call from the earth, immediately you will come forth.', NULL, NULL, NULL, NULL, NULL, 'https://everyayah.com/data/Alafasy_128kbps/030025.mp3', now()),
  (30, 26, '', '[{"id":29242,"position":1,"text_uthmani":"وَلَهُۥ","transliteration":"walahu","translation_bn":"এবং জন্যে তাঁরই","root":"—","lemma":"وَلَهُۥ","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":29243,"position":2,"text_uthmani":"مَن","transliteration":"man","translation_bn":"যা কিছু","root":"—","lemma":"مَن\r","grammar_bn":"সাপেক্ষ সর্বনাম (Relative)"},{"id":29244,"position":3,"text_uthmani":"فِى","transliteration":"fī","translation_bn":"মধ্যে (আছে)","root":"—","lemma":"فِى\r","grammar_bn":"অব্যয় (Preposition)"},{"id":29245,"position":4,"text_uthmani":"ٱلسَّمَـٰوَٰتِ","transliteration":"l-samāwāti","translation_bn":"আকাশমন্ডলীর","root":"سمو","lemma":"سَمَا^ء","grammar_bn":"শব্দ"},{"id":29246,"position":5,"text_uthmani":"وَٱلْأَرْضِ ۖ","transliteration":"wal-arḍi","translation_bn":"ও পৃথিবীর","root":"ارض","lemma":"أَرْض","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":29248,"position":6,"text_uthmani":"كُلٌّۭ","transliteration":"kullun","translation_bn":"সবকিছু","root":"كلل","lemma":"كُلّ","grammar_bn":"বিশেষ্য (Noun)"},{"id":29249,"position":7,"text_uthmani":"لَّهُۥ","transliteration":"lahu","translation_bn":"প্রতি তাঁরই","root":"—","lemma":"لَّهُۥ","grammar_bn":"অব্যয় (Preposition)"},{"id":29250,"position":8,"text_uthmani":"قَـٰنِتُونَ","transliteration":"qānitūna","translation_bn":"অনুগত","root":"قنت","lemma":"قَانِت","grammar_bn":"বিশেষ্য (Noun)"},{"id":29251,"position":9,"text_uthmani":"٢٦","transliteration":"","translation_bn":"(২৬)","root":"—","lemma":"٢٦","grammar_bn":"মার্কার"}]'::jsonb, 'walahu man fī l-samāwāti wal-arḍi kullun lahu qānitūna', 'আকাশমন্ডলী ও পৃথিবীতে যা আছে সব তাঁরই, সকলই তাঁর প্রতি অনুগত।', 'And to Him belongs whoever is in the heavens and earth. All are to Him devoutly obedient.', 'আকাশমন্ডলী ও পৃথিবীতে যা আছে সব তাঁরই, সকলই তাঁর প্রতি অনুগত।', 'And to Him belongs whoever is in the heavens and earth. All are to Him devoutly obedient.', NULL, NULL, NULL, NULL, NULL, 'https://everyayah.com/data/Alafasy_128kbps/030026.mp3', now()),
  (30, 27, '', '[{"id":30162,"position":1,"text_uthmani":"وَهُوَ","transliteration":"wahuwa","translation_bn":"এবং তিনিই (আল্লাহ)","root":"—","lemma":"وَهُوَ","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":30163,"position":2,"text_uthmani":"ٱلَّذِى","transliteration":"alladhī","translation_bn":"যিনি","root":"—","lemma":"ٱلَّذِى","grammar_bn":"সাপেক্ষ সর্বনাম (Relative)"},{"id":30164,"position":3,"text_uthmani":"يَبْدَؤُا۟","transliteration":"yabda-u","translation_bn":"সূচনা করেন","root":"بدا","lemma":"بَدَأَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":30165,"position":4,"text_uthmani":"ٱلْخَلْقَ","transliteration":"l-khalqa","translation_bn":"সৃষ্টির","root":"خلق","lemma":"خَلْق","grammar_bn":"শব্দ"},{"id":30166,"position":5,"text_uthmani":"ثُمَّ","transliteration":"thumma","translation_bn":"এরপর","root":"—","lemma":"ثُمّ\r","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":30167,"position":6,"text_uthmani":"يُعِيدُهُۥ","transliteration":"yuʿīduhu","translation_bn":"পুনরাবৃত্তি করবেন তার","root":"عود","lemma":"أُعِيدُ","grammar_bn":"ক্রিয়া (Verb)"},{"id":30168,"position":7,"text_uthmani":"وَهُوَ","transliteration":"wahuwa","translation_bn":"এবং তা","root":"—","lemma":"وَهُوَ","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":30169,"position":8,"text_uthmani":"أَهْوَنُ","transliteration":"ahwanu","translation_bn":"সহজতর","root":"هون","lemma":"أَهْوَن","grammar_bn":"বিশেষ্য (Noun)"},{"id":30170,"position":9,"text_uthmani":"عَلَيْهِ ۚ","transliteration":"ʿalayhi","translation_bn":"কাছে তাঁর","root":"—","lemma":"عَلَىٰ\r","grammar_bn":"অব্যয় (Preposition)"},{"id":30172,"position":10,"text_uthmani":"وَلَهُ","transliteration":"walahu","translation_bn":"এবং জন্যে তাঁরই","root":"—","lemma":"وَلَهُ","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":30173,"position":11,"text_uthmani":"ٱلْمَثَلُ","transliteration":"l-mathalu","translation_bn":"গুণাবলী (মর্যাদা)","root":"مثل","lemma":"مَثَل","grammar_bn":"শব্দ"},{"id":30174,"position":12,"text_uthmani":"ٱلْأَعْلَىٰ","transliteration":"l-aʿlā","translation_bn":"সর্বোত্তম","root":"علو","lemma":"أَعْلَىٰ","grammar_bn":"শব্দ"},{"id":30175,"position":13,"text_uthmani":"فِى","transliteration":"fī","translation_bn":"মধ্যে","root":"—","lemma":"فِى\r","grammar_bn":"অব্যয় (Preposition)"},{"id":30176,"position":14,"text_uthmani":"ٱلسَّمَـٰوَٰتِ","transliteration":"l-samāwāti","translation_bn":"আকাশসমূহের","root":"سمو","lemma":"سَمَا^ء","grammar_bn":"শব্দ"},{"id":30177,"position":15,"text_uthmani":"وَٱلْأَرْضِ ۚ","transliteration":"wal-arḍi","translation_bn":"এবং পৃথিবীতে","root":"ارض","lemma":"أَرْض","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":30179,"position":16,"text_uthmani":"وَهُوَ","transliteration":"wahuwa","translation_bn":"এবং তিনি","root":"—","lemma":"وَهُوَ","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":30180,"position":17,"text_uthmani":"ٱلْعَزِيزُ","transliteration":"l-ʿazīzu","translation_bn":"পরাক্রমশালী","root":"عزز","lemma":"عَزِيز","grammar_bn":"শব্দ"},{"id":30181,"position":18,"text_uthmani":"ٱلْحَكِيمُ","transliteration":"l-ḥakīmu","translation_bn":"প্রজ্ঞাময়","root":"حكم","lemma":"حَكِيم","grammar_bn":"শব্দ"},{"id":30182,"position":19,"text_uthmani":"٢٧","transliteration":"","translation_bn":"(২৭)","root":"—","lemma":"٢٧","grammar_bn":"মার্কার"}]'::jsonb, 'wahuwa alladhī yabda-u l-khalqa thumma yuʿīduhu wahuwa ahwanu ʿalayhi walahu l-mathalu l-aʿlā fī l-samāwāti wal-arḍi wahuwa l-ʿazīzu l-ḥakīmu', 'তিনিই সৃষ্টির সূচনা করেন, অতঃপর তার পুনরাবৃত্তি করবেন আর তা তার জন্য খুবই সহজ। আকাশ ও পৃথিবীতে সর্বোচ্চ দৃষ্টান্ত তাঁর জন্যই, তিনিই মহাপরাক্রমশালী, বড়ই হিকমতওয়ালা।', 'And it is He who begins creation; then He repeats it, and that is [even] easier for Him. To Him belongs the highest attribute in the heavens and earth. And He is the Exalted in Might, the Wise.', 'তিনিই সৃষ্টির সূচনা করেন, অতঃপর তার পুনরাবৃত্তি করবেন আর তা তার জন্য খুবই সহজ। আকাশ ও পৃথিবীতে সর্বোচ্চ দৃষ্টান্ত তাঁর জন্যই, তিনিই মহাপরাক্রমশালী, বড়ই হিকমতওয়ালা।', 'And it is He who begins creation; then He repeats it, and that is [even] easier for Him. To Him belongs the highest attribute in the heavens and earth. And He is the Exalted in Might, the Wise.', NULL, NULL, NULL, NULL, NULL, 'https://everyayah.com/data/Alafasy_128kbps/030027.mp3', now()),
  (30, 28, '', '[{"id":31218,"position":1,"text_uthmani":"ضَرَبَ","transliteration":"ḍaraba","translation_bn":"পেশ করেন (আল্লাহ)","root":"ضرب","lemma":"ضَرَبَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":31219,"position":2,"text_uthmani":"لَكُم","transliteration":"lakum","translation_bn":"জন্যে তোমাদের","root":"—","lemma":"لَكُم","grammar_bn":"অব্যয় (Preposition)"},{"id":31220,"position":3,"text_uthmani":"مَّثَلًۭا","transliteration":"mathalan","translation_bn":"একটি দৃষ্টান্ত","root":"مثل","lemma":"مَثَل","grammar_bn":"বিশেষ্য (Noun)"},{"id":31221,"position":4,"text_uthmani":"مِّنْ","transliteration":"min","translation_bn":"মধ্য হ''তে","root":"—","lemma":"مِن\r","grammar_bn":"অব্যয় (Preposition)"},{"id":31222,"position":5,"text_uthmani":"أَنفُسِكُمْ ۖ","transliteration":"anfusikum","translation_bn":"নিজেদের তোমাদের","root":"نفس","lemma":"نَفْس","grammar_bn":"বিশেষ্য (Noun)"},{"id":31224,"position":6,"text_uthmani":"هَل","transliteration":"hal","translation_bn":"(আছে) কি","root":"—","lemma":"هَل\r","grammar_bn":"প্রশ্নবোধক (Interrogative)"},{"id":31225,"position":7,"text_uthmani":"لَّكُم","transliteration":"lakum","translation_bn":"জন্যে তোমাদের","root":"—","lemma":"لَّكُم","grammar_bn":"অব্যয় (Preposition)"},{"id":31226,"position":8,"text_uthmani":"مِّن","transliteration":"min","translation_bn":"মধ্য হ''তে","root":"—","lemma":"مِن\r","grammar_bn":"অব্যয় (Preposition)"},{"id":31227,"position":9,"text_uthmani":"مَّا","transliteration":"mā","translation_bn":"যাকে","root":"—","lemma":"مَا\r","grammar_bn":"সাপেক্ষ সর্বনাম (Relative)"},{"id":31228,"position":10,"text_uthmani":"مَلَكَتْ","transliteration":"malakat","translation_bn":"মালিক করেছে","root":"ملك","lemma":"مَلَكَتْ","grammar_bn":"ক্রিয়া (Verb)"},{"id":31229,"position":11,"text_uthmani":"أَيْمَـٰنُكُم","transliteration":"aymānukum","translation_bn":"ডানহাত তোমাদের (অর্থাৎ তোমাদের দাসদাসী)","root":"يمن","lemma":"يَمِين","grammar_bn":"বিশেষ্য (Noun)"},{"id":31230,"position":12,"text_uthmani":"مِّن","transliteration"